window.QURAN={"total_verses": 6236, "surahs": [{"num": 1, "name": "Al-Fatihah", "meaning": "The Opening", "verses": [{"ayah": 1, "translit": "Bismillaahir Rahmaanir Raheem", "translation": "In the name of Allah, the Entirely Merciful, the Especially Merciful."}, {"ayah": 2, "translit": "Alhamdu lillaahi Rabbil 'aalameen", "translation": "[All] praise is [due] to Allah, Lord of the worlds -"}, {"ayah": 3, "translit": "Ar-Rahmaanir-Raheem", "translation": "The Entirely Merciful, the Especially Merciful,"}, {"ayah": 4, "translit": "Maaliki Yawmid-Deen", "translation": "Sovereign of the Day of Recompense."}, {"ayah": 5, "translit": "Iyyaaka na'budu wa lyyaaka nasta'een", "translation": "It is You we worship and You we ask for help."}, {"ayah": 6, "translit": "Ihdinas-Siraatal-Mustaqeem", "translation": "Guide us to the straight path -"}, {"ayah": 7, "translit": "Siraatal-lazeena an'amta 'alaihim ghayril-maghdoobi 'alaihim wa lad-daaalleen", "translation": "The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray."}]}, {"num": 2, "name": "Al-Baqarah", "meaning": "The Cow", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Meeem", "translation": "Alif, Lam, Meem."}, {"ayah": 2, "translit": "Zaalikal Kitaabu laa raiba feeh; udal lilmuttaqeen", "translation": "This is the Book about which there is no doubt, a guidance for those conscious of Allah -"}, {"ayah": 3, "translit": "Allazeena yu'minoona bilghaibi wa yuqeemoonas salaata wa mimmaa razaqnaahum yunfiqoon", "translation": "Who believe in the unseen, establish prayer, and spend out of what We have provided for them,"}, {"ayah": 4, "translit": "Wallazeena yu'minoona bimaa unzila ilaika wa maaa unzila min qablika wa bil Aakhirati hum yooqinoon", "translation": "And who believe in what has been revealed to you, [O Muhammad], and what was revealed before you, and of the Hereafter they are certain [in faith]."}, {"ayah": 5, "translit": "Ulaaa'ika 'alaa hudam mir rabbihim wa ulaaa'ika humul muflihoon", "translation": "Those are upon [right] guidance from their Lord, and it is those who are the successful."}, {"ayah": 6, "translit": "Innal lazeena kafaroo sawaaa'un 'alaihim 'a-anzar tahum am lam tunzirhum laa yu'minoon", "translation": "Indeed, those who disbelieve - it is all the same for them whether you warn them or do not warn them - they will not believe."}, {"ayah": 7, "translit": "Khatamal laahu 'alaa quloobihim wa 'alaa sam'i-him wa 'alaaa absaarihim ghishaa watunw wa lahum 'azaabun 'azeem", "translation": "Allah has set a seal upon their hearts and upon their hearing, and over their vision is a veil. And for them is a great punishment."}, {"ayah": 8, "translit": "Wa minan naasi mai yaqoolu aamannaa billaahi wa bil yawmil aakhiri wa maa hum bimu'mineen", "translation": "And of the people are some who say, \"We believe in Allah and the Last Day,\" but they are not believers."}, {"ayah": 9, "translit": "Yukhaadi'oonal laaha wallazeena aamanoo wa maa yakhda'oona illaaa anfusahum wa maa yash'uroon", "translation": "They [think to] deceive Allah and those who believe, but they deceive not except themselves and perceive [it] not."}, {"ayah": 10, "translit": "Fee quloobihim mara dun fazaadahumul laahu maradan wa lahum 'azaabun aleemum bimaa kaanoo yakziboon", "translation": "In their hearts is disease, so Allah has increased their disease; and for them is a painful punishment because they [habitually] used to lie."}, {"ayah": 11, "translit": "Wa izaa qeela lahum laa tufsidoo fil ardi qaalo innamaa nahnu muslihoon", "translation": "And when it is said to them, \"Do not cause corruption on the earth,\" they say, \"We are but reformers.\""}, {"ayah": 12, "translit": "Alaaa innahum humul mufsidoona wa laakil laa yash'uroon", "translation": "Unquestionably, it is they who are the corrupters, but they perceive [it] not."}, {"ayah": 13, "translit": "Wa izaa qeela lahum aaminoo kamaaa aamanan naasu qaalooo anu'minu kamaaa aamanas sufahaaa'; alaaa innahum humus sufahaaa'u wa laakil laa ya'lamoon", "translation": "And when it is said to them, \"Believe as the people have believed,\" they say, \"Should we believe as the foolish have believed?\" Unquestionably, it is they who are the foolish, but they know [it] not."}, {"ayah": 14, "translit": "Wa izaa laqul lazeena aamanoo qaalooo aamannaa wa izaa khalw ilaa shayaateenihim qaalooo innaa ma'akum innamaa nahnu mustahzi'oon", "translation": "And when they meet those who believe, they say, \"We believe\"; but when they are alone with their evil ones, they say, \"Indeed, we are with you; we were only mockers.\""}, {"ayah": 15, "translit": "Allahu yastahzi'u bihim wa yamudduhum fee tughyaanihim ya'mahoon", "translation": "[But] Allah mocks them and prolongs them in their transgression [while] they wander blindly."}, {"ayah": 16, "translit": "Ulaaa'ikal lazeenash tara wud dalaalata bilhudaa famaa rabihat tijaaratuhum wa maa kaanoo muhtadeen", "translation": "Those are the ones who have purchased error [in exchange] for guidance, so their transaction has brought no profit, nor were they guided."}, {"ayah": 17, "translit": "Masaluhum kamasalillazis tawqada naaran falammaaa adaaa'at maa hawlahoo zahabal laahu binoorihim wa tarakahum fee zulumaatil laa yubsiroon", "translation": "Their example is that of one who kindled a fire, but when it illuminated what was around him, Allah took away their light and left them in darkness [so] they could not see."}, {"ayah": 18, "translit": "Summum bukmun 'umyun fahum laa yarji'oon", "translation": "Deaf, dumb and blind - so they will not return [to the right path]."}, {"ayah": 19, "translit": "Aw kasaiyibim minas samaaa'i feehi zulumaatunw wa ra'dunw wa barq, yaj'aloona asaabi'ahum feee aazaanihim minas sawaa'iqi hazaral mawt' wallaahu muheetum bilkaafireen", "translation": "Or [it is] like a rainstorm from the sky within which is darkness, thunder and lightning. They put their fingers in their ears against the thunderclaps in dread of death. But Allah is encompassing of the disbelievers."}, {"ayah": 20, "translit": "Yakaadul barqu yakhtafu absaarahum kullamaaa adaaa'a lahum mashaw feehi wa izaaa azlama 'alaihim qaamoo; wa law shaaa'al laahu lazahaba bisam'ihim wa absaarihim; innal laaha 'alaa kulli shai'in Qadeer", "translation": "The lightning almost snatches away their sight. Every time it lights [the way] for them, they walk therein; but when darkness comes over them, they stand [still]. And if Allah had willed, He could have taken away their hearing and their sight. Indeed, Allah is over all things competent."}, {"ayah": 21, "translit": "Yaaa aiyuhan naasu'budoo Rabbakumul lazee khalaqakum wallazeena min qablikum la'allakum tattaqoon", "translation": "O mankind, worship your Lord, who created you and those before you, that you may become righteous -"}, {"ayah": 22, "translit": "Allazee ja'ala lakumul arda firaashanw wassamaaa'a binaaa 'anw wa anzala minassamaaa'i maaa'an fa akhraja bihee minas samaraati rizqal lakum falaa taj'aloo lillaahi andaadanw wa antum ta'lamoon", "translation": "[He] who made for you the earth a bed [spread out] and the sky a ceiling and sent down from the sky, rain and brought forth thereby fruits as provision for you. So do not attribute to Allah equals while you know [that there is nothing similar to Him]."}, {"ayah": 23, "translit": "Wa in kuntum fee raibim mimmaa nazzalnaa 'alaa 'abdinaa fatoo bi Sooratim mim mislihee wad'oo shuhadaaa'akum min doonil laahi in kuntum saadiqeen", "translation": "And if you are in doubt about what We have sent down upon Our Servant [Muhammad], then produce a surah the like thereof and call upon your witnesses other than Allah, if you should be truthful."}, {"ayah": 24, "translit": "Fail lam taf'aloo wa lan taf'aloo fattaqun Naaral latee waqooduhan naasu walhijaaratu u'iddat lilkaafireen", "translation": "But if you do not - and you will never be able to - then fear the Fire, whose fuel is men and stones, prepared for the disbelievers."}, {"ayah": 25, "translit": "Wa bashshiril lazeena aamanoo wa 'amilus saalihaati anna lahum jannaatin tajree min tahtihal anhaaru kullamaa riziqoo minhaa min samaratir rizqan qaaloo haazal lazee ruziqnaa min qablu wa utoo bihee mutashaabihaa, wa lahum feehaaa azwaajum mutahhara tunw wa hum feehaa khaalidoon", "translation": "And give good tidings to those who believe and do righteous deeds that they will have gardens [in Paradise] beneath which rivers flow. Whenever they are provided with a provision of fruit therefrom, they will say, \"This is what we were provided with before.\" And it is given to them in likeness. And they will have therein purified spouses, and they will abide therein eternally."}, {"ayah": 26, "translit": "Innal laaha laa yastahyeee ai yadriba masalam maa ba'oodatan famaa fawqahaa; faammal lazeena aamanoo faya'lamoona annahul haqqu mir rabbihim wa ammal lazeena kafaroo fayaqooloona maazaaa araadal laahu bihaazaa masalaa; yudillu bihee kaseeranw wa yahdee bihee kaseeraa; wa maa yudillu biheee illal faasiqeen", "translation": "Indeed, Allah is not timid to present an example - that of a mosquito or what is smaller than it. And those who have believed know that it is the truth from their Lord. But as for those who disbelieve, they say, \"What did Allah intend by this as an example?\" He misleads many thereby and guides many thereby. And He misleads not except the defiantly disobedient,"}, {"ayah": 27, "translit": "Allazeena yanqudoona 'ahdal laahi mim ba'di meesaaqihee wa yaqt'oona maaa amaral laahu biheee ai yoosala wa yufsidoona fil ard; ulaaa'ika hum khaasirron", "translation": "Who break the covenant of Allah after contracting it and sever that which Allah has ordered to be joined and cause corruption on earth. It is those who are the losers."}, {"ayah": 28, "translit": "Kaifa takfuroona billaahi wa kuntum amwaatan fa ahyaakum summa yumeetukum summa yuhyeekum summaa ilaihi turja'oon", "translation": "How can you disbelieve in Allah when you were lifeless and He brought you to life; then He will cause you to die, then He will bring you [back] to life, and then to Him you will be returned."}, {"ayah": 29, "translit": "Huwal lazee khalaqa lakum maa fil ardi jamee'an summas tawaaa ilas samaaa'i fasaw waahunna sab'a samaa waat; wa Huwa bikulli shai'in Aleem", "translation": "It is He who created for you all of that which is on the earth. Then He directed Himself to the heaven, [His being above all creation], and made them seven heavens, and He is Knowing of all things."}, {"ayah": 30, "translit": "Wa iz qaala rabbuka lil malaaa'ikati innee jaa'ilun fil ardi khaleefatan qaalooo ataj'alu feehaa mai yufsidu feehaa wa yasfikud dimaaa'a wa nahnu nusabbihu bihamdika wa nuqaddisu laka qaala inneee a'lamu maa laa ta'lamoon", "translation": "And [mention, O Muhammad], when your Lord said to the angels, \"Indeed, I will make upon the earth a successive authority.\" They said, \"Will You place upon it one who causes corruption therein and sheds blood, while we declare Your praise and sanctify You?\" Allah said, \"Indeed, I know that which you do not know.\""}, {"ayah": 31, "translit": "Wa 'allama Aadamal asmaaa'a kullahaa summa 'aradahum 'alal malaaa'ikati faqaala ambi'oonee bias maaa'i haaa'ulaaa'i in kuntum saadiqeen", "translation": "And He taught Adam the names - all of them. Then He showed them to the angels and said, \"Inform Me of the names of these, if you are truthful.\""}, {"ayah": 32, "translit": "Qaaloo subhaanaka laa 'ilma lanaaa illaa maa 'allamtanaaa innaka antal'aleemul hakeem", "translation": "They said, \"Exalted are You; we have no knowledge except what You have taught us. Indeed, it is You who is the Knowing, the Wise.\""}, {"ayah": 33, "translit": "Qaala yaaa Aadamu ambi' hum biasmaaa'ihimfalammaaa amba ahum bi asmaaa'ihim qaala alam aqul lakum inneee a'lamu ghaibas samaawaati wal ardi wa a'lamu maa tubdoona wa maa kuntum taktumoon", "translation": "He said, \"O Adam, inform them of their names.\" And when he had informed them of their names, He said, \"Did I not tell you that I know the unseen [aspects] of the heavens and the earth? And I know what you reveal and what you have concealed.\""}, {"ayah": 34, "translit": "Wa iz qulnaa lilmalaaa'i katis judoo liAadama fasajadooo illaaa Ibleesa abaa wastakbara wa kaana minal kaafireen", "translation": "And [mention] when We said to the angels, \"Prostrate before Adam\"; so they prostrated, except for Iblees. He refused and was arrogant and became of the disbelievers."}, {"ayah": 35, "translit": "Wa qulnaa yaaa Aadamus kun anta wa zawjukal jannata wa kulaa minhaa raghadan haisu shi'tumaa wa laa taqabaa haazihish shajarata fatakoonaa minaz zaalimeen", "translation": "And We said, \"O Adam, dwell, you and your wife, in Paradise and eat therefrom in [ease and] abundance from wherever you will. But do not approach this tree, lest you be among the wrongdoers.\""}, {"ayah": 36, "translit": "Fa azallahumash Shaitaanu 'anhaa fa akhrajahumaa mimmaa kaanaa fee wa qulnah bitoo ba'dukum liba'din 'aduwwunw wa lakum fil ardi mustaqarrunw wa mataa'un ilaa heen", "translation": "But Satan caused them to slip out of it and removed them from that [condition] in which they had been. And We said, \"Go down, [all of you], as enemies to one another, and you will have upon the earth a place of settlement and provision for a time.\""}, {"ayah": 37, "translit": "Fatalaqqaaa Aadamu mir Rabbihee Kalimaatin fataaba 'alayh; innahoo Huwat Tawwaabur Raheem", "translation": "Then Adam received from his Lord [some] words, and He accepted his repentance. Indeed, it is He who is the Accepting of repentance, the Merciful."}, {"ayah": 38, "translit": "Qulnah bitoo minhaa jamee 'an fa immaa yaatiyannakum minnee hudan faman tabi'a hudaaya falaa khawfun 'alaihim wa laa hum yahza noon", "translation": "We said, \"Go down from it, all of you. And when guidance comes to you from Me, whoever follows My guidance - there will be no fear concerning them, nor will they grieve."}, {"ayah": 39, "translit": "Wallazeena kafaroo wa kaz zabooo bi aayaatinaa ulaaa'ika Ashaabun Naari hum feehaa khaalidoon (section 4)", "translation": "And those who disbelieve and deny Our signs - those will be companions of the Fire; they will abide therein eternally.\""}, {"ayah": 40, "translit": "Yaa Baneee Israaa'eelaz kuroo ni'matiyal lateee an'amtu 'alaikum wa awfoo bi'Ahdeee oofi bi ahdikum wa iyyaaya farhaboon", "translation": "O Children of Israel, remember My favor which I have bestowed upon you and fulfill My covenant [upon you] that I will fulfill your covenant [from Me], and be afraid of [only] Me."}, {"ayah": 41, "translit": "Wa aaminoo bimaaa anzaltu musaddiqal limaa ma'akum wa laa takoonooo awwala kaafirim bihee wa laa tashtaroo bi Aayaatee samanan qaleelanw wa iyyaaya fattaqoon", "translation": "And believe in what I have sent down confirming that which is [already] with you, and be not the first to disbelieve in it. And do not exchange My signs for a small price, and fear [only] Me."}, {"ayah": 42, "translit": "Wa laa talbisul haqqa bilbaatili wa taktumul haqqa wa antum ta'lamoon", "translation": "And do not mix the truth with falsehood or conceal the truth while you know [it]."}, {"ayah": 43, "translit": "Wa aqeemus salaata wa aatuz zakaata warka'oo ma'ar raaki'een", "translation": "And establish prayer and give zakah and bow with those who bow [in worship and obedience]."}, {"ayah": 44, "translit": "Ataamuroonan naasa bilbirri wa tansawna anfusakum wa antum tatloonal Kitaab; afalaa ta'qiloon", "translation": "Do you order righteousness of the people and forget yourselves while you recite the Scripture? Then will you not reason?"}, {"ayah": 45, "translit": "Wasta'eenoo bissabri was Salaah; wa innahaa lakabee ratun illaa alal khaashi'een", "translation": "And seek help through patience and prayer, and indeed, it is difficult except for the humbly submissive [to Allah]"}, {"ayah": 46, "translit": "Allazeena yazunnoona annahum mulaaqoo Rabbihim wa annahum ilaihi raaji'oon", "translation": "Who are certain that they will meet their Lord and that they will return to Him."}, {"ayah": 47, "translit": "Yaa Baneee Israaa'eelaz kuroo ni'matiyal lateee an'amtu 'alaikum wa annee faddaltukum 'alal 'aalameen", "translation": "O Children of Israel, remember My favor that I have bestowed upon you and that I preferred you over the worlds."}, {"ayah": 48, "translit": "Wattaqoo Yawmal laa tajzee nafsun 'an nafsin shai'anw wa laa yuqbalu minhaa shafaa'atunw wa laa yu'khazu minhaa 'adlunw wa laa hum yunsaroon", "translation": "And fear a Day when no soul will suffice for another soul at all, nor will intercession be accepted from it, nor will compensation be taken from it, nor will they be aided."}, {"ayah": 49, "translit": "Wa iz najjainaakum min Aali Fir'awna yasoomoonakum sooo'al azaabi yuzabbihoona abuaaa'akum wa yastahyoona nisaaa'akum; wa fee zaalikum balaaa'um mir Rabbikum 'azeem", "translation": "And [recall] when We saved your forefathers from the people of Pharaoh, who afflicted you with the worst torment, slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord."}, {"ayah": 50, "translit": "Wa iz faraqnaa bikumul bahra fa anjainaakum wa agh-raqnaaa Aala Fir'awna wa antum tanzuroon", "translation": "And [recall] when We parted the sea for you and saved you and drowned the people of Pharaoh while you were looking on."}, {"ayah": 51, "translit": "Wa iz waa'adnaa Moosaaa arba'eena lailatan summattakhaztumul 'ijla mim ba'dihee wa antum zaalimoon", "translation": "And [recall] when We made an appointment with Moses for forty nights. Then you took [for worship] the calf after him, while you were wrongdoers."}, {"ayah": 52, "translit": "Summa 'afawnaa 'ankum mim ba'di zaalika la'allakum tashkuroon", "translation": "Then We forgave you after that so perhaps you would be grateful."}, {"ayah": 53, "translit": "Wa iz aatainaa Moosal kitaaba wal Furqaana la'allakum tahtadoon", "translation": "And [recall] when We gave Moses the Scripture and criterion that perhaps you would be guided."}, {"ayah": 54, "translit": "Wa iz qaala Moosaa liqawmihee yaa qawmi innakum zalamtum anfusakum bittikhaa zikumul 'ijla fatoobooo ilaa Baari'ikum faqtulooo anfusakum zaalikum khairul lakum 'inda Baari'ikum fataaba 'alaikum; innahoo Huwat Tawwaabur Raheem", "translation": "And [recall] when Moses said to his people, \"O my people, indeed you have wronged yourselves by your taking of the calf [for worship]. So repent to your Creator and kill yourselves. That is best for [all of] you in the sight of your Creator.\" Then He accepted your repentance; indeed, He is the Accepting of repentance, the Merciful."}, {"ayah": 55, "translit": "Wa iz qultum yaa Moosaa lan nu'mina laka hattaa naral laaha jahratan fa akhazat kumus saa'iqatu wa antum tanzuroon", "translation": "And [recall] when you said, \"O Moses, we will never believe you until we see Allah outright\"; so the thunderbolt took you while you were looking on."}, {"ayah": 56, "translit": "Summa ba'asnaakum mim ba'di mawtikum la'allakum tashkuroon", "translation": "Then We revived you after your death that perhaps you would be grateful."}, {"ayah": 57, "translit": "Wa zallalnaa 'alaikumul ghamaama wa anzalnaa 'alaikumul Manna was Salwaa kuloo min taiyibaati maa razaqnaakum wa maa zalamoonaa wa laakin kaanooo anfusahum yazlimoon", "translation": "And We shaded you with clouds and sent down to you manna and quails, [saying], \"Eat from the good things with which We have provided you.\" And they wronged Us not - but they were [only] wronging themselves."}, {"ayah": 58, "translit": "Wa iz qulnad khuloo haazihil qaryata fakuloo minhaa haisu shi'tum raghadanw wadkhulul baaba sujjadanw wa qooloo hittatun naghfir lakum khataayaakum; wa sanazeedul muhsineen", "translation": "And [recall] when We said, \"Enter this city and eat from it wherever you will in [ease and] abundance, and enter the gate bowing humbly and say, 'Relieve us of our burdens.' We will [then] forgive your sins for you, and We will increase the doers of good [in goodness and reward].\""}, {"ayah": 59, "translit": "Fabaddalal lazeena zalamoo qawlan ghairal lazee qeela lahum fa anzalnaa 'alal lazeena zalamoo rijzam minas samaaa'i bimaa kaanoo yafsuqoon", "translation": "But those who wronged changed [those words] to a statement other than that which had been said to them, so We sent down upon those who wronged a punishment from the sky because they were defiantly disobeying."}, {"ayah": 60, "translit": "Wa izis tasqaa Moosaa liqawmihee faqulnad rib bi'asaakal hajara fanfajarat minhusnataaa 'ashrata 'aynan qad 'alima kullu unaasim mash rabahum kuloo washraboo mir rizqil laahi wa laa ta'saw fil ardi mufsideen", "translation": "And [recall] when Moses prayed for water for his people, so We said, \"Strike with your staff the stone.\" And there gushed forth from it twelve springs, and every people knew its watering place. \"Eat and drink from the provision of Allah, and do not commit abuse on the earth, spreading corruption.\""}, {"ayah": 61, "translit": "Wa iz qultum yaa Moosaa lan nasbira 'alaa ta'aaminw waahidin fad'u lanaa rabbaka yukhrij lanaa mimmaa tumbitul ardu mimbaqlihaa wa qis saaa'ihaa wa foomihaa wa 'adasihaa wa basalihaa qaala atastabdiloonal lazee huwa adnaa billazee huwa khayr; ihbitoo misran fa inna lakum maa sa altum; wa duribat 'alaihimuz zillatu walmaskanatu wa baaa'oo bighadabim minal laah; zaalika bi annahum kaano yakfuroona bi aayaatil laahi wa yaqtuloonan Nabiyyeena bighairil haqq; zaalika bimaa 'asaw wa kaanoo ya'tadoon", "translation": "And [recall] when you said, \"O Moses, we can never endure one [kind of] food. So call upon your Lord to bring forth for us from the earth its green herbs and its cucumbers and its garlic and its lentils and its onions.\" [Moses] said, \"Would you exchange what is better for what is less? Go into [any] settlement and indeed, you will have what you have asked.\" And they were covered with humiliation and poverty and returned with anger from Allah [upon them]. That was because they [repeatedly] disbelieved in the signs of Allah and killed the prophets without right. That was because they disobeyed and were [habitually] transgressing."}, {"ayah": 62, "translit": "Innal lazeena aamanoo wallazeena haadoo wan nasaaraa was Saabi'eena man aamana billaahi wal yawmil aakhiri wa 'amila saalihan falahum ajruhum 'inda Rabbihim wa laa khawfun 'alaihim wa laa hum yahzanoon", "translation": "Indeed, those who believed and those who were Jews or Christians or Sabeans [before Prophet Muhammad] - those [among them] who believed in Allah and the Last Day and did righteousness - will have their reward with their Lord, and no fear will there be concerning them, nor will they grieve."}, {"ayah": 63, "translit": "Wa iz akhaznaa meesaaqakum wa rafa'naa fawqakumut Toora khuzoo maaa aatainaakum biquwwatinw wazkuroo maa feehi la'allakum tattaqoon", "translation": "And [recall] when We took your covenant, [O Children of Israel, to abide by the Torah] and We raised over you the mount, [saying], \"Take what We have given you with determination and remember what is in it that perhaps you may become righteous.\""}, {"ayah": 64, "translit": "Summa tawallaitum mim ba'di zaalika falawlaa fadlul laahi 'alaikum wa rahmatuhoo lakuntum minal khaasireen", "translation": "Then you turned away after that. And if not for the favor of Allah upon you and His mercy, you would have been among the losers."}, {"ayah": 65, "translit": "Wa laqad 'alimtumul lazeena'-tadaw minkum fis Sabti faqulnaa lahum koonoo qiradatan khaasi'een", "translation": "And you had already known about those who transgressed among you concerning the sabbath, and We said to them, \"Be apes, despised.\""}, {"ayah": 66, "translit": "Faja'alnaahaa nakaalal limaa baina yadihaa wa maa khalfahaa wa maw'izatal lilmuttaqeen", "translation": "And We made it a deterrent punishment for those who were present and those who succeeded [them] and a lesson for those who fear Allah."}, {"ayah": 67, "translit": "Wa iz qaala Moosaa liqawmiheee innal laaha yaamurukum an tazbahoo baqaratan qaalooo atattakhizunna huzuwan qaala a'oozu billaahi an akoona minal jaahileen", "translation": "And [recall] when Moses said to his people, \"Indeed, Allah commands you to slaughter a cow.\" They said, \"Do you take us in ridicule?\" He said, \"I seek refuge in Allah from being among the ignorant.\""}, {"ayah": 68, "translit": "Qaalud-'u lanaa rabbaka yubaiyil lanaa maa hee; qaala innahoo yaqoolu innahaa baqaratul laa faaridunw wa laa bikrun 'awaanum baina zaalika faf'aloo maa tu'maroon", "translation": "They said, \"Call upon your Lord to make clear to us what it is.\" [Moses] said, \"[Allah] says, 'It is a cow which is neither old nor virgin, but median between that,' so do what you are commanded.\""}, {"ayah": 69, "translit": "Qaalud-'u lanaa rabaaka yubaiyil lanaa maa lawnuhaa; qaala innahoo yaqoolu innahaa baqaratun safraaa'u faqi'ul lawnuhaa tasurrunnaazireen", "translation": "They said, \"Call upon your Lord to show us what is her color.\" He said, \"He says, 'It is a yellow cow, bright in color - pleasing to the observers.' \""}, {"ayah": 70, "translit": "Qaalud-'u lanaa rabbaka yubaiyil lanaa maa hiya innal baqara tashaabaha 'alainaa wa innaaa in shaaa'al laahu lamuhtadoon", "translation": "They said, \"Call upon your Lord to make clear to us what it is. Indeed, [all] cows look alike to us. And indeed we, if Allah wills, will be guided.\""}, {"ayah": 71, "translit": "Qaala innahoo yaqoolu innahaa baqaratul laa zaloolun tuseerul arda wa laa tasqil harsa musallamatullaa shiyata feehaa; qaalul 'aana jita bilhaqq; fazabahoohaa wa maa kaado yaf'aloon", "translation": "He said, \"He says, 'It is a cow neither trained to plow the earth nor to irrigate the field, one free from fault with no spot upon her.' \" They said, \"Now you have come with the truth.\" So they slaughtered her, but they could hardly do it."}, {"ayah": 72, "translit": "Wa iz qataltum nafsan faddaara'tum feehaa wallaahu mukrijum maa kuntum taktumoon", "translation": "And [recall] when you slew a man and disputed over it, but Allah was to bring out that which you were concealing."}, {"ayah": 73, "translit": "Faqulnad riboohu biba'dihaa; kazaalika yuhyil laa hul mawtaa wa yureekum aayaatihee la'allakum ta'qiloon", "translation": "So, We said, \"Strike the slain man with part of it.\" Thus does Allah bring the dead to life, and He shows you His signs that you might reason."}, {"ayah": 74, "translit": "Summa qasat quloobukum mim ba'di zaalika fahiya kalhijaarati aw-ashaadu qaswah; wa inna minal hijaarati lamaa yatafajjaru minhul anhaar; wa inna minhaa lamaa yash shaqqaqu fayakhruju minhul maaa'; wa inna minhaa lamaa yahbitu min khashyatil laa; wa mal laahu bighaafilin 'ammaa ta'maloon", "translation": "Then your hearts became hardened after that, being like stones or even harder. For indeed, there are stones from which rivers burst forth, and there are some of them that split open and water comes out, and there are some of them that fall down for fear of Allah. And Allah is not unaware of what you do."}, {"ayah": 75, "translit": "Afatatma'oona ai yu'minoo lakum wa qad kaana fareequm minhum yasma'oona Kalaamal laahi summa yuharri foonahoo mim ba'di maa'aqaloohu wa hum ya'lamoon", "translation": "Do you covet [the hope, O believers], that they would believe for you while a party of them used to hear the words of Allah and then distort the Torah after they had understood it while they were knowing?"}, {"ayah": 76, "translit": "Wa izaa laqul lazeena aamanoo qaalooo aamannaa wa izaakhalaa ba'duhum ilaa ba'din qaalooo atuhaddisoonahum bimaa fatahal laahu 'alaikum liyuhaajjookum bihee 'inda rabbikum; afalaa ta'qiloon", "translation": "And when they meet those who believe, they say, \"We have believed\"; but when they are alone with one another, they say, \"Do you talk to them about what Allah has revealed to you so they can argue with you about it before your Lord?\" Then will you not reason?"}, {"ayah": 77, "translit": "Awalaa ya'lamoona annal laaha ya'lamu maa yusirroona wa maa yu'linoon", "translation": "But do they not know that Allah knows what they conceal and what they declare?"}, {"ayah": 78, "translit": "Wa minhum ummiyyoona laa ya'lamoonal kitaaba illaaa amaaniyya wa in hum illaa yazunnoon", "translation": "And among them are unlettered ones who do not know the Scripture except in wishful thinking, but they are only assuming."}, {"ayah": 79, "translit": "Fawailul lillazeena yaktuboonal kitaaba bi aydddhim summa yaqooloona haazaa min 'indil laahi liyashtaroo bihee samanan qaleelan fawilul lahum mimaa katabat aydeehim wa wailul lahum mimmaa yaksiboon", "translation": "So woe to those who write the \"scripture\" with their own hands, then say, \"This is from Allah,\" in order to exchange it for a small price. Woe to them for what their hands have written and woe to them for what they earn."}, {"ayah": 80, "translit": "Wa qaaloo lan tamassanan Naaru illaaa ayyaamam ma'doo dah; qul attakhaztum 'indal laahi 'ahdan falai yukhlifal laahu 'ahdahooo am taqooloona 'alal laahi maa laa ta'lamoon", "translation": "And they say, \"Never will the Fire touch us, except for a few days.\" Say, \"Have you taken a covenant with Allah? For Allah will never break His covenant. Or do you say about Allah that which you do not know?\""}, {"ayah": 81, "translit": "Balaa man kasaba sayyi'atanw wa ahaatat bihee khateee'atuhoo fa-ulaaa'ika Ashaabun Naari hum feehaa khaalidoon", "translation": "Yes, whoever earns evil and his sin has encompassed him - those are the companions of the Fire; they will abide therein eternally."}, {"ayah": 82, "translit": "Wallazeena aamanoo wa 'amilus saalihaati ulaaa'ika Ashaabul Jannati hum feeha khaalidoon", "translation": "But they who believe and do righteous deeds - those are the companions of Paradise; they will abide therein eternally."}, {"ayah": 83, "translit": "Wa iz akhaznaa meesaaqa Baneee Israaa'eela laa ta'budoona illal laaha wa bil waalidaini ihsaananw wa zil qurbaa walyataamaa walmasaakeeni wa qooloo linnaasi husnanw wa aqeemus salaata wa aatuzZakaata summa tawallitum illaa qaleelam minkum wa antum mu'ridoon", "translation": "And [recall] when We took the covenant from the Children of Israel, [enjoining upon them], \"Do not worship except Allah; and to parents do good and to relatives, orphans, and the needy. And speak to people good [words] and establish prayer and give zakah.\" Then you turned away, except a few of you, and you were refusing."}, {"ayah": 84, "translit": "Wa iz akhaznaa meesaa qakum laa tasfikoona dimaaa'akum wa laa tukrijoona anfusakum min diyaarikum summa aqrartum wa antum tashhadoon", "translation": "And [recall] when We took your covenant, [saying], \"Do not shed each other's blood or evict one another from your homes.\" Then you acknowledged [this] while you were witnessing."}, {"ayah": 85, "translit": "Summa antum haaa'ulaaa'i taqtuloona anfusakum wa tukhrijoona fareeqam minkum min diyaarihim tazaaharoona 'alaihim bil ismi wal'udwaani wa iny yaatookum usaaraa tufaadoohum wahuwa muharramun 'alaikum ikhraajuhum; afatu' mi-noona biba'dil Kitaabi wa takfuroona biba'd; famaa jazaaa'u mai yaf'alu zaalika minkum illaa khizyun fil hayaatid-dunyaa wa yawmal qiyaamati yuraddoona ilaaa ashaddil 'azaab; wa mal laahu bighaafilin 'ammaa ta'maloon", "translation": "Then, you are those [same ones who are] killing one another and evicting a party of your people from their homes, cooperating against them in sin and aggression. And if they come to you as captives, you ransom them, although their eviction was forbidden to you. So do you believe in part of the Scripture and disbelieve in part? Then what is the recompense for those who do that among you except disgrace in worldly life; and on the Day of Resurrection they will be sent back to the severest of punishment. And Allah is not unaware of what you do."}, {"ayah": 86, "translit": "Ulaaa'ikal lazeenash tarawul hayaatad dunyaa bil aakhirati falaa yukhaffafu 'anhumul 'azaabu wa laa hum yunsaroon", "translation": "Those are the ones who have bought the life of this world [in exchange] for the Hereafter, so the punishment will not be lightened for them, nor will they be aided."}, {"ayah": 87, "translit": "Wa laqad aatainaa Moosal Kitaaba wa qaffainaa mim ba'dihee bir Rusuli wa aatainaa 'Eesab-na-Maryamal baiyinaati wa ayyadnaahu bi Roohil Qudus; afakullamaa jaaa'akum Rasoolum bimaa laa tahwaaa anfusukumus takbartum fafareeqan kazzabtum wa fareeqan taqtuloon", "translation": "And We did certainly give Moses the Torah and followed up after him with messengers. And We gave Jesus, the son of Mary, clear proofs and supported him with the Pure Spirit. But is it [not] that every time a messenger came to you, [O Children of Israel], with what your souls did not desire, you were arrogant? And a party [of messengers] you denied and another party you killed."}, {"ayah": 88, "translit": "Wa qaaloo quloobunaa ghulf; bal la'anahumul laahu bikufrihim faqaleelam maa yu'minoon", "translation": "And they said, \"Our hearts are wrapped.\" But, [in fact], Allah has cursed them for their disbelief, so little is it that they believe."}, {"ayah": 89, "translit": "Wa lammaa jaaa'ahum Kitaabum min 'indil laahi musaddiqul limaa ma'ahum wa kaanoo min qablu yastaftihoona 'alal lazeena kafaroo falammaa jaaa'ahum maa 'arafoo kafaroo bih; fala 'natul laahi 'alal kaafireen", "translation": "And when there came to them a Book from Allah confirming that which was with them - although before they used to pray for victory against those who disbelieved - but [then] when there came to them that which they recognized, they disbelieved in it; so the curse of Allah will be upon the disbelievers."}, {"ayah": 90, "translit": "Bi'samash taraw biheee anfusahum ai yakfuroo bimaaa anzalal laahu baghyan ai yunazzilal laahu min fadlilhee 'alaa mai yashaaa'u min ibaadihee fabaaa'oo bighadabin 'alaa ghadab; wa lilkaafireena 'azaabum muheen", "translation": "How wretched is that for which they sold themselves - that they would disbelieve in what Allah has revealed through [their] outrage that Allah would send down His favor upon whom He wills from among His servants. So they returned having [earned] wrath upon wrath. And for the disbelievers is a humiliating punishment."}, {"ayah": 91, "translit": "Wa izaa qeela lahum aaminoo bimaaa anzalal laahu qaaloo nu'minu bimaaa unzila 'alainaa wa yakfuroona bimaa waraaa'ahoo wa huwal haqqu musaddiqal limaa ma'ahum; qul falima taqtuloona Ambiyaaa'al laahi min qablu in kuntum mu'mineen", "translation": "And when it is said to them, \"Believe in what Allah has revealed,\" they say, \"We believe [only] in what was revealed to us.\" And they disbelieve in what came after it, while it is the truth confirming that which is with them. Say, \"Then why did you kill the prophets of Allah before, if you are [indeed] believers?\""}, {"ayah": 92, "translit": "Wa laqad jaaa'akum Moosa bilbaiyinaati summat takhaztunmul 'ijla mim ba'dihee wa antum zaalimoon", "translation": "And Moses had certainly brought you clear proofs. Then you took the calf [in worship] after that, while you were wrongdoers."}, {"ayah": 93, "translit": "Wa iz akhaznaa meesaaqakum wa rafa'naa fawqa kumut Toora khuzoo maaa aatainaakum biquwwatinw wasma'oo qaaloo sami'naa wa 'asainaa wa ushriboo fee quloobihimul 'ijla bikufrihim; qul bi'samaa yaamurukum biheee eemaanukum in kuntum mu'mineen", "translation": "And [recall] when We took your covenant and raised over you the mount, [saying], \"Take what We have given you with determination and listen.\" They said [instead], \"We hear and disobey.\" And their hearts absorbed [the worship of] the calf because of their disbelief. Say, \"How wretched is that which your faith enjoins upon you, if you should be believers.\""}, {"ayah": 94, "translit": "Qul in kaanat lakumud Daarul Aakhiratu 'indal laahi khaalisatam min doonin naasi fatamannawul mawta in kuntum saadiqeen", "translation": "Say, [O Muhammad], \"If the home of the Hereafter with Allah is for you alone and not the [other] people, then wish for death, if you should be truthful."}, {"ayah": 95, "translit": "Wa lai yatamannawhu abadam bimaa qaddamat aydeehim; wallaahu 'aleemum bizzaalimeen", "translation": "But they will never wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers."}, {"ayah": 96, "translit": "Wa latajidannahum ahrasannaasi 'alaa hayaatinw wa minal lazeena ashrakoo; yawaddu ahaduhum law yu'ammaru alfa sanatinw wa maa huwa bi muzahzihihee minal 'azaabi ai yu'ammar; wallaahu baseerum bimaa ya'maloon", "translation": "And you will surely find them the most greedy of people for life - [even] more than those who associate others with Allah. One of them wishes that he could be granted life a thousand years, but it would not remove him in the least from the [coming] punishment that he should be granted life. And Allah is Seeing of what they do."}, {"ayah": 97, "translit": "Qul man kaana 'aduwwal li Jibreela fainnahoo nazzalahoo 'alaa qalbika bi iznil laahi musaddiqal limaa baina yadihi wa hudanw wa bushraa lilmu'mineen", "translation": "Say, \"Whoever is an enemy to Gabriel - it is [none but] he who has brought the Qur'an down upon your heart, [O Muhammad], by permission of Allah, confirming that which was before it and as guidance and good tidings for the believers.\""}, {"ayah": 98, "translit": "Man kaana 'aduwwal lillaahi wa malaaa'ikatihee wa Rusulihee wa Jibreela wa Meekaala fa innal laaha 'aduwwul lilkaafireen", "translation": "Whoever is an enemy to Allah and His angels and His messengers and Gabriel and Michael - then indeed, Allah is an enemy to the disbelievers."}, {"ayah": 99, "translit": "Wa laqad anzalnaaa ilaika Aayaatim baiyinaatinw wa maa yakfuru bihaaa illal faasiqoon", "translation": "And We have certainly revealed to you verses [which are] clear proofs, and no one would deny them except the defiantly disobedient."}, {"ayah": 100, "translit": "Awa kullamaa 'aahadoo ahdan nabazahoo fareequm minhum; bal aksaruhum laa u'minoon", "translation": "Is it not [true] that every time they took a covenant a party of them threw it away? But, [in fact], most of them do not believe."}, {"ayah": 101, "translit": "Wa lammaa jaaa'ahum Rasoolum min 'indil laahi musaddiqul limaa ma'ahum nabaza fareequm minal lazeena ootul Kitaaba Kitaabal laahi waraaa'a zuhoorihim ka annahum laa ya'lamoon", "translation": "And when a messenger from Allah came to them confirming that which was with them, a party of those who had been given the Scripture threw the Scripture of Allah behind their backs as if they did not know [what it contained]."}, {"ayah": 102, "translit": "Wattaba'oo maa tatlush Shayaateenu 'alaa mulki Sulaimaana wa maa kafara Sulaimaanu wa laakinnash Shayattena kafaroo yu'al limoonan naasas sihra wa maaa unzila 'alal malakaini bi Baabila Haaroota wa Maaroot; wa maa yu'allimaani min ahadin hattaa yaqoolaaa innamaa nahnu fitnatun falaa takfur fayata'al lamoona minhumaa maa yufarriqoona bihee bainal mar'i wa zawjih; wa maa hum bidaaarreena bihee min ahadin illaa bi-iznillah; wa yata'allamoona maa yadurruhum wa laa yanfa'uhum; wa laqad 'alimoo lamanish taraahu maa lahoo fil Aakhirati min khalaaq; wa labi'sa maa sharaw biheee anfusahum; law kaanoo ya'lamoon", "translation": "And they followed [instead] what the devils had recited during the reign of Solomon. It was not Solomon who disbelieved, but the devils disbelieved, teaching people magic and that which was revealed to the two angels at Babylon, Harut and Marut. But the two angels do not teach anyone unless they say, \"We are a trial, so do not disbelieve [by practicing magic].\" And [yet] they learn from them that by which they cause separation between a man and his wife. But they do not harm anyone through it except by permission of Allah. And the people learn what harms them and does not benefit them. But the Children of Israel certainly knew that whoever purchased the magic would not have in the Hereafter any share. And wretched is that for which they sold themselves, if they only knew."}, {"ayah": 103, "translit": "Wa law annahum aamanoo wattaqaw lamasoobatum min 'indillaahi khairun law kaanoo ya'lamoon", "translation": "And if they had believed and feared Allah, then the reward from Allah would have been [far] better, if they only knew."}, {"ayah": 104, "translit": "Yaaa ayyuhal lazeena aamanoo laa taqooloo raa'inaa wa qoolun zurnaa wasma'oo; wa lilkaafireena 'azaabun aleem", "translation": "O you who have believed, say not [to Allah 's Messenger], \"Ra'ina\" but say, \"Unthurna\" and listen. And for the disbelievers is a painful punishment."}, {"ayah": 105, "translit": "Maa yawaddul lazeena kafaroo min ahlil kitaabi wa lal mushrikeena ai-yunazzala 'alaikum min khairim mir Rabbikum; wallaahu yakhtassu birahmatihee mai-yashaaa; wallaahu zul fadlil'azeem", "translation": "Neither those who disbelieve from the People of the Scripture nor the polytheists wish that any good should be sent down to you from your Lord. But Allah selects for His mercy whom He wills, and Allah is the possessor of great bounty."}, {"ayah": 106, "translit": "Maa nansakh min aayatin aw nunsihaa na-ti bikhairim minhaaa aw mislihaaa; alam ta'lam annal laaha 'alaa kulli shai'in qadeer", "translation": "We do not abrogate a verse or cause it to be forgotten except that We bring forth [one] better than it or similar to it. Do you not know that Allah is over all things competent?"}, {"ayah": 107, "translit": "Alam ta'lam annallaaha lahoo mulkus samaawaati wal ard; wa maa lakum min doonil laahi minw waliyyinw wa laa naseer", "translation": "Do you not know that to Allah belongs the dominion of the heavens and the earth and [that] you have not besides Allah any protector or any helper?"}, {"ayah": 108, "translit": "Am tureedoona an tas'aloo Rasoolakum kamaa su'ila Moosa min qabl; wa mai yatabaddalil kufra bil eemaani faqad dalla sawaaa'as sabeel", "translation": "Or do you intend to ask your Messenger as Moses was asked before? And whoever exchanges faith for disbelief has certainly strayed from the soundness of the way."}, {"ayah": 109, "translit": "Wadda kaseerum min ahlil kitaabi law yaruddoo nakum mim ba'di eemaanikum kuffaaran hasadam min 'indi anfusihim mim ba'di maa tabaiyana lahumul haqqu fa'foo washfahoo hattaa yaa tiyallaahu bi amrih; innal laaha 'alaa kulli shai'in qadeer", "translation": "Many of the People of the Scripture wish they could turn you back to disbelief after you have believed, out of envy from themselves [even] after the truth has become clear to them. So pardon and overlook until Allah delivers His command. Indeed, Allah is over all things competent."}, {"ayah": 110, "translit": "Wa aqeemus salaata wa aatuz zakaah; wa maa tuqaddimoo li anfusikum min khairin tajidoohu 'indal laah; innal laaha bimaa ta'maloona baseer", "translation": "And establish prayer and give zakah, and whatever good you put forward for yourselves - you will find it with Allah. Indeed, Allah of what you do, is Seeing."}, {"ayah": 111, "translit": "Wa qaaloo lai yadkhulal jannata illaa man kaana Hoodan aw Nasaaraa; tilka ammniyyuhum; qul haatoo burhaa nakum in kuntum saadiqeen", "translation": "And they say, \"None will enter Paradise except one who is a Jew or a Christian.\" That is [merely] their wishful thinking, Say, \"Produce your proof, if you should be truthful.\""}, {"ayah": 112, "translit": "Balaa man aslama wajhahoo lillaahi wa huwa muhsinun falahooo ajruhoo 'inda rabbihee wa laa khawfun 'alaihim wa laa hum yahzanoon", "translation": "Yes [on the contrary], whoever submits his face in Islam to Allah while being a doer of good will have his reward with his Lord. And no fear will there be concerning them, nor will they grieve."}, {"ayah": 113, "translit": "Wa qaalatil Yahoodu laisatin Nasaaraa 'alaa shai'inw-wa qaalatin Nasaaraaa laisatil Yahoodu 'alaa shai'inw'wa hum yatloonal Kitaab; kazaalika qaalal lazeena la ya'lamoona misla qawlihim Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon", "translation": "The Jews say \"The Christians have nothing [true] to stand on,\" and the Christians say, \"The Jews have nothing to stand on,\" although they [both] recite the Scripture. Thus the polytheists speak the same as their words. But Allah will judge between them on the Day of Resurrection concerning that over which they used to differ."}, {"ayah": 114, "translit": "Wa man azlamu mimmam-mana'a masaajidal laahi ai-yuzkara feehas muhoo wa sa'aa fee kharaabihaaa; ulaaa'ika maa kaana lahum ai yadkhuloohaaa illaa khaaa''feen; lahum fiddunyaa khizyunw wa lahum fil aakhirati 'azaabun 'azeem", "translation": "And who are more unjust than those who prevent the name of Allah from being mentioned in His mosques and strive toward their destruction. It is not for them to enter them except in fear. For them in this world is disgrace, and they will have in the Hereafter a great punishment."}, {"ayah": 115, "translit": "Wa lillaahil mashriqu walmaghrib; fa aynamaa tuwalloo fasamma wajhullaah; innal laaha waasi'un Aleem", "translation": "And to Allah belongs the east and the west. So wherever you [might] turn, there is the Face of Allah. Indeed, Allah is all-Encompassing and Knowing."}, {"ayah": 116, "translit": "Wa qaalut takhazal laahu waladan subhaanahoo bal lahoo maa fis samaawaati wal ardi kullul lahoo qaanitoon", "translation": "They say, \"Allah has taken a son.\" Exalted is He! Rather, to Him belongs whatever is in the heavens and the earth. All are devoutly obedient to Him,"}, {"ayah": 117, "translit": "Badree'us samaawaati wal ardi wa izaa qadaaa amran fa innamaa yaqoolu lahoo kun fayakoon", "translation": "Originator of the heavens and the earth. When He decrees a matter, He only says to it, \"Be,\" and it is."}, {"ayah": 118, "translit": "Wa qaalal lazeena laa ya'lamoona law laa yukallimunal laahu aw taateenaaa aayah; kazaalika qaalal lazeena min qablihim misla qawlihim; tashaabahat quloobuhum; qad baiyannal aayaati liqawminy yooqinoon", "translation": "Those who do not know say, \"Why does Allah not speak to us or there come to us a sign?\" Thus spoke those before them like their words. Their hearts resemble each other. We have shown clearly the signs to a people who are certain [in faith]."}, {"ayah": 119, "translit": "Innaaa arsalnaaka bilhaqqi basheeranw wa nazeeranw wa laa tus'alu 'am Ashaabil Jaheem", "translation": "Indeed, We have sent you, [O Muhammad], with the truth as a bringer of good tidings and a warner, and you will not be asked about the companions of Hellfire."}, {"ayah": 120, "translit": "Wa lan tardaa 'ankal Yahoodu wa lan Nasaaraa hattaa tattabi'a millatahum; qul inna hudal laahi huwalhudaa; wa la'init taba'ta ahwaaa'ahum ba'dal lazee jaaa'aka minal 'ilmimaa laka minal laahi minw waliyyinw wa laa naseer", "translation": "And never will the Jews or the Christians approve of you until you follow their religion. Say, \"Indeed, the guidance of Allah is the [only] guidance.\" If you were to follow their desires after what has come to you of knowledge, you would have against Allah no protector or helper."}, {"ayah": 121, "translit": "Allazeena aatainaahumul Kitaaba yatloonahoo haqqa tilaawatiheee ulaaa'ika yu'minoona bi; wa mai yakfur bihee fa ulaaa'ika humul khaasiroon", "translation": "Those to whom We have given the Book recite it with its true recital. They [are the ones who] believe in it. And whoever disbelieves in it - it is they who are the losers."}, {"ayah": 122, "translit": "Yaa Baneee Israaa'eelaz-kuroo ni'matiyal lateee an'amtu 'alaikum wa annee faddaltukum 'alal 'aalameen", "translation": "O Children of Israel, remember My favor which I have bestowed upon you and that I preferred you over the worlds."}, {"ayah": 123, "translit": "Wattaqoo yawmal laa tajzee nafsun 'an nafsin shai 'anw wa laa yuqbalu minhaa 'adlunw wa laa tanfa'uhaa shafaa 'atunw wa laa hum yunsaroon", "translation": "And fear a Day when no soul will suffice for another soul at all, and no compensation will be accepted from it, nor will any intercession benefit it, nor will they be aided."}, {"ayah": 124, "translit": "Wa izib talaaa Ibraaheema Rabbuho bi Kalimaatin fa atammahunna qaala Innee jaa'iluka linnaasi Imaaman qaala wa min zurriyyatee qaala laa yanaalu 'ahdiz zaalimeen", "translation": "And [mention, O Muhammad], when Abraham was tried by his Lord with commands and he fulfilled them. [Allah] said, \"Indeed, I will make you a leader for the people.\" [Abraham] said, \"And of my descendants?\" [Allah] said, \"My covenant does not include the wrongdoers.\""}, {"ayah": 125, "translit": "Wa iz ja'alnal Baita masaabatal linnassi wa amnanw wattakhizoo mim Maqaami Ibraaheema musallaaa; wa 'ahidnaaa ilaaa Ibraaheema wa Ismaa'eela an tahhiraa Baitiya littaaa'ifeena wal'aakifeena warrukka'is sujood", "translation": "And [mention] when We made the House a place of return for the people and [a place of] security. And take, [O believers], from the standing place of Abraham a place of prayer. And We charged Abraham and Ishmael, [saying], \"Purify My House for those who perform Tawaf and those who are staying [there] for worship and those who bow and prostrate [in prayer].\""}, {"ayah": 126, "translit": "Wa iz qaala Ibraaheemu Rabbij 'al haazaa baladan aaminanw warzuq ahlahoo minas samaraati man aamana minhum billaahi wal yawmil aakhiri qaala wa man kafara faumatti'uhoo qaleelan summa adtarruhooo ilaa 'azaabin Naari wa bi'salmaseer", "translation": "And [mention] when Abraham said, \"My Lord, make this a secure city and provide its people with fruits - whoever of them believes in Allah and the Last Day.\" [Allah] said. \"And whoever disbelieves - I will grant him enjoyment for a little; then I will force him to the punishment of the Fire, and wretched is the destination.\""}, {"ayah": 127, "translit": "Wa iz yarfa'u Ibraaheemul qawaa'ida minal Baitiwa Ismaa'eelu Rabbanaa taqabbal minnaa innaka Antas Samee'ul Aleem", "translation": "And [mention] when Abraham was raising the foundations of the House and [with him] Ishmael, [saying], \"Our Lord, accept [this] from us. Indeed You are the Hearing, the Knowing."}, {"ayah": 128, "translit": "Rabbanaa waj'alnaa muslimaini laka wa min zurriyyatinaaa ummatam muslimatal laka wa arinaa manaasikanaa wa tub 'alainaa innaka antat Tawwaabur Raheem", "translation": "Our Lord, and make us Muslims [in submission] to You and from our descendants a Muslim nation [in submission] to You. And show us our rites and accept our repentance. Indeed, You are the Accepting of repentance, the Merciful."}, {"ayah": 129, "translit": "Rabbanaa wab'as feehim Rasoolam minhum yatloo 'alaihim aayaatika wa yu'allimuhumul Kitaaba wal Hikmata wa yuzakkeehim; innaka Antal 'Azeezul Hakeem", "translation": "Our Lord, and send among them a messenger from themselves who will recite to them Your verses and teach them the Book and wisdom and purify them. Indeed, You are the Exalted in Might, the Wise.\""}, {"ayah": 130, "translit": "Wa manny yarghabu 'am-Millarti Ibraaheema illaa man safiha nafsah; wa laqadis tafainaahu fid-dunyaa wa innaho fil aakhirati laminas saaliheen", "translation": "And who would be averse to the religion of Abraham except one who makes a fool of himself. And We had chosen him in this world, and indeed he, in the Hereafter, will be among the righteous."}, {"ayah": 131, "translit": "Iz qaala lahoo Rabbuhooo aslim qaala aslamtu li Rabbil 'aalameen", "translation": "When his Lord said to him, \"Submit\", he said \"I have submitted [in Islam] to the Lord of the worlds.\""}, {"ayah": 132, "translit": "Wa wassaa bihaaa Ibraaheemu baneehi wa Ya'qoob, yaa baniyya innal laahas tafaa lakumud deena falaa tamootunna illaa wa antum muslimoon", "translation": "And Abraham instructed his sons [to do the same] and [so did] Jacob, [saying], \"O my sons, indeed Allah has chosen for you this religion, so do not die except while you are Muslims.\""}, {"ayah": 133, "translit": "Am kuntum shuhadaaa'a iz hadara Ya'qoobal mawtu iz qaala libaneehi maa ta'budoona mim ba'dee qaaloo na'budu ilaahaka wa ilaaha aabaaa'ika Ibraaheema wa Ismaa'eela wa Ishaaqa Ilaahanw waahidanw wa nahnu lahoo muslimoon", "translation": "Or were you witnesses when death approached Jacob, when he said to his sons, \"What will you worship after me?\" They said, \"We will worship your God and the God of your fathers, Abraham and Ishmael and Isaac - one God. And we are Muslims [in submission] to Him.\""}, {"ayah": 134, "translit": "Tilka ummatun qad khalat lahaa maa kasabat wa lakum maa kasabtum wa laa tus'aloona 'ammaa kaano ya'maloon", "translation": "That was a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do."}, {"ayah": 135, "translit": "Wa qaaloo koonoo Hoodan aw Nasaaraa tahtadoo; qul bal Millata Ibraaheema Haneefanw wa maa kaana minal mushrikeen", "translation": "They say, \"Be Jews or Christians [so] you will be guided.\" Say, \"Rather, [we follow] the religion of Abraham, inclining toward truth, and he was not of the polytheists.\""}, {"ayah": 136, "translit": "Qoolooo aamannaa billaahi wa maaa unzila ilainaa wa maaa unzila ilaaa Ibraaheema wa Ismaa'eela wa Ishaaqa wa Ya'qooba wal Asbaati wa maaootiya Moosa wa 'Eesaa wa maaa ootiyan Nabiyyoona mir Rabbihim laa nufaariq baina ahadim minhum wa nahnu lahoo muslimoon", "translation": "Say, [O believers], \"We have believed in Allah and what has been revealed to us and what has been revealed to Abraham and Ishmael and Isaac and Jacob and the Descendants and what was given to Moses and Jesus and what was given to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [in submission] to Him.\""}, {"ayah": 137, "translit": "Fa in aamanoo bimisli maaa aamantum bihee faqadih tadaw wa in tawallaw fa innamaa hum fee shiqaaq; fasayakfeekahumul laah; wa Huwas Samee'ul Aleem", "translation": "So if they believe in the same as you believe in, then they have been [rightly] guided; but if they turn away, they are only in dissension, and Allah will be sufficient for you against them. And He is the Hearing, the Knowing."}, {"ayah": 138, "translit": "Sibghatal laahi wa man ahsanu minal laahi sibghatanw wa nahnu lahoo 'aabidoon", "translation": "[And say, \"Ours is] the religion of Allah. And who is better than Allah in [ordaining] religion? And we are worshippers of Him.\""}, {"ayah": 139, "translit": "Qul atuhaaajjoonanaa fil laahi wa Huwa Rabbunaa wa Rabbukum wa lanaa a'maalunaa wa lakum a'maalukum wa nahnu lahoo mukhlisson", "translation": "Say, [O Muhammad], \"Do you argue with us about Allah while He is our Lord and your Lord? For us are our deeds, and for you are your deeds. And we are sincere [in deed and intention] to Him.\""}, {"ayah": 140, "translit": "Am taqooloona inna Ibraaheema wa Ismaa'eela wa Ishaaq wa Ya'qooba wal asbaata kaanoo Hoodan aw Nasaaraa; qul 'a-antum a'lamu amil laah; wa man azlamu mimman katama shahaadatan 'indahoo minallaah; wa mallaahu bighaafilin 'ammaa ta'maloon", "translation": "Or do you say that Abraham and Ishmael and Isaac and Jacob and the Descendants were Jews or Christians? Say, \"Are you more knowing or is Allah?\" And who is more unjust than one who conceals a testimony he has from Allah? And Allah is not unaware of what you do."}, {"ayah": 141, "translit": "Tilka ummatun qad khalat lahaa maa kasabat wa lakum maa kasabtum wa laa tus'aloona 'ammaa kaano ya'maloo", "translation": "That is a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do."}, {"ayah": 142, "translit": "Sayaqoolus sufahaaa'u minan naasi maa wallaahum 'an Qiblatihimul latee kaanoo 'alaihaa; qulo lillaahil mashriqu walmaghrib; yahdee mai yashaaa'u ilaa Siraatim Mustaqeem", "translation": "The foolish among the people will say, \"What has turned them away from their qiblah, which they used to face?\" Say, \"To Allah belongs the east and the west. He guides whom He wills to a straight path.\""}, {"ayah": 143, "translit": "Wa kazaalika ja'alnaakum ummatanw wasatal litakoonoo shuhadaaa'a 'alan naasi wa yakoonar Rasoolu 'alaikum  shaheedaa; wa maa ja'alnal qiblatal latee kunta 'alaihaaa illaa lina'lama mai yattabi'ur Rasoola mimmai yanqalibu 'alaa 'aqibayh; wa in kaanat lakabeeratan illaa 'alal lazeena hadal laah; wa maa kaanal laahu liyudee'a eemaanakum; innal laaha binnaasi la Ra'oofur Raheem", "translation": "And thus we have made you a just community that you will be witnesses over the people and the Messenger will be a witness over you. And We did not make the qiblah which you used to face except that We might make evident who would follow the Messenger from who would turn back on his heels. And indeed, it is difficult except for those whom Allah has guided. And never would Allah have caused you to lose your faith. Indeed Allah is, to the people, Kind and Merciful."}, {"ayah": 144, "translit": "Qad naraa taqalluba wajhika fis samaaa'i fala nuwalliyannaka qiblatan tardaahaa; fawalli wajhaka shatral Masjidil haaraam; wa haisu maa kuntum fawalloo wujoohakum shatrah; wa innal lazeena ootul Kitaaba laya'lamoona annahul haqqu mir Rabbihim; wa mal laahu bighaafilin 'ammaa ya'maloon", "translation": "We have certainly seen the turning of your face, [O Muhammad], toward the heaven, and We will surely turn you to a qiblah with which you will be pleased. So turn your face toward al-Masjid al-Haram. And wherever you [believers] are, turn your faces toward it [in prayer]. Indeed, those who have been given the Scripture well know that it is the truth from their Lord. And Allah is not unaware of what they do."}, {"ayah": 145, "translit": "Wa la'in ataital lazeena ootul kitaaba bikulli aayatim maa tabi'oo Qiblatak; wa maaa anta bitaabi'in Qiblatahum; wa maa ba'duhum bitaabi''in Qiblata ba'd; wa la'init taba'ta ahwaaa;ahum mim ba'di maa jaaa'aka minal 'ilmi innaka izal laminaz zaalimeen", "translation": "And if you brought to those who were given the Scripture every sign, they would not follow your qiblah. Nor will you be a follower of their qiblah. Nor would they be followers of one another's qiblah. So if you were to follow their desires after what has come to you of knowledge, indeed, you would then be among the wrongdoers."}, {"ayah": 146, "translit": "Allazeena aatainaahumul kitaaba ya'rifoonahoo kamaa ya'rifoona abnaaa'ahum wa inna fareeqam minhum layaktumoonal haqqa wa hum ya'lamoon", "translation": "Those to whom We gave the Scripture know him as they know their own sons. But indeed, a party of them conceal the truth while they know [it]."}, {"ayah": 147, "translit": "Alhaqqu mir Rabbika falaa takoonana minal mumtareen", "translation": "The truth is from your Lord, so never be among the doubters."}, {"ayah": 148, "translit": "Wa likullinw wijhatun huwa muwalleehaa fastabiqul khairaat; ayna maa takoonoo yaati bikumullaahu jamee'aa; innal laaha 'alaa kulli shai'in qadeer", "translation": "For each [religious following] is a direction toward which it faces. So race to [all that is] good. Wherever you may be, Allah will bring you forth [for judgement] all together. Indeed, Allah is over all things competent."}, {"ayah": 149, "translit": "Wa min haisu kharajta fawalli wajhaka shatral Masjidil Haraami wa innahoo lalhaqqu mir Rabbik; wa mallaahu bighaafilin 'ammaa ta'maloon", "translation": "So from wherever you go out [for prayer, O Muhammad] turn your face toward al- Masjid al-Haram, and indeed, it is the truth from your Lord. And Allah is not unaware of what you do."}, {"ayah": 150, "translit": "Wa min haisu kharajta fawalli wajhaka shatral Masjidil Haraam; wa haisu maa kuntum fawalloo wujoohakum shatrahoo li'allaa yakoona linnaasi 'alaikum hujjatun illal lazeena zalamoo minhum falaa takhshawhum wakhshawnee wa liutimma ni'matee 'alaikum wa la'allakum tahtadoon", "translation": "And from wherever you go out [for prayer], turn your face toward al-Masjid al-Haram. And wherever you [believers] may be, turn your faces toward it in order that the people will not have any argument against you, except for those of them who commit wrong; so fear them not but fear Me. And [it is] so I may complete My favor upon you and that you may be guided."}, {"ayah": 151, "translit": "kamaaa arsalnaa feekum Rasoolam minkum yatloo 'alaikum aayaatina wa yuzakkeekum wa yu'alli mukumul kitaaba wal hikmata wa yu'allimukum maa lam takoonoo ta'lamoon", "translation": "Just as We have sent among you a messenger from yourselves reciting to you Our verses and purifying you and teaching you the Book and wisdom and teaching you that which you did not know."}, {"ayah": 152, "translit": "Fazkurooneee azkurkum washkuroo lee wa laa takfuroon", "translation": "So remember Me; I will remember you. And be grateful to Me and do not deny Me."}, {"ayah": 153, "translit": "Yaaa ayyuhal laazeena aamanus ta'eenoo bissabri was Salaah; innal laaha ma'as-saabireen", "translation": "O you who have believed, seek help through patience and prayer. Indeed, Allah is with the patient."}, {"ayah": 154, "translit": "Wa laa taqooloo limai yuqtalu fee sabeelil laahi amwaat; bal ahyaaa'unw wa laakil laa tash'uroon", "translation": "And do not say about those who are killed in the way of Allah, \"They are dead.\" Rather, they are alive, but you perceive [it] not."}, {"ayah": 155, "translit": "Wa lanablu wannakum bishai'im minal khawfi waljoo'i wa naqsim minal amwaali wal anfusi was samaraat; wa bashshiris saabireen", "translation": "And We will surely test you with something of fear and hunger and a loss of wealth and lives and fruits, but give good tidings to the patient,"}, {"ayah": 156, "translit": "Allazeena izaaa asaabathum museebatun qaalooo innaa lillaahi wa innaaa ilaihi raaji'oon", "translation": "Who, when disaster strikes them, say, \"Indeed we belong to Allah, and indeed to Him we will return.\""}, {"ayah": 157, "translit": "Ulaaa'ika 'alaihim salawaatun mir Rabbihim wa rahma; wa ulaaa'ika humul muhtadoon", "translation": "Those are the ones upon whom are blessings from their Lord and mercy. And it is those who are the [rightly] guided."}, {"ayah": 158, "translit": "Innas Safaa wal-Marwata min sha'aaa'iril laahi faman hajjal Baita awi'tamara falaa junaaha 'alaihi ai yattawwafa bihimaa; wa man tatawwa'a khairan fa innal laaha Shaakirun'Aleem", "translation": "Indeed, as-Safa and al-Marwah are among the symbols of Allah. So whoever makes Hajj to the House or performs 'umrah - there is no blame upon him for walking between them. And whoever volunteers good - then indeed, Allah is appreciative and Knowing."}, {"ayah": 159, "translit": "Innal lazeena yaktumoona maaa anzalnaa minal baiyinaati walhudaa mim ba'di maa baiyannaahu linnaasi fil kitaabi ulaaa'ika yal'anuhumul laahu wa yal'anuhumul laa 'inoon", "translation": "Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Scripture - those are cursed by Allah and cursed by those who curse,"}, {"ayah": 160, "translit": "Illal lazeena taaboo wa aslahoo wa baiyanoo fa ulaaa'ika atoobu 'alaihim; wa Anat Tawwaabur Raheem", "translation": "Except for those who repent and correct themselves and make evident [what they concealed]. Those - I will accept their repentance, and I am the Accepting of repentance, the Merciful."}, {"ayah": 161, "translit": "Innal lazeena kafaroo wamaa too wa hum kuffaarun ulaaa'ika 'alaihim la 'natul laahi walmalaa'ikati wannaasi ajma'een", "translation": "Indeed, those who disbelieve and die while they are disbelievers - upon them will be the curse of Allah and of the angels and the people, all together,"}, {"ayah": 162, "translit": "khaalideena feeha laa yukhaffafu 'anhumul 'azaabu wa laa hum yunzaroon", "translation": "Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved."}, {"ayah": 163, "translit": "Wa ilaahukum illaahunw waahid, laaa ilaaha illaa Huwar Rahmaanur Raheem", "translation": "And your god is one God. There is no deity [worthy of worship] except Him, the Entirely Merciful, the Especially Merciful."}, {"ayah": 164, "translit": "Inna fee khalqis samaawaati wal ardi wakhtilaafil laili wannahaari walfulkil latee tajree fil hahri bimaa yanfa'unnaasa wa maaa anzalal laahu minas samaaa'i mim maaa'in fa ahyaa bihil arda ba'da mawtihaa wa bas sa feehaa min kulli daaabbatinw wa tasreefir riyaahi wassahaabil musakhkhari bainas samaaa'i wal ardi la aayaatil liqawminy ya'qiloon", "translation": "Indeed, in the creation of the heavens and earth, and the alternation of the night and the day, and the [great] ships which sail through the sea with that which benefits people, and what Allah has sent down from the heavens of rain, giving life thereby to the earth after its lifelessness and dispersing therein every [kind of] moving creature, and [His] directing of the winds and the clouds controlled between the heaven and the earth are signs for a people who use reason."}, {"ayah": 165, "translit": "Wa minan naasi mai yattakhizu min doonil laahi andaadai yuhibboonahum kahubbil laahi wallazeena aamanooo ashaddu hubbal lillah; wa law yaral lazeena zalamoo iz yarawnal 'azaaba annal quwwata lillaahi jamee'anw wa annallaaha shadeedul 'azaab", "translation": "And [yet], among the people are those who take other than Allah as equals [to Him]. They love them as they [should] love Allah. But those who believe are stronger in love for Allah. And if only they who have wronged would consider [that] when they see the punishment, [they will be certain] that all power belongs to Allah and that Allah is severe in punishment."}, {"ayah": 166, "translit": "Iz tabarra al lazeenat tubi'oo minal lazeenattaba'oo wa ra awul 'azaaba wa taqatta'at bihimul asbaab", "translation": "[And they should consider that] when those who have been followed disassociate themselves from those who followed [them], and they [all] see the punishment, and cut off from them are the ties [of relationship],"}, {"ayah": 167, "translit": "Wa qaalal lazeenat taba'oo law anna lanaa karratan fanatabarra a minhum kamaa tabarra'oo minnaa; kazaalika yureehimullaahu a'maalahum hasaraatin 'alaihim wa maa hum bikhaarijeena minan Naar", "translation": "Those who followed will say, \"If only we had another turn [at worldly life] so we could disassociate ourselves from them as they have disassociated themselves from us.\" Thus will Allah show them their deeds as regrets upon them. And they are never to emerge from the Fire."}, {"ayah": 168, "translit": "Yaaa ayyuhan naasu kuloo mimmaa fil ardi halaalan taiyibanw wa laa tattabi'oo khutu waatish Shaitaan; innahoo lakum 'aduwwum mubeen", "translation": "O mankind, eat from whatever is on earth [that is] lawful and good and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy."}, {"ayah": 169, "translit": "Innamaa yaamurukum bissooo'i walfahshaaa'i wa an taqooloo alal laahi maa laa ta'lamoon", "translation": "He only orders you to evil and immorality and to say about Allah what you do not know."}, {"ayah": 170, "translit": "Wa izaa qeela lahumuttabi'oo maaa anzalal laahu qaaloo bal nattabi'u maaa alfainaa 'alaihi aabaaa'anaaa; awalaw kaana aabaaa'hum laa ya'qiloona shai'anw wa laa yahtadoon", "translation": "And when it is said to them, \"Follow what Allah has revealed,\" they say, \"Rather, we will follow that which we found our fathers doing.\" Even though their fathers understood nothing, nor were they guided?"}, {"ayah": 171, "translit": "Wa masalul lazeena kafaroo kamasalil lazee yan'iqu bimaa laa yasma'u illaa du'aaa'anw wa nidaaa'aa; summum bukmun 'umyun fahum laa ya'qiloon", "translation": "The example of those who disbelieve is like that of one who shouts at what hears nothing but calls and cries cattle or sheep - deaf, dumb and blind, so they do not understand."}, {"ayah": 172, "translit": "Yaaa ayyuhal lazeena aamanoo kuloo min taiyibaati maa razaqnaakum washkuroo lillaahi in kuntum iyyaahu ta'budoon", "translation": "O you who have believed, eat from the good things which We have provided for you and be grateful to Allah if it is [indeed] Him that you worship."}, {"ayah": 173, "translit": "Innamaa harrama 'alaikumul maitata waddama wa lahmal khinzeeri wa maaa uhilla bihee lighairil laahi famanid turra ghaira baaghinw wa laa 'aadin falaaa isma 'alaih; innal laaha Ghafoorur Raheem", "translation": "He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], there is no sin upon him. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 174, "translit": "Innal lazeena yaktumoona maaa anzalal laahu minal kitaabi wa yashtaroona bihee samanan qaleelan ulaaa'ika maa yaakuloona fee butoonihim illan Naara wa laa yukallimu humul laahu Yawmal Qiyaamati wa laa yuzakkeehim wa lahum 'azaabun aleem", "translation": "Indeed, they who conceal what Allah has sent down of the Book and exchange it for a small price - those consume not into their bellies except the Fire. And Allah will not speak to them on the Day of Resurrection, nor will He purify them. And they will have a painful punishment."}, {"ayah": 175, "translit": "Ulaaa'ikal lazeenash tarawud dalaalata bilhudaa wal'azaaba bilmaghfirah; famaaa asbarahum 'alan Naar", "translation": "Those are the ones who have exchanged guidance for error and forgiveness for punishment. How patient they are in pursuit of the Fire!"}, {"ayah": 176, "translit": "Zaalika bi annal laaha nazzalal kitaaba bilhaqq; wa innal lazeenakh talafoo fil kitaabi lafee shiqaaqim ba'eed", "translation": "That is [deserved by them] because Allah has sent down the Book in truth. And indeed, those who differ over the Book are in extreme dissension."}, {"ayah": 177, "translit": "Laisal birra an tuwalloo wujoohakum qibalal mashriqi walmaghribi wa laakinnal birra man aamana billaahi wal yawmil aakhiri wal malaaa 'ikati wal kitaabi wan nabiyyeena wa aatalmaala 'alaa hubbihee zawilqurbaa walyataa maa walmasaakeena wabnas sabeeli wassaaa'ileena wa firriqaabi wa aqaamas salaata wa aataz zakaata walmoofoona bi ahdihim izaa 'aahadoo wasaabireena fil baasaaa'i waddarraaa'i wa heenal baas; ulaaa'ikal lazeena sadaqoo wa ulaaa 'ika humul muttaqoon", "translation": "Righteousness is not that you turn your faces toward the east or the west, but [true] righteousness is [in] one who believes in Allah, the Last Day, the angels, the Book, and the prophets and gives wealth, in spite of love for it, to relatives, orphans, the needy, the traveler, those who ask [for help], and for freeing slaves; [and who] establishes prayer and gives zakah; [those who] fulfill their promise when they promise; and [those who] are patient in poverty and hardship and during battle. Those are the ones who have been true, and it is those who are the righteous."}, {"ayah": 178, "translit": "Yaaa ayyuhal lazeena aamanoo kutiba alaikumul qisaasu fil qatlaa alhurru bilhurri wal'abdu bil'abdi wal unsaa bil unsaa; faman 'ufiya lahoo min akheehi shai'un fattibaa'um bilma'roofi wa adaaa'un ilaihi bi ihsaan; zaalika takhfeefum mir rahbikum wa rahmah; famani' tadaa ba'da zaalika falahoo 'azaabun aleem", "translation": "O you who have believed, prescribed for you is legal retribution for those murdered - the free for the free, the slave for the slave, and the female for the female. But whoever overlooks from his brother anything, then there should be a suitable follow-up and payment to him with good conduct. This is an alleviation from your Lord and a mercy. But whoever transgresses after that will have a painful punishment."}, {"ayah": 179, "translit": "Wa lakum fil qisaasi hayaatuny yaaa ulil albaabi la 'allakum tattaqoon", "translation": "And there is for you in legal retribution [saving of] life, O you [people] of understanding, that you may become righteous."}, {"ayah": 180, "translit": "Kutiba 'alaikum izaa hadara ahadakumul mawtu in taraka khairanil wasiyyatu lilwaalidaini wal aqrabeena bilma'roofi haqqan 'alalmut taqeen", "translation": "Prescribed for you when death approaches [any] one of you if he leaves wealth [is that he should make] a bequest for the parents and near relatives according to what is acceptable - a duty upon the righteous."}, {"ayah": 181, "translit": "Famam baddalahoo ba'da maa sami'ahoo fa innamaaa ismuhoo 'alallazeena yubaddi loonah; innallaha Samee'un 'Aleem", "translation": "Then whoever alters the bequest after he has heard it - the sin is only upon those who have altered it. Indeed, Allah is Hearing and Knowing."}, {"ayah": 182, "translit": "Faman khaafa mim moosin janafan aw isman fa aslaha bainahum falaaa ismaa 'alayh; innal laaha Ghafooru Raheem", "translation": "But if one fears from the bequeather [some] error or sin and corrects that which is between them, there is no sin upon him. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 183, "translit": "Yaa ayyuhal lazeena aamanoo kutiba 'alaikumus Siyaamu kamaa kutiba 'alal lazeena min qablikum la'allakum tattaqoon", "translation": "O you who have believed, decreed upon you is fasting as it was decreed upon those before you that you may become righteous -"}, {"ayah": 184, "translit": "Ayyaamam ma'doodaat; faman kaana minkum mareedan aw'alaa safarin fa'iddatum min ayyaamin ukhar; wa 'alal lazeena yuteeqoonahoo fidyatun ta'aamu miskeenin faman tatawwa'a khairan fahuwa khairulo lahoo wa an tasoomoo khairul lakum in kuntum ta'lamoon", "translation": "[Fasting for] a limited number of days. So whoever among you is ill or on a journey [during them] - then an equal number of days [are to be made up]. And upon those who are able [to fast, but with hardship] - a ransom [as substitute] of feeding a poor person [each day]. And whoever volunteers excess - it is better for him. But to fast is best for you, if you only knew."}, {"ayah": 185, "translit": "Shahru Ramadaanallazeee unzila feehil Qur'aanu hudal linnaasi wa baiyinaatim minal hudaa wal furqaan; faman shahida minkumush shahra falyasumhu wa man kaana mareedan aw 'alaa safarin fa'iddatum min ayyaamin ukhar; yureedul laahu bikumul yusra wa laa yureedu bikumul 'usra wa litukmilul 'iddata wa litukabbirul laaha 'alaa maa hadaakum wa la'allakum tashkuroon", "translation": "The month of Ramadhan [is that] in which was revealed the Qur'an, a guidance for the people and clear proofs of guidance and criterion. So whoever sights [the new moon of] the month, let him fast it; and whoever is ill or on a journey - then an equal number of other days. Allah intends for you ease and does not intend for you hardship and [wants] for you to complete the period and to glorify Allah for that [to] which He has guided you; and perhaps you will be grateful."}, {"ayah": 186, "translit": "Wa izaa sa alaka 'ibaadee 'annnee fa innee qareebun ujeebu da'wataddaa'i izaa da'aani falyastajeeboo lee walyu minoo beela 'allahum yarshudoon", "translation": "And when My servants ask you, [O Muhammad], concerning Me - indeed I am near. I respond to the invocation of the supplicant when he calls upon Me. So let them respond to Me [by obedience] and believe in Me that they may be [rightly] guided."}, {"ayah": 187, "translit": "Uhilla lakum laylatas Siyaamir rafasu ilaa nisaaa'ikum; hunna libaasullakum wa antum libaasullahunn; 'alimal laahu annakum kuntum takhtaanoona anfusakum fataaba 'alaikum wa 'afaa 'ankum fal'aana baashiroo hunna wabtaghoo maa katabal laahoo lakum; wa kuloo washraboo hattaa yatabaiyana lakumul khaitul abyadu minal khaitil aswadi minal fajri summa atimmus Siyaama ilal layl; wa laa tubaashiroo hunna wa antum 'aakifoona fil masaajid; tilka hudoodul laahi falaa taqraboohaa; kazaalika yubaiyinul laahu aayaatihee linnaasi la'allahum yattaqoon", "translation": "It has been made permissible for you the night preceding fasting to go to your wives [for sexual relations]. They are clothing for you and you are clothing for them. Allah knows that you used to deceive yourselves, so He accepted your repentance and forgave you. So now, have relations with them and seek that which Allah has decreed for you. And eat and drink until the white thread of dawn becomes distinct to you from the black thread [of night]. Then complete the fast until the sunset. And do not have relations with them as long as you are staying for worship in the mosques. These are the limits [set by] Allah, so do not approach them. Thus does Allah make clear His ordinances to the people that they may become righteous."}, {"ayah": 188, "translit": "Wa laa taakuloo amwaalakum bainakum bilbaatili wa tudloo bihaaa ilal hukkaami litaakuloo fareeqam min amwaalin naasi bil ismi wa antum ta'lamoon", "translation": "And do not consume one another's wealth unjustly or send it [in bribery] to the rulers in order that [they might aid] you [to] consume a portion of the wealth of the people in sin, while you know [it is unlawful]."}, {"ayah": 189, "translit": "Yas'aloonaka 'anil ahillati qul hiya mawaaqeetu linnaasi wal Hajj; wa laisal birru bi an taatul buyoota min zuhoorihaa wa laakinnal birra manit taqaa; waatul buyoota min abwaa bihaa; wattaqullaaha la'allakum tuflihoon", "translation": "They ask you, [O Muhammad], about the new moons. Say, \"They are measurements of time for the people and for Hajj.\" And it is not righteousness to enter houses from the back, but righteousness is [in] one who fears Allah. And enter houses from their doors. And fear Allah that you may succeed."}, {"ayah": 190, "translit": "Wa qaatiloo fee sabeelillaahil lazeena yuqaatiloonakum wa laa ta'tadooo; innal laaha laa yuhibbul mu'tadeen", "translation": "Fight in the way of Allah those who fight you but do not transgress. Indeed. Allah does not like transgressors."}, {"ayah": 191, "translit": "Waqtuloohum haisu saqif tumoohum wa akhrijoohum min haisu akhrajookum; walfitnatu ashaddu minal qatl; wa laa tuqaatiloohum 'indal Majidil Haraami hattaa yaqaatilookum feehi fa in qaatalookum faqtuloohum; kazaalika jazaaa'ul kaafireen", "translation": "And kill them wherever you overtake them and expel them from wherever they have expelled you, and fitnah is worse than killing. And do not fight them at al-Masjid al- Haram until they fight you there. But if they fight you, then kill them. Such is the recompense of the disbelievers."}, {"ayah": 192, "translit": "Fa ini-ntahaw fa innal laaha Ghafoorur Raheem", "translation": "And if they cease, then indeed, Allah is Forgiving and Merciful."}, {"ayah": 193, "translit": "Wa qaatiloohum hatta laa takoona fitnatunw wa yakoonad deenu lillaahi fa-inin tahaw falaa 'udwaana illaa 'alaz zaalimeen", "translation": "Fight them until there is no [more] fitnah and [until] worship is [acknowledged to be] for Allah. But if they cease, then there is to be no aggression except against the oppressors."}, {"ayah": 194, "translit": "Ash Shahrul Haraamu bish Shahril Haraami wal hurumaatu qisaas; famani'tadaa 'alaikum fa'tadoo 'alaihi bimsisli ma'tadaa 'alaikum; wattaqul laaha wa'lamooo annal laaha ma'al muttaqeen", "translation": "[Fighting in] the sacred month is for [aggression committed in] the sacred month, and for [all] violations is legal retribution. So whoever has assaulted you, then assault him in the same way that he has assaulted you. And fear Allah and know that Allah is with those who fear Him."}, {"ayah": 195, "translit": "Wa anfiqoo fee sabeelil laahi wa laa tulqoo bi aydeekum ilat tahlukati wa ahsinoo; innal laaha yuhibbul muhsineen", "translation": "And spend in the way of Allah and do not throw [yourselves] with your [own] hands into destruction [by refraining]. And do good; indeed, Allah loves the doers of good."}, {"ayah": 196, "translit": "Wa atimmul Hajja wal Umarata lillaah; fain uhsirtum famas taisara minal hadyi walaa tahliqoo ru'oosakum hatta yablughal hadyu mahillah; faman kaana minkum mareedan aw biheee azam mir raasihee fafidyatum min Siyaamin aw sadaqatin aw nusuk; fa izaaa amintum faman tamatta'a bil 'Umrati ilal Hajji famastaisara minal hady; famal lam yajid fa Siyaamu salaasti ayyaamin fil Hajji wa sab'atin izaa raja'tum; tilka 'asharatun kaamilah; zaalika limal lam yakun ahluhoo haadiril Masjidil Haraam; wattaqul laaha wa'lamoo annal laaha shadeedul'iqaab (section 24)", "translation": "And complete the Hajj and 'umrah for Allah. But if you are prevented, then [offer] what can be obtained with ease of sacrificial animals. And do not shave your heads until the sacrificial animal has reached its place of slaughter. And whoever among you is ill or has an ailment of the head [making shaving necessary must offer] a ransom of fasting [three days] or charity or sacrifice. And when you are secure, then whoever performs 'umrah [during the Hajj months] followed by Hajj [offers] what can be obtained with ease of sacrificial animals. And whoever cannot find [or afford such an animal] - then a fast of three days during Hajj and of seven when you have returned [home]. Those are ten complete [days]. This is for those whose family is not in the area of al-Masjid al-Haram. And fear Allah and know that Allah is severe in penalty."}, {"ayah": 197, "translit": "Al-Hajju ashhurum ma'-loomaat; faman farada feeinnal hajja falaa rafasa wa laa fusooqa wa laa jidaala fil Hajj; wa maa taf'aloo min khairiny ya'lamhul laah; wa tazawwadoo fa inna khairaz zaadit taqwaa; wattaqooni yaaa ulil albaab", "translation": "Hajj is [during] well-known months, so whoever has made Hajj obligatory upon himself therein [by entering the state of ihram], there is [to be for him] no sexual relations and no disobedience and no disputing during Hajj. And whatever good you do - Allah knows it. And take provisions, but indeed, the best provision is fear of Allah. And fear Me, O you of understanding."}, {"ayah": 198, "translit": "Laisa 'alaikum junaahun an tabtaghoo fad lam mir rabbikum; fa izaaa afadtum min 'Arafaatin fazkurul laaha 'indal-Mash'aril Haraami waz kuroohu kamaa hadaakum wa in kuntum min qablihee laminad daaaleen", "translation": "There is no blame upon you for seeking bounty from your Lord [during Hajj]. But when you depart from 'Arafat, remember Allah at al- Mash'ar al-Haram. And remember Him, as He has guided you, for indeed, you were before that among those astray."}, {"ayah": 199, "translit": "Summa afeedoo min haisu afaadan naasu wastagh firullaah; innnal laaha Ghafoo rur-Raheem", "translation": "Then depart from the place from where [all] the people depart and ask forgiveness of Allah. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 200, "translit": "Fa-izan qadaitum manaa sikakum fazkurul laaha kazikrikum aabaaa'akum aw ashadda zikraa; faminannaasi mai yaqoolu Rabbanaaa aatinaa fiddunyaa wa maa lahoo fil Aakhirati min khalaaq", "translation": "And when you have completed your rites, remember Allah like your [previous] remembrance of your fathers or with [much] greater remembrance. And among the people is he who says, \"Our Lord, give us in this world,\" and he will have in the Hereafter no share."}, {"ayah": 201, "translit": "Wa minhum mai yaqoolu rabbanaaa aatina fid dunyaa hasanatawn wa fil aakhirati hasanatanw wa qinaa azaaban Naar", "translation": "But among them is he who says, \"Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire.\""}, {"ayah": 202, "translit": "Ulaaa'ika lahum naseebum mimmaa kasaboo; wal laahu saree'ul hisaab", "translation": "Those will have a share of what they have earned, and Allah is swift in account."}, {"ayah": 203, "translit": "Wazkurul laaha feee ayyaamim ma'doodaat; faman ta'ajjala fee yawmaini falaaa ismaa 'alaihi wa man taakhkhara falaaa isma 'alayh; limanit-taqaa; wattaqul laaha wa'lamooo annakum ilaihi tuhsharoon", "translation": "And remember Allah during [specific] numbered days. Then whoever hastens [his departure] in two days - there is no sin upon him; and whoever delays [until the third] - there is no sin upon him - for him who fears Allah. And fear Allah and know that unto Him you will be gathered."}, {"ayah": 204, "translit": "Wa minan naasi mai yu'jibuka qawluhoo fil hayaatid dunyaa wa yushhidul laaha 'alaa maa fee qalbihee wa huwa aladdulkhisaam", "translation": "And of the people is he whose speech pleases you in worldly life, and he calls Allah to witness as to what is in his heart, yet he is the fiercest of opponents."}, {"ayah": 205, "translit": "Wa izaa tawallaa sa'aa fil ardi liyufsida feeha wa yuhlikal harsa wannasl; wallaahu laa yuhibbul fasaad", "translation": "And when he goes away, he strives throughout the land to cause corruption therein and destroy crops and animals. And Allah does not like corruption."}, {"ayah": 206, "translit": "Wa izaa qeela lahuttaqil laaha akhazathul izzatu bil-ism; fahasbuhoo jahannam; wa labi'sal mihaad", "translation": "And when it is said to him, \"Fear Allah,\" pride in the sin takes hold of him. Sufficient for him is Hellfire, and how wretched is the resting place."}, {"ayah": 207, "translit": "Wa minan naasi mai yashree nafsahub tighaaa'a mardaatil laah; wallaahu ra'oofum bil'ibaad", "translation": "And of the people is he who sells himself, seeking means to the approval of Allah. And Allah is kind to [His] servants."}, {"ayah": 208, "translit": "Yaaa ayyuhal lazeena aamanud khuloo fis silmi kaaaffatanw wa laa tattabi'oo khutuwaatish Shaitaan; innahoo lakum 'aduwwum mubeen", "translation": "O you who have believed, enter into Islam completely [and perfectly] and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy."}, {"ayah": 209, "translit": "Fa in zalaltum mimba'di maa jaaa'atkumul baiyinaatu fa'lamoo annallaaha 'Azeezun hakeem", "translation": "But if you deviate after clear proofs have come to you, then know that Allah is Exalted in Might and Wise."}, {"ayah": 210, "translit": "Hal yanzuroona illaaa ai yaatiyahumul laahu fee zulalim minal ghamaami walmalaaa'ikatu wa qudiyal amr; wa ilal laahi turja'ulumoor", "translation": "Do they await but that Allah should come to them in covers of clouds and the angels [as well] and the matter is [then] decided? And to Allah [all] matters are returned."}, {"ayah": 211, "translit": "Sal Banee Israaa'eela kam aatainaahum min aayatim baiyinah; wa mai yubaddil ni'matal laahi mim ba'di maa jaaa'athu fa innallaaha shadeedul'iqaab", "translation": "Ask the Children of Israel how many a sign of evidence We have given them. And whoever exchanges the favor of Allah [for disbelief] after it has come to him - then indeed, Allah is severe in penalty."}, {"ayah": 212, "translit": "Zuyyina lillazeena kafarul hayaatud dunyaa wa yaskharoona minal lazeena aamanoo; wallazeenat taqaw fawqahum yawmal Qiyaamah; wallaahu yarzuqu mai yashaaa'u bighairi hisaab;", "translation": "Beautified for those who disbelieve is the life of this world, and they ridicule those who believe. But those who fear Allah are above them on the Day of Resurrection. And Allah gives provision to whom He wills without account."}, {"ayah": 213, "translit": "Kaanan naasu ummatanw waahidatan fab'asal laahun Nabiyyeena mubashshireena wa munzireena wa anzala ma'ahumul kitaaba bilhaqqi liyahkuma bainan naasi feemakh talafoo feeh; wa makh talafa feehi 'illallazeena ootoohu mim ba'di maa jaaa'athumul baiyinaatu baghyam bainahm fahadal laahul lazeena aamanoo limakh talafoo feehi minal haqqi bi iznih; wallaahu yahdee mai yashaaa'u ilaa Siraatim Mustaqeem", "translation": "Mankind was [of] one religion [before their deviation]; then Allah sent the prophets as bringers of good tidings and warners and sent down with them the Scripture in truth to judge between the people concerning that in which they differed. And none differed over the Scripture except those who were given it - after the clear proofs came to them - out of jealous animosity among themselves. And Allah guided those who believed to the truth concerning that over which they had differed, by His permission. And Allah guides whom He wills to a straight path."}, {"ayah": 214, "translit": "Am hasibtum an tadkhulul jannata wa lammaa yaa-tikum masalul lazeena khalaw min qablikum massathumul baasaaa'u waddarraaaa'u wa zulziloo hattaa yaqoolar Rasoolu wallazeena aamanoo ma'ahoo mataa nasrul laah; alaaa inna nasral laahiqareeb", "translation": "Or do you think that you will enter Paradise while such [trial] has not yet come to you as came to those who passed on before you? They were touched by poverty and hardship and were shaken until [even their] messenger and those who believed with him said, \"When is the help of Allah?\" Unquestionably, the help of Allah is near."}, {"ayah": 215, "translit": "Yas'aloonaka maazaa yunfiqoona qul maaa anfaqtum min khairin falil waalidaini wal aqrabeena walyataamaa wal masaakeeni wabnis sabeel; wa maa taf'aloo min khairin fa innal laaha bihee 'Aleem", "translation": "They ask you, [O Muhammad], what they should spend. Say, \"Whatever you spend of good is [to be] for parents and relatives and orphans and the needy and the traveler. And whatever you do of good - indeed, Allah is Knowing of it.\""}, {"ayah": 216, "translit": "Kutiba alaikumulqitaalu wa huwa kurhullakum wa 'asaaa an takrahoo shai'anw wa huwa khairullakum wa 'asaaa an tuhibbo shai'anw wa huwa sharrullakum; wallaahu ya'lamu wa antum laa ta'lamoon", "translation": "Fighting has been enjoined upon you while it is hateful to you. But perhaps you hate a thing and it is good for you; and perhaps you love a thing and it is bad for you. And Allah Knows, while you know not."}, {"ayah": 217, "translit": "Yas'aloonaka 'anish Shahril Haraami qitaalin feehi qul qitaahun feehi kabeerunw wa saddun 'an sabeelil laahi wa kufrum bihee wal Masjidil Haraami wa ikhraaju ahlihee minhu akbaru 'indal laah; walfitnatu akbaru minal qatl; wa laa yazaaloona yuqaatiloonakum hatta yaruddookum 'an deenikum inis tataa'oo; wa mai yartadid minkum 'an deenihee fayamut wahuwa kaafirun fa ulaaa'ika habitat a'maaluhum fid dunyaa wal aakhirati wa ulaaa'ika ashaabun Naari hum feehaa khaalidoon", "translation": "They ask you about the sacred month - about fighting therein. Say, \"Fighting therein is great [sin], but averting [people] from the way of Allah and disbelief in Him and [preventing access to] al-Masjid al-Haram and the expulsion of its people therefrom are greater [evil] in the sight of Allah. And fitnah is greater than killing.\" And they will continue to fight you until they turn you back from your religion if they are able. And whoever of you reverts from his religion [to disbelief] and dies while he is a disbeliever - for those, their deeds have become worthless in this world and the Hereafter, and those are the companions of the Fire, they will abide therein eternally."}, {"ayah": 218, "translit": "Innal lazeena aamanoo wallazeena haajaroo wa jaahadoo fee sabeelil laahi ulaaaika yarjoona rahmatal laah; wallaahu Ghafoorur Raheem", "translation": "Indeed, those who have believed and those who have emigrated and fought in the cause of Allah - those expect the mercy of Allah. And Allah is Forgiving and Merciful."}, {"ayah": 219, "translit": "Yas'aloonaka 'anilkhamri walmaisiri qul feehimaaa ismun kabeerunw wa manaafi'u linnaasi wa ismuhumaa akbaru min naf'ihimaa; wa yas'aloonaka maaza yunfiqoona qulil-'afw; kazaalika yubaiyinul laahu lakumul-aayaati la'allakum tatafakkaroon", "translation": "They ask you about wine and gambling. Say, \"In them is great sin and [yet, some] benefit for people. But their sin is greater than their benefit.\" And they ask you what they should spend. Say, \"The excess [beyond needs].\" Thus Allah makes clear to you the verses [of revelation] that you might give thought."}, {"ayah": 220, "translit": "Fid dunyaa wal aakhirah; wa yas'aloonaka 'anil yataamaa qul islaahullahum khayr, wa in tukhaalitoohum fa ikhwaanukum; wallaahu ya'lamul mufsida minalmuslih; wa law shaaa'al laahu la-a'natakum; innal laaha 'Azeezun Hakeem", "translation": "To this world and the Hereafter. And they ask you about orphans. Say, \"Improvement for them is best. And if you mix your affairs with theirs - they are your brothers. And Allah knows the corrupter from the amender. And if Allah had willed, He could have put you in difficulty. Indeed, Allah is Exalted in Might and Wise."}, {"ayah": 221, "translit": "Wa laatankihul mushrikaati hattaa yu'minn; wa la amatum mu'minatun khairum mim mushrikatinw wa law a'jabatkum; wa laa tunkihul mushrikeena hattaa yu'minoo; wa la'abdummu'minun khairum mimmushrikinw wa law 'ajabakum; ulaaa'ika yad'oona ilan Naari wallaahu yad'ooo ilal Jannati walmaghfirati biiznihee wa yubaiyinu Aayaatihee linnaasi la'allahum yatazakkaroon", "translation": "And do not marry polytheistic women until they believe. And a believing slave woman is better than a polytheist, even though she might please you. And do not marry polytheistic men [to your women] until they believe. And a believing slave is better than a polytheist, even though he might please you. Those invite [you] to the Fire, but Allah invites to Paradise and to forgiveness, by His permission. And He makes clear His verses to the people that perhaps they may remember."}, {"ayah": 222, "translit": "Wa yas'aloonaka 'anil maheedi qul huwa azan fa'tazilun nisaaa'a fil maheedi wa laa taqraboo hunna hattaa yathurna fa-izaa tathharna faatoohunna min haisu amarakumul laah; innallaaha yuhibbut Tawwaabeena wa yuhibbul mutatahhireen", "translation": "And they ask you about menstruation. Say, \"It is harm, so keep away from wives during menstruation. And do not approach them until they are pure. And when they have purified themselves, then come to them from where Allah has ordained for you. Indeed, Allah loves those who are constantly repentant and loves those who purify themselves.\""}, {"ayah": 223, "translit": "Nisaaa'ukum harsullakum faatoo harsakum annaa shi'tum wa qaddimoo li anfusikum; wattaqul laaha wa'lamooo annakum mulaaqooh; wa bash shirilmu 'mineen", "translation": "Your wives are a place of sowing of seed for you, so come to your place of cultivation however you wish and put forth [righteousness] for yourselves. And fear Allah and know that you will meet Him. And give good tidings to the believers."}, {"ayah": 224, "translit": "Wa laa taj'alul laaha 'urdatal li aymaanikum an tabarroo wa tattaqoo wa tuslihoo bainan naas; wallaahu Samee'un 'Aleem", "translation": "And do not make [your oath by] Allah an excuse against being righteous and fearing Allah and making peace among people. And Allah is Hearing and Knowing."}, {"ayah": 225, "translit": "Laa yu'aakhi zukumul laahu billaghwi feee aymaa nikum wa laakiny yu'aakhi zukum bimaa kasabat quloo bukum; wallaahu Ghafoorun Haleem", "translation": "Allah does not impose blame upon you for what is unintentional in your oaths, but He imposes blame upon you for what your hearts have earned. And Allah is Forgiving and Forbearing."}, {"ayah": 226, "translit": "Lillazeena yu'loona min nisaaa'ihim tarabbusu arba'ati ashhurin fain faaa'oo fa innal laaha Ghafoorur Raheem", "translation": "For those who swear not to have sexual relations with their wives is a waiting time of four months, but if they return [to normal relations] - then indeed, Allah is Forgiving and Merciful."}, {"ayah": 227, "translit": "Wa in 'azamut talaaqa fa innal laaha Samee'un 'Aleem", "translation": "And if they decide on divorce - then indeed, Allah is Hearing and Knowing."}, {"ayah": 228, "translit": "Walmutallaqaatu yatarab basna bi anfusihinna salaasata qurooo'; wa laa yahillu lahunna ai yaktumna maa khalaqal laahu feee arhaaminhinna in kunna yu'minna billaahi wal yawmil aakhir; wa bu'oola tuhunna ahaqqu biraddihinna fee zaalika in araadooo islaahaa; wa lahunna mislul lazee 'araihinna bilma'roof; wa lirrijjaali 'alaihinna daraja; wallaahu 'Azeezun Hakeem", "translation": "Divorced women remain in waiting for three periods, and it is not lawful for them to conceal what Allah has created in their wombs if they believe in Allah and the Last Day. And their husbands have more right to take them back in this [period] if they want reconciliation. And due to the wives is similar to what is expected of them, according to what is reasonable. But the men have a degree over them [in responsibility and authority]. And Allah is Exalted in Might and Wise."}, {"ayah": 229, "translit": "Attalaaqu marrataani fa imsaakum bima'roofin aw tasreehum bi ihsaan; wa laa yahillu lakum an taakhuzoo mimmaaa aataitumoohunna shai'an illaaa ai yakhaafaaa alla yuqeemaa hudoodallahi fa in khiftum allaa yuqeemaa budoodal laahi falaa junaaha 'Alaihimaa feemaf tadat bihee tilka hudoodul laahi falaa ta'tadoohaa; wa mai yata'adda hudoodal laahi fa ulaaa'ika humuzzaa limoon", "translation": "Divorce is twice. Then, either keep [her] in an acceptable manner or release [her] with good treatment. And it is not lawful for you to take anything of what you have given them unless both fear that they will not be able to keep [within] the limits of Allah. But if you fear that they will not keep [within] the limits of Allah, then there is no blame upon either of them concerning that by which she ransoms herself. These are the limits of Allah, so do not transgress them. And whoever transgresses the limits of Allah - it is those who are the wrongdoers."}, {"ayah": 230, "translit": "Fa in tallaqahaa falaa tahillu lahoo mim ba'du hattaa tankiha zawjan ghairah; fa in tallaqahaa falaa junaaha 'alaihimaaa ai yataraaja'aaa in zannaaa ai yuqeemaa hudoodal laa; wa tilka hudoodul laahi yubaiyinuhaa liqawminy ya'lamoon", "translation": "And if he has divorced her [for the third time], then she is not lawful to him afterward until [after] she marries a husband other than him. And if the latter husband divorces her [or dies], there is no blame upon the woman and her former husband for returning to each other if they think that they can keep [within] the limits of Allah. These are the limits of Allah, which He makes clear to a people who know."}, {"ayah": 231, "translit": "Wa izaa tallaqtumun nisaaa'a fabalaghna ajala hunna fa amsikoohunna bima'roofin law sarrihoo hunna bima'roof; wa laa tumsikoo hunna diraa rallita'tadoo; wa mai yaf'al zaalika faqad zalama nafsah; wa laa tattakhizooo aayaatillaahi huzuwaa; wazkuroo ni'matal laahi 'alaikum wa maaa anzala 'alaikum minal kitaabi wal ikmati ya'izukum bih; wattaqul laaha wa'lamooo annal laaha bikulli shai'i 'Aleem", "translation": "And when you divorce women and they have [nearly] fulfilled their term, either retain them according to acceptable terms or release them according to acceptable terms, and do not keep them, intending harm, to transgress [against them]. And whoever does that has certainly wronged himself. And do not take the verses of Allah in jest. And remember the favor of Allah upon you and what has been revealed to you of the Book and wisdom by which He instructs you. And fear Allah and know that Allah is Knowing of all things."}, {"ayah": 232, "translit": "Wa izaa tallaqtumun nisaaa'a fabalaghna ajalahunna falaa ta'duloo hunna ai yankihna azwaaja humna izaa taraadaw bainahum bilma' roof; zaalika yoo'azu bihee man kaana minkum yu'minu billaahi wal yawmil aakhir; zaalikum azkaa lakum wa athar; wallaahu ya'lamu wa antum laa ta'lamu wa antum laa ta'lamoon", "translation": "And when you divorce women and they have fulfilled their term, do not prevent them from remarrying their [former] husbands if they agree among themselves on an acceptable basis. That is instructed to whoever of you believes in Allah and the Last Day. That is better for you and purer, and Allah knows and you know not."}, {"ayah": 233, "translit": "Walwaa lidaatu yurdi'na awlaada hunna hawlaini kaamilaini liman araada ai yutimmar radaa'ah; wa 'alalmawloodi lahoo rizuhunna wa kiswatuhunna bilma'roof; laatukallafu nafsun illaa wus'ahaa; laa tudaaarra waalidatum biwaladihaa wa laa mawloodul lahoo biwaladih; wa 'alal waarisi mislu zaalik; fa in araadaa Fisaalan 'an taraadim minhumaa wa tashaawurin falaa junaaha 'alaimaa; wa in arattum an tastardi'ooo awlaadakum falaa junaaha 'alaikum izaa sallamtum maaa aataitum bilma'roof; wattaqul laaha wa'lamooo annal laaha bimaa ta'maloona baseer", "translation": "Mothers may breastfeed their children two complete years for whoever wishes to complete the nursing [period]. Upon the father is the mothers' provision and their clothing according to what is acceptable. No person is charged with more than his capacity. No mother should be harmed through her child, and no father through his child. And upon the [father's] heir is [a duty] like that [of the father]. And if they both desire weaning through mutual consent from both of them and consultation, there is no blame upon either of them. And if you wish to have your children nursed by a substitute, there is no blame upon you as long as you give payment according to what is acceptable. And fear Allah and know that Allah is Seeing of what you do."}, {"ayah": 234, "translit": "Wallazeena yutawaffawna minkum wa yazaroona azwaajai yatarabbasna bi anfusihinna arba'ata ashhurinw wa 'ashran fa izaa balaghna ajalahunna falaa junaaha 'alaikum feemaa fa'alna feee anfusihinna bilma'roof; wallaahu bimaa ta'maloona Khabeer", "translation": "And those who are taken in death among you and leave wives behind - they, [the wives, shall] wait four months and ten [days]. And when they have fulfilled their term, then there is no blame upon you for what they do with themselves in an acceptable manner. And Allah is [fully] Acquainted with what you do."}, {"ayah": 235, "translit": "Wa laa junaaha 'alaikum feema 'arradtum bihee min khitbatin nisaaa'i aw aknantum feee anfusikum; 'alimal laahu annakum satazkuroonahunna wa laakil laa tuwaa'idoohunna sirran illaaa an taqooloo qawlamma'roofaa; wa laa ta'zimoo 'uqdatan nikaahi hattaa yablughal kitaabu ajalah; wa'lamooo annal laaha ya'lamumaa feee anfusikum fahzarooh; wa'lamooo annallaaha Ghafoorun Haleem", "translation": "There is no blame upon you for that to which you [indirectly] allude concerning a proposal to women or for what you conceal within yourselves. Allah knows that you will have them in mind. But do not promise them secretly except for saying a proper saying. And do not determine to undertake a marriage contract until the decreed period reaches its end. And know that Allah knows what is within yourselves, so beware of Him. And know that Allah is Forgiving and Forbearing."}, {"ayah": 236, "translit": "Laa junaaha 'alaikum in tallaqtumun nisaaa'a maa lam tamassoohunna aw tafridoo lahunna fareedah; wa matti'oona 'alal moosi'i qadaruhoo wa 'alal muqtiri qadaruhoo matta'am bilma'roofi haqqan 'alalmuhsineen", "translation": "There is no blame upon you if you divorce women you have not touched nor specified for them an obligation. But give them [a gift of] compensation - the wealthy according to his capability and the poor according to his capability - a provision according to what is acceptable, a duty upon the doers of good."}, {"ayah": 237, "translit": "Wa in tallaqtumoohunna min qabli an tamassoohunna wa qad farad tum lahunna fareedatan fanisfu maa faradtum illaaa ai ya'foona aw ya'fuwallazee biyadihee 'uqdatunnikaah; wa an ta'foona aw ya'fuwallazee biyadihee 'uqdatunnikaah; wa an ta'fooo aqrabu littaqwaa; wa laa tansawulfadla bainakum; innal laaha bimaa ta'maloona Baseer", "translation": "And if you divorce them before you have touched them and you have already specified for them an obligation, then [give] half of what you specified - unless they forego the right or the one in whose hand is the marriage contract foregoes it. And to forego it is nearer to righteousness. And do not forget graciousness between you. Indeed Allah, of whatever you do, is Seeing."}, {"ayah": 238, "translit": "Haafizoo 'alas salawaati was Salaatil Wustaa wa qoomoo lillaahi qaaniteen", "translation": "Maintain with care the [obligatory] prayers and [in particular] the middle prayer and stand before Allah, devoutly obedient."}, {"ayah": 239, "translit": "Fa in khiftum farijaalan aw rukbaanan fa izaaa amintum fazkurul laaha kamaa 'allamakum maa lam takoonoo ta'lamoon", "translation": "And if you fear [an enemy, then pray] on foot or riding. But when you are secure, then remember Allah [in prayer], as He has taught you that which you did not [previously] know."}, {"ayah": 240, "translit": "Wallazeena yutawaf fawna minkum wa yazaroona azwaajanw wasiyyatal li azwaajihim mataa'an ilal hawlighaira ikhraaj; fa in kharajna falaa junaaha 'alaikum fee maa fa'alna junaaha 'alaikum fee maa fa'alna feee anfusihinna mim ma'roof; wallaahu Azeezun Hakeem", "translation": "And those who are taken in death among you and leave wives behind - for their wives is a bequest: maintenance for one year without turning [them] out. But if they leave [of their own accord], then there is no blame upon you for what they do with themselves in an acceptable way. And Allah is Exalted in Might and Wise."}, {"ayah": 241, "translit": "Wa lilmutallaqaati mataa'um bilma'roofi haqqan 'alal muttaqeen", "translation": "And for divorced women is a provision according to what is acceptable - a duty upon the righteous."}, {"ayah": 242, "translit": "Kazaalika yubaiyinul laahu lakum aayaatihee la'allakum ta'qiloon", "translation": "Thus does Allah make clear to you His verses that you might use reason."}, {"ayah": 243, "translit": "Alam tara ilal lazeena kharajoo min diyaarihim wa hum uloofun hazaral mawti faqaaala lahumul laahu mootoo summa ahyaahum; innal laaha lazoo fadlin 'alannaasi wa laakinna aksarannaasi laa yashkuroon", "translation": "Have you not considered those who left their homes in many thousands, fearing death? Allah said to them, \"Die\"; then He restored them to life. And Allah is full of bounty to the people, but most of the people do not show gratitude."}, {"ayah": 244, "translit": "Wa qaatiloo fee sabeelil laahi wa'lamooo annal laaha Samee'un 'Aleem", "translation": "And fight in the cause of Allah and know that Allah is Hearing and Knowing."}, {"ayah": 245, "translit": "Man zal lazee yuqridul laaha qardan hasanan fayudaa 'ifahoo lahoo ad'aafan kaseerah; wallaahu yaqbidu wa yabsut wa ilaihi turja'oon", "translation": "Who is it that would loan Allah a goodly loan so He may multiply it for him many times over? And it is Allah who withholds and grants abundance, and to Him you will be returned."}, {"ayah": 246, "translit": "Alam tara ilal malai mim Baneee Israaa'eela mim ba'di Moosaaa iz qaaloo li Nabiyyil lahumub 'as lanaa malikan nuqaatil fee sabeelillaahi qaala hal 'asaitum in kutiba 'alaikumul qitaalu allaa tuqaatiloo qaaloo wa maa lanaaa allaa nuqaatila fee sabeelil laahi wa qad ukhrijnaa min diyaarinaa wa abnaaa'inaa falammaa kutiba 'alaihimul qitaalu tawallaw illaa qaleelam minhum; wallaahu 'aleemum bizzaalimeen", "translation": "Have you not considered the assembly of the Children of Israel after [the time of] Moses when they said to a prophet of theirs, \"Send to us a king, and we will fight in the way of Allah \"? He said, \"Would you perhaps refrain from fighting if fighting was prescribed for you?\" They said, \"And why should we not fight in the cause of Allah when we have been driven out from our homes and from our children?\" But when fighting was prescribed for them, they turned away, except for a few of them. And Allah is Knowing of the wrongdoers."}, {"ayah": 247, "translit": "Wa qaala lahum Nabiy yuhum innal laaha qad ba'asa lakum Taaloota malikaa; qaalooo annaa yakoonu lahul mulku 'alainaa wa nahnu ahaqqu bilmulki minhu wa lam yu'ta sa'atamminal maal; qaala innallaahas tafaahu 'alaikum wa zaadahoo bastatan fil'ilmi waljismi wallaahu yu'tee mulkahoo mai yashaaa'; wallaahu Waasi'un 'Aleem", "translation": "And their prophet said to them, \"Indeed, Allah has sent to you Saul as a king.\" They said, \"How can he have kingship over us while we are more worthy of kingship than him and he has not been given any measure of wealth?\" He said, \"Indeed, Allah has chosen him over you and has increased him abundantly in knowledge and stature. And Allah gives His sovereignty to whom He wills. And Allah is all-Encompassing [in favor] and Knowing.\""}, {"ayah": 248, "translit": "Wa qaala lahum Nabiyyuhum inna Aayata mulkiheee ai yaatiyakumut Taabootu feei sakeenatummir Rabbikum wa baqiyyatummimmaa taraka Aalu Moosa wa Aalu Haaroona tahmiluhul malaaa'ikah; inna fee zaalika la Aayatal lakum in kuntum mu'mineen (section 32)", "translation": "And their prophet said to them, \"Indeed, a sign of his kingship is that the chest will come to you in which is assurance from your Lord and a remnant of what the family of Moses and the family of Aaron had left, carried by the angels. Indeed in that is a sign for you, if you are believers.\""}, {"ayah": 249, "translit": "Falammaa fasala Taalootu biljunoodi qaala innal laaha mubtaleekum binaharin faman shariba minhu falaisa minnee wa mallam yat'amhu fa innahoo minneee illaa manigh tarafa ghurfatam biyadih; fashariboo minhu illaa qaleelamminhum; falammaa jaawazahoo huwa wallazeena aamanoo ma'ahoo qaaloo laa taaqata lanal yawma bi Jaaloota wa junoodih; qaalallazeena yazunnoona annahum mulaaqul laahi kam min fi'atin qaleelatin ghalabat fi'atan kaseeratam bi iznil laah; wallaahuma'as saabireen", "translation": "And when Saul went forth with the soldiers, he said, \"Indeed, Allah will be testing you with a river. So whoever drinks from it is not of me, and whoever does not taste it is indeed of me, excepting one who takes [from it] in the hollow of his hand.\" But they drank from it, except a [very] few of them. Then when he had crossed it along with those who believed with him, they said, \"There is no power for us today against Goliath and his soldiers.\" But those who were certain that they would meet Allah said, \"How many a small company has overcome a large company by permission of Allah. And Allah is with the patient.\""}, {"ayah": 250, "translit": "Wa lammaa barazoo liJaaloota wa junoodihee qaaloo Rabbanaaa afrigh 'alainaa sabranw wa sabbit aqdaamanaa wansurnaa 'alal qawmil kaafireen", "translation": "And when they went forth to [face] Goliath and his soldiers, they said, \"Our Lord, pour upon us patience and plant firmly our feet and give us victory over the disbelieving people.\""}, {"ayah": 251, "translit": "Fahazamoohum bi iznillaahi wa qatala Daawoodu jaaloota wa aataahul laahulmulka Wal Hikmata wa 'allamahoo mimmaa yashaaa'; wa law laa daf'ullaahin naasa ba'dahum biba'dil lafasadatil ardu wa laakinnal laaha zoo fadlin 'alal'aalameen", "translation": "So they defeated them by permission of Allah, and David killed Goliath, and Allah gave him the kingship and prophethood and taught him from that which He willed. And if it were not for Allah checking [some] people by means of others, the earth would have been corrupted, but Allah is full of bounty to the worlds."}, {"ayah": 252, "translit": "Tilka Aayaatul laahi natloohaa 'alaika bilhaqq; wa innaka laminal mursaleen", "translation": "These are the verses of Allah which We recite to you, [O Muhammad], in truth. And indeed, you are from among the messengers."}, {"ayah": 253, "translit": "Tilkar Rusulu faddalnaa ba'dahum 'alaa ba'd; minhum man kallamal laahu wa rafa'a ba'dahum darajaat; wa aatainaa 'Eesab na Maryamal baiyinaati wa ayyadnaahu bi Roohil Qudus; wa law shaaa'al laahu maqtatalal lazeena mimba'dihim mim ba'di maa jaaa'athumul baiyinaatu wa laakinikh talafoo faminhum man aamana wa minhum man kafar; wa law shaaa'al laahu maq tataloo wa laakinnallaaha yaf'alu maa yureed (section 33)", "translation": "Those messengers - some of them We caused to exceed others. Among them were those to whom Allah spoke, and He raised some of them in degree. And We gave Jesus, the Son of Mary, clear proofs, and We supported him with the Pure Spirit. If Allah had willed, those [generations] succeeding them would not have fought each other after the clear proofs had come to them. But they differed, and some of them believed and some of them disbelieved. And if Allah had willed, they would not have fought each other, but Allah does what He intends."}, {"ayah": 254, "translit": "Yaa ayyuhal lazeena aamanoo anfiqoo mimmaa razaqnaakum min qabli ai yaatiya yawmul laa bai'un fee wa la khullatunw wa laa shafaa'ah; walkaa firoona humuz zaalimoon", "translation": "O you who have believed, spend from that which We have provided for you before there comes a Day in which there is no exchange and no friendship and no intercession. And the disbelievers - they are the wrongdoers."}, {"ayah": 255, "translit": "Allahu laaa ilaaha illaa Huwal Haiyul Qaiyoom; laa taakhuzuhoo sinatunw wa laa nawm; lahoo maa fissamaawaati wa maa fil ard; man zal lazee yashfa'u indahooo illaa bi-iznih; ya'lamu maa baina aydeehim wa maa khalfahum wa laa yuheetoona bishai'im min 'ilmihee illaa bimaa shaaa'; wasi'a Kursiyyuhus samaawaati wal arda wa laa ya'ooduho hifzuhumaa; wa Huwal Aliyyul 'Azeem", "translation": "Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great."}, {"ayah": 256, "translit": "Laaa ikraaha fid deeni qat tabiyanar rushdu minal ghayy; famai yakfur bit Taaghooti wa yu'mim billaahi faqadis tamsaka bil'urwatil wusqaa lan fisaama lahaa; wallaahu Samee'un 'Aleem", "translation": "There shall be no compulsion in [acceptance of] the religion. The right course has become clear from the wrong. So whoever disbelieves in Taghut and believes in Allah has grasped the most trustworthy handhold with no break in it. And Allah is Hearing and Knowing."}, {"ayah": 257, "translit": "Allaahu waliyyul lazeena aamanoo yukhrijuhum minaz zulumaati ilan noori wallazeena kafarooo awliyaaa'uhumut Taaghootu yukhrijoonahum minan noori ilaz zulumaat; ulaaa'ika Ashaabun Naari hum feehaa khaalidoon", "translation": "Allah is the ally of those who believe. He brings them out from darknesses into the light. And those who disbelieve - their allies are Taghut. They take them out of the light into darknesses. Those are the companions of the Fire; they will abide eternally therein."}, {"ayah": 258, "translit": "Alam tara ilal lazee Haaajja Ibraaheema fee Rabbiheee an aataahullaahul mulka iz qaala Ibraaheemu Rabbiyal lazee yuhyee wa yumeetu qaala ana uhyee wa yumeetu qaala ana uhyee wa umeetu qaala Ibraaheemu fa innal laaha yaatee bishshamsi minal mashriqi faati bihaa minal maghribi fabuhital lazee kafar; wallaahu laa yahdil qawmaz zaalimeen", "translation": "Have you not considered the one who argued with Abraham about his Lord [merely] because Allah had given him kingship? When Abraham said, \"My Lord is the one who gives life and causes death,\" he said, \"I give life and cause death.\" Abraham said, \"Indeed, Allah brings up the sun from the east, so bring it up from the west.\" So the disbeliever was overwhelmed [by astonishment], and Allah does not guide the wrongdoing people."}, {"ayah": 259, "translit": "Aw kallazee marra 'alaa qaryatinw wa hiya khaawiyatun 'alaa 'urooshihaa qaala annaa yuhyee haazihil laahu ba'da mawtihaa fa amaatahul laahu mi'ata 'aamin suumma ba'asahoo qaala kam labista qaala labistu yawman aw ba'da yawmin qaala bal labista mi'ata 'aamin fanzur ilaa ta'aamika wa sharaabika lam yatasannah wanzur ilaa himaarika wa linaj'alaka Aayatal linnaasi wanzur ilal'izaami kaifa nunshizuhaa summa naksoohaa lahmaa; falammaa tabiyana lahoo qaala a'lamu annal laaha 'alaakulli shai'in Qadeer", "translation": "Or [consider such an example] as the one who passed by a township which had fallen into ruin. He said, \"How will Allah bring this to life after its death?\" So Allah caused him to die for a hundred years; then He revived him. He said, \"How long have you remained?\" The man said, \"I have remained a day or part of a day.\" He said, \"Rather, you have remained one hundred years. Look at your food and your drink; it has not changed with time. And look at your donkey; and We will make you a sign for the people. And look at the bones [of this donkey] - how We raise them and then We cover them with flesh.\" And when it became clear to him, he said, \"I know that Allah is over all things competent.\""}, {"ayah": 260, "translit": "Wa iz qaala Ibraaheemu Rabbi arinee kaifa tuhyil mawtaa qaala awa lam tu'min qaala balaa wa laakil liyatma'inna qalbee qaala fakhuz arab'atam minal tairi fasurhunna ilaika summaj 'al a'alaa kulli jabalim minhunna juz'an sumaad 'uhunna yaateenaka sa'yaa; wa'lam annal laaha 'Azeezun Hakeem", "translation": "And [mention] when Abraham said, \"My Lord, show me how You give life to the dead.\" [Allah] said, \"Have you not believed?\" He said, \"Yes, but [I ask] only that my heart may be satisfied.\" [Allah] said, \"Take four birds and commit them to yourself. Then [after slaughtering them] put on each hill a portion of them; then call them - they will come [flying] to you in haste. And know that Allah is Exalted in Might and Wise.\""}, {"ayah": 261, "translit": "Masalul lazeena yunfiqoona amwaalahum fee sabeelil laahi kamasali habbatin ambatat sab'a sanaabila fee kulli sumbulatim mi'atu habbah; wallaahu yudaa'ifu limai yashaaa; wallaahu Waasi'un 'Aleem", "translation": "The example of those who spend their wealth in the way of Allah is like a seed [of grain] which grows seven spikes; in each spike is a hundred grains. And Allah multiplies [His reward] for whom He wills. And Allah is all-Encompassing and Knowing."}, {"ayah": 262, "translit": "Allazeena yunfiqoona amwaalahum fee sabeelillaahi summa laa yutbi'oona maaa anfaqoo mannanw wa laaa azal lahum ajruhum 'inda Rabbihim; wa laa khawfun 'alaihim wa laa hum yahzanoon", "translation": "Those who spend their wealth in the way of Allah and then do not follow up what they have spent with reminders [of it] or [other] injury will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve."}, {"ayah": 263, "translit": "Qawlum ma'roofunw wa maghfiratun khairum min sadaqatiny yatba'uhaaa azaa; wallaahu Ghaniyyun Haleem", "translation": "Kind speech and forgiveness are better than charity followed by injury. And Allah is Free of need and Forbearing."}, {"ayah": 264, "translit": "Yaaa ayyuhal lazeena aamanoo laa tubtiloo sadaqaatikum bilmanni wal azaa kallazee yunfiqu maalahoo ri'aaa'an naasi wa laa yu'minu billaahi wal yawmil aakhiri famasaluhoo kamasali safwaanin 'alaihi turaabun fa asaabahoo waabilun fatara kahoo saldaa; laa yaqdiroona 'alaa shai'im mimmaa kasaboo; wallaahu laa yahdil qawmal kaafireen", "translation": "O you who have believed, do not invalidate your charities with reminders or injury as does one who spends his wealth [only] to be seen by the people and does not believe in Allah and the Last Day. His example is like that of a [large] smooth stone upon which is dust and is hit by a downpour that leaves it bare. They are unable [to keep] anything of what they have earned. And Allah does not guide the disbelieving people."}, {"ayah": 265, "translit": "Wa masalul lazeena yunfiqoona amwaalahumub ti ghaaaa'a mardaatil laahi wa tasbeetam min anfusihim kamasali jannatim birabwatin asaabahaa waabilun fa aatat ukulahaa di'faini fa il lam yusibhaa waabilun fatall; wallaahu bimaa ta'maloona Baseer", "translation": "And the example of those who spend their wealth seeking means to the approval of Allah and assuring [reward for] themselves is like a garden on high ground which is hit by a downpour - so it yields its fruits in double. And [even] if it is not hit by a downpour, then a drizzle [is sufficient]. And Allah, of what you do, is Seeing."}, {"ayah": 266, "translit": "Ayawaddu ahadukum an takoona lahoo jannatum min nakheelinw wa a'naabin tajree min tahtihal anhaaru lahoo feehaa min kullis samaraati wa asaabahul kibaru wa lahoo zurriyyatun du'afaaa'u fa asaabahaaa i'saarun feehi naarun fahtaraqat; kazaalika yubaiyinul laahu lakumul aayaati la'allakum tatafakkaroon", "translation": "Would one of you like to have a garden of palm trees and grapevines underneath which rivers flow in which he has from every fruit? But he is afflicted with old age and has weak offspring, and it is hit by a whirlwind containing fire and is burned. Thus does Allah make clear to you [His] verses that you might give thought."}, {"ayah": 267, "translit": "Yaaa 'ayyuhal lazeena aamanooo anfiqoo min taiyibaati maa kasabtum wa mimmaaa akhrajuaa lakum minal ardi wa laa tayammamul khabeesa minhu tunfiqoona wa lastum bi aakhizeehi illaaa an tughmidoo feeh; wa'lamooo annal laaha Ghaniyyun Hameed", "translation": "O you who have believed, spend from the good things which you have earned and from that which We have produced for you from the earth. And do not aim toward the defective therefrom, spending [from that] while you would not take it [yourself] except with closed eyes. And know that Allah is Free of need and Praiseworthy."}, {"ayah": 268, "translit": "Ash Shaitaanu ya'idukumul faqra wa yaamurukum bilfahshaaa'i wallaahu ya'idukum maghfiratam minhu wa fadlaa; wallaahu Waasi'un 'Aleem", "translation": "Satan threatens you with poverty and orders you to immorality, while Allah promises you forgiveness from Him and bounty. And Allah is all-Encompassing and Knowing."}, {"ayah": 269, "translit": "Yu'til Hikmata mai yashaaa'; wa mai yutal Hikmata faqad ootiya khairan kaseeraa; wa maa yazzakkaru illaaa ulul albaab", "translation": "He gives wisdom to whom He wills, and whoever has been given wisdom has certainly been given much good. And none will remember except those of understanding."}, {"ayah": 270, "translit": "Wa maaa anfaqtum min nafaqatin aw nazartum min nazrin fa innal laaha ya'lamuh; wa maa lizzaalimeena min ansaar", "translation": "And whatever you spend of expenditures or make of vows - indeed, Allah knows of it. And for the wrongdoers there are no helpers."}, {"ayah": 271, "translit": "In tubdus sadaqaati fani'immaa hiya wa in tukhfoohaa wa tu'toohal fuqaraaa'a fahuwa khayrul lakum; wa yukaffiru 'ankum min saiyi aatikum; wallaahu bimaa ta'maloona Khabeer", "translation": "If you disclose your charitable expenditures, they are good; but if you conceal them and give them to the poor, it is better for you, and He will remove from you some of your misdeeds [thereby]. And Allah, with what you do, is [fully] Acquainted."}, {"ayah": 272, "translit": "Laisa 'alaika hudaahum wa laakinnal laaha yahdee mai yashaaa'; wa maa tunfiqoo min khairin fali anfusikum; wa maa tunfiqoona illab tighaaa'a wajhil laah; wa maa tunfiqoo min khairiny yuwaffa ilaikum wa antum laa tuzlamoon", "translation": "Not upon you, [O Muhammad], is [responsibility for] their guidance, but Allah guides whom He wills. And whatever good you [believers] spend is for yourselves, and you do not spend except seeking the countenance of Allah. And whatever you spend of good - it will be fully repaid to you, and you will not be wronged."}, {"ayah": 273, "translit": "Lilfuqaraaa'il lazeena uhsiroo fee sabeelil laahi laa yastatee'oona darban fil ardi yah sabuhumul jaahilu aghniyaaa'a minat ta'affufi ta'rifuhum biseemaahum laa yas'aloonan naasa ilhaafaa; wa maa tunfiqoo min khairin fa innal laaha bihee 'Aleem", "translation": "[Charity is] for the poor who have been restricted for the cause of Allah, unable to move about in the land. An ignorant [person] would think them self-sufficient because of their restraint, but you will know them by their [characteristic] sign. They do not ask people persistently [or at all]. And whatever you spend of good - indeed, Allah is Knowing of it."}, {"ayah": 274, "translit": "Allazeena yunfiqoona amwaalahum billaili wan nahaari sirranw wa 'alaaniyatan falahum ajruhum 'inda Rabbihim wa laa khawfun 'alaihim wa laa hum yahzanoon", "translation": "Those who spend their wealth [in Allah 's way] by night and by day, secretly and publicly - they will have their reward with their Lord. And no fear will there be concerning them, nor will they grieve."}, {"ayah": 275, "translit": "Allazeena yaakuloonar ribaa laa yaqoomoona illaa kamaa yaqoomul lazee yatakhabbatuhush shaitaanu minal mass; zaalika bi annahum qaalooo innamal bai'u mishur ribaa; wa ahallal laahul bai'a wa harramar ribba; faman jaaa'ahoo maw'izatum mir rabbihee fantahaa falahoo maa salafa wa amruhooo ilal laahi wa man 'aada fa ulaaa 'ika Ashaabun naari hum feehaa khaalidoon", "translation": "Those who consume interest cannot stand [on the Day of Resurrection] except as one stands who is being beaten by Satan into insanity. That is because they say, \"Trade is [just] like interest.\" But Allah has permitted trade and has forbidden interest. So whoever has received an admonition from his Lord and desists may have what is past, and his affair rests with Allah. But whoever returns to [dealing in interest or usury] - those are the companions of the Fire; they will abide eternally therein."}, {"ayah": 276, "translit": "Yamhaqul laahur ribaa wa yurbis sadaqaat; wallaahu laa yuhibbu kulla kaffaarin aseem", "translation": "Allah destroys interest and gives increase for charities. And Allah does not like every sinning disbeliever."}, {"ayah": 277, "translit": "Innal lazeena aamanoo wa amilus saalihaati wa aqaamus salaata wa aatawuz zakaata lahum ajruhum 'inda rabbihim wa laa khawfun 'alaihim wa laa hum yahzanoon", "translation": "Indeed, those who believe and do righteous deeds and establish prayer and give zakah will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve."}, {"ayah": 278, "translit": "Yaaa ayyuhal lazeena aamanut taqul laaha wa zaroo maa baqiya minar ribaaa in kuntum mu'mineen", "translation": "O you who have believed, fear Allah and give up what remains [due to you] of interest, if you should be believers."}, {"ayah": 279, "translit": "Fail lam taf'aloo faazanoo biharbim minal laahi wa Rasoolihee wa in tubtum falakum ru'oosu amwaalikum laa tazlimoona wa laa tuzlamoon", "translation": "And if you do not, then be informed of a war [against you] from Allah and His Messenger. But if you repent, you may have your principal - [thus] you do no wrong, nor are you wronged."}, {"ayah": 280, "translit": "Wa in kaana zoo 'usratin fanaziratun ilaa maisarah; wa an tasaddaqoo khairul lakum in kuntum ta'lamoon", "translation": "And if someone is in hardship, then [let there be] postponement until [a time of] ease. But if you give [from your right as] charity, then it is better for you, if you only knew."}, {"ayah": 281, "translit": "Wattaqoo yawman turja'oona feehi ilal laahi summa tuwaffaa kullu nafsim maa kasabat wa hum laa yuzlamoon", "translation": "And fear a Day when you will be returned to Allah. Then every soul will be compensated for what it earned, and they will not be treated unjustly."}, {"ayah": 282, "translit": "Yaa ayyuhal lazeena aamanoo izaa tadaayantum bidinin ilaa ajalimmusamman faktubooh; walyaktub bainakum kaatibum bil'adl; wa laa yaaba kaatibun ai yaktuba kamaa 'allamahul laah; falyaktub walyumlilil lazee 'alaihil haqqu walyattaqil laaha rabbahoo wa laa yabkhas minhu shai'aa; fa in kaanal lazee 'alaihil lhaqqu safeehan aw da'eefan aw laa yastatee'u ai yumilla huwa falyumlil waliyyuhoo bil'adl; wastash hidoo shaheedaini mir rijaalikum fa il lam yakoonaa rajulaini farajulunw wamra ataani mimman tardawna minash shuhadaaa'i an tadilla ihdaahumaa fatuzakkira ihdaahumal ukhraa; wa laa yaabash shuhadaaa'u izaa maadu'oo; wa laa tas'amooo an taktuboohu sagheeran awkabeeran ilaaa ajalih; zaalikum aqsatu 'indal laahi wa aqwamu lishshahaadati wa adnaaa allaa tartaabooo illaaa an takoona tijaaratan haadiratan tudeeroonahaa bainakum falaisa 'alaikum junaahun allaa taktuboohan; wa ashidooo izaa tabaaya'tum; wa laa yudaaarra kaatibunw wa laa shaheed; wa in taf'aloo fa innahoo fusooqum bikum; wattaqul laaha wa yu'allimu kumul laah; wallaahu bikulli shai'in 'Aleem", "translation": "O you who have believed, when you contract a debt for a specified term, write it down. And let a scribe write [it] between you in justice. Let no scribe refuse to write as Allah has taught him. So let him write and let the one who has the obligation dictate. And let him fear Allah, his Lord, and not leave anything out of it. But if the one who has the obligation is of limited understanding or weak or unable to dictate himself, then let his guardian dictate in justice. And bring to witness two witnesses from among your men. And if there are not two men [available], then a man and two women from those whom you accept as witnesses - so that if one of the women errs, then the other can remind her. And let not the witnesses refuse when they are called upon. And do not be [too] weary to write it, whether it is small or large, for its [specified] term. That is more just in the sight of Allah and stronger as evidence and more likely to prevent doubt between you, except when it is an immediate transaction which you conduct among yourselves. For [then] there is no blame upon you if you do not write it. And take witnesses when you conclude a contract. Let no scribe be harmed or any witness. For if you do so, indeed, it is [grave] disobedience in you. And fear Allah. And Allah teaches you. And Allah is Knowing of all things."}, {"ayah": 283, "translit": "Wa in kuntum 'alaa safarinw wa lam tajidoo kaatiban farihaanum maqboodatun fa in amina ba'dukum ba'dan falyu'addil lazi tumina amaa natahoo walyattaqil laaha Rabbah; wa laa taktumush shahaadah; wa mai yaktumhaa fa innahooo aasimun qalbuh; wallaahu bimaa ta'maloona 'Aleem", "translation": "And if you are on a journey and cannot find a scribe, then a security deposit [should be] taken. And if one of you entrusts another, then let him who is entrusted discharge his trust [faithfully] and let him fear Allah, his Lord. And do not conceal testimony, for whoever conceals it - his heart is indeed sinful, and Allah is Knowing of what you do."}, {"ayah": 284, "translit": "Lillaahi maa fissamaawaati wa maa fil ard; wa in tubdoo maa feee anfusikum aw tukhfoohu yuhaasibkum bihil laa; fayaghfiru li mai yashaaa'u wa yu'azzibu mai yashaaa u;wallaahu 'alaa kulli shai in qadeer", "translation": "To Allah belongs whatever is in the heavens and whatever is in the earth. Whether you show what is within yourselves or conceal it, Allah will bring you to account for it. Then He will forgive whom He wills and punish whom He wills, and Allah is over all things competent."}, {"ayah": 285, "translit": "Aamanar-Rasoolu bimaaa unzila ilaihi mir-Rabbihee walmu'minoon; kullun aamana billaahi wa Malaaa'ikathihee wa Kutubhihee wa Rusulih laa nufarriqu baina ahadim-mir-Rusulihee wa qaaloo sami'naa wa ata'naa ghufraanaka Rabbanaa wa ilaikal-maseer", "translation": "The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], \"We make no distinction between any of His messengers.\" And they say, \"We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination.\""}, {"ayah": 286, "translit": "Laa yukalliful-laahu nafsan illaa wus'ahaa; lahaa maa kasabat wa 'alaihaa maktasabat; Rabbanaa la tu'aakhiznaa in naseenaaa aw akhtaanaa; Rabbanaa wa laa tahmil-'alainaaa isran kamaa hamaltahoo 'alal-lazeena min qablinaa; Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bih wa'fu 'annaa waghfir lanaa warhamnaa; Anta mawlaanaa fansurnaa 'alal qawmil kaafireen (section 40)", "translation": "Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. \"Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people.\""}]}, {"num": 3, "name": "Aal-Imran", "meaning": "Family of Imran", "verses": [{"ayah": 1, "translit": "Alif-Laam-Meeem", "translation": "Alif, Lam, Meem."}, {"ayah": 2, "translit": "Allaahu laaa ilaaha illaa Huwal Haiyul Qaiyoom", "translation": "Allah - there is no deity except Him, the Ever-Living, the Sustainer of existence."}, {"ayah": 3, "translit": "Nazzala 'alaikal Kitaaba bilhaqqi musaddiqal limaa baina yadaihi wa anzalat Tawraata wal Injeel", "translation": "He has sent down upon you, [O Muhammad], the Book in truth, confirming what was before it. And He revealed the Torah and the Gospel."}, {"ayah": 4, "translit": "Min qablu hudal linnaasi wa anzalal Furqaan; innallazeena kafaroo bi Aayaatil laahi lahum 'azaabun shadeed; wallaahu 'azeezun zun tiqaam", "translation": "Before, as guidance for the people. And He revealed the Qur'an. Indeed, those who disbelieve in the verses of Allah will have a severe punishment, and Allah is exalted in Might, the Owner of Retribution."}, {"ayah": 5, "translit": "Innal laaha laa yakhfaa 'alaihi shai'un fil ardi wa laa fis samaaa'", "translation": "Indeed, from Allah nothing is hidden in the earth nor in the heaven."}, {"ayah": 6, "translit": "Huwal lazee yusawwirukum fil arhaami kaifa yashaaa'; laa ilaaha illaa Huwal 'Azeezul Hakeem", "translation": "It is He who forms you in the wombs however He wills. There is no deity except Him, the Exalted in Might, the Wise."}, {"ayah": 7, "translit": "Huwal lazeee anzala 'alaikal Kitaaba minhu Aayaatum Muh kamaatun hunna Ummul Kitaabi wa ukharu Mutashaabihaatun faammal lazeena fee quloobihim ziyghun fa yattabi'oona ma tashaabaha minhubtighaaa 'alfitnati wabtighaaa'a taaweelih; wa maa ya'lamu taaweelahooo illal laah; warraasikhoona fil 'ilmi yaqooloona aamannaa bihee kullum min 'indi Rabbinaa; wa maa yazzakkaru illaaa ulul albaab", "translation": "It is He who has sent down to you, [O Muhammad], the Book; in it are verses [that are] precise - they are the foundation of the Book - and others unspecific. As for those in whose hearts is deviation [from truth], they will follow that of it which is unspecific, seeking discord and seeking an interpretation [suitable to them]. And no one knows its [true] interpretation except Allah. But those firm in knowledge say, \"We believe in it. All [of it] is from our Lord.\" And no one will be reminded except those of understanding."}, {"ayah": 8, "translit": "Rabbanaa laa tuzigh quloobanaa ba'da iz hadaitanaa wa hab lanaa mil ladunka rahmah; innaka antal Wahhaab", "translation": "[Who say], \"Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower."}, {"ayah": 9, "translit": "Rabbanaaa innaka jaami 'un-naasi li Yawmil laa raibafeeh; innal laaha laa yukhliful mee'aad", "translation": "Our Lord, surely You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise.\""}, {"ayah": 10, "translit": "Innal lazeena kafaroo lan tughniya 'anhum amwaaluhum wa laaa awlaaduhum minal laahi shai'anw wa ulaaa'ika hum waqoodun Naar", "translation": "Indeed, those who disbelieve - never will their wealth or their children avail them against Allah at all. And it is they who are fuel for the Fire."}, {"ayah": 11, "translit": "Kadaabi Aali Fir'awna wallazeena min qablihim; kazzaboo bi Aayaatinaa fa akhazahumul laahu bizunoo bihim; wallaahu shadeedul 'iqaab", "translation": "[Theirs is] like the custom of the people of Pharaoh and those before them. They denied Our signs, so Allah seized them for their sins. And Allah is severe in penalty."}, {"ayah": 12, "translit": "Qul lillazeena kafaroosatughlaboona wa tuhsharoona ilaa jahannam; wa bi'sal mihaad", "translation": "Say to those who disbelieve, \"You will be overcome and gathered together to Hell, and wretched is the resting place.\""}, {"ayah": 13, "translit": "Qad kaana lakum Aayatun fee fi'atainil taqataa fi'atun tuqaatilu fee sabeelil laahi wa ukhraa kaafiratuny yarawnahum mislaihim raayal 'ayn; wallaahu yu'ayyidu bi nasrihee mai yashaaa'; innaa fee zaalika la 'ibratal li ulil absaar", "translation": "Already there has been for you a sign in the two armies which met - one fighting in the cause of Allah and another of disbelievers. They saw them [to be] twice their [own] number by [their] eyesight. But Allah supports with His victory whom He wills. Indeed in that is a lesson for those of vision."}, {"ayah": 14, "translit": "Zuyyina linnaasi hubbush shahawaati minannisaaa'i wal baneena walqanaateeril muqantarati minaz zahabi walfiddati walkhailil musawwamati wal an'aami walhars; zaalika mataa'ul hayaatid dunyaa wallaahu 'indahoo husnul ma-aab", "translation": "Beautified for people is the love of that which they desire - of women and sons, heaped-up sums of gold and silver, fine branded horses, and cattle and tilled land. That is the enjoyment of worldly life, but Allah has with Him the best return."}, {"ayah": 15, "translit": "Qul a'unabbi 'ukum bikhairim min zaalikum; lillazeenat taqaw 'inda Rabbihim jannaatun tajree min tahtihal anhaaru khaalideena feehaa wa azwaajum mutahharatunw wa ridwaanum minal laah; wallaahu baseerum bil'ibaad", "translation": "Say, \"Shall I inform you of [something] better than that? For those who fear Allah will be gardens in the presence of their Lord beneath which rivers flow, wherein they abide eternally, and purified spouses and approval from Allah. And Allah is Seeing of [His] servants -"}, {"ayah": 16, "translit": "Allazeena yaqooloona Rabbanaaa innanaaa aamannaa faghfir lanaa zunoobanaa wa qinaa 'azaaban Naar", "translation": "Those who say, \"Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire,\""}, {"ayah": 17, "translit": "Assaabireena wassaa diqeena walqaaniteena walmunfiqeena walmus taghfireena bil ashaar", "translation": "The patient, the true, the obedient, those who spend [in the way of Allah], and those who seek forgiveness before dawn."}, {"ayah": 18, "translit": "Shahidal laahu annahoo laa ilaaha illaa Huwa walmalaaa'ikatu wa ulul 'ilmi qaaa'imam bilqist; laaa ilaaha illaa Huwal 'Azeezul Hakeem", "translation": "Allah witnesses that there is no deity except Him, and [so do] the angels and those of knowledge - [that He is] maintaining [creation] in justice. There is no deity except Him, the Exalted in Might, the Wise."}, {"ayah": 19, "translit": "Innad deena 'indal laahil Islaam; wa makhtalafal lazeena ootul Kitaaba illaa mim ba'di maa jaaa'ahumul 'ilmu baghyam bainahum; wa mai yakfur bi Aayaatil laahi fa innal laaha saree'ul hisaab", "translation": "Indeed, the religion in the sight of Allah is Islam. And those who were given the Scripture did not differ except after knowledge had come to them - out of jealous animosity between themselves. And whoever disbelieves in the verses of Allah, then indeed, Allah is swift in [taking] account."}, {"ayah": 20, "translit": "Fa in haaajjooka faqul aslamtu wajhiya lillaahi wa manit taba'an; wa qul lillazeena ootul Kitaaba wal ummiyyeena 'a-aslamtum; fa in aslamoo faqadih tadaw wa in tawallaw fa innamaa 'alaikal balaagh; wallaahu baseerum bil 'ibaad", "translation": "So if they argue with you, say, \"I have submitted myself to Allah [in Islam], and [so have] those who follow me.\" And say to those who were given the Scripture and [to] the unlearned, \"Have you submitted yourselves?\" And if they submit [in Islam], they are rightly guided; but if they turn away - then upon you is only the [duty of] notification. And Allah is Seeing of [His] servants."}, {"ayah": 21, "translit": "Innal lazeena yakfuroona  bi Aayaatil laahi wa yaqtuloonan Nabiyyeena bighairi haqqinw wa yaqtuloonal lazeena yaamuroona bilqisti minannaasi fabashirhum bi'azaabin aleem", "translation": "Those who disbelieve in the signs of Allah and kill the prophets without right and kill those who order justice from among the people - give them tidings of a painful punishment."}, {"ayah": 22, "translit": "Ulaaa'ikal lazeena habitat a'maaluhum fid dunyaa wal Aaakhirati wa maa lahum min naasireen", "translation": "They are the ones whose deeds have become worthless in this world and the Hereafter, and for them there will be no helpers."}, {"ayah": 23, "translit": "Alam tara ilal lazeena ootoo naseebam minal Kitaabi yud'awna ilaa Kitaabil laahi liyahkuma bainahum summa yatawallaa fareequm minhum wa hum mu'ridoon", "translation": "Do you not consider, [O Muhammad], those who were given a portion of the Scripture? They are invited to the Scripture of Allah that it should arbitrate between them; then a party of them turns away, and they are refusing."}, {"ayah": 24, "translit": "Zaalika bi annahum qaaloo lan tamassanan naaru illaaa ayyaamam ma'doodaatinw wa gharrahum fee deenihim maa kaanoo yaftaroon", "translation": "That is because they say, \"Never will the Fire touch us except for [a few] numbered days,\" and [because] they were deluded in their religion by what they were inventing."}, {"ayah": 25, "translit": "Fakaifa izaa jama'naahum li Yawmil laa raiba fee wa wuffiyat kullu nafsim maa kasabat wa hum laa yuzlamoon", "translation": "So how will it be when We assemble them for a Day about which there is no doubt? And each soul will be compensated [in full for] what it earned, and they will not be wronged."}, {"ayah": 26, "translit": "Qulil laahumma Maalikal Mulki tu'til mulka man tashaaa'u wa tanzi'ulmulka mimman tashhaaa'u wa tu'izzu man tashaaa'u wa tuzillu man tashaaa'u biyadikal khairu innaka 'alaa kulli shai'in Qadeer", "translation": "Say, \"O Allah, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand is [all] good. Indeed, You are over all things competent."}, {"ayah": 27, "translit": "Toolijul laila fin nahaari wa toolijun nahaara fil  laili wa tukhrijul haiya minalmaiyiti wa tukhrijulo maiyita minal haiyi wa tarzuqu man tashaaa'u bighari hisab", "translation": "You cause the night to enter the day, and You cause the day to enter the night; and You bring the living out of the dead, and You bring the dead out of the living. And You give provision to whom You will without account.\""}, {"ayah": 28, "translit": "Laa yattakhizil mu'minoonal kaafireena awliyaaa'a min doonil mu'mineena wa mai yaf'al zaalika falaisa minal laahi fee shai'in illaaa an tattaqoo minhum tuqaah; wa yuhazzirukumul laahu nafsah; wa ilal laahil maseer", "translation": "Let not believers take disbelievers as allies rather than believers. And whoever [of you] does that has nothing with Allah, except when taking precaution against them in prudence. And Allah warns you of Himself, and to Allah is the [final] destination."}, {"ayah": 29, "translit": "Qul in tukhfoo maa fee sudoorikum aw tubdoohu ya'lamhul laah; wa ya'lamu maa fis samaawaati wa maa fil ard; wallaahu 'alaa kulli shai'in Qadeer", "translation": "Say, \"Whether you conceal what is in your breasts or reveal it, Allah knows it. And He knows that which is in the heavens and that which is on the earth. And Allah is over all things competent."}, {"ayah": 30, "translit": "Yawma tajidu kullu nafsim maa'amilat min khairim muhdaranw wa maa 'amilat min sooo'in tawaddu law anna bainahaa wa bainahooo amadam ba'eedaa; wa yuhazzirukumul laahu nafsah; wallaahu ra'oofum bil'ibaad", "translation": "The Day every soul will find what it has done of good present [before it] and what it has done of evil, it will wish that between itself and that [evil] was a great distance. And Allah warns you of Himself, and Allah is Kind to [His] servants.\""}, {"ayah": 31, "translit": "Qul in kuntum tuhibboonal laaha fattabi' oonee yuhbibkumul laahu wa yaghfir lakum zunoobakum; wallaahu Ghafoorur Raheem", "translation": "Say, [O Muhammad], \"If you should love Allah, then follow me, [so] Allah will love you and forgive you your sins. And Allah is Forgiving and Merciful.\""}, {"ayah": 32, "translit": "Qul atee'ul laaha war Rasoola fa in tawallaw fa innal laaha laa yuhibbul kaafireen", "translation": "Say, \"Obey Allah and the Messenger.\" But if they turn away - then indeed, Allah does not like the disbelievers."}, {"ayah": 33, "translit": "Innal laahas tafaaa Aadama wa Noohanw wa Aala Ibraaheema wa Aala Imraana 'alal 'aalameen", "translation": "Indeed, Allah chose Adam and Noah and the family of Abraham and the family of 'Imran over the worlds -"}, {"ayah": 34, "translit": "Zurriyyatam ba'duhaa mim ba'd; wallaahu Samee'un 'Aleem", "translation": "Descendants, some of them from others. And Allah is Hearing and Knowing."}, {"ayah": 35, "translit": "Iz qaalatim ra atu 'Imraana Rabbi innee nazartu laka maa fee batnee muharraran fataqabbal minnee innaka Antas Samee'ul 'Aleem", "translation": "[Mention, O Muhammad], when the wife of 'Imran said, \"My Lord, indeed I have pledged to You what is in my womb, consecrated [for Your service], so accept this from me. Indeed, You are the Hearing, the Knowing.\""}, {"ayah": 36, "translit": "Falammaa waqa'athaa qaalat Rabbi innee wada'tuhaaa unsaa wallaahu a'lamu bimaa wada'at wa laisaz zakaru kalunsaa wa innee sammaituhaa Maryama wa innee u'eezuhaa bika wa zurriyyatahaa minash Shaitaanir Rajeem", "translation": "But when she delivered her, she said, \"My Lord, I have delivered a female.\" And Allah was most knowing of what she delivered, \"And the male is not like the female. And I have named her Mary, and I seek refuge for her in You and [for] her descendants from Satan, the expelled [from the mercy of Allah].\""}, {"ayah": 37, "translit": "Fataqabbalahaa Rabbuhaa biqaboolin hasaninw wa ambatahaa nabaatan hasananw wa kaffalahaa Zakariyyaa kullamaa dakhala 'alaihaa Zakariyyal Mihraaba wajada 'indahaa rizqan qaala yaa Maryamu annaa laki haazaa qaalat huwa min 'indil laahi innal laaha yarzuqu mai yashaaa'u bighairi hisaab", "translation": "So her Lord accepted her with good acceptance and caused her to grow in a good manner and put her in the care of Zechariah. Every time Zechariah entered upon her in the prayer chamber, he found with her provision. He said, \"O Mary, from where is this [coming] to you?\" She said, \"It is from Allah. Indeed, Allah provides for whom He wills without account.\""}, {"ayah": 38, "translit": "Hunaaalika da'aa Zakariyyaa Rabbahoo qaala Rabbi hab lee mil ladunka zurriyyatan taiyibatan innaka samee'ud du'aaa'", "translation": "At that, Zechariah called upon his Lord, saying, \"My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication.\""}, {"ayah": 39, "translit": "Fanaadat hul malaaa'ikatu wa huwa qaaa'imuny yusallee fil Mihraabi annal laaha yubashshiruka bi Yahyaa musaddiqam bi Kalimatim minal laahi wa saiyidanw wa hasooranw wa Nabiyyam minas saaliheen", "translation": "So the angels called him while he was standing in prayer in the chamber, \"Indeed, Allah gives you good tidings of John, confirming a word from Allah and [who will be] honorable, abstaining [from women], and a prophet from among the righteous.\""}, {"ayah": 40, "translit": "Qaala Rabbi annaa yakoonu lee ghulaamunw wa qad balaghaniyal kibaru wamraatee 'aaqirun qaala kazaalikal laahu yaf'alu maa yashaaa'", "translation": "He said, \"My Lord, how will I have a boy when I have reached old age and my wife is barren?\" The angel said, \"Such is Allah; He does what He wills.\""}, {"ayah": 41, "translit": "Qaala Rabbij 'al leee Aayatan qaala Aaayatuka allaa tukalliman naasa salaasata ayyaamin illa ramzaa; wzkur Rabbaka kaseeranw wa sabbih bil'ashiyyi wal ibkaar (section 4)", "translation": "He said, \"My Lord, make for me a sign.\" He Said, \"Your sign is that you will not [be able to] speak to the people for three days except by gesture. And remember your Lord much and exalt [Him with praise] in the evening and the morning.\""}, {"ayah": 42, "translit": "Wa iz qaalatil malaaa'ikatu yaa Ya Maryamu innal laahas tafaaki wa tahharaki wastafaaki 'alaa nisaaa'il 'aalameen", "translation": "And [mention] when the angels said, \"O Mary, indeed Allah has chosen you and purified you and chosen you above the women of the worlds."}, {"ayah": 43, "translit": "Yaa Maryamuq nutee li Rabbiki wasjudee warka'ee ma'ar raaki'een", "translation": "O Mary, be devoutly obedient to your Lord and prostrate and bow with those who bow [in prayer].\""}, {"ayah": 44, "translit": "Zaalika min ambaaa'il ghaibi nooheehi ilaik; wa maa kunta ladaihim iz yulqoona aqlaamahum ayyuhum yakfulu Maryama wa maa kunta ladaihim iz yakhtasimoon", "translation": "That is from the news of the unseen which We reveal to you, [O Muhammad]. And you were not with them when they cast their pens as to which of them should be responsible for Mary. Nor were you with them when they disputed."}, {"ayah": 45, "translit": "Iz qaalatil  malaaa'ikatu yaa Maryamu innal laaha yubashshiruki bi Kalimatim minhus muhul Maseeh u 'Eesab nu Maryama wajeehan fid dunyaa wal Aakhirati wa minal muqarrabeen", "translation": "[And mention] when the angels said, \"O Mary, indeed Allah gives you good tidings of a word from Him, whose name will be the Messiah, Jesus, the son of Mary - distinguished in this world and the Hereafter and among those brought near [to Allah]."}, {"ayah": 46, "translit": "Wa yukallimun naasa filmahdi wa kahlanw wa minassaaliheen", "translation": "He will speak to the people in the cradle and in maturity and will be of the righteous.\""}, {"ayah": 47, "translit": "Qaalat Rabbi annaa yakoonu ee waladunw wa lam yamsasnee basharun qaala kazaalikil laahu yakhluqu maa yashaaa'; izaa qadaaa amran fa innamaa yaqoolu lahoo kun fayakoon", "translation": "She said, \"My Lord, how will I have a child when no man has touched me?\" [The angel] said, \"Such is Allah; He creates what He wills. When He decrees a matter, He only says to it, 'Be,' and it is."}, {"ayah": 48, "translit": "Wa yu'allimuhul Kitaaba wal Hikmata wat Tawraata wal Injeel", "translation": "And He will teach him writing and wisdom and the Torah and the Gospel"}, {"ayah": 49, "translit": "Wa Rasoolan ilaa Baneee Israaa'eela annee qad ji'tukum bi Aayatim mir Rabbikum annee akhluqu lakum minatteeni kahai 'atittairi fa anfukhu feehi fayakoonu tairam bi iznil laahi wa ubri'ul akmaha wal abrasa wa uhyil mawtaa bi iznil laahi wa unabbi'ukum bimaa taakuloona wa maa taddakhiroona fee buyootikum; inna fee zaalika la Aayatal lakum in kuntum mu'mineen", "translation": "And [make him] a messenger to the Children of Israel, [who will say], 'Indeed I have come to you with a sign from your Lord in that I design for you from clay [that which is] like the form of a bird, then I breathe into it and it becomes a bird by permission of Allah. And I cure the blind and the leper, and I give life to the dead - by permission of Allah. And I inform you of what you eat and what you store in your houses. Indeed in that is a sign for you, if you are believers."}, {"ayah": 50, "translit": "Wa musaddiqal limaa baina yadaiya minat Tawraati wa liuhilla lakum ba'dal lazee hurrima 'alaikum; wa ji'tukum bi Aayatim mir Rabbikum fattaqul laaha wa atee'oon", "translation": "And [I have come] confirming what was before me of the Torah and to make lawful for you some of what was forbidden to you. And I have come to you with a sign from your Lord, so fear Allah and obey me."}, {"ayah": 51, "translit": "Innal laaha Rabbee wa Rabbukum fa'budooh; haazaa Siraatum Mustaqeem", "translation": "Indeed, Allah is my Lord and your Lord, so worship Him. That is the straight path.\""}, {"ayah": 52, "translit": "Falammaaa ahassa 'Eesaa minhumul kufra qaala man ansaaree ilal laahi qaalal Hawaariyyoona nahnu ansaarul laahi aamannaa billaahi washhad bi annaa muslimoon", "translation": "But when Jesus felt [persistence in] disbelief from them, he said, \"Who are my supporters for [the cause of] Allah?\" The disciples said, \"We are supporters for Allah. We have believed in Allah and testify that we are Muslims [submitting to Him]."}, {"ayah": 53, "translit": "Rabbanaaa aamannaa bimaaa anzalta wattaba'nar Rasoola faktubnaa ma'ash shaahideen", "translation": "Our Lord, we have believed in what You revealed and have followed the messenger Jesus, so register us among the witnesses [to truth].\""}, {"ayah": 54, "translit": "Wa makaroo wa makaral laahu wallaahu khairul maakireen", "translation": "And the disbelievers planned, but Allah planned. And Allah is the best of planners."}, {"ayah": 55, "translit": "Iz qaalal laahu yaa 'Eesaaa innee mutawaffeeka wa raafi'uka ilaiya wa mutah hiruka minal lazeena kafaroo wa jaa'ilul lazeenattaba ooka fawqal lazeena kafarooo ilaa Yawmil Qiyaamati summa ilaiya marji'ukum fa ahkumu bainakum feemaa kuntum feehi takhtaliifoon", "translation": "[Mention] when Allah said, \"O Jesus, indeed I will take you and raise you to Myself and purify you from those who disbelieve and make those who follow you [in submission to Allah alone] superior to those who disbelieve until the Day of Resurrection. Then to Me is your return, and I will judge between you concerning that in which you used to differ."}, {"ayah": 56, "translit": "Fa ammal lazeena kafaroo fa u'az zibuhum 'azaaban shadeedan fiddunyaa wal Aakhirati wa maa lahum min naasireen", "translation": "And as for those who disbelieved, I will punish them with a severe punishment in this world and the Hereafter, and they will have no helpers.\""}, {"ayah": 57, "translit": "Wa ammal lazeena aamanoo wa 'amilus saalihaati fa yuwaffeehim ujoorahum; wallaahu laa yuhibbuz zaalimeen", "translation": "But as for those who believed and did righteous deeds, He will give them in full their rewards, and Allah does not like the wrongdoers."}, {"ayah": 58, "translit": "Zaalika natloohu 'alaika minal Aayaati wa Zikril Hakeem", "translation": "This is what We recite to you, [O Muhammad], of [Our] verses and the precise [and wise] message."}, {"ayah": 59, "translit": "Inna masala 'Eesaa 'indal laahi kamasali Aadama khalaqahoo min turaabin summa qaala lahoo kun fayakoon", "translation": "Indeed, the example of Jesus to Allah is like that of Adam. He created Him from dust; then He said to him, \"Be,\" and he was."}, {"ayah": 60, "translit": "Alhaqqu mir Rabbika falaa takum minal mumtareen", "translation": "The truth is from your Lord, so do not be among the doubters."}, {"ayah": 61, "translit": "Faman haaajjaka feehi mim ba'di maa jaaa'aka minal 'ilmi faqul ta'aalaw nad'u abnaaa'anaa wa abnaaa'akum wa nisaaa'anaa wa nisaaa'akum wa anfusanaa wa anfusakum summa nabtahil fanaj'al la'natal laahi 'alal kaazibeen", "translation": "Then whoever argues with you about it after [this] knowledge has come to you - say, \"Come, let us call our sons and your sons, our women and your women, ourselves and yourselves, then supplicate earnestly [together] and invoke the curse of Allah upon the liars [among us].\""}, {"ayah": 62, "translit": "Innaa haazaa lahuwal qasasul haqq; wa maa min ilaahin illal laah; wa innal laahaa la Huwal 'Azeezul Hakeem", "translation": "Indeed, this is the true narration. And there is no deity except Allah. And indeed, Allah is the Exalted in Might, the Wise."}, {"ayah": 63, "translit": "Fa in tawallaw fa innal laaha'aleemun bil mufsideen", "translation": "But if they turn away, then indeed - Allah is Knowing of the corrupters."}, {"ayah": 64, "translit": "Qul yaa Ahlal Kitaabi ta'aalaw ilaa Kalimatin sawaaa'im bainanaa wa bainakum allaa na'buda illal laaha wa laa nushrika bihee shai'anw wa laa yattakhiza ba'dunaa ba'dan arbaabam min doonil laah; fa in tawallaw faqoolush hadoo bi annaa muslimoon", "translation": "Say, \"O People of the Scripture, come to a word that is equitable between us and you - that we will not worship except Allah and not associate anything with Him and not take one another as lords instead of Allah.\" But if they turn away, then say, \"Bear witness that we are Muslims [submitting to Him].\""}, {"ayah": 65, "translit": "Yaaa Ahlal Kitaabi limaa tuhaaajjoona feee Ibraaheema wa maaa unzilatit Tawraatu wal Injeelu illaa mim ba'dih; afala ta'qiloon", "translation": "O People of the Scripture, why do you argue about Abraham while the Torah and the Gospel were not revealed until after him? Then will you not reason?"}, {"ayah": 66, "translit": "Haaa antum haaa'ulaaa'i baajajtum feemaa lakum bihee 'ilmun falima tuhaaajjoonaa feemaa laisa lakum bihee 'ilm; wallaahu ya'lamu wa antum laa ta'lamoon", "translation": "Here you are - those who have argued about that of which you have [some] knowledge, but why do you argue about that of which you have no knowledge? And Allah knows, while you know not."}, {"ayah": 67, "translit": "Maa kaana Ibraaheemu Yahoodiyyanw wa laa Nasraa niyyanw wa laakin kaana Haneefam Muslimanw wa maa kaana minal mushrikeen", "translation": "Abraham was neither a Jew nor a Christian, but he was one inclining toward truth, a Muslim [submitting to Allah]. And he was not of the polytheists."}, {"ayah": 68, "translit": "Innaa awlan naasi bi Ibraaheema lallazeenat taba 'oohu wa haazan nabiyyu wallazeena aamanoo; wallaahu waliyyul mu'mineen", "translation": "Indeed, the most worthy of Abraham among the people are those who followed him [in submission to Allah] and this prophet, and those who believe [in his message]. And Allah is the ally of the believers."}, {"ayah": 69, "translit": "Waddat taaa'ifatum min Ahlil Kitaabi law yudil loonakum wa maa yudilloona illaaa anfusahum wa maa yash'uroon", "translation": "A faction of the people of the Scripture wish they could mislead you. But they do not mislead except themselves, and they perceive [it] not."}, {"ayah": 70, "translit": "Yaaa Ahlal Kitaabi lima takfuroona bi Aayaatil laahi wan antum tashadoon", "translation": "O People of the Scripture, why do you disbelieve in the verses of Allah while you witness [to their truth]?"}, {"ayah": 71, "translit": "Yaaa Ahalal Kitaabi lima talbisoonal haqqa bilbaatili wa taktumoonal haqqa wa antum ta'lamoon", "translation": "O People of the Scripture, why do you confuse the truth with falsehood and conceal the truth while you know [it]?"}, {"ayah": 72, "translit": "Wa qaalat taaa'ifatum min Ahlil Kitaabi aaminoo billazeee unzila 'alal lazeena aamanoo wajhan nahaari wakfurooo aakhirahoo la'alla hum yarji'oon", "translation": "And a faction of the People of the Scripture say [to each other], \"Believe in that which was revealed to the believers at the beginning of the day and reject it at its end that perhaps they will abandon their religion,"}, {"ayah": 73, "translit": "Wa laa tu'minooo illaa liman tabi'a deenakum qul innal hudaa hudal laahi ai yu'taaa ahadum misla maaa ooteetum aw yuhaaajjookum 'inda Rabbikum, qul innal fadla biyadil laah; yu'teehi mai yashaaa'; wallaahu Waasi'un 'Aleem", "translation": "And do not trust except those who follow your religion.\" Say, \"Indeed, the [true] guidance is the guidance of Allah. [Do you fear] lest someone be given [knowledge] like you were given or that they would [thereby] argue with you before your Lord?\" Say, \"Indeed, [all] bounty is in the hand of Allah - He grants it to whom He wills. And Allah is all-Encompassing and Wise.\""}, {"ayah": 74, "translit": "Yakhtassu birahmatihee mai yashaaa'; wallaahu zulfadil 'azeem", "translation": "He selects for His mercy whom He wills. And Allah is the possessor of great bounty."}, {"ayah": 75, "translit": "Wa min Ahlil Kitaabi man in taamanhu biqintaariny yu'addihee ilaika wa minhum man in taamanhu bideenaaril laa yu'addiheee ilaika illaa maa dumta 'alaihi qaaa' imaa; zaalika biannahum qaaloo laisa 'alainaa fil ummiyyeena sabeelunw wa yaqooloona 'alal laahil kaziba wa hum ya'lamoon", "translation": "And among the People of the Scripture is he who, if you entrust him with a great amount [of wealth], he will return it to you. And among them is he who, if you entrust him with a [single] silver coin, he will not return it to you unless you are constantly standing over him [demanding it]. That is because they say, \"There is no blame upon us concerning the unlearned.\" And they speak untruth about Allah while they know [it]."}, {"ayah": 76, "translit": "Balaa man awfaa bi'ahdihee wattaqaa fainnal laaha yuhibbul muttaqeen", "translation": "But yes, whoever fulfills his commitment and fears Allah - then indeed, Allah loves those who fear Him."}, {"ayah": 77, "translit": "Innal lazeena yashtaroona bi'ahdil laahi wa aymaanihim samanan qaleelan ulaaa'ika laa khalaaqa lahum fil Aakhirati wa laa yukallimuhumul laahu wa laa yanzuru ilaihim Yawmal Qiyaamati wa laa yuzakkeehim wa lahum 'azabun 'aleem", "translation": "Indeed, those who exchange the covenant of Allah and their [own] oaths for a small price will have no share in the Hereafter, and Allah will not speak to them or look at them on the Day of Resurrection, nor will He purify them; and they will have a painful punishment."}, {"ayah": 78, "translit": "Wa inna minhum lafaree qany yalwoona alsinatahum bil Kitaabi litahsaboohu minal Kitaab, wa maa huwa minal Kitaabi wa yaqooloon huwa min 'indillaahi wa maa huwa min 'indillaahi wa yaqooloona 'alal laahil kaziba wa hum ya'lamoon", "translation": "And indeed, there is among them a party who alter the Scripture with their tongues so you may think it is from the Scripture, but it is not from the Scripture. And they say, \"This is from Allah,\" but it is not from Allah. And they speak untruth about Allah while they know."}, {"ayah": 79, "translit": "Maa kaana libasharin ai yu'tiyahul laahul Kitaaba walhukma wan Nubuwwata summa yaqoola linnaasi koonoo 'ibaadal lee min doonil laahi wa laakin koonoo rabbaaniy yeena bimaa kuntum tu'allimoonal Kitaaba wa bimaa kuntum tadrusoon", "translation": "It is not for a human [prophet] that Allah should give him the Scripture and authority and prophethood and then he would say to the people, \"Be servants to me rather than Allah,\" but [instead, he would say], \"Be pious scholars of the Lord because of what you have taught of the Scripture and because of what you have studied.\""}, {"ayah": 80, "translit": "Wa laa yaamurakum an tattakhizul malaaa 'ikata wan Nabiyyeena arbaabaa; a yaamurukum bilkufri ba'da iz antum muslimoon", "translation": "Nor could he order you to take the angels and prophets as lords. Would he order you to disbelief after you had been Muslims?"}, {"ayah": 81, "translit": "Wa iz akhazal laahu meesaaqan Nabiyyeena lamaaa aataitukum min Kitaabinw wa Hikmatin summa jaaa'akum Rasoolum musaddiqul limaa ma'akum latu'minunna bihee wa latansurunnah; qaala 'aaqrartum wa akhaztum alaa zaalikum isree qaalooo aqrarnaa; qaala fashhadoo wa ana ma'akum minash shaahideen", "translation": "And [recall, O People of the Scripture], when Allah took the covenant of the prophets, [saying], \"Whatever I give you of the Scripture and wisdom and then there comes to you a messenger confirming what is with you, you [must] believe in him and support him.\" [Allah] said, \"Have you acknowledged and taken upon that My commitment?\" They said, \"We have acknowledged it.\" He said, \"Then bear witness, and I am with you among the witnesses.\""}, {"ayah": 82, "translit": "Faman tawallaa ba'da zaalika fa ulaaa'ika humul faasiqoon", "translation": "And whoever turned away after that - they were the defiantly disobedient."}, {"ayah": 83, "translit": "Afaghaira deenil laahi yabghoona wa lahooo aslama man fis samaawaati wal ardi taw'anw wa karhanw wa ilaihi yurja'oon", "translation": "So is it other than the religion of Allah they desire, while to Him have submitted [all] those within the heavens and earth, willingly or by compulsion, and to Him they will be returned?"}, {"ayah": 84, "translit": "Qul aamannaa billaahi wa maaa unzila 'alainaa wa maaa unzila 'alaaa Ibraaheema wa Ismaa'eela wa Ishaaqa wa Ya'qooba wal Asbaati wa maaa ootiya Moosaa wa 'Eesaa wan Nabiyyoona mir Rabbihim laa nufarriqu baina ahadim minhum wa nahnu lahoo muslimoon", "translation": "Say, \"We have believed in Allah and in what was revealed to us and what was revealed to Abraham, Ishmael, Isaac, Jacob, and the Descendants, and in what was given to Moses and Jesus and to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [submitting] to Him.\""}, {"ayah": 85, "translit": "Wa mai yabtaghi ghairal Islaami deenan falany yuqbala minhu wa huwa fil Aakhirati minal khaasireen", "translation": "And whoever desires other than Islam as religion - never will it be accepted from him, and he, in the Hereafter, will be among the losers."}, {"ayah": 86, "translit": "Kaifa yahdil laahu qawman kafaroo ba'da eemaanihim wa shahidooo annar Rasoola haqqunw wa jaaa'ahumul baiyinaat; wallaahu laa yahdil qawmaz zaalimeen", "translation": "How shall Allah guide a people who disbelieved after their belief and had witnessed that the Messenger is true and clear signs had come to them? And Allah does not guide the wrongdoing people."}, {"ayah": 87, "translit": "Ulaaa'ika jazaaa'uhum anna 'alaihim la'natal laahi walmalaaa'ikati wannaasi ajma'een", "translation": "Those - their recompense will be that upon them is the curse of Allah and the angels and the people, all together,"}, {"ayah": 88, "translit": "Khaalideena feehaa laa yukhaffafu 'anhumul 'azaabu wa laa hum yunzaroon", "translation": "Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved."}, {"ayah": 89, "translit": "Illal lazeena taaboo mim ba'di zaalika wa aslahoo fa innal laaha Ghafoorur Raheem", "translation": "Except for those who repent after that and correct themselves. For indeed, Allah is Forgiving and Merciful."}, {"ayah": 90, "translit": "Innal lazeena kafaroo ba'da eemaanihim summaz daadoo kufral lan tuqbala tawbatuhum wa ulaaa'ika humud daaalloon", "translation": "Indeed, those who reject the message after their belief and then increase in disbelief - never will their [claimed] repentance be accepted, and they are the ones astray."}, {"ayah": 91, "translit": "Innal lazeena kafaroo wa maatoo wa hum kuffaarun falany yuqbala min ahadihim mil'ul ardi zahabanw wa lawiftadaa bih; ulaaa 'ika lahum 'azaabun aleemunw wa maa lahum min naasireen", "translation": "Indeed, those who disbelieve and die while they are disbelievers - never would the [whole] capacity of the earth in gold be accepted from one of them if he would [seek to] ransom himself with it. For those there will be a painful punishment, and they will have no helpers."}, {"ayah": 92, "translit": "Lan tanaalul birra hattaa tunfiqoo mimmaa tuhibboon; wa maa tunfiqoo min shai'in fa innal laaha bihee 'Aleem", "translation": "Never will you attain the good [reward] until you spend [in the way of Allah] from that which you love. And whatever you spend - indeed, Allah is Knowing of it."}, {"ayah": 93, "translit": "Kullut ta'aami kaana hillal li Baneee Israaa'eela illaa maa harrama Israaa'eelu 'alaa nafsihee min qabli an tunzzalat Tawraah; qul faatoo bit Tawraati fatloohaaa in kuntum saadiqeen", "translation": "All food was lawful to the Children of Israel except what Israel had made unlawful to himself before the Torah was revealed. Say, [O Muhammad], \"So bring the Torah and recite it, if you should be truthful.\""}, {"ayah": 94, "translit": "Famanif taraa 'alal laahilkaziba mim ba'di zaalika fa ulaaa'ika humuz zaalimoon", "translation": "And whoever invents about Allah untruth after that - then those are [truly] the wrongdoers."}, {"ayah": 95, "translit": "Qul sadaqal laah; fattabi'oo Millata Ibraaheema Haneefanw wa maa kaana minal mush rikeen", "translation": "Say, \"Allah has told the truth. So follow the religion of Abraham, inclining toward truth; and he was not of the polytheists.\""}, {"ayah": 96, "translit": "Inna awwala Baitinw wudi'a linnaasi lallazee bi Bakkata mubaarakanw wa hudal lil 'aalameen", "translation": "Indeed, the first House [of worship] established for mankind was that at Makkah - blessed and a guidance for the worlds."}, {"ayah": 97, "translit": "Feehi Aayaatum baiyinaatum Maqaamu Ibraaheema wa man dakhalahoo kaana aaminaa; wa lillaahi 'alan naasi Hijjul Baiti manis tataa'a ilaihi sabeelaa; wa man kafara fa innal laaha ghaniyyun 'anil 'aalameen", "translation": "In it are clear signs [such as] the standing place of Abraham. And whoever enters it shall be safe. And [due] to Allah from the people is a pilgrimage to the House - for whoever is able to find thereto a way. But whoever disbelieves - then indeed, Allah is free from need of the worlds."}, {"ayah": 98, "translit": "Qul yaaa Ahlal Kitaabi lima takfuroona bi Aayaatillaahi wallaahu shaheedun 'alaa maa ta'maloon", "translation": "Say, \"O People of the Scripture, why do you disbelieve in the verses of Allah while Allah is Witness over what you do?\""}, {"ayah": 99, "translit": "Qul yaaa Ahlal Kitaabi lima tusuddoona 'an sabeelil laahi man aamana tabghoonahaa 'iwajanw wa antum shuhadaaa'; wa mallaahu bighaafilin 'ammaa ta'maloon", "translation": "Say, \"O People of the Scripture, why do you avert from the way of Allah those who believe, seeking to make it [seem] deviant, while you are witnesses [to the truth]? And Allah is not unaware of what you do.\""}, {"ayah": 100, "translit": "Yaaa ayyuhal lazeena aamanoo in tutee'oo fareeqam minal lazeena ootul Kitaaba yaruddookum ba'da eemaanikum kaafireen", "translation": "O you who have believed, if you obey a party of those who were given the Scripture, they would turn you back, after your belief, [to being] unbelievers."}, {"ayah": 101, "translit": "Wa kaifa takfuroona wa antum tutlaa 'alaikum Aayaatul laahi wa feekum Rasooluh; wa mai ya'tasim baillaahi faqad hudiya ilaa Siraatim Mustaqeem", "translation": "And how could you disbelieve while to you are being recited the verses of Allah and among you is His Messenger? And whoever holds firmly to Allah has [indeed] been guided to a straight path."}, {"ayah": 102, "translit": "Yaaa ayyuhal lazeena aamanut taqul laaha haqqa tuqaatihee wa laa tamoontunna illaa wa antum muslimoon", "translation": "O you who have believed, fear Allah as He should be feared and do not die except as Muslims [in submission to Him]."}, {"ayah": 103, "translit": "Wa'tasimoo bi Hablil laahi jamee'anw wa laa tafarraqoo; wazkuroo ni'matal laahi alaikum iz kuntum a'daaa'an fa allafa baina quloobikum fa asbah tum bini'matiheee ikhwaananw wa kuntum 'alaa shafaa hufratim minan Naari fa anqazakum minhaa; kazaalika yubaiyinul laahu lakum aayaatihee la'allakum tahtadoon", "translation": "And hold firmly to the rope of Allah all together and do not become divided. And remember the favor of Allah upon you - when you were enemies and He brought your hearts together and you became, by His favor, brothers. And you were on the edge of a pit of the Fire, and He saved you from it. Thus does Allah make clear to you His verses that you may be guided."}, {"ayah": 104, "translit": "Waltakum minkum ummatuny yad'oona ilal khairi wa yaamuroona bilma 'roofi wa yanhawna 'anil munkar; wa ulaaa'ika humul muflihoon", "translation": "And let there be [arising] from you a nation inviting to [all that is] good, enjoining what is right and forbidding what is wrong, and those will be the successful."}, {"ayah": 105, "translit": "Wa laa takoonoo kallazeena tafarraqoo wakhtalafoo mim ba'di maa jaaa'ahumul baiyinaat; wa ulaaa'ika lahum 'azaabun 'azeem", "translation": "And do not be like the ones who became divided and differed after the clear proofs had come to them. And those will have a great punishment."}, {"ayah": 106, "translit": "Yawma tabyaddu wujoohunw wa taswaddu wujooh; faammal lazeenas waddat wujoohum akafartum ba'da eemaanikum fazooqul 'azaaba bimaa kuntum takfuroon", "translation": "On the Day [some] faces will turn white and [some] faces will turn black. As for those whose faces turn black, [to them it will be said], \"Did you disbelieve after your belief? Then taste the punishment for what you used to reject.\""}, {"ayah": 107, "translit": "Wa ammal lazeenabyadd at wujoohuhum fafee rahmatil laahi hum feehaa khaalidoon", "translation": "But as for those whose faces will turn white, [they will be] within the mercy of Allah. They will abide therein eternally."}, {"ayah": 108, "translit": "Tilka Aayaatul laahi natloohaa 'alaika bilhaqq; wa mal laahu yureedu zulmallil 'aalameen", "translation": "These are the verses of Allah. We recite them to you, [O Muhammad], in truth; and Allah wants no injustice to the worlds."}, {"ayah": 109, "translit": "Wa lillaahi maa fissamaawaati wa maa fil ard; wa ilal laahi turja;ul umoor", "translation": "To Allah belongs whatever is in the heavens and whatever is on the earth. And to Allah will [all] matters be returned."}, {"ayah": 110, "translit": "Kuntum khaira ummatin ukhrijat linnaasi taamuroona bilma'roofi wa tanhawna 'anil munkari wa tu'minoona billaah; wa law aamana Ahlul Kitaabi lakaana khairal lahum minhumul mu'minoona wa aksaruhumul faasiqoon", "translation": "You are the best nation produced [as an example] for mankind. You enjoin what is right and forbid what is wrong and believe in Allah. If only the People of the Scripture had believed, it would have been better for them. Among them are believers, but most of them are defiantly disobedient."}, {"ayah": 111, "translit": "Lai yadurrookum 'illaaa azanw wa ai yuqaatilookum yuwallookumul adbaara summa laa yunsaroon", "translation": "They will not harm you except for [some] annoyance. And if they fight you, they will show you their backs; then they will not be aided."}, {"ayah": 112, "translit": "Duribat 'alaihimuz zillatu aina maa suqifooo illaa bihablim minal laahi wa hablim minan naasi wa baaa'oo bighadabim minallaahi wa duribat 'alaihimul maskanah; zaalika bi-annahum kaanoo yakfuroona bi Aayaatil laahi wa yaqtuloonal Ambiyaaa'a bighairi haqq; zaalika bimaa 'asaw wa kaanoo ya'tadoon", "translation": "They have been put under humiliation [by Allah] wherever they are overtaken, except for a covenant from Allah and a rope from the Muslims. And they have drawn upon themselves anger from Allah and have been put under destitution. That is because they disbelieved in the verses of Allah and killed the prophets without right. That is because they disobeyed and [habitually] transgressed."}, {"ayah": 113, "translit": "Laisoo sawaaa'a; min Ahlil Kitaabi ummatun qaaa'imatuny yatloona Aayaatil laahi aanaaa'al laili wa hum yasjudoon", "translation": "They are not [all] the same; among the People of the Scripture is a community standing [in obedience], reciting the verses of Allah during periods of the night and prostrating [in prayer]."}, {"ayah": 114, "translit": "Yu'minoona billaahi wal Yawmil Aakhiri wa yaa muroona bilma'roofi wa yanhawna 'anil munkari wa yusaari'oona fil khairaati wa ulaa'ika minas saaliheen", "translation": "They believe in Allah and the Last Day, and they enjoin what is right and forbid what is wrong and hasten to good deeds. And those are among the righteous."}, {"ayah": 115, "translit": "Wa maa yaf'aloo min khairin falai yukfarooh; wallaahu 'aleemun bilmuttaqeen", "translation": "And whatever good they do - never will it be removed from them. And Allah is Knowing of the righteous."}, {"ayah": 116, "translit": "Innal lazeena kafaroo lan tughniya 'anhum amwaalum wa laaa awlaaduhum minal laahi shai anw wa ulaaa'ika Ashaabun Naar; hum feehaa khaalidoon", "translation": "Indeed, those who disbelieve - never will their wealth or their children avail them against Allah at all, and those are the companions of the Fire; they will abide therein eternally."}, {"ayah": 117, "translit": "Masalu maa yunfiqoona fee haazihil hayaatid dunyaa kamasali reehin feehaa sirrun as aabat harsa qawmin zalamooo anfusahum fa ahlakath; wa maa zalamahumul laahu wa laakin anfusahum yazlimoon", "translation": "The example of what they spend in this worldly life is like that of a wind containing frost which strikes the harvest of a people who have wronged themselves and destroys it. And Allah has not wronged them, but they wrong themselves."}, {"ayah": 118, "translit": "Yaaa ayyuhal lazeena aamanoo laa tattakhizoo bitaanatam min doonikum laa yaaloonakum khabaalanw waddoo maa 'anittum qad badatil baghdaaa'u min afwaahihim; wa maa tukhfee sudooruhum akbar; qad baiyannaa lakumul Aayaati in kuntum ta'qiloon", "translation": "O you who have believed, do not take as intimates those other than yourselves, for they will not spare you [any] ruin. They wish you would have hardship. Hatred has already appeared from their mouths, and what their breasts conceal is greater. We have certainly made clear to you the signs, if you will use reason."}, {"ayah": 119, "translit": "Haaa antum ulaaa'i tuhibboonahum wa laa yuhibboonakum wa tu'minoona bil kitaabi kullihee wa izaa laqookum qaalooo aamannaa wa izaa khalaw 'addoo 'alaikumul anaamila minal ghaiz; qul mootoo bighai zikum; innal laaha 'aleemum bizaatis sudoor", "translation": "Here you are loving them but they are not loving you, while you believe in the Scripture - all of it. And when they meet you, they say, \"We believe.\" But when they are alone, they bite their fingertips at you in rage. Say, \"Die in your rage. Indeed, Allah is Knowing of that within the breasts.\""}, {"ayah": 120, "translit": "In tamsaskum hasanatun tasu'hum wa in tusibkum saiyi'atuny yafrahoo bihaa wa in tasbiroo wa tattaqoo laa yad urrukum kaiduhum shai'aa; innal laaha bimaa ya'maloona muheet", "translation": "If good touches you, it distresses them; but if harm strikes you, they rejoice at it. And if you are patient and fear Allah, their plot will not harm you at all. Indeed, Allah is encompassing of what they do."}, {"ayah": 121, "translit": "Wa iz ghadawta min ahlika tubawwi'ul mu'mineena maqaa'ida lilqitaal; wallaahu samee'un 'aleem", "translation": "And [remember] when you, [O Muhammad], left your family in the morning to post the believers at their stations for the battle [of Uhud] - and Allah is Hearing and Knowing -"}, {"ayah": 122, "translit": "Iz hammat taaa'ifataani minkum an tafshalaa wallaahu waliyyuhumaa; wa 'alal laahi falyatawakkalil mu'minoon", "translation": "When two parties among you were about to lose courage, but Allah was their ally; and upon Allah the believers should rely."}, {"ayah": 123, "translit": "Wa laqad nasarakumul laahu bi-Badrinw wa antum azillatun fattaqul laaha la'allakum tashkuroon", "translation": "And already had Allah given you victory at [the battle of] Badr while you were few in number. Then fear Allah; perhaps you will be grateful."}, {"ayah": 124, "translit": "Iz taqoolu lilmu'mineena alai yakfiyakum ai-yumiddakum Rabbukum bisalaasati aalaafim minal malaaa'ikati munzaleen", "translation": "[Remember] when you said to the believers, \"Is it not sufficient for you that your Lord should reinforce you with three thousand angels sent down?"}, {"ayah": 125, "translit": "Balaaa; in tasbiroo wa tattaqoo wa yaatookum min fawrihim haazaa yumdidkum Rabbukum bikhamsati aalaafim minal malaaa'ikati musawwaimeen", "translation": "Yes, if you remain patient and conscious of Allah and the enemy come upon you [attacking] in rage, your Lord will reinforce you with five thousand angels having marks [of distinction]"}, {"ayah": 126, "translit": "Wa maa ja'alahul laahu illaa bushraa lakum wa litatma'inna quloobukum bih' wa man-nasru illaa min 'indilllaahil 'Azeezil Hakeem", "translation": "And Allah made it not except as [a sign of] good tidings for you and to reassure your hearts thereby. And victory is not except from Allah, the Exalted in Might, the Wise -"}, {"ayah": 127, "translit": "Laiyaqta'a tarafam minal lazeena kafarooo aw yakbitahum fayanqaliboo khaaa'ibeen", "translation": "That He might cut down a section of the disbelievers or suppress them so that they turn back disappointed."}, {"ayah": 128, "translit": "Laisa laka minal amrishai'un aw yatooba 'alaihim aw yu'az zi bahum fa innahum zaalimoon", "translation": "Not for you, [O Muhammad, but for Allah], is the decision whether He should [cut them down] or forgive them or punish them, for indeed, they are wrongdoers."}, {"ayah": 129, "translit": "Wa lilaahi maa fissamaawaati wa maa fil-ard; yaghfiru limai-yashaaa'u wa yu'azzibu mai-yashaaa'; wallaahu Ghafoorur Raheem", "translation": "And to Allah belongs whatever is in the heavens and whatever is on the earth. He forgives whom He wills and punishes whom He wills. And Allah is Forgiving and Merciful."}, {"ayah": 130, "translit": "Yaaa ayyuhal lazeena aamanoo la taakuhur ribaaa ad'aafam mudaa'afatanw wattaqul laaha la'allakum tuflihoon", "translation": "O you who have believed, do not consume usury, doubled and multiplied, but fear Allah that you may be successful."}, {"ayah": 131, "translit": "Wattaqun Naaral lateee u'iddat lilkaafireen", "translation": "And fear the Fire, which has been prepared for the disbelievers."}, {"ayah": 132, "translit": "Wa atee'ul laaha war Rasoola la'allakum turhamoon", "translation": "And obey Allah and the Messenger that you may obtain mercy."}, {"ayah": 133, "translit": "Wa saari'ooo ilaa maghfiratim mir Rabbikum wa Jannatin arduhassamaawaatu wal ardu u'iddat lilmuttaqeen", "translation": "And hasten to forgiveness from your Lord and a garden as wide as the heavens and earth, prepared for the righteous"}, {"ayah": 134, "translit": "Allazeena yunfiqoona fissarraaa'i waddarraaa'i wal kaazimeenal ghaiza wal aafeena 'anin-naas; wallaahu yuhibbul muhsineen", "translation": "Who spend [in the cause of Allah] during ease and hardship and who restrain anger and who pardon the people - and Allah loves the doers of good;"}, {"ayah": 135, "translit": "Wallazeena izaa fa'aloo faahishatan aw zalamooo anfusahum zakarul laaha fastaghfaroo lizunoobihim; wa mai yaghfiruz zunooba illal laahu wa lam yusirroo 'alaa maa fa'aloo wa hum ya'lamooo", "translation": "And those who, when they commit an immorality or wrong themselves [by transgression], remember Allah and seek forgiveness for their sins - and who can forgive sins except Allah? - and [who] do not persist in what they have done while they know."}, {"ayah": 136, "translit": "Ulaaa'ika jazaaa'uhum maghfiratum mir Rabbihim wa Jannaatun tajree min tahtihal anhaaru khaalideena feeha; wa ni'ma ajrul 'aamileen", "translation": "Those - their reward is forgiveness from their Lord and gardens beneath which rivers flow [in Paradise], wherein they will abide eternally; and excellent is the reward of the [righteous] workers."}, {"ayah": 137, "translit": "Qad khalat min qablikum sunanum faseeroo fil ardi fanzuroo kaifa kaana 'aaqiba tul mukazzibeen", "translation": "Similar situations [as yours] have passed on before you, so proceed throughout the earth and observe how was the end of those who denied."}, {"ayah": 138, "translit": "Haazaa bayaanul linnaasi wa hudanw wa maw'izatul lilmuttaqeen", "translation": "This [Qur'an] is a clear statement to [all] the people and a guidance and instruction for those conscious of Allah."}, {"ayah": 139, "translit": "Wa laa tahinoo wa laa tahzanoo wa antumul a'lawna in kuntum mu'mineen", "translation": "So do not weaken and do not grieve, and you will be superior if you are [true] believers."}, {"ayah": 140, "translit": "Iny-yamsaskum qarhum faqad massal qawma qarhum misluh; wa tilkal ayyaamu nudaawiluhaa bainan naasi wa liya'lamal laahul lazeena aamanoo wa yattakhiza minkum shuhadaaa'; wallaahu laa yuh ibbuz zaalimeen", "translation": "If a wound should touch you - there has already touched the [opposing] people a wound similar to it. And these days [of varying conditions] We alternate among the people so that Allah may make evident those who believe and [may] take to Himself from among you martyrs - and Allah does not like the wrongdoers -"}, {"ayah": 141, "translit": "Wa liyumahhisal laahul lazeena aamanoo wa yamhaqal kaafireen", "translation": "And that Allah may purify the believers [through trials] and destroy the disbelievers."}, {"ayah": 142, "translit": "Am hasibtum an tadkhulul Jannnata wa lammaa ya'lamil laahul lazeena jaahadoo minkum wa ya'lamas saabireen", "translation": "Or do you think that you will enter Paradise while Allah has not yet made evident those of you who fight in His cause and made evident those who are steadfast?"}, {"ayah": 143, "translit": "Wa laqad kuntum tamannnawnal mawta min qabli an talqawhu faqad ra aitumoohu wa antum tanzuroon", "translation": "And you had certainly wished for martyrdom before you encountered it, and you have [now] seen it [before you] while you were looking on."}, {"ayah": 144, "translit": "Wa maa Muhammadun illaa Rasoolun qad khalat min qablihir Rusul; afa'im maata aw qutilan qalabtum 'alaaa a'qaabikum; wa mai yanqalib 'alaa aqibihi falai yadurral laaha shai'aa; wa sayajzil laahush shaakireen", "translation": "Muhammad is not but a messenger. [Other] messengers have passed on before him. So if he was to die or be killed, would you turn back on your heels [to unbelief]? And he who turns back on his heels will never harm Allah at all; but Allah will reward the grateful."}, {"ayah": 145, "translit": "Wa maa kaana linafsin an tamoota illaa bi iznillaahi kitaabam mu'ajjalaa; wa mai yurid sawaabad dunyaa nu'tihee minhaa wa mai yurid sawaabal Aakhirati nu'tihee minhaa; wa sanajzish shaakireen", "translation": "And it is not [possible] for one to die except by permission of Allah at a decree determined. And whoever desires the reward of this world - We will give him thereof; and whoever desires the reward of the Hereafter - We will give him thereof. And we will reward the grateful."}, {"ayah": 146, "translit": "Wa ka aiyim min Nabiyyin qaatala ma'ahoo ribbiyyoona kaseerun famaa wahanoo limaaa Asaabahum fee sabeelil laahi wa maa da'ufoo wa mas takaanoo; wallaahu yuhibbus saabireen", "translation": "And how many a prophet [fought and] with him fought many religious scholars. But they never lost assurance due to what afflicted them in the cause of Allah, nor did they weaken or submit. And Allah loves the steadfast."}, {"ayah": 147, "translit": "Wa maa kaana qawlahum illaa an qaaloo Rabbanagh fir lanaa zunoobanaa wa israafanaa feee amirnaa wa sabbit aqdaamanaa wansurnaa 'alal qawmil kaafireen", "translation": "And their words were not but that they said, \"Our Lord, forgive us our sins and the excess [committed] in our affairs and plant firmly our feet and give us victory over the disbelieving people.\""}, {"ayah": 148, "translit": "Fa aataahumul laahu sawaabad dunyaa wa husna sawaabil Aakhirah; wallaahu yuhibbul muhsineen", "translation": "So Allah gave them the reward of this world and the good reward of the Hereafter. And Allah loves the doers of good."}, {"ayah": 149, "translit": "Yaaa 'aiyuhal lazeena aamanoo in tutee'ullazeena kafaroo yaruddookum 'alaaa a'qaabkum fatanqaliboo khaasireen", "translation": "O you who have believed, if you obey those who disbelieve, they will turn you back on your heels, and you will [then] become losers."}, {"ayah": 150, "translit": "Balil laahu mawlaakum wa Huwa khairun naasireen", "translation": "But Allah is your protector, and He is the best of helpers."}, {"ayah": 151, "translit": "Sanulqee fee quloobil lazeena kafarur ru'ba bimaaa ashrakoo billaahi maa lam yunazzil bihee sultaana wa maawaahumun Naar; wa bi'sa maswaz zaalimeen", "translation": "We will cast terror into the hearts of those who disbelieve for what they have associated with Allah of which He had not sent down [any] authority. And their refuge will be the Fire, and wretched is the residence of the wrongdoers."}, {"ayah": 152, "translit": "Wa laqad sadaqakumul laahu wa'dahooo iz tahussoo nahum bi iznihee hattaaa izaa fashiltim wa tanaaza'tum fil amri wa 'asaitum mim ba'di maaa araakum maa tuhibboon; minkum mai yureedud dunyaa wa minkum mai yureedul Aakhirah; summa sarafakum 'anhum sarafakum 'anhum liyabtaliyakum wa laqad 'afaa 'ankum; wallaahu zoo fadlin 'alal mu'mineen", "translation": "And Allah had certainly fulfilled His promise to you when you were killing the enemy by His permission until [the time] when you lost courage and fell to disputing about the order [given by the Prophet] and disobeyed after He had shown you that which you love. Among you are some who desire this world, and among you are some who desire the Hereafter. Then he turned you back from them [defeated] that He might test you. And He has already forgiven you, and Allah is the possessor of bounty for the believers."}, {"ayah": 153, "translit": "Iz tus'idoona wa laa talwoona 'alaaa ahadinw war Rasoolu yad'ookum feee ukhraakum fa asaabakum ghammam bighammil likailaa tahzanoo 'alaa maa faatakum wa laa maaa asaabakum; wallaahu khabeerum bimaa ta'maloon", "translation": "[Remember] when you [fled and] climbed [the mountain] without looking aside at anyone while the Messenger was calling you from behind. So Allah repaid you with distress upon distress so you would not grieve for that which had escaped you [of victory and spoils of war] or [for] that which had befallen you [of injury and death]. And Allah is [fully] Acquainted with what you do."}, {"ayah": 154, "translit": "Summa anzala 'alaikum mim ba'dil ghammi amanatan nu'aasai yaghshaa taaa' ifatam minkum wa taaa'ifatun qad ahammathum anfusuhum yazunnoona billaahi ghairal haqqi zannal jaahiliyyati yaqooloona hal lanaa minal amri min shai'; qul innal amra kullahoo lillaah; yukhfoona fee anfusihim maa laa yubdoona laka yaqooloona law kaana lanaa minal amri shai'ummaa qutilnaa haahunaa; qul law kuntum fee buyootikum labarazal lazeena kutiba 'alaihimul qatlu ilaa madaaji'ihim wa liyabtaliyal laahu maa fee sudoorikum wa liyumah hisa maa fee quloobikum; wallaahu 'aleemum bizaatis sudoor", "translation": "Then after distress, He sent down upon you security [in the form of] drowsiness, overcoming a faction of you, while another faction worried about themselves, thinking of Allah other than the truth - the thought of ignorance, saying, \"Is there anything for us [to have done] in this matter?\" Say, \"Indeed, the matter belongs completely to Allah.\" They conceal within themselves what they will not reveal to you. They say, \"If there was anything we could have done in the matter, some of us would not have been killed right here.\" Say, \"Even if you had been inside your houses, those decreed to be killed would have come out to their death beds.\" [It was] so that Allah might test what is in your breasts and purify what is in your hearts. And Allah is Knowing of that within the breasts."}, {"ayah": 155, "translit": "Innal lazeena tawallaw minkum yawmal taqal jam'aani innamas tazallahumush Shaitaanu biba'di maa kasaboo wa laqad 'afal laahu 'anhum; innnal laaha Ghafoorum Haleem", "translation": "Indeed, those of you who turned back on the day the two armies met, it was Satan who caused them to slip because of some [blame] they had earned. But Allah has already forgiven them. Indeed, Allah is Forgiving and Forbearing."}, {"ayah": 156, "translit": "Yaaa ayyuhul lazeena aamanoo laa takoonoo kallazeena kafaroo wa qaaloo li ikhwaanihim izaa daraboo fil ardi aw kaanoo ghuzzal law kaanoo 'indanaa maa maatoo wa maa qutiloo liyaj'alal laahu zaalika hasratan fee quloobihim; qallaahu yuhyee wa yumeet; wallaahu bimaa ta'maloona Baseer", "translation": "O you who have believed, do not be like those who disbelieved and said about their brothers when they traveled through the land or went out to fight, \"If they had been with us, they would not have died or have been killed,\" so Allah makes that [misconception] a regret within their hearts. And it is Allah who gives life and causes death, and Allah is Seeing of what you do."}, {"ayah": 157, "translit": "Wa la'in qutiltum fee sabeelil laahi aw muttum lamaghfiratum minal laahi wa rahmatun khairum mimmaa yajma'oon", "translation": "And if you are killed in the cause of Allah or die - then forgiveness from Allah and mercy are better than whatever they accumulate [in this world]."}, {"ayah": 158, "translit": "Wa la'im muttum 'aw qutiltumla ilal laahi tuhsharoon", "translation": "And whether you die or are killed, unto Allah you will be gathered."}, {"ayah": 159, "translit": "Fabimaa rahmatim minal laahi linta lahum wa law kunta fazzan ghaleezal qalbi lanfaddoo min hawlika fafu 'anhum wastaghfir lahum wa shaawirhum fil amri fa izaa 'azamta fatawakkal 'alal laah; innallaaha yuhibbul mutawak kileen", "translation": "So by mercy from Allah, [O Muhammad], you were lenient with them. And if you had been rude [in speech] and harsh in heart, they would have disbanded from about you. So pardon them and ask forgiveness for them and consult them in the matter. And when you have decided, then rely upon Allah. Indeed, Allah loves those who rely [upon Him]."}, {"ayah": 160, "translit": "Iny-yansurkumul laahu falaa ghaaliba lakum wa iny-yakhzulkum faman zal lazee yansurukum mim ba'dih; wa 'alal laahi falyatawakkalil mu'minoon", "translation": "If Allah should aid you, no one can overcome you; but if He should forsake you, who is there that can aid you after Him? And upon Allah let the believers rely."}, {"ayah": 161, "translit": "Wa maa kaana li Nabiyyin ai yaghull; wa mai yaghlul yaati bimaa ghalla Yawmal Qiyaamah; summa tuwaffaa kullu nafsim maa kasabat wa hum laa yuzlamoon", "translation": "It is not [attributable] to any prophet that he would act unfaithfully [in regard to war booty]. And whoever betrays, [taking unlawfully], will come with what he took on the Day of Resurrection. Then will every soul be [fully] compensated for what it earned, and they will not be wronged."}, {"ayah": 162, "translit": "Afamanit taba'a Ridwaanal laahi kamam baaa'a bisakhatim minal laahi wa maawaahu Jahannam; wa bi'sal maseer", "translation": "So is one who pursues the pleasure of Allah like one who brings upon himself the anger of Allah and whose refuge is Hell? And wretched is the destination."}, {"ayah": 163, "translit": "Hum darajaatun 'indal laah; wallaahu baseerum bimaa ya'maloon", "translation": "They are [varying] degrees in the sight of Allah, and Allah is Seeing of whatever they do."}, {"ayah": 164, "translit": "Laqad mannal laahu 'alal mu'mineena iz ba'asa feehim Rasoolam min anfusihim yatloo 'alaihim Aayaatihee wa yuzakkeehim wa yu'allimu humul Kitaaba wal Hikmata wa in kaanoo min qablu lafee dalaalim mubeen", "translation": "Certainly did Allah confer [great] favor upon the believers when He sent among them a Messenger from themselves, reciting to them His verses and purifying them and teaching them the Book and wisdom, although they had been before in manifest error."}, {"ayah": 165, "translit": "Awa lammaaa asaabatkum museebatun qad asabtum mislaihaa qultum annaa haazaa qul huwa min 'indi anfusikum; innal laaha 'alaa kulli shai'in Qadeer", "translation": "Why [is it that] when a [single] disaster struck you [on the day of Uhud], although you had struck [the enemy in the battle of Badr] with one twice as great, you said, \"From where is this?\" Say, \"It is from yourselves.\" Indeed, Allah is over all things competent."}, {"ayah": 166, "translit": "Wa maa asaabakum yawmal taqal jam'aani fabiiznil laahi wa liya'lamal mu'mineen", "translation": "And what struck you on the day the two armies met was by permission of Allah that He might make evident the [true] believers."}, {"ayah": 167, "translit": "Wa liya'lamal lazeena naafaqoo; wa qeela lahum ta'aalaw qaatiloo fee sabeelil laahi awid fa'oo qaaloo law na'lamu qitaalallat taba'naakum; hum lilkufri yawma'izin aqrabu minhum lil eemaan; yaqooloona bi afwaahihim maa laisa fee quloobihim; wallaahu a'lamu bimaa yaktumoon", "translation": "And that He might make evident those who are hypocrites. For it was said to them, \"Come, fight in the way of Allah or [at least] defend.\" They said, \"If we had known [there would be] fighting, we would have followed you.\" They were nearer to disbelief that day than to faith, saying with their mouths what was not in their hearts. And Allah is most Knowing of what they conceal -"}, {"ayah": 168, "translit": "Allazeena qaaloo liikhwaanihim wa qa'adoo law ataa'oonaa maa qutiloo; qul fadra'oo'an anfusikumul mawta in kuntum saadiqeen", "translation": "Those who said about their brothers while sitting [at home], \"If they had obeyed us, they would not have been killed.\" Say, \"Then prevent death from yourselves, if you should be truthful.\""}, {"ayah": 169, "translit": "Wa laa tahsabannal lazeena qutiloo fee sabeelillaahi amwaata; bal ahyaaa'un 'inda Rabbihim yurzaqoon", "translation": "And never think of those who have been killed in the cause of Allah as dead. Rather, they are alive with their Lord, receiving provision,"}, {"ayah": 170, "translit": "Fariheena bimaaa aataa humul laahu min fadlihee wa yastabshiroona billazeena lam yalhaqoo bihim min khalfihim allaa khawfun 'alaihim wa laa hum yahzanoon", "translation": "Rejoicing in what Allah has bestowed upon them of His bounty, and they receive good tidings about those [to be martyred] after them who have not yet joined them - that there will be no fear concerning them, nor will they grieve."}, {"ayah": 171, "translit": "Yastabshiroona bini'matim minal laahi wa fad linw wa annal laaha laa yudee'u ajral mu'mineen", "translation": "They receive good tidings of favor from Allah and bounty and [of the fact] that Allah does not allow the reward of believers to be lost -"}, {"ayah": 172, "translit": "Allazeenas tajaaboo lil laahi war Rasooli mim ba'di maaa asaabahumulqarh; lillazeena ahsanoo minhum wattaqaw ajrun 'azeem", "translation": "Those [believers] who responded to Allah and the Messenger after injury had struck them. For those who did good among them and feared Allah is a great reward -"}, {"ayah": 173, "translit": "Allazeena qaala lahumun naasu innan naasa qad jama'oo lakum fakhshawhuin fazaadahum eemaannanwa wa qaaloo hasbunal laahu wa ni'malwakeel", "translation": "Those to whom hypocrites said, \"Indeed, the people have gathered against you, so fear them.\" But it [merely] increased them in faith, and they said, \"Sufficient for us is Allah, and [He is] the best Disposer of affairs.\""}, {"ayah": 174, "translit": "Fanqalaboo bini'matim minal laahi wa fadlil lam yamsashum sooo'unw wattaba'oo ridwaanal laah; wallaahu zoo fadlin 'azeem", "translation": "So they returned with favor from Allah and bounty, no harm having touched them. And they pursued the pleasure of Allah, and Allah is the possessor of great bounty."}, {"ayah": 175, "translit": "Innamaa zaalikumush Shaitaanu yukhawwifu awliyaaa'ahoo falaa takhaafoohum wa khaafooni in kuntum mu'mineen", "translation": "That is only Satan who frightens [you] of his supporters. So fear them not, but fear Me, if you are [indeed] believers."}, {"ayah": 176, "translit": "Wa laa yahzunkal lazeena yusaari'oona fil Kufr; innahum lai yadurrul laaha shai'aa; yureedul laahu allaa yaj'ala lahum hazzan fil Aakhirati wa lahum 'azaabun 'azeem", "translation": "And do not be grieved, [O Muhammad], by those who hasten into disbelief. Indeed, they will never harm Allah at all. Allah intends that He should give them no share in the Hereafter, and for them is a great punishment."}, {"ayah": 177, "translit": "Innal lazeenash tarawul kufra bil eemaani lai yadurrul laaha shai anw wa lahum 'azdaabun aleem", "translation": "Indeed, those who purchase disbelief [in exchange] for faith - never will they harm Allah at all, and for them is a painful punishment."}, {"ayah": 178, "translit": "Wa laa yahsabannal lazeena kafarooo annamaa numlee lahum khairulli anfusihim; innamaa numlee lahum liyazdaadooo ismaa wa lahum 'azaabum muheen", "translation": "And let not those who disbelieve ever think that [because] We extend their time [of enjoyment] it is better for them. We only extend it for them so that they may increase in sin, and for them is a humiliating punishment."}, {"ayah": 179, "translit": "Maa kaanal laahu liyazaral mu'mineena 'alaa maaa antum 'alaihi hattaa yameezal khabeesa minat taiyib; wa maa kaanal laahu liyutli'akum 'alal ghaibi wa laakinnal laaha yajtabee mir Rusulihii mai yashaaa'u fa aaminoo billaahi wa Rusulih; wa in tu 'minoo wa tattaqoo falakum ajrun 'azeem", "translation": "Allah would not leave the believers in that [state] you are in [presently] until He separates the evil from the good. Nor would Allah reveal to you the unseen. But [instead], Allah chooses of His messengers whom He wills, so believe in Allah and His messengers. And if you believe and fear Him, then for you is a great reward."}, {"ayah": 180, "translit": "Wa laa yahsabannal lazeena yabkhaloon bimaa aataahumul lahu min fadilhee huwa khairal lahum bal huwa sharrul lahum sayutaw waqoona maa bakhiloo bihee Yawmal Qiyaamah; wa lillaahi meeraasus samaawaati wal ard; wallaahu bimaa ta'maloona Khabeer", "translation": "And let not those who [greedily] withhold what Allah has given them of His bounty ever think that it is better for them. Rather, it is worse for them. Their necks will be encircled by what they withheld on the Day of Resurrection. And to Allah belongs the heritage of the heavens and the earth. And Allah, with what you do, is [fully] Acquainted."}, {"ayah": 181, "translit": "Laqad sami'al laahu qawlal lazeena qaalooo innal laaha faqeerunw wa nahnu aghniyaaa'; sanaktubu maa qaaloo wa qatlahumul Ambiyaa'a bighairi haqqinw wa naqoolu zooqoo 'azaaba Ihreeq", "translation": "Allah has certainly heard the statement of those [Jews] who said, \"Indeed, Allah is poor, while we are rich.\" We will record what they said and their killing of the prophets without right and will say, \"Taste the punishment of the Burning Fire."}, {"ayah": 182, "translit": "Zaalika bimaa qaddamat aideekum wa annal laaha laisa bizallaamil lil'abeed", "translation": "That is for what your hands have put forth and because Allah is not ever unjust to [His] servants.\""}, {"ayah": 183, "translit": "Allazeena qaalooo innal laaha 'ahida ilainaaa allaa nu'mina liRasoolin hatta yaa tiyanaa biqurbaanin taa kuluhun naar; qul qad jaaa'akum Rusulum min qablee bilbaiyinaati wa billazee qultum falima qataltumoohum in kuntum saadiqeen", "translation": "[They are] those who said, \"Indeed, Allah has taken our promise not to believe any messenger until he brings us an offering which fire [from heaven] will consume.\" Say, \"There have already come to you messengers before me with clear proofs and [even] that of which you speak. So why did you kill them, if you should be truthful?\""}, {"ayah": 184, "translit": "Fa in kaz zabooka faqad kuz ziba Rusulum min qablika jaaa'oo bilbaiyinaati waz Zuburi wal Kitaabil Muneer", "translation": "Then if they deny you, [O Muhammad] - so were messengers denied before you, who brought clear proofs and written ordinances and the enlightening Scripture."}, {"ayah": 185, "translit": "Kulu nafsin zaaa'iqatul mawt; wa innamaa tuwaffawna ujoorakum Yawmal Qiyaamati faman zuhziha 'anin Naari waudkhilal Jannata faqad faaz; wa mal hayaatud dunyaaa illaa mataa'ul ghuroor", "translation": "Every soul will taste death, and you will only be given your [full] compensation on the Day of Resurrection. So he who is drawn away from the Fire and admitted to Paradise has attained [his desire]. And what is the life of this world except the enjoyment of delusion."}, {"ayah": 186, "translit": "Latublawunna feee amwaalikum wa anfusikum wa latasma'unna minal lazeena ootul Kitaaba min qablikum wa minal lazeena ashrakooo azan kaseeraa; wa in tasbiroo wa tattaqoo fa inna zaalika min 'azmil umoor", "translation": "You will surely be tested in your possessions and in yourselves. And you will surely hear from those who were given the Scripture before you and from those who associate others with Allah much abuse. But if you are patient and fear Allah - indeed, that is of the matters [worthy] of determination."}, {"ayah": 187, "translit": "Wa iz akhazal laahu meesaaqal lazeena ootul Kitaaba latubaiyinunnahoo linnaasi wa laa taktumoona hoo fanabazoohu waraaa'a zuhoorihim washtaraw bihee samanan qaleelan fabi'sa maa yashtaroon", "translation": "And [mention, O Muhammad], when Allah took a covenant from those who were given the Scripture, [saying], \"You must make it clear to the people and not conceal it.\" But they threw it away behind their backs and exchanged it for a small price. And wretched is that which they purchased."}, {"ayah": 188, "translit": "Laa tahsabannal lazeena yafrahoona bimaaa ataw wa yuhibbona ai yuhmadoo bimaa lam yaf'aloo falaa tahsabunnahum bimafaazatim minal 'azaabi wa lahum 'azaabun aleem", "translation": "And never think that those who rejoice in what they have perpetrated and like to be praised for what they did not do - never think them [to be] in safety from the punishment, and for them is a painful punishment."}, {"ayah": 189, "translit": "Wa lillaahi mulkus samaawaati wal ard; wallaahu 'alaa kulli shai'in Qadeer", "translation": "And to Allah belongs the dominion of the heavens and the earth, and Allah is over all things competent."}, {"ayah": 190, "translit": "Inna fee khalqis samaawati wal ardi wakhtilaafil laili wannahaari la Aayaatil liulil albaab", "translation": "Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding."}, {"ayah": 191, "translit": "Allazeena yazkuroonal laaha qiyaamaiw-wa qu'oodanw-wa 'alaa juno obihim wa yatafakkaroona fee khalqis samaawaati wal ardi Rabbanaa maa khalaqta haaza baatilan Subhaanak faqinaa 'azaaban Naar", "translation": "Who remember Allah while standing or sitting or [lying] on their sides and give thought to the creation of the heavens and the earth, [saying], \"Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire."}, {"ayah": 192, "translit": "Rabbanaaa innaka man tudkhilin Naara faqad akhzai tahoo wa maa lizzaalimeena min ansaar", "translation": "Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers."}, {"ayah": 193, "translit": "Rabbanaaa innanaa sami'naa munaadiyai yunaadee lil eemaani an aaminoo bi Rabbikum fa aamannaa; Rabbanaa faghfir lanaa zunoobanaa wa kaffir 'annaa saiyi aatina wa tawaffanaa ma'al abraar", "translation": "Our Lord, indeed we have heard a caller calling to faith, [saying], 'Believe in your Lord,' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous."}, {"ayah": 194, "translit": "Rabbanaa wa aatinaa maa wa'attanaa 'alaa Rusulika wa laa tukhzinaa Yawmal Qiyaamah; innaka laa tukhliful mee'aad", "translation": "Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise.\""}, {"ayah": 195, "translit": "Fastajaaba lahum Rabbuhum annee laaa Udee'u 'amala 'aamilim minkum min zakarin aw unsaa ba'dukum mim ba'din fal lazeena haajaroo wa ukhrijoo min diyaarihim wa oozoo fee sabeelee wa qaataloo wa qutiloo la ukaffiranna 'anhum saiyi aatihim wa la udkhilanna hum Jannnatin tajree min tahtihal anhaaru sawaabam min 'indil laah; wallaahu 'indahoo husnus sawaab", "translation": "And their Lord responded to them, \"Never will I allow to be lost the work of [any] worker among you, whether male or female; you are of one another. So those who emigrated or were evicted from their homes or were harmed in My cause or fought or were killed - I will surely remove from them their misdeeds, and I will surely admit them to gardens beneath which rivers flow as reward from Allah, and Allah has with Him the best reward.\""}, {"ayah": 196, "translit": "Laa yaghurrannaka taqal lubul lazeena kafaroo fil bilaad", "translation": "Be not deceived by the [uninhibited] movement of the disbelievers throughout the land."}, {"ayah": 197, "translit": "Mataa'un qaleelun summa maawaahum Jahannam; wa bi'sal mihaad", "translation": "[It is but] a small enjoyment; then their [final] refuge is Hell, and wretched is the resting place."}, {"ayah": 198, "translit": "Laakinil lazeenat taqaw Rabbahum lahum Jannnaatun tajree min tahtihal anhaaru khaalideena feehaa nuzulammin 'indil laah; wa maa 'indal laahi khairul lil abraar", "translation": "But those who feared their Lord will have gardens beneath which rivers flow, abiding eternally therein, as accommodation from Allah. And that which is with Allah is best for the righteous."}, {"ayah": 199, "translit": "Wa inna min Ahlil Kitaabi lamai yu minu billaahi wa maaa unzila ilaikum wa maaa unzila ilaihim khaashi 'eena lillaahi laa yashtaroona bi Aayaatil laahi samanan qaleelaa; ulaaa'ika lahum ajruhum 'inda Rabbihim; innal laaha saree'ul hisaab", "translation": "And indeed, among the People of the Scripture are those who believe in Allah and what was revealed to you and what was revealed to them, [being] humbly submissive to Allah. They do not exchange the verses of Allah for a small price. Those will have their reward with their Lord. Indeed, Allah is swift in account."}, {"ayah": 200, "translit": "Yaaa aiyuhal lazeena aamanus biroo wa saabiroo wa raabitoo wattaqul laaha la'allakum tuflihoon", "translation": "O you who have believed, persevere and endure and remain stationed and fear Allah that you may be successful."}]}, {"num": 4, "name": "An-Nisa", "meaning": "The Women", "verses": [{"ayah": 1, "translit": "Yaaa aiyuhan naasut taqoo Rabbakumul lazee khalaqakum min nafsinw waahidatinw wa khalaqa minhaa zawjahaa wa bas sa minhumaa rijaalan kaseeranw wa nisaaa'aa; wattaqul laahallazee tasaaa 'aloona bihee wal arhaam; innal laaha kaana 'alaikum Raqeeba", "translation": "O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer."}, {"ayah": 2, "translit": "Wa aatul yataamaaa amwaalahum wa laa tatabad dalul khabeesa bittaiyibi wa laa taakulooo amwaalahum ilaaa amwaalikum; innahoo kaana hooban kabeeraa", "translation": "And give to the orphans their properties and do not substitute the defective [of your own] for the good [of theirs]. And do not consume their properties into your own. Indeed, that is ever a great sin."}, {"ayah": 3, "translit": "Wa in khiftum allaa tuqsitoo fil yataamaa fankihoo maa taaba lakum minan nisaaa'i masnaa wa sulaasa wa rubaa'a fa'in khiftum allaa ta'diloo fawaahidatan aw maa malakat aimaanukum; zaalika adnaaa allaa ta'ooloo", "translation": "And if you fear that you will not deal justly with the orphan girls, then marry those that please you of [other] women, two or three or four. But if you fear that you will not be just, then [marry only] one or those your right hand possesses. That is more suitable that you may not incline [to injustice]."}, {"ayah": 4, "translit": "Wa aatun nisaaa'a sadu qaatihinna nihlah; fa in tibna lakum 'an shai'im minhu nafsan fakuloohu hanee'am mareee'aa", "translation": "And give the women [upon marriage] their [bridal] gifts graciously. But if they give up willingly to you anything of it, then take it in satisfaction and ease."}, {"ayah": 5, "translit": "Wa laa tu'tus sufahaaa'a amwaalakumul latee ja'alal laahu lakum qiyaamanw-warzuqoohum feehaa waksoohum wa qooloo lahum qawlam ma'roofaa", "translation": "And do not give the weak-minded your property, which Allah has made a means of sustenance for you, but provide for them with it and clothe them and speak to them words of appropriate kindness."}, {"ayah": 6, "translit": "Wabtalul yataamaa hattaaa izaa balaghun nikaaha fa in aanastum minhum rushdan fad fa'ooo ilaihim amwaalahum wa laa taa kuloohaaa israafanw wa bidaaran ai yakbaroo; wa mai kaana ghaniyyan falyasta' fif wa mai kaana faqeeran falyaakul bilma'roof; fa izaa dafa'tum ilaihim amwaalahum fa'ashhidoo 'alaihim; wa kafaa billaahi Haseeba", "translation": "And test the orphans [in their abilities] until they reach marriageable age. Then if you perceive in them sound judgement, release their property to them. And do not consume it excessively and quickly, [anticipating] that they will grow up. And whoever, [when acting as guardian], is self-sufficient should refrain [from taking a fee]; and whoever is poor - let him take according to what is acceptable. Then when you release their property to them, bring witnesses upon them. And sufficient is Allah as Accountant."}, {"ayah": 7, "translit": "Lirrijaali naseebum mimmaa tarakal waalidaani wal aqraboona wa lin nisaaa'i naseebum mimmaa tarakal waalidaani wal aqraboona mimmaa qalla minhu aw kasur; naseebam mafroodaa", "translation": "For men is a share of what the parents and close relatives leave, and for women is a share of what the parents and close relatives leave, be it little or much - an obligatory share."}, {"ayah": 8, "translit": "Wa izaa hadaral qismata ulul qurbaa walyataamaa walmasaakeenu farzuqoohum minhu wa qooloo lahum qawlam ma'roofaa", "translation": "And when [other] relatives and orphans and the needy are present at the [time of] division, then provide for them [something] out of the estate and speak to them words of appropriate kindness."}, {"ayah": 9, "translit": "Walyakhshal lazeena law tarakoo min khalfihim zurriyyatan di'aafan khaafoo 'alaihim falyattaqul laaha walyaqooloo qawlan sadeedaa", "translation": "And let those [executors and guardians] fear [injustice] as if they [themselves] had left weak offspring behind and feared for them. So let them fear Allah and speak words of appropriate justice."}, {"ayah": 10, "translit": "Innal lazeena yaakuloona amwaalal yataamaa zulman innamaa yaakuloona fee butoonihim Naaranw-wa sayaslawna sa'eeraa", "translation": "Indeed, those who devour the property of orphans unjustly are only consuming into their bellies fire. And they will be burned in a Blaze."}, {"ayah": 11, "translit": "Yooseekumul laahu feee awlaadikum liz zakari mislu hazzil unsayayn; fa in kunna nisaaa'an fawqas nataini falahunna sulusaa maa taraka wa in kaanat waahidatan falahan nisf; wa li abawaihi likulli waahidim minhumas sudusu mimmma taraka in kaana lahoo walad; fa il lam yakul lahowaladunw wa warisahooo abawaahu fali ummihis sulus; fa in kaana lahoo ikhwatun fali ummihis sudus; mim ba'di wasiyyatiny yoosee bihaaa aw dayn; aabaaa'ukum wa abnaaa'ukum laa tadroona aiyuhum aqrabu lakum naf'aa; fareedatam minallaah; innal laaha kaana 'Aleeman Hakeemaa", "translation": "Allah instructs you concerning your children: for the male, what is equal to the share of two females. But if there are [only] daughters, two or more, for them is two thirds of one's estate. And if there is only one, for her is half. And for one's parents, to each one of them is a sixth of his estate if he left children. But if he had no children and the parents [alone] inherit from him, then for his mother is one third. And if he had brothers [or sisters], for his mother is a sixth, after any bequest he [may have] made or debt. Your parents or your children - you know not which of them are nearest to you in benefit. [These shares are] an obligation [imposed] by Allah. Indeed, Allah is ever Knowing and Wise."}, {"ayah": 12, "translit": "Wa lakum nisfu maa taraka azwaajukum il lam yakul lahunna walad; fa in kaana lahunna waladun falakumur rub'u mimmaa tarakna mim ba'di wasiyyatiny yooseena bihaaa aw dayn; wa lahunnar rubu'u mimmaa tarakum il lam yakul lakum walad; fa in kaana lakum waladun falahunnas sumunu mimmaa taraktum; mim ba'di wasiyyatin toosoona bihaaa aw dayn; wa in kaana rajuluny yoorasu kalaalatan awim ra atunw wa lahooo akhun aw ukhtun falikulli waahidim minhumas sudus; fa in kaanooo aksara min zaalika fahum shurakaaa'u fissulusi mim ba'di wasiyyatiny yoosaa bihaaa aw dainin ghaira mudaaarr; wasiyyatam minal laah; wallaahu 'Aleemun Haleem", "translation": "And for you is half of what your wives leave if they have no child. But if they have a child, for you is one fourth of what they leave, after any bequest they [may have] made or debt. And for the wives is one fourth if you leave no child. But if you leave a child, then for them is an eighth of what you leave, after any bequest you [may have] made or debt. And if a man or woman leaves neither ascendants nor descendants but has a brother or a sister, then for each one of them is a sixth. But if they are more than two, they share a third, after any bequest which was made or debt, as long as there is no detriment [caused]. [This is] an ordinance from Allah, and Allah is Knowing and Forbearing."}, {"ayah": 13, "translit": "Tilka hudoodul laah; wa mai yuti'il laaha wa Rasoolahoo yudkhilhu Jannaatin tajree min tahtihal anhaaru khaalideena feehaa; wa zaalikal fawzul 'azeem", "translation": "These are the limits [set by] Allah, and whoever obeys Allah and His Messenger will be admitted by Him to gardens [in Paradise] under which rivers flow, abiding eternally therein; and that is the great attainment."}, {"ayah": 14, "translit": "Wa mai ya'sil laaha wa Rasoolahoo wa yata'adda hudoodahoo yudkhilhu Naaran khaalidan feehaa wa lahoo 'azaabum muheen", "translation": "And whoever disobeys Allah and His Messenger and transgresses His limits - He will put him into the Fire to abide eternally therein, and he will have a humiliating punishment."}, {"ayah": 15, "translit": "Wallaatee yaateenal faahishata min nisaaa'ikum fastashhidoo 'alaihinna arba'atam minkum fa in shahidoo fa amsikoohunna fil buyooti hatta yatawaffaa hunnal mawtu aw yaj'alal laahu lahunna sabeelaa", "translation": "Those who commit unlawful sexual intercourse of your women - bring against them four [witnesses] from among you. And if they testify, confine the guilty women to houses until death takes them or Allah ordains for them [another] way."}, {"ayah": 16, "translit": "Wallazaani yaatiyaanihaa minkum fa aazoohumaa fa in taabaa wa aslahaa fa a'ridoo 'anhumaaa; innal laaha kaana Tawwaabar Raheema", "translation": "And the two who commit it among you, dishonor them both. But if they repent and correct themselves, leave them alone. Indeed, Allah is ever Accepting of repentance and Merciful."}, {"ayah": 17, "translit": "Innamat tawbatu 'alallaahi lillazeena ya'maloonas sooo'a bijahaalatin summa yatooboona min qareebin faulaaika yatoobul laahu 'alaihim; wa kaanal laahu 'Aleeman Hakeemaa", "translation": "The repentance accepted by Allah is only for those who do wrong in ignorance [or carelessness] and then repent soon after. It is those to whom Allah will turn in forgiveness, and Allah is ever Knowing and Wise."}, {"ayah": 18, "translit": "Wa laisatit tawbatu lillazeena ya'maloonas saiyiaati hattaaa izaa hadara ahadahumul mawtu qaala innee tubtul 'aana wa lallazeena yamootoona wa hum kuffaar; ulaaa'ika a'tadnaa lahum 'azaaban aleemaa", "translation": "But repentance is not [accepted] of those who [continue to] do evil deeds up until, when death comes to one of them, he says, \"Indeed, I have repented now,\" or of those who die while they are disbelievers. For them We have prepared a painful punishment."}, {"ayah": 19, "translit": "Yaaa aiyuhal lazeena aamanoo laa yahillu lakum an tarisun nisaaa'a karhan wa laa ta'duloohunna litazhaboo biba'di maaa aataitumoohunna illaaa ai yaateena bifaahishatim mubaiyinah; wa 'aashiroo hunna bilma'roof; fa in karihtumoohunna fa'asaaa an takrahoo shai'anw wa yaj'alal laahu feehi khairan kaseeraa", "translation": "O you who have believed, it is not lawful for you to inherit women by compulsion. And do not make difficulties for them in order to take [back] part of what you gave them unless they commit a clear immorality. And live with them in kindness. For if you dislike them - perhaps you dislike a thing and Allah makes therein much good."}, {"ayah": 20, "translit": "Wa in arattumustib daala zawjim makaana zawjin wa aataitum ihdaahunna qintaaran falaa taakhuzoo minhu shai'aa; ataakhuzoonahoo buhtaannanw wa ismam mubeenaa", "translation": "But if you want to replace one wife with another and you have given one of them a great amount [in gifts], do not take [back] from it anything. Would you take it in injustice and manifest sin?"}, {"ayah": 21, "translit": "Wa kaifa taakhuzoonahoo wa qad afdaa ba'dukum ilaa ba'dinw wa akhazna minkum meesaaqan ghaleezaa", "translation": "And how could you take it while you have gone in unto each other and they have taken from you a solemn covenant?"}, {"ayah": 22, "translit": "Wa laa tankihoo maa nakaha aabaaa'ukum minan nisaaa'i illaa maa qad salaf; inahoo kaana faahishatanw wa maqtanw wa saaa'a sabeelaa", "translation": "And do not marry those [women] whom your fathers married, except what has already occurred. Indeed, it was an immorality and hateful [to Allah] and was evil as a way."}, {"ayah": 23, "translit": "Hurrimat 'alaikum umma haatukum wa bannaatukum wa akhawaatukum wa 'ammaatukum wa khaalaatukum wa banaatul akhi wa banaatul ukhti wa ummahaatu kumul laateee arda' nakum wa akhawaatukum minarradaa'ati wa ummahaatu nisaaa'ikum wa rabaaa'i bukumul laatee fee hujoorikum min nisaaa'ikumul laatee dakhaltum bihinna Fa il lam takoonoo dakhaltum bihina falaa junaaha 'alaikum wa halaaa'ilu abnaaa'ikumul lazeena min aslaabikum wa an tajma'oo bainal ukhtaini illaa maa qad salaf; innallaaha kaana Ghafoorar Raheema", "translation": "Prohibited to you [for marriage] are your mothers, your daughters, your sisters, your father's sisters, your mother's sisters, your brother's daughters, your sister's daughters, your [milk] mothers who nursed you, your sisters through nursing, your wives' mothers, and your step-daughters under your guardianship [born] of your wives unto whom you have gone in. But if you have not gone in unto them, there is no sin upon you. And [also prohibited are] the wives of your sons who are from your [own] loins, and that you take [in marriage] two sisters simultaneously, except for what has already occurred. Indeed, Allah is ever Forgiving and Merciful."}, {"ayah": 24, "translit": "Walmuhsanaatu minan nisaaa'i illaa maa malakat aimaanukum kitaabal laahi 'alaikum; wa uhilla lakum maa waraaa'a zaalikum an tabtaghoo bi amwaali kum muhsineena ghaira musaa fiheen; famastamta'tum bihee minhunna fa aatoohunna ujoorahunna fareedah; wa laa junaaha 'alaikum feemaa taraadaitum bihee mim ba'dil fareedah; innal laaha kaana 'Aleeman Hakeemaa", "translation": "And [also prohibited to you are all] married women except those your right hands possess. [This is] the decree of Allah upon you. And lawful to you are [all others] beyond these, [provided] that you seek them [in marriage] with [gifts from] your property, desiring chastity, not unlawful sexual intercourse. So for whatever you enjoy [of marriage] from them, give them their due compensation as an obligation. And there is no blame upon you for what you mutually agree to beyond the obligation. Indeed, Allah is ever Knowing and Wise."}, {"ayah": 25, "translit": "Wa mal lam yastati' minkum tawlan ai yankihal muhsanaatil mu'minaati famimmaa malakat aimaanukum min fatayaatikumul mu'minaat; wallaahu a'lamu bi eemaanikum; ba'dukum mim ba'd; fankihoohunna bi izni ahlihinna wa aatoohunna ujoorahunna bilma'roofi muhsanaatin ghaira musaa fihaatinw wa laa muttakhizaati akhdaan; fa izaaa uhsinna fa in ataina bifaahi shatin fa'alaihinnna nisfu maa 'alal muhsanaati minal 'azaab; zaalika liman khashiyal 'anata minkum; wa an tasbiroo khairul lakum; wallaahu Ghafoorur Raheem", "translation": "And whoever among you cannot [find] the means to marry free, believing women, then [he may marry] from those whom your right hands possess of believing slave girls. And Allah is most knowing about your faith. You [believers] are of one another. So marry them with the permission of their people and give them their due compensation according to what is acceptable. [They should be] chaste, neither [of] those who commit unlawful intercourse randomly nor those who take [secret] lovers. But once they are sheltered in marriage, if they should commit adultery, then for them is half the punishment for free [unmarried] women. This [allowance] is for him among you who fears sin, but to be patient is better for you. And Allah is Forgiving and Merciful."}, {"ayah": 26, "translit": "Yureedul laahu liyubai yina lakum wa yahdiyakum sunanal lazeena min qablikum wa yatooba 'alaikum; wallaahu 'Aleemun Hakeem", "translation": "Allah wants to make clear to you [the lawful from the unlawful] and guide you to the [good] practices of those before you and to accept your repentance. And Allah is Knowing and Wise."}, {"ayah": 27, "translit": "Wallaahu yureedu ai yatooba 'alaikum wa yureedul lazeena yattabi 'oonash shahawaati an tameeloo mailan 'azeemaa", "translation": "Allah wants to accept your repentance, but those who follow [their] passions want you to digress [into] a great deviation."}, {"ayah": 28, "translit": "Yureedul laahu ai yukhaffifa 'ankum; wa khuliqal insaanu da'eefaa", "translation": "And Allah wants to lighten for you [your difficulties]; and mankind was created weak."}, {"ayah": 29, "translit": "Yaaa aiyuhal lazeena aamanoo laa taakulooo amwaalakum bainakum bilbaatili 'illaaa an takoona tijaaratan 'an taraadim minkum; wa laa taqtulooo anfusakum; innal laaha kaana bikum Raheemaa", "translation": "O you who have believed, do not consume one another's wealth unjustly but only [in lawful] business by mutual consent. And do not kill yourselves [or one another]. Indeed, Allah is to you ever Merciful."}, {"ayah": 30, "translit": "Wa mai yaf'al zaalika 'udwaananw wa zulman fasawfa nusleehi Naaraa; wa kaana zaalika 'alal laahi yaseeraa", "translation": "And whoever does that in aggression and injustice - then We will drive him into a Fire. And that, for Allah, is [always] easy."}, {"ayah": 31, "translit": "In tajtaniboo kabaaa'ira maa tunhawna 'anhu nukaffir 'ankum saiyiaatikum wa nudkhilkum mudkhalan kareemaa", "translation": "If you avoid the major sins which you are forbidden, We will remove from you your lesser sins and admit you to a noble entrance [into Paradise]."}, {"ayah": 32, "translit": "Wa laa tatamannaw maa faddalal laahu bihee ba'dakum 'alaa ba'd; lirrijaali naseebum mimak tasaboo wa linnisaaa'i naseebum mimmak tasabna; was'alullaaha min fadlih; innal laaha kaana bikulli shai'in 'Aleemaa", "translation": "And do not wish for that by which Allah has made some of you exceed others. For men is a share of what they have earned, and for women is a share of what they have earned. And ask Allah of his bounty. Indeed Allah is ever, of all things, Knowing."}, {"ayah": 33, "translit": "Wa likullin ja'alnaa ma waaliya mimmaa tarakal waalidaani wal aqraboon; wallazeena 'aqadat aimaanukum fa aatoohum naseebahum; innal laaha kaana 'alaa kulli shai'in Shaheedaa", "translation": "And for all, We have made heirs to what is left by parents and relatives. And to those whom your oaths have bound [to you] - give them their share. Indeed Allah is ever, over all things, a Witness."}, {"ayah": 34, "translit": "Arrijaalu qawwaamoona 'alan nisaaa'i bimaa fad dalallaahu ba'dahum 'alaa ba'dinw wa bimaaa anfoqoo min amwaalihim; fassaalihaatu qaanitaatun haafizaatul lil ghaibi bimaa hafizal laah; wallaatee takhaafoona nushoo zahunna fa 'izoohunna wahjuroohunna fil madaaji'i wadriboohunna fa in ata'nakum falaa tabghoo 'alaihinna sabeelaa; innallaaha kaana 'Aliyyan Kabeeraa", "translation": "Men are in charge of women by [right of] what Allah has given one over the other and what they spend [for maintenance] from their wealth. So righteous women are devoutly obedient, guarding in [the husband's] absence what Allah would have them guard. But those [wives] from whom you fear arrogance - [first] advise them; [then if they persist], forsake them in bed; and [finally], strike them. But if they obey you [once more], seek no means against them. Indeed, Allah is ever Exalted and Grand."}, {"ayah": 35, "translit": "Wa in khiftum shiqaaqa baini himaa fab'asoo haka mam min ahlihee wa hakamam min ahlihaa; iny-yureedaaa islaah ai-yuwaffiqil laahu bainahumaa; innal laaha kaana 'Aleeman Khabeeraa", "translation": "And if you fear dissension between the two, send an arbitrator from his people and an arbitrator from her people. If they both desire reconciliation, Allah will cause it between them. Indeed, Allah is ever Knowing and Acquainted [with all things]."}, {"ayah": 36, "translit": "Wa'budul laaha wa laa tushrikoo bihee shai'anw wa bilwaalidaini ihsaananw wa bizil qurbaa walyataamaa walmasaakeeni waljaari zilqurbaa waljaaril junubi wassaahibi biljambi wabnis sabeeli wa maa malakat aimaanukum; innal laaha laa yuhibbu man kaana mukhtaalan fakhooraa", "translation": "Worship Allah and associate nothing with Him, and to parents do good, and to relatives, orphans, the needy, the near neighbor, the neighbor farther away, the companion at your side, the traveler, and those whom your right hands possess. Indeed, Allah does not like those who are self-deluding and boastful."}, {"ayah": 37, "translit": "Allazeena yabkhaloona wa yaamuroonan naasa bilbukhli wa yaktumoona maaa aataahu mullaahu min fadlih; wa a'tadnaa lilkaafireena 'azaabam muheenaa", "translation": "Who are stingy and enjoin upon [other] people stinginess and conceal what Allah has given them of His bounty - and We have prepared for the disbelievers a humiliating punishment -"}, {"ayah": 38, "translit": "Wallazeena yunfiqoona amwaalahum ri'aaa'an naasi wa laa yu'minoona billaahi wa laa bil Yawmil Aakhir; wa mai yakunish shaitaanu lahoo qareenan fasaaa'a qareenaa", "translation": "And [also] those who spend of their wealth to be seen by the people and believe not in Allah nor in the Last Day. And he to whom Satan is a companion - then evil is he as a companion."}, {"ayah": 39, "translit": "Wa maazaa 'alaihim law aamanoo billaahi wal Yawmil Aakhiri wa anfaqoo mimmaa razaqahumul laah; wa kaanallaahu bihim Aaleemaa", "translation": "And what [harm would come] upon them if they believed in Allah and the Last Day and spent out of what Allah provided for them? And Allah is ever, about them, Knowing."}, {"ayah": 40, "translit": "Innal laaha laa yazlimu misqaala zarratinw wa in taku hasanatany yudaa'ifhaa wa yu'ti mil ladunhu ajran 'azeemaa", "translation": "Indeed, Allah does not do injustice, [even] as much as an atom's weight; while if there is a good deed, He multiplies it and gives from Himself a great reward."}, {"ayah": 41, "translit": "Fakaifa izaa ji'naa min kulli ummatim bishaheedinw wa ji'naabika 'alaa haaa'ulaaa 'i Shaheedan", "translation": "So how [will it be] when We bring from every nation a witness and we bring you, [O Muhammad] against these [people] as a witness?"}, {"ayah": 42, "translit": "Yawma'iziny yawad dullazeena kafaroo wa'asawur Rasoola law tusawwaa bihimul ardu wa laa yaktumoonal laaha hadeesaa", "translation": "That Day, those who disbelieved and disobeyed the Messenger will wish they could be covered by the earth. And they will not conceal from Allah a [single] statement."}, {"ayah": 43, "translit": "yaaa aiyuhal lazeena aamanoo laa taqrabus Salaata wa antum sukaaraa hatta ta'lamoo ma taqooloona wa la junuban illaa 'aabiree sabeelin hatta taghtasiloo; wa in kuntum mardaaa aw 'alaa safarin aw jaaa'a ahadum minkum minal ghaaa'iti aw laamastumun nisaaa'a falam tajidoo maaa'an fatayam mamoo sa'eedan taiyiban famsahoo biwujoohikum wa aideekum; innal laaha kaana 'Afuwwan Ghafooraa", "translation": "O you who have believed, do not approach prayer while you are intoxicated until you know what you are saying or in a state of janabah, except those passing through [a place of prayer], until you have washed [your whole body]. And if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and find no water, then seek clean earth and wipe over your faces and your hands [with it]. Indeed, Allah is ever Pardoning and Forgiving."}, {"ayah": 44, "translit": "Alam tara ilal lazeena ootoo naseebam minal Kitaabi yashtaroonad dalaalata wa yureedoona an tadillus sabeel", "translation": "Have you not seen those who were given a portion of the Scripture, purchasing error [in exchange for it] and wishing you would lose the way?"}, {"ayah": 45, "translit": "Wallaahu a'lamu bi a'daaa'i-kum; wa kafaa billaahi waliyyanw wa kafaa billaahi naseera", "translation": "And Allah is most knowing of your enemies; and sufficient is Allah as an ally, and sufficient is Allah as a helper."}, {"ayah": 46, "translit": "Minal lazeena haadoo yuharrifoonal Kalima 'am mawaadi'ihee wa yaqooloona sami'naa wa 'asainaa wasma' ghaira musma'inw wa raa'inaa laiyam bi alsinatihim wa ta'nan fiddeen; wa law annahum qaaloo sami'naa wa ata'naa wasma' wanzurnaa lakaana khairal lahum wa aqwama wa laakil la ''anahumul laahu bikufrihim falaa yu'minoona illaa qaleela", "translation": "Among the Jews are those who distort words from their [proper] usages and say, \"We hear and disobey\" and \"Hear but be not heard\" and \"Ra'ina,\" twisting their tongues and defaming the religion. And if they had said [instead], \"We hear and obey\" and \"Wait for us [to understand],\" it would have been better for them and more suitable. But Allah has cursed them for their disbelief, so they believe not, except for a few."}, {"ayah": 47, "translit": "yaaa aiyuha lazeena ootu Kitaaba aaminoo bimaa nazzalnaa musadiqallimaa ma'akum min qabli an natmisa wujoohan fanaruddahaa 'alaaa adbaarihaaa aw nal'anahum kamaa la'annaaa Ashaabas Sabt; wa kaana amrul laahi maf'oolaa", "translation": "O you who were given the Scripture, believe in what We have sent down [to Muhammad], confirming that which is with you, before We obliterate faces and turn them toward their backs or curse them as We cursed the sabbath-breakers. And ever is the decree of Allah accomplished."}, {"ayah": 48, "translit": "Innal laaha laa yaghfiru ai yushraka bihee wa yaghfiru maa doona zaalika limai yashaaa'; wa mai yushrik billaahi faqadif taraaa isman 'azeemaa", "translation": "Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allah has certainly fabricated a tremendous sin."}, {"ayah": 49, "translit": "Alam tara ilal lazeena yuzakkoona anfusahum; balil laahu yuzakkee mai yashaaa'u wa laa yuzlamoona fateelaa", "translation": "Have you not seen those who claim themselves to be pure? Rather, Allah purifies whom He wills, and injustice is not done to them, [even] as much as a thread [inside a date seed]."}, {"ayah": 50, "translit": "Unzur kaifa yaftaroona 'alal laahil kazib, wakafaa biheee ismamm mubeenaa", "translation": "Look how they invent about Allah untruth, and sufficient is that as a manifest sin."}, {"ayah": 51, "translit": "Alam tara ilal lazeena 'ootoo naseebam minal kitaabi yu'minoona bil Jibti wat Taaghooti wa yaqooloona lillazeena kafaroo haaa ulaaa'i ahdaa minal lazeena aamanoo sabeelaa", "translation": "Have you not seen those who were given a portion of the Scripture, who believe in superstition and false objects of worship and say about the disbelievers, \"These are better guided than the believers as to the way\"?"}, {"ayah": 52, "translit": "Ulaaa'ikal lazeena la'ana humul laahu wa mai yal'anil laahu falan tajida lahoo naseeraa", "translation": "Those are the ones whom Allah has cursed; and he whom Allah curses - never will you find for him a helper."}, {"ayah": 53, "translit": "Am lahum naseebum minal mulki fa izal laa yu'toonan naasa naqeeraa", "translation": "Or have they a share of dominion? Then [if that were so], they would not give the people [even as much as] the speck on a date seed."}, {"ayah": 54, "translit": "Am yahsudoonan naasa 'alaa maaa aataahumul laahu min fadlihee faqad aatainaaa Aala Ibraaheemal Kitaaba wal Hikmata wa aatainaahum mulkan 'azeemaa", "translation": "Or do they envy people for what Allah has given them of His bounty? But we had already given the family of Abraham the Scripture and wisdom and conferred upon them a great kingdom."}, {"ayah": 55, "translit": "Faminhum man aamana bihee wa minhum man sadda 'anh; wa kafaa bi Jahannama sa'eeraa", "translation": "And some among them believed in it, and some among them were averse to it. And sufficient is Hell as a blaze."}, {"ayah": 56, "translit": "Innal lazeena kafaroo bi Aayaatinaa sawfa nusleehim Naaran kullamaa nadijat julooduhum baddalnaahum juloodan ghairahaa liyazooqul 'azaab; innallaaha kaana 'Azeezan Hakeemaa", "translation": "Indeed, those who disbelieve in Our verses - We will drive them into a Fire. Every time their skins are roasted through We will replace them with other skins so they may taste the punishment. Indeed, Allah is ever Exalted in Might and Wise."}, {"ayah": 57, "translit": "Wallazeena aamanoo wa 'amilus saalihaati sanud khiluum jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa, lahum feehaaa azwaajum mutahharatun wa nudkhiluhum zillan zaleelaa", "translation": "But those who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they abide forever. For them therein are purified spouses, and We will admit them to deepening shade."}, {"ayah": 58, "translit": "Innal laaha yaamurukum an tu'addul amaanaati ilaaa ahlihaa wa izaa hakamutum bainan naasi an tahkumoo bil'adl; innal laaha ni'immaa ya'izukum bih; innal laaha kaana Samee'am Baseeraa", "translation": "Indeed, Allah commands you to render trusts to whom they are due and when you judge between people to judge with justice. Excellent is that which Allah instructs you. Indeed, Allah is ever Hearing and Seeing."}, {"ayah": 59, "translit": "Yaaa aiyuhal lazeena aamanooo atee'ul laaha wa atee'ur Rasoola wa ulil amri minkum fa in tanaaza'tum fee shai'in faruddoohu ilal laahi war Rasooli in kuntum tu'minoona billaahi wal yawmil Aakhir; zaalika khairunw wa ahsanu taaweelaa", "translation": "O you who have believed, obey Allah and obey the Messenger and those in authority among you. And if you disagree over anything, refer it to Allah and the Messenger, if you should believe in Allah and the Last Day. That is the best [way] and best in result."}, {"ayah": 60, "translit": "Alam tara ilal lazeena yaz'umoona annahum aarmanoo bimaa unzilaa ilaika wa maaa unzila min qablika yureedoona ai yatahaakamooo ilat Taaghooti wa qad umirooo ai yakfuroo bih, wa yureedush Shaitaanu ai yudillahum dalaalam ba'eedaa", "translation": "Have you not seen those who claim to have believed in what was revealed to you, [O Muhammad], and what was revealed before you? They wish to refer legislation to Taghut, while they were commanded to reject it; and Satan wishes to lead them far astray."}, {"ayah": 61, "translit": "Wa izaa qeela lahum ta'aalaw ilaa maaa anzalallaahu wa ilar Rasooli ra aital munaafiqeena yasuddoona 'anka sudoodaa", "translation": "And when it is said to them, \"Come to what Allah has revealed and to the Messenger,\" you see the hypocrites turning away from you in aversion."}, {"ayah": 62, "translit": "Fakaifa izaaa asaabathum museebatum bimaa qaddamat aideehim summa jaaa'ooka yahlifoona billaahi in aradnaaa illaaa ihsaananw wa tawfeeqaa", "translation": "So how [will it be] when disaster strikes them because of what their hands have put forth and then they come to you swearing by Allah, \"We intended nothing but good conduct and accommodation.\""}, {"ayah": 63, "translit": "Ulaaa'ikal lazeena ya'la mullaahu maa fee quloobihim fa a'rid 'anhum wa 'izhum wa qul lahum feee anfusihim qawlam baleeghaa", "translation": "Those are the ones of whom Allah knows what is in their hearts, so turn away from them but admonish them and speak to them a far-reaching word."}, {"ayah": 64, "translit": "Wa maa arsalnaa mir Rasoolin illaa liyutaa'a bi iznil laah; wa law annahum 'iz zalamooo anfusahum jaaa'ooka fastaghfarul laaha wastaghfara lahumur Rasoolu la wajadul laaha Tawwaabar Raheemaa", "translation": "And We did not send any messenger except to be obeyed by permission of Allah. And if, when they wronged themselves, they had come to you, [O Muhammad], and asked forgiveness of Allah and the Messenger had asked forgiveness for them, they would have found Allah Accepting of repentance and Merciful."}, {"ayah": 65, "translit": "Falaa wa Rabbika laa yu'minoona hattaa yuhakkimooka fe emaa shajara bainahum summa laa yajidoo fee anfusihim harajam mimmaa qadaita wa yusal limoo tasleemaa", "translation": "But no, by your Lord, they will not [truly] believe until they make you, [O Muhammad], judge concerning that over which they dispute among themselves and then find within themselves no discomfort from what you have judged and submit in [full, willing] submission."}, {"ayah": 66, "translit": "Wa law annaa katabnaa 'alaihim aniq tulooo anfusakum awikh rujoo min diyaarikum maa fa'aloohu illaa qaleelum minhum wa law annahum fa'aloo maa yoo'azoona bihee lakaana khairal lahum wa ashadda tasbeetaa", "translation": "And if We had decreed upon them, \"Kill yourselves\" or \"Leave your homes,\" they would not have done it, except for a few of them. But if they had done what they were instructed, it would have been better for them and a firmer position [for them in faith]."}, {"ayah": 67, "translit": "Wa izal la aatainaahum mil ladunnaaa ajran 'azeemaa", "translation": "And then We would have given them from Us a great reward."}, {"ayah": 68, "translit": "Wa lahadainaahum Siraatam mustaqeemaa", "translation": "And We would have guided them to a straight path."}, {"ayah": 69, "translit": "Wa many-yuti'il laaha war Rasoola fa ulaaa'ika ma'al lazeena an'amal laahu 'alaihim minan nabiyyeena wassiddeeqeena washshuhadaaa'i wassaaliheen; wa hasuna ulaaa'ika rafeeqaa", "translation": "And whoever obeys Allah and the Messenger - those will be with the ones upon whom Allah has bestowed favor of the prophets, the steadfast affirmers of truth, the martyrs and the righteous. And excellent are those as companions."}, {"ayah": 70, "translit": "Zaalikal fadlu minal laah; wa kafaa billaahi 'Aleemaa", "translation": "That is the bounty from Allah, and sufficient is Allah as Knower."}, {"ayah": 71, "translit": "Yaaa aiyuhal lazeena aamanoo khuzoo hizrakum fanfiroo subaatin awin firoo jamee'aa", "translation": "O you who have believed, take your precaution and [either] go forth in companies or go forth all together."}, {"ayah": 72, "translit": "Wa inna minkum lamal la yubatti'anna fa in asaabatkum museebatun qaala qad an'amal laahu 'alaiya iz lam akum ma'ahum shaheeda", "translation": "And indeed, there is among you he who lingers behind; and if disaster strikes you, he says, \"Allah has favored me in that I was not present with them.\""}, {"ayah": 73, "translit": "Wa la'in asaabakum fadlum minal laahi la yaqoolanna ka al lam takum bainakum wa bainahoo mawaddatuny yaa laitanee kuntu ma'ahum fa afooza fawzan 'azeemaa", "translation": "But if bounty comes to you from Allah, he will surely say, as if there had never been between you and him any affection. \"Oh, I wish I had been with them so I could have attained a great attainment.\""}, {"ayah": 74, "translit": "Falyuqaatil fee sabeelil laahil lazeena yashroonal hayaatad dunyaa bil Aakhirah; wa many-uqaatil fee sabeelil laahi fa yuqtal aw yaghlib fasawfa nu'teehi ajran 'azeemaa", "translation": "So let those fight in the cause of Allah who sell the life of this world for the Hereafter. And he who fights in the cause of Allah and is killed or achieves victory - We will bestow upon him a great reward."}, {"ayah": 75, "translit": "Wa maa lakum laa tuqaatiloona fee sabeelil laahi walmustad'afeena minar rijaali wannisaaa'i walwildaanil lazeena yaqooloona Rabbanaaa akhrijnaa min haazihil qaryatiz zaalimi ahluhaa waj'al lanaa mil ladunka waliyanw waj'al lanaa mil ladunka naseeraa", "translation": "And what is [the matter] with you that you fight not in the cause of Allah and [for] the oppressed among men, women, and children who say, \"Our Lord, take us out of this city of oppressive people and appoint for us from Yourself a protector and appoint for us from Yourself a helper?\""}, {"ayah": 76, "translit": "Allazeena aamanoo yuqaatiloona fee sabeelil laahi wallazeena kafaroo yuqaatiloona fee sabeelit Taaghoot faqaatiloo awliyaaa'ash Shaitaan; inna kaidash Shairaani kaana da'eefa", "translation": "Those who believe fight in the cause of Allah, and those who disbelieve fight in the cause of Taghut. So fight against the allies of Satan. Indeed, the plot of Satan has ever been weak."}, {"ayah": 77, "translit": "Alam tara ilal lazeena qeela lahum kuffooo aidiyakum wa aqeemus Salaata w aaatuz Zakaata falammaa kutiba 'alaihimul qitaalu izaa fareequm minhum yakhshawnnan naasa kakhashyatil laahi aw ashadda khashyah; wa qaaloo Rabbanaa lima katabta 'alainal qitaala law laaa akhkhartanaa ilaaa ajalin qareeb; qul mataa'ud dunyaa qaleelunw wal Aakhiratu khairul limanit taqaa wa laa tuzlamoona fateelaa", "translation": "Have you not seen those who were told, \"Restrain your hands [from fighting] and establish prayer and give zakah\"? But then when fighting was ordained for them, at once a party of them feared men as they fear Allah or with [even] greater fear. They said, \"Our Lord, why have You decreed upon us fighting? If only You had postponed [it for] us for a short time.\" Say, The enjoyment of this world is little, and the Hereafter is better for he who fears Allah. And injustice will not be done to you, [even] as much as a thread [inside a date seed].\""}, {"ayah": 78, "translit": "Ainamaa takoonoo yudrikkumul mawtu wa law kuntum fee buroojim mushai yadah; wa in tusibhum hasanatuny yaqooloo haazihee min indil laahi wa in tusibhum saiyi'atuny yaqooloo haazihee min 'indik; qul kullum min 'indillaahi famaa lihaaa 'ulaaa'il qawmi laa yakkaadoona yafqahoona hadeesaa", "translation": "Wherever you may be, death will overtake you, even if you should be within towers of lofty construction. But if good comes to them, they say, \"This is from Allah \"; and if evil befalls them, they say, \"This is from you.\" Say, \"All [things] are from Allah.\" So what is [the matter] with those people that they can hardly understand any statement?"}, {"ayah": 79, "translit": "Maaa asaabaka min hasanatin faminal laahi wa maaa asaaabaka min saiyi'atin famin nafsik; wa arsalnaaka linnaasi Rasoolaa; wa kafaa billaahi Shaheedaa", "translation": "What comes to you of good is from Allah, but what comes to you of evil, [O man], is from yourself. And We have sent you, [O Muhammad], to the people as a messenger, and sufficient is Allah as Witness."}, {"ayah": 80, "translit": "Man yuti'ir Rasoola faqad ataa'al laaha wa man tawallaa famaaa arsalnaaka 'alaihim hafeezaa", "translation": "He who obeys the Messenger has obeyed Allah; but those who turn away - We have not sent you over them as a guardian."}, {"ayah": 81, "translit": "Wa yaqooloona taa'antun fa izaa barazoo min 'indika baiyata taaa'ifatum minhum ghairal lazee taqoolu wallaahu yaktubu maa yubaiyitoona faa'rid 'anhum wa tawakkal 'alal laah; wa kafaa billaahi Wakeelaa", "translation": "And they say, \"[We pledge] obedience.\" But when they leave you, a group of them spend the night determining to do other than what you say. But Allah records what they plan by night. So leave them alone and rely upon Allah. And sufficient is Allah as Disposer of affairs."}, {"ayah": 82, "translit": "Afalaa yatadabbaroonal Qur'aan; wa law kaana min 'indi ghairil laahi la wajadoo fee hikh tilaafan kaseeraa", "translation": "Then do they not reflect upon the Qur'an? If it had been from [any] other than Allah, they would have found within it much contradiction."}, {"ayah": 83, "translit": "Wa izaa jaaa'ahum amrum  minal amni awil kkhawfi azaa'oo bihee wa law raddoohu ilar Rasooli wa ilaaa ulil amri minhum la'alimahul lazeena yastambitoonahoo minhum; wa law laa fadlul laahi 'alaikum wa rahmatuhoo lattaba'tumush Shaitaana illaa qaleelaa", "translation": "And when there comes to them information about [public] security or fear, they spread it around. But if they had referred it back to the Messenger or to those of authority among them, then the ones who [can] draw correct conclusions from it would have known about it. And if not for the favor of Allah upon you and His mercy, you would have followed Satan, except for a few."}, {"ayah": 84, "translit": "Faqaatil fee sabeelil laahi laa tukallafu illa nafsaka wa harridil mu'mineena 'asallaahu ai yakuffa baasallazeena kafaroo; wallaahu ashaddu baasanw wa ashaaddu tanakeelaa", "translation": "So fight, [O Muhammad], in the cause of Allah; you are not held responsible except for yourself. And encourage the believers [to join you] that perhaps Allah will restrain the [military] might of those who disbelieve. And Allah is greater in might and stronger in [exemplary] punishment."}, {"ayah": 85, "translit": "Mai yashfa' shafaa'atan hasanatay yakul lahoo naseebum minhaa wa mai yashfa' shafaa'tan saiyi'atanny-yakul lahoo kiflum minhaa; wa kaanal laahu 'alaa kulli shai'im Muqeetaa", "translation": "Whoever intercedes for a good cause will have a reward therefrom; and whoever intercedes for an evil cause will have a burden therefrom. And ever is Allah, over all things, a Keeper."}, {"ayah": 86, "translit": "Wa izaa huyyeetum bitahiy yatin fahaiyoo bi ahsana minhaaa aw ruddoohaa; innal laaha kaana 'alaa kulli shai'in Haseeba", "translation": "And when you are greeted with a greeting, greet [in return] with one better than it or [at least] return it [in a like manner]. Indeed, Allah is ever, over all things, an Accountant."}, {"ayah": 87, "translit": "Allaahu laaa ilaaha illaa huwa la yajma'annakum ilaa Yawmil Qiyaamati laa raiba feeh; wa man asdaqu mminallaahi hadeesaa", "translation": "Allah - there is no deity except Him. He will surely assemble you for [account on] the Day of Resurrection, about which there is no doubt. And who is more truthful than Allah in statement."}, {"ayah": 88, "translit": "Famaa lakum filmuna afiqeena fi'ataini wallaahu arkasahum bimaa kasaboo; atureedoona an tahdoo man adallal laahu wa mmai yudlilil laahu falan tajida lahoo sabeelaa", "translation": "What is [the matter] with you [that you are] two groups concerning the hypocrites, while Allah has made them fall back [into error and disbelief] for what they earned. Do you wish to guide those whom Allah has sent astray? And he whom Allah sends astray - never will you find for him a way [of guidance]."}, {"ayah": 89, "translit": "Wadoo law takfuroona kamaa kafaroo fatakoonoona sawaaa'an falaa tattakhizoo minhum awliyaaa'a hattaa yuhaajiroo fee sabeelil laah; fa in tawallaw fa khuzoohum waqtuloohum haisu wajat tumoohum wa laa tattakhizoo minhum waliyyanw wa laa naseeraa", "translation": "They wish you would disbelieve as they disbelieved so you would be alike. So do not take from among them allies until they emigrate for the cause of Allah. But if they turn away, then seize them and kill them wherever you find them and take not from among them any ally or helper."}, {"ayah": 90, "translit": "Illal lazeena yasiloona ilaa qawmim binakum wa bainahum meesaaqun aw jaaa'ookum hasirat sudooruhum ai yuqaatilookum aw yuqaatiloo qawmahum, wa law shaaa'al laahu lasallatahum 'alaikum falaqaatalookum; fa ini' tazalookum falam yuqaatilookum wa alqaw ilaikumus salama famaa ja'alal laahu lakum 'alaihim sabeelaa", "translation": "Except for those who take refuge with a people between yourselves and whom is a treaty or those who come to you, their hearts strained at [the prospect of] fighting you or fighting their own people. And if Allah had willed, He could have given them power over you, and they would have fought you. So if they remove themselves from you and do not fight you and offer you peace, then Allah has not made for you a cause [for fighting] against them."}, {"ayah": 91, "translit": "Satajidoona aakhareena yureedoona ai yaamanookum wa yaamanoo qawmahum kullamaa ruddooo ilal fitnati urkisoo feehaa; fa il lam ya'tazilookum wa yulqooo ilai kumus salama wa yakuffooo aidiyahum fakhuzoohum waqtuloohum haisu saqif tumoohum; wa ulaaa'ikum ja'alnaa lakum 'alaihim sultaanam mubeenaa", "translation": "You will find others who wish to obtain security from you and [to] obtain security from their people. Every time they are returned to [the influence of] disbelief, they fall back into it. So if they do not withdraw from you or offer you peace or restrain their hands, then seize them and kill them wherever you overtake them. And those - We have made for you against them a clear authorization."}, {"ayah": 92, "translit": "Wa maa kaana limu'minin ai yaqtula mu'minan illaa khata'aa; waman qatala mu'minan khata'an fatahreeru raqabatim mu'minatinw wa diyatum mmusallamatun ilaaa ahliheee illaaa ai yassaddaqoo; fa in kaana min qawmin 'aduwwil lakum wa huwa mu'minun fatahreeru raqabatim mu'minah; wa in kaana min qawmim bainakum wa bainahum meesaaqun fadiyatum mmusallamatun ilaaa ahlihee wa tahreeru raqabatim mu'minatin famal lam yajid fa Siyaamu shahraini mutataabi'aini tawhatam minal laah; wa kaanal laahu 'Aleeman hakeemaa", "translation": "And never is it for a believer to kill a believer except by mistake. And whoever kills a believer by mistake - then the freeing of a believing slave and a compensation payment presented to the deceased's family [is required] unless they give [up their right as] charity. But if the deceased was from a people at war with you and he was a believer - then [only] the freeing of a believing slave; and if he was from a people with whom you have a treaty - then a compensation payment presented to his family and the freeing of a believing slave. And whoever does not find [one or cannot afford to buy one] - then [instead], a fast for two months consecutively, [seeking] acceptance of repentance from Allah. And Allah is ever Knowing and Wise."}, {"ayah": 93, "translit": "Wa mai yaqtul mu'minammuta 'ammidan fajazaaa'uhoo Jahannamu khaalidan feehaa wa ghadibal laahu' alaihi wa la'anahoo wa a'adda lahoo 'azaaban 'azeemaa", "translation": "But whoever kills a believer intentionally - his recompense is Hell, wherein he will abide eternally, and Allah has become angry with him and has cursed him and has prepared for him a great punishment."}, {"ayah": 94, "translit": "Yaaa aiyuhal lazeena aamanoo izaa darabtum fee sabeelil laahi fatabaiyanoo wa laa taqooloo liman alqaaa ilaikumus salaama lasta mu'minan tabtaghoona 'aradal hayaatid dunyaa fa'indal laahi maghaanimu kaseerah; kazaalika kuntum min qablu famannnal laahu 'alaikum fatabaiyanoo; innallaaha kaana bimaa ta'maloona Khabeeraa", "translation": "O you who have believed, when you go forth [to fight] in the cause of Allah, investigate; and do not say to one who gives you [a greeting of] peace \"You are not a believer,\" aspiring for the goods of worldly life; for with Allah are many acquisitions. You [yourselves] were like that before; then Allah conferred His favor upon you, so investigate. Indeed Allah is ever, with what you do, Acquainted."}, {"ayah": 95, "translit": "Laa yastawil qaa'idoona Minal mu'mineena ghairu ulid darari walmujaahidoona fee sabeelil laahi bi amwaalihim wa anfusihim; faddalal laahul mujaahideena bi am waalihim wa anfusihim 'alalqaa'ideena darajab; wa kullanw wa'adal laahul husnaa; wa faddalal laahul mujaahideena 'alal qaa'ideena ajran 'azeemaa", "translation": "Not equal are those believers remaining [at home] - other than the disabled - and the mujahideen, [who strive and fight] in the cause of Allah with their wealth and their lives. Allah has preferred the mujahideen through their wealth and their lives over those who remain [behind], by degrees. And to both Allah has promised the best [reward]. But Allah has preferred the mujahideen over those who remain [behind] with a great reward -"}, {"ayah": 96, "translit": "Darajaatim minhu wa maghfiratanw wa rahmah; wa kaanal laahu Ghafoorar Raheema", "translation": "Degrees [of high position] from Him and forgiveness and mercy. And Allah is ever Forgiving and Merciful."}, {"ayah": 97, "translit": "Innal lazeena tawaffaa humul malaaa'ikatu zaalimeee anfusihim qaaloo feema kuntum qaaloo kunnaa mustad'afeena fil-ard; qaalooo alam takun ardul laahi waasi'atan fatuhaajiroo feehaa; fa ulaaa'ika maawaahum Jahannamu wa saaa'at maseeraa", "translation": "Indeed, those whom the angels take [in death] while wronging themselves - [the angels] will say, \"In what [condition] were you?\" They will say, \"We were oppressed in the land.\" The angels will say, \"Was not the earth of Allah spacious [enough] for you to emigrate therein?\" For those, their refuge is Hell - and evil it is as a destination."}, {"ayah": 98, "translit": "Illal mustad 'afeena minar rijaali wannisaaa'i walwildaani laa yastatee'oona heelatanw wa laa yahtadoona sabeela", "translation": "Except for the oppressed among men, women and children who cannot devise a plan nor are they directed to a way -"}, {"ayah": 99, "translit": "Fa ulaaa'ika 'asal laahu ai ya'fuwa 'anhum; wa kaanal laahu 'Afuwwan Ghafooraa", "translation": "For those it is expected that Allah will pardon them, and Allah is ever Pardoning and Forgiving."}, {"ayah": 100, "translit": "Wa mai yuhaajir fee sabeelil laahi yajid fil ardi mmuraaghaman kaseeranw wa sa'ah; wa mai yakhruj mim baitihee muhaajiran ilal laahi wa Rasoolihee summa yudrikhul mawtu faqad waqa'a ajruhoo 'alal laah; wa kaanal laahu Ghafoorar Raheemaa", "translation": "And whoever emigrates for the cause of Allah will find on the earth many [alternative] locations and abundance. And whoever leaves his home as an emigrant to Allah and His Messenger and then death overtakes him - his reward has already become incumbent upon Allah. And Allah is ever Forgiving and Merciful."}, {"ayah": 101, "translit": "Wa izaa darabtum fil ardi falaisa 'alaikum junaahun an taqsuroo minas Salaati in khiftum ai yaftinakumul lazeena kafarooo; innal kaafireena kaanoo lakum aduwwam mubeenaa", "translation": "And when you travel throughout the land, there is no blame upon you for shortening the prayer, [especially] if you fear that those who disbelieve may disrupt [or attack] you. Indeed, the disbelievers are ever to you a clear enemy."}, {"ayah": 102, "translit": "Wa izaa kunta feehim fa aqamta lahumus Salaata faltaqum taaa'ifatum minhum ma'aka walyaakhuzooo aslihatahum fa izaa sajadoo fal yakoonoo minw waraaa'ikum waltaati taaa'ifatun ukhraa lam yusalloo falyusallo ma'aka walyaakhuzoo hizrahum wa aslihatahum; waddal lazeena kafaroo law taghfuloona 'anaslihatikum wa amti'atikum fa yameeloona 'alaikum mailatanw waahidah; wa laa junaaha 'alaikum in kaana bikum azam mimmatarin aw kuntum mmardaaa an tada'ooo aslihatakum wa khuzoo hizrakum; innal laaha a'adda lilkaafireena 'azaabam muheenaa", "translation": "And when you are among them and lead them in prayer, let a group of them stand [in prayer] with you and let them carry their arms. And when they have prostrated, let them be [in position] behind you and have the other group come forward which has not [yet] prayed and let them pray with you, taking precaution and carrying their arms. Those who disbelieve wish that you would neglect your weapons and your baggage so they could come down upon you in one [single] attack. But there is no blame upon you, if you are troubled by rain or are ill, for putting down your arms, but take precaution. Indeed, Allah has prepared for the disbelievers a humiliating punishment."}, {"ayah": 103, "translit": "Fa izaa qadaitumus Salaata fazkurul laaha qiyaamanw wa qu'oodanw wa 'alaa junoobikum; fa izat maanantum fa aqeemus Salaah; innas Salaata kaanat 'alal mu'mineena kitaabam mawqootaa", "translation": "And when you have completed the prayer, remember Allah standing, sitting, or [lying] on your sides. But when you become secure, re-establish [regular] prayer. Indeed, prayer has been decreed upon the believers a decree of specified times."}, {"ayah": 104, "translit": "Wa laa tahinoo fibtighaaa'il qawmi in takoonoo taalamoona fa innahum yaalamoona kamaa taalamoona wa tarjoona minal laahi maa laa yarjoon; wa kaanal laahu 'Aleeman Hakeemaa", "translation": "And do not weaken in pursuit of the enemy. If you should be suffering - so are they suffering as you are suffering, but you expect from Allah that which they expect not. And Allah is ever Knowing and Wise."}, {"ayah": 105, "translit": "Innaaa anzalnaaa ilaikal Kitaaba bilhaqqi litahkuma bainan naasi bimaaa araakal laah; wa laa takul lilkhaaa'ineena khaseemaa", "translation": "Indeed, We have revealed to you, [O Muhammad], the Book in truth so you may judge between the people by that which Allah has shown you. And do not be for the deceitful an advocate."}, {"ayah": 106, "translit": "Wastaghfiril laaha innal laaha kaana Ghafoorar Raheema", "translation": "And seek forgiveness of Allah. Indeed, Allah is ever Forgiving and Merciful."}, {"ayah": 107, "translit": "Wa laa tujaadil 'anil lazeena yakhtaanoona anfusahum; innal laaha laa yuhibbuman kaana khawwaanan aseemaa", "translation": "And do not argue on behalf of those who deceive themselves. Indeed, Allah loves not one who is a habitually sinful deceiver."}, {"ayah": 108, "translit": "Yastakhfoona minannaasi wa laa yastakh foona minal laahi wa huwa ma'ahum iz yubaiyitoona maa laa yardaa minal qawl; wa kaanal laahu bimaa ya'maloona muheetaa", "translation": "They conceal [their evil intentions and deeds] from the people, but they cannot conceal [them] from Allah, and He is with them [in His knowledge] when they spend the night in such as He does not accept of speech. And ever is Allah, of what they do, encompassing."}, {"ayah": 109, "translit": "haaa antum haaa'ulaaa'i jaadaltum 'anhum fil hayaatid dunyaa famai yujaadilul laaha 'anhum Yawmal Qiyaamati am mai yakoonu 'alaihim wakeelaa", "translation": "Here you are - those who argue on their behalf in [this] worldly life - but who will argue with Allah for them on the Day of Resurrection, or who will [then] be their representative?"}, {"ayah": 110, "translit": "Wa mai ya'mal sooo'an aw yazlim nafsahoo summa yastaghfiril laaha yajidil laaha Ghafoorar Raheemaa", "translation": "And whoever does a wrong or wrongs himself but then seeks forgiveness of Allah will find Allah Forgiving and Merciful."}, {"ayah": 111, "translit": "Wa mai yaksib isman fa innamaa yaksibuhoo 'alaa nafsih; wa kaanal laahu 'Aleeman hakeemaa", "translation": "And whoever commits a sin only earns it against himself. And Allah is ever Knowing and Wise."}, {"ayah": 112, "translit": "Wa mai yaksib khateee'atan aw isman summa yarmi bihee bareee'an faqadih tamala buhtaananw wa ismam mubeenaa", "translation": "But whoever earns an offense or a sin and then blames it on an innocent [person] has taken upon himself a slander and manifest sin."}, {"ayah": 113, "translit": "Wa law laa fadlul laahi 'alaika wa rahmatuhoo lahammat taaa'ifatum minhum ai yudillooka wa maa yudilloona illaaa anfusahum wa maa yadurroonaka min shai'; wa anzalal laahu 'alaikal Kitaaba wal Hikmata wa 'allamaka maa lam takun ta'lam; wa kaana fadlul laahi 'alaika 'azeemaa", "translation": "And if it was not for the favor of Allah upon you, [O Muhammad], and His mercy, a group of them would have determined to mislead you. But they do not mislead except themselves, and they will not harm you at all. And Allah has revealed to you the Book and wisdom and has taught you that which you did not know. And ever has the favor of Allah upon you been great."}, {"ayah": 114, "translit": "laa khaira fee kaseerim min najwaahum illaa man amara bisadaqatin aw ma'roofin aw islaahim bainan naas; wa mai yaf'al zaalikab tighaaa'a mardaatil laahi fa sawfa nu'teehi ajran 'azeemaa", "translation": "No good is there in much of their private conversation, except for those who enjoin charity or that which is right or conciliation between people. And whoever does that seeking means to the approval of Allah - then We are going to give him a great reward."}, {"ayah": 115, "translit": "Wa mai yushaaqiqir Rasoola mim ba'di maa tabaiyana lahul hudaa wa tattabi' ghaira sabeelil mu'mineena nuwallihee ma tawallaa wa nuslihee Jahannama wa saaa'at maseeraa", "translation": "And whoever opposes the Messenger after guidance has become clear to him and follows other than the way of the believers - We will give him what he has taken and drive him into Hell, and evil it is as a destination."}, {"ayah": 116, "translit": "Innal laaha laa yaghfiru ai yushraka bihee wayaghfiru maa doona zaalika limai yashaaa'; wa mai yushrik billaahi faqad dalla dalaalam ba'eedaa", "translation": "Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allah has certainly gone far astray."}, {"ayah": 117, "translit": "iny yad'oona min dooniheee illaaa inaasanw wa iny yad'oona illaa Shaitaanam mareedaa", "translation": "They call upon instead of Him none but female [deities], and they [actually] call upon none but a rebellious Satan."}, {"ayah": 118, "translit": "La'anahul laah; wa qaala la attakhizanna min 'ibaadika naseebam mafroodaa", "translation": "Whom Allah has cursed. For he had said, \"I will surely take from among Your servants a specific portion."}, {"ayah": 119, "translit": "Wa la udillannahum wa la umanni yannnahum wa la aamurannahum fala yubat tikunna aazaanal lan'aami wa la aamurannahum fala yughai yirunna khalqal laah; wa mai yattakhizish Shaitaana waliyyam mmin doonil laahi faqad khasira khusraanam mubeena", "translation": "And I will mislead them, and I will arouse in them [sinful] desires, and I will command them so they will slit the ears of cattle, and I will command them so they will change the creation of Allah.\" And whoever takes Satan as an ally instead of Allah has certainly sustained a clear loss."}, {"ayah": 120, "translit": "Ya'iduhum wa yuman neehim wa maa ya'iduhumush Shaitaanu illaa ghurooraa", "translation": "Satan promises them and arouses desire in them. But Satan does not promise them except delusion."}, {"ayah": 121, "translit": "Ulaaa'ika maawaahum Jahannamu wa laa yajidoona 'anhaa maheesaa", "translation": "The refuge of those will be Hell, and they will not find from it an escape."}, {"ayah": 122, "translit": "Wallazeena aamanoo wa 'amilus saalihaati sanud khiluhum Jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa; wa'dal laahi haqqaa; wa man asdaqu minal laahi qeelaa", "translation": "But the ones who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they will abide forever. [It is] the promise of Allah, [which is] truth, and who is more truthful than Allah in statement."}, {"ayah": 123, "translit": "Laisa bi amaaniyyikum wa laaa amaaniyyi Ahlil Kitaab; mai ya'mal sooo'ai yujza bihee wa laa yajid lahoo min doonil laahi waliyanw wa laa naseeraa", "translation": "Paradise is not [obtained] by your wishful thinking nor by that of the People of the Scripture. Whoever does a wrong will be recompensed for it, and he will not find besides Allah a protector or a helper."}, {"ayah": 124, "translit": "Wa mai ya'mal minas saalihaati min zakarin aw unsaa wa huwa mu'minun fa ulaaa'ika yadkhuloonal Jannata wa laa yuzlamoona naqeeraa", "translation": "And whoever does righteous deeds, whether male or female, while being a believer - those will enter Paradise and will not be wronged, [even as much as] the speck on a date seed."}, {"ayah": 125, "translit": "Wa man ahsanu deenam mimmman aslama wajhahoo lillaahi wa huwa muhsinunw wattaba'a Millata Ibraaheema haneefaa; wattakhazal laahu Ibraaheema khaleelaa", "translation": "And who is better in religion than one who submits himself to Allah while being a doer of good and follows the religion of Abraham, inclining toward truth? And Allah took Abraham as an intimate friend."}, {"ayah": 126, "translit": "Wa lillaahi maa fis samaawaati wa maa fil ard; wa kaanal laahu bikulli shai'im muheetaa", "translation": "And to Allah belongs whatever is in the heavens and whatever is on the earth. And ever is Allah, of all things, encompassing."}, {"ayah": 127, "translit": "Wa yastaftoonaka finnisaaa'i qulil laahu yufteekum feehinna wa maa yutlaa 'alaikum fil Kitaabi fee yataaman nisaaa'il laatee laa tu'toonahunna mmaa kutiba lahunnna wa targhaboona an tankihoohunna wal mustad'a feena minal wildaani wa an taqoomoo lilyataamaa bilqist; wa maa taf'aloo min khairin fa innal laaha kaana bihee 'Aleemaa", "translation": "And they request from you, [O Muhammad], a [legal] ruling concerning women. Say, \"Allah gives you a ruling about them and [about] what has been recited to you in the Book concerning the orphan girls to whom you do not give what is decreed for them - and [yet] you desire to marry them - and concerning the oppressed among children and that you maintain for orphans [their rights] in justice.\" And whatever you do of good - indeed, Allah is ever Knowing of it."}, {"ayah": 128, "translit": "Wa inimra atun khaafat mim ba'lihaa nushoozan aw i'raadan falaa junaaha 'alaihi maaa ai yuslihaa bainahumaa sulhaa; wassulhu khair; wa uhdiratil anfusush shuhh; wa in tuhsinoo wa tattaqoo fa innal laaha kaana bimaa ta'maloona Khabeeraa", "translation": "And if a woman fears from her husband contempt or evasion, there is no sin upon them if they make terms of settlement between them - and settlement is best. And present in [human] souls is stinginess. But if you do good and fear Allah - then indeed Allah is ever, with what you do, Acquainted."}, {"ayah": 129, "translit": "Wa lan tastatee'ooo an ta'diloo bainan nisaaa'i wa law harastum falaa tameeloo kullal maili fatazaroohaa kalmu'al laqah; wa in tuslihoo wa tattaqoo fa innal laaha kaana Ghafoorar Raheema", "translation": "And you will never be able to be equal [in feeling] between wives, even if you should strive [to do so]. So do not incline completely [toward one] and leave another hanging. And if you amend [your affairs] and fear Allah - then indeed, Allah is ever Forgiving and Merciful."}, {"ayah": 130, "translit": "Wa iny-yatafarraqaa yughnil laahu kullam min sa'atih; wa kaanal laahu Waasi'an Hakeemaa", "translation": "But if they separate [by divorce], Allah will enrich each [of them] from His abundance. And ever is Allah Encompassing and Wise."}, {"ayah": 131, "translit": "Wa lillaahi maafis samaawaati wa maa fil ard; wa laqad wassainal lazeena ootul Kitaaba min qablikum wa iyyaakum anit taqul laah; wa intakfuroo fa inna lillaahi maa fis samaawaati wa maa fil ard; wa kaanal laahu Ghaniyyan hameedaa", "translation": "And to Allah belongs whatever is in the heavens and whatever is on the earth. And We have instructed those who were given the Scripture before you and yourselves to fear Allah. But if you disbelieve - then to Allah belongs whatever is in the heavens and whatever is on the earth. And ever is Allah Free of need and Praiseworthy."}, {"ayah": 132, "translit": "Wa lillaahi maa fis samaawaati wa maa fil ard; wa kafaa billaahi Wakeelaa", "translation": "And to Allah belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs."}, {"ayah": 133, "translit": "Iny-yashaa yuzhibkum aiyuhan naasu wa yaati bi aakhareen; wa kaanal laahu 'alaa zaalika Qadeeraa", "translation": "If He wills, He can do away with you, O people, and bring others [in your place]. And ever is Allah competent to do that."}, {"ayah": 134, "translit": "man kaana yureedu sawaabad dunyaa fa'indallaahi sawaabud dunyaa wal Aakhirah; wa kaanal laahu Samee'am Baseeraa", "translation": "Whoever desires the reward of this world - then with Allah is the reward of this world and the Hereafter. And ever is Allah Hearing and Seeing."}, {"ayah": 135, "translit": "Yaa aiyuhal lazeena aamanoo koonoo qawwa ameena bilqisti shuhadaaa'a lillaahi wa law 'alaa anfusikum awil waalidaini wal aqrabeen iny yakun ghaniyyan aw faqeeran fallaahu awlaa bihimaa falaaa tattabi'ul hawaaa an ta'diloo; wa in talwooo aw tu'ridoo fa innal laaha kaana bimaa ta'maloona Khabeera", "translation": "O you who have believed, be persistently standing firm in justice, witnesses for Allah, even if it be against yourselves or parents and relatives. Whether one is rich or poor, Allah is more worthy of both. So follow not [personal] inclination, lest you not be just. And if you distort [your testimony] or refuse [to give it], then indeed Allah is ever, with what you do, Acquainted."}, {"ayah": 136, "translit": "Yaaa aiyuhal lazeena aamanooo aaminoo billaahi wa Rasoolihee wal Kitaabil lazee nazzala 'alaa Rasoolihee wal Kitaabil lazeee anzala min qabl; wa mai yakfur billaahi wa Malaaa'ikatihee wa Kutubihee wa Rusulihee wal Yawmil Aakhiri faqad dalla dalaalam ba'eedaa", "translation": "O you who have believed, believe in Allah and His Messenger and the Book that He sent down upon His Messenger and the Scripture which He sent down before. And whoever disbelieves in Allah, His angels, His books, His messengers, and the Last Day has certainly gone far astray."}, {"ayah": 137, "translit": "Innal lazeena aamanoo summa kafaroo summa aamanoo summa kafaroo summaz daado kufral lam yakunil laahu liyaghfira lahum wa laa liyahdiyahum sabeelaa", "translation": "Indeed, those who have believed then disbelieved, then believed, then disbelieved, and then increased in disbelief - never will Allah forgive them, nor will He guide them to a way."}, {"ayah": 138, "translit": "Bashshiril munaafiqeena bi anna lahum 'azaaban aleemaa", "translation": "Give tidings to the hypocrites that there is for them a painful punishment -"}, {"ayah": 139, "translit": "Allazeena yattakhizoo nal kaafireena awliyaaa'a min doonil mu'mineen; a-yabta ghoona 'indahumul 'izzata fainnnal 'izzata lillaahi jamee'aa", "translation": "Those who take disbelievers as allies instead of the believers. Do they seek with them honor [through power]? But indeed, honor belongs to Allah entirely."}, {"ayah": 140, "translit": "Wa qad nazzala 'alaikum fil Kitaabi an izaa sami'tum Aayaatil laahi yukfaru bihaa wa yustahza u bihaa falaa taq'udoo ma'ahum hattaa yakhoodoo fee hadeesin ghairih; innakum izam misluhum; innal laaha jaami'ul munaafiqeena wal kaafireena fee jahannama jamee'aa", "translation": "And it has already come down to you in the Book that when you hear the verses of Allah [recited], they are denied [by them] and ridiculed; so do not sit with them until they enter into another conversation. Indeed, you would then be like them. Indeed Allah will gather the hypocrites and disbelievers in Hell all together -"}, {"ayah": 141, "translit": "Allazeena yatarab basoona bikum fa in kaana lakum fathum minal laahi qaalooo alam nakum ma'akum wa in kaana lilkaafireena naseebun qaalooo alam nastah wiz 'alaikum wa nammna'kum minal mu'mineen; fallaahu yahkumu bainakum Yawmal Qiyaamah; wa lai yaj'alal laahu lilkaafireena 'alal mu'mineena sabeelaa", "translation": "Those who wait [and watch] you. Then if you gain a victory from Allah, they say, \"Were we not with you?\" But if the disbelievers have a success, they say [to them], \"Did we not gain the advantage over you, but we protected you from the believers?\" Allah will judge between [all of] you on the Day of Resurrection, and never will Allah give the disbelievers over the believers a way [to overcome them]."}, {"ayah": 142, "translit": "Innal munaafiqeena yukhaadi'oonal laaha wa huwa khaadi'uhum wa izaa qaamooo ilas Salaati qaamoo kusaalaa yuraaa'oonan naasa wa laa yazkuroonal laaha illaa qaleelaa", "translation": "Indeed, the hypocrites [think to] deceive Allah, but He is deceiving them. And when they stand for prayer, they stand lazily, showing [themselves to] the people and not remembering Allah except a little,"}, {"ayah": 143, "translit": "Muzabzabeena baina zaalika laaa ilaa haaa' ulaaa'i wa laaa ilaa haaa'ulaaa'; wa mai yudlilil laahu falan tajida lahoo sabeela", "translation": "Wavering between them, [belonging] neither to the believers nor to the disbelievers. And whoever Allah leaves astray - never will you find for him a way."}, {"ayah": 144, "translit": "Yaaa aiyuhal lazeena aamanoo laa tattakhizul kaafireena awliyaaa'a min doonil mu'mineen; aturee doona an taj'aloo lillaahi 'alaikum sultaanam mubeenaa", "translation": "O you who have believed, do not take the disbelievers as allies instead of the believers. Do you wish to give Allah against yourselves a clear case?"}, {"ayah": 145, "translit": "Innal munaafiqeena fiddarkil asfali minan Naari wa lan tajjida lahum naseeraa", "translation": "Indeed, the hypocrites will be in the lowest depths of the Fire - and never will you find for them a helper -"}, {"ayah": 146, "translit": "Illal lazeena taaboo wa aslahoo wa'tasamoo billaahi wa akhlasoo deenahum lillaahi faulaaa'ika ma'al mu'mineena wa sawfa yu'til laahul mu'mineena ajran 'azeemaa", "translation": "Except for those who repent, correct themselves, hold fast to Allah, and are sincere in their religion for Allah, for those will be with the believers. And Allah is going to give the believers a great reward."}, {"ayah": 147, "translit": "maa yafa'lul laahu bi 'azaabikum in shakartum wa aamantum; wa kaanal laahu Shaakiran 'Aleema", "translation": "What would Allah do with your punishment if you are grateful and believe? And ever is Allah Appreciative and Knowing."}, {"ayah": 148, "translit": "Laa yuhibbullaahul jahra bis sooo'i minal qawli illaa man zulim; wa kaanallaahu Samee'an 'Aleeman", "translation": "Allah does not like the public mention of evil except by one who has been wronged. And ever is Allah Hearing and Knowing."}, {"ayah": 149, "translit": "in tubdoo khairann aw tukhfoohu aw ta'foo 'an sooo'in fa innal laaha kaana 'afuwwan Qadeeraa", "translation": "If [instead] you show [some] good or conceal it or pardon an offense - indeed, Allah is ever Pardoning and Competent."}, {"ayah": 150, "translit": "Innal lazeena yakkfuroona billaahi wa Rusulihee wa yureedoona ai yufarriqoo bainal laahi wa Rusulihee wa yaqooloona nu'minu biba'dinw wa nakfuru biba' dinw wa yureedoona ai yattakhizoo baina zaalika sabeelaa", "translation": "Indeed, those who disbelieve in Allah and His messengers and wish to discriminate between Allah and His messengers and say, \"We believe in some and disbelieve in others,\" and wish to adopt a way in between -"}, {"ayah": 151, "translit": "Ulaaa'ika humul kaafiroona haqqaa; wa a'tadnaa lilkaafireena 'azaabam muheenaa", "translation": "Those are the disbelievers, truly. And We have prepared for the disbelievers a humiliating punishment."}, {"ayah": 152, "translit": "Wallazeena aamanoo billaahi wa Rusulihee wa lam yufarriqoo baina ahadim minhum ulaaa'ika sawfa yu'teehim ujoorahum; wa kaanal laahu Ghafoorar Raheema", "translation": "But they who believe in Allah and His messengers and do not discriminate between any of them - to those He is going to give their rewards. And ever is Allah Forgiving and Merciful."}, {"ayah": 153, "translit": "yas'aluka Ahlul Kitaabi an tunazzila 'alaihim Kitaabam minas samaaa'i faqad sa aloo Moosaa akbara min zaalika faqaaloo arinal laaha jahratan fa akhazat humus saa'iqatu bizulmihim; summat takhazul 'ijla mim ba'di maa jaa'at humul baiyinaatu fa'afawnaa  'ann zaalik; wa aatainaa Moosaa sultaanam mubeenaa", "translation": "The People of the Scripture ask you to bring down to them a book from the heaven. But they had asked of Moses [even] greater than that and said, \"Show us Allah outright,\" so the thunderbolt struck them for their wrongdoing. Then they took the calf [for worship] after clear evidences had come to them, and We pardoned that. And We gave Moses a clear authority."}, {"ayah": 154, "translit": "Wa rafa'naa fawqahumut Toora bimeesaaqihim wa qulnaa lahumud khulul baaba sujjadanw wa qulnaa lahum laa ta'doo fis Sabti wa akhaznaa minhum meesaaqan ghaleezaa", "translation": "And We raised over them the mount for [refusal of] their covenant; and We said to them, \"Enter the gate bowing humbly\", and We said to them, \"Do not transgress on the sabbath\", and We took from them a solemn covenant."}, {"ayah": 155, "translit": "Fabimaa naqdihim meesaaqahum wa kufrihim bi Aayaatil laahi wa qatlihimul Ambiyaaa'a bighairi haqqinw wa qawlihim quloobunna ghulf; bal taba'al laahu 'alaihaa bikufrihim falaa yu'minoona illaa qaleelaa", "translation": "And [We cursed them] for their breaking of the covenant and their disbelief in the signs of Allah and their killing of the prophets without right and their saying, \"Our hearts are wrapped\". Rather, Allah has sealed them because of their disbelief, so they believe not, except for a few."}, {"ayah": 156, "translit": "Wa bikufrihim wa qawlihim 'alaa Maryama buh taanan 'azeema", "translation": "And [We cursed them] for their disbelief and their saying against Mary a great slander,"}, {"ayah": 157, "translit": "Wa qawlihim innaa qatal nal maseeha 'Eesab-na-Maryama Rasoolal laahi wa maa qataloohu wa maa salaboohu wa laakin shubbiha lahum; wa innal lazeenakh talafoo fee lafee shakkim minh; maa lahum bihee min 'ilmin illat tibaa'az zann; wa maa qataloohu yaqeenaa", "translation": "And [for] their saying, \"Indeed, we have killed the Messiah, Jesus, the son of Mary, the messenger of Allah.\" And they did not kill him, nor did they crucify him; but [another] was made to resemble him to them. And indeed, those who differ over it are in doubt about it. They have no knowledge of it except the following of assumption. And they did not kill him, for certain."}, {"ayah": 158, "translit": "Bar rafa'ahul laahu ilayh; wa kaanal laahu 'Azeezan Hakeemaa", "translation": "Rather, Allah raised him to Himself. And ever is Allah Exalted in Might and Wise."}, {"ayah": 159, "translit": "Wa im min Ahlil Kitaabi illaa layu'minanna bihee qabla mawtihee wa Yawmal Qiyaamati yakoonu 'alaihim shaheedaa", "translation": "And there is none from the People of the Scripture but that he will surely believe in Jesus before his death. And on the Day of Resurrection he will be against them a witness."}, {"ayah": 160, "translit": "Fabizulmin minal lazeena haadoo harramnaa 'alaihim taiyibaatin uhillat lahum wa bisadihim 'an sabeelil laahi kaseeraa", "translation": "For wrongdoing on the part of the Jews, We made unlawful for them [certain] good foods which had been lawful to them, and for their averting from the way of Allah many [people],"}, {"ayah": 161, "translit": "Wa akhzihimur ribaa wa qad nuhoo 'anhu wa aklihim amwaalan naasi bilbaatil; wa a'tadnaa lilkaafireena minhum 'azaaban aleema", "translation": "And [for] their taking of usury while they had been forbidden from it, and their consuming of the people's wealth unjustly. And we have prepared for the disbelievers among them a painful punishment."}, {"ayah": 162, "translit": "Laakinir raasikhoona fil'ilmi minhum walmu'minoona yu'minoona bimaaa unzila ilaika wa maaa unzila min qablika walmuqeemeenas Salaata walmu'toonaz Zakaata walmu 'minoona billaahi wal yawmil Aakhir; ulaaa'ika sanu'teehim ajran 'azeemaa", "translation": "But those firm in knowledge among them and the believers believe in what has been revealed to you, [O Muhammad], and what was revealed before you. And the establishers of prayer [especially] and the givers of zakah and the believers in Allah and the Last Day - those We will give a great reward."}, {"ayah": 163, "translit": "innaaa awhainaaa ilaika kamaaa awhainaaa ilaa Noohinw wan nabiyyeena mim ba'dih; wa awhainaaa ilaaa ibraaheema wa Ismaaa'eela wa Ishaaqa wa Ya'qooba wal Asbaati wa 'Eesaa wa Ayyooba wa Yoonusa wa haaroona wa Sulaimaan; wa aatainaa Daawooda Zabooraa", "translation": "Indeed, We have revealed to you, [O Muhammad], as We revealed to Noah and the prophets after him. And we revealed to Abraham, Ishmael, Isaac, Jacob, the Descendants, Jesus, Job, Jonah, Aaron, and Solomon, and to David We gave the book [of Psalms]."}, {"ayah": 164, "translit": "Wa Rusulan qad qasas naahum 'alaika min qablu wa Rusulal lam naqsushum 'alaik; wa kallamallaahu Moosaa takleemaa", "translation": "And [We sent] messengers about whom We have related [their stories] to you before and messengers about whom We have not related to you. And Allah spoke to Moses with [direct] speech."}, {"ayah": 165, "translit": "Rusulam mubashshireena wa munzireena li'allaa yakoona linnaasi 'alal laahi hujjatum ba'dar Rusul; wa kaanallaahu 'Azeezan Hakeema", "translation": "[We sent] messengers as bringers of good tidings and warners so that mankind will have no argument against Allah after the messengers. And ever is Allah Exalted in Might and Wise."}, {"ayah": 166, "translit": "Laakinil laahu yashhadu bimaaa anzala ilaika anzalahoo bi'ilmihee wal malaaa'ikatu yashhadoon; wa kafaa billaahi Shaheeda", "translation": "But Allah bears witness to that which He has revealed to you. He has sent it down with His knowledge, and the angels bear witness [as well]. And sufficient is Allah as Witness."}, {"ayah": 167, "translit": "Innal lazeena kafaroo wa saddoo 'an sabeelil laahi qad dalloo dalaalam ba'eedaa", "translation": "Indeed, those who disbelieve and avert [people] from the way of Allah have certainly gone far astray."}, {"ayah": 168, "translit": "Innal lazeenakafaroo wa zalamoo lam yakkunillaahu liyaghfira lahum wa laa liyahdiyahum tareeqaa", "translation": "Indeed, those who disbelieve and commit wrong [or injustice] - never will Allah forgive them, nor will He guide them to a path."}, {"ayah": 169, "translit": "Illaa tareeqa jahannamma khaalideena feehaa abadaa; wa kaana zaalika 'alal laahi yaseeraa", "translation": "Except the path of Hell; they will abide therein forever. And that, for Allah, is [always] easy."}, {"ayah": 170, "translit": "Yaaa aiyuhan naasu qad jaaa'akumur Rasoolu bilhaqqi mir Rabbikum fa ammminoo khairal lakum; wa in takfuroo fainnna lillaahi maa fis samaawaati wal ard; wa kaanal laahu 'Aleemann hakeemaa", "translation": "O Mankind, the Messenger has come to you with the truth from your Lord, so believe; it is better for you. But if you disbelieve - then indeed, to Allah belongs whatever is in the heavens and earth. And ever is Allah Knowing and Wise."}, {"ayah": 171, "translit": "Yaaa Ahlal Kitaabi laa taghloo fee deenikum wa laa taqooloo 'alal laahi illalhaqq; innamal Maseehu 'Eesab-nu-Maryamma Rasoolul laahi wa Kalimatuhooo alqaahaaa ilaa Maryamma wa roohum minhum fa aaminoo billaahi wa Rusulihee wa laa taqooloo salaasah; intahoo khairallakum; innamal laahu Ilaahunw Waahid, Subhaanahooo ani yakoona lahoo walad; lahoo maa fissamaawaati wa maa fil ard; wa kafaa billaahi Wakeelaa", "translation": "O People of the Scripture, do not commit excess in your religion or say about Allah except the truth. The Messiah, Jesus, the son of Mary, was but a messenger of Allah and His word which He directed to Mary and a soul [created at a command] from Him. So believe in Allah and His messengers. And do not say, \"Three\"; desist - it is better for you. Indeed, Allah is but one God. Exalted is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs."}, {"ayah": 172, "translit": "Lanny yastankifal Maseehu ai yakoona 'abdal lillaahi wa lal malaaa'ikatul muqarraboon; wa mai yastankif 'an ibaadatihee wa yastakbir fasa yahshuruhum ilaihi jamee'aa", "translation": "Never would the Messiah disdain to be a servant of Allah, nor would the angels near [to Him]. And whoever disdains His worship and is arrogant - He will gather them to Himself all together."}, {"ayah": 173, "translit": "Fa ammal lazeena aamanoo wa 'amilus saalihaati fa yuwaffeehim ujoorahum wa yazeeduhum min fadlihee wa ammal lazeenas tankafoo wastakbaroo fa yu'azzibuhum 'azaaban aleemanw wa laa yajidoona lahum min doonil laahi waliyyanw wa laa naseeraa", "translation": "And as for those who believed and did righteous deeds, He will give them in full their rewards and grant them extra from His bounty. But as for those who disdained and were arrogant, He will punish them with a painful punishment, and they will not find for themselves besides Allah any protector or helper."}, {"ayah": 174, "translit": "yaa aiyuhan naasu qad jaaa'akum burhaanum mir Rabbikum wa anzalnaaa ilaikum Nooram Mubeena", "translation": "O mankind, there has come to you a conclusive proof from your Lord, and We have sent down to you a clear light."}, {"ayah": 175, "translit": "Fa ammal lazeena aamanoo billaahi wa'tasamoo bihee fasa yudkhiluhum fee rah matim minhu wa fadlinw wa yahdeehim ilaihi Siraatam Mustaqeema", "translation": "So those who believe in Allah and hold fast to Him - He will admit them to mercy from Himself and bounty and guide them to Himself on a straight path."}, {"ayah": 176, "translit": "Yastaftoonaka qulillaahu yafteekum fil kalaalah; inimru'un halaka laisa lahoo waladunw wa lahoo ukhtun falahaa nisfu maa tarak; wa huwa yarisuhaaa il lam yakkul lahaa walad; fa in kaanatas nataini falahumas sulusaani mimmmaa tarak; wa in kaanooo ikhwatar rijaalanw wa nisaaa'an faliz zakari mislu hazzil unsayayn; yubaiyinullaahu lakum an tadilloo; wallaahu bikulli shai'in Aleem", "translation": "They request from you a [legal] ruling. Say, \"Allah gives you a ruling concerning one having neither descendants nor ascendants [as heirs].\" If a man dies, leaving no child but [only] a sister, she will have half of what he left. And he inherits from her if she [dies and] has no child. But if there are two sisters [or more], they will have two-thirds of what he left. If there are both brothers and sisters, the male will have the share of two females. Allah makes clear to you [His law], lest you go astray. And Allah is Knowing of all things."}]}, {"num": 5, "name": "Al-Ma'idah", "meaning": "The Table Spread", "verses": [{"ayah": 1, "translit": "Yaaa aiyuhal lazeena aamanoo awfoo bil'uqood; uhillat lakum baheematul an'aami illaa maa yutlaa 'alaikum ghaira muhillis saidi wa antum hurum; innal laaha yahkumu maa yureed", "translation": "O you who have believed, fulfill [all] contracts. Lawful for you are the animals of grazing livestock except for that which is recited to you [in this Qur'an] - hunting not being permitted while you are in the state of ihram. Indeed, Allah ordains what He intends."}, {"ayah": 2, "translit": "Yaaa aiyuhal lazeena aamanoo laa tuhilloo sha'aaa 'iral laahi wa lash Shahral Haraama wa lal hadya wa lal qalaaa'ida wa laa aaammeenal Baital Haraama yabtaghoona fadlam mir Rabbihim wa ridwaanaa; wa izaa halaltum fastaadoo; wa laa yajrimannakum shana aanu qawmin an saddookum 'anil Masjidil-Haraami an ta'tadoo; wa ta'aawanoo 'alalbirri wattaqwaa; wa laa ta'aawanoo 'alal ismi wal'udwaan; wattaqul laah; innal laaha shadeedul 'iqaab", "translation": "O you who have believed, do not violate the rites of Allah or [the sanctity of] the sacred month or [neglect the marking of] the sacrificial animals and garlanding [them] or [violate the safety of] those coming to the Sacred House seeking bounty from their Lord and [His] approval. But when you come out of ihram, then [you may] hunt. And do not let the hatred of a people for having obstructed you from al-Masjid al-Haram lead you to transgress. And cooperate in righteousness and piety, but do not cooperate in sin and aggression. And fear Allah; indeed, Allah is severe in penalty."}, {"ayah": 3, "translit": "Hurrimat 'alaikumul maitatu waddamu wa lahmul khinzeeri wa maaa uhilla lighiril laahi bihee walmun khani qatu wal mawqoozatu wal mutarad diyatu wanna teehatu wa maaa akalas sabu'u illaa maa zakkaitum wa maa zubiha 'alan nusubi wa an tastaqsimoo bil azlaam; zaalikum fisq; alyawma ya'isal lazeena kafaroo min deenikum falaa takhshawhum wakh shawn; alyawma akmaltu lakum deenakum wa atmamtu 'alaikum ni'matee wa radeetu lakumul Islaama deenaa; famanidturra fee makhmasatin ghaira mutajaanifil li ismin fa innallaaha Ghafoorur Raheem", "translation": "Prohibited to you are dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah, and [those animals] killed by strangling or by a violent blow or by a head-long fall or by the goring of horns, and those from which a wild animal has eaten, except what you [are able to] slaughter [before its death], and those which are sacrificed on stone altars, and [prohibited is] that you seek decision through divining arrows. That is grave disobedience. This day those who disbelieve have despaired of [defeating] your religion; so fear them not, but fear Me. This day I have perfected for you your religion and completed My favor upon you and have approved for you Islam as religion. But whoever is forced by severe hunger with no inclination to sin - then indeed, Allah is Forgiving and Merciful."}, {"ayah": 4, "translit": "Yas'aloonaka maazaaa uhilla lahum; qul uhilla lakumuttaiyibaatu wa maa'allamtum minal jawaarihi mukallibeena tu'allimoonahunnamimmaa 'allamakumul laahu fakuloo mimmaaa amsakna 'alaikum wazkurus mal laahi 'alaih; wattaqul laah; innal laaha saree'ul hisaab", "translation": "They ask you, [O Muhammad], what has been made lawful for them. Say, \"Lawful for you are [all] good foods and [game caught by] what you have trained of hunting animals which you train as Allah has taught you. So eat of what they catch for you, and mention the name of Allah upon it, and fear Allah.\" Indeed, Allah is swift in account."}, {"ayah": 5, "translit": "Alyawma uhilla lakumut taiyibaatu wa ta'aamul lazeena ootul Kitaaba hillul lakum wa ta'aamukum hillul lahum wal muhsanaatu minal mu'minaati walmuhsanaatu minal lazeena ootul Kitaaba min qablikum izaaa aataitumoohunna ujoorahunna muhsineena ghaira musaafiheena wa laa muttakhizeee akhdaan; wa mai yakfur bil eemaani faqad habita 'amaluhoo wa huwa fil Aaakhirati minal khaasireen", "translation": "This day [all] good foods have been made lawful, and the food of those who were given the Scripture is lawful for you and your food is lawful for them. And [lawful in marriage are] chaste women from among the believers and chaste women from among those who were given the Scripture before you, when you have given them their due compensation, desiring chastity, not unlawful sexual intercourse or taking [secret] lovers. And whoever denies the faith - his work has become worthless, and he, in the Hereafter, will be among the losers."}, {"ayah": 6, "translit": "Yaaa aiyuhal lazeena aamanoo izaa qumtum ilas Salaati faghsiloo wujoohakum wa Aidiyakum ilal maraafiqi wamsahoo biru'oosikum wa arjulakum ilal ka'bayn; wa in kuntum junuban fattahharoo; wain kuntum mardaaa aw'alaa safarin aw jaaa'a ahadum minkum minal ghaaa'iti aw laamastumunnisaaa'a falam tajidoo maaa'an fatayammamoo sa'eedan taiyiban famsahoo biwujoohikum wa aideekum minh; ma yureedul laahu liyaj'ala 'alaikum min harajinw wa laakidy yureedu liyutahhirakum wa liyutimma ni'matahoo 'alaikum la'allakum tashkuroon", "translation": "O you who have believed, when you rise to [perform] prayer, wash your faces and your forearms to the elbows and wipe over your heads and wash your feet to the ankles. And if you are in a state of janabah, then purify yourselves. But if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and do not find water, then seek clean earth and wipe over your faces and hands with it. Allah does not intend to make difficulty for you, but He intends to purify you and complete His favor upon you that you may be grateful."}, {"ayah": 7, "translit": "Wazkuroo ni'matal laahi 'alaikum wa meesaaqahul lazee waasaqakum biheee iz qultum sami'naa wa ata'naa wattaqul laah; innal laaha 'aleemum bizaatis sudoor", "translation": "And remember the favor of Allah upon you and His covenant with which He bound you when you said, \"We hear and we obey\"; and fear Allah. Indeed, Allah is Knowing of that within the breasts."}, {"ayah": 8, "translit": "Yaaa aiyuhal lazeena aamaanoo koonoo qawwaa meena lillaahi shuhadaaa'a bilqist, wa laa yajrimannakum shana aanu qawmin 'alaaa allaa ta'diloo; i'diloo; huwa aqrabu littaqwaa wattaqul laah; innal laaha khabeerum bimaa ta'maloon", "translation": "O you who have believed, be persistently standing firm for Allah, witnesses in justice, and do not let the hatred of a people prevent you from being just. Be just; that is nearer to righteousness. And fear Allah; indeed, Allah is Acquainted with what you do."}, {"ayah": 9, "translit": "Wa'adal laahul lazeena aamanoo wa 'amilus saalihaati lahum maghfiratunw wa ajrun 'azeem", "translation": "Allah has promised those who believe and do righteous deeds [that] for them there is forgiveness and great reward."}, {"ayah": 10, "translit": "Wallazeena kafaroo wa kazzaboo bi Aayaatinaaa ulaaa'ika Ashaabul Jaheem", "translation": "But those who disbelieve and deny Our signs - those are the companions of Hellfire."}, {"ayah": 11, "translit": "Yaa aiyuhal lazeena aamanuz kuroo ni'matallaahi 'alaikum iz hamma qawmun ai yabsutooo ilaikum aidiyahm fakaffa aidiyahum 'ankum wattaqullaah; wa'alal laahi fal yatawakalil mu'minoon", "translation": "O you who have believed, remember the favor of Allah upon you when a people determined to extend their hands [in aggression] against you, but He withheld their hands from you; and fear Allah. And upon Allah let the believers rely."}, {"ayah": 12, "translit": "Wa laqad akhazal laahu meesaaqa Banee Israaa'eela wa ba'sanaa minhumus nai 'ashara naqeebanw wa qaalal laahu innee ma'akum la'in aqamtumus Salaata wa aataitumuz Zakaata wa aamantum bi Rusulee wa'azzartumoohum wa aqradtumul laaha qardan hasanal la ukaffiranna 'ankum saiyiaatikum wa la udkhilan nakum Jannaatin tajree min tahtihal anhaar; faman kafara ba'da zaalika minkum faqad dalla sawaaa'as Sabeel", "translation": "And Allah had already taken a covenant from the Children of Israel, and We delegated from among them twelve leaders. And Allah said, \"I am with you. If you establish prayer and give zakah and believe in My messengers and support them and loan Allah a goodly loan, I will surely remove from you your misdeeds and admit you to gardens beneath which rivers flow. But whoever of you disbelieves after that has certainly strayed from the soundness of the way.\""}, {"ayah": 13, "translit": "Fabimaa naqdihim meesaa qahum la'annaahum wa ja'alnaa quloobahum qaasiyatai yuharrifoonal kalima 'ammawaadi'ihee wa nasoo hazzam mimmaa zukkiroo bih; wa laa tazaalu tatali'u 'alaa khaaa'inatim minhum illaa qaleelam minhum", "translation": "So for their breaking of the covenant We cursed them and made their hearts hard. They distort words from their [proper] usages and have forgotten a portion of that of which they were reminded. And you will still observe deceit among them, except a few of them. But pardon them and overlook [their misdeeds]. Indeed, Allah loves the doers of good."}, {"ayah": 14, "translit": "Wa minal lazeena qaalooo innaa nasaaraaa akhaznaa meesaaqahum fanasoo hazzam mimmaa zukkiroo bihee fa aghrainaa binahumul 'adaawata walbaghdaaa'a ilaa yawmil Qiyaamah; wa sawfa yunabbi'uhumul laahu bimaa kaanoo yasna'oon", "translation": "And from those who say, \"We are Christians\" We took their covenant; but they forgot a portion of that of which they were reminded. So We caused among them animosity and hatred until the Day of Resurrection. And Allah is going to inform them about what they used to do."}, {"ayah": 15, "translit": "yaaa Ahlal kitaabi qad jaaa'akum Rasoolunaa yubaiyinu lakum kaseeram mimmmaa kuntum tukhfoona minal Kitaabi wa ya'foo 'an kaseer; qad jaaa'akum minal laahi noorunw wa Kitaabum Mubeen", "translation": "O People of the Scripture, there has come to you Our Messenger making clear to you much of what you used to conceal of the Scripture and overlooking much. There has come to you from Allah a light and a clear Book."}, {"ayah": 16, "translit": "Yahdee bihil laahu manit taba'a ridwaanahoo subulas salaami wa yukhrijuhum minaz zulumaati ilan noori bi iznihee wa yahdeehim ilaa Siraatim Mustaqeem", "translation": "By which Allah guides those who pursue His pleasure to the ways of peace and brings them out from darknesses into the light, by His permission, and guides them to a straight path."}, {"ayah": 17, "translit": "Laqad kafaral lazeena qaalooo innal laaha huwal maseehub nu Maryam; qul famany-yamliku minal laahi shai'an in araada ai yuhlikal Maseehab na Maryama wa ummahoo wa man fil ardi jamee'aa, wa lillaahi mmulkus samaawaati wal ardi wa maa bainahumaa; yakhluqu maa Yashaaa'; wallaahu 'alaa kulli shai'in Qadeer", "translation": "They have certainly disbelieved who say that Allah is Christ, the son of Mary. Say, \"Then who could prevent Allah at all if He had intended to destroy Christ, the son of Mary, or his mother or everyone on the earth?\" And to Allah belongs the dominion of the heavens and the earth and whatever is between them. He creates what He wills, and Allah is over all things competent."}, {"ayah": 18, "translit": "Wa qaalatil Yahoodu wan Nasaaraa nahnu abnaaa'ul laahi wa ahibbaaa'uh; qul falima yu'azzibukum bizunoobikum bal antum basharum mimmman khalaq; yaghfiru limai yashaaa'u wa yu'azzibu mai yashaaa'; wa lillaahi mulkus samaawaati wal ardi wa maa bainahumaa wa ilaihil maseer", "translation": "But the Jews and the Christians say, \"We are the children of Allah and His beloved.\" Say, \"Then why does He punish you for your sins?\" Rather, you are human beings from among those He has created. He forgives whom He wills, and He punishes whom He wills. And to Allah belongs the dominion of the heavens and the earth and whatever is between them, and to Him is the [final] destination."}, {"ayah": 19, "translit": "Yaaa Ahlal Kitaabi qad jaaa'akum Rasoolunaa yubaiyinu lakum 'alaa fatratim minal Rusuli an taqooloo maa jaaa'anaa mim basheerinw wa laa nazeerin faqad jaaa'akum basheerunw wa nazeer; wallaahu 'alaa kulli shai'in Qadeer", "translation": "O People of the Scripture, there has come to you Our Messenger to make clear to you [the religion] after a period [of suspension] of messengers, lest you say, \"There came not to us any bringer of good tidings or a warner.\" But there has come to you a bringer of good tidings and a warner. And Allah is over all things competent."}, {"ayah": 20, "translit": "Wa iz qaala Moosaa liqawmihee yaa qawmiz kuroo ni'matal laahi 'alaikum iz ja'ala feekum ambiyaaa'a wa ja'alakum mulookanw wa aataakum maa lam yu'ti ahadam minal 'aalameen", "translation": "And [mention, O Muhammad], when Moses said to his people, \"O my people, remember the favor of Allah upon you when He appointed among you prophets and made you possessors and gave you that which He had not given anyone among the worlds."}, {"ayah": 21, "translit": "Yaa qawmid khulul Ardal MMuqaddasatal latee katabal laahu lakum wa laa tartaddoo 'alaaa adbaarikum fatanqaliboo khaasireen", "translation": "O my people, enter the Holy Land which Allah has assigned to you and do not turn back [from fighting in Allah 's cause] and [thus] become losers.\""}, {"ayah": 22, "translit": "Qaaloo yaa Moosaaa innaa feehaa qawman jabbaareena wa innaa lan nadkhulahaa hattaa yakhrujoo minhaa fa-iny yakhrujoo minhaa fa innaa daakhiloon", "translation": "They said, \"O Moses, indeed within it is a people of tyrannical strength, and indeed, we will never enter it until they leave it; but if they leave it, then we will enter.\""}, {"ayah": 23, "translit": "Qaala rajulaani minal lazeena yakhaafoona an'amal laahu 'alaihimad khuloo 'alaihimul baab, fa izaa dakhaltumoohu fa innakum ghaaliboon; wa 'alal laahi fatawakkalooo in kuntum mu'mineen", "translation": "Said two men from those who feared [to disobey] upon whom Allah had bestowed favor, \"Enter upon them through the gate, for when you have entered it, you will be predominant. And upon Allah rely, if you should be believers.\""}, {"ayah": 24, "translit": "Qaaloo yaa Moosaaa innaa lan nadkhulahaa abadam maa daamoo feehaa fazhab anta wa Rabbuka faqaatilaaa innaa haahunaa qaa'idoon", "translation": "They said, \"O Moses, indeed we will not enter it, ever, as long as they are within it; so go, you and your Lord, and fight. Indeed, we are remaining right here.\""}, {"ayah": 25, "translit": "Qaala Rabbi innee laaa amliku illaa nafsee wa akhee fafruq bainanaa wa bainal qawmil faasiqeen", "translation": "[Moses] said, \"My Lord, indeed I do not possess except myself and my brother, so part us from the defiantly disobedient people.\""}, {"ayah": 26, "translit": "Qaala fa innahaa muhar ramatun 'alaihim arba'eena sanah; yateehoona fil ard; falaa taasa 'alal qawmil faasiqeen", "translation": "[Allah] said, \"Then indeed, it is forbidden to them for forty years [in which] they will wander throughout the land. So do not grieve over the defiantly disobedient people.\""}, {"ayah": 27, "translit": "Watlu 'alaihim naba abnai Aadama bilhaqq; iz qarrabaa qurbaanan fatuqubbila min ahadihimaa wa lam yutaqabbal minal aakhari qaala la aqtulannnaka qaala innamaa yataqabbalul laahu minal muttaqeen", "translation": "And recite to them the story of Adam's two sons, in truth, when they both offered a sacrifice [to Allah], and it was accepted from one of them but was not accepted from the other. Said [the latter], \"I will surely kill you.\" Said [the former], \"Indeed, Allah only accepts from the righteous [who fear Him]."}, {"ayah": 28, "translit": "La'im basatta ilaiya yadaka litaqtulanee maaa ana bibaasitiny yadiya ilaika li aqtulaka inneee akhaaful laaha Rabbal 'aalameen", "translation": "If you should raise your hand against me to kill me - I shall not raise my hand against you to kill you. Indeed, I fear Allah, Lord of the worlds."}, {"ayah": 29, "translit": "Inee ureedu an tabooo'a bi ismee wa ismika fatakoona min Ashaabin Naar; wa zaalika jazaaa'uz zaalimeen", "translation": "Indeed I want you to obtain [thereby] my sin and your sin so you will be among the companions of the Fire. And that is the recompense of wrongdoers.\""}, {"ayah": 30, "translit": "Fatawwa'at lahoo nafsu hoo qatla akheehi faqatalahoo fa asbaha minal khaasireen", "translation": "And his soul permitted to him the murder of his brother, so he killed him and became among the losers."}, {"ayah": 31, "translit": "Faba'asal laahu ghuraabai yabhasu fil ardi liyuriyahoo kaifa yuwaaree sawata akheeh; qaala yaa wailataaa a'ajaztu an akoona misla haazal ghuraabi fa uwaariya saw ata akhee fa asbaha minan naadimeen", "translation": "Then Allah sent a crow searching in the ground to show him how to hide the disgrace of his brother. He said, \"O woe to me! Have I failed to be like this crow and hide the body of my brother?\" And he became of the regretful."}, {"ayah": 32, "translit": "min ajli zaalika katabnaa 'alaa Banee Israaa'eela annahoo man qatala nnafsam bighairi nafsin aw fasaadin fil ardi faka annammaa qatalan naasa jamee'anw wa man ahyaahaa faka annamaaa ahyan naasa jamee'aa; wa laqad jaaa'at hum Rusulunaa bilbaiyinaati summa inna kaseeram minhum ba'da zaalika fil ardi lamusrifoon", "translation": "Because of that, We decreed upon the Children of Israel that whoever kills a soul unless for a soul or for corruption [done] in the land - it is as if he had slain mankind entirely. And whoever saves one - it is as if he had saved mankind entirely. And our messengers had certainly come to them with clear proofs. Then indeed many of them, [even] after that, throughout the land, were transgressors."}, {"ayah": 33, "translit": "Innamaa jazaaa'ul lazeena yuhaariboonal laaha wa Rasoolahoo wa yas'awna fil ardi fasaadan ai yuqattalooo aw yusallabooo aw tuqatta'a aideehim wa arjuluhum min khilaafin aw yunfaw minalard; zaalika lahum khizyun fid dunyaa wa lahum fil Aakhirati 'azaabun 'azeem", "translation": "Indeed, the penalty for those who wage war against Allah and His Messenger and strive upon earth [to cause] corruption is none but that they be killed or crucified or that their hands and feet be cut off from opposite sides or that they be exiled from the land. That is for them a disgrace in this world; and for them in the Hereafter is a great punishment,"}, {"ayah": 34, "translit": "Illal lazeena taaboo min qabli an taqdiroo 'alaihim fa'lamooo annnal laaha Ghafoorur Raheem", "translation": "Except for those who return [repenting] before you apprehend them. And know that Allah is Forgiving and Merciful."}, {"ayah": 35, "translit": "yaaa aiyuhal lazeena aamanut taqul laaha wabtaghooo ilaihil waseelata wa jaahidoo fee sabeelihee la'allakum tuflihoon", "translation": "O you who have believed, fear Allah and seek the means [of nearness] to Him and strive in His cause that you may succeed."}, {"ayah": 36, "translit": "Innal lazeena kafaroo law anna lahum maa fil ardi jamee'anw wa mislahoo ma'ahoo liyaftadoo bihee min 'azaabi Yawmil Qiyaamati maa tuqubbila minhum wa lahum azaabun aleem", "translation": "Indeed, those who disbelieve - if they should have all that is in the earth and the like of it with it by which to ransom themselves from the punishment of the Day of Resurrection, it will not be accepted from them, and for them is a painful punishment"}, {"ayah": 37, "translit": "Yureedoona ai yakhrujoo minan Naari wa maa hum bikhaari jeena minhaa wa lahum 'azaabum muqeem", "translation": "They will wish to get out of the Fire, but never are they to emerge therefrom, and for them is an enduring punishment."}, {"ayah": 38, "translit": "Wassaariqu wassaariqatu faqta'oo aidiyahumma jazaaa'am bimaa kasabaa nakaalam minal laah; wallaahu 'Azeezun hakeem", "translation": "[As for] the thief, the male and the female, amputate their hands in recompense for what they committed as a deterrent [punishment] from Allah. And Allah is Exalted in Might and Wise."}, {"ayah": 39, "translit": "Faman taaba mim ba'di zulmihee wa aslaha fa innal laaha yatoobu 'alaih; innal laaha Ghafoorur Raheem", "translation": "But whoever repents after his wrongdoing and reforms, indeed, Allah will turn to him in forgiveness. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 40, "translit": "Alam ta'lam annal laaha lahoo mulkus samaawaati wal ardi yu'az zibu many-yashaa'u wa yaghfiru limany-yashaaa'; wallaahu 'alaa kulli shai'in Qadeer", "translation": "Do you not know that to Allah belongs the dominion of the heavens and the earth? He punishes whom He wills and forgives whom He wills, and Allah is over all things competent."}, {"ayah": 41, "translit": "Yaaa ayyuhar Rasoolu laa yahzukal lazeena yusaa ri'oona fil kufri minal lazeena qaaloo aamannaa bi afwaahihim wa lam tu'min quloobuhum; wa minal lazeena haadoo sammaa'oona lilkazibi sammaa'oona liqawmin aakhareena lam yaatooka yuharifoonal kalima mim ba'di mawaadi'ihee yaqooloona in ooteetum haazaa fakhuzoohu wa il lam tu'tawhu fahzaroo; wa many-yuridil laahu fitnatahoo falan tamlika lahoo minal laahi shai'aa; ulaaa 'ikal lazeena lam yuridil laahu any-yutahhira quloobahum; lahum fid dunyaa khizyunw wa lahum fil Aakhirati'azaabun 'azeem", "translation": "O Messenger, let them not grieve you who hasten into disbelief of those who say, \"We believe\" with their mouths, but their hearts believe not, and from among the Jews. [They are] avid listeners to falsehood, listening to another people who have not come to you. They distort words beyond their [proper] usages, saying \"If you are given this, take it; but if you are not given it, then beware.\" But he for whom Allah intends fitnah - never will you possess [power to do] for him a thing against Allah. Those are the ones for whom Allah does not intend to purify their hearts. For them in this world is disgrace, and for them in the Hereafter is a great punishment."}, {"ayah": 42, "translit": "Sammaa'oona lilkazibi akkaaloona lissuht; fa in jaaa'ooka fahkum bainahum aw a'rid anhum wa in tu'rid 'anhum falany-yadurrooka shai'anw wa in hakamta fahkum bainahum bilqist; innal laaha yuhibbul muqsiteen", "translation": "[They are] avid listeners to falsehood, devourers of [what is] unlawful. So if they come to you, [O Muhammad], judge between them or turn away from them. And if you turn away from them - never will they harm you at all. And if you judge, judge between them with justice. Indeed, Allah loves those who act justly."}, {"ayah": 43, "translit": "Wa kaifa yuhakkimoonaka wa 'indahumut Tawraatu feehaa hukmul laahi summa yatawallawna mim ba'di zaalik; wa maaa ulaaa'ika bilmu'mineen", "translation": "But how is it that they come to you for judgement while they have the Torah, in which is the judgement of Allah? Then they turn away, [even] after that; but those are not [in fact] believers."}, {"ayah": 44, "translit": "Innaaa anzalnat Tawraata feehaa hudanw wa noor; yahkumu bihan Nabiyyoonal lazeena aslamoo lillazeena haadoo war rabbaaniyyoona wal ahbaaru bimas tuhfizoo min Kitaabil laahi wa kaanoo 'alaihi shuhadaaa'; falaa takhshawun naasa wakhshawni wa laa tashtaroo bi aayaatee samanan qaleelaa; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa'ika humul kaafiroon", "translation": "Indeed, We sent down the Torah, in which was guidance and light. The prophets who submitted [to Allah] judged by it for the Jews, as did the rabbis and scholars by that with which they were entrusted of the Scripture of Allah, and they were witnesses thereto. So do not fear the people but fear Me, and do not exchange My verses for a small price. And whoever does not judge by what Allah has revealed - then it is those who are the disbelievers."}, {"ayah": 45, "translit": "Wa katabnaa 'alaihim feehaaa annan nafsa binnafsi wal'aina bil'aini wal anfa bilanfi wal uzuna bil uzuni wassinna bissinni waljurooha qisaas; faman tasaddaqa bihee fahuwa kaffaaratul lah; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa'ika humuz zalimoon", "translation": "And We ordained for them therein a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth, and for wounds is legal retribution. But whoever gives [up his right as] charity, it is an expiation for him. And whoever does not judge by what Allah has revealed - then it is those who are the wrongdoers."}, {"ayah": 46, "translit": "Wa qaffainaa 'alaaa aasaaarihim bi 'Eesab ni Maryama musaddiqal limaa baina yadihi minat Tawraati wa aatainaahul Injeela feehi hudanw wa noorunw wa musaddiqal limaa baina yadaihi minat Tawraati wa hudanw wa maw'izatal lilmuttaqeen", "translation": "And We sent, following in their footsteps, Jesus, the son of Mary, confirming that which came before him in the Torah; and We gave him the Gospel, in which was guidance and light and confirming that which preceded it of the Torah as guidance and instruction for the righteous."}, {"ayah": 47, "translit": "Walyahkum Ahlul Injeeli bimaaa anzalal laahu feeh; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa'ika humul faasiqoon", "translation": "And let the People of the Gospel judge by what Allah has revealed therein. And whoever does not judge by what Allah has revealed - then it is those who are the defiantly disobedient."}, {"ayah": 48, "translit": "Wa anzalnaa ilaikal Kitaaba bilhaqqi musaddiqallimaa baina yadaihi minal Kitaabi wa muhaiminan 'alaihi fahkum bainahum bimaa anzalal laahu wa laa tattabi ahwaaa'ahum 'ammaa jaaa'aka minal haqq; likullin ja'alnaa minkum shir'atanw wa minhaajaa; wa law shaaa'al laahu laja'alakum ummatanw waahidatanw wa laakil liyabluwakum fee maa aataakum fastabiqul khairaat; ilal laahi arji'ukum jamee'an fayunab bi'ukum bimaa kuntum feehi takhtalifoon", "translation": "And We have revealed to you, [O Muhammad], the Book in truth, confirming that which preceded it of the Scripture and as a criterion over it. So judge between them by what Allah has revealed and do not follow their inclinations away from what has come to you of the truth. To each of you We prescribed a law and a method. Had Allah willed, He would have made you one nation [united in religion], but [He intended] to test you in what He has given you; so race to [all that is] good. To Allah is your return all together, and He will [then] inform you concerning that over which you used to differ."}, {"ayah": 49, "translit": "Wa anih kum bainahum bimaaa anzalal laahu wa laa tattabi' ahwaaa'ahum wahzarhum ai yaftinooka 'am ba'di maaa anzalal laahu ilaika fa in tawallaw fa'lam annamaa yureedul laahu ai yuseebahum biba'di zunoobihim; wa inna kaseeram minan naasi lafaasiqoon", "translation": "And judge, [O Muhammad], between them by what Allah has revealed and do not follow their inclinations and beware of them, lest they tempt you away from some of what Allah has revealed to you. And if they turn away - then know that Allah only intends to afflict them with some of their [own] sins. And indeed, many among the people are defiantly disobedient."}, {"ayah": 50, "translit": "Afahukmal jaahiliyyati yabghoon; wa man ahsanu minal laahi hukmal liqawminy yooqinoon", "translation": "Then is it the judgement of [the time of] ignorance they desire? But who is better than Allah in judgement for a people who are certain [in faith]."}, {"ayah": 51, "translit": "Yaaa aiyuhal lazeena aamanoo laa tattakhizul Yahooda wan nasaaraaa awliyaaa'; ba'duhum awliyaaa'u ba'd; wa mai yatawallahum minkum fa innahoo minhum; innal laaha laa yahdil qawmaz zaalimeen", "translation": "O you who have believed, do not take the Jews and the Christians as allies. They are [in fact] allies of one another. And whoever is an ally to them among you - then indeed, he is [one] of them. Indeed, Allah guides not the wrongdoing people."}, {"ayah": 52, "translit": "Fataral lazeena fee quloobihim maraduny yusaari'oona feehim yaqooloona nakhshaaa an tuseebanaa daaa'irah; fa'asallaahu ai yaatiya bilfathi aw amrim min 'indihee fa yusbihoo 'alaa maaa asarroo feee anfusihim naadimeen", "translation": "So you see those in whose hearts is disease hastening into [association with] them, saying, \"We are afraid a misfortune may strike us.\" But perhaps Allah will bring conquest or a decision from Him, and they will become, over what they have been concealing within themselves, regretful."}, {"ayah": 53, "translit": "Wa yaqoolul lazeena aamanooo ahaaa'ulaaa'il lazeena aqsamoo billaahi jahda aimaanihim innahum lama'akum; habitat a'maaluhum fa asbahoo khaasireen", "translation": "And those who believe will say, \"Are these the ones who swore by Allah their strongest oaths that indeed they were with you?\" Their deeds have become worthless, and they have become losers."}, {"ayah": 54, "translit": "Yaa aiyuhal lazeena aamanoo mai yartadda minkum 'an deenihee fasawfa yaatil laahu biqawminy yuhibbuhum wa yuhibboonahoo azillatin 'alal mu'mineena a'izzatin 'alal kaafireena yujaahidoona fee sabeelil laahi wa laa yakhaafoona lawmata laaa'im; zaalika fadlul laahi yu'teehi mai yashaaa'; wallaahu Waasi'un 'Aleem", "translation": "O you who have believed, whoever of you should revert from his religion - Allah will bring forth [in place of them] a people He will love and who will love Him [who are] humble toward the believers, powerful against the disbelievers; they strive in the cause of Allah and do not fear the blame of a critic. That is the favor of Allah; He bestows it upon whom He wills. And Allah is all-Encompassing and Knowing."}, {"ayah": 55, "translit": "Innamaa waliyyukumul laahu wa Rasooluhoo wal lazeena aamanul lazeena yuqeemoonas Salaata wa yu'toonaz Zakaata wa hum raaki'oon", "translation": "Your ally is none but Allah and [therefore] His Messenger and those who have believed - those who establish prayer and give zakah, and they bow [in worship]."}, {"ayah": 56, "translit": "Wa mai yatawallal laaha wa Rasoolahoo wallazeena aamanoo fa inna hizbal laahi humul ghaaliboon", "translation": "And whoever is an ally of Allah and His Messenger and those who have believed - indeed, the party of Allah - they will be the predominant."}, {"ayah": 57, "translit": "Yaaa aiyuhal lazeena aamanoo laa tattakhizul lazeenat takhazoo deenakum huzuwanw wa la'ibam minal lazeena ootul Kitaaba min qablikum walkuffaara awliyaaa'; wattaqul laaha in kuntum muu'mineen", "translation": "O you who have believed, take not those who have taken your religion in ridicule and amusement among the ones who were given the Scripture before you nor the disbelievers as allies. And fear Allah, if you should [truly] be believers."}, {"ayah": 58, "translit": "Wa izaa naadaitum ilas Salaatit takhazoohaa huzu wan'w wa la'ibaa; zaalika biannnahum qawmul laa ya'qiloon", "translation": "And when you call to prayer, they take it in ridicule and amusement. That is because they are a people who do not use reason."}, {"ayah": 59, "translit": "Qul yaaa Ahlal Kitaabi hal tanqimoona minnaaa illaaa an aamannaa billaahi wa maaa unzila ilainaa wa maa unzila min qablu wa annna aksarakum faasiqoon", "translation": "Say, \"O People of the Scripture, do you resent us except [for the fact] that we have believed in Allah and what was revealed to us and what was revealed before and because most of you are defiantly disobedient?\""}, {"ayah": 60, "translit": "Qul hal unabbi'ukum bisharrim min zaalika masoobatan 'indal laah; malla'ana hul laahu wa ghadiba 'alaihi wa ja'ala minhumul qiradata wal khanaazeera wa 'abadat Taaghoot; ulaaa'ika sharrum makaananw wa adallu 'an Sawaaa'is Sabeel", "translation": "Say, \"Shall I inform you of [what is] worse than that as penalty from Allah? [It is that of] those whom Allah has cursed and with whom He became angry and made of them apes and pigs and slaves of Taghut. Those are worse in position and further astray from the sound way.\""}, {"ayah": 61, "translit": "Wa izaa jaaa'ookum qaalooo aamannaa wa qad dakhaloo bilkufri wa hum qad kharajoo bih; wallaahu a'lamu bimaa kaanoo yaktumoon", "translation": "And when they come to you, they say, \"We believe.\" But they have entered with disbelief [in their hearts], and they have certainly left with it. And Allah is most knowing of what they were concealing."}, {"ayah": 62, "translit": "Wa taraa kaseeram minhum yusaari'oona fil ismi wal'udwaani wa aklihimus suht; labi'sa maa kaanoo ya'maloon", "translation": "And you see many of them hastening into sin and aggression and the devouring of [what is] unlawful. How wretched is what they have been doing."}, {"ayah": 63, "translit": "Law laa yanhaahumur rabbaaniyyoona wal ahbaaru 'an qawlihimul ismaa wa aklihimus suht; labi'sa maa kaanoo yasna'oon", "translation": "Why do the rabbis and religious scholars not forbid them from saying what is sinful and devouring what is unlawful? How wretched is what they have been practicing."}, {"ayah": 64, "translit": "Wa qaalatil Yahoodu Yadullaahi maghloolah; ghulla aideehim wa lu'inoo bimaa qaaloo; bal yadaahu mabsoo tataani yunfiqu kaifa yashaaa'; wa la yazeedanna kaseeramm minhum maaa unzila ilaika mir Rabbika tughyaananw wa kufraa; wa alqainaa bainahumul 'adaawata wal baghdaaa a' ilaa Yawmil Qiyaamah; kullamaaa awqadoo naaral lilharbi at fa-ahal laah; wa yas'awna fil ardi fasaadaa; wal laahu laa yuhibbul mufsideen", "translation": "And the Jews say, \"The hand of Allah is chained.\" Chained are their hands, and cursed are they for what they say. Rather, both His hands are extended; He spends however He wills. And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. And We have cast among them animosity and hatred until the Day of Resurrection. Every time they kindled the fire of war [against you], Allah extinguished it. And they strive throughout the land [causing] corruption, and Allah does not like corrupters."}, {"ayah": 65, "translit": "Wa law anna Ahlal Kitaabi aamanoo wattaqaw lakaffarnaa 'anhum saiyiaatihim wa la adkhalnaahu Jannaatin Na'eem", "translation": "And if only the People of the Scripture had believed and feared Allah, We would have removed from them their misdeeds and admitted them to Gardens of Pleasure."}, {"ayah": 66, "translit": "Wa law annahum aqaamut Tawraata wal Injeela wa maaa unzila ilaihim mir Rabbihim la akaloo min fawqihim wa min tahti arjulihim; minhum ummatum muqta sidatunw wa kaseerum minhum saaa'a maa ya'maloon", "translation": "And if only they upheld [the law of] the Torah, the Gospel, and what has been revealed to them from their Lord, they would have consumed [provision] from above them and from beneath their feet. Among them are a moderate community, but many of them - evil is that which they do."}, {"ayah": 67, "translit": "Yaaa aiyuhar Rasoolu balligh maaa unzila ilaika mir Rabbika wa il lam taf'al famaaa ballaghta Risaalatah; wallaahu ya'simuka minan naas; innal laaha laa yahdil qawmal kaafireen", "translation": "O Messenger, announce that which has been revealed to you from your Lord, and if you do not, then you have not conveyed His message. And Allah will protect you from the people. Indeed, Allah does not guide the disbelieving people."}, {"ayah": 68, "translit": "Qul yaaa Ahlal Kitaabi lastum 'alaa shai'in hattaa tuqeemut Tawraata wal Injeela wa maaa unzila ilaikum mir Rabbikum; wa layazeedanna kaseeram minhum maa unzila ilaika mir Rabbika tugh yaananw wa kufran falaa taasa 'alal qawmil kaafireen", "translation": "Say, \"O People of the Scripture, you are [standing] on nothing until you uphold [the law of] the Torah, the Gospel, and what has been revealed to you from your Lord.\" And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. So do not grieve over the disbelieving people."}, {"ayah": 69, "translit": "Innal lazeena aamanoo wallazeena haadoo was saabi'oona wan Nasaaraa man aamana billaahi wal yawmil Aakhiri wa 'amila saalihan falaa khawfun 'alaihim wa laa hum yahzanoon", "translation": "Indeed, those who have believed [in Prophet Muhammad] and those [before Him] who were Jews or Sabeans or Christians - those [among them] who believed in Allah and the Last Day and did righteousness - no fear will there be concerning them, nor will they grieve."}, {"ayah": 70, "translit": "Laqad akhaznaa meesaaqa Banee Israaa'eela wa arsalnaaa ilaihim Rusulan kullamaa jaaa'ahum Rasoolum bimaa laa tahwaaa anfusuhum fareeqan kazzaboo wa fareeqany yaqtuloon", "translation": "We had already taken the covenant of the Children of Israel and had sent to them messengers. Whenever there came to them a messenger with what their souls did not desire, a party [of messengers] they denied, and another party they killed."}, {"ayah": 71, "translit": "Wa hasibooo allaa takoona fitnaun fa'amoo wa sammoo summa taabal laahu 'alaihim summa 'amoo wa sammoo kaseerum minhum; wallaahu baseerum bimaa ya'maloon", "translation": "And they thought there would be no [resulting] punishment, so they became blind and deaf. Then Allah turned to them in forgiveness; then [again] many of them became blind and deaf. And Allah is Seeing of what they do."}, {"ayah": 72, "translit": "Laqad kafaral lazeena qaalooo innal laaha Huwal maseehub nu Maryama wa qaalal Maseehu yaa Baneee Israaa'eela u'budul laaha Rabbee wa Rabbakum innnahoo many-yushrik ballaahi faqad harramal laahu 'alaihil jannata wa maa waahun Naaru wa maa lizzaalimeena min ansaar", "translation": "They have certainly disbelieved who say, \"Allah is the Messiah, the son of Mary\" while the Messiah has said, \"O Children of Israel, worship Allah, my Lord and your Lord.\" Indeed, he who associates others with Allah - Allah has forbidden him Paradise, and his refuge is the Fire. And there are not for the wrongdoers any helpers."}, {"ayah": 73, "translit": "laqad kafaral lazeena qaalooo innal laaha saalisu salaasah; wa maa min ilaahin illaaa Ilaahunw Waahid; wa illam yantahoo 'ammaa yaqooloona layamas sannal lazeena kafaroo minhum 'azaabun aleem", "translation": "They have certainly disbelieved who say, \"Allah is the third of three.\" And there is no god except one God. And if they do not desist from what they are saying, there will surely afflict the disbelievers among them a painful punishment."}, {"ayah": 74, "translit": "Afalaa yatooboona ilal laahi wa yastaghfiroonah; wallaahu Ghafoorur Raheem", "translation": "So will they not repent to Allah and seek His forgiveness? And Allah is Forgiving and Merciful."}, {"ayah": 75, "translit": "Mal Maseehub nu Maryama illaa Rasoolun qad khalat min qablihir Rusulu wa ummuhoo siddeeqatun kaanaa yaa kulaanit ta'aam; unzur kaifa nubaiyinu lahumul Aayaati suman zur annaa yu'fakoon", "translation": "The Messiah, son of Mary, was not but a messenger; [other] messengers have passed on before him. And his mother was a supporter of truth. They both used to eat food. Look how We make clear to them the signs; then look how they are deluded."}, {"ayah": 76, "translit": "Qul ata'budoona min doonil laahi maa laa yamliku lakum darranw wa laa naf'aa; wallaahu Huwas Samee'ul 'Aleem", "translation": "Say, \"Do you worship besides Allah that which holds for you no [power of] harm or benefit while it is Allah who is the Hearing, the Knowing?\""}, {"ayah": 77, "translit": "Qul yaaa Ahlal Kitaabi laa taghloo fee deenikum ghairal haqqi wa laa tattabi'ooo ahwaaa'a qawmin qad dalloo min qablu wa adalloo kaseeranw wa dalloo 'an Sawaaa'is Sabeel", "translation": "Say, \"O People of the Scripture, do not exceed limits in your religion beyond the truth and do not follow the inclinations of a people who had gone astray before and misled many and have strayed from the soundness of the way.\""}, {"ayah": 78, "translit": "Lu'inal lazeena kafaroo mim Baneee israaa'eela 'alaa lisaani Daawooda wa 'Eesab ni Maryam; zaalika bimaa 'asaw wa kaanoo ya'tadoon", "translation": "Cursed were those who disbelieved among the Children of Israel by the tongue of David and of Jesus, the son of Mary. That was because they disobeyed and [habitually] transgressed."}, {"ayah": 79, "translit": "Kaanoo laa yatanaahawna 'am munkarin fa'aluhoo; labi'sa maa kaanoo yafa'loon", "translation": "They used not to prevent one another from wrongdoing that they did. How wretched was that which they were doing."}, {"ayah": 80, "translit": "Taraa kaseeram minhum yatawallawnal lazeena kafaroo; labi'sa maa qaddamat lahum anfusuhum an sakhital laahu 'alaihim wa fil 'azaabi hum khaalidoon", "translation": "You see many of them becoming allies of those who disbelieved. How wretched is that which they have put forth for themselves in that Allah has become angry with them, and in the punishment they will abide eternally."}, {"ayah": 81, "translit": "Wa law kaanoo yu'minoona billaahi wan nabiyyi wa maaa unzila ilaihi mattakhazoohum awliyaaa'a wa laakinna kaseeram minhum faasiqoon", "translation": "And if they had believed in Allah and the Prophet and in what was revealed to him, they would not have taken them as allies; but many of them are defiantly disobedient."}, {"ayah": 82, "translit": "Latajidanna ashad dan naasi 'adaawatal lillazeena aamanul Yahooda wallazeena ashrakoo wa latajidanna aqrabahum mawaddatal lil lazeena aamanul lazeena qaalooo innaa Nasaaraa; zaalika bi anna mminhum qiseeseena wa ruhbaananw wa annahum laa yastakbiroon", "translation": "You will surely find the most intense of the people in animosity toward the believers [to be] the Jews and those who associate others with Allah; and you will find the nearest of them in affection to the believers those who say, \"We are Christians.\" That is because among them are priests and monks and because they are not arrogant."}, {"ayah": 83, "translit": "Wa izaa sami'oo maaa unzila ilar Rasooli taraaa a'yunahum tafeedu minad dam'i mimmmaa 'arafoo minalhaqq; yaqooloona Rabbanaaa aamannaa faktubnaa ma'ash shaahideen", "translation": "And when they hear what has been revealed to the Messenger, you see their eyes overflowing with tears because of what they have recognized of the truth. They say, \"Our Lord, we have believed, so register us among the witnesses."}, {"ayah": 84, "translit": "Wa maa lanaa laa nu'minu billaahi wa maa jaaa'anaa minal haqqi wa natma'u ai yudkhilanaa Rabbunaa ma'al qawmis saaliheen", "translation": "And why should we not believe in Allah and what has come to us of the truth? And we aspire that our Lord will admit us [to Paradise] with the righteous people.\""}, {"ayah": 85, "translit": "Fa asaabahumul laahu bimaa qaaloo Jannnaatin tajree min tahtihal anhaaru khaalideena feehaa; wa zaalika jazaaa'ul muhsineen", "translation": "So Allah rewarded them for what they said with gardens [in Paradise] beneath which rivers flow, wherein they abide eternally. And that is the reward of doers of good."}, {"ayah": 86, "translit": "Wallazeena kafaroo wa kazzaboo bi Aayaatinaaa ulaaa'ika Ashaabul Jaheem", "translation": "But those who disbelieved and denied Our signs - they are the companions of Hellfire."}, {"ayah": 87, "translit": "Yaaa aiyuhal lazeena aamanoo laa tuharrimoo taiyibaati maaa ahallal laahu lakum wa laa ta'tadooo; innal laaha laa yuhibbul mu'tadeen", "translation": "O you who have believed, do not prohibit the good things which Allah has made lawful to you and do not transgress. Indeed, Allah does not like transgressors."}, {"ayah": 88, "translit": "Wa kuloo mimmaa razaqakumul laahu halaalan taiyibaa; wattaqul laahallazeee antum bihee mu'minon", "translation": "And eat of what Allah has provided for you [which is] lawful and good. And fear Allah, in whom you are believers."}, {"ayah": 89, "translit": "Laa yu'aakhizukumul laahu billaghwi feee aimaanikum wa laakiny ya'aakhizukum bimaa 'aqqattumul aimaana fakaf faaratuhooo it'aamu 'asharati masaakeena min awsati maa tut'imoona ahleekum aw kiswatuhum aw tahreeru raqabatin famallam yajid fa Siyaamu salaasati aiyaam; zaalika kaffaaratu aimaanikum izaa halaftum; wahfazooo aimaanakum; kazaalika yubaiyinul laahu lakum Aayaatihee la'allakum tashkuroon", "translation": "Allah will not impose blame upon you for what is meaningless in your oaths, but He will impose blame upon you for [breaking] what you intended of oaths. So its expiation is the feeding of ten needy people from the average of that which you feed your [own] families or clothing them or the freeing of a slave. But whoever cannot find [or afford it] - then a fast of three days [is required]. That is the expiation for oaths when you have sworn. But guard your oaths. Thus does Allah make clear to you His verses that you may be grateful."}, {"ayah": 90, "translit": "yaaa aiyuhal lazeena aamanooo innamal khamru walmaisiru wal ansaabu wal azlaamu rijsum min 'amalish shaitaani fajtaniboohu la'al lakum tuflihoon", "translation": "O you who have believed, indeed, intoxicants, gambling, [sacrificing on] stone alters [to other than Allah], and divining arrows are but defilement from the work of Satan, so avoid it that you may be successful."}, {"ayah": 91, "translit": "Innamaa yureedush Shaitaanu ai yooqi'a bainakumul 'adaawata wal baghdaaa'a fil khamri wal maisiri wa yasuddakum 'an zikril laahi wa 'anis Salaati fahal antum muntahoon", "translation": "Satan only wants to cause between you animosity and hatred through intoxicants and gambling and to avert you from the remembrance of Allah and from prayer. So will you not desist?"}, {"ayah": 92, "translit": "Wa atee'ul laaha wa atee'ur Rasoola wahzaroo; fa in tawal laitum fa'lamooo annamaa 'alaa Rasoolinal balaaghul mubeen", "translation": "And obey Allah and obey the Messenger and beware. And if you turn away - then know that upon Our Messenger is only [the responsibility for] clear notification."}, {"ayah": 93, "translit": "Laisa 'alal lazeena aamanoo wa 'amilus saalihaati junaahun feemaa ta'imooo izaa mat taqaw wa aamanoo wa 'amilus saalihaati summat taqaw wa aamanoo summat taqaw wa ahsanoo; wallaahu yuhibbul muhsineen", "translation": "There is not upon those who believe and do righteousness [any] blame concerning what they have eaten [in the past] if they [now] fear Allah and believe and do righteous deeds, and then fear Allah and believe, and then fear Allah and do good; and Allah loves the doers of good."}, {"ayah": 94, "translit": "Yaaa aiyuhal lazeena aamanoo la yabluwannnakumul laahu bishai'im minas saidi tanaaluhooo aideekum wa rimaahukum liya'lamal laahu mai yakhaafuhoo bilghaib; famani' tadaa ba'da zaalika falahoo 'azaabun aleem", "translation": "O you who have believed, Allah will surely test you through something of the game that your hands and spears [can] reach, that Allah may make evident those who fear Him unseen. And whoever transgresses after that - for him is a painful punishment."}, {"ayah": 95, "translit": "Yaaa aiyuhal lazeena aamanoo laa taqtulus saida wa antum hurum; wa man qatalahoo minkum mut'am midan fajazaaa'um mislu maa qatala minanna'ami yahkumu bihee zawaa 'adlim minkum hadyam baalighal Ka'bati aw kaffaaratun ta'aamu masaakeena aw 'adlu zaalika Siyaamal liyazooqa wabaala amrih; 'afal laahu 'ammaa salaf; wa man 'aada fayanta qimul laahu minh; wallaahu 'azeezun zuntiqaam", "translation": "O you who have believed, do not kill game while you are in the state of ihram. And whoever of you kills it intentionally - the penalty is an equivalent from sacrificial animals to what he killed, as judged by two just men among you as an offering [to Allah] delivered to the Ka'bah, or an expiation: the feeding of needy people or the equivalent of that in fasting, that he may taste the consequence of his deed. Allah has pardoned what is past; but whoever returns [to violation], then Allah will take retribution from him. And Allah is Exalted in Might and Owner of Retribution."}, {"ayah": 96, "translit": "Uhilla lakum saidul bahri wa ta'aamuhoo mataa'al lakum wa lissaiyaarati wa hurrima 'alaikum saidul barri maa dumtum hurumaa; wattaqul laahal lazeee ilaihi tuhsharoon", "translation": "Lawful to you is game from the sea and its food as provision for you and the travelers, but forbidden to you is game from the land as long as you are in the state of ihram. And fear Allah to whom you will be gathered."}, {"ayah": 97, "translit": "Ja'alal laahul Ka'batal Baital Haraama qiyaamal linnaasi wash Shahral Haraama walhadya walqalaaa'id; zaalika lita'lamooo annal laaha ya'lamu maa fis samaawaati wa maa fil ardi wa annal laaha bikulli shai'in 'Aleem", "translation": "Allah has made the Ka'bah, the Sacred House, standing for the people and [has sanctified] the sacred months and the sacrificial animals and the garlands [by which they are identified]. That is so you may know that Allah knows what is in the heavens and what is in the earth and that Allah is Knowing of all things."}, {"ayah": 98, "translit": "I'lamooo annal laaha shadeedul 'iqaabi wa annal laaha Ghafoorur Raheem", "translation": "Know that Allah is severe in penalty and that Allah is Forgiving and Merciful."}, {"ayah": 99, "translit": "Maa 'alar Rasooli illal balaagh; wallaahu ya'lamu maa tubdoona wa maa taktumoon", "translation": "Not upon the Messenger is [responsibility] except [for] notification. And Allah knows whatever you reveal and whatever you conceal."}, {"ayah": 100, "translit": "Qul laa yastawil khabeesu wattaiyibu wa law a'jabaka kasratul khabees; fattaqul laaha yaaa ulil albaabi la'allakum tuflihoon", "translation": "Say, \"Not equal are the evil and the good, although the abundance of evil might impress you.\" So fear Allah, O you of understanding, that you may be successful."}, {"ayah": 101, "translit": "yaaa aiyuhal lazeena aamanoo laa tas'aloo 'an ashyaaa'a in tubda lakum tasu'kum wa in tas'aloo 'anhaa heena yunazzalul Qur'aanu tubda lakum; 'afallaahu 'anhaa; wallaahu Ghafoorun Haleem", "translation": "O you who have believed, do not ask about things which, if they are shown to you, will distress you. But if you ask about them while the Qur'an is being revealed, they will be shown to you. Allah has pardoned that which is past; and Allah is Forgiving and Forbearing."}, {"ayah": 102, "translit": "Qad sa alahaa qawmum min qablikum summa asbahoo bihaa kaafireen", "translation": "A people asked such [questions] before you; then they became thereby disbelievers."}, {"ayah": 103, "translit": "Maa ja'alal laahu mim baheeratinw wa laa saaa'ibatinw wa laa waseelatinw wa laa haaminw wa laakinnal lazeena kafaroo yaftaroona 'alallaahil kazib; wa aksaruhum laa ya'qiloon", "translation": "Allah has not appointed [such innovations as] bahirah or sa'ibah or wasilah or ham. But those who disbelieve invent falsehood about Allah, and most of them do not reason."}, {"ayah": 104, "translit": "Wa izaa qeela lahum ta'aalaw ilaa maaa anzalallaahu wa ilar Rasooli qaaloo hasbunaa maa wajadnaa 'alaihi aabaaa'anaa; awa law kaana aabaaa'uhum laa ya'lamoona shai'anw wa laa yahtadoon", "translation": "And when it is said to them, \"Come to what Allah has revealed and to the Messenger,\" they say, \"Sufficient for us is that upon which we found our fathers.\" Even though their fathers knew nothing, nor were they guided?"}, {"ayah": 105, "translit": "Yaaa aiyuhal lazeena aamanoo 'alaikum anfusakum laa yadurrukum man dalla izah tadaitum; ilal laahi marji'ukum jamee'an fayunabbi'ukum bimaa kuntum ta'maloon", "translation": "O you who have believed, upon you is [responsibility for] yourselves. Those who have gone astray will not harm you when you have been guided. To Allah is you return all together; then He will inform you of what you used to do."}, {"ayah": 106, "translit": "Yaaa aiyuhal lazeena aamanoo shahaadatu bainikum izaa hadara ahadakumul mawtu heenal wasiyyatis naani zawaa 'adlim minkum aw aakharaani min ghairikum in antum darabtum fil ardi fa asaabatkum museebatul mawt; tahbi soonahumaa mim ba'dis Salaati fa yuqsimaani billaahi inirtabtum laa nashtaree bihee samananw wa law kaana zaa qurbaa wa laa naktumu shahaadatal laahi innaaa izal laminal aasimeen", "translation": "O you who have believed, testimony [should be taken] among you when death approaches one of you at the time of bequest - [that of] two just men from among you or two others from outside if you are traveling through the land and the disaster of death should strike you. Detain them after the prayer and let them both swear by Allah if you doubt [their testimony, saying], \"We will not exchange our oath for a price, even if he should be a near relative, and we will not withhold the testimony of Allah. Indeed, we would then be of the sinful.\""}, {"ayah": 107, "translit": "Fa in 'usira 'alaaa annahumas tahaqqaaa isman fa aakharaani yaqoomaani maqaamahumaa minal lazeenas tahaqqa 'alaihimul awlayaani fa yuqsimaani billaahi lashahaadatunaaa ahaqqu min shahaadatihimaaa wa ma'tadainaaa innaaa izal laminaz zaalimeen", "translation": "But if it is found that those two were guilty of perjury, let two others stand in their place [who are] foremost [in claim] from those who have a lawful right. And let them swear by Allah, \"Our testimony is truer than their testimony, and we have not transgressed. Indeed, we would then be of the wrongdoers.\""}, {"ayah": 108, "translit": "Zaalika adnaaa ai yaatoo bishshahaadati 'alaa wajhihaaa aw yakhaafooo an turadda aimaanum ba'da aimaanihim; wattaqul laaha wasma'oo; wallaahu laa yahdil qawmal faasiqeen", "translation": "That is more likely that they will give testimony according to its [true] objective, or [at least] they would fear that [other] oaths might be taken after their oaths. And fear Allah and listen; and Allah does not guide the defiantly disobedient people."}, {"ayah": 109, "translit": "yawma yajma'ul laahur Rusula fa yaqoolu maazaaa ujibtum qaaloo laa 'ilma lanaa innaka Anta 'Allaamul Ghuyoob", "translation": "[Be warned of] the Day when Allah will assemble the messengers and say, \"What was the response you received?\" They will say, \"We have no knowledge. Indeed, it is You who is Knower of the unseen\""}, {"ayah": 110, "translit": "Iz qaalal laahu yaa 'Eesab-na-Maryamaz kur ni'matee 'alaika wa 'alaa waalidatik; iz aiyattuka bi Roohil Qudusi tukallimun naasa fil mahdi wa kahlanw wa iz 'allamtukal kitaaba wal Hikmata wa Tawraata wal Injeela wa iz Takhluqu minat teeni kahai 'atit tairi bi iznee fatanfukhu feeha fatakoonu tairam bi iznee wa tubri'ul akmaha wal abrasa bi iznee wa iz tukhrijul mawtaa bi iznee wa iz kafaftu Baneee Israaa'eela 'anka iz ji'tahum bil baiyinaati fa qaalal lazeena kafaroo minhum in haazaaa illaa sihrum mubeen", "translation": "[The Day] when Allah will say, \"O Jesus, Son of Mary, remember My favor upon you and upon your mother when I supported you with the Pure Spirit and you spoke to the people in the cradle and in maturity; and [remember] when I taught you writing and wisdom and the Torah and the Gospel; and when you designed from clay [what was] like the form of a bird with My permission, then you breathed into it, and it became a bird with My permission; and you healed the blind and the leper with My permission; and when you brought forth the dead with My permission; and when I restrained the Children of Israel from [killing] you when you came to them with clear proofs and those who disbelieved among them said, \"This is not but obvious magic.\""}, {"ayah": 111, "translit": "Wa iz awhaitu ilal hawaariyyeena an aaminoo bee wa bi Rasoolee qaalooo aamannaa washhad bi annanaa muslimoon", "translation": "And [remember] when I inspired to the disciples, \"Believe in Me and in My messenger Jesus.\" They said, \"We have believed, so bear witness that indeed we are Muslims [in submission to Allah].\""}, {"ayah": 112, "translit": "Iz qaalal hawaariyyoona yaa 'Eesab na Maryama hal yastatee'u Rabbuka ai yunaz zila 'alinaa maaa'idatam minas samaaa'i qaalat taqul laaha in kuntum mu'mineen", "translation": "[And remember] when the disciples said, \"O Jesus, Son of Mary, can your Lord send down to us a table [spread with food] from the heaven? [Jesus] said,\" Fear Allah, if you should be believers.\""}, {"ayah": 113, "translit": "Qaaloo nureedu an naakula minhaa wa tatam'inna quloo bunaa wa na'lama an qad sadaqtana wa nakoona 'alaihaa minash shaahideen", "translation": "They said, \"We wish to eat from it and let our hearts be reassured and know that you have been truthful to us and be among its witnesses.\""}, {"ayah": 114, "translit": "Qaala 'Eesab nu Maryamal laahumma Rabbanaaa anzil 'alainaa maaa'idatam minas samaaa'i takoonu lanaa 'eedal li awwalinaa wa aakirinaa wa Aayatam minka warzuqnaa wa Anta khairur raaziqeen", "translation": "Said Jesus, the son of Mary, \"O Allah, our Lord, send down to us a table [spread with food] from the heaven to be for us a festival for the first of us and the last of us and a sign from You. And provide for us, and You are the best of providers.\""}, {"ayah": 115, "translit": "Qaalal laahu innee munaz ziluhaa 'alaikum faman yakfur ba'du minkum fa inneee u'azzibuhoo 'azaabal laaa u'azzibuhooo ahadam minal 'aalameen", "translation": "Allah said, \"Indeed, I will sent it down to you, but whoever disbelieves afterwards from among you - then indeed will I punish him with a punishment by which I have not punished anyone among the worlds.\""}, {"ayah": 116, "translit": "Wa iz qaalal laahu yaa 'Eesab na Maryama 'a-anta qulta linnaasit takhizoonee wa ummiya ilaahaini min doonil laahi qaala Subhaanaka  maa yakkoonu leee an aqoola maa laisa lee bihaqq; in kuntu qultuhoo faqad 'alimtah; ta'lamu maa fee nafsee wa laaa a'almu maa fee nafsik; innaka Anta 'Allaamul Ghuyoob", "translation": "And [beware the Day] when Allah will say, \"O Jesus, Son of Mary, did you say to the people, 'Take me and my mother as deities besides Allah?'\" He will say, \"Exalted are You! It was not for me to say that to which I have no right. If I had said it, You would have known it. You know what is within myself, and I do not know what is within Yourself. Indeed, it is You who is Knower of the unseen."}, {"ayah": 117, "translit": "Maa qultu lahum illaa maaa amartanee bihee ani'budul laaha Rabbeee wa Rabbakum; wa kuntu 'alaihim shaheedam maa dumtu feehim falammaa tawaffaitanee kunta Antar Raqeeba 'alaihim; wa Anta 'alaa kulli shai'in Shaheed", "translation": "I said not to them except what You commanded me - to worship Allah, my Lord and your Lord. And I was a witness over them as long as I was among them; but when You took me up, You were the Observer over them, and You are, over all things, Witness."}, {"ayah": 118, "translit": "In tu'azzibhum fa innahum ibaaduka wa in taghfir lahum fa innaka Antal 'Azzezul Hakeem", "translation": "If You should punish them - indeed they are Your servants; but if You forgive them - indeed it is You who is the Exalted in Might, the Wise."}, {"ayah": 119, "translit": "Qaalal laahu haaza yawmu yanfa'us saadiqeena sidquhum; lahum janaatunn tajree min tahtihal anhaaru khaalideena feehaaa abadaa; radiyal laahu 'anhum wa radoo 'anh; zaalikal fawzul 'azeem", "translation": "Allah will say, \"This is the Day when the truthful will benefit from their truthfulness.\" For them are gardens [in Paradise] beneath which rivers flow, wherein they will abide forever, Allah being pleased with them, and they with Him. That is the great attainment."}, {"ayah": 120, "translit": "Lillaahi mulkus samaawaati wal ardi wa maa feehinn; wa Huwa 'alaa kulli shain'in Qadeer", "translation": "To Allah belongs the dominion of the heavens and the earth and whatever is within them. And He is over all things competent."}]}, {"num": 6, "name": "Al-An'am", "meaning": "The Cattle", "verses": [{"ayah": 1, "translit": "Alhamdu lillaahil lazee khalaqas samaawaati wal arda wa ja'alaz zulumaati wannoor; summal lazeena kafaroo bi Rabbihim ya'diloon", "translation": "[All] praise is [due] to Allah, who created the heavens and the earth and made the darkness and the light. Then those who disbelieve equate [others] with their Lord."}, {"ayah": 2, "translit": "Huwal lazee khalaqakum min teenin summa qadaaa ajalanw wa ajalum musamman 'indahoo summa antum tamtaroon", "translation": "It is He who created you from clay and then decreed a term and a specified time [known] to Him; then [still] you are in dispute."}, {"ayah": 3, "translit": "Wa Huwal laahu fissamaawaati wa fil ardi ya'lamu sirrakum wa jahrakum wa ya'lamu maa taksiboon", "translation": "And He is Allah, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn."}, {"ayah": 4, "translit": "Wa maa taateehim min Aayatim min Aayaati Rabbihim illaa kaanoo 'anhaa mu'rideen", "translation": "And no sign comes to them from the signs of their Lord except that they turn away therefrom."}, {"ayah": 5, "translit": "Faqad kazzaboo bilhaqqi lammaa jaaa'ahum fasawfa yaateehim ambaaa'u maa kaanoo bihee yastahzi'oon", "translation": "For they had denied the truth when it came to them, but there is going to reach them the news of what they used to ridicule."}, {"ayah": 6, "translit": "Alam yaraw kam ahlaknaa min qablihim min qarnim makkannaahum fil ardi maa lam numakkil lakum wa arsalnas samaaa'a 'alaihim midraaranw wa ja'alnal anhaara tajree min tahtihim fa ahlak naahum bizunoobihim wa anshaanaa mim ba'dihim qarnan aakhareen", "translation": "Have they not seen how many generations We destroyed before them which We had established upon the earth as We have not established you? And We sent [rain from] the sky upon them in showers and made rivers flow beneath them; then We destroyed them for their sins and brought forth after them a generation of others."}, {"ayah": 7, "translit": "Wa law nazzalnaa 'alaika Kitaaban fee qirtaasin falamasoohu bi aideehim laqaalal lazeena kafarooo in haazaaa illaa sihrum mubeen", "translation": "And even if We had sent down to you, [O Muhammad], a written scripture on a page and they touched it with their hands, the disbelievers would say, \"This is not but obvious magic.\""}, {"ayah": 8, "translit": "Wa qaaloo law laaa unzila alaihi malakunw wa law anzalna malakal laqudiyal amru summa laa yunzaroon", "translation": "And they say, \"Why was there not sent down to him an angel?\" But if We had sent down an angel, the matter would have been decided; then they would not be reprieved."}, {"ayah": 9, "translit": "Wa law ja'alnaahu malakal laja'alnaahu rajulanw wa lalabasnaa 'alaihim maa yalbisoon", "translation": "And if We had made him an angel, We would have made him [appear as] a man, and We would have covered them with that in which they cover themselves."}, {"ayah": 10, "translit": "Wa laqadis tuhzi'a bi-Rusulim min qablika fahaaqa billazeena sakhiroo minhum maa kaanoo bihee yastahzi'oon", "translation": "And already were messengers ridiculed before you, but those who mocked them were enveloped by that which they used to ridicule."}, {"ayah": 11, "translit": "Qul seeroo fil ardi summan zuroo kaifa kaana 'aaqibatul mukazzibeen", "translation": "Say, \"Travel through the land; then observe how was the end of the deniers.\""}, {"ayah": 12, "translit": "Qul limam maa fis samaawaati wal ardi qul lillaah; kataba 'alaa nafsihir rahmah; la yajma 'annakum ilaa Yawmil Qiyaamati laa raiba feeh; allazeena khasirooo anfusahum fahum laa yu'minoon", "translation": "Say, \"To whom belongs whatever is in the heavens and earth?\" Say, \"To Allah.\" He has decreed upon Himself mercy. He will surely assemble you for the Day of Resurrection, about which there is no doubt. Those who will lose themselves [that Day] do not believe."}, {"ayah": 13, "translit": "Wa lahoo maa sakana fillaili wannahaar; wa Huwas Samee'ul Aleem", "translation": "And to Him belongs that which reposes by night and by day, and He is the Hearing, the Knowing."}, {"ayah": 14, "translit": "Qul aghairal laahi attakhizu waliyyan faatiris samaawaati wal ardi wa Huwa yut'imu wa laa yut'am; qul inneee umirtu an akoona awwala man salama wa laa takoonanna minal mushrikeen", "translation": "Say, \"Is it other than Allah I should take as a protector, Creator of the heavens and the earth, while it is He who feeds and is not fed?\" Say, [O Muhammad], \"Indeed, I have been commanded to be the first [among you] who submit [to Allah] and [was commanded], 'Do not ever be of the polytheists.' \""}, {"ayah": 15, "translit": "Qul inneee akhaafu in 'asaitu Rabbee 'azaaba Yawmin 'Azeem", "translation": "Say, \"Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day.\""}, {"ayah": 16, "translit": "Mai yusraf 'anhu Yawma'izin faqad rahimah; wa zaalikal fawzul mubeen", "translation": "He from whom it is averted that Day - [Allah] has granted him mercy. And that is the clear attainment."}, {"ayah": 17, "translit": "Wa iny-yamsaskal laahu bidurrin falaaa kaashifa lahoo illaa Huwa wa iny-yamsaska bikhairin fa Huwa 'alaa kulli shai'in Qadeer", "translation": "And if Allah should touch you with adversity, there is no remover of it except Him. And if He touches you with good - then He is over all things competent."}, {"ayah": 18, "translit": "Wa Huwal gaahiru fawqa 'ibaadih; wa Huwal Hakeemul Khabeer", "translation": "And He is the subjugator over His servants. And He is the Wise, the Acquainted [with all]."}, {"ayah": 19, "translit": "Qul ayyu shai'in akbaru shahaadatan qulil laahu shaheedum bainee wa bainakum; wa oohiya ilaiya haazal Qur'aanu li unzirakum bihee wa mam balagh; a'innakum latashhadoona anna ma'al laahi aalihatan ukhraa; qul laaa ashhad; qul innamaa Huwa Ilaahunw Waahidunw wa innanee baree'um mimmaa tushrikoon", "translation": "Say, \"What thing is greatest in testimony?\" Say, \"Allah is witness between me and you. And this Qur'an was revealed to me that I may warn you thereby and whomever it reaches. Do you [truly] testify that with Allah there are other deities?\" Say, \"I will not testify [with you].\" Say, \"Indeed, He is but one God, and indeed, I am free of what you associate [with Him].\""}, {"ayah": 20, "translit": "Allazeena aatainaa humul Kitaaba ya'rifoonahoo kamaa ya'rifoona abnaaa'ahum; allazeena khasirooo anfusahum fahum laa yu'minoon", "translation": "Those to whom We have given the Scripture recognize it as they recognize their [own] sons. Those who will lose themselves [in the Hereafter] do not believe."}, {"ayah": 21, "translit": "Wa man azlamu mim manif tara 'alal laahi kaziban aw kazzaba bi Aayaatih; innahoo laa yuflihuz zaalimoon", "translation": "And who is more unjust than one who invents about Allah a lie or denies His verses? Indeed, the wrongdoers will not succeed."}, {"ayah": 22, "translit": "Wa yawma nahshuruhum jamee'an summa naqoolu lillazeena ashrakooo ayna shurakaaa' ukumul lazeena kuntum taz'umoon", "translation": "And [mention, O Muhammad], the Day We will gather them all together; then We will say to those who associated others with Allah, \"Where are your 'partners' that you used to claim [with Him]?\""}, {"ayah": 23, "translit": "Summa lam takun fitnatuhum illaaa an qaaloo wallaahi Rabbinaa maa kunnaa mushrikeen", "translation": "Then there will be no [excuse upon] examination except they will say, \"By Allah, our Lord, we were not those who associated.\""}, {"ayah": 24, "translit": "Unzur kaifa kazaboo 'alaaa anfusihim, wa dalla 'anhum maa kaanoo yaftaroon", "translation": "See how they will lie about themselves. And lost from them will be what they used to invent."}, {"ayah": 25, "translit": "Wa minhum mai yastami'u ilaika wa ja'alnaa 'alaa quloobihim akinnatan ai yafqahoohu wa feee aazaanihim waqraa; wa ai yaraw kulla Aayatil laa yu'minoo bihaa; hattaaa izaa jaaa'oka  yujaadiloonaka yaqoolul lazeena kafaroo in haazaa illaaa asaateerul awwaleen", "translation": "And among them are those who listen to you, but We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if they should see every sign, they will not believe in it. Even when they come to you arguing with you, those who disbelieve say, \"This is not but legends of the former peoples.\""}, {"ayah": 26, "translit": "Wa hum yanhawna 'anhu wa yan'awna 'anhu wa iny yuhlikoona illaa anfusahum wa maa yash'uroon", "translation": "And they prevent [others] from him and are [themselves] remote from him. And they do not destroy except themselves, but they perceive [it] not."}, {"ayah": 27, "translit": "Wa law taraaa iz wauqifoo 'alan Naari faqaaloo yaa laitanaa nuraddu wa laa nukaz ziba bi Aayaati Rabbinaa wa nakoona minal mu'mineen", "translation": "If you could but see when they are made to stand before the Fire and will say, \"Oh, would that we could be returned [to life on earth] and not deny the signs of our Lord and be among the believers.\""}, {"ayah": 28, "translit": "Bal  badaa lahum maa kaanoo yukhfoona min qablu wa law ruddoo la'aadoo limaa nuhoo 'anhu wa innahum lakaaziboon", "translation": "But what they concealed before has [now] appeared to them. And even if they were returned, they would return to that which they were forbidden; and indeed, they are liars."}, {"ayah": 29, "translit": "Wa qaalooo in hiya illaa hayaatunad dunyaa wa maa nahnu bimab'ooseen", "translation": "And they say, \"There is none but our worldly life, and we will not be resurrected.\""}, {"ayah": 30, "translit": "Wa law taraa iz wuqifoo 'alaa Rabbihim; qaala alaisa haazaa bilhaqq; qaaloo balaa wa Rabbinaa; qaala fazooqul 'azaaba bimaa kuntum takfuroon", "translation": "If you could but see when they will be made to stand before their Lord. He will say, \"Is this not the truth?\" They will say, \"Yes, by our Lord.\" He will [then] say, \"So taste the punishment because you used to disbelieve.\""}, {"ayah": 31, "translit": "Qad khasiral lazeena kazzaboo biliqaaa'il laahi hattaaa izaa jaaa'at humus Saa'atu baghtan qaaloo yaa hasratanaa 'alaa maa farratnaa feehaa wa hum yahmiloona awzaarahum 'alaa zuhoorihim; alaa saaa'a ma yaziroon", "translation": "Those will have lost who deny the meeting with Allah, until when the Hour [of resurrection] comes upon them unexpectedly, they will say, \"Oh, [how great is] our regret over what we neglected concerning it,\" while they bear their burdens on their backs. Unquestionably, evil is that which they bear."}, {"ayah": 32, "translit": "Wa mal hayaatud dunyaaa illaa la'ibunw wa lahwunw wa lad Daarul Aakhiratu kahyrul lillazeena yattaqoon; afalaa ta'qiloon", "translation": "And the worldly life is not but amusement and diversion; but the home of the Hereafter is best for those who fear Allah, so will you not reason?"}, {"ayah": 33, "translit": "Qad na'lamu innahoo layahzunukal lazee yaqooloona fa innahum laa yukazziboonaka wa laakinnaz zaalimeena bi Aayaatil laahi yajhadoon", "translation": "We know that you, [O Muhammad], are saddened by what they say. And indeed, they do not call you untruthful, but it is the verses of Allah that the wrongdoers reject."}, {"ayah": 34, "translit": "Wa laqad kuzzibat Rusulum min qablika fasabaroo 'alaa maa kuzziboo wa oozoo hattaaa ataahum nasrunaa; wa laa mubaddila li Kalimaatil laah; wa laqad jaaa'aka min naba'il mursaleen", "translation": "And certainly were messengers denied before you, but they were patient over [the effects of] denial, and they were harmed until Our victory came to them. And none can alter the words of Allah. And there has certainly come to you some information about the [previous] messengers."}, {"ayah": 35, "translit": "Wa in kaana kabura 'alaika i'raaduhum fa inistata'ta an tabtaghiya nafaqan fil ardi aw sullaman fis samaaa'i fataa tiyahum bi Aayah; wa law shaaa'al laahu lajama'ahum 'alal hudaa; falaa takoonanna minal jaahileen", "translation": "And if their evasion is difficult for you, then if you are able to seek a tunnel into the earth or a stairway into the sky to bring them a sign, [then do so]. But if Allah had willed, He would have united them upon guidance. So never be of the ignorant."}, {"ayah": 36, "translit": "Innamaa yastajeebul lazeena yasma'oon; walmawtaa yab'asuhumul laahu summa ilaihi yurja'oon", "translation": "Only those who hear will respond. But the dead - Allah will resurrect them; then to Him they will be returned."}, {"ayah": 37, "translit": "Wa qaaloo law laa nuzzila 'alaihi Aayatum mir Rabbih; qul innal laaha qaadirun 'alaaa ai yunazzila Aayatanw wa laakinna aksarahum laa ya'lamoon", "translation": "And they say, \"Why has a sign not been sent down to him from his Lord?\" Say, \"Indeed, Allah is Able to send down a sign, but most of them do not know.\""}, {"ayah": 38, "translit": "Wa maa min daaabbatin fil ardi wa laa taaa'iriny yateeru bijanaahaihi illaaa umamun amsaalukum; maa farratnaa fil Kitaabi min shai'in summa ilaa Rabbihim yuhsharoon", "translation": "And there is no creature on [or within] the earth or bird that flies with its wings except [that they are] communities like you. We have not neglected in the Register a thing. Then unto their Lord they will be gathered."}, {"ayah": 39, "translit": "Wallazeena kazzaboo bi Aayaatinaa summunw wa bukmun fiz zulumaat; mai yasha il laahu yudlilh; wa mai yashaa yaj'alhu 'alaa Siraatim Mustaqeem", "translation": "But those who deny Our verses are deaf and dumb within darknesses. Whomever Allah wills - He leaves astray; and whomever He wills - He puts him on a straight path."}, {"ayah": 40, "translit": "Qaul ara'aytakum in ataakum 'azaabul laahi aw atatkumus Saa'atu a-ghairal laahi tad'oona in kuntum saadiqeen", "translation": "Say, \"Have you considered: if there came to you the punishment of Allah or there came to you the Hour - is it other than Allah you would invoke, if you should be truthful?\""}, {"ayah": 41, "translit": "Bal iyyaahu tad'oona fa yakshifu maa tad'oona ilaihi in shaaa'a wa tansawna maa tushrikoon", "translation": "No, it is Him [alone] you would invoke, and He would remove that for which you invoked Him if He willed, and you would forget what you associate [with Him]."}, {"ayah": 42, "translit": "Wa laqad arsalnaaa ilaaa umamim min qablika fa akhaznaahum bilbaasaaa'i waddarraaa'i la'allahum yata darra'oon", "translation": "And We have already sent [messengers] to nations before you, [O Muhammad]; then We seized them with poverty and hardship that perhaps they might humble themselves [to Us]."}, {"ayah": 43, "translit": "Falaw laaa iz jaaa'ahum baasunaa tadarra'oo wa laakin qasat quloobuhum wa zaiyana lahumush Shaitaanu maa kaanoo ya'maloon", "translation": "Then why, when Our punishment came to them, did they not humble themselves? But their hearts became hardened, and Satan made attractive to them that which they were doing."}, {"ayah": 44, "translit": "Falammaa nasoo maa zukkiroo bihee fatahnaa 'alaihim abwaaba kulli shai'in hattaaa izaa farihoo bimaaa ootooo akhaznaahum baghtatan fa izaa hum mmublisoon", "translation": "So when they forgot that by which they had been reminded, We opened to them the doors of every [good] thing until, when they rejoiced in that which they were given, We seized them suddenly, and they were [then] in despair."}, {"ayah": 45, "translit": "Faquti'a daabirul qawmil lazeena zalamoo; walhamdu lillaahi Rabbil 'aalameen", "translation": "So the people that committed wrong were eliminated. And praise to Allah, Lord of the worlds."}, {"ayah": 46, "translit": "Qul ara'aitum in akhazal laahu sam'akum wa absaarakum wa khatama 'alaa quloobikum man ilaahun ghairul laahi yaateekum bih; unzur kaifa nusarriful Aayaati summa hum yasdifoon", "translation": "Say, \"Have you considered: if Allah should take away your hearing and your sight and set a seal upon your hearts, which deity other than Allah could bring them [back] to you?\" Look how we diversify the verses; then they [still] turn away."}, {"ayah": 47, "translit": "Qul ara'aitakum in ataakum 'azaabul laahi baghtatan aw jahratan hal yuhlaku illal qawmuz zaalimoon", "translation": "Say, \"Have you considered: if the punishment of Allah should come to you unexpectedly or manifestly, will any be destroyed but the wrongdoing people?\""}, {"ayah": 48, "translit": "Wa maa nursilul mursaleena illaa mubashshireena wa munzireena faman aamana wa aslaha falaa khawfun 'alaihim wa laa hum yahzanoon", "translation": "And We send not the messengers except as bringers of good tidings and warners. So whoever believes and reforms - there will be no fear concerning them, nor will they grieve."}, {"ayah": 49, "translit": "Wallazeena kazzaboo bi Aayaatinaa yamassuhumul 'azaabu bimaa kaanoo yafsuqoon", "translation": "But those who deny Our verses - the punishment will touch them for their defiant disobedience."}, {"ayah": 50, "translit": "Qul laaa aqoolu lakum 'indee khazaaa'inul laahi wa laaa a'lamul ghaiba wa laaa aqoolu lakum innee malakun in attabi'u illaa maa yoohaaa ilaiy; qul hal yastawil a'maa walbaseer; afalaa tatafakkaroon", "translation": "Say, [O Muhammad], \"I do not tell you that I have the depositories [containing the provision] of Allah or that I know the unseen, nor do I tell you that I am an angel. I only follow what is revealed to me.\" Say, \"Is the blind equivalent to the seeing? Then will you not give thought?\""}, {"ayah": 51, "translit": "Wa anzir bihil lazeena yakhaafoona ai yuhsharooo ilaa Rabbihim laisa lahum min doonihee waliyyunw wa laa shafee'ul la'allahum yattaqoon", "translation": "And warn by the Qur'an those who fear that they will be gathered before their Lord - for them besides Him will be no protector and no intercessor - that they might become righteous."}, {"ayah": 52, "translit": "Wa laa tatrudil lazeena yad'oona Rabbahum bilghadaati wal 'ashiyyi yureedoona Wajhahoo ma 'alaika min hisaabihim min shai'inw wa maa min hisaabika 'alaihim min shai'in fatatrudahum fatakoona minaz zaalimeen", "translation": "And do not send away those who call upon their Lord morning and afternoon, seeking His countenance. Not upon you is anything of their account and not upon them is anything of your account. So were you to send them away, you would [then] be of the wrongdoers."}, {"ayah": 53, "translit": "Wa kazaalika fatannaa ba'dahum biba'dil liyaqoolooo ahaaa'ulaaa'i mannal laahu 'alaihim mim baininaa; alaisal laahu bi-a'lama bish shaakireen", "translation": "And thus We have tried some of them through others that the disbelievers might say, \"Is it these whom Allah has favored among us?\" Is not Allah most knowing of those who are grateful?"}, {"ayah": 54, "translit": "Wa izaa jaaa'akal lazeena yu'minoona bi Aayaatinaa faqul salaamun 'alaikum kataba Rabbukum 'alaa nafsihir rahmata annahoo man 'amila minkum sooo'am bijahaalatin summa taaba mim ba'dihee wa aslaha fa annahoo Ghafoorur Raheem", "translation": "And when those come to you who believe in Our verses, say, \"Peace be upon you. Your Lord has decreed upon Himself mercy: that any of you who does wrong out of ignorance and then repents after that and corrects himself - indeed, He is Forgiving and Merciful.\""}, {"ayah": 55, "translit": "Wa kazaalika nufassilul Aayaati wa litastabeena sabeelul mujrimeen", "translation": "And thus do We detail the verses, and [thus] the way of the criminals will become evident."}, {"ayah": 56, "translit": "Qul innee nuheetu an a'budal lazeena tad'oona min doonil laah; qul laaa attabi'u ahwaaa'akum qad dalaltu izanw wa maaa ana minal muhtadeen", "translation": "Say, \"Indeed, I have been forbidden to worship those you invoke besides Allah.\" Say, \"I will not follow your desires, for I would then have gone astray, and I would not be of the [rightly] guided.\""}, {"ayah": 57, "translit": "Qul innee 'alaa baiyinatim mir Rabbee wa kazzabtum bih; maa 'indee maa tasta'jiloona bih; inil hukmu illaa lillaahi yaqussul haqqa wa Huwa khairul faasileen", "translation": "Say, \"Indeed, I am on clear evidence from my Lord, and you have denied it. I do not have that for which you are impatient. The decision is only for Allah. He relates the truth, and He is the best of deciders.\""}, {"ayah": 58, "translit": "Qul law anna 'indee maa tasta'jiloona bihee laqudiyal amru bainee wa bainakum; wallaahu a'lamu bizzaalimeen", "translation": "Say, \"If I had that for which you are impatient, the matter would have been decided between me and you, but Allah is most knowing of the wrongdoers.\""}, {"ayah": 59, "translit": "Wa 'indahoo mafaatihul ghaibi laa ya'lamuhaaa illaa Hoo; wa ya'lamu maa fil barri walbahr; wa maa tasqutu minw waraqatin illaa ya'lamuhaa wa laa habbatin fee zulumaatil ardi wa laa ratbinw wa laa yaabisin illaa fee Kitaabim Mubeen", "translation": "And with Him are the keys of the unseen; none knows them except Him. And He knows what is on the land and in the sea. Not a leaf falls but that He knows it. And no grain is there within the darknesses of the earth and no moist or dry [thing] but that it is [written] in a clear record."}, {"ayah": 60, "translit": "Wa Huwal lazee yatawaf faakum billaili wa ya'lamu maa jarahtum binnahaari summa yab'asukum fee liyuqdaaa ajalum musamman summa ilaihi marji'ukum summa yunabbi 'ukum bimaa kuntum ta'maloon", "translation": "And it is He who takes your souls by night and knows what you have committed by day. Then He revives you therein that a specified term may be fulfilled. Then to Him will be your return; then He will inform you about what you used to do."}, {"ayah": 61, "translit": "Wa huwal qaahiru fawqa 'ibaadihee wa yursilu 'alaikum hafazatan hattaaa izaa jaaa'a ahadakumul mawtu tawaffathu rusulunaa wa hum laa yufarritoon", "translation": "And He is the subjugator over His servants, and He sends over you guardian-angels until, when death comes to one of you, Our messengers take him, and they do not fail [in their duties]."}, {"ayah": 62, "translit": "Summa ruddooo ilallaahi mawlaahumul haqq; alaa lahul hukmu wa Huwa asra'ul haasibeen", "translation": "Then they His servants are returned to Allah, their true Lord. Unquestionably, His is the judgement, and He is the swiftest of accountants."}, {"ayah": 63, "translit": "Qul mai yunajjeekum min zulumaatil barri walbahri tad'oonahoo tadarru'anw wa khufyatann la'in anjaanaa min haazihee lanakoonana minash shaakireen", "translation": "Say, \"Who rescues you from the darknesses of the land and sea [when] you call upon Him imploring [aloud] and privately, 'If He should save us from this [crisis], we will surely be among the thankful.' \""}, {"ayah": 64, "translit": "Qulil laahu yunajjjeekum minhaa wa min kulli karbin summa antum tushrikoon", "translation": "Say, \"It is Allah who saves you from it and from every distress; then you [still] associate others with Him.\""}, {"ayah": 65, "translit": "Qul huwal Qaadiru 'alaaa ai yab'asa 'alaikum 'azaabam min fawqikum aw min tahti arjulikum aw yalbisakum shiya'anw wa yuzeeqa ba'dakum baasa ba'd; unzur kaifa nusarriful Aayaati la'allahum yafqahoon", "translation": "Say, \"He is the [one] Able to send upon you affliction from above you or from beneath your feet or to confuse you [so you become] sects and make you taste the violence of one another.\" Look how We diversify the signs that they might understand."}, {"ayah": 66, "translit": "Wa kaz zaba bihee qawmuka wa huwal haqq; qul lastu'alaikum biwakeel", "translation": "But your people have denied it while it is the truth. Say, \"I am not over you a manager.\""}, {"ayah": 67, "translit": "Likulli naba im mustaqar runw wa sawfa ta'lamoon", "translation": "For every happening is a finality; and you are going to know."}, {"ayah": 68, "translit": "Wa izaa ra aital lazeena yakhoodoona feee Aayaatinaa fa a'rid 'anhum hattaa yakkhoodoo fee hadeesin ghairih; wa immaa yunsiyannakash Shaitaanu falaa taq'ud ba'dazzikraa ma'al qawmiz zaalimeen", "translation": "And when you see those who engage in [offensive] discourse concerning Our verses, then turn away from them until they enter into another conversation. And if Satan should cause you to forget, then do not remain after the reminder with the wrongdoing people."}, {"ayah": 69, "translit": "Wa maa 'alal lazeena yattaqoona min hisaabihim min shai'inw wa laakin zikraa la'allahum yattaqoon", "translation": "And those who fear Allah are not held accountable for the disbelievers at all, but [only for] a reminder - that perhaps they will fear Him."}, {"ayah": 70, "translit": "Wa zaril lazeenat takhazoo deenahum la'ibanwwa lahwanw wa gharrat humul ha yaatud dunyaa; wa zakkir biheee an tubsala nafsum bimaa kasabat laisa lahaa min doonil laahi waliyyunw wa laa shafee'unw wa in ta'dil kulla 'adlil laa yu'khaz minhaa; ulaaa 'ikal lazeena ubsiloo bimaa kasaboo lahum sharaabum min hameeminw wa 'azaabun aleemum bimaa kaanoo yakkfuroon (section 8)", "translation": "And leave those who take their religion as amusement and diversion and whom the worldly life has deluded. But remind with the Qur'an, lest a soul be given up to destruction for what it earned; it will have other than Allah no protector and no intercessor. And if it should offer every compensation, it would not be taken from it. Those are the ones who are given to destruction for what they have earned. For them will be a drink of scalding water and a painful punishment because they used to disbelieve."}, {"ayah": 71, "translit": "Qul anad'oo min doonil laahi maa laa yanfa'unaa wa laa yadurrunaa wa nuraddu 'alaaa a'qaabina ba'da iz hadaanal laahu kallazis tahwat hush Shayaateenu fil ardi hairaana lahooo ashaabuny yad'oo nahooo ilal huda' tinaa; qul inna hudal laahi huwal hudaa wa umirnaa linuslima li Rabbil 'aalameen", "translation": "Say, \"Shall we invoke instead of Allah that which neither benefits us nor harms us and be turned back on our heels after Allah has guided us? [We would then be] like one whom the devils enticed [to wander] upon the earth confused, [while] he has companions inviting him to guidance, [calling], 'Come to us.' \" Say, \"Indeed, the guidance of Allah is the [only] guidance; and we have been commanded to submit to the Lord of the worlds."}, {"ayah": 72, "translit": "Wa an aqeemus Salaata wattaqooh; wa Hual lazeee ilaihi tuhsharoon", "translation": "And to establish prayer and fear Him.\" And it is He to whom you will be gathered."}, {"ayah": 73, "translit": "Wa an Huwal lazee khalaqas samaawaati wal arda bilhaqq; wa Yawma yaqoolu kun fa yakoon; Qawluhul haqq; wa lahul mulku Yawma yunfakhu fis Soor; 'Aalimul Ghaibi wash shahaadah; wa Huwal Hakeemul Khabeer", "translation": "And it is He who created the heavens and earth in truth. And the day He says, \"Be,\" and it is, His word is the truth. And His is the dominion [on] the Day the Horn is blown. [He is] Knower of the unseen and the witnessed; and He is the Wise, the Acquainted."}, {"ayah": 74, "translit": "Wa iz qaala Ibraaheemu li abeehi Aazara a-tattakhizu asnaaman aalihatan inneee araaka wa qawmaka fee dalaalim mmubeen", "translation": "And [mention, O Muhammad], when Abraham said to his father Azar, \"Do you take idols as deities? Indeed, I see you and your people to be in manifest error.\""}, {"ayah": 75, "translit": "Wa kazaalika nureee Ibraaheema malakootas samaawaati wal ardi wa liyakoona minal mooqineen", "translation": "And thus did We show Abraham the realm of the heavens and the earth that he would be among the certain [in faith]"}, {"ayah": 76, "translit": "Falammaa janna 'alaihil lailu ra aa kawkabaan qaala haaza Rabbee falammaaa afala qaala laaa uhibbul aafileen", "translation": "So when the night covered him [with darkness], he saw a star. He said, \"This is my lord.\" But when it set, he said, \"I like not those that disappear.\""}, {"ayah": 77, "translit": "Falammmaa ra al qamara baazighan qaala haazaa Rabbee falammmmaaa afala qaala la'il lam yahdinee Rabbee la akoonanna minal qawmid daaalleen", "translation": "And when he saw the moon rising, he said, \"This is my lord.\" But when it set, he said, \"Unless my Lord guides me, I will surely be among the people gone astray.\""}, {"ayah": 78, "translit": "Falammmaa ra ashshamsa baazighatan qaala haazaa Rabbee haazaaa akbaru falammaaa afalat qaala yaa qawmi innee bareee'um mimmaa tushrikoon", "translation": "And when he saw the sun rising, he said, \"This is my lord; this is greater.\" But when it set, he said, \"O my people, indeed I am free from what you associate with Allah."}, {"ayah": 79, "translit": "Innnee wajjahtu wajhiya lillazee fataras samaawaati wal arda haneefanw wa maaa ana minal mushrikeen", "translation": "Indeed, I have turned my face toward He who created the heavens and the earth, inclining toward truth, and I am not of those who associate others with Allah.\""}, {"ayah": 80, "translit": "Wa haaajjahoo qawmuh; qaala a-tuh aaajjooonnnee fillaahi wa qad hadaan; wa laaa akhaafu mmaa tushrikoona bihee illaaa ai yashaaa'a Rabbee shai'anw wasi'a Rabbee kulla shai'in 'ilman afalaa tatazakkaroon", "translation": "And his people argued with him. He said, \"Do you argue with me concerning Allah while He has guided me? And I fear not what you associate with Him [and will not be harmed] unless my Lord should will something. My Lord encompasses all things in knowledge; then will you not remember?"}, {"ayah": 81, "translit": "Wa kaifa akhaafu maaa ashraktum wa laa takhaafoona annakum ashraktum billaahi maa lam yunazzil bihee 'alaikum sultaanaa; fa aiyul fareeqaini ahaqqu bil amni in kuntum ta'lamoon", "translation": "And how should I fear what you associate while you do not fear that you have associated with Allah that for which He has not sent down to you any authority? So which of the two parties has more right to security, if you should know?"}, {"ayah": 82, "translit": "Allazeena aamanoo wa lam yalbisooo eemaanahum bizulmin ulaaa'ika lahumul amnu wa hum muhtadoon", "translation": "They who believe and do not mix their belief with injustice - those will have security, and they are [rightly] guided."}, {"ayah": 83, "translit": "Wa tilka hujjatunaaa aatainaahaaa Ibraaheema 'alaa qawmih; narfa'u darajaatim man nashaaa'; inna Rabbaka Hakeemun 'Aleem", "translation": "And that was Our [conclusive] argument which We gave Abraham against his people. We raise by degrees whom We will. Indeed, your Lord is Wise and Knowing."}, {"ayah": 84, "translit": "Wa wahabnaa lahoo ishaaqa wa ya'qoob; kullan hadainaa; wa Noohan hadainaa min qablu wa min zurriyyatihee Daawooda wa Sulaimaana wa Ayyooba wa Yoosufa wa Moosaa wa haaroon; wa kazaalika najzil muhsineen", "translation": "And We gave to Abraham, Isaac and Jacob - all [of them] We guided. And Noah, We guided before; and among his descendants, David and Solomon and Job and Joseph and Moses and Aaron. Thus do We reward the doers of good."}, {"ayah": 85, "translit": "Wa Zakariyyaa wa Yahyaa wa 'Eesaa wa Illyaasa kullum minas saaliheen", "translation": "And Zechariah and John and Jesus and Elias - and all were of the righteous."}, {"ayah": 86, "translit": "Wa Ismaa'eela wal Yasa'a wa Yoonusa wa Lootaa; wa kullan faddalnaa 'alal 'aalameen", "translation": "And Ishmael and Elisha and Jonah and Lot - and all [of them] We preferred over the worlds."}, {"ayah": 87, "translit": "Wa min aabaaa'ihim wa zurriyyaatihim wa ikhwaanihim wajtabainaahum wa hadainaahum ilaa Siraatim Mustaqeem", "translation": "And [some] among their fathers and their descendants and their brothers - and We chose them and We guided them to a straight path."}, {"ayah": 88, "translit": "Zaalika hudal laahi yahdee bihee mai yashaaa'u min 'ibaadih; wa law ashrakoo lahabita 'anhum maa kaanoo ya'maloon", "translation": "That is the guidance of Allah by which He guides whomever He wills of His servants. But if they had associated others with Allah, then worthless for them would be whatever they were doing."}, {"ayah": 89, "translit": "Ulaaa'ikal lazeena aatainaahumul Kitaaba wal hukma wan Nubuwwah; fa iny yakfur bihaa haaa'ulaaa'i faqad wakkalnaa bihaa qawmal laisoo bihaa bikaafireen", "translation": "Those are the ones to whom We gave the Scripture and authority and prophethood. But if the disbelievers deny it, then We have entrusted it to a people who are not therein disbelievers."}, {"ayah": 90, "translit": "Ulaaa'ikal lazeena hadal laahu fabihudaahumuq tadih; qul laaa as'alukum 'alaihi ajran in huwa illaa zikraa lil 'aalameen", "translation": "Those are the ones whom Allah has guided, so from their guidance take an example. Say, \"I ask of you for this message no payment. It is not but a reminder for the worlds.\""}, {"ayah": 91, "translit": "Wa maa qadarul laaha haqqa qadriheee iz qaaloo maaa anzalal laahu 'alaa basharim min shai'; qul man anzalal Kitaabal lazee jaaa'a bihee Moosaa nooranw wa hudal linnaasi taj'aloonahoo qaraateesa tubdoonahaa wa tukhfoona kaseeranw wa 'ullimtum maa lam ta'lamooo antum wa laaa aabaaa'ukum qulil laahu summa zarhum fee khawdihim yal'aboon", "translation": "And they did not appraise Allah with true appraisal when they said, \"Allah did not reveal to a human being anything.\" Say, \"Who revealed the Scripture that Moses brought as light and guidance to the people? You [Jews] make it into pages, disclosing [some of] it and concealing much. And you were taught that which you knew not - neither you nor your fathers.\" Say, \"Allah [revealed it].\" Then leave them in their [empty] discourse, amusing themselves."}, {"ayah": 92, "translit": "Wa haazaa Kitaabun anzalnaahu Mubaarakum musaddiqul lazee bainaa yadaihi wa litunzira ummal Quraa wa man hawlahaa; wallazeena yu'minoona bil Aakhirati yu'minoona bihee wa hum'alaa Salaatihim yuhaafizoon", "translation": "And this is a Book which We have sent down, blessed and confirming what was before it, that you may warn the Mother of Cities and those around it. Those who believe in the Hereafter believe in it, and they are maintaining their prayers."}, {"ayah": 93, "translit": "Wa man azlamu mimmanif taraa 'alal laahi kaziban aw qaala oohiya ilaiya wa lam yooha ilaihi shai'un wa man qaala sa unzilu misla maaa anzalal laah; wa law taraaa iziz zaalimoona fee ghamaraatil mawti walmalaaa'ikatu baasitooo aideehim akhrijooo anfusakum; al yawma tujzawna 'azaabal hooni bimaa kuntum taqooloona 'alal laahi ghairal haqqi wa kuntum 'an aayaatihee tastakbiroon", "translation": "And who is more unjust than one who invents a lie about Allah or says, \"It has been inspired to me,\" while nothing has been inspired to him, and one who says, \"I will reveal [something] like what Allah revealed.\" And if you could but see when the wrongdoers are in the overwhelming pangs of death while the angels extend their hands, [saying], \"Discharge your souls! Today you will be awarded the punishment of [extreme] humiliation for what you used to say against Allah other than the truth and [that] you were, toward His verses, being arrogant.\""}, {"ayah": 94, "translit": "Wa laqad ji'tumoonaa furaadaa kamaa khalaqnaakum awwala marratinw wa taraktum maa khawwalnaakum waraaa'a zuhoorikum wa maa naraa ma'akum shufa'aaa' akumul lazeena za'amtum annahum feekum shurakaaa'; laqat taqatta'a bainakum wa dalla 'annkum maa kuntum taz'umoon", "translation": "[It will be said to them], \"And you have certainly come to Us alone as We created you the first time, and you have left whatever We bestowed upon you behind you. And We do not see with you your 'intercessors' which you claimed that they were among you associates [of Allah]. It has [all] been severed between you, and lost from you is what you used to claim.\""}, {"ayah": 95, "translit": "Innal laaha faaliqul habbi wannawaa yukhrijul haiya minal maiyiti wa mukhrijul maiyiti minal haiy; zaalikumul laahu fa annaa tu'fakoon", "translation": "Indeed, Allah is the cleaver of grain and date seeds. He brings the living out of the dead and brings the dead out of the living. That is Allah; so how are you deluded?"}, {"ayah": 96, "translit": "Faaliqul isbaahi wa ja'alal laila sakananw washh shamsa walqamara husbaanaa; zaalika taqdeerul 'Azeezil 'Aleem", "translation": "[He is] the cleaver of daybreak and has made the night for rest and the sun and moon for calculation. That is the determination of the Exalted in Might, the Knowing."}, {"ayah": 97, "translit": "Wa Huwal lazee ja'ala lakumun nujooma litahtadoo bihaa fee zulumaatil barri walbahr; qad fassalnal Aayaati liqawminy ya'lamoon", "translation": "And it is He who placed for you the stars that you may be guided by them through the darknesses of the land and sea. We have detailed the signs for a people who know."}, {"ayah": 98, "translit": "Wa hhuwal lazeee ansha akum min nasinw waahidatin famustaqarrunw wa mustawda'; qad fassalnal Aayaati liqaw miny-yafqahoon", "translation": "And it is He who produced you from one soul and [gave you] a place of dwelling and of storage. We have detailed the signs for a people who understand."}, {"ayah": 99, "translit": "Wa Huwal lazeee anzala minas samaaa'i maaa'an fa akhrajnaa bihee nabaata kulli shai'in fa akhrajnaa minhu khadiran nukhriju minhu habbam mutaraakibanw wa minan nakhli min tal'ihaa qinwaanun daaniyatunw wa jannaatim min a'naabinw wazzaitoona warrummaana mushhtabihanw wa ghaira mutashaabih; unzurooo ilaa samariheee izaaa asmars wa yan'ih; inna fee zaalikum la Aayaatil liqawminy yu'minoon", "translation": "And it is He who sends down rain from the sky, and We produce thereby the growth of all things. We produce from it greenery from which We produce grains arranged in layers. And from the palm trees - of its emerging fruit are clusters hanging low. And [We produce] gardens of grapevines and olives and pomegranates, similar yet varied. Look at [each of] its fruit when it yields and [at] its ripening. Indeed in that are signs for a people who believe."}, {"ayah": 100, "translit": "Wa ja'aloo lillaahi shurakaaa'al jinna wa khalaqa hum wa kharaqoo lahoo baneena wa banaatim bighairi 'ilm Subhaanahoo wa Ta'aalaa 'amma yasifoon", "translation": "But they have attributed to Allah partners - the jinn, while He has created them - and have fabricated for Him sons and daughters. Exalted is He and high above what they describe"}, {"ayah": 101, "translit": "Badee'us samaawaati wal ardi annnaa yakoonu lahoo waladunw wa lam takul lahoo saahibatunw wa khalaqa kulla shai'in 'Aleem", "translation": "[He is] Originator of the heavens and the earth. How could He have a son when He does not have a companion and He created all things? And He is, of all things, Knowing."}, {"ayah": 102, "translit": "Zaalikumul laahu Rabbukum laaa ilaaha illaa huwa khaaliqu kulli shai'in fa'budooh; wa huwa 'alaa kulli shai'inw Wakeel", "translation": "That is Allah, your Lord; there is no deity except Him, the Creator of all things, so worship Him. And He is Disposer of all things."}, {"ayah": 103, "translit": "Laa tudrikuhul absaaru wa Huwa yudrikul absaara wa huwal Lateeful Khabeer", "translation": "Vision perceives Him not, but He perceives [all] vision; and He is the Subtle, the Acquainted."}, {"ayah": 104, "translit": "Qad jaaa'akum basaaa'iru mir Rabbikum faman absara falinafsihee wa man 'amiya fa'alaihaa; wa maaa ana 'alaikum bihafeez", "translation": "There has come to you enlightenment from your Lord. So whoever will see does so for [the benefit of] his soul, and whoever is blind [does harm] against it. And [say], \"I am not a guardian over you.\""}, {"ayah": 105, "translit": "Wa kazaalika nusarriful Aayaati wa liyaqooloo darasta wa linubaiyinahoo liqawminy ya'lamoon", "translation": "And thus do We diversify the verses so the disbelievers will say, \"You have studied,\" and so We may make the Qur'an clear for a people who know."}, {"ayah": 106, "translit": "ittabi' maaa oohiya ilaika mir Rabbika laaa ilaaha illaa Huwa wa a'rid 'anil mushrikeen", "translation": "Follow, [O Muhammad], what has been revealed to you from your Lord - there is no deity except Him - and turn away from those who associate others with Allah."}, {"ayah": 107, "translit": "Wa law shaaa'al laahu maaa ashrakoo; wa maa ja'alnaaka 'alaihim hafeezanw wa maaa anta 'alaihim biwakeel", "translation": "But if Allah had willed, they would not have associated. And We have not appointed you over them as a guardian, nor are you a manager over them."}, {"ayah": 108, "translit": "Wa laa tasubbul lazeena yad'oona min doonil laahi fa yasubbul laaha 'adwam bighairi 'ilm; kazaalika zaiyannaa likulli ummatin 'amalahum summa ilaa Rabbihim marji'uhum fa yunabbi'uhum bimaa kaanooya'maloon", "translation": "And do not insult those they invoke other than Allah, lest they insult Allah in enmity without knowledge. Thus We have made pleasing to every community their deeds. Then to their Lord is their return, and He will inform them about what they used to do."}, {"ayah": 109, "translit": "Wa aqsamoo billaahi jahda aimaanihim la'in jaaa'at hum Aayatul la yu'minunna bihaa; qul innamal Aayaatu 'indal laahi wa maa yush'irukum annahaaa izaa jaaa'at laa yu'minoon", "translation": "And they swear by Allah their strongest oaths that if a sign came to them, they would surely believe in it. Say, \"The signs are only with Allah.\" And what will make you perceive that even if a sign came, they would not believe."}, {"ayah": 110, "translit": "Wa nuqallibu af'idatahum wa absaarahum kamaa lam yu'minoo biheee awwala marratinw wa wa nazaruhum fee tughyaanihim ya'mahoon", "translation": "And We will turn away their hearts and their eyes just as they refused to believe in it the first time. And We will leave them in their transgression, wandering blindly."}, {"ayah": 111, "translit": "Wa law annanaa nazzal naaa ilaihimul malaaa'ikata wa kallamahumul mawtaa wa hasharnaa 'alaihim kulla shai'in qubulam maa kaanoo liyu'minooo illaaa ai yashaaa'al laahu wa laakinna aksarahum yajhaloon", "translation": "And even if We had sent down to them the angels [with the message] and the dead spoke to them [of it] and We gathered together every [created] thing in front of them, they would not believe unless Allah should will. But most of them, [of that], are ignorant."}, {"ayah": 112, "translit": "Wa kazaalika ja'alnaa likulli nabiyyin 'aduwwan Shayaateenal insi waljinni yoohee ba'duhum ilaa ba'din zukhrufal qawli ghurooraa; wa law shaaa'a Rabbuka maa fa'aloohu fazarhum wa maa yaftaroon", "translation": "And thus We have made for every prophet an enemy - devils from mankind and jinn, inspiring to one another decorative speech in delusion. But if your Lord had willed, they would not have done it, so leave them and that which they invent."}, {"ayah": 113, "translit": "Wa litasghaaa ilaihi af'idatul lazeena laa yu'minoona bil Aakhirati wa liyardawhu wa liyaqtarifoo maa hum muqtarifoon", "translation": "And [it is] so the hearts of those who disbelieve in the Hereafter will incline toward it and that they will be satisfied with it and that they will commit that which they are committing."}, {"ayah": 114, "translit": "Afaghairal laahi abtaghee hakamanw wa Huwal lazee anzala ilaikumul Kitaaba mufassalaa; wallazeena atai naahumul Kitaaba ya'lamoona annahoo munazzalum mir Rabbika bilhaqqi falaa takoonanna minal mumtareen", "translation": "[Say], \"Then is it other than Allah I should seek as judge while it is He who has revealed to you the Book explained in detail?\" And those to whom We [previously] gave the Scripture know that it is sent down from your Lord in truth, so never be among the doubters."}, {"ayah": 115, "translit": "Wa tammat Kalimatu Rabbika sidqanw wa 'adlaa; laa mubaddila li Kalimaatih; wa Huwas Samee'ul 'Aleem", "translation": "And the word of your Lord has been fulfilled in truth and in justice. None can alter His words, and He is the Hearing, the Knowing."}, {"ayah": 116, "translit": "Wa in tuti' aksara man fil ardi yudillooka 'an sabeelil laah; iny yattabi'oona illaz zanna wa in hum illaa yakhrusoon", "translation": "And if you obey most of those upon the earth, they will mislead you from the way of Allah. They follow not except assumption, and they are not but falsifying."}, {"ayah": 117, "translit": "Inna rabbaka Huwa a'lamu mai yadillu 'an sabeelihee wa Huwa a'lamu bilmuhtadeen", "translation": "Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of the [rightly] guided."}, {"ayah": 118, "translit": "Fakuloo mimmmaa zukirasmul laahi 'alaihi in kuntum bi Aayaatihee mu'mineen", "translation": "So eat of that [meat] upon which the name of Allah has been mentioned, if you are believers in His verses."}, {"ayah": 119, "translit": "Wa maa lakum allaa taakuloo mimmaa zukirasmul laahi 'alaihi wa qad fassala lakum maa harrama 'alaikum illaa mad turirtum ilaih; wa inna kaseeral la yudilloona bi ahwaaa'ihim bighairi 'ilm; inna Rabbaka Huwa a'lamu bilmu'tadeen", "translation": "And why should you not eat of that upon which the name of Allah has been mentioned while He has explained in detail to you what He has forbidden you, excepting that to which you are compelled. And indeed do many lead [others] astray through their [own] inclinations without knowledge. Indeed, your Lord - He is most knowing of the transgressors."}, {"ayah": 120, "translit": "Wa zaroo zaahiral ismi wa baatinah; innal lazeena yaksiboonal ismaa sa yujzawna bimaa kaanoo yaqtarifoon", "translation": "And leave what is apparent of sin and what is concealed thereof. Indeed, those who earn [blame for] sin will be recompensed for that which they used to commit."}, {"ayah": 121, "translit": "Wa laa taakuloo mimaa lam yuzkaris mullaahi 'alaihi wa innahoo lafisq; wa innash Shayaateena la yoohoona ilaaa awliyaaa'ihim liyujaadilookum wa in ata'tumoohum innnakum lamushrikoon", "translation": "And do not eat of that upon which the name of Allah has not been mentioned, for indeed, it is grave disobedience. And indeed do the devils inspire their allies [among men] to dispute with you. And if you were to obey them, indeed, you would be associators [of others with Him]."}, {"ayah": 122, "translit": "Awa man kaana maitan fa ahyainaahu wa ja'alnaa lahoo noorany yamshee bihee fin naasi kamamm masaluhoo fiz zulumaati laisa bikhaarijim minhaa; kazaalika zuyyina lilkaafireena maa kaanoo ya'maloon", "translation": "And is one who was dead and We gave him life and made for him light by which to walk among the people like one who is in darkness, never to emerge therefrom? Thus it has been made pleasing to the disbelievers that which they were doing."}, {"ayah": 123, "translit": "Wa kazaalika ja'alnaa fee kulli qaryatin akaabira mujrimeehaa liyamkuroo feehaa wa maa yamkuroona illaa bi anfusihim wa maa yash'uroon", "translation": "And thus We have placed within every city the greatest of its criminals to conspire therein. But they conspire not except against themselves, and they perceive [it] not."}, {"ayah": 124, "translit": "Wa izaa jaaa'athum Aayatun qaaloo lan nu'mina hatta nu'taa misla maaa ootiya Rusulul laah; Allahu a'almu haisu yaj'alu Risaalatah; sa yuseebul lazeena ajramoo saghaarun 'indal laahi wa 'azaabun shadeedum bimaa kaanoo yamkuroon", "translation": "And when a sign comes to them, they say, \"Never will we believe until we are given like that which was given to the messengers of Allah.\" Allah is most knowing of where He places His message. There will afflict those who committed crimes debasement before Allah and severe punishment for what they used to conspire."}, {"ayah": 125, "translit": "Famai yuridil laahu ai yahdiyahoo yashrah sadrahoo lil islaami wa mai yurid ai yudillaho yaj'al sadrahoo daiyiqan harajan ka annamaa yassa' 'adu fis samaaa'; kazaalika yaj'alul laahur rijsa 'alal lazeena la yu'minoon", "translation": "So whoever Allah wants to guide - He expands his breast to [contain] Islam; and whoever He wants to misguide - He makes his breast tight and constricted as though he were climbing into the sky. Thus does Allah place defilement upon those who do not believe."}, {"ayah": 126, "translit": "Wa haazaa siraatu Rabbika Mustaqeemaa; qad fassalnal Aayaati liqawminy yazzakkaroon", "translation": "And this is the path of your Lord, [leading] straight. We have detailed the verses for a people who remember."}, {"ayah": 127, "translit": "Lahum daarus salaami 'inda Rabbihim wa huwa waliyyuhum bimaa kaanoo ya'maloon", "translation": "For them will be the Home of Peace with their Lord. And He will be their protecting friend because of what they used to do."}, {"ayah": 128, "translit": "Wa yawma yahshuruhum jamee'ai yaa ma'sharal jinni qadistaksartum minal insi wa qaala awliyaaa'uhy minal insi Rabbanas tamta'a ba'dunaa biba'dinw wa balaghnaaa ajalannal lazeee ajjalta lanaa; qaalan Naaru maswaakum khaalideena feehaaa illaa maa shaaa'allaah; inna Rabbaka Hakeemun 'Aleem", "translation": "And [mention, O Muhammad], the Day when He will gather them together [and say], \"O company of jinn, you have [misled] many of mankind.\" And their allies among mankind will say, \"Our Lord, some of us made use of others, and we have [now] reached our term, which you appointed for us.\" He will say, \"The Fire is your residence, wherein you will abide eternally, except for what Allah wills. Indeed, your Lord is Wise and Knowing.\""}, {"ayah": 129, "translit": "Wa kazaalika nuwallee ba'daz zaalimeena ba'dam bimaa kaanoo yaksiboon", "translation": "And thus will We make some of the wrongdoers allies of others for what they used to earn."}, {"ayah": 130, "translit": "Yaa ma'sharal jinni wal insi alam yaatikum Rusulum minkum yaqussoona 'alaikum Aayaatee wa yunziroonakum liqaaa'a Yawmikum haazaa; qaaloo shahidnaa 'alaaa anfusinaa wa gharrat humul hayaatud dunyaa wa shahidooo 'alaa anfusihim annahum kaanoo kaafireen", "translation": "\"O company of jinn and mankind, did there not come to you messengers from among you, relating to you My verses and warning you of the meeting of this Day of yours?\" They will say, \"We bear witness against ourselves\"; and the worldly life had deluded them, and they will bear witness against themselves that they were disbelievers."}, {"ayah": 131, "translit": "Zaalika al lam yakkur Rabbuka muhlikal  quraa bizulminw wa ahluhaa ghaafiloon", "translation": "That is because your Lord would not destroy the cities for wrongdoing while their people were unaware."}, {"ayah": 132, "translit": "Wa likullin darajaatum mimmaa 'amiloo; wa maa Rabbuka bighaafilin 'ammaa ya'maloon", "translation": "And for all are degrees from what they have done. And your Lord is not unaware of what they do."}, {"ayah": 133, "translit": "Wa Rabbukal ghaniyyu zur rahmah; iny yashaaa yuz hibkum wa yastakhlif mim ba'dikum wa yastakhlif mim ba'dikum maa yashaaa'u kamaaa ansha akum min zurriyyati qawmin aakhareen", "translation": "And your Lord is the Free of need, the possessor of mercy. If He wills, he can do away with you and give succession after you to whomever He wills, just as He produced you from the descendants of another people."}, {"ayah": 134, "translit": "Inna maa too'adoona la aatinw wa maaa antum bimu'jizeen", "translation": "Indeed, what you are promised is coming, and you will not cause failure [to Allah]."}, {"ayah": 135, "translit": "Qul yaa qawmi' maloo 'alaa makaanatikum innee 'aamilun fasawfa ta'lamoona man takoonu lahoo 'aaqibatud daar; innahoo laa yuflihuz zaalimoon", "translation": "Say, \"O my people, work according to your position; [for] indeed, I am working. And you are going to know who will have succession in the home. Indeed, the wrongdoers will not succeed."}, {"ayah": 136, "translit": "Wa ja'aloo lillaahi mimmaa zara-a minal harsi walan'aami naseeban faqaaloo haazaa lillaahi biza'mihim wa haaza lishurakaa'inaa famaa kaana lishurakaaa'ihim falaa yasilu ilal laahi wa maa kaana lillaahi fahuwa yasilu ilaa shurakaaa'ihim; saaa'a maa yahkumoon", "translation": "And the polytheists assign to Allah from that which He created of crops and livestock a share and say, \"This is for Allah,\" by their claim, \"and this is for our partners [associated with Him].\" But what is for their \"partners\" does not reach Allah, while what is for Allah - this reaches their \"partners.\" Evil is that which they rule."}, {"ayah": 137, "translit": "Wa kazaalika zaiyana likaseerim minal mushrikeena qatla awlaadihim shurakaaa'uhum liyurdoohum wa liyalbisoo 'alaihim deenahum wa law shaaa'al laahu maa fa'aloohu fazarhum wa maa yaftaroon", "translation": "And likewise, to many of the polytheists their partners have made [to seem] pleasing the killing of their children in order to bring about their destruction and to cover them with confusion in their religion. And if Allah had willed, they would not have done so. So leave them and that which they invent."}, {"ayah": 138, "translit": "Wa qaaloo haaziheee an'aamunw wa harsun hijrun laa yat'amuhaaa illaa man nashaaa'u biza'mihim wa an'aamun hurrimat zuhooruhaa wa an'aamul laa yazkuroonas mal laahi 'alaihaf tiraaa'an 'alaih; sa yajzeehim bimaa kaanoo yaftaroon", "translation": "And they say, \"These animals and crops are forbidden; no one may eat from them except whom we will,\" by their claim. And there are those [camels] whose backs are forbidden [by them] and those upon which the name of Allah is not mentioned - [all of this] an invention of untruth about Him. He will punish them for what they were inventing."}, {"ayah": 139, "translit": "Wa qaaloo maa fee butooni haazihil an'aami khaalisatul lizukoorinaa wa muharramun 'alaaa azwaajinaa wa iny yakum maitatan fahum feehi shurakaaa'; sa yajzeehim wasfahum; innahoo Hakeemun  'Aleem", "translation": "And they say, \"What is in the bellies of these animals is exclusively for our males and forbidden to our females. But if it is [born] dead, then all of them have shares therein.\" He will punish them for their description. Indeed, He is Wise and Knowing."}, {"ayah": 140, "translit": "Qad khasiral lazeena qatalooo awlaadahum safaham bighairi 'ilminw wa harramoo maa razaqahumul laahuf tiraaa'an 'alal laah; qad dalloo wa maa kaanoo muhtadeen", "translation": "Those will have lost who killed their children in foolishness without knowledge and prohibited what Allah had provided for them, inventing untruth about Allah. They have gone astray and were not [rightly] guided."}, {"ayah": 141, "translit": "Wa Huwal lazee ansha-a jannaatim ma'rooshaatinw wa ghaira ma'rooshaatinw wan nakhla wazzar'a mukhtalifan ukuluhoo wazzaitoona warrum maana mutashaabihanw wa ghaira mutashaabih; kuloo min samariheee izaaa asmara wa aatoo haqqahoo yawma hasaadihee wa laa tusrifoo; innahoo laa yuhibbul musrifeen", "translation": "And He it is who causes gardens to grow, [both] trellised and untrellised, and palm trees and crops of different [kinds of] food and olives and pomegranates, similar and dissimilar. Eat of [each of] its fruit when it yields and give its due [zakah] on the day of its harvest. And be not excessive. Indeed, He does not like those who commit excess."}, {"ayah": 142, "translit": "Wa minal an'aami hamoolatanw wa farshaa; kuloo mimmaa razaqakumul laahu wa laa tattabi'oo khutuwaatish Shaitaan; innahoo lakum 'aduwwum mubeen", "translation": "And of the grazing livestock are carriers [of burdens] and those [too] small. Eat of what Allah has provided for you and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy."}, {"ayah": 143, "translit": "Samaaniyata azwaaj minad daanis naini wa minal ma'zis nain; qul 'aazzaka raini harrama amil unsaiyayni ammash tamalat 'alaihi arhaamul unsayaini nabbi 'oonee bi'ilmin in kuntum saadiqeen", "translation": "[They are] eight mates - of the sheep, two and of the goats, two. Say, \"Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Inform me with knowledge, if you should be truthful.\""}, {"ayah": 144, "translit": "Wa minal ibilis naini wa minal baqaris nain; qul 'aaazzakaraini harrama amil unsayaini ammash tamalat 'alaihi arhaamul unsayaini am kuntum shuhadaaa'a iz wassaakumul laahu bihaazaa; faman azlamu mimmanif taraa 'alal laahi kazibal liyuddillan naasa bighari 'ilm; innal laaha laa yahdil qawmaz zaalimeen", "translation": "And of the camels, two and of the cattle, two. Say, \"Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Or were you witnesses when Allah charged you with this? Then who is more unjust than one who invents a lie about Allah to mislead the people by [something] other than knowledge? Indeed, Allah does not guide the wrongdoing people.\""}, {"ayah": 145, "translit": "Qul laaa ajidu fee maaa oohiya ilaiya muharraman 'alaa taa'iminy yat'amuhooo illaaa ai yakoona maitatan aw damam masfoohan aw lahma khinzeerin fa innahoo rijsun aw fisqan uhilla lighairil laahi bih; famanid turra ghaira baa ghinw wa laa 'aadin fa inna Rabbaka Ghafoorur Raheem", "translation": "Say, \"I do not find within that which was revealed to me [anything] forbidden to one who would eat it unless it be a dead animal or blood spilled out or the flesh of swine - for indeed, it is impure - or it be [that slaughtered in] disobedience, dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], then indeed, your Lord is Forgiving and Merciful.\""}, {"ayah": 146, "translit": "Wa 'alal lazeena haadoo harramnaa kulla zee zufurinw wa minal baqari walghanami harramnaa 'alihim shuh oomahumaaa illaa maa hamalat zuhooruhumaaa awil hawaayaaa aw makhtalata bi'azm zaalika jazainaahum bibaghyihim wa innaa lasaa diqoon", "translation": "And to those who are Jews We prohibited every animal of uncloven hoof; and of the cattle and the sheep We prohibited to them their fat, except what adheres to their backs or the entrails or what is joined with bone. [By] that We repaid them for their injustice. And indeed, We are truthful."}, {"ayah": 147, "translit": "Fa in kazzabooka faqur Rabbukum zoo rahmatinw waasi'atinw waasi'atinw wa laa yuraddu baasuhoo 'anil qawmil mujrimeen", "translation": "So if they deny you, [O Muhammad], say, \"Your Lord is the possessor of vast mercy; but His punishment cannot be repelled from the people who are criminals.\""}, {"ayah": 148, "translit": "Sayaqoolul lazeena ashrakoo law shaaa'al laahu maaa ashraknaa wa laaa aabaa'unaa wa laa harramnaa min shai'; kazaalika kazzabal lazeena min qablihim hattaa zaaqoo baasanaa; qul hal 'indakum min 'ilmin fatukh rijoohu lanaa in tattabi'oona illaz zanna wa in antum illaa takhhrusoon", "translation": "Those who associated with Allah will say, \"If Allah had willed, we would not have associated [anything] and neither would our fathers, nor would we have prohibited anything.\" Likewise did those before deny until they tasted Our punishment. Say, \"Do you have any knowledge that you can produce for us? You follow not except assumption, and you are not but falsifying.\""}, {"ayah": 149, "translit": "Qul falillaahil hujjatul baalighatu falaw shaaa'a lahadaakum ajma'een", "translation": "Say, \"With Allah is the far-reaching argument. If He had willed, He would have guided you all.\""}, {"ayah": 150, "translit": "Qul halumma shuhadaaa'akumul lazeena yash hadoona annal laaha harrama haazaa fa in shahidoo falaa tashhad ma'ahum; wa laa tattabi' ahwaaa'al lazeena kazzaboo bi Aayaatinaa wallazeena laa yu'minoona bil Aakhirati wa hum bi Rabbihim ya'diloon", "translation": "Say, [O Muhammad], \"Bring forward your witnesses who will testify that Allah has prohibited this.\" And if they testify, do not testify with them. And do not follow the desires of those who deny Our verses and those who do not believe in the Hereafter, while they equate [others] with their Lord."}, {"ayah": 151, "translit": "Qul ta'aalaw atlu maa harrama Rabbukum 'alaikum allaa tushrikoo bihee shai'anw wa bilwaalidaini ihsaananw wa laa taqtulooo aw alaadakum min imlaaq; nahnu narzuqukum wa iyyaahum wa laa taqrabul fawaahisha maa zahara minhaa wa maa batana wa laa taqtulun nafsal latee harramal laahu illaa bilhaqq; zaalikum wassaakum bihee la'allakum ta'qiloon", "translation": "Say, \"Come, I will recite what your Lord has prohibited to you. [He commands] that you not associate anything with Him, and to parents, good treatment, and do not kill your children out of poverty; We will provide for you and them. And do not approach immoralities - what is apparent of them and what is concealed. And do not kill the soul which Allah has forbidden [to be killed] except by [legal] right. This has He instructed you that you may use reason.\""}, {"ayah": 152, "translit": "Wa laa taqraboo maalal yateemi illaa billatee hiyaa ahsanu hattaa yablugha ashuddahoo wa awful kaila walmeezaana bilqisti laa nukallifu nafsan illaa wus'ahaa wa izaa qultum fa'diloo wa law kaana zaa qurbaa wa bi 'ahdil laahi awfoo; zaalikum wassaakum bihee la'allakum tazakkarron", "translation": "And do not approach the orphan's property except in a way that is best until he reaches maturity. And give full measure and weight in justice. We do not charge any soul except [with that within] its capacity. And when you testify, be just, even if [it concerns] a near relative. And the covenant of Allah fulfill. This has He instructed you that you may remember."}, {"ayah": 153, "translit": "Wa annna haazaa Siraatee mustaqeeman fattabi'oohu wa laa tattabi'us subula fatafarraqa bikum 'an sabeelih; zaalikum wassaakum bihee la'allakum tattaqoon", "translation": "And, [moreover], this is My path, which is straight, so follow it; and do not follow [other] ways, for you will be separated from His way. This has He instructed you that you may become righteous."}, {"ayah": 154, "translit": "Summa aatainaa Moosal Kitaaba tammaaman 'alal lazeee ahsana wa tafseelal likulli shai'inw wa hudanw wa rahmatal la'allahum biliqaaa'i Rabbihim yu'minoon", "translation": "Then We gave Moses the Scripture, making complete [Our favor] upon the one who did good and as a detailed explanation of all things and as guidance and mercy that perhaps in [the matter of] the meeting with their Lord they would believe."}, {"ayah": 155, "translit": "Wa haazaa Kitaabun anzalnaahu Mubaarakun fattabi'oohu wattaqoo la'al lakum urhamoon", "translation": "And this [Qur'an] is a Book We have revealed [which is] blessed, so follow it and fear Allah that you may receive mercy."}, {"ayah": 156, "translit": "An taqooloo innammaaa unzilal Kitaabu 'alaa taaa'ifataini min qablinaa wa in kunnaa 'an diraasatihim laghaafileen", "translation": "[We revealed it] lest you say, \"The Scripture was only sent down to two groups before us, but we were of their study unaware,\""}, {"ayah": 157, "translit": "Aw taqooloo law annaaa unzila 'alainal kitaabu lakunnaaa ahdaa minhum; faqad jaaa'akum baiyinatum mir Rabbikum wa hudanw wa rahmah; faman azlamu mimman kazzaba bi Aayaatil laahi wa sadaf 'anhaa; sanajzil lazeena yasdifoona 'an Aayaatinaa sooo'al 'azaabi bimaa kaanoo yasdifoon", "translation": "Or lest you say, \"If only the Scripture had been revealed to us, we would have been better guided than they.\" So there has [now] come to you a clear evidence from your Lord and a guidance and mercy. Then who is more unjust than one who denies the verses of Allah and turns away from them? We will recompense those who turn away from Our verses with the worst of punishment for their having turned away."}, {"ayah": 158, "translit": "hal yanzuroona illaaa an taatiyahumul malaaa'ikatu aw yaatiya Rabbuka aw yaatiya ba'du Aayaati Rabbik; yawma yaatee ba'du Aayaati Rabbika laa yanfa'u nafsan eemaanuhaa lam takun aamanat min qablu aw kasabat feee eemaanihaa khairaa; qulin tazirooo innaa muntaziroon", "translation": "Do they [then] wait for anything except that the angels should come to them or your Lord should come or that there come some of the signs of your Lord? The Day that some of the signs of your Lord will come no soul will benefit from its faith as long as it had not believed before or had earned through its faith some good. Say, \"Wait. Indeed, we [also] are waiting.\""}, {"ayah": 159, "translit": "Innal lazeena farraqoo deenahum wa kaanoo shiya'allasta minhum fee shai'; innamaaa amruhum ilallaahi summma yunabbi'uhum bimaa kaanoo yaf'aloon", "translation": "Indeed, those who have divided their religion and become sects - you, [O Muhammad], are not [associated] with them in anything. Their affair is only [left] to Allah; then He will inform them about what they used to do."}, {"ayah": 160, "translit": "man jaaa'a bilhasanati falahoo 'ashru amsaalihaa wa man jaaa'a bissaiyi'ati falaa yujzaaa illaa mislahaa wa hum laa yuzlamoon", "translation": "Whoever comes [on the Day of Judgement] with a good deed will have ten times the like thereof [to his credit], and whoever comes with an evil deed will not be recompensed except the like thereof; and they will not be wronged."}, {"ayah": 161, "translit": "Qul innanee hadaanee Rabbeee ilaa Siraatim Mustaqeemin deenan qiyamam Millata Ibraaheema haneefaa; wa maa kaana minal mushrikeen", "translation": "Say, \"Indeed, my Lord has guided me to a straight path - a correct religion - the way of Abraham, inclining toward truth. And he was not among those who associated others with Allah.\""}, {"ayah": 162, "translit": "Qul inna Salaatee wa nusukee wa mahyaaya wa mamaatee lillaahi Rabbil 'aalameen", "translation": "Say, \"Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allah, Lord of the worlds."}, {"ayah": 163, "translit": "Laa shareeka lahoo wa bizaalika umirtu wa ana awwalul muslimeen", "translation": "No partner has He. And this I have been commanded, and I am the first [among you] of the Muslims.\""}, {"ayah": 164, "translit": "Qul aghairal laahi abhee Rabbanw wa Huwa Rabbu kulli shai'; wa laa taksibu kullu nafsin illaa 'alaihaa; wa laa taziru waaziratunw wizra ukhraa; summa ilaa Rabbikum marji'ukum fa yunabbi'ukum bimaa kuntum feehi takhtalifoon", "translation": "Say, \"Is it other than Allah I should desire as a lord while He is the Lord of all things? And every soul earns not [blame] except against itself, and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you concerning that over which you used to differ.\""}, {"ayah": 165, "translit": "Wa Huwal lazee ja'alakum khalaaa'ifal ardi wa rafa'a ba'dakum fawqa ba'din darajaatil liyabluwakum fee maaa aataakum; inna Rabbaka saree'ul 'iqaab; wa innahoo la Ghafoorur Raheem", "translation": "And it is He who has made you successors upon the earth and has raised some of you above others in degrees [of rank] that He may try you through what He has given you. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful."}]}, {"num": 7, "name": "Al-A'raf", "meaning": "The Heights", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Meeem-Saaad", "translation": "Alif, Lam, Meem, Sad."}, {"ayah": 2, "translit": "Kitaabun unzila ilaika falaa yakum fee sadrika harajum minhu litunzira bihee wa zikraa lilmu'mineen", "translation": "[This is] a Book revealed to you, [O Muhammad] - so let there not be in your breast distress therefrom - that you may warn thereby and as a reminder to the believers."}, {"ayah": 3, "translit": "Ittabi'oo maaa unzila 'ilaikum mir Rabbikum wa laa tattabi'oo min dooniheee awliyaaa'; qaleelam maa tazakkaroon", "translation": "Follow, [O mankind], what has been revealed to you from your Lord and do not follow other than Him any allies. Little do you remember."}, {"ayah": 4, "translit": "Wa kam min qaryatin ahlaknaahaa fajaaa'ahaa baasunaa bayaatan aw hum qaaa'iloon", "translation": "And how many cities have We destroyed, and Our punishment came to them at night or while they were sleeping at noon."}, {"ayah": 5, "translit": "Famaa kaana da'waahum iz jaaa'ahum baasunaa illaaa an qaalooo innaa kunnaa zaalimeen", "translation": "And their declaration when Our punishment came to them was only that they said, \"Indeed, we were wrongdoers!\""}, {"ayah": 6, "translit": "Falanas 'alannal lazeena ursila ilaihim wa lanas 'alannal mursaleen", "translation": "Then We will surely question those to whom [a message] was sent, and We will surely question the messengers."}, {"ayah": 7, "translit": "Falanaqussanna 'alaihim bi'ilminw wa maa kunnaa ghaaa'ibeen", "translation": "Then We will surely relate [their deeds] to them with knowledge, and We were not [at all] absent."}, {"ayah": 8, "translit": "Walwaznu Yawma'izinil haqq; faman saqulat mawaa zeenuhoo fa-ulaaa'ika humul muflihoon", "translation": "And the weighing [of deeds] that Day will be the truth. So those whose scales are heavy - it is they who will be the successful."}, {"ayah": 9, "translit": "Wa man khaffat mawaazeenuhoo fa ulaaa'ikal lazeena khasirooo anfusahum bimaa kaanoo bi Aayaatinaa yazlimoon", "translation": "And those whose scales are light - they are the ones who will lose themselves for what injustice they were doing toward Our verses."}, {"ayah": 10, "translit": "Wa laqad makkannaakum fil ardi wa ja'alnaa lakum feehaa ma'aayish; qaleelam maa tashkuroon", "translation": "And We have certainly established you upon the earth and made for you therein ways of livelihood. Little are you grateful."}, {"ayah": 11, "translit": "Wa laqad khalaqnaakum summa sawwarnaakum summa qulnaa lilmalaaa'ikatis judoo li Aadama fa-sajadooo illaaa Ibleesa lam yakum minas saajideen", "translation": "And We have certainly created you, [O Mankind], and given you [human] form. Then We said to the angels, \"Prostrate to Adam\"; so they prostrated, except for Iblees. He was not of those who prostrated."}, {"ayah": 12, "translit": "Qaala maa mana'aka allaa tasjuda iz amartuka qaala ana khairum minhu khalaqtanee min naarinw wa khalaqtahoo min teen", "translation": "[Allah] said, \"What prevented you from prostrating when I commanded you?\" [Satan] said, \"I am better than him. You created me from fire and created him from clay.\""}, {"ayah": 13, "translit": "Qaala fahbit minhaa famaa yakoonu laka an tatakabbara feehaa fakhruj innaka minas saaghireen", "translation": "[Allah] said, \"Descend from Paradise, for it is not for you to be arrogant therein. So get out; indeed, you are of the debased."}, {"ayah": 14, "translit": "Qaala anzirneee ilaa Yawmi yub'asoon", "translation": "[Satan] said, \"Reprieve me until the Day they are resurrected.\""}, {"ayah": 15, "translit": "Qaala innaka minal munzareen", "translation": "[Allah] said, \"Indeed, you are of those reprieved.\""}, {"ayah": 16, "translit": "Qaala fabimaaa aghway tanee la aq'udanna lahum Siraatakal Mustaqeem", "translation": "[Satan] said, \"Because You have put me in error, I will surely sit in wait for them on Your straight path."}, {"ayah": 17, "translit": "Summa la aatiyannahum mim baine aideehim wa min khalfihim wa 'an aimaanihim wa 'an shamaaa'ilihim wa laa tajidu aksarahum shaakireen", "translation": "Then I will come to them from before them and from behind them and on their right and on their left, and You will not find most of them grateful [to You].\""}, {"ayah": 18, "translit": "Qaalakh ruj mnhaa maz'oomam madhooraa; laman tabi'aka minhum la amla'anna Jahannama minkum ajma'een", "translation": "[Allah] said, \"Get out of Paradise, reproached and expelled. Whoever follows you among them - I will surely fill Hell with you, all together.\""}, {"ayah": 19, "translit": "Wa yaaa Aadamus kun anta wa zawjukal Jannata fakulaa min haisu shi'tumaa wa laa taqrabaa haazihish shajarata fatakoonaa minza zaalimeen", "translation": "And \"O Adam, dwell, you and your wife, in Paradise and eat from wherever you will but do not approach this tree, lest you be among the wrongdoers.\""}, {"ayah": 20, "translit": "Fawaswasa lahumash Shaitaanu liyubdiya lahumaa maa wooriya 'anhumaa min saw aatihimaa wa qaala maa nahaakumaa Rabbukumaa 'an haazihish shajarati illaaa an takoonaa malakaini aw takoonaa minal khaalideen", "translation": "But Satan whispered to them to make apparent to them that which was concealed from them of their private parts. He said, \"Your Lord did not forbid you this tree except that you become angels or become of the immortal.\""}, {"ayah": 21, "translit": "Wa qaasamahumaaa innee lakumaa laminan naasiheen", "translation": "And he swore [by Allah] to them, \"Indeed, I am to you from among the sincere advisors.\""}, {"ayah": 22, "translit": "Fadallaahumaa bighuroor; falammaa zaaqash shajarata badat lahumaa saw aatuhumaa wa tafiqaa yakhsifaani 'alaihimaa minw waraqil jannati wa naadaahumaa Rabbuhumaaa alam anhakumaa 'an tilkumash shajarati wa aqul lakumaaa innash Shaitaana lakumaa 'aduwwum mubeen", "translation": "So he made them fall, through deception. And when they tasted of the tree, their private parts became apparent to them, and they began to fasten together over themselves from the leaves of Paradise. And their Lord called to them, \"Did I not forbid you from that tree and tell you that Satan is to you a clear enemy?\""}, {"ayah": 23, "translit": "Qaalaa Rabbanaa zalamnaaa anfusanaa wa illam taghfir lanaa wa tarhamnaa lanakoonanna minal khaasireen", "translation": "They said, \"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.\""}, {"ayah": 24, "translit": "Qaalah bitoo ba'dukum liba'din aduwwunw wa lakum fil ardi mmustaqarrunw wa mataa'un ilaaheen", "translation": "[Allah] said, \"Descend, being to one another enemies. And for you on the earth is a place of settlement and enjoyment for a time.\""}, {"ayah": 25, "translit": "Qaala feehaa tahyawna wa feehaa tamootoona wa minhaa tukhrajoon (section 2)", "translation": "He said, \"Therein you will live, and therein you will die, and from it you will be brought forth.\""}, {"ayah": 26, "translit": "Yaa Baneee Aadama qad anzalnaa 'alaikum libaasany yuwaaree saw aatikum wa reeshanw wa libaasut taqwaa zaalika khair; zaalika min Aayaatil laahi la'allahum yaz zakkaroon", "translation": "O children of Adam, We have bestowed upon you clothing to conceal your private parts and as adornment. But the clothing of righteousness - that is best. That is from the signs of Allah that perhaps they will remember."}, {"ayah": 27, "translit": "Yaa Banee Aadama laa yaftinannnakumush Shaitaanu kamaaa akhraja abawaikum minal Jannati yanzi'u 'anhumaa libaasahumaa liyuriyahumaa saw aatihimaaa; innahoo yaraakum huwa wa qabeeluhoo min haisu laa tarawnahum; innaa ja'alnash Shayaateena awliyaaa'a lillazeena laa yu'minoon", "translation": "O children of Adam, let not Satan tempt you as he removed your parents from Paradise, stripping them of their clothing to show them their private parts. Indeed, he sees you, he and his tribe, from where you do not see them. Indeed, We have made the devils allies to those who do not believe."}, {"ayah": 28, "translit": "Wa izaa fa'aloo faahishatan qaaloo wajadnaa 'alaihaaa aabaaa'ana wallaahu amaranaa bihaa; qul innal laaha laa yaamuru bilfahshaaa'i a-taqooloona 'alal laahi mmaa laa ta'lamoon", "translation": "And when they commit an immorality, they say, \"We found our fathers doing it, and Allah has ordered us to do it.\" Say, \"Indeed, Allah does not order immorality. Do you say about Allah that which you do not know?\""}, {"ayah": 29, "translit": "Qul amara Rabbee bilqisti wa aqeemoo wujoohakum 'inda kulli masjidin wad'oohu mukhliseena lahud deen; kamaa bada akum ta'oodoon", "translation": "Say, [O Muhammad], \"My Lord has ordered justice and that you maintain yourselves [in worship of Him] at every place [or time] of prostration, and invoke Him, sincere to Him in religion.\" Just as He originated you, you will return [to life] -"}, {"ayah": 30, "translit": "Fareeqan hadaa wa fareeqan haqqa 'alaihimud dalaalah; innahumut takhazush Shayaateena awliyaaa'a min doonil laahi wa yahsaboona annnahum muhtadoon", "translation": "A group [of you] He guided, and a group deserved [to be in] error. Indeed, they had taken the devils as allies instead of Allah while they thought that they were guided."}, {"ayah": 31, "translit": "Yaa Banneee Adama khuzoo zeenatakum 'inda kulli masjidinw wa kuloo washraboo wa laa tusrifoo; innahoo laa yuhibbul musrifeen", "translation": "O children of Adam, take your adornment at every masjid, and eat and drink, but be not excessive. Indeed, He likes not those who commit excess."}, {"ayah": 32, "translit": "Qul man harrama zeenatal laahil lateee akhraja li'ibaadihee wattaiyibaati minar rizq; qul hiya lillazeena aamanoo fil hayaatid dunyaa khaalisatany Yawmal Qiyaamah; kazaalika nufassihul Aayaati liqawminy ya'lamoon", "translation": "Say, \"Who has forbidden the adornment of Allah which He has produced for His servants and the good [lawful] things of provision?\" Say, \"They are for those who believe during the worldly life [but] exclusively for them on the Day of Resurrection.\" Thus do We detail the verses for a people who know."}, {"ayah": 33, "translit": "Qul innamaa harrama Rabbiyal fawaahisha maa zahara minhaa wa maa bataa wal isma walbaghya bighairil haqqi wa an tushrikoo billaahi maa lam yunazzil bihee sultaananw wa an taqooloo 'alal laahi maa laa ta'lamoon", "translation": "Say, \"My Lord has only forbidden immoralities - what is apparent of them and what is concealed - and sin, and oppression without right, and that you associate with Allah that for which He has not sent down authority, and that you say about Allah that which you do not know.\""}, {"ayah": 34, "translit": "Wa likulli ummatin ajalun fa izaa jaaa'a ajaluhum laa yastaakhiroona saa'atanw wa laa yastaqdimoon", "translation": "And for every nation is a [specified] term. So when their time has come, they will not remain behind an hour, nor will they precede [it]."}, {"ayah": 35, "translit": "yaa Banee Aadama immaa yaatiyannakum Rusulum minkum yaqussoona 'alaikum Aayaatee famanit taqaa wa aslaha falaa khawfun 'alaihim wa laa hum yahzanoon", "translation": "O children of Adam, if there come to you messengers from among you relating to you My verses, then whoever fears Allah and reforms - there will be no fear concerning them, nor will they grieve."}, {"ayah": 36, "translit": "Wallazeena kazzaboo bi Aayaatinaa wastakbaroo 'anhhaaa ulaaa'ika Ashaabun naari hum feehaa khaalidoon", "translation": "But the ones who deny Our verses and are arrogant toward them - those are the companions of the Fire; they will abide therein eternally."}, {"ayah": 37, "translit": "Faman azlamu mimmanif taraa 'alal laahi kaziban aw kazzaba bi Aayaatih; ulaaa'ika yanaaluhum naseebuhum minal Kitaab; hataaa izaa jaaa'at hum rusulunaa yatawaf fawnahum qaalooo aina maa kuntum tad'oonaa min doonil laahi qaaloo dalloo 'annaa wa shahidoo 'alaaa anfusihim annahum kaanoo kaafieen", "translation": "And who is more unjust than one who invents about Allah a lie or denies His verses? Those will attain their portion of the decree until when Our messengers come to them to take them in death, they will say, \"Where are those you used to invoke besides Allah?\" They will say, \"They have departed from us,\" and will bear witness against themselves that they were disbelievers."}, {"ayah": 38, "translit": "Qaalad khuloo feee umamin qad khalat min qablikum minal jinni wal insifin naari kullamaa dakhalat ummatul la'anat ukhtahaa hattaaa izad daarakoo feehaa jamee'an qaalat ukhraahum li oolaahum Rabbannaa haaa'u laaa'i adalloonaa fa aatihim 'azaaban di'fam minan naari qaala likullin di funw wa laakil laa ta'lamoon", "translation": "[Allah] will say, \"Enter among nations which had passed on before you of jinn and mankind into the Fire.\" Every time a nation enters, it will curse its sister until, when they have all overtaken one another therein, the last of them will say about the first of them \"Our Lord, these had misled us, so give them a double punishment of the Fire. He will say, \"For each is double, but you do not know.\""}, {"ayah": 39, "translit": "Wa qaalat oolaahum li ukhraahum famaa kaana lakum 'alainaa min fadlin fazooqul azaaba bimaa kuntum taksiboon", "translation": "And the first of them will say to the last of them, \"Then you had not any favor over us, so taste the punishment for what you used to earn.\""}, {"ayah": 40, "translit": "Innal lazeena kazzaboo bi Aayaatinaa wastakbaroo 'anhaa laa tufattahu lahum ahwaabus samaaa'i wa laa yadkhuloonal jannata hattaa yalijal jamalu fee sammil khiyaat; wa kazaalika najzil mujrimeen", "translation": "Indeed, those who deny Our verses and are arrogant toward them - the gates of Heaven will not be opened for them, nor will they enter Paradise until a camel enters into the eye of a needle. And thus do We recompense the criminals."}, {"ayah": 41, "translit": "Lahum min jahannama mihaadunw wa min fawqihim ghawaash; wa kazaalika najziz zaalimeen", "translation": "They will have from Hell a bed and over them coverings [of fire]. And thus do We recompense the wrongdoers."}, {"ayah": 42, "translit": "Wallazeena aamanoo wa 'amilus saalihaati la nukallifu nafsan illaa wus'ahaaa ulaaa'ika Ashaabul jannati hum feehaa khaalidoon", "translation": "But those who believed and did righteous deeds - We charge no soul except [within] its capacity. Those are the companions of Paradise; they will abide therein eternally."}, {"ayah": 43, "translit": "Wa naza'naa maa fee sudoorihim min ghillin tajree min tahtihimul anhaaru wa qaalul hamdu lillaahil lazee hadaanaa lihaaza wa maa kunna linahtadiya law laaa ann hadaanal laahu laqad jaaa'at Rusulu Rabbinaa bilhaqq; wa noodoo an tilkumul jannnatu ooristumoohaa bimaa kuntum ta'maloon", "translation": "And We will have removed whatever is within their breasts of resentment, [while] flowing beneath them are rivers. And they will say, \"Praise to Allah, who has guided us to this; and we would never have been guided if Allah had not guided us. Certainly the messengers of our Lord had come with the truth.\" And they will be called, \"This is Paradise, which you have been made to inherit for what you used to do.\""}, {"ayah": 44, "translit": "Wa naadaa Ashaabul jannati ashaaban Naari an qad wajadnaa maa wa'adannaa Rabbunaa haqqan fahal wajattum maa wa'ada Rabbukum haqqan qaaloo na'am; fa azzana mu'azzinum bainahum al la'natul laahi 'alaz zaalimeen", "translation": "And the companions of Paradise will call out to the companions of the Fire, \"We have already found what our Lord promised us to be true. Have you found what your Lord promised to be true?\" They will say, \"Yes.\" Then an announcer will announce among them, \"The curse of Allah shall be upon the wrongdoers.\""}, {"ayah": 45, "translit": "Allazeena yasuddoona 'an sabeelil laahi wa yabghoo nahaa 'iwajanw wa hum bil Aakhirati kaafiroon", "translation": "Who averted [people] from the way of Allah and sought to make it [seem] deviant while they were, concerning the Hereafter, disbelievers."}, {"ayah": 46, "translit": "Wa bainahumaa hijaab; wa 'alal A'raafi rijaaluny ya'rifoona kullam biseemaahum; wa naadaw Ashaabal jannati an salaamun 'alaikum; lam yadkhuloohaa wa hum yatma'oon", "translation": "And between them will be a partition, and on [its] elevations are men who recognize all by their mark. And they call out to the companions of Paradise, \"Peace be upon you.\" They have not [yet] entered it, but they long intensely."}, {"ayah": 47, "translit": "Wa izaa surifat absaaruhum tilqaaa'a Ashaabin Naari qaalo Rabbanaa laa taj'alnaa ma'al qawmiz zaalimneen", "translation": "And when their eyes are turned toward the companions of the Fire, they say, \"Our Lord, do not place us with the wrongdoing people.\""}, {"ayah": 48, "translit": "Wa naadaaa Ashaabul A'raffi rijaalany ya'rifoonahum biseemaahum qaaloo maaa aghnaa 'ankum jam'ukum wa maa kuntum tastakbiroon", "translation": "And the companions of the Elevations will call to men [within Hell] whom they recognize by their mark, saying, \"Of no avail to you was your gathering and [the fact] that you were arrogant.\""}, {"ayah": 49, "translit": "A haaa'ulaaa'il lazeena aqsamtum laa yanaaluhumul laahu birahma; udkhulul Jannata laa khawfun 'alaikum wa laaa antum tahzanoon", "translation": "[Allah will say], \"Are these the ones whom you [inhabitants of Hell] swore that Allah would never offer them mercy? Enter Paradise, [O People of the Elevations]. No fear will there be concerning you, nor will you grieve.\""}, {"ayah": 50, "translit": "Wa naadaaa Ashaabun Naari Ashaabal jannati an afeedoo 'alainaa minal maaa'i aw mimma razaqakumul laah; qaaloo innal laaha harrama humaa 'alal kaafireen", "translation": "And the companions of the Fire will call to the companions of Paradise, \"Pour upon us some water or from whatever Allah has provided you.\" They will say, \"Indeed, Allah has forbidden them both to the disbelievers.\""}, {"ayah": 51, "translit": "Allazeenat takhazoo deenahu lahwanw wa la'i-banw wa gharrat humul hayaatud dunyaa; fal Yawma nnannsaahum kamaa nasoo liqaaa'a Yawmihim haazaa wa maa kaanoo bi aayaatinaa yajhadoon", "translation": "Who took their religion as distraction and amusement and whom the worldly life deluded.\" So today We will forget them just as they forgot the meeting of this Day of theirs and for having rejected Our verses."}, {"ayah": 52, "translit": "Wa laqad ji'naahum bi Kitaabin fassalnaahu 'alaa 'ilmin hudanw wa rahmatal liqawminy-yu'miinoon", "translation": "And We had certainly brought them a Book which We detailed by knowledge - as guidance and mercy to a people who believe."}, {"ayah": 53, "translit": "hal yanzuroona illaa taa weelah; yawma yaatee taaweeluhoo yaqoolul lazeena nasoohu min qablu qad jaaa'at Rusulu Rabbinaa bilhaqq; fahal lanaa min shufa'aaa'a fa yashfa'oo lanaaa aw nuraddu fana'mala ghairal lazee kunnaa na'mal; qad khasirooo anfusahum wa dalla 'anhum maa kaanoo yaftaroon", "translation": "Do they await except its result? The Day its result comes those who had ignored it before will say, \"The messengers of our Lord had come with the truth, so are there [now] any intercessors to intercede for us or could we be sent back to do other than we used to do?\" They will have lost themselves, and lost from them is what they used to invent."}, {"ayah": 54, "translit": "Inna Rabbakkumul laahul lazee khalaqas sammaawaati wal arda fee sittati qiyaamin summmas tawaa 'alal 'arshi yughshil lailan nahaara yatlu buhoo haseesanw washshamsa walqamara wannujooma musakhkharaatim bi amrih; alaa lahul khalqu wal-amr; tabaarakal laahu Rabbul 'aalameen", "translation": "Indeed, your Lord is Allah, who created the heavens and earth in six days and then established Himself above the Throne. He covers the night with the day, [another night] chasing it rapidly; and [He created] the sun, the moon, and the stars, subjected by His command. Unquestionably, His is the creation and the command; blessed is Allah, Lord of the worlds."}, {"ayah": 55, "translit": "Ud'oo Rabbakum tadarru'anw wa khufyah; innahoo laa yuhibbul mu'tadeen", "translation": "Call upon your Lord in humility and privately; indeed, He does not like transgressors."}, {"ayah": 56, "translit": "Wa laa tufsidoo fil ardi ba'da islaahihaa wad'oohu khawfanw wa tama'aa; inna rahmatal laahi qareebum minal muhsineen", "translation": "And cause not corruption upon the earth after its reformation. And invoke Him in fear and aspiration. Indeed, the mercy of Allah is near to the doers of good."}, {"ayah": 57, "translit": "Wa Huwal lazee yursilur riyaaha bushram baina yadai rahmatihee hattaaa izaaa aqallat sahaaban siqaalan suqnaahu libaladim maiyitin fa annzalnaa bihil maaa'a fa akhrajnaa bihee minn kullis samaraat; kazaalika nukhrijul mawtaa la'allakum tazakkaroon", "translation": "And it is He who sends the winds as good tidings before His mercy until, when they have carried heavy rainclouds, We drive them to a dead land and We send down rain therein and bring forth thereby [some] of all the fruits. Thus will We bring forth the dead; perhaps you may be reminded."}, {"ayah": 58, "translit": "Walbaladut taiyibu yakhruju nabaatuhoo bi-izni Rabbihee wallazee khabusa laa yakhruju illaa nakidaa; kazaalika nusarriful Aayaati liqawminy yashkuroon", "translation": "And the good land - its vegetation emerges by permission of its Lord; but that which is bad - nothing emerges except sparsely, with difficulty. Thus do We diversify the signs for a people who are grateful."}, {"ayah": 59, "translit": "Laqad arsalnaa noohan ilaa qawmihee faqaala yaa qawmi' budul laaha maa lakum min ilaahin ghairuhoo inneee akhaafu 'alaikum 'azaaba Yawmin 'Azeem", "translation": "We had certainly sent Noah to his people, and he said, \"O my people, worship Allah; you have no deity other than Him. Indeed, I fear for you the punishment of a tremendous Day."}, {"ayah": 60, "translit": "Qaalal mala-u min qaw miheee innaa lanaraaka fee dalaalim mubeen", "translation": "Said the eminent among his people, \"Indeed, we see you in clear error.\""}, {"ayah": 61, "translit": "Qaala yaa qawmi laisa bee dalaalatunw wa laakinnee Rasoolum mir Rabbil 'aalameen", "translation": "[Noah] said, \"O my people, there is not error in me, but I am a messenger from the Lord of the worlds.\""}, {"ayah": 62, "translit": "Uballighukum Risaalaati Rabbee wa ansahu lakum wa a'lamu minal laahi maa laa ta'lamoon", "translation": "I convey to you the messages of my Lord and advise you; and I know from Allah what you do not know."}, {"ayah": 63, "translit": "awa'ajibtum an jaaa'akum zikrum mir Rabbikum 'alaa rajulim minkum liyunzirakum wa litattaqoo wa la'allakum turhamoon", "translation": "Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you and that you may fear Allah so you might receive mercy.\""}, {"ayah": 64, "translit": "Fakazzaboohu fa anjai naahu wallazeena ma'ahoo fil fulki wa aghraqnal lazeena kazzaboo bi Aayaatinaa; innahum kaanoo qawman 'ameen", "translation": "But they denied him, so We saved him and those who were with him in the ship. And We drowned those who denied Our signs. Indeed, they were a blind people."}, {"ayah": 65, "translit": "Wa ilaa 'aadin akhaahum Hoodaa; qaala yaa qawmi' budul laaha maa lakum min ilaahin ghairuh; afalaa tattaqoon", "translation": "And to the 'Aad [We sent] their brother Hud. He said, \"O my people, worship Allah; you have no deity other than Him. Then will you not fear Him?\""}, {"ayah": 66, "translit": "Qaalal mala ul lazeena kafaroo min qawmiheee innaa lanaraaka fee safaahatinw wa innaa lannazunnuka minal kaazibeen", "translation": "Said the eminent ones who disbelieved among his people, \"Indeed, we see you in foolishness, and indeed, we think you are of the liars.\""}, {"ayah": 67, "translit": "Qaala yaa qawmi laisa bee safaahatunw wa laakinnee Rasoolum mir Rabbil 'aalameen", "translation": "[Hud] said, \"O my people, there is not foolishness in me, but I am a messenger from the Lord of the worlds.\""}, {"ayah": 68, "translit": "Uballighukum Risaalaati Rabbee wa ana lakum naasihun ameen", "translation": "I convey to you the messages of my Lord, and I am to you a trustworthy adviser."}, {"ayah": 69, "translit": "awa 'ajibtum an jaaa'akum zikrum mir Rabbikum 'alaa rajulim minkum liyunzirakum; wazkurooo iz ja'alakum khulafaaa'a mim ba'di qawmi noohinw wa zaadakum filkhalqi bastatan fazkurooo aalaaa'al laahi la'allakum tuflihoon", "translation": "Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you? And remember when He made you successors after the people of Noah and increased you in stature extensively. So remember the favors of Allah that you might succeed."}, {"ayah": 70, "translit": "Qaalooo aji'tanaa lina'budal laaha wahdahoo wa nazara maa kaana ya'budu aabaaa'u naa faatinaa bimaa ta'idunaaa in kunta minas saadiqeen", "translation": "They said, \"Have you come to us that we should worship Allah alone and leave what our fathers have worshipped? Then bring us what you promise us, if you should be of the truthful.\""}, {"ayah": 71, "translit": "Qaala qad waqa'a alaikum mir Rabbikum rijsunw wa ghadab, atujaadiloonanee feee asmaaa'in sammaitumoohaaa antum wa aabaaa'ukum maa nazzalal laahu bihaa min sultaan; fantazirooo innee ma'akum minal muntazireen", "translation": "[Hud] said, \"Already have defilement and anger fallen upon you from your Lord. Do you dispute with me concerning [mere] names you have named them, you and your fathers, for which Allah has not sent down any authority? Then wait; indeed, I am with you among those who wait.\""}, {"ayah": 72, "translit": "Fa anjainaahu wallazeena ma'ahoo birahmatim minnaa wa qata'naa daabiral lazeena kazzaboo bi Aayaatinaa wa maa kaanoo mu'mineen", "translation": "So We saved him and those with him by mercy from Us. And We eliminated those who denied Our signs, and they were not [at all] believers."}, {"ayah": 73, "translit": "Wa ilaa Samooda akhaahum Saalihaa; qaala yaa qawmi' budul laaha maa lakum min ilaahin ghairuhoo qad jaaa'atkum baiyinatum mir Rabbikum haazihee naaqatul laahi lakum Aayatan fazaroohaa taakul feee ardil laahi wa laa tamassoohaa bisooo'in fa yaakhuzakum 'azaabun aleem", "translation": "And to the Thamud [We sent] their brother Salih. He said, \"O my people, worship Allah; you have no deity other than Him. There has come to you clear evidence from your Lord. This is the she-camel of Allah [sent] to you as a sign. So leave her to eat within Allah 's land and do not touch her with harm, lest there seize you a painful punishment."}, {"ayah": 74, "translit": "Wazkkurooo iz ja'alakum khulafaaa'a mim ba'di 'Aadinw wa bawwa akum fil ardi tattakhizoona min suhoolihaa qusooranw wa tanhitoonal jibaala buyootan fazkurooo aalaaa'al laahi wa laa ta'saw fil ardi mufsideen", "translation": "And remember when He made you successors after the 'Aad and settled you in the land, [and] you take for yourselves palaces from its plains and carve from the mountains, homes. Then remember the favors of Allah and do not commit abuse on the earth, spreading corruption.\""}, {"ayah": 75, "translit": "Qaalal mala ul lazeenas takbaroo min qawmihee lillazeenas tud'ifoo liman aamana minhum ata'almoona anna Saaliham mursalum mir Rabbih; qaalooo innaa bimaaa ursila bihee mu'minoon", "translation": "Said the eminent ones who were arrogant among his people to those who were oppressed - to those who believed among them, \"Do you [actually] know that Salih is sent from his Lord?\" They said, \"Indeed we, in that with which he was sent, are believers.\""}, {"ayah": 76, "translit": "Qaalal lazeenas takbarooo innaa billazeee aamanntum bihee kaafiroon", "translation": "Said those who were arrogant, \"Indeed we, in that which you have believed, are disbelievers.\""}, {"ayah": 77, "translit": "Fa'aqarun naaqata wa'ataw 'an amri Rabbihim wa qaaloo yaa Saalihu' tinaa bimaa ta'idunaaa in kunta minal mursaleen", "translation": "So they hamstrung the she-camel and were insolent toward the command of their Lord and said, \"O Salih, bring us what you promise us, if you should be of the messengers.\""}, {"ayah": 78, "translit": "Fa akhazat humur rajftu fa asbahoo fee daarihim jaasimmeen", "translation": "So the earthquake seized them, and they became within their home [corpses] fallen prone."}, {"ayah": 79, "translit": "Fa tawalla 'anhum wa qaala yaa qawmi laqad ablaghtukum Risaalata Rabbee wa nasahtu lakum wa laakil laa tuhibboonan naasiheen", "translation": "And he turned away from them and said, \"O my people, I had certainly conveyed to you the message of my Lord and advised you, but you do not like advisors.\""}, {"ayah": 80, "translit": "Wa Lootan iz qaala liqawmiheee ataatoonal faahishata maa sabaqakum bihaa min ahadim minal 'aalameen", "translation": "And [We had sent] Lot when he said to his people, \"Do you commit such immorality as no one has preceded you with from among the worlds?"}, {"ayah": 81, "translit": "Innakum lataatoonar rijaala shahwatam min doonin nisaaa'; bal antumqawmum musrifoon", "translation": "Indeed, you approach men with desire, instead of women. Rather, you are a transgressing people.\""}, {"ayah": 82, "translit": "Wa maa kaana jawaaba qawmihee illaa an qaalooo akhrijoohum min qaryatikum innahum unaasuny yatatah haroon", "translation": "But the answer of his people was only that they said, \"Evict them from your city! Indeed, they are men who keep themselves pure.\""}, {"ayah": 83, "translit": "Fa anjainaahu wa ahlahooo illam ra atahoo kaanat minal ghaabireen", "translation": "So We saved him and his family, except for his wife; she was of those who remained [with the evildoers]."}, {"ayah": 84, "translit": "Wa 'amtarnaa 'alaihim mataran fanzur kaifa kaana aaqibatul mujjrimeen", "translation": "And We rained upon them a rain [of stones]. Then see how was the end of the criminals."}, {"ayah": 85, "translit": "Wa ilaa Madyana akhaahum Shu'aybaa; qaala yaa qawmi' budul laaha maa lakum min ilaahin ghairuhoo qad jaaa'atkum baiyinatum mir Rabbikum fa awful kaila walmeezaana wa laa tabkhasun naasa ashyaa'ahum wa laa tufsidoo fil ardi ba'da islaahihaa; zaalikum khairul lakum in kuntum mu'mineen", "translation": "And to [the people of] Madyan [We sent] their brother Shu'ayb. He said, \"O my people, worship Allah; you have no deity other than Him. There has come to you clear evidence from your Lord. So fulfill the measure and weight and do not deprive people of their due and cause not corruption upon the earth after its reformation. That is better for you, if you should be believers."}, {"ayah": 86, "translit": "Wa laa taq'udoo bikulli siraatin too'idoona wa tasuddoona 'an sabeelil laahi man aamana bihee wa abghoonahaa 'iwajaa; waz kurooo iz kuntum qaleelan fakassarakum wanzuroo kaifa kaana 'aaqibatul mufsideen", "translation": "And do not sit on every path, threatening and averting from the way of Allah those who believe in Him, seeking to make it [seem] deviant. And remember when you were few and He increased you. And see how was the end of the corrupters."}, {"ayah": 87, "translit": "Wa In kaana taaa'ifatum minkum aamanoo billazeee ursiltu bihee wa taaa'ifatul lam yu'minoo fasbiroo hattaa yahkumual laahu bainanaa; wa Huwa khairul haakimeen", "translation": "And if there should be a group among you who has believed in that with which I have been sent and a group that has not believed, then be patient until Allah judges between us. And He is the best of judges.\""}, {"ayah": 88, "translit": "Qaalal mala ul lazeenas takbaroo min qawmihee lanukhrijannaka yaa Shu'aibu wallazeena aamanoo ma'aka min qaryatinaaa aw lata'oo dunna fee millatinaa; qaala awa law kunnaa kaariheen", "translation": "Said the eminent ones who were arrogant among his people, \"We will surely evict you, O Shu'ayb, and those who have believed with you from our city, or you must return to our religion.\" He said, \"Even if we were unwilling?\""}, {"ayah": 89, "translit": "Qadif tarainaa 'alal laahi kaziban in 'udnaa fee millatikum ba'da iz najjaanal laahu minhaa; wa maa yakoonu lanaaa an na'ooda feehaaa illaaa ai yashaaa'al laahu Rabbunaa; wasi'a Rabbunaa kulla shai'in 'ilmaa; 'alal laahi tawakkalnaa; Rabbanaf tah bainanaa wa baina qawminaa bilhaqqi wa Anta khairul faatiheen", "translation": "We would have invented against Allah a lie if we returned to your religion after Allah had saved us from it. And it is not for us to return to it except that Allah, our Lord, should will. Our Lord has encompassed all things in knowledge. Upon Allah we have relied. Our Lord, decide between us and our people in truth, and You are the best of those who give decision.\""}, {"ayah": 90, "translit": "Wa qaalal mala ul lazeena kafaroo min qawmihee la'init taba'tum Shu'aiban innakum izal lakhaasiroon", "translation": "Said the eminent ones who disbelieved among his people, \"If you should follow Shu'ayb, indeed, you would then be losers.\""}, {"ayah": 91, "translit": "Fa akhazat humur rajfatu fa asbahoo fee daarihim jaasimeen", "translation": "So the earthquake seized them, and they became within their home [corpses] fallen prone."}, {"ayah": 92, "translit": "Allazeena kazzaboo Shu'aiban ka al alm yaghnaw feehaa; allazeena kazzaboo Shu'aiban kaanoo humul khaasireen", "translation": "Those who denied Shu'ayb - it was as though they had never resided there. Those who denied Shu'ayb - it was they who were the losers."}, {"ayah": 93, "translit": "Fatawalla 'anhum wa qaala yaa qawmi laqad ablaghtukum Risaalaati Rabbee wa nasahtu lakum fakaifa aasaa'alaa qawmin kaafireen", "translation": "And he turned away from them and said, \"O my people, I had certainly conveyed to you the messages of my Lord and advised you, so how could I grieve for a disbelieving people?\""}, {"ayah": 94, "translit": "Wa maaa arsalnaa fee qaryatim min Nabiyyin illaaa akhaznaaa ahlahaa bil baasaaa'i waddarraaa'i la'allahum yaddarra'oon", "translation": "And We sent to no city a prophet [who was denied] except that We seized its people with poverty and hardship that they might humble themselves [to Allah]."}, {"ayah": 95, "translit": "Summa baddalnaa makaa nas saiyi'atil hasanata hattaa 'afaw wa qaaloo qad massa aabaa'anad darraaa'u wassarraaa'u fa akhaznaahum baghtatanw wa hum laa yash'uroon", "translation": "Then We exchanged in place of the bad [condition], good, until they increased [and prospered] and said, \"Our fathers [also] were touched with hardship and ease.\" So We seized them suddenly while they did not perceive."}, {"ayah": 96, "translit": "Wa law anna ahlal quraaa aamanoo wattaqaw lafatahnaa 'alaihim barakaatim minas samaaa'i wal ardi wa laakin kazzaboo fa akhaznaahum bimaa kaanoo yaksiboon", "translation": "And if only the people of the cities had believed and feared Allah, We would have opened upon them blessings from the heaven and the earth; but they denied [the messengers], so We seized them for what they were earning.\""}, {"ayah": 97, "translit": "Afa amina ahlul quraaa ai yaatiyahum baasunaa bayaatanw wa hum naaa'imoon", "translation": "Then, did the people of the cities feel secure from Our punishment coming to them at night while they were asleep?"}, {"ayah": 98, "translit": "Awa amina ahlul quraaa ai yaatiyahum baasunaa duhanw wa hum yal'aboon", "translation": "Or did the people of the cities feel secure from Our punishment coming to them in the morning while they were at play?"}, {"ayah": 99, "translit": "Afa aminoo makral laah; falaa yaamanu makral laahi illal qawmul khaasiroon", "translation": "Then did they feel secure from the plan of Allah? But no one feels secure from the plan of Allah except the losing people."}, {"ayah": 100, "translit": "Awa lam yahdi lillazeena yarisoonal arda mim ba'di ahlihaaa al law nashaaa'u asabnaahum bizunoobihim; wa natba'u 'alaa quloobihim fahum laa yasma'oon", "translation": "Has it not become clear to those who inherited the earth after its [previous] people that if We willed, We could afflict them for their sins? But We seal over their hearts so they do not hear."}, {"ayah": 101, "translit": "Tilkal quraa naqussu 'alaika min ambaaa'ihaa; wa laqad jaaa'at hum Rusuluhum bilbaiyinaati famaa kaanoo liyu'minoo bimaa kazzaboo min qabl; kazaalika yatba'ul laahu 'alaa quloobil kaafireen", "translation": "Those cities - We relate to you, [O Muhammad], some of their news. And certainly did their messengers come to them with clear proofs, but they were not to believe in that which they had denied before. Thus does Allah seal over the hearts of the disbelievers."}, {"ayah": 102, "translit": "Wa maa wajadnaa li aksarihim min 'ahd; wa inw wajadnaaa aksarahum lafaasiqeen", "translation": "And We did not find for most of them any covenant; but indeed, We found most of them defiantly disobedient."}, {"ayah": 103, "translit": "Summa ba'asnaa mim ba'dihim Moosaa bi Aayaatinaaa ilaa Fir'awana wa mala'ihee fazalamoo bihaa fanzur kaifa kaana 'aaqibatul mufsideen", "translation": "Then We sent after them Moses with Our signs to Pharaoh and his establishment, but they were unjust toward them. So see how was the end of the corrupters."}, {"ayah": 104, "translit": "Wa qaala Moosaa yaa Fir'awnu inee Rasoolum mir Rabbil 'aalameen", "translation": "And Moses said, \"O Pharaoh, I am a messenger from the Lord of the worlds"}, {"ayah": 105, "translit": "Haqeequn 'alaaa al laaa aqoola 'alal laahi illal haqq; qad ji'tukum bibaiyinatim mir Rabbikum fa arsil ma'iya Baneee Israaa'eel", "translation": "[Who is] obligated not to say about Allah except the truth. I have come to you with clear evidence from your Lord, so send with me the Children of Israel.\""}, {"ayah": 106, "translit": "Qaala in kunta ji'ta bi Aayatin faati bihaaa in kunta minas saadiqeen", "translation": "[Pharaoh] said, \"If you have come with a sign, then bring it forth, if you should be of the truthful.\""}, {"ayah": 107, "translit": "Qa alqaa 'asaahu fa izaa hiya su'baanum mubeen", "translation": "So Moses threw his staff, and suddenly it was a serpent, manifest."}, {"ayah": 108, "translit": "Wa naza'a yadahoo fa izaa hiya baidaaa'u linnaazireen", "translation": "And he drew out his hand; thereupon it was white [with radiance] for the observers."}, {"ayah": 109, "translit": "Qaalal mala-u min qawmi Fir'awna inna haazaa lasaa hirun 'aleem", "translation": "Said the eminent among the people of Pharaoh, \"Indeed, this is a learned magician"}, {"ayah": 110, "translit": "Yureedu ai yukhrijakum min ardikum famaazaa taamuroon", "translation": "Who wants to expel you from your land [through magic], so what do you instruct?\""}, {"ayah": 111, "translit": "Qaalooo arjih wa akhaahu wa arsil filmadaaa'ini haashireen", "translation": "They said, \"Postpone [the matter of] him and his brother and send among the cities gatherers"}, {"ayah": 112, "translit": "Yaatooka bikulli saahirin 'aleem", "translation": "Who will bring you every learned magician.\""}, {"ayah": 113, "translit": "Wa jaaa'as saharatu Fir'awna qaaloo inna lanaa la ajjran in kunnaa nahnul ghaalibeen", "translation": "And the magicians came to Pharaoh. They said, \"Indeed for us is a reward if we are the predominant.\""}, {"ayah": 114, "translit": "Qaala na'am wa innakum laminal muqarrabeen", "translation": "He said, \"Yes, and, [moreover], you will be among those made near [to me].\""}, {"ayah": 115, "translit": "Qaaloo yaa Moosaaa immaaa an tulqiya wa immaaa an nakoona nahnul mulqeen", "translation": "They said, \"O Moses, either you throw [your staff], or we will be the ones to throw [first].\""}, {"ayah": 116, "translit": "Qaala alqoo falam maaa alqaw saharooo a'yunannaasi wastarhaboohum wa jaaa'oo bisihrin 'azeem", "translation": "He said, \"Throw,\" and when they threw, they bewitched the eyes of the people and struck terror into them, and they presented a great [feat of] magic."}, {"ayah": 117, "translit": "Wa awhainaaa ilaa Moosaaa an alqi 'asaaka fa izaa hiya talqafu maa yaafikoon", "translation": "And We inspired to Moses, \"Throw your staff,\" and at once it devoured what they were falsifying."}, {"ayah": 118, "translit": "Fawaqa'al haqqu wa batala maa kaanoo ya'maloon", "translation": "So the truth was established, and abolished was what they were doing."}, {"ayah": 119, "translit": "Faghuliboo hunaalika wanqalaboo saaghireen", "translation": "And Pharaoh and his people were overcome right there and became debased."}, {"ayah": 120, "translit": "Wa ulqiyas saharatu saajideen", "translation": "And the magicians fell down in prostration [to Allah]."}, {"ayah": 121, "translit": "Qaaloo aamannaa bi Rabbil 'aalameen", "translation": "They said, \"We have believed in the Lord of the worlds,"}, {"ayah": 122, "translit": "Rabbi Moosaa wa Haaroon", "translation": "The Lord of Moses and Aaron.\""}, {"ayah": 123, "translit": "Qaala Fir'awnu aamantum bihee qabla an aazana lakum; inna haaza lamakrum makartumoohu filmadeenati litukhrijoo minhaaa ahlahaa fasawfa ta'almoon", "translation": "Said Pharaoh, \"You believed in him before I gave you permission. Indeed, this is a conspiracy which you conspired in the city to expel therefrom its people. But you are going to know."}, {"ayah": 124, "translit": "La uqatti'anna aidiyakum wa arjulakum min khilaafin summa la usallibannakum ajma'een", "translation": "I will surely cut off your hands and your feet on opposite sides; then I will surely crucify you all.\""}, {"ayah": 125, "translit": "Qaaloo innaaa ilaa Rabbinaa munqaliboon", "translation": "They said, \"Indeed, to our Lord we will return."}, {"ayah": 126, "translit": "Wa maa tanqimu minnaaa illaaa an aamannaa bi Aayaati Rabbinaa lammaa jaaa'atnaa; Rabbanaaa afrigh 'alainaa sabranw wa tawaffanaa muslimeen", "translation": "And you do not resent us except because we believed in the signs of our Lord when they came to us. Our Lord, pour upon us patience and let us die as Muslims [in submission to You].\""}, {"ayah": 127, "translit": "Wa qaalal mala-u min qawmi Fir'awna atazaru Moosaa wa qawmahoo liyufsidoo fil ardi wa yazaraka wa aalihatak; qaala sanuqattilu abnaaa 'ahum wa nastahyee nisaaa'ahum wa innaa fawqahum qaahiroon", "translation": "And the eminent among the people of Pharaoh said,\" Will you leave Moses and his people to cause corruption in the land and abandon you and your gods?\" [Pharaoh] said, \"We will kill their sons and keep their women alive; and indeed, we are subjugators over them.\""}, {"ayah": 128, "translit": "Qaala Moosaa liqawmihis ta'eenoo billaahi wasbiroo innal arda lillaahi yoorisuhaa mai yashaaa'u min 'ibaadihee wal 'aaqibatu lilmuttaqeen", "translation": "Said Moses to his people, \"Seek help through Allah and be patient. Indeed, the earth belongs to Allah. He causes to inherit it whom He wills of His servants. And the [best] outcome is for the righteous.\""}, {"ayah": 129, "translit": "Qaaloo oozeenaa min qabli an taatiyanaa wa mim ba'di maa ji'tanaa; qaala 'asaa Rabbukum ai yuhlika 'aduwwakum wa yastakhli fakum fil ardi fayanzura kaifa ta'maloon", "translation": "They said, \"We have been harmed before you came to us and after you have come to us.\" He said, \"Perhaps your Lord will destroy your enemy and grant you succession in the land and see how you will do.\""}, {"ayah": 130, "translit": "Wa laqad akhaznaaa Aala Fir'awna bis sineena wa naqsim minas samaraati la'allahum yazzakkaroon", "translation": "And We certainly seized the people of Pharaoh with years of famine and a deficiency in fruits that perhaps they would be reminded."}, {"ayah": 131, "translit": "Fa izaa jaaa'at humul hasanatu qaaloo lanaa haazihee wa in tusibhum saiyi'atuny yattaiyaroo bi Moosaa wa mam ma'ah; alaaa innamaa taaa'iruhum 'indal laahi wa laakinna aksarahum laa ya'lamoon", "translation": "But when good came to them, they said, \"This is ours [by right].\" And if a bad [condition] struck them, they saw an evil omen in Moses and those with him. Unquestionably, their fortune is with Allah, but most of them do not know."}, {"ayah": 132, "translit": "Wa qaaloo mahmaa taatinaa bihee min Aayatil litasharanaa bihaa famaa nahnu  laka bimu'mineen", "translation": "And they said, \"No matter what sign you bring us with which to bewitch us, we will not be believers in you.\""}, {"ayah": 133, "translit": "Fa arsalnaa 'alaihimut toofaana waljaraada walqum mala waddafaadi'a waddama Aayaatim mufassalaatin fastakbaroo wa kaanoo qawmam mujrimeen", "translation": "So We sent upon them the flood and locusts and lice and frogs and blood as distinct signs, but they were arrogant and were a criminal people."}, {"ayah": 134, "translit": "Wa lammaa waqa'a 'alaihimur rijzu qaaloo ya Moosad-u lanaa rabbaka bimaa 'ahida 'indaka la'in kashafta 'annar rijza lanu 'minanna laka wa lanursilanna ma'aka Banee Israaa'eel", "translation": "And when the punishment descended upon them, they said, \"O Moses, invoke for us your Lord by what He has promised you. If you [can] remove the punishment from us, we will surely believe you, and we will send with you the Children of Israel.\""}, {"ayah": 135, "translit": "Falammaa kashafnaa 'anhumur rijza ilaaa ajalin hum baalighoohu izaa hum yankusoon", "translation": "But when We removed the punishment from them until a term which they were to reach, then at once they broke their word."}, {"ayah": 136, "translit": "Fantaqamnaa minhum fa aghraqnaahum kazzaboo bi Aayaatinaa wa kaanoo 'anhaa ghaafileen", "translation": "So We took retribution from them, and We drowned them in the sea because they denied Our signs and were heedless of them."}, {"ayah": 137, "translit": "Wa awrasnal qawmal lazeena kaanoo yustad'afoona mashaariqal ardi wa maghaari bahal latee baaraknaa feehaa wa tammat kalimatu Rabbikal husnaa 'alaa Baneee Israaa'eela bimaa sabaroo wa dammarnaa maa kaana yasna'u Fir'awnu wa qawmuhoo wa maa kaanoo ya'rishoon", "translation": "And We caused the people who had been oppressed to inherit the eastern regions of the land and the western ones, which We had blessed. And the good word of your Lord was fulfilled for the Children of Israel because of what they had patiently endured. And We destroyed [all] that Pharaoh and his people were producing and what they had been building."}, {"ayah": 138, "translit": "Wa jaawaznaa bi Banneee Israaa'eelal bahra fa ataw 'alaa qawminy ya'kufoona 'alaaa asnaamil lahum; qaaloo yaa Moosaj'al lanaa ilaahan kamaa lahum aalihah; qaala innakum qawmun tajhaloon", "translation": "And We took the Children of Israel across the sea; then they came upon a people intent in devotion to [some] idols of theirs. They said, \"O Moses, make for us a god just as they have gods.\" He said, \"Indeed, you are a people behaving ignorantly."}, {"ayah": 139, "translit": "Innaa haaa'ulaaa'i mutabbarum maa hum feehi wa baatilum maa kaanoo ya'maloon", "translation": "Indeed, those [worshippers] - destroyed is that in which they are [engaged], and worthless is whatever they were doing.\""}, {"ayah": 140, "translit": "Qaala a-ghairal laahi abgheekum ilaahanw wa Huwa faddalakum 'alal 'aalameen", "translation": "He said, \"Is it other than Allah I should desire for you as a god while He has preferred you over the worlds?\""}, {"ayah": 141, "translit": "Wa iz anjainaakum min Aali Fir'awna yasoomoo nakum sooo'al 'azaab, yuqattiloona abnaaa'akum wa yastahyoona nisaaa'akum; wa fee zaalikum balaaa'um mir Rabbikum 'azeem", "translation": "And [recall, O Children of Israel], when We saved you from the people of Pharaoh, [who were] afflicting you with the worst torment - killing your sons and keeping your women alive. And in that was a great trial from your Lord."}, {"ayah": 142, "translit": "Wa waa'adnaa Moosaa salaaseena lailatanw wa at mamnaahaa bi'ashrim fatamma meeqaatu Rabbihee arba'eena lailah; wa qaala Moosaa liakheehi Haaroonakh lufnee fee qawmee wa aslih wa laa tattabi' sabeelal mufsideen", "translation": "And We made an appointment with Moses for thirty nights and perfected them by [the addition of] ten; so the term of his Lord was completed as forty nights. And Moses said to his brother Aaron, \"Take my place among my people, do right [by them], and do not follow the way of the corrupters.\""}, {"ayah": 143, "translit": "Wa lammaa jaaa'a Moosa limeeqaatinaa wa kallamahoo Rabbuhoo qaala Rabbi arineee anzur ilaik; qaala lan taraanee wa laakininzur ilal jabali fa inistaqarra makaanahoo faswfa taraanee; falammaa tajallaa Rabbuhoo liljabali ja'alahoo dakkanw wa kharra Moosaa sa'iqaa; falammaaa afaaqa qaala Subhaanaka tubtu ilaika wa ana awwalul mu'mineen", "translation": "And when Moses arrived at Our appointed time and his Lord spoke to him, he said, \"My Lord, show me [Yourself] that I may look at You.\" [Allah] said, \"You will not see Me, but look at the mountain; if it should remain in place, then you will see Me.\" But when his Lord appeared to the mountain, He rendered it level, and Moses fell unconscious. And when he awoke, he said, \"Exalted are You! I have repented to You, and I am the first of the believers.\""}, {"ayah": 144, "translit": "Qaala yaa Moosaaa innis tafaituka 'alan naasi bi Risaalaatee wa bi kalaamee fakhuz maaa aataituka wa kum minash shaakireen", "translation": "[Allah] said, \"O Moses, I have chosen you over the people with My messages and My words [to you]. So take what I have given you and be among the grateful.\""}, {"ayah": 145, "translit": "Wa katabnaa lahoo fil alwaahi minkulli shai'immaw 'izaanw wa tafseelal likulli shai'in fakhuzhaa biquwwatinw waamur qawmaka yaakhuzoo bi ahsanihaa; wa ooreekum daaral faasiqeen", "translation": "And We wrote for him on the tablets [something] of all things - instruction and explanation for all things, [saying], \"Take them with determination and order your people to take the best of it. I will show you the home of the defiantly disobedient.\""}, {"ayah": 146, "translit": "Sa asrifu 'an Aayaatiyal lazeena yatakabbaroona fil ardi bighairil haqq; wa iny-yaraw kulla Aayatil laa yu'minoo bihaa wa iny-yaraw sabeelar rushdi laa yattakhizoohu sabeelanw wa iny-yaraw sabeelal ghaiyi yatta khizoohu sabeelaa; zaalika bi annahum kazzaboo bi Aayaatinaa wa kaanoo 'anhaa ghaafileen", "translation": "I will turn away from My signs those who are arrogant upon the earth without right; and if they should see every sign, they will not believe in it. And if they see the way of consciousness, they will not adopt it as a way; but if they see the way of error, they will adopt it as a way. That is because they have denied Our signs and they were heedless of them."}, {"ayah": 147, "translit": "Wallazeena kazzaboo bi Aayaatinaa wa liqaaa'il Aakhirati habitat 'amaaluhum; hal yujzawna illaa maa kaanoo ya'maloon", "translation": "Those who denied Our signs and the meeting of the Hereafter - their deeds have become worthless. Are they recompensed except for what they used to do?"}, {"ayah": 148, "translit": "Wattakhaza qawmu Moosaa mim ba'dihee min huliyyihim 'ijlan jasadal lahoo khuwaar; alam yaraw annahoo laa yukallimuhum wa laa yahdeehim sabeelaa; ittakha zoohu wa kaanoo zaalimeen", "translation": "And the people of Moses made, after [his departure], from their ornaments a calf - an image having a lowing sound. Did they not see that it could neither speak to them nor guide them to a way? They took it [for worship], and they were wrongdoers."}, {"ayah": 149, "translit": "Wa lammaa suqita feee aideehim wa ra aw annahum qad dalloo qaaloo la'il lam yarhamnaa Rabbunaa wa yaghfir lanaa lanakoonanna minal khaasireen", "translation": "And when regret overcame them and they saw that they had gone astray, they said, \"If our Lord does not have mercy upon us and forgive us, we will surely be among the losers.\""}, {"ayah": 150, "translit": "Wa lammaa raja'a Moosaaa ilaa qawmihee ghadbaana asifan qaala bi'samaa khalaftumoonee mim ba'dee a-'ajiltum amra Rabbikum wa alqal alwaaha wa akhaza biraasi akheehi yajurruhoo ilaih; qaalab na umma innal qawmas tad'afoonee wa kadoo yaqtu loonanee; falaa tushmit biyal a'daaa'a wa laa taj'alnee ma'al qawmiz zaalimeen", "translation": "And when Moses returned to his people, angry and grieved, he said, \"How wretched is that by which you have replaced me after [my departure]. Were you impatient over the matter of your Lord?\" And he threw down the tablets and seized his brother by [the hair of] his head, pulling him toward him. [Aaron] said, \"O son of my mother, indeed the people oppressed me and were about to kill me, so let not the enemies rejoice over me and do not place me among the wrongdoing people.\""}, {"ayah": 151, "translit": "Qaala Rabbigh fir lee wa li akhee wa adkhilnaa fee rahmatika wa Anta arhamur raahimeen", "translation": "[Moses] said, \"My Lord, forgive me and my brother and admit us into Your mercy, for You are the most merciful of the merciful.\""}, {"ayah": 152, "translit": "Innal lazeenat takhazul 'ijla-sa yanaaluhum ghadabum mir Rabbihim wa zillatun fil hayaatid dunyaa; wa kazaalika najzil muftareen", "translation": "Indeed, those who took the calf [for worship] will obtain anger from their Lord and humiliation in the life of this world, and thus do We recompense the inventors [of falsehood]."}, {"ayah": 153, "translit": "Wallazeena 'amilus saiyiaati summa taaboo mim ba'dihaa wa aamanooo inna Rabbaka mim ba'dihaa la Ghafoorur Raheem", "translation": "But those who committed misdeeds and then repented after them and believed - indeed your Lord, thereafter, is Forgiving and Merciful."}, {"ayah": 154, "translit": "Wa lammaa sakata 'am Moosal ghadabu akhazal al waaha wa fee nnuskhatihaa hudanw wa rahmatul lillazeena hum li Rabbihim yarhaboon", "translation": "And when the anger subsided in Moses, he took up the tablets; and in their inscription was guidance and mercy for those who are fearful of their Lord."}, {"ayah": 155, "translit": "Wakhtaara Moosaa qawmahoo sab'eena rajjulal limeeqaatinaa falammaa akhazat humur rajfatu qaala Rabbi law shi'ta ahlaktahum min qablu wa iyyaaya atuhlikunna bimaa fa'alas sufahaaa'u minnaa in hiya illaa fitnatuka tudillu bihaa man tashaaa'u wa tahdee man tashaaa'u Anta waliyyunaa faghfir lanaa warhammnnaa wa Anta khairul ghaafireen", "translation": "And Moses chose from his people seventy men for Our appointment. And when the earthquake seized them, he said, \"My Lord, if You had willed, You could have destroyed them before and me [as well]. Would You destroy us for what the foolish among us have done? This is not but Your trial by which You send astray whom You will and guide whom You will. You are our Protector, so forgive us and have mercy upon us; and You are the best of forgivers."}, {"ayah": 156, "translit": "Waktub lanaa fee haazi hid dunyaa hasanatanw wa fil Aakhirati innnaa hudnaaa ilaik; qaala 'azaabee useebu bihee man ashaaa'u wa rahmatee wasi'at kulla shai'; fasa aktubuhaa lillazeena yattaqoona wa yu'toonaz Zakaata wallazeena hum bi Aayaatinaa yu'minoon", "translation": "And decree for us in this world [that which is] good and [also] in the Hereafter; indeed, we have turned back to You.\" [Allah] said, \"My punishment - I afflict with it whom I will, but My mercy encompasses all things.\" So I will decree it [especially] for those who fear Me and give zakah and those who believe in Our verses -"}, {"ayah": 157, "translit": "Allazeena yattabi'oonar Rasoolan Nabiyyal ummiyyal lazee yajidoonahoo maktooban 'indahum fit Tawraati wal Injeeli yaa muruhum bilma'roofi wa yanhaahum 'anil munkari wa yuhillu lahumul taiyibaati wa yuharrimu 'alaihimul khabaaa'isa wa yada'u 'anhum israhum wal aghlaalal latee kaanat 'alaihim; fallazeena aamanoo bihee wa 'azzaroohu wa nnasaroohu wattaba'un nooral lazeee unzila ma'ahooo ulaaa'ika humul muflihoon", "translation": "Those who follow the Messenger, the unlettered prophet, whom they find written in what they have of the Torah and the Gospel, who enjoins upon them what is right and forbids them what is wrong and makes lawful for them the good things and prohibits for them the evil and relieves them of their burden and the shackles which were upon them. So they who have believed in him, honored him, supported him and followed the light which was sent down with him - it is those who will be the successful."}, {"ayah": 158, "translit": "Qul yaaa aiyuhan naasu innee Rasoohul laahi ilaikum jamee'anil lazee lahoo mulkus samaawaati wal ardi laaa ilaaha illaa Huwa yuhyee wa yumeetu fa aaminoo billaahi wa Rasoolihin Nabiyyil ummiy yil lazee yu'minu billaahi wa Kalimaatihee wattabi'oohu la'allakum tahtadoon", "translation": "Say, [O Muhammad], \"O mankind, indeed I am the Messenger of Allah to you all, [from Him] to whom belongs the dominion of the heavens and the earth. There is no deity except Him; He gives life and causes death.\" So believe in Allah and His Messenger, the unlettered prophet, who believes in Allah and His words, and follow him that you may be guided."}, {"ayah": 159, "translit": "Wa min qawmi Moosaaa ummatuny yahdoona bilhaqqi wa bihee ya'diloon", "translation": "And among the people of Moses is a community which guides by truth and by it establishes justice."}, {"ayah": 160, "translit": "Wa qatta' naahumus natai 'ashrata asbaatan umamaa; wa awhainaa ilaa Moosaaa izis tasqaahu qawmuhooo anid rib bi'asaakal hajara fambajasat minhus nata 'ashrata 'ainan qad 'alima kullu unaasim mashrabahm; wa zallalnaa 'alaihimul ghammaamma wa anzalnaa 'alaihimul MManna was Salwaa kuloo min taiyibaati maa razaqnaakum; wa maa zalamoonaa wa laakin kaanooo anfusahum yazlimoon", "translation": "And We divided them into twelve descendant tribes [as distinct] nations. And We inspired to Moses when his people implored him for water, \"Strike with your staff the stone,\" and there gushed forth from it twelve springs. Every people knew its watering place. And We shaded them with clouds and sent down upon them manna and quails, [saying], \"Eat from the good things with which We have provided you.\" And they wronged Us not, but they were [only] wronging themselves."}, {"ayah": 161, "translit": "Wa iz qeela lahumuskunoo haazihil qaryata wa kuloo minhaa haisu shi'tum wa qooloo hittatunw wadkhulul baaba sujjadan naghfir lakum khateee'aatikum; sanazeedul muhsineen", "translation": "And [mention, O Muhammad], when it was said to them, \"Dwell in this city and eat from it wherever you will and say, 'Relieve us of our burdens,' and enter the gate bowing humbly; We will [then] forgive you your sins. We will increase the doers of good [in goodness and reward].\""}, {"ayah": 162, "translit": "Fabaddalal lazeena zalamoo minhum qawlan ghairal lazee qeela lahum fa arsalnaa 'alaihim rijzam minas samaaa'i bimaa kaanoo yazlimoon", "translation": "But those who wronged among them changed [the words] to a statement other than that which had been said to them. So We sent upon them a punishment from the sky for the wrong that they were doing."}, {"ayah": 163, "translit": "Was'alhum 'anil qaryatil latee kaanat haadiratal bahri iz ya'doona fis Sabt iz taateehim heetaanuhum yawma Sabtihim shurra'anw wa yawma laa yasbitoona laa taateehim; kazaalika nabloohum bimaa kaanoo yafsuqoon", "translation": "And ask them about the town that was by the sea - when they transgressed in [the matter of] the sabbath - when their fish came to them openly on their sabbath day, and the day they had no sabbath they did not come to them. Thus did We give them trial because they were defiantly disobedient."}, {"ayah": 164, "translit": "Wa iz qaalat ummatum minhum lima ta'izoona qaw manil laahu muhlikuhum aw mu'azzibuhum 'azaaban shadeedan qaaloo ma'ziratan ilaa Rabbikum wa la'allahum yattaqoon", "translation": "And when a community among them said, \"Why do you advise [or warn] a people whom Allah is [about] to destroy or to punish with a severe punishment?\" they [the advisors] said, \"To be absolved before your Lord and perhaps they may fear Him.\""}, {"ayah": 165, "translit": "Falammaa nasoo maa zukkiroo bihee anjainal lazeena yanhawna 'anis sooo'i wa akhaznal lazeena zalamoo bi'azaabim ba'eeim bimaa kaanooyafsuqoon", "translation": "And when they forgot that by which they had been reminded, We saved those who had forbidden evil and seized those who wronged, with a wretched punishment, because they were defiantly disobeying."}, {"ayah": 166, "translit": "Falammaa 'ataw 'ammmaa nuhoo 'anhu qulna lahum kkoonoo qiradatan khaasi'een", "translation": "So when they were insolent about that which they had been forbidden, We said to them, \"Be apes, despised.\""}, {"ayah": 167, "translit": "Wa iz ta azzana Rabbuka la yab'asannna 'alaihim ilaa Yawmil Qiyaamati mai yasoomuhum sooo'al 'azaab; inna Rabbaka lasaree'ul 'iqaab; wa innahoo la Ghafoorur Raheem", "translation": "And [mention] when your Lord declared that He would surely [continue to] send upon them until the Day of Resurrection those who would afflict them with the worst torment. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful."}, {"ayah": 168, "translit": "Wa qatta'naahum fil ardi umamam minhumus aalihoona wa min hum doona zaalika wa balawnaahum bilhasanaati wassaiyi aati la'allahum yarji'oon", "translation": "And We divided them throughout the earth into nations. Of them some were righteous, and of them some were otherwise. And We tested them with good [times] and bad that perhaps they would return [to obedience]."}, {"ayah": 169, "translit": "Fakhalafa mim ba'dihim khalfunw warisul Kitaaba yaa khuzoona 'arada haazal adnaa wa yaqooloona sayughfaru lanaa wa iny yaatihim 'aradum misluhoo yaakhuzooh; alam yu'khaz 'alaihim 'aradum misluhoo yaakhuzooh; alam yu'khaz 'alaihim meesaaqul Kitaabi al laa yaqooloo 'alal laahi illal haqqa wa darasoo maa feeh; wad Daarul Aakhirtu khairul lillazeena yattaqoon; afalaa ta'qiloon", "translation": "And there followed them successors who inherited the Scripture [while] taking the commodities of this lower life and saying, \"It will be forgiven for us.\" And if an offer like it comes to them, they will [again] take it. Was not the covenant of the Scripture taken from them that they would not say about Allah except the truth, and they studied what was in it? And the home of the Hereafter is better for those who fear Allah, so will you not use reason?"}, {"ayah": 170, "translit": "Wallazeena yumas sikoona bil Kitaabi wa aqaamus Salaata innaa laa nudee'uajral musliheen", "translation": "But those who hold fast to the Book and establish prayer - indeed, We will not allow to be lost the reward of the reformers."}, {"ayah": 171, "translit": "Wa iz nataqnal jabala fawqahum ka annahoo zullatunw wa zannooo annahoo waaqi'um bihim khuzoo maaa aatainaakum biquwwatinw wazkuroo maa feehi la'allakum tattaqoon", "translation": "And [mention] when We raised the mountain above them as if it was a dark cloud and they were certain that it would fall upon them, [and Allah said], \"Take what We have given you with determination and remember what is in it that you might fear Allah.\""}, {"ayah": 172, "translit": "Wa iz akhaza Rabbuka mim Baneee Aadama min zuhoorihim zurriyyatahum wa ash hadahum 'alaa anfusihim alastu bi Rabbikum qaaloo balaa shahidnaaa; an taqooloo Yawmal Qiyaamati innaa kunnaa 'an haazaa ghaafileen", "translation": "And [mention] when your Lord took from the children of Adam - from their loins - their descendants and made them testify of themselves, [saying to them], \"Am I not your Lord?\" They said, \"Yes, we have testified.\" [This] - lest you should say on the day of Resurrection, \"Indeed, we were of this unaware.\""}, {"ayah": 173, "translit": "Aw taqoolooo innamaaa ashraka aabaaa 'unaa min qablu wa kunnaa zurriyyatam mim ba'dihim afatuhlikunna bimaa fa'alal mubtiloon", "translation": "Or [lest] you say, \"It was only that our fathers associated [others in worship] with Allah before, and we were but descendants after them. Then would You destroy us for what the falsifiers have done?\""}, {"ayah": 174, "translit": "Wa kazaalika nufassihul Aayaati wa la'allahum yarji'oon", "translation": "And thus do We [explain in] detail the verses, and perhaps they will return."}, {"ayah": 175, "translit": "Watlu 'alaihim naba allazeee aatainaahu Aayaatinaa fansalakha minhaa fa atba'a hush Shaytaano fakaana minal ghaaween", "translation": "And recite to them, [O Muhammad], the news of him to whom we gave [knowledge of] Our signs, but he detached himself from them; so Satan pursued him, and he became of the deviators."}, {"ayah": 176, "translit": "Wa law shi'naa larafa'naahu bihaa wa laakin nahooo akhlada ilal ardi watta ba'a hawaah; famasaluhoo kamasalil kalb; in tahmil 'alaihi yalhas aw tatruk hu yalhas; zaalika masalul qawmil lazeena kazzaboo bi Aayaatinaa; faqsusil qasasa la'allahum yatafakkaroon", "translation": "And if We had willed, we could have elevated him thereby, but he adhered [instead] to the earth and followed his own desire. So his example is like that of the dog: if you chase him, he pants, or if you leave him, he [still] pants. That is the example of the people who denied Our signs. So relate the stories that perhaps they will give thought."}, {"ayah": 177, "translit": "Saaa'a masalanil qawmul lazeena kazzaboo bi Aayaatinaa wa anfusahum kaanoo yazlimoon", "translation": "How evil an example [is that of] the people who denied Our signs and used to wrong themselves."}, {"ayah": 178, "translit": "mai yahdil laahu fa huwal muhtadee wa mai yudlil fa ulaaa'ika humul khaasiroon", "translation": "Whoever Allah guides - he is the [rightly] guided; and whoever He sends astray - it is those who are the losers."}, {"ayah": 179, "translit": "Wa laqad zaraanaa li jahannama kaseeram minal jinni wal insi lahum quloobul laa yafqahoona bihaa wa lahum a'yunul laa yubisiroona bihaa wa lahum aazaanul laa yasma'oona bihaa; ulaaa'ika kal an'aami bal hum adall; ulaaa'ika humul ghaafiloon", "translation": "And We have certainly created for Hell many of the jinn and mankind. They have hearts with which they do not understand, they have eyes with which they do not see, and they have ears with which they do not hear. Those are like livestock; rather, they are more astray. It is they who are the heedless."}, {"ayah": 180, "translit": "Wa lillaahil Asmaaa 'ul Husnaa fad'oohu bihaa wa zarul lazeena yulhidoona feee Asmaaa'ih; sa yujzawna maa kaanoo ya'maloon", "translation": "And to Allah belong the best names, so invoke Him by them. And leave [the company of] those who practice deviation concerning His names. They will be recompensed for what they have been doing."}, {"ayah": 181, "translit": "Wa mimman khalaqnaaa ummatuny yahdoona bilhaqqi wa bihee ya'diloon", "translation": "And among those We created is a community which guides by truth and thereby establishes justice."}, {"ayah": 182, "translit": "Wallazeena kazzaboo bi Aayaatinaa sanastadrijuhum min haisu laa ya'lamoon", "translation": "But those who deny Our signs - We will progressively lead them [to destruction] from where they do not know."}, {"ayah": 183, "translit": "Wa umlee lahum; inna kaidee mateen", "translation": "And I will give them time. Indeed, my plan is firm."}, {"ayah": 184, "translit": "Awalam yatafakkaroo maa bisaahibihim min jinnah; in huwa illaa nazeerum mubeen", "translation": "Then do they not give thought? There is in their companion [Muhammad] no madness. He is not but a clear warner."}, {"ayah": 185, "translit": "Awalam yanzuroo fee malakootis samaawaati wal ardi wa maa khalaqal laahu min shai'inw wa an 'asaaa ai yakoona qadiqtaraba ajaluhum fabi aiyi hadeesim ba'dahoo yu'minoon", "translation": "Do they not look into the realm of the heavens and the earth and everything that Allah has created and [think] that perhaps their appointed time has come near? So in what statement hereafter will they believe?"}, {"ayah": 186, "translit": "Mai yadlilil laahu falaa haadiyaa lah; wa yazaruhum fee tughyaanihim ya'mahoon", "translation": "Whoever Allah sends astray - there is no guide for him. And He leaves them in their transgression, wandering blindly."}, {"ayah": 187, "translit": "Yas'aloonaka 'anis Saa'ati aiyaana mursaahaa qul innamaa 'ilmuhaa 'inda Rabbee laa yujallaeehaa liwaqtihaaa illaa Hoo; saqulat fis samaawaati wal ard; laa taateekum illaa baghtah; yas'aloonaka ka annaka hafiyyun 'anhaa qul innamaa 'ilmuhaa 'indal laahi wa laakinna aksaran naasi laa ya'lamoon", "translation": "They ask you, [O Muhammad], about the Hour: when is its arrival? Say, \"Its knowledge is only with my Lord. None will reveal its time except Him. It lays heavily upon the heavens and the earth. It will not come upon you except unexpectedly.\" They ask you as if you are familiar with it. Say, \"Its knowledge is only with Allah, but most of the people do not know.\""}, {"ayah": 188, "translit": "Qul laaa amliku linafsee naf'anw wa laa darran illaa maa shaaa'al laah; wa law kuntu a'alamul ghaiba lastaksartu minal khairi wa maa massaniyas soo'; in ana illaa nazeerunw wa basheerul liqawminy yu'minoon", "translation": "Say, \"I hold not for myself [the power of] benefit or harm, except what Allah has willed. And if I knew the unseen, I could have acquired much wealth, and no harm would have touched me. I am not except a warner and a bringer of good tidings to a people who believe.\""}, {"ayah": 189, "translit": "Huwal lazee khalaqakum min nafsinw waahidatinw wa ja'ala minhaa zawjahaa liyas kuna ilaihaa falammaa taghash shaahaa hamalat hamlan khafeefan famarrat bihee falammaaa asqalad da'awal laaha Rabbahumaa la'in aayaitanaa saalihal lanakoo nanna minash shaakireen", "translation": "It is He who created you from one soul and created from it its mate that he might dwell in security with her. And when he covers her, she carries a light burden and continues therein. And when it becomes heavy, they both invoke Allah, their Lord, \"If You should give us a good [child], we will surely be among the grateful.\""}, {"ayah": 190, "translit": "Falammaaa aataahumaa saalihan ja'alaa lahoo shurakaaa'a feemaaa aataahumaa; fata'aalal laahu 'ammaa yushrikoon", "translation": "But when He gives them a good [child], they ascribe partners to Him concerning that which He has given them. Exalted is Allah above what they associate with Him."}, {"ayah": 191, "translit": "A yushrikoona maa laa yakhluqu shai'anw wa hum yukhlaqoon", "translation": "Do they associate with Him those who create nothing and they are [themselves] created?"}, {"ayah": 192, "translit": "Wa laa yastatee'oona lahum nasranw wa laaa anfusahum yansuroon", "translation": "And the false deities are unable to [give] them help, nor can they help themselves."}, {"ayah": 193, "translit": "Wa in tad'oohum ilalhudaa laa yattabi'ookum; sawaaa'un 'alaikum a-da'awtumoohum am antum saamitoon", "translation": "And if you [believers] invite them to guidance, they will not follow you. It is all the same for you whether you invite them or you are silent."}, {"ayah": 194, "translit": "Innal lazeena tad'oona min doonil laahi 'ibaadun amsaalukum fad'oohum fal yastajeeboo lakum in kuntum saadiqeen", "translation": "Indeed, those you [polytheists] call upon besides Allah are servants like you. So call upon them and let them respond to you, if you should be truthful."}, {"ayah": 195, "translit": "A lahum arjuluny yamshoona bihaa am lahum aidiny yabtishoona bihaaa am lahum a'yunuy yubsiroona bihaaa am lahum aazaanuny yasma'oona bihaa; qulid'oo shurakaaa'akum summa keedooni falaa tunziroon", "translation": "Do they have feet by which they walk? Or do they have hands by which they strike? Or do they have eyes by which they see? Or do they have ears by which they hear? Say, [O Muhammad], \"Call your 'partners' and then conspire against me and give me no respite."}, {"ayah": 196, "translit": "Inna waliyyial laahul lazee nazzalal Kitaaba wa Huwa yatawallas saaliheen", "translation": "Indeed, my protector is Allah, who has sent down the Book; and He is an ally to the righteous."}, {"ayah": 197, "translit": "Wallazeena tad'oona min doonihee laa yastatee'oona nasrakum wa laaa anfusahum yansuroon", "translation": "And those you call upon besides Him are unable to help you, nor can they help themselves.\""}, {"ayah": 198, "translit": "Wa in tad'oohum ilal hudaa laa yasm'oo wa taraahum yanzuroona ilaika wa hum laa yubsiroon", "translation": "And if you invite them to guidance, they do not hear; and you see them looking at you while they do not see."}, {"ayah": 199, "translit": "khuzil 'afwa waamur bil'urfi waa'rid 'anil jaahileen", "translation": "Take what is given freely, enjoin what is good, and turn away from the ignorant."}, {"ayah": 200, "translit": "Wa immaa yanzaghannaka minash Shaitaani nazghun fasta'iz billaah; innahoo Samee'un Aleem", "translation": "And if an evil suggestion comes to you from Satan, then seek refuge in Allah. Indeed, He is Hearing and Knowing."}, {"ayah": 201, "translit": "Innal lazeenat taqaw izaa massahum taaa'ifum minash Shaitaani tazakkaroo fa izaa hum mubsiroon", "translation": "Indeed, those who fear Allah - when an impulse touches them from Satan, they remember [Him] and at once they have insight."}, {"ayah": 202, "translit": "Wa ikhwaanuhum yamuddoonahum fil ghaiyi summa laa yuqsiroon", "translation": "But their brothers - the devils increase them in error; then they do not stop short."}, {"ayah": 203, "translit": "Wa izaa lam taatihim bi aayatin qaaloo law lajtabai tahaa; qul innamaaa attabi'u maa yoohaaa ilaiya mir Rabbee; haazaa basaaa'iru mir Rabbikum wa hudanw wa rahmatul liqawminy yu'minoon", "translation": "And when you, [O Muhammad], do not bring them a sign, they say, \"Why have you not contrived it?\" Say, \"I only follow what is revealed to me from my Lord. This [Qur'an] is enlightenment from your Lord and guidance and mercy for a people who believe.\""}, {"ayah": 204, "translit": "Wa izaa quri'al Quraanu fastami'oo lahoo wa ansitoo la 'allakum turhamoon", "translation": "So when the Qur'an is recited, then listen to it and pay attention that you may receive mercy."}, {"ayah": 205, "translit": "Wazkur Rabbaka fee nafsika tadarru'anw wa kheefatanw wa doonal jahri minal qawli bilghuduwwi wal aasali wa laa takum minal ghaafileen", "translation": "And remember your Lord within yourself in humility and in fear without being apparent in speech - in the mornings and the evenings. And do not be among the heedless."}, {"ayah": 206, "translit": "Innal lazeena 'inda Rabbika laa yastakbiroona 'an 'ibaadatihee wa yusabbihoonahoo wa lahoo yasjudoon", "translation": "Indeed, those who are near your Lord are not prevented by arrogance from His worship, and they exalt Him, and to Him they prostrate."}]}, {"num": 8, "name": "Al-Anfal", "meaning": "The Spoils of War", "verses": [{"ayah": 1, "translit": "Yas'aloonaka 'anil anfaali qulil anfaalu lillaahi war Rasooli fattaqul laaha wa ahlihoo zaata bainikum wa atee'ul laaha wa Rasoolahooo in kuntum mu'mineen", "translation": "They ask you, [O Muhammad], about the bounties [of war]. Say, \"The [decision concerning] bounties is for Allah and the Messenger.\" So fear Allah and amend that which is between you and obey Allah and His Messenger, if you should be believers."}, {"ayah": 2, "translit": "Innamal mu'minoonal lazeena izaa zukiral laahu wajilat quloobuhum wa izaa tuliyat 'alaihim Aayaatuhoo zaadat hum eemaananw wa 'alaa Rabbihim yatawakkaloon", "translation": "The believers are only those who, when Allah is mentioned, their hearts become fearful, and when His verses are recited to them, it increases them in faith; and upon their Lord they rely -"}, {"ayah": 3, "translit": "Allazeena yuqeemoonas Salaata wa mimmaa razaqnaahum yunfiqoon", "translation": "The ones who establish prayer, and from what We have provided them, they spend."}, {"ayah": 4, "translit": "Ulaaa'ika humul mu'minoona haqqaa; lahum darajaatun 'inda Rabbihim wa magh firatunw wa rizqun kareem", "translation": "Those are the believers, truly. For them are degrees [of high position] with their Lord and forgiveness and noble provision."}, {"ayah": 5, "translit": "Kaamaaa akhrajaka Rabbuka mim baitika bilhaqq; wa inna fareeqam minal mu'mineena lakaarihoon", "translation": "[It is] just as when your Lord brought you out of your home [for the battle of Badr] in truth, while indeed, a party among the believers were unwilling,"}, {"ayah": 6, "translit": "Yujaadiloonaka fil haqqi ba'da maa tabaiyana kaannamaa yasaaqoona ilal mawti wa hum uanzuroon", "translation": "Arguing with you concerning the truth after it had become clear, as if they were being driven toward death while they were looking on."}, {"ayah": 7, "translit": "Wa iz ya'idukumul laahu ihdat taaa'ifataini annahaa lakum wa tawaddoona anna ghaira zaatish shawkati takoonu lakum wa yureedul laahu ai yuhiqqal haqqa bikalimaatihee wa taqta'a daabiral kaafireen", "translation": "[Remember, O believers], when Allah promised you one of the two groups - that it would be yours - and you wished that the unarmed one would be yours. But Allah intended to establish the truth by His words and to eliminate the disbelievers"}, {"ayah": 8, "translit": "Liyuhiqqal haqqa wa tubtilal baatila wa law karihal mujrimoon", "translation": "That He should establish the truth and abolish falsehood, even if the criminals disliked it."}, {"ayah": 9, "translit": "Iz tastagheesoona Rabbakum fastajaaba lakum annee mumiddukum bi alfim minal malaaa'ikati murdifeen", "translation": "[Remember] when you asked help of your Lord, and He answered you, \"Indeed, I will reinforce you with a thousand from the angels, following one another.\""}, {"ayah": 10, "translit": "Wa maa ja'alahul laahu illaa bushraa wa litatma'inna bihee quloobukum; wa man nasru illaa min 'indil laah; innal laaha Azeezun Hakeem", "translation": "And Allah made it not but good tidings and so that your hearts would be assured thereby. And victory is not but from Allah. Indeed, Allah is Exalted in Might and Wise."}, {"ayah": 11, "translit": "Iz yughashsheekumun nu'assa amanatam minhu wa yunazzilu 'alaikum minas samaaa'i maaa'al liyutah hirakum bihee wa yuzhiba 'ankum rijzash Shaitaani wa liyarbita 'ala quloobikum wa yusabbita bihil aqdaam", "translation": "[Remember] when He overwhelmed you with drowsiness [giving] security from Him and sent down upon you from the sky, rain by which to purify you and remove from you the evil [suggestions] of Satan and to make steadfast your hearts and plant firmly thereby your feet."}, {"ayah": 12, "translit": "Iz yoohee Rabbuka ilal malaaa'ikati annee ma'akum fasabbitul lazeena aamanoo; sa ulqee fee quloobil lazeena kafarur ru'ba fadriboo fawqal a'naaqi wadriboo minhum kulla banaan", "translation": "[Remember] when your Lord inspired to the angels, \"I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip.\""}, {"ayah": 13, "translit": "Zaalika bi annahum shaaaqqul laaha wa Rasoolah; wa mai yushaqiqil laaha wa Rasoolahoo fa innal laaha shadeedul 'iqaab", "translation": "That is because they opposed Allah and His Messenger. And whoever opposes Allah and His Messenger - indeed, Allah is severe in penalty."}, {"ayah": 14, "translit": "Zaalikum fazooqoohu wa anna lilkaafireena 'azaaban Naar", "translation": "\"That [is yours], so taste it.\" And indeed for the disbelievers is the punishment of the Fire."}, {"ayah": 15, "translit": "Yaaa aiyuhal lazeena aamanoo izaa laqeetumul lazeena kafaroo zahfan falaa tuwalloohumul adbaar", "translation": "O you who have believed, when you meet those who disbelieve advancing [for battle], do not turn to them your backs [in flight]."}, {"ayah": 16, "translit": "Wa mai yuwallihim yawma'izin duburahooo illaa mutaharrifal liqitaalin aw mutahaiyizan ilaa fi'atin faqad baaa'a bighadabim minal laahi wa maawaahu Jahannamu wa bi'sal maseer", "translation": "And whoever turns his back to them on such a day, unless swerving [as a strategy] for war or joining [another] company, has certainly returned with anger [upon him] from Allah, and his refuge is Hell - and wretched is the destination."}, {"ayah": 17, "translit": "Falam taqtuloohum wa laakinnal laaha qatalahum; wa maa ramaita iz ramaita wa laakinnal laaha ramaa; wa liyubliyal mu'mineena minhu balaaa'an hasanaa; innal laaha Samee'un Aleem", "translation": "And you did not kill them, but it was Allah who killed them. And you threw not, [O Muhammad], when you threw, but it was Allah who threw that He might test the believers with a good test. Indeed, Allah is Hearing and Knowing."}, {"ayah": 18, "translit": "Zaalikum wa annal laaha moohinu kaidil kaafireen", "translation": "That [is so], and [also] that Allah will weaken the plot of the disbelievers."}, {"ayah": 19, "translit": "In tastaftihoo faqad jaaa'akumul fathu wa in tantahoo fahuwa khairul lakum wa in ta'oodoo na'ud wa lan tughniya 'ankum fi'atukum shai'anw wa law kasurat wa annal laaha ma'al mu'mineen", "translation": "If you [disbelievers] seek the victory - the defeat has come to you. And if you desist [from hostilities], it is best for you; but if you return [to war], We will return, and never will you be availed by your [large] company at all, even if it should increase; and [that is] because Allah is with the believers."}, {"ayah": 20, "translit": "Yaaa aiyuhal lazeena aamanoo atee'ul laaha wa Rasoolahoo wa laa tawallaw 'anhu wa antum tasm'oon", "translation": "O you who have believed, obey Allah and His Messenger and do not turn from him while you hear [his order]."}, {"ayah": 21, "translit": "Wa laa takoonoo kallazeena qaaloo sami'naa wa hum laa yasma'oon", "translation": "And do not be like those who say, \"We have heard,\" while they do not hear."}, {"ayah": 22, "translit": "Inna sharrad dawaaabbi 'indal laahis summul bukmul lazeena laa ya'qiloon", "translation": "Indeed, the worst of living creatures in the sight of Allah are the deaf and dumb who do not use reason."}, {"ayah": 23, "translit": "Wa law 'alimal laahu feehim khairal la asma'ahum; wa law asma'ahum latawallaw wa hum mu'ridoon", "translation": "Had Allah known any good in them, He would have made them hear. And if He had made them hear, they would [still] have turned away, while they were refusing."}, {"ayah": 24, "translit": "Yaaa aiyuhal lazeena aamanus tajeeboo lillaahi wa lir Rasooli izaa da'aakum limaa yuhyeekum wa'lamooo annal laaha yahoolu bainal mar'i wa qalbihee wa anahooo ilaihi tuhsharoon", "translation": "O you who have believed, respond to Allah and to the Messenger when he calls you to that which gives you life. And know that Allah intervenes between a man and his heart and that to Him you will be gathered."}, {"ayah": 25, "translit": "Wattaqoo fitnatal laa tuseebannal lazeena zalamoo minkum khaaaassatanw wa'lamooo annal laaha shadeedul 'iqaab", "translation": "And fear a trial which will not strike those who have wronged among you exclusively, and know that Allah is severe in penalty."}, {"ayah": 26, "translit": "Wazkurooo iz antum qaleelum mustad 'afoona filardi takhaafoona ai yatakhat tafakumun naasu fa aawaakum wa aiyadakum binasrihee wa razaqakum minat taiyibaati la'allakum tashkuroon", "translation": "And remember when you were few and oppressed in the land, fearing that people might abduct you, but He sheltered you, supported you with His victory, and provided you with good things - that you might be grateful."}, {"ayah": 27, "translit": "Yaaa aiyuhal lazeena aamanoo laa takhoonal laaha war Rasoola wa takhoonooo amaanaatikum wa antum ta'lamoon", "translation": "O you who have believed, do not betray Allah and the Messenger or betray your trusts while you know [the consequence]."}, {"ayah": 28, "translit": "Wa'lamooo annamaaa amwaalukum wa awlaadukum fitnatunw wa annal laaha 'indahooo ajrun azeem", "translation": "And know that your properties and your children are but a trial and that Allah has with Him a great reward."}, {"ayah": 29, "translit": "Yaaa aiyuhal lazeena aamanooo in tattaqul laaha yaj'al lakum furqaananw wa yukaffir 'ankum saiyi aatikum wa yaghfir lakum; wallaahu zul fadlil 'azeem", "translation": "O you who have believed, if you fear Allah, He will grant you a criterion and will remove from you your misdeeds and forgive you. And Allah is the possessor of great bounty."}, {"ayah": 30, "translit": "Wa iz yamkuru bikal lazeena kafaroo liyusbitooka aw yaqtulooka aw yukhrijook; wa yamkuroona wa yamkurul laahu wallaahu khairul maakireen", "translation": "And [remember, O Muhammad], when those who disbelieved plotted against you to restrain you or kill you or evict you [from Makkah]. But they plan, and Allah plans. And Allah is the best of planners."}, {"ayah": 31, "translit": "Wa izaa tutlaa 'alaihim Aayaatunaa qaaloo qad sami'naa law nashaaa'u laqulnaa misla haazaaa in haazaaa illaaa asaateerul awwaleen", "translation": "And when Our verses are recited to them, they say, \"We have heard. If we willed, we could say [something] like this. This is not but legends of the former peoples.\""}, {"ayah": 32, "translit": "Wa iz qaalul laahumma in kaana haazaa huwal haqqa min 'indika fa amtir 'alainaa hijaaratam minas samaaa'i awi'tinaa bi 'azaabin alaeem", "translation": "And [remember] when they said, \"O Allah, if this should be the truth from You, then rain down upon us stones from the sky or bring us a painful punishment.\""}, {"ayah": 33, "translit": "Wa maa kanal laahu liyu'az zibahum wa anta feehim; wa maa kaanal laahu mu'az zibahum wa hum yastaghfiroon", "translation": "But Allah would not punish them while you, [O Muhammad], are among them, and Allah would not punish them while they seek forgiveness."}, {"ayah": 34, "translit": "Wa maa lahum allaa yu'az zibahumul laahu wa hum yasuddoona 'anil Masjidil-Haraami wa maa kaanooo awliyaaa'ah; in awliyaaa' uhooo illal muttaqoona wa laakinna aksarahum laa ya'lamoon", "translation": "But why should Allah not punish them while they obstruct [people] from al-Masjid al- Haram and they were not [fit to be] its guardians? Its [true] guardians are not but the righteous, but most of them do not know."}, {"ayah": 35, "translit": "Wa maa kaana Salaatuhum 'indal Baiti illa mukaaa anw-wa tasdiyah; fazooqul 'azaaba bimaa kuntum takfuroon", "translation": "And their prayer at the House was not except whistling and handclapping. So taste the punishment for what you disbelieved."}, {"ayah": 36, "translit": "Innal lazeena kafaroo yunfiqoona amwaalahum liyasuddoo 'an sabeelil laah; fasayunfiqoonahaa summa takoonu 'alaihim hasratan summa yughlaboon; wal lazeena kafarooo ilaa Jahannnama yuhsharoona", "translation": "Indeed, those who disbelieve spend their wealth to avert [people] from the way of Allah. So they will spend it; then it will be for them a [source of] regret; then they will be overcome. And those who have disbelieved - unto Hell they will be gathered."}, {"ayah": 37, "translit": "Liyameezal laahul khabeesa minat taiyibi wa yaj'alal khabeesa ba'dahoo 'ala ba'din fayarkumahoo jamee'an fayaj'alahoo fee Jahannnam; ulaaa'ika humul khaasiroon", "translation": "[This is] so that Allah may distinguish the wicked from the good and place the wicked some of them upon others and heap them all together and put them into Hell. It is those who are the losers."}, {"ayah": 38, "translit": "Qul lillazeena kafarooo iny yantahoo yughfar lahum maa qad salafa wa iny ya'oodoo faqad madat sunnatul awwaleen", "translation": "Say to those who have disbelieved [that] if they cease, what has previously occurred will be forgiven for them. But if they return [to hostility] - then the precedent of the former [rebellious] peoples has already taken place."}, {"ayah": 39, "translit": "Wa qaatiloohum hattaa laa takoona fitnatunw wa yakoonaddeenu kulluhoo lillaah; fainin tahaw fa innallaaha bimaa ya'maloona Baseer", "translation": "And fight them until there is no fitnah and [until] the religion, all of it, is for Allah. And if they cease - then indeed, Allah is Seeing of what they do."}, {"ayah": 40, "translit": "Wa in tawallaw fa'lamooo annal laaha mawlaakum; ni'mal mawlaa wa ni'man naseer", "translation": "But if they turn away - then know that Allah is your protector. Excellent is the protector, and Excellent is the helper."}, {"ayah": 41, "translit": "Wa'lamooo annamaa ghanimtum min sha'in fa anna lillaahi khumusahoo wa lir Rasooli wa lizil qurba walyataamaa walmasaakeeni wabnis sabeeli in kuntum aamantum billaahi wa maaa anzalnaa 'ala 'abdinaa yawmal Furqaani yawmaltaqal jam'aan; wal laahu 'alaa kulli shai'in Qadeer", "translation": "And know that anything you obtain of war booty - then indeed, for Allah is one fifth of it and for the Messenger and for [his] near relatives and the orphans, the needy, and the [stranded] traveler, if you have believed in Allah and in that which We sent down to Our Servant on the day of criterion - the day when the two armies met. And Allah, over all things, is competent."}, {"ayah": 42, "translit": "Iz antum bil'udwatid dunyaa wa hum bil'udwatil quswaa warrakbu asfala minkum; wa law tawaa'attum lakhtalaftum fil mee'aadi wa laakil liyaqdiyal laahu amran kaana maf'oolal liyahlika man halaka 'am baiyinatinw wa yahyaa man haiya 'am baiyinah; wa innal laaha la Samee'un 'Aleem", "translation": "[Remember] when you were on the near side of the valley, and they were on the farther side, and the caravan was lower [in position] than you. If you had made an appointment [to meet], you would have missed the appointment. But [it was] so that Allah might accomplish a matter already destined - that those who perished [through disbelief] would perish upon evidence and those who lived [in faith] would live upon evidence; and indeed, Allah is Hearing and Knowing."}, {"ayah": 43, "translit": "Iz yureekahumul laahu fee manaamika qaleela; wa law araakahum kaseeral lafashiltum wa latanaaza'tum fil amri wa laakinnal laaha sallam; innahoo 'aleemum bizaatis sudoor", "translation": "[Remember, O Muhammad], when Allah showed them to you in your dream as few; and if He had shown them to you as many, you [believers] would have lost courage and would have disputed in the matter [of whether to fight], but Allah saved [you from that]. Indeed, He is Knowing of that within the breasts."}, {"ayah": 44, "translit": "Wa iz yureekumoohum izil taqaitum feee a'yunikum qaleelanw wa yuqallilukum feee a'yunihim liyaqdiyal laahu amran kaana maf'oolaa; wa ilal laahi turja'ul umoor", "translation": "And [remember] when He showed them to you, when you met, as few in your eyes, and He made you [appear] as few in their eyes so that Allah might accomplish a matter already destined. And to Allah are [all] matters returned."}, {"ayah": 45, "translit": "Yaaa aiyuhal lazeena aamanooo izaa laqeetum fi'atan fasbutoo wazkurul laaha kaseeral la'allakum tuflihoon", "translation": "O you who have believed, when you encounter a company [from the enemy forces], stand firm and remember Allah much that you may be successful."}, {"ayah": 46, "translit": "Wa atee'ul laaha wa Rasoolahoo wa laa tanaaza'oo fatafshaloo wa tazhaba reehukum wasbiroo; innal laaha ma'as saabireen", "translation": "And obey Allah and His Messenger, and do not dispute and [thus] lose courage and [then] your strength would depart; and be patient. Indeed, Allah is with the patient."}, {"ayah": 47, "translit": "Wa laa takoonoo kallazeena kharajoo min diyaarihim bataranw wa ri'aaa'an naasi wa yasuddoona 'an sabeelil laah; wallaahu bimaa ya'maloona muheet", "translation": "And do not be like those who came forth from their homes insolently and to be seen by people and avert [them] from the way of Allah. And Allah is encompassing of what they do."}, {"ayah": 48, "translit": "Wa iz zaiyana lahumush shaitaanu a'ma alahum wa qaala laa ghaaliba lakumul yawma minan naasi wa innee jaarul lakum falammaa taraaa'atil fi'ataani nakasa 'alaa aqibaihi wa qaala innee bareee'um minkum innee araa maa laa tarawna inneee akhaaful laah; wallaahu shadeedul 'iqaab", "translation": "And [remember] when Satan made their deeds pleasing to them and said, \"No one can overcome you today from among the people, and indeed, I am your protector.\" But when the two armies sighted each other, he turned on his heels and said, \"Indeed, I am disassociated from you. Indeed, I see what you do not see; indeed I fear Allah. And Allah is severe in penalty.\""}, {"ayah": 49, "translit": "Iz yaqoolul munaafiqoona wallazeena fee quloobihim maradun gharra haaa'ulaaa'i deenuhum; wa mai yatawakkal 'alal laahi fa innal laaha 'azee zun Hakeem", "translation": "[Remember] when the hypocrites and those in whose hearts was disease said, \"Their religion has deluded those [Muslims].\" But whoever relies upon Allah - then indeed, Allah is Exalted in Might and Wise."}, {"ayah": 50, "translit": "Wa law taraaa iz yatawaf fal lazeena kafarul malaaa'ikatu yadriboona wujoohahum wa adbaarahum wa zooqoo 'azaabal hareeq", "translation": "And if you could but see when the angels take the souls of those who disbelieved... They are striking their faces and their backs and [saying], \"Taste the punishment of the Burning Fire."}, {"ayah": 51, "translit": "Zaalika bimaa qaddamat aideekum wa anal laaha laisa bizallaamil lil 'abeed", "translation": "That is for what your hands have put forth [of evil] and because Allah is not ever unjust to His servants.\""}, {"ayah": 52, "translit": "Kadaabi Aali Fir'awna wal lazeena min qablihim; kafaroo bi Aayaatil laahi fa akhazahu mul laahu bizunoobihim; innal laaha qawiyyun shadeedul 'iqaab", "translation": "[Theirs is] like the custom of the people of Pharaoh and of those before them. They disbelieved in the signs of Allah, so Allah seized them for their sins. Indeed, Allah is Powerful and severe in penalty."}, {"ayah": 53, "translit": "Zaalika bi annal laaha lam yaku mughaiyiran ni matan an'amahaa 'alaa qawmin hattaa yughaiyiroo maa bianfusihim wa annallaaha samee un 'Aleem", "translation": "That is because Allah would not change a favor which He had bestowed upon a people until they change what is within themselves. And indeed, Allah is Hearing and Knowing."}, {"ayah": 54, "translit": "Kadaabi Aali Fir'awna wallazeena min qablihim; kazzaboo bi Aayaati Rabbihim faahlaknaahum bizunoobihim wa aghraqnaa Aala Fir'awn; wa kullun kaanoo zaalimeen", "translation": "[Theirs is] like the custom of the people of Pharaoh and of those before them. They denied the signs of their Lord, so We destroyed them for their sins, and We drowned the people of Pharaoh. And all [of them] were wrongdoers."}, {"ayah": 55, "translit": "Inna sharrad dawaaabbi 'indal laahil lazeena kafaroo fahum laa yu'minoon", "translation": "Indeed, the worst of living creatures in the sight of Allah are those who have disbelieved, and they will not [ever] believe -"}, {"ayah": 56, "translit": "Allazeena'aahatta min hum summa yanqudoona 'ahdahum fee kulli marratinw wa hum laa yattaqoon", "translation": "The ones with whom you made a treaty but then they break their pledge every time, and they do not fear Allah."}, {"ayah": 57, "translit": "Fa immaa tasqafannahum fil harbi fasharrid bihim man khalfahum la'allahum yazzakkaroon", "translation": "So if you, [O Muhammad], gain dominance over them in war, disperse by [means of] them those behind them that perhaps they will be reminded."}, {"ayah": 58, "translit": "Wa immaa takhaafana min qawmin khiyaanatan fambiz ilaihim 'alaa sawaaa'; innal laaha laayuhibbul khaaa'ineen", "translation": "If you [have reason to] fear from a people betrayal, throw [their treaty] back to them, [putting you] on equal terms. Indeed, Allah does not like traitors."}, {"ayah": 59, "translit": "Wa laa yahsabannal lazeena kafaroo sabaqooo; innahum laa yu'jizoon", "translation": "And let not those who disbelieve think they will escape. Indeed, they will not cause failure [to Allah]."}, {"ayah": 60, "translit": "Wa a'iddoo lahum mastata'tum min quwwatinw wa mirribaatil khaili turhiboona bihee 'aduwwal laahi wa 'aduwwakum wa aakhareena min doonihim laa ta'lamoo nahum Allaahu ya'lamuhum; wa maa tunfiqoo min shai'in fee sabeelil laahi yuwaf failaikum wa antum laa tuzlamoon", "translation": "And prepare against them whatever you are able of power and of steeds of war by which you may terrify the enemy of Allah and your enemy and others besides them whom you do not know [but] whom Allah knows. And whatever you spend in the cause of Allah will be fully repaid to you, and you will not be wronged."}, {"ayah": 61, "translit": "Wa in janahoo lissalmi fajnah lahaa wa tawakkal 'alal laah; innahoo Huwas Samee'ul 'Aleem", "translation": "And if they incline to peace, then incline to it [also] and rely upon Allah. Indeed, it is He who is the Hearing, the Knowing."}, {"ayah": 62, "translit": "Wa  iny yureedooo any-yakhda'ooka fainna hasbakal laah; Huwal lazeee aiyadaka binasrihee wa bilmu'mineen", "translation": "But if they intend to deceive you - then sufficient for you is Allah. It is He who supported you with His help and with the believers"}, {"ayah": 63, "translit": "Wa allafa baina quloobihim; law anfaqta maa fil ardi jamee'am maaa allafta baina quloobihim wa laakinnallaaha allafa bainahum; innaahoo 'Azeezun Hakeem", "translation": "And brought together their hearts. If you had spent all that is in the earth, you could not have brought their hearts together; but Allah brought them together. Indeed, He is Exalted in Might and Wise."}, {"ayah": 64, "translit": "Yaaa aiyuhan Nabiyyu hasbukal laahu wa manittaba 'aka minal mu'mineen", "translation": "O Prophet, sufficient for you is Allah and for whoever follows you of the believers."}, {"ayah": 65, "translit": "Yaaa aiyuhan Nabiyyu harridil mu'mineena 'alal qitaal; iny-yakum minkum 'ishroona saabiroona yaghliboo mi'atayn; wa iny-yakum minkum min'atuny yaghlibooo alfam minal lazeena kafaroo bi anahum qawmul laa yafqahoon", "translation": "O Prophet, urge the believers to battle. If there are among you twenty [who are] steadfast, they will overcome two hundred. And if there are among you one hundred [who are] steadfast, they will overcome a thousand of those who have disbelieved because they are a people who do not understand."}, {"ayah": 66, "translit": "Al'aana khaffafal laahu 'ankum wa 'alima anna feekum da'faa; fa-iny yakum minkum mi'atun saabiratuny yaghliboo mi'atayn; wa iny-yakum minkum alfuny yaghlibooo alfaini bi iznil laah; wallaahu ma'as saabireen", "translation": "Now, Allah has lightened [the hardship] for you, and He knows that among you is weakness. So if there are from you one hundred [who are] steadfast, they will overcome two hundred. And if there are among you a thousand, they will overcome two thousand by permission of Allah. And Allah is with the steadfast."}, {"ayah": 67, "translit": "Maa kaana li Nabiyyin ai yakoona lahooo asraa hatta yuskhina fil ard; tureedoona aradad dunyaa wallaahu yureedul Aakhirah; wallaahu 'Azeezun Hakeem", "translation": "It is not for a prophet to have captives [of war] until he inflicts a massacre [upon Allah 's enemies] in the land. Some Muslims desire the commodities of this world, but Allah desires [for you] the Hereafter. And Allah is Exalted in Might and Wise."}, {"ayah": 68, "translit": "Law laa Kitaabum minal laahi sabaqa lamassakum fee maaa akhaztum 'azaabun 'azeem", "translation": "If not for a decree from Allah that preceded, you would have been touched for what you took by a great punishment."}, {"ayah": 69, "translit": "Fakuloo mimaa ghanimtum halaalan taiyibaa; watta qullaah; innal laaha Ghafoorur Raheem", "translation": "So consume what you have taken of war booty [as being] lawful and good, and fear Allah. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 70, "translit": "Yaaa aiyuhan Nabiyyu qul liman feee aideekum minal asraaa iny-ya lamillaahu fee quloobikum khairany yu'tikum khayram mimmaaa ukhiza minkum wa yaghfir lakum; wallaahu Ghafoorur Raheem", "translation": "O Prophet, say to whoever is in your hands of the captives, \"If Allah knows [any] good in your hearts, He will give you [something] better than what was taken from you, and He will forgive you; and Allah is Forgiving and Merciful.\""}, {"ayah": 71, "translit": "Wa iny-yureedoo khiyaa nataka faqad khaanullaaha min qablu fa amkana minhum; wallaahu 'aleemum Hakeem", "translation": "But if they intend to betray you - then they have already betrayed Allah before, and He empowered [you] over them. And Allah is Knowing and Wise."}, {"ayah": 72, "translit": "Innal lazeena aamanoo wa haajaroo wa jaahadoo bi amwaalihim wa anfusihim fee sabeelil laahi wallazeena aawaw wa nasarooo ulaaa'ika ba'duhum awliyaaa'u ba'd; wallazeena aamanoo wa lam yuhaajiroo maa lakum minw walaayatihim min shai'in hatta yuhaajiroo; wa inistan sarookum fid deeni fa'alaiku munnasru illaa 'alaa qawmim bainakum wa bainahum meesaaq; wallaahu bimaa ta'maloona Baseer", "translation": "Indeed, those who have believed and emigrated and fought with their wealth and lives in the cause of Allah and those who gave shelter and aided - they are allies of one another. But those who believed and did not emigrate - for you there is no guardianship of them until they emigrate. And if they seek help of you for the religion, then you must help, except against a people between yourselves and whom is a treaty. And Allah is Seeing of what you do."}, {"ayah": 73, "translit": "Wallazeena kafaroo ba'duhum awliyaaa'u ba'd; illaa taf'aloohu takun fitnatun fil ardi wa fasaadun kabeer", "translation": "And those who disbelieved are allies of one another. If you do not do so, there will be fitnah on earth and great corruption."}, {"ayah": 74, "translit": "Wallazeena aamanoo wa haajaroo wa jaahadoo fee sabeelil laahi wallazeena aawaw wa nasarooo ulaaa'ika humul mu'minoona haqqaa; lahum maghfiratunw wa rizqun kareem", "translation": "But those who have believed and emigrated and fought in the cause of Allah and those who gave shelter and aided - it is they who are the believers, truly. For them is forgiveness and noble provision."}, {"ayah": 75, "translit": "Wallazeena aamanoo mim ba'du wa haajaroo wa jaahadoo ma;akum faulaaa'ika minkum; wa ulul arhaami baduhum awlaa biba'din fee Kitaabil laah; innal laaha bikulli shai'in 'Aleem", "translation": "And those who believed after [the initial emigration] and emigrated and fought with you - they are of you. But those of [blood] relationship are more entitled [to inheritance] in the decree of Allah. Indeed, Allah is Knowing of all things."}]}, {"num": 9, "name": "At-Tawbah", "meaning": "The Repentance", "verses": [{"ayah": 1, "translit": "Baraaa'atum minal laahi wa Rasooliheee ilal lazeena 'anhattum minal mushrikeen", "translation": "[This is a declaration of] disassociation, from Allah and His Messenger, to those with whom you had made a treaty among the polytheists."}, {"ayah": 2, "translit": "Faseehoo fil ardi arba'ata ashhurinw wa'lamoooannakum ghairu mu'jizil laahi wa annal laaha mukhzil kaafireen", "translation": "So travel freely, [O disbelievers], throughout the land [during] four months but know that you cannot cause failure to Allah and that Allah will disgrace the disbelievers."}, {"ayah": 3, "translit": "Wa azaanum minal laahi wa Rasooliheee ilan naasi yawmal Hajjil Akbari annal laaha bareee'um minal mushrikeena wa Rasooluh; fa-in tubtum fahuwa khairullakum wa in tawallaitum fa'lamooo annakum ghairu mu'jizil laah; wa bashiril lazeena kafaroo biazaabin aleem", "translation": "And [it is] an announcement from Allah and His Messenger to the people on the day of the greater pilgrimage that Allah is disassociated from the disbelievers, and [so is] His Messenger. So if you repent, that is best for you; but if you turn away - then know that you will not cause failure to Allah. And give tidings to those who disbelieve of a painful punishment."}, {"ayah": 4, "translit": "Illal lazeena 'aahattum minal mushrikeena summa lam yanqusookum shai'anw-wa lam yuzaahiroo 'alaikum ahadan fa atimmooo ilaihim 'ahdahum ilaa muddatihim; innal laaha yuhibbul muttaqeen", "translation": "Excepted are those with whom you made a treaty among the polytheists and then they have not been deficient toward you in anything or supported anyone against you; so complete for them their treaty until their term [has ended]. Indeed, Allah loves the righteous [who fear Him]."}, {"ayah": 5, "translit": "Fa izansalakhal Ashhurul Hurumu faqtulul mushrikeena haisu wajattumoohum wa khuzoohum wahsuroohum qaq'udoo lahum kulla marsad; fa-in taaboo wa aqaamus Salaata wa aatawuz Zakaata fakhalloo sabeelahum; innal laaha Ghafoorur Raheem", "translation": "And when the sacred months have passed, then kill the polytheists wherever you find them and capture them and besiege them and sit in wait for them at every place of ambush. But if they should repent, establish prayer, and give zakah, let them [go] on their way. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 6, "translit": "Wa in ahadum minal mushrikeenas tajaaraka fa ajirhu hattaa yasma'a Kalaamal laahi summa ablighhu maa manah; zaalika bi annahum qawmul laa ya'lamoon", "translation": "And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the words of Allah. Then deliver him to his place of safety. That is because they are a people who do not know."}, {"ayah": 7, "translit": "Kaifa yakoonu lilmush rikeena 'ahdun 'indallaahi wa 'inda Rasoolihee illal lazeena 'aahattum 'indal Masjidil Haraami famas taqaamoo lakum fastaqeemoo lahum; innallaaha yuhibbul muttaqeen", "translation": "How can there be for the polytheists a treaty in the sight of Allah and with His Messenger, except for those with whom you made a treaty at al-Masjid al-Haram? So as long as they are upright toward you, be upright toward them. Indeed, Allah loves the righteous [who fear Him]."}, {"ayah": 8, "translit": "Kaifa wa iny-yazharoo 'alaikum laa yarquboo feekum illanw wa laa zimmah; yurdoo nakum biafwaahihim wa taabaa quloobuhum wa aksaruhum faasiqoon", "translation": "How [can there be a treaty] while, if they gain dominance over you, they do not observe concerning you any pact of kinship or covenant of protection? They satisfy you with their mouths, but their hearts refuse [compliance], and most of them are defiantly disobedient."}, {"ayah": 9, "translit": "Ishtaraw bi  Aayaatil laahi samanan qaleelan fasaddoo 'an sabeelih; innahum saaa'a maa kaanoo ya'maloon", "translation": "They have exchanged the signs of Allah for a small price and averted [people] from His way. Indeed, it was evil that they were doing."}, {"ayah": 10, "translit": "Laa yarquboona fee mu'minin illanw wa laa zimmah wa ulaaa 'ika humulmu 'tadoon", "translation": "They do not observe toward a believer any pact of kinship or covenant of protection. And it is they who are the transgressors."}, {"ayah": 11, "translit": "Fa in taaboo wa aqaamus Salaata wa aatawuz Zakaata fa ikhwaanukum fid deen; wa nufassilul Aayaati liqawminy ya'lamoon", "translation": "But if they repent, establish prayer, and give zakah, then they are your brothers in religion; and We detail the verses for a people who know."}, {"ayah": 12, "translit": "Wa in nakasooo aimaanahum mim ba'di 'ahdihim wa ta'anoo fee deenikum faqaatilooo a'immatal kufri innahum laaa aimaana lahum la'allahum yantahoon", "translation": "And if they break their oaths after their treaty and defame your religion, then fight the leaders of disbelief, for indeed, there are no oaths [sacred] to them; [fight them that] they might cease."}, {"ayah": 13, "translit": "Alaa tuqaatiloona qawman nakasooo aimaanahum wa hammoo bi ikhraajir Rasooli wa hum bada'ookum awwala marrah; atakhshawnahum; fallaahu ahaqqu an takhshawhu in kuntum mu'mineen", "translation": "Would you not fight a people who broke their oaths and determined to expel the Messenger, and they had begun [the attack upon] you the first time? Do you fear them? But Allah has more right that you should fear Him, if you are [truly] believers."}, {"ayah": 14, "translit": "Qaatiloohum yu'az zibhumul laahu bi aideekum wa yukhzihim wa yansurkum 'alaihim wa yashfi sudoora qawmim mu 'mineen", "translation": "Fight them; Allah will punish them by your hands and will disgrace them and give you victory over them and satisfy the breasts of a believing people"}, {"ayah": 15, "translit": "Wa yuzhib ghaiza quloobihim; wa yatoobullaahu 'alaa mai yashaaa'; wallaahu 'Aleemun Hakeem", "translation": "And remove the fury in the believers' hearts. And Allah turns in forgiveness to whom He wills; and Allah is Knowing and Wise."}, {"ayah": 16, "translit": "Am hasibtum an turakoo wa lammaa ya'lamil laahul lazeena jaahadoo minkum wa lam yattakhizoo min doonil laahi wa laa Rasoolihee wa lalmu'mineena waleejah; wallaahu khabeerum bimaa ta'maloon", "translation": "Do you think that you will be left [as you are] while Allah has not yet made evident those among you who strive [for His cause] and do not take other than Allah, His Messenger and the believers as intimates? And Allah is Acquainted with what you do."}, {"ayah": 17, "translit": "maa kaana lilmushrikeena ai ya'muroo masaajidal laahi shaahideena 'alaaa anfusihim bilkufr; ulaaa'ika habitat a'maaluhum wa fin naari hum khaalidoon", "translation": "It is not for the polytheists to maintain the mosques of Allah [while] witnessing against themselves with disbelief. [For] those, their deeds have become worthless, and in the Fire they will abide eternally."}, {"ayah": 18, "translit": "Innamaa ya'muru masaa jidal laahi man aamana billaahi wal Yawmil Aakhiri wa aqaamas Salaata wa aataz Zakaata wa lam yakkhsa illal laaha fa'asaaa ulaaa'ika ai yakoonoo minal muhtadeen", "translation": "The mosques of Allah are only to be maintained by those who believe in Allah and the Last Day and establish prayer and give zakah and do not fear except Allah, for it is expected that those will be of the [rightly] guided."}, {"ayah": 19, "translit": "Aja'altum siqaayatal haaajji wa 'imaaratal masjidil haraami kamman aamana billaahi wal Yawmil Aakhiri wa jaahada fee sabeelil laah; laa yastawoona 'indal laah; wallaahu laa yahdil qawmaz zaalimeen", "translation": "Have you made the providing of water for the pilgrim and the maintenance of al-Masjid al-Haram equal to [the deeds of] one who believes in Allah and the Last Day and strives in the cause of Allah? They are not equal in the sight of Allah. And Allah does not guide the wrongdoing people."}, {"ayah": 20, "translit": "Allazeena aamanoo wa haajaroo wa jaahadoo fee sabeelil laahi bi amwaalihim wa anufsihim a'zamu darajatan 'indal laah; wa ulaaa'ika humul faaa'izoon", "translation": "The ones who have believed, emigrated and striven in the cause of Allah with their wealth and their lives are greater in rank in the sight of Allah. And it is those who are the attainers [of success]."}, {"ayah": 21, "translit": "Yubashshiruhum Rabbuhum birahmatim minhu wa ridwaaninw wa Jannaatil lahum feehaa na'eemum muqeem", "translation": "Their Lord gives them good tidings of mercy from Him and approval and of gardens for them wherein is enduring pleasure."}, {"ayah": 22, "translit": "Khaalideena feehaaa abadaa; innal laaha 'indahooo ajrun 'azeem", "translation": "[They will be] abiding therein forever. Indeed, Allah has with Him a great reward."}, {"ayah": 23, "translit": "Yaaa aiyuhal lazeena aamanoo laa tattakhizooo aabaaa 'akum wa ikhwaanakum awliyaaa'a inis tahabbul kufra 'alal eemaan; wa mai yatawal lahum minkum fa ulaaa'ika humuz zaalimoon", "translation": "O you who have believed, do not take your fathers or your brothers as allies if they have preferred disbelief over belief. And whoever does so among you - then it is those who are the wrongdoers."}, {"ayah": 24, "translit": "Qul in kaana aabaaa'ukum wa abnaaa'ukum wa ikhwaanukum wa azwaajukum wa 'asheeratukum wa amwaaluniq taraftumoohaa wa tijaaratun takhshawna kasaadahaa wa masaakinu tardawnahaaa ahabba ilaikum minal laahi wa Rasoolihee wa Jihaadin fee Sabeelihee fatarabbasoo hattaa yaatiyallaahu bi amrih; wallaahu laa yahdil qawmal faasiqeen", "translation": "Say, [O Muhammad], \"If your fathers, your sons, your brothers, your wives, your relatives, wealth which you have obtained, commerce wherein you fear decline, and dwellings with which you are pleased are more beloved to you than Allah and His Messenger and jihad in His cause, then wait until Allah executes His command. And Allah does not guide the defiantly disobedient people.\""}, {"ayah": 25, "translit": "Laqad nasarakumul laahu fee mawaatina kaseeratinw wa yawma Hunainin iz a'jabatkum kasratukum falam tughni 'ankum shai'anw wa daaqat 'alaikumul ardu bimaa rahubat summa wallaitum mudbireen", "translation": "Allah has already given you victory in many regions and [even] on the day of Hunayn, when your great number pleased you, but it did not avail you at all, and the earth was confining for you with its vastness; then you turned back, fleeing."}, {"ayah": 26, "translit": "Summa anzalal laahu sakeenatahoo 'alaa Rasoolihee wa 'alalmu 'mineena wa anzala junoodal lam tarawhaa wa azzabal lazeena kafaroo; wa zaalika jazaaa'ul kaafireen", "translation": "Then Allah sent down His tranquillity upon His Messenger and upon the believers and sent down soldiers angels whom you did not see and punished those who disbelieved. And that is the recompense of the disbelievers."}, {"ayah": 27, "translit": "Summa yatoobul laahu mim ba'di zaalika 'alaa mai yashaaa'; wallaahu Ghafoorur Raheem", "translation": "Then Allah will accept repentance after that for whom He wills; and Allah is Forgiving and Merciful."}, {"ayah": 28, "translit": "Yaaa aiyuhal lazeena aamanooo innamal mushrikoona najasun falaa yaqrabul Masjidal Haraama ba'da 'aamihim haaza; wa in khiftum 'ailatan fasawfa yughnee kumul laahu min fadliheee in shaaa'; innallaaha 'Aleemun hakeem", "translation": "O you who have believed, indeed the polytheists are unclean, so let them not approach al-Masjid al-Haram after this, their [final] year. And if you fear privation, Allah will enrich you from His bounty if He wills. Indeed, Allah is Knowing and Wise."}, {"ayah": 29, "translit": "Qaatilul lazeena laa yu'minoona billaahi wa laa bil yawmil Aakhiri wa laa yuharrimoona maa harramal laahu wa Rasooluhoo wa laa yadeenoona deenal haqqi minal lazeena ootul Kitaaba hattaa yu'tul jizyata ai yadinw wa hum saaghiroon", "translation": "Fight those who do not believe in Allah or in the Last Day and who do not consider unlawful what Allah and His Messenger have made unlawful and who do not adopt the religion of truth from those who were given the Scripture - [fight] until they give the jizyah willingly while they are humbled."}, {"ayah": 30, "translit": "Q qaalatil yahoodu 'Uzairunib nul laahi wa qaalatin Nasaaral Maseehub nul laahi zaalika qawluhum bi afwaahihim yudaahi'oona qawlal lazeena kafaroo min qabl; qatalahumul laah; annaa yu'fakoon", "translation": "The Jews say, \"Ezra is the son of Allah \"; and the Christians say, \"The Messiah is the son of Allah.\" That is their statement from their mouths; they imitate the saying of those who disbelieved [before them]. May Allah destroy them; how are they deluded?"}, {"ayah": 31, "translit": "ittakhazooo ahbaarahum wa ruhbaanahum arbaabammin doonil laahi wal Maseehab na Maryama wa maaa umirooo illaa liya'budooo Ilaahanw Waa hidan laaa ilaaha illaa Hoo; Subhaanahoo 'ammaa yushrikoon", "translation": "They have taken their scholars and monks as lords besides Allah, and [also] the Messiah, the son of Mary. And they were not commanded except to worship one God; there is no deity except Him. Exalted is He above whatever they associate with Him."}, {"ayah": 32, "translit": "Yureedoona ai yutfi'oo nooral laahi bi'afwaahihim wa yaaballaahu illaaa ai yutimma noorahoo wa law karihal kaafiroon", "translation": "They want to extinguish the light of Allah with their mouths, but Allah refuses except to perfect His light, although the disbelievers dislike it."}, {"ayah": 33, "translit": "huwal lazeee ar sala Rasoolahoo bilhudaa wa deenil haqqi liyuzhirahoo 'alad deeni kullihee wa law karihal mushrikoon", "translation": "It is He who has sent His Messenger with guidance and the religion of truth to manifest it over all religion, although they who associate others with Allah dislike it."}, {"ayah": 34, "translit": "Yaaa aiyuhal lazeena aamanooo inna kaseeramminal ahbaari warruhbaani la yaakuloona amwaalan naasi bil baatili wa yasuddoona 'an sabeelil laah; wallazeena yaknizoonaz zahaba wal fiddata wa laayunfiqoonahaa fee sabeelil laahi fabashshirhum bi'azaabin aleem", "translation": "O you who have believed, indeed many of the scholars and the monks devour the wealth of people unjustly and avert [them] from the way of Allah. And those who hoard gold and silver and spend it not in the way of Allah - give them tidings of a painful punishment."}, {"ayah": 35, "translit": "Yawma yuhmaa 'alaihaa fee naari jahannama fatukwaa bihaa jibaahuhum haazaa maa kanaztum li anfusikum fazooqoo maa kuntum taknizoon", "translation": "The Day when it will be heated in the fire of Hell and seared therewith will be their foreheads, their flanks, and their backs, [it will be said], \"This is what you hoarded for yourselves, so taste what you used to hoard.\""}, {"ayah": 36, "translit": "Inna 'iddatash shuhoori 'indal laahis naa 'ashara shahran fee Kitaabil laahi yawma khalaqas samaawaati wal arda minhaaa arba'atun hurum; zaalikad deenul qaiyim; falaa tazlimoo feehinna anfusakum; wa qaatilul mushrikeena kaaaf fattan kamaa yuqaati loonakum kaaaffah; wa'lamooo annal laaha ma'al muttaqeen", "translation": "Indeed, the number of months with Allah is twelve [lunar] months in the register of Allah [from] the day He created the heavens and the earth; of these, four are sacred. That is the correct religion, so do not wrong yourselves during them. And fight against the disbelievers collectively as they fight against you collectively. And know that Allah is with the righteous [who fear Him]."}, {"ayah": 37, "translit": "Innamma naseee'u ziyaadatun filkufri yudallu bihillazeena kafaroo yuhil loonahoo 'aamanw wa yuhar rimoonahoo 'aamalliyu watti'oo 'iddata maa harramal laah; zuyyina lahum sooo'u a'maalihim; wallaahu laa yahdil qawmal kaafireen", "translation": "Indeed, the postponing [of restriction within sacred months] is an increase in disbelief by which those who have disbelieved are led [further] astray. They make it lawful one year and unlawful another year to correspond to the number made unlawful by Allah and [thus] make lawful what Allah has made unlawful. Made pleasing to them is the evil of their deeds; and Allah does not guide the disbelieving people."}, {"ayah": 38, "translit": "Yaaa aiyuhal lazeena aamanoo maa lakum izaa qeela lakumun firoo fee sabeelil laahis saaqaltum ilal ard; aradeetum bilhayaatid dunyaa minal Aakhirah; famaa ma taaul hayaatiddunyaa fil Aakhirati illaa qaleel", "translation": "O you who have believed, what is [the matter] with you that, when you are told to go forth in the cause of Allah, you adhere heavily to the earth? Are you satisfied with the life of this world rather than the Hereafter? But what is the enjoyment of worldly life compared to the Hereafter except a [very] little."}, {"ayah": 39, "translit": "Illaa tanfiroo yu'az zibkum 'azaaban aleemanw wa yastabdil qawman ghairakum wa laa tadurroohu shai'aa; wal laahu 'alaa kulli shai'in Qadeer", "translation": "If you do not go forth, He will punish you with a painful punishment and will replace you with another people, and you will not harm Him at all. And Allah is over all things competent."}, {"ayah": 40, "translit": "Illaa tansuroohu faqad nasarahul laahu iz akhrajahul lazeena kafaroo saaniyasnaini iz humaa filghaari iz yaqoolu lisaahibihee la tahzan innnal laaha ma'anaa fa anzalallaahu sakeenatahoo 'alaihi wa aiyadahoo bijunoodil lam tarawhaa wa ja'ala kalimatal lazeena kafarus suflaa; wa Kalimatul laahi hiyal 'ulyaa; wallaahu 'Azeezun Hakeem;", "translation": "If you do not aid the Prophet - Allah has already aided him when those who disbelieved had driven him out [of Makkah] as one of two, when they were in the cave and he said to his companion, \"Do not grieve; indeed Allah is with us.\" And Allah sent down his tranquillity upon him and supported him with angels you did not see and made the word of those who disbelieved the lowest, while the word of Allah - that is the highest. And Allah is Exalted in Might and Wise."}, {"ayah": 41, "translit": "Infiroo khifaafanw wa siqaalanw wa jaahidoo bi amwaalikum wa anfusikum fee sabeelil laah; zaalikum khairul lakum in kuntum ta'lamoon", "translation": "Go forth, whether light or heavy, and strive with your wealth and your lives in the cause of Allah. That is better for you, if you only knew."}, {"ayah": 42, "translit": "Law kaana 'aradan qareebanw wa safaran qaasidal lattaba'ooka wa laakim ba'udat 'alaihimush shuqqah; wa sayahlifoona billaahi lawis tata'naa lakharajnaa ma'akum; yuhlikoona anfusahum wal laahu ya'lamu innahum lakaa ziboon", "translation": "Had it been an easy gain and a moderate trip, the hypocrites would have followed you, but distant to them was the journey. And they will swear by Allah, \"If we were able, we would have gone forth with you,\" destroying themselves [through false oaths], and Allah knows that indeed they are liars."}, {"ayah": 43, "translit": "'Afal laahu 'anka lima azinta lahum hattaa yatabai yana lakal lazeena sadaqoo wa ta'lamal kaazibeen", "translation": "May Allah pardon you, [O Muhammad]; why did you give them permission [to remain behind]? [You should not have] until it was evident to you who were truthful and you knew [who were] the liars."}, {"ayah": 44, "translit": "Laa yastaazinukal lazeena yu'minoona billaahi wal Yawmil Aakhiri ai yujaa hidoo bi amwaalihim wa anfusihim; wallaahu 'aleemum bilmut taqeen", "translation": "Those who believe in Allah and the Last Day would not ask permission of you to be excused from striving with their wealth and their lives. And Allah is Knowing of those who fear Him."}, {"ayah": 45, "translit": "Innamaa yastaazinukal lazeena laa yu'minoona billaahi wal Yawmil Aakhiri wartaabat quloobuhum fahum fee raibihim yataraddadoon", "translation": "Only those would ask permission of you who do not believe in Allah and the Last Day and whose hearts have doubted, and they, in their doubt, are hesitating."}, {"ayah": 46, "translit": "Wa law araadul khurooja la-'addoo lahoo 'uddatanw wa laakin karihal laahum bi'aasahum fasabbatahum wa qeelaq 'udoo ma'al qaa'ideen", "translation": "And if they had intended to go forth, they would have prepared for it [some] preparation. But Allah disliked their being sent, so He kept them back, and they were told, \"Remain [behind] with those who remain.\""}, {"ayah": 47, "translit": "Law kharajoo feekum maa zaadookum ilaa Khabaalanw wa la awda'oo khilaalakum yabghoona kumul fitnata wa feekum sammaa'oona lahum; wallaahu 'aleemum biz zaalimeen", "translation": "Had they gone forth with you, they would not have increased you except in confusion, and they would have been active among you, seeking [to cause] you fitnah. And among you are avid listeners to them. And Allah is Knowing of the wrongdoers."}, {"ayah": 48, "translit": "Laqadib taghawul fitnata min qablu wa qallaboo lakal umoora hattaa jaaa'al haqqu wa zahara amrul laahi wa hum kaarihoon", "translation": "They had already desired dissension before and had upset matters for you until the truth came and the ordinance of Allah appeared, while they were averse."}, {"ayah": 49, "translit": "Wa minhum mai yaqoolu' zal lee wa laa taftinneee; alaa fil fitnati saqatoo; wa inna Jahannama lamuheetatum bil kaafireen", "translation": "And among them is he who says, \"Permit me [to remain at home] and do not put me to trial.\" Unquestionably, into trial they have fallen. And indeed, Hell will encompass the disbelievers."}, {"ayah": 50, "translit": "in tusibka hasanatun tasu'hum; wa in tusibka museebatuny yaqooloo qad akhaznaaa amranaa min qablu wa yatawallaw wa hum farihoon", "translation": "If good befalls you, it distresses them; but if disaster strikes you, they say, \"We took our matter [in hand] before,\" and turn away while they are rejoicing."}, {"ayah": 51, "translit": "Qul lany-yuseebanaaa illaa maa katabal laahu lanaa Huwa mawlaanaa; wa 'alal laahi falyatawak kalimu 'minoon", "translation": "Say, \"Never will we be struck except by what Allah has decreed for us; He is our protector.\" And upon Allah let the believers rely."}, {"ayah": 52, "translit": "Qul hal tarabbasoona binaaa illaaa ihdal husnayayni wa nahnu natrabbasu bikum ai yus eebakumul laahu bi'azaa bim min 'indiheee aw biaidee naa fatarabbasooo innaa ma'akum mutarabbisoon", "translation": "Say, \"Do you await for us except one of the two best things while we await for you that Allah will afflict you with punishment from Himself or at our hands? So wait; indeed we, along with you, are waiting.\""}, {"ayah": 53, "translit": "Qul anfiqoo taw'an aw karhal lany yutaqabbala min kum innakum kuntum qawman faasiqeen", "translation": "Say, \"Spend willingly or unwillingly; never will it be accepted from you. Indeed, you have been a defiantly disobedient people.\""}, {"ayah": 54, "translit": "Wa maa mana'ahum an tuqbala minhum nafaqaatuhum illaaa annnahum kafaroo billaahi wa bi Rasoolihee wa laa yaatoonas Salaata illaa wa hum kusaalaa wa laa yunfiqoona illaa wa hum kaarihoon", "translation": "And what prevents their expenditures from being accepted from them but that they have disbelieved in Allah and in His Messenger and that they come not to prayer except while they are lazy and that they do not spend except while they are unwilling."}, {"ayah": 55, "translit": "Falaa tu'jibka amwaaluhum wa laaa awlaaduhum; innamaa yureedul laahu liyu'az zibahum bihaa fil hayaatid dunyaa wa tazhaqa anfusuhum wa hum kaafiroon", "translation": "So let not their wealth or their children impress you. Allah only intends to punish them through them in worldly life and that their souls should depart [at death] while they are disbelievers."}, {"ayah": 56, "translit": "Wa yahlifoona billaahi innnahum laminkum wa maa hum minkum wa laakinnahum qawmuny yafraqoon", "translation": "And they swear by Allah that they are from among you while they are not from among you; but they are a people who are afraid."}, {"ayah": 57, "translit": "Law yajidoona malja'an aw maghaaraatin aw mudda khalal lawallaw ilaihi wa hum yajmahoon", "translation": "If they could find a refuge or some caves or any place to enter [and hide], they would turn to it while they run heedlessly."}, {"ayah": 58, "translit": "Wa minhum mai yalmizuka fis sadaqaati fa-in u'too minhaa radoo wa illam yu'taw minhaaa izaa hum yaskhatoon", "translation": "And among them are some who criticize you concerning the [distribution of] charities. If they are given from them, they approve; but if they are not given from them, at once they become angry."}, {"ayah": 59, "translit": "Wa law annahum radoo maaa aataahumul laahu wa Rasooluhoo wa qaaloo hasbunal laahu wayu'teenallaahu min fadlihee wa Rasooluhooo innaaa ilallaahi raaghiboon", "translation": "If only they had been satisfied with what Allah and His Messenger gave them and said, \"Sufficient for us is Allah; Allah will give us of His bounty, and [so will] His Messenger; indeed, we are desirous toward Allah,\" [it would have been better for them]."}, {"ayah": 60, "translit": "Innamas sadaqaatu lilfuqaraaa'i walmasaakeeni wal 'aamileena 'alaihaa wal mu'al lafati quloobuhum wa fir riqaabi walghaarimeena wa fee sabeelil laahi wabnis sabeeli fareedatam minal laah; wal laahu 'Aleemun Hakeem", "translation": "Zakah expenditures are only for the poor and for the needy and for those employed to collect [zakah] and for bringing hearts together [for Islam] and for freeing captives [or slaves] and for those in debt and for the cause of Allah and for the [stranded] traveler - an obligation [imposed] by Allah. And Allah is Knowing and Wise."}, {"ayah": 61, "translit": "Wa minhumul lazeena yu'zoonan nabiyya wa yaqooloona huwa uzun; qul uzunu khairil lakum yu'minu billaahi wa yu'minu lilmu mi neena wa rahmatul  lillazeena aamanoo minkum; wallazeena yu'zoona Rasoolal laahi lahum 'azaabun aleem", "translation": "And among them are those who abuse the Prophet and say, \"He is an ear.\" Say, \"[It is] an ear of goodness for you that believes in Allah and believes the believers and [is] a mercy to those who believe among you.\" And those who abuse the Messenger of Allah - for them is a painful punishment."}, {"ayah": 62, "translit": "yahlifoona billaahi lakum liyurdookum wallaahu wa Rasooluhoo ahaqqu ai yurdoohu in kaanoo mu'mineen", "translation": "They swear by Allah to you [Muslims] to satisfy you. But Allah and His Messenger are more worthy for them to satisfy, if they should be believers."}, {"ayah": 63, "translit": "Alam ya'lamooo annahoo mai yuhaadidillaaha wa Rasoolahoo faanna lahoo Naara jahannama khaalidan feehaa; zaalikal khizyul 'Azeem", "translation": "Do they not know that whoever opposes Allah and His Messenger - that for him is the fire of Hell, wherein he will abide eternally? That is the great disgrace."}, {"ayah": 64, "translit": "Yahzarul munaafiqoona an tunaz zala 'alaihim Sooratun tunabbi 'uhum bimaa feequloobihim; qulistahzi'oo innal laaha mukhrijum maa tahzaroon", "translation": "They hypocrites are apprehensive lest a surah be revealed about them, informing them of what is in their hearts. Say, \"Mock [as you wish]; indeed, Allah will expose that which you fear.\""}, {"ayah": 65, "translit": "Wala'in sa altahum layaqoolunna innamaa kunnaa nakhoodu wa nal'ab; qul abillaahi wa 'Aayaatihee wa Rasoolihee kuntum tastahzi'oon", "translation": "And if you ask them, they will surely say, \"We were only conversing and playing.\" Say, \"Is it Allah and His verses and His Messenger that you were mocking?\""}, {"ayah": 66, "translit": "Laa ta'taziroo qad kafartum ba'da eemaanikum; in na'fu 'an taaa'ifatim minkum nu'az zib taaa'ifatam bi annahum kaanoo mujrimeen", "translation": "Make no excuse; you have disbelieved after your belief. If We pardon one faction of you - We will punish another faction because they were criminals."}, {"ayah": 67, "translit": "Almunaafiqoona wal munaafiqaatu ba'duhum mim ba'd; yaamuroona bilmunkari wa yanhawna 'anil ma'roofi wa yaqbidoona aidiyahum; nasul laaha fanasiyahum; innal munaafiqeena humul faasiqoon", "translation": "The hypocrite men and hypocrite women are of one another. They enjoin what is wrong and forbid what is right and close their hands. They have forgotten Allah, so He has forgotten them [accordingly]. Indeed, the hypocrites - it is they who are the defiantly disobedient."}, {"ayah": 68, "translit": "Wa'adal laahul munafiqeena wal munaafiqaati wal kuffaara naara jahannnamma khaalideena feehaa; hiya hasbuhum; wa la'annahumul laahu wa lahum 'azaabum muqeem", "translation": "Allah has promised the hypocrite men and hypocrite women and the disbelievers the fire of Hell, wherein they will abide eternally. It is sufficient for them. And Allah has cursed them, and for them is an enduring punishment."}, {"ayah": 69, "translit": "Kallazeena min qablikum kaanoo ashadda minkum quwwatanw wa aksara amwaalanw wa awlaadan fastamta'oo bikhalaaqihim fastamta'tum bikhalaaqikum kamas tamta'al lazeena min qablikum bikhalaa qihim wa khudtum kallazee khaadooo; ulaaa'ika habitat a'maaluhum fid dunyaa wal Aakhirati wa ulaaa'ika humul khaasiroon", "translation": "[You disbelievers are] like those before you; they were stronger than you in power and more abundant in wealth and children. They enjoyed their portion [of worldly enjoyment], and you have enjoyed your portion as those before you enjoyed their portion, and you have engaged [in vanities] like that in which they engaged. [It is] those whose deeds have become worthless in this world and in the Hereafter, and it is they who are the losers."}, {"ayah": 70, "translit": "Alam yaatihim naba ul lazeena min qablihim qawmi Noohinw wa 'Aadinw wa Samooda wa qawmi Ibraaheema wa ashaabi adyana walmu'tafikaat; atathum Rusuluhum bilbaiyinaati famaa kaanal laahu liyazlimahum wa laakin kaanooo anfusahum yazlimoon", "translation": "Has there not reached them the news of those before them - the people of Noah and [the tribes of] 'Aad and Thamud and the people of Abraham and the companions of Madyan and the towns overturned? Their messengers came to them with clear proofs. And Allah would never have wronged them, but they were wronging themselves."}, {"ayah": 71, "translit": "Walmu'minoona wal mu'minaatu ba'duhum awliyaaa'u ba;d; yaamuroona bilma'roofi wa yanhawna 'anil munkari wa yuqeemoonas Salaata wa yu'toonaz Zakaata wa yutee'oonal laaha wa Rasoolah; ulaaa'ika sayarhamuhumul laah; innallaaha 'Azeezun Hakeem", "translation": "The believing men and believing women are allies of one another. They enjoin what is right and forbid what is wrong and establish prayer and give zakah and obey Allah and His Messenger. Those - Allah will have mercy upon them. Indeed, Allah is Exalted in Might and Wise."}, {"ayah": 72, "translit": "Wa'adal laahulmu' mineena walmu'minaati Jannaatin tajree min tahtihal anhaaru khaalideena feehaa wa masaakina taiyibatan fee Jannnaati 'adn; wa ridwaanum minal laahi akbar; zaalika hual fawzul 'azeem", "translation": "Allah has promised the believing men and believing women gardens beneath which rivers flow, wherein they abide eternally, and pleasant dwellings in gardens of perpetual residence; but approval from Allah is greater. It is that which is the great attainment."}, {"ayah": 73, "translit": "yaaa aiyuhan Nabiyyu jaahidil kuffaara walmunaafiqeena waghluz 'alaihim; wa maawaahum jahannnamu wa bi'sal maseer", "translation": "O Prophet, fight against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination."}, {"ayah": 74, "translit": "Yahlifoona billaahi wa qaaloo wa laqad qaaloo kalimatal kufri wa kafaroo ba'da Islaamihim wa hammoo bimaa lam yanaaloo; wa maa naqamooo illaaa an aghnaa humullaahu wa Rasooluhoo min fadlih; fainy yatooboo yaku khairal lahum wa iny yatawal law yu'az zibhumullaahu 'azaaban aleeman fiddunyaa wal Aakhirah; wamaa lahum fil ardi minw waliyyinw wa laa naseer", "translation": "They swear by Allah that they did not say [anything against the Prophet] while they had said the word of disbelief and disbelieved after their [pretense of] Islam and planned that which they were not to attain. And they were not resentful except [for the fact] that Allah and His Messenger had enriched them of His bounty. So if they repent, it is better for them; but if they turn away, Allah will punish them with a painful punishment in this world and the Hereafter. And there will not be for them on earth any protector or helper."}, {"ayah": 75, "translit": "Wa minhum man 'aaha dal laaha la'in aataanaa min fadlihee lanas saddaqanna wa lanakoonanna minassaaliheen", "translation": "And among them are those who made a covenant with Allah, [saying], \"If He should give us from His bounty, we will surely spend in charity, and we will surely be among the righteous.\""}, {"ayah": 76, "translit": "Falammaaa aataahum min fadlihee bakhiloo bihee wa tawallaw wa hum mu'ridoon", "translation": "But when he gave them from His bounty, they were stingy with it and turned away while they refused."}, {"ayah": 77, "translit": "Fa a'qabahum nifaaqan fee quloobihim ilaa Yawmi yalqaw nahoo bimaaa akhlaful laaha maa wa'adoohu wa bimaa kaanoo yakhziboon", "translation": "So He penalized them with hypocrisy in their hearts until the Day they will meet Him - because they failed Allah in what they promised Him and because they [habitually] used to lie."}, {"ayah": 78, "translit": "Alam ya'lamooo annal laaha ya'lamu sirrahum wa najwaahum wa annal laaha 'Allaamul Ghuyoob", "translation": "Did they not know that Allah knows their secrets and their private conversations and that Allah is the Knower of the unseen?"}, {"ayah": 79, "translit": "Allazeena yalmizoonal mut tawwi'eena minalmu'mineena fis sadaqaati wallazeena laa yajidoona illaa juhdahum fayaskharoona minhum sakhiral laahu minhum wa lahum azaabun aleem", "translation": "Those who criticize the contributors among the believers concerning [their] charities and [criticize] the ones who find nothing [to spend] except their effort, so they ridicule them - Allah will ridicule them, and they will have a painful punishment."}, {"ayah": 80, "translit": "istaghfir lahum aw laa tastaghfir lahum in tastaghfir lahum sab'eena marratan falany yaghfiral laahu lahum; zaalika bi annahum kafaroo billaahi wa Rasoolih; wallaahu laa yahdil qawmal faasiqeen", "translation": "Ask forgiveness for them, [O Muhammad], or do not ask forgiveness for them. If you should ask forgiveness for them seventy times - never will Allah forgive them. That is because they disbelieved in Allah and His Messenger, and Allah does not guide the defiantly disobedient people."}, {"ayah": 81, "translit": "Farihal mukhallafoona bimaq'adihim khilaafa Rasoolil laahi wa karihooo ai yujaahidoo bi amwaalihim wa anfusihim fee sabeelil laahi wa qaaloo la tanfiroo fil harr; qul Naaru jahannama ashaddu harraa; law kaanoo yafqahoon", "translation": "Those who remained behind rejoiced in their staying [at home] after [the departure of] the Messenger of Allah and disliked to strive with their wealth and their lives in the cause of Allah and said, \"Do not go forth in the heat.\" Say, \"The fire of Hell is more intensive in heat\" - if they would but understand."}, {"ayah": 82, "translit": "Falyadhakoo qaleelanw walyabkoo kaseeran jazaaa'am bimaa kaanoo yaksiboon", "translation": "So let them laugh a little and [then] weep much as recompense for what they used to earn."}, {"ayah": 83, "translit": "Fa ir raja'akal laahu ilaa taaa'ifatim minhum fastaaa zanooka lilkhurooji faqul lan takhrujoo ma'iya abadanw a lan tuqaatiloo ma'iya 'aduwwan innakum radeetum bilqu'oodi awwala marratin faq'udoo ma'al khaalifeen", "translation": "If Allah should return you to a faction of them [after the expedition] and then they ask your permission to go out [to battle], say, \"You will not go out with me, ever, and you will never fight with me an enemy. Indeed, you were satisfied with sitting [at home] the first time, so sit [now] with those who stay behind.\""}, {"ayah": 84, "translit": "Wa laa tusalli 'alaaa ahadim minhum maata abadanw wa laa taqum 'alaa qabriheee innahum kafaroo billaahi wa Rasoolihee wa maatoo wa hum faasiqoon", "translation": "And do not pray [the funeral prayer, O Muhammad], over any of them who has died - ever - or stand at his grave. Indeed, they disbelieved in Allah and His Messenger and died while they were defiantly disobedient."}, {"ayah": 85, "translit": "Wa laa tu'jibka amwaa luhum wa awlaaduhum; innamaa yureedul laahu ai yu'az zibahum bihaa fid dunyaa wa tazhaqa anfusuhum wa hum kaafiroon", "translation": "And let not their wealth and their children impress you. Allah only intends to punish them through them in this world and that their souls should depart [at death] while they are disbelievers."}, {"ayah": 86, "translit": "Wa izaaa unzilat Sooratun an aaminoo billaahi wa jaahidoo ma'a Rasoolihis taazanaka uluttawli minhum wa qaaloo zarnaa nakum ma'alqaa 'ideen", "translation": "And when a surah was revealed [enjoining them] to believe in Allah and to fight with His Messenger, those of wealth among them asked your permission [to stay back] and said, \"Leave us to be with them who sit [at home].\""}, {"ayah": 87, "translit": "Radoo bi ai yakoonoo ma'al khawaalifi wa tubi'a 'alaa quloobihim fahum laa yafqahoon", "translation": "They were satisfied to be with those who stay behind, and their hearts were sealed over, so they do not understand."}, {"ayah": 88, "translit": "Laakinir Rasoolu wal lazeena aamanoo ma'ahoo jaahadoo bi amwaalihim wa anfusihim; wa ulaaa'ika lahumul khairaatu wa ulaaa'ika humul muflihoon", "translation": "But the Messenger and those who believed with him fought with their wealth and their lives. Those will have [all that is] good, and it is those who are the successful."}, {"ayah": 89, "translit": "A'addal laahu lahum Jannaatin tajree min tahtihal anhaaru khaalideena feehaa; zaalikal fawzul 'azeem", "translation": "Allah has prepared for them gardens beneath which rivers flow, wherein they will abide eternally. That is the great attainment."}, {"ayah": 90, "translit": "Wa jaaa'al mu'az ziroona minal A'raabi liyu'zana lahum wa qa'adal lazeena kazabul laaha wa Rasoolah; sayuseebul lazeena kafaroo minhum 'azaabun aleem", "translation": "And those with excuses among the bedouins came to be permitted [to remain], and they who had lied to Allah and His Messenger sat [at home]. There will strike those who disbelieved among them a painful punishment."}, {"ayah": 91, "translit": "Laisa 'alad du'aaaa'i wa laa 'alal mardaa wa laa 'alal lazeena laa yajidoona maa yunfiqoona harajun izaa nasahoo lillaahi wa Rasoolih; maa 'alal muhsineena min sabeel; wallaahu Ghafoorur Raheem", "translation": "There is not upon the weak or upon the ill or upon those who do not find anything to spend any discomfort when they are sincere to Allah and His Messenger. There is not upon the doers of good any cause [for blame]. And Allah is Forgiving and Merciful."}, {"ayah": 92, "translit": "Wa laa 'alal lazeena izaa maaa atawka litahmilahum qulta laaa ajidu maaa ahmilukum 'alaihi tawallaw wa a'yunuhum tafeedu minaddam'i hazanan allaa yajidoo maa yunfiqoon", "translation": "Nor [is there blame] upon those who, when they came to you that you might give them mounts, you said, \"I can find nothing for you to ride upon.\" They turned back while their eyes overflowed with tears out of grief that they could not find something to spend [for the cause of Allah]."}, {"ayah": 93, "translit": "Innamas sabeelu 'alal lazeena yastaazinoonaka wa hum aghniyaaa'; radoo biany-yakoonoo ma'al khawaalifi wa taba'al laahu 'alaa quloobihim fahum laa ya'lamoon", "translation": "The cause [for blame] is only upon those who ask permission of you while they are rich. They are satisfied to be with those who stay behind, and Allah has sealed over their hearts, so they do not know."}, {"ayah": 94, "translit": "ya'taziroona ilaikum izaa raja'tum ilaihim; qul laa ta'taziroo lan nu'mina lakum qad nabba annal laahu min akhbaarikum; wa sa yaral laahu 'amalakum wa Rasooluhoo suma turaddoona ilaa 'Aalimil Ghaibi washshahaadati fa yunabbi'ukum bimaa kuntum ta'maloon", "translation": "They will make excuses to you when you have returned to them. Say, \"Make no excuse - never will we believe you. Allah has already informed us of your news. And Allah will observe your deeds, and [so will] His Messenger; then you will be taken back to the Knower of the unseen and the witnessed, and He will inform you of what you used to do.\""}, {"ayah": 95, "translit": "Sa yahlifoona billaahi lakum izanqalabtum ilaihim litu'ridoo 'anhum fa a'ridoo 'anhum innahum rijsunw wa maawaahum jahannamu jazaaa 'ambimaa kaanoo yaksiboon", "translation": "They will swear by Allah to you when you return to them that you would leave them alone. So leave them alone; indeed they are evil; and their refuge is Hell as recompense for what they had been earning."}, {"ayah": 96, "translit": "Yahlifoona lakum litardaw 'anhum fa in tardaw 'anhum fa innal laaha laa yardaa 'anil qawmil faasiqeen", "translation": "They swear to you so that you might be satisfied with them. But if you should be satisfied with them - indeed, Allah is not satisfied with a defiantly disobedient people."}, {"ayah": 97, "translit": "Al A'raabu ashaddu kufranw wa nifaaqanw wa ajdaru allaa ya'lamoo hudooda maaa anzalal laahu 'alaa Rasoolih; wallaahu 'Aleemun Hakeem", "translation": "The bedouins are stronger in disbelief and hypocrisy and more likely not to know the limits of what [laws] Allah has revealed to His Messenger. And Allah is Knowing and Wise."}, {"ayah": 98, "translit": "Wa minal A'raabi mai yattakhizu maa yunfiqu maghramanw wa yatarabbasu bikumud dawaaa'ir; alaihim daaa'iratus saw'; wallaahu Samee'un 'Aleem", "translation": "And among the bedouins are some who consider what they spend as a loss and await for you turns of misfortune. Upon them will be a misfortune of evil. And Allah is Hearing and Knowing."}, {"ayah": 99, "translit": "Wa minal A'raabi mai yu'minu billaahi wal yawmil AAkhiri wa yattakhizu maa yunfiqu qurubaatin 'indal laahi wa salawaatir Rasool; alaaa innahaa qurbatul lahum; sayudkhiluhumul laahu fee rahmatih; innal laaha Ghafoorur Raheem", "translation": "But among the bedouins are some who believe in Allah and the Last Day and consider what they spend as means of nearness to Allah and of [obtaining] invocations of the Messenger. Unquestionably, it is a means of nearness for them. Allah will admit them to His mercy. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 100, "translit": "Was saabiqoonal awwa loona minal Muhaajireena wal Ansaari wallazeenat taba'oo hum bi ihsaanir radiyal laahu 'anhum wa radoo 'anhu wa a'adda lahum jannnaatin tajree tahtahal anhaaru khaalideena feehaaa abadaa; zaalikal fawzul 'azeem", "translation": "And the first forerunners [in the faith] among the Muhajireen and the Ansar and those who followed them with good conduct - Allah is pleased with them and they are pleased with Him, and He has prepared for them gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment."}, {"ayah": 101, "translit": "Wa mimmann hawlakum minal A'raabi munaafiqoona wa min ahlil Madeenati maradoo 'alan nifaaq, laa ta'lamuhum nahnu na'lamuhum; sanu'azzibuhum marrataini summa yuraddoona ilaa 'azaabin 'azeem", "translation": "And among those around you of the bedouins are hypocrites, and [also] from the people of Madinah. They have become accustomed to hypocrisy. You, [O Muhammad], do not know them, [but] We know them. We will punish them twice [in this world]; then they will be returned to a great punishment."}, {"ayah": 102, "translit": "Wa aakharoona' tarafoo bizunoobihim khalatoo 'amalan saalihanw wa aakhara saiyi'an 'asal laahu ai yatooba 'alaihim; innal laaha Ghafoorur Raheem", "translation": "And [there are] others who have acknowledged their sins. They had mixed a righteous deed with another that was bad. Perhaps Allah will turn to them in forgiveness. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 103, "translit": "Khuz min amwaalihim sadaqtan tutahhiruhum wa tuzakkeehim bihaa wa salli 'alaihim inna salaataka sakanul lahum; wallaahu Samee'un 'Aleem", "translation": "Take, [O, Muhammad], from their wealth a charity by which you purify them and cause them increase, and invoke [Allah 's blessings] upon them. Indeed, your invocations are reassurance for them. And Allah is Hearing and Knowing."}, {"ayah": 104, "translit": "Alam ya'lamooo annnal laaha huwa yaqbalut tawbata 'an ibaadihee wa yaakhuzus sadaqaati wa annal laaha Huwat awwaabur Raheem", "translation": "Do they not know that it is Allah who accepts repentance from His servants and receives charities and that it is Allah who is the Accepting of repentance, the Merciful?"}, {"ayah": 105, "translit": "Wa quli'maloo fasayaral laahu 'amalakum wa Rasooluhoo walmu'minoona wa saturaddoona ilaa 'Aalimil Ghaibi washshahaadati fa yunabbi'ukum bimaa kuntum ta'maloon", "translation": "And say, \"Do [as you will], for Allah will see your deeds, and [so, will] His Messenger and the believers. And you will be returned to the Knower of the unseen and the witnessed, and He will inform you of what you used to do.\""}, {"ayah": 106, "translit": "Wa aakharoona murjawna li amril laahi imaa yu'az zibuhum wa immaa yatoobu 'alaihim; wallaahu 'Aleemun Hakeem", "translation": "And [there are] others deferred until the command of Allah - whether He will punish them or whether He will forgive them. And Allah is Knowing and Wise."}, {"ayah": 107, "translit": "Wallazeenat takhazoo masjidan diraaranw wa kufranw wa tafreeqam bainal mu'mineena wa irsaadal liman haarabal laaha wa Rasoolahoo min qabl; wa la yahlifunna in aradnaaa illal husnaa wallaahu yash hadu innahum lakaaziboon", "translation": "And [there are] those [hypocrites] who took for themselves a mosque for causing harm and disbelief and division among the believers and as a station for whoever had warred against Allah and His Messenger before. And they will surely swear, \"We intended only the best.\" And Allah testifies that indeed they are liars."}, {"ayah": 108, "translit": "Laa taqum feehi abadaa; lamasjidun ussisa 'alat taqwaa min awwali yawmin ahaqqu an taqooma feeh; feehi rijaaluny yuhibbona ai yatatahharoo, wallaahu yuhibbul mmuttah hireen", "translation": "Do not stand [for prayer] within it - ever. A mosque founded on righteousness from the first day is more worthy for you to stand in. Within it are men who love to purify themselves; and Allah loves those who purify themselves."}, {"ayah": 109, "translit": "Afaman assasa bunyaa nahoo 'alaa taqwaa minal laahi wa ridwaanin khairun am man assasa bunyaanahoo 'alaa shafaa jurufin haarin fanhaara bihee fee Naari Jahannnam; wallaahu laa yahdil qawmaz zaalimeen", "translation": "Then is one who laid the foundation of his building on righteousness [with fear] from Allah and [seeking] His approval better or one who laid the foundation of his building on the edge of a bank about to collapse, so it collapsed with him into the fire of Hell? And Allah does not guide the wrongdoing people."}, {"ayah": 110, "translit": "Laa yazaalu bunyaanu humul lazee banaw reebatan fee quloobihim illaaa an taqatta'a quloobuhum; wal laahu 'Aleemun Hakeem", "translation": "Their building which they built will not cease to be a [cause of] skepticism in their hearts until their hearts are stopped. And Allah is Knowing and Wise."}, {"ayah": 111, "translit": "Innal laahash taraa minal mu'mineena anfusahum wa amwaalahum bi anna lahumul jannah; yuqaatiloona fee sabeelil laahi fa yaqtuloona wa yuqtaloona wa'dan 'alaihi haqqan fit Tawraati wal Injeeli wal Qur-aan; wa man awfaa be'ahdihee minal laah; fastabshiroo bibai'ikumul lazee baaya'tum bih; wa zaalika huwal fawzul 'azeem", "translation": "Indeed, Allah has purchased from the believers their lives and their properties [in exchange] for that they will have Paradise. They fight in the cause of Allah, so they kill and are killed. [It is] a true promise [binding] upon Him in the Torah and the Gospel and the Qur'an. And who is truer to his covenant than Allah? So rejoice in your transaction which you have contracted. And it is that which is the great attainment."}, {"ayah": 112, "translit": "At taaa'iboonal 'aabidoonal haamidoonas saaa'ihoonar raaki'oonas saajidoonal aamiroona bilma'roofi wannaahoona 'anil munkari walhaafizoona lihudoodil laah; wa bashshiril mu'mineen", "translation": "[Such believers are] the repentant, the worshippers, the praisers [of Allah], the travelers [for His cause], those who bow and prostrate [in prayer], those who enjoin what is right and forbid what is wrong, and those who observe the limits [set by] Allah. And give good tidings to the believers."}, {"ayah": 113, "translit": "Maa kaana lin nabiyyi wallazeena aamanooo ai yastaghfiroo lilmushrikeena wa law kaanoo ulee qurbaa mim ba'di maa tabiyana lahum annahum Ashaabul jaheem", "translation": "It is not for the Prophet and those who have believed to ask forgiveness for the polytheists, even if they were relatives, after it has become clear to them that they are companions of Hellfire."}, {"ayah": 114, "translit": "Wa maa kaanas tighfaaru ibraaheema li abeehi illaa 'ammaw 'idatinw wa 'adahaaa iyyaahu falammaa tabaiyana lahooo annahoo 'aduwwul lillaahi tabarra a minh; inna Ibraaheema la awwaahum haleem", "translation": "And the request of forgiveness of Abraham for his father was only because of a promise he had made to him. But when it became apparent to Abraham that his father was an enemy to Allah, he disassociated himself from him. Indeed was Abraham compassionate and patient."}, {"ayah": 115, "translit": "Wa maa kaanal laahu liyudilla qawmam ba'da iz hadaahum hatta yubaiyina lahum maa yattaqoon; innal laaha bikulli shai'in 'Aleem", "translation": "And Allah would not let a people stray after He has guided them until He makes clear to them what they should avoid. Indeed, Allah is Knowing of all things."}, {"ayah": 116, "translit": "Innal laaha lahoo mulkus samaawaati wal ardi yuhyee wa yumeet; wa maa lakum min doonil laahi minw waliyyinw wa laa naseer", "translation": "Indeed, to Allah belongs the dominion of the heavens and the earth; He gives life and causes death. And you have not besides Allah any protector or any helper."}, {"ayah": 117, "translit": "Laqat taabal laahu 'alan nabiyyi wal Muhaajireena wal Ansaaril lazeenat taba'oohu fee saa'atil 'usrati mim ba'di maa kaada yazeeghu quloobu fareeqim minhum summma taaba 'alaihim; innahoo bihim Ra'oofur Raheem", "translation": "Allah has already forgiven the Prophet and the Muhajireen and the Ansar who followed him in the hour of difficulty after the hearts of a party of them had almost inclined [to doubt], and then He forgave them. Indeed, He was to them Kind and Merciful."}, {"ayah": 118, "translit": "Wa 'alas salaasatil lazeena khullifoo hattaaa izaa daaqat 'alaihimul ardu bimaa rahubat wa daaqat 'alaihim anfusuhum wa zannnooo al laa malja-a minal laahi illaaa ilaihi summa taaba 'alaihim liyatooboo; innal laaha Huwat Tawwaabur Raheem", "translation": "And [He also forgave] the three who were left behind [and regretted their error] to the point that the earth closed in on them in spite of its vastness and their souls confined them and they were certain that there is no refuge from Allah except in Him. Then He turned to them so they could repent. Indeed, Allah is the Accepting of repentance, the Merciful."}, {"ayah": 119, "translit": "Yaaa aiyuhal lazeena aamanut taqul laaha wa koonoo ma'as saadiqeen", "translation": "O you who have believed, fear Allah and be with those who are true."}, {"ayah": 120, "translit": "Maa kaana li ahlil Madeenati wa man hawlahum minal A'raabi ai yatakhallafoo 'ar-Rasoolil laahi wa laa yarghaboo bi anfusihim 'an nafsih; zaalika bi annahum laa yuseebuhum zama unw wa laa nasabunw wa laa makhmasatun fee sabeelil laahi wa laa yata'oona mawti'ai yagheezul kuffaara wa laa yanaaloona min 'aduwwin nailan illaa kutiba lahum bihee 'amalun saalih; innal laaha laa yudee'u ajral muhsineen", "translation": "It was not [proper] for the people of Madinah and those surrounding them of the bedouins that they remain behind after [the departure of] the Messenger of Allah or that they prefer themselves over his self. That is because they are not afflicted by thirst or fatigue or hunger in the cause of Allah, nor do they tread on any ground that enrages the disbelievers, nor do they inflict upon an enemy any infliction but that is registered for them as a righteous deed. Indeed, Allah does not allow to be lost the reward of the doers of good."}, {"ayah": 121, "translit": "Wa laa yunfiqoona nafa qatan sagheeratanw wa laa kabeeratanw wa laa yaqta'oona waadiyan illaa kutiba lahum liyajziyahumul laahu ahsana maa kaanoo ya'maloon", "translation": "Nor do they spend an expenditure, small or large, or cross a valley but that it is registered for them that Allah may reward them for the best of what they were doing."}, {"ayah": 122, "translit": "Wa maa kaanal mu'minoona liyanfiroo kaaaffah; falaw laa nafara min kulli firqatim minhum taaa'ifatul liyatafaqqahoo fiddeeni wa liyunziroo qawmahum izaa raja'ooo ilaihim la'allahum yahzaroon", "translation": "And it is not for the believers to go forth [to battle] all at once. For there should separate from every division of them a group [remaining] to obtain understanding in the religion and warn their people when they return to them that they might be cautious."}, {"ayah": 123, "translit": "Yaaa aiyuhal lazeena aamanoo qaatilul lazeena yaloonakum minal kuffaari walyajidoo feekum ghilzah; wa'lamooo annal laaha ma'al muttaqeen", "translation": "O you who have believed, fight those adjacent to you of the disbelievers and let them find in you harshness. And know that Allah is with the righteous."}, {"ayah": 124, "translit": "Wa izaa maaa unzilat Sooratun faminhum mai yaqoolu aiyukum zaadat hu haazihee eemaanaa; fa ammal lazeena aamanoo fazaadat hum eemaananw wa hum yastabshiroon", "translation": "And whenever a surah is revealed, there are among the hypocrites those who say, \"Which of you has this increased faith?\" As for those who believed, it has increased them in faith, while they are rejoicing."}, {"ayah": 125, "translit": "Wa ammal lazeena fee quloobihim maradun fazaadat hum rijsan ilaa rijsihim wa maatoo wa hum kaafiroon", "translation": "But as for those in whose hearts is disease, it has [only] increased them in evil [in addition] to their evil. And they will have died while they are disbelievers."}, {"ayah": 126, "translit": "Awalaa yarawna annahum yuftanoona fee kulli 'aamim marratan aw marrataini summa laa yatooboona wa laa hum yazzakkkaroon", "translation": "Do they not see that they are tried every year once or twice but then they do not repent nor do they remember?"}, {"ayah": 127, "translit": "Wa izaa maaa unzilat Sooratun nazara ba'duhum ilaa ba'din hal yaraakum min ahadin summman sarafoo; sarafal laahu quloobahum bi annahum qawmul laa yafqahoon", "translation": "And whenever a surah is revealed, they look at each other, [saying], \"Does anyone see you?\" and then they dismiss themselves. Allah has dismissed their hearts because they are a people who do not understand."}, {"ayah": 128, "translit": "Laqad jaaa'akum Rasoolum min anfusikum 'azeezun 'alaihi maa 'anittum hareesun 'alaikum bilmu'mineena ra'oofur raheem", "translation": "There has certainly come to you a Messenger from among yourselves. Grievous to him is what you suffer; [he is] concerned over you and to the believers is kind and merciful."}, {"ayah": 129, "translit": "Fa in tawallaw faqul lhasbiyal laahu laaa ilaaha illaa Huwa 'alaihi tawakkkaltu wa Huwa Rabbul 'Arshil 'Azeem", "translation": "But if they turn away, [O Muhammad], say, \"Sufficient for me is Allah; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne.\""}]}, {"num": 10, "name": "Yunus", "meaning": "Jonah", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Raa; tilka Aayaatul Kitaabil Hakeem", "translation": "Alif, Lam, Ra. These are the verses of the wise Book"}, {"ayah": 2, "translit": "A kaana linnaasi 'aaban an awhainaaa ilaa rajulim minhum an anzirin naasa wa bashshiril lazeena aamanoo anna lahum qadama sidqin 'inda Rabbihim; qaalal kaafiroona inna haaza lasaahirum mubeen", "translation": "Have the people been amazed that We revealed [revelation] to a man from among them, [saying], \"Warn mankind and give good tidings to those who believe that they will have a [firm] precedence of honor with their Lord\"? [But] the disbelievers say, \"Indeed, this is an obvious magician.\""}, {"ayah": 3, "translit": "Inna Rabbakumul laahul lazee khalaqas samaawaati wal arda fee sittati aiyaamin summas tawaa 'alal 'Arshi yudabbirul amra maa min shafee'in illaa mim ba'di iznih; zalikumul laahu Rabbukum fa'budooh; afalaa tazakkaroon", "translation": "Indeed, your Lord is Allah, who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter [of His creation]. There is no intercessor except after His permission. That is Allah, your Lord, so worship Him. Then will you not remember?"}, {"ayah": 4, "translit": "Ilaihi marji'ukum jamee 'anw wa'dal laahi haqqaa; innahoo yabda'ul khalqa summa yu'eeduhoo liyajziyal lazeena aamanoo wa 'amilus saalihaati bilqist; wallazeena kafaroo lahum sharaabum min hamee minw wa 'azaabun aleemum bimaa kaanoo yakfuroon", "translation": "To Him is your return all together. [It is] the promise of Allah [which is] truth. Indeed, He begins the [process of] creation and then repeats it that He may reward those who have believed and done righteous deeds, in justice. But those who disbelieved will have a drink of scalding water and a painful punishment for what they used to deny."}, {"ayah": 5, "translit": "Huwal lazee ja'alash shamsa diyaaa'anw walqamara nooranw wa qaddarahoo manaaz zila lita'lamoo 'adadas sineena walhisaab; maa khalaqal laahu zaalika illa bilhaqq; yufassilul aayaati liqawminw ya'lamoon", "translation": "It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allah has not created this except in truth. He details the signs for a people who know"}, {"ayah": 6, "translit": "Inna fikh tilaafil laili wannahaari wa maa khalaqal laahu fis samaawaati wal ardi la Aayaatil liqawminy yattaqoon", "translation": "Indeed, in the alternation of the night and the day and [in] what Allah has created in the heavens and the earth are signs for a people who fear Allah"}, {"ayah": 7, "translit": "Innal lazeena laa yarjoona liqaaa'anaa wa radoo bilhayaatid dunyaa watma annoo bihaa wallazeena hum 'an Aayaatinaa ghaafiloon", "translation": "Indeed, those who do not expect the meeting with Us and are satisfied with the life of this world and feel secure therein and those who are heedless of Our signs"}, {"ayah": 8, "translit": "Ulaaa'ika maawaahumun Naaru bimaa kaanoo yaksiboon", "translation": "For those their refuge will be the Fire because of what they used to earn."}, {"ayah": 9, "translit": "Innal lazeena aamanoo wa 'amilus saalihaati yahdeehim Rabbuhum bi eemaanihim tajree min tahtihimul anhaaru fee jannaatin Na'eem", "translation": "Indeed, those who have believed and done righteous deeds - their Lord will guide them because of their faith. Beneath them rivers will flow in the Gardens of Pleasure"}, {"ayah": 10, "translit": "Da'waahum feehaa Subbaanakal laahumma wa tahiyyatuhum feehaa salaam; wa aakhiru da'waahum anil hamdu lillaahi Rabbil 'aalameen", "translation": "Their call therein will be, \"Exalted are You, O Allah,\" and their greeting therein will be, \"Peace.\" And the last of their call will be, \"Praise to Allah, Lord of the worlds!\""}, {"ayah": 11, "translit": "Wa law yu'aijilul laahu linnaasish sharras ti'jaalahum bilkhairi laqudiya ilaihim ajaluhum fanazarul lazeena laa yarjoona liqaaa'anna fee tughyaanihim ya'mahoon", "translation": "And if Allah was to hasten for the people the evil [they invoke] as He hastens for them the good, their term would have been ended for them. But We leave the ones who do not expect the meeting with Us, in their transgression, wandering blindly"}, {"ayah": 12, "translit": "Wa izaa massal insaanad durru da'aanaa lijambiheee aw qaa'idan aw qaaa'iman falammaa kashafnaa 'anhu durrahoo marra ka al lam yad'unaaa ilaa durrim massah; kazaalika zuyyina lilmusrifeena maa kaanoo ya'maloon", "translation": "And when affliction touches man, he calls upon Us, whether lying on his side or sitting or standing; but when We remove from him his affliction, he continues [in disobedience] as if he had never called upon Us to [remove] an affliction that touched him. Thus is made pleasing to the transgressors that which they have been doing"}, {"ayah": 13, "translit": "Wa laqad ahlaknal quroona min qablikum lammaa zalamoo wa jaaa'at hum Rusuluhum bil baiyinaati wa maa kaanoo liyu'minoo; kazaalika najzil qawmal mujrimeen", "translation": "And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people"}, {"ayah": 14, "translit": "Summa ja'alnaakum khalaaa'ifa fil ardi mim ba'dihim linanzura kaifa ta'maloon", "translation": "Then We made you successors in the land after them so that We may observe how you will do."}, {"ayah": 15, "translit": "Wa izaa tutlaa 'alaihim aayaatunaa baiyinaatin qaalal lazeena laa yarjoona liqaaa'ana'ti bi Quraanin ghairi haazaaa aw baddilh; qul maa yakoonu leee an ubaddilahoo min tilqaaa'i nafsee in attabi'u illaa maa yoohaaa ilaiya inneee akhaafu in 'asaytu Rabbee 'azaaba Yawmin 'Azeeem", "translation": "And when Our verses are recited to them as clear evidences, those who do not expect the meeting with Us say, \"Bring us a Qur'an other than this or change it.\" Say, [O Muhammad], \"It is not for me to change it on my own accord. I only follow what is revealed to me. Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day.\""}, {"ayah": 16, "translit": "Qul law shaaa'al laahu maa talawtuhoo 'alaikum wa laaa adraakum bihee faqad labistu feekum 'umuram min qablih; afalaa ta'qiloon", "translation": "Say, \"If Allah had willed, I would not have recited it to you, nor would He have made it known to you, for I had remained among you a lifetime before it. Then will you not reason?\""}, {"ayah": 17, "translit": "Faman azlamu mimmanif taraa 'alal laahi kaziban aw kazzaba bi Aayaatih; innahoo laa yuflihul mujrimoon", "translation": "So who is more unjust than he who invents a lie about Allah or denies His signs? Indeed, the criminals will not succeed"}, {"ayah": 18, "translit": "Wa ya'budoona min doonil laahi maa laa yadurruhum wa laa yanfa'uhum wa yaqooloona haaa'ulaaa'i shufa'aaa 'unaa 'indal laah; qul atunabbi 'oonal laaha bima laa ya'lamu fis samaawaati wa laa fil ard; subhaanahoo wa Ta'aalaa 'ammaa yushrikoon", "translation": "And they worship other than Allah that which neither harms them nor benefits them, and they say, \"These are our intercessors with Allah \" Say, \"Do you inform Allah of something He does not know in the heavens or on the earth?\" Exalted is He and high above what they associate with Him"}, {"ayah": 19, "translit": "Wa maa kaanan naasu illaaa ummmatanw waahidatan fakh talafoo; wa law laa kalimatun sabaqat mir Rabbika laqudiya bainahum fee maa feehi yakhtalifoon", "translation": "And mankind was not but one community [united in religion], but [then] they differed. And if not for a word that preceded from your Lord, it would have been judged between them [immediately] concerning that over which they differ."}, {"ayah": 20, "translit": "W yaqooloona law laaa unzila 'alaihi aayatum mir Rabbihee faqul innamal ghaibu lillaahi fantaziroo innee ma'akum minal muntazireen", "translation": "And they say, \"Why is a sign not sent down to him from his Lord?\" So say, \"The unseen is only for Allah [to administer], so wait; indeed, I am with you among those who wait.\""}, {"ayah": 21, "translit": "Wa izaaa azaqnan naasa rahmatam mim ba'di darraaa'a massat hum izaa lahum makrun feee aayaatinaa; qulil laahu asra'u makraa; inna rusulanaa yaktuboona maa tamkuroon", "translation": "And when We give the people a taste of mercy after adversity has touched them, at once they conspire against Our verses. Say, \"Allah is swifter in strategy.\" Indeed, Our messengers record that which you conspire"}, {"ayah": 22, "translit": "Huwal lazee yusaiyirukum fil barri walbahri hattaaa izaa kuntum fil fulki wa jaraina bihim bireeh in taiyibatinw wa farihoo bihaa jaaa'at haa reehun 'aasifunw wa jaaa'ahumul mawju min kulli makaaninw wa zannooo annahum uheeta bihim da'awul laaha mukhliseena lahud deena la'in anjaitanaa min haazihee lanakoonannna minash shaakireen", "translation": "It is He who enables you to travel on land and sea until, when you are in ships and they sail with them by a good wind and they rejoice therein, there comes a storm wind and the waves come upon them from everywhere and they assume that they are surrounded, supplicating Allah, sincere to Him in religion, \"If You should save us from this, we will surely be among the thankful.\""}, {"ayah": 23, "translit": "Falammaaa anjaahum izaa hum yabghoona fil ardi bighairil haqq; yaaa aiyuhannaasu innamaa bagh yukum 'alaaa anfusikum mataa'al hayaatid dunyaa summa ilainaa marji'ukum fanunabbi 'ukum bimaa kuntum ta'maloon", "translation": "But when He saves them, at once they commit injustice upon the earth without right. O mankind, your injustice is only against yourselves, [being merely] the enjoyment of worldly life. Then to Us is your return, and We will inform you of what you used to do."}, {"ayah": 24, "translit": "Innamaa masalul hayaatid dunyaa kammaaa'in anzalnaahu minas sammaaa'i fakhtalata bihee nabaatul ardi mimmaa yaakulun naasu wal an'aam; hattaaa izaaa akhazatil ardu zukhrufahaa wazziyanat wa zanna ahluhaaa annahum qaadiroona 'alaihaaa ataahaaa amrunaa lailan aw nahaaran faja'alnaahaa haseedan ka allam taghna bil-ams; kazaalika nufassilul aayaati liqawminy yatafakkaroon", "translation": "The example of [this] worldly life is but like rain which We have sent down from the sky that the plants of the earth absorb - [those] from which men and livestock eat - until, when the earth has taken on its adornment and is beautified and its people suppose that they have capability over it, there comes to it Our command by night or by day, and We make it as a harvest, as if it had not flourished yesterday. Thus do We explain in detail the signs for a people who give thought."}, {"ayah": 25, "translit": "Wallaahu yad'ooo ilaa daaris salaami wa yahdee mai yashaaa'u ilaa Siraatim Mustaqeem", "translation": "And Allah invites to the Home of Peace and guides whom He wills to a straight path"}, {"ayah": 26, "translit": "Lillazeena ahsanul husnaa wa ziyaadahtunw wa laa yarhaqu wujoohahum qatarunw wa laa zillah; ulaaa'ika ashaabul jannnati hum feehaa khaalidoon", "translation": "For them who have done good is the best [reward] and extra. No darkness will cover their faces, nor humiliation. Those are companions of Paradise; they will abide therein eternally"}, {"ayah": 27, "translit": "Wallazeena kasabus saiyi aati jazaaa'u saiyi'atim bimislihaa wa tarhaquhum zillah; maa lahum minal laahi min 'aasimin ka annamaaa ughshiyat wujoohuhum qita 'am minal laili muzlimaa; ulaaa'ika Ashaabun Naari hum feeha khaalidoon", "translation": "But they who have earned [blame for] evil doings - the recompense of an evil deed is its equivalent, and humiliation will cover them. They will have from Allah no protector. It will be as if their faces are covered with pieces of the night - so dark [are they]. Those are the companions of the Fire; they will abide therein eternally."}, {"ayah": 28, "translit": "Wa yawma nahshuruhum jamee'an summa naqoolu lillazeena ashrakoo makaanakum antum wa shurakaaa'ukum; fazaiyalnaa bainahum wa qaala shurakaaa'uhum maa kuntum iyyaanaa ta'budoon", "translation": "And [mention, O Muhammad], the Day We will gather them all together - then We will say to those who associated others with Allah, \"[Remain in] your place, you and your 'partners.' \" Then We will separate them, and their \"partners\" will say, \"You did not used to worship us,"}, {"ayah": 29, "translit": "Fakafaa billaahi shaheedam bainanaa wa bainakum in kunnaa 'an 'ibaadatikum laghaafileen", "translation": "And sufficient is Allah as a witness between us and you that we were of your worship unaware.\""}, {"ayah": 30, "translit": "Hunaalika tabloo kullu nafsim maaa aslafat; wa ruddoo ilal laahi mawlaahu mul haqqi wa dalla 'anhum maa kaanoo yaftaroon", "translation": "There, [on that Day], every soul will be put to trial for what it did previously, and they will be returned to Allah, their master, the Truth, and lost from them is whatever they used to invent."}, {"ayah": 31, "translit": "Qul mai yarzuqukum minas samaaa'i wal ardi ammany yamlikus sam'a wal absaara wa mai yukhrijul haiya minal maiyiti wa yikhrijul maiyita minal haiyi wa mai yudabbirul amr; fasa yaqooloonal laah; faqul afalaa tattaqoon", "translation": "Say, \"Who provides for you from the heaven and the earth? Or who controls hearing and sight and who brings the living out of the dead and brings the dead out of the living and who arranges [every] matter?\" They will say, \"Allah,\" so say, \"Then will you not fear Him?\""}, {"ayah": 32, "translit": "Fazaalikumul laahu Rabbukumul haqq; famaazaa ba'dal haqqi illad dalaalu fa annnaa tusrafoon", "translation": "For that is Allah, your Lord, the Truth. And what can be beyond truth except error? So how are you averted?"}, {"ayah": 33, "translit": "Kazaalika haqqat Kalimatu Rabbika 'alal lazeena fasaqooo annahum laa yu'minoon", "translation": "Thus the word of your Lord has come into effect upon those who defiantly disobeyed - that they will not believe."}, {"ayah": 34, "translit": "Qul hal min shurakaaa 'ikum mai yabda'ul khalqa suma yu'eeduh; qulil laahu yabda'ul khalqa summa yu'eeduhoo fa annaa tu'fakoon", "translation": "Say, \"Are there of your 'partners' any who begins creation and then repeats it?\" Say, \"Allah begins creation and then repeats it, so how are you deluded?\""}, {"ayah": 35, "translit": "Qul hal min shurakaaa 'ikum mai yahdeee ilal haqq; qulil laahu yahdee lilhaqq; afamai yahdeee ilal haqqi ahaqqu ai yuttaba'a ammal laa yahiddeee illaaa ai yuhdaa famaa lakum kaifa tahkumoon", "translation": "Say, \"Are there of your 'partners' any who guides to the truth?\" Say, \"Allah guides to the truth. So is He who guides to the truth more worthy to be followed or he who guides not unless he is guided? Then what is [wrong] with you - how do you judge?\""}, {"ayah": 36, "translit": "Wa maa yattabi'u aksaruhum illaa zannaa; innaz zanna laa yughnee minal haqqi shai'aa; innal laaha 'Aleemum bimaa yaf'aloon", "translation": "And most of them follow not except assumption. Indeed, assumption avails not against the truth at all. Indeed, Allah is Knowing of what they do."}, {"ayah": 37, "translit": "Wa maa kaana haazal Quraanu ai yuftaraa min doonil laahi wa laakin tasdeeqal lazee baina yadaihi wa tafseelal Kitaabi laa raiba fee mir Rabbil 'aalameen", "translation": "And it was not [possible] for this Qur'an to be produced by other than Allah, but [it is] a confirmation of what was before it and a detailed explanation of the [former] Scripture, about which there is no doubt, from the Lord of the worlds."}, {"ayah": 38, "translit": "Am yaqooloonaf taraahu qul faatoo bisooratim mislihee wad'oo manis tata'tum min doonil laahi in kuntum saadiqeen", "translation": "Or do they say [about the Prophet], \"He invented it?\" Say, \"Then bring forth a surah like it and call upon [for assistance] whomever you can besides Allah, if you should be truthful.\""}, {"ayah": 39, "translit": "Bal kazzaboo bimaa lam yuheetoo bi'ilmihee wa lammaa yaatihim taaweeluh; kazaalika kazzabal lazeena min qablihim fanzur kaifa kaana 'aaqibatuz zaalimeen", "translation": "Rather, they have denied that which they encompass not in knowledge and whose interpretation has not yet come to them. Thus did those before them deny. Then observe how was the end of the wrongdoers."}, {"ayah": 40, "translit": "Wa minhum mai yu 'minu bihee wa minhum mal laa yu'minu bih; wa Rabbuka a'lamu bilmufsideen", "translation": "And of them are those who believe in it, and of them are those who do not believe in it. And your Lord is most knowing of the corrupters"}, {"ayah": 41, "translit": "Wa in kazzabooka faqul lee 'amalee wa lakum 'amalukum antum bareee'oona mimmaaa a'malu wa ana bareee'um mimmaa ta'maloon", "translation": "And if they deny you, [O Muhammad], then say, \"For me are my deeds, and for you are your deeds. You are disassociated from what I do, and I am disassociated from what you do.\""}, {"ayah": 42, "translit": "Wa minhum mai yastami'oona iliak; afa anta tusmi'us summa wa law kaanoo la ya'qiloon", "translation": "And among them are those who listen to you. But can you cause the deaf to hear, although they will not use reason?"}, {"ayah": 43, "translit": "Wa minhum mai yanzuru ilaik; afa anta tahdil 'umya wa law kaanoo laa yubsiroon", "translation": "And among them are those who look at you. But can you guide the blind although they will not [attempt to] see?"}, {"ayah": 44, "translit": "Innal laaha laa yazlimun naasa shai'anw wa laakin nannaasa anfusahum yazlimoon", "translation": "Indeed, Allah does not wrong the people at all, but it is the people who are wronging themselves."}, {"ayah": 45, "translit": "Wa Yawma yahshuruhum ka al lam yalbasooo illaa saa'atam minan nahaari yata'aarafoona bainahum; qad khasiral lazeena kazzaboo biliqaaa'il laahi wa maa kaanoo muhtadeen", "translation": "And on the Day when He will gather them, [it will be] as if they had not remained [in the world] but an hour of the day, [and] they will know each other. Those will have lost who denied the meeting with Allah and were not guided"}, {"ayah": 46, "translit": "Wa imma nuriyannaka ba'dal lazee na'iduhum aw natawaffayannaka fa ilainaa marji'uhum summal laahu shaheedun 'alaa maa yaf'aloon", "translation": "And whether We show you some of what We promise them, [O Muhammad], or We take you in death, to Us is their return; then, [either way], Allah is a witness concerning what they are doing"}, {"ayah": 47, "translit": "Wa likulli ummatir Rasoolun fa izaa jaaa'a Rasooluhum qudiya bainahum bilqisti wa hum laa yuzlamoon", "translation": "And for every nation is a messenger. So when their messenger comes, it will be judged between them in justice, and they will not be wronged"}, {"ayah": 48, "translit": "Wa yaqooloona mataa haazal wa'du in kuntum saadiqeen", "translation": "And they say, \"When is [the fulfillment of] this promise, if you should be truthful?\""}, {"ayah": 49, "translit": "Qul laaa amliku linafsee darranw wa laa naf'an illaa maa shaaa'al laah; likulli ummatin ajalun izaa jaaa'a ajaluhum falaaa yastaakhiroona saa'a tanw wa laa yastaqdimoon", "translation": "Say, \"I possess not for myself any harm or benefit except what Allah should will. For every nation is a [specified] term. When their time has come, then they will not remain behind an hour, nor will they precede [it].\""}, {"ayah": 50, "translit": "Qul ara'aitum in ataakum 'azaabuhoo bayaatan aw nahaaram maazaa yasta'jilu minhul mujrimoon", "translation": "Say, \"Have you considered: if His punishment should come to you by night or by day - for which [aspect] of it would the criminals be impatient?\""}, {"ayah": 51, "translit": "Asumma izaa maa waqa'a aamantum bih; aaal'aana wa qad kuntum bihee tasta'jiloon", "translation": "Then is it that when it has [actually] occurred you will believe in it? Now? And you were [once] for it impatient"}, {"ayah": 52, "translit": "Summa qeela lillazeena zalamoo zooqoo 'azaabal khuld hal tujzawna illaa bimaa kuntum taksiboon", "translation": "Then it will be said to those who had wronged, \"Taste the punishment of eternity; are you being recompensed except for what you used to earn?\""}, {"ayah": 53, "translit": "Wa yastambi'oonaka ahaqqun huwa qul ee wa Rabbeee innahoo lahaqq; wa maaa antum bimu'jizeen", "translation": "And they ask information of you, [O Muhammad], \"Is it true?\" Say, \"Yes, by my Lord. Indeed, it is truth; and you will not cause failure [to Allah].\""}, {"ayah": 54, "translit": "Wa law anna likulli nafsin zalamat maa fil ardi laftadat bih; wa asarrun nadaamata lammaa ra awul 'azaab, wa qudiya bainahum bilqist; wa hum laa yuzlamoon", "translation": "And if each soul that wronged had everything on earth, it would offer it in ransom. And they will confide regret when they see the punishment; and they will be judged in justice, and they will not be wronged"}, {"ayah": 55, "translit": "Alaaa inna lillaahi maa fis samaawaati wal ard; alaaa inna wa'dal laahi haqqunw wa laakinna aksarahum laa ya'lamoon", "translation": "Unquestionably, to Allah belongs whatever is in the heavens and the earth. Unquestionably, the promise of Allah is truth, but most of them do not know"}, {"ayah": 56, "translit": "Huwa yuhyee wa yumeetu wailaihi turja'oon", "translation": "He gives life and causes death, and to Him you will be returned"}, {"ayah": 57, "translit": "Yaaa aiyuhan naasu qad jaaa'atkum maw 'izatum mir Rabbikum wa shifaaa'ul limaa fis sudoori wa hudanw wa rahmatul lilmu'mineen", "translation": "O mankind, there has to come to you instruction from your Lord and healing for what is in the breasts and guidance and mercy for the believers."}, {"ayah": 58, "translit": "Qul bifadlil laahi wa birahmatihii fabizaalika falyaf rahoo huwa khairum mimmaa yajma'oon", "translation": "Say, \"In the bounty of Allah and in His mercy - in that let them rejoice; it is better than what they accumulate.\""}, {"ayah": 59, "translit": "Qul ara'aitum maaa anzalal laahu lakum mir rizqin faja'altum minhu haraamanw wa halaalan qul aaallaahu azina lakum am 'alal laahi taftaroon", "translation": "Say, \"Have you seen what Allah has sent down to you of provision of which you have made [some] lawful and [some] unlawful?\" Say, \"Has Allah permitted you [to do so], or do you invent [something] about Allah?\""}, {"ayah": 60, "translit": "Wa maa zannul lazeena yaftaroona 'alal laahil kaziba Yawmal Qiyaamah; innal laaha lazoo fadlin 'alan naasi wa laakinna aksarahum laa yashkuroon", "translation": "And what will be the supposition of those who invent falsehood about Allah on the Day of Resurrection? Indeed, Allah is full of bounty to the people, but most of them are not grateful.\""}, {"ayah": 61, "translit": "Wa  maa takoonu fee shaaninw wa maa tatloo minhu min quraaninw wa laa ta'maloona min 'amalin illaa kunnaa 'alaikum shuhoodan iz tufeedoona feeh; wa maa ya'zubu 'ar Rabbika mim mis qaali zarratin fil ardi wa laa fis samaaa'i wa laaa asghara min zaalika wa laaa akbara illaa fee Kitaabim Mubeen", "translation": "And, [O Muhammad], you are not [engaged] in any matter or recite any of the Qur'an and you [people] do not do any deed except that We are witness over you when you are involved in it. And not absent from your Lord is any [part] of an atom's weight within the earth or within the heaven or [anything] smaller than that or greater but that it is in a clear register."}, {"ayah": 62, "translit": "Alaa innaa awliyaaa'al laahi laa khawfun 'alaihim wa laa hum yahzanoon", "translation": "Unquestionably, [for] the allies of Allah there will be no fear concerning them, nor will they grieve"}, {"ayah": 63, "translit": "Allazeena aamanoo wa kaanoo yattaqoon", "translation": "Those who believed and were fearing Allah"}, {"ayah": 64, "translit": "Lahumul bushraa filha yaatid dunyaa wa fil Aakhirah; laa tabdeela likalimaatil laah; zaalika huwal fawzul 'azeem", "translation": "For them are good tidings in the worldly life and in the Hereafter. No change is there in the words of Allah. That is what is the great attainment."}, {"ayah": 65, "translit": "Wa laa yahzunka qawluhum; innal 'izzata lillaahi jamee'aa; Huwas Samee'ul 'Aleem", "translation": "And let not their speech grieve you. Indeed, honor [due to power] belongs to Allah entirely. He is the Hearing, the Knowing."}, {"ayah": 66, "translit": "Alaaa inna lillaahi man fis samaawaati wa man fil ard; wa maa yattabi'ul lazeena yad'oona min doonil laahi shurakaaa'; iny yattabi'oona illaz zannna wa in hum illaa yakhrusoon", "translation": "Unquestionably, to Allah belongs whoever is in the heavens and whoever is on the earth. And those who invoke other than Allah do not [actually] follow [His] \"partners.\" They follow not except assumption, and they are not but falsifying"}, {"ayah": 67, "translit": "Huwal lazee ja'ala lakumul laila litaskunoo feehi wannahaara mubsiraa; inna fee zaalika la Aayaatil liqawmai yasma'oon", "translation": "It is He who made for you the night to rest therein and the day, giving sight. Indeed in that are signs for a people who listen."}, {"ayah": 68, "translit": "Qaalut takhazal laahu waladan Subhaanahoo Huwal Ghaniyyu lahoo maa fis samaawaati wa maa fil ard; in 'indakum min sultaanim bihaazaaa; ataqooloona 'alal laahi maa laa ta'lamoon", "translation": "They have said, \"Allah has taken a son.\" Exalted is He; He is the [one] Free of need. To Him belongs whatever is in the heavens and whatever is in the earth. You have no authority for this [claim]. Do you say about Allah that which you do not know?"}, {"ayah": 69, "translit": "Qul innal lazeena yaftaroona 'alal laahil kaziba laa yuflihoon", "translation": "Say, \"Indeed, those who invent falsehood about Allah will not succeed.\""}, {"ayah": 70, "translit": "Mataa'un fiddunyaa summa ilainaa marji'uhum summa nuzeequhumul 'azaabash shadeeda bimaa kaanoo yakkfuroon", "translation": "[For them is brief] enjoyment in this world; then to Us is their return; then We will make them taste the severe punishment because they used to disbelieve"}, {"ayah": 71, "translit": "Watlu 'alaihim naba-a-Noohin iz qaala liqawmihee yaa qawmi in kaana kabura 'alaikum maqaamee wa tazkeeree bi Aayaatil laahi fa'alal laahi tawakkaltu fa ajmi'ooo amrakum wa shurakaaa'akum summa laa yakun amrukum 'alaikum ghummatan summmaq dooo ilaiya wa laa tunziroon", "translation": "And recite to them the news of Noah, when he said to his people, \"O my people, if my residence and my reminding of the signs of Allah has become burdensome upon you - then I have relied upon Allah. So resolve upon your plan and [call upon] your associates. Then let not your plan be obscure to you. Then carry it out upon me and do not give me respite."}, {"ayah": 72, "translit": "Fa in tawallaitum famaa sa altukum min ajrin in ajriya illaa 'alal laahi wa umirtu an akoona minal muslimeen", "translation": "And if you turn away [from my advice] then no payment have I asked of you. My reward is only from Allah, and I have been commanded to be of the Muslims.\""}, {"ayah": 73, "translit": "Fakazzaboohu fanajjainaahu wa mamm'ahoo fil fulki wa ja'alnaahum khalaaa'ifa wa aghraqnal lazeena kazzaboo bi aayaatinaa fanzur kaifa kaana 'aaqibatul munzareen", "translation": "And they denied him, so We saved him and those with him in the ship and made them successors, and We drowned those who denied Our signs. Then see how was the end of those who were warned."}, {"ayah": 74, "translit": "Summma ba'asnaa mim ba'dihee Rusulan ilaa qawmihim fajaaa'oohum bilbaiyinaati famaa kaanoo liyu'minoo bimaa kazzaboo bihee min qabl; kazaalika natba'u 'alaa quloobil mu'tadeen", "translation": "Then We sent after him messengers to their peoples, and they came to them with clear proofs. But they were not to believe in that which they had denied before. Thus We seal over the hearts of the transgressors"}, {"ayah": 75, "translit": "Summa ba'asnaa mim ba'dihim Moosaa Wa Haaroona ilaa Fir'awna wa mala'ihee bi aayaatinaa fastakbaroo wa kaanoo qawmam mujrimeen", "translation": "Then We sent after them Moses and Aaron to Pharaoh and his establishment with Our signs, but they behaved arrogantly and were a criminal people"}, {"ayah": 76, "translit": "Falammaa jaaa'ahumul haqqu min 'indinaa qaalooo inna haazaa lasihrum mubeen", "translation": "So when there came to them the truth from Us, they said, \"Indeed, this is obvious magic.\""}, {"ayah": 77, "translit": "Qaalaa Moosaaa ataqooloona lilhaqqi lammmaa jaaa'a kum asihrun haazaa wa laa yuflihus saahiroon", "translation": "Moses said, \"Do you say [thus] about the truth when it has come to you? Is this magic? But magicians will not succeed.\""}, {"ayah": 78, "translit": "Qaaloo aji'tanaa litalfitanaa 'ammaa wajadnaa 'alaihi aabaaa'anaa wa takoona lakumal kibriyaaa'u fil ardi wa maa nahnu lakumaa bimu' mineen", "translation": "They said, \"Have you come to us to turn us away from that upon which we found our fathers and so that you two may have grandeur in the land? And we are not believers in you.\""}, {"ayah": 79, "translit": "Wa qaala Fir'awnu' toonee bikulli saahirin 'aleem", "translation": "And Pharaoh said, \"Bring to me every learned magician.\""}, {"ayah": 80, "translit": "Falammaa jaaa'assa haratu qaala lahum Moosaaa alqoo maaa antum mulqoon", "translation": "So when the magicians came, Moses said to them, \"Throw down whatever you will throw.\""}, {"ayah": 81, "translit": "Falammaaa alqaw qaala Moosaa maa ji'tum bihis sihru innal laaha sa yubtiluhoo innal laaha laa yuslihu 'amalal mufsideen", "translation": "And when they had thrown, Moses said, \"What you have brought is [only] magic. Indeed, Allah will expose its worthlessness. Indeed, Allah does not amend the work of corrupters."}, {"ayah": 82, "translit": "Wa yuhiqqul laahul haqqa bi Kalimaatihee wa law karihal mujrimoon", "translation": "And Allah will establish the truth by His words, even if the criminals dislike it.\""}, {"ayah": 83, "translit": "Famaaa aamana li-Moosaaa illaa zurriyyatum min qawmihee 'alaa khawfim min Fir'awna wa mala'ihim ai yaftinahum; wa inna Fir'awna la'aalin fil ardi wa innahoo laminal musrifeen", "translation": "But no one believed Moses, except [some] youths among his people, for fear of Pharaoh and his establishment that they would persecute them. And indeed, Pharaoh was haughty within the land, and indeed, he was of the transgressors"}, {"ayah": 84, "translit": "Wa qaala Moosaa yaa qawmi in kuntum aamantum billaahi fa'alaihi tawakkalooo in kuntum muslimeen", "translation": "And Moses said, \"O my people, if you have believed in Allah, then rely upon Him, if you should be Muslims.\""}, {"ayah": 85, "translit": "Faqaaloo 'alal laahi tawakkalnaa Rabbanaa laa taj'alnaa fitnatal lilqawmiz zaalimeen", "translation": "So they said, \"Upon Allah do we rely. Our Lord, make us not [objects of] trial for the wrongdoing people"}, {"ayah": 86, "translit": "Wa najjinaa birahmatika minal qawmil kaafireen", "translation": "And save us by Your mercy from the disbelieving people.\""}, {"ayah": 87, "translit": "Wa awhainaaa ilaa Moosaa wa akheehi an tabaw wa aa liqawmikuma bi Misra bu yootanw waj'aloo bu yootakum qiblatanw wa aqeemus Salaah; wa bashshiril mu'mineen", "translation": "And We inspired to Moses and his brother, \"Settle your people in Egypt in houses and make your houses [facing the] qiblah and establish prayer and give good tidings to the believers.\""}, {"ayah": 88, "translit": "Wa qaala Mosaa Rabbanaaa innaka aataita Fir'awna wa mala ahoo zeenatanw wa amwaalan fil hayaatid dunyaa Rabbanaa liyudillo 'ansabeelika Rabbanat mis 'alaaa amwaalihim washdud 'alaa quloobihim falaa yu'minoo hatta yarawul 'azaabal aleem", "translation": "And Moses said, \"Our Lord, indeed You have given Pharaoh and his establishment splendor and wealth in the worldly life, our Lord, that they may lead [men] astray from Your way. Our Lord, obliterate their wealth and harden their hearts so that they will not believe until they see the painful punishment.\""}, {"ayah": 89, "translit": "Qaala qad ujeebad da'watukumaa fastaqeemaa wa laa tattabi'aaanni sabeelal lazeena laaya'lamoon", "translation": "[Allah] said, \"Your supplication has been answered.\" So remain on a right course and follow not the way of those who do not know.\""}, {"ayah": 90, "translit": "Wa jaawaznaa bi Baneee Israaa'eelal bahra fa atba'ahum Fir'awnu wa junooduhoo baghyanw wa 'adwan hattaaa izaaa adrakahul gharaqu qaala aamantu annnahoo laaa ilaaha illal lazeee aamanat bihee Banooo Israaa'eela wa ana minal muslimeen", "translation": "And We took the Children of Israel across the sea, and Pharaoh and his soldiers pursued them in tyranny and enmity until, when drowning overtook him, he said, \"I believe that there is no deity except that in whom the Children of Israel believe, and I am of the Muslims.\""}, {"ayah": 91, "translit": "Aaal'aana wa qad 'asaita qablu wa kunta minal mufsideen", "translation": "Now? And you had disobeyed [Him] before and were of the corrupters?"}, {"ayah": 92, "translit": "Falyawma nunajjeeka bibadanika litakoona liman khalfaka Aayah; wa inna kaseeram minan naasi 'an aayaatinaa laghaafiloon", "translation": "So today We will save you in body that you may be to those who succeed you a sign. And indeed, many among the people, of Our signs, are heedless"}, {"ayah": 93, "translit": "Wa laqad bawwaanaa Baneee Israaa'eela mubawwa-a sidqinw wa razaqnaahum minnat taiyibaati famakh talafoo hattaa jaaa'ahmul 'ilm; inna Rabbaka yaqdee bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon", "translation": "And We had certainty settled the Children of Israel in an agreeable settlement and provided them with good things. And they did not differ until [after] knowledge had come to them. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ"}, {"ayah": 94, "translit": "Fa in kunta fee shakkim mimmaaa anzalnaaa ilaika fas'alil lazeena yaqra'oonal Kitaaba min qablik; laqad jaaa'akal haqqu mir Rabbika falaa takoonanna minal mumtareen", "translation": "So if you are in doubt, [O Muhammad], about that which We have revealed to you, then ask those who have been reading the Scripture before you. The truth has certainly come to you from your Lord, so never be among the doubters."}, {"ayah": 95, "translit": "Wa laa takoonanna minal lazeena kazzaboo bi Aayaatil laahi fatakoona minal khaasireen", "translation": "And never be of those who deny the signs of Allah and [thus] be among the losers."}, {"ayah": 96, "translit": "Innal lazeena haqqat 'alaihim Kalimatu Rabbika laa yu'minoon", "translation": "Indeed, those upon whom the word of your Lord has come into effect will not believe,"}, {"ayah": 97, "translit": "Wa law jaaa'at hum kullu Aayatin hattaa yarawul 'azaabal aleem", "translation": "Even if every sign should come to them, until they see the painful punishment."}, {"ayah": 98, "translit": "Falaw laa kaanat qaryatun aamanat fanafa'ahaaa eemaanuhaaa illaa qawma Yoonusa lammaaa aamanoo kashafnaa 'anhum 'azaabal khizyi fil hayaatid dunyaa wa matta'naahum ilaa heen", "translation": "Then has there not been a [single] city that believed so its faith benefited it except the people of Jonah? When they believed, We removed from them the punishment of disgrace in worldly life and gave them enjoyment for a time."}, {"ayah": 99, "translit": "Wa law shaaa'a Rabbuka la aamana man fil ardi kulluhum jamee'aa; afa anta tukrihun naasa hattaa yakoonoo mu'mineen", "translation": "And had your Lord willed, those on earth would have believed - all of them entirely. Then, [O Muhammad], would you compel the people in order that they become believers?"}, {"ayah": 100, "translit": "Wa maa kaana linafsin an tu'mina illaa bi iznil laah; wa yaj'alur rijsa 'alal lazeena laa ya'qiloon", "translation": "And it is not for a soul to believe except by permission of Allah, and He will place defilement upon those who will not use reason."}, {"ayah": 101, "translit": "Qulin zuroo maazaa fissamaawaati wal ard; wa maa tughnil Aayaatu wannuzuru 'an qawmil laa yu'minoon", "translation": "Say, \"Observe what is in the heavens and earth.\" But of no avail will be signs or warners to a people who do not believe"}, {"ayah": 102, "translit": "Fahal yantaziroona illaa misla ayyaamil lazeena khalaw min qablihim; qul fantazirooo innee ma'akum minal muntazireen", "translation": "So do they wait except for like [what occurred in] the days of those who passed on before them? Say, \"Then wait; indeed, I am with you among those who wait.\""}, {"ayah": 103, "translit": "Summma nunajjee Ruslanaa wallazeena aamanoo; kazaalika haqqan 'alainaa nunjil mu'mineen", "translation": "Then We will save our messengers and those who have believed. Thus, it is an obligation upon Us that We save the believers"}, {"ayah": 104, "translit": "Qul yaaa ayyuhan naasu in kuntum fee shakkkim min deenee falaa a'budul lazeena ta'budoona min doonil laahi wa laakin a'budul laahal lazee yatawaffaakum wa umirtu an akoona minal mu'mineen", "translation": "Say, [O Muhammad], \"O people, if you are in doubt as to my religion - then I do not worship those which you worship besides Allah; but I worship Allah, who causes your death. And I have been commanded to be of the believers"}, {"ayah": 105, "translit": "Wa an aqim wajhaka liddeeni Haneefanw wa laa takoonannna minal mushrikeen", "translation": "And [commanded], 'Direct your face toward the religion, inclining to truth, and never be of those who associate others with Allah;"}, {"ayah": 106, "translit": "Wa laa tad'u min doonil laahi maa laa yanfa'uka wa laa yadurruka fa in fa'alta fa innaka izam minaz zaalimeen", "translation": "And do not invoke besides Allah that which neither benefits you nor harms you, for if you did, then indeed you would be of the wrongdoers.'\""}, {"ayah": 107, "translit": "Wa iny yamsaskal laahu bidurrin falaa kaashifa lahoo illaa Huwa wa iny yuridka bikhairin falaa raaadda lifadlih; yuseebu bihee man yashaaa'u min 'ibaadih; wa huwal Ghafoorur Raheem", "translation": "And if Allah should touch you with adversity, there is no remover of it except Him; and if He intends for you good, then there is no repeller of His bounty. He causes it to reach whom He wills of His servants. And He is the Forgiving, the Merciful"}, {"ayah": 108, "translit": "Qul yaaa aiyuhan naasu qad jaaa'akumul haqqu mir Rabbikum famanih tadaa fa innamaa yahtadee linafsihee wa man dalla fa innamaa yadillu 'alaihaa wa maaa ana 'alaikum biwakeel", "translation": "Say, \"O mankind, the truth has come to you from your Lord, so whoever is guided is only guided for [the benefit of] his soul, and whoever goes astray only goes astray [in violation] against it. And I am not over you a manager.\""}, {"ayah": 109, "translit": "Wattabi' maa yoohaaa ilaika wasbir hattaa yahkumal laah; wa Huwa khairul haakimeen", "translation": "And follow what is revealed to you, [O Muhammad], and be patient until Allah will judge. And He is the best of judges."}]}, {"num": 11, "name": "Hud", "meaning": "Hud", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Raa; Kitaabun uhkimat Aayaatuhoo summa fussilat mil ladun Hakeemin Khabeer", "translation": "Alif, Lam, Ra. [This is] a Book whose verses are perfected and then presented in detail from [one who is] Wise and Acquainted."}, {"ayah": 2, "translit": "Allaa ta'budooo illal laah; innanee lakum minhu nazeerunw wa basheer", "translation": "[Through a messenger, saying], \"Do not worship except Allah. Indeed, I am to you from Him a warner and a bringer of good tidings,\""}, {"ayah": 3, "translit": "Wa anis taghfiroo Rabbakum summa toobooo ilaihi yumatti'kum mataa'an hasanan ilaaa ajalim musammanw wa yu'ti kulla zee fadlin fadlahoo wa in tawallaw fa inneee akhaafu 'alaikum 'azaaba Yawmin Kabeer", "translation": "And [saying], \"Seek forgiveness of your Lord and repent to Him, [and] He will let you enjoy a good provision for a specified term and give every doer of favor his favor. But if you turn away, then indeed, I fear for you the punishment of a great Day."}, {"ayah": 4, "translit": "Ilal laahi marji'ukum wa Huwa 'alaa kulli shai'in Qadeer", "translation": "To Allah is your return, and He is over all things competent.\""}, {"ayah": 5, "translit": "Alaa innahum yasnoona sudoorahum liyastakhfoo minh; alaa heena yastaghshoona siyaabahum ya'lamu maa yusiroona wa maa yu'linoon; innahoo 'aleemum bizaatis sudoor", "translation": "Unquestionably, they the disbelievers turn away their breasts to hide themselves from Him. Unquestionably, [even] when they cover themselves in their clothing, Allah knows what they conceal and what they declare. Indeed, He is Knowing of that within the breasts."}, {"ayah": 6, "translit": "Wa maa min daaabbatin fil ardi illaa 'alal laahi rizquhaa wa ya'lamu mustaqarrahaa wa mustawda'ahaa; kullun fee Kitaabim Mubeen", "translation": "And there is no creature on earth but that upon Allah is its provision, and He knows its place of dwelling and place of storage. All is in a clear register."}, {"ayah": 7, "translit": "Wa Huwal lazee khalaqas samaawaati wal alrda fee sittati aiyaaminw wa kaana 'Arshuhoo alal maaa'i liyablu wakum aiyukum ahsanu 'amalaa; wa la'in qulta innakum mab'oosoona mim ba'dil mawti la yaqoolanal lazeena kafaroo in haazaaa illaa sihrum mubeen", "translation": "And it is He who created the heavens and the earth in six days - and His Throne had been upon water - that He might test you as to which of you is best in deed. But if you say, \"Indeed, you are resurrected after death,\" those who disbelieve will surely say, \"This is not but obvious magic.\""}, {"ayah": 8, "translit": "Wala'in akhkharnaa 'anhumul 'azaaba ilaaa ummatim ma'doodatil la yaqoolunna maa yahbisuh; alaa yawma yaateehim laisa masroofan 'anhum wa haaqa bihim maa kaanoo bihee yastahzi'oon", "translation": "And if We hold back from them the punishment for a limited time, they will surely say, \"What detains it?\" Unquestionably, on the Day it comes to them, it will not be averted from them, and they will be enveloped by what they used to ridicule."}, {"ayah": 9, "translit": "Wa la'in azaqnal insaana minnaa rahmatan summa naza'naahaa minhu, innahoo laya'oosun kafoor", "translation": "And if We give man a taste of mercy from Us and then We withdraw it from him, indeed, he is despairing and ungrateful."}, {"ayah": 10, "translit": "Wala'in azaqnaahu na'maaa'a ba'da darraaa'a massat hu la yaqoolanna zahabas saiyiaatu 'anneee; innahoo lafarihun fakhoor", "translation": "But if We give him a taste of favor after hardship has touched him, he will surely say, \"Bad times have left me.\" Indeed, he is exultant and boastful -"}, {"ayah": 11, "translit": "Illal lazeena sabaroo wa 'amilus saalihaati ulaaa'ika lahum maghfiratunw wa ajrun kabeer", "translation": "Except for those who are patient and do righteous deeds; those will have forgiveness and great reward."}, {"ayah": 12, "translit": "Fala'allaka taarikum ba'da maa yoohaaa ilaika wa daaa'iqum bihee sadruka ai yaqooloo law laaa unzila 'alaihi kanzun aw jaaa'a ma'ahoo malak; innamaa anta nazeer; wallaahu 'alaa kulli shai'inw wakeel", "translation": "Then would you possibly leave [out] some of what is revealed to you, or is your breast constrained by it because they say, \"Why has there not been sent down to him a treasure or come with him an angel?\" But you are only a warner. And Allah is Disposer of all things."}, {"ayah": 13, "translit": "Am yaqooloonaf taraahu qul faatoo bi'ashri Suwarim mislihee muftarayaatinw wad'oo manis tata'tum min doonil laahi in kuntum saadiqeen", "translation": "Or do they say, \"He invented it\"? Say, \"Then bring ten surahs like it that have been invented and call upon [for assistance] whomever you can besides Allah, if you should be truthful.\""}, {"ayah": 14, "translit": "Fa il lam yastajeeboo lakum fa'lamooo annamaaa unzilla bi'ilmil laahi wa al laaa ilaaha illaa Huwa fahal antum muslimoon", "translation": "And if they do not respond to you - then know that the Qur'an was revealed with the knowledge of Allah and that there is no deity except Him. Then, would you [not] be Muslims?"}, {"ayah": 15, "translit": "Man kaana yureedul hayaatad dunyaa zeenatahaa nuwaffi ilaihim a'maa lahum feehaa wa hum feehaa laa yubkhasoon", "translation": "Whoever desires the life of this world and its adornments - We fully repay them for their deeds therein, and they therein will not be deprived."}, {"ayah": 16, "translit": "Ulaaa'ikal lazeena laisa lahum fil Aakhirati illan Naaru wa habita maa sana'oo feehaa wa baatilum maa kaanoo ya'maloon", "translation": "Those are the ones for whom there is not in the Hereafter but the Fire. And lost is what they did therein, and worthless is what they used to do."}, {"ayah": 17, "translit": "Afaman kaana 'alas baiyinatim mir Rabbihee wa yatloohu shaahidum minhu wa min qablihee Kitaabu Moosaaa imaamanw wa rahmah; ulaaa 'ika yu'minoona bih; wa mai yakfur bihee minal Ahzaabi fan Naaru maw'iduh; falaa taku fee miryatim minh; innahul haqqu mir Rabbika wa laakinna aksaran naasi laa yu'minoon", "translation": "So is one who [stands] upon a clear evidence from his Lord [like the aforementioned]? And a witness from Him follows it, and before it was the Scripture of Moses to lead and as mercy. Those [believers in the former revelations] believe in the Qur'an. But whoever disbelieves in it from the [various] factions - the Fire is his promised destination. So be not in doubt about it. Indeed, it is the truth from your Lord, but most of the people do not believe."}, {"ayah": 18, "translit": "Wa man azlamu mimmanif taraa 'alal laahi kazibaa; ulaaa'ika yu'radoona 'alaa Rabbihim wa yaqoolul ashhaa duhaaa'ulaaa'il lazeena kazaboo 'alaa Rabbihim; alaa la'natul laahi alaz zaalimeen", "translation": "And who is more unjust than he who invents a lie about Allah? Those will be presented before their Lord, and the witnesses will say, \"These are the ones who lied against their Lord.\" Unquestionably, the curse of Allah is upon the wrongdoers."}, {"ayah": 19, "translit": "Allazeena yasuddoona 'an sabeelil laahi wa yabghoonahaa 'iwajanw wa hum bil Aakhiratihum kaafiroon", "translation": "Who averted [people] from the way of Allah and sought to make it [seem] deviant while they, concerning the Hereafter, were disbelievers."}, {"ayah": 20, "translit": "Ulaaa'ika lam yakoonoo mu'jizeena fil ardi wa maa kaana lahum min doonil laahi min awliyaaa'; yudaa'afu lahumul 'azaab; maa kaanoo yastatee'oonas sam'a wa maa kaanoo yubsiroon", "translation": "Those were not causing failure [to Allah] on earth, nor did they have besides Allah any protectors. For them the punishment will be multiplied. They were not able to hear, nor did they see."}, {"ayah": 21, "translit": "Ulaaa'ikal lazeena khasirooo anfusahum wa dalla 'anhum maa kaanoo yaftaroon", "translation": "Those are the ones who will have lost themselves, and lost from them is what they used to invent."}, {"ayah": 22, "translit": "Laa jarama annahum fil Aakhirati humul akhsaroon", "translation": "Assuredly, it is they in the Hereafter who will be the greatest losers."}, {"ayah": 23, "translit": "Innal lazeena aamanoo wa 'amilus saalihaati wa akhbatooo ilaa Rabbihim ulaaa'ika Ashaabul Jannati hum feehaa khaalidoon", "translation": "Indeed, they who have believed and done righteous deeds and humbled themselves to their Lord - those are the companions of Paradise; they will abide eternally therein."}, {"ayah": 24, "translit": "Masalul fareeqini kal a'maa wal asammi walbaseeri wassamee'; hal yastawiyaani masalaa; afalaa tazakkaroon", "translation": "The example of the two parties is like the blind and deaf, and the seeing and hearing. Are they equal in comparison? Then, will you not remember?"}, {"ayah": 25, "translit": "Wa laqad arsalnaa Noohan ilaa qawmihee innee lakum nazeerum mubeen", "translation": "And We had certainly sent Noah to his people, [saying], \"Indeed, I am to you a clear warner"}, {"ayah": 26, "translit": "Al laa ta'budooo illal laaha inneee akhaafu 'alaikum 'azaaba Yawmin aleem", "translation": "That you not worship except Allah. Indeed, I fear for you the punishment of a painful day.\""}, {"ayah": 27, "translit": "Faqaalal mala ul lazeena kafaroo min qawmihee ma naraaka illaa basharam mislanaa wa maa naraakat taba'aka illal lazeena hum araazilunaa baadiyar raayi wa maa naraa lakum 'alainaa min fadlim bal nazunnukum kaazibeen", "translation": "So the eminent among those who disbelieved from his people said, \"We do not see you but as a man like ourselves, and we do not see you followed except by those who are the lowest of us [and] at first suggestion. And we do not see in you over us any merit; rather, we think you are liars.\""}, {"ayah": 28, "translit": "Qaala yaa qawmi ara'aitum in kuntu 'alaa baiyinatim mir Rabbee wa aataanee rahmatam min 'indihee fa'um miyat 'alaikum anulzimuku moohaa wa antum lahaa kaarihoon", "translation": "He said, \"O my people have you considered: if I should be upon clear evidence from my Lord while He has given me mercy from Himself but it has been made unapparent to you, should we force it upon you while you are averse to it?"}, {"ayah": 29, "translit": "Wa yaa qawmi laaa as'alukum 'alaihi maalan in ajriya illaa 'alal laah; wa maaa ana bitaaridil lazeena aamanoo; innahum mulaaqoo Rabbihim wa laakinneee araakum qawman tajhaloon", "translation": "And O my people, I ask not of you for it any wealth. My reward is not but from Allah. And I am not one to drive away those who have believed. Indeed, they will meet their Lord, but I see that you are a people behaving ignorantly."}, {"ayah": 30, "translit": "Wa yaa qawmi mai yansurunee minal laahi in tarattuhum; afalaa tazak karoon", "translation": "And O my people, who would protect me from Allah if I drove them away? Then will you not be reminded?"}, {"ayah": 31, "translit": "Wa laa aqoolu lakum 'indee khazaa'inul laahi wa laaa a'lamul ghaiba wa laa aqoolu inee malakunw wa laaa aqoolu lillazeena tazdareee a'yunukum lai yu'tiyahumul laahu khairan Allaahu a'lamu bimaa feee anfusihim innee izal laminaz zaalimeen", "translation": "And I do not tell you that I have the depositories [containing the provision] of Allah or that I know the unseen, nor do I tell you that I am an angel, nor do I say of those upon whom your eyes look down that Allah will never grant them any good. Allah is most knowing of what is within their souls. Indeed, I would then be among the wrongdoers.\""}, {"ayah": 32, "translit": "Qaaloo yaa Noohu qad jaadaltanaa fa aksarta jidaalanaa faatinaa bimaa ta'idunaaa in kunta minas saadiqeen", "translation": "They said, \"O Noah, you have disputed us and been frequent in dispute of us. So bring us what you threaten us, if you should be of the truthful.\""}, {"ayah": 33, "translit": "Qaala innamaa yaateekum bihil laahu in shaaa'a wa maaa antum bimu'jizeen", "translation": "He said, \"Allah will only bring it to you if He wills, and you will not cause [Him] failure."}, {"ayah": 34, "translit": "Wa laa yanfa'ukum nusheee in arattu an ansaha lakum in kaanal laahu yureedu ai yughwi yakum; Huwa Rabbukum wa ilaihi turja'oon", "translation": "And my advice will not benefit you - although I wished to advise you - If Allah should intend to put you in error. He is your Lord, and to Him you will be returned.\""}, {"ayah": 35, "translit": "Am yaqooloonaf taraahu qul inif taraituhoo fa'alaiya ijraamee wa ana bareee'um mimmaa tujrimoon", "translation": "Or do they say [about Prophet Muhammad], \"He invented it\"? Say, \"If I have invented it, then upon me is [the consequence of] my crime; but I am innocent of what [crimes] you commit.\""}, {"ayah": 36, "translit": "Wa oohiya ilaa Noohin annahoo lany-yu'mina min qawmika illaa man qad aamana falaa tabta'is bimaa kaanoo yaf'aloon", "translation": "And it was revealed to Noah that, \"No one will believe from your people except those who have already believed, so do not be distressed by what they have been doing."}, {"ayah": 37, "translit": "Wasna'il fulka bi-a'yuninaa wa wahyinaa wa laa tukhaa tibnee fil lazeena zalamoo; innahum mughraqoon", "translation": "And construct the ship under Our observation and Our inspiration and do not address Me concerning those who have wronged; indeed, they are [to be] drowned.\""}, {"ayah": 38, "translit": "Wa yasn'ul fulka wa kullamaa marra 'alaihi malaum min qawmihee sakhiroo minh; qaala in taskharoo minnaa fa innaa naskharu minkum kamaa taskharoon", "translation": "And he constructed the ship, and whenever an assembly of the eminent of his people passed by him, they ridiculed him. He said, \"If you ridicule us, then we will ridicule you just as you ridicule."}, {"ayah": 39, "translit": "Fasawfa ta'lamoona mai yaateehi 'azaabuny yaukhzeehi wa yahillu 'alaihi 'azaabum muqeem", "translation": "And you are going to know who will get a punishment that will disgrace him [on earth] and upon whom will descend an enduring punishment [in the Hereafter].\""}, {"ayah": 40, "translit": "Hattaaa izaa jaaa'a amrunaa wa faarat tannooru qulnah mil feehaa min kullin zawjainis naini wa ahlaka illaa man sabaqa 'alaihil qawlu wa man aaman; wa maaa aamana ma'ahooo illaa qaleel", "translation": "[So it was], until when Our command came and the oven overflowed, We said, \"Load upon the ship of each [creature] two mates and your family, except those about whom the word has preceded, and [include] whoever has believed.\" But none had believed with him, except a few."}, {"ayah": 41, "translit": "Wa qaalar kaboo feehaa bismil laahi majraihaa wa mursaahaa; inna Rabbee la Ghafoorur Raheem", "translation": "And [Noah] said, \"Embark therein; in the name of Allah is its course and its anchorage. Indeed, my Lord is Forgiving and Merciful.\""}, {"ayah": 42, "translit": "Wa hiya tajree bihim fee mawjin kaljibaali wa naadaa Noohunib nahoo wa kaana fee ma'ziliny yaa bunai yarkam ma'anaa wa laa takum ma'al kaafireen", "translation": "And it sailed with them through waves like mountains, and Noah called to his son who was apart [from them], \"O my son, come aboard with us and be not with the disbelievers.\""}, {"ayah": 43, "translit": "Qaala sa aaweee ilaa jabaliny ya'simunee minal maaa'; qaala laa 'aasimal yawma min amril laahi illaa mar rahim; wa haala bainahumal mawju fakaana minal mughraqeen", "translation": "[But] he said, \"I will take refuge on a mountain to protect me from the water.\" [Noah] said, \"There is no protector today from the decree of Allah, except for whom He gives mercy.\" And the waves came between them, and he was among the drowned."}, {"ayah": 44, "translit": "Wa qeela yaaa ardubla'ee maaa'aki wa yaa samaaa'u aqi'ee wa gheedal maaa'u wa qudiyal amru wastawat 'alal joodiyyi wa qeela bu'dal lilqawmiz zaalimeen", "translation": "And it was said, \"O earth, swallow your water, and O sky, withhold [your rain].\" And the water subsided, and the matter was accomplished, and the ship came to rest on the [mountain of] Judiyy. And it was said, \"Away with the wrongdoing people.\""}, {"ayah": 45, "translit": "Wa naadaa noohur Rabbahoo faqaala Rabbi innabnee min ahlee wa inna wa'dakal haqqu wa Anta ahkamul haakimeen", "translation": "And Noah called to his Lord and said, \"My Lord, indeed my son is of my family; and indeed, Your promise is true; and You are the most just of judges!\""}, {"ayah": 46, "translit": "Qaala yaa Noohu innahoo laisa min ahlika innahoo 'amalun ghairu saalihin falaa tas'alni mmaa laisa laka bihee 'ilmun inneee a'izuka an takoona minal jaahileen", "translation": "He said, \"O Noah, indeed he is not of your family; indeed, he is [one whose] work was other than righteous, so ask Me not for that about which you have no knowledge. Indeed, I advise you, lest you be among the ignorant.\""}, {"ayah": 47, "translit": "Qaala rabbi inneee a'oozu bika an as'alaka maa laisa lee bihee 'ilmunw wa illaa taghfir lee wa tarhamneee akum minal khaasireen", "translation": "[Noah] said, \"My Lord, I seek refuge in You from asking that of which I have no knowledge. And unless You forgive me and have mercy upon me, I will be among the losers.\""}, {"ayah": 48, "translit": "Qeela yaa Noohuh bit bisalaamim minnaa wa barakaatin 'alaika wa 'alaaa umamim mimmam ma'ak; wa umamun sanumatti'uhum summa yamassuhum minaa 'azaabun aleem", "translation": "It was said, \"O Noah, disembark in security from Us and blessings upon you and upon nations [descending] from those with you. But other nations [of them] We will grant enjoyment; then there will touch them from Us a painful punishment.\""}, {"ayah": 49, "translit": "Tilka min ambaaa'il ghaibi nooheehaaa ilaika maa kunta ta'lamuhaaaa anta wa laa qawmuka min qabli haazaa fasbir innal 'aaqibata lilmuttaqeen (section 4)", "translation": "That is from the news of the unseen which We reveal to you, [O Muhammad]. You knew it not, neither you nor your people, before this. So be patient; indeed, the [best] outcome is for the righteous."}, {"ayah": 50, "translit": "Wa ilaa 'aadin akhaahum Hoodaa; qaala yaa qawmi' budul laaha maa lakum min ilaahin ghairuhooo in antum illaa muftaroon", "translation": "And to 'Aad [We sent] their brother Hud. He said, \"O my people, worship Allah; you have no deity other than Him. You are not but inventors [of falsehood]."}, {"ayah": 51, "translit": "Yaa qawmi laaa as'alukum 'alaihi ajran in ajriya illaa 'alal lazee fataranee; afalaa ta'qiloon", "translation": "O my people, I do not ask you for it any reward. My reward is only from the one who created me. Then will you not reason?"}, {"ayah": 52, "translit": "Wa yaa qawmis taghfiroo Rabbakum summa toobooo ilaihi yursilis samaaa'a 'alaikum midraaranw wa yazidkum quwwatan ilaa quwwatikum wa laa tatawallaw mujrimeen", "translation": "And O my people, ask forgiveness of your Lord and then repent to Him. He will send [rain from] the sky upon you in showers and increase you in strength [added] to your strength. And do not turn away, [being] criminals.\""}, {"ayah": 53, "translit": "Qaaloo yaa Hoodu maa ji'tanaa bibaiyinatinw wa maa nahnu bitaarikeee aalihatinaa 'an qawlika wa maa nahnu laka bimu'mineen", "translation": "They said, \"O Hud, you have not brought us clear evidence, and we are not ones to leave our gods on your say-so. Nor are we believers in you."}, {"ayah": 54, "translit": "In naqoolu illa' taraaka ba'du aalihatinaa bisooo'; qaala inneee ushhidul laaha wash hadooo annee bareee'um mimmaa tushrikoon", "translation": "We only say that some of our gods have possessed you with evil.\" He said, \"Indeed, I call Allah to witness, and witness [yourselves] that I am free from whatever you associate with Allah"}, {"ayah": 55, "translit": "Min doonihee fakeedoonee jamee'an summa laa tunziroon", "translation": "Other than Him. So plot against me all together; then do not give me respite."}, {"ayah": 56, "translit": "Innee tawakkaltu 'alallaahi Rabbee wa Rabbikum; maa min daaabbatin illaa Huwa aakhizum binaasiyatihaa; inna Rabbee 'alaa Siraatim mustaqeem", "translation": "Indeed, I have relied upon Allah, my Lord and your Lord. There is no creature but that He holds its forelock. Indeed, my Lord is on a path [that is] straight.\""}, {"ayah": 57, "translit": "Fa in tawallaw faqad ablaghtukum maaa ursiltu biheee ilaikum; wa yastakhlifu Rabbee qawman ghairakum wa laa tadur roonahoo shai'aa; inna Rabbee 'alaa kulli shai'in Hafeez", "translation": "But if they turn away, [say], \"I have already conveyed that with which I was sent to you. My Lord will give succession to a people other than you, and you will not harm Him at all. Indeed my Lord is, over all things, Guardian.\""}, {"ayah": 58, "translit": "Wa lammaa jaaa'a amrunaa najainaa Hoodanw wallazeena aamanoo ma'ahoo birahmatim minnaa wa najainaahum min 'azaabin ghaleez", "translation": "And when Our command came, We saved Hud and those who believed with him, by mercy from Us; and We saved them from a harsh punishment."}, {"ayah": 59, "translit": "Wa tilka 'aad, jahadoo bi Aayaati Rabbihim wa 'asaw Rusulahoo wattaba'ooo amra kulli jabbaarin 'aneed", "translation": "And that was 'Aad, who rejected the signs of their Lord and disobeyed His messengers and followed the order of every obstinate tyrant."}, {"ayah": 60, "translit": "Wa utbi'oo fee haazihid dunyaa la'natanw wa Yawmal Qiyaamah; alaaa inna 'Aadan kafaroo Rabbahum; alaa bu'dal li 'Aadin qawmin Hood", "translation": "And they were [therefore] followed in this world with a curse and [as well] on the Day of Resurrection. Unquestionably, 'Aad denied their Lord; then away with 'Aad, the people of Hud."}, {"ayah": 61, "translit": "Wa ilaa Samooda akhaahum Saalihaa; qaala yaa qawmi' budul laaha maa lakum min ilaahim ghairuhoo Huwa ansha akum minal ardi wasta' marakum feehaa fastaghfiroohu summa toobooo ilaih; inna Rabbee Qareebum Mujeeb", "translation": "And to Thamud [We sent] their brother Salih. He said, \"O my people, worship Allah; you have no deity other than Him. He has produced you from the earth and settled you in it, so ask forgiveness of Him and then repent to Him. Indeed, my Lord is near and responsive.\""}, {"ayah": 62, "translit": "Qaaloo yaa Saalihu qad kunta feenaa marjuwwan qabla haazaaa atanhaanaaa an na'bu da maa ya'budu aabaaa'unaa wa innanaa lafee shakkim mimmaa tad'oonaaa ilaihi mureeb", "translation": "They said, \"O Salih, you were among us a man of promise before this. Do you forbid us to worship what our fathers worshipped? And indeed we are, about that to which you invite us, in disquieting doubt.\""}, {"ayah": 63, "translit": "Qaala yaa qawmi ara'aytum in kuntu 'alaa baiyinatim mir Rabbee wa aataanee minhu rahmatan famai yansurunee minal laahi in 'asaituhoo famaa tazeedoonanee ghaira takhseer", "translation": "He said, \"O my people, have you considered: if I should be upon clear evidence from my Lord and He has given me mercy from Himself, who would protect me from Allah if I disobeyed Him? So you would not increase me except in loss."}, {"ayah": 64, "translit": "Wa yaa qawmi haazihee naaqatul laahi lakum aayatan fazaroohaa taakul feee ardil laahi wa laa tamassoohaa bisooo'in fa yaakhuzakum azaabun qareeb", "translation": "And O my people, this is the she-camel of Allah - [she is] to you a sign. So let her feed upon Allah 's earth and do not touch her with harm, or you will be taken by an impending punishment.\""}, {"ayah": 65, "translit": "Fa 'aqaroohaa faqaala tamatta'oo fee daarikum salaasata aiyaamin zaalika wa'dun ghairu makzoob", "translation": "But they hamstrung her, so he said, \"Enjoy yourselves in your homes for three days. That is a promise not to be denied.\""}, {"ayah": 66, "translit": "Falammaa jaaa'a amrunaa najjainaa Saalihanw wal lazeena aamanoo ma'ahoo birahmatim minnaa wa min khizyi Yawmi'iz inna Rabbaka Huwal Qawiyyul 'Azeez", "translation": "So when Our command came, We saved Salih and those who believed with him, by mercy from Us, and [saved them] from the disgrace of that day. Indeed, it is your Lord who is the Powerful, the Exalted in Might."}, {"ayah": 67, "translit": "Wa akhazal lazeena zalamus saihatu fa asbahoo fee diyaarihim jaasimeena", "translation": "And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone"}, {"ayah": 68, "translit": "Ka al lam yaghnaw feehaaa; alaaa inna Samooda kafaroo Rabbahum; alaa bu'dal li Samood.", "translation": "As if they had never prospered therein. Unquestionably, Thamud denied their Lord; then, away with Thamud."}, {"ayah": 69, "translit": "Wa laqad jaaa'at Rusulunaaa Ibraaheema bilbushraa qaaloo salaaman qaala salaamun famaa labisa an jaaa'a bi'ijin haneez", "translation": "And certainly did Our messengers come to Abraham with good tidings; they said, \"Peace.\" He said, \"Peace,\" and did not delay in bringing [them] a roasted calf."}, {"ayah": 70, "translit": "Falammaa ra aaa aidiyahum laa tasilu ilaihi nakirahum wa awjasa minhum kheefah; qaaloo la takhaf innaaa ursilnaaa ilaa qawmi Loot", "translation": "But when he saw their hands not reaching for it, he distrusted them and felt from them apprehension. They said, \"Fear not. We have been sent to the people of Lot.\""}, {"ayah": 71, "translit": "Wamra atuhoo qaaa'imatun fadahikat fabashsharnaahaa bi Ishaaqa wa minw waraaa'i Ishaaqa Ya'qoob", "translation": "And his Wife was standing, and she smiled. Then We gave her good tidings of Isaac and after Isaac, Jacob."}, {"ayah": 72, "translit": "Qaalat yaa wailataaa 'aalidu wa ana 'ajoozunw wa haaza ba'lee shaikhan inna haazaa lashai'un 'ajeeb", "translation": "She said, \"Woe to me! Shall I give birth while I am an old woman and this, my husband, is an old man? Indeed, this is an amazing thing!\""}, {"ayah": 73, "translit": "Qaalooo ata'jabeena min amril laahi rahmatul laahi wa barakaatuho 'alaikum Ahlal Bayt; innahoo Hameedum Majeed", "translation": "They said, \"Are you amazed at the decree of Allah? May the mercy of Allah and His blessings be upon you, people of the house. Indeed, He is Praiseworthy and Honorable.\""}, {"ayah": 74, "translit": "Falammaa zahaba an Ibraaheemar raw'u wa jaaa'at hul bushraaa yujaadilunaa fee qawmi Loot", "translation": "And when the fright had left Abraham and the good tidings had reached him, he began to argue with Us concerning the people of Lot."}, {"ayah": 75, "translit": "Inna Ibraaheema lahaleemun awwwaahum muneeb", "translation": "Indeed, Abraham was forbearing, grieving and [frequently] returning [to Allah]."}, {"ayah": 76, "translit": "Yaaa Ibraaheemu a'rid 'an haazaaa innahoo qad jaaa'a amru Rabbika wa innahum aateehim 'azaabun ghairun mardood", "translation": "[The angels said], \"O Abraham, give up this [plea]. Indeed, the command of your Lord has come, and indeed, there will reach them a punishment that cannot be repelled.\""}, {"ayah": 77, "translit": "Wa lammaa jaaa'at Rusulunaa Lootan seee'a bihim wa daaqa bihim zar'anw wa qaala haazaa yawmun 'aseeb", "translation": "And when Our messengers, [the angels], came to Lot, he was anguished for them and felt for them great discomfort and said, \"This is a trying day.\""}, {"ayah": 78, "translit": "Wa jaaa'ahoo qawmuhoo yuhra'oona ilaihi wa min qablu kaanoo ya'maloonas saiyiaat; qaala yaa qawmi haaa'ulaaa'i banaatee hunna atharu lakum fattaqul laaha wa laa tukhzooni fee daifee alaisa minkum rajulur rasheed", "translation": "And his people came hastening to him, and before [this] they had been doing evil deeds. He said, \"O my people, these are my daughters; they are purer for you. So fear Allah and do not disgrace me concerning my guests. Is there not among you a man of reason?\""}, {"ayah": 79, "translit": "Qaaloo laqad 'alimta maa lanaa fee banastika min haqq, wa innaka lata'lamu maa nureed", "translation": "They said, \"You have already known that we have not concerning your daughters any claim, and indeed, you know what we want.\""}, {"ayah": 80, "translit": "Qaala law anna lee bikum quwwatan aw aaweee ilaa ruknin shadeed", "translation": "He said, \"If only I had against you some power or could take refuge in a strong support.\""}, {"ayah": 81, "translit": "Qaaloo yaa Lootu innaa Rusulu Rabbika lai yasiloo ilaika fa asri bi ahlika biqit 'im minal laili wa laa yaltafit minkum ahadun illam ra ataka innahoo museebuhaa maaa asaabahum; inna maw'i dahumus subh; alaisas subhu biqareeb", "translation": "The angels said, \"O Lot, indeed we are messengers of your Lord; [therefore], they will never reach you. So set out with your family during a portion of the night and let not any among you look back - except your wife; indeed, she will be struck by that which strikes them. Indeed, their appointment is [for] the morning. Is not the morning near?\""}, {"ayah": 82, "translit": "Falammaa jaaa'a amrunaa ja'alnaa 'aaliyahaa saafilahaa wa amtamaa 'alaihaa hijaaratam min sijjeelim mandood", "translation": "So when Our command came, We made the highest part [of the city] its lowest and rained upon them stones of layered hard clay, [which were]"}, {"ayah": 83, "translit": "Musawwamatan 'inda Rabbik; wa maa hiya minaz zaalimena biba'eed (section 7)", "translation": "Marked from your Lord. And Allah 's punishment is not from the wrongdoers [very] far."}, {"ayah": 84, "translit": "Wa ilaa Madyana akhaahum Shu'aibaa; qaala yaa qawmi' budul laaha maa lakum min ilaahin ghairuhoo wa laa tanqusul mikyaala walmeezaan; inneee araakum bikhairinw wa innee akhaafu 'alaikum 'azaaba Yawmim muheet", "translation": "And to Madyan [We sent] their brother Shu'ayb. He said, \"O my people, worship Allah; you have no deity other than Him. And do not decrease from the measure and the scale. Indeed, I see you in prosperity, but indeed, I fear for you the punishment of an all-encompassing Day."}, {"ayah": 85, "translit": "Wa yaa qawmi awful mikyaala walmeezaana bilqisti wa laa tabkhasun naasa ashyaaa'ahum wa laa ta'saw fil ardi mufsideen", "translation": "And O my people, give full measure and weight in justice and do not deprive the people of their due and do not commit abuse on the earth, spreading corruption."}, {"ayah": 86, "translit": "Baqiyyatul laahi khairul lakum in kuntum mu'mineen; wa maa ana 'alaikum bihafeez", "translation": "What remains [lawful] from Allah is best for you, if you would be believers. But I am not a guardian over you.\""}, {"ayah": 87, "translit": "Qaaloo yaa Shu'aybu asalaatuka taamuruka an natruka maa ya'budu aabaaa'unaaa aw an naf'ala feee amwaalinaa maa nashaaa'oo innaka la antal haleemur rasheed", "translation": "They said, \"O Shu'ayb, does your prayer command you that we should leave what our fathers worship or not do with our wealth what we please? Indeed, you are the forbearing, the discerning!\""}, {"ayah": 88, "translit": "Qaala yaa qawmi ara'aitum in kuntu 'alaa baiyinatim mir Rabbee wa razaqanee minhu rizqan hasanaa; wa maaa ureedu an ukhaalifakum ilaa maaa anhaakum 'anh; in ureedu illal islaaha mastata't; wa maa tawfeeqeee illaa billaah; 'alaihi tawakkaltu wa ilaihi uneeb", "translation": "He said, \"O my people, have you considered: if I am upon clear evidence from my Lord and He has provided me with a good provision from Him...? And I do not intend to differ from you in that which I have forbidden you; I only intend reform as much as I am able. And my success is not but through Allah. Upon him I have relied, and to Him I return."}, {"ayah": 89, "translit": "Wa yaa qawmi laa yajri mannakum shiqaaqeee ai yuseebakum mislu maaa asaaba qawma Noohin aw qawma Hoodin aw qawma Saalih; wa maa qawmu Lootim minkum biba'eed", "translation": "And O my people, let not [your] dissension from me cause you to be struck by that similar to what struck the people of Noah or the people of Hud or the people of Salih. And the people of Lot are not from you far away."}, {"ayah": 90, "translit": "Wastaghfiroo Rabbakum summa toobooo ilaih; inna Rabbee Raheemunw Wadood", "translation": "And ask forgiveness of your Lord and then repent to Him. Indeed, my Lord is Merciful and Affectionate.\""}, {"ayah": 91, "translit": "Qaaloo yaa Shu'aibu maa nafqahu kaseeram mimmaa taqoolu wa innaa lanaraaka feenaa da'eefanw wa law laa rahtuka larajamnaaka wa maaa anta 'alainaa bi'azeez", "translation": "They said, \"O Shu'ayb, we do not understand much of what you say, and indeed, we consider you among us as weak. And if not for your family, we would have stoned you [to death]; and you are not to us one respected.\""}, {"ayah": 92, "translit": "Qaala yaa qawmi arahteee a'azzu 'alaikum minal laahi wattakhaztumoohu waraaa'akum zihriyyan inna Rabbee bimaa ta'maloona muheet", "translation": "He said, \"O my people, is my family more respected for power by you than Allah? But you put Him behind your backs [in neglect]. Indeed, my Lord is encompassing of what you do."}, {"ayah": 93, "translit": "Wa yaa qawmi' maloo 'alaa makaanatikum innee 'aamilun sawfa ta'lamoona mai yaateehi 'azaabuny yukhzeehi wa man huwa kaazib; wartaqibooo innnee ma'akum raqeeb", "translation": "And O my people, work according to your position; indeed, I am working. You are going to know to whom will come a punishment that will disgrace him and who is a liar. So watch; indeed, I am with you a watcher, [awaiting the outcome].\""}, {"ayah": 94, "translit": "Wa lammaa jaaa'a amrunaa najjainaa shu'aibanw wal lazeena aamanoo ma'ahoo birahmatim minnaa wa akhazatil lazeena zalamus saihatu fa asbahoo fee diyaarihim jaasimeen", "translation": "And when Our command came, We saved Shu'ayb and those who believed with him, by mercy from Us. And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone"}, {"ayah": 95, "translit": "Ka-al-lam yaghnaw feehaaa; alaa bu'dal li Madyana Kamaa ba'idat Samood", "translation": "As if they had never prospered therein. Then, away with Madyan as Thamud was taken away."}, {"ayah": 96, "translit": "Wa laqad arsalnaa Moosaa bi Aayaatinaa wa sultaanim mubeen", "translation": "And We did certainly send Moses with Our signs and a clear authority"}, {"ayah": 97, "translit": "Ilaa Fir'awna wa mala'ihee fattaba'ooo amra Fir'awna wa maaa amru Fir'awna birasheed", "translation": "To Pharaoh and his establishment, but they followed the command of Pharaoh, and the command of Pharaoh was not [at all] discerning."}, {"ayah": 98, "translit": "Yaqdumu qawmahoo Yawmal Qiyaamati fa awrada humun Naara wa bi'sal wirdul mawrood", "translation": "He will precede his people on the Day of Resurrection and lead them into the Fire; and wretched is the place to which they are led."}, {"ayah": 99, "translit": "Wa utbi'oo fee haazihee la'natanw wa Yawmal Qiyaamah; bi'sar rifdul marfood", "translation": "And they were followed in this [world] with a curse and on the Day of Resurrection. And wretched is the gift which is given."}, {"ayah": 100, "translit": "Zaalika min ambaaa'il quraa naqussuhoo 'alaika minhaa qaaa'imunw wa haseed", "translation": "That is from the news of the cities, which We relate to you; of them, some are [still] standing and some are [as] a harvest [mowed down]."}, {"ayah": 101, "translit": "Wa maa zalamnaahum wa laakin zalamooo anfusahum famaaa aghnat 'anhum aalihatuhumul latee yad'oona min doonil laahi min shai'il lammaa jaaa'a amru Rabbika wa maa zaadoohum ghaira tatbeeb", "translation": "And We did not wrong them, but they wronged themselves. And they were not availed at all by their gods which they invoked other than Allah when there came the command of your Lord. And they did not increase them in other than ruin."}, {"ayah": 102, "translit": "Wa kazaalika akhzu Rabbika izaaa akhazal quraa wa hiya zaalimah; inna akhzahooo aleemun shadeed", "translation": "And thus is the seizure of your Lord when He seizes the cities while they are committing wrong. Indeed, His seizure is painful and severe."}, {"ayah": 103, "translit": "Inna fee zaalika la aayatal liman khaafa 'azaabal Aakhirah; zaalika Yawmum majmoo'ul lahun naasu wa zaalika Yawmum mashhood", "translation": "Indeed in that is a sign for those who fear the punishment of the Hereafter. That is a Day for which the people will be collected, and that is a Day [which will be] witnessed."}, {"ayah": 104, "translit": "Wa maa nu'akhkhiruhooo illaa li ajalim ma'dood", "translation": "And We do not delay it except for a limited term."}, {"ayah": 105, "translit": "Yawma yaati laa takallamu nafsun illaa bi iznih; faminhum shaqiyyunw wa sa'eed", "translation": "The Day it comes no soul will speak except by His permission. And among them will be the wretched and the prosperous."}, {"ayah": 106, "translit": "Fa ammal lazeena shaqoo fafin Naari lahum feehaa zafeerunw wa shaheeq", "translation": "As for those who were [destined to be] wretched, they will be in the Fire. For them therein is [violent] exhaling and inhaling."}, {"ayah": 107, "translit": "Khaalideena feehaa maa daamatis samaawaatu wal ardu illaa maa shaaa'a Rabbuk; inna Rabbaka fa' 'aalul limaa yureed", "translation": "[They will be] abiding therein as long as the heavens and the earth endure, except what your Lord should will. Indeed, your Lord is an effecter of what He intends."}, {"ayah": 108, "translit": "Wa ammal lazeena su'idoo fafil Jannati khaalideena feehaa maa daamatis samaawaatu wal ardu illaa maa shaaa'a Rabbuk; ataaa'an ghaira majzooz", "translation": "And as for those who were [destined to be] prosperous, they will be in Paradise, abiding therein as long as the heavens and the earth endure, except what your Lord should will - a bestowal uninterrupted."}, {"ayah": 109, "translit": "Falaa taku fee miryatim mimmmaa ya'budu haaa'ulaaa'; maa ya'budoona illaa kamaa ya'budu aabaaa'uhum min qabl; wa innaa lamuwaf foohum naseebahum ghaira manqoos", "translation": "So do not be in doubt, [O Muhammad], as to what these [polytheists] are worshipping. They worship not except as their fathers worshipped before. And indeed, We will give them their share undiminished."}, {"ayah": 110, "translit": "Wa laqad aatainaa Moosal Kitaaba fakhtulifa feeh; wa law laa Kalimatun sabaqat mir Rabbika laqudiya bainahum; wa innahum lafee shakkim minhu mureeb", "translation": "And We had certainly given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been judged between them. And indeed they are, concerning the Qur'an, in disquieting doubt."}, {"ayah": 111, "translit": "Wa inna kullal lammaa la yuwaffiyannahum Rabbuka a'maalahum; innahoo bimaa ya'maloona Khabeer", "translation": "And indeed, each [of the believers and disbelievers] - your Lord will fully compensate them for their deeds. Indeed, He is Acquainted with what they do."}, {"ayah": 112, "translit": "Fastaqim kamaaa umirta wa man taaba ma'aka wa laa tatghaw; innahoo bimaa ta'maloona Baseer", "translation": "So remain on a right course as you have been commanded, [you] and those who have turned back with you [to Allah], and do not transgress. Indeed, He is Seeing of what you do."}, {"ayah": 113, "translit": "Wa laa tarkanooo ilal lazeena zalamoo fatamassa kumun Naaru wa maa lakum min doonil laahi min awliyaaa'a summa laa tunsaroon", "translation": "And do not incline toward those who do wrong, lest you be touched by the Fire, and you would not have other than Allah any protectors; then you would not be helped."}, {"ayah": 114, "translit": "Wa aqimis Salaata tarafayin nahaari wa zulafam minal layl; innal hasanaati yuzhibnas saiyi aat; zaalika zikraa liz zaakireen", "translation": "And establish prayer at the two ends of the day and at the approach of the night. Indeed, good deeds do away with misdeeds. That is a reminder for those who remember."}, {"ayah": 115, "translit": "Wasbir fa innal laaha laa yudee'u ajral muhsineen", "translation": "And be patient, for indeed, Allah does not allow to be lost the reward of those who do good."}, {"ayah": 116, "translit": "Falw laa kaana minal qurooni min qablikum ooloo baqiyyatiny yanhawna 'anil fasaadi fil ardi illaa qaleelam mimman anjainaa minhum; wattaba'al lazeena zalamoo maaa utrifoo feehi wa kaanoo mujrimeen", "translation": "So why were there not among the generations before you those of enduring discrimination forbidding corruption on earth - except a few of those We saved from among them? But those who wronged pursued what luxury they were given therein, and they were criminals."}, {"ayah": 117, "translit": "Wa maa kaana Rabbuka liyuhlikal quraa bizulminw wa ahluhaa muslihoon", "translation": "And your Lord would not have destroyed the cities unjustly while their people were reformers."}, {"ayah": 118, "translit": "Wa law shaaa'a Rabbuka laja'alannnaasa ummatanw waa hidatanw wa laa yazaaloona mukhtalifeen", "translation": "And if your Lord had willed, He could have made mankind one community; but they will not cease to differ."}, {"ayah": 119, "translit": "Illaa mar rahima Rabbuk; wa lizaalika khalaqahum; wa tammat Kalimatu Rabbika la amla'ana Jahannama minal jinnati wannnaasi ajma'een", "translation": "Except whom your Lord has given mercy, and for that He created them. But the word of your Lord is to be fulfilled that, \"I will surely fill Hell with jinn and men all together.\""}, {"ayah": 120, "translit": "Wa kullan naqussu 'alaika min ambaaa'ir Rusuli maa nusabbitu bihee fu'aadak; wa jaaa'aka fee haazihil haqqu wa maw'izatunw wa zikraa lilmu' mineen", "translation": "And each [story] We relate to you from the news of the messengers is that by which We make firm your heart. And there has come to you, in this, the truth and an instruction and a reminder for the believers."}, {"ayah": 121, "translit": "Wa qul lillazeena laa yu'minoona' maloo 'alaa makaanatikum innaa 'aamiloon", "translation": "And say to those who do not believe, \"Work according to your position; indeed, we are working."}, {"ayah": 122, "translit": "Wantaziroo innaa mun taziroon", "translation": "And wait, indeed, we are waiting.\""}, {"ayah": 123, "translit": "Wa lillaahi ghaibus samaawaati wal ardi wa ilaihi yurja'ul amru kulluhoo fa'bu-dhu wa tawakkal 'alaih; wa maa Rabbuka bighaafilin 'ammaa ta'maloon", "translation": "And to Allah belong the unseen [aspects] of the heavens and the earth and to Him will be returned the matter, all of it, so worship Him and rely upon Him. And your Lord is not unaware of that which you do."}]}, {"num": 12, "name": "Yusuf", "meaning": "Joseph", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Raa; tilka Aayaatul Kitaabil Mubeen", "translation": "Alif, Lam, Ra. These are the verses of the clear Book."}, {"ayah": 2, "translit": "Innaaa anzalnaahu quraanan 'Arabiyyal la 'allakum ta'qiloon", "translation": "Indeed, We have sent it down as an Arabic Qur'an that you might understand."}, {"ayah": 3, "translit": "Nahnu naqussu 'alaika ahsanal qasasi bimaaa awhainaaa ilaika haazal quraana wa in kunta min qablihee laminal ghaafileen", "translation": "We relate to you, [O Muhammad], the best of stories in what We have revealed to you of this Qur'an although you were, before it, among the unaware."}, {"ayah": 4, "translit": "Iz qaala Yoosufu li abeehi yaaa abati innee ra aytu ahada 'ashara kawkabanw wash shamsa walqamara ra aytuhum lee saajideen", "translation": "[Of these stories mention] when Joseph said to his father, \"O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me.\""}, {"ayah": 5, "translit": "Qaala yaa bunaiya laa taqsus ru'yaaka 'alaaa ikhwatika fayakeedoo laka kaidaa; innash Shaitaana lil insaani 'aduwwum mubeen", "translation": "He said, \"O my son, do not relate your vision to your brothers or they will contrive against you a plan. Indeed Satan, to man, is a manifest enemy."}, {"ayah": 6, "translit": "Wa kazaalika yajtabeeka rabbuka wa yu'allimuka min taaweelil ahaadeesi wa yutimmu ni'matahoo 'alaika wa 'alaaa Aali Ya'qooba kamaaa atammahaa 'alaaa abawaika min qablu Ibraaheema wa Ishaaq; inna Rabbaka 'Aleemun hakeem", "translation": "And thus will your Lord choose you and teach you the interpretation of narratives and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise.\""}, {"ayah": 7, "translit": "Laqad kaana fee Yoosufa wa ikhwatiheee Aayaatul lissaaa'ileen", "translation": "Certainly were there in Joseph and his brothers signs for those who ask,"}, {"ayah": 8, "translit": "Iz qaaloo la Yoosufu wa akhoohu ahabbu ilaaa Abeenaa minnaa wa nahnu 'usbah; inna abaanaa lafee dalaalim mubeen", "translation": "When they said, \"Joseph and his brother are more beloved to our father than we, while we are a clan. Indeed, our father is in clear error."}, {"ayah": 9, "translit": "Uqtuloo Yoosufa awitra hoohu ardany yakhlu lakum wajhu abeekum wa takoonoo mim ba'dihee qawman saaliheen", "translation": "Kill Joseph or cast him out to [another] land; the countenance of your father will [then] be only for you, and you will be after that a righteous people.\""}, {"ayah": 10, "translit": "Qaalaa qaaa'ilum minhum laa taqtuloo Yoosufa wa alqoohu fee ghayaabatil jubbi yaltaqithu badus sai yaarati in kuntum faa 'ileen", "translation": "Said a speaker among them, \"Do not kill Joseph but throw him into the bottom of the well; some travelers will pick him up - if you would do [something].\""}, {"ayah": 11, "translit": "Qaaloo yaaa abaanaa maa laka laa taamannaa 'alaa Yoosufa wa innaa lahoo lanaa sihoon", "translation": "They said, \"O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?"}, {"ayah": 12, "translit": "Arilhu ma'anaa ghadany yarta'wa yal'ab wa innaa lahoo lahaafizoon", "translation": "Send him with us tomorrow that he may eat well and play. And indeed, we will be his guardians."}, {"ayah": 13, "translit": "Qaala innee la yahzununeee an tazhaboo bihee wa akhaafu anyyaakulahuz zi'bu wa antum 'anhu ghaafiloon", "translation": "[Jacob] said, \"Indeed, it saddens me that you should take him, and I fear that a wolf would eat him while you are of him unaware.\""}, {"ayah": 14, "translit": "Qaaloo la in akalahuzzi'bu wa nahnu 'usbatun innaaa izal lakhaasiroon", "translation": "They said, \"If a wolf should eat him while we are a [strong] clan, indeed, we would then be losers.\""}, {"ayah": 15, "translit": "Falammaa zahaboo bihee wa ajma'ooo anyyaj'aloohu fee ghayaabatil jubb; wa awyainaaa ilaihi latunabbi 'annahum bi amrihim haaza wa hum laa yash'uroon", "translation": "So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, \"You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity].\""}, {"ayah": 16, "translit": "Wa jaaa'ooo abaahum 'ishaaa 'any yabkoon", "translation": "And they came to their father at night, weeping."}, {"ayah": 17, "translit": "Qaaloo yaaa abaanaaa innaa zahabnaa nastabiqu wa taraknaa Yoosufa 'inda mataa'inaa fa akhalahuz zi'b, wa maaa anta bimu'minil lanaa wa law kunnaa saadiqeen", "translation": "They said, \"O our father, indeed we went racing each other and left Joseph with our possessions, and a wolf ate him. But you would not believe us, even if we were truthful.\""}, {"ayah": 18, "translit": "Wa jaaa'oo 'alaa qamee shihee bidamin kazi' qaala bal sawwalat lakum anfusukum amraa; fasabrun jameel; wallaahul musta'aanu 'alaa man tasifoon", "translation": "And they brought upon his shirt false blood. [Jacob] said, \"Rather, your souls have enticed you to something, so patience is most fitting. And Allah is the one sought for help against that which you describe.\""}, {"ayah": 19, "translit": "Wa jaaa'at saiyaaratun fa-arsaloo waaridahum fa adlaa dalwah; qaala yaa bushraa haaza ghulaam; wa asarroohu bi-daa'ah; wallaahu 'aleemum bimaa ya'maloon", "translation": "And there came a company of travelers; then they sent their water drawer, and he let down his bucket. He said, \"Good news! Here is a boy.\" And they concealed him, [taking him] as merchandise; and Allah was knowing of what they did."}, {"ayah": 20, "translit": "Wa sharawhu bisamanim bakhsin daraahima ma'doo datinw wa kaanoo feehi minaz zaahideen", "translation": "And they sold him for a reduced price - a few dirhams - and they were, concerning him, of those content with little."}, {"ayah": 21, "translit": "Wa qaalal lazish taraahu mim Misra limra atiheee akrimee maswaahu 'asaaa any-yanfa'anaaa aw nattakhizahoo waladaa; wa kazaalika mak-kannaa li-Yoosufa fil ardi wa linu'allimahoo min taaweelil ahaadees; wallaahu ghaalibun 'alaaa amrihee wa laakinna aksaran naasi laa ya'lamoon", "translation": "And the one from Egypt who bought him said to his wife, \"Make his residence comfortable. Perhaps he will benefit us, or we will adopt him as a son.\" And thus, We established Joseph in the land that We might teach him the interpretation of events. And Allah is predominant over His affair, but most of the people do not know."}, {"ayah": 22, "translit": "Wa lammaa balagha ashuddahooo aatainaahu bukmanw wa 'ilmaa; wa kazaa lika najzil muhsineen", "translation": "And when Joseph reached maturity, We gave him judgment and knowledge. And thus We reward the doers of good."}, {"ayah": 23, "translit": "Wa raawadat hul latee huwa fee baitihaa 'an nafsihee wa ghallaqatil abwaaba wa qaalat haita lak; qaala ma'aazal laahi innahoo rabbeee ahsana maswaay; innahoo laa yuflihuz-zaalimoon", "translation": "And she, in whose house he was, sought to seduce him. She closed the doors and said, \"Come, you.\" He said, \"[I seek] the refuge of Allah. Indeed, he is my master, who has made good my residence. Indeed, wrongdoers will not succeed.\""}, {"ayah": 24, "translit": "Wa laqad hammat bihee wa hamma bihaa law laaa ar ra-aa burhaana rabbih;; kazaalika linasrifa 'anhu sooo'a walfa hshaaa'; innahoo min 'ibaadi nal mukhlaseen", "translation": "And she certainly determined [to seduce] him, and he would have inclined to her had he not seen the proof of his Lord. And thus [it was] that We should avert from him evil and immorality. Indeed, he was of Our chosen servants."}, {"ayah": 25, "translit": "Wastabaqal baaba wa qaddat qameesahoo min dubu rinw wa alfayaa saiyidahaa ladal baab; qaalat maa jazaaa'u man araada bi ahlika sooo'an illaaa any-yusjana aw azaabun aleem", "translation": "And they both raced to the door, and she tore his shirt from the back, and they found her husband at the door. She said, \"What is the recompense of one who intended evil for your wife but that he be imprisoned or a painful punishment?\""}, {"ayah": 26, "translit": "Qaala hiya raawadatnee 'an nafsee wa shahida shaahidum min ahlihaa in kaana qameesuhoo qudda min qubulin fasadaqat wa huwa minal kaazibeen", "translation": "[Joseph] said, \"It was she who sought to seduce me.\" And a witness from her family testified. \"If his shirt is torn from the front, then she has told the truth, and he is of the liars."}, {"ayah": 27, "translit": "Wa in kaana qameesuhoo qudda min duburin fakazabat wa huwa minas saadiqeen", "translation": "But if his shirt is torn from the back, then she has lied, and he is of the truthful.\""}, {"ayah": 28, "translit": "Falammaa ra-aa qamee sahoo qudda min duburin qaala innahoo min kaidikunna inna kaidakunna 'azeem", "translation": "So when her husband saw his shirt torn from the back, he said, \"Indeed, it is of the women's plan. Indeed, your plan is great."}, {"ayah": 29, "translit": "Yoosofu a'rid 'an haaza wastaghfiree lizambiki innaki kunti minal khaati'een", "translation": "Joseph, ignore this. And, [my wife], ask forgiveness for your sin. Indeed, you were of the sinful.\""}, {"ayah": 30, "translit": "Wa qaala niswatun filma deenatim ra atul'Azeezi turaawidu fataahaa 'an nafsihee qad shaghafahaa bubbaa; innaa lana raahaa fee dalaalim mubeen", "translation": "And women in the city said, \"The wife of al-'Azeez is seeking to seduce her slave boy; he has impassioned her with love. Indeed, we see her [to be] in clear error.\""}, {"ayah": 31, "translit": "Falammaa sami'at bimak rihinna arsalat ilaihinna wa a'tadat lahunna muttaka anw wa aatat kulla waahidatim min hunna sikkeenanw wa qaala tikh ruj 'alaihinna falammaa ra aynahooo akbarnahoo wa qatta'na aydiyahunna wa qulna haasha lillaahi maa haaza basharaa; in haazaaa illaa malakun kareem", "translation": "So when she heard of their scheming, she sent for them and prepared for them a banquet and gave each one of them a knife and said [to Joseph], \"Come out before them.\" And when they saw him, they greatly admired him and cut their hands and said, \"Perfect is Allah! This is not a man; this is none but a noble angel.\""}, {"ayah": 32, "translit": "Qaalat fazaalikunnal lazee lumtunnanee feeh; wa laqad raawattuhoo 'an nafsihee fasta'sam; wa la'il lam yaf'al maaa aamuruhoo la yusjananna wa la yakoonam minas saaghireen", "translation": "She said, \"That is the one about whom you blamed me. And I certainly sought to seduce him, but he firmly refused; and if he will not do what I order him, he will surely be imprisoned and will be of those debased.\""}, {"ayah": 33, "translit": "Qaala rabbis sijnu ahabbu ilaiya mimma yad'oo naneee 'ilaihi wa illaa tasrif 'annee kaidahunna asbu ilaihinna wa akum minal jaahileen", "translation": "He said, \"My Lord, prison is more to my liking than that to which they invite me. And if You do not avert from me their plan, I might incline toward them and [thus] be of the ignorant.\""}, {"ayah": 34, "translit": "Fastajaaba lahoo rabbuhoo fasarafa 'anhu kaidahunn; innahoo Huswas_Samee'ul 'Aleem (section 4)", "translation": "So his Lord responded to him and averted from him their plan. Indeed, He is the Hearing, the Knowing."}, {"ayah": 35, "translit": "Summa badaa lahum mim ba'di maa ra-awul Aayaati layasjununnahoo hatta heen", "translation": "Then it appeared to them after they had seen the signs that al-'Azeez should surely imprison him for a time."}, {"ayah": 36, "translit": "Wa dakhala ma'ahussijna fata yaan; qaala ahaduhumaaa inneee araaneee a'siru khamranw wa qaalal aakharu inneee khubzan taakulut tairu minh; nabbi 'naa bitaaweelihee innaa naraaka minal muhsineen", "translation": "And there entered the prison with him two young men. One of them said, \"Indeed, I have seen myself [in a dream] pressing wine.\" The other said, \"Indeed, I have seen myself carrying upon my head [some] bread, from which the birds were eating. Inform us of its interpretation; indeed, we see you to be of those who do good.\""}, {"ayah": 37, "translit": "Qaala laa yaateekumaa ta'aamun turzaqaaniheee illaa nabbaatukumaa bitaaweelihee qabla any yaatiyakumaa; zaali kumaa mimmaa 'allamanee rabbee; innee taraktu millata qawmil laa yu'minoona billaahi wahum bil aakhirati hum kaafiroon", "translation": "He said, \"You will not receive food that is provided to you except that I will inform you of its interpretation before it comes to you. That is from what my Lord has taught me. Indeed, I have left the religion of a people who do not believe in Allah, and they, in the Hereafter, are disbelievers."}, {"ayah": 38, "translit": "Wattab'tu millata aabaaa'eee Ibraaheema wa Ishaaqa wa Ya'qoob; maa kaana lanaaa an nushrika billaahi min shai' zaalikamin fadlil laahi 'alainaa wa 'alan naasi wa laakinna aksaran naasi laa yashkuroon", "translation": "And I have followed the religion of my fathers, Abraham, Isaac and Jacob. And it was not for us to associate anything with Allah. That is from the favor of Allah upon us and upon the people, but most of the people are not grateful."}, {"ayah": 39, "translit": "Yaa saahibayis sijni 'a-arbaabum mutafarriqoona khayrun amil laahul waahidul qahhaar", "translation": "O [my] two companions of prison, are separate lords better or Allah, the One, the Prevailing?"}, {"ayah": 40, "translit": "Maa  ta'budoona min doonihee illaaa asmaaa'an sam maitumoohaaa antum wa aabaaa'ukum maaa anzalal laahu bihaa min sultan; inilhukmu illaa lillaah; amara allaa ta'budooo illaaa iyyaah; zaalikad deenul qaiyimu wa laakinna aksaran naasi laa ya'lamoon", "translation": "You worship not besides Him except [mere] names you have named them, you and your fathers, for which Allah has sent down no authority. Legislation is not but for Allah. He has commanded that you worship not except Him. That is the correct religion, but most of the people do not know."}, {"ayah": 41, "translit": "Yaa saahibayis sijni ammaaa ahadukumaa fa yasqee rabbahoo khamranw wa ammal aakharu fa yuslabu fataakulut tairu mir raasih; qudiyal amrul lazee feehi tastaftiyaan", "translation": "O two companions of prison, as for one of you, he will give drink to his master of wine; but as for the other, he will be crucified, and the birds will eat from his head. The matter has been decreed about which you both inquire.\""}, {"ayah": 42, "translit": "Wa qaala lillazee zanna annahoo najim minhumaz kurnee 'inda rabbika fa-ansaahush Shaitaanu zikra Rabbihee falabisa fis sijni bad'a sineen", "translation": "And he said to the one whom he knew would go free, \"Mention me before your master.\" But Satan made him forget the mention [to] his master, and Joseph remained in prison several years."}, {"ayah": 43, "translit": "Wa qaalal maliku inneee araa sab'a baqaraatin simaaniny yaakuluhunna sab'un 'ijaafunw wa sab'a sumbulaatinkhudrinw wa ukhara yaabisaat; yaaa ayuhal mala-u aftoonee fee nu'yaaya in kuntum lirru'yaa ta'buroon", "translation": "And [subsequently] the king said, \"Indeed, I have seen [in a dream] seven fat cows being eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry. O eminent ones, explain to me my vision, if you should interpret visions.\""}, {"ayah": 44, "translit": "Qaalooo adghaasu ahlaa minw wa maa nahnu bitaaweelil ahlaami bi'aalimeen", "translation": "They said, \"[It is but] a mixture of false dreams, and we are not learned in the interpretation of dreams.\""}, {"ayah": 45, "translit": "Wa qaalal lazee najaa minhumaa waddakara ba'da ummatin ana unabbi'ukum bitalweelihee fa-arsiloon", "translation": "But the one who was freed and remembered after a time said, \"I will inform you of its interpretation, so send me forth.\""}, {"ayah": 46, "translit": "Yoosufu ayyuhas siddee qu aftinaa fee sab'i baqaraatin simaaniny yaakuluhunna sab'un 'ijaafunw wa sabi'i sumbulaatin khudrinw wa ukhara yaabisaatil la'alleee arj'u ilan naasi la'allahum ya'lamoon", "translation": "[He said], \"Joseph, O man of truth, explain to us about seven fat cows eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry - that I may return to the people; perhaps they will know [about you].\""}, {"ayah": 47, "translit": "Qaala tazra'oona sab'a sineena da aban famaa basattum fazaroohu fee sumbu liheee illaa qaleelam mimmaa taakuloon", "translation": "[Joseph] said, \"You will plant for seven years consecutively; and what you harvest leave in its spikes, except a little from which you will eat."}, {"ayah": 48, "translit": "Summa yaatee mim ba'di zaalika sab'un shidaaduny yaa kulna maa qaddamtum lahunna illaa qaleelam mimma tuhsinoon", "translation": "Then will come after that seven difficult [years] which will consume what you saved for them, except a little from which you will store."}, {"ayah": 49, "translit": "Summa yadtee mim ba'di zaalika 'aamun feehi yughaa sun naasu wa feehi ya'siroon", "translation": "Then will come after that a year in which the people will be given rain and in which they will press [olives and grapes].\""}, {"ayah": 50, "translit": "Wa qaalal maliku'toonee bihee falammaa jaaa'ahur rasoolu qaalar-ji ilaa rabbika fas'alhu maa baalun niswatil laatee qatta'na aydiyahunn; inna Rabbee bikaidihinna 'Aleem", "translation": "And the king said, \"Bring him to me.\" But when the messenger came to him, [Joseph] said, \"Return to your master and ask him what is the case of the women who cut their hands. Indeed, my Lord is Knowing of their plan.\""}, {"ayah": 51, "translit": "Qaala maa khatbukunna iz raawattunna Yoosufa 'annafsih; qulna haasha lillaahi maa 'alimnaa 'alaihi min sooo'; qaalatim ra atul 'Azeezil 'aana hashasal haqq, ana raawat tuhoo 'an nafsihee wa innahoo laminas saadiqeen", "translation": "Said [the king to the women], \"What was your condition when you sought to seduce Joseph?\" They said, \"Perfect is Allah! We know about him no evil.\" The wife of al-'Azeez said, \"Now the truth has become evident. It was I who sought to seduce him, and indeed, he is of the truthful."}, {"ayah": 52, "translit": "Zaalika liya'lama annee lam akhunhu bilghaibi wa annal laaha laa yahdee kaidal khaaa'ineen", "translation": "That is so al-'Azeez will know that I did not betray him in [his] absence and that Allah does not guide the plan of betrayers."}, {"ayah": 53, "translit": "Wa maa ubarri'u nafsee; innan nafsa la ammaaratum bissooo'i illaa maa rahima Rabbee; inna Rabbee Ghafoorur Raheem", "translation": "And I do not acquit myself. Indeed, the soul is a persistent enjoiner of evil, except those upon which my Lord has mercy. Indeed, my Lord is Forgiving and Merciful.\""}, {"ayah": 54, "translit": "Wa qaalal maliku' toonee biheee astakhlishu linafsee falammaa kallamahoo qaala innakal yawma ladainaa makeenun ameen", "translation": "And the king said, \"Bring him to me; I will appoint him exclusively for myself.\" And when he spoke to him, he said, \"Indeed, you are today established [in position] and trusted.\""}, {"ayah": 55, "translit": "Qaalaj 'alnee 'alaa khazaaa'inil ardi innee hafeezun 'aleem", "translation": "[Joseph] said, \"Appoint me over the storehouses of the land. Indeed, I will be a knowing guardian.\""}, {"ayah": 56, "translit": "Wa kazaalika makkannaa li Yoosufa fil ardi yatabawwa'u minhaa haisu yashaaaa'; nuseebu birahmatinaa man nashaaa'u wa laa nudee'u ajral muhsineen", "translation": "And thus We established Joseph in the land to settle therein wherever he willed. We touch with Our mercy whom We will, and We do not allow to be lost the reward of those who do good."}, {"ayah": 57, "translit": "Wa la ajrul Aakhirati khairul lillazeena aamanoo wa kaanoo yattaqoon", "translation": "And the reward of the Hereafter is better for those who believed and were fearing Allah."}, {"ayah": 58, "translit": "Wa jaaa'a ikhwatu Yoosufa fadakhaloo 'alaihi fa'arafahum wa hum lahoo munkiroon", "translation": "And the brothers of Joseph came [seeking food], and they entered upon him; and he recognized them, but he was to them unknown."}, {"ayah": 59, "translit": "Wa lammaa jahhazahum bijahaazihim qaala' toonee bi akhil lakum min abeekum; alaa tarawna anneee oofil kaila wa ana khairul munzileen", "translation": "And when he had furnished them with their supplies, he said, \"Bring me a brother of yours from your father. Do not you see that I give full measure and that I am the best of accommodators?"}, {"ayah": 60, "translit": "Fa il lam taatoonee bihee falaa kaila lakum 'indee wa laa taqraboon", "translation": "But if you do not bring him to me, no measure will there be [hereafter] for you from me, nor will you approach me.\""}, {"ayah": 61, "translit": "Qaaloo sanuraawidu 'anhu abaahu wa innaa lafaa'iloon", "translation": "They said, \"We will attempt to dissuade his father from [keeping] him, and indeed, we will do [it].\""}, {"ayah": 62, "translit": "Wa qaala lifityaanihij 'aloo bidaa'atahum fee rihaalihim la'allahum ya'rifoonahaaa izan qalabooo ilaaa ahlihim la'allahum yarji'oon", "translation": "And [Joseph] said to his servants, \"Put their merchandise into their saddlebags so they might recognize it when they have gone back to their people that perhaps they will [again] return.\""}, {"ayah": 63, "translit": "Falammaa raja'ooo ilaaa abeehim qaaloo yaaa abaanaa muni'a minnal kailu fa arsil ma'anaaa akhaanaa naktal wa innaa lahoo lahaafizoon", "translation": "So when they returned to their father, they said, \"O our father, [further] measure has been denied to us, so send with us our brother [that] we will be given measure. And indeed, we will be his guardians.\""}, {"ayah": 64, "translit": "Qaala hal aamanukum 'alihi illaa kamaa amintukum 'alaaa akheehimin qabl; fal laahu khairun haafizanw wa Huwa arhamur Raahimeen", "translation": "He said, \"Should I entrust you with him except [under coercion] as I entrusted you with his brother before? But Allah is the best guardian, and He is the most merciful of the merciful.\""}, {"ayah": 65, "translit": "Wa lammaa fatahoo mataa 'ahum wajadoo bidaa'atahum ruddat ilaihim qaaloo yaaa abaanaa maa nabghee; haazihee bida 'atunaa ruddat ilainaa wa nameeru ahlanaa wa nahfazu akhaanaa wa nazdaadu kaila ba'eer; zaalika kailuny yaseer", "translation": "And when they opened their baggage, they found their merchandise returned to them. They said, \"O our father, what [more] could we desire? This is our merchandise returned to us. And we will obtain supplies for our family and protect our brother and obtain an increase of a camel's load; that is an easy measurement.\""}, {"ayah": 66, "translit": "Qaala lan ursilahoo ma'akum hattaa tu'tooni mawsiqam minal laahis lataa tunnanee biheee illaaa nay yuhaata bikum falammaaa aatawhu mawsiqahum qaalal laahu 'alaa maa naqoolu Wakeel", "translation": "[Jacob] said, \"Never will I send him with you until you give me a promise by Allah that you will bring him [back] to me, unless you should be surrounded by enemies.\" And when they had given their promise, he said, \"Allah, over what we say, is Witness.\""}, {"ayah": 67, "translit": "Wa qaala yaa baniyya laa tadkhuloo mim baabinw waa hidinw wadkhuloo min abwaabim mutafarriqah; wa maaa ughnee 'ankum minal laahi min shai'in; inil hukmu illaa lillaahi 'alaihi tawakkaltu wa 'alaihi fal yatawakkalil Mutawakkiloon", "translation": "And he said, \"O my sons, do not enter from one gate but enter from different gates; and I cannot avail you against [the decree of] Allah at all. The decision is only for Allah; upon Him I have relied, and upon Him let those who would rely [indeed] rely.\""}, {"ayah": 68, "translit": "Wa lammaa dakhaloo min haisu amarahum aboohum maa kaana yughnee 'anhum minal laahi min shai'in illaa haajatan fee nafsi Ya'qooba qadaahaa; wa innahoo lazoo 'ilmil limaa 'allamnaahu wa laakinna aksaran naasi laa ya'lamoon", "translation": "And when they entered from where their father had ordered them, it did not avail them against Allah at all except [it was] a need within the soul of Jacob, which he satisfied. And indeed, he was a possessor of knowledge because of what We had taught him, but most of the people do not know."}, {"ayah": 69, "translit": "Wa lammaa dakhaloo 'alaa Yoosufa aawaaa ilaihi akhaahu qaala inneee ana akhooka falaa tabta'is bimaa kaanoo ya'maloon", "translation": "And when they entered upon Joseph, he took his brother to himself; he said, \"Indeed, I am your brother, so do not despair over what they used to do [to me].\""}, {"ayah": 70, "translit": "Falammaa jahhazahum bijahaazihim ja'alas siqaayata fee rahli akheehi summa azzana mu'azzinun ayyatuhal'eeru innakum lasaariqoon", "translation": "So when he had furnished them with their supplies, he put the [gold measuring] bowl into the bag of his brother. Then an announcer called out, \"O caravan, indeed you are thieves.\""}, {"ayah": 71, "translit": "Qaaloo wa aqbaloo 'alaihim maazaa tafqidoon", "translation": "They said while approaching them, \"What is it you are missing?\""}, {"ayah": 72, "translit": "Qaaloo nafqidu suwaa'al maliki wa liman jaaa'a bihee himlu ba'eerinw wa ana bihee za'eem", "translation": "They said, \"We are missing the measure of the king. And for he who produces it is [the reward of] a camel's load, and I am responsible for it.\""}, {"ayah": 73, "translit": "Qaaloo tallaahi laqad 'alimtum maa ji'na linufsida fil ardi wa maa kunnaa saariqeen", "translation": "They said, \"By Allah, you have certainly known that we did not come to cause corruption in the land, and we have not been thieves.\""}, {"ayah": 74, "translit": "Qaaloo famaa jazaaa'u hooo in kuntum kaazibeen", "translation": "The accusers said, \"Then what would be its recompense if you should be liars?\""}, {"ayah": 75, "translit": "Qaaloo jazaaa'uhoo manw wujida fee rahlihee fahuwa jazaaa'uh; kazaalika najziz zaalimeen", "translation": "[The brothers] said, \"Its recompense is that he in whose bag it is found - he [himself] will be its recompense. Thus do we recompense the wrongdoers.\""}, {"ayah": 76, "translit": "Fabada-a bi-aw'iyatihim qabla wi'aaa'i akheehi summas takhrajahaa minw wi 'aaa'i akheeh; kazaalika kidnaa li Yoosuf; maa kaana liyaakhuza akhaahu fee deenil maliki illaaa any yashaaa'al laah; narfa'u darajaatim man nashaaa'; wa fawqa kulli zee 'ilmin 'Aleem", "translation": "So he began [the search] with their bags before the bag of his brother; then he extracted it from the bag of his brother. Thus did We plan for Joseph. He could not have taken his brother within the religion of the king except that Allah willed. We raise in degrees whom We will, but over every possessor of knowledge is one [more] knowing."}, {"ayah": 77, "translit": "Qaaloo iny yasriq faqad saraqa akhul lahoo min qabl; fa asarrahaa Yoosufu fee nafsihee wa lam yubdihaa lahum; qaala antum sharrum makaananw wallaahu a'lamu bimaa tasifoon", "translation": "They said, \"If he steals - a brother of his has stolen before.\" But Joseph kept it within himself and did not reveal it to them. He said, \"You are worse in position, and Allah is most knowing of what you describe.\""}, {"ayah": 78, "translit": "Qaaloo yaaa ayyuhal 'Azeezu inna lahooo aban shaikhan kabeeran fakhuz ahadanaa makaanahoo innaa naraaka minal muhsineen", "translation": "They said, \"O 'Azeez, indeed he has a father [who is] an old man, so take one of us in place of him. Indeed, we see you as a doer of good.\""}, {"ayah": 79, "translit": "Qaala ma'aazal laahi an naakhuza illaa manw wajadnaa mataa'anaa 'indahoo innaaa izal lazaalimoon", "translation": "He said, \"[I seek] the refuge of Allah [to prevent] that we take except him with whom we found our possession. Indeed, we would then be unjust.\""}, {"ayah": 80, "translit": "Falammas tay'asoo minhu khalasoo najiyyan qaala kabeeruhum alam ta'lamoon anna abaakum qad akhaza 'alaikum mawsiqam minal laahi wa min qablu maa farrattum fee Yoosufa falan abrahal arda hattaa yaazana leee abeee aw yahkumal laahu lee wa huwa khairul lhaakimeen", "translation": "So when they had despaired of him, they secluded themselves in private consultation. The eldest of them said, \"Do you not know that your father has taken upon you an oath by Allah and [that] before you failed in [your duty to] Joseph? So I will never leave [this] land until my father permits me or Allah decides for me, and He is the best of judges."}, {"ayah": 81, "translit": "Irji'ooo ilaaa abeekum faqooloo yaaa abaanaaa innab naka saraq; wa maa shahidnaaa illaa bimaa 'alimnaa wa maa kunnaa lilghaibi haafizeen", "translation": "Return to your father and say, \"O our father, indeed your son has stolen, and we did not testify except to what we knew. And we were not witnesses of the unseen,"}, {"ayah": 82, "translit": "Was'alil qaryatal latee kunnaa feehaa wal'eeral lateee aqbalnaa feehaa wa innaa lasaadiqoon", "translation": "And ask the city in which we were and the caravan in which we came - and indeed, we are truthful,\""}, {"ayah": 83, "translit": "Qaala bal sawwalat lakum anfusukum amran fasabrun jameelun 'asal laahu any yaa tiyanee bihim jamee'aa; innahoo Huwal 'Aleemul Hakeem", "translation": "[Jacob] said, \"Rather, your souls have enticed you to something, so patience is most fitting. Perhaps Allah will bring them to me all together. Indeed it is He who is the Knowing, the Wise.\""}, {"ayah": 84, "translit": "Wa tawallaa 'anhum wa qaala yaaa asafaa 'alaa Yoosufa wabyaddat 'aynaahu minal huzni fahuwa kazeem", "translation": "And he turned away from them and said, \"Oh, my sorrow over Joseph,\" and his eyes became white from grief, for he was [of that] a suppressor."}, {"ayah": 85, "translit": "Qaaloo tallaahi tafta'u tazkuru Yoosufa hattaa takoona haradan aw takoona minal haalikeen", "translation": "They said, \"By Allah, you will not cease remembering Joseph until you become fatally ill or become of those who perish.\""}, {"ayah": 86, "translit": "Qaala innamaaa ashkoo bassee wa huzneee ilal laahi wa a'lamu minal laahi maa laa ta'lamoon", "translation": "He said, \"I only complain of my suffering and my grief to Allah, and I know from Allah that which you do not know."}, {"ayah": 87, "translit": "Yaa baniyyaz haboo fatahassasoo miny Yoosufa wa akheehi wa laa tai'asoo mir rawhil laahi innahoo laa yai'asu mir rawhil laahi illal qawmul kaafiroon", "translation": "O my sons, go and find out about Joseph and his brother and despair not of relief from Allah. Indeed, no one despairs of relief from Allah except the disbelieving people.\""}, {"ayah": 88, "translit": "Falammaa dakhaloo 'alaihi qaaloo yaaa ayyuhal 'Azeezu massanaa wa ahlanad durru wa ji'naa bibidaa 'timmuzjaatin fa awfi lanal kaila wa tasaddaq 'alainaa innal laaha yajzil mutasaddiqeen", "translation": "So when they entered upon Joseph, they said, \"O 'Azeez, adversity has touched us and our family, and we have come with goods poor in quality, but give us full measure and be charitable to us. Indeed, Allah rewards the charitable.\""}, {"ayah": 89, "translit": "Qaala hal 'alimtum maa fa'altum bi Yoosufa wa akheehi iz antum jaahiloon", "translation": "He said, \"Do you know what you did with Joseph and his brother when you were ignorant?\""}, {"ayah": 90, "translit": "Qaaloo 'a innaka la anta Yoosufu qaala ana Yoosufu wa haazaaa akhee qad mannal laahu 'alainaa innahoo mai yattaqi wa yasbir fa innal laaha laa yudee'u ajral muhsineen", "translation": "They said, \"Are you indeed Joseph?\" He said \"I am Joseph, and this is my brother. Allah has certainly favored us. Indeed, he who fears Allah and is patient, then indeed, Allah does not allow to be lost the reward of those who do good.\""}, {"ayah": 91, "translit": "Qaaloo tallaahi laqad aasarakal laahu 'alainaa wa in kunnaa lakhaati'een", "translation": "They said, \"By Allah, certainly has Allah preferred you over us, and indeed, we have been sinners.\""}, {"ayah": 92, "translit": "Qaala laa tasreeba 'alaikumul yawma yaghfirul laahu lakum wa Huwa arhamur raahimeen", "translation": "He said, \"No blame will there be upon you today. Allah will forgive you; and He is the most merciful of the merciful.\""}, {"ayah": 93, "translit": "Izhaboo biqameesee haazaa fa alqoohu 'alaa wajhi abee yaati baseeranw waatoonee bi ahlikum ajma'een", "translation": "Take this, my shirt, and cast it over the face of my father; he will become seeing. And bring me your family, all together.\""}, {"ayah": 94, "translit": "Wa lammaa fasalatil 'eeru qaala aboohum innee la ajidu reeha Yoosufa law laaa an tufannidoon", "translation": "And when the caravan departed [from Egypt], their father said, \"Indeed, I find the smell of Joseph [and would say that he was alive] if you did not think me weakened in mind.\""}, {"ayah": 95, "translit": "Qaaloo tallaahi innaka lafee dalaalikal qadeem", "translation": "They said, \"By Allah, indeed you are in your [same] old error.\""}, {"ayah": 96, "translit": "Falammaaa an jaaa'albasheeru alqaahu 'alaa wajhihee fartadda baseeran qaala alam aqul lakum inneee a'lamu minal laahi maa laa ta'lamoon", "translation": "And when the bearer of good tidings arrived, he cast it over his face, and he returned [once again] seeing. He said, \"Did I not tell you that I know from Allah that which you do not know?\""}, {"ayah": 97, "translit": "Qaaloo yaaa abaanas taghfir lanaa zunoo =banaaa innaa kunnaa khaati'een", "translation": "They said, \"O our father, ask for us forgiveness of our sins; indeed, we have been sinners.\""}, {"ayah": 98, "translit": "Qaala sawfa astaghfiru lakum Rabbeee innahoo Huwal Ghafoorur Raheem", "translation": "He said, \"I will ask forgiveness for you from my Lord. Indeed, it is He who is the Forgiving, the Merciful.\""}, {"ayah": 99, "translit": "Falammaa dakhaloo 'alaa Yoosufa aawaaa ilaihi abayaihi wa qaalad khuloo Misra inshaaa'al laahu aamineen", "translation": "And when they entered upon Joseph, he took his parents to himself and said, \"Enter Egypt, Allah willing, safe [and secure].\""}, {"ayah": 100, "translit": "Wa raf'a abawaihi 'alal 'arshi wa kharroo lahoo sujjadaa; wa qaala yaaa abati haaza taaweelu ru'yaaya min qablu qad ja'alahaa Rabbee haqqaa; wa qad ahsana beee iz akhrajanee minas sijni wa jaaa'a bikum minal badwi mim ba'di an nazaghash Shaitaanu bainee wa baina ikhwatee; inna Rabbee lateeful limaa yashaaa'; innahoo Huwal 'Aleemul Hakeem", "translation": "And he raised his parents upon the throne, and they bowed to him in prostration. And he said, \"O my father, this is the explanation of my vision of before. My Lord has made it reality. And He was certainly good to me when He took me out of prison and brought you [here] from bedouin life after Satan had induced [estrangement] between me and my brothers. Indeed, my Lord is Subtle in what He wills. Indeed, it is He who is the Knowing, the Wise."}, {"ayah": 101, "translit": "Rabbi qad aataitanee minal mulki wa 'allamtanee min taaweelil ahaadees; faati ras samaawaati wal ardi Anta waliyyee fid dunyaa wal Aakhirati tawaffanee muslimanw wa alhiqnee bissaaliheen", "translation": "My Lord, You have given me [something] of sovereignty and taught me of the interpretation of dreams. Creator of the heavens and earth, You are my protector in this world and in the Hereafter. Cause me to die a Muslim and join me with the righteous.\""}, {"ayah": 102, "translit": "Zaalika min ambaaa'il ghaibi nooheehi ilaika wa maa kunta ladaihim iz ajma'ooo amrahum wa hum yamkuroon", "translation": "That is from the news of the unseen which We reveal, [O Muhammad], to you. And you were not with them when they put together their plan while they conspired."}, {"ayah": 103, "translit": "Wa maa aksarun naasi wa law harasta bimu'mineen", "translation": "And most of the people, although you strive [for it], are not believers."}, {"ayah": 104, "translit": "Wa maa tas'aluhum 'alaihi min ajr; in huwa illaa zikrul lil'aalameen", "translation": "And you do not ask of them for it any payment. It is not except a reminder to the worlds."}, {"ayah": 105, "translit": "Wa ka ayyim min Aayatin fis samaawaati wal ardi yamurroona 'alaihaa wa hum 'anhaa mu'ridoon", "translation": "And how many a sign within the heavens and earth do they pass over while they, therefrom, are turning away."}, {"ayah": 106, "translit": "Wa maa yu'minu aksaru hum billaahi illaa wa hum mushrikoon", "translation": "And most of them believe not in Allah except while they associate others with Him."}, {"ayah": 107, "translit": "Afa aminooo an taatiya hum ghaashiyatum min 'azaabil laahi aw taatiyahumus Saa'atu baghtatanw wa hum laa yash'uroon", "translation": "Then do they feel secure that there will not come to them an overwhelming [aspect] of the punishment of Allah or that the Hour will not come upon them suddenly while they do not perceive?"}, {"ayah": 108, "translit": "Qul haazihee sabeeleee ad'ooo ilal laah; 'alaa baseera tin ana wa manit taba'anee wa Subhaanal laahi wa maaa ana minal mushrikeen", "translation": "Say, \"This is my way; I invite to Allah with insight, I and those who follow me. And exalted is Allah; and I am not of those who associate others with Him.\""}, {"ayah": 109, "translit": "Wa maaa arsalnaa min qablika illaa rijaalan nooheee ilaihim min ahlil quraa; afalam yaseeroo fil ardi fa yanzuroo kaifa kaana 'aaqibatul lazeena min qablihim; wa la Daarul Aakhirati Khairul lillazeenat taqaw; afalaa ta'qiloon", "translation": "And We sent not before you [as messengers] except men to whom We revealed from among the people of cities. So have they not traveled through the earth and observed how was the end of those before them? And the home of the Hereafter is best for those who fear Allah; then will you not reason?"}, {"ayah": 110, "translit": "Hattaaa izas tai'asar Rusulu wa zannooo annahum qad kuziboo jaaa'ahum nas runaa fanujjiya man nashaaa'u wa laa yuraddu baasunna 'anil qawmil mujrimeen", "translation": "[They continued] until, when the messengers despaired and were certain that they had been denied, there came to them Our victory, and whoever We willed was saved. And Our punishment cannot be repelled from the people who are criminals."}, {"ayah": 111, "translit": "Laqad kaana fee qasasihim 'ibratul li ulil albaa; maa kaana hadeesany yuftaraa wa laakin tasdeeqal lazee baina yadihi wa tafseela kulli shai'inw wa hudanw wa rahmatal liqawminy yu'minoon", "translation": "There was certainly in their stories a lesson for those of understanding. Never was the Qur'an a narration invented, but a confirmation of what was before it and a detailed explanation of all things and guidance and mercy for a people who believe."}]}, {"num": 13, "name": "Ar-Ra'd", "meaning": "The Thunder", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Meeem-Raa; tilka Aayaatul Kitaab; wallazee unzila ilaika mir Rabbikal haqqu wa laakinna aksaran naasi laa yu'minoon", "translation": "Alif, Lam, Meem, Ra. These are the verses of the Book; and what has been revealed to you from your Lord is the truth, but most of the people do not believe."}, {"ayah": 2, "translit": "Allaahul lazee raf'as samaawaati bighairi 'amadin tarawnahaa summas tawaa 'alal 'Arshi wa sakhkharash shamsa walqamara kulluny yajree li ajalim musammaa; yudabbirul amra yufassilil Aayaati la'allakum biliqaaa'i Rabbikum tooqinoon", "translation": "It is Allah who erected the heavens without pillars that you [can] see; then He established Himself above the Throne and made subject the sun and the moon, each running [its course] for a specified term. He arranges [each] matter; He details the signs that you may, of the meeting with your Lord, be certain."}, {"ayah": 3, "translit": "Wa Huwal lazee maddal arda wa ja'ala feehaa rawaasiya wa anhaaraa; wa min kullis samaraati ja'ala feehaa zawjainis yaini Yughshil lailan nahaar; inna fee zaalika la aayaatil liqawminy yatafakkaroon", "translation": "And it is He who spread the earth and placed therein firmly set mountains and rivers; and from all of the fruits He made therein two mates; He causes the night to cover the day. Indeed in that are signs for a people who give thought."}, {"ayah": 4, "translit": "Wa fil ardi qita'um muta jaawiraatunw wa jannaatum min a'naabinw wa zar'unw wa nakheelun sinwaanunw wa ghairu sinwaaniny yusqaa bimaaa'inw waahid; wa nufaddilu ba'dahaa 'alaa ba'din fil-ukul; inna fee zaalika la aayaatil liqawminy ya'qiloon", "translation": "And within the land are neighboring plots and gardens of grapevines and crops and palm trees, [growing] several from a root or otherwise, watered with one water; but We make some of them exceed others in [quality of] fruit. Indeed in that are signs for a people who reason."}, {"ayah": 5, "translit": "Wa in ta'jab fa'ajabun qawluhm 'a-izaa kunna turaaban 'a-inna lafee khalqin jadeed; ulaaa 'ikal lazeena kafaroo bi Rabbihim wa ulaaa'ikal aghlaalu feee a'naaqihim wa ulaa'ika Ashaabun Naari hum feehaa khaalidoon", "translation": "And if you are astonished, [O Muhammad] - then astonishing is their saying, \"When we are dust, will we indeed be [brought] into a new creation?\" Those are the ones who have disbelieved in their Lord, and those will have shackles upon their necks, and those are the companions of the Fire; they will abide therein eternally."}, {"ayah": 6, "translit": "Wa yasta'jiloonaka bis saiyi'ati qablal hasanati wa qad khalat min qablihimul masulaat; wa inna Rabbaka lazoo maghfiratil linnaasi 'alaa zulmihim wa inna Rabbaka lashadeedul 'iqaab", "translation": "They impatiently urge you to bring about evil before good, while there has already occurred before them similar punishments [to what they demand]. And indeed, your Lord is full of forgiveness for the people despite their wrongdoing, and indeed, your Lord is severe in penalty."}, {"ayah": 7, "translit": "Wa yaqoolul lazeena kafaroo law laaa unzila 'alaihi Aayatum mir Rabbih; innamaaa anta munzirunw wa likulli qawmin haad", "translation": "And those who disbelieved say, \"Why has a sign not been sent down to him from his Lord?\" You are only a warner, and for every people is a guide."}, {"ayah": 8, "translit": "Allaahu ya'lamu maa tahmilu kullu unsaa wa maa tagheedul arhaamu wa maa tazdaad, wa kullu shai'in 'indahoo bimiqdaar", "translation": "Allah knows what every female carries and what the wombs lose [prematurely] or exceed. And everything with Him is by due measure."}, {"ayah": 9, "translit": "'Aalimul Ghaibi wash shahaadatil Kaabeerul Muta'aal", "translation": "[He is] Knower of the unseen and the witnessed, the Grand, the Exalted."}, {"ayah": 10, "translit": "Sawaaa'um minkum man asarral qawla wa man jahara bihee wa man huwa mustakhfim billaili wa saaribum binnahaar", "translation": "It is the same [to Him] concerning you whether one conceals [his] speech or one publicizes it and whether one is hidden by night or conspicuous [among others] by day."}, {"ayah": 11, "translit": "Lahoo mu'aqqibaatum mim baini yadaihi wa min khalfihee yahfazoonahoo min amril laah; innal laaha laa yughaiyiru maa biqawmin hattaa yughaiyiroo maa bianfusihim; wa izaaa araadal laahu biqawmin sooo'an falaa maradda lah; wa maa lahum min dooniheeminw waal", "translation": "For each one are successive [angels] before and behind him who protect him by the decree of Allah. Indeed, Allah will not change the condition of a people until they change what is in themselves. And when Allah intends for a people ill, there is no repelling it. And there is not for them besides Him any patron."}, {"ayah": 12, "translit": "Huwal lazee yureekumul barqa khawfanw wa tama'anw wa yunshi'us sahaabas siqaal", "translation": "It is He who shows you lightening, [causing] fear and aspiration, and generates the heavy clouds."}, {"ayah": 13, "translit": "Wa yusabbihur ra'du bihamdihee walmalaaa'ikatu min kheefatihee wa yursilus sawaa'iqa fa yuseebu bihaa mai yashaaa'u wa hum yujaadiloona fil laahi wa Huwa shadeedul mihaal", "translation": "And the thunder exalts [Allah] with praise of Him - and the angels [as well] from fear of Him - and He sends thunderbolts and strikes therewith whom He wills while they dispute about Allah; and He is severe in assault."}, {"ayah": 14, "translit": "Lahoo da'watul haqq; wallazeena yad'oona min doonihee laa yastajeeboona lahum bishai'in illaa kabaasiti kaffaihi ilal maaa'i liyablugha faahu wa maa huwa bibaalighih; wa maa du'aaa'ul aafireena illaa fee dalaal", "translation": "To Him [alone] is the supplication of truth. And those they call upon besides Him do not respond to them with a thing, except as one who stretches his hands toward water [from afar, calling it] to reach his mouth, but it will not reach it [thus]. And the supplication of the disbelievers is not but in error [i.e. futility]."}, {"ayah": 15, "translit": "Wa lillaahi yasjudu man fis samaawaati wal ardi taw 'anw wa karhanw wa zilaaluhum bilghuduwwi wal aasaal", "translation": "And to Allah prostrates whoever is within the heavens and the earth, willingly or by compulsion, and their shadows [as well] in the mornings and the afternoons."}, {"ayah": 16, "translit": "Qul mar Rabbus samaawaati wal ard; qulillaah; qul afattakhaztum min dooniheee awliyaaa'a laa yamlikoona li anfusihim naf'anw wa laa darraa; qul hal yastawil a'maa wal baseeru am hal tastawiz zulumaatu wannoor; am ja'aloo lillaahi shurakaaa'a khalaqoo kakhalqihee fatashaa bahal khalqu 'alaihim; qulil laahu Khaaliqu kulli shai'inw wa Huwal Waahidul Qahhar", "translation": "Say, \"Who is Lord of the heavens and earth?\" Say, \"Allah.\" Say, \"Have you then taken besides Him allies not possessing [even] for themselves any benefit or any harm?\" Say, \"Is the blind equivalent to the seeing? Or is darkness equivalent to light? Or have they attributed to Allah partners who created like His creation so that the creation [of each] seemed similar to them?\" Say, \"Allah is the Creator of all things, and He is the One, the Prevailing.\""}, {"ayah": 17, "translit": "Anzala minas samaaa'i maaa'an fasaalat awdiyatum biqadarihaa fahtamalas sailu zabadar raabiyaa; wa mimmmaa yooqidoona 'alaihi fin naarib tighaaa'a bilyatin aw mataa'in zabadum misluh; kazaalika yadribul laahul haqqa wal baatil; fa ammaz zabadu fa yazhabu jufaaa'aa; wa ammaa maa yanfa'un naasa fa yamkusu fil ard; kazaalika yadribul laahul amsaal", "translation": "He sends down from the sky, rain, and valleys flow according to their capacity, and the torrent carries a rising foam. And from that [ore] which they heat in the fire, desiring adornments and utensils, is a foam like it. Thus Allah presents [the example of] truth and falsehood. As for the foam, it vanishes, [being] cast off; but as for that which benefits the people, it remains on the earth. Thus does Allah present examples."}, {"ayah": 18, "translit": "Lillazeenas tajaaboo lirabbihimul husnaa; wallazeena lam yastajeeboo lahoo law anna lahum maa fil ardi jamee'anw wa mislahoo ma'ahoo laftadaw bih; ulaaa'ika lahum sooo'ul hisaab; wa maawaahum Jahannamu wa bi'sal mihaad", "translation": "For those who have responded to their Lord is the best [reward], but those who did not respond to Him - if they had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby. Those will have the worst account, and their refuge is Hell, and wretched is the resting place."}, {"ayah": 19, "translit": "Afamai ya'lamu annamaaa unzila ilaika mir Rabbikal haqqu kaman huwa a'maa; innamaa yatazakkaru ulul albaab", "translation": "Then is he who knows that what has been revealed to you from your Lord is the truth like one who is blind? They will only be reminded who are people of understanding -"}, {"ayah": 20, "translit": "Allazeena yoofoona bi'ahdil laahi wa laa yanqu doonal meesaaq", "translation": "Those who fulfill the covenant of Allah and do not break the contract,"}, {"ayah": 21, "translit": "Wallazeena yasiloona maaa amaral laahu bihee an yoosala wa yakhshawna Rabbahum wa yakhaafoona sooo'al hisaab", "translation": "And those who join that which Allah has ordered to be joined and fear their Lord and are afraid of the evil of [their] account,"}, {"ayah": 22, "translit": "Wallazeena sabarub tighaaa'a Wajhi Rabbihim wa aqaamus Salaata wa anfaqoo mimmaa razaqnaahum sirranw wa 'alaaniyatanw wa yadra'oona bilhasanatis saiyi'ata ulaaa'ika lahum 'uqbad daar", "translation": "And those who are patient, seeking the countenance of their Lord, and establish prayer and spend from what We have provided for them secretly and publicly and prevent evil with good - those will have the good consequence of [this] home -"}, {"ayah": 23, "translit": "jannaatu 'adiny yadkhu loonahaa wa man salaha min aabaaa'ihim wa man salaha min aabaaa'ihim wa azwaajihim wa zurriyyaatihim walmalaaa'i katu yadkhuloona 'alaihim min kulli baab", "translation": "Gardens of perpetual residence; they will enter them with whoever were righteous among their fathers, their spouses and their descendants. And the angels will enter upon them from every gate, [saying],"}, {"ayah": 24, "translit": "Salaamun 'alaikum bimaa sabartum; fani'ma 'uqbad daar", "translation": "\"Peace be upon you for what you patiently endured. And excellent is the final home.\""}, {"ayah": 25, "translit": "Wallazeena yanqudoona 'Ahdal laahi mim ba'di  meesaaqihee wa yaqta'oona maaa amaral laahu biheee ai yoosala wa yufsidoona fil ardi ulaaa'ika lahumul la'natu wa lahum sooo'ud daar", "translation": "But those who break the covenant of Allah after contracting it and sever that which Allah has ordered to be joined and spread corruption on earth - for them is the curse, and they will have the worst home."}, {"ayah": 26, "translit": "Allaahu yabsutur rizqa limai yashaaa'u wa yaqdir; wa farihoo bilhayaatid dunyaa wa mal hayaatud dunya fil Aakhirati illaa mataa'", "translation": "Allah extends provision for whom He wills and restricts [it]. And they rejoice in the worldly life, while the worldly life is not, compared to the Hereafter, except [brief] enjoyment."}, {"ayah": 27, "translit": "Wa yaqoolul lazeena kafaroo law laaa unzila 'alaihi Aayatum mir Rabbih; qul innal laaha yudillu mai yashaa'u wa yahdeee ilaihi man anaab", "translation": "And those who disbelieved say, \"Why has a sign not been sent down to him from his Lord?\" Say, [O Muhammad], \"Indeed, Allah leaves astray whom He wills and guides to Himself whoever turns back [to Him] -"}, {"ayah": 28, "translit": "Allazeena aamanoo wa tatma'innu quloobuhum bizikril laah; alaa bizikril laahi tatma'innul quloob", "translation": "Those who have believed and whose hearts are assured by the remembrance of Allah. Unquestionably, by the remembrance of Allah hearts are assured.\""}, {"ayah": 29, "translit": "Allazeena aamanoo w a'amilus saalihaati toobaa lahum wa husnu ma aab", "translation": "Those who have believed and done righteous deeds - a good state is theirs and a good return."}, {"ayah": 30, "translit": "Kazaalika arsalnaaka feee ummatin qad khalat min qablihaaa umamul litatluwa 'alaihimul lazeee awhainaaa ilaika wa hum yakfuroona bir Rahmaaan; qul Huwa Rabbee laaa ilaaha illaa Huwa Rabbee laaa ilaaha illaa Huwa 'alaihi tawakkaltu wa ilaihi mataab", "translation": "Thus have We sent you to a community before which [other] communities have passed on so you might recite to them that which We revealed to you, while they disbelieve in the Most Merciful. Say, \"He is my Lord; there is no deity except Him. Upon Him I rely, and to Him is my return.\""}, {"ayah": 31, "translit": "Wa law anna Quraanan suyyirat bihil jibaalu aw qutti'at bihil ardu aw kullima bihil mawtaa; bal lillaahil amru jamee'aa; afalam yai'asil lazeena aamanooo al law yashaaa 'ullaahu lahadan naasa jamee'aa; wa laa yazaalul lazeena kafaroo tuseebuhum bimaa sana'oo qaari'atun aw tahullu qareebam min daarihim hatta yaatiya wa'dul laah; innal laaha laa yukhliful mee'aad", "translation": "And if there was any qur'an by which the mountains would be removed or the earth would be broken apart or the dead would be made to speak, [it would be this Qur'an], but to Allah belongs the affair entirely. Then have those who believed not accepted that had Allah willed, He would have guided the people, all of them? And those who disbelieve do not cease to be struck, for what they have done, by calamity - or it will descend near their home - until there comes the promise of Allah. Indeed, Allah does not fail in [His] promise."}, {"ayah": 32, "translit": "Wa laqadis tuhzi'a bi Rusulim min qablika fa amlaitu lillazeena kafaroo summa akhaztuhum fakaifa kaana 'iqaab", "translation": "And already were [other] messengers ridiculed before you, and I extended the time of those who disbelieved; then I seized them, and how [terrible] was My penalty."}, {"ayah": 33, "translit": "Afaman Huwa qaaa'imun 'alaa kulli nafsim bimaa kasabat; wa ja'aloo illlaahi shurakaaa'a qul samoohum; am tunabbi'oona hoo bimaa laa ya'lamu fil ardi; am bizaahirim minal qawl; bal zuyyina lillazeena kafaroo makruhum wa suddoo 'anis sabeel; wa mai yudlilil laaahu famaa lahoo min haad;", "translation": "Then is He who is a maintainer of every soul, [knowing] what it has earned, [like any other]? But to Allah they have attributed partners. Say, \"Name them. Or do you inform Him of that which He knows not upon the earth or of what is apparent of speech?\" Rather, their [own] plan has been made attractive to those who disbelieve, and they have been averted from the way. And whomever Allah leaves astray - there will be for him no guide."}, {"ayah": 34, "translit": "Lahum 'azaabun fil hayaatid dunyaa wa la'azaabul Aakhirati ashaaq, wa maa lahum minal laahi min-waaq", "translation": "For them will be punishment in the life of [this] world, and the punishment of the Hereafter is more severe. And they will not have from Allah any protector."}, {"ayah": 35, "translit": "Masalul Jannatil latee wu'idal muttaqoona tajree min tahtihal anhaaru ukuluhaa daaa'imunw wa zilluhaa; tilka uqbal lazeenat taqaw wa 'uqbal kafireenan Naar", "translation": "The example of Paradise, which the righteous have been promised, is [that] beneath it rivers flow. Its fruit is lasting, and its shade. That is the consequence for the righteous, and the consequence for the disbelievers is the Fire."}, {"ayah": 36, "translit": "Wallazeena aatainaa humul Kitaaba yafrahoona bimaa unzila ilaika wa minal Ahzaabi mai yunkiru ba'dah; qul innamaa umirtu an a'budal laaha wa laaa ushrika bih; ilaihi ad'oo wa ilaihi maab", "translation": "And [the believers among] those to whom We have given the [previous] Scripture rejoice at what has been revealed to you, [O Muhammad], but among the [opposing] factions are those who deny part of it. Say, \"I have only been commanded to worship Allah and not associate [anything] with Him. To Him I invite, and to Him is my return.\""}, {"ayah": 37, "translit": "Wa kazaalika anzalnaahu hukman 'Arabiyyaa; wa la'init taba'ta ahwaaa 'ahum ba'da maa jaaa'aka minal 'ilmi maa laka minal laahi minw waliyinw wa laa waaq", "translation": "And thus We have revealed it as an Arabic legislation. And if you should follow their inclinations after what has come to you of knowledge, you would not have against Allah any ally or any protector."}, {"ayah": 38, "translit": "Wa laqad arsalnaa Rusulam min qablika wa ja'alnaa lahum azwaajanw wa zurriyyah; wa maa kaana lirasoolin ai yaatiya bi aayatin illaa bi iznil laah; likulli ajalin kitaab", "translation": "And We have already sent messengers before you and assigned to them wives and descendants. And it was not for a messenger to come with a sign except by permission of Allah. For every term is a decree."}, {"ayah": 39, "translit": "Yamhul laahu maa yashaaa'u wa yusbitu wa 'indahooo ummul Kitaab", "translation": "Allah eliminates what He wills or confirms, and with Him is the Mother of the Book."}, {"ayah": 40, "translit": "Wa im maa nurriyannaka ba'dal lazee na'iduhum aw nata waffayannaka fa innamaa 'alaikal balaaghu wa 'alainal hisaab", "translation": "And whether We show you part of what We promise them or take you in death, upon you is only the [duty of] notification, and upon Us is the account."}, {"ayah": 41, "translit": "Awalam yaraw annaa naatil arda nanqusuhaa min atraafihaa; wallaahu yahkumu laa mu'aqqiba lihukmih; wa Huwa saree'ul hisaab", "translation": "Have they not seen that We set upon the land, reducing it from its borders? And Allah decides; there is no adjuster of His decision. And He is swift in account."}, {"ayah": 42, "translit": "Wa qad makaral lazeena min qablihim falillaahil makru jamee'aa; ya'lamu maa taksibu kullu nafs; wa sa ya'lamul kuffaaru liman 'uqbad daar", "translation": "And those before them had plotted, but to Allah belongs the plan entirely. He knows what every soul earns, and the disbelievers will know for whom is the final home."}, {"ayah": 43, "translit": "Wa yaqoolul lazeena kafaroo lasta mursalaa; qul kafaa billaahi shaheedam bainee wa bainakum wa man 'indahoo 'ilmul Kitaab", "translation": "And those who have disbelieved say, \"You are not a messenger.\" Say, [O Muhammad], \"Sufficient is Allah as Witness between me and you, and [the witness of] whoever has knowledge of the Scripture.\""}]}, {"num": 14, "name": "Ibrahim", "meaning": "Abraham", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Raa; Kitaabun anzalnaahu ilaika litukhrijan-naasa minaz zulumaati ilan noori bi-izni Rabbihim ilaa siraatil 'Azeezil Hameed", "translation": "Alif, Lam, Ra. [This is] a Book which We have revealed to you, [O Muhammad], that you might bring mankind out of darknesses into the light by permission of their Lord - to the path of the Exalted in Might, the Praiseworthy -"}, {"ayah": 2, "translit": "Allaahil lazee lahoo maa fis samaawaati wa maa fill ard; wa wailul lilkaafireena min 'azaabin shadeed", "translation": "Allah, to whom belongs whatever is in the heavens and whatever is on the earth. And woe to the disbelievers from a severe punishment"}, {"ayah": 3, "translit": "Allazeena yastahibboo nal hayaatad dunyaa 'alal aakhirati wa yasuddoona 'ansabeelil laahi wa yabghoonahaa 'iwajaa; ulaaa 'ika fee dalaalim ba'eed", "translation": "The ones who prefer the worldly life over the Hereafter and avert [people] from the way of Allah, seeking to make it (seem) deviant. Those are in extreme error."}, {"ayah": 4, "translit": "Wa maaa arsalnaa mir Rasoolin illaa bilisaani qawmihee liyubaiyina lahum faiudillul laahu mai yashaaa'u wa yahde mai yashaaa'; wa Huwal 'Azeezul Hakeem", "translation": "And We did not send any messenger except [speaking] in the language of his people to state clearly for them, and Allah sends astray [thereby] whom He wills and guides whom He wills. And He is the Exalted in Might, the Wise."}, {"ayah": 5, "translit": "Wa laqad arsalnaa Moosaa bi Aayaatinaa an akhrij qawmaka minaz zulumaati ilan noori wa zak kirhum bi ayyaamil laah; inna fee zaalika la aayaatil likulli sabbaarin shakoor", "translation": "And We certainly sent Moses with Our signs, [saying], \"Bring out your people from darknesses into the light and remind them of the days of Allah.\" Indeed in that are signs for everyone patient and grateful."}, {"ayah": 6, "translit": "Wa iz qaala Moosaa liqawmihiz kuroo ni'matal laahi 'alaikum iz anjaakum min Aali Fir'awna yasoomoo nakum sooo'al 'azaabi wa yuzabbihoona abnaaa'akum wa yastahyoona nisaaa'akum; wa fee zaalikum balaaa'um mir Rabbikum 'azeem", "translation": "And [recall, O Children of Israel], when Moses said to His people, \"Remember the favor of Allah upon you when He saved you from the people of Pharaoh, who were afflicting you with the worst torment and were slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord."}, {"ayah": 7, "translit": "Wa iz ta azzana Rabbukum la'in shakartum la azeedannakum wa la'in kafartum inn'azaabee lashadeed", "translation": "And [remember] when your Lord proclaimed, 'If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe.' \""}, {"ayah": 8, "translit": "Wa qaala Moosaaa in takfurooo antum wa man fil ardi jamee'an fa innal laaha la Ghaniyyun Hameed", "translation": "And Moses said, \"If you should disbelieve, you and whoever is on the earth entirely - indeed, Allah is Free of need and Praiseworthy.\""}, {"ayah": 9, "translit": "Alam yaatikum naba'ul lazeena min qablikum qawmi Noohinw wa 'Aadinw wa Samood, wallazeena mim ba'dihim; laa ya'lamuhum illallaah; jaaa'at hum Rusuluhum bilbaiyinaati faraddooo aydiyahum feee afwaahihim wa qaalooo innaa kafarnaa bimaaa ursiltum bihee wa innaa lafee shakkim mimmaa tad'oonanaaa ilaihi mureeb", "translation": "Has there not reached you the news of those before you - the people of Noah and 'Aad and Thamud and those after them? No one knows them but Allah. Their messengers brought them clear proofs, but they returned their hands to their mouths and said, \"Indeed, we disbelieve in that with which you have been sent, and indeed we are, about that to which you invite us, in disquieting doubt.\""}, {"ayah": 10, "translit": "Qaalat Rusuluhum afillaahi shakkun faatiris samaawaati wal ardi yad'ookum liyaghfira lakum min zunoobikum wa yu'akhkhirakum ilaaa ajalim musam maa; qaaloo in antum illaa basharum mislunaa tureedoona an tasuddoonaa 'ammaa kaana ya'budu aabaaa'unaa faatoonaa bisul taanim mubeen", "translation": "Their messengers said, \"Can there be doubt about Allah, Creator of the heavens and earth? He invites you that He may forgive you of your sins, and He delays your death for a specified term.\" They said, \"You are not but men like us who wish to avert us from what our fathers were worshipping. So bring us a clear authority.\""}, {"ayah": 11, "translit": "Qaalat lahum Rusuluhum in nahnu illaa basharum mislukum wa laakinnal laaha yamunnu 'alaa mai yashaaa'u min 'ibaadihee wa maa kaana lanaaa an naatiyakum bisul taanin illaa bi iznil laah; wa 'alal laahi falyatawakkalil mu'minonn", "translation": "Their messengers said to them, \"We are only men like you, but Allah confers favor upon whom He wills of His servants. It has never been for us to bring you evidence except by permission of Allah. And upon Allah let the believers rely."}, {"ayah": 12, "translit": "Wa maa lanaa allaa natawakkala 'alal laahi wa qad hadaanaa subulanaa; wa lanasbiranna 'alaa maaa aazaitumoonaa; wa 'alal laahi falyatawakkalil mutawakkiloon", "translation": "And why should we not rely upon Allah while He has guided us to our [good] ways. And we will surely be patient against whatever harm you should cause us. And upon Allah let those who would rely [indeed] rely.\""}, {"ayah": 13, "translit": "Wa qaalal lazeena kafaroo li Rusulihim lanukhrijanna kum min aardinaaa aw lata'oo dunna fee millatinaa fa awhaaa ilaihim Rabbuhum lanuhlikannaz zalimeen", "translation": "And those who disbelieved said to their messengers, \"We will surely drive you out of our land, or you must return to our religion.\" So their Lord inspired to them, \"We will surely destroy the wrongdoers."}, {"ayah": 14, "translit": "Wa lanuskinan nakumul arda mim ba'dihim; zaalika liman khaafa maqaamee wa khaafa wa'eed", "translation": "And We will surely cause you to dwell in the land after them. That is for he who fears My position and fears My threat.\""}, {"ayah": 15, "translit": "Wastaftahoo wa khaaba kullu jabbaarin 'aneed", "translation": "And they requested victory from Allah, and disappointed, [therefore], was every obstinate tyrant."}, {"ayah": 16, "translit": "Minw waraaa'ihee jahannamu wa yusqaa mim maaa'in sadeed", "translation": "Before him is Hell, and he will be given a drink of purulent water."}, {"ayah": 17, "translit": "Yatajarra'uhoo wa laa yakaadu yuseeghuhoo wa yaateehil mawtu min kulli makaaninw wa maa huwa bimaiyitinw wa minw waraaa'ihee 'azaabun ghaleez", "translation": "He will gulp it but will hardly [be able to] swallow it. And death will come to him from everywhere, but he is not to die. And before him is a massive punishment."}, {"ayah": 18, "translit": "Masalul lazeena kafaroo bi Rabbihim a'maaluhum karamaadinish taddat bihir reehu fee yawmin 'aasif; laa yaqdiroona mimmaa kasaboo 'alaa shai'; zaalika huwad dalaalul ba'eed", "translation": "The example of those who disbelieve in their Lord is [that] their deeds are like ashes which the wind blows forcefully on a stormy day; they are unable [to keep] from what they earned a [single] thing. That is what is extreme error."}, {"ayah": 19, "translit": "Alam tara annal laaha khalaqas samaawaati wal arda bilhaqq; iny yashaa yuzhibkum wa yaati bikhalqin jadeed", "translation": "Have you not seen that Allah created the heavens and the earth in truth? If He wills, He can do away with you and produce a new creation."}, {"ayah": 20, "translit": "Wa maa zaalika 'alal laahi bi 'azeez", "translation": "And that is not difficult for Allah."}, {"ayah": 21, "translit": "Wa barazoo lillaahi jamee'an faqaalad du'afaaa'u lillazeenas takbarooo innaa kunnaa lakum taba'an fahal antum mughnoona 'annaa min 'azaabil laahi min shai'; qaaloo law hadaanal laahu lahadai naakum sawaaa'un 'alainaaa ajazi'naa am sabarnaa maa lanaa mim mahees", "translation": "And they will come out [for judgement] before Allah all together, and the weak will say to those who were arrogant, \"Indeed, we were your followers, so can you avail us anything against the punishment of Allah?\" They will say, \"If Allah had guided us, we would have guided you. It is all the same for us whether we show intolerance or are patient: there is for us no place of escape.\""}, {"ayah": 22, "translit": "Wa qaalash Shaitaanu lammaa qudiyal amru innal laaha wa'adakum wa'dal haqqi wa wa'attukum faakhlaftukum wa maa kaana liya 'alaikum min sultaanin illaaa an da'awtukum fastajabtum lee falaa taloomoonee wa loomooo anfusakum maaa ana bimusrikhikum wa maaa antum bimusrikhiyya innee kafartu bimaaa ashraktumooni min qabl; innaz zaalimeena lahum azaabun aleem", "translation": "And Satan will say when the matter has been concluded, \"Indeed, Allah had promised you the promise of truth. And I promised you, but I betrayed you. But I had no authority over you except that I invited you, and you responded to me. So do not blame me; but blame yourselves. I cannot be called to your aid, nor can you be called to my aid. Indeed, I deny your association of me [with Allah] before. Indeed, for the wrongdoers is a painful punishment.\""}, {"ayah": 23, "translit": "Wa udkhilal lazeena aamanoo wa 'amilus saalihaati Jannaatin tajree min tahtihal anhaaru khaalideena feehaa bi izni Rabbihim tahiyyatuhum feeha salaam", "translation": "And those who believed and did righteous deeds will be admitted to gardens beneath which rivers flow, abiding eternally therein by permission of their Lord; and their greeting therein will be, \"Peace!\""}, {"ayah": 24, "translit": "Alam tara kaifa darabal laahu masalan kalimatan taiyibatan kashajaratin taiyibatin asluhaa saabitunw wa far'uhaa fis samaaa'", "translation": "Have you not considered how Allah presents an example, [making] a good word like a good tree, whose root is firmly fixed and its branches [high] in the sky?"}, {"ayah": 25, "translit": "Tu'teee ukulahaa kulla heenim bi izni Rabbihaa; wa yadribul laahul amsaala linnaasi la'allahum yatazak karoon", "translation": "It produces its fruit all the time, by permission of its Lord. And Allah presents examples for the people that perhaps they will be reminded."}, {"ayah": 26, "translit": "Wa masalu kalimatin khabeesatin kashajaratin khabee satinij tussat min fawqil ardi maa lahaa min qaraar", "translation": "And the example of a bad word is like a bad tree, uprooted from the surface of the earth, not having any stability."}, {"ayah": 27, "translit": "Yusabbitul laahul lazeena aamanoo bilqawlis saabiti fil hayaatid dunyaa wa fil Aakhirati wa yudillul laahuz zaalimeen; wa yaf'alul laahu maa yashaaa'", "translation": "Allah keeps firm those who believe, with the firm word, in worldly life and in the Hereafter. And Allah sends astray the wrongdoers. And Allah does what He wills."}, {"ayah": 28, "translit": "Alam tara ilal lazeena baddaloo ni'matal laahi kufranw wa ahalloo qawmahum daaral bawaar", "translation": "Have you not considered those who exchanged the favor of Allah for disbelief and settled their people [in] the home of ruin?"}, {"ayah": 29, "translit": "Jahannama yaslawnahaa wa bi'sal qaraar", "translation": "[It is] Hell, which they will [enter to] burn, and wretched is the settlement."}, {"ayah": 30, "translit": "Wa ja'aloo lillaahi andaadal liyudilloo 'an sabeelih; qul tamatta'oo fa innaa maseerakum ilan Naar", "translation": "And they have attributed to Allah equals to mislead [people] from His way. Say, \"Enjoy yourselves, for indeed, your destination is the Fire.\""}, {"ayah": 31, "translit": "Qul li'ibaadiyal lazeena aamanoo yuqeemus Salaata wa yunfiqoo mimmaa razaqnaahum sirranw wa 'alaaniyatam min qabli any yaatiya Yawmul laa bai'un feehi wa laa khilaal", "translation": "[O Muhammad], tell My servants who have believed to establish prayer and spend from what We have provided them, secretly and publicly, before a Day comes in which there will be no exchange, nor any friendships."}, {"ayah": 32, "translit": "Allaahul lazee khalaqas samaawaati wal arda wa anzala minas samaaa'i maaa'an faakhraja bihee minas samaraati rizqal lakum wa sakhkhara lakumul fulka litajriya fil bahri bi amrihee wa sakhkhara lakumul anhaar", "translation": "It is Allah who created the heavens and the earth and sent down rain from the sky and produced thereby some fruits as provision for you and subjected for you the ships to sail through the sea by His command and subjected for you the rivers."}, {"ayah": 33, "translit": "Wa sakhkhara lakumush shamsa walqamara daaa'ibaini wa sakhkhara lakumul laila wannahaar", "translation": "And He subjected for you the sun and the moon, continuous [in orbit], and subjected for you the night and the day."}, {"ayah": 34, "translit": "Wa aataakum min kulli maa sa altumooh; wa in ta'uddoo ni'matal laahi laa tuhsoohaa; innal insaana lazaloo mun kaffaar", "translation": "And He gave you from all you asked of Him. And if you should count the favor of Allah, you could not enumerate them. Indeed, mankind is [generally] most unjust and ungrateful."}, {"ayah": 35, "translit": "Wa iz qaala Ibraaheemu Rabbij 'al haazal balada aaminanw wajnubnee wa baniyya an na'budal asnaam", "translation": "And [mention, O Muhammad], when Abraham said, \"My Lord, make this city [Makkah] secure and keep me and my sons away from worshipping idols."}, {"ayah": 36, "translit": "Rabbi innahunna adlalna kaseeram minan naasi faman tabi'anee fa innahoo minnee wa man 'asaanee fa innaka Ghafoorur Raheem", "translation": "My Lord, indeed they have led astray many among the people. So whoever follows me - then he is of me; and whoever disobeys me - indeed, You are [yet] Forgiving and Merciful."}, {"ayah": 37, "translit": "Rabbanaaa inneee askantu min zurriyyatee biwaadin ghairi zee zar'in 'inda Baitikal Muharrami Rabbanaa liyuqeemus Salaata faj'al af'idatam minan naasi tahweee ilaihim warzuqhum minas samaraati la'allahum yashkuroon", "translation": "Our Lord, I have settled some of my descendants in an uncultivated valley near Your sacred House, our Lord, that they may establish prayer. So make hearts among the people incline toward them and provide for them from the fruits that they might be grateful."}, {"ayah": 38, "translit": "Rabbanaaa innaka ta'lamu maa nukhfee wa maa nu'lin; wa maa yakhfaa 'alal laahi min shai'in fil ardi wa laa fis samaaa'", "translation": "Our Lord, indeed You know what we conceal and what we declare, and nothing is hidden from Allah on the earth or in the heaven."}, {"ayah": 39, "translit": "Alhamdu lillaahil lazee wahaba lee 'alal kibari Ismaa'eela wa Ishaaq; inna Rabbee lasamee'ud du'aaa", "translation": "Praise to Allah, who has granted to me in old age Ishmael and Isaac. Indeed, my Lord is the Hearer of supplication."}, {"ayah": 40, "translit": "Rabbij 'alnee muqeemas Salaati wa min zurriyyatee Rabbanaa wa taqabbal du'aaa'", "translation": "My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication."}, {"ayah": 41, "translit": "Rabbanagh fir lee wa liwaalidaiya wa lilmu'mineena Yawma yaqoomul hisaab", "translation": "Our Lord, forgive me and my parents and the believers the Day the account is established.\""}, {"ayah": 42, "translit": "Wa laa tahsabannal laaha ghaafilan 'ammaa ya'maluz zaalimoon; innamaa yu'akh khiruhum li Yawmin tashkhasu feehil absaar", "translation": "And never think that Allah is unaware of what the wrongdoers do. He only delays them for a Day when eyes will stare [in horror]."}, {"ayah": 43, "translit": "Muhti'eena muqni'ee ru'oosihim laa yartaddu ilaihim tarfuhum wa af'idatuhum hawaaa'", "translation": "Racing ahead, their heads raised up, their glance does not come back to them, and their hearts are void."}, {"ayah": 44, "translit": "Wa anzirin naasa Yawma yaateehimul 'azaabu fa yaqoolul lazeena zalamoo Rabbanaaa akhkhirnaaa ilaaa ajalin qareebin nujib da'wataka wa nattabi 'ir Rusul; awalam takoonooo aqsamtum min qablu maa lakum min zawaal", "translation": "And, [O Muhammad], warn the people of a Day when the punishment will come to them and those who did wrong will say, \"Our Lord, delay us for a short term; we will answer Your call and follow the messengers.\" [But it will be said], \"Had you not sworn, before, that for you there would be no cessation?"}, {"ayah": 45, "translit": "Wa sakantum fee masaakinil lazeena zalamooo anfusahum wa tabaiyana lakum kaifa fa'alnaa bihim wa darabnaa lakumul amsaal", "translation": "And you lived among the dwellings of those who wronged themselves, and it had become clear to you how We dealt with them. And We presented for you [many] examples.\""}, {"ayah": 46, "translit": "Wa qad makaroo makrahum wa 'indal laahi makruhum wa in kaana makruhum litazoola minhul jibaal", "translation": "And they had planned their plan, but with Allah is [recorded] their plan, even if their plan had been [sufficient] to do away with the mountains."}, {"ayah": 47, "translit": "Falaa tahsabannal laaha mukhlifa wa'dihee Rusulah; innal laaha 'azeezun zuntiqaam", "translation": "So never think that Allah will fail in His promise to His messengers. Indeed, Allah is Exalted in Might and Owner of Retribution."}, {"ayah": 48, "translit": "Yawma tubaddalul ardu ghairal ardi wassamaawaatu wa barazoo lillaahil Waahidil Qahhaar", "translation": "[It will be] on the Day the earth will be replaced by another earth, and the heavens [as well], and all creatures will come out before Allah, the One, the Prevailing."}, {"ayah": 49, "translit": "Wa taral mujrimeena Yawma 'izim muqarraneena filasfaad", "translation": "And you will see the criminals that Day bound together in shackles,"}, {"ayah": 50, "translit": "Saraabeeluhum min qatiraaninw wa taghshaa wujoohahumun Naar", "translation": "Their garments of liquid pitch and their faces covered by the Fire."}, {"ayah": 51, "translit": "Liyajziyal laahu kulla nafsim maa kasabat; innal laaha saree'ul hisaab", "translation": "So that Allah will recompense every soul for what it earned. Indeed, Allah is swift in account."}, {"ayah": 52, "translit": "Haaza balaaghul linnaasi wa liyunzaroo bihee wa liya'lamooo annamaa Huwa Illaahunw Waahidunw wa liyaz zakkara ulul albaab", "translation": "This [Qur'an] is notification for the people that they may be warned thereby and that they may know that He is but one God and that those of understanding will be reminded."}]}, {"num": 15, "name": "Al-Hijr", "meaning": "The Rocky Tract", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Raa; tilka Aayaatul Kitaabi wa Qur-aa-nim Mubeen", "translation": "Alif, Lam, Ra. These are the verses of the Book and a clear Qur'an."}, {"ayah": 2, "translit": "Rubamaa yawaddul lazeena kafaroo law kaanoo muslimeen", "translation": "Perhaps those who disbelieve will wish that they had been Muslims."}, {"ayah": 3, "translit": "Zarhum yaakuloo wa tatamatta'oo wa yulhihimul amalu fasawfa ya'lamoon", "translation": "Let them eat and enjoy themselves and be diverted by [false] hope, for they are going to know."}, {"ayah": 4, "translit": "Wa maaa ahlaknaa min qaryatin illaa wa lahaa kitaabum ma'loom", "translation": "And We did not destroy any city but that for it was a known decree."}, {"ayah": 5, "translit": "Maa tasbiqu min ummatin ajalahaa wa maa yastaakhiroon", "translation": "No nation will precede its term, nor will they remain thereafter."}, {"ayah": 6, "translit": "Wa qaaloo yaaa aiyuhal lazee nuzzila 'alaihiz Zikru innaka lamajnoon", "translation": "And they say, \"O you upon whom the message has been sent down, indeed you are mad."}, {"ayah": 7, "translit": "Law maa taateenaa bil malaaa'ikati in kunta minas saadiqeen", "translation": "Why do you not bring us the angels, if you should be among the truthful?\""}, {"ayah": 8, "translit": "Maa nunazzilul malaaa'i kata illaa bilhaqqi wa maa kaanooo izam munzareen", "translation": "We do not send down the angels except with truth; and the disbelievers would not then be reprieved."}, {"ayah": 9, "translit": "Innaa Nahnu nazalnaz Zikra wa Innaa lahoo lahaa fizoon", "translation": "Indeed, it is We who sent down the Qur'an and indeed, We will be its guardian."}, {"ayah": 10, "translit": "Wa laqad arsalnaa min qablika fee shiya'il awwaleen", "translation": "And We had certainly sent [messengers] before you, [O Muhammad], among the sects of the former peoples."}, {"ayah": 11, "translit": "Wa maa yaateehim mir Rasoolin illaa kaanoo bihee yastahzi'oon", "translation": "And no messenger would come to them except that they ridiculed him."}, {"ayah": 12, "translit": "kazaalika naslukuhoo fee quloobil mujrimeen", "translation": "Thus do We insert denial into the hearts of the criminals."}, {"ayah": 13, "translit": "Laa yu'minoona bihee wa qad khalat sunnatul awwaleen", "translation": "They will not believe in it, while there has already occurred the precedent of the former peoples."}, {"ayah": 14, "translit": "Wa law fatahnaa 'alaihim baabam minas samaaa'i fazaloo feehi ya'rujoon", "translation": "And [even] if We opened to them a gate from the heaven and they continued therein to ascend,"}, {"ayah": 15, "translit": "Laqaaloo innamaa sukkirat absaarunaa bal nahnu qawmum mashooroon", "translation": "They would say, \"Our eyes have only been dazzled. Rather, we are a people affected by magic.\""}, {"ayah": 16, "translit": "Wa laqad ja'alnaa fissamaaa'i buroojanw wa zaiyannaahaa linnaazireen", "translation": "And We have placed within the heaven great stars and have beautified it for the observers."}, {"ayah": 17, "translit": "Wa hafiznaahaa min kulli Shaitaanir rajeem", "translation": "And We have protected it from every devil expelled [from the mercy of Allah]"}, {"ayah": 18, "translit": "Illaa manis taraqas sam'a fa atba'ahoo shihaabum mubeen", "translation": "Except one who steals a hearing and is pursued by a clear burning flame."}, {"ayah": 19, "translit": "Wal arda madadnaahaa wa alqainaa feehaa rawaasiya wa ambatnaa feehaa min kulli shai'im mawzoon", "translation": "And the earth - We have spread it and cast therein firmly set mountains and caused to grow therein [something] of every well-balanced thing."}, {"ayah": 20, "translit": "Wa ja'alnaa lakum feehaa ma'aayisha wa mal lastum lahoo biraaziqeen", "translation": "And We have made for you therein means of living and [for] those for whom you are not providers."}, {"ayah": 21, "translit": "Wa im min shai'in illaa 'indanaa khazaaa 'inuhoo wa maa nunazziluhooo illaa biqadarim ma'loom", "translation": "And there is not a thing but that with Us are its depositories, and We do not send it down except according to a known measure."}, {"ayah": 22, "translit": "Wa arsalnar riyaaha la waaqiha fa anzalnaa minas samaaa'i maaa'an fa asqai naakumoohu wa maaa antum lahoo bikhaazineen", "translation": "And We have sent the fertilizing winds and sent down water from the sky and given you drink from it. And you are not its retainers."}, {"ayah": 23, "translit": "Wa innnaa la nahnu nuhyee wa numeetu wa nahnul waarisoon", "translation": "And indeed, it is We who give life and cause death, and We are the Inheritor."}, {"ayah": 24, "translit": "Wa la qad 'alimnal mustaqdimeena minkum wa laqad 'alimnal mustaakhireen", "translation": "And We have already known the preceding [generations] among you, and We have already known the later [ones to come]."}, {"ayah": 25, "translit": "Wa inna Rabbaka Huwa yahshuruhum; innahoo Hakeem 'Aleem", "translation": "And indeed, your Lord will gather them; indeed, He is Wise and Knowing."}, {"ayah": 26, "translit": "Wa laqad khalaqnal insaana min salsaalim min hama im masnoon", "translation": "And We did certainly create man out of clay from an altered black mud."}, {"ayah": 27, "translit": "Waljaaanna khalaqnaahu min qablu min naaris samoom", "translation": "And the jinn We created before from scorching fire."}, {"ayah": 28, "translit": "Wa iz qaala Rabbuka lilmalaaa' ikati innee khaaliqum basharam min salsaalim min hama im masnoon", "translation": "And [mention, O Muhammad], when your Lord said to the angels, \"I will create a human being out of clay from an altered black mud."}, {"ayah": 29, "translit": "Fa izaa sawwaituhoo wa nafakhtu feehi mir roohee faqa'oo lahoo saajideen", "translation": "And when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration.\""}, {"ayah": 30, "translit": "Fasajadal malaaa'ikatu kulluhum ajma'oon", "translation": "So the angels prostrated - all of them entirely,"}, {"ayah": 31, "translit": "Illaaa ibleesa abaaa ai yakoona ma'as saajideen", "translation": "Except Iblees, he refused to be with those who prostrated."}, {"ayah": 32, "translit": "Qaala yaaa Ibleesu maa laka allaa takoona ma'as saajideen", "translation": "[Allah] said, O Iblees, what is [the matter] with you that you are not with those who prostrate?\""}, {"ayah": 33, "translit": "Qaala lam akul li asjuda libasharin khalaqtahoo min salsaalim min hama im masnoon", "translation": "He said, \"Never would I prostrate to a human whom You created out of clay from an altered black mud.\""}, {"ayah": 34, "translit": "Qaala fakhruj minhaa fa innaka rajeem", "translation": "[Allah] said, \"Then get out of it, for indeed, you are expelled."}, {"ayah": 35, "translit": "Wa inna 'alikal la'nata ilaa Yawmid Deen", "translation": "And indeed, upon you is the curse until the Day of Recompense.\""}, {"ayah": 36, "translit": "Qaala Rabbi fa anzirneee ilaa Yawmi yub'asoon", "translation": "He said, \"My Lord, then reprieve me until the Day they are resurrected.\""}, {"ayah": 37, "translit": "Qaala fa innaka minal munzareen", "translation": "[Allah] said, \"So indeed, you are of those reprieved"}, {"ayah": 38, "translit": "Ilaa Yawmil waqtil ma'loom", "translation": "Until the Day of the time well-known.\""}, {"ayah": 39, "translit": "Qaala Rabbi bimaaa aghwaitanee la uzayyinaana lahum fil ardi wa la ughwiyan nahum ajma'een", "translation": "[Iblees] said, \"My Lord, because You have put me in error, I will surely make [disobedience] attractive to them on earth, and I will mislead them all"}, {"ayah": 40, "translit": "Illaa 'ibaadaka minhumul mukhlaseen", "translation": "Except, among them, Your chosen servants.\""}, {"ayah": 41, "translit": "Qaala haaza Siraatun 'alaiya Mustaqeem", "translation": "[Allah] said, \"This is a path [of return] to Me [that is] straight."}, {"ayah": 42, "translit": "Inna 'ibaadee laisa laka 'alaihim sultaanun illaa manittaba'aka minal ghaaween", "translation": "Indeed, My servants - no authority will you have over them, except those who follow you of the deviators."}, {"ayah": 43, "translit": "Wa inna jahannama lamaw'iduhum ajma'een", "translation": "And indeed, Hell is the promised place for them all."}, {"ayah": 44, "translit": "Lahaa sab'atu abwaab; likulli baabim minhum juz'um maqsoom", "translation": "It has seven gates; for every gate is of them a portion designated.\""}, {"ayah": 45, "translit": "Innal muttaqeena fee Jannaatinw wa 'uyoon", "translation": "Indeed, the righteous will be within gardens and springs."}, {"ayah": 46, "translit": "Udkhuloohaa bisalaamin aamineen", "translation": "[Having been told], \"Enter it in peace, safe [and secure].\""}, {"ayah": 47, "translit": "Wa naza'naa ma fee sudoorihim min ghillin ikhwaanan 'alaa sururim mutaqaabileen", "translation": "And We will remove whatever is in their breasts of resentment, [so they will be] brothers, on thrones facing each other."}, {"ayah": 48, "translit": "Laa yamas suhum feehaa nasabunw wa maa hum minhaa bimukhrajeen", "translation": "No fatigue will touch them therein, nor from it will they [ever] be removed."}, {"ayah": 49, "translit": "Nabbi' 'ibaadeee annneee anal Ghafoorur Raheem", "translation": "[O Muhammad], inform My servants that it is I who am the Forgiving, the Merciful."}, {"ayah": 50, "translit": "Wa anna 'azaabee uwal 'azaabul aleem", "translation": "And that it is My punishment which is the painful punishment."}, {"ayah": 51, "translit": "Wa nabbi'hum 'an daifi Ibraaheem", "translation": "And inform them about the guests of Abraham,"}, {"ayah": 52, "translit": "Iz dakhaloo 'alaihi faqaaloo salaaman qaala innaa minkum wajiloon", "translation": "When they entered upon him and said, \"Peace.\" [Abraham] said, \"Indeed, we are fearful of you.\""}, {"ayah": 53, "translit": "Qaaloo la tawjal innaa nubashshiruka bighulaamin 'aleem", "translation": "[The angels] said, \"Fear not. Indeed, we give you good tidings of a learned boy.\""}, {"ayah": 54, "translit": "Qaala abashshartumoonee 'alaaa am massaniyal kibaru fabima tubashshiroon", "translation": "He said, \"Have you given me good tidings although old age has come upon me? Then of what [wonder] do you inform?\""}, {"ayah": 55, "translit": "Qaaloo bashsharnaaka bilhaqqi falaa takum minal qaaniteen", "translation": "They said, \"We have given you good tidings in truth, so do not be of the despairing.\""}, {"ayah": 56, "translit": "Qaala wa mai yaqnatu mir rahmati Rabbiheee illad daaaloon", "translation": "He said, \"And who despairs of the mercy of his Lord except for those astray?\""}, {"ayah": 57, "translit": "Qaala famaa khatbukum aiyuhal mursaloon", "translation": "[Abraham] said, \"Then what is your business [here], O messengers?\""}, {"ayah": 58, "translit": "Qaaloo innaaa ursilnaaa ilaa qawmim mujrimeen", "translation": "They said, \"Indeed, we have been sent to a people of criminals,"}, {"ayah": 59, "translit": "Illaaa Aala Loot; innaa lamunajjoohum ajma'een", "translation": "Except the family of Lot; indeed, we will save them all"}, {"ayah": 60, "translit": "Illam ra atahoo qaddarnaaa innahaa laminal ghaabireen", "translation": "Except his wife.\" Allah decreed that she is of those who remain behind."}, {"ayah": 61, "translit": "Falamma jaaa'a Aala Lootinil mursaloon", "translation": "And when the messengers came to the family of Lot,"}, {"ayah": 62, "translit": "Qaala innakum qawmum munkaroon", "translation": "He said, \"Indeed, you are people unknown.\""}, {"ayah": 63, "translit": "Qaaloo bal ji'naaka bimaa kaanoo feehi yamtaroon", "translation": "They said, \"But we have come to you with that about which they were disputing,"}, {"ayah": 64, "translit": "Wa atainaaka bilhaqqi wa innaa lasaadiqoon", "translation": "And we have come to you with truth, and indeed, we are truthful."}, {"ayah": 65, "translit": "Fa asri bi ahlika biqit'im minal laili wattabi' adbaarahum wa laa yaltafit minkum ahadunw wamdoo haisu tu'maroon", "translation": "So set out with your family during a portion of the night and follow behind them and let not anyone among you look back and continue on to where you are commanded.\""}, {"ayah": 66, "translit": "Wa qadainaaa ilaihi zaalikal amra anna daabira haaa'ulaaa'i maqtoo'um musbiheen", "translation": "And We conveyed to him [the decree] of that matter: that those [sinners] would be eliminated by early morning."}, {"ayah": 67, "translit": "Wa jaaa'a ahlul madeenati yastabshiroon", "translation": "And the people of the city came rejoicing."}, {"ayah": 68, "translit": "Qaala inna haaa'ulaaa'i daifee falaa tafdahoon", "translation": "[Lot] said, \"Indeed, these are my guests, so do not shame me."}, {"ayah": 69, "translit": "Wattaqul laaha wa laa tukhzoon", "translation": "And fear Allah and do not disgrace me.\""}, {"ayah": 70, "translit": "Qaalooo awalam nanhaka 'anil 'aalameen", "translation": "They said, \"Have we not forbidden you from [protecting] people?\""}, {"ayah": 71, "translit": "Qaala haaa'ulaaa'i banaateee in kuntum faa'ileen", "translation": "[Lot] said, \"These are my daughters - if you would be doers [of lawful marriage].\""}, {"ayah": 72, "translit": "La'amruka innahum lafee sakratihim ya'mahoon", "translation": "By your life, [O Muhammad], indeed they were, in their intoxication, wandering blindly."}, {"ayah": 73, "translit": "Fa akhazat humus saihatu mushriqeen", "translation": "So the shriek seized them at sunrise."}, {"ayah": 74, "translit": "Faja'alnaa 'aaliyahaa saafilahaa wa amtamaa 'alaihim hijaaratam min sjijjeel", "translation": "And We made the highest part [of the city] its lowest and rained upon them stones of hard clay."}, {"ayah": 75, "translit": "Inna fee zaalika la Aayaatil lilmutawassimeen", "translation": "Indeed in that are signs for those who discern."}, {"ayah": 76, "translit": "Wa innahaa labi sabeelim muqeem", "translation": "And indeed, those cities are [situated] on an established road."}, {"ayah": 77, "translit": "Inna fee zaalika la Aayatal lilmu'mineen", "translation": "Indeed in that is a sign for the believers."}, {"ayah": 78, "translit": "Wa in kaana Ashaabul Aikati lazaalimeen", "translation": "And the companions of the thicket were [also] wrongdoers."}, {"ayah": 79, "translit": "Fantaqamnaa minhum wa innahumaa labi imaamim mubeen", "translation": "So We took retribution from them, and indeed, both [cities] are on a clear highway."}, {"ayah": 80, "translit": "Wa laqad kazzaba ashaabul Hijril mursaleen", "translation": "And certainly did the companions of Thamud deny the messengers."}, {"ayah": 81, "translit": "Wa aatainaahum Aayaatinaa fakaanoo 'anhaa mu'rideen", "translation": "And We gave them Our signs, but from them they were turning away."}, {"ayah": 82, "translit": "Wa kaanoo yanhitoona minal jibaali buyootan aamineen", "translation": "And they used to carve from the mountains, houses, feeling secure."}, {"ayah": 83, "translit": "Fa akhazat humus saihatu musbiheen", "translation": "But the shriek seized them at early morning."}, {"ayah": 84, "translit": "Famaaa aghnaa 'anhum maa kaanoo yaksiboon", "translation": "So nothing availed them [from] what they used to earn."}, {"ayah": 85, "translit": "Wa maa khalaqnas samaawaati wal arda wa maa bainahumaaa illaa bilhaqq; wa innas Saa'ata la aatiyatun fasfahis safhal jameel", "translation": "And We have not created the heavens and earth and that between them except in truth. And indeed, the Hour is coming; so forgive with gracious forgiveness."}, {"ayah": 86, "translit": "Inna Rabbaka Huwal khallaaqul 'aleem", "translation": "Indeed, your Lord - He is the Knowing Creator."}, {"ayah": 87, "translit": "Wa laqad aatainaaka sab'am mnal masaanee wal Qur-aanal 'azeem", "translation": "And We have certainly given you, [O Muhammad], seven of the often repeated [verses] and the great Qur'an."}, {"ayah": 88, "translit": "Laa tamuddanna 'ainaika ilaa maa matta 'naa biheee azwaajam minhum wa laa tahzan 'alaihim wakhfid janaahaka lilmu 'mineen", "translation": "Do not extend your eyes toward that by which We have given enjoyment to [certain] categories of the disbelievers, and do not grieve over them. And lower your wing to the believers"}, {"ayah": 89, "translit": "Wa qul inneee anan nazeerul mubeen", "translation": "And say, \"Indeed, I am the clear warner\" -"}, {"ayah": 90, "translit": "Kamaaa anzalnaa 'alal muqtasimeen", "translation": "Just as We had revealed [scriptures] to the separators"}, {"ayah": 91, "translit": "Allazeena ja'alul Quraana'ideen", "translation": "Who have made the Qur'an into portions."}, {"ayah": 92, "translit": "Fawa Rabbika lanas'a lannahum ajma'een", "translation": "So by your Lord, We will surely question them all"}, {"ayah": 93, "translit": "'Ammaa kaanoo ya'maloon", "translation": "About what they used to do."}, {"ayah": 94, "translit": "Fasda' bimaa tu'maru wa a'rid anil mushrikeen", "translation": "Then declare what you are commanded and turn away from the polytheists."}, {"ayah": 95, "translit": "Innaa kafainaakal mustahzi'een", "translation": "Indeed, We are sufficient for you against the mockers"}, {"ayah": 96, "translit": "Allazeena yaj'aloona ma'al laahi ilaahan aakhar; fasawfa ya'lamoon", "translation": "Who make [equal] with Allah another deity. But they are going to know."}, {"ayah": 97, "translit": "Wa laqad na'lamu annak yadeequ sadruka bimaa yaqooloon", "translation": "And We already know that your breast is constrained by what they say."}, {"ayah": 98, "translit": "Fasbbih bihamdi Rabbika wa kum minas saajideen", "translation": "So exalt [Allah] with praise of your Lord and be of those who prostrate [to Him]."}, {"ayah": 99, "translit": "Wa'bud Rabbaka hattaa yaatiyakal yaqeen", "translation": "And worship your Lord until there comes to you the certainty (death)."}]}, {"num": 16, "name": "An-Nahl", "meaning": "The Bee", "verses": [{"ayah": 1, "translit": "Ataaa amrullaahi falaa tasta'jilooh; Subhaanahoo wa Ta'aalaa 'ammaa yushrikoon", "translation": "The command of Allah is coming, so be not impatient for it. Exalted is He and high above what they associate with Him."}, {"ayah": 2, "translit": "Yunazzilul malaaa 'ikata birroohi min amrihee 'alaa mai yashaaa'u min 'ibaadiheee an anzirooo annahoo laaa ilaaha illaaa ana fattaqoon", "translation": "He sends down the angels, with the inspiration of His command, upon whom He wills of His servants, [telling them], \"Warn that there is no deity except Me; so fear Me.\""}, {"ayah": 3, "translit": "Khalaqas samaawaati wal arda bilhaqq; Ta'aalaa 'ammaa yushrikoon", "translation": "He created the heavens and earth in truth. High is He above what they associate with Him."}, {"ayah": 4, "translit": "Khalaqal insaana min nutfatin fa izaa huwa khaseemum mubeen", "translation": "He created man from a sperm-drop; then at once, he is a clear adversary."}, {"ayah": 5, "translit": "Wal an 'amaa khalaqahaa; lakum feehaa dif'unw wa manaafi'u wa minhaa taakuloon", "translation": "And the grazing livestock He has created for you; in them is warmth and [numerous] benefits, and from them you eat."}, {"ayah": 6, "translit": "Wa lakum feehaa jamaalun heena tureehoona wa heena tasrahoon", "translation": "And for you in them is [the enjoyment of] beauty when you bring them in [for the evening] and when you send them out [to pasture]."}, {"ayah": 7, "translit": "Wa tahmilu asqaalakum ilaa baladil lam takoonoo baaligheehi illaa bishiqqil anfus; inna Rabbakum la Ra'oofur Raheem", "translation": "And they carry your loads to a land you could not have reached except with difficulty to yourselves. Indeed, your Lord is Kind and Merciful."}, {"ayah": 8, "translit": "Walkhaila wal bighaala wal hameera litarkaboohaa wa zeenah; wa yakhluqu maa laa ta'lamoon", "translation": "And [He created] the horses, mules and donkeys for you to ride and [as] adornment. And He creates that which you do not know."}, {"ayah": 9, "translit": "Wa 'alal laahi qasdus sabeeli wa minhaa jaaa'ir; wa law shaaa'a lahadaakum ajma'een", "translation": "And upon Allah is the direction of the [right] way, and among the various paths are those deviating. And if He willed, He could have guided you all."}, {"ayah": 10, "translit": "Huwal lazeee anzala minas samaaa'i maaa'al lakum minhu sharaabunw wa minhu shajarun feehi tuseemoon", "translation": "It is He who sends down rain from the sky; from it is drink and from it is foliage in which you pasture [animals]."}, {"ayah": 11, "translit": "Yumbitu lakum bihiz zar'a wazzaitoona wanna kheela wal-a'naaba wa min kullis samaraat, inna fee zaalika la Aayatal liqawminy yatafakkaroon", "translation": "He causes to grow for you thereby the crops, olives, palm trees, grapevines, and from all the fruits. Indeed in that is a sign for a people who give thought."}, {"ayah": 12, "translit": "Wa sakkhkhara lakumul laila wannahaara wash shamsa walqamara wannujoomu musakhkharaatum bi amrih; inna fee zaalika la Aayaatil liqawminy ya'qiloon", "translation": "And He has subjected for you the night and day and the sun and moon, and the stars are subjected by His command. Indeed in that are signs for a people who reason."}, {"ayah": 13, "translit": "Wa maa zara a lakum fil ardi mukhtalifan alwaanuh; inna fee zaalika la Aayatal liqawminy yazakkaroon", "translation": "And [He has subjected] whatever He multiplied for you on the earth of varying colors. Indeed in that is a sign for a people who remember."}, {"ayah": 14, "translit": "Wa Huwal lazee sakhkharal bahra litaakuloo minhu lahman tariyyanw wa tastakhrijoo minhu hilyatan talbasoonahaa wa taral fulka mawaakhira feehi wa litabtaghoo min fadlihee wa la'allakum tashkuroon", "translation": "And it is He who subjected the sea for you to eat from it tender meat and to extract from it ornaments which you wear. And you see the ships plowing through it, and [He subjected it] that you may seek of His bounty; and perhaps you will be grateful."}, {"ayah": 15, "translit": "Wa alqaa fil ardi rawaasiya an tameeda bikum wa anhaaranw wa sublulal la 'allakum tahtadoon", "translation": "And He has cast into the earth firmly set mountains, lest it shift with you, and [made] rivers and roads, that you may be guided,"}, {"ayah": 16, "translit": "Wa 'alaamaat; wa bin najmi hum yahtadoon", "translation": "And landmarks. And by the stars they are [also] guided."}, {"ayah": 17, "translit": "Afamany yakhluqu kamallaa yakhluq; afalaa tazak karoon", "translation": "Then is He who creates like one who does not create? So will you not be reminded?"}, {"ayah": 18, "translit": "Wa in ta'uddoo ni'matal laahi laa tuhsoohaa; innal laaha la Ghafoorur Raheem", "translation": "And if you should count the favors of Allah, you could not enumerate them. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 19, "translit": "Wallaahu ya'lamu maa tusirroona wa maa tu'linoon", "translation": "And Allah knows what you conceal and what you declare."}, {"ayah": 20, "translit": "Wallazeena yad'oona min doonil laahi laa yakhluqoona shai'anw wa hum yukhlaqoon", "translation": "And those they invoke other than Allah create nothing, and they [themselves] are created."}, {"ayah": 21, "translit": "Amwaatun ghairu ahyaaa'inw wa maa yash'uroona aiyaana yub'asoon (section 2)", "translation": "They are, [in fact], dead, not alive, and they do not perceive when they will be resurrected."}, {"ayah": 22, "translit": "Illahukum Ilaahunw Waahid; fallazeena laa yu'minoona bil Aakhirati quloobuhum munkiratunw wa hum mustakbiroon", "translation": "Your god is one God. But those who do not believe in the Hereafter - their hearts are disapproving, and they are arrogant."}, {"ayah": 23, "translit": "Laa jarama annal laaha ya'lamu maa yusirrona wa ma yu'linoon; innahoo laa yuhibbul mustakbireen", "translation": "Assuredly, Allah knows what they conceal and what they declare. Indeed, He does not like the arrogant."}, {"ayah": 24, "translit": "Wa izaa qeela lahum maazaaa anzala Rabbukum qaaloo asaateerul awwaleen", "translation": "And when it is said to them, \"What has your Lord sent down?\" They say, \"Legends of the former peoples,\""}, {"ayah": 25, "translit": "Liyahmilooo awzaarahum kaamilatany Yawmal Qiyaamati wa min awzaaril lazeena yudilloonahum bighairi 'ilm; alaa saaa'a maa yaziroon", "translation": "That they may bear their own burdens in full on the Day of Resurrection and some of the burdens of those whom they misguide without knowledge. Unquestionably, evil is that which they bear."}, {"ayah": 26, "translit": "Qad makaral lazeena min qablihim fa atal laahu bunyaa nahum minal qawaa'idi fakharra 'alaihimus saqfu min fawqihim wa ataahumul 'azaabu min haisu laa yash'uroon", "translation": "Those before them had already plotted, but Allah came at their building from the foundations, so the roof fell upon them from above them, and the punishment came to them from where they did not perceive."}, {"ayah": 27, "translit": "Summa Yawmal Qiyaamati yukhzeehim wa yaqoolu aina shurakaaa'iyal lazeena kuntum tushaaaqqoona feehim; qaalal lazeena ootul 'ilma innal khizyal Yawma wassooo'a 'alal kaafireen", "translation": "Then on the Day of Resurrection He will disgrace them and say, \"Where are My 'partners' for whom you used to oppose [the believers]?\" Those who were given knowledge will say, \"Indeed disgrace, this Day, and evil are upon the disbelievers\" -"}, {"ayah": 28, "translit": "Allazeena tatawaf faahu mul malaaa'ikatu zaalimeee anfusihim fa alqawus salama maa kunnaa na'malu min sooo'; balaaa innal laaha 'aleemum bimaa kuntum ta'maloon", "translation": "The ones whom the angels take in death [while] wronging themselves, and [who] then offer submission, [saying], \"We were not doing any evil.\" But, yes! Indeed, Allah is Knowing of what you used to do."}, {"ayah": 29, "translit": "Fadkhulooo abwaaba jahannama khaalideena feeha falabi'sa maswal mutakab bireen", "translation": "So enter the gates of Hell to abide eternally therein, and how wretched is the residence of the arrogant."}, {"ayah": 30, "translit": "Wa qeela lillazeenat taqaw maazaaa anzala Rabbukum; qaaloo khairaa; lillazeena absanoo fee haazihid dunyaa hasanah; wa la Daarul Aakhirati khair; wa lani'ma daarul muttaqeen", "translation": "And it will be said to those who feared Allah, \"What did your Lord send down?\" They will say, \"[That which is] good.\" For those who do good in this world is good; and the home of the Hereafter is better. And how excellent is the home of the righteous -"}, {"ayah": 31, "translit": "Jannaatu 'Adniny yadkhuloonahaa tajree min tahtihal anhaaru lahum feehaa maa yashaaa'oon; kazaalika yajzil laahul muttaqeen", "translation": "Gardens of perpetual residence, which they will enter, beneath which rivers flow. They will have therein whatever they wish. Thus does Allah reward the righteous -"}, {"ayah": 32, "translit": "Allazeena tatawaf faahumul malaaa'ikatu taiyibeena yaqooloona salaamun 'alai kumud khulul Jannata bimaa kuntum ta'maloon", "translation": "The ones whom the angels take in death, [being] good and pure; [the angels] will say, \"Peace be upon you. Enter Paradise for what you used to do.\""}, {"ayah": 33, "translit": "Hal yanzuroona illaaa an taatiyahumul malaaa'ikatu aw yaatiya amru Rabbik; kazaalika fa'alal lazeena min qablihim; wa maa zalamahumul laahu wa laakin kaanoo anfusahum yazlimoon", "translation": "Do the disbelievers await [anything] except that the angels should come to them or there comes the command of your Lord? Thus did those do before them. And Allah wronged them not, but they had been wronging themselves."}, {"ayah": 34, "translit": "Fa asaabahum saiyi aatu maa 'amiloo wa haaqa bihim maa kaano bihee yastahzi'oon", "translation": "So they were struck by the evil consequences of what they did and were enveloped by what they used to ridicule."}, {"ayah": 35, "translit": "Wa qaalal lazeena ashrakoo law shaaa'al laahu ma 'abadnaa min doonihee min shai'in nahnu wa laaa aabaaa'unaa wa laa harramnaa min doonihee min shai'; kazaalika fa'alal lazeena min qablihim fahal 'alar Rusuli illal balaaghul mubeen", "translation": "And those who associate others with Allah say, \"If Allah had willed, we would not have worshipped anything other than Him, neither we nor our fathers, nor would we have forbidden anything through other than Him.\" Thus did those do before them. So is there upon the messengers except [the duty of] clear notification?"}, {"ayah": 36, "translit": "Wa laqad ba'asnaa fee kulli ummatir Rasoolan ani'budul laaha wajtanibut Taaghoota faminhum man hadal laahu wa minhum man haqqat 'alaihid dalaalah; faseeroo fil ardi fanzuroo kaifa kaana 'aaqibatul mukazzibeen", "translation": "And We certainly sent into every nation a messenger, [saying], \"Worship Allah and avoid Taghut.\" And among them were those whom Allah guided, and among them were those upon whom error was [deservedly] decreed. So proceed through the earth and observe how was the end of the deniers."}, {"ayah": 37, "translit": "In tahris 'alaa hudaahum fa innal laaha laa yahdee mai yudillu wa maa lahum min naasireen", "translation": "[Even] if you should strive for their guidance, [O Muhammad], indeed, Allah does not guide those He sends astray, and they will have no helpers."}, {"ayah": 38, "translit": "Wa aqsamoo billaahi jahda aimaanihim laa yab'asul laahu mai yamoot; balaa wa'dan 'alaihi haqqanw wa laakinna aksaran naasi laa ya'lamoon", "translation": "And they swear by Allah their strongest oaths [that] Allah will not resurrect one who dies. But yes - [it is] a true promise [binding] upon Him, but most of the people do not know."}, {"ayah": 39, "translit": "Liyubaiyina lahumul lazee yakhtalifoona feehi wa liya'lamal lazeena kafarooo annahum kaanoo kaazibeen", "translation": "[It is] so He will make clear to them [the truth of] that wherein they differ and so those who have disbelieved may know that they were liars."}, {"ayah": 40, "translit": "Innamaa qawlunaa lisha y'in izaa aradnaahu an naqoola lahoo kun fa yakoon", "translation": "Indeed, Our word to a thing when We intend it is but that We say to it, \"Be,\" and it is."}, {"ayah": 41, "translit": "Wallazeena haajaroo fil laahi mim ba'di maa zulimoo lanubawwi' annahum fiddunyaa hasanatanw wa la ajrul Aakhirati akbar; law kaanoo ya'lamoon", "translation": "And those who emigrated for [the cause of] Allah after they had been wronged - We will surely settle them in this world in a good place; but the reward of the Hereafter is greater, if only they could know."}, {"ayah": 42, "translit": "Allazeena sabaroo wa 'alaa Rabbihim yatawak kaloon", "translation": "[They are] those who endured patiently and upon their Lord relied."}, {"ayah": 43, "translit": "Wa maaa arsalnaa min qablika illaa rijaalan nooheee ilaihim; fas'alooo ahlaz zikri in kuntum laa ta'lamoon", "translation": "And We sent not before you except men to whom We revealed [Our message]. So ask the people of the message if you do not know."}, {"ayah": 44, "translit": "Bilbaiyinaati waz Zubur; wa anzalnaaa ilaikaz Zikra litubaiyina linnaasi maa nuzzila ilaihim wa la'allahum yatafakkaroon", "translation": "[We sent them] with clear proofs and written ordinances. And We revealed to you the message that you may make clear to the people what was sent down to them and that they might give thought."}, {"ayah": 45, "translit": "Afa aminal lazeena makarus saiyi aati ai yakhsifal laahu bihimul arda aw yaaa tiyahumul 'azaabu min haisu laa yash'uroon", "translation": "Then, do those who have planned evil deeds feel secure that Allah will not cause the earth to swallow them or that the punishment will not come upon them from where they do not perceive?"}, {"ayah": 46, "translit": "Aw yaakhuzahum fee taqallubihim famaa hum bi mu'jizeen", "translation": "Or that He would not seize them during their [usual] activity, and they could not cause failure?"}, {"ayah": 47, "translit": "Aw yaakhuzahum 'alaa takhawwuf; fa inna Rabbakum la Ra'oofur Raheem", "translation": "Or that He would not seize them gradually [in a state of dread]? But indeed, your Lord is Kind and Merciful."}, {"ayah": 48, "translit": "Awa lam yaraw ilaa maa khalaqal laahu min shai'iny-yatafaiya'u zilaaluhoo 'anil yameeni washshamaaa' ili sujjadal lillaahi wa hum daakhiroon", "translation": "Have they not considered what things Allah has created? Their shadows incline to the right and to the left, prostrating to Allah, while they are humble."}, {"ayah": 49, "translit": "Wa lillaahi yasjudu maa fis samaawaati wa maa fil ardi min daaabbatinw walma laaa'ikatu wa hum laa yastakbiroon", "translation": "And to Allah prostrates whatever is in the heavens and whatever is on the earth of creatures, and the angels [as well], and they are not arrogant."}, {"ayah": 50, "translit": "yakhaafoona Rabbahum min fawqihim wa yaf'aloona maa yu'maroon (section 6)", "translation": "They fear their Lord above them, and they do what they are commanded."}, {"ayah": 51, "translit": "Wa qaalal laahu laa tatta khizooo ilaahainis naini innamaa Huwa Ilaahunw Waahid; fa iyyaaya farhaboon", "translation": "And Allah has said, \"Do not take for yourselves two deities. He is but one God, so fear only Me.\""}, {"ayah": 52, "translit": "Wa lahoo maa fis samaawaati wal ardi wa lahud deenu waasibaa; afaghairal laahi tattaqoon", "translation": "And to Him belongs whatever is in the heavens and the earth, and to Him is [due] worship constantly. Then is it other than Allah that you fear?"}, {"ayah": 53, "translit": "Wa maa bikum minni'matin faminal laahi summa izaa massakumud durru fa ilaihi taj'aroon", "translation": "And whatever you have of favor - it is from Allah. Then when adversity touches you, to Him you cry for help."}, {"ayah": 54, "translit": "Summaa izaa kashafad durra 'ankum izaa fareequm minkum bi Rabbihim yushrikoon", "translation": "Then when He removes the adversity from you, at once a party of you associates others with their Lord"}, {"ayah": 55, "translit": "Liyakfuroo bimaa aatainaahum; fatamatta'oo, faswfa ta'lamoon", "translation": "So they will deny what We have given them. Then enjoy yourselves, for you are going to know."}, {"ayah": 56, "translit": "Wa yaj'aloona limaa laa ya'lamoona naseebam mimmaa razaqnnaahum; tallaahi latus'alunaa 'ammaa kuntum taftaroon", "translation": "And they assign to what they do not know a portion of that which We have provided them. By Allah, you will surely be questioned about what you used to invent."}, {"ayah": 57, "translit": "Wa yaj'aloona lillaahil banaati Subhaanahoo wa lahum maa yashtahoon", "translation": "And they attribute to Allah daughters - exalted is He - and for them is what they desire."}, {"ayah": 58, "translit": "Wa izaa bushshira ahaduhum bil unsaa zalla wajhuhoo muswaddanw wa huwa kazeem", "translation": "And when one of them is informed of [the birth of] a female, his face becomes dark, and he suppresses grief."}, {"ayah": 59, "translit": "yatawaaraa minal qawmimin sooo'i maa bushshira bih; a-yumsikuhoo 'alaa hoonin am yadussuhoo fit turaab; alaa saaa'a maa yahkumoon", "translation": "He hides himself from the people because of the ill of which he has been informed. Should he keep it in humiliation or bury it in the ground? Unquestionably, evil is what they decide."}, {"ayah": 60, "translit": "Lillazeena laa yu'minoona bil Aakhirati masalus saw'i wa lillaahil masalul a'laa; wa Huwal 'Azeezul Hakeem", "translation": "For those who do not believe in the Hereafter is the description of evil; and for Allah is the highest attribute. And He is Exalted in Might, the Wise."}, {"ayah": 61, "translit": "Wa law yu'aakhizul laahun naasa bizulminhim maa taraka 'alaihaa min daaabbatinw wa laakiny yu'akhkhiruhum ilaaa ajalim musamman fa izaa jaaa'a ajaluhum laa yastaakhiroona saa'atanw wa laa yastaqdimoon", "translation": "And if Allah were to impose blame on the people for their wrongdoing, He would not have left upon the earth any creature, but He defers them for a specified term. And when their term has come, they will not remain behind an hour, nor will they precede [it]."}, {"ayah": 62, "translit": "Wa yaj'aloona lillaahi maa yakrahoona wa tasifu alsinatuhumul kaziba anna lahumul husnaa laa jarama anna lahumun Naara wa annahum mufratoon", "translation": "And they attribute to Allah that which they dislike, and their tongues assert the lie that they will have the best [from Him]. Assuredly, they will have the Fire, and they will be [therein] neglected."}, {"ayah": 63, "translit": "Tallaahi laqad arsalnaaa ilaaa umamim min qablika fazayyana lahumush Shaitaanu a'maalahum fahuwa waliyyuhumul yawma wa lahum 'azaabun aleem", "translation": "By Allah, We did certainly send [messengers] to nations before you, but Satan made their deeds attractive to them. And he is the disbelievers' ally today [as well], and they will have a painful punishment."}, {"ayah": 64, "translit": "Wa maaa anzalnaa 'alaikal Kitaaba illaa litubaiyina lahumul lazikh talafoo feehi wa hudanw wa rahmatal liqawminy yu'minoon", "translation": "And We have not revealed to you the Book, [O Muhammad], except for you to make clear to them that wherein they have differed and as guidance and mercy for a people who believe."}, {"ayah": 65, "translit": "Wallaahu anzala minas samaaa'i maaa'an fa ahyaa bihil arda ba'da mawtihaa; inna fee zaalika la aayatal liqaw miny yasma'oon", "translation": "And Allah has sent down rain from the sky and given life thereby to the earth after its lifelessness. Indeed in that is a sign for a people who listen."}, {"ayah": 66, "translit": "Wa inna lakum fil an'aami la'ibrah; nusqeekum mimmmaa fee butoonihee mim baini farsinw wa damil labanann khaalisan saaa'ighallish shaaribeen", "translation": "And indeed, for you in grazing livestock is a lesson. We give you drink from what is in their bellies - between excretion and blood - pure milk, palatable to drinkers."}, {"ayah": 67, "translit": "Wa min samaraatin nakheeli wal a'nnaabi tattakhizoona minhu sakaranw wa rizqann hasanaa; inna fee zaalika la Aayatal liqawminy ya'qiloon", "translation": "And from the fruits of the palm trees and grapevines you take intoxicant and good provision. Indeed in that is a sign for a people who reason."}, {"ayah": 68, "translit": "Wa awhaa Rabbuka ilannnabli anit takhizee minal jabaali buyootanw wa minash shajari wa mimmaa ya'rishoon", "translation": "And your Lord inspired to the bee, \"Take for yourself among the mountains, houses, and among the trees and [in] that which they construct."}, {"ayah": 69, "translit": "Summma kulee min kullis samaraati faslukee subula Rabbiki zululaa; yakhruju mim butoonihaa sharaabum mukh talifun alwaanuhoo feehi shifaaa'ul linnaas, innna fee zaalika la Aayatal liqawminy yatafakkaroon", "translation": "Then eat from all the fruits and follow the ways of your Lord laid down [for you].\" There emerges from their bellies a drink, varying in colors, in which there is healing for people. Indeed in that is a sign for a people who give thought."}, {"ayah": 70, "translit": "Wallaahu khalaqakum suma tatawaffaakum; wa minkum many-yuradu ilaaa arzalil 'umuri likai laa ya'lama ba'da 'ilmin shai'aa; innal laaha 'Aleemun Qadeer", "translation": "And Allah created you; then He will take you in death. And among you is he who is reversed to the most decrepit [old] age so that he will not know, after [having had] knowledge, a thing. Indeed, Allah is Knowing and Competent."}, {"ayah": 71, "translit": "Wallaahu faddala ba'dakum 'alaa ba'din fir rizq; famal lazeena fuddiloo biraaaddee rizqihim 'alaa maa malakat aimaanuhum fahum feehi sawaaa'; afabini'matil laahi yajhadoon", "translation": "And Allah has favored some of you over others in provision. But those who were favored would not hand over their provision to those whom their right hands possess so they would be equal to them therein. Then is it the favor of Allah they reject?"}, {"ayah": 72, "translit": "Wallaahu ja'ala lakum min anfusikum azwaajanw wa ja'ala lakum min azwaajikum baneena wa hafadatanw wa razaqakum minat yaiyibaat; afabil baatili yu'minoona wa bini'matil laahi hum yakkfuroon", "translation": "And Allah has made for you from yourselves mates and has made for you from your mates sons and grandchildren and has provided for you from the good things. Then in falsehood do they believe and in the favor of Allah they disbelieve?"}, {"ayah": 73, "translit": "Wa ya'budoona min doonil laahi maa laa yamliku lahum rizqam minas samaawaati wal ardi shai'anw wa laa yastatee'oon", "translation": "And they worship besides Allah that which does not possess for them [the power of] provision from the heavens and the earth at all, and [in fact], they are unable."}, {"ayah": 74, "translit": "Falaa tadriboo lillaahil amsaal; innal laaha ya'lamu wa antum laa ta'lamoon", "translation": "So do not assert similarities to Allah. Indeed, Allah knows and you do not know."}, {"ayah": 75, "translit": "Darabal laahu masalan 'abdam mammlookal laa yaqdiru 'alaa shai'inw wa marrazaqnaahu mminnaa rizqan hasanan fahuwa yunfiqu minhu sirranw wa jahra; hal yasta-woon; alhamdu lillaah; bal aksaruhum laa ya'lamoon", "translation": "Allah presents an example: a slave [who is] owned and unable to do a thing and he to whom We have provided from Us good provision, so he spends from it secretly and publicly. Can they be equal? Praise to Allah! But most of them do not know."}, {"ayah": 76, "translit": "Wa darabal laahu masalar rajulaini ahaduhumaaa abkamu laa yaqdiru 'alaa shai'inw wa huwa kallun 'alaa mawlaahu ainamaa yuwajjihhu laa yaati bikhairin hal yastawee huwa wa many-yaamuru bil'adli wa huwa 'alaa Siraatim MMustaqeem", "translation": "And Allah presents an example of two men, one of them dumb and unable to do a thing, while he is a burden to his guardian. Wherever he directs him, he brings no good. Is he equal to one who commands justice, while he is on a straight path?"}, {"ayah": 77, "translit": "Wa lillaahi ghaibus samaawaati wal ard; wa maaa amrus Saa'ati illaa kalamhil basari aw huwa aqrab; innal laaha 'alaaa kulli shai'in Qadeer", "translation": "And to Allah belongs the unseen [aspects] of the heavens and the earth. And the command for the Hour is not but as a glance of the eye or even nearer. Indeed, Allah is over all things competent."}, {"ayah": 78, "translit": "Wallaahu akhrajakum mim butooni ummahaatikum laa ta'lamoona shai'anw wa ja'ala lakumus sam'a wal absaara wal af'idata la'allakum tashkuroon", "translation": "And Allah has extracted you from the wombs of your mothers not knowing a thing, and He made for you hearing and vision and intellect that perhaps you would be grateful."}, {"ayah": 79, "translit": "Alam yaraw ilat tairi musakhkharaatin fee jawwis samaaa'i maa yumsikuhunna illal laah; inna fee zaalika la Aayaatil liqawminy yu'minoon", "translation": "Do they not see the birds controlled in the atmosphere of the sky? None holds them up except Allah. Indeed in that are signs for a people who believe."}, {"ayah": 80, "translit": "Wallaahu ja'ala lakum min juloodil an'aami buyootan tastakhif foonahaa yawma za'nikum wa yawma iqaamatikum wa min aswaafihaa wa awbaarihaa wa ash'aarihaaa asaasanw wa mataa'an ilaa been", "translation": "And Allah has made for you from your homes a place of rest and made for you from the hides of the animals tents which you find light on your day of travel and your day of encampment; and from their wool, fur and hair is furnishing and enjoyment for a time."}, {"ayah": 81, "translit": "Wallaahu ja'ala lakum mimmaa khalaqa zilaalanw wa ja'ala lakum minal jibaali aknaananw wa ja'ala lakum saraabeela taqeekumul harra wa saraabeela taqeekum baasakum; kazaalika yutimmu ni'matahoo alaikum la'allakum tuslimoon", "translation": "And Allah has made for you, from that which He has created, shadows and has made for you from the mountains, shelters and has made for you garments which protect you from the heat and garments which protect you from your [enemy in] battle. Thus does He complete His favor upon you that you might submit [to Him]."}, {"ayah": 82, "translit": "Fa in tawallaw fa innamaa 'alaikal balaaghul mubeen", "translation": "But if they turn away, [O Muhammad] - then only upon you is [responsibility for] clear notification."}, {"ayah": 83, "translit": "Ya'rifoona ni'matal laahi summa yunkiroonahaa wa aksaruhumul kaafiroon", "translation": "They recognize the favor of Allah; then they deny it. And most of them are disbelievers."}, {"ayah": 84, "translit": "Wa yawma nab'asu min kulli ummatin shaheedan summa laa yu'zanu lillazeena kafaroo wa laa hum yusta'taboon", "translation": "And [mention] the Day when We will resurrect from every nation a witness. Then it will not be permitted to the disbelievers [to apologize or make excuses], nor will they be asked to appease [Allah]."}, {"ayah": 85, "translit": "Wa izaa ra al lazeena zalamul 'azaaba falaa yukhaf fafu 'anhum wa laa hum yunzaroon", "translation": "And when those who wronged see the punishment, it will not be lightened for them, nor will they be reprieved."}, {"ayah": 86, "translit": "Wa izaa ra al lazeena ashrakoo shurakaaa'ahum qaaloo Rabbana haaa'ulaaa'i shurakaaa'unal lazeena kunnaa nad'oo min doonika fa alqaw ilaihimul qawla innakum lakaaziboon", "translation": "And when those who associated others with Allah see their \"partners,\" they will say,\" Our Lord, these are our partners [to You] whom we used to invoke besides You.\" But they will throw at them the statement, \"Indeed, you are liars.\""}, {"ayah": 87, "translit": "Wa alqaw ilal laahi yawma'izinis salama wa dalla 'anhum maa kaanoo yaftaroon", "translation": "And they will impart to Allah that Day [their] submission, and lost from them is what they used to invent."}, {"ayah": 88, "translit": "Allazeena kafaroo wa saddoo 'an sabeelil laahi zidnaahum 'azaaban fawqal 'azaabi bimaa kaanoo yufsidoon", "translation": "Those who disbelieved and averted [others] from the way of Allah - We will increase them in punishment over [their] punishment for what corruption they were causing."}, {"ayah": 89, "translit": "Wa yawma nab'asu fee kulli ummmatin shaheedan 'alaihim min anfusihim wa ji'naa bika shaheedan 'alaa haaa'ulaaa'; wa nazzalnaa 'alaikal Kitaaba tibyaanal likulli shai'inw wa hudanw wa rahmatanw wa bushraa lilmuslimeen", "translation": "And [mention] the Day when We will resurrect among every nation a witness over them from themselves. And We will bring you, [O Muhammad], as a witness over your nation. And We have sent down to you the Book as clarification for all things and as guidance and mercy and good tidings for the Muslims."}, {"ayah": 90, "translit": "Innal laaha yaamaru bil 'adli wal ihsaani wa eetaaa'i zil qurbaa wa yanhaa 'anil fahshaaa'i wal munkari walbagh-i' ya'izukum la'allakum tazakkkaroon", "translation": "Indeed, Allah orders justice and good conduct and giving to relatives and forbids immorality and bad conduct and oppression. He admonishes you that perhaps you will be reminded."}, {"ayah": 91, "translit": "Wa awfoo bi Ahdil laahi izaa 'aahattum wa laa tanqudul aimaana ba'da tawkeedihaa wa qad ja'altumul laaha 'alaikum kafeelaa; innal laaha ya'lamu maa taf'aloon", "translation": "And fulfill the covenant of Allah when you have taken it, [O believers], and do not break oaths after their confirmation while you have made Allah, over you, a witness. Indeed, Allah knows what you do."}, {"ayah": 92, "translit": "Wa laa takoonoo kallatee naqadat ghazlahaa mim ba'di quwwatin ankaasaa; tattakhizoona aimaanakum dakhlalam bainakum an takoona ummatun hiya arbaa min ummah; innnamaa yablookumul laahu bih; wa la yubaiyinanna lakum yawmal Qiyaamati maa kuntum fee takhtalifoon", "translation": "And do not be like she who untwisted her spun thread after it was strong [by] taking your oaths as [means of] deceit between you because one community is more plentiful [in number or wealth] than another community. Allah only tries you thereby. And He will surely make clear to you on the Day of Resurrection that over which you used to differ."}, {"ayah": 93, "translit": "Wa law shaaa'al laahu laja'alakum ummmatanw waahidatanw wa laakiny yudillu many-yashaaa'u wa yahdee many-yashaaa'; wa latus'alunna 'ammaa kuntum ta'maloon", "translation": "And if Allah had willed, He could have made you [of] one religion, but He causes to stray whom He wills and guides whom He wills. And you will surely be questioned about what you used to do."}, {"ayah": 94, "translit": "Wa laa tattakhizooo aimaanakum dakhalam bainakum ftazilla qadamum ba'da subootihaa wa tazooqus sooo'a bimmaa sadattum 'an sabeelil laahi wa lakum 'azaabun 'azeem", "translation": "And do not take your oaths as [means of] deceit between you, lest a foot slip after it was [once] firm, and you would taste evil [in this world] for what [people] you diverted from the way of Allah, and you would have [in the Hereafter] a great punishment."}, {"ayah": 95, "translit": "Wa laa tashtaroo bi 'ahdil laahi samanan qaleelaa; innamaa 'indal laahi huwa khairul lakum in kuntum ta'lamoon", "translation": "And do not exchange the covenant of Allah for a small price. Indeed, what is with Allah is best for you, if only you could know."}, {"ayah": 96, "translit": "maa 'indakum yanfadu wa maa 'indal laahi baaq; wa lanajziyannal lazeena sabarooo ajjrahum bi ahsani maa kaanoo ya'maloon", "translation": "Whatever you have will end, but what Allah has is lasting. And We will surely give those who were patient their reward according to the best of what they used to do."}, {"ayah": 97, "translit": "Man 'amila saaliham min zakarin aw unsaa wa huwa mu'minun falanuhyiyannahoo hayaatan taiiyibatanw wa lanajzi yannnahum ajrahum bi ahsani maa kaanoo ya'maloon", "translation": "Whoever does righteousness, whether male or female, while he is a believer - We will surely cause him to live a good life, and We will surely give them their reward [in the Hereafter] according to the best of what they used to do."}, {"ayah": 98, "translit": "Fa izaa qara tal Quraana fasta'iz billaahi minashh Shai taanir rajeem", "translation": "So when you recite the Qur'an, [first] seek refuge in Allah from Satan, the expelled [from His mercy]."}, {"ayah": 99, "translit": "Innahoo laisa lahoo sultaanun 'alal lazeena aamanoo wa 'alaa Rabbihim yatawakkaloon", "translation": "Indeed, there is for him no authority over those who have believed and rely upon their Lord."}, {"ayah": 100, "translit": "Innnamaa sultaanuhoo 'alal lazeena yatawallawnahoo wallazeena hum bihee mushrikoon", "translation": "His authority is only over those who take him as an ally and those who through him associate others with Allah."}, {"ayah": 101, "translit": "Wa izaa baddalnaaa Aayatam makaana Aayatinw wal laahu a'lamu bimaa yunazzilu qaalooo innamaa anta muftar; bal aksaruhum laa ya'lamoon", "translation": "And when We substitute a verse in place of a verse - and Allah is most knowing of what He sends down - they say, \"You, [O Muhammad], are but an inventor [of lies].\" But most of them do not know."}, {"ayah": 102, "translit": "Qul nazzalahoo Roohul Qudusi mir Rabbika bilhaqqi liyusabbital lazeena aamanoo wa hudanw wa bushraa lilmuslimeen", "translation": "Say, [O Muhammad], \"The Pure Spirit has brought it down from your Lord in truth to make firm those who believe and as guidance and good tidings to the Muslims.\""}, {"ayah": 103, "translit": "Wa laqad na'lamu annahum yaqooloona innamaa yu'allimuhoo bashar; lisaanul lazee yulhidoona ilaihi a'ja miyyunw wa haaza lisaanun 'Arabiyyum mubeen", "translation": "And We certainly know that they say, \"It is only a human being who teaches the Prophet.\" The tongue of the one they refer to is foreign, and this Qur'an is [in] a clear Arabic language."}, {"ayah": 104, "translit": "Innal lazeena laa yu'minoona bi Aayaatil laahi laa yahdehimul laahu wa lahum 'azaabun aleem", "translation": "Indeed, those who do not believe in the verses of Allah - Allah will not guide them, and for them is a painful punishment."}, {"ayah": 105, "translit": "Innamaa yaftaril kazibal lazeena laa yu'minoona bi Aayaatil laahi wa ulaaa'ika humul kaaziboon", "translation": "They only invent falsehood who do not believe in the verses of Allah, and it is those who are the liars."}, {"ayah": 106, "translit": "man kafara billaahi mim ba'di eemaanihee illaa man ukriha wa qalbuhoo mutmma'innum bil eemaani wa laakim man sharaha bilkufri sadran fa'alaihim ghadabum minal laahi wa lahum 'azaabun 'azeem", "translation": "Whoever disbelieves in Allah after his belief... except for one who is forced [to renounce his religion] while his heart is secure in faith. But those who [willingly] open their breasts to disbelief, upon them is wrath from Allah, and for them is a great punishment;"}, {"ayah": 107, "translit": "Zaalika bi annahumus tahabbul hayaatad dunyaa 'alal Aakhirati wa annal laaha laa yahdil qawmal kaafireen", "translation": "That is because they preferred the worldly life over the Hereafter and that Allah does not guide the disbelieving people."}, {"ayah": 108, "translit": "Ulaaa'ikal lazeena taba'al laahu 'alaa quloobihim wa sam'ihim wa absaarihim wa ulaaa'ika humul ghaafiloon", "translation": "Those are the ones over whose hearts and hearing and vision Allah has sealed, and it is those who are the heedless."}, {"ayah": 109, "translit": "Laa jarama annnahum fil Aakhirati humul khassiroon", "translation": "Assuredly, it is they, in the Hereafter, who will be the losers."}, {"ayah": 110, "translit": "Summa inna Rabbaka lillazeena haajaroo mim ba'dimaa futinoo summma jaahadoo wa sabaroo inna Rabbaka mim ba'dihaa la Ghafoorur Raheem (section 14)", "translation": "Then, indeed your Lord, to those who emigrated after they had been compelled [to renounce their religion] and thereafter fought [for the cause of Allah] and were patient - indeed, your Lord, after that, is Forgiving and Merciful"}, {"ayah": 111, "translit": "Yawma taatee kullu nafsin tujaadilu 'an nafsihaa wa tuwaffaa kullu nafsim maa 'amilat wa hum laa yuzlamoon", "translation": "On the Day when every soul will come disputing for itself, and every soul will be fully compensated for what it did, and they will not be wronged."}, {"ayah": 112, "translit": "Wa darabal laahu masalan qaryatan kaanat aaminatam mutma'innatany yaaateehaa rizquhaa rghadam min kulli makaanin fakafarat bi an'umil laahi fa azaaqahal laahu libaasal joo'i walkhawfi bimaa kaanoo yasna'oon", "translation": "And Allah presents an example: a city which was safe and secure, its provision coming to it in abundance from every location, but it denied the favors of Allah. So Allah made it taste the envelopment of hunger and fear for what they had been doing."}, {"ayah": 113, "translit": "Wa laqad jaaa'ahum Rasoolum minhum fakazzaboohu fa akhazahumul 'azaabu wa hum zaalimoon", "translation": "And there had certainly come to them a Messenger from among themselves, but they denied him; so punishment overtook them while they were wrongdoers."}, {"ayah": 114, "translit": "Fakuloo mimmaa razaqa kumul laahu halaalan taiyibanw washkuroo ni'matal laahi in kuntum iyyaahu ta'budoon", "translation": "Then eat of what Allah has provided for you [which is] lawful and good. And be grateful for the favor of Allah, if it is [indeed] Him that you worship."}, {"ayah": 115, "translit": "Innamaa harrma 'alai kumul maitata waddama wa lahmal khinzeeri wa maaa uhilla lighairil laahi bihee famanid turra ghaira baaghinw wa laa 'aadin fa innal laaha Ghafoorur Raheem", "translation": "He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit] - then indeed, Allah is Forgiving and Merciful."}, {"ayah": 116, "translit": "Wa laa taqooloo limaa tasifu alsinatukumul kaziba haaza halaalunw wa haazaa haraamul litaftaroo 'alal laahil kazib; innal lazeena yaftaroona 'alal laahil kaziba laa yuflihoon", "translation": "And do not say about what your tongues assert of untruth, \"This is lawful and this is unlawful,\" to invent falsehood about Allah. Indeed, those who invent falsehood about Allah will not succeed."}, {"ayah": 117, "translit": "Mata'un qaleelunw wa lahum 'azaabun aleem", "translation": "[It is but] a brief enjoyment, and they will have a painful punishment."}, {"ayah": 118, "translit": "Wa 'alal lazeena haadoo harramnaa ma qasasnaa 'alaika min qablu wa maa zalamanaahum wa laakin kaanoo anfusahum wa laakin kaanoo anfusahum yazlimoon", "translation": "And to those who are Jews We have prohibited that which We related to you before. And We did not wrong them [thereby], but they were wronging themselves."}, {"ayah": 119, "translit": "Summma inna Rabbaka lillazeena 'amilus sooo'a bijahaalatin summa taaboo mim ba'di zaaalika wa aslahoo inna Rabbaka mim ba'dihaa la Ghafoorur Raheem", "translation": "Then, indeed your Lord, to those who have done wrong out of ignorance and then repent after that and correct themselves - indeed, your Lord, thereafter, is Forgiving and Merciful."}, {"ayah": 120, "translit": "Inna Ibraaheema kaana ummatan qaanital lillaahi Haneefanw wa lam yakuminal mushrikeen", "translation": "Indeed, Abraham was a [comprehensive] leader, devoutly obedient to Allah, inclining toward truth, and he was not of those who associate others with Allah."}, {"ayah": 121, "translit": "Shaakiral li an'umih; ijtabaahu wa hadaahu ilaa Siraatim Muustaqeem", "translation": "[He was] grateful for His favors. Allah chose him and guided him to a straight path."}, {"ayah": 122, "translit": "Wa aatainaahu fid dunyaa hasanah; wa innahoo fil Aakhirati laminas saaliheen", "translation": "And We gave him good in this world, and indeed, in the Hereafter he will be among the righteous."}, {"ayah": 123, "translit": "Summma awhainaa ilaika anit tabi' Millata Ibraaheema haneefaa; wa maa kaana minal mushrikeen", "translation": "Then We revealed to you, [O Muhammad], to follow the religion of Abraham, inclining toward truth; and he was not of those who associate with Allah."}, {"ayah": 124, "translit": "Innnamaa ju'ilas Sabtu 'alal lazeenakhtalafoo feeh; wa inna Rabbaka la yahkumu bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon", "translation": "The sabbath was only appointed for those who differed over it. And indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ."}, {"ayah": 125, "translit": "Ud'u ilaa sabeeli Rabbika bilhikmati walmaw 'izatil hasanati wa jaadilhum billatee hiya ahsan; inna Rabbaka huwa a'almu biman dalla 'an sabeelihee wa Huwa a'lamu bilmuhtadeen", "translation": "Invite to the way of your Lord with wisdom and good instruction, and argue with them in a way that is best. Indeed, your Lord is most knowing of who has strayed from His way, and He is most knowing of who is [rightly] guided."}, {"ayah": 126, "translit": "Wa in 'aaqabtum fa'aaqiboo bimisli maa 'ooqibtum bihee wa la'in sabartum lahuwa khairul lissaabireen", "translation": "And if you punish [an enemy, O believers], punish with an equivalent of that with which you were harmed. But if you are patient - it is better for those who are patient."}, {"ayah": 127, "translit": "Wasbir wa maa sabruka illaa billaah; wa laa tahzan 'alaihim wa laa taku fee daiqim mimmaa yamkuroon", "translation": "And be patient, [O Muhammad], and your patience is not but through Allah. And do not grieve over them and do not be in distress over what they conspire."}, {"ayah": 128, "translit": "Innal laaha ma'al lazeenat taqaw wal lazeena hum muhsinoon", "translation": "Indeed, Allah is with those who fear Him and those who are doers of good."}]}, {"num": 17, "name": "Al-Isra", "meaning": "The Night Journey", "verses": [{"ayah": 1, "translit": "Subhaanal lazeee asraa bi'abdihee lailam minal Masjidil Haraami ilal Masjidil Aqsal-lazee baaraknaa haw lahoo linuriyahoo min aayaatinaa;innahoo Huwas Samee'ul-Baseer", "translation": "Exalted is He who took His Servant by night from al-Masjid al-Haram to al-Masjid al-Aqsa, whose surroundings We have blessed, to show him of Our signs. Indeed, He is the Hearing, the Seeing."}, {"ayah": 2, "translit": "Wa aatainaa Moosal-Kitaaba wa ja'alnaahu hudal-liBaneee Israaa'eel;allaa tat-takhizoo min doonee wakeelaa.", "translation": "And We gave Moses the Scripture and made it a guidance for the Children of Israel that you not take other than Me as Disposer of affairs,"}, {"ayah": 3, "translit": "Zurriyyata man hamalnaa ma'a Nooh innahoo kaana 'abdan shakooraa", "translation": "O descendants of those We carried [in the ship] with Noah. Indeed, he was a grateful servant."}, {"ayah": 4, "translit": "Wa qadainaaa ilaa Baneee Israaa'eela fil Kitaabi latufsidunna fil ardi marratain; wa lata'lunna'uluwwan kabeeraa", "translation": "And We conveyed to the Children of Israel in the Scripture that, \"You will surely cause corruption on the earth twice, and you will surely reach [a degree of] great haughtiness."}, {"ayah": 5, "translit": "Fa-izaa jaaa'a wa'duoolaahumaa ba'asnaaa 'alykurr 'ibaadai-lanaaa ulee baasin shadeedin fajaasoo khilaalad diyaar; wa kaana wa'dam maf'oolaa", "translation": "So when the [time of] promise came for the first of them, We sent against you servants of Ours - those of great military might, and they probed [even] into the homes, and it was a promise fulfilled."}, {"ayah": 6, "translit": "Summa radadnaa lakumul karrata 'alaihim wa amdad-naakum-bi amwaalinuw wa baneen; wa ja'alnaakum aksara nafeeraa", "translation": "Then We gave back to you a return victory over them. And We reinforced you with wealth and sons and made you more numerous in manpower"}, {"ayah": 7, "translit": "In ahsantum ahsantum li anfusikum wa in asaatum falahaa; fa izaa jaaa'a wa'dul aakhirati liyasooo'oo wujoo hakum wa liyadkhulul masjida kamaa dakhaloohu awwala marratinw wa liyutabbiroo mass'alaw tatbeera", "translation": "[And said], \"If you do good, you do good for yourselves; and if you do evil, [you do it] to yourselves.\" Then when the final promise came, [We sent your enemies] to sadden your faces and to enter the temple in Jerusalem, as they entered it the first time, and to destroy what they had taken over with [total] destruction."}, {"ayah": 8, "translit": "'Asaa rabbukum anyyarhamakum; wa in 'uttum 'udnaa; wa ja'alnaa jahannama lilkaafireena haseera", "translation": "[Then Allah said], \"It is expected, [if you repent], that your Lord will have mercy upon you. But if you return [to sin], We will return [to punishment]. And We have made Hell, for the disbelievers, a prison-bed.\""}, {"ayah": 9, "translit": "Inna haazal Quraana yahdee lillatee hiya aqwamu wa yubashshirul mu'mineenal lazeena ya'maloonas saalihaati anna lahum ajran kabeeraa", "translation": "Indeed, this Qur'an guides to that which is most suitable and gives good tidings to the believers who do righteous deeds that they will have a great reward."}, {"ayah": 10, "translit": "Wa annal lazeena laa yu'minoona bil aakhirati a'tadnaa lahum 'azaaban aleemaa", "translation": "And that those who do not believe in the Hereafter - We have prepared for them a painful punishment."}, {"ayah": 11, "translit": "Wa  yad'ul insaanu bishsharri du'aaa 'ahoo bilkhayr; wa kaanal insaanu 'ajoola", "translation": "And man supplicates for evil as he supplicates for good, and man is ever hasty."}, {"ayah": 12, "translit": "Wa ja'alnal laila wannahaara Aayatayni famahawnaaa Aayatal laili wa ja'alnaaa Aayatan nahaari mubsiratal litabtaghoo fadlam mir Rabbikum wa lita'lamoo 'adadas sineena walhisaab; wa kulla shai'in fassalnaahu tafseelaa", "translation": "And We have made the night and day two signs, and We erased the sign of the night and made the sign of the day visible that you may seek bounty from your Lord and may know the number of years and the account [of time]. And everything We have set out in detail."}, {"ayah": 13, "translit": "Wa kulla insaanin alzamnaahu taaa'irahoo fe 'unuqihee wa nukhriji lahoo Yawmal Qiyaamati kitaabany yalqaahu manshooraa", "translation": "And [for] every person We have imposed his fate upon his neck, and We will produce for him on the Day of Resurrection a record which he will encounter spread open."}, {"ayah": 14, "translit": "Iqra kitaabak kafaa binafsikal Yawma 'alaika haseebaa", "translation": "[It will be said], \"Read your record. Sufficient is yourself against you this Day as accountant.\""}, {"ayah": 15, "translit": "Manihtadaa fa innamaa yahtadee linafsihee wa man dalla fa innamaa yadillu 'alaihaa; wa laa taziru waaziratunw wizra ukhraa; wa maa kunnaa mu'azzibeena hatta nab'asa Rasoola", "translation": "Whoever is guided is only guided for [the benefit of] his soul. And whoever errs only errs against it. And no bearer of burdens will bear the burden of another. And never would We punish until We sent a messenger."}, {"ayah": 16, "translit": "Wa izaaa aradnaaa an nuhlika qaryatan amarnaa mutrafeehaa fafasaqoo feehaa fahaqqa 'alaihal qawlu fadammarnaahaa tadmeeraa", "translation": "And when We intend to destroy a city, We command its affluent but they defiantly disobey therein; so the word comes into effect upon it, and We destroy it with [complete] destruction."}, {"ayah": 17, "translit": "Wa kam ahlaknaa minal qurooni mim ba'di Nooh; wa kafaa bi Rabbika bizunoobi 'ibaadihee Khabeeram Baseeraa", "translation": "And how many have We destroyed from the generations after Noah. And sufficient is your Lord, concerning the sins of His servants, as Acquainted and Seeing."}, {"ayah": 18, "translit": "Man kaana yureedul 'aajilata 'ajjalnaa lahoo feehaa maa nashaaa'u liman nureedu summa ja'alnaa lahoo Jahannama yaslaahaa mazmoomammad hooraa", "translation": "Whoever should desire the immediate - We hasten for him from it what We will to whom We intend. Then We have made for him Hell, which he will [enter to] burn, censured and banished."}, {"ayah": 19, "translit": "Wa man araadal Aakhirata wa sa'aa lahaa sa'yahaa wa huwa mu'minun fa ulaaa'ika kaana sa'yuhum mashkooraa", "translation": "But whoever desires the Hereafter and exerts the effort due to it while he is a believer - it is those whose effort is ever appreciated [by Allah]."}, {"ayah": 20, "translit": "Kullan numiddu haaa 'ulaaa'i wa haaa'ulaaa'i min 'ataaa'i rabbik; wa maa kaana 'ataaa'u rabbika mahzooraa", "translation": "To each [category] We extend - to these and to those - from the gift of your Lord. And never has the gift of your Lord been restricted."}, {"ayah": 21, "translit": "Unzur kaifa faddalnaa ba'dahum 'alaa ba'd; wa lal Aakhiratu akbaru darajaatinw wa akbaru tafdeelaa", "translation": "Look how We have favored [in provision] some of them over others. But the Hereafter is greater in degrees [of difference] and greater in distinction."}, {"ayah": 22, "translit": "Laa taj'al ma'al laahi ilaahan aakhara fataq'uda mazoomam makhzoolaa", "translation": "Do not make [as equal] with Allah another deity and [thereby] become censured and forsaken."}, {"ayah": 23, "translit": "Wa qadaa Rabbuka allaa ta'budooo illaaa iyyaahu wa bilwaalidaini ihsaanaa; immaa yablughanna 'indakal kibara ahaduhumaaa aw kilaahumaa falaa taqul lahumaaa uffinw wa laa tanharhumaa wa qullahumaa qawlan kareemaa", "translation": "And your Lord has decreed that you not worship except Him, and to parents, good treatment. Whether one or both of them reach old age [while] with you, say not to them [so much as], \"uff,\" and do not repel them but speak to them a noble word."}, {"ayah": 24, "translit": "Wakhfid lahumaa janaahaz zulli minar rahmati wa qur Rabbir hamhumaa kamaa rabbayaanee sagheera", "translation": "And lower to them the wing of humility out of mercy and say, \"My Lord, have mercy upon them as they brought me up [when I was] small.\""}, {"ayah": 25, "translit": "Rabbukum a'lamu bimaa fee nufoosikum; in takoonoo saaliheena fa innahoo kaana lil awwaabeena Ghafoooraa", "translation": "Your Lord is most knowing of what is within yourselves. If you should be righteous [in intention] - then indeed He is ever, to the often returning [to Him], Forgiving."}, {"ayah": 26, "translit": "Wa aati zal qurbaa haqqahoo walmiskeena wabnas sabeeli wa laa tubazzir tabzeeraa", "translation": "And give the relative his right, and [also] the poor and the traveler, and do not spend wastefully."}, {"ayah": 27, "translit": "Innal mubazzireena kaanoo ikhwaanash shayaateeni wa kaanash shaytaanu li Rabbihee kafooraa", "translation": "Indeed, the wasteful are brothers of the devils, and ever has Satan been to his Lord ungrateful."}, {"ayah": 28, "translit": "Wa immaa turidanna 'anhumub tighaaa'a rahmatim mir rabbika tarjoohaa faqul lahum qawlam maisooraa", "translation": "And if you [must] turn away from the needy awaiting mercy from your Lord which you expect, then speak to them a gentle word."}, {"ayah": 29, "translit": "Wa laa taj'al yadaka maghloolatan il 'unuqika wa laa tabsut haa kullal basti fataq'uda maloomam mahsooraa", "translation": "And do not make your hand [as] chained to your neck or extend it completely and [thereby] become blamed and insolvent."}, {"ayah": 30, "translit": "Inna Rabbaka yabsuturrizqa limai yashaaa'u wa yaqdir; innahoo kaana bi'ibaadihee Khabeeram Baseera", "translation": "Indeed, your Lord extends provision for whom He wills and restricts [it]. Indeed He is ever, concerning His servants, Acquainted and Seeing."}, {"ayah": 31, "translit": "Wa laa taqtulooo awlaadakum khashyata imlaaq; nahnu narzuquhum wa iyyaakum; inna qatlahum kaana khitan kabeeraa", "translation": "And do not kill your children for fear of poverty. We provide for them and for you. Indeed, their killing is ever a great sin."}, {"ayah": 32, "translit": "Wa laa taqrabuz zinaaa innahoo kaana faahishatanw wa saaa'a sabeelaa", "translation": "And do not approach unlawful sexual intercourse. Indeed, it is ever an immorality and is evil as a way."}, {"ayah": 33, "translit": "Wa laa taqtulun nafsal latee harramal laahu illaa bilhaqq; wa man qutila mazlooman faqad ja'alnaa liwaliyyihee sultaanan falaa yusrif fil qatli innahoo kaana mansooraa", "translation": "And do not kill the soul which Allah has forbidden, except by right. And whoever is killed unjustly - We have given his heir authority, but let him not exceed limits in [the matter of] taking life. Indeed, he has been supported [by the law]."}, {"ayah": 34, "translit": "Wa laa taqraboo maalal yateemi illaa billatee hiya ahsanu hattaa yablugha ashuddah; wa awfoo bil'ahd, innal 'ahda kaana mas'oolaa", "translation": "And do not approach the property of an orphan, except in the way that is best, until he reaches maturity. And fulfill [every] commitment. Indeed, the commitment is ever [that about which one will be] questioned."}, {"ayah": 35, "translit": "Wa awful kaila izaa kiltum wa zinoo bilqistaasil mustaqeem; zaalika khairunw wa ahsanu taaweelaa", "translation": "And give full measure when you measure, and weigh with an even balance. That is the best [way] and best in result."}, {"ayah": 36, "translit": "Wa laa taqfu maa laisa laka bihee 'ilm; innas sam'a walbasara walfu'aada kullu ulaaa'ika kaana 'anhu mas'oolaa", "translation": "And do not pursue that of which you have no knowledge. Indeed, the hearing, the sight and the heart - about all those [one] will be questioned."}, {"ayah": 37, "translit": "Wa laa tamshi fil ardi marahan innaka lan takhriqal arda wa lan tablughal jibaala toola", "translation": "And do not walk upon the earth exultantly. Indeed, you will never tear the earth [apart], and you will never reach the mountains in height."}, {"ayah": 38, "translit": "Kullu zaalika kaana sayyi'uhoo inda Rabbika makroohaa", "translation": "All that - its evil is ever, in the sight of your Lord, detested."}, {"ayah": 39, "translit": "Zaalika mimmaaa awhaaa ilaika Rabbuka minal hikmah; wa laa taj'al ma'allaahi ilaahan aakhara fatulqaa fee Jahannama maloomam mad hooraa", "translation": "That is from what your Lord has revealed to you, [O Muhammad], of wisdom. And, [O mankind], do not make [as equal] with Allah another deity, lest you be thrown into Hell, blamed and banished."}, {"ayah": 40, "translit": "Afa asfaakum rabbukum bilbaneena wattakhaza minal malaaa'ikati inaasaa; innakum lataqooloona qawlan 'azeema", "translation": "Then, has your Lord chosen you for [having] sons and taken from among the angels daughters? Indeed, you say a grave saying."}, {"ayah": 41, "translit": "Wa laqad sarrafnaa fee haazal Quraani liyazzakkaroo wa maa yazeeduhum illaa nufooraa", "translation": "And We have certainly diversified [the contents] in this Qur'an that mankind may be reminded, but it does not increase the disbelievers except in aversion."}, {"ayah": 42, "translit": "Qul law kaana ma'ahooo aalihatun kamaa yaqooloona izal labtaghaw ilaa zil 'Arshi Sabeela", "translation": "Say, [O Muhammad], \"If there had been with Him [other] gods, as they say, then they [each] would have sought to the Owner of the Throne a way.\""}, {"ayah": 43, "translit": "Subhaanahoo wa Ta'aalaa 'ammaa yaqooloona 'uluwwan kabeeraa", "translation": "Exalted is He and high above what they say by great sublimity."}, {"ayah": 44, "translit": "Tusabbihu lahus samaawaatus sab'u wal ardu wa man feehinn;  wa im min shai'in illaa yusabbihu bihamdihee wa laakil laa tafqahoona tasbeehahum; innahoo kaana Haleeman Ghafooraa", "translation": "The seven heavens and the earth and whatever is in them exalt Him. And there is not a thing except that it exalts [Allah] by His praise, but you do not understand their [way of] exalting. Indeed, He is ever Forbearing and Forgiving."}, {"ayah": 45, "translit": "Wa izaa qaraatal Quraana ja'alnaa bainaka wa bainal lazeena laa yu'minoona bil aakhirati hijaabam mastooraa", "translation": "And when you recite the Qur'an, We put between you and those who do not believe in the Hereafter a concealed partition."}, {"ayah": 46, "translit": "Wa ja'alnaa 'alaa quloo bihim akinnatan any yafqahoohu wa feee aazaanihim waqraa; wa izaa zakarta Rabbaka fil Quraani wahdahoo wallaw 'alaaa adbaarihim nufooraa", "translation": "And We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And when you mention your Lord alone in the Qur'an, they turn back in aversion."}, {"ayah": 47, "translit": "nahnu a'lamu bimaa yastami'oona biheee iz yastami'oona ilaika wa iz hum najwaaa iz yaqooluz zaalimoona in tattabi'oona illaa rajulam mas hooraa", "translation": "We are most knowing of how they listen to it when they listen to you and [of] when they are in private conversation, when the wrongdoers say, \"You follow not but a man affected by magic.\""}, {"ayah": 48, "translit": "Unzur kaifa daraboo lakal amsaala fadalloo falaa yastatee'oona sabeelaa", "translation": "Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way."}, {"ayah": 49, "translit": "Wa qaalooo'a izaa kunnaa 'izaamanw wa rufaatan 'a innaa lamab'oosoona khalqan jadeedaa", "translation": "And they say, \"When we are bones and crumbled particles, will we [truly] be resurrected as a new creation?\""}, {"ayah": 50, "translit": "Qul koonoo jijaaratan aw hadeedaa", "translation": "Say, \"Be you stones or iron"}, {"ayah": 51, "translit": "aw khalqam mimmaa yakburu fee sudoorikum; fasa yaqooloona mai yu'eedunaa qulil lazee fatarakum awwala marrah; fasa yunghidoona ilaika ru'oosahum wa yaqooloona mataa huwa qul 'asaaa any yakoona qareeba", "translation": "Or [any] creation of that which is great within your breasts.\" And they will say, \"Who will restore us?\" Say, \"He who brought you forth the first time.\" Then they will nod their heads toward you and say, \"When is that?\" Say, \"Perhaps it will be soon -"}, {"ayah": 52, "translit": "Yawma yad'ookum fatastajeeboona bihamdihee wa tazunnoona il labistum illaa qaleela", "translation": "On the Day He will call you and you will respond with praise of Him and think that you had not remained [in the world] except for a little.\""}, {"ayah": 53, "translit": "Wa qul li'ibaadee yaqoolul latee hiya ahsan; innash shaitaana yanzaghu bainahum; innash shaitaana kaana lil insaani 'aduwwam mubeenaa", "translation": "And tell My servants to say that which is best. Indeed, Satan induces [dissension] among them. Indeed Satan is ever, to mankind, a clear enemy."}, {"ayah": 54, "translit": "Rabbukum a'lamu bikum iny yashaaa yarhamkum aw iny yashaa yu'azzibkum; wa maaa arsalnaaka 'alaihim wakeelaa", "translation": "Your Lord is most knowing of you. If He wills, He will have mercy upon you; or if He wills, He will punish you. And We have not sent you, [O Muhammad], over them as a manager."}, {"ayah": 55, "translit": "Wa Rabbuka a'lamu biman fis samaawaati wal lard; wa laqad faddalnaa ba'dan Nabiyyeena 'alaa ba'dinw wa aatainaaa Daawooda Zabooraa", "translation": "And your Lord is most knowing of whoever is in the heavens and the earth. And We have made some of the prophets exceed others [in various ways], and to David We gave the book [of Psalms]."}, {"ayah": 56, "translit": "Qulid 'ul lazeena za'amtum min doonihee falaa yamlikoona kashfad durri'ankum wa laa tahweelaa", "translation": "Say, \"Invoke those you have claimed [as gods] besides Him, for they do not possess the [ability for] removal of adversity from you or [for its] transfer [to someone else].\""}, {"ayah": 57, "translit": "Ulaaa'ikal lazeena yad'oona yabtaghoona ilaa Rabbihimul waseelata ayyuhum aqrabu wa yarjoona rahmatahoo wa yakhaafoona 'azaabah; inna 'azaaba rabbika kaana mahzooraa", "translation": "Those whom they invoke seek means of access to their Lord, [striving as to] which of them would be nearest, and they hope for His mercy and fear His punishment. Indeed, the punishment of your Lord is ever feared."}, {"ayah": 58, "translit": "Wa im min qaryatin illaa Nahnu muhlikoohaa qabla Yawmil Qiyaamati aw mu'az ziboohaa 'azaaban shadeedaa; kaana zaalika fil Kitaabi mastooraa", "translation": "And there is no city but that We will destroy it before the Day of Resurrection or punish it with a severe punishment. That has ever been in the Register inscribed."}, {"ayah": 59, "translit": "Wa maa mana'anaaa an nursila bil aayaati illaaa an kazzaba bihal awwaloon; wa aatainaa Samoodan naaqata mubsiratan fazalamoo bihaa; wa maa nursilu bil aayaati illaa takhweefaa", "translation": "And nothing has prevented Us from sending signs except that the former peoples denied them. And We gave Thamud the she-camel as a visible sign, but they wronged her. And We send not the signs except as a warning."}, {"ayah": 60, "translit": "Wa iz qulnaa laka inna rabbaka ahaata binnaas; wa maa ja'alnar ru'yal lateee arainaaka illaa fitnatal linnaasi washshajaratal mal'oonata fil quraan; wa nukhaw wifuhum famaa yazeeduhum illa tughyaanan kabeeraa", "translation": "And [remember, O Muhammad], when We told you, \"Indeed, your Lord has encompassed the people.\" And We did not make the sight which We showed you except as a trial for the people, as was the accursed tree [mentioned] in the Qur'an. And We threaten them, but it increases them not except in great transgression."}, {"ayah": 61, "translit": "Wa iz qulnaa lilma laaa'ikatis judoo li Aadama fasajadooo illaaa Ibleesa qaala 'a-asjudu liman khalaqta teena", "translation": "And [mention] when We said to the angles, \"Prostrate to Adam,\" and they prostrated, except for Iblees. He said, \"Should I prostrate to one You created from clay?\""}, {"ayah": 62, "translit": "Qaala ara'aytaka haazal lazee karramta 'alaiya la'in akhhartani ilaa Yawmil Qiyaamati la-ah tanikanna zurriyyatahooo illaa qaleelaa", "translation": "[Iblees] said, \"Do You see this one whom You have honored above me? If You delay me until the Day of Resurrection, I will surely destroy his descendants, except for a few.\""}, {"ayah": 63, "translit": "Qaalaz hab faman tabi'aka minhum fa inna Jahannama jazaaa'ukum jazaaa'am mawfooraa", "translation": "[Allah] said, \"Go, for whoever of them follows you, indeed Hell will be the recompense of you - an ample recompense."}, {"ayah": 64, "translit": "Wastafziz manis tat'ta minhum bisawtika wa ajlib 'alaihim bikhailika wa rajilika wa shaarik hum fil amwaali wal awlaadi wa 'idhum; wa maa ya'iduhumush Shaitaanu illaa ghurooraa", "translation": "And incite [to senselessness] whoever you can among them with your voice and assault them with your horses and foot soldiers and become a partner in their wealth and their children and promise them.\" But Satan does not promise them except delusion."}, {"ayah": 65, "translit": "Inna 'ibaadee laisa laka 'alaihim sultaan; wa kafaa bi Rabbika Wakeelaa", "translation": "Indeed, over My [believing] servants there is for you no authority. And sufficient is your Lord as Disposer of affairs."}, {"ayah": 66, "translit": "Rabbukumul lazee yuzjee lakumul fulka fil bahri litabtaghoo min fadlih; innahoo kaana bikum Raheemaa", "translation": "It is your Lord who drives the ship for you through the sea that you may seek of His bounty. Indeed, He is ever, to you, Merciful."}, {"ayah": 67, "translit": "Wa izaa massakumuddurru fil bahri dalla man tad'oona illaaa iyyaahu falammaa najjaakum ilal barri a'radtum; wa kaanal insaanu kafooraa", "translation": "And when adversity touches you at sea, lost are [all] those you invoke except for Him. But when He delivers you to the land, you turn away [from Him]. And ever is man ungrateful."}, {"ayah": 68, "translit": "Afa amintum any yakhsifa bikum jaanibal barri aw yursil 'alaikum haasiban summa laa tajidoo lakum wakeelaa", "translation": "Then do you feel secure that [instead] He will not cause a part of the land to swallow you or send against you a storm of stones? Then you would not find for yourselves an advocate."}, {"ayah": 69, "translit": "Am amintum any yu'eedakum feehi taaratan ukhraa fa yursila 'alaikum qaasifam minar reehi fa yugh riqakum bimaa kafartum summa laa tajidoo lakum 'alainaa bihee tabee'aa", "translation": "Or do you feel secure that He will not send you back into the sea another time and send upon you a hurricane of wind and drown you for what you denied? Then you would not find for yourselves against Us an avenger."}, {"ayah": 70, "translit": "Wa laqad karramnaa Baneee aadama wa hamalnaahum fil barri walbahri wa razaqnaahum minat taiyibaati wa faddalnaahum 'alaa kaseerim mimman khalaqnaa tafdeelaa", "translation": "And We have certainly honored the children of Adam and carried them on the land and sea and provided for them of the good things and preferred them over much of what We have created, with [definite] preference."}, {"ayah": 71, "translit": "Yawma nad'oo kulla unaasim bi imaamihim faman ootiya kitaabahoo bi yameenihee fa ulaaa'ika yaqra'oona kitaabahum wa laa yuzlamoona fateelaa", "translation": "[Mention, O Muhammad], the Day We will call forth every people with their record [of deeds]. Then whoever is given his record in his right hand - those will read their records, and injustice will not be done to them, [even] as much as a thread [inside the date seed]."}, {"ayah": 72, "translit": "Wa man kaana fee haaziheee a'maa fahuwa fil aakhirati a'maa wa adallu sabeelaa", "translation": "And whoever is blind in this [life] will be blind in the Hereafter and more astray in way."}, {"ayah": 73, "translit": "Wa in kaadoo la yaftinoonaka 'anil lazeee awhainaaa ilaika litaftariya 'alainaaa ghairahoo wa izallat takhazooka khaleelaa", "translation": "And indeed, they were about to tempt you away from that which We revealed to you in order to [make] you invent about Us something else; and then they would have taken you as a friend."}, {"ayah": 74, "translit": "Wa law laaa an sabbatnaaka laqad kitta tarkanu ilaihim sha'an qaleela", "translation": "And if We had not strengthened you, you would have almost inclined to them a little."}, {"ayah": 75, "translit": "Izal la azaqnaaka di'falhayaati wa di'fal mamaati summa laa tajidu laka 'alainaa naseeraa", "translation": "Then [if you had], We would have made you taste double [punishment in] life and double [after] death. Then you would not find for yourself against Us a helper."}, {"ayah": 76, "translit": "Wa in kaadoo la yastafizzoonaka minal ardi liyukhri jooka minhaa wa izal laa yalbasoona khilaafaka illaa qaleelaa", "translation": "And indeed, they were about to drive you from the land to evict you therefrom. And then [when they do], they will not remain [there] after you, except for a little."}, {"ayah": 77, "translit": "Sunnata man qad arsalnaa qablakamir Rusulinaa wa laa tajidu lisunnatinaa tahhweelaa", "translation": "[That is Our] established way for those We had sent before you of Our messengers; and you will not find in Our way any alteration."}, {"ayah": 78, "translit": "Aqimis Salaata liduloo kish shamsi ilaa ghasaqil laili wa quraanal Fajri inna quraa nal Fajri kaana mashhoodaa", "translation": "Establish prayer at the decline of the sun [from its meridian] until the darkness of the night and [also] the Qur'an of dawn. Indeed, the recitation of dawn is ever witnessed."}, {"ayah": 79, "translit": "Wa minal laili fatahajjad bihee naafilatal laka 'asaaa any yab'asaka Rabbuka Maqaamam Mahmoodaa", "translation": "And from [part of] the night, pray with it as additional [worship] for you; it is expected that your Lord will resurrect you to a praised station."}, {"ayah": 80, "translit": "Wa qur Rabbi adkhilnee mudkhala sidqinw wa akhrijnee mukhraja sidqinw waj'al lee milladunka sultaanan naseeraa", "translation": "And say, \"My Lord, cause me to enter a sound entrance and to exit a sound exit and grant me from Yourself a supporting authority.\""}, {"ayah": 81, "translit": "Wa qul jaaa'al haqqu wa zahaqal baatil; innal baatila kaana zahooqaa", "translation": "And say, \"Truth has come, and falsehood has departed. Indeed is falsehood, [by nature], ever bound to depart.\""}, {"ayah": 82, "translit": "Wa nunazzilu minal quraani maa huwa shifaaa'unw wa rahmatul lilmu;mineena wa laa yazeeduz zaalimeena illaa khasaaraa", "translation": "And We send down of the Qur'an that which is healing and mercy for the believers, but it does not increase the wrongdoers except in loss."}, {"ayah": 83, "translit": "Wa izaaa an'amnaa 'alal insaani a'rada wa na-aa bijaani bihee wa izaa massahush sharru kaana ya'oosaa", "translation": "And when We bestow favor upon the disbeliever, he turns away and distances himself; and when evil touches him, he is ever despairing."}, {"ayah": 84, "translit": "Qul kulluny ya'malu 'alaa shaakilatihee fa rabbukum a'lamu biman huwa ahdaa sabeelaa", "translation": "Say, \"Each works according to his manner, but your Lord is most knowing of who is best guided in way.\""}, {"ayah": 85, "translit": "Wa yas'aloonaka 'anirrooh; qulir roohu min amri rabbee wa maaa ooteetum minal 'ilmi illaa qaleelaa", "translation": "And they ask you, [O Muhammad], about the soul. Say, \"The soul is of the affair of my Lord. And mankind have not been given of knowledge except a little.\""}, {"ayah": 86, "translit": "Wa la'in shi'naa lanaz habanna billazeee awhainaaa ilaika summa laa tajidu laka bihee 'alainaa wakeelaa", "translation": "And if We willed, We could surely do away with that which We revealed to you. Then you would not find for yourself concerning it an advocate against Us."}, {"ayah": 87, "translit": "Illaa rahmatam mir Rabbik; inna fadlahoo kaana 'alaika kabeeraa", "translation": "Except [We have left it with you] as a mercy from your Lord. Indeed, His favor upon you has ever been great."}, {"ayah": 88, "translit": "Qul la'inij tama'atil insu waljinnu 'alaaa any yaatoo bimisli haazal quraani laa yaatoona bimislihee wa law kaana ba'duhum liba 'din zaheeraa", "translation": "Say, \"If mankind and the jinn gathered in order to produce the like of this Qur'an, they could not produce the like of it, even if they were to each other assistants.\""}, {"ayah": 89, "translit": "Qa laqad sarrafnaa linnaasi fee haazal quraani min kulli masalin fa abaaa aksarun naasi illaa kufooraa", "translation": "And We have certainly diversified for the people in this Qur'an from every [kind] of example, but most of the people refused [anything] except disbelief."}, {"ayah": 90, "translit": "Wa qaaloo lan nu'mina laka hattaa tafjura lanaa minal ardi yamboo'aa", "translation": "And they say, \"We will not believe you until you break open for us from the ground a spring."}, {"ayah": 91, "translit": "Aw takoona laka jannatum min nakheelinw wa 'inabin fatufajjiral anhaara khilaalahaa tafjeeraa", "translation": "Or [until] you have a garden of palm tress and grapes and make rivers gush forth within them in force [and abundance]"}, {"ayah": 92, "translit": "Aw tusqitas samaaa'a kamaa za'amta 'alainaa kisafan aw taatiya billaahi walma laaa'ikati qabeelaa", "translation": "Or you make the heaven fall upon us in fragments as you have claimed or you bring Allah and the angels before [us]"}, {"ayah": 93, "translit": "Aw yakoona laka baitum min zukhrufin aw tarqaa fis samaaa'i wa lan nu'mina liruqiyyika hatta tunazzila 'alainaa kitaaban naqra'uh; qul Subhaana Rabbee hal kuntu illaa basharar Rasoolaa", "translation": "Or you have a house of gold or you ascend into the sky. And [even then], we will not believe in your ascension until you bring down to us a book we may read.\" Say, \"Exalted is my Lord! Was I ever but a human messenger?\""}, {"ayah": 94, "translit": "Wa maa mana'an naasa any yu'minooo iz jaaa'ahumul hudaaa illaaa an qaalooo aba'asal laahu basharar Rasoolaa", "translation": "And what prevented the people from believing when guidance came to them except that they said, \"Has Allah sent a human messenger?\""}, {"ayah": 95, "translit": "Qul law kaana fil ardi malaaa 'ikatuny yamshoona mutma'inneena lanazzalnaa 'alaihim minas samaaa'i malakar Rasoolaa", "translation": "Say, \"If there were upon the earth angels walking securely, We would have sent down to them from the heaven an angel [as a] messenger.\""}, {"ayah": 96, "translit": "Qul kafaa billaahi shaheedam bainee wa bainakum; innahoo kaana bi'ibaadihee Khabeeram Baseeraa", "translation": "Say, \"Sufficient is Allah as Witness between me and you. Indeed he is ever, concerning His servants, Acquainted and Seeing.\""}, {"ayah": 97, "translit": "Wa mai yahdil laahu fahuwal muhtad; wa mai yudlil falan tajida lahum awliyaaa'a min doonih; wa nahshuruhum Yawmal Qiyaamati 'alaa wujoohihim umyanw wa bukmanw wa summaa; maa waahum Jahannamu kullamaa khabat zidnaahum sa'eeraa", "translation": "And whoever Allah guides - he is the [rightly] guided; and whoever He sends astray - you will never find for them protectors besides Him, and We will gather them on the Day of Resurrection [fallen] on their faces - blind, dumb and deaf. Their refuge is Hell; every time it subsides We increase them in blazing fire."}, {"ayah": 98, "translit": "Zaalika jazaa'uhum biannahum kafaroo bi aayaatinaa wa qaalooo 'a izaa kunnaa 'izaamanw wa rufaatan'a innaa lamaboosoona khalqan jadeedaa", "translation": "That is their recompense because they disbelieved in Our verses and said, \"When we are bones and crumbled particles, will we [truly] be resurrected [in] a new creation?\""}, {"ayah": 99, "translit": "Awalam yaraw annal laahal lazee khalaqas samaawaati wal arda qaadirun 'alaaa any yakhluqa mislahum wa ja'ala lahum ajalal laa raiba fee; fa abaz zaalimoona illaa kufooraa", "translation": "Do they not see that Allah, who created the heavens and earth, is [the one] Able to create the likes of them? And He has appointed for them a term, about which there is no doubt. But the wrongdoers refuse [anything] except disbelief."}, {"ayah": 100, "translit": "Qul law antum tamlikoona khazaaa'ina rahmati Rabbeee izal la amsaktum khash yatal infaaq; wa kaanal insaanu qatooraa", "translation": "Say [to them], \"If you possessed the depositories of the mercy of my Lord, then you would withhold out of fear of spending.\" And ever has man been stingy."}, {"ayah": 101, "translit": "Wa laqad aatainaa Moosaa tis'a Aayaatim baiyinaatin fas'al Baneee Israaa'eela iz jaaa'ahum faqaala lahoo Fir'awnu inee la azunnuka yaa Moosaa mas hooraa", "translation": "And We had certainly given Moses nine evident signs, so ask the Children of Israel [about] when he came to them and Pharaoh said to him, \"Indeed I think, O Moses, that you are affected by magic.\""}, {"ayah": 102, "translit": "Qaala laqad 'alimta maaa anzala haaa'ulaaa'i illaa Rabbus samaawaati wal ardi basaaa'ira wa innee la azun nuka yaa Fir'awnu masbooraa", "translation": "[Moses] said, \"You have already known that none has sent down these [signs] except the Lord of the heavens and the earth as evidence, and indeed I think, O Pharaoh, that you are destroyed.\""}, {"ayah": 103, "translit": "Fa araada any yastafizzahum minal ardi fa aghraqnaahu wa mam ma'ahoo jamee'aa", "translation": "So he intended to drive them from the land, but We drowned him and those with him all together."}, {"ayah": 104, "translit": "Wa qulnaa mim ba'dihee li Baneee Israaa'eelas kunul arda faizaa jaaa'a wa'dulaakhirati ji'naa bikum lafeefaa", "translation": "And We said after Pharaoh to the Children of Israel, \"Dwell in the land, and when there comes the promise of the Hereafter, We will bring you forth in [one] gathering.\""}, {"ayah": 105, "translit": "Wa bilhaqqi anzalnaahu wa bilhaqqi nazal; wa maaa arsalnaaka illaa mubash shiranw wa nazeeraa", "translation": "And with the truth We have sent the Qur'an down, and with the truth it has descended. And We have not sent you, [O Muhammad], except as a bringer of good tidings and a warner."}, {"ayah": 106, "translit": "Wa quraanan faraqnaahu litaqra ahoo 'alan naasi 'alaa muksinw wa nazzalnaahu tanzeelaa", "translation": "And [it is] a Qur'an which We have separated [by intervals] that you might recite it to the people over a prolonged period. And We have sent it down progressively."}, {"ayah": 107, "translit": "Qul aaaniminoo biheee aw laa tu'minoo; innal lazeena ootul 'ilma min qabliheee izaa yutlaa 'alaihim yakhirroona lil azqaani sujjadaa", "translation": "Say, \"Believe in it or do not believe. Indeed, those who were given knowledge before it - when it is recited to them, they fall upon their faces in prostration,"}, {"ayah": 108, "translit": "Wa yaqooloona Subhaana Rabbinaaa in kaana wa'du Rabbinaa lamaf'oolaa", "translation": "And they say, \"Exalted is our Lord! Indeed, the promise of our Lord has been fulfilled.\""}, {"ayah": 109, "translit": "Wa yakhirroona lil azqaani yabkoona wa yazeeduhum khushoo'aa", "translation": "And they fall upon their faces weeping, and the Qur'an increases them in humble submission."}, {"ayah": 110, "translit": "Qulid'ul laaha awid'ur Rahmaana ayyam maa tad'oo falahul asmaaa'ul Husnaa; wa laa tajhar bi Salaatika wa laa tukhaafit bihaa wabtaghi baina zaalika sabeela", "translation": "Say, \"Call upon Allah or call upon the Most Merciful. Whichever [name] you call - to Him belong the best names.\" And do not recite [too] loudly in your prayer or [too] quietly but seek between that an [intermediate] way."}, {"ayah": 111, "translit": "Wa qulil hamdu lillaahil lazee lam yattakhiz waladanw wa lam yakul lahoo shareekun fil mulki wa lam yakul lahoo waliyyum minaz zulli wa kabbirhu takbeeraa", "translation": "And say, \"Praise to Allah, who has not taken a son and has had no partner in [His] dominion and has no [need of a] protector out of weakness; and glorify Him with [great] glorification.\""}]}, {"num": 18, "name": "Al-Kahf", "meaning": "The Cave", "verses": [{"ayah": 1, "translit": "Alhamdu lillaahil lazeee anzala 'alaa 'abdihil kitaaba wa lam yaj'al lahoo 'iwajaa", "translation": "[All] praise is [due] to Allah, who has sent down upon His Servant the Book and has not made therein any deviance."}, {"ayah": 2, "translit": "Qaiyimal liyunzira baasan shadeedam mil ladunhu wa yubashshiral mu'mineenal lazeena ya'maloonas saalihaati anna lahum ajran hasanaa", "translation": "[He has made it] straight, to warn of severe punishment from Him and to give good tidings to the believers who do righteous deeds that they will have a good reward"}, {"ayah": 3, "translit": "Maakiseena feehi abadaa", "translation": "In which they will remain forever"}, {"ayah": 4, "translit": "Wa yunziral lazeena qaalut takhazal laahu waladaa", "translation": "And to warn those who say, \"Allah has taken a son.\""}, {"ayah": 5, "translit": "Maa lahum bihee min 'ilminw wa laa li aabaaa'ihim; kaburat kalimatan takhruju min afwaahihim; iny yaqooloona illaa kazibaa", "translation": "They have no knowledge of it, nor had their fathers. Grave is the word that comes out of their mouths; they speak not except a lie."}, {"ayah": 6, "translit": "Fala'allaka baakhi'un nafsaka 'alaaa aasaarihim illam yu;minoo bihaazal hadeesi asafaa", "translation": "Then perhaps you would kill yourself through grief over them, [O Muhammad], if they do not believe in this message, [and] out of sorrow."}, {"ayah": 7, "translit": "Innaa ja'alnaa ma 'alal ardi zeenatal lahaa linabluwahum ayyuhum ahsanu 'amalaa", "translation": "Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed."}, {"ayah": 8, "translit": "Wa innaa lajaa 'iloona maa 'alaihaa sa'aeedan juruzaa", "translation": "And indeed, We will make that which is upon it [into] a barren ground."}, {"ayah": 9, "translit": "Am hasibta anna Ashaabal Kahfi war Raqeemi kaanoo min Aayaatinaa 'ajabaa", "translation": "Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder?"}, {"ayah": 10, "translit": "Iz awal fityatu ilal Kahfi faqaaloo Rabbanaaa aatinaa mil ladunka rahmatanw wa haiyi' lanaa min amrinaa rashadaa", "translation": "[Mention] when the youths retreated to the cave and said, \"Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance.\""}, {"ayah": 11, "translit": "Fadarabnaa 'alaaa aazaanihim fil Kahfi seneena 'adadaa", "translation": "So We cast [a cover of sleep] over their ears within the cave for a number of years."}, {"ayah": 12, "translit": "Summa ba'asnaahum lina'lama ayyul hizbaini ahsaa limaa labisooo amadaa", "translation": "Then We awakened them that We might show which of the two factions was most precise in calculating what [extent] they had remained in time."}, {"ayah": 13, "translit": "Nahnu naqussu 'alaika naba ahum bilhaqq; innahum fityatun aamanoo bi Rabbihim wa zidnaahum hudaa", "translation": "It is We who relate to you, [O Muhammad], their story in truth. Indeed, they were youths who believed in their Lord, and We increased them in guidance."}, {"ayah": 14, "translit": "Wa rabatnaa 'alaa quloo bihim iz qaamoo faqaaloo Rabbunaa Rabbus samaawaati wal ardi lan nad'uwa min dooniheee ilaahal laqad qulnaaa izan shatataa", "translation": "And We made firm their hearts when they stood up and said, \"Our Lord is the Lord of the heavens and the earth. Never will we invoke besides Him any deity. We would have certainly spoken, then, an excessive transgression."}, {"ayah": 15, "translit": "Haaa'ulaaa'i qawmunat takhazoo min dooniheee aalihatal law laa yaatoona 'alaihim bisultaanim baiyin; faman azlamu mimmaniftaraa 'alal laahi kazibaa", "translation": "These, our people, have taken besides Him deities. Why do they not bring for [worship of] them a clear authority? And who is more unjust than one who invents about Allah a lie?\""}, {"ayah": 16, "translit": "Wa izi'tazal tumoohum wa maa ya'budoona illal laaha faawooo ilal kahfi yanshur lakum Rabbukum mir rahmatihee wa yuhaiyi' lakum min amrikum mirfaqa", "translation": "[The youths said to one another], \"And when you have withdrawn from them and that which they worship other than Allah, retreat to the cave. Your Lord will spread out for you of His mercy and will prepare for you from your affair facility.\""}, {"ayah": 17, "translit": "Wa tarash shamsa izaa tala'at tazaawaru 'an kahfihim zaatal yameeni wa izaa gharabat taqriduhum zaatash shimaali wa hum fee fajwatim minh; zaalika min Aayaatillaah; mai yahdil laahu fahuwal muhtad, wa mai yudlil falan tajida lahoo waliyyam murshidaa", "translation": "And [had you been present], you would see the sun when it rose, inclining away from their cave on the right, and when it set, passing away from them on the left, while they were [laying] within an open space thereof. That was from the signs of Allah. He whom Allah guides is the [rightly] guided, but he whom He leaves astray - never will you find for him a protecting guide."}, {"ayah": 18, "translit": "Wa tahsabuhum ayqaazanw wa hum ruqood; wa nuqallibuhum zaatal yameeni wa zaatash shimaali wa kalbuhum baasitun ziraa'ayhi bilwaseed; lawit tala'ta 'alaihim la wallaita minhum firaaranw wa lamuli'ta minhum rubaa", "translation": "And you would think them awake, while they were asleep. And We turned them to the right and to the left, while their dog stretched his forelegs at the entrance. If you had looked at them, you would have turned from them in flight and been filled by them with terror."}, {"ayah": 19, "translit": "Wa kazaalika ba'asnaahum liyatasaaa'aloo bainahum; qaala qaaa'ilum minhum kam labistum qaaloo labisnaa yawman aw ba'da yawm; qaaloo Rabbukum a'lamu bimaa labistum fab'asooo ahadakum biwariqikum haazihee ilal madeenati falyanzur ayyuhaaa azkaa ta'aaman falyaatikum birizqim minhu walyatalattaf wa laa yush'iranna bikum ahadaa", "translation": "And similarly, We awakened them that they might question one another. Said a speaker from among them, \"How long have you remained [here]?\" They said, \"We have remained a day or part of a day.\" They said, \"Your Lord is most knowing of how long you remained. So send one of you with this silver coin of yours to the city and let him look to which is the best of food and bring you provision from it and let him be cautious. And let no one be aware of you."}, {"ayah": 20, "translit": "Innahum iny yazharoo 'alaikum yarjumookum aw yu'eedookum fee millatihim wa lan tuflihooo izan abadaa", "translation": "Indeed, if they come to know of you, they will stone you or return you to their religion. And never would you succeed, then - ever.\""}, {"ayah": 21, "translit": "Wa kazaalika a'sarnaa 'alaihim liya'lamooo anna wa'dal laahi haqqunw wa annas Saa'ata laa raiba feehaa iz yatanaaza'oona bainahum amrahum faqaalub noo 'alaihim bunyaanaa; Rabbuhum a'lamu bihim; qaalal lazeena ghalaboo 'alaaa amrihim lanat takhizanna 'alaihim masjidaa", "translation": "And similarly, We caused them to be found that they [who found them] would know that the promise of Allah is truth and that of the Hour there is no doubt. [That was] when they disputed among themselves about their affair and [then] said, \"Construct over them a structure. Their Lord is most knowing about them.\" Said those who prevailed in the matter, \"We will surely take [for ourselves] over them a masjid.\""}, {"ayah": 22, "translit": "Sa yaqooloona salaasatur raabi'uhum kalbuhum wa yaqooloona khamsatun saadisuhum kalbuhum rajmam bilghaib; wa yaqooloona sab'atunw wa saaminuhum kalbuhum; qur Rabbeee a'lamu bi'iddatihim maa ya'lamuhum illaa qaleel; falaa tumaari feehim illaa miraaa'an zaahiranw wa laa tastafti feehim minhum ahadaa", "translation": "They will say there were three, the fourth of them being their dog; and they will say there were five, the sixth of them being their dog - guessing at the unseen; and they will say there were seven, and the eighth of them was their dog. Say, [O Muhammad], \"My Lord is most knowing of their number. None knows them except a few. So do not argue about them except with an obvious argument and do not inquire about them among [the speculators] from anyone.\""}, {"ayah": 23, "translit": "Wa laa taqoolanna lishai'in innee faa'ilun zaalika ghadaa", "translation": "And never say of anything, \"Indeed, I will do that tomorrow,\""}, {"ayah": 24, "translit": "Illaaa any yashaaa'al laah; wazkur Rabbaka izaa naseeta wa qul 'asaaa any yahdiyani Rabbee li aqraba min haazaa rashadaa", "translation": "Except [when adding], \"If Allah wills.\" And remember your Lord when you forget [it] and say, \"Perhaps my Lord will guide me to what is nearer than this to right conduct.\""}, {"ayah": 25, "translit": "Wa labisoo fee kahfihim salaasa mi'atin sineena wazdaadoo tis'aa", "translation": "And they remained in their cave for three hundred years and exceeded by nine."}, {"ayah": 26, "translit": "Qulil laahu a'lamu bimaa labisoo lahoo ghaibus samaawaati wal ardi absir bihee wa asmi'; maa lahum min doonihee minw waliyyinw wa laa yushriku fee hukmihee ahadaa", "translation": "Say, \"Allah is most knowing of how long they remained. He has [knowledge of] the unseen [aspects] of the heavens and the earth. How Seeing is He and how Hearing! They have not besides Him any protector, and He shares not His legislation with anyone.\""}, {"ayah": 27, "translit": "Watlu maaa oohiya ilaika min Kitaabi Rabbika laa mubaddila li Kalimaatihee wa lan tajida min doonihee multahadaa", "translation": "And recite, [O Muhammad], what has been revealed to you of the Book of your Lord. There is no changer of His words, and never will you find in other than Him a refuge."}, {"ayah": 28, "translit": "Wasbir nafsaka ma'al lazeena yad'oona Rabbahum bilghadaati wal'ashiyyi yureedoona Wajhahoo wa laa ta'du 'aynaaka 'anhum tureedu zeenatal hayaatid dunyaa wa laa tuti' man aghfalnaa qalbahoo 'an zikrinaa wattaba'a hawaahu wa kaana amruhoo furutaa", "translation": "And keep yourself patient [by being] with those who call upon their Lord in the morning and the evening, seeking His countenance. And let not your eyes pass beyond them, desiring adornments of the worldly life, and do not obey one whose heart We have made heedless of Our remembrance and who follows his desire and whose affair is ever [in] neglect."}, {"ayah": 29, "translit": "Wa qulil haqqu mir Rabbikum faman shaaa'a falyu minw wa man shaaa'a falyakfur; innaaa a'tadnaa lizzaalimeena Naaran ahaata bihim suraadiquhaa; wa iny yastagheesoo yaghaasoo bimaaa'in kalmuhli yashwil wujooh' bi'sash-sharaab; wa saaa'at murtafaqaa", "translation": "And say, \"The truth is from your Lord, so whoever wills - let him believe; and whoever wills - let him disbelieve.\" Indeed, We have prepared for the wrongdoers a fire whose walls will surround them. And if they call for relief, they will be relieved with water like murky oil, which scalds [their] faces. Wretched is the drink, and evil is the resting place."}, {"ayah": 30, "translit": "Innal lazeena aamanoo wa 'amilus saalihaati innaa laa nudee'u ajra man ahsana 'amalaa", "translation": "Indeed, those who have believed and done righteous deeds - indeed, We will not allow to be lost the reward of any who did well in deeds."}, {"ayah": 31, "translit": "Ulaaa'ika lahum Jannaatu 'Adnin tajree min tahtihimul anhaaru yuhallawna feehaa min asaawira min zahabinw wa yalbasoona siyaaban khudram min sundusinw wa istabraqim muttaki'eena feehaa 'alal araaa'ik; ni'mas sawaab; wa hasunat murtafaqaa", "translation": "Those will have gardens of perpetual residence; beneath them rivers will flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein on adorned couches. Excellent is the reward, and good is the resting place."}, {"ayah": 32, "translit": "Wadrib lahum masalar rajulaini ja'alnaa li ahadihimaa jannataini min a'naabinw wa hafafnaahumaa binakhilinw wa ja'alnaa bainahumaa zar'aa", "translation": "And present to them an example of two men: We granted to one of them two gardens of grapevines, and We bordered them with palm trees and placed between them [fields of] crops."}, {"ayah": 33, "translit": "Kiltal jannataini aatat ukulahaa wa lam tazlim minhu shai'anw wa fajjarnaa khi laalahumaa naharaa", "translation": "Each of the two gardens produced its fruit and did not fall short thereof in anything. And We caused to gush forth within them a river."}, {"ayah": 34, "translit": "Wa kaana lahoo samarun faqaala lisaahibihee wa huwa yuhaawiruhoo ana aksaru minka maalanw wa a'azzu nafaraa", "translation": "And he had fruit, so he said to his companion while he was conversing with him, \"I am greater than you in wealth and mightier in [numbers of] men.\""}, {"ayah": 35, "translit": "Wa dakhala jannatahoo wa huwa zaalimul linafsihee qaala maaa azunnu an tabeeda haaziheee abadaa", "translation": "And he entered his garden while he was unjust to himself. He said, \"I do not think that this will perish - ever."}, {"ayah": 36, "translit": "Wa maaa azunnus Saa'ata qaaa'imatanw wa la'ir rudittu ilaa Rabbee la ajidanna khairam minhaa munqalabaa", "translation": "And I do not think the Hour will occur. And even if I should be brought back to my Lord, I will surely find better than this as a return.\""}, {"ayah": 37, "translit": "Qaala lahoo saahibuhoo wa huwa yuhaawiruhooo akafarta billazee khalaqaka min turaabin summa min nutfatin summa sawwaaka rajulaa", "translation": "His companion said to him while he was conversing with him, \"Have you disbelieved in He who created you from dust and then from a sperm-drop and then proportioned you [as] a man?"}, {"ayah": 38, "translit": "Laakinaa Huwal laahu Rabbee wa laa ushriku bi Rabbeee ahadaa", "translation": "But as for me, He is Allah, my Lord, and I do not associate with my Lord anyone."}, {"ayah": 39, "translit": "Wa law laaa iz dakhalta jannataka qulta maa shaaa'al laahu laa quwwata illaa billaah; in tarani ana aqalla minka maalanw wa waladaa", "translation": "And why did you, when you entered your garden, not say, 'What Allah willed [has occurred]; there is no power except in Allah '? Although you see me less than you in wealth and children,"}, {"ayah": 40, "translit": "Fa'asaa Rabeee any yu'tiyani khairam min jannatika wa yursila 'alaihaa husbaanam minas samaaa'i fatusbiha sa'eedan zalaqaa", "translation": "It may be that my Lord will give me [something] better than your garden and will send upon it a calamity from the sky, and it will become a smooth, dusty ground,"}, {"ayah": 41, "translit": "Aw yusbiha maaa'uhaaa ghawran falan tastatee'a lahoo talabaa", "translation": "Or its water will become sunken [into the earth], so you would never be able to seek it.\""}, {"ayah": 42, "translit": "Wa uheeta bisamarihee faasbaha yuqallibu kaffaihi 'alaa maaa anfaqa feehaa wa hiya khaawiyatun 'alaa 'urooshihaa wa yaqoolu yaalaitanee lam ushrik bi Rabbeee ahadaa", "translation": "And his fruits were encompassed [by ruin], so he began to turn his hands about [in dismay] over what he had spent on it, while it had collapsed upon its trellises, and said, \"Oh, I wish I had not associated with my Lord anyone.\""}, {"ayah": 43, "translit": "Wa lam takul lahoo fi'atuny yansuroonahoo min doonil laahi wa maa kaana muntasiraa", "translation": "And there was for him no company to aid him other than Allah, nor could he defend himself."}, {"ayah": 44, "translit": "Hunaalikal walaayatu lillaahil haqq; huwa khairun sawaabanw wa khairun 'uqbaa", "translation": "There the authority is [completely] for Allah, the Truth. He is best in reward and best in outcome."}, {"ayah": 45, "translit": "Wadrib lahum masalal hayaatid dunyaa kamaaa'in anzalnaahu minas samaaa'i fakhtalata bihee nabaatul ardi fa asbaha hasheeman tazroo hur riyaah; wa kaanal laahu 'alaa kulli shai'im muqtadiraa", "translation": "And present to them the example of the life of this world, [its being] like rain which We send down from the sky, and the vegetation of the earth mingles with it and [then] it becomes dry remnants, scattered by the winds. And Allah is ever, over all things, Perfect in Ability."}, {"ayah": 46, "translit": "Almaalu walbanoona zeenatul hayaatid dunya wal baaqiyaatus saalihaatu khairun 'inda Rabbika sawaabanw wa khairun amalaa", "translation": "Wealth and children are [but] adornment of the worldly life. But the enduring good deeds are better to your Lord for reward and better for [one's] hope."}, {"ayah": 47, "translit": "Wa yawma nusaiyirul jibaala wa taral arda baariza tanw wa hasharnaahum falam nughaadir minhum ahadaa", "translation": "And [warn of] the Day when We will remove the mountains and you will see the earth prominent, and We will gather them and not leave behind from them anyone."}, {"ayah": 48, "translit": "Wa 'uridoo 'alaa Rabbika saffaa, laqad ji'tumoonaa kamaa khalaqnaakum awala marrah; bal za'amtum allannaj'ala lakum maw'idaa", "translation": "And they will be presented before your Lord in rows, [and He will say], \"You have certainly come to Us just as We created you the first time. But you claimed that We would never make for you an appointment.\""}, {"ayah": 49, "translit": "Wa wudi'al kitaabu fataral mujrimeena mushfiqeena mimmaa feehi wa yaqooloona yaa wailatanaa maa lihaazal kitaabi laa yughaadiru saghee ratanw wa laa kabeeratan illaaa ahsaahaa; wa wajadoo maa 'amiloo haadiraa; wa laa yazlimu Rabbuka ahadaa (Section 6)", "translation": "And the record [of deeds] will be placed [open], and you will see the criminals fearful of that within it, and they will say, \"Oh, woe to us! What is this book that leaves nothing small or great except that it has enumerated it?\" And they will find what they did present [before them]. And your Lord does injustice to no one."}, {"ayah": 50, "translit": "Wa iz qulnaa lilma laaa'ikatis judoo li Aadama fasajadooo illaaa Ibleesa kaana minal jinni fafasaqa 'an amri Rabbih; afatattakhizoonahoo wa zurriyatahooo awliyaaa'a min doonee wa hum lakum 'aduww; bi'sa lizzaalimeena badalaa", "translation": "And [mention] when We said to the angels, \"Prostrate to Adam,\" and they prostrated, except for Iblees. He was of the jinn and departed from the command of his Lord. Then will you take him and his descendants as allies other than Me while they are enemies to you? Wretched it is for the wrongdoers as an exchange."}, {"ayah": 51, "translit": "Maaa ash hattuhum khalqas samaawaati wal ardi wa laa khalqa anfusihim wa maa kuntu muttakizal mudilleena 'adudaa", "translation": "I did not make them witness to the creation of the heavens and the earth or to the creation of themselves, and I would not have taken the misguiders as assistants."}, {"ayah": 52, "translit": "Wa Yawma yaqoolu naadoo shurakaaa'i yal lazeena za'amtum fada'awhum falam yastajeeboo lahum wa ja'alnaa bainahum maw biqaa", "translation": "And [warn of] the Day when He will say, \"Call 'My partners' whom you claimed,\" and they will invoke them, but they will not respond to them. And We will put between them [a valley of] destruction."}, {"ayah": 53, "translit": "Wa ra al mujrimoonan Naara fazannooo annahum muwaaqi'oohaa wa lam yajidoo 'anhaa masrifaa", "translation": "And the criminals will see the Fire and will be certain that they are to fall therein. And they will not find from it a way elsewhere."}, {"ayah": 54, "translit": "Wa laqad sarrafnaa fee haazal quraani linnaasi mn kulli masal; wa kaanal insaanu aksara shai'in jadalaa", "translation": "And We have certainly diversified in this Qur'an for the people from every [kind of] example; but man has ever been, most of anything, [prone to] dispute."}, {"ayah": 55, "translit": "Wa maa mana'an naasa any yu'minooo iz jaaa'ahumul hudaa wa yastaghfiroo Rabbahum illaaa an taatiyahum sunnatul awwaleena aw yaatiyahumul 'azaabu qubulaa", "translation": "And nothing has prevented the people from believing when guidance came to them and from asking forgiveness of their Lord except that there [must] befall them the [accustomed] precedent of the former peoples or that the punishment should come [directly] before them."}, {"ayah": 56, "translit": "Wa maa nursilul mursaleena illaa mubashshireena wa munzireen; wa yujaadilul lazeena kafaroo bilbaatili liyudhidoo bihil haqqa wattakhazooo Aayaatee wa maaa unziroo huzuwaa", "translation": "And We send not the messengers except as bringers of good tidings and warners. And those who disbelieve dispute by [using] falsehood to [attempt to] invalidate thereby the truth and have taken My verses, and that of which they are warned, in ridicule."}, {"ayah": 57, "translit": "Wa man azlamu mimman zukkira bi ayaati Rabbihee fa-a'rada 'anhaa wa nasiya maa qaddamat yadaah; innaa ja'alnaa 'alaa quloobihim akinnatan any yafqahoohu wa feee aazaanihim waqraa; wa in tad'uhum ilal hudaa falany yahtadooo izan abadaa", "translation": "And who is more unjust than one who is reminded of the verses of his Lord but turns away from them and forgets what his hands have put forth? Indeed, We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if you invite them to guidance - they will never be guided, then - ever."}, {"ayah": 58, "translit": "Wa Rabbukal Ghafooru zur rahmati law yu'aakhi zuhum bimaa kasaboo la'ajala lahumul 'azaab; bal lahum maw'idul lany yajidoo min doonihee maw'ilaa", "translation": "And your Lord is the Forgiving, full of mercy. If He were to impose blame upon them for what they earned, He would have hastened for them the punishment. Rather, for them is an appointment from which they will never find an escape."}, {"ayah": 59, "translit": "Wa tkal quraaa ahlak nahum lammaa zulamoo wa ja'alnaa limahlikihim maw'idaa", "translation": "And those cities - We destroyed them when they wronged, and We made for their destruction an appointed time."}, {"ayah": 60, "translit": "Wa iz qaalaa Moosaa lifataahu laaa abrahu hattaaa ablugha majma'al bahrayni aw amdiya huqubaa", "translation": "And [mention] when Moses said to his servant, \"I will not cease [traveling] until I reach the junction of the two seas or continue for a long period.\""}, {"ayah": 61, "translit": "Falammaa balaghaa majma'a bainihimaa nasiyaa hootahumaa fattakhaza sabeelahoo fil bahri sarabaa", "translation": "But when they reached the junction between them, they forgot their fish, and it took its course into the sea, slipping away."}, {"ayah": 62, "translit": "Falammaa jaawazaa qaala lifataahu aatinaa ghadaaa'anaa laqad laqeena min safarinaa haazaa nasabaa", "translation": "So when they had passed beyond it, [Moses] said to his boy, \"Bring us our morning meal. We have certainly suffered in this, our journey, [much] fatigue.\""}, {"ayah": 63, "translit": "Qaala ara'ayta iz awainaaa ilas sakhrati fa innee naseetul hoota wa maaa ansaaneehu illash Shaitaanu an azkurah; wattakhaza sabeelahoo fil bahri'ajabaa", "translation": "He said, \"Did you see when we retired to the rock? Indeed, I forgot [there] the fish. And none made me forget it except Satan - that I should mention it. And it took its course into the sea amazingly\"."}, {"ayah": 64, "translit": "Qaala zaalika maa kunnaa nabgh; fartaddaa 'alaa aasaari him maa qasasaa", "translation": "[Moses] said, \"That is what we were seeking.\" So they returned, following their footprints."}, {"ayah": 65, "translit": "Fa wajadaa 'abdam min 'ibaadinaaa aatainaahu Rahmatam min 'indinaa wa 'allamnaahu mil ladunnaa 'ilmaa", "translation": "And they found a servant from among Our servants to whom we had given mercy from us and had taught him from Us a [certain] knowledge."}, {"ayah": 66, "translit": "Qaala lahoo Moosaa hal attabi'uka 'alaaa an tu'allimani mimmaa 'ullimta rushdaa", "translation": "Moses said to him, \"May I follow you on [the condition] that you teach me from what you have been taught of sound judgement?\""}, {"ayah": 67, "translit": "Qaalaa innaka lan tastatee'a ma'iya sabraa", "translation": "He said, \"Indeed, with me you will never be able to have patience."}, {"ayah": 68, "translit": "Wa kaifa tasbiru 'alaa maa lam tuhit bihee khubraa", "translation": "And how can you have patience for what you do not encompass in knowledge?\""}, {"ayah": 69, "translit": "Qaala satajiduneee in shaa 'al laahu saabiranw wa laaa a'see laka amraa", "translation": "[Moses] said, \"You will find me, if Allah wills, patient, and I will not disobey you in [any] order.\""}, {"ayah": 70, "translit": "Qaala fa init taba'tanee falaa tas'alnee 'an shai'in hattaaa uhdisa laka minhu zikraa", "translation": "He said, \"Then if you follow me, do not ask me about anything until I make to you about it mention.\""}, {"ayah": 71, "translit": "Fantalaqaa hattaaa izaa rakibaa fis safeenati kharaqahaa qaala akharaqtahaa litughriqa ahlahaa laqad ji'ta shai'an imraa", "translation": "So they set out, until when they had embarked on the ship, al-Khidh r tore it open. [Moses] said, \"Have you torn it open to drown its people? You have certainly done a grave thing.\""}, {"ayah": 72, "translit": "Qaala alam aqul innaka lan tastatee'a ma'iya sabraa", "translation": "[Al-Khidh r] said, \"Did I not say that with me you would never be able to have patience?\""}, {"ayah": 73, "translit": "Qaala laa tu'aakhiznee bimaa naseetu wa laa turhiqnee min amree 'usraa", "translation": "[Moses] said, \"Do not blame me for what I forgot and do not cover me in my matter with difficulty.\""}, {"ayah": 74, "translit": "Fantalaqaa hattaa izaa laqiyaa ghulaaman faqatalahoo qaala aqatalta nafsan zakiy yatam bighairi nafs; laqad ji'ta shai'an nukraa", "translation": "So they set out, until when they met a boy, al-Khidh r killed him. [Moses] said, \"Have you killed a pure soul for other than [having killed] a soul? You have certainly done a deplorable thing.\""}, {"ayah": 75, "translit": "Qaala alam aqul laka innaka lan tastatee'a ma'iya sabraa", "translation": "[Al-Khidh r] said, \"Did I not tell you that with me you would never be able to have patience?\""}, {"ayah": 76, "translit": "Qaala in sa altuka 'an shai'im ba'dahaa falaa tusaahibnee qad balaghta mil ladunnee 'uzraa", "translation": "[Moses] said, \"If I should ask you about anything after this, then do not keep me as a companion. You have obtained from me an excuse.\""}, {"ayah": 77, "translit": "Fantalaqaa hattaaa izaaa atayaaa ahla qaryatinis tat'amaaa ahlahaa fa abaw any yudaiyifoohumaa fawajadaa feehaa jidaarany yureedu any yanqadda fa aqaamah; qaala law shi'ta lattakhazta 'alaihi ajraa", "translation": "So they set out, until when they came to the people of a town, they asked its people for food, but they refused to offer them hospitality. And they found therein a wall about to collapse, so al-Khidh r restored it. [Moses] said, \"If you wished, you could have taken for it a payment.\""}, {"ayah": 78, "translit": "Qaala haazaa firaaqu bainee wa bainik; sa unabi 'uka bitaaweeli maa lam tastati' 'alaihi sabraa", "translation": "[Al-Khidh r] said, \"This is parting between me and you. I will inform you of the interpretation of that about which you could not have patience."}, {"ayah": 79, "translit": "Ammas safeenatu fakaanat limasaakeena ya'maloona fil bahri fa arattu an a'eebahaa wa kaana waraaa' ahum malikuny yaakhuzu kulla safeenatin ghasbaa", "translation": "As for the ship, it belonged to poor people working at sea. So I intended to cause defect in it as there was after them a king who seized every [good] ship by force."}, {"ayah": 80, "translit": "Wa aammal ghulaamu fakaana abawaahu mu'minaini fakhasheenaaa any yurhiqa humaa tughyaananw wa kufraa", "translation": "And as for the boy, his parents were believers, and we feared that he would overburden them by transgression and disbelief."}, {"ayah": 81, "translit": "Faradnaa any yubdila humaa Rabbuhumaa khairam minhu zakaatanw wa aqraba ruhmaa", "translation": "So we intended that their Lord should substitute for them one better than him in purity and nearer to mercy."}, {"ayah": 82, "translit": "Wa ammal jidaaru fakaana lighulaamaini yateemaini fil madeenati wa kaana tahtahoo kanzul lahumaa wa kaana aboohumaa saalihan fa araada Rabbuka any yablughaaa ashuddahumaa wa yastakhrijaa kanzahumaa rahmatam mir Rabbik; wa maa fa'altuhoo 'an amree; zaalika taaweelu maa lam tasti' 'alaihi sabra", "translation": "And as for the wall, it belonged to two orphan boys in the city, and there was beneath it a treasure for them, and their father had been righteous. So your Lord intended that they reach maturity and extract their treasure, as a mercy from your Lord. And I did it not of my own accord. That is the interpretation of that about which you could not have patience.\""}, {"ayah": 83, "translit": "Wa yas'aloonaka 'an Zil Qarnaini qul sa atloo 'alaikum minhu zikraa", "translation": "And they ask you, [O Muhammad], about Dhul-Qarnayn. Say, \"I will recite to you about him a report.\""}, {"ayah": 84, "translit": "Innaa makkannaa lahoo fil ardi wa aatainaahu min kulli shai'in sababaa", "translation": "Indeed We established him upon the earth, and We gave him to everything a way."}, {"ayah": 85, "translit": "Fa atba'a sababaa", "translation": "So he followed a way"}, {"ayah": 86, "translit": "Hattaaa izaa balagha maghribash shamsi wajadahaaa taghrubu fee 'aynin hami'a tinw wa wajada 'indahaa qawmaa; qulnaa yaa Zal Qarnaini immaaa an tu'az ziba wa immaaa an tattakhiza feehim husnaa", "translation": "Until, when he reached the setting of the sun, he found it [as if] setting in a spring of dark mud, and he found near it a people. Allah said, \"O Dhul-Qarnayn, either you punish [them] or else adopt among them [a way of] goodness.\""}, {"ayah": 87, "translit": "Qaala amaa man zalama fasawfa nu'azzibuhoo summa yuraddu ilaa Rabbihee fa yu 'azzibuhoo azaaban nukraa", "translation": "He said, \"As for one who wrongs, we will punish him. Then he will be returned to his Lord, and He will punish him with a terrible punishment."}, {"ayah": 88, "translit": "Wa ammaa man aamana wa 'amila saalihan falahoo jazaaa'anil husnaa wa sanaqoolu lahoo min amrinaa yusraa", "translation": "But as for one who believes and does righteousness, he will have a reward of Paradise, and we will speak to him from our command with ease.\""}, {"ayah": 89, "translit": "Summa atba'a sababaa", "translation": "Then he followed a way"}, {"ayah": 90, "translit": "Hattaaa izaa balagha matli'ash shamsi wajdahaa tatlu'u alaa qawmil lam naj'al lahum min doonihaa sitraa", "translation": "Until, when he came to the rising of the sun, he found it rising on a people for whom We had not made against it any shield."}, {"ayah": 91, "translit": "Kazaalika wa qad ahatnaa bimaa ladaihi khubraa", "translation": "Thus. And We had encompassed [all] that he had in knowledge."}, {"ayah": 92, "translit": "Summa atba'a sababaa", "translation": "Then he followed a way"}, {"ayah": 93, "translit": "Hattaaa izaa balagha bainas saddaini wajada min doonihimaa qawmal laa yakaa doona yafqahoona qawlaa", "translation": "Until, when he reached [a pass] between two mountains, he found beside them a people who could hardly understand [his] speech."}, {"ayah": 94, "translit": "Qaaloo yaa Zal qarnaini inna Yaajooja wa Maajooja mufsidoona fil ardi fahal naj'alu laka kharjan 'alaaa an taj'ala bainanaa wa bainahum saddas", "translation": "They said, \"O Dhul-Qarnayn, indeed Gog and Magog are [great] corrupters in the land. So may we assign for you an expenditure that you might make between us and them a barrier?\""}, {"ayah": 95, "translit": "Qaala maa makkannee feehi Rabbee khairun fa-a'eenoonee biquwwatin aj'al bainakum wa bainahum radmaa", "translation": "He said, \"That in which my Lord has established me is better [than what you offer], but assist me with strength; I will make between you and them a dam."}, {"ayah": 96, "translit": "Aatoonee zubaral hadeed, hattaaa izaa saawaa bainas sadafaini qaalan fukhoo hattaaa izaa ja'alahoo naaran qaala aatooneee ufrigh 'alaihi qitraa", "translation": "Bring me sheets of iron\" - until, when he had leveled [them] between the two mountain walls, he said, \"Blow [with bellows],\" until when he had made it [like] fire, he said, \"Bring me, that I may pour over it molten copper.\""}, {"ayah": 97, "translit": "Famas taa'ooo any yazharoohu wa mastataa'oo lahoo naqbaa", "translation": "So Gog and Magog were unable to pass over it, nor were they able [to effect] in it any penetration."}, {"ayah": 98, "translit": "Qaala haaza rahmatummir Rabbee fa izaa jaaa'a wa'du Rabbee ja'alahoo dakkaaa'a; wa kaana; wa du Rabbee haqqaa", "translation": "[Dhul-Qarnayn] said, \"This is a mercy from my Lord; but when the promise of my Lord comes, He will make it level, and ever is the promise of my Lord true.\""}, {"ayah": 99, "translit": "Wa taraknaa ba'dahum Yawma'iziny yamooju fee ba'dinw wa nufikha fis Soori fajama'naahum jam'aa", "translation": "And We will leave them that day surging over each other, and [then] the Horn will be blown, and We will assemble them in [one] assembly."}, {"ayah": 100, "translit": "Wa 'aradnaa jahannama Yawma'izil lilkaafireena 'ardaa", "translation": "And We will present Hell that Day to the Disbelievers, on display -"}, {"ayah": 101, "translit": "Allazeena kaanat a'yunuhum fee ghitaaa'in 'an zikree wa kaanoo la yastatee'oona sam'aa (section 11)", "translation": "Those whose eyes had been within a cover [removed] from My remembrance, and they were not able to hear."}, {"ayah": 102, "translit": "Afahasibal lazeena kafarooo any yattakhizoo 'ibaadee min dooneee awliyaaa'; innaaa a'tadnaa jahannama lilkaafi reena nuzulaa", "translation": "Then do those who disbelieve think that they can take My servants instead of Me as allies? Indeed, We have prepared Hell for the disbelievers as a lodging."}, {"ayah": 103, "translit": "Qul hal nunabbi'ukum bilakhsareena a'maalaa", "translation": "Say, [O Muhammad], \"Shall we [believers] inform you of the greatest losers as to [their] deeds?"}, {"ayah": 104, "translit": "Allazeena dalla sa'yuhum fil hayaatid dunyaa wa hum yahsaboona annahum yuhsinoona sun'aa", "translation": "[They are] those whose effort is lost in worldly life, while they think that they are doing well in work.\""}, {"ayah": 105, "translit": "Ulaaa'ikal lazeena kafaroo bi aayaati Rabbihim wa liqaaa'ihee fahabitat a'maaluhum falaa nuqeemu lahum Yawmal Qiyaamati waznaa", "translation": "Those are the ones who disbelieve in the verses of their Lord and in [their] meeting Him, so their deeds have become worthless; and We will not assign to them on the Day of Resurrection any importance."}, {"ayah": 106, "translit": "Zaalika jazaaa'uhum jahannamu bimaa kafaroo wattakhazooo Aayaatee wa Rusulee huzuwaa", "translation": "That is their recompense - Hell - for what they denied and [because] they took My signs and My messengers in ridicule."}, {"ayah": 107, "translit": "Innal lazeena aamanoo wa 'amilus saalihaati kaanat lahum Jannaatul Firdawsi nuzulaa", "translation": "Indeed, those who have believed and done righteous deeds - they will have the Gardens of Paradise as a lodging,"}, {"ayah": 108, "translit": "Khaalideena feeha la yabghoona 'anhaa hiwalaa", "translation": "Wherein they abide eternally. They will not desire from it any transfer."}, {"ayah": 109, "translit": "Qul law kaanal bahru midaadal lik Kalimaati Rabbee lanafidal bahru qabla an tanfada Kalimaatu Rabbee wa law ji'naa bimislihee madadaa", "translation": "Say, \"If the sea were ink for [writing] the words of my Lord, the sea would be exhausted before the words of my Lord were exhausted, even if We brought the like of it as a supplement.\""}, {"ayah": 110, "translit": "Qul innamaaa ana basharum mislukum yoohaaa ilaiya annamaa ilaahukum Ilaahunw Waahid; faman kaana yarjoo liqaaa'a Rabbihee falya'mal 'amalan saalihanw wa laa yushrik bi'ibaadati Rabbiheee ahadaa", "translation": "Say, \"I am only a man like you, to whom has been revealed that your god is one God. So whoever would hope for the meeting with his Lord - let him do righteous work and not associate in the worship of his Lord anyone.\""}]}, {"num": 19, "name": "Maryam", "meaning": "Mary", "verses": [{"ayah": 1, "translit": "Kaaaf-Haa-Yaa-'Ayyyn-Saaad", "translation": "Kaf, Ha, Ya, 'Ayn, Sad."}, {"ayah": 2, "translit": "Zikru rahmati Rabbika 'abdahoo Zakariyya", "translation": "[This is] a mention of the mercy of your Lord to His servant Zechariah"}, {"ayah": 3, "translit": "Iz naadaa Rabbahoo nidaaa'an khafiyyaa", "translation": "When he called to his Lord a private supplication."}, {"ayah": 4, "translit": "Qaala Rabbi innee wahanal'azmu minnee washta'alar raasu shaibanw wa lam akum bidu'aaa'ika Rabbi shaqiyyaa", "translation": "He said, \"My Lord, indeed my bones have weakened, and my head has filled with white, and never have I been in my supplication to You, my Lord, unhappy."}, {"ayah": 5, "translit": "Wa innee khiftul mawaa liya minw waraaa'ee wa kaana tim ra atee 'aairan fahab lee mil ladunka waliyyaa", "translation": "And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir"}, {"ayah": 6, "translit": "Yarisunee wa yarisu min aali Ya'qoob, waj'alhu Rabbi radiyya", "translation": "Who will inherit me and inherit from the family of Jacob. And make him, my Lord, pleasing [to You].\""}, {"ayah": 7, "translit": "Yaa Zakariyyaaa innaa nubashshiruka bighulaami nismuhoo Yahyaa lam naj'al lahoo min qablu samiyyaa", "translation": "[He was told], \"O Zechariah, indeed We give you good tidings of a boy whose name will be John. We have not assigned to any before [this] name.\""}, {"ayah": 8, "translit": "Qaala Rabbi annaa yakoonu lee ghulaamunw wa kaanatim ra atee aaqiranw wa qad balaghtu minal kibari 'itiyyaa", "translation": "He said, \"My Lord, how will I have a boy when my wife has been barren and I have reached extreme old age?\""}, {"ayah": 9, "translit": "Qaala kazaalika qaala Rabbuka huwa 'alaiya haiyinunw wa qad khalaqtuka min qablu wa lam taku shai'aa", "translation": "[An angel] said, \"Thus [it will be]; your Lord says, 'It is easy for Me, for I created you before, while you were nothing.' \""}, {"ayah": 10, "translit": "Qaala Rabbij 'al leee Aayah; qaala Aayatuka allaa tukalliman naasa salaasa layaalin sawiyyaa", "translation": "[Zechariah] said, \"My Lord, make for me a sign.\" He said, \"Your sign is that you will not speak to the people for three nights, [being] sound.\""}, {"ayah": 11, "translit": "Fakharaja 'alaa qawmihee minal mihraabi fa-awhaaa ilaihim an sabbihoo bukratanw wa 'ashiyyaa", "translation": "So he came out to his people from the prayer chamber and signaled to them to exalt [Allah] in the morning and afternoon."}, {"ayah": 12, "translit": "Yaa Yahyaa khuzil Kitaaba biquwwatinw wa aatainaahul hukma saiyyaa", "translation": "[Allah] said, \"O John, take the Scripture with determination.\" And We gave him judgement [while yet] a boy"}, {"ayah": 13, "translit": "Wa hanaanam mil ladunnaa wa zakaatanw wa kaana taqiyyaa", "translation": "And affection from Us and purity, and he was fearing of Allah"}, {"ayah": 14, "translit": "Wa barram biwaalidayhi wa lam yakum jabbaaran 'asiyyaa", "translation": "And dutiful to his parents, and he was not a disobedient tyrant."}, {"ayah": 15, "translit": "Wa salaamun 'alaihi yawma wulida wa yawma yamootu wa yawma yub'asu haiyaa", "translation": "And peace be upon him the day he was born and the day he dies and the day he is raised alive."}, {"ayah": 16, "translit": "Wazkur fil Kitaabi Marya; izin tabazat min ahlihaa makaanan shariqyyaa", "translation": "And mention, [O Muhammad], in the Book [the story of] Mary, when she withdrew from her family to a place toward the east."}, {"ayah": 17, "translit": "Fattakhazat min doonihim hijaaban fa arsalnaaa ilaihaa roohanaa fatamassala lahaa basharan sawiyyaa", "translation": "And she took, in seclusion from them, a screen. Then We sent to her Our Angel, and he represented himself to her as a well-proportioned man."}, {"ayah": 18, "translit": "Qaalat inneee a'oozu bir Rahmaani minka in kunta taqiyyaa", "translation": "She said, \"Indeed, I seek refuge in the Most Merciful from you, [so leave me], if you should be fearing of Allah.\""}, {"ayah": 19, "translit": "Qaala innamaa ana rasoolu Rabbiki li ahaba laki ghulaaman zakiyyaa", "translation": "He said, \"I am only the messenger of your Lord to give you [news of] a pure boy.\""}, {"ayah": 20, "translit": "Qaalat anna yakoonu lee ghulaamunw wa lam yamsasnee bashrunw wa lam aku baghiyyaa", "translation": "She said, \"How can I have a boy while no man has touched me and I have not been unchaste?\""}, {"ayah": 21, "translit": "Qaala kazaaliki qaala Rabbuki huwa 'alaiya yaiyimunw wa linaj 'alahooo Aayatal linnaasi wa rahmatam minnaa; wa kaana amram maqdiyyaa", "translation": "He said, \"Thus [it will be]; your Lord says, 'It is easy for Me, and We will make him a sign to the people and a mercy from Us. And it is a matter [already] decreed.' \""}, {"ayah": 22, "translit": "Fahamalat hu fantabazat bihee makaanan qasiyyaa", "translation": "So she conceived him, and she withdrew with him to a remote place."}, {"ayah": 23, "translit": "Fa ajaaa 'ahal makhaadu ilaa jiz'in nakhlati qaalat yaa laitanee mittu qabla haazaa wa kuntu nasyam mansiyyaa", "translation": "And the pains of childbirth drove her to the trunk of a palm tree. She said, \"Oh, I wish I had died before this and was in oblivion, forgotten.\""}, {"ayah": 24, "translit": "Fanaadaahaa min tahtihaan allaa tahzanee qad ja'ala Rabbuki tahtaki sariyyaa", "translation": "But he called her from below her, \"Do not grieve; your Lord has provided beneath you a stream."}, {"ayah": 25, "translit": "Wa huzzeee ilaiki bijiz 'in nakhlati tusaaqit 'alaiki rutaban janiyyaa", "translation": "And shake toward you the trunk of the palm tree; it will drop upon you ripe, fresh dates."}, {"ayah": 26, "translit": "Fakulee washrabee wa qarree 'ainaa; fa immaa tarayinnna minal bashari ahadan faqooleee innee nazartu lir Rahmaani sawman falan ukallimal yawma insiyyaa", "translation": "So eat and drink and be contented. And if you see from among humanity anyone, say, 'Indeed, I have vowed to the Most Merciful abstention, so I will not speak today to [any] man.' \""}, {"ayah": 27, "translit": "Fa atat bihee qawmahaa tahmiluhoo qaaloo yaa Maryamoo laqad ji'ti shai'an fariyyaa", "translation": "Then she brought him to her people, carrying him. They said, \"O Mary, you have certainly done a thing unprecedented."}, {"ayah": 28, "translit": "Yaaa ukkhta Haaroona maa kaana abokim ra-a saw'inw wa maa kaanat ummuki baghiyyaa", "translation": "O sister of Aaron, your father was not a man of evil, nor was your mother unchaste.\""}, {"ayah": 29, "translit": "Fa ashaarat ilaih; qaaloo kaifa nukallimu man kaana fil mahdi sabiyyaa", "translation": "So she pointed to him. They said, \"How can we speak to one who is in the cradle a child?\""}, {"ayah": 30, "translit": "Qaala innee 'abdullaahi aataaniyal Kitaaba wa ja'alanee Nabiyyaa", "translation": "[Jesus] said, \"Indeed, I am the servant of Allah. He has given me the Scripture and made me a prophet."}, {"ayah": 31, "translit": "Wa ja'alanee mubaarakan aina maa kuntu wa awsaanee bis Salaati waz Zakaati maa dumtu haiyaa", "translation": "And He has made me blessed wherever I am and has enjoined upon me prayer and zakah as long as I remain alive"}, {"ayah": 32, "translit": "Wa barram biwaalidatee wa lam yaj'alnee jabbaaran shaqiyyaa", "translation": "And [made me] dutiful to my mother, and He has not made me a wretched tyrant."}, {"ayah": 33, "translit": "Wassalaamu 'alaiya yawma wulittu wa yawma amootu wa yawma ub'asu baiyaa", "translation": "And peace is on me the day I was born and the day I will die and the day I am raised alive.\""}, {"ayah": 34, "translit": "Zaalika 'Eesab-nu Marya; qawlal haqqil lazee feehi yamtaroon", "translation": "That is Jesus, the son of Mary - the word of truth about which they are in dispute."}, {"ayah": 35, "translit": "Maa kaana lillaahi ai yattakhiza minw waladin Subhaanah; izaa qadaaa amran fa innamaa yaqoolu lahoo kun fa yakoon", "translation": "It is not [befitting] for Allah to take a son; exalted is He! When He decrees an affair, He only says to it, \"Be,\" and it is."}, {"ayah": 36, "translit": "Wa innal laaha Rabbee wa Rabbukum fa'budooh; haazaa Siraatum Mustaqeem", "translation": "[Jesus said], \"And indeed, Allah is my Lord and your Lord, so worship Him. That is a straight path.\""}, {"ayah": 37, "translit": "Fakhtalafal ahzaabu mim bainihim fawailul lillazeena kafaroo mim mashhadi Yawmin 'azeem", "translation": "Then the factions differed [concerning Jesus] from among them, so woe to those who disbelieved - from the scene of a tremendous Day."}, {"ayah": 38, "translit": "Asmi' bihim wa absir Yawma yaatoonanaa laakiniz zaalimoonal yawma fee dalaalim mubeen", "translation": "How [clearly] they will hear and see the Day they come to Us, but the wrongdoers today are in clear error."}, {"ayah": 39, "translit": "Wa anzirhum Yawmal hasrati iz qudiyal amr; wa hum fee ghaflatinw wa hum laa yu'minoon", "translation": "And warn them, [O Muhammad], of the Day of Regret, when the matter will be concluded; and [yet], they are in [a state of] heedlessness, and they do not believe."}, {"ayah": 40, "translit": "Innaa NNahnu narisul arda wa man 'alaihaa wa ilainaa yurja'oon (section 2)", "translation": "Indeed, it is We who will inherit the earth and whoever is on it, and to Us they will be returned."}, {"ayah": 41, "translit": "Wazkur fil Kitaabi Ibraaheem; innahoo kaana siddeeqan Nabiyyaa", "translation": "And mention in the Book [the story of] Abraham. Indeed, he was a man of truth and a prophet."}, {"ayah": 42, "translit": "Iz qaala li abeehi yaaa abati lima ta'budu maa laa yasma'u wa laa yubsiru wa laa yughnee 'anka shai'aa", "translation": "[Mention] when he said to his father, \"O my father, why do you worship that which does not hear and does not see and will not benefit you at all?"}, {"ayah": 43, "translit": "Yaaa abati innee qad jaaa'anee minal 'ilmi maa lam yaatika fattabi'neee ahdika siraatan Sawiyyaa", "translation": "O my father, indeed there has come to me of knowledge that which has not come to you, so follow me; I will guide you to an even path."}, {"ayah": 44, "translit": "Yaaa abati laa ta'budish Shaitaana innash Shaitaana kaana lir Rahmaani 'asiyyaa", "translation": "O my father, do not worship Satan. Indeed Satan has ever been, to the Most Merciful, disobedient."}, {"ayah": 45, "translit": "Yaaa abati innee akhaafu ai yamssaka 'azaabum minar Rahmaani fatakoona lish Shaitaani waliyyaa", "translation": "O my father, indeed I fear that there will touch you a punishment from the Most Merciful so you would be to Satan a companion [in Hellfire].\""}, {"ayah": 46, "translit": "Qaala araaghibun anta 'an aalihatee yaaa Ibraaheemu la 'il lam tantahi la arjumannaka wahjumee maliyyaa", "translation": "[His father] said, \"Have you no desire for my gods, O Abraham? If you do not desist, I will surely stone you, so avoid me a prolonged time.\""}, {"ayah": 47, "translit": "Qaala salaamun 'alaika sa astaghfiru laka Rabbeee innahoo kaana bee hafiyyaa", "translation": "[Abraham] said, \"Peace will be upon you. I will ask forgiveness for you of my Lord. Indeed, He is ever gracious to me."}, {"ayah": 48, "translit": "Wa a'tazilukum wa maa tad'oona min doonil laahi wa ad'o Rabbee 'asaaa allaaa akoona bidu'aaa'i Rabbee shaqiyyaa", "translation": "And I will leave you and those you invoke other than Allah and will invoke my Lord. I expect that I will not be in invocation to my Lord unhappy.\""}, {"ayah": 49, "translit": "Falamma' tazalahum wa maa ya'budoona min doonil laahi wahabnaa lahoo is-haaqa wa ya'qoob, wa kullan ja'alnaa Nabiyyaa", "translation": "So when he had left them and those they worshipped other than Allah, We gave him Isaac and Jacob, and each [of them] We made a prophet."}, {"ayah": 50, "translit": "Wa wahabnaa lahum mirrahmatinaa wa ja'alnaa lahum lisaana sidqin 'aliyyaa", "translation": "And We gave them of Our mercy, and we made for them a reputation of high honor."}, {"ayah": 51, "translit": "Wazkur fil Kitaabi Moosaaa; innahoo kaana mukhlasanw wa kaana Rasoolan Nabiyyaa", "translation": "And mention in the Book, Moses. Indeed, he was chosen, and he was a messenger and a prophet."}, {"ayah": 52, "translit": "Wa naadainaahu min jaanibit Tooril aimani wa qarrabnaahu najiyyaa", "translation": "And We called him from the side of the mount at [his] right and brought him near, confiding [to him]."}, {"ayah": 53, "translit": "Wa wahabnaa lahoo mir rahmatinaaa akhaahu Haaroona Nabiyyaa", "translation": "And We gave him out of Our mercy his brother Aaron as a prophet."}, {"ayah": 54, "translit": "Wazkur fil Kitaabi ismaa'eel; innahoo kaana saadiqal wa'di wa kaana Rasoolan Nabiyyaa", "translation": "And mention in the Book, Ishmael. Indeed, he was true to his promise, and he was a messenger and a prophet."}, {"ayah": 55, "translit": "Wa kaana yaamuru ahlahoo bis Salaati waz zakaati wa kaana 'inda Rabbihee mardiyyaa", "translation": "And he used to enjoin on his people prayer and zakah and was to his Lord pleasing."}, {"ayah": 56, "translit": "Wazkur fil Kitaabi Idrees; innahoo kaana siddeeqan Nabiyyaa", "translation": "And mention in the Book, Idrees. Indeed, he was a man of truth and a prophet."}, {"ayah": 57, "translit": "Wa rafa'naahu makaanan 'aliyyaa", "translation": "And We raised him to a high station."}, {"ayah": 58, "translit": "Ulaaa'ikal lazeena an'amal laahu 'alaihim minan Nabiyyeena min zurriyyati Aadama wa mimman hamalnaa ma'a Noohinw wa min zurriyyati Ibraaheema wa Israaa'eela wa mimman hadainaa wajta bainaaa; izaa tutlaa 'alaihim Aayaatur Rahmaani kharroo sujjadanw wa bukiyyaa", "translation": "Those were the ones upon whom Allah bestowed favor from among the prophets of the descendants of Adam and of those We carried [in the ship] with Noah, and of the descendants of Abraham and Israel, and of those whom We guided and chose. When the verses of the Most Merciful were recited to them, they fell in prostration and weeping."}, {"ayah": 59, "translit": "Fakhalafa mim ba'dihim khalfun adaa'us Salaata wattaba'ush shahawaati fasawfa yalqawna ghaiyaa", "translation": "But there came after them successors who neglected prayer and pursued desires; so they are going to meet evil -"}, {"ayah": 60, "translit": "Illaa man taaba wa aamana wa 'amila saalihan fa ulaaa'ika yadkhuloonal jannata wa laa yuzlamoona shai'aa", "translation": "Except those who repent, believe and do righteousness; for those will enter Paradise and will not be wronged at all."}, {"ayah": 61, "translit": "Jannaati 'adninil latee wa'adar Rahmaanu ibaadahoo bilghaib; innahoo kaana wa'duhoo maatiyyaa", "translation": "[Therein are] gardens of perpetual residence which the Most Merciful has promised His servants in the unseen. Indeed, His promise has ever been coming."}, {"ayah": 62, "translit": "Laa yasma'oona feehaa laghwan illaa salaamaa; wa lahum rizquhum feehaa bukratanw wa 'ashiyyaa", "translation": "They will not hear therein any ill speech - only [greetings of] peace - and they will have their provision therein, morning and afternoon."}, {"ayah": 63, "translit": "Tilkal jannatul latee oorisu min 'ibaadinaa man kaana taqiyyaa", "translation": "That is Paradise, which We give as inheritance to those of Our servants who were fearing of Allah."}, {"ayah": 64, "translit": "Wa maa natanazzalu illaa bi amri Rabbika lahoo maa baina aideenaa wa maa khalfanaa wa maa baina zaalik; wa maa kaana Rabbuka nasiyyaa", "translation": "[Gabriel said], \"And we [angels] descend not except by the order of your Lord. To Him belongs that before us and that behind us and what is in between. And never is your Lord forgetful -"}, {"ayah": 65, "translit": "Rabbus samaawaati wal ardi wa maa bainahumaa fa'bud hu wastabir li'ibaadatih; hal ta'lamu lahoo samiyyaa", "translation": "Lord of the heavens and the earth and whatever is between them - so worship Him and have patience for His worship. Do you know of any similarity to Him?\""}, {"ayah": 66, "translit": "Wa yaqoolul insaanu 'aizaa maa mittu lasawfa ukhraju haiyaa", "translation": "And the disbeliever says, \"When I have died, am I going to be brought forth alive?\""}, {"ayah": 67, "translit": "awalaa yazkurul insaanu annaa khalaqnaahu min qablu wa lam yaku shai'aa", "translation": "Does man not remember that We created him before, while he was nothing?"}, {"ayah": 68, "translit": "Fawa Rabbika lanahshu rannahum wash shayaateena summa lanuhdirannahum hawla jahannama jisiyyaa", "translation": "So by your Lord, We will surely gather them and the devils; then We will bring them to be present around Hell upon their knees."}, {"ayah": 69, "translit": "Summa lananzi 'anna min kulli shee'atin aiyuhum ashaddu 'alar Rahmaani 'itiyyaa", "translation": "Then We will surely extract from every sect those of them who were worst against the Most Merciful in insolence."}, {"ayah": 70, "translit": "Summa lanahnu a'lamu billazeena hum awlaa bihaa siliyyaa", "translation": "Then, surely it is We who are most knowing of those most worthy of burning therein."}, {"ayah": 71, "translit": "Wa im minkum illaa waa riduhaa; kaana 'alaa Rabbika hatmam maqdiyyaa", "translation": "And there is none of you except he will come to it. This is upon your Lord an inevitability decreed."}, {"ayah": 72, "translit": "Summa nunajjil lazeenat taqaw wa nazaruz zaalimeena feehaa jisiyyaa", "translation": "Then We will save those who feared Allah and leave the wrongdoers within it, on their knees."}, {"ayah": 73, "translit": "Wa izaa tutlaa 'alaihim Aayaatunaa baiyinaatin qaalal lazeena kafaroo lillazeena aamanooo aiyul fareeqaini khairum maqaamanw wa ahsanu nadiyyaa", "translation": "And when Our verses are recited to them as clear evidences, those who disbelieve say to those who believe, \"Which of [our] two parties is best in position and best in association?\""}, {"ayah": 74, "translit": "Wa kam ahlaknaa qablahum min qarnin hum ahsanu asaasanw wa ri'yaa", "translation": "And how many a generation have We destroyed before them who were better in possessions and [outward] appearance?"}, {"ayah": 75, "translit": "Qul man kaana fidda laalati falyamdud lahur Rahmaanu maddaa; hattaaa izaa ra aw maa yoo'adoona immal 'azaaba wa immas Saa'ata fasa ya'lamoona man huwa sharrum makaananw wa ad'afu jundaa", "translation": "Say, \"Whoever is in error - let the Most Merciful extend for him an extension [in wealth and time] until, when they see that which they were promised - either punishment [in this world] or the Hour [of resurrection] - they will come to know who is worst in position and weaker in soldiers.\""}, {"ayah": 76, "translit": "Wa yazeedul laahul lazeenah tadaw hudaa; wal baaqiyaatus saalihaatu khairun 'inda Rabbika sawaabanw wa khairum maraddaa", "translation": "And Allah increases those who were guided, in guidance, and the enduring good deeds are better to your Lord for reward and better for recourse."}, {"ayah": 77, "translit": "Afara'aytal lazee kafara bi Aayaatinaa wa qaala la oota yanna maalanw wa waladaa", "translation": "Then, have you seen he who disbelieved in Our verses and said, \"I will surely be given wealth and children [in the next life]?\""}, {"ayah": 78, "translit": "Attala'al ghaiba amitta khaza'indar Rahmaani 'ahdaa", "translation": "Has he looked into the unseen, or has he taken from the Most Merciful a promise?"}, {"ayah": 79, "translit": "Kallaa; sanaktubu maa yaqoolu wa namuddu lahoo minal 'azaabi maddaa", "translation": "No! We will record what he says and extend for him from the punishment extensively."}, {"ayah": 80, "translit": "Wa narisuhoo maa yaqoolu wa yaateenaa fardaa", "translation": "And We will inherit him [in] what he mentions, and he will come to Us alone."}, {"ayah": 81, "translit": "Wattakhazoo min doonil laahi aalihatal liyakoonoo lahum 'izzaa", "translation": "And they have taken besides Allah [false] deities that they would be for them [a source of] honor."}, {"ayah": 82, "translit": "Kallaa; sa yakfuroona bi'ibaadatihim wa yakoonoona 'alaihim diddaa", "translation": "No! Those \"gods\" will deny their worship of them and will be against them opponents [on the Day of Judgement]."}, {"ayah": 83, "translit": "Alam tara annaaa arsalnash Shayaateena 'alal kaafireena ta'uzzuhum azzaa", "translation": "Do you not see that We have sent the devils upon the disbelievers, inciting them to [evil] with [constant] incitement?"}, {"ayah": 84, "translit": "Falaa ta'jal alaihim innamaa na 'uddu lahum 'addaa", "translation": "So be not impatient over them. We only count out to them a [limited] number."}, {"ayah": 85, "translit": "Yawma nahshurul muttaqeena ilar Rahmaani wafdaa", "translation": "On the Day We will gather the righteous to the Most Merciful as a delegation"}, {"ayah": 86, "translit": "Wa nasooqul mujrimeena ilaa Jahannama wirdaa", "translation": "And will drive the criminals to Hell in thirst"}, {"ayah": 87, "translit": "Laa yamlikoonash shafaa'ta illaa manittakhaza 'indar Rahmaani 'ahdaa", "translation": "None will have [power of] intercession except he who had taken from the Most Merciful a covenant."}, {"ayah": 88, "translit": "Wa qaalut takhazar Rahmaanu waladaa", "translation": "And they say, \"The Most Merciful has taken [for Himself] a son.\""}, {"ayah": 89, "translit": "Laqad ji'tum shai'an iddaa", "translation": "You have done an atrocious thing."}, {"ayah": 90, "translit": "Takaadus samaawaatu yatafattarna minhu wa tanshaq qul ardu wa takhirrul jibaalu haddaa", "translation": "The heavens almost rupture therefrom and the earth splits open and the mountains collapse in devastation"}, {"ayah": 91, "translit": "An da'aw lir Rahmaani waladaa", "translation": "That they attribute to the Most Merciful a son."}, {"ayah": 92, "translit": "Wa maa yambaghee lir Rahmaani ai yattakhiza waladaa", "translation": "And it is not appropriate for the Most Merciful that He should take a son."}, {"ayah": 93, "translit": "In kullu man fis samaawaati wal ardi illaaa aatir Rahmaani 'abdaa", "translation": "There is no one in the heavens and earth but that he comes to the Most Merciful as a servant."}, {"ayah": 94, "translit": "Laqad ahsaahum wa addahum 'addaa", "translation": "He has enumerated them and counted them a [full] counting."}, {"ayah": 95, "translit": "Wa kulluhum aateehi Yawmal Qiyaamati fardaa", "translation": "And all of them are coming to Him on the Day of Resurrection alone."}, {"ayah": 96, "translit": "Innal lazeena aamanoo wa 'amilus saalihaati sa yaj'alu lahumur Rahmaanu wuddaa", "translation": "Indeed, those who have believed and done righteous deeds - the Most Merciful will appoint for them affection."}, {"ayah": 97, "translit": "Fa innamaa yassarnaahu bilisaanika litubashshira bihil muttaqeena wa tunzira bihee qawmal luddaa", "translation": "So, [O Muhammad], We have only made Qur'an easy in the Arabic language that you may give good tidings thereby to the righteous and warn thereby a hostile people."}, {"ayah": 98, "translit": "Wa kam ahlaknaa qabla hum min qarnin hal tuhissu minhum min ahadin aw tasma'u lahum rikzaa", "translation": "And how many have We destroyed before them of generations? Do you perceive of them anyone or hear from them a sound?"}]}, {"num": 20, "name": "Ta-Ha", "meaning": "Ta-Ha", "verses": [{"ayah": 1, "translit": "Taa-Haa", "translation": "Ta, Ha."}, {"ayah": 2, "translit": "Maaa anzalnaa 'alaikal Qur-aana litashqaaa", "translation": "We have not sent down to you the Qur'an that you be distressed"}, {"ayah": 3, "translit": "Illaa tazkiratal limany yakshaa", "translation": "But only as a reminder for those who fear [Allah] -"}, {"ayah": 4, "translit": "Tanzeelam mimman khalaqal arda was samaawaatil 'ulaa", "translation": "A revelation from He who created the earth and highest heavens,"}, {"ayah": 5, "translit": "Ar-Rahmaanu 'alal 'Arshis tawaa", "translation": "The Most Merciful [who is] above the Throne established."}, {"ayah": 6, "translit": "Lahoo maa fis samaawaati wa maa fil ardi wa maa bainahumaa wa maa tahtassaraa", "translation": "To Him belongs what is in the heavens and what is on the earth and what is between them and what is under the soil."}, {"ayah": 7, "translit": "Wa in tajhar bilqawli fainnahoo ya'lamus sirra wa akhfaa", "translation": "And if you speak aloud - then indeed, He knows the secret and what is [even] more hidden."}, {"ayah": 8, "translit": "Allaahu laaa ilasha illaa Huwa lahul Asmaaa'ul Husnaa", "translation": "Allah - there is no deity except Him. To Him belong the best names."}, {"ayah": 9, "translit": "Wa hal ataaka hadeesu Moosa", "translation": "And has the story of Moses reached you? -"}, {"ayah": 10, "translit": "Iz ra aa naaran faqaala li alhlihim kusooo inneee aanastu naaral la'alleee aateekum minhaa biqabasin aw ajidu 'alan naari hudaa", "translation": "When he saw a fire and said to his family, \"Stay here; indeed, I have perceived a fire; perhaps I can bring you a torch or find at the fire some guidance.\""}, {"ayah": 11, "translit": "Falammaaa ataahaa noodiya yaa Moosaa", "translation": "And when he came to it, he was called, \"O Moses,"}, {"ayah": 12, "translit": "Inneee Ana Rabbuka fakhla' na'laika innaka bilwaadil muqaddasi Tuwaa", "translation": "Indeed, I am your Lord, so remove your sandals. Indeed, you are in the sacred valley of Tuwa."}, {"ayah": 13, "translit": "Wa anakhtartuka fastami' limaa yoohaa", "translation": "And I have chosen you, so listen to what is revealed [to you]."}, {"ayah": 14, "translit": "Innaneee Anal laahu laaa ilaaha illaa Ana fa'budnee wa aqimis-salaata lizikree", "translation": "Indeed, I am Allah. There is no deity except Me, so worship Me and establish prayer for My remembrance."}, {"ayah": 15, "translit": "Innas Saa'ata aatiyatun akaadu ukhfeehaa litujzaa kullu nafsim bimaa tas'aa", "translation": "Indeed, the Hour is coming - I almost conceal it - so that every soul may be recompensed according to that for which it strives."}, {"ayah": 16, "translit": "Falaa yasuddannnaka 'anhaa mal laa yu'minu bihaa wattaba'a hawaahu fatardaa", "translation": "So do not let one avert you from it who does not believe in it and follows his desire, for you [then] would perish."}, {"ayah": 17, "translit": "Wa maa tilka bi yamee nika yaa Moosaa", "translation": "And what is that in your right hand, O Moses?\""}, {"ayah": 18, "translit": "Qaala hiya 'asaaya atawakka'u alaihaa wa ahushshu bihaa 'alaa ghanamee wa liya feehaa ma aaribu ukhraa", "translation": "He said, \"It is my staff; I lean upon it, and I bring down leaves for my sheep and I have therein other uses.\""}, {"ayah": 19, "translit": "Qaala alqihaa yaa Moosaa", "translation": "[Allah] said, \"Throw it down, O Moses.\""}, {"ayah": 20, "translit": "Fa-alqaahaa fa -izaa hiya haiyatun tas'aa", "translation": "So he threw it down, and thereupon it was a snake, moving swiftly."}, {"ayah": 21, "translit": "Qaala khuzhaa wa laa ta khaf sanu'eeduhaa seeratahal oolaa", "translation": "[Allah] said, \"Seize it and fear not; We will return it to its former condition."}, {"ayah": 22, "translit": "Wadmum yadaka ilaa janaahika takhruj baidaaa'a min ghairi sooo'in Aayatan ukhraa", "translation": "And draw in your hand to your side; it will come out white without disease - another sign,"}, {"ayah": 23, "translit": "Linuriyaka min Aayaatinal Kubra", "translation": "That We may show you [some] of Our greater signs."}, {"ayah": 24, "translit": "Izhab ilaa Fir'awna innahoo taghaa", "translation": "Go to Pharaoh. Indeed, he has transgressed.\""}, {"ayah": 25, "translit": "Qaala Rabbish rah lee sadree", "translation": "[Moses] said, \"My Lord, expand for me my breast [with assurance]"}, {"ayah": 26, "translit": "Wa yassir leee amree", "translation": "And ease for me my task"}, {"ayah": 27, "translit": "Wahlul 'uqdatam milli saanee", "translation": "And untie the knot from my tongue"}, {"ayah": 28, "translit": "Yafqahoo qawlee", "translation": "That they may understand my speech."}, {"ayah": 29, "translit": "Waj'al lee wazeeram min ahlee", "translation": "And appoint for me a minister from my family -"}, {"ayah": 30, "translit": "Haaroona akhee", "translation": "Aaron, my brother."}, {"ayah": 31, "translit": "Ushdud biheee azree", "translation": "Increase through him my strength"}, {"ayah": 32, "translit": "Wa ashrik hu feee amree", "translation": "And let him share my task"}, {"ayah": 33, "translit": "Kai nusabbihaka kaseeraa", "translation": "That we may exalt You much"}, {"ayah": 34, "translit": "Wa nazkuraka kaseeraa", "translation": "And remember You much."}, {"ayah": 35, "translit": "Innaka kunta binaa baseeraa", "translation": "Indeed, You are of us ever Seeing.\""}, {"ayah": 36, "translit": "Qaala qad ooteeta su'laka yaa Moosaa", "translation": "[Allah] said, \"You have been granted your request, O Moses."}, {"ayah": 37, "translit": "Wa laqad manannaa 'alaika marratan ukhraaa", "translation": "And We had already conferred favor upon you another time,"}, {"ayah": 38, "translit": "Iz awhainaaa ilaaa ummika maa yoohaaa", "translation": "When We inspired to your mother what We inspired,"}, {"ayah": 39, "translit": "Aniqzifeehi fit Taabooti faqzifeehi fil yammi fal yul qihil yammu bis saahili yaakhuzhu 'aduwwul lee wa 'aduwwul lah; wa alqaitu 'alaika mahabbatam minnee wa litusna'a 'alaa 'ainee", "translation": "[Saying], 'Cast him into the chest and cast it into the river, and the river will throw it onto the bank; there will take him an enemy to Me and an enemy to him.' And I bestowed upon you love from Me that you would be brought up under My eye."}, {"ayah": 40, "translit": "Iz tamsheee ukhtuka fataqoolu hal adullukum 'alaa mai yakfuluhoo faraja 'naaka ilaaa ummika kai taqarra 'ainuhaa wa laa tahzan; wa qatalta nafsan fanajjainaaka minal ghammi wa fatannaaka futoonaa; falabista sineena feee ahli Madyana summa ji'ta 'alaa qadariny yaa Moosa", "translation": "[And We favored you] when your sister went and said, 'Shall I direct you to someone who will be responsible for him?' So We restored you to your mother that she might be content and not grieve. And you killed someone, but We saved you from retaliation and tried you with a [severe] trial. And you remained [some] years among the people of Madyan. Then you came [here] at the decreed time, O Moses."}, {"ayah": 41, "translit": "Wastana' tuka linafsee", "translation": "And I produced you for Myself."}, {"ayah": 42, "translit": "Izhab anta wa akhooka bi Aayaatee wa laa taniyaa fee zikree", "translation": "Go, you and your brother, with My signs and do not slacken in My remembrance."}, {"ayah": 43, "translit": "Izhabaaa ilaa Fir'awna innahoo taghaa", "translation": "Go, both of you, to Pharaoh. Indeed, he has transgressed."}, {"ayah": 44, "translit": "Faqoolaa lahoo qawlal laiyinal la allahoo yatazakkkaru 'aw yakhshaa", "translation": "And speak to him with gentle speech that perhaps he may be reminded or fear [Allah].\""}, {"ayah": 45, "translit": "Qaalaa Rabbanaaa innanaa nakhaafu ai yafruta 'alainaaa aw ai yatghaa", "translation": "They said, \"Our Lord, indeed we are afraid that he will hasten [punishment] against us or that he will transgress.\""}, {"ayah": 46, "translit": "Qaala laa takhaafaaa innanee ma'akumaa asma'u wa araa", "translation": "[Allah] said, \"Fear not. Indeed, I am with you both; I hear and I see."}, {"ayah": 47, "translit": "Faatiyaahu faqoolaaa innaa Rasoolaa Rabbika fa arsil ma'anaa Banee Israaa'eela wa laa tu'azzibhum qad ji'naaka bi Aayatim mir Rabbika wassa laamu 'alaa manit taba'al hudaa", "translation": "So go to him and say, 'Indeed, we are messengers of your Lord, so send with us the Children of Israel and do not torment them. We have come to you with a sign from your Lord. And peace will be upon he who follows the guidance."}, {"ayah": 48, "translit": "Innaa qad oohiya ilainaaa annnal 'azaaba 'alaa man kaz zaba wa tawalla", "translation": "Indeed, it has been revealed to us that the punishment will be upon whoever denies and turns away.' \""}, {"ayah": 49, "translit": "Qaala famar Rabbu kumaa yaa Moosa", "translation": "[Pharaoh] said, \"So who is the Lord of you two, O Moses?\""}, {"ayah": 50, "translit": "Qaala Rabbunal lazeee a'taa kulla shai'in khalqahoo summa hadaa", "translation": "He said, \"Our Lord is He who gave each thing its form and then guided [it].\""}, {"ayah": 51, "translit": "Qaala famaa baalul quroonil oolaa", "translation": "[Pharaoh] said, \"Then what is the case of the former generations?\""}, {"ayah": 52, "translit": "Qaala 'ilmuhaa 'inda Rabee fee kitaab, laa yadillu Rabbee wa laa yansaa", "translation": "[Moses] said, \"The knowledge thereof is with my Lord in a record. My Lord neither errs nor forgets.\""}, {"ayah": 53, "translit": "Allazee ja'ala lakumul arda mahdanw wa salaka lakum feehaa subulanw wa anzala minas samaaa'i maaa'an fa akhrajnaa biheee azwaajam min nabaatin shatta", "translation": "[It is He] who has made for you the earth as a bed [spread out] and inserted therein for you roadways and sent down from the sky, rain and produced thereby categories of various plants."}, {"ayah": 54, "translit": "Kuloo war'aw an'aamakum; inna fee zaalika la Aayaatil li ulin nuhaa", "translation": "Eat [therefrom] and pasture your livestock. Indeed, in that are signs for those of intelligence."}, {"ayah": 55, "translit": "Minhaa khalaqnaakum wa feehaa nu'eedukum wa minhaa nukhrijukum taaratan ukhraa", "translation": "From the earth We created you, and into it We will return you, and from it We will extract you another time."}, {"ayah": 56, "translit": "Wa laqad arainaahu Aayaatinaa kullahaa fakaz zaba wa abaa", "translation": "And We certainly showed Pharaoh Our signs - all of them - but he denied and refused."}, {"ayah": 57, "translit": "Qaala aji'tanaa litukhri janaa min ardinaa bisihrika yaa Moosa", "translation": "He said, \"Have you come to us to drive us out of our land with your magic, O Moses?"}, {"ayah": 58, "translit": "Falanaatiyannaka bisihrim mislihee faj'al bainanaa wa bainaka maw'idal laa nukhlifuhoo nahnu wa laaa anta makaanan suwaa", "translation": "Then we will surely bring you magic like it, so make between us and you an appointment, which we will not fail to keep and neither will you, in a place assigned.\""}, {"ayah": 59, "translit": "Qaala maw'idukum yawmuz zeenati wa ai yuhsharan naasu duhaa", "translation": "[Moses] said, \"Your appointment is on the day of the festival when the people assemble at mid-morning.\""}, {"ayah": 60, "translit": "Fatawallaa Fir'awnu fajjama'a kaidahoo summa ataa", "translation": "So Pharaoh went away, put together his plan, and then came [to Moses]."}, {"ayah": 61, "translit": "Qaala lahum Moosaa wailakum laa taftaroo 'alal laahi kaziban fa yus hitakum bi 'azaab, wa qad khaaba manif taraa", "translation": "Moses said to the magicians summoned by Pharaoh, \"Woe to you! Do not invent a lie against Allah or He will exterminate you with a punishment; and he has failed who invents [such falsehood].\""}, {"ayah": 62, "translit": "Fatanaaza'ooo amrahum bainahum wa asarrun najwaa", "translation": "So they disputed over their affair among themselves and concealed their private conversation."}, {"ayah": 63, "translit": "Qaalooo in haaazaani lasaahiraani yureedaani ai yukhrijaakum min ardikum bisihrihimaa wa yazhabaa bitareeqatikumul muslaa", "translation": "They said, \"Indeed, these are two magicians who want to drive you out of your land with their magic and do away with your most exemplary way."}, {"ayah": 64, "translit": "Fa ajmi'oo kaidakum summma'too saffaa; wa qad aflahal yawma manis ta'laa", "translation": "So resolve upon your plan and then come [forward] in line. And he has succeeded today who overcomes.\""}, {"ayah": 65, "translit": "Qaaloo yaa Moosaaa immaaa an tulqiya wa immaaa an nakoona awala man alqaa", "translation": "They said, \"O Moses, either you throw or we will be the first to throw.\""}, {"ayah": 66, "translit": "Qaala bal alqoo fa izaa hibaaluhum wa 'isiyyuhum yuhaiyalu ilaihi min sihrihim annahaa tas'aa", "translation": "He said, \"Rather, you throw.\" And suddenly their ropes and staffs seemed to him from their magic that they were moving [like snakes]."}, {"ayah": 67, "translit": "Fa awjasa fee nafsihee kheefatam Moosa", "translation": "And he sensed within himself apprehension, did Moses."}, {"ayah": 68, "translit": "Qulnaa laa takhaf innaka antal a'laa", "translation": "Allah said, \"Fear not. Indeed, it is you who are superior."}, {"ayah": 69, "translit": "Wa alqi maa fee yamee nika talqaf maa sana'oo; innamaa sana'oo kaidu saahir; wa laa yuflihus saahiru haisu ataa", "translation": "And throw what is in your right hand; it will swallow up what they have crafted. What they have crafted is but the trick of a magician, and the magician will not succeed wherever he is.\""}, {"ayah": 70, "translit": "Fa ulqiyas saharatu sujjadan qaalooo aamannaa bi Rabbi Haaroona wa Moosa", "translation": "So the magicians fell down in prostration. They said, \"We have believed in the Lord of Aaron and Moses.\""}, {"ayah": 71, "translit": "Qaala aamantum lahoo qabla an aazana lakum; innahoo lakabeerukumul lazee 'allama kumus sihra fala uqatti'anna aidiyakum wa arjulakum min khilaafinw wa la usallibannakum fee juzoo'in nakhli wa lata'lamunna aiyunaaa ashaddu 'azaabanw wa abqaa", "translation": "[Pharaoh] said, \"You believed him before I gave you permission. Indeed, he is your leader who has taught you magic. So I will surely cut off your hands and your feet on opposite sides, and I will crucify you on the trunks of palm trees, and you will surely know which of us is more severe in [giving] punishment and more enduring.\""}, {"ayah": 72, "translit": "Qaaloo lan nu'siraka 'alaa maa jaaa'anaa minal baiyinaati wallazee fataranaa faqdi maaa anta qaad; innamaa taqdee haazihil hayaatad dunyaa", "translation": "They said, \"Never will we prefer you over what has come to us of clear proofs and [over] He who created us. So decree whatever you are to decree. You can only decree for this worldly life."}, {"ayah": 73, "translit": "Innaaa aamannaa bi Rabbinaa liyaghfira lanaa khataayaanaa wa maaa akrahtanaa 'alaihi minas sihr; wallaahu khairunw waabqaa", "translation": "Indeed, we have believed in our Lord that He may forgive us our sins and what you compelled us [to do] of magic. And Allah is better and more enduring.\""}, {"ayah": 74, "translit": "Innahoo mai yaati Rabbahoo mujriman fa inna lahoo Jahannama laa yamotu feehaa wa laa yahyaa", "translation": "Indeed, whoever comes to his Lord as a criminal - indeed, for him is Hell; he will neither die therein nor live."}, {"ayah": 75, "translit": "Wa mai yaatihee mu'minan qad 'amilas saalihaati fa ulaaa'ika lahumud dara jaatul 'ulaa", "translation": "But whoever comes to Him as a believer having done righteous deeds - for those will be the highest degrees [in position]:"}, {"ayah": 76, "translit": "Jannaatu 'Adnin tajree min tahtihal anhaaru khaalideena feehaa; wa zaalika jazaaa'ua man tazakka", "translation": "Gardens of perpetual residence beneath which rivers flow, wherein they abide eternally. And that is the reward of one who purifies himself."}, {"ayah": 77, "translit": "Wa laqad awhainaaa ilaa Moosaaa an asri bi'ibaadee fadrib lahum tareeqan fil bahri yabasal laa takhaafu darakanw wa laa takhshaa", "translation": "And We had inspired to Moses, \"Travel by night with My servants and strike for them a dry path through the sea; you will not fear being overtaken [by Pharaoh] nor be afraid [of drowning].\""}, {"ayah": 78, "translit": "Fa atba'ahum Fir'awnu bijunoodihee faghashiyahum minal yammmi maa ghashi yahum", "translation": "So Pharaoh pursued them with his soldiers, and there covered them from the sea that which covered them,"}, {"ayah": 79, "translit": "wa adalla fir'awnu qawmahoo wa maa hadaa", "translation": "And Pharaoh led his people astray and did not guide [them]."}, {"ayah": 80, "translit": "Yaa Baneee Israaa'eela qad anjainaakum min 'aduw wikum wa wa'adnaakum jaanibat Tooril aimana wa nazzalnaa 'alaikumul Manna was Salwaa", "translation": "O Children of Israel, We delivered you from your enemy, and We made an appointment with you at the right side of the mount, and We sent down to you manna and quails,"}, {"ayah": 81, "translit": "Kuloo min taiyibaati maa razaqnaakum wa laa tatghaw feehi fa yahilla 'alaikum ghadabee wa mai yahlil 'alaihi ghadabee faqad hawaa", "translation": "[Saying], \"Eat from the good things with which We have provided you and do not transgress [or oppress others] therein, lest My anger should descend upon you. And he upon whom My anger descends has certainly fallen.\""}, {"ayah": 82, "translit": "Wa innee la Ghaffaarul liman taaba wa aamana wa 'amila saalihan summah tadaa", "translation": "But indeed, I am the Perpetual Forgiver of whoever repents and believes and does righteousness and then continues in guidance."}, {"ayah": 83, "translit": "Wa maaa a'jalaka 'an qawmika yaa Moosa", "translation": "[Allah] said, \"And what made you hasten from your people, O Moses?\""}, {"ayah": 84, "translit": "Qaala hum ulaaa'i 'alaaa asaree wa 'ajiltu ilaika Rabbi litardaa", "translation": "He said, \"They are close upon my tracks, and I hastened to You, my Lord, that You be pleased.\""}, {"ayah": 85, "translit": "Qaala fa innaa qad fatannaa qawmaka mim ba'dika wa adallahumus Saamiriyy", "translation": "[Allah] said, \"But indeed, We have tried your people after you [departed], and the Samiri has led them astray.\""}, {"ayah": 86, "translit": "Faraja's Moosaaa ilaa qawmihee ghadbaana asifaa; qaala yaa qawmi alam ya'idkum Rabbukum wa'dan hasanaa; afataala 'alaikumul 'ahdu am arattum ai yahilla 'alaikum ghadabum mir Rabbikum fa akhlaftum maw'idee", "translation": "So Moses returned to his people, angry and grieved. He said, \"O my people, did your Lord not make you a good promise? Then, was the time [of its fulfillment] too long for you, or did you wish that wrath from your Lord descend upon you, so you broke your promise [of obedience] to me?\""}, {"ayah": 87, "translit": "Qaaloo maaa akhlafnaa maw'idaka bimalkinna wa laakinna hummilnaaa awzaaram min zeenatil qawmi faqazafnaahaa fakazaalika alqas Saamiriyy", "translation": "They said, \"We did not break our promise to you by our will, but we were made to carry burdens from the ornaments of the people [of Pharaoh], so we threw them [into the fire], and thus did the Samiri throw.\""}, {"ayah": 88, "translit": "Fa akhraja lahum 'ijlan jasadal lahoo khuwaarun faqaaloo haazaaa ilaahukum wa ilaahu Moosaa fanasee", "translation": "And he extracted for them [the statue of] a calf which had a lowing sound, and they said, \"This is your god and the god of Moses, but he forgot.\""}, {"ayah": 89, "translit": "Afalaa yarawna allaa yarji'u ilaihim qawlanw wa laa yamliku lahum darranw wa laa naf'aa", "translation": "Did they not see that it could not return to them any speech and that it did not possess for them any harm or benefit?"}, {"ayah": 90, "translit": "Wa laqad qaala lahum Haaroonu min qablu yaa qawmi innamaa futintum bihee wa inna Rabbakumur Rahmaanu fattabi'oonee wa atee'ooo amree", "translation": "And Aaron had already told them before [the return of Moses], \"O my people, you are only being tested by it, and indeed, your Lord is the Most Merciful, so follow me and obey my order.\""}, {"ayah": 91, "translit": "Qaaloo lan nabraha 'alaihi 'aakifeena hattaa yarji'a ilainaa Moosaa", "translation": "They said, \"We will never cease being devoted to the calf until Moses returns to us.\""}, {"ayah": 92, "translit": "Qaala Yaa Haaroonu maa mana 'aka iz ra aitahum dallooo", "translation": "[Moses] said, \"O Aaron, what prevented you, when you saw them going astray,"}, {"ayah": 93, "translit": "Allaa tattabi'ani afa'asaita amree", "translation": "From following me? Then have you disobeyed my order?\""}, {"ayah": 94, "translit": "Qaala yabna'umma laa taakhuz bilihyatee wa laa biraasee innee khashetu an taqoola farraqta baina Baneee Israaa'eela wa lam tarqub qawlee", "translation": "[Aaron] said, \"O son of my mother, do not seize [me] by my beard or by my head. Indeed, I feared that you would say, 'You caused division among the Children of Israel, and you did not observe [or await] my word.' \""}, {"ayah": 95, "translit": "Qaala famaa khatbuka yaa Saamiriyy", "translation": "[Moses] said, \"And what is your case, O Samiri?\""}, {"ayah": 96, "translit": "Qaala basurtu bimaa lam yabsuroo bihee faqabadtu qabdatam min asarir Rasooli fanabaztuhaa wa kazaalika sawwalat lee nafsee", "translation": "He said, \"I saw what they did not see, so I took a handful [of dust] from the track of the messenger and threw it, and thus did my soul entice me.\""}, {"ayah": 97, "translit": "Qaala fazhab fa inna laka fil hayaati an taqoola laa misaasa wa inna laka maw'idal lan tukhlafahoo wanzur ilaaa ilaahikal lazee zalta 'alaihi 'aakifaa; lanuharriqannnahoo summa lanansifanahoo fil yammi nasfaa", "translation": "[Moses] said, \"Then go. And indeed, it is [decreed] for you in [this] life to say, 'No contact.' And indeed, you have an appointment [in the Hereafter] you will not fail to keep. And look at your 'god' to which you remained devoted. We will surely burn it and blow it into the sea with a blast."}, {"ayah": 98, "translit": "Innamaaa ilaahukkumul laahul lazee laa ilaaha illaa Hoo; wasi'a kulla shai'in ilmaa", "translation": "Your god is only Allah, except for whom there is no deity. He has encompassed all things in knowledge.\""}, {"ayah": 99, "translit": "Kazaalika naqussu 'alaika min ambaaa'i maa qad sabaq; wa qad aatainaaka mil ladunnaa Zikraa", "translation": "Thus, [O Muhammad], We relate to you from the news of what has preceded. And We have certainly given you from Us the Qur'an."}, {"ayah": 100, "translit": "Man a'rada 'anhu, fa innahoo yahmilu Yawmal Qiyaamati wizraa", "translation": "Whoever turns away from it - then indeed, he will bear on the Day of Resurrection a burden,"}, {"ayah": 101, "translit": "Khaalideena feehi wa saaa'a lahum Yawmal Qiyaamati himlaa", "translation": "[Abiding] eternally therein, and evil it is for them on the Day of Resurrection as a load -"}, {"ayah": 102, "translit": "Yawma yunfakhu fissoori wa nahshurul mujrimeena Yawma 'izin zurqaa", "translation": "The Day the Horn will be blown. And We will gather the criminals, that Day, blue-eyed."}, {"ayah": 103, "translit": "Yatakhaafatoona bainahum il labistum illaa 'ashraa", "translation": "They will murmur among themselves, \"You remained not but ten [days in the world].\""}, {"ayah": 104, "translit": "nahnu a'lamu bimaa yaqooloona iz yaqoolu amsaluhum tareeqatan illabistum illaa yawmaa", "translation": "We are most knowing of what they say when the best of them in manner will say, \"You remained not but one day.\""}, {"ayah": 105, "translit": "Wa yas'aloonaka 'anil jibaali faqul yansifuhaa Rabbee nasfaa", "translation": "And they ask you about the mountains, so say, \"My Lord will blow them away with a blast."}, {"ayah": 106, "translit": "Fa yazaruhaa qaa'an safsafaa", "translation": "And He will leave the earth a level plain;"}, {"ayah": 107, "translit": "Laa taraa feehaa 'iwajanw wa laaa amtaa", "translation": "You will not see therein a depression or an elevation.\""}, {"ayah": 108, "translit": "Yawma iziny yattabi'oonad daa'iya laa 'iwaja lahoo wa khasha'atil aswaatu lir Rahmaani falaa tasma'u illaa hamsaa", "translation": "That Day, everyone will follow [the call of] the Caller [with] no deviation therefrom, and [all] voices will be stilled before the Most Merciful, so you will not hear except a whisper [of footsteps]."}, {"ayah": 109, "translit": "Yawma 'izil laa tanfa'ush shafaa'atu illaa man azina lahur Rahmaanu wa radiya lahoo qawlaa", "translation": "That Day, no intercession will benefit except [that of] one to whom the Most Merciful has given permission and has accepted his word."}, {"ayah": 110, "translit": "Ya'lamu maa bainaa aideehim wa maa khalfahum wa laa yauheetoona bihee 'ilmaa", "translation": "Allah knows what is [presently] before them and what will be after them, but they do not encompass it in knowledge."}, {"ayah": 111, "translit": "Wa 'anatil wujoohu lil Haiiyil Qaiyoomi wa qad khaaba man hamala zulmaa", "translation": "And [all] faces will be humbled before the Ever-Living, the Sustainer of existence. And he will have failed who carries injustice."}, {"ayah": 112, "translit": "Wa mai ya'mal minas saalihaati wa huwa mu'minun falaa yakhaafu zulmanw wa laa hadmaa", "translation": "But he who does of righteous deeds while he is a believer - he will neither fear injustice nor deprivation."}, {"ayah": 113, "translit": "Wa kazaalika anzalnaahu Qur-aanan 'Arabiyyanw wa sarrafnaa fee hi minal wa'eedi la'allahum yattaqoona aw yuhdisu lahum zikraa", "translation": "And thus We have sent it down as an Arabic Qur'an and have diversified therein the warnings that perhaps they will avoid [sin] or it would cause them remembrance."}, {"ayah": 114, "translit": "Fata'aalal laahul Malikul Haqq; wa laa ta'jal bil Quraani min qabli ai yuqdaaa ilaika wahyuhoo wa qur Rabbi zidnee 'ilmaa", "translation": "So high [above all] is Allah, the Sovereign, the Truth. And, [O Muhammad], do not hasten with [recitation of] the Qur'an before its revelation is completed to you, and say, \"My Lord, increase me in knowledge.\""}, {"ayah": 115, "translit": "Wa laqad 'ahidnaaa ilaaa Aadama min qablu fanasiya wa lam najid lahoo 'azmaa", "translation": "And We had already taken a promise from Adam before, but he forgot; and We found not in him determination."}, {"ayah": 116, "translit": "Wa iz qulnaa lilma laaa'ikatis judoo li Aadama fasajadooo illaaa Iblees; abaa", "translation": "And [mention] when We said to the angels, \"Prostrate to Adam,\" and they prostrated, except Iblees; he refused."}, {"ayah": 117, "translit": "Faqulnaa yaaa Aadamu inna haazaa 'aduwwul laka wa lizawjika falaa yukhrijan nakumaa minal Jannati fatashqaa", "translation": "So We said, \"O Adam, indeed this is an enemy to you and to your wife. Then let him not remove you from Paradise so you would suffer."}, {"ayah": 118, "translit": "Innaa laka allaa tajoo'a feeha wa laa ta'raa", "translation": "Indeed, it is [promised] for you not to be hungry therein or be unclothed."}, {"ayah": 119, "translit": "Wa annaka laa tazma'u feehaa wa laa tadhaa", "translation": "And indeed, you will not be thirsty therein or be hot from the sun.\""}, {"ayah": 120, "translit": "Fa waswasa ilaihish Shaitaanu qaala yaaa Aadamu hal adulluka 'alaa shajaratil khuldi wa mulkil laa yablaa", "translation": "Then Satan whispered to him; he said, \"O Adam, shall I direct you to the tree of eternity and possession that will not deteriorate?\""}, {"ayah": 121, "translit": "Fa akalaa minhaa fabadat lahumaa saw aatuhumaa wa tafiqaa yakhsifaani 'alaihimaa minw waraqil jannah; wa 'asaaa Aadamu Rabbahoo faghawaa", "translation": "And Adam and his wife ate of it, and their private parts became apparent to them, and they began to fasten over themselves from the leaves of Paradise. And Adam disobeyed his Lord and erred."}, {"ayah": 122, "translit": "Summaj tabbahu Rabbuhoo fataaba 'alaihi wa hadaa", "translation": "Then his Lord chose him and turned to him in forgiveness and guided [him]."}, {"ayah": 123, "translit": "Qaalah bita minhaa jamee'am ba'dukum liba'din 'aduww; fa immaa yaati yannakum minnee hudan famanit taba'a hudaaya falaa yadillu wa laa yashhqaa", "translation": "[Allah] said, \"Descend from Paradise - all, [your descendants] being enemies to one another. And if there should come to you guidance from Me - then whoever follows My guidance will neither go astray [in the world] nor suffer [in the Hereafter]."}, {"ayah": 124, "translit": "Wa man a'rada 'an Zikree fa inna lahoo ma'eeshatan dankanw wa nahshuruhoo Yawmal Qiyaamati a'maa", "translation": "And whoever turns away from My remembrance - indeed, he will have a depressed life, and We will gather him on the Day of Resurrection blind.\""}, {"ayah": 125, "translit": "Qaala Rabbi lima hashar tanee a'maa wa qad kuntu baseeraa", "translation": "He will say, \"My Lord, why have you raised me blind while I was [once] seeing?\""}, {"ayah": 126, "translit": "Qaala kazaalika atatka Aayaatunaa fanaseetahaa wa kazaalikal Yawma tunsaa", "translation": "[Allah] will say, \"Thus did Our signs come to you, and you forgot them; and thus will you this Day be forgotten.\""}, {"ayah": 127, "translit": "Wa kazaalika najzee man asrafa wa lam yu'mim bi Aayaati Rabbih; wa la'azaabul Aakhirati ashaddu wa abqaa", "translation": "And thus do We recompense he who transgressed and did not believe in the signs of his Lord. And the punishment of the Hereafter is more severe and more enduring."}, {"ayah": 128, "translit": "Afalam yahdi lahum kam ahlaknaa qablahum minal qurooni yamshoona fee masaakinihim; inna fee zaalika la Aayaatil li ulinnuhaa", "translation": "Then, has it not become clear to them how many generations We destroyed before them as they walk among their dwellings? Indeed in that are signs for those of intelligence."}, {"ayah": 129, "translit": "Wa law laa Kalimatun sabaqat mir Rabbika lakaana lizaamanw wa ajalum musammaa", "translation": "And if not for a word that preceded from your Lord, punishment would have been an obligation [due immediately], and [if not for] a specified term [decreed]."}, {"ayah": 130, "translit": "Fasbir 'alaa maa yaqooloona wa sabbih bihamdi Rabbika qabla tuloo'ish shamsi wa qabla ghuroobihaa wa min aanaaa'il laili fasbbih wa atraafan nahaari la 'allaka tardaa", "translation": "So be patient over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting; and during periods of the night [exalt Him] and at the ends of the day, that you may be satisfied."}, {"ayah": 131, "translit": "Wa laa tamuddanna 'ainaika ilaa ma matta'na biheee azwajam minhum zahratal hayaatid dunya linaftinahum feeh; wa rizqu Rabbika khairunw wa abqaa", "translation": "And do not extend your eyes toward that by which We have given enjoyment to [some] categories of them, [its being but] the splendor of worldly life by which We test them. And the provision of your Lord is better and more enduring."}, {"ayah": 132, "translit": "Waamur ahlaka bis Salaati wastabir 'alaihaa la nas'aluka rizqaa; nahnu narzuquk; wal 'aaqibatu littaqwaa", "translation": "And enjoin prayer upon your family [and people] and be steadfast therein. We ask you not for provision; We provide for you, and the [best] outcome is for [those of] righteousness."}, {"ayah": 133, "translit": "Wa qaaloo law laa yaateenaa bi Aayatim mmir Rabbih; awalam taatihim baiyinatu maa fis suhufil oolaa", "translation": "And they say, \"Why does he not bring us a sign from his Lord?\" Has there not come to them evidence of what was in the former scriptures?"}, {"ayah": 134, "translit": "Wa law annaaa ahlaknaahum bi'azaabim min qablihee laqaaloo Rabbanaa law laaa arsalta ilainaa Rasoolan fanattabi's Aayaatika min qabli an nazilla wa nakhzaa", "translation": "And if We had destroyed them with a punishment before him, they would have said, \"Our Lord, why did You not send to us a messenger so we could have followed Your verses before we were humiliated and disgraced?\""}, {"ayah": 135, "translit": "Qul kullum mutarabbisun fatarabbasoo fasta'lamoona man Ashaabus Siraatis Sawiyyi wa manih tadaa", "translation": "Say, \"Each [of us] is waiting; so wait. For you will know who are the companions of the sound path and who is guided.\""}]}, {"num": 21, "name": "Al-Anbiya", "meaning": "The Prophets", "verses": [{"ayah": 1, "translit": "Iqtaraba linnaasi hisaa buhum wa hum fee ghaflatim mu'ridoon", "translation": "[The time of] their account has approached for the people, while they are in heedlessness turning away."}, {"ayah": 2, "translit": "Maa yaateehim min zikrim mir Rabbihim muhdasin illas tama'oohu wa hum yal'aboon", "translation": "No mention comes to them anew from their Lord except that they listen to it while they are at play"}, {"ayah": 3, "translit": "Laahiyatan quloobuhum; wa asarrun najwal lazeena zalamoo hal haazaa illaa basharum mislukum afataa toonas sihra wa antum tubsiroon", "translation": "With their hearts distracted. And those who do wrong conceal their private conversation, [saying], \"Is this [Prophet] except a human being like you? So would you approach magic while you are aware [of it]?\""}, {"ayah": 4, "translit": "Qaala Rabbee ya'lamul qawla fis samaaa'i wal ardi wa Huwas Samee'ul Aleem", "translation": "The Prophet said, \"My Lord knows whatever is said throughout the heaven and earth, and He is the Hearing, the Knowing.\""}, {"ayah": 5, "translit": "Bal qaalooo adghaasu ahlaamim balif taraahu bal huwa shaa'irun falyaatinaa bi Aayatin kamaa ursilal awwaloon", "translation": "But they say, \"[The revelation is but] a mixture of false dreams; rather, he has invented it; rather, he is a poet. So let him bring us a sign just as the previous [messengers] were sent [with miracles].\""}, {"ayah": 6, "translit": "Maaa aaamanat qablahum min qaryatin ahlaknaahaa a-fahum yu'minoon", "translation": "Not a [single] city which We destroyed believed before them, so will they believe?"}, {"ayah": 7, "translit": "Wa maaa arsalnaa qablaka illaa rijaalan nooheee ilaihim fas'aloo ahlaz zikri in kuntum laa ta'lamoon", "translation": "And We sent not before you, [O Muhammad], except men to whom We revealed [the message], so ask the people of the message if you do not know."}, {"ayah": 8, "translit": "Wa maa ja'alnaahum jasadal laa yaakuloonat ta'aama wa maa kaanoo khaalideen", "translation": "And We did not make the prophets forms not eating food, nor were they immortal [on earth]."}, {"ayah": 9, "translit": "summa sadaqnaa humul wa'da fa-anjainaahum wa man nashaaa'u wa ahlaknal musrifeen", "translation": "Then We fulfilled for them the promise, and We saved them and whom We willed and destroyed the transgressors."}, {"ayah": 10, "translit": "Laqad anzalnaaa ilaikum Kitaaban feehi zikrukum afalaa ta'qiloon", "translation": "We have certainly sent down to you a Book in which is your mention. Then will you not reason?"}, {"ayah": 11, "translit": "Wa kam qasamnaa min qaryatin kannat zaalimatanw wa anshadnaa ba'dahaa qawman aakhareen", "translation": "And how many a city which was unjust have We shattered and produced after it another people."}, {"ayah": 12, "translit": "Falammaaa ahassoo baasanaaa izaaa hum minhaa yarkudoon", "translation": "And when its inhabitants perceived Our punishment, at once they fled from it."}, {"ayah": 13, "translit": "Laa tarkudoo warji'ooo ilaa maaa utriftum feehe wa masaakinikum la'allakum tus'aloon", "translation": "[Some angels said], \"Do not flee but return to where you were given luxury and to your homes - perhaps you will be questioned.\""}, {"ayah": 14, "translit": "Qaaloo yaa wailanaaa innaa kunnaa zaalimeen", "translation": "They said, \"O woe to us! Indeed, we were wrongdoers.\""}, {"ayah": 15, "translit": "Famaa zaalat tilka da'waahum hattaa ja'alnaahum haseedan khaamideen", "translation": "And that declaration of theirs did not cease until We made them [as] a harvest [mowed down], extinguished [like a fire]."}, {"ayah": 16, "translit": "Wa maa khalaqnas samaaa'a wal arda wa maa bainahumaa laa'ibeen", "translation": "And We did not create the heaven and earth and that between them in play."}, {"ayah": 17, "translit": "Law aradnaaa an nattakhiza lahwal lat takhaznaahu mil ladunnaaa in kunnaa faa'ileen", "translation": "Had We intended to take a diversion, We could have taken it from [what is] with Us - if [indeed] We were to do so."}, {"ayah": 18, "translit": "Bal naqzifu bilhaqqi 'alal baatili fa yadmaghuhoo fa izaa huwa zaahiq; wa lakumul wailu mimmaa tasifoon", "translation": "Rather, We dash the truth upon falsehood, and it destroys it, and thereupon it departs. And for you is destruction from that which you describe."}, {"ayah": 19, "translit": "Wa lahoo man fis samaawaati wal ard; wa man 'indahoo laa yastakbiroona 'an 'ibaada tihee wa laa yastahsiroon", "translation": "To Him belongs whoever is in the heavens and the earth. And those near Him are not prevented by arrogance from His worship, nor do they tire."}, {"ayah": 20, "translit": "Yusabbihoona laila wannahaara laa yafturoon", "translation": "They exalt [Him] night and day [and] do not slacken."}, {"ayah": 21, "translit": "Amit takhazooo aalihatam minal ardi hum yunshiroon", "translation": "Or have men taken for themselves gods from the earth who resurrect [the dead]?"}, {"ayah": 22, "translit": "Law kaana feehimaaa aalihatun illal laahu lafasadataa; fa-Subhaanal laahi Rabbil 'Arshi 'ammaa yasifoon", "translation": "Had there been within the heavens and earth gods besides Allah, they both would have been ruined. So exalted is Allah, Lord of the Throne, above what they describe."}, {"ayah": 23, "translit": "Laa yus'alu 'ammaa yaf'alu wa hum yus'aloon", "translation": "He is not questioned about what He does, but they will be questioned."}, {"ayah": 24, "translit": "Amit takhazoo min doonihee aalihatan qul haatoo burhaanakum haaza zikru mam ma'iya wa zikru man qablee; bal aksaruhum laa ya'lamoonal haqqa fahum mu'ridoon", "translation": "Or have they taken gods besides Him? Say, [O Muhammad], \"Produce your proof. This [Qur'an] is the message for those with me and the message of those before me.\" But most of them do not know the truth, so they are turning away."}, {"ayah": 25, "translit": "Wa maaa arsalnaa min qablika mir Rasoolin illaa nooheee ilaihi annahoo laaa ilaaha illaaa Ana fa'budoon", "translation": "And We sent not before you any messenger except that We revealed to him that, \"There is no deity except Me, so worship Me.\""}, {"ayah": 26, "translit": "Wa qaalut takhazar Rahmaanu waladan Subhaanah; bal 'ibaadum mkkramoon", "translation": "And they say, \"The Most Merciful has taken a son.\" Exalted is He! Rather, they are [but] honored servants."}, {"ayah": 27, "translit": "Laa yasbiqoonahoo bil qawli wa hum bi amrihee ya'maloon", "translation": "They cannot precede Him in word, and they act by His command."}, {"ayah": 28, "translit": "Ya'lamu maa baina aideehim wa maa khalfahum wa laa yashfa'oona illaa limanir tadaa wa hum min khash yatihee mushfiqoon", "translation": "He knows what is [presently] before them and what will be after them, and they cannot intercede except on behalf of one whom He approves. And they, from fear of Him, are apprehensive."}, {"ayah": 29, "translit": "Wa mai yaqul minhum inneee ilaahum min doonihee fazaalika najzeehi Jahannam; kazaalika najziz zaalimeen", "translation": "And whoever of them should say, \"Indeed, I am a god besides Him\"- that one We would recompense with Hell. Thus do We recompense the wrongdoers."}, {"ayah": 30, "translit": "Awalam yaral lazeena kafarooo annas samaawaati wal arda kaanataa ratqan faftaqnaahumaa wa ja'alnaa minal maaa'i kulla shai'in haiyin afalaa yu'minoon", "translation": "Have those who disbelieved not considered that the heavens and the earth were a joined entity, and We separated them and made from water every living thing? Then will they not believe?"}, {"ayah": 31, "translit": "Wa ja'alnaa fil ardi rawaasiya an tameeda bihim wa ja'alnaa feehaa fijaajan subulal la'allahum yahtadoon", "translation": "And We placed within the earth firmly set mountains, lest it should shift with them, and We made therein [mountain] passes [as] roads that they might be guided."}, {"ayah": 32, "translit": "Wa ja'alnas samaaa'a saqfam mahfoozanw wa hum 'an Aayaatihaa mu'ridoon", "translation": "And We made the sky a protected ceiling, but they, from its signs, are turning away."}, {"ayah": 33, "translit": "Wa Huwal lazee khalaqal laila wannahaara washshamsa wal qamara kullun fee falakiny yashbahoon", "translation": "And it is He who created the night and the day and the sun and the moon; all [heavenly bodies] in an orbit are swimming."}, {"ayah": 34, "translit": "Wa maa ja'alnaa libasharim min qablikal khuld; afaimmitta fahumul khaalidoon", "translation": "And We did not grant to any man before you eternity [on earth]; so if you die - would they be eternal?"}, {"ayah": 35, "translit": "Kullu nafsin zaaa'iqatul mawt; wa nablookum bishsharri walkhairi fitnatanw wa ilainaa turja'oon", "translation": "Every soul will taste death. And We test you with evil and with good as trial; and to Us you will be returned."}, {"ayah": 36, "translit": "Wa izaa ra aakal lazeena kafarooo iny-yattakhizoonaka illa huzuwaa; ahaazal lazee yazkuru aalihatakum wa hum bi zikrir Rahmaani hum kaafiroon", "translation": "And when those who disbelieve see you, [O Muhammad], they take you not except in ridicule, [saying], \"Is this the one who insults your gods?\" And they are, at the mention of the Most Merciful, disbelievers."}, {"ayah": 37, "translit": "Khuliqal insaanu min 'ajal; sa ureekum Aayaatee falaa tasta'jiloon", "translation": "Man was created of haste. I will show you My signs, so do not impatiently urge Me."}, {"ayah": 38, "translit": "Wa yaqooloona mataa haazal wa'du in kuntum saadiqeen", "translation": "And they say, \"When is this promise, if you should be truthful?\""}, {"ayah": 39, "translit": "Law ya'lamul lazeena kafaroo heena laa yakuffoona 'anw wujoohihimun Naara wa laa 'an zuhoorihim wa laa hum yunsaroon", "translation": "If those who disbelieved but knew the time when they will not avert the Fire from their faces or from their backs and they will not be aided..."}, {"ayah": 40, "translit": "Bal taateehim baghtatan fatabhatuhum falaa yastatee'oona raddahaa wa laa hum yunzaroon", "translation": "Rather, it will come to them unexpectedly and bewilder them, and they will not be able to repel it, nor will they be reprieved."}, {"ayah": 41, "translit": "Wa laqadis tuhzi'a bi-Rusulim min qablika fahaaqa billazeena sakhiroo minhum maa kaanoo bihee yastahzi'oon", "translation": "And already were messengers ridiculed before you, but those who mocked them were enveloped by what they used to ridicule."}, {"ayah": 42, "translit": "Qul mai yakla 'ukum billaili wannahaari minar Rahmaan; bal hum 'an zikri Rabbihim mu'ridoon", "translation": "Say, \"Who can protect you at night or by day from the Most Merciful?\" But they are, from the remembrance of their Lord, turning away."}, {"ayah": 43, "translit": "Am lahum aalihatun tamna'ulum min dooninaa; laa yastatee'oona nasra anfusihim wa laa hum minnna yus-haboon", "translation": "Or do they have gods to defend them other than Us? They are unable [even] to help themselves, nor can they be protected from Us."}, {"ayah": 44, "translit": "Bal matta'naa haaa'ulaaa'i wa aabaaa'ahum hattaa taala 'alaihimul 'umur; afalaa yarawna anna naatil arda nanqusuhaa min atraafihaa; afahumul ghaaliboon", "translation": "But, [on the contrary], We have provided good things for these [disbelievers] and their fathers until life was prolonged for them. Then do they not see that We set upon the land, reducing it from its borders? So it is they who will overcome?"}, {"ayah": 45, "translit": "Qul innamaaa unzirukum bilwahyi; wa laa yasma'us summud du'aaa'a izaa maa yunzaroon", "translation": "Say, \"I only warn you by revelation.\" But the deaf do not hear the call when they are warned."}, {"ayah": 46, "translit": "Wa la'im massat hum nafhatum min 'azaabi Rabbika la yaqoolunna yaawailanaaa innnaa kunnaa zaalimeen", "translation": "And if [as much as] a whiff of the punishment of your Lord should touch them, they would surely say, \"O woe to us! Indeed, we have been wrongdoers.\""}, {"ayah": 47, "translit": "Wa nada'ul mawaazeenal qista li Yawmil Qiyaamati falaa tuzlamu nafsun shai'aa; wa in kaana misqaala habbatim min khardalin atainaa bihaa; wa kafaa binaa haasibeen", "translation": "And We place the scales of justice for the Day of Resurrection, so no soul will be treated unjustly at all. And if there is [even] the weight of a mustard seed, We will bring it forth. And sufficient are We as accountant."}, {"ayah": 48, "translit": "Wa laqad aatainaa Moosa wa haaroonal Furqaana wa diyaa'anw wa zikral lilmuttaqeen", "translation": "And We had already given Moses and Aaron the criterion and a light and a reminder for the righteous"}, {"ayah": 49, "translit": "Allazeena yakhshawna Rabbahum bilghaibi wa hum minas Saa'ati mushfiqoon", "translation": "Who fear their Lord unseen, while they are of the Hour apprehensive."}, {"ayah": 50, "translit": "Wa haazaa Zikrum Mubaarakun anzalnaah; afa antum lahoo munkiroon", "translation": "And this [Qur'an] is a blessed message which We have sent down. Then are you with it unacquainted?"}, {"ayah": 51, "translit": "Wa laqad aatainaaa Ibraaheema rushdahoo min qablu wa kunnaa bihee 'aalimeen", "translation": "And We had certainly given Abraham his sound judgement before, and We were of him well-Knowing"}, {"ayah": 52, "translit": "Iz qaala li abeehi wa qawmihee maa haazihit tamaaseelul lateee antum lahee 'aakifoon", "translation": "When he said to his father and his people, \"What are these statues to which you are devoted?\""}, {"ayah": 53, "translit": "Qaaloo wajadnaaa aabaaa'anaa lahaa 'aabideen", "translation": "They said, \"We found our fathers worshippers of them.\""}, {"ayah": 54, "translit": "Qaala laqad kuntum antum wa aabaaa'ukum fee dalaalim mubeen", "translation": "He said, \"You were certainly, you and your fathers, in manifest error.\""}, {"ayah": 55, "translit": "Qaalooo aji'tanaa bil haqqi am anta minal laa'ibeen", "translation": "They said, \"Have you come to us with truth, or are you of those who jest?\""}, {"ayah": 56, "translit": "Qaala bar Rabbukum Rabbus samaawaati wal ardil lazee fatarahunna wa ana 'alaa zaalikum minash shaahideen", "translation": "He said, \"[No], rather, your Lord is the Lord of the heavens and the earth who created them, and I, to that, am of those who testify."}, {"ayah": 57, "translit": "Wa tallaahi la akeedanna asnaamakum ba'da an tuwalloo mudbireen", "translation": "And [I swear] by Allah, I will surely plan against your idols after you have turned and gone away.\""}, {"ayah": 58, "translit": "Faja'alahum juzaazan illaa kabeeral lahum la'allahum ilaihi yarji'oon", "translation": "So he made them into fragments, except a large one among them, that they might return to it [and question]."}, {"ayah": 59, "translit": "Qaaloo man fa'ala haazaa bi aalihatinaaa innahoo laminaz zaalimeen", "translation": "They said, \"Who has done this to our gods? Indeed, he is of the wrongdoers.\""}, {"ayah": 60, "translit": "Qaaloo sami'naa fatany yazkuruhum yuqaalu lahooo Ibraaheem", "translation": "They said, \"We heard a young man mention them who is called Abraham.\""}, {"ayah": 61, "translit": "Qaaloo faatoo bihee 'alaaa a'yunin naasi la'allahum yash hadoon", "translation": "They said, \"Then bring him before the eyes of the people that they may testify.\""}, {"ayah": 62, "translit": "Qaalooo 'a-anta fa'alta haazaa bi aalihatinaa yaaa Ibraaheem", "translation": "They said, \"Have you done this to our gods, O Abraham?\""}, {"ayah": 63, "translit": "Qaala bal fa'alahoo kabeeruhum haazaa fas'aloohum in kaanoo yantiqoon", "translation": "He said, \"Rather, this - the largest of them - did it, so ask them, if they should [be able to] speak.\""}, {"ayah": 64, "translit": "Faraja'ooo ilaaa anfusihim faqaalooo innakum antumuz zaalimoon", "translation": "So they returned to [blaming] themselves and said [to each other], \"Indeed, you are the wrongdoers.\""}, {"ayah": 65, "translit": "Summa nukisoo 'alaa ru'oosihim laqad 'alimta maa haaa'ulaaa'i yantiqoon", "translation": "Then they reversed themselves, [saying], \"You have already known that these do not speak!\""}, {"ayah": 66, "translit": "Qaala afata'budoona min doonil laahi maa laa yanfa'ukum shai'anw wa laa yadurrukum", "translation": "He said, \"Then do you worship instead of Allah that which does not benefit you at all or harm you?"}, {"ayah": 67, "translit": "Uffil lakum wa limaa ta'budoona min doonil laah; afalaa ta'qiloon", "translation": "Uff to you and to what you worship instead of Allah. Then will you not use reason?\""}, {"ayah": 68, "translit": "Qaaloo harriqooho wansurooo aalihatakum in kuntum faa'ileen", "translation": "They said, \"Burn him and support your gods - if you are to act.\""}, {"ayah": 69, "translit": "Qulnaa yaa naaru koonee bardanw wa salaaman 'alaaa Ibraaheem", "translation": "Allah said, \"O fire, be coolness and safety upon Abraham.\""}, {"ayah": 70, "translit": "Wa araadoo bihee kaidan faja'alnaahumul akhsareen", "translation": "And they intended for him harm, but We made them the greatest losers."}, {"ayah": 71, "translit": "Wa najjainaahu wa Lootan ilal ardil latee baaraknaa feehaa lil 'aalameen", "translation": "And We delivered him and Lot to the land which We had blessed for the worlds."}, {"ayah": 72, "translit": "Wa wahabnaa lahooo Ishaaq; wa Ya'qooba naafilah; wa kullan ja'alnaa saaliheen", "translation": "And We gave him Isaac and Jacob in addition, and all [of them] We made righteous."}, {"ayah": 73, "translit": "Wa ja'alnaahum a'immatany yahdoona bi amrinaa wa awhainaaa ilaihim fi'lal khairaati wa iqaamas Salaati wa eetaaa'az Zakaati wa kaanoo lanaa 'aabideen", "translation": "And We made them leaders guiding by Our command. And We inspired to them the doing of good deeds, establishment of prayer, and giving of zakah; and they were worshippers of Us."}, {"ayah": 74, "translit": "Wa Lootan aatainaahu hukmanw wa 'ilmanw wa najjainaahu minal qaryatil latee kaanat ta'malul khabaaa'is; innahum kaanoo qawma saw'in faasiqeen", "translation": "And to Lot We gave judgement and knowledge, and We saved him from the city that was committing wicked deeds. Indeed, they were a people of evil, defiantly disobedient."}, {"ayah": 75, "translit": "Wa adkhalnaahu fee rahmatinaa innahoo minas saalihee", "translation": "And We admitted him into Our mercy. Indeed, he was of the righteous."}, {"ayah": 76, "translit": "Wa noohan iz naadaa min qablu fastajabnaa lahoo fanajjainaahu wa ahlahoo minal karbil 'azeem", "translation": "And [mention] Noah, when he called [to Allah] before [that time], so We responded to him and saved him and his family from the great flood."}, {"ayah": 77, "translit": "Wa nasarnaahu minal qawmil lazeena kazzaboo bi Aayaatinaa; innahum kkaanoo qawma saw'in fa-aghraq naahum ajma'een", "translation": "And We saved him from the people who denied Our signs. Indeed, they were a people of evil, so We drowned them, all together."}, {"ayah": 78, "translit": "Wa Daawooda wa Sulaimaana iz yahkumaani fil harsi iz nafashat feehi ghanamul qawmi wa kunnaa lihukmihim shaahideen", "translation": "And [mention] David and Solomon, when they judged concerning the field - when the sheep of a people overran it [at night], and We were witness to their judgement."}, {"ayah": 79, "translit": "Fafahhamnaahaa sulaimaan; wa kullan aatainaa hukmanw wa'ilmanw wa sakh kharnaa ma'a Daawoodal jibaala yusabbihna wattayr; wa kunnaa faa'ileen", "translation": "And We gave understanding of the case to Solomon, and to each [of them] We gave judgement and knowledge. And We subjected the mountains to exalt [Us], along with David and [also] the birds. And We were doing [that]."}, {"ayah": 80, "translit": "Wa 'allamanaahu san'ata laboosil lakum lituhsinakum mim baasikum fahal antum shaakiroon", "translation": "And We taught him the fashioning of coats of armor to protect you from your [enemy in] battle. So will you then be grateful?"}, {"ayah": 81, "translit": "Wa li Sulaimaanar reeha 'aasifatan tajree bi amriheee ilal ardil latee baaraknaa feehaa; wa kunnaa bikulli shai'in 'aalimeen", "translation": "And to Solomon [We subjected] the wind, blowing forcefully, proceeding by his command toward the land which We had blessed. And We are ever, of all things, Knowing."}, {"ayah": 82, "translit": "Wa minash Shayaateeni mai yaghoosoona lahoo wa ya'maloona 'amalan doona zaalika wa kunna lahum baafizeen", "translation": "And of the devils were those who dived for him and did work other than that. And We were of them a guardian."}, {"ayah": 83, "translit": "Wa Ayyooba iz naadaa Rabbahooo annee massaniyad durru wa Anta arhamur raahimeen", "translation": "And [mention] Job, when he called to his Lord, \"Indeed, adversity has touched me, and you are the Most Merciful of the merciful.\""}, {"ayah": 84, "translit": "Fastajabnaa lahoo fakashaf naa maa bihee min durrinw wa aatainaahu ahlahoo wa mislahum ma'ahum rahmatam min 'indinaa wa zikraa lil'aabideen", "translation": "So We responded to him and removed what afflicted him of adversity. And We gave him [back] his family and the like thereof with them as mercy from Us and a reminder for the worshippers [of Allah]."}, {"ayah": 85, "translit": "Wa Ismaa'eela wa Idreesa wa Zal Kifli kullum minas saabireen", "translation": "And [mention] Ishmael and Idrees and Dhul-Kifl; all were of the patient."}, {"ayah": 86, "translit": "Wa adkhalnaahum fee rahmatinaa innahum minas saaliheen", "translation": "And We admitted them into Our mercy. Indeed, they were of the righteous."}, {"ayah": 87, "translit": "Wa Zan Nooni iz zahaba mughaadiban fazaanna al lan naqdira 'alaihi fanaanna al lan naqdira 'alaihi fanaadaa fiz zulumaati al laaa ilaaha illaaa Anta Subhaanaka innee kuntu minaz zaalimeen", "translation": "And [mention] the man of the fish, when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, \"There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.\""}, {"ayah": 88, "translit": "Fastajabnaa lahoo wa najjainaahu minal ghamm; wa kazaalika nunjil mu'mineen", "translation": "So We responded to him and saved him from the distress. And thus do We save the believers."}, {"ayah": 89, "translit": "Wa Zakariyyaaa iz naadaa Rabbahoo Rabbi laa tazarnee fardanw wa Anta khairul waariseen", "translation": "And [mention] Zechariah, when he called to his Lord, \"My Lord, do not leave me alone [with no heir], while you are the best of inheritors.\""}, {"ayah": 90, "translit": "Fastajabnaa lahoo wa wahabnaa lahoo Yahyaa Wa aslahnaa lahoo zawjah; innahum kaanoo yusaari'oona fil khairaati wa yad'oonanaa raghabanw wa rahabaa; wa kaanoo lanaa khaashi'een", "translation": "So We responded to him, and We gave to him John, and amended for him his wife. Indeed, they used to hasten to good deeds and supplicate Us in hope and fear, and they were to Us humbly submissive."}, {"ayah": 91, "translit": "Wallateee ahsanat farjahaa fanafakhnaa feehaa mir roohinaa wa ja'alnaahaa wabnahaaa Aayatal lil'aalameen", "translation": "And [mention] the one who guarded her chastity, so We blew into her [garment] through Our angel [Gabriel], and We made her and her son a sign for the worlds."}, {"ayah": 92, "translit": "Inna haaziheee ummatukum ummatanw waahidatanw wa Ana Rabbukum fa'budoon", "translation": "Indeed this, your religion, is one religion, and I am your Lord, so worship Me."}, {"ayah": 93, "translit": "Wa taqatta'ooo amrahum bainahum kullun ilainaaa raaji'oon", "translation": "And [yet] they divided their affair among themselves, [but] all to Us will return."}, {"ayah": 94, "translit": "Famai ya'mal minas saalihaati wa huwa mu'minun falaa kufraana lisa'yihee wa innaa lahoo kaatiboon", "translation": "So whoever does righteous deeds while he is a believer - no denial will there be for his effort, and indeed We, of it, are recorders."}, {"ayah": 95, "translit": "Wa haraamun 'alaa qaryatin ahlaknaahaaa annahum laa yarji'oon", "translation": "And there is prohibition upon [the people of] a city which We have destroyed that they will [ever] return"}, {"ayah": 96, "translit": "Hattaaa izaa futihat Yaajooju wa Maajooju wa hum min kulli hadabiny yansiloon", "translation": "Until when [the dam of] Gog and Magog has been opened and they, from every elevation, descend"}, {"ayah": 97, "translit": "Waqtarabal wa'dul haqqu fa-izaa hiya shaakhisatun absaarul lazeena kafaroo yaawailanaa qad kunna fee ghaflatim min haaza bal kunnaa zaalimeen", "translation": "And [when] the true promise has approached; then suddenly the eyes of those who disbelieved will be staring [in horror, while they say], \"O woe to us; we had been unmindful of this; rather, we were wrongdoers.\""}, {"ayah": 98, "translit": "Innakum wa maa ta'budoona min doonil laahi hasabu Jahannama antum lahaa waaridoon", "translation": "Indeed, you [disbelievers] and what you worship other than Allah are the firewood of Hell. You will be coming to [enter] it."}, {"ayah": 99, "translit": "Law kaana haaa'ulaaa'i aalihatam maa waradoohaa wa kullun feehaa khaalidoon", "translation": "Had these [false deities] been [actual] gods, they would not have come to it, but all are eternal therein."}, {"ayah": 100, "translit": "Lahum feehaa zafeerunw wa hum feehaa laa yasma'oon", "translation": "For them therein is heavy sighing, and they therein will not hear."}, {"ayah": 101, "translit": "Innal lazeena sabaqat lahum minnal husnaaa ulaaa'ika 'anhaa mub'adoon", "translation": "Indeed, those for whom the best [reward] has preceded from Us - they are from it far removed."}, {"ayah": 102, "translit": "Laa yasma'oona hasee sahaa wa hum fee mash tahat anfusuhum khaalidoon", "translation": "They will not hear its sound, while they are, in that which their souls desire, abiding eternally."}, {"ayah": 103, "translit": "Laa yahzunuhumul faza'ul akbaru wa tatalaq qaahumul malaaa'ikatu haazaa Yawmukumul lazee kuntum too'adoon", "translation": "They will not be grieved by the greatest terror, and the angels will meet them, [saying], \"This is your Day which you have been promised\" -"}, {"ayah": 104, "translit": "Yawma natwis samaaa'a kataiyis sijilli lilkutub; kamaa badaanaa awwala khalqin nu'eeduh; wa'dan 'alainaa; innaa kunna faa'ileen", "translation": "The Day when We will fold the heaven like the folding of a [written] sheet for the records. As We began the first creation, We will repeat it. [That is] a promise binding upon Us. Indeed, We will do it."}, {"ayah": 105, "translit": "Wa laqad katabnaa fiz Zaboori mim ba'diz zikri annal arda yarisuhaa 'ibaadi yas saalihoon", "translation": "And We have already written in the book [of Psalms] after the [previous] mention that the land [of Paradise] is inherited by My righteous servants."}, {"ayah": 106, "translit": "Inna fee haaza labalaa ghal liqawmin 'aabideen", "translation": "Indeed, in this [Qur'an] is notification for a worshipping people."}, {"ayah": 107, "translit": "Wa maaa arsalnaaka illaa rahmatal lil'aalameen", "translation": "And We have not sent you, [O Muhammad], except as a mercy to the worlds."}, {"ayah": 108, "translit": "Qul innamaa yoohaa ilaiya annamaaa ilaahukum illaahunw Waahid, fahal antum muslimoon", "translation": "Say, \"It is only revealed to me that your god is but one God; so will you be Muslims [in submission to Him]?\""}, {"ayah": 109, "translit": "Fa in tawallaw faqul aazantukum 'alaa sawaaa'; wa in adreee aqareebun am ba'eedum maa too'adoon", "translation": "But if they turn away, then say, \"I have announced to [all of] you equally. And I know not whether near or far is that which you are promised."}, {"ayah": 110, "translit": "Innahoo ya'lamul jahra minal qawli wa ya'lamu maa taktumoon", "translation": "Indeed, He knows what is declared of speech, and He knows what you conceal."}, {"ayah": 111, "translit": "Wa in adree la'allahoo fitnatul lakum wa mataa'un ilaaheen", "translation": "And I know not; perhaps it is a trial for you and enjoyment for a time.\""}, {"ayah": 112, "translit": "Qaala Rabbih kum bil haqq; wa Rabbunar Rahmaa nul musta'aanu 'alaa maa tasifoon", "translation": "[The Prophet] has said, \"My Lord, judge [between us] in truth. And our Lord is the Most Merciful, the one whose help is sought against that which you describe.\""}]}, {"num": 22, "name": "Al-Hajj", "meaning": "The Pilgrimage", "verses": [{"ayah": 1, "translit": "Yaaa ayyuhan naasuttaqoo Rabbakum; inna zalzalatas Saa'ati shai'un 'azeem", "translation": "O mankind, fear your Lord. Indeed, the convulsion of the [final] Hour is a terrible thing."}, {"ayah": 2, "translit": "Yawma tarawnahaa tazhalu kullu murdi'atin 'ammaaa arda'at wa tada'u kullu zaati hamlin hamlahaa wa tarannaasa sukaaraa wa  maa hum bisukaaraa wa lakinaa 'azaabal laahi shadeed", "translation": "On the Day you see it every nursing mother will be distracted from that [child] she was nursing, and every pregnant woman will abort her pregnancy, and you will see the people [appearing] intoxicated while they are not intoxicated; but the punishment of Allah is severe."}, {"ayah": 3, "translit": "Wa minan naasi mai yujaadilu fil laahi bighairi 'ilminw wa yattabi'u kullaa shaitaanim mareed", "translation": "And of the people is he who disputes about Allah without knowledge and follows every rebellious devil."}, {"ayah": 4, "translit": "Kutiba 'alaihi annahoo man tawallaahu fa annahoo yudil lauhoo wa yahdeehi ilaa 'azaabis sa'eer", "translation": "It has been decreed for every devil that whoever turns to him - he will misguide him and will lead him to the punishment of the Blaze."}, {"ayah": 5, "translit": "Yaaa ayyuhan naasu in kuntum fee raibim minal ba'si fa innaa khalaqnaakum min turaabin summa min nutfatin summaa min 'alaqatin summa mim mud ghatim mukhal laqatinw wa ghairi mukhalla qatil linubaiyina lakum; wa nuqirru fil arhaami maa nashaaa'u ilaaa ajalim musam man summa nukhrijukum tiflan summa litablughooo ashud dakum wa minkum mai yutawaffa wa minkum mai yuraddu ilaaa arzalil 'umuri likailaa ya'lama mim ba'di 'ilmin shai'aa; wa taral arda haamidatan fa izaaa anzalnaa 'alaihal maaa'ah tazzat wa rabat wa ambatat min kulli zawjim baheej", "translation": "O People, if you should be in doubt about the Resurrection, then [consider that] indeed, We created you from dust, then from a sperm-drop, then from a clinging clot, and then from a lump of flesh, formed and unformed - that We may show you. And We settle in the wombs whom We will for a specified term, then We bring you out as a child, and then [We develop you] that you may reach your [time of] maturity. And among you is he who is taken in [early] death, and among you is he who is returned to the most decrepit [old] age so that he knows, after [once having] knowledge, nothing. And you see the earth barren, but when We send down upon it rain, it quivers and swells and grows [something] of every beautiful kind."}, {"ayah": 6, "translit": "Zaalika bi annal laaha Huwal haqqu wa annahoo yuhyil mawtaa wa annahoo 'alaakulli shai'in Qadeer", "translation": "That is because Allah is the Truth and because He gives life to the dead and because He is over all things competent"}, {"ayah": 7, "translit": "Wa annas Saa'ata aatiya tul laa raiba feeha wa annal laaha yab'asuman fil quboor", "translation": "And [that they may know] that the Hour is coming - no doubt about it - and that Allah will resurrect those in the graves."}, {"ayah": 8, "translit": "Wa minan naasi mai yujaadilu fil laahi bighairi 'ilminw wa laa hudanw wa laa Kitaabim Muneer", "translation": "And of the people is he who disputes about Allah without knowledge or guidance or an enlightening book [from Him],"}, {"ayah": 9, "translit": "Saaniya 'itfihee liyudilla 'an sabeelil laahi lahoo fiddun yaa khizyunw wa nuzeequhoo Yawmal Qiyaamati 'azaabal lhareeq", "translation": "Twisting his neck [in arrogance] to mislead [people] from the way of Allah. For him in the world is disgrace, and We will make him taste on the Day of Resurrection the punishment of the Burning Fire [while it is said],"}, {"ayah": 10, "translit": "Zaalika bimaa qaddamat yadaaka wa annal laaha laisa bizallaamil lil'abeed", "translation": "\"That is for what your hands have put forth and because Allah is not ever unjust to [His] servants.\""}, {"ayah": 11, "translit": "Wa minan naasi mai ya'budul laaha 'alaa harfin fa in asaabahoo khairunit maanna bihee wa in asaabat hu fitnatunin qalaba 'alaa wajhihee khasirad dunyaa wal aakhirah; zaalika huwal khusraanul mubeen", "translation": "And of the people is he who worships Allah on an edge. If he is touched by good, he is reassured by it; but if he is struck by trial, he turns on his face [to the other direction]. He has lost [this] world and the Hereafter. That is what is the manifest loss."}, {"ayah": 12, "translit": "Yad'oo min doonil laahi maa laa yadurruhoo wa maa laa yanfa'uh' zaalika huwad dalaalul ba'ed", "translation": "He invokes instead of Allah that which neither harms him nor benefits him. That is what is the extreme error."}, {"ayah": 13, "translit": "Yad'oo laman darruhooo aqrabu min naf'ih; labi'salmawlaa wa labi'sal 'asheer", "translation": "He invokes one whose harm is closer than his benefit - how wretched the protector and how wretched the associate."}, {"ayah": 14, "translit": "Innal laaha yudkhilul laeena aamanoo wa 'amilus saalihaati jannaatin tajree min tahtihal anhaar; innal laaha yaf'alu maa yureed", "translation": "Indeed, Allah will admit those who believe and do righteous deeds to gardens beneath which rivers flow. Indeed, Allah does what He intends."}, {"ayah": 15, "translit": "Man kaana yazunnu allai yansurahul laahu fid dunyaa wal aakhirati fal yamdud bisababin ilas samaaa'i summal yaqta' falyanzur hal yuzhibanna kaiduhoo maa yagheez", "translation": "Whoever should think that Allah will not support [Prophet Muhammad] in this world and the Hereafter - let him extend a rope to the ceiling, then cut off [his breath], and let him see: will his effort remove that which enrages [him]?"}, {"ayah": 16, "translit": "Wa kazaalika anzalnaahu aayaatim baiyinaatinw wa annal laaha yahdee mai yureed", "translation": "And thus have We sent the Qur'an down as verses of clear evidence and because Allah guides whom He intends."}, {"ayah": 17, "translit": "Innal lazeena aamanoo wallazeena haadoo was saabi'eena wan nasaaraa wal Majoosa wallazeena ashrakooo innal laaha yafsilu bainahum yawmal qiyaamah; innal laaha 'alaa kulli shai'in shaheed", "translation": "Indeed, those who have believed and those who were Jews and the Sabeans and the Christians and the Magians and those who associated with Allah - Allah will judge between them on the Day of Resurrection. Indeed Allah is, over all things, Witness."}, {"ayah": 18, "translit": "Alam tara annal laaha yasjudu lahoo man fis samaawaati wa man fil ardi wash shamsu walqamaru wan nu joomu wal jibaalu wash shajaru wad dawaaabbu wa kaseerum minan naasi wa kaseerun haqqa 'alaihil 'azaab; wa mai yuhinil laahu famaa lahoo mim mukrim; innallaaha yaf'alu maa yashaaa", "translation": "Do you not see that to Allah prostrates whoever is in the heavens and whoever is on the earth and the sun, the moon, the stars, the mountains, the trees, the moving creatures and many of the people? But upon many the punishment has been justified. And he whom Allah humiliates - for him there is no bestower of honor. Indeed, Allah does what He wills."}, {"ayah": 19, "translit": "Haazaani khasmaanikh tasamoo fee Rabbihim fal lazeena kafaroo qutti'at lahum siyaabum min naar; yusabbu min fawqi ru'oosihimul hameem", "translation": "These are two adversaries who have disputed over their Lord. But those who disbelieved will have cut out for them garments of fire. Poured upon their heads will be scalding water"}, {"ayah": 20, "translit": "Yusharu bihee maa fee butoonihim waljulood", "translation": "By which is melted that within their bellies and [their] skins."}, {"ayah": 21, "translit": "Wa lahum maqaami'u min hadeed", "translation": "And for [striking] them are maces of iron."}, {"ayah": 22, "translit": "Kullamaa araadooo any yakhrujoo minhaa min ghammin u'eedoo feeha wa zooqoo 'azaabal hareeq (section 2)", "translation": "Every time they want to get out of Hellfire from anguish, they will be returned to it, and [it will be said], \"Taste the punishment of the Burning Fire!\""}, {"ayah": 23, "translit": "Innal laaha yudkhilul lazeena aamanoo wa 'amilus saalihaati jannaatin tajree min tahtihal anhaaru yuhallawna feehaa min asaawira min zahabinw wa lu'lu'aa; wa libaasuhum feehaa hareer", "translation": "Indeed, Allah will admit those who believe and do righteous deeds to gardens beneath which rivers flow. They will be adorned therein with bracelets of gold and pearl, and their garments therein will be silk."}, {"ayah": 24, "translit": "Wa hudooo ilat taiyibi minal qawli wa hudooo ilaaa siraatil hameed", "translation": "And they had been guided [in worldly life] to good speech, and they were guided to the path of the Praiseworthy."}, {"ayah": 25, "translit": "Innal lazeena kafaroo wa yasuddoona 'an sabeelil laahi wal Masjidil Haraamil lazee ja'alnaahu linnaasi sawaaa'anil 'aakifu feehi walbaad; wa mai yurid feehi bi ilhaadim bizulmin nuziqhu min 'azaabin aleem", "translation": "Indeed, those who have disbelieved and avert [people] from the way of Allah and [from] al-Masjid al-Haram, which We made for the people - equal are the resident therein and one from outside; and [also] whoever intends [a deed] therein of deviation [in religion] or wrongdoing - We will make him taste of a painful punishment."}, {"ayah": 26, "translit": "Wa iz bawwaanaa li Ibraaheema makaanal Baiti allaa tushrik bee shai'anw wa tahhir Baitiya litaaa'ifeena walqaaa' imeena warrukka 'is sujood", "translation": "And [mention, O Muhammad], when We designated for Abraham the site of the House, [saying], \"Do not associate anything with Me and purify My House for those who perform Tawaf and those who stand [in prayer] and those who bow and prostrate."}, {"ayah": 27, "translit": "Wa azzin fin naasi bil Hajji yaatooka rijaalanw wa 'alaa kulli daamiriny yaateena min kulli fajjin 'ameeq", "translation": "And proclaim to the people the Hajj [pilgrimage]; they will come to you on foot and on every lean camel; they will come from every distant pass -"}, {"ayah": 28, "translit": "Li yashhadoo manaafi'a lahum wa yazkurus mal laahi feee ayyaamimma'loomaatin 'alaa maa razaqahum mim baheematil an'aami fakuloo minhaa wa at'imul baaa'isal faqeer", "translation": "That they may witness benefits for themselves and mention the name of Allah on known days over what He has provided for them of [sacrificial] animals. So eat of them and feed the miserable and poor."}, {"ayah": 29, "translit": "Summal yaqdoo tafasahum wal yoofoo nuzoorahum wal yattawwafoo bil Baitil 'Ateeq", "translation": "Then let them end their untidiness and fulfill their vows and perform Tawaf around the ancient House.\""}, {"ayah": 30, "translit": "Zaalika wa mai yu'azzim hurumaatil laahi fahuwa khairul lahoo 'inda Rabbih; wa uhillat lakumul an'aamu illaa maa yutlaa 'alaikum fajtanibur rijsa minal awsaani wajtaniboo qawlaz zoor", "translation": "That [has been commanded], and whoever honors the sacred ordinances of Allah - it is best for him in the sight of his Lord. And permitted to you are the grazing livestock, except what is recited to you. So avoid the uncleanliness of idols and avoid false statement,"}, {"ayah": 31, "translit": "Hunafaaa'a lillaahi ghaira mushrikeena bih; wa mai yushrik billaahi faka annamaa kharra minas samaaa'i fatakh tafuhut tairu aw tahwee bihir reehu bee makaanin saheeq", "translation": "Inclining [only] to Allah, not associating [anything] with Him. And he who associates with Allah - it is as though he had fallen from the sky and was snatched by the birds or the wind carried him down into a remote place."}, {"ayah": 32, "translit": "Zaalika wa mai yu'azzim sha'aaa'iral laahi fa innahaa min taqwal quloob", "translation": "That [is so]. And whoever honors the symbols of Allah - indeed, it is from the piety of hearts."}, {"ayah": 33, "translit": "Lakum feehaa manaafi'u ilaaa ajalim musamman summa mahilluhaaa ilal Baitil 'Ateeq", "translation": "For you the animals marked for sacrifice are benefits for a specified term; then their place of sacrifice is at the ancient House."}, {"ayah": 34, "translit": "Wa likulli ummatin ja'alnaa mansakal liyazkurus mal laahi 'alaa maa razaqahum mim baheematil an'aam; failaahukum ilaahunw Waahidun falahooo aslimoo; wa bashshiril mukhbiteen", "translation": "And for all religion We have appointed a rite [of sacrifice] that they may mention the name of Allah over what He has provided for them of [sacrificial] animals. For your god is one God, so to Him submit. And, [O Muhammad], give good tidings to the humble [before their Lord]"}, {"ayah": 35, "translit": "Allazeena izaa zukiral laahu wajilat quloobuhum wassaabireena 'alaa maaa asaabahum walmuqeemis Salaati wa mimmaa razaqnaahum yunfiqoon", "translation": "Who, when Allah is mentioned, their hearts are fearful, and [to] the patient over what has afflicted them, and the establishers of prayer and those who spend from what We have provided them."}, {"ayah": 36, "translit": "Walbudna ja'alnaahaa lakum min sha'aaa'iril laahi lakum feehaa khairun fazkurusmal laahi 'alaihaa sawaaff; fa izaa wajabat junoobuhaa fakuloo minhaa wa at'imul qaani'a walmu'tarr; kazaalika sakhkharnaahaa lakum la'allakum tashkuroon", "translation": "And the camels and cattle We have appointed for you as among the symbols of Allah; for you therein is good. So mention the name of Allah upon them when lined up [for sacrifice]; and when they are [lifeless] on their sides, then eat from them and feed the needy and the beggar. Thus have We subjected them to you that you may be grateful."}, {"ayah": 37, "translit": "Lany yanaalal laaha luhoo muhaa wa laa dimaaa'uhaa wa laakiny yanaaluhut taqwaa minkum; kazaalika sakhkharhaa lakum litukabbirul laaha 'alaa ma hadaakum; wa bashshirul muhsineen", "translation": "Their meat will not reach Allah, nor will their blood, but what reaches Him is piety from you. Thus have We subjected them to you that you may glorify Allah for that [to] which He has guided you; and give good tidings to the doers of good."}, {"ayah": 38, "translit": "Innal laaha yudaafi' 'anil lazeena aamanoo; innal laaha laa yuhibbu kulla khawwaanin kafoor", "translation": "Indeed, Allah defends those who have believed. Indeed, Allah does not like everyone treacherous and ungrateful."}, {"ayah": 39, "translit": "Uzina lillazeena yuqaataloona bi annahum zulimoo; wa innal laaha 'alaa nasrihim la Qaderr", "translation": "Permission [to fight] has been given to those who are being fought, because they were wronged. And indeed, Allah is competent to give them victory."}, {"ayah": 40, "translit": "Allazeena ukhrijoo min diyaarihim bighairi haqqin illaaa any yaqooloo rabbunallaah; wa law laa daf'ul laahin naasa ba'dahum biba'dil lahuddimat sawaami'u wa biya'unw wa salawaatunw wa masaajidu yuzkaru feehasmul laahi kaseeraa; wa layansurannal laahu mai yansuruh; innal laaha la qawiyyun 'Azeez", "translation": "[They are] those who have been evicted from their homes without right - only because they say, \"Our Lord is Allah.\" And were it not that Allah checks the people, some by means of others, there would have been demolished monasteries, churches, synagogues, and mosques in which the name of Allah is much mentioned. And Allah will surely support those who support Him. Indeed, Allah is Powerful and Exalted in Might."}, {"ayah": 41, "translit": "Allazeena im makkan naahum fil ardi aqaamus Salaata wa aatawuz Zakaata wa amaroo bilma'roofi wa nahaw 'anil munkar; wa lillaahi 'aaqibatul umoor", "translation": "[And they are] those who, if We give them authority in the land, establish prayer and give zakah and enjoin what is right and forbid what is wrong. And to Allah belongs the outcome of [all] matters."}, {"ayah": 42, "translit": "Wa iny yukazzibooka faqad kazzabat qablahum qawmu Nooinw wa Aadunw wa Samood", "translation": "And if they deny you, [O Muhammad] - so, before them, did the people of Noah and 'Aad and Thamud deny [their prophets],"}, {"ayah": 43, "translit": "Wa qawmu Ibraaheema wa qawmu Loot", "translation": "And the people of Abraham and the people of Lot"}, {"ayah": 44, "translit": "Wa as haabu Madyana wa kuzziba Moosaa fa amlaitu lilkaafireena summa akhaztuhum fakaifa kaana nakeer", "translation": "And the inhabitants of Madyan. And Moses was denied, so I prolonged enjoyment for the disbelievers; then I seized them, and how [terrible] was My reproach."}, {"ayah": 45, "translit": "Faka ayyim min qaryatin ahlaknaahaa wa hiya zaalimatun fahiya khaawiyatun 'alaa 'urooshihaa wa bi'rim mu'at talatinw wa qasrim masheed", "translation": "And how many a city did We destroy while it was committing wrong - so it is [now] fallen into ruin - and [how many] an abandoned well and [how many] a lofty palace."}, {"ayah": 46, "translit": "Afalam yaseeroo fil ardi fatakoona lahum quloobuny ya'qiloona bihaaa aw aazaanuny yasm'oona bihaa fa innahaa laa ta'mal absaaru wa laakin ta'mal quloobul latee fissudoor", "translation": "So have they not traveled through the earth and have hearts by which to reason and ears by which to hear? For indeed, it is not eyes that are blinded, but blinded are the hearts which are within the breasts."}, {"ayah": 47, "translit": "Wa yasta'juloonaka bil'azaabi wa lany yukhlifal laahu wa'dah; wa inna yawman 'inda Rabbika ka'alfi sanatim mimmaa ta'uddoon", "translation": "And they urge you to hasten the punishment. But Allah will never fail in His promise. And indeed, a day with your Lord is like a thousand years of those which you count."}, {"ayah": 48, "translit": "Wa ka ayyim min qaryatin amlaitu lahaa wa hiya zaalimatun summa akhaztuhaa wa ilaiyal maseer", "translation": "And for how many a city did I prolong enjoyment while it was committing wrong. Then I seized it, and to Me is the [final] destination."}, {"ayah": 49, "translit": "Qul yaaa ayyuhan naasu innamaaa ana lakum nazeerum mubeen", "translation": "Say, \"O people, I am only to you a clear warner.\""}, {"ayah": 50, "translit": "Fallazeena aamanoo wa 'amilu saalihaati lahum maghfiratunw wa rizqun kareem", "translation": "And those who have believed and done righteous deeds - for them is forgiveness and noble provision."}, {"ayah": 51, "translit": "Wallazeena sa'aw feee Aayaatinaa mu'aajizeena ulaaa ika As-haabul jaheem", "translation": "But the ones who strove against Our verses, [seeking] to cause failure - those are the companions of Hellfire."}, {"ayah": 52, "translit": "Wa maaa arsalnaa min qablika mir Rasoolinnw wa laa Nabiyyin illaaa izaaa tamannaaa alqash Shaitaanu feee umniy yatihee fa yansakhul laahu maa yulqish Shaitaanu summa yuhkimul laahu aayaatih; wallaahu 'Aleemun Hakeem", "translation": "And We did not send before you any messenger or prophet except that when he spoke [or recited], Satan threw into it [some misunderstanding]. But Allah abolishes that which Satan throws in; then Allah makes precise His verses. And Allah is Knowing and Wise."}, {"ayah": 53, "translit": "Liyaj'ala maa yulqish Shaitaanu fitnatal lillazeena fee quloobihim maradunw walqaasiyati quloobuhum; wa innaz zaalimeena lafee shiqaaqim ba'eed", "translation": "[That is] so He may make what Satan throws in a trial for those within whose hearts is disease and those hard of heart. And indeed, the wrongdoers are in extreme dissension."}, {"ayah": 54, "translit": "Wa liya'lamal lazeena ootul 'ilma annahul haqqu mir Rabbika fa yu'minoo bihee fatukhbita ahoo quloobuhum; wa innal laaha lahaadil lazeena aamanoo ilaa Siraatim Mustaqeem", "translation": "And so those who were given knowledge may know that it is the truth from your Lord and [therefore] believe in it, and their hearts humbly submit to it. And indeed is Allah the Guide of those who have believed to a straight path."}, {"ayah": 55, "translit": "Wa laa yazaalul lazeena kafaroo fee miryatim minhu hattaa taatiyahumus Saa'atu baghtatan aw yaatiyahum 'azaabu Yawmin 'aqeem", "translation": "But those who disbelieve will not cease to be in doubt of it until the Hour comes upon them unexpectedly or there comes to them the punishment of a barren Day."}, {"ayah": 56, "translit": "Almulku Yawma'izil lillaahi yahkumu bainahum; fallazeena aamanoo wa 'amilus saalihaati fee jannaatin Na'eem", "translation": "[All] sovereignty that Day is for Allah; He will judge between them. So they who believed and did righteous deeds will be in the Gardens of Pleasure."}, {"ayah": 57, "translit": "Wallazeena kafaroo wa kazzaboo bi Aayaatinaa fa ulaaa'ika lahum 'azaabum muheen", "translation": "And they who disbelieved and denied Our signs - for those there will be a humiliating punishment."}, {"ayah": 58, "translit": "Wallazeena haajaroo fee sabeelil laahi summa qutilooo law maatoo la yarzuqan nahumul laahu rizqan hasanaa; wa innal laaha la Huwa khairur raaziqeen", "translation": "And those who emigrated for the cause of Allah and then were killed or died - Allah will surely provide for them a good provision. And indeed, it is Allah who is the best of providers."}, {"ayah": 59, "translit": "La yudkhilan nahum mud khalany yardawnah; wa innal laaha la 'Aleemun Haleem", "translation": "He will surely cause them to enter an entrance with which they will be pleased, and indeed, Allah is Knowing and Forbearing."}, {"ayah": 60, "translit": "Zaalika wa man 'aaqaba bimisli maa 'ooqiba bihee summa bughiya 'alaihi la yansurannahul laah; innal laaha la 'Afuwwun Ghafoor", "translation": "That [is so]. And whoever responds [to injustice] with the equivalent of that with which he was harmed and then is tyrannized - Allah will surely aid him. Indeed, Allah is Pardoning and Forgiving."}, {"ayah": 61, "translit": "Zaalika bi annal laaha yoolijul laila fin nahaari wa yoolijun nahaara fil laili wa annal laaha Samee'um Baseer", "translation": "That is because Allah causes the night to enter the day and causes the day to enter the night and because Allah is Hearing and Seeing."}, {"ayah": 62, "translit": "Zaalika bi annal laaha Huwal haqqu wa anna maa yad'oona min doonihee huwal baatilu wa annal laaha Huwal 'Aliyyul kabeer", "translation": "That is because Allah is the Truth, and that which they call upon other than Him is falsehood, and because Allah is the Most High, the Grand."}, {"ayah": 63, "translit": "Alam tara annal laaha anzala minas samaaa'i maaa'an fatusbihul ardu mukhdarrah; innal laaha Lateefun Khabeer", "translation": "Do you not see that Allah has sent down rain from the sky and the earth becomes green? Indeed, Allah is Subtle and Acquainted."}, {"ayah": 64, "translit": "Lahoo ma fis samaawaati wa ma fil ard; wa innal laaha la Huwal Ghaniyyul Hameed", "translation": "To Him belongs what is in the heavens and what is on the earth. And indeed, Allah is the Free of need, the Praiseworthy."}, {"ayah": 65, "translit": "Alam tara annal laaha sakhkhara lakum maa fil ardi wal fulka tajree fil bahri bi amrihee wa yumsikus samaaa'a an taqa'a 'alal ardi illaa biiznih; innal laaha binnaasi la Ra'oofur Raheem", "translation": "Do you not see that Allah has subjected to you whatever is on the earth and the ships which run through the sea by His command? And He restrains the sky from falling upon the earth, unless by His permission. Indeed Allah, to the people, is Kind and Merciful."}, {"ayah": 66, "translit": "Wa Huwal lazee ahyaakum summa yumeetukum summma yuheekum; innal insaana lakafoor", "translation": "And He is the one who gave you life; then He causes you to die and then will [again] give you life. Indeed, mankind is ungrateful."}, {"ayah": 67, "translit": "Likulli ummatin ja'alnaa mansakan hum naasikoohu falaa yunaazi 'unnaka fil amr; wad'u ilaa Rabbika innaka la 'alaa hudam mustaqeem", "translation": "For every religion We have appointed rites which they perform. So, [O Muhammad], let the disbelievers not contend with you over the matter but invite them to your Lord. Indeed, you are upon straight guidance."}, {"ayah": 68, "translit": "Wa in jaadalooka faqulil laahu a'lamu bimaa ta'maloon", "translation": "And if they dispute with you, then say, \"Allah is most knowing of what you do."}, {"ayah": 69, "translit": "Allaahu yahkumu bainakum Yawmal Qiyaamati feemaa kuntum feehi takhtalifoon", "translation": "Allah will judge between you on the Day of Resurrection concerning that over which you used to differ.\""}, {"ayah": 70, "translit": "Alam ta'lam annal laaha ya'lamu maa fis samaaa'i wal ard; inna zaalika fee kitaab; inna zaalika 'alal laahi yaseer", "translation": "Do you not know that Allah knows what is in the heaven and earth? Indeed, that is in a Record. Indeed that, for Allah, is easy."}, {"ayah": 71, "translit": "Wa ya'budoona min doonil laahi maa lam yunazzil bihee sultaananw wa maa laisa lahum bihee 'ilm; wa maa lizzaalimeena min naseer", "translation": "And they worship besides Allah that for which He has not sent down authority and that of which they have no knowledge. And there will not be for the wrongdoers any helper."}, {"ayah": 72, "translit": "Wa izaa tutlaa 'laihim Aayaatunaa baiyinaatin ta'rifu fee wujoohil lazeena kafarul munkara yakaadoona yastoona bil lazeena yatloona 'alaihim Aayaatinaa; qul afa unab bi'ukum bisharrim min zaalikum; an Naaru wa 'adahal laahul lazeena kafaroo wa bi'sal maseer", "translation": "And when Our verses are recited to them as clear evidences, you recognize in the faces of those who disbelieve disapproval. They are almost on the verge of assaulting those who recite to them Our verses. Say, \"Then shall I inform you of [what is] worse than that? [It is] the Fire which Allah has promised those who disbelieve, and wretched is the destination.\""}, {"ayah": 73, "translit": "Yaaa ayyuhan naasu duriba masalun fastami'oo lah; innal lazeena tad'oona min doonil laahi lai yakhluqoo zubaabanw wa lawijtama'oo lahoo wa iny yaslub humuz zubbabu shai'al laa yastan qizoohu minh; da'ufat taalibu walmatloob", "translation": "O people, an example is presented, so listen to it. Indeed, those you invoke besides Allah will never create [as much as] a fly, even if they gathered together for that purpose. And if the fly should steal away from them a [tiny] thing, they could not recover it from him. Weak are the pursuer and pursued."}, {"ayah": 74, "translit": "Maa qadrul laaha haqqa qadrih; innal laaha la Qawiyyun 'Azeez", "translation": "They have not appraised Allah with true appraisal. Indeed, Allah is Powerful and Exalted in Might."}, {"ayah": 75, "translit": "Allahu yastafee minal malaaa'ikati Rusulanw wa minan naas; innal laaha Samee'um Baseer", "translation": "Allah chooses from the angels messengers and from the people. Indeed, Allah is Hearing and Seeing."}, {"ayah": 76, "translit": "Ya'lamu maa baina aydeehim wa maa khalfahum; wa ilal laahi turja'ul umoor", "translation": "He knows what is [presently] before them and what will be after them. And to Allah will be returned [all] matters."}, {"ayah": 77, "translit": "Yaaa ayyuhal lazeena aamanur ka'oo wasjudoo wa'budoo Rabbakum waf'alul khaira la'allakum tuflihoon", "translation": "O you who have believed, bow and prostrate and worship your Lord and do good - that you may succeed."}, {"ayah": 78, "translit": "Wa jaahidoo fil laahi haqqa jihaadih; Huwaj tabaakum wa maa ja'ala 'alaikum fid deeni min haraj; Millata abeekum Ibraaheem; Huwa sammaakumul muslimeena min qablu wa fee haaza li yakoonar Rasoolu shaheedan 'alaikum wa takoonoo shuhadaaa'a 'alan naas; fa aqeemus salaata wa aatuz zakaata wa'tasimoo billaahi Huwa mawlaakum fani'mal mawlaa wa ni'man naseer", "translation": "And strive for Allah with the striving due to Him. He has chosen you and has not placed upon you in the religion any difficulty. [It is] the religion of your father, Abraham. Allah named you \"Muslims\" before [in former scriptures] and in this [revelation] that the Messenger may be a witness over you and you may be witnesses over the people. So establish prayer and give zakah and hold fast to Allah. He is your protector; and excellent is the protector, and excellent is the helper."}]}, {"num": 23, "name": "Al-Mu'minun", "meaning": "The Believers", "verses": [{"ayah": 1, "translit": "Qad aflahal mu'minoon", "translation": "Certainly will the believers have succeeded:"}, {"ayah": 2, "translit": "Allazeena hum fee Salaatihim khaashi'oon", "translation": "They who are during their prayer humbly submissive"}, {"ayah": 3, "translit": "Wallazeena hum 'anillaghwimu'ridoon", "translation": "And they who turn away from ill speech"}, {"ayah": 4, "translit": "Wallazeena hum liz Zakaati faa'iloon", "translation": "And they who are observant of zakah"}, {"ayah": 5, "translit": "Wallazeena hum lifuroo jihim haafizoon", "translation": "And they who guard their private parts"}, {"ayah": 6, "translit": "Illaa 'alaaa azwaajihim aw maa malakat aimaanuhum fa innahum ghairu maloomeen", "translation": "Except from their wives or those their right hands possess, for indeed, they will not be blamed -"}, {"ayah": 7, "translit": "Famanib taghaa waraaa'a zaalika fa ulaaa'ika humul 'aadoon", "translation": "But whoever seeks beyond that, then those are the transgressors -"}, {"ayah": 8, "translit": "Wallazeena hum li amaanaatihim wa 'ahdihim raa'oon", "translation": "And they who are to their trusts and their promises attentive"}, {"ayah": 9, "translit": "Wallazeena hum 'alaa Salawaatihim yuhaafizoon", "translation": "And they who carefully maintain their prayers -"}, {"ayah": 10, "translit": "Ulaaa'ika humul waarisoon", "translation": "Those are the inheritors"}, {"ayah": 11, "translit": "Allazeena yarisoonal Firdawsa hum feehaa khaalidoon", "translation": "Who will inherit al-Firdaus. They will abide therein eternally."}, {"ayah": 12, "translit": "Wa laqad khalaqnal insaana min sulaalatim minteen", "translation": "And certainly did We create man from an extract of clay."}, {"ayah": 13, "translit": "Summa ja'alnaahu nutfatan fee qaraarim makeen", "translation": "Then We placed him as a sperm-drop in a firm lodging."}, {"ayah": 14, "translit": "Summa khalaqnan nutfata 'alaqatan fakhalaqnal 'alaqata mudghatan fakhalaq nal mudghata 'izaaman fakasawnal 'izaama lahman summa anshaanaahu khalqan aakhar; fatabaarakal laahu ahsanul khaaliqeen", "translation": "Then We made the sperm-drop into a clinging clot, and We made the clot into a lump [of flesh], and We made [from] the lump, bones, and We covered the bones with flesh; then We developed him into another creation. So blessed is Allah, the best of creators."}, {"ayah": 15, "translit": "Summa innakum ba'da zaalika la maaiyitoon", "translation": "Then indeed, after that you are to die."}, {"ayah": 16, "translit": "Summa innakum Yawmal Qiyaamati tub'asoon", "translation": "Then indeed you, on the Day of Resurrection, will be resurrected."}, {"ayah": 17, "translit": "Wa laqad khalaqnaa fawqakum sab'a taraaa'iqa wa maa kunnaa 'anil khalqi ghaafileen", "translation": "And We have created above you seven layered heavens, and never have We been of [Our] creation unaware."}, {"ayah": 18, "translit": "Wa anzalnaa minas samaaa'i maaa'am biqadarin fa-askannaahu fil ardi wa innaa 'alaa zahaabim bihee laqaa diroon", "translation": "And We have sent down rain from the sky in a measured amount and settled it in the earth. And indeed, We are Able to take it away."}, {"ayah": 19, "translit": "Fa anshaanaa lakum bihee Jannaatim min nakheelinw wa a'naab; lakum feehaa fawaakihu kaseeratunw wa minhaa taakuloon", "translation": "And We brought forth for you thereby gardens of palm trees and grapevines in which for you are abundant fruits and from which you eat."}, {"ayah": 20, "translit": "Wa shajaratan takhruju min Toori Sainaaa'a tambutu bidduhni wa sibghil lil aakileen", "translation": "And [We brought forth] a tree issuing from Mount Sinai which produces oil and food for those who eat."}, {"ayah": 21, "translit": "Wa inna lakum fil an'aami la'ibrah; nusqeekum mimmaa fee butoonihaa wa lakum feehaa manaafi'u kaseeratunw wa minhaa taakuloon", "translation": "And indeed, for you in livestock is a lesson. We give you drink from that which is in their bellies, and for you in them are numerous benefits, and from them you eat."}, {"ayah": 22, "translit": "Wa 'alaihaa wa'alal fulki tuhmaloon", "translation": "And upon them and on ships you are carried."}, {"ayah": 23, "translit": "Wa laqad arsalnaa Noohan ilaa qawmihee faqaala yaa qawmi'budul laaha maa lakum min ilahin ghairuhoo afalaa tattaqoon", "translation": "And We had certainly sent Noah to his people, and he said, \"O my people, worship Allah; you have no deity other than Him; then will you not fear Him?\""}, {"ayah": 24, "translit": "Faqaalal mala'ul lazeena kafaroo min qawmihee maa haazaaa illaa basharum mislukum yureedu ai yatafaddala 'alaikum wa law shaaa'al laahu la anzala malaaa'ikatam maa sami'naa bihaazaa feee aabaaa'inal  awwaleen", "translation": "But the eminent among those who disbelieved from his people said, \"This is not but a man like yourselves who wishes to take precedence over you; and if Allah had willed [to send a messenger], He would have sent down angels. We have not heard of this among our forefathers."}, {"ayah": 25, "translit": "In huwa illaa rajulum bihee jinnatun fatarabbasoo bihee hattan heen", "translation": "He is not but a man possessed with madness, so wait concerning him for a time.\""}, {"ayah": 26, "translit": "Qaala Rabbin surnee bimaa kazzaboon", "translation": "[Noah] said, \"My Lord, support me because they have denied me.\""}, {"ayah": 27, "translit": "Fa awhainaaa ilaihi anis na'il fulka bi a'yuninaa wa wahyinaa fa izaa jaaa'a amrunaa wa faarat tannooru fasluk feehaa min kullin zawjainis naini wa ahlaka illaa man sabaqa 'alaihil qawlu minhum wa laa tukhaat ibnee fil lazeena zalamooo innaahum mughraqoon", "translation": "So We inspired to him, \"Construct the ship under Our observation, and Our inspiration, and when Our command comes and the oven overflows, put into the ship from each [creature] two mates and your family, except those for whom the decree [of destruction] has proceeded. And do not address Me concerning those who have wronged; indeed, they are to be drowned."}, {"ayah": 28, "translit": "Fa izas tawaita ata wa mam ma'aka 'alal fulki faqulil hamdu lillaahil lazee najjaanaa minal qawmiz zalimeen", "translation": "And when you have boarded the ship, you and those with you, then say, 'Praise to Allah who has saved us from the wrongdoing people.'"}, {"ayah": 29, "translit": "Wa qur Rabbi anzilnee munzalam mubaarakanw wa Anta khairul munzileen", "translation": "And say, 'My Lord, let me land at a blessed landing place, and You are the best to accommodate [us].' \""}, {"ayah": 30, "translit": "Inna fee zaalika la Aayaatinw wa in kunnaa lamubtaleen", "translation": "Indeed in that are signs, and indeed, We are ever testing [Our servants]."}, {"ayah": 31, "translit": "Summaa anshaana mim ba'dihim qarnan aakhareen", "translation": "Then We produced after them a generation of others."}, {"ayah": 32, "translit": "Fa arsalnaa feehim Rasoolam minhum ani'budul laaha maa lakum min ilaahin ghairuhoo afalaa tattaqoon", "translation": "And We sent among them a messenger from themselves, [saying], \"Worship Allah; you have no deity other than Him; then will you not fear Him?\""}, {"ayah": 33, "translit": "Wa qaalal mala-u min qawmihil lazeena kafaroo wa kazzaboo bi liqaaa'il Aakhirati wa atrafnaahum fil hayaatid dunyaa maa haazaaa illaa basharum mislukum yaakulu mimmaa taakuloona minhu wa yashrabu mimmaa tashraboon", "translation": "And the eminent among his people who disbelieved and denied the meeting of the Hereafter while We had given them luxury in the worldly life said, \"This is not but a man like yourselves. He eats of that from which you eat and drinks of what you drink."}, {"ayah": 34, "translit": "Wa la'in at'atum basharam mislakum innakum izal lakhaasiroon", "translation": "And if you should obey a man like yourselves, indeed, you would then be losers."}, {"ayah": 35, "translit": "A-Ya'idukum annakum izaa mittum wa kuntum turaabanw wa izaaman annakum mukhrajoon", "translation": "Does he promise you that when you have died and become dust and bones that you will be brought forth [once more]?"}, {"ayah": 36, "translit": "Haihaata haihaata limaa too'adoon", "translation": "How far, how far, is that which you are promised."}, {"ayah": 37, "translit": "In hiya illaa hayaatunad dunyaa namootu wa nahyaa wa maa nahnu bimab'ooseen", "translation": "Life is not but our worldly life - we die and live, but we will not be resurrected."}, {"ayah": 38, "translit": "In huwa illaa rajulunif taraa 'alal laahi kazibanw wa maa nahnuu lahoo bimu'mineen", "translation": "He is not but a man who has invented a lie about Allah, and we will not believe him.\""}, {"ayah": 39, "translit": "Qaala Rabbin surnee bimaa kazzaboon", "translation": "He said, \"My Lord, support me because they have denied me.\""}, {"ayah": 40, "translit": "Qaala 'ammaa qaleelil la yusbihunna naadimeen", "translation": "[Allah] said, \"After a little, they will surely become regretful.\""}, {"ayah": 41, "translit": "Fa akhazat humus saihatu bilhaqqi faja'alnaahum ghusaaa'aa; fabu;dal lilqaw miz zaalimeen", "translation": "So the shriek seized them in truth, and We made them as [plant] stubble. Then away with the wrongdoing people."}, {"ayah": 42, "translit": "Summa anshaanaa mim ba'dihim quroonan aakhareen", "translation": "Then We produced after them other generations."}, {"ayah": 43, "translit": "Maa tasbiqu min ummatin ajalahaa wa maa yastaakhiroon", "translation": "No nation will precede its time [of termination], nor will they remain [thereafter]."}, {"ayah": 44, "translit": "Summa arsalnaa Rusulanaa tatraa kulla maa jaaa'a ummatar Rasooluhaa kazzabooh; fa atba'naa ba'dahum ba'danw wa ja'alnaahum ahaadees; fabu'dal liqawmil laa yu'minoon", "translation": "Then We sent Our messengers in succession. Every time there came to a nation its messenger, they denied him, so We made them follow one another [to destruction], and We made them narrations. So away with a people who do not believe."}, {"ayah": 45, "translit": "Summa arsalnaa Moosaa wa akhaahu Haaroona bi Aayaatinaa wa sultaanim mubeen", "translation": "Then We sent Moses and his brother Aaron with Our signs and a clear authority"}, {"ayah": 46, "translit": "Ilaa Fir'awna wa mala'ihee fastakbaroo wa kaanoo qawman 'aaleem", "translation": "To Pharaoh and his establishment, but they were arrogant and were a haughty people."}, {"ayah": 47, "translit": "Faqaaloo annu'minu libasharaini mislinaa wa qawmuhumaa lanaa 'aabidoon", "translation": "They said, \"Should we believe two men like ourselves while their people are for us in servitude?\""}, {"ayah": 48, "translit": "Fakazzaboohumaa fakaanoo minal mmuhlakeen", "translation": "So they denied them and were of those destroyed."}, {"ayah": 49, "translit": "Wa laqad aatainaa Moosal Kitaaba la'allahum yahtadoon", "translation": "And We certainly gave Moses the Scripture that perhaps they would be guided."}, {"ayah": 50, "translit": "Wa ja'alnab na Maryama wa ummahooo aayatannw wa aawainaahumaaa ilaa rabwatin zaati qaraarinw wa ma'een", "translation": "And We made the son of Mary and his mother a sign and sheltered them within a high ground having level [areas] and flowing water."}, {"ayah": 51, "translit": "Yaaa aiyuhar Rusulu kuloo minat taiyibaati wa'maloo saalihan innee bimaa ta'maloona 'Aleem", "translation": "[Allah said], \"O messengers, eat from the good foods and work righteousness. Indeed, I, of what you do, am Knowing."}, {"ayah": 52, "translit": "Wa inna haaziheee ummatukum ummatanw waahidatanw wa Ana Rabbukum fattaqoon", "translation": "And indeed this, your religion, is one religion, and I am your Lord, so fear Me.\""}, {"ayah": 53, "translit": "Fataqatta'ooo amrahum bainahum zuburaa; kullu hizbim bimaa ladaihim farihoon", "translation": "But the people divided their religion among them into sects - each faction, in what it has, rejoicing."}, {"ayah": 54, "translit": "Fazarhum fee ghamratihim hattaa heen", "translation": "So leave them in their confusion for a time."}, {"ayah": 55, "translit": "A-yahsaboona annnamaa numiduhum bihee mimmaalinw wa baneen", "translation": "Do they think that what We extend to them of wealth and children"}, {"ayah": 56, "translit": "Nusaari'u lahum fil khairaat; bal laa yash'uroon", "translation": "Is [because] We hasten for them good things? Rather, they do not perceive."}, {"ayah": 57, "translit": "Innal lazeena hum min khashyati Rabbihim mushfiqoon", "translation": "Indeed, they who are apprehensive from fear of their Lord"}, {"ayah": 58, "translit": "Wallazeena hum bi Aayaati Rabbihim yu'minoon", "translation": "And they who believe in the signs of their Lord"}, {"ayah": 59, "translit": "Wallazeena hum bi Rabbihim laa yushrikoon", "translation": "And they who do not associate anything with their Lord"}, {"ayah": 60, "translit": "Wallazeena yu'toona maaa aataw wa quloobuhum wajilatun annahum ilaa Rabbihim raaji'oon", "translation": "And they who give what they give while their hearts are fearful because they will be returning to their Lord -"}, {"ayah": 61, "translit": "Ulaaa'ika yusaari'oona fil khairaati wa hum lahaa saabiqoon", "translation": "It is those who hasten to good deeds, and they outstrip [others] therein."}, {"ayah": 62, "translit": "Wa laa nukallifu nafsan illaa wus'ahaa wa ladainaa kitaabuny yantiqu bilhaqqi w ahum la yuzlamoon", "translation": "And We charge no soul except [with that within] its capacity, and with Us is a record which speaks with truth; and they will not be wronged."}, {"ayah": 63, "translit": "Bal quloobuhum fee ghamratim min haazaa wa lahum a'maalum min dooni zaalika hum lahaa 'aamiloon", "translation": "But their hearts are covered with confusion over this, and they have [evil] deeds besides disbelief which they are doing,"}, {"ayah": 64, "translit": "Hattaaa izaaa akhznaa mutrafeehim bil'azaabi izaa hum yaj'aroon", "translation": "Until when We seize their affluent ones with punishment, at once they are crying [to Allah] for help."}, {"ayah": 65, "translit": "Laa taj'arul yawma innakum minnaa laa tunsaroon", "translation": "Do not cry out today. Indeed, by Us you will not be helped."}, {"ayah": 66, "translit": "Qad kaanat Aayaatee tutlaa 'alaikum fakuntum 'alaaa a'qaabikum tankisoon", "translation": "My verses had already been recited to you, but you were turning back on your heels"}, {"ayah": 67, "translit": "Mustakbireena bihee saamiran tahjuroon", "translation": "In arrogance regarding it, conversing by night, speaking evil."}, {"ayah": 68, "translit": "Afalam yaddabbarrul qawla am jaaa'ahum maa lam yaati aabaaa'ahumul awwaleen", "translation": "Then have they not reflected over the Qur'an, or has there come to them that which had not come to their forefathers?"}, {"ayah": 69, "translit": "Am lam ya'rifoo Rasoolahum fahum lahoo munkiroon", "translation": "Or did they not know their Messenger, so they are toward him disacknowledging?"}, {"ayah": 70, "translit": "Am yaqooloona bihee jinnnah; bal jaaa'ahum bilhaqqi wa aksaruhum lil haqqi kaarihoon", "translation": "Or do they say, \"In him is madness?\" Rather, he brought them the truth, but most of them, to the truth, are averse."}, {"ayah": 71, "translit": "Wa lawit taba'al haqqu ahwaaa'ahum lafasadatis samaawaatu wal ardu wa man feehinnn; bal atainaahum bizikrihim fahum 'an zikrihim mu'ridon", "translation": "But if the Truth had followed their inclinations, the heavens and the earth and whoever is in them would have been ruined. Rather, We have brought them their message, but they, from their message, are turning away."}, {"ayah": 72, "translit": "Am tas'aluhum kharjan fakharaaju Rabbika khairunw wa Huwa khairur raaziqeen", "translation": "Or do you, [O Muhammad], ask them for payment? But the reward of your Lord is best, and He is the best of providers."}, {"ayah": 73, "translit": "Wa innaka latad'oohum ilaa Siraatim Mustaqeem", "translation": "And indeed, you invite them to a straight path."}, {"ayah": 74, "translit": "Wa innnal lazeena laa yu'minoona bil Aakhirati 'anis siraati lanaakiboon", "translation": "But indeed, those who do not believe in the Hereafter are deviating from the path."}, {"ayah": 75, "translit": "Wa law rahimnaahum wa kashafnaa maa bihim min durril lalajjoo fee tughyaanihim ya'mahoon", "translation": "And even if We gave them mercy and removed what was upon them of affliction, they would persist in their transgression, wandering blindly."}, {"ayah": 76, "translit": "Wa laqad akhaznaahum bil'azaabi famastakaanoo li Rabbihim wa maa yatadarra'oon", "translation": "And We had gripped them with suffering [as a warning], but they did not yield to their Lord, nor did they humbly supplicate, [and will continue thus]"}, {"ayah": 77, "translit": "Hattaaa izaa fatahnaa 'alaihim baaban zaa 'azaabin shadeedin izaa hum feehi mublisoon", "translation": "Until when We have opened before them a door of severe punishment, immediately they will be therein in despair."}, {"ayah": 78, "translit": "Wa Huwal lazeee ansha a-lakumus sam'a wal absaara wal af'idah; qaleelam maa tashkuroon", "translation": "And it is He who produced for you hearing and vision and hearts; little are you grateful."}, {"ayah": 79, "translit": "Wa Huwal lazee zara akum fil ardi wa ilaihi tuhsharoon", "translation": "And it is He who has multiplied you throughout the earth, and to Him you will be gathered."}, {"ayah": 80, "translit": "Wa Huwal lazee yuhyee wa yumeetu wa lahukh tilaaful laili wannahaar; afalaa ta'qiloon", "translation": "And it is He who gives life and causes death, and His is the alternation of the night and the day. Then will you not reason?"}, {"ayah": 81, "translit": "Bal qaaloo misla maa qaalal awwaloon", "translation": "Rather, they say like what the former peoples said."}, {"ayah": 82, "translit": "Qaalooo 'a-izaa mitnaa wa kunnaa turaabanw wa 'izaaman 'a-innaa lamab 'oosoon", "translation": "They said, \"When we have died and become dust and bones, are we indeed to be resurrected?"}, {"ayah": 83, "translit": "Laqad wu'idnaa nahnu wa aabaaa'unaa haazaa min qablu in haazaaa illaaa asaateerul awwaleen", "translation": "We have been promised this, we and our forefathers, before; this is not but legends of the former peoples.\""}, {"ayah": 84, "translit": "Qul limanil ardu wa man feehaaa in kuntum ta'lamoon", "translation": "Say, [O Muhammad], \"To whom belongs the earth and whoever is in it, if you should know?\""}, {"ayah": 85, "translit": "Sa-yaqooloona lillaah; qul afalaa tazakkkaroon", "translation": "They will say, \"To Allah.\" Say, \"Then will you not remember?\""}, {"ayah": 86, "translit": "Qul mar Rabbus samaawaatis sab'i wa Rabbul 'Arshil 'Azeem", "translation": "Say, \"Who is Lord of the seven heavens and Lord of the Great Throne?\""}, {"ayah": 87, "translit": "Sa yaqooloona lillaah; qul afalaa tattaqoon", "translation": "They will say, \"[They belong] to Allah.\" Say, \"Then will you not fear Him?\""}, {"ayah": 88, "translit": "Qul mam bi yadihee malakootu kulli shai'inw wa Huwa yujeeru wa laa yujaaru 'alaihi in kuntum ta'lamoon", "translation": "Say, \"In whose hand is the realm of all things - and He protects while none can protect against Him - if you should know?\""}, {"ayah": 89, "translit": "Sa yaqooloona lillaah; qul fa annaa tus haroon", "translation": "They will say, \"[All belongs] to Allah.\" Say, \"Then how are you deluded?\""}, {"ayah": 90, "translit": "Bal atainaahum bil haqqi wa innahum lakaaziboon", "translation": "Rather, We have brought them the truth, and indeed they are liars."}, {"ayah": 91, "translit": "Mat takhazal laahu minw waladinw wa maa kaana ma'ahoo min ilaah; izal lazahaba kullu ilaahim bimaa khalaqa wa la'alaa ba'duhum 'alaa ba'd; Subhaannal laahi 'ammaa yasifoon", "translation": "Allah has not taken any son, nor has there ever been with Him any deity. [If there had been], then each deity would have taken what it created, and some of them would have sought to overcome others. Exalted is Allah above what they describe [concerning Him]."}, {"ayah": 92, "translit": "'Aalimil Ghaibi wash shahhaadati fata'aalaa 'ammaa yushrikoon (section 5)", "translation": "[He is] Knower of the unseen and the witnessed, so high is He above what they associate [with Him]."}, {"ayah": 93, "translit": "Qur Rabbi immmaa turiyannee maa yoo'adoon", "translation": "Say, [O Muhammad], \"My Lord, if You should show me that which they are promised,"}, {"ayah": 94, "translit": "Rabbi falaa taj'alnee fil qawmiz zaalimeen", "translation": "My Lord, then do not place me among the wrongdoing people.\""}, {"ayah": 95, "translit": "Wa innaa 'alaaa an nuriyaka maa na'iduhum laqaadiroon", "translation": "And indeed, We are able to show you what We have promised them."}, {"ayah": 96, "translit": "Idfa' billate hiya ahsanus saiyi'ah; nahnu a'lamu bimaa yasifoon", "translation": "Repel, by [means of] what is best, [their] evil. We are most knowing of what they describe."}, {"ayah": 97, "translit": "Wa qur Rabbi a'oozu bika min hamazaatish Shayaateen", "translation": "And say, \"My Lord, I seek refuge in You from the incitements of the devils,"}, {"ayah": 98, "translit": "Wa a'oozu bika Rabbi ai-yahduroon", "translation": "And I seek refuge in You, my Lord, lest they be present with me.\""}, {"ayah": 99, "translit": "Hattaaa izaa jaaa'a ahada humul mawtu qaala Rabbir ji'oon", "translation": "[For such is the state of the disbelievers], until, when death comes to one of them, he says, \"My Lord, send me back"}, {"ayah": 100, "translit": "La'alleee a'malu saalihan feemaa taraktu kallaa; innahaa kalimatun huwa qaaa'iluhaa wa minw waraaa'him barzakhun ilaa Yawmi yub'asoon", "translation": "That I might do righteousness in that which I left behind.\" No! It is only a word he is saying; and behind them is a barrier until the Day they are resurrected."}, {"ayah": 101, "translit": "Fa izaa nufikha fis Soori falaaa ansaaba bainahum yawma'izinw wa laa yatasaaa'aloon", "translation": "So when the Horn is blown, no relationship will there be among them that Day, nor will they ask about one another."}, {"ayah": 102, "translit": "Faman saqulat mawaazee nuhoo fa ulaaa'ika humul muflihoon", "translation": "And those whose scales are heavy [with good deeds] - it is they who are the successful."}, {"ayah": 103, "translit": "Wa man khaffat mawaa zeenuhoo fa ulaaa'ikal lazeena khasiroon anfusahum fee Jahannnama khaalidoon", "translation": "But those whose scales are light - those are the ones who have lost their souls, [being] in Hell, abiding eternally."}, {"ayah": 104, "translit": "Talfahu wujoohahumun Naaru wa hum feehaa kaalihood", "translation": "The Fire will sear their faces, and they therein will have taut smiles."}, {"ayah": 105, "translit": "Alam takun Aayaatee tutlaa 'alaikum fakuntum bihaa tukazziboon", "translation": "[It will be said]. \"Were not My verses recited to you and you used to deny them?\""}, {"ayah": 106, "translit": "Qaaloo Rabbanaa ghalabat 'alainaa shiqwatunaa wa kunnaa qawman daaalleen", "translation": "They will say, \"Our Lord, our wretchedness overcame us, and we were a people astray."}, {"ayah": 107, "translit": "Rabbanaa akhrijnaa minhaa fa in 'udnaa fa innaa zaalimoon", "translation": "Our Lord, remove us from it, and if we were to return [to evil], we would indeed be wrongdoers.\""}, {"ayah": 108, "translit": "Qaalakh sa'oo feehaa wa laa tukallimoon", "translation": "He will say, \"Remain despised therein and do not speak to Me."}, {"ayah": 109, "translit": "Innahoo kaana fareequm min 'ibaadee yaqooloona Rabbanaaa aamannaa faghfir lanaa warhamnaa wa Anta khairur raahimeen", "translation": "Indeed, there was a party of My servants who said, 'Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.'"}, {"ayah": 110, "translit": "Fattakhaztumoohum sikhriyyan hattaaa ansawkum zikree wa kuntum minhum tadhakoon", "translation": "But you took them in mockery to the point that they made you forget My remembrance, and you used to laugh at them."}, {"ayah": 111, "translit": "Inee jazaituhumul Yawma bimaa sabarooo annahum humul faaa'izoon", "translation": "Indeed, I have rewarded them this Day for their patient endurance - that they are the attainers [of success].\""}, {"ayah": 112, "translit": "Qaala kam labistum fil ardi 'adada sineen", "translation": "[Allah] will say, \"How long did you remain on earth in number of years?\""}, {"ayah": 113, "translit": "Qaaloo labisnaa yawman aw ba'da yawmin fas'alil 'aaaddeen", "translation": "They will say, \"We remained a day or part of a day; ask those who enumerate.\""}, {"ayah": 114, "translit": "Qaala il labistum illaa qaleelal law annakum kuntum ta'lamoon", "translation": "He will say, \"You stayed not but a little - if only you had known."}, {"ayah": 115, "translit": "Afahsibtum annamaa khalaqnaakum 'abasanw wa annakum ilainaa laa turja'oon", "translation": "Then did you think that We created you uselessly and that to Us you would not be returned?\""}, {"ayah": 116, "translit": "Fata'aalal laahul Malikul Haqq; laaa ilaaha illaa Huwa Rabbul 'Arshil Kareem", "translation": "So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne."}, {"ayah": 117, "translit": "Wa mai yad'u ma'allaahi ilaahan aakhara laa burhaana lahoo bihee fa innnamaa hisaabuhoo 'inda Rabbih; innahoo laa yuflihul kaafiroon", "translation": "And whoever invokes besides Allah another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed."}, {"ayah": 118, "translit": "Wa qur Rabbigh fir warham wa Anta khairur raahimeen", "translation": "And, [O Muhammad], say, \"My Lord, forgive and have mercy, and You are the best of the merciful.\""}]}, {"num": 24, "name": "An-Nur", "meaning": "The Light", "verses": [{"ayah": 1, "translit": "Sooratun anzalnaahaa wa faradnaahaa wa anzalnaa feehaaa Aayaatim baiyinaatil la'allakum tazakkaroon", "translation": "[This is] a surah which We have sent down and made [that within it] obligatory and revealed therein verses of clear evidence that you might remember."}, {"ayah": 2, "translit": "Azzaaniyatu wazzaanee fajlidoo kulla waahidim minhumaa mi'ata jaldatinw wa laa taakhuzkum bihimaa raafatun fee deenil laahi in kuntum tu'minoona billaahi wal Yawmil Aakhiri wal yashhad 'azaabahumaa taaa'ifatum minal mu'mineen", "translation": "The [unmarried] woman or [unmarried] man found guilty of sexual intercourse - lash each one of them with a hundred lashes, and do not be taken by pity for them in the religion of Allah, if you should believe in Allah and the Last Day. And let a group of the believers witness their punishment."}, {"ayah": 3, "translit": "Azzaanee laa yankihu illaa zaaniyatan aw mushrikatanw wazzaaniyatu laa yankihuhaaa illaa zaanin aw mushrik; wa hurrima zaalika 'alal mu'mineen", "translation": "The fornicator does not marry except a [female] fornicator or polytheist, and none marries her except a fornicator or a polytheist, and that has been made unlawful to the believers."}, {"ayah": 4, "translit": "Wallazeena yarmoonal muhsanaati summa lam yaatoo bi-arba'ati shuhadaaa'a fajlidoohum samaaneena jaldatanw wa laa taqbaloo lahum shahaadatan abadaa; wa ulaaa'ika humul faasiqoon", "translation": "And those who accuse chaste women and then do not produce four witnesses - lash them with eighty lashes and do not accept from them testimony ever after. And those are the defiantly disobedient,"}, {"ayah": 5, "translit": "Illal lazeena taaboo mim ba'di zaalika wa aslahoo fa innal laaha Ghafoorur Raheem", "translation": "Except for those who repent thereafter and reform, for indeed, Allah is Forgiving and Merciful."}, {"ayah": 6, "translit": "Wallazeena yarmoona azwaajahum wa lam yakul lahum shuhadaaa'u illaaa anfusuhum fashahaadatu ahadihim arb'u shahaadaatim billaahi innahoo laminas saadiqeen", "translation": "And those who accuse their wives [of adultery] and have no witnesses except themselves - then the witness of one of them [shall be] four testimonies [swearing] by Allah that indeed, he is of the truthful."}, {"ayah": 7, "translit": "Wal khaamisatu anna la'natal laahi 'alaihi in kaana minal kaazibeen", "translation": "And the fifth [oath will be] that the curse of Allah be upon him if he should be among the liars."}, {"ayah": 8, "translit": "Wa yadra'u anhal 'azaaba an tashhada arba'a shahaa daatim billaahi innahoo laminal kaazibeen", "translation": "But it will prevent punishment from her if she gives four testimonies [swearing] by Allah that indeed, he is of the liars."}, {"ayah": 9, "translit": "Wal khaamisata anna ghadabal laahi 'alaihaaa in kaana minas saadiqeen", "translation": "And the fifth [oath will be] that the wrath of Allah be upon her if he was of the truthful."}, {"ayah": 10, "translit": "Wa law laa fadlul laahi 'alaikum wa rahmatuhoo wa annal laaha Tawwaabun Hakeem", "translation": "And if not for the favor of Allah upon you and His mercy... and because Allah is Accepting of repentance and Wise."}, {"ayah": 11, "translit": "Innal lazeena jaaa'oo bilifki 'usbatum minkum; laa tahsaboohu sharral lakum bal huwa khairul lakum; likul limri'im minhum mak tasaba minal-ism; wallazee tawallaa kibrahoo minhum lahoo 'azaabun 'azeem", "translation": "Indeed, those who came with falsehood are a group among you. Do not think it bad for you; rather it is good for you. For every person among them is what [punishment] he has earned from the sin, and he who took upon himself the greater portion thereof - for him is a great punishment."}, {"ayah": 12, "translit": "Law laaa iz sami'tumoohu zannal mu'minoona walmu'minaatu bi anfusihim khairanw wa qaaloo haazaaa ifkum mmubeen", "translation": "Why, when you heard it, did not the believing men and believing women think good of one another and say, \"This is an obvious falsehood\"?"}, {"ayah": 13, "translit": "Law laa jaaa'oo 'alaihi bi-arba'ati shuhadaaa'; fa iz lam yaatoo bishshuhadaaa'i fa ulaaa 'ika 'indal laahi humul kaaziboon", "translation": "Why did they [who slandered] not produce for it four witnesses? And when they do not produce the witnesses, then it is they, in the sight of Allah, who are the liars."}, {"ayah": 14, "translit": "Wa law laa fadlul laahi 'alaikum wa rahmatuhoo fiddunyaa wal aakhirati lamassakum fee maaa afadtum feehi 'azaabun 'azeem", "translation": "And if it had not been for the favor of Allah upon you and His mercy in this world and the Hereafter, you would have been touched for that [lie] in which you were involved by a great punishment"}, {"ayah": 15, "translit": "iz talaqqawnahoo bi alsinatikum wa taqooloona bi afwaahikum maa laisa lakum bihee 'ilmunw wa tahsaboo nahoo haiyinanw wa huwa 'indl laahi 'azeem", "translation": "When you received it with your tongues and said with your mouths that of which you had no knowledge and thought it was insignificant while it was, in the sight of Allah, tremendous."}, {"ayah": 16, "translit": "Wa law laaa iz sami'tu moohu qultum maa yakoonu lanaaa an natakallama bihaazaa Subhaanaka haaza buhtaanun 'azeem", "translation": "And why, when you heard it, did you not say, \"It is not for us to speak of this. Exalted are You, [O Allah]; this is a great slander\"?"}, {"ayah": 17, "translit": "Ya'izukumul laahu an ta'oodoo limisliheee abadan in kuntum mu'mineen", "translation": "Allah warns you against returning to the likes of this [conduct], ever, if you should be believers."}, {"ayah": 18, "translit": "Wa yubaiyinul laahu lakumul Aayaat; wallaahu 'Aleemun Hakeem", "translation": "And Allah makes clear to you the verses, and Allah is Knowing and Wise."}, {"ayah": 19, "translit": "Innal lazeena yuhibboona an tashee'al faahishatu fil lazeena aamanoo lahum 'azaabun aleemun fid dunyaa wal Aakhirah; wallaahu ya'lamu wa antum laa ta'lamoon", "translation": "Indeed, those who like that immorality should be spread [or publicized] among those who have believed will have a painful punishment in this world and the Hereafter. And Allah knows and you do not know."}, {"ayah": 20, "translit": "Wa law laa fadlul laahi 'alaikum wa rahmatuhoo wa annal laaha Ra'oofur Raheem", "translation": "And if it had not been for the favor of Allah upon you and His mercy... and because Allah is Kind and Merciful."}, {"ayah": 21, "translit": "Yaaa aiyuhal lazeena aamanoo laa tattabi'oo khutuwaatish Shaitaan; wa many-yattabi' khutuwaatish Shaitaani fa innahoo yaamuru bilfahshaaa'i walmunkar; wa law laa fadlul laahi 'alaikum wa rahmatuhoo maa zakaa minkum min ahadin abadanw wa laakinnal laaha yuzakkee many-yashaaa'; wallaahu Samee'un 'Aleem", "translation": "O you who have believed, do not follow the footsteps of Satan. And whoever follows the footsteps of Satan - indeed, he enjoins immorality and wrongdoing. And if not for the favor of Allah upon you and His mercy, not one of you would have been pure, ever, but Allah purifies whom He wills, and Allah is Hearing and Knowing."}, {"ayah": 22, "translit": "Wa laa yaatali ulul fadli minkum wassa'ati ai yu'tooo ulil qurbaa walmasaakeena walmuhaajireena fee sabeelillaahi walya'foo walyasfahoo; alaa tuhibboona ai yaghfiral laahu lakum; wal laahu Ghafoorur Raheem", "translation": "And let not those of virtue among you and wealth swear not to give [aid] to their relatives and the needy and the emigrants for the cause of Allah, and let them pardon and overlook. Would you not like that Allah should forgive you? And Allah is Forgiving and Merciful."}, {"ayah": 23, "translit": "Innal lazeena yarmoonal muhsanaatil ghaafilaatil mu'minaati lu'inoo fid dunyaa wal Aakhirati wa lahum 'azaabun 'azeem", "translation": "Indeed, those who [falsely] accuse chaste, unaware and believing women are cursed in this world and the Hereafter; and they will have a great punishment"}, {"ayah": 24, "translit": "Yawma tashhhadu 'alaihim alsinatuhum wa aideehim wa arjuluhum bimaa kaanoo ya'maloon", "translation": "On a Day when their tongues, their hands and their feet will bear witness against them as to what they used to do."}, {"ayah": 25, "translit": "Yawma'iziny yuwaf feehimul laahu deenahumul haqqa wa ya'lamoona annal laaha Huwal Haqqul Mubeen", "translation": "That Day, Allah will pay them in full their deserved recompense, and they will know that it is Allah who is the perfect in justice."}, {"ayah": 26, "translit": "Alkhabeesaatu lilkha beeseena walkhabeesoona lilkhabeesaati wattaiyibaatu littaiyibeena wattaiyiboona littaiyibaat; ulaaa'ika mubar ra'oona maimma yaqooloona lahum maghfiratunw wa rizqun kareem", "translation": "Evil words are for evil men, and evil men are [subjected] to evil words. And good words are for good men, and good men are [an object] of good words. Those [good people] are declared innocent of what the slanderers say. For them is forgiveness and noble provision."}, {"ayah": 27, "translit": "Yaaa aiyuhal lazeena aamanoo laa tadkhuloo buyootan ghaira buyootikum hatta tastaanisoo wa tusallimoo 'allaa ahlihaa; zaalikum khairul lakum la'allakum tazakkaroon", "translation": "O you who have believed, do not enter houses other than your own houses until you ascertain welcome and greet their inhabitants. That is best for you; perhaps you will be reminded."}, {"ayah": 28, "translit": "Fa il lam tajidoo feehaaa ahadan falaa tadkhuloohaa hattaa yu'zana lakum wa in qeela lakumurji'oo farji'oo huwa azkaa lakum; wallaahu bimaa ta'maloona 'Aleem", "translation": "And if you do not find anyone therein, do not enter them until permission has been given you. And if it is said to you, \"Go back,\" then go back; it is purer for you. And Allah is Knowing of what you do."}, {"ayah": 29, "translit": "Laisa 'alaikum junaahun ann tadkhuloo buyootan ghaira maskoonatin feeha mataa'ul lakum; wallaahu ya'lamu maa tubdoona wa maa taktumoon", "translation": "There is no blame upon you for entering houses not inhabited in which there is convenience for you. And Allah knows what you reveal and what you conceal."}, {"ayah": 30, "translit": "Qul lilmu' mineena yaghuuddoo min absaarihim wa yahfazoo furoojahum; zaalika azkaa lahum; innallaaha khabeerum bimaa yasna'oon", "translation": "Tell the believing men to reduce [some] of their vision and guard their private parts. That is purer for them. Indeed, Allah is Acquainted with what they do."}, {"ayah": 31, "translit": "Wa qul lilmu'minaati yaghdudna min absaarihinna wa yahfazna furoojahunna wa laa yubdeena zeenatahunna illaa maa zahara minhaa walyadribna bikhumurihinna 'alaa juyoobihinna wa laa yubdeena zeenatahunna illaa libu'oolatihinna aw aabaaa'i hinna aw aabaaa'i bu'oolati hinna aw abnaaa'ihinaa aw abnaaa'i bu'oolatihinnna aw ikhwaanihinnna aw baneee ikhwaanihinna aw banee akhawaatihinna aw nisaaa'i hinna aw maa malakat aimaanuhunna awit taabi'eena ghairi ilil irbati minar rijaali awit tiflillazeena lam yazharoo 'alaa 'awraatin nisaaa'i wala yadribnna bi arjulihinna min zeenatihinn; wa toobooo ilallaahi jammee'an aiyuhal mu'minoona la'allakum tuflihoon", "translation": "And tell the believing women to reduce [some] of their vision and guard their private parts and not expose their adornment except that which [necessarily] appears thereof and to wrap [a portion of] their headcovers over their chests and not expose their adornment except to their husbands, their fathers, their husbands' fathers, their sons, their husbands' sons, their brothers, their brothers' sons, their sisters' sons, their women, that which their right hands possess, or those male attendants having no physical desire, or children who are not yet aware of the private aspects of women. And let them not stamp their feet to make known what they conceal of their adornment. And turn to Allah in repentance, all of you, O believers, that you might succeed."}, {"ayah": 32, "translit": "Wa ankihul ayaamaa minkum was saaliheena min 'ibaadikum wa imaa'kum; iny-yakoonoo fuqaraaa'a yughni himul laahu min fadlih; wal laahu Waasi'un 'Aleem", "translation": "And marry the unmarried among you and the righteous among your male slaves and female slaves. If they should be poor, Allah will enrich them from His bounty, and Allah is all-Encompassing and Knowing."}, {"ayah": 33, "translit": "Wal yasta'fifil lazeena laa yajidoona nikaahan hata yughniyahumul laahu mi fadlih; wallazeena yabtaghoonal kitaaba mimmaa malakat aimaanukum fakaatiboohum in 'alimtum feehim khairanw wa aatoohum mimmaalil laahil lazeee aataakum; wa laa tukrihoo fatayaatikum 'alal bighaaa'i in aradna tahassunal litabtaghoo 'aradal hayaatid dunyaa; wa mai yukrihhunna fa innal laaha mim ba'di ikraahihinna Ghafoor Raheem", "translation": "But let them who find not [the means for] marriage abstain [from sexual relations] until Allah enriches them from His bounty. And those who seek a contract [for eventual emancipation] from among whom your right hands possess - then make a contract with them if you know there is within them goodness and give them from the wealth of Allah which He has given you. And do not compel your slave girls to prostitution, if they desire chastity, to seek [thereby] the temporary interests of worldly life. And if someone should compel them, then indeed, Allah is [to them], after their compulsion, Forgiving and Merciful."}, {"ayah": 34, "translit": "Wa laqad anzalnaaa ilaikum Aayaatim mubaiyinaatinw wa masalam minnal lazeena khalaw min qablikum wa maw'izatal lilmuttaqeen", "translation": "And We have certainly sent down to you distinct verses and examples from those who passed on before you and an admonition for those who fear Allah."}, {"ayah": 35, "translit": "Allaahu noorus samaawaati wal ard; masalu noorihee kamishkaatin feehaa misbaah; almisbaahu fee zujaajatin azzujaajatu ka annahaa kawkabun durriyyuny yooqadu min shajaratim mubaarakatin zaitoonatil laa shariqiyyatinw wa laa gharbiyyatiny yakaadu zaituhaa yudeee'u wa law alm tamsashu naar; noorun 'alaa noor; yahdil laahu linoorihee mai yashaaa'; wa yadribul laahul amsaala linnaas; wallaahu bikulli shai'in Aleem", "translation": "Allah is the Light of the heavens and the earth. The example of His light is like a niche within which is a lamp, the lamp is within glass, the glass as if it were a pearly [white] star lit from [the oil of] a blessed olive tree, neither of the east nor of the west, whose oil would almost glow even if untouched by fire. Light upon light. Allah guides to His light whom He wills. And Allah presents examples for the people, and Allah is Knowing of all things."}, {"ayah": 36, "translit": "Fee buyootin azinal laahu an turfa'a wa yuzkara feehasmuhoo yusabbihu lahoo feehaa bilghuduwwi wal aasaal", "translation": "[Such niches are] in mosques which Allah has ordered to be raised and that His name be mentioned therein; exalting Him within them in the morning and the evenings"}, {"ayah": 37, "translit": "Rinjaalul laa tulheehim tijaaratunw wa laa bai'un 'an zikril laahi wa iqaamis Salaati wa eetaaa'iz Zakaati yakkhaafoona Yawman tataqallabu feehil quloobu wal absaar", "translation": "[Are] men whom neither commerce nor sale distracts from the remembrance of Allah and performance of prayer and giving of zakah. They fear a Day in which the hearts and eyes will [fearfully] turn about -"}, {"ayah": 38, "translit": "Liyajziyahumul laahu ahsana maa 'amiloo wa yazeedahum  min fadlih; wal laahu yarzuqu mai yashaaa'u bighairi hisaab", "translation": "That Allah may reward them [according to] the best of what they did and increase them from His bounty. And Allah gives provision to whom He wills without account."}, {"ayah": 39, "translit": "Wallazeena kafarooo a'maaluhum kasaraabim biqee'atiny yahsabuhuz zamaanu maaa'an hattaaa izaa jaaa'ahoo lam yajid hu shai'anw wa wajadal laaha 'indahoo fa waffaahu hisaabah; wallaahu saree'ul hisaab", "translation": "But those who disbelieved - their deeds are like a mirage in a lowland which a thirsty one thinks is water until, when he comes to it, he finds it is nothing but finds Allah before Him, and He will pay him in full his due; and Allah is swift in account."}, {"ayah": 40, "translit": "Aw kazulumaatin fee bahril lujjiyyiny yaghshaahu mawjum min fawqihee mawjum min fawqihee mawjum min fawqihee sahaab; zulumatum ba'duhaa fawqa ba'din izaaa akhraja yadahoo lam yakad yaraahaa wa mal lam yaj'alil laahu lahoo noora famaa lahoo min noor", "translation": "Or [they are] like darknesses within an unfathomable sea which is covered by waves, upon which are waves, over which are clouds - darknesses, some of them upon others. When one puts out his hand [therein], he can hardly see it. And he to whom Allah has not granted light - for him there is no light."}, {"ayah": 41, "translit": "Alam tara annal laaha yusabbihu lahoo man fissamaawaati wal ardi wat tairu saaaffaatim kullun qad 'alima Salaatahoo wa tasbeehah; wallaahu 'aleemum bimaa yaf'aloon", "translation": "Do you not see that Allah is exalted by whomever is within the heavens and the earth and [by] the birds with wings spread [in flight]? Each [of them] has known his [means of] prayer and exalting [Him], and Allah is Knowing of what they do."}, {"ayah": 42, "translit": "Wa lillaahi mulkus samaawaati wal ardi wa ilal laahil maseer", "translation": "And to Allah belongs the dominion of the heavens and the earth, and to Allah is the destination."}, {"ayah": 43, "translit": "Alam tara annal laaha yuzjee sahaaban summa yu'allifu bainahoo summa yaj'aluhoo rukaaman fataral wadqa yakhruju min khilaalihee wa yunazzilu minas samaaa'i min jibaalin feehaa mim barain fa yuseebu bihee mai yashaaa'u wa yasrifuhoo 'am mai yashaaa'u yakkaadu sanaa barqihee yazhabu bil absaar", "translation": "Do you not see that Allah drives clouds? Then He brings them together, then He makes them into a mass, and you see the rain emerge from within it. And He sends down from the sky, mountains [of clouds] within which is hail, and He strikes with it whom He wills and averts it from whom He wills. The flash of its lightening almost takes away the eyesight."}, {"ayah": 44, "translit": "Yuqallibul laahul laila wannahaar; inna fee zaalika la'ibratal li ulil absaar", "translation": "Allah alternates the night and the day. Indeed in that is a lesson for those who have vision."}, {"ayah": 45, "translit": "Wallaahu khalaqa kulla daaabbatim mim maaa'in faminhum mai yamshee 'alaa batnihee wa minhum mai yamshee 'alaa rijlaine wa minhum mai yamshee 'alaaa arba'; yakhluqul laahu maa yashaaa'; innal laaha 'alaa kulli shai'in Qadeer", "translation": "Allah has created every [living] creature from water. And of them are those that move on their bellies, and of them are those that walk on two legs, and of them are those that walk on four. Allah creates what He wills. Indeed, Allah is over all things competent."}, {"ayah": 46, "translit": "Laqad anzalnaaa Aayaatim mubaiyinaat; wallaahu yahdee mai yashaaa'u ilaa Siraatim Mustaqeem", "translation": "We have certainly sent down distinct verses. And Allah guides whom He wills to a straight path."}, {"ayah": 47, "translit": "Wa yaqooloona aamannaa billaahi wa bir Rasooli wa ata'naa summa yatawallaa fareequm minhum mim ba'di zaalik; wa maaa ulaaa'ika bilmu'mineen", "translation": "But the hypocrites say, \"We have believed in Allah and in the Messenger, and we obey\"; then a party of them turns away after that. And those are not believers."}, {"ayah": 48, "translit": "Wa izaa du'ooo ilal laahi wa Rasoolihee li yahkuma bainahum izaa fareequm minhum mu'ridoon", "translation": "And when they are called to [the words of] Allah and His Messenger to judge between them, at once a party of them turns aside [in refusal]."}, {"ayah": 49, "translit": "Wa iny-yakul lahumul haqqu yaatooo ilaihi muz'ineen", "translation": "But if the right is theirs, they come to him in prompt obedience."}, {"ayah": 50, "translit": "Afee quloobihim ma radun amirtaabooo am yakhaafoona ani yaheefallaahu 'alaihim wa Rasooluh; bal ulaaa'ika humuz zaalimoon", "translation": "Is there disease in their hearts? Or have they doubted? Or do they fear that Allah will be unjust to them, or His Messenger? Rather, it is they who are the wrongdoers."}, {"ayah": 51, "translit": "Innamaa kaana qawlal mu'mineena izaa du'ooo ilal laahi wa Rasoolihee li yahkuma bainahum ai yaqooloo sami'naa wa ata'naa; wa ulaaa'ika humul muflihoon", "translation": "The only statement of the [true] believers when they are called to Allah and His Messenger to judge between them is that they say, \"We hear and we obey.\" And those are the successful."}, {"ayah": 52, "translit": "Wa mai yuti'il laaha wa Rasoolahoo wa yakhshal laaha wa yattaqhi fa ulaaa'ika humul faaa'izoon", "translation": "And whoever obeys Allah and His Messenger and fears Allah and is conscious of Him - it is those who are the attainers."}, {"ayah": 53, "translit": "Wa aqsamoo billaahi jahda aimaanihim la'in amartahum la yakhrujunna qul laa tuqsimoo taa'atum ma'roofah innal laaha khabeerum bimaa ta'maloon", "translation": "And they swear by Allah their strongest oaths that if you ordered them, they would go forth [in Allah 's cause]. Say, \"Do not swear. [Such] obedience is known. Indeed, Allah is Acquainted with that which you do.\""}, {"ayah": 54, "translit": "Qul atee'ul laaha wa atee'ur Rasoola fa in tawallaw fa innamaa 'alaihi maa hummila wa 'alaikum maa hummiltum wa in tutee'oohu tahtadoo; wa maa'alar Rasooli illal balaaghul mubeen", "translation": "Say, \"Obey Allah and obey the Messenger; but if you turn away - then upon him is only that [duty] with which he has been charged, and upon you is that with which you have been charged. And if you obey him, you will be [rightly] guided. And there is not upon the Messenger except the [responsibility for] clear notification.\""}, {"ayah": 55, "translit": "Wa'adal laahul lazeena aamanoo minkum wa 'amilus saalihaati la yastakhlifan nahum fil ardi kamastakh lafal lazeena min qablihim wa la yumakkinanna lahum deenahumul lazir tadaa lahum wa la yubaddilannahum mim ba'di khawfihim amnaa; ya'budoonanee laayushrikoona bee shai'aa; wa man kafara ba'da zaalika fa ulaaa'ika humul faasiqoon", "translation": "Allah has promised those who have believed among you and done righteous deeds that He will surely grant them succession [to authority] upon the earth just as He granted it to those before them and that He will surely establish for them [therein] their religion which He has preferred for them and that He will surely substitute for them, after their fear, security, [for] they worship Me, not associating anything with Me. But whoever disbelieves after that - then those are the defiantly disobedient."}, {"ayah": 56, "translit": "Wa aqeemus Salaata wa aatuz Zakaata wa atee'ur Rasoola la'allakum turhamoon", "translation": "And establish prayer and give zakah and obey the Messenger - that you may receive mercy."}, {"ayah": 57, "translit": "Laa tahsabannal lazeena kafaroo mu'jizeena fil ard; wa maawaahumun Naaru wa labi'sal maseer", "translation": "Never think that the disbelievers are causing failure [to Allah] upon the earth. Their refuge will be the Fire - and how wretched the destination."}, {"ayah": 58, "translit": "Yaaa aiyuhal lazeena aamanoo li yastaazinkumul lazeena malakat aimaanukum wallazeena lam yablughul huluma minkum salaasa marraat; min qabli Salaatil Fajri wa heena tada'oona siyaa bakum minaz zaheerati wa mim ba'di Salaatil Ishaaa'; salaasu 'awraatil lakum; laisa 'alaikum wa laa 'alaihim junaahum ba'dahunn; tawwaafoona 'alaikum ba'dukum 'alaa ba'd; kazaalika yubaiyinul laahu lakumul aayaat wallaahu 'Aleemun Hakeem", "translation": "O you who have believed, let those whom your right hands possess and those who have not [yet] reached puberty among you ask permission of you [before entering] at three times: before the dawn prayer and when you put aside your clothing [for rest] at noon and after the night prayer. [These are] three times of privacy for you. There is no blame upon you nor upon them beyond these [periods], for they continually circulate among you - some of you, among others. Thus does Allah make clear to you the verses; and Allah is Knowing and Wise."}, {"ayah": 59, "translit": "Wa izaa balaghal atfaalu minkumul huluma fal yastaazinoo kamas taazanal lazeena min qablihim; kazaalika yubaiyinul laahu lakum Aayaatih; wallaahu 'Aleemun Hakeem", "translation": "And when the children among you reach puberty, let them ask permission [at all times] as those before them have done. Thus does Allah make clear to you His verses; and Allah is Knowing and Wise."}, {"ayah": 60, "translit": "Walqawaa'idu minan nisaaa'il laatee laa yarjoona nikaahan falisa 'alaihinna junaahun ai yada'na siyaabahunna ghaira mutabar rijaatim bizeenah; wa ai yasta'fifna khairul lahunn; wallaahu Samee'un 'Aleem", "translation": "And women of post-menstrual age who have no desire for marriage - there is no blame upon them for putting aside their outer garments [but] not displaying adornment. But to modestly refrain [from that] is better for them. And Allah is Hearing and Knowing."}, {"ayah": 61, "translit": "Laisa 'alal a'maa barajunw wa laa 'alal a'raji barajunw wa laa 'alal mareedi barajun wa laa 'alaa anfusikum an taakuloo mim buyootikum aw buyooti aabaaa'ikum aw buyooti ummahaatikum aw buyooti ikhwaanikum aw buyooti akhawaatikum aw buyooti a'maamikum aw buyooti 'ammaatikum aw buyooti akhwaalikum aw buyooti khaalaatikum aw maa malaktum mafaatihahooo aw sadeeqikum; laisa 'alaikum junaahun an taakuloo jamee'an aw ashtaata; fa izaa dakhaltum buyootan fasallimoo 'alaaa anfusikum tahiyyatam min 'indil laahi mubaarakatan taiyibah; kazaalika yubai yinul laahu lakumul Aayaati la'allakum ta'qiloon", "translation": "There is not upon the blind [any] constraint nor upon the lame constraint nor upon the ill constraint nor upon yourselves when you eat from your [own] houses or the houses of your fathers or the houses of your mothers or the houses of your brothers or the houses of your sisters or the houses of your father's brothers or the houses of your father's sisters or the houses of your mother's brothers or the houses of your mother's sisters or [from houses] whose keys you possess or [from the house] of your friend. There is no blame upon you whether you eat together or separately. But when you enter houses, give greetings of peace upon each other - a greeting from Allah, blessed and good. Thus does Allah make clear to you the verses [of ordinance] that you may understand."}, {"ayah": 62, "translit": "Innamal mu'minoonal lazeena aamanoo billaahi wa Rasoolihee wa izaa kaanoo ma'ahoo 'alaaa amrin jaami'il lam yazhaboo hataa yastaazinooh; innal lazeena yastaa zinookana ulaaa'ikal lazeena yu'minoona billaahi wa Rasoolih; fa izas taazanooka liba'di shaanihim faazal liman shi'ta minhum wastaghfir lahumul laah; innal laaha Gahfoor Raheem", "translation": "The believers are only those who believe in Allah and His Messenger and, when they are [meeting] with him for a matter of common interest, do not depart until they have asked his permission. Indeed, those who ask your permission, [O Muhammad] - those are the ones who believe in Allah and His Messenger. So when they ask your permission for something of their affairs, then give permission to whom you will among them and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 63, "translit": "La taj'aloo du'aaa'ar Rasooli bainakum kadu'aaa'i badikum ba'daa; qad ya'lamul laahul lazeena yatasallaloona minkum liwaazaa; fal yahzaril lazeena yukhaalifoona 'an amriheee an tuseebahum fitnatun aw yuseebahum 'azaabun aleem", "translation": "Do not make [your] calling of the Messenger among yourselves as the call of one of you to another. Already Allah knows those of you who slip away, concealed by others. So let those beware who dissent from the Prophet's order, lest fitnah strike them or a painful punishment."}, {"ayah": 64, "translit": "Alaaa inna lillaahi maa fis samaawaati wal ardi qad ya'lamu maaa antum 'alaihi wa Yawma yurja'oona ilaihi fa yunaabi 'uhum bimaa 'amiloo; wallaahu bikulli shai'in 'Aleem", "translation": "Unquestionably, to Allah belongs whatever is in the heavens and earth. Already He knows that upon which you [stand] and [knows] the Day when they will be returned to Him and He will inform them of what they have done. And Allah is Knowing of all things."}]}, {"num": 25, "name": "Al-Furqan", "meaning": "The Criterion", "verses": [{"ayah": 1, "translit": "Tabaarakal lazee nazzalal Furqaana 'alaa 'abdihee li yakoona lil'aalameena nazeera", "translation": "Blessed is He who sent down the Criterion upon His Servant that he may be to the worlds a warner -"}, {"ayah": 2, "translit": "Allazee lahoo mulkus samaawaati wal ardi wa lam yattakhiz waladanw wa lam yakul lahoo shareekun filmulki wa khalaqa kulla shai'in faqaddarahoo taqdeeraa", "translation": "He to whom belongs the dominion of the heavens and the earth and who has not taken a son and has not had a partner in dominion and has created each thing and determined it with [precise] determination."}, {"ayah": 3, "translit": "Wattakhazoo min dooniheee aahihatal laa yakhluqoona shai'anw wa hum yukhlaqoona wa laa yamlikoona li anfusihim darranw wa laa naf'anw wa laa yamlikoona mawtanw wa laa hayaatanw wa laa nushooraa", "translation": "But they have taken besides Him gods which create nothing, while they are created, and possess not for themselves any harm or benefit and possess not [power to cause] death or life or resurrection."}, {"ayah": 4, "translit": "Wa qaalal lazeena kafarooo in haazaaa illaaa ifkunif taraahu wa a'aanahoo 'alaihi qawmun aakharoona faqad jaaa'oo zulmanw wa zooraa", "translation": "And those who disbelieve say, \"This [Qur'an] is not except a falsehood he invented, and another people assisted him in it.\" But they have committed an injustice and a lie."}, {"ayah": 5, "translit": "Wa qaalooo asaateerul awwaleenak tatabahaa fahiya tumlaa 'alaihi bukratanw wa aseelaa", "translation": "And they say, \"Legends of the former peoples which he has written down, and they are dictated to him morning and afternoon.\""}, {"ayah": 6, "translit": "Qul anzalhul lazee ya'lamus sirra fis samaawaati wal-ard; innahoo kaana Ghafoorar Raheemaa", "translation": "Say, [O Muhammad], \"It has been revealed by He who knows [every] secret within the heavens and the earth. Indeed, He is ever Forgiving and Merciful.\""}, {"ayah": 7, "translit": "Wa qaaloo maa li haazar Rasooli yaakulut ta'aama wa yamshee fil aswaaq; law laaa unzila ilaihi malakun fa yakoona ma'ahoo nazeeraa", "translation": "And they say, \"What is this messenger that eats food and walks in the markets? Why was there not sent down to him an angel so he would be with him a warner?"}, {"ayah": 8, "translit": "Aw yulqaaa ilaihi kanzun aw takoonu lahoo jannatuny yaakulu minhaa; wa qaalaz zaalimoona in tattabi'oona illaa rajulam mas hooraa", "translation": "Or [why is not] a treasure presented to him [from heaven], or does he [not] have a garden from which he eats?\" And the wrongdoers say, \"You follow not but a man affected by magic.\""}, {"ayah": 9, "translit": "Unzur kaifa daraboo lakal amsaala fadalloo falaa yastatee'oona sabeelaa", "translation": "Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way."}, {"ayah": 10, "translit": "Tabaarakal lazeee in shaaa'a ja'ala laka khairam min zaalika jannaatin tajree min tahtihal anhaaru wa yaj'al laka qusooraa", "translation": "Blessed is He who, if He willed, could have made for you [something] better than that - gardens beneath which rivers flow - and could make for you palaces."}, {"ayah": 11, "translit": "Bal kazzaboo bis Saa'ati wa a'tadnaa liman kazzaba bis Saa'ati sa'eeraa", "translation": "But they have denied the Hour, and We have prepared for those who deny the Hour a Blaze."}, {"ayah": 12, "translit": "Izaa ra'at hum mim ma kaanim ba'eedin sami'oo lahaa taghaiyuzanw wa zafeeraa", "translation": "When the Hellfire sees them from a distant place, they will hear its fury and roaring."}, {"ayah": 13, "translit": "Wa izaaa ulqoo minhaa makaanan daiyiqam muqar raneena da'aw hunaalika subooraa", "translation": "And when they are thrown into a narrow place therein bound in chains, they will cry out thereupon for destruction."}, {"ayah": 14, "translit": "Laa tad'ul yawma subooranw waahidanw wad'oo subooran kaseeraa", "translation": "[They will be told], \"Do not cry this Day for one destruction but cry for much destruction.\""}, {"ayah": 15, "translit": "Qul azaalika khairun am Jannatul khuldil latee wu'idal muttaqoon; kaanat lahum jazaaa'anw wa maseeraa", "translation": "Say, \"Is that better or the Garden of Eternity which is promised to the righteous? It will be for them a reward and destination."}, {"ayah": 16, "translit": "Lahum feehaa maa yashaaa'oona khaalideen; kaana 'alaa Rabbika wa'dam mas'oolaa", "translation": "For them therein is whatever they wish, [while] abiding eternally. It is ever upon your Lord a promise [worthy to be] requested."}, {"ayah": 17, "translit": "Wa Yawma yahshuruhum wa maa ya'budoona min doonil lahi fa yaqoolu 'a-antum adlaltum 'ibaadee haaa'ulaaa'i am hum dallus sabeel", "translation": "And [mention] the Day He will gather them and that which they worship besides Allah and will say, \"Did you mislead these, My servants, or did they [themselves] stray from the way?\""}, {"ayah": 18, "translit": "Qaaloo Subhaanaka maa kaana yambaghee lanaaa an nattakhiza min doonika min awliyaaa'a wa laakim matta'tahum wa aabaaa'ahum hattaa nasuz zikra wa kaanoo qawmam booraa", "translation": "They will say, \"Exalted are You! It was not for us to take besides You any allies. But You provided comforts for them and their fathers until they forgot the message and became a people ruined.\""}, {"ayah": 19, "translit": "Faqad kazzabookum bimaa taqooloona famaa tastatee'oona sarfanw wa laa nasraa; wa mai yazlim minkum nuziqhu 'azaaban kabeeraa", "translation": "So they will deny you, [disbelievers], in what you say, and you cannot avert [punishment] or [find] help. And whoever commits injustice among you - We will make him taste a great punishment."}, {"ayah": 20, "translit": "Wa maaa arsalnaa qablaka minal mursaleena illaaa innahum la yaakuloonat ta'aama wa yamshoona fil aswaaq; wa ja'alnaa ba'dakum liba'din fitnatan atasbiroon; wa kaana Rabbuka Baseera", "translation": "And We did not send before you, [O Muhammad], any of the messengers except that they ate food and walked in the markets. And We have made some of you [people] as trial for others - will you have patience? And ever is your Lord, Seeing."}, {"ayah": 21, "translit": "Wa qaalal lazeena laa yarjoona liqaaa'anaa law laaa unzila 'alainal malaaa'ikatu awnaraa Rabbanaa; laqadistakbaroo feee anfusihim wa 'ataw 'utuwwan kabeeraa", "translation": "And those who do not expect the meeting with Us say, \"Why were not angels sent down to us, or [why] do we [not] see our Lord?\" They have certainly become arrogant within themselves and [become] insolent with great insolence."}, {"ayah": 22, "translit": "Yawma yarawnal malaaa 'ikata laa bushraa Yawma'izil lilmujrimeena wa yaqooloona hijram mahjooraa", "translation": "The day they see the angels - no good tidings will there be that day for the criminals, and [the angels] will say, \"Prevented and inaccessible.\""}, {"ayah": 23, "translit": "Wa qadimnaaa ilaa maa 'amiloo min 'amalin faja'alnaahu habaaa'am mansooraa", "translation": "And We will regard what they have done of deeds and make them as dust dispersed."}, {"ayah": 24, "translit": "As haabul jannati yawma'izin khairum mustaqar ranw wa ahsanu maqeela", "translation": "The companions of Paradise, that Day, are [in] a better settlement and better resting place."}, {"ayah": 25, "translit": "Wa Yawma tashaqqaqus samaaa'u bilghamaami wa nuzzilal malaaa'ikatu tanzeela", "translation": "And [mention] the Day when the heaven will split open with [emerging] clouds, and the angels will be sent down in successive descent."}, {"ayah": 26, "translit": "Almulku Yawma'izinil haqqu lir Rahmaan; wa kaana Yawman'alal kaafireena 'aseeraa", "translation": "True sovereignty, that Day, is for the Most Merciful. And it will be upon the disbelievers a difficult Day."}, {"ayah": 27, "translit": "Wa Yawma ya'adduz zaalimu 'alaa yadaihi yaqoolu yaa laitanit takhaztu ma'ar Rasooli sabeelaa", "translation": "And the Day the wrongdoer will bite on his hands [in regret] he will say, \"Oh, I wish I had taken with the Messenger a way."}, {"ayah": 28, "translit": "Yaa wailataa laitanee lam attakhiz fulaanan khaleelaa", "translation": "Oh, woe to me! I wish I had not taken that one as a friend."}, {"ayah": 29, "translit": "Laqad adallanee 'aniz zikri ba'da iz jaaa'anee; wa kaanash Shaitaanu lil insaani khazoolaa", "translation": "He led me away from the remembrance after it had come to me. And ever is Satan, to man, a deserter.\""}, {"ayah": 30, "translit": "Wa qaalar Rasoolu yaa Rabbi inna qawmit takhazoo haazal Qur-aana mahjooraa", "translation": "And the Messenger has said, \"O my Lord, indeed my people have taken this Qur'an as [a thing] abandoned.\""}, {"ayah": 31, "translit": "Wa kazaalika ja'alnaa likulli Nabiyyin 'aduwwam minal mujrimeen; wa kafaa bi Rabbika haadiyanw wa naseeraa", "translation": "And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper."}, {"ayah": 32, "translit": "Wa qaalal lazeena kafaroo law laa nuzzila 'alaihil Quraanu jumlatanw waahidah; kazaalika linusabbita bihee fu'aadaka wa rattalnaahu tarteelaa", "translation": "And those who disbelieve say, \"Why was the Qur'an not revealed to him all at once?\" Thus [it is] that We may strengthen thereby your heart. And We have spaced it distinctly."}, {"ayah": 33, "translit": "Wa laa yaatoonaka bimasainn illaa ji'naaka bilhaqqi wa ahsana tafseeraa", "translation": "And they do not come to you with an argument except that We bring you the truth and the best explanation."}, {"ayah": 34, "translit": "Allazeena yuhsharoona 'alaa wujoohim ilaa jahannama ulaaa'ika sharrum makaananw wa adallu sabeelaa )section 3)", "translation": "The ones who are gathered on their faces to Hell - those are the worst in position and farthest astray in [their] way."}, {"ayah": 35, "translit": "Wa laqad aatainaa Moosal Kitaaba wa ja'alnaa ma'ahooo akhaahu Haaroona wazeeraa", "translation": "And We had certainly given Moses the Scripture and appointed with him his brother Aaron as an assistant."}, {"ayah": 36, "translit": "Faqulnaz habaaa ilal qawmil lazeena kazzaboo bi Aayaatinaa fadammarnaahum tadmeeraa", "translation": "And We said, \"Go both of you to the people who have denied Our signs.\" Then We destroyed them with [complete] destruction."}, {"ayah": 37, "translit": "Wa qawma Noohil lammaa kazzabur Rusula aghraqnaahum wa ja'alnaahum linnaasi Aayatanw wa a'tadnaa lizzaalimeena 'azaaban aleemaa", "translation": "And the people of Noah - when they denied the messengers, We drowned them, and We made them for mankind a sign. And We have prepared for the wrongdoers a painful punishment."}, {"ayah": 38, "translit": "Wa 'Aadanw Samooda wa As haabar Rassi wa quroonam baina zaalika kaseeraa", "translation": "And [We destroyed] 'Aad and Thamud and the companions of the well and many generations between them."}, {"ayah": 39, "translit": "Wa kullandarabnaa lahul amsaala wa kullan tabbarnaa tatbeera", "translation": "And for each We presented examples [as warnings], and each We destroyed with [total] destruction."}, {"ayah": 40, "translit": "Wa laqad ataw 'alal qaryatil lateee umtirat mataras saw'; afalam yakoonoo yarawnahaa; bal kaanoo laa yarjoona nushooraa", "translation": "And they have already come upon the town which was showered with a rain of evil. So have they not seen it? But they are not expecting resurrection."}, {"ayah": 41, "translit": "Wa izaa ra awka iny yattakhizoonaka illaa huzuwan ahaazal lazee ba'asal laahu Rasoolaa", "translation": "And when they see you, [O Muhammad], they take you not except in ridicule, [saying], \"Is this the one whom Allah has sent as a messenger?"}, {"ayah": 42, "translit": "In kaada la yudillunaa 'an aalihatinaa law laaa an sabarnaa 'alaihaa; wa sawfa ya'lamoona heena yarawnal 'azaaba man adallu sabeela", "translation": "He almost would have misled us from our gods had we not been steadfast in [worship of] them.\" But they are going to know, when they see the punishment, who is farthest astray in [his] way."}, {"ayah": 43, "translit": "Ara'aita manit takhaza ilaahahoo hawaahu afa anta takoonu 'alaihi wakeelaa", "translation": "Have you seen the one who takes as his god his own desire? Then would you be responsible for him?"}, {"ayah": 44, "translit": "Am tahsabu annna aksarahum yasma'oona aw ya''qiloon; in hum illaa kal an'aami bal hum adallu sabeelan", "translation": "Or do you think that most of them hear or reason? They are not except like livestock. Rather, they are [even] more astray in [their] way."}, {"ayah": 45, "translit": "Alam tara ilaa Rabbika kaifa maddaz zilla wa law shaaa'a laja'alahoo saakinan summa ja'alnash shamsa 'alaihe daleelaa", "translation": "Have you not considered your Lord - how He extends the shadow, and if He willed, He could have made it stationary? Then We made the sun for it an indication."}, {"ayah": 46, "translit": "Summa qabadnaahu ilainaa qabdany yaseeraa", "translation": "Then We hold it in hand for a brief grasp."}, {"ayah": 47, "translit": "Wa Huwal lazee ja'ala lakumul laila libaasanw wannawma subaatanw wa ja'alan nahaara nushooraa", "translation": "And it is He who has made the night for you as clothing and sleep [a means for] rest and has made the day a resurrection."}, {"ayah": 48, "translit": "Wa Huwal lazeee arsalar riyaaha bushram baina yadai rahmatih; wa anzalnaa minas samaaa'i maaa'an tahooraa", "translation": "And it is He who sends the winds as good tidings before His mercy, and We send down from the sky pure water"}, {"ayah": 49, "translit": "Linuhyiya bihee balda tam maitanw wa nusqiyahoo mimmaa khalaqnaaa an'aa manw wa anaasiyya kaseeraa", "translation": "That We may bring to life thereby a dead land and give it as drink to those We created of numerous livestock and men."}, {"ayah": 50, "translit": "Wa laqad sarrafnaahu bainahum li yazzakkaroo fa abaaa aksarun naasi illaa kufooraa", "translation": "And We have certainly distributed it among them that they might be reminded, but most of the people refuse except disbelief."}, {"ayah": 51, "translit": "Wa law shi'naa laba'asnaa fee kulli qar yatin nazeeraa", "translation": "And if We had willed, We could have sent into every city a warner."}, {"ayah": 52, "translit": "Falaa tuti'il kaafireena wa jaahidhum bihee jihaadan kabeeraa", "translation": "So do not obey the disbelievers, and strive against them with the Qur'an a great striving."}, {"ayah": 53, "translit": "Wa Huwal lazee marajal bahraini haazaa 'azbun furaatunw wa haazaa milhun ujaaj; wa ja'ala bainahumaa barzakhanw wa hijram mahjooraa", "translation": "And it is He who has released [simultaneously] the two seas, one fresh and sweet and one salty and bitter, and He placed between them a barrier and prohibiting partition."}, {"ayah": 54, "translit": "Wa Huwal lazee khalaqa minal maaa'i basharran fa ja'alahoo nasaban wa sihraa; wa kaana Rabbuka Qadeeraa", "translation": "And it is He who has created from water a human being and made him [a relative by] lineage and marriage. And ever is your Lord competent [concerning creation]."}, {"ayah": 55, "translit": "Wa ya'budoona min doonil laahi maa laa yanfa'uhum wa laa yadurruhum; wa kaanal kaafiru 'alaa Rabbihee zaheeraa", "translation": "But they worship rather than Allah that which does not benefit them or harm them, and the disbeliever is ever, against his Lord, an assistant [to Satan]."}, {"ayah": 56, "translit": "Wa maa arsalnaaka illaa mubashshiranw wa nazeeraa", "translation": "And We have not sent you, [O Muhammad], except as a bringer of good tidings and a warner."}, {"ayah": 57, "translit": "Qul maaa as'alukum 'alaihi min ajrin illaa man shaaa'a ai yattakhiza ilaa Rabbihee sabeelaa", "translation": "Say, \"I do not ask of you for it any payment - only that whoever wills might take to his Lord a way.\""}, {"ayah": 58, "translit": "Wa tawakkal 'alal Haiyil lazee laa yamootu wa sabbih bihamdih; wa kafaa bihee bizunoobi 'ibaadihee khabeeraa", "translation": "And rely upon the Ever-Living who does not die, and exalt [Allah] with His praise. And sufficient is He to be, with the sins of His servants, Acquainted -"}, {"ayah": 59, "translit": "Allazee khalaqas samaawaati wal arda wa maa bainahumaa fee sittati aiyaamin summmmastawaa 'alal 'Arsh; ar Rahmaanu fas'al bihee khabeeraa", "translation": "He who created the heavens and the earth and what is between them in six days and then established Himself above the Throne - the Most Merciful, so ask about Him one well informed."}, {"ayah": 60, "translit": "Wa izaa qeela lahumus judoo lir Rahmaani qaaloo wa mar Rahmaanu anasjudu limaa taamurunaa wa zaadahum nufooraa", "translation": "And when it is said to them, \"Prostrate to the Most Merciful,\" they say, \"And what is the Most Merciful? Should we prostrate to that which you order us?\" And it increases them in aversion."}, {"ayah": 61, "translit": "Tabaarakal lazee ja'ala fis samaaa'i buroojanw wa ja'ala feehaa siraajanw wa qamaram muneeraa", "translation": "Blessed is He who has placed in the sky great stars and placed therein a [burning] lamp and luminous moon."}, {"ayah": 62, "translit": "Wa huwal lazee ja'alal laila wannahaara khilfatal liman araada ai yazzakkara aw araadaa shookooraa", "translation": "And it is He who has made the night and the day in succession for whoever desires to remember or desires gratitude."}, {"ayah": 63, "translit": "Wa 'ibaadur Rahmaanil lazeena yamshoona 'alal ardi hawnanw wa izaa khaata bahumul jaahiloona qaaloo salaamaa", "translation": "And the servants of the Most Merciful are those who walk upon the earth easily, and when the ignorant address them [harshly], they say [words of] peace,"}, {"ayah": 64, "translit": "Wallazeena yabeetoona li Rabbihim sujjadanw wa qiyaamaa", "translation": "And those who spend [part of] the night to their Lord prostrating and standing [in prayer]"}, {"ayah": 65, "translit": "Wallazeena yaqooloona Rabbanas rif 'annnaa 'azaaba Jahannama inn 'azaabahaa kaana gharaamaa", "translation": "And those who say, \"Our Lord, avert from us the punishment of Hell. Indeed, its punishment is ever adhering;"}, {"ayah": 66, "translit": "Innahaa saaa'at mustaqarranw wa muqaamaa", "translation": "Indeed, it is evil as a settlement and residence.\""}, {"ayah": 67, "translit": "Wallazeena izaaa anfaqoo lam yusrifoo wa lam yaqturoo wa kaana baina zaalika qawaamaa", "translation": "And [they are] those who, when they spend, do so not excessively or sparingly but are ever, between that, [justly] moderate"}, {"ayah": 68, "translit": "Wallazeena laa yad'oona ma'al laahi ilaahan aakhara wa laa yaqtuloonan nafsal latee harramal laahu illaa bilhaqqi wa laa yaznoon; wa mai yaf'al zaalika yalqa asaamaa", "translation": "And those who do not invoke with Allah another deity or kill the soul which Allah has forbidden [to be killed], except by right, and do not commit unlawful sexual intercourse. And whoever should do that will meet a penalty."}, {"ayah": 69, "translit": "Yudaa'af lahul 'azaabu Yawmal Qiyaamati wa yakhlud feehee muhaanaa", "translation": "Multiplied for him is the punishment on the Day of Resurrection, and he will abide therein humiliated -"}, {"ayah": 70, "translit": "Illaa man taaba wa 'aamana wa 'amila 'amalan saalihan fa ulaaa'ika yubad dilul laahu saiyi aatihim hasanaat; wa kaanal laahu Ghafoorar Raheemaa", "translation": "Except for those who repent, believe and do righteous work. For them Allah will replace their evil deeds with good. And ever is Allah Forgiving and Merciful."}, {"ayah": 71, "translit": "Wa man taaba wa 'amila saalihan fa innnahoo yatoobu ilal laahi mataabaa", "translation": "And he who repents and does righteousness does indeed turn to Allah with [accepted] repentance."}, {"ayah": 72, "translit": "Wallazeena laa yash hadoonaz zoora wa izaa marroo billaghwi marroo kiraamaa", "translation": "And [they are] those who do not testify to falsehood, and when they pass near ill speech, they pass by with dignity."}, {"ayah": 73, "translit": "Wallazeena izaa zukkiroo bi Aayaati Rabbihim lam yakhirroo 'alaihaa summanw wa'umyaanaa", "translation": "And those who, when reminded of the verses of their Lord, do not fall upon them deaf and blind."}, {"ayah": 74, "translit": "Wallazeena yaqooloona Rabbanaa hab lanaa min azwaajinaa wa zurriyaatinaa qurrata a'yuninw waj 'alnaa lilmuttaqeena Imaamaa", "translation": "And those who say, \"Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous.\""}, {"ayah": 75, "translit": "Ulaaa'ika yujzawnal ghurfata bimaa sabaroo wa yulaqqawna feehaa tahiyyatanw wa salaamaa", "translation": "Those will be awarded the Chamber for what they patiently endured, and they will be received therein with greetings and [words of] peace."}, {"ayah": 76, "translit": "Khaalideena feehaa; hasunat mustaqarranw wa muqaamaa", "translation": "Abiding eternally therein. Good is the settlement and residence."}, {"ayah": 77, "translit": "Qul maa ya'ba'u bikum Rabbee law laa du'aaa'ukum faqad kazzabtum fasawfa yakoonu lizaamaa", "translation": "Say, \"What would my Lord care for you if not for your supplication?\" For you [disbelievers] have denied, so your denial is going to be adherent."}]}, {"num": 26, "name": "Ash-Shu'ara", "meaning": "The Poets", "verses": [{"ayah": 1, "translit": "Taa-Seeen-Meeem", "translation": "Ta, Seen, Meem."}, {"ayah": 2, "translit": "Tilka Aayaatul Kitaabil Mubeen", "translation": "These are the verses of the clear Book."}, {"ayah": 3, "translit": "La'allaka baakhi'un nafsaka allaa yakoonoo mu'mineen", "translation": "Perhaps, [O Muhammad], you would kill yourself with grief that they will not be believers."}, {"ayah": 4, "translit": "In nashaa nunazzil 'alaihim minas samaaa'i Aayatan fazallat a'naaquhum lahaa khaadi'een", "translation": "If We willed, We could send down to them from the sky a sign for which their necks would remain humbled."}, {"ayah": 5, "translit": "Wa maa yaateehim min zikrim minar Rahmaani muhdasin illaa kaanoo 'anhu mu'rideen", "translation": "And no revelation comes to them anew from the Most Merciful except that they turn away from it."}, {"ayah": 6, "translit": "Faqad kazzaboo fasa yaateehim ambaaa'u maa kaanoo bihee yastahzi'oon", "translation": "For they have already denied, but there will come to them the news of that which they used to ridicule."}, {"ayah": 7, "translit": "Awa lam yaraw ilal ardi kam ambatnaa feehaa min kulli zawjin kareem", "translation": "Did they not look at the earth - how much We have produced therein from every noble kind?"}, {"ayah": 8, "translit": "Inn fee zaalika la Aayah; wa maa kaana aksaruhum mu'mineen", "translation": "Indeed in that is a sign, but most of them were not to be believers."}, {"ayah": 9, "translit": "Wa inna Rabbaka la Huwal 'Azeezur Raheem", "translation": "And indeed, your Lord - He is the Exalted in Might, the Merciful."}, {"ayah": 10, "translit": "Wa iz naadaa Rabbuka Moosaaa ani'-til qawmaz zaalimeen", "translation": "And [mention] when your Lord called Moses, [saying], \"Go to the wrongdoing people -"}, {"ayah": 11, "translit": "Qawma Fir'awn; alaa yattaqoon", "translation": "The people of Pharaoh. Will they not fear Allah?\""}, {"ayah": 12, "translit": "Qaala Rabbi inneee akhaafu ai yukazziboon", "translation": "He said, \"My Lord, indeed I fear that they will deny me"}, {"ayah": 13, "translit": "Wa yadeequ sadree wa laa yantaliqu lisaanee fa arsil ilaa Haaroon", "translation": "And that my breast will tighten and my tongue will not be fluent, so send for Aaron."}, {"ayah": 14, "translit": "Wa lahum 'alaiya zambun fa akhaafu ai yaqtuloon", "translation": "And they have upon me a [claim due to] sin, so I fear that they will kill me.\""}, {"ayah": 15, "translit": "Qaala kallaa fazhabaa bi Aayaatinaaa innaa ma'akum mustami'oon", "translation": "[Allah] said, \"No. Go both of you with Our signs; indeed, We are with you, listening."}, {"ayah": 16, "translit": "Faatiyaa Fir'awna faqoolaaa innaa Rasoolu Rabbil 'aalameen", "translation": "Go to Pharaoh and say, 'We are the messengers of the Lord of the worlds,"}, {"ayah": 17, "translit": "An arsil ma'anaa Baneee Israaa'eel", "translation": "[Commanded to say], \"Send with us the Children of Israel.\"'\""}, {"ayah": 18, "translit": "Qaala alam nurabbika feenaa waleedanw wa labista feenaa min 'umurika sineen", "translation": "[Pharaoh] said, \"Did we not raise you among us as a child, and you remained among us for years of your life?"}, {"ayah": 19, "translit": "Wa fa'alta fa'latakal latee fa'alta wa anta minal kaafireen", "translation": "And [then] you did your deed which you did, and you were of the ungrateful.\""}, {"ayah": 20, "translit": "Qaala fa'altuhaaa izanw wa ana minad daaaleen", "translation": "[Moses] said, \"I did it, then, while I was of those astray."}, {"ayah": 21, "translit": "Fafarartu minkum lam maa khiftukum fawahaba lee Rabbee hukmanw wa ja'alanee minal mursaleen", "translation": "So I fled from you when I feared you. Then my Lord granted me wisdom and prophethood and appointed me [as one] of the messengers."}, {"ayah": 22, "translit": "Wa tilka ni'matun tamun nuhaa 'alaiya an 'abbatta Baneee Israaa'eel", "translation": "And is this a favor of which you remind me - that you have enslaved the Children of Israel?\""}, {"ayah": 23, "translit": "Qaala Fir'awnu wa maa Rabbul 'aalameen", "translation": "Said Pharaoh, \"And what is the Lord of the worlds?\""}, {"ayah": 24, "translit": "Qaala Rabbus samaawaati wal ardi wa maa bainahumaa in kuntum mooqineen", "translation": "[Moses] said, \"The Lord of the heavens and earth and that between them, if you should be convinced.\""}, {"ayah": 25, "translit": "Qaala liman hawlahooo alaa tastami'oon", "translation": "[Pharaoh] said to those around him, \"Do you not hear?\""}, {"ayah": 26, "translit": "Qaala Rabbukum wa Rabbu aabaaa'ikumul awwaleen", "translation": "[Moses] said, \"Your Lord and the Lord of your first forefathers.\""}, {"ayah": 27, "translit": "Qaala inna Rasoolakumul lazee ursila ilaikum lamajnoon", "translation": "[Pharaoh] said, \"Indeed, your 'messenger' who has been sent to you is mad.\""}, {"ayah": 28, "translit": "Qaala Rabbul mashriqi wal maghribi wa maa baina humaa in kuntum ta'qiloon", "translation": "[Moses] said, \"Lord of the east and the west and that between them, if you were to reason.\""}, {"ayah": 29, "translit": "Qaala la'init takhazta ilaahan ghairee la aj'alannaka minal masjooneen", "translation": "[Pharaoh] said, \"If you take a god other than me, I will surely place you among those imprisoned.\""}, {"ayah": 30, "translit": "Qaala awalw ji'tuka bishai'im mubeen", "translation": "[Moses] said, \"Even if I brought you proof manifest?\""}, {"ayah": 31, "translit": "Qaala faati biheee in kunta minas saadiqeen", "translation": "[Pharaoh] said, \"Then bring it, if you should be of the truthful.\""}, {"ayah": 32, "translit": "Fa alqaa 'asaahu fa izaaa hiya su'baanum mubeen", "translation": "So [Moses] threw his staff, and suddenly it was a serpent manifest."}, {"ayah": 33, "translit": "Wa naza'a yadahoo faizaa hiya baidaaa'u linnaa zireen", "translation": "And he drew out his hand; thereupon it was white for the observers."}, {"ayah": 34, "translit": "Qaala lilmala-i hawlahooo inna haazaa lasaahirun 'aleem", "translation": "[Pharaoh] said to the eminent ones around him, \"Indeed, this is a learned magician."}, {"ayah": 35, "translit": "Yureedu ai yukhrijakum min ardikum bisihrihee famaazaa taamuroon", "translation": "He wants to drive you out of your land by his magic, so what do you advise?\""}, {"ayah": 36, "translit": "Qaalooo arjih wa akhaahu wab'as filmadaaa'ini haashireen", "translation": "They said, \"Postpone [the matter of] him and his brother and send among the cities gatherers"}, {"ayah": 37, "translit": "Yaatooka bikulli sah haarin 'aleem", "translation": "Who will bring you every learned, skilled magician.\""}, {"ayah": 38, "translit": "Fa jumi'as saharatu limeeqaati Yawmim ma'loom", "translation": "So the magicians were assembled for the appointment of a well-known day."}, {"ayah": 39, "translit": "Wa qeela linnaasi hal antum mujtami'oon", "translation": "And it was said to the people, \"Will you congregate"}, {"ayah": 40, "translit": "La'allanaa nattabi'us saharata in kaanoo humul ghaalibeen", "translation": "That we might follow the magicians if they are the predominant?\""}, {"ayah": 41, "translit": "Falammaa jaaa'as saharatu qaaloo li Fir'awna a'inna lanaa la ajjran in kunnaa nahnul ghaalibeen", "translation": "And when the magicians arrived, they said to Pharaoh, \"Is there indeed for us a reward if we are the predominant?\""}, {"ayah": 42, "translit": "Qaala na'am wa innakum izal laminal muqarrabeen", "translation": "He said, \"Yes, and indeed, you will then be of those near [to me].\""}, {"ayah": 43, "translit": "Qaala lahum Moosaaa alqoo maaa antum mulqoon", "translation": "Moses said to them, \"Throw whatever you will throw.\""}, {"ayah": 44, "translit": "Fa alqaw hibaalahum wa 'isiyyahum wa qaaloo bi'izzati Fir'awna innaa lanahnul ghaaliboon", "translation": "So they threw their ropes and their staffs and said, \"By the might of Pharaoh, indeed it is we who are predominant.\""}, {"ayah": 45, "translit": "Fa alqaa Moosaa 'asaahu fa izaa hiya talqafu maa yaafikoon", "translation": "Then Moses threw his staff, and at once it devoured what they falsified."}, {"ayah": 46, "translit": "Fa ulqiyas saharatu saajideen", "translation": "So the magicians fell down in prostration [to Allah]."}, {"ayah": 47, "translit": "Qaalooo aamannaa bi Rabbil 'aalameen", "translation": "They said, \"We have believed in the Lord of the worlds,"}, {"ayah": 48, "translit": "Rabbi Moosaa wa Haaroon", "translation": "The Lord of Moses and Aaron.\""}, {"ayah": 49, "translit": "Qaala aamantum lahoo qabla an aazana lakum innahoo lakabeerukumul lazee 'alla makumus sihra falasawfa ta'lamoon; la uqatti'anna aidiyakum wa arjulakum min khilaafinw wa la usallibanna kum ajma'een", "translation": "[Pharaoh] said, \"You believed Moses before I gave you permission. Indeed, he is your leader who has taught you magic, but you are going to know. I will surely cut off your hands and your feet on opposite sides, and I will surely crucify you all.\""}, {"ayah": 50, "translit": "Qaaloo la daira innaaa ilaa Rabbinaa munqalliboon", "translation": "They said, \"No harm. Indeed, to our Lord we will return."}, {"ayah": 51, "translit": "Innaa natma'u ai yaghfira lanaa Rabbunna khataa yaanaaa an kunnaaa awwalal mu'mineen", "translation": "Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers.\""}, {"ayah": 52, "translit": "Wa awhainaaa ilaa Moosaaa an asri bi'ibaadeee innakum muttaba'oon", "translation": "And We inspired to Moses, \"Travel by night with My servants; indeed, you will be pursued.\""}, {"ayah": 53, "translit": "Fa arsala Fir'awnu filmadaaa'ini haashireen", "translation": "Then Pharaoh sent among the cities gatherers"}, {"ayah": 54, "translit": "Inna haaa'ulaaa'i lashir zimatun qaleeloon", "translation": "[And said], \"Indeed, those are but a small band,"}, {"ayah": 55, "translit": "Wa innahum lanaa laghaaa'izoon", "translation": "And indeed, they are enraging us,"}, {"ayah": 56, "translit": "Wa innaa lajamee'un haaziroon", "translation": "And indeed, we are a cautious society... \""}, {"ayah": 57, "translit": "Fa akhrajnaahum min Jannaatinw wa 'uyoon", "translation": "So We removed them from gardens and springs"}, {"ayah": 58, "translit": "Wa kunoozinw wa ma qaamin kareem", "translation": "And treasures and honorable station -"}, {"ayah": 59, "translit": "Kazaalika wa awrasnaahaa Baneee Israaa'eel", "translation": "Thus. And We caused to inherit it the Children of Israel."}, {"ayah": 60, "translit": "Fa atba'oohum mushriqeen", "translation": "So they pursued them at sunrise."}, {"ayah": 61, "translit": "Falammaa taraaa'al jam'aani qaala as haabu Moosaaa innaa lamudrakoon", "translation": "And when the two companies saw one another, the companions of Moses said, \"Indeed, we are to be overtaken!\""}, {"ayah": 62, "translit": "Qaala kallaaa inna ma'iya Rabbee sa yahdeen", "translation": "[Moses] said, \"No! Indeed, with me is my Lord; He will guide me.\""}, {"ayah": 63, "translit": "Fa awhainaaa ilaa Moosaaa anidrib bi'asaakal bahra fanfalaqa fakaana kullu firqin kattawdil 'azeem", "translation": "Then We inspired to Moses, \"Strike with your staff the sea,\" and it parted, and each portion was like a great towering mountain."}, {"ayah": 64, "translit": "Wa azlafnaa sammal aakhareen", "translation": "And We advanced thereto the pursuers."}, {"ayah": 65, "translit": "Wa anjainaa Moosaa wa mam ma'ahooo ajma'een", "translation": "And We saved Moses and those with him, all together."}, {"ayah": 66, "translit": "Summa aghraqnal aakhareen", "translation": "Then We drowned the others."}, {"ayah": 67, "translit": "Inna fee zaalika la Aayaah; wa maa kaana aksaru hu mu'mineen", "translation": "Indeed in that is a sign, but most of them were not to be believers."}, {"ayah": 68, "translit": "Wa inna Rabbaka la Huwal 'Azeezur Raheem", "translation": "And indeed, your Lord - He is the Exalted in Might, the Merciful."}, {"ayah": 69, "translit": "Watlu 'alaihim naba-a Ibraaheem", "translation": "And recite to them the news of Abraham,"}, {"ayah": 70, "translit": "Iz qaala li abeehi wa qawmihee maa ta'budoon", "translation": "When he said to his father and his people, \"What do you worship?\""}, {"ayah": 71, "translit": "Qaaloo na'budu asnaaman fanazallu lahaa 'aakifeen", "translation": "They said, \"We worship idols and remain to them devoted.\""}, {"ayah": 72, "translit": "Qaala hal yasma'oona kum iz tad'oon", "translation": "He said, \"Do they hear you when you supplicate?"}, {"ayah": 73, "translit": "Aw yanfa'oonakum aw yadurroon", "translation": "Or do they benefit you, or do they harm?\""}, {"ayah": 74, "translit": "Qaaloo bal wajadnaaa aabaaa 'anaa kazaalika yaf'aloon", "translation": "They said, \"But we found our fathers doing thus.\""}, {"ayah": 75, "translit": "Qaala afara 'aitum maa kuntum ta'budoon", "translation": "He said, \"Then do you see what you have been worshipping,"}, {"ayah": 76, "translit": "Antum wa aabaaa'ukumul aqdamoon", "translation": "You and your ancient forefathers?"}, {"ayah": 77, "translit": "Fa innahum 'aduwwwul leee illaa Rabbal 'aalameen", "translation": "Indeed, they are enemies to me, except the Lord of the worlds,"}, {"ayah": 78, "translit": "Allazee khalaqanee fa Huwa yahdeen", "translation": "Who created me, and He [it is who] guides me."}, {"ayah": 79, "translit": "Wallazee Huwa yut'imunee wa yasqeen", "translation": "And it is He who feeds me and gives me drink."}, {"ayah": 80, "translit": "Wa izaa mardtu fahuwa yashfeen", "translation": "And when I am ill, it is He who cures me"}, {"ayah": 81, "translit": "Wallazee yumeetunee summa yuhyeen", "translation": "And who will cause me to die and then bring me to life"}, {"ayah": 82, "translit": "Wallazeee atma'u ai yaghfira lee khateee' atee Yawmad Deen", "translation": "And who I aspire that He will forgive me my sin on the Day of Recompense.\""}, {"ayah": 83, "translit": "Rabbi hab lee hukmanw wa alhiqnee bis saaliheen", "translation": "[And he said], \"My Lord, grant me authority and join me with the righteous."}, {"ayah": 84, "translit": "Waj'al lee lisaana sidqin fil aakhireen", "translation": "And grant me a reputation of honor among later generations."}, {"ayah": 85, "translit": "Waj'alnee minw warasati Jannnatin Na'eem", "translation": "And place me among the inheritors of the Garden of Pleasure."}, {"ayah": 86, "translit": "Waghfir li abeee innahoo kaana mind daalleen", "translation": "And forgive my father. Indeed, he has been of those astray."}, {"ayah": 87, "translit": "Wa laa tukhzinee Yawma yub'asoon", "translation": "And do not disgrace me on the Day they are [all] resurrected -"}, {"ayah": 88, "translit": "Yawma laa yanfa'u maalunw wa laa banoon", "translation": "The Day when there will not benefit [anyone] wealth or children"}, {"ayah": 89, "translit": "Illaa man atal laaha biqalbin saleem", "translation": "But only one who comes to Allah with a sound heart.\""}, {"ayah": 90, "translit": "Wa uzlifatil Jannatu lilmuttaqeen", "translation": "And Paradise will be brought near [that Day] to the righteous."}, {"ayah": 91, "translit": "Wa burrizatil Jaheemu lilghaaween", "translation": "And Hellfire will be brought forth for the deviators,"}, {"ayah": 92, "translit": "Wa qeela lahum aina maa kuntum ta'budoon", "translation": "And it will be said to them, \"Where are those you used to worship"}, {"ayah": 93, "translit": "Min doonil laahi hal yansuroonakum aw yantasiroon", "translation": "Other than Allah? Can they help you or help themselves?\""}, {"ayah": 94, "translit": "Fakubkiboo feehaa hum walghaawoon", "translation": "So they will be overturned into Hellfire, they and the deviators"}, {"ayah": 95, "translit": "Wa junoodu Ibleesa ajma'oon", "translation": "And the soldiers of Iblees, all together."}, {"ayah": 96, "translit": "Qaaloo wa hum feehaa yakkhtasimoon", "translation": "They will say while they dispute therein,"}, {"ayah": 97, "translit": "Tallaahi in kunnaa lafee dalaalim mubeen", "translation": "\"By Allah, we were indeed in manifest error"}, {"ayah": 98, "translit": "Iz nusawweekum bi Rabbil 'aalameen", "translation": "When we equated you with the Lord of the worlds."}, {"ayah": 99, "translit": "Wa maaa adallanaaa illal mujrimoon", "translation": "And no one misguided us except the criminals."}, {"ayah": 100, "translit": "Famaa lanaa min shaa fi'een", "translation": "So now we have no intercessors"}, {"ayah": 101, "translit": "Wa laa sadeeqin hameem", "translation": "And not a devoted friend."}, {"ayah": 102, "translit": "Falaw anna lanaa karratan fanakoona minal mu'mineen", "translation": "Then if we only had a return [to the world] and could be of the believers... \""}, {"ayah": 103, "translit": "Inna fee zaalika la Aayatanw wa maa kaana aksaruhum mu'mineen", "translation": "Indeed in that is a sign, but most of them were not to be believers."}, {"ayah": 104, "translit": "Wa inna Rabbaka la Huwal 'Azeezur Raheem", "translation": "And indeed, your Lord - He is the Exalted in Might, the Merciful."}, {"ayah": 105, "translit": "Kazzabat qawmu Noohinil Mursaleen", "translation": "The people of Noah denied the messengers"}, {"ayah": 106, "translit": "Iz qaala lahum akhoohum Noohun alaa tattaqoon", "translation": "When their brother Noah said to them, \"Will you not fear Allah?"}, {"ayah": 107, "translit": "Innee lakum Rasoolun ameen", "translation": "Indeed, I am to you a trustworthy messenger."}, {"ayah": 108, "translit": "Fattaqullaaha wa atee'oon", "translation": "So fear Allah and obey me."}, {"ayah": 109, "translit": "Wa maaa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen", "translation": "And I do not ask you for it any payment. My payment is only from the Lord of the worlds."}, {"ayah": 110, "translit": "Fattaqul laaha wa atee'oon", "translation": "So fear Allah and obey me.\""}, {"ayah": 111, "translit": "Qaalooo anu'minu laka wattaba 'akal arzaloon", "translation": "They said, \"Should we believe you while you are followed by the lowest [class of people]?\""}, {"ayah": 112, "translit": "Qaala wa maa 'ilmee bimaa kaanoo ya'maloon", "translation": "He said, \"And what is my knowledge of what they used to do?"}, {"ayah": 113, "translit": "In hisaabuhum illaa 'alaa Rabbee law tash'uroon", "translation": "Their account is only upon my Lord, if you [could] perceive."}, {"ayah": 114, "translit": "Wa maaa ana bitaaridil mu'mineen", "translation": "And I am not one to drive away the believers."}, {"ayah": 115, "translit": "In ana illaa nazeerum mubeen", "translation": "I am only a clear warner.\""}, {"ayah": 116, "translit": "Qaaloo la'il lam tantahi yaa Noohu latakoonanna minal marjoomeen", "translation": "They said, \"If you do not desist, O Noah, you will surely be of those who are stoned.\""}, {"ayah": 117, "translit": "Qaala Rabbi inna qawmee kazzaboon", "translation": "He said, \"My Lord, indeed my people have denied me."}, {"ayah": 118, "translit": "Faftab bainee wa bai nahum fat hanw wa najjinee wa mam ma'iya minal mu'mineen", "translation": "Then judge between me and them with decisive judgement and save me and those with me of the believers.\""}, {"ayah": 119, "translit": "Fa anjainaahu wa mamma'ahoo fil fulkil mashhoon", "translation": "So We saved him and those with him in the laden ship."}, {"ayah": 120, "translit": "Summa aghraqnaa ba'dul baaqeen", "translation": "Then We drowned thereafter the remaining ones."}, {"ayah": 121, "translit": "Inna fee zaalika la Aayaah; wa maa kaana aksaruhum mu'mineen", "translation": "Indeed in that is a sign, but most of them were not to be believers."}, {"ayah": 122, "translit": "Wa inna Rabbaka la huwal 'Azeezur Raheem", "translation": "And indeed, your Lord - He is the Exalted in Might, the Merciful."}, {"ayah": 123, "translit": "Kazzabat 'Aadunil mursaleen", "translation": "'Aad denied the messengers"}, {"ayah": 124, "translit": "Iz qaala lahum akhoohum Hoodun alaa tattaqoon", "translation": "When their brother Hud said to them, \"Will you not fear Allah?"}, {"ayah": 125, "translit": "Innee lakum Rasoolun ameen", "translation": "Indeed, I am to you a trustworthy messenger."}, {"ayah": 126, "translit": "Fattaqullaaha wa atee'oon", "translation": "So fear Allah and obey me."}, {"ayah": 127, "translit": "Wa maa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen", "translation": "And I do not ask you for it any payment. My payment is only from the Lord of the worlds."}, {"ayah": 128, "translit": "Atabnoona bikulli ree'in aayatan ta'basoon", "translation": "Do you construct on every elevation a sign, amusing yourselves,"}, {"ayah": 129, "translit": "Wa tattakhizoona masaani'a la'allakum takhludoon", "translation": "And take for yourselves palaces and fortresses that you might abide eternally?"}, {"ayah": 130, "translit": "Wa izaa batashtum batashtum jabbaareen", "translation": "And when you strike, you strike as tyrants."}, {"ayah": 131, "translit": "Fattaqul laaha wa atee'oon", "translation": "So fear Allah and obey me."}, {"ayah": 132, "translit": "Wattaqul lazeee amad dakum bimaa ta'lamoon", "translation": "And fear He who provided you with that which you know,"}, {"ayah": 133, "translit": "Amaddakum bi an'aa minw wa baneen", "translation": "Provided you with grazing livestock and children"}, {"ayah": 134, "translit": "Wa jannaatinw wa 'uyoon", "translation": "And gardens and springs."}, {"ayah": 135, "translit": "Innee akhaafu 'alaikum 'azaaba Yawmin 'azeem", "translation": "Indeed, I fear for you the punishment of a terrible day.\""}, {"ayah": 136, "translit": "Qaaloo sawaaa'un 'alainaaa awa 'azta am lam takum minal waa'izeen", "translation": "They said, \"It is all the same to us whether you advise or are not of the advisors."}, {"ayah": 137, "translit": "In haazaaa illaa khuluqul awwaleen", "translation": "This is not but the custom of the former peoples,"}, {"ayah": 138, "translit": "Wa maa nahnu bimu 'azzabeen", "translation": "And we are not to be punished.\""}, {"ayah": 139, "translit": "Fakazzaboohu fa ahlaknaahum; inna fee zaalika la aayah; wa maa kaana aksaruhum mu'mineen", "translation": "And they denied him, so We destroyed them. Indeed in that is a sign, but most of them were not to be believers."}, {"ayah": 140, "translit": "Wa inna Rabbaka la huwal 'Azeezur Raheem", "translation": "And indeed, your Lord - He is the Exalted in Might, the Merciful."}, {"ayah": 141, "translit": "Kazzabat Samoodul mursaleen", "translation": "Thamud denied the messengers"}, {"ayah": 142, "translit": "Iz qaala lahum akhoohum Saalihun alaa tattaqoon", "translation": "When their brother Salih said to them, \"Will you not fear Allah?"}, {"ayah": 143, "translit": "Innee lakum Rasoolun ameen", "translation": "Indeed, I am to you a trustworthy messenger."}, {"ayah": 144, "translit": "Fattaqul laaha wa atee'oon", "translation": "So fear Allah and obey me."}, {"ayah": 145, "translit": "Wa maaa as'alukum 'alaihi  min ajrin in ajriya illaa 'alaa Rabbil 'aalameen", "translation": "And I do not ask you for it any payment. My payment is only from the Lord of the worlds."}, {"ayah": 146, "translit": "Atutrakoona fee maa haahunnaaa aamineen", "translation": "Will you be left in what is here, secure [from death],"}, {"ayah": 147, "translit": "Fee jannaatinw wa 'uyoon", "translation": "Within gardens and springs"}, {"ayah": 148, "translit": "Wa zuroo inw wa nakhlin tal 'uhaa hadeem", "translation": "And fields of crops and palm trees with softened fruit?"}, {"ayah": 149, "translit": "Wa tanhitoona minal jibaali buyootan faariheen", "translation": "And you carve out of the mountains, homes, with skill."}, {"ayah": 150, "translit": "Fattaqul laaha wa atee'oon", "translation": "So fear Allah and obey me."}, {"ayah": 151, "translit": "Wa laa tutee'ooo amral musrifeen", "translation": "And do not obey the order of the transgressors,"}, {"ayah": 152, "translit": "Allazeena yufsidoona fil ardi wa laa yuslihoon", "translation": "Who cause corruption in the land and do not amend.\""}, {"ayah": 153, "translit": "Qaalooo innamaa anta minal musahhareen", "translation": "They said, \"You are only of those affected by magic."}, {"ayah": 154, "translit": "Maaa anta illaa basharum mislunaa faati bi Aayatin in kunta minas saadiqeen", "translation": "You are but a man like ourselves, so bring a sign, if you should be of the truthful.\""}, {"ayah": 155, "translit": "Qaala haazihee naaqatul lahaa shirbunw w alakum shirbu yawmim ma'loom", "translation": "He said, \"This is a she-camel. For her is a [time of] drink, and for you is a [time of] drink, [each] on a known day."}, {"ayah": 156, "translit": "Wa laa tamassoohaa bisooo'in fa yaakhuzakum 'azaabu Yawmin 'Azeem", "translation": "And do not touch her with harm, lest you be seized by the punishment of a terrible day.\""}, {"ayah": 157, "translit": "Fa'aqaroohaa fa asbahoo naadimeen", "translation": "But they hamstrung her and so became regretful."}, {"ayah": 158, "translit": "Fa akhazahumul 'azaab; inna fee zaalika la Aayah; wa maa kaana aksaruhum m'mineen", "translation": "And the punishment seized them. Indeed in that is a sign, but most of them were not to be believers."}, {"ayah": 159, "translit": "Wa inna Rabbaka la Huwal 'Azeezur Raheem", "translation": "And indeed, your Lord - He is the Exalted in Might, the Merciful."}, {"ayah": 160, "translit": "kazzabat qawmu Lootinil mursaleen", "translation": "The people of Lot denied the messengers"}, {"ayah": 161, "translit": "Iz qaala lahum akhoohum Lootun alaa tattaqoon", "translation": "When their brother Lot said to them, \"Will you not fear Allah?"}, {"ayah": 162, "translit": "Innee lakum rasoolun ameen", "translation": "Indeed, I am to you a trustworthy messenger."}, {"ayah": 163, "translit": "Fattaqul laaha wa atee'oon", "translation": "So fear Allah and obey me."}, {"ayah": 164, "translit": "Wa maaa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen", "translation": "And I do not ask you for it any payment. My payment is only from the Lord of the worlds."}, {"ayah": 165, "translit": "Ataatoonaz zukraana minal 'aalameen", "translation": "Do you approach males among the worlds"}, {"ayah": 166, "translit": "Wa tazaroona maa khalaqa lakum Rabbukum min azwaajikum; bal antum qawmun 'aadoon", "translation": "And leave what your Lord has created for you as mates? But you are a people transgressing.\""}, {"ayah": 167, "translit": "Qaloo la'il lam tantahi yaa Lootu latakoonanna minal mukhrajeen", "translation": "They said, \"If you do not desist, O Lot, you will surely be of those evicted.\""}, {"ayah": 168, "translit": "Qaala innee li'amalikum minal qaaleen", "translation": "He said, \"Indeed, I am, toward your deed, of those who detest [it]."}, {"ayah": 169, "translit": "Rabbi najjjinee wa ahlee mimmmaa ya'maloon", "translation": "My Lord, save me and my family from [the consequence of] what they do.\""}, {"ayah": 170, "translit": "Fanajjainaahu wa ahlahooo ajma'een", "translation": "So We saved him and his family, all,"}, {"ayah": 171, "translit": "Illaa 'ajoozan filghaabireen", "translation": "Except an old woman among those who remained behind."}, {"ayah": 172, "translit": "Summa dammarnal aa khareen", "translation": "Then We destroyed the others."}, {"ayah": 173, "translit": "Wa amtarnaa 'alaihim mataran fasaaa'a matarul munzareen", "translation": "And We rained upon them a rain [of stones], and evil was the rain of those who were warned."}, {"ayah": 174, "translit": "Inna fee zaalika la Aayah; wa maa kaana aksaruhum mu'mineen", "translation": "Indeed in that is a sign, but most of them were not to be believers."}, {"ayah": 175, "translit": "Wa inna Rabbaka la Huwal 'Azeezur Raheem", "translation": "And indeed, your Lord - He is the Exalted in Might, the Merciful."}, {"ayah": 176, "translit": "Kazzaba As haabul Aykatil mursaleen", "translation": "The companions of the thicket denied the messengers"}, {"ayah": 177, "translit": "Iz qaala lahum Shu'aybun alaa tattaqoon", "translation": "When Shu'ayb said to them, \"Will you not fear Allah?"}, {"ayah": 178, "translit": "Innee lakum Rasoolun ameen", "translation": "Indeed, I am to you a trustworthy messenger."}, {"ayah": 179, "translit": "Fattaqul laaha wa atee'oon", "translation": "So fear Allah and obey me."}, {"ayah": 180, "translit": "Wa maaa as'alukum 'alaihi min ajrin in ajriya illaa 'alaa Rabbil 'aalameen", "translation": "And I do not ask you for it any payment. My payment is only from the Lord of the worlds."}, {"ayah": 181, "translit": "Awful kaila wa laa takoonoo minal mukhsireen", "translation": "Give full measure and do not be of those who cause loss."}, {"ayah": 182, "translit": "Wa zinoo bilqistaasil mustaqeem", "translation": "And weigh with an even balance."}, {"ayah": 183, "translit": "Wa laa tabkhasun naasa ashyaaa 'ahum wa laa ta'saw fil ardi mufsideen", "translation": "And do not deprive people of their due and do not commit abuse on earth, spreading corruption."}, {"ayah": 184, "translit": "Wattaqul lazee khalaqakum waljibillatal awwaleen", "translation": "And fear He who created you and the former creation.\""}, {"ayah": 185, "translit": "Qaalooo innamaa anta minal musahhareen", "translation": "They said, \"You are only of those affected by magic."}, {"ayah": 186, "translit": "Wa maaa anta illaa basharum mislunaa wa innazunnuka laminal kaazibeen", "translation": "You are but a man like ourselves, and indeed, we think you are among the liars."}, {"ayah": 187, "translit": "Fa asqit 'alainaa kisafam minas samaaa'i in kunta minas saadiqeen", "translation": "So cause to fall upon us fragments of the sky, if you should be of the truthful.\""}, {"ayah": 188, "translit": "Qaala Rabbeee a'lamu bimaa ta'maloon", "translation": "He said, \"My Lord is most knowing of what you do.\""}, {"ayah": 189, "translit": "Fakazzaboohu fa akhazahum 'azaabu Yawmiz zullah; innahoo kaana 'azaaba Yawmin 'Azeem", "translation": "And they denied him, so the punishment of the day of the black cloud seized them. Indeed, it was the punishment of a terrible day."}, {"ayah": 190, "translit": "Inna fee zaalika la Aayah; wa maa kaana aksaruhum mu'mineen", "translation": "Indeed in that is a sign, but most of them were not to be believers."}, {"ayah": 191, "translit": "Wa inna Rabbaka la huwal 'Azeezur Raheem", "translation": "And indeed, your Lord - He is the Exalted in Might, the Merciful."}, {"ayah": 192, "translit": "Wa innahoo latanzeelu Rabbil 'aalameen", "translation": "And indeed, the Qur'an is the revelation of the Lord of the worlds."}, {"ayah": 193, "translit": "Nazala bihir Roohul Ameen", "translation": "The Trustworthy Spirit has brought it down"}, {"ayah": 194, "translit": "'Alaa qalbika litakoona minal munzireen", "translation": "Upon your heart, [O Muhammad] - that you may be of the warners -"}, {"ayah": 195, "translit": "Bilisaanin 'Arabiyyim mubeen", "translation": "In a clear Arabic language."}, {"ayah": 196, "translit": "Wa innahoo lafee Zuburil awwaleen", "translation": "And indeed, it is [mentioned] in the scriptures of former peoples."}, {"ayah": 197, "translit": "Awalam yakul lahum Aayatan ai ya'lamahoo 'ulamaaa'u Baneee Israaa'eel", "translation": "And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?"}, {"ayah": 198, "translit": "Wa law nazzalnaahu 'alaa ba'dil a'jameen", "translation": "And even if We had revealed it to one among the foreigners"}, {"ayah": 199, "translit": "Faqara ahoo 'alaihim maa kaanoo bihee mu'mineen", "translation": "And he had recited it to them [perfectly], they would [still] not have been believers in it."}, {"ayah": 200, "translit": "Kazaalika salaknaahu fee quloobil mujrimeen", "translation": "Thus have We inserted disbelief into the hearts of the criminals."}, {"ayah": 201, "translit": "Laa yu'minoona bihee hattaa yarawul 'azaabal aleem", "translation": "They will not believe in it until they see the painful punishment."}, {"ayah": 202, "translit": "Fayaatiyahum baghtatanw wa hum laa yash'uroon", "translation": "And it will come to them suddenly while they perceive [it] not."}, {"ayah": 203, "translit": "Fa yaqooloo hal nahnu munzaroon", "translation": "And they will say, \"May we be reprieved?\""}, {"ayah": 204, "translit": "Aafabi 'azaabinaa yasta'jiloon", "translation": "So for Our punishment are they impatient?"}, {"ayah": 205, "translit": "Aara'aita im matta'naahum sineen", "translation": "Then have you considered if We gave them enjoyment for years"}, {"ayah": 206, "translit": "Summa jaaa'ahum maa kaanoo yoo'adoon", "translation": "And then there came to them that which they were promised?"}, {"ayah": 207, "translit": "Maaa aghnaaa 'anhum maa kaanoo yumaatoo'oon", "translation": "They would not be availed by the enjoyment with which they were provided."}, {"ayah": 208, "translit": "Wa maaa ahlaknaa min qaryatin illaa lahaa munziroon", "translation": "And We did not destroy any city except that it had warners"}, {"ayah": 209, "translit": "Zikraa wa maa kunnaa zaalimeen", "translation": "As a reminder; and never have We been unjust."}, {"ayah": 210, "translit": "Wa maa tanazzalat bihish Shayaateen", "translation": "And the devils have not brought the revelation down."}, {"ayah": 211, "translit": "Wa maa yambaghee lahum wa maa yastatee'oon", "translation": "It is not allowable for them, nor would they be able."}, {"ayah": 212, "translit": "Innahum 'anis sam'i lama'zooloon", "translation": "Indeed they, from [its] hearing, are removed."}, {"ayah": 213, "translit": "Falaa tad'u ma'al laahi ilaahan aakhara fatakoona minal mu'azzabeen", "translation": "So do not invoke with Allah another deity and [thus] be among the punished."}, {"ayah": 214, "translit": "Wa anzir 'asheeratakal aqrabeen", "translation": "And warn, [O Muhammad], your closest kindred."}, {"ayah": 215, "translit": "Wakhfid janaahaka limanit taba 'aka minal mu'mineen", "translation": "And lower your wing to those who follow you of the believers."}, {"ayah": 216, "translit": "Fa in asawka faqul innee bareee'um mimmmaa ta'maloon", "translation": "And if they disobey you, then say, \"Indeed, I am disassociated from what you are doing.\""}, {"ayah": 217, "translit": "Wa tawakkal alal 'Azeezir Raheem", "translation": "And rely upon the Exalted in Might, the Merciful,"}, {"ayah": 218, "translit": "Allazee yaraaka heena taqoom", "translation": "Who sees you when you arise"}, {"ayah": 219, "translit": "Wa taqallubaka fis saajideen", "translation": "And your movement among those who prostrate."}, {"ayah": 220, "translit": "Innahoo Huwas Samee'ul 'Aleem", "translation": "Indeed, He is the Hearing, the Knowing."}, {"ayah": 221, "translit": "Hal unabbi'ukum 'alaa man tanazzalush Shayaateen", "translation": "Shall I inform you upon whom the devils descend?"}, {"ayah": 222, "translit": "Tanazzalu 'alaa kulli affaakin aseem", "translation": "They descend upon every sinful liar."}, {"ayah": 223, "translit": "Yulqoonas sam'a wa aksaruhum aaziboon", "translation": "They pass on what is heard, and most of them are liars."}, {"ayah": 224, "translit": "Washshu 'araaa'u yattabi 'uhumul ghaawoon", "translation": "And the poets - [only] the deviators follow them;"}, {"ayah": 225, "translit": "Alam tara annahum fee kulli waadiny yaheemoon", "translation": "Do you not see that in every valley they roam"}, {"ayah": 226, "translit": "Wa annahum yaqooloona ma laa yaf'aloon", "translation": "And that they say what they do not do? -"}, {"ayah": 227, "translit": "Illal lazeena aamanoo w a'amilus saalihaati wa zakarul laaha kaseeranw wantasaroo mim ba'di maa zulimoo; wa saya'lamul lazeena zalamooo aiya munqalbiny yanqaliboon", "translation": "Except those [poets] who believe and do righteous deeds and remember Allah often and defend [the Muslims] after they were wronged. And those who have wronged are going to know to what [kind of] return they will be returned."}]}, {"num": 27, "name": "An-Naml", "meaning": "The Ant", "verses": [{"ayah": 1, "translit": "Taa-Seeen; tilka Aayaatul Qur-aani wa Kitaabim Mubeen", "translation": "Ta, Seen. These are the verses of the Qur'an and a clear Book"}, {"ayah": 2, "translit": "Hudanw wa bushraa lil mu'mineen", "translation": "As guidance and good tidings for the believers"}, {"ayah": 3, "translit": "Allazeena yuqeemoonas Salaata wa yu'toonaz Zakaata wa hum bil Aakhirati hum yooqinoon", "translation": "Who establish prayer and give zakah, and of the Hereafter they are certain [in faith]."}, {"ayah": 4, "translit": "Innal lazeena laa yu'mimoona bil Aakhirati zaiyannaa lahum a'maalahum fahum ya'mahoon", "translation": "Indeed, for those who do not believe in the Hereafter, We have made pleasing to them their deeds, so they wander blindly."}, {"ayah": 5, "translit": "Ulaaa'ikal lazeena lahum sooo'ul 'azaabi wa hum fil Aakhirati humul akhsaroon", "translation": "Those are the ones for whom there will be the worst of punishment, and in the Hereafter they are the greatest losers."}, {"ayah": 6, "translit": "Wa innaka latulaqqal Qur-aana mil ladun Hakeemin 'Aleem", "translation": "And indeed, [O Muhammad], you receive the Qur'an from one Wise and Knowing."}, {"ayah": 7, "translit": "Iz qaala Moosaa li ahliheee inneee aanastu naaran saaateekum minhaa bikhabarin aw aateekum bishihaabin qabasil la'allakum tastaloon", "translation": "[Mention] when Moses said to his family, \"Indeed, I have perceived a fire. I will bring you from there information or will bring you a burning torch that you may warm yourselves.\""}, {"ayah": 8, "translit": "Falammaa jaaa'ahaa noodiya am boorika man finnnnaari wa man hawlahaa wa Subhaanal laahi Rabbil 'aalameen", "translation": "But when he came to it, he was called, \"Blessed is whoever is at the fire and whoever is around it. And exalted is Allah, Lord of the worlds."}, {"ayah": 9, "translit": "Yaa Moosaaa innahooo Anal laahul 'Azeezul Hakeem", "translation": "O Moses, indeed it is I - Allah, the Exalted in Might, the Wise.\""}, {"ayah": 10, "translit": "Wa alqi 'asaak; falammmaa ra aahaa tahtazzu ka annahaa jaaannunw wallaa mudbiranw wa lam yu'aqqib; yaa Moosaa laa takhaf innee laa yakhaafu ladaiyal mursaloon", "translation": "And [he was told], \"Throw down your staff.\" But when he saw it writhing as if it were a snake, he turned in flight and did not return. [Allah said], \"O Moses, fear not. Indeed, in My presence the messengers do not fear."}, {"ayah": 11, "translit": "Illaa man zalama summa baddala husnam ba'da sooo'in fa innee Ghafoorur Raheem", "translation": "Otherwise, he who wrongs, then substitutes good after evil - indeed, I am Forgiving and Merciful."}, {"ayah": 12, "translit": "Wa adkhil yadaka fee jaibika takhruj baidaaa'a min ghairisooo'in feetis'i Aayaatin ilaa Fir'awna wa qawmih; innahum kaanoo qawman faasiqeen", "translation": "And put your hand into the opening of your garment [at the breast]; it will come out white without disease. [These are] among the nine signs [you will take] to Pharaoh and his people. Indeed, they have been a people defiantly disobedient.\""}, {"ayah": 13, "translit": "Falammaa jaaa'at hum Aayaatunaa mubsiratan qaaloo haazaa sihrum mubeen", "translation": "But when there came to them Our visible signs, they said, \"This is obvious magic.\""}, {"ayah": 14, "translit": "Wa jahadoo bihaa wastaiqanat haaa anfusuhum zulmanw-wa 'uluwwaa; fanzur kaifa kaana 'aaqibatul mufsideen", "translation": "And they rejected them, while their [inner] selves were convinced thereof, out of injustice and haughtiness. So see how was the end of the corrupters."}, {"ayah": 15, "translit": "Wa laqad aatainaa Daawooda wa sulaimaana 'ilmaa; wa qaalal hamdu lil laahil lazee faddalanaa 'alaa kaseerim min 'ibaadihil mu'mineen", "translation": "And We had certainly given to David and Solomon knowledge, and they said, \"Praise [is due] to Allah, who has favored us over many of His believing servants.\""}, {"ayah": 16, "translit": "Wa warisa Sulaimaanu Daawooda wa qaala yaaa aiyuhan naasu 'ullimnaa mantiqat tairi wa ooteenaa min kulli shai'in inna haazaa lahuwal fadlul mubeen", "translation": "And Solomon inherited David. He said, \"O people, we have been taught the language of birds, and we have been given from all things. Indeed, this is evident bounty.\""}, {"ayah": 17, "translit": "Wa hushira Sulaimaana junooduhoo minal jinni wal insi wattairi fahum yooza'oon", "translation": "And gathered for Solomon were his soldiers of the jinn and men and birds, and they were [marching] in rows."}, {"ayah": 18, "translit": "hattaaa izaaa ataw 'alaa waadin namli qaalat namlatuny yaaa aiyuhan namlud khuloo masaakinakum laa yahtimannakum Sulaimaanu wa junooduhoo wa hum laa yash'uroon", "translation": "Until, when they came upon the valley of the ants, an ant said, \"O ants, enter your dwellings that you not be crushed by Solomon and his soldiers while they perceive not.\""}, {"ayah": 19, "translit": "Fatabassama daahikam min qawlihaa wa qaala Rabbi awzi'nee an ashkura ni'mata kal lateee an'amta 'alaiya wa 'alaa waalidaiya wa an a'mala saalihan tardaahu wa adkhilnee birahmatika fee 'ibaadikas saaliheen", "translation": "So [Solomon] smiled, amused at her speech, and said, \"My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants.\""}, {"ayah": 20, "translit": "Wa tafaqqadat taira faqaala maa liya laaa aral hud hud, am kaana minal ghaaa'ibeen", "translation": "And he took attendance of the birds and said, \"Why do I not see the hoopoe - or is he among the absent?"}, {"ayah": 21, "translit": "La-u'azzibanahoo 'azaaban shadeedan aw la azbahannahoo aw layaatiyannee bisultaanim mubeen", "translation": "I will surely punish him with a severe punishment or slaughter him unless he brings me clear authorization.\""}, {"ayah": 22, "translit": "Famakasa ghaira ba'eedin faqaala ahattu bimaa lam tuhit bihee wa ji'tuka min Sabaim binaba iny-yaqeen", "translation": "But the hoopoe stayed not long and said, \"I have encompassed [in knowledge] that which you have not encompassed, and I have come to you from Sheba with certain news."}, {"ayah": 23, "translit": "Innee wajattum ra atan tamlikuhum wa ootiyat min kulli shai'inw wa lahaa 'arshun 'azeem", "translation": "Indeed, I found [there] a woman ruling them, and she has been given of all things, and she has a great throne."}, {"ayah": 24, "translit": "Wajattuhaa wa qawmahaa yasjudoona lishshamsi min doonil laahi wa zaiyana lahumush Shaitaanu a'maalahum fasaddahum 'anis sabeeli fahum laa yahtadoon", "translation": "I found her and her people prostrating to the sun instead of Allah, and Satan has made their deeds pleasing to them and averted them from [His] way, so they are not guided,"}, {"ayah": 25, "translit": "Allaa yasjudoo lillaahil lazee yukhrijul khab'a fis samaawaati wal ardi wa ya'lamu maa tukhfoona wa maa tu'linoon", "translation": "[And] so they do not prostrate to Allah, who brings forth what is hidden within the heavens and the earth and knows what you conceal and what you declare -"}, {"ayah": 26, "translit": "Allaahu laaa ilaaha illaa Huwa Rabbul 'Arshil Azeem", "translation": "Allah - there is no deity except Him, Lord of the Great Throne.\""}, {"ayah": 27, "translit": "Qaala sananzuru asadaqta am kunta minal kaazibeen", "translation": "[Solomon] said, \"We will see whether you were truthful or were of the liars."}, {"ayah": 28, "translit": "Izhab bikitaabee haaza fa alqih ilaihim summma tawalla 'anhum fanzur maazaa yarji'oon", "translation": "Take this letter of mine and deliver it to them. Then leave them and see what [answer] they will return.\""}, {"ayah": 29, "translit": "Qaalat yaaa aiyuhal mala'u innee ulqiya ilaiya kitaabun kareem", "translation": "She said, \"O eminent ones, indeed, to me has been delivered a noble letter."}, {"ayah": 30, "translit": "Innahoo min Sulaimaana wa innahoo bismil laahir Rahmaanir Raheem", "translation": "Indeed, it is from Solomon, and indeed, it reads: 'In the name of Allah, the Entirely Merciful, the Especially Merciful,"}, {"ayah": 31, "translit": "Allaa ta'loo 'alaiya waa toonee muslimeen", "translation": "Be not haughty with me but come to me in submission [as Muslims].' \""}, {"ayah": 32, "translit": "Qaalat yaaa aiyuhal mala'u aftoonee fee amree maa kuntu qaati'atan amran hattaa tashhhaddon", "translation": "She said, \"O eminent ones, advise me in my affair. I would not decide a matter until you witness [for] me.\""}, {"ayah": 33, "translit": "Qaaloo nahnu uloo quwwatinw wa uloo baasin shadeed; wal amru ilaiki fanzuree maazaa taamureen", "translation": "They said, \"We are men of strength and of great military might, but the command is yours, so see what you will command.\""}, {"ayah": 34, "translit": "Qaalat innal mulooka izaa dakhaloo qaryatan afsadoohaa wa ja'alooo a'izzata ahlihaaa azillah; wa kazaalika yaf'aloon", "translation": "She said, \"Indeed kings - when they enter a city, they ruin it and render the honored of its people humbled. And thus do they do."}, {"ayah": 35, "translit": "Wa innee mursilatun ilaihim bihadiyyatin fanaaziratum bima yarji'ul mursaloon", "translation": "But indeed, I will send to them a gift and see with what [reply] the messengers will return.\""}, {"ayah": 36, "translit": "Falammaa jaaa'a Sulaimaana qaala atumiddoonani bimaalin famaaa aataakum bal antum bihadiy yatikum tafrahoon", "translation": "So when they came to Solomon, he said, \"Do you provide me with wealth? But what Allah has given me is better than what He has given you. Rather, it is you who rejoice in your gift."}, {"ayah": 37, "translit": "Irji' ilaihim falanaatiyan nahum bijunoodil laa qibala lahum bihaa wa lanukhri jannahum minhaaa azillatanw wa hum saaghiroon", "translation": "Return to them, for we will surely come to them with soldiers that they will be powerless to encounter, and we will surely expel them therefrom in humiliation, and they will be debased.\""}, {"ayah": 38, "translit": "Qaala yaaa aiyuhal mala'u aiyukum yaateenee bi'arshihaa qabla ai yaatoonee muslimeen", "translation": "[Solomon] said, \"O assembly [of jinn], which of you will bring me her throne before they come to me in submission?\""}, {"ayah": 39, "translit": "Qaala 'ifreetum minal jinni ana aateeka bihee qabla an taqooma mim maqaamika wa innee 'alaihi laqawiyyun ameen", "translation": "A powerful one from among the jinn said, \"I will bring it to you before you rise from your place, and indeed, I am for this [task] strong and trustworthy.\""}, {"ayah": 40, "translit": "Qaalal lazee indahoo 'ilmum minal Kitaabi ana aateeka bihee qabla ai yartadda ilaika tarfuk; falammaa ra aahu mustaqirran 'indahoo qaala haazaa min fadli Rabbee li yabluwaneee 'a-ashkuru am akfuru wa man shakara fa innamaa yashkuru linafsihee wa man kafara fa inna Rabbee Ghaniyyun Kareem", "translation": "Said one who had knowledge from the Scripture, \"I will bring it to you before your glance returns to you.\" And when [Solomon] saw it placed before him, he said, \"This is from the favor of my Lord to test me whether I will be grateful or ungrateful. And whoever is grateful - his gratitude is only for [the benefit of] himself. And whoever is ungrateful - then indeed, my Lord is Free of need and Generous.\""}, {"ayah": 41, "translit": "Qaala nakkiroo lahaa 'arshahaa nanzur atahtadeee am takoonu minal lazeena laa yahtadoon", "translation": "He said, \"Disguise for her her throne; we will see whether she will be guided [to truth] or will be of those who is not guided.\""}, {"ayah": 42, "translit": "Falammaa jaaa'at qeela ahaakaza 'arshuki qaalat kaanna hoo; wa ooteenal 'ilma min qablihaa wa kunnaa muslimeen", "translation": "So when she arrived, it was said [to her], \"Is your throne like this?\" She said, \"[It is] as though it was it.\" [Solomon said], \"And we were given knowledge before her, and we have been Muslims [in submission to Allah]."}, {"ayah": 43, "translit": "Wa saddahaa maa kaanat ta'budu min doonil laahi innahaa kaanat min qawmin kaafireen", "translation": "And that which she was worshipping other than Allah had averted her [from submission to Him]. Indeed, she was from a disbelieving people.\""}, {"ayah": 44, "translit": "Qeela lahad khulis sarha falammaa ra at hu hasibat hu lujjatanw wa khashafat 'an saaqaihaa; qaala innahoo sarhum mumarradum min qawaareer; qaalat Rabbi innee zalamtu nafsee wa aslamtu ma'a Sulaimaana lillaahi Rabbil 'aalameen", "translation": "She was told, \"Enter the palace.\" But when she saw it, she thought it was a body of water and uncovered her shins [to wade through]. He said, \"Indeed, it is a palace [whose floor is] made smooth with glass.\" She said, \"My Lord, indeed I have wronged myself, and I submit with Solomon to Allah, Lord of the worlds.\""}, {"ayah": 45, "translit": "Wa laqad arsalnaaa ilaa Samoda akhaahum Saalihan ani'budul lahha fa izaa hum fareeqaani yakhtasimoon", "translation": "And We had certainly sent to Thamud their brother Salih, [saying], \"Worship Allah,\" and at once they were two parties conflicting."}, {"ayah": 46, "translit": "Qaala yaa qawmi lima tasta'jiloona bissaiyi'ati qablal hasanati law laa tas taghfiroonal laaha la'allakum turhamoon", "translation": "He said, \"O my people, why are you impatient for evil instead of good? Why do you not seek forgiveness of Allah that you may receive mercy?\""}, {"ayah": 47, "translit": "Qaalut taiyarnaa bika wa bimam ma'ak; qaala taaa'irukum 'indal laahi bal antum qawmun tuftanoon", "translation": "They said, \"We consider you a bad omen, you and those with you.\" He said, \"Your omen is with Allah. Rather, you are a people being tested.\""}, {"ayah": 48, "translit": "Wa kaana fil madeenati tis'atu rahtiny yufsidoona fil ardi wa laa yuslihoon", "translation": "And there were in the city nine family heads causing corruption in the land and not amending [its affairs]."}, {"ayah": 49, "translit": "Qaaloo taqaasamoo billaahi lanubaiyitannahoo wa ahlahoo summaa lanaqoolana liwaliy yihee maa shahidnaa mahlika ahliee wa innaa lasaadiqoon", "translation": "They said, \"Take a mutual oath by Allah that we will kill him by night, he and his family. Then we will say to his executor, 'We did not witness the destruction of his family, and indeed, we are truthful.' \""}, {"ayah": 50, "translit": "Wa makaroo makranw wa makarnaa makranw wa hum laa yash'uroon", "translation": "And they planned a plan, and We planned a plan, while they perceived not."}, {"ayah": 51, "translit": "Fanzur kaifa kaana 'aaqibatu makrihim annaa dammar naahum wa qawmahum ajma'een", "translation": "Then look how was the outcome of their plan - that We destroyed them and their people, all."}, {"ayah": 52, "translit": "Fatilka buyootuhum khaa wiyatam bimaa zalamoo; inna fee zaalika la Aayatal liqaw miny-ya'lamoon", "translation": "So those are their houses, desolate because of the wrong they had done. Indeed in that is a sign for people who know."}, {"ayah": 53, "translit": "Wa anjainal lazeena aamanoo wa kaanoo yattaqoon", "translation": "And We saved those who believed and used to fear Allah."}, {"ayah": 54, "translit": "Wa lootan iz qaala liqawmiheee ataatoonal faa hishata wa antum qawmun tajjhaloon", "translation": "And [mention] Lot, when he said to his people, \"Do you commit immorality while you are seeing?"}, {"ayah": 55, "translit": "A'innakum lataatoonar rijaala shahwatam min doonin nisaaa'; bal antum qawmun tajhaloon", "translation": "Do you indeed approach men with desire instead of women? Rather, you are a people behaving ignorantly.\""}, {"ayah": 56, "translit": "Fammaa kaana jawaaba qawmiheee illaaa an qaalooo akrijoon aalaa Lootim min qaryatikum innahum unaasuny yatatahharoon", "translation": "But the answer of his people was not except that they said, \"Expel the family of Lot from your city. Indeed, they are people who keep themselves pure.\""}, {"ayah": 57, "translit": "Fa anjainaahu wa ahlahooo illam ra atahoo qaddarnaahaa minal ghaabireen", "translation": "So We saved him and his family, except for his wife; We destined her to be of those who remained behind."}, {"ayah": 58, "translit": "Wa amtarnaa 'alaihimm mataran fasaaa'a matarul munzareen", "translation": "And We rained upon them a rain [of stones], and evil was the rain of those who were warned."}, {"ayah": 59, "translit": "Qulil hamdu lillaahi wa salaamun 'alaa 'ibaadihil lazeenas tafaa; aaallaahu khairun ammmaa yushrikoon", "translation": "Say, [O Muhammad], \"Praise be to Allah, and peace upon His servants whom He has chosen. Is Allah better or what they associate with Him?\""}, {"ayah": 60, "translit": "Amman khalaqas samaawaati wal arda wa anzala lakum minas samaaa'i maaa'an fa ambatnaa bihee hadaaa'iqa zaata bahjjah; maa kanna lakum an tumbitoo shajarahaa; 'a-ilaahum ma'al laah; bal hum qawmuny ya'diloon", "translation": "[More precisely], is He [not best] who created the heavens and the earth and sent down for you rain from the sky, causing to grow thereby gardens of joyful beauty which you could not [otherwise] have grown the trees thereof? Is there a deity with Allah? [No], but they are a people who ascribe equals [to Him]."}, {"ayah": 61, "translit": "Ammann ja'alal arda qaraaranw wa ja'ala khilaalahaaa anhaaranw wa ja'ala lahaa rawaasiya wa ja'ala bainal bahraini haajizaa; 'a-ilaahumma'allah; bal aksaruhum la ya'lamoon", "translation": "Is He [not best] who made the earth a stable ground and placed within it rivers and made for it firmly set mountains and placed between the two seas a barrier? Is there a deity with Allah? [No], but most of them do not know."}, {"ayah": 62, "translit": "Ammany-yujeebul mud tarra izaa da'aahu wa yakshifussooo'a wa yaj'alukum khula faaa'al ardi 'a-ilaahum ma'al laahi qaleelam maa tazak karoon", "translation": "Is He [not best] who responds to the desperate one when he calls upon Him and removes evil and makes you inheritors of the earth? Is there a deity with Allah? Little do you remember."}, {"ayah": 63, "translit": "Ammany-yahdeekum fee zulumaatil barri wal bahri wa many yursilu riyaaha bushram baina yadai rahmatih; 'a-ilaahum ma'al laah; Ta'aalal laahu 'ammaa yushrikoon", "translation": "Is He [not best] who guides you through the darknesses of the land and sea and who sends the winds as good tidings before His mercy? Is there a deity with Allah? High is Allah above whatever they associate with Him."}, {"ayah": 64, "translit": "Ammmany-yabda'ul khalqa summa yu'eeduhoo wa many-yarzuqukum minas sammaaa'i wal ard; 'a-ilaahum ma'allah; qul haatoo burhaanakum in kuntum saadiqeen", "translation": "Is He [not best] who begins creation and then repeats it and who provides for you from the heaven and earth? Is there a deity with Allah? Say, \"Produce your proof, if you should be truthful.\""}, {"ayah": 65, "translit": "Qul laa ya'lamu mman fis sammaawaati wal ardil ghaiba illal laah; wa maa yash'uroona aiyaana yub'asoon", "translation": "Say, \"None in the heavens and earth knows the unseen except Allah, and they do not perceive when they will be resurrected.\""}, {"ayah": 66, "translit": "Balid daaraka 'ilmuhum fil Aakhirah; bal hum fee shakkim minhaa bal hum minhaa 'amoon", "translation": "Rather, their knowledge is arrested concerning the Hereafter. Rather, they are in doubt about it. Rather, they are, concerning it, blind."}, {"ayah": 67, "translit": "Wa qaalal lazeena kafarooo 'a-izaa kunnaa turaabanw wa aabaaa'unaaa a'innaa lamukhrajoon", "translation": "And those who disbelieve say, \"When we have become dust as well as our forefathers, will we indeed be brought out [of the graves]?"}, {"ayah": 68, "translit": "Laqad wu'idnaa haazaa nahnu wa aabaaa'unaa min qablu in haazaaa illaaa asaateerul awwaleen", "translation": "We have been promised this, we and our forefathers, before. This is not but legends of the former peoples.\""}, {"ayah": 69, "translit": "Qul seeroo fil ardi fanzuroo kaifa kaana 'aaqibatul mujremeen", "translation": "Say, [O Muhammad], \"Travel through the land and observe how was the end of the criminals.\""}, {"ayah": 70, "translit": "Wa laa tahzan 'alaihim wa laa takun fee daiqim mimmaa yamkuroon", "translation": "And grieve not over them or be in distress from what they conspire."}, {"ayah": 71, "translit": "Wa yaqooloona mataa haazal wa'du in kuntum saadiqeen", "translation": "And they say, \"When is [the fulfillment of] this promise, if you should be truthful?\""}, {"ayah": 72, "translit": "Qul 'asaaa any-yakoona radifa lakum ba'dul lazee tasta'jiloon", "translation": "Say, \"Perhaps it is close behind you - some of that for which you are impatient."}, {"ayah": 73, "translit": "Wa innna Rabbaka lazoo fadlin 'alan naasi wa laakina aksarahum laa yashkuroon", "translation": "And indeed, your Lord is full of bounty for the people, but most of them do not show gratitude.\""}, {"ayah": 74, "translit": "Wa inna Rabbaka la ya'lamu maa tukinnu sudooruhum wa maa yu'linoon", "translation": "And indeed, your Lord knows what their breasts conceal and what they declare."}, {"ayah": 75, "translit": "Wa maa min ghaaa'ibatin fis samaaa'i wal ardi illaa fee kitaabimm mubeen", "translation": "And there is nothing concealed within the heaven and the earth except that it is in a clear Register."}, {"ayah": 76, "translit": "Inna haazal Qur-aana yaqussu 'alaa Baneee israaa'eela aksaral lazee hum feehi yakhtalifoon", "translation": "Indeed, this Qur'an relates to the Children of Israel most of that over which they disagree."}, {"ayah": 77, "translit": "Wa innahoo lahudanw wa rahmatul lilmu'mineen", "translation": "And indeed, it is guidance and mercy for the believers."}, {"ayah": 78, "translit": "Inna Rabbaka yaqdee bainahum bihukmih; wa Huwal 'Azeezul 'Aleem", "translation": "Indeed, your Lord will judge between them by His [wise] judgement. And He is the Exalted in Might, the Knowing."}, {"ayah": 79, "translit": "Fatawakkal 'alal laahi innaka 'alal haqqil mubeen", "translation": "So rely upon Allah; indeed, you are upon the clear truth."}, {"ayah": 80, "translit": "Innaka laa tusmi'ul mawtaa wa laa tusmi'us summad du'aaa izaa wallaw mudbireen", "translation": "Indeed, you will not make the dead hear, nor will you make the deaf hear the call when they have turned their backs retreating."}, {"ayah": 81, "translit": "Wa maaa anta bihaadil 'umyi 'an dalaalatihim in tusmi'u illaa mai yu'minu bi aayaatinaa fahum muslimoon", "translation": "And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [submitting to Allah]."}, {"ayah": 82, "translit": "Wa izaa waqa'al qawhu 'alaihim akhrajnaa lahum daabbatam minal ardi tukal limuhum annan naasa kaanoo bi aayaatinaa laa yooqinoon", "translation": "And when the word befalls them, We will bring forth for them a creature from the earth speaking to them, [saying] that the people were, of Our verses, not certain [in faith]."}, {"ayah": 83, "translit": "Wa Yawma nahshuru min kulli ummmatin fawjam mim many-yukazzibu bi Aayaatinaa fahum yooza'oon", "translation": "And [warn of] the Day when We will gather from every nation a company of those who deny Our signs, and they will be [driven] in rows"}, {"ayah": 84, "translit": "Hattaaa izaa jaaa'oo qaala akazzabtum bi Aayaatee wa lam tuheetoo bihaa 'ilman ammaazaa kuntum ta'maloon", "translation": "Until, when they arrive [at the place of Judgement], He will say, \"Did you deny My signs while you encompassed them not in knowledge, or what [was it that] you were doing?\""}, {"ayah": 85, "translit": "Wa waqa'al qawlu 'alaihim bimaa zalamoo fahum laa yantiqoon", "translation": "And the decree will befall them for the wrong they did, and they will not [be able to] speak."}, {"ayah": 86, "translit": "Alam yaraw annaa ja'alnal laila li yaskunoo feehi wannahaara mubsiraa; inna fee zaalika la Aayaatil liqaw miny-yu'minoon", "translation": "Do they not see that We made the night that they may rest therein and the day giving sight? Indeed in that are signs for a people who believe."}, {"ayah": 87, "translit": "Wa Yawma yunfakhu fis Soori fafazi'a man fis samaawaati wa man fil ardi illaa man shaaa'al laah; wa kullun atawhu daakhireen", "translation": "And [warn of] the Day the Horn will be blown, and whoever is in the heavens and whoever is on the earth will be terrified except whom Allah wills. And all will come to Him humbled."}, {"ayah": 88, "translit": "Wa taral jibaala tahsabuhaa jaamidatanw wa hiya tamurru marras sahaab; sun'al laahil lazeee atqana kulla shai'; innahoo khabeerum bimaa taf'aloon", "translation": "And you see the mountains, thinking them rigid, while they will pass as the passing of clouds. [It is] the work of Allah, who perfected all things. Indeed, He is Acquainted with that which you do."}, {"ayah": 89, "translit": "Man jaaa'a bilhasanati falahoo khairum minhaa wa hum min faza'iny Yawma'izin aaminoon", "translation": "Whoever comes [at Judgement] with a good deed will have better than it, and they, from the terror of that Day, will be safe."}, {"ayah": 90, "translit": "Wa man jaaa'a bissai yi'ati fakubbat wujoohuhum fin Naari hal tujzawna illaa maa kuntum ta'maloon", "translation": "And whoever comes with an evil deed - their faces will be overturned into the Fire, [and it will be said], \"Are you recompensed except for what you used to do?\""}, {"ayah": 91, "translit": "Innamaaa umirtu an a'buda Rabba haazihil baldatil lazee harramahaa wa lahoo kullu shai'inw wa umirtu an akoona minal muslimeen", "translation": "[Say, O Muhammad], \"I have only been commanded to worship the Lord of this city, who made it sacred and to whom [belongs] all things. And I am commanded to be of the Muslims [those who submit to Allah]"}, {"ayah": 92, "translit": "Wa an atluwal Qur-aana famanih tadaa fa innnamaa yahtadee linafsihee wa man dalla faqul innamaaa ana minal munzireen", "translation": "And to recite the Qur'an.\" And whoever is guided is only guided for [the benefit of] himself; and whoever strays - say, \"I am only [one] of the warners.\""}, {"ayah": 93, "translit": "Wa qulil hamdu lillaahi sa yureekum Aayaatihee fata'ri foonahaa; wa maa Rabbuka bighaaflin 'ammaa ta'maloon", "translation": "And say, \"[All] praise is [due] to Allah. He will show you His signs, and you will recognize them. And your Lord is not unaware of what you do.\""}]}, {"num": 28, "name": "Al-Qasas", "meaning": "The Stories", "verses": [{"ayah": 1, "translit": "Taa-Seeen-Meeem", "translation": "Ta, Seen, Meem."}, {"ayah": 2, "translit": "Tilka Aayaatul Kitaabil mubeen", "translation": "These are the verses of the clear Book."}, {"ayah": 3, "translit": "Natloo 'alaika min naba-i Moosaa wa Fi'awna bilhaqqi liqawminy yu'miinoon", "translation": "We recite to you from the news of Moses and Pharaoh in truth for a people who believe."}, {"ayah": 4, "translit": "Inna Fir'awna 'alaa fil ardi wa ja'ala ahlahaa shiya'ai yastad'ifu taaa'ifatam minhum yuzabbihu abnaaa'ahum wa yastahyee nisaaa'ahum; innahoo kaana minal mufsideen", "translation": "Indeed, Pharaoh exalted himself in the land and made its people into factions, oppressing a sector among them, slaughtering their [newborn] sons and keeping their females alive. Indeed, he was of the corrupters."}, {"ayah": 5, "translit": "Wa nureedu an namunna 'alal lazeenas tud'ifoo fil ardi wa naj'alahum a'immatanw wa naj'alahumul waariseen", "translation": "And We wanted to confer favor upon those who were oppressed in the land and make them leaders and make them inheritors"}, {"ayah": 6, "translit": "Wa numakkina lahum fil ardi wa nuriya Fir'awna wa Haamaana wa junoodahumaa minhum maa kaanoo yahzaroon", "translation": "And establish them in the land and show Pharaoh and [his minister] Haman and their soldiers through them that which they had feared."}, {"ayah": 7, "translit": "Wa awhainaaa ilaaa ummi Moosaaa an ardi'eehi faizaa khifti 'alaihi fa alqeehi filyammi wa laa takhaafee wa laa tahzaneee innaa raaaddoohu ilaiki wa jaa'iloohu minal mursaleen", "translation": "And We inspired to the mother of Moses, \"Suckle him; but when you fear for him, cast him into the river and do not fear and do not grieve. Indeed, We will return him to you and will make him [one] of the messengers.\""}, {"ayah": 8, "translit": "Faltaqatahooo Aalu Fir'awna li yakoona lahum 'aduwwanw wa hazanaa; inna Fir'awna wa Haamaana wa junooda humaa kaanoo khaati'een", "translation": "And the family of Pharaoh picked him up [out of the river] so that he would become to them an enemy and a [cause of] grief. Indeed, Pharaoh and Haman and their soldiers were deliberate sinners."}, {"ayah": 9, "translit": "Wa qaalatim ra atu Fir'awna qurratu 'aynil lee wa lak; laa taqtuloohu 'asaaa aiyanfa'anaa aw nattakhizahoo waladanw wa hum laa yash'uroon", "translation": "And the wife of Pharaoh said, \"[He will be] a comfort of the eye for me and for you. Do not kill him; perhaps he may benefit us, or we may adopt him as a son.\" And they perceived not."}, {"ayah": 10, "translit": "Wa asbaha fu'aadu ummi Moosaa faarighan in kaadat latubdee bihee law laaa arrabatnaa 'alaa qalbihaa litakoona minal mu'mineen", "translation": "And the heart of Moses' mother became empty [of all else]. She was about to disclose [the matter concerning] him had We not bound fast her heart that she would be of the believers."}, {"ayah": 11, "translit": "Wa qaalat li ukhtihee qusseehi fabasurat bihee 'an junubinw wahum laa yash'uroon", "translation": "And she said to his sister, \"Follow him\"; so she watched him from a distance while they perceived not."}, {"ayah": 12, "translit": "Wa harramnaa 'alaihil maraadi'a min qablu faqaalat hal adullukum 'alaaa ahli baitiny yakfuloonahoo lakum wa hum lahoo naasihoon", "translation": "And We had prevented from him [all] wet nurses before, so she said, \"Shall I direct you to a household that will be responsible for him for you while they are to him [for his upbringing] sincere?\""}, {"ayah": 13, "translit": "Faradadnaahu ilaa ummihee kai taqarra 'ainuhaa wa laa tahzana wa lita'lama anna wa'dal laahi haqqunw wa laakinna aksarahum laa ya'lamoon", "translation": "So We restored him to his mother that she might be content and not grieve and that she would know that the promise of Allah is true. But most of the people do not know."}, {"ayah": 14, "translit": "Wa lammaa balagha ashuddahoo wastawaaa aatai naahu hukmanw wa 'ilmaa; wa kazaalika najzil muhsineen", "translation": "And when he attained his full strength and was [mentally] mature, We bestowed upon him judgement and knowledge. And thus do We reward the doers of good."}, {"ayah": 15, "translit": "Wa dakhalal madeenata 'alaa heene ghaflatim min ahlihaa fawajada feeha raju laini yaqtatilaani haazaa min shee'atihee wa haaza min 'aduwwihee fastaghaasahul lazee min shee'atihee 'alal lazee min 'aduwwihee fawakazahoo Moosaa faqadaa 'alaihi qaala haaza min 'amalish Shaitaani innahoo 'aduwwum mmudillum mubeen", "translation": "And he entered the city at a time of inattention by its people and found therein two men fighting: one from his faction and one from among his enemy. And the one from his faction called for help to him against the one from his enemy, so Moses struck him and [unintentionally] killed him. [Moses] said, \"This is from the work of Satan. Indeed, he is a manifest, misleading enemy.\""}, {"ayah": 16, "translit": "Qaala Rabbi innee zalamtu nafsee faghfir lee faghafaralah; innahoo Huwal Ghafoorur Raheem", "translation": "He said, \"My Lord, indeed I have wronged myself, so forgive me,\" and He forgave him. Indeed, He is the Forgiving, the Merciful."}, {"ayah": 17, "translit": "Qaala Rabbi bimaaa an'amta 'alaiya falan akoona zaheeral lilmujrimeen", "translation": "He said, \"My Lord, for the favor You bestowed upon me, I will never be an assistant to the criminals.\""}, {"ayah": 18, "translit": "Fa asbaha fil madeenati khaaa'ifany yataraqqabu fa izal lazis tansarahoo bil amsi yastasrikhuh; qaala lahoo moosaaa innaka laghawiyyum mubeen", "translation": "And he became inside the city fearful and anticipating [exposure], when suddenly the one who sought his help the previous day cried out to him [once again]. Moses said to him, \"Indeed, you are an evident, [persistent] deviator.\""}, {"ayah": 19, "translit": "Falammaaa an araada ai yabtisha billazee huwa 'aduwwul lahumaa qaala yaa Moosaaa atureedu an taqtulanee kamaa qatalta nafsam bil amsi in tureedu illaaa an takoona jabbaaram fil ardi wa maa tureedu an takoona minal musliheen", "translation": "And when he wanted to strike the one who was an enemy to both of them, he said, \"O Moses, do you intend to kill me as you killed someone yesterday? You only want to be a tyrant in the land and do not want to be of the amenders.\""}, {"ayah": 20, "translit": "Wa jaaa'a rajulum min aqsal madeenati yas'aa qaala yaa Moosaaa innal mala a yaa tamiroona bika liyaqtulooka fakhruj innee laka minan naasiheen", "translation": "And a man came from the farthest end of the city, running. He said, \"O Moses, indeed the eminent ones are conferring over you [intending] to kill you, so leave [the city]; indeed, I am to you of the sincere advisors.\""}, {"ayah": 21, "translit": "Fakharaja minhaa khaaa 'ifany-yataraqqab; qaala Rabbi najjinee minal qawmiz zaalimeen", "translation": "So he left it, fearful and anticipating [apprehension]. He said, \"My Lord, save me from the wrongdoing people.\""}, {"ayah": 22, "translit": "Wa lammaa tawajjaha tilqaaa'a Madyana qaala 'asaa Rabbeee ai yahdiyanee Sawaaa'as Sabeel", "translation": "And when he directed himself toward Madyan, he said, \"Perhaps my Lord will guide me to the sound way.\""}, {"ayah": 23, "translit": "Wa lammaa warada maaa'a Madyana wajada 'alaihi ummatam minannaasi yasqoona wa wajada min doonihimum ra ataini tazoodaani qaala maa khatubkumaa qaalataa laa nasqee hataa yusdirar ri'aaa'u wa aboonaa shaikhun kabeer", "translation": "And when he came to the well of Madyan, he found there a crowd of people watering [their flocks], and he found aside from them two women driving back [their flocks]. He said, \"What is your circumstance?\" They said, \"We do not water until the shepherds dispatch [their flocks]; and our father is an old man.\""}, {"ayah": 24, "translit": "Fasaqaa lahumaa summa tawallaaa ilaz zilli faqaala Rabbi innee limaaa anzalta ilaiya min khairin faqeer", "translation": "So he watered [their flocks] for them; then he went back to the shade and said, \"My Lord, indeed I am, for whatever good You would send down to me, in need.\""}, {"ayah": 25, "translit": "Fajaaa'at hu ihdaahumaa tamshee 'alas tihyaaa'in qaalat inna abee yad'ooka li yajziyaka ajra maa saqaita lanaa; falammaa jaaa'ahoo wa qassa 'alaihil qasasa qaala laa takhaf najawta minal qawmiz zaalimeen", "translation": "Then one of the two women came to him walking with shyness. She said, \"Indeed, my father invites you that he may reward you for having watered for us.\" So when he came to him and related to him the story, he said, \"Fear not. You have escaped from the wrongdoing people.\""}, {"ayah": 26, "translit": "Qaalat ihdaahumaa yaaa abatis taajirhu inna khaira manistaajartal qawiyyul ameen", "translation": "One of the women said, \"O my father, hire him. Indeed, the best one you can hire is the strong and the trustworthy.\""}, {"ayah": 27, "translit": "Qaala innee ureedu an unkihaka ihdab nataiya haataini 'alaaa an taajuranee samaaniya hijaj; fa in atmamta 'ashran famin 'indika wa maaa ureedu an ashuqqa 'alaik; satajiduneee in shaaa'al laahu minas saaliheen", "translation": "He said, \"Indeed, I wish to wed you one of these, my two daughters, on [the condition] that you serve me for eight years; but if you complete ten, it will be [as a favor] from you. And I do not wish to put you in difficulty. You will find me, if Allah wills, from among the righteous.\""}, {"ayah": 28, "translit": "Qaala zaalika bainee wa bainaka aiyamal ajalaini qadaitu falaa 'udwaana 'alaiya wallaahu 'alaa ma naqoolu Wakeel", "translation": "[Moses] said, \"That is [established] between me and you. Whichever of the two terms I complete - there is no injustice to me, and Allah, over what we say, is Witness.\""}, {"ayah": 29, "translit": "Falammmaa qadaa Moosal ajala wa saara bi ahliheee aanasa min jaanibit Toori naaran qaala li ahlihim kusooo inneee aanastu naaral la 'alleee aateekum minhaa bikhabarin aw jazwatim minan naari la 'allakum tastaloon", "translation": "And when Moses had completed the term and was traveling with his family, he perceived from the direction of the mount a fire. He said to his family, \"Stay here; indeed, I have perceived a fire. Perhaps I will bring you from there [some] information or burning wood from the fire that you may warm yourselves.\""}, {"ayah": 30, "translit": "Falammaaa ataahaa noodiya min shaati'il waadil aimani fil buq'atil muubaarakati minash shajarati ai yaa Moosaaa inneee Anal laahu Rabbul 'aalameen", "translation": "But when he came to it, he was called from the right side of the valley in a blessed spot - from the tree, \"O Moses, indeed I am Allah, Lord of the worlds.\""}, {"ayah": 31, "translit": "Wa an alqi 'asaaka falam maa ra aahaa tahtazzu ka annnahaa jaaannunw wallaa mudbiranw wa lam yu'aqqib; yaa Moosaa aqbil wa laa takhaf innaka minal aamineen", "translation": "And [he was told], \"Throw down your staff.\" But when he saw it writhing as if it was a snake, he turned in flight and did not return. [Allah said], \"O Moses, approach and fear not. Indeed, you are of the secure."}, {"ayah": 32, "translit": "Usluk yadaka fee jaibika takhruj baidaaa'a min ghairi sooo'inw wadmum ilaika janaahaka minar rahbi fazaanika burhaanaani mir Rabbika ilaa Fiw'awna wa mala'ih; innahum kaanoo qawman faasiqeen", "translation": "Insert your hand into the opening of your garment; it will come out white, without disease. And draw in your arm close to you [as prevention] from fear, for those are two proofs from your Lord to Pharaoh and his establishment. Indeed, they have been a people defiantly disobedient.\""}, {"ayah": 33, "translit": "Qaala Rabbi innee qataltu minhum nafsan fa akhaafu ai yaqtuloon", "translation": "He said, \"My Lord, indeed, I killed from among them someone, and I fear they will kill me."}, {"ayah": 34, "translit": "Wa akhee Haaroonu huwa afsahu minnee lisaanan fa arsilhu ma'iya rid ai yusaddiquneee innee akhaafu ai yukazziboon", "translation": "And my brother Aaron is more fluent than me in tongue, so send him with me as support, verifying me. Indeed, I fear that they will deny me.\""}, {"ayah": 35, "translit": "Qaala sanashuddu 'adudaka bi akheeka wa naj'alu lakumaa sultaanan falaa yasiloona ilaikumaa; bi Aayaatinaa antumaa wa manit taba'akumal ghaaliboon", "translation": "[Allah] said, \"We will strengthen your arm through your brother and grant you both supremacy so they will not reach you. [It will be] through Our signs; you and those who follow you will be the predominant.\""}, {"ayah": 36, "translit": "Falammaa jaaa'ahum Moosaa bi Aayaatinaa baiyinaatin qaaloo maa haazaaa illaa sihrum muftaranw wa maa sami'naa bihaazaa feee aabaaa'inal awwaleen", "translation": "But when Moses came to them with Our signs as clear evidences, they said, \"This is not except invented magic, and we have not heard of this [religion] among our forefathers.\""}, {"ayah": 37, "translit": "Wa qaala Moosaa Rabbeee a'alamu biman jaaa'a bilhudaa min 'indihee wa man takoonu lahoo 'aaqibatud daari innahoo laa yuflihuz zaalimoon", "translation": "And Moses said, \"My Lord is more knowing [than we or you] of who has come with guidance from Him and to whom will be succession in the home. Indeed, wrongdoers do not succeed.\""}, {"ayah": 38, "translit": "Wa qaala Fir'awnu yaaa aiyuhal mala-u maa 'alimtu lakum min ilaahin ghairee fa awqid lee yaa Haamaanu 'alatteeni faj'al lee sarhal la'alleee attali'u ilaaa ilaahi Moosaa wa innee la azunnuhoo minal kaazibeen", "translation": "And Pharaoh said, \"O eminent ones, I have not known you to have a god other than me. Then ignite for me, O Haman, [a fire] upon the clay and make for me a tower that I may look at the God of Moses. And indeed, I do think he is among the liars.\""}, {"ayah": 39, "translit": "Wastakbara huwa wa junooduhoo fil ardi bighairil haqqi wa zannooo annahum ilainaa laa yurja'oon", "translation": "And he was arrogant, he and his soldiers, in the land, without right, and they thought that they would not be returned to Us."}, {"ayah": 40, "translit": "Fa akhaznaahu wa junoo dahoo fanabaznaahum fil yammi fanzur kaifa kaana 'aaqibatuz zaalimeen", "translation": "So We took him and his soldiers and threw them into the sea. So see how was the end of the wrongdoers."}, {"ayah": 41, "translit": "Wa ja'alnaahum a'immatany yad'oona ilan Naari wa Yawmal Qiyaamati laa yunsaroon", "translation": "And We made them leaders inviting to the Fire, and on the Day of Resurrection they will not be helped."}, {"ayah": 42, "translit": "Wa atba'naahum fee haazihid dunyaa la'natanw wa Yawmal Qiyaamati hum minal maqbooheen", "translation": "And We caused to overtake them in this world a curse, and on the Day of Resurrection they will be of the despised."}, {"ayah": 43, "translit": "Wa laqad aatainaa Moosal Kitaaba mim ba'di maaa ahlaknal quroonal oolaa basaaa'ira linnaasi wa hudanw wa rahmatal la'allahum yata zakkkaroon", "translation": "And We gave Moses the Scripture, after We had destroyed the former generations, as enlightenment for the people and guidance and mercy that they might be reminded."}, {"ayah": 44, "translit": "Wa maa kunta bijaanibil gharbiyyi iz qadainaaa ilaa Moosal amra wa maa kunta minash shaahideen", "translation": "And you, [O Muhammad], were not on the western side [of the mount] when We revealed to Moses the command, and you were not among the witnesses [to that]."}, {"ayah": 45, "translit": "Wa laakinnaa anshaanaa quroonan fatataawala 'alaihimul 'umur; wa maa kunta saawiyan feee ahli Madyana tatloo 'alaihim Aayaatinaa wa laakinnaa kunnaa mursileen", "translation": "But We produced [many] generations [after Moses], and prolonged was their duration. And you were not a resident among the people of Madyan, reciting to them Our verses, but We were senders [of this message]."}, {"ayah": 46, "translit": "Wa maa kunta bijaanibit Toori iz naadainaa wa laakir rahmatam mir Rabbika litunzira qawmam maaa ataahum min nazeerim min qablika la'allahum yatazakkaroon", "translation": "And you were not at the side of the mount when We called [Moses] but [were sent] as a mercy from your Lord to warn a people to whom no warner had come before you that they might be reminded."}, {"ayah": 47, "translit": "Wa law laaa an tuseebahum museebatum bimaa qaddamat aideehim fa yaqooloo Rabbanaa law laaa arsalta ilainaa Rasoolan fanattabi'a Aayaatika wa nakoona minal mu'mineen", "translation": "And if not that a disaster should strike them for what their hands put forth [of sins] and they would say, \"Our Lord, why did You not send us a messenger so we could have followed Your verses and been among the believers?\"..."}, {"ayah": 48, "translit": "Falammaa jaaa'ahumul haqqu min 'indinaa qaaloo law laa ootiya misla maaa ootiyaa Moosaa; awalam yakfuroo bimaaa ootiya Moosaa min qablu qaaloo sihraani tazaaharaa wa qaalooo innaa bikullin kaafiroon", "translation": "But when the truth came to them from Us, they said, \"Why was he not given like that which was given to Moses?\" Did they not disbelieve in that which was given to Moses before? They said, \"[They are but] two works of magic supporting each other, and indeed we are, in both, disbelievers.\""}, {"ayah": 49, "translit": "Qul faatoo bi Kitaabim min 'indil laahi huwa ahdaa minhu maaa attabi'hu in kuntum saadiqeen", "translation": "Say, \"Then bring a scripture from Allah which is more guiding than either of them that I may follow it, if you should be truthful.\""}, {"ayah": 50, "translit": "Fa il lam yastajeeboo laka fa'lam annamaa yattabi'oona ahwaaa'ahum; w aman adallu mimmanit taba'a hawaahu bighari hudam minal laah; innal laaha laa yahdil qawmaz zaalimeen", "translation": "But if they do not respond to you - then know that they only follow their [own] desires. And who is more astray than one who follows his desire without guidance from Allah? Indeed, Allah does not guide the wrongdoing people."}, {"ayah": 51, "translit": "Wa laqad wassalnaa lahumul qawla la'allahum yatazakkaroon", "translation": "And We have [repeatedly] conveyed to them the Qur'an that they might be reminded."}, {"ayah": 52, "translit": "Allazeena aatainaahu mul Kitaaba min qablihee hum bihee yu'minoon", "translation": "Those to whom We gave the Scripture before it - they are believers in it."}, {"ayah": 53, "translit": "Wa izaa yutlaa 'alaihim qaaloo aamannaa biheee innahul haqqu mir rabbinaaa innaa kunnaa min qablihee muslimeen", "translation": "And when it is recited to them, they say, \"We have believed in it; indeed, it is the truth from our Lord. Indeed we were, [even] before it, Muslims [submitting to Allah].\""}, {"ayah": 54, "translit": "Ulaaa'ika yu'tawna ajrahum marratayni bimaa sabaroo wa yadra'oona bil hasanatis saiyi'ata wa mimmmaa razaq naahum yunfiqoon", "translation": "Those will be given their reward twice for what they patiently endured and [because] they avert evil through good, and from what We have provided them they spend."}, {"ayah": 55, "translit": "Wa izaa sami'ul laghwa a'radoo 'anhu wa qaaloo lanaaa a'maalunaa wa lakum a'maalukum salaamun 'alaikum laa nabtaghil jaahileen", "translation": "And when they hear ill speech, they turn away from it and say, \"For us are our deeds, and for you are your deeds. Peace will be upon you; we seek not the ignorant.\""}, {"ayah": 56, "translit": "Innaka laa tahdee man ahbata wa laakinna laaha yahdee mai yashaaa'; wa Huwaa'lamu bilmuhtadeen", "translation": "Indeed, [O Muhammad], you do not guide whom you like, but Allah guides whom He wills. And He is most knowing of the [rightly] guided."}, {"ayah": 57, "translit": "Wa qaalooo in nattabi'il hudaa ma'aka nutakhattaf min ardinaa; awalam numakkkil lahum haraman aaminany yujbaaa ilaihi samaraatu kulli shai'ir rizqam mil ladunnaa wa laakinna aksarahum laa ya'lamoon", "translation": "And they say, \"If we were to follow the guidance with you, we would be swept from our land.\" Have we not established for them a safe sanctuary to which are brought the fruits of all things as provision from Us? But most of them do not know."}, {"ayah": 58, "translit": "Wa kam ahlaknaa min qaryatim batirat ma'eeshatahaa fatilka masaainuhum lam tuskam mim ba'dihim illaa qaleelaa; wa kunnaa Nahnul waariseen", "translation": "And how many a city have We destroyed that was insolent in its [way of] living, and those are their dwellings which have not been inhabited after them except briefly. And it is We who were the inheritors."}, {"ayah": 59, "translit": "Wa maa kaana Rabbuka muhlikal quraa hattaa yab'asa feee ummihaa Rasoolany yatloo 'alaihim aayaatina; wa maa kunnaa muhlikil quraaa illaa wa ahluhaa zaalimoon", "translation": "And never would your Lord have destroyed the cities until He had sent to their mother a messenger reciting to them Our verses. And We would not destroy the cities except while their people were wrongdoers."}, {"ayah": 60, "translit": "Wa maaa ooteetum min shai'in famataa'ul hayaatid dunyaa wa zeenatuhaa; wa maa 'indal laahi khairunw wa abqaa; afalaa ta'qiloon", "translation": "And whatever thing you [people] have been given - it is [only for] the enjoyment of worldly life and its adornment. And what is with Allah is better and more lasting; so will you not use reason?"}, {"ayah": 61, "translit": "Afamanw wa'adnaahu wa'dan hasanan fahuwa laaqeehi kamam matta'naahu mataa'al hayaatid dunyaa summa huwa Yawmal Qiyaamati minal muhdareen", "translation": "Then is he whom We have promised a good promise which he will obtain like he for whom We provided enjoyment of worldly life [but] then he is, on the Day of Resurrection, among those presented [for punishment in Hell]?"}, {"ayah": 62, "translit": "Wa Yawma yunaadeehim fa-yaqoolu aina shurakaaa 'iyal lazeena kuntum taz'umoon", "translation": "And [warn of] the Day He will call them and say, \"Where are My 'partners' which you used to claim?\""}, {"ayah": 63, "translit": "Qaalal lazeena haqqa 'alaihimul qawlu Rabbanaa haaa'ulaaa'il lazeena aghwainaa aghwainaahu kamaa ghawainaa tabarraanaaa ilaika maa kaanoo iyyaanaa ya'budoon", "translation": "Those upon whom the word will have come into effect will say, \"Our Lord, these are the ones we led to error. We led them to error just as we were in error. We declare our disassociation [from them] to You. They did not used to worship us.\""}, {"ayah": 64, "translit": "Wa qeelad 'oo shurakaaa'akum fada'awhum falam yastajeeboo lahum wa ra awul 'azaab; law annahum kaanoo yahtadoon", "translation": "And it will be said, \"Invoke your 'partners' \" and they will invoke them; but they will not respond to them, and they will see the punishment. If only they had followed guidance!"}, {"ayah": 65, "translit": "Wa Yawma yunaadeehim fa yaqoolu maazaaa ajabtumul mursaleen", "translation": "And [mention] the Day He will call them and say, \"What did you answer the messengers?\""}, {"ayah": 66, "translit": "Fa'amiyat 'alaihimul ambaaa'u Yawma'izin fahum laa yatasaaa'aloon", "translation": "But the information will be unapparent to them that Day, so they will not [be able to] ask one another."}, {"ayah": 67, "translit": "Fa ammaa man taaba wa aamana wa 'amila saalihan fa'asaaa ai yakoona minal mufliheen", "translation": "But as for one who had repented, believed, and done righteousness, it is promised by Allah that he will be among the successful."}, {"ayah": 68, "translit": "Wa Rabbuka yakhuluqu maa yashaaa'u wa yakhtaar; maa kaana lahumul khiyarah; Subhannal laahi wa Ta'aalaa 'ammmaa yushrikoon", "translation": "And your Lord creates what He wills and chooses; not for them was the choice. Exalted is Allah and high above what they associate with Him."}, {"ayah": 69, "translit": "Wa Rabbuka ya'lamu maa tukinnu sudooruhum wa maa yu'linoon", "translation": "And your Lord knows what their breasts conceal and what they declare."}, {"ayah": 70, "translit": "Wa Huwal laahu laaa ilaaha illaa Huwa lahul hamdu fil oolaa wal Aakhirati wa lahul hukmu wa ilaihi turja'oon", "translation": "And He is Allah; there is no deity except Him. To Him is [due all] praise in the first [life] and the Hereafter. And His is the [final] decision, and to Him you will be returned."}, {"ayah": 71, "translit": "Qul ara'aitum in ja'alal laahu 'alaikumul laila sarmadan ilaa Yawmil Qiyaamati man ilaahun ghairul laahi yaa teekum bidiyaaa'in afalaa tasma'oon", "translation": "Say, \"Have you considered: if Allah should make for you the night continuous until the Day of Resurrection, what deity other than Allah could bring you light? Then will you not hear?\""}, {"ayah": 72, "translit": "Qul ara'aitum in ja'alal laahu 'alaikumun nahaara sarmadan ilaa Yawmil Qiyaamati man ilaahun ghairul laahi yaateekum bilailin taskunoona feehi afalaa tubsiroon", "translation": "Say, \"Have you considered: if Allah should make for you the day continuous until the Day of Resurrection, what deity other than Allah could bring you a night in which you may rest? Then will you not see?\""}, {"ayah": 73, "translit": "Wa mir rahmatihee ja'ala lakumul laila wannahaara litaskunoo feehi wa litabtaghoo min fadlihee wa la'allakum tashkuroon", "translation": "And out of His mercy He made for you the night and the day that you may rest therein and [by day] seek from His bounty and [that] perhaps you will be grateful."}, {"ayah": 74, "translit": "Wa Yawma yunaadeehim fa yaqoolu aina shurakaaa'iyal lazeena kuntum tazz'umoon", "translation": "And [warn of] the Day He will call them and say, \"Where are my 'partners' which you used to claim?\""}, {"ayah": 75, "translit": "Wa naza'naa min kulli ummatin shaheedan faqulnaa haatoo burhaanakum fa'alimooo annal haqqa lillaahi wa dalla 'anhum maa kaanoo yaftaroon", "translation": "And We will extract from every nation a witness and say, \"Produce your proof,\" and they will know that the truth belongs to Allah, and lost from them is that which they used to invent."}, {"ayah": 76, "translit": "Inna Qaaroona kaana min qawmi Moosaa fabaghaaa 'alaihim wa aatainaahu minal kunoozi maaa inna mafaati hahoo latanooo'u bil'usbati ulil quwwati iz qaala lahoo qawmuhoo laa tafrah innal laahaa laa yuhibbul fariheen", "translation": "Indeed, Qarun was from the people of Moses, but he tyrannized them. And We gave him of treasures whose keys would burden a band of strong men; thereupon his people said to him, \"Do not exult. Indeed, Allah does not like the exultant."}, {"ayah": 77, "translit": "Wabtaghi feemaaa aataakal laahud Daaral Aakhirata wa laa tansa naseebaka minad dunyaa wa ahsin kamaaa ahsanal laahu ilaika wa laa tabghil fasaada fil ardi innal laaha laa yuhibbul mufsideen", "translation": "But seek, through that which Allah has given you, the home of the Hereafter; and [yet], do not forget your share of the world. And do good as Allah has done good to you. And desire not corruption in the land. Indeed, Allah does not like corrupters.\""}, {"ayah": 78, "translit": "Qaala innamaaa ootee tuhoo 'alaa 'ilmin 'indeee; awalam ya'lam annal laaha qad ahlaka min qablihee minal qurooni man huwa ashaddu minhu quwwatanw wa aksaru jam'aa; wa laa yus'alu 'an zunoobihimul mujrimoon", "translation": "He said, \"I was only given it because of knowledge I have.\" Did he not know that Allah had destroyed before him of generations those who were greater than him in power and greater in accumulation [of wealth]? But the criminals, about their sins, will not be asked."}, {"ayah": 79, "translit": "Fakharaja 'alaa qawmihee fee zeenatih; qaalal lazeena yureedoonal hayaatad dunyaa yaalaita lanaa misla maaa ootiya Qaaroonu innahoo lazoo hazzin 'azeem", "translation": "So he came out before his people in his adornment. Those who desired the worldly life said, \"Oh, would that we had like what was given to Qarun. Indeed, he is one of great fortune.\""}, {"ayah": 80, "translit": "Wa qaalal lazeena ootul 'ilma wailakum sawaabul laahi khairul liman aamana wa 'amila saalihaa; wa laa yulaq qaahaaa illas saabiroon", "translation": "But those who had been given knowledge said, \"Woe to you! The reward of Allah is better for he who believes and does righteousness. And none are granted it except the patient.\""}, {"ayah": 81, "translit": "Fakhasafnaa bihee wa bidaarihil arda famaa kaana laho min fi'atiny yansuroo nahoo min doonil laahi wa maa kaana minal muntasireen", "translation": "And We caused the earth to swallow him and his home. And there was for him no company to aid him other than Allah, nor was he of those who [could] defend themselves."}, {"ayah": 82, "translit": "Wa asbahal lazeena tamannaw makaanahoo bil amsi yaqooloona waika annal laaha yabsutur rizqa limany ya shaaa'u min 'ibaadihee wa yaqdiru law laaa am mannal laahu 'alainaa lakhasafa binaa waika annahoo laa yuflihul kaafiroon", "translation": "And those who had wished for his position the previous day began to say, \"Oh, how Allah extends provision to whom He wills of His servants and restricts it! If not that Allah had conferred favor on us, He would have caused it to swallow us. Oh, how the disbelievers do not succeed!\""}, {"ayah": 83, "translit": "Tilkad Daarul Aakhiratu naj'aluhaa lillazeena laa yureedoona 'uluwwan fil ardi wa laa fasaadaa; wal 'aaqibatu lilmuttaqeen", "translation": "That home of the Hereafter We assign to those who do not desire exaltedness upon the earth or corruption. And the [best] outcome is for the righteous."}, {"ayah": 84, "translit": "Man jaaa'a bilhasanati falahoo khairum minhaa wa man jaaa'a bissaiyi'ati falaa yujzal lazeena 'amilus saiyiaati illaa maa kaanoo ya'maloon", "translation": "Whoever comes [on the Day of Judgement] with a good deed will have better than it; and whoever comes with an evil deed - then those who did evil deeds will not be recompensed except [as much as] what they used to do."}, {"ayah": 85, "translit": "Innal azee farada 'alaikal Qur-aana laraaadduka ilaa ma'aad; qur Rabbeee a'lamu man jjaaa'a bil hudaa wa man huwa fee dalaalim mubeen", "translation": "Indeed, [O Muhammad], He who imposed upon you the Qur'an will take you back to a place of return. Say, \"My Lord is most knowing of who brings guidance and who is in clear error.\""}, {"ayah": 86, "translit": "Wa maa kunta tarjooo ai yulqaaa ilaikal Kitaabu illaa rahmatam mir Rabbika falaa takoonanna zaheeral lilkaafireen", "translation": "And you were not expecting that the Book would be conveyed to you, but [it is] a mercy from your Lord. So do not be an assistant to the disbelievers."}, {"ayah": 87, "translit": "Wa laa yasuddunnaka 'an Aayaatil laahi ba'da iz unzilat ilaika wad'u ilaa Rabbika wa laa takonanna minal mushrikeen", "translation": "And never let them avert you from the verses of Allah after they have been revealed to you. And invite [people] to your Lord. And never be of those who associate others with Allah."}, {"ayah": 88, "translit": "Wa laa tad'u ma'al laahi ilaahan aakhar; laaa ilaaha illaa Hoo; kullu shai'in haalikun illaa Wajhah; lahul hukkmu wa ilaihi turja'oon", "translation": "And do not invoke with Allah another deity. There is no deity except Him. Everything will be destroyed except His Face. His is the judgement, and to Him you will be returned."}]}, {"num": 29, "name": "Al-Ankabut", "meaning": "The Spider", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Meeem", "translation": "Alif, Lam, Meem"}, {"ayah": 2, "translit": "Ahasiban naasu anyu yutrakooo any yaqoolooo aamannaa wa hum la yuftanoon", "translation": "Do the people think that they will be left to say, \"We believe\" and they will not be tried?"}, {"ayah": 3, "translit": "Wa laqad fatannal lazeena min qablihim fala ya'lamannal laahul lazeena sadaqoo wa la ya'lamannal kaazibeen", "translation": "But We have certainly tried those before them, and Allah will surely make evident those who are truthful, and He will surely make evident the liars."}, {"ayah": 4, "translit": "Am hasibal lazeena ya'maloonas sayyiaati any yasbiqoonaa; saaa'a maa yahkumoon", "translation": "Or do those who do evil deeds think they can outrun Us? Evil is what they judge."}, {"ayah": 5, "translit": "Man kaana yarjoo liqaaa 'allaahi fa inna ajalal laahi laaat; wa Huwass Sameeul 'Aleem", "translation": "Whoever should hope for the meeting with Allah - indeed, the term decreed by Allah is coming. And He is the Hearing, the Knowing."}, {"ayah": 6, "translit": "Wa man jaahada fainnamaa yujaahidu linafsih; innal laaha laghaniyyun 'anil 'aalameen", "translation": "And whoever strives only strives for [the benefit of] himself. Indeed, Allah is free from need of the worlds."}, {"ayah": 7, "translit": "Wallazeena aamanoo wa 'amilus saalihaati lanukaf firanna 'anhum saiyiaatihim wa lanajziyannahum ahsanal lazee kaanoo ya'maloon", "translation": "And those who believe and do righteous deeds - We will surely remove from them their misdeeds and will surely reward them according to the best of what they used to do."}, {"ayah": 8, "translit": "Wa wassainal insaana biwaalidaihi husnanw wa in jaahadaaka litushrika bee maa laisa laka bihee 'ilmun falaa tuti'humaa; ilaiya marji'ukum fa unabbi'ukum bimaa kuntum ta'maloon", "translation": "And We have enjoined upon man goodness to parents. But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them. To Me is your return, and I will inform you about what you used to do."}, {"ayah": 9, "translit": "Wallazeena aamanoo w a'amilus saalihaati lanudkhilan nahum fis saaliheen", "translation": "And those who believe and do righteous deeds - We will surely admit them among the righteous [into Paradise]."}, {"ayah": 10, "translit": "Wa minan naasi many yaqoolu aamannaa billaahi faizaaa ooziya fil laahi ja'ala fitnatan naasi ka'azaabil laahi wa la'in jaaa'a nasrum mir Rabbika la yaqoolunna innaa kunnaa ma'akum; awa laisal laahu bi a'lama bimaa fee surdooril 'aalameen", "translation": "And of the people are some who say, \"We believe in Allah,\" but when one [of them] is harmed for [the cause of] Allah, they consider the trial of the people as [if it were] the punishment of Allah. But if victory comes from your Lord, they say, \"Indeed, We were with you.\" Is not Allah most knowing of what is within the breasts of all creatures?"}, {"ayah": 11, "translit": "Wa la ya'lamannal laahul lazeena aamanoo wa la ya'lamannal munaafiqeen", "translation": "And Allah will surely make evident those who believe, and He will surely make evident the hypocrites."}, {"ayah": 12, "translit": "Wa qaalal lazaeena kafaroo lillazeena aamanut tabi'oo sabeelanaa walnahmil khataayaakum wa maa hum bihaamileena min khataa yaahum min shai'in innahum lakaaziboon", "translation": "And those who disbelieve say to those who believe, \"Follow our way, and we will carry your sins.\" But they will not carry anything of their sins. Indeed, they are liars."}, {"ayah": 13, "translit": "Wa la yahmilunna asqaa lahum wa asqaalam ma'a asqaalihim wa la yus'alunna Yawmal Qiyaamati 'ammaa kaanoo yaftaroon", "translation": "But they will surely carry their [own] burdens and [other] burdens along with their burdens, and they will surely be questioned on the Day of Resurrection about what they used to invent."}, {"ayah": 14, "translit": "Wa laqad arsalnaa Noohan ilaa qawmihee falabisa feehim alfa sanatin illaa khamseena 'aaman fa akhazahumut toofaanu wa hum zaalimoon", "translation": "And We certainly sent Noah to his people, and he remained among them a thousand years minus fifty years, and the flood seized them while they were wrongdoers."}, {"ayah": 15, "translit": "Fa anjainaahu wa as haabas safeenati wa ja'alnaahaaa Aayatal lil'aalameen", "translation": "But We saved him and the companions of the ship, and We made it a sign for the worlds."}, {"ayah": 16, "translit": "Wa Ibraheema iz qaala liqawmihi' budul laaha wattaqoohu zaalikum khayrul lakum in kuntum ta'lamoon", "translation": "And [We sent] Abraham, when he said to his people, \"Worship Allah and fear Him. That is best for you, if you should know."}, {"ayah": 17, "translit": "Innamaa ta'ubdoona min doonil laahi awsaananw-wa takhluqoona ifkaa; innal lazeena ta'budoona min doonil laahi laa yamlikoona lakum rizqan fabtaghoo 'indal laahir rizqa fabtaghoo 'indal laahir rizqa wa'budoohu washkuroo lahooo ilaihi turja'oon", "translation": "You only worship, besides Allah, idols, and you produce a falsehood. Indeed, those you worship besides Allah do not possess for you [the power of] provision. So seek from Allah provision and worship Him and be grateful to Him. To Him you will be returned.\""}, {"ayah": 18, "translit": "Wa in tukazziboo faqad kazzaba umamum min qablikum wa maa'alar Rasooli illal balaaghul mubeen", "translation": "And if you [people] deny [the message] - already nations before you have denied. And there is not upon the Messenger except [the duty of] clear notification."}, {"ayah": 19, "translit": "Awa lam yaraw kaifa yubdi'ul laahul khalqa summa yu'eeduh; inna zaalika 'alal laahi yaseer", "translation": "Have they not considered how Allah begins creation and then repeats it? Indeed that, for Allah, is easy."}, {"ayah": 20, "translit": "Qul seeroo fil ardi fanzuroo kaifa baa al khalqa summal laahu yunshi''un nash atal Aakhirah; innal laaha 'alaa kulli shai'in Qadeer", "translation": "Say, [O Muhammad], \"Travel through the land and observe how He began creation. Then Allah will produce the final creation. Indeed Allah, over all things, is competent.\""}, {"ayah": 21, "translit": "Yu'azzibu many yashaaa'u wa yarhamu many yashaaa'; wa ilaihi tuqlaboon", "translation": "He punishes whom He wills and has mercy upon whom He wills, and to Him you will be returned."}, {"ayah": 22, "translit": "Wa maaa antum bimu'jizeena fil ardi wa laa fissamaaa'i wa maa lakum min doonil laahi minw waliyyinw wa laa naseer", "translation": "And you will not cause failure [to Allah] upon the earth or in the heaven. And you have not other than Allah any protector or any helper."}, {"ayah": 23, "translit": "Wallazeena kafaroo bi Aayaatil laahi wa liqaaa'iheee ulaaa'ika ya'isoo mir rahmatee wa ulaaa'ika lahum 'azaabun aleem", "translation": "And the ones who disbelieve in the signs of Allah and the meeting with Him - those have despaired of My mercy, and they will have a painful punishment."}, {"ayah": 24, "translit": "Famaa kaana jawaaba qawmiheee illaaa an qaaluqtuloohu aw harriqoohu faanjaahul laahu minan naar; inna fee zaalika la Aayaatil laqawminy yu'minoon", "translation": "And the answer of Abraham's people was not but that they said, \"Kill him or burn him,\" but Allah saved him from the fire. Indeed in that are signs for a people who believe."}, {"ayah": 25, "translit": "Wa qaala innamat takhaz tum min doonil laahi awsaanam mawaddata bainikum fil hayaatid dunyaa summa yawmal qiyaamati yakfuru ba'dukum biba 'dinw wa yal'anu ba'dukum ba'danw-wa yal'anu ba'dukum ba'danw wa maa waakumun Naaru wa maa lakum min naasireen", "translation": "And [Abraham] said, \"You have only taken, other than Allah, idols as [a bond of] affection among you in worldly life. Then on the Day of Resurrection you will deny one another and curse one another, and your refuge will be the Fire, and you will not have any helpers.\""}, {"ayah": 26, "translit": "Fa aamana lahoo Loot; wa qaala innee mauhajirun ilaa Rabbee innahoo Huwal 'Azeezul Hakeem", "translation": "And Lot believed him. [Abraham] said, \"Indeed, I will emigrate to [the service of] my Lord. Indeed, He is the Exalted in Might, the Wise.\""}, {"ayah": 27, "translit": "Wa wahabnaa lahoo Ishaaqa wa Ya'Qooba wa ja'alnaa fee zurriyyatihin Nubuwwata wal Kitaaba wa aatainaahu ajrahoo fid dunyaa wa innahoo fil aakhirati laminas saaliheen", "translation": "And We gave to Him Isaac and Jacob and placed in his descendants prophethood and scripture. And We gave him his reward in this world, and indeed, he is in the Hereafter among the righteous."}, {"ayah": 28, "translit": "Wa Lootan iz qaala liqawmiheee innakum laatoonal faahishata maa sabaqakum bihaa min ahadim minal 'aalameen", "translation": "And [mention] Lot, when he said to his people, \"Indeed, you commit such immorality as no one has preceded you with from among the worlds."}, {"ayah": 29, "translit": "A'innakum lataatoonar rijaala wa taqta'oonas sabeela wa taatoona fee naadekumul munkara famaa kaana jawaaba qawmiheee illaaa an qaalu' tinaaa bi'azaabil laahi in kunta minas saadiqeen", "translation": "Indeed, you approach men and obstruct the road and commit in your meetings [every] evil.\" And the answer of his people was not but they said, \"Bring us the punishment of Allah, if you should be of the truthful.\""}, {"ayah": 30, "translit": "Qaala Rabbin surnee 'alal qawmil mufsideen", "translation": "He said, \"My Lord, support me against the corrupting people.\""}, {"ayah": 31, "translit": "Wa lammaa jaaa'at Rusulunaaa Ibraaheema bil bushraa qaalooo innaa muhlikoo ahli haazihil qaryati inna ahlahaa kaanoo zaalimeen", "translation": "And when Our messengers came to Abraham with the good tidings, they said, \"Indeed, we will destroy the people of that Lot's city. Indeed, its people have been wrongdoers.\""}, {"ayah": 32, "translit": "Qaala inna feeha Lootaa; qaaloo nahnu a'lamu biman feehaa lanunajjjiyannahoo wa ahlahooo illam ra atahoo kaanat minal ghaabireen", "translation": "[Abraham] said, \"Indeed, within it is Lot.\" They said, \"We are more knowing of who is within it. We will surely save him and his family, except his wife. She is to be of those who remain behind.\""}, {"ayah": 33, "translit": "Wa lammaaa an jaaa'at Rusulunaa Lootan seee'a bihim wa daaqa bihim zar'anw wa qaaloo laa takhaf wa laa tahzan innaa munajjooka wa ahlaka illam ra ataka kaanat minal ghaabireen", "translation": "And when Our messengers came to Lot, he was distressed for them and felt for them great discomfort. They said, \"Fear not, nor grieve. Indeed, we will save you and your family, except your wife; she is to be of those who remain behind."}, {"ayah": 34, "translit": "Innaa munziloona 'alaaa ahli haazihil qaryati rijzam minas samaaa'i bimaa kaanoo yafsuqoon", "translation": "Indeed, we will bring down on the people of this city punishment from the sky because they have been defiantly disobedient.\""}, {"ayah": 35, "translit": "Wa laqat taraknaa min haaa aayatam baiyinatal liqawminy ya'qiloon", "translation": "And We have certainly left of it a sign as clear evidence for a people who use reason."}, {"ayah": 36, "translit": "Wa ilaa Madyana akhaahum Shu'ayban faqaala yaa qawmi'-budul laaha warjul yawmal aakhira wa laa ta'saw fil ardi mufsideen", "translation": "And to Madyan [We sent] their brother Shu'ayb, and he said, \"O my people, worship Allah and expect the Last Day and do not commit abuse on the earth, spreading corruption.\""}, {"ayah": 37, "translit": "Fakazzaboohu fa akhazat humur rajfatu fa asbahoo fee daarihim jaasimeen", "translation": "But they denied him, so the earthquake seized them, and they became within their home [corpses] fallen prone."}, {"ayah": 38, "translit": "Wa 'Aadanw wa Samooda wa qat tabaiyana lakum mim masaakinihim wa zaiyana lahumush Shaitaanu a'maalahum fasaddahum 'anis sabeeli wa kaanoo mustabsireen", "translation": "And [We destroyed] 'Aad and Thamud, and it has become clear to you from their [ruined] dwellings. And Satan had made pleasing to them their deeds and averted them from the path, and they were endowed with perception."}, {"ayah": 39, "translit": "Wa Qaaroona wa Fir'awna wa haamaana wa laqad jaaa'ahum Moosa bilbaiyinaati fastakbaroo fil ardi wa maa kaanoo saabiqeen", "translation": "And [We destroyed] Qarun and Pharaoh and Haman. And Moses had already come to them with clear evidences, and they were arrogant in the land, but they were not outrunners [of Our punishment]."}, {"ayah": 40, "translit": "Fakullan akhaznaa bizam bihee faminhum man arsalnaa 'alaihi haasibaa; wa minhum man akhazat hus saihatu wa minhum man khasafnaa bihil arda wa minhum man aghraqnaa; wa maa kaanal laahu li yazlimahum wa laakin kaanoo anfusahum yazlimoon", "translation": "So each We seized for his sin; and among them were those upon whom We sent a storm of stones, and among them were those who were seized by the blast [from the sky], and among them were those whom We caused the earth to swallow, and among them were those whom We drowned. And Allah would not have wronged them, but it was they who were wronging themselves."}, {"ayah": 41, "translit": "Masalul lazeenat takhazoo min doonil laahi awliyaaa'a kamasalil 'ankaboot, ittakhazat baitaa; wa inna awhanal buyooti la baitul 'ankaboot; law kaanoo ya'lamoon", "translation": "The example of those who take allies other than Allah is like that of the spider who takes a home. And indeed, the weakest of homes is the home of the spider, if they only knew."}, {"ayah": 42, "translit": "Innal laaha ya'lamu maa yad'oona min doonihee min shai'; wa Huwal 'Azeezul Hakeem", "translation": "Indeed, Allah knows whatever thing they call upon other than Him. And He is the Exalted in Might, the Wise."}, {"ayah": 43, "translit": "Wa tilkal amsaalu nadribuhaa linnaasi wa maa ya'qiluhaaa illal 'aalimoon", "translation": "And these examples We present to the people, but none will understand them except those of knowledge."}, {"ayah": 44, "translit": "Khalaqal laahus samaawaati wal arda bilhaqq; inna fee zaalika la aayatal lilmu mineen", "translation": "Allah created the heavens and the earth in truth. Indeed in that is a sign for the believers."}, {"ayah": 45, "translit": "Utlu maaa oohiya ilaika mional Kitaabi wa aqimis Salaata innas Salaata tanhaa 'anil fahshaaa'i wal munkar; wa lazikrul laahi akbar; wal laahu ya'lamu maa tasna'oon", "translation": "Recite, [O Muhammad], what has been revealed to you of the Book and establish prayer. Indeed, prayer prohibits immorality and wrongdoing, and the remembrance of Allah is greater. And Allah knows that which you do."}, {"ayah": 46, "translit": "Wa laa tujaadilooo Ahlal Kitaabi illaa billatee hiya ahsanu illal lazeena zalamoo minhum wa qoolooo aamannaa billazeee unzila ilainaa wa unzila ilaikum wa illaahunna wa illahukum waahidunw-wa nahnu lahoo muslimoon", "translation": "And do not argue with the People of the Scripture except in a way that is best, except for those who commit injustice among them, and say, \"We believe in that which has been revealed to us and revealed to you. And our God and your God is one; and we are Muslims [in submission] to Him.\""}, {"ayah": 47, "translit": "Wa kazaalika anzalnaaa ilaikal Kitaab; fallazeena aatainaahumul kitaaba yu'minoona bihee wa min haaa'ulaaa'i many yu'minu bih; wa maa yajhadu bi'Aayaatinaa illal kaafiroon", "translation": "And thus We have sent down to you the Qur'an. And those to whom We [previously] gave the Scripture believe in it. And among these [people of Makkah] are those who believe in it. And none reject Our verses except the disbelievers."}, {"ayah": 48, "translit": "Wa maa kunta tatloo min qablihee min kitaabinw wa laa takhuttubhoo bi yameenika izal lartaabal mubtiloon", "translation": "And you did not recite before it any scripture, nor did you inscribe one with your right hand. Otherwise the falsifiers would have had [cause for] doubt."}, {"ayah": 49, "translit": "Bal huwa aayaatum baiyinaatun fee sudooril lazeena ootul 'ilm; wa maa yajhadu bi aayaatinaa illaz zaalimoon", "translation": "Rather, the Qur'an is distinct verses [preserved] within the breasts of those who have been given knowledge. And none reject Our verses except the wrongdoers."}, {"ayah": 50, "translit": "Wa qaaloo law laaa unzila 'alaihi aayaatum mir Rabbihee qul innamal aayaatu 'indal laahi wa innamaaa ana nazeerum mubeen", "translation": "But they say, \"Why are not signs sent down to him from his Lord?\" Say, \"The signs are only with Allah, and I am only a clear warner.\""}, {"ayah": 51, "translit": "Awa lam yakfihim annaaa anzalnaa 'alaikal kitaaba yutlaa 'alaikhim; inna fee zaalika larahmatanw wa zikraa liqawminy yu'minoon", "translation": "And is it not sufficient for them that We revealed to you the Book which is recited to them? Indeed in that is a mercy and reminder for a people who believe."}, {"ayah": 52, "translit": "Qul kafaa billaahi bainee wa bainakum shaheedaa; ya'lamu maa fis samaawaati wal ard; wallazeena aamanoo bil baatili wa kafaroo billaahi ulaaa'ika humul khaasiroon", "translation": "Say, \"Sufficient is Allah between me and you as Witness. He knows what is in the heavens and earth. And they who have believed in falsehood and disbelieved in Allah - it is those who are the losers.\""}, {"ayah": 53, "translit": "Wa yasta'jiloonaka bil'azaab; wa law laaa ajalum musammal lajaaa'ahumul 'zaab; wa la yaatiyannahum baghta tanw wa hum laa yash'uroon", "translation": "And they urge you to hasten the punishment. And if not for [the decree of] a specified term, punishment would have reached them. But it will surely come to them suddenly while they perceive not."}, {"ayah": 54, "translit": "Yasta'jiloonak bil'azaab; wa inna Jahannama lamuhee tatum bilkaafireen", "translation": "They urge you to hasten the punishment. And indeed, Hell will be encompassing of the disbelievers"}, {"ayah": 55, "translit": "Yawma yaghshaahumul 'azaabu min fawqihim wa min tahti arjulim wa yaqoolu zooqoo maa kuntum ta'maloon", "translation": "On the Day the punishment will cover them from above them and from below their feet and it is said, \"Taste [the result of] what you used to do.\""}, {"ayah": 56, "translit": "Yaa 'ibaadiyal lazeena aamanooo inna ardee waasi 'atun fa iyyaaya fa'budoon", "translation": "O My servants who have believed, indeed My earth is spacious, so worship only Me."}, {"ayah": 57, "translit": "Kullu nafsin zaaa'iqatul mawti summa ilainaa turja'oon", "translation": "Every soul will taste death. Then to Us will you be returned."}, {"ayah": 58, "translit": "Wallazeena aamanoo wa 'amilus saalihaati la nubawwi 'annahum minal Jannati ghurafan tajree min tahtihal anhaaru khaalideena feehaa; ni'ma ajrul 'aamileen", "translation": "And those who have believed and done righteous deeds - We will surely assign to them of Paradise [elevated] chambers beneath which rivers flow, wherein they abide eternally. Excellent is the reward of the [righteous] workers"}, {"ayah": 59, "translit": "Allazeena sabaroo wa 'alaa Rabbihim yatawakkaloon", "translation": "Who have been patient and upon their Lord rely."}, {"ayah": 60, "translit": "Wa ka ayyim min daaabbatil laa tahmilu riqqahaa; al laahu yarzuquhaa wa iyyaakum; wa Huwas Samee'ul Aleem", "translation": "And how many a creature carries not its [own] provision. Allah provides for it and for you. And He is the Hearing, the Knowing."}, {"ayah": 61, "translit": "Wa la'in sa altahum man khalaqas samaawaati wal arda wa sakhkharash shamsa wal qamara la yaqoolunnal laahu fa ann yu'fakoon", "translation": "If you asked them, \"Who created the heavens and earth and subjected the sun and the moon?\" they would surely say, \"Allah.\" Then how are they deluded?"}, {"ayah": 62, "translit": "Allaahu yabsutur rizqa limany yashaaa'u min 'ibaadihee wa yaqdiru lah; innal laaha bikulli shai'in Aleem", "translation": "Allah extends provision for whom He wills of His servants and restricts for him. Indeed Allah is, of all things, Knowing."}, {"ayah": 63, "translit": "Wa la'in sa altahum man nazzala minas samaaa'e maaa'an fa ahyaa bihil arda mim ba'di mawtihaa la yaqoolunnal laah; qulil hamdu lillah; bal aksaruhum laa ya'qiloon", "translation": "And if you asked them, \"Who sends down rain from the sky and gives life thereby to the earth after its lifelessness?\" they would surely say \" Allah.\" Say, \"Praise to Allah \"; but most of them do not reason."}, {"ayah": 64, "translit": "Wa maa haazihil hayaa tud dunyaaa illaa lahwunw-wa la'ib; wa innad Daaral Aakhirata la hiyal ha yawaan; law kaano ya'lamoon", "translation": "And this worldly life is not but diversion and amusement. And indeed, the home of the Hereafter - that is the [eternal] life, if only they knew."}, {"ayah": 65, "translit": "Fa-izaa rakiboo fil fulki da'awul laaha mukhilseena lahud deena falammaa najjaa hum ilal baari izaa hum yushrikoon", "translation": "And when they board a ship, they supplicate Allah, sincere to Him in religion. But when He delivers them to the land, at once they associate others with Him"}, {"ayah": 66, "translit": "Li yakfuroo bimaaa aatainaahum wa li yatamatta'oo fasaw fa ya'lamoon", "translation": "So that they will deny what We have granted them, and they will enjoy themselves. But they are going to know."}, {"ayah": 67, "translit": "Awalam yaraw annaa ja'alnaa haraman aaminanw wa yutakhattafun naasu min haw lihim; afabil baatili yu'minoona wa bini'matil laahi yakfuroon", "translation": "Have they not seen that We made [Makkah] a safe sanctuary, while people are being taken away all around them? Then in falsehood do they believe, and in the favor of Allah they disbelieve?"}, {"ayah": 68, "translit": "Wa man azlamu mimma nif taraa 'alal laahi kaziban aw kazzaba bilhaqqi lammaa jaaa'ah; alaisa fee jahannama maswal lil kaafireen", "translation": "And who is more unjust than one who invents a lie about Allah or denies the truth when it has come to him? Is there not in Hell a [sufficient] residence for the disbelievers?"}, {"ayah": 69, "translit": "Wallazeena jaahadoo feenaa lanahdiyannahum subulana; wa innal laaha lama'al muhsineen", "translation": "And those who strive for Us - We will surely guide them to Our ways. And indeed, Allah is with the doers of good."}]}, {"num": 30, "name": "Ar-Rum", "meaning": "The Romans", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Meeem", "translation": "Alif, Lam, Meem."}, {"ayah": 2, "translit": "Ghulibatir Room", "translation": "The Byzantines have been defeated"}, {"ayah": 3, "translit": "Feee adnal ardi wa hummim ba'di ghalabihim sa ya ghliboon", "translation": "In the nearest land. But they, after their defeat, will overcome."}, {"ayah": 4, "translit": "Fee bid'i sineen; lillaahil amru min qablu wa mim ba'd; wa yawma'iziny yafrahul mu'minoon", "translation": "Within three to nine years. To Allah belongs the command before and after. And that day the believers will rejoice"}, {"ayah": 5, "translit": "Binasril laa; yansuru mai yashaaa'u wa Huwal 'Azeezur Raheem", "translation": "In the victory of Allah. He gives victory to whom He wills, and He is the Exalted in Might, the Merciful."}, {"ayah": 6, "translit": "Wa'dal laahi laa yukhliful laahu wa'dahoo wa laakin na aksaran naasi laa ya'lamoon", "translation": "[It is] the promise of Allah. Allah does not fail in His promise, but most of the people do not know."}, {"ayah": 7, "translit": "Ya'lamoona zaahiram minal hayaatid dunya wa hum 'anil Aakhirati hum ghaafiloon", "translation": "They know what is apparent of the worldly life, but they, of the Hereafter, are unaware."}, {"ayah": 8, "translit": "Awalam yatafakkaroo feee anfusihim; maa khalaqal laahus samaawaati wal arda wa maa bainahumaaa illaa bil haqqi wa ajalim musammaa; wa inna kaseeram minan naasi biliqaaa'i Rabbihim lakaafiroon", "translation": "Do they not contemplate within themselves? Allah has not created the heavens and the earth and what is between them except in truth and for a specified term. And indeed, many of the people, in [the matter of] the meeting with their Lord, are disbelievers."}, {"ayah": 9, "translit": "Awalm yaseeroo fil ardi fa-yanzuroo kaifa kaana 'aaqibatul lazeena min qablihim; kaanooo ashadda minhhum quwwatanw wa asaarul arda wa 'amaroohaaa aksara mimmaa 'amaroohaa wa jaaa'athum Rusuluhum bil baiyinaati famaa kaanal laahu liyazli mahum wa laakin kaanooo anfusahum yazlimoon", "translation": "Have they not traveled through the earth and observed how was the end of those before them? They were greater than them in power, and they plowed the earth and built it up more than they have built it up, and their messengers came to them with clear evidences. And Allah would not ever have wronged them, but they were wronging themselves."}, {"ayah": 10, "translit": "Summa kaana'aaqibatal lazeena asaaa'us sooo aaa an kazzaboo bi aayaatil laahi wa kaanoo bihaa yastahzi'oon", "translation": "Then the end of those who did evil was the worst [consequence] because they denied the signs of Allah and used to ridicule them."}, {"ayah": 11, "translit": "Allaahu yabda'ul khalqa summa yu'eeduhoo summa ilaihi turja'oon", "translation": "Allah begins creation; then He will repeat it; then to Him you will be returned."}, {"ayah": 12, "translit": "Wa yawma taqoomus Saa'atu yublisul mujrimoon", "translation": "And the Day the Hour appears the criminals will be in despair."}, {"ayah": 13, "translit": "Wa lam yakul lahum min shurakaaa'ihim shufa'aaa'u wa kaanoo bishurakaaa'ihim kaafireen", "translation": "And there will not be for them among their [alleged] partners any intercessors, and they will [then] be disbelievers in their partners."}, {"ayah": 14, "translit": "Wa Yawma taqoomus Saa'atu Yawma'iziny yatafarraqoon", "translation": "And the Day the Hour appears - that Day they will become separated."}, {"ayah": 15, "translit": "Fa ammal lazeena aamanoo wa 'amilus saalihaati fahum fee rawdatiny yuhbaroon", "translation": "And as for those who had believed and done righteous deeds, they will be in a garden [of Paradise], delighted."}, {"ayah": 16, "translit": "Wa ammal lazeena kafaroo wa kazzaboo bi-Aayaatinaa wa liqaaa'il Aakhirati faulaaa'ika fil'azaabi muhdaroon", "translation": "But as for those who disbelieved and denied Our verses and the meeting of the Hereafter, those will be brought into the punishment [to remain]."}, {"ayah": 17, "translit": "Fa Subhaanal laahi heena tumsoona wa heena tusbihoon", "translation": "So exalted is Allah when you reach the evening and when you reach the morning."}, {"ayah": 18, "translit": "Wa lahul hamdu fis samaawaati wal ardi wa 'ashiyyanw wa heena tuzhiroon", "translation": "And to Him is [due all] praise throughout the heavens and the earth. And [exalted is He] at night and when you are at noon."}, {"ayah": 19, "translit": "Yukhrijul haiya minal maiyiti wa yukhrijul maiyita minal haiyi wa yuhyil arda ba'da mawtihaa; wa kazaalika tukhrajoon", "translation": "He brings the living out of the dead and brings the dead out of the living and brings to life the earth after its lifelessness. And thus will you be brought out."}, {"ayah": 20, "translit": "Wa min Aayaatiheee an khalaqakum min turaabin summa izaaa antum basharun tantashiroon", "translation": "And of His signs is that He created you from dust; then, suddenly you were human beings dispersing [throughout the earth]."}, {"ayah": 21, "translit": "Wa min Aayaatiheee an khalaqa lakum min anfusikum azwaajal litaskunooo ilaihaa wa ja'ala bainakum mawad datanw wa rahmah; inna fee zaalika la Aayaatil liqawminy yatafakkaroon", "translation": "And of His signs is that He created for you from yourselves mates that you may find tranquillity in them; and He placed between you affection and mercy. Indeed in that are signs for a people who give thought."}, {"ayah": 22, "translit": "Wa min Aayaatihee khalqus samaawaati wal aardi wakhtilaafu alsinatikum wa alwaanikum; inna fee zaalika la Aayaatil lil'aalimeen", "translation": "And of His signs is the creation of the heavens and the earth and the diversity of your languages and your colors. Indeed in that are signs for those of knowledge."}, {"ayah": 23, "translit": "Wa min Aayaatihee manaamukum bil laili wannahaari wabtighaaa'ukum min fadlih; inna fee zaalika la Aayaatil liqawminy yasma'oon", "translation": "And of His signs is your sleep by night and day and your seeking of His bounty. Indeed in that are signs for a people who listen."}, {"ayah": 24, "translit": "Wa min Aayaatihee yureekumul barqa khawfanw wa tama'anw wa yunazzilu minas samaaa'i maaa'an fa yuhyee bihil arda ba'da mawtihaaa inna fee zaalika la Aayaatil liqawminy ya'qiloon", "translation": "And of His signs is [that] He shows you the lightning [causing] fear and aspiration, and He sends down rain from the sky by which He brings to life the earth after its lifelessness. Indeed in that are signs for a people who use reason."}, {"ayah": 25, "translit": "Wa min Aayaatihee an taqoomas samaaa'u wal ardu bi-amrih; summa izaa da'aakum da'watam minal ardi izaaa antum takhrujoon", "translation": "And of His signs is that the heaven and earth remain by His command. Then when He calls you with a [single] call from the earth, immediately you will come forth."}, {"ayah": 26, "translit": "Wa lahoo man fissamaawaati wal ardi kullul lahoo qaanitoon", "translation": "And to Him belongs whoever is in the heavens and earth. All are to Him devoutly obedient."}, {"ayah": 27, "translit": "Wa Huwal lazee yabda'ul khalqa summa yu'eeduhoo wa huwa ahwanu 'alaih; wa lahul masalul la'laa fissamaawaati wal-ard; wa Huwal 'Azeezul Hakeem", "translation": "And it is He who begins creation; then He repeats it, and that is [even] easier for Him. To Him belongs the highest attribute in the heavens and earth. And He is the Exalted in Might, the Wise."}, {"ayah": 28, "translit": "Daraba lakum masalam min anfusikum hal lakum mimmaa malakat aymaanukum min shurakaaa'a fee maa razaqnaakum fa antum feehi sawaaa'un takhaafoonahum kakheefa tikum anfusakum; kazaalika nufassilul Aayaati liqawminy ya'qiloon", "translation": "He presents to you an example from yourselves. Do you have among those whom your right hands possess any partners in what We have provided for you so that you are equal therein [and] would fear them as your fear of one another [within a partnership]? Thus do We detail the verses for a people who use reason."}, {"ayah": 29, "translit": "Balit taba'al lazeena zalamooo ahwaaa'ahum bighairi 'ilmin famai yahdee man adallal laahu wa maa lahum min naasireen", "translation": "But those who wrong follow their [own] desires without knowledge. Then who can guide one whom Allah has sent astray? And for them there are no helpers."}, {"ayah": 30, "translit": "Fa aqim wajhaka liddeeni Haneefaa; fitratal laahil latee fataran naasa 'alaihaa; laa taabdeela likhalqil laah; zaalikad deenul qaiyimu wa laakinna aksaran naasi laa ya'lamoon", "translation": "So direct your face toward the religion, inclining to truth. [Adhere to] the fitrah of Allah upon which He has created [all] people. No change should there be in the creation of Allah. That is the correct religion, but most of the people do not know."}, {"ayah": 31, "translit": "Muneebeena ilaihi wattaqoohu wa aqeemus Salaata wa laa takoonoo minal mushrikeen", "translation": "[Adhere to it], turning in repentance to Him, and fear Him and establish prayer and do not be of those who associate others with Allah"}, {"ayah": 32, "translit": "Minal lazeena farraqoo deenahum wa kaanoo shiya'an kullu hizbim bimaa ladaihim farihoon", "translation": "[Or] of those who have divided their religion and become sects, every faction rejoicing in what it has."}, {"ayah": 33, "translit": "Wa izaa massan naasa durrun da'aw Rabbahum muneebeena ilaihi summa izaaa azaqahum minhu rahmatan izaa fareequm minhum be Rabbihim yushrikoon", "translation": "And when adversity touches the people, they call upon their Lord, turning in repentance to Him. Then when He lets them taste mercy from Him, at once a party of them associate others with their Lord,"}, {"ayah": 34, "translit": "Li yakfuroo bimaaa aatainaahum; fatamatta'oo fasawfa ta'lamoon", "translation": "So that they will deny what We have granted them. Then enjoy yourselves, for you are going to know."}, {"ayah": 35, "translit": "Am anzalnaa 'alaihim sultaanan fahuwa yatakallamu bimaa kaanoo bihee yushrikoon", "translation": "Or have We sent down to them an authority, and it speaks of what they were associating with Him?"}, {"ayah": 36, "translit": "Wa izaaa azaqnan naasa rahmatan farihoo bihaa wa in tusibhum sayyi'atum bimaa qaddamat aydeehim izaa hum yaqnatoon", "translation": "And when We let the people taste mercy, they rejoice therein, but if evil afflicts them for what their hands have put forth, immediately they despair."}, {"ayah": 37, "translit": "Awalam yaraw annal laaha yabsutur rizqa limai yashaaa'u wa yaqdir; inna fee zaalika la Aayaatil liqawminy yu'minoon", "translation": "Do they not see that Allah extends provision for whom He wills and restricts [it]? Indeed, in that are signs for a people who believe."}, {"ayah": 38, "translit": "Fa aati zal qurbaa haqqahoo walmiskeena wabnassabeel; zaalika khairul lil lazeena yureedoona Wajhal laahi wa ulaaa'ika humul muflihoon", "translation": "So give the relative his right, as well as the needy and the traveler. That is best for those who desire the countenance of Allah, and it is they who will be the successful."}, {"ayah": 39, "translit": "Wa maaa aataitum mir ribal li yarbuwa feee amwaalin naasi falaa yarboo 'indal laahi wa maaa aataitum min zaakaatin tureedoona wajhal laahi fa ulaaa'ika humul mud'ifoon", "translation": "And whatever you give for interest to increase within the wealth of people will not increase with Allah. But what you give in zakah, desiring the countenance of Allah - those are the multipliers."}, {"ayah": 40, "translit": "Allaahul lazee khalaqa kum summa razaqakm summa yumeetukum summa yuhyeekum hal min shurakaaa'ikum mai yaf'alu min zaalikum min shai'; Sub haanahoo wa Ta'aalaa 'ammaa yushrikoon", "translation": "Allah is the one who created you, then provided for you, then will cause you to die, and then will give you life. Are there any of your \"partners\" who does anything of that? Exalted is He and high above what they associate with Him."}, {"ayah": 41, "translit": "Zaharal fasaadu fil barri wal bahri bimaa kasabat aydinnaasi li yuzeeqahum ba'dal lazee 'amiloo la'allahum yarji'oon", "translation": "Corruption has appeared throughout the land and sea by [reason of] what the hands of people have earned so He may let them taste part of [the consequence of] what they have done that perhaps they will return [to righteousness]."}, {"ayah": 42, "translit": "Qul seeroo fil ardi fanzuroo kaifa kaana 'aaqibatul lazeena min qabl; kaana aksaruhum mushrikeen", "translation": "Say, [O Muhammad], \"Travel through the land and observe how was the end of those before. Most of them were associators [of others with Allah]."}, {"ayah": 43, "translit": "Fa aqim wajhaka lid deenil qaiyimi min qabli any yaatiya Yawmul laa maradda lahoo minal laahi Yawma'iziny yassadda'oon", "translation": "So direct your face toward the correct religion before a Day comes from Allah of which there is no repelling. That Day, they will be divided."}, {"ayah": 44, "translit": "Man kafara fa'alaihi kufruhoo wa man 'amila saalihan fali anfusihim yamhadoon", "translation": "Whoever disbelieves - upon him is [the consequence of] his disbelief. And whoever does righteousness - they are for themselves preparing,"}, {"ayah": 45, "translit": "Li yajziyal lazeena aamanoo wa 'amilus saalihaati min fadlih; innahoo laa yuhibbul kaafireen", "translation": "That He may reward those who have believed and done righteous deeds out of His bounty. Indeed, He does not like the disbelievers."}, {"ayah": 46, "translit": "Wa min Aayaatiheee anyyursilar riyaaha mubashshi raatinw wa li yuzeeqakum mir rahmatihee wa litajriyal fulku bi amrihee wa litabtaghoo min fadlihee wa la'allakum tashkuroon", "translation": "And of His signs is that He sends the winds as bringers of good tidings and to let you taste His mercy and so the ships may sail at His command and so you may seek of His bounty, and perhaps you will be grateful."}, {"ayah": 47, "translit": "Wa laqad arsalnaa min qablika Rusulan ilaa qawmihim fajaaa'oohum bil baiyinaati fantaqamnaa minal lazeena ajramoo wa kaana haqqan 'alainaa nasrul mu'mineen", "translation": "And We have already sent messengers before you to their peoples, and they came to them with clear evidences; then We took retribution from those who committed crimes, and incumbent upon Us was support of the believers."}, {"ayah": 48, "translit": "Allaahul lazee yursilur riyaaha fatuseeru sahaaban fa yabsutuhoo fis samaaa'i kaifa yashaaa'u wa yaj'aluhoo kisafan fataral wadqa yakhruju min khilaalihee fa izaaa asaaba bihee mai yashaaa'u min 'ibaadiheee izaa hum yastabshiroon", "translation": "It is Allah who sends the winds, and they stir the clouds and spread them in the sky however He wills, and He makes them fragments so you see the rain emerge from within them. And when He causes it to fall upon whom He wills of His servants, immediately they rejoice"}, {"ayah": 49, "translit": "Wa in kaanoo min qabli any yunazzala 'alaihim min qablihee lamubliseen", "translation": "Although they were, before it was sent down upon them - before that, in despair."}, {"ayah": 50, "translit": "Fanzur ilaaa aasaari rahmatil laahi kaifa yuhyil arda ba'da mawtihaa; inna zaalika lamuhyil mawtaa wa Huwa 'alaa kulli shai'in Qadeer", "translation": "So observe the effects of the mercy of Allah - how He gives life to the earth after its lifelessness. Indeed, that [same one] will give life to the dead, and He is over all things competent."}, {"ayah": 51, "translit": "Wa la'in arsalnaa reehan fara awhu musfarral lazalloo mim ba'dihee yakfuroon", "translation": "But if We should send a [bad] wind and they saw [their crops] turned yellow, they would remain thereafter disbelievers."}, {"ayah": 52, "translit": "Fa innaka laa tusmi'ul mawtaa wa laa tusmi'us summad du'aaa'a izaa wallaw mudbireen", "translation": "So indeed, you will not make the dead hear, nor will you make the deaf hear the call when they turn their backs, retreating."}, {"ayah": 53, "translit": "Wa maa anta bihaadil 'umyi 'an dalaalatihim in tusmi'u illaa mai yuminu bi aayaatinaa fahum muslimoon  (section 5)", "translation": "And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [in submission to Allah]."}, {"ayah": 54, "translit": "Allahul lazee khalaqa kum min du'fin summa ja'ala mim ba'di du'fin quwwatan summa ja'ala mim ba'di quwwatin du'fanw wa shaibah; yakhluqu maa yashaaa'u wa Huwal 'Aleemul Qadeer", "translation": "Allah is the one who created you from weakness, then made after weakness strength, then made after strength weakness and white hair. He creates what He wills, and He is the Knowing, the Competent."}, {"ayah": 55, "translit": "Wa Yawma taqoomus Saa'atu yuqsimul mujrimoona maa labisoo ghaira saa'ah; kazaalika kaanoo yu'fakoon", "translation": "And the Day the Hour appears the criminals will swear they had remained but an hour. Thus they were deluded."}, {"ayah": 56, "translit": "Wa qaalal lazeena ootul 'ilma wal eemaana laqad labistum fee kitaabil laahi ilaa yawmil ba'si fahaazaa yawmul ba'si wa laakinnakum kuntum laa ta'lamoon", "translation": "But those who were given knowledge and faith will say, \"You remained the extent of Allah 's decree until the Day of Resurrection, and this is the Day of Resurrection, but you did not used to know.\""}, {"ayah": 57, "translit": "Fa Yawma'izil laa yanfa'ul lazeena zalamoo ma'ziratu hum wa laa hum yusta'taboon", "translation": "So that Day, their excuse will not benefit those who wronged, nor will they be asked to appease [Allah]."}, {"ayah": 58, "translit": "Wa laqad darabnaa linnaasi fee haazal Quraani min kulli masal; wa la'in ji'tahum bi aayatil la yaqoolannal lazeena kafaroo in antum illaa mubtiloon", "translation": "And We have certainly presented to the people in this Qur'an from every [kind of] example. But, [O Muhammad], if you should bring them a sign, the disbelievers will surely say, \"You [believers] are but falsifiers.\""}, {"ayah": 59, "translit": "Kazaalika yatba'ul laahu 'alaa quloobil lazeena laa ya'lamoon", "translation": "Thus does Allah seal the hearts of those who do not know."}, {"ayah": 60, "translit": "Fasbir inna wa'dal laahi haqqunw wa laa yastakhif fannakal lazeena laa yooqinoon", "translation": "So be patient. Indeed, the promise of Allah is truth. And let them not disquiet you who are not certain [in faith]."}]}, {"num": 31, "name": "Luqman", "meaning": "Luqman", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Meeem", "translation": "Alif, Lam, Meem."}, {"ayah": 2, "translit": "Tilka Aayaatul Kitaabil Hakeem", "translation": "These are verses of the wise Book,"}, {"ayah": 3, "translit": "Hudanw wa rahmatal lilmuhsineen", "translation": "As guidance and mercy for the doers of good"}, {"ayah": 4, "translit": "Allazeena yuqeemoonas Salaata wa yu'toonaz Zakaata wa hum bil Aakhirati hum yooqinoon", "translation": "Who establish prayer and give zakah, and they, of the Hereafter, are certain [in faith]."}, {"ayah": 5, "translit": "Ulaaa'ika 'alaa hudam mir Rabbihim wa ulaaa'ika humul muflihoon", "translation": "Those are on [right] guidance from their Lord, and it is those who are the successful."}, {"ayah": 6, "translit": "Wa minan naasi mai-yashtaree lahuwal hadeesi li yudilla 'an sabeelil laahi bighairi 'ilminw wa yattakhizahaa huzuwaa; ulaaa'ika lahum 'azaabum muheen", "translation": "And of the people is he who buys the amusement of speech to mislead [others] from the way of Allah without knowledge and who takes it in ridicule. Those will have a humiliating punishment."}, {"ayah": 7, "translit": "Wa izaa tutlaa 'alayhi Aayaatunaa wallaa mustakbiran ka al lam yasma'haa ka anna feee uzunwihi waqran fabash shiru bi'azaabin aleem", "translation": "And when our verses are recited to him, he turns away arrogantly as if he had not heard them, as if there was in his ears deafness. So give him tidings of a painful punishment."}, {"ayah": 8, "translit": "Innal lazeena aamanoo wa 'amilus saalihaati lahum Janaatun Na'eem", "translation": "Indeed, those who believe and do righteous deeds - for them are the Gardens of Pleasure."}, {"ayah": 9, "translit": "Khaalideena feeha wa'dal laahi haqqaa; wa Huwal 'Azeezul Hakeem", "translation": "Wherein they abide eternally; [it is] the promise of Allah [which is] truth. And He is the Exalted in Might, the Wise."}, {"ayah": 10, "translit": "Khalaqas samaawaati bi ghairi 'amadin tarawnahaa wa alqaa fil ardi rawaasiya an tameeda bikum wa bassa feehaa min kulli daaabbah; wa anzalnaa minas samaaa'i maaa'an fa ambatnaa feeha min kulli zawjin kareem", "translation": "He created the heavens without pillars that you see and has cast into the earth firmly set mountains, lest it should shift with you, and dispersed therein from every creature. And We sent down rain from the sky and made grow therein [plants] of every noble kind."}, {"ayah": 11, "translit": "Haazaa khalqul laahi fa aroonee maazaa khalaqal lazeena min doonih; baliz zaalimoona fee dalalim Mubeen", "translation": "This is the creation of Allah. So show Me what those other than Him have created. Rather, the wrongdoers are in clear error."}, {"ayah": 12, "translit": "Wa laqad aatainaa Luqmaanal hikmata anishkur lillaah; wa many yashkur fa innamaa yashkuru linafsihee wa man kafara fa innal laaha Ghaniyyun Hameed", "translation": "And We had certainly given Luqman wisdom [and said], \"Be grateful to Allah.\" And whoever is grateful is grateful for [the benefit of] himself. And whoever denies [His favor] - then indeed, Allah is Free of need and Praiseworthy."}, {"ayah": 13, "translit": "Wa iz qaala luqmaanu libnihee wa huwa ya'izuhoo ya bunaiya laa tushrik billaah; innash shirka lazulmun 'azeem", "translation": "And [mention, O Muhammad], when Luqman said to his son while he was instructing him, \"O my son, do not associate [anything] with Allah. Indeed, association [with him] is great injustice.\""}, {"ayah": 14, "translit": "Wa wassainal insaana bi waalidaihi hamalat hu ummuhoo wahnan 'alaa wahninw wa fisaaluhoo fee 'aamaini anishkur lee wa liwaalidaika ilaiyal maseer", "translation": "And We have enjoined upon man [care] for his parents. His mother carried him, [increasing her] in weakness upon weakness, and his weaning is in two years. Be grateful to Me and to your parents; to Me is the [final] destination."}, {"ayah": 15, "translit": "Wa in jaahadaaka 'alaaa an tushrika bee maa laisa laka bihee 'ilmun falaa tuti'humaa wa saahib humaa fid dunyaa ma'roofanw wattabi' sabeela man anaaba ilayy; summa ilaiya marji'ukum fa unabbi'ukum bimaa kuntum ta'maloon", "translation": "But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them but accompany them in [this] world with appropriate kindness and follow the way of those who turn back to Me [in repentance]. Then to Me will be your return, and I will inform you about what you used to do."}, {"ayah": 16, "translit": "Ya bunaiya innahaaa in taku misqaala habbatim min khardalin fatakun fee sakhratin aw fis samaawaati aw fil ardi yaati bihal laa; innal laaha lateefun Khabeer", "translation": "[And Luqman said], \"O my son, indeed if wrong should be the weight of a mustard seed and should be within a rock or [anywhere] in the heavens or in the earth, Allah will bring it forth. Indeed, Allah is Subtle and Acquainted."}, {"ayah": 17, "translit": "Yaa bunaiya aqimis-Salaata waamur bilma'roofi wanha 'anil munkari wasbir 'alaa maaa asaabaka inna zaalika min 'azmil umoor", "translation": "O my son, establish prayer, enjoin what is right, forbid what is wrong, and be patient over what befalls you. Indeed, [all] that is of the matters [requiring] determination."}, {"ayah": 18, "translit": "Wa laa tusa'-'ir khaddaka linnaasi wa laa tamshi fil ardi maarahan innal laaha laa yuhibbu kulla mukhtaalin fakhoor", "translation": "And do not turn your cheek [in contempt] toward people and do not walk through the earth exultantly. Indeed, Allah does not like everyone self-deluded and boastful."}, {"ayah": 19, "translit": "Waqsid fee mashyika waghdud min sawtik; inna ankaral aswaati lasawtul hameer", "translation": "And be moderate in your pace and lower your voice; indeed, the most disagreeable of sounds is the voice of donkeys.\""}, {"ayah": 20, "translit": "Alam taraw annal laaha sakhkhara lakum maa fis sa maawaati wa maa fil ardi wa asbaha 'alaikum ni'amahoo zaahiratanw wa baatinah; wa minan naasi many yujaadilu fil laahi bighayri 'ilminw wa laa hudanw wa laa Kitaabim muneer", "translation": "Do you not see that Allah has made subject to you whatever is in the heavens and whatever is in the earth and amply bestowed upon you His favors, [both] apparent and unapparent? But of the people is he who disputes about Allah without knowledge or guidance or an enlightening Book [from Him]."}, {"ayah": 21, "translit": "Wa izaa qeela lahumut-tabi'oo maaa anzalal laahu qaaloo bal nattabi'u maa wajadnaa 'alaihi aabaaa'anaa; awalaw kaanash Shaitaanu yad'oohum ilaa 'azaabis sa'eer", "translation": "And when it is said to them, \"Follow what Allah has revealed,\" they say, \"Rather, we will follow that upon which we found our fathers.\" Even if Satan was inviting them to the punishment of the Blaze?"}, {"ayah": 22, "translit": "Wa many yuslim wajha hooo ilal laahi wa huwa muhsinun faqadistamsaka bil'ur watil wusqaa; wa ilal laahi 'aaqibatul umoor", "translation": "And whoever submits his face to Allah while he is a doer of good - then he has grasped the most trustworthy handhold. And to Allah will be the outcome of [all] matters."}, {"ayah": 23, "translit": "Wa man kafara falaa yahzunka kufruh; ilainaa marji'uhum fanunabbi'uhum bimaa 'amiloo; innal laaha 'aleemum bizaatis sudoor", "translation": "And whoever has disbelieved - let not his disbelief grieve you. To Us is their return, and We will inform them of what they did. Indeed, Allah is Knowing of that within the breasts."}, {"ayah": 24, "translit": "Numatti'uhum qaleelan summa nadtarruhum ilaa 'azaabin ghaleez", "translation": "We grant them enjoyment for a little; then We will force them to a massive punishment."}, {"ayah": 25, "translit": "Wa la'in sa altahum man khalaqas samaawaati wal arda la yaqoolunnal laah; qulil hamdu lillaah; bal aksaruhum laa ya'lamoon", "translation": "And if you asked them, \"Who created the heavens and earth?\" they would surely say, \"Allah.\" Say, \"[All] praise is [due] to Allah \"; but most of them do not know."}, {"ayah": 26, "translit": "Lilaahi ma fis samaa waati wal ard; innal laaha Huwal Ghaniyyul Hameed", "translation": "To Allah belongs whatever is in the heavens and earth. Indeed, Allah is the Free of need, the Praiseworthy."}, {"ayah": 27, "translit": "Wa law annamaa fil ardi min shajaratin aqlaamunw wal bahru yamudduhoo mim ba'dihee sab'atu abhurim maa nafidat Kalimaatul laah; innal laaha 'azeezun Hakeem", "translation": "And if whatever trees upon the earth were pens and the sea [was ink], replenished thereafter by seven [more] seas, the words of Allah would not be exhausted. Indeed, Allah is Exalted in Might and Wise."}, {"ayah": 28, "translit": "Maa khalqukum wa laa ba'sukum illaa kanafsinw-waa hidah; innal laaha Samee'um Baseer", "translation": "Your creation and your resurrection will not be but as that of a single soul. Indeed, Allah is Hearing and Seeing."}, {"ayah": 29, "translit": "Alam tara annal laaha yoolijul laila fin nahaari wa yoolijun nahaara fil laili wa sakhkharash shamsa wal qamara kulluny yajreee ilaaa ajalim musammanw wa annal laaha bimaa ta'malona Khabeer", "translation": "Do you not see that Allah causes the night to enter the day and causes the day to enter the night and has subjected the sun and the moon, each running [its course] for a specified term, and that Allah, with whatever you do, is Acquainted?"}, {"ayah": 30, "translit": "Zaalika bi annal laaha Huwal Haqqu wa anna maa yad'oona min doonihil baatilu wa annal laaha Huwal 'Aliyyul Kabeer", "translation": "That is because Allah is the Truth, and that what they call upon other than Him is falsehood, and because Allah is the Most High, the Grand."}, {"ayah": 31, "translit": "Alam tara annal fulka tajree fil bahri bini'matil laahi li yuriyakum min Aayaatih; inna fee zaalika la Aayaatil likulli sabbaarin shakoor", "translation": "Do you not see that ships sail through the sea by the favor of Allah that He may show you of His signs? Indeed in that are signs for everyone patient and grateful."}, {"ayah": 32, "translit": "Wa izaa ghashiyahum mawjun kazzulali da'a-wul laaha mukhliseena lahud deena fa lammaa najjaahum ilal barri faminhum muqtasid; wa maa yajhadu bi Aayaatinaa illaa kullu khattaarin kafoor", "translation": "And when waves come over them like canopies, they supplicate Allah, sincere to Him in religion. But when He delivers them to the land, there are [some] of them who are moderate [in faith]. And none rejects Our signs except everyone treacherous and ungrateful."}, {"ayah": 33, "translit": "Yaaa ayyuhan naasuttaqoo Rabbakum wakhshaw Yawmal laa yajzee waalidun 'anw waladihee wa laa mawloodun huwa jaazin 'anw waalidihee shai'aa; innaa wa'dal laahi haqqun falaa taghurran nakumul hayaatud dunyaa wa laa yaghur rannakum billaahil gharoon", "translation": "O mankind, fear your Lord and fear a Day when no father will avail his son, nor will a son avail his father at all. Indeed, the promise of Allah is truth, so let not the worldly life delude you and be not deceived about Allah by the Deceiver."}, {"ayah": 34, "translit": "Innal laaha 'indahoo 'ilmus saa'ati wa yunazzilul ghaisa wa ya'lamu maa fil arhaami wa maa tadree nafsum maazaa takisbu ghadaa; wa maa tadree nafsum bi ayyi ardin tamoot; innal laaha 'Aleemun Khabeer", "translation": "Indeed, Allah [alone] has knowledge of the Hour and sends down the rain and knows what is in the wombs. And no soul perceives what it will earn tomorrow, and no soul perceives in what land it will die. Indeed, Allah is Knowing and Acquainted."}]}, {"num": 32, "name": "As-Sajdah", "meaning": "The Prostration", "verses": [{"ayah": 1, "translit": "Alif-Laaam-Meeem", "translation": "Alif, Lam, Meem."}, {"ayah": 2, "translit": "Tanzeelul Kitaabi 'laaraiba feehi mir rabbil 'aalameen", "translation": "[This is] the revelation of the Book about which there is no doubt from the Lord of the worlds."}, {"ayah": 3, "translit": "Am yaqooloonaf taraahu bal huwal haqqu mir rabbika litunzira qawma maaa ataahum min nazeerim min qablika la'allahum yahtadoon", "translation": "Or do they say, \"He invented it\"? Rather, it is the truth from your Lord, [O Muhammad], that you may warn a people to whom no warner has come before you [so] perhaps they will be guided."}, {"ayah": 4, "translit": "Allaahul lazee khalaqas samaawaati wal arda wa maa bainahumaa fee sittati ayyaam;Thummas tawaa 'alal 'arsh; maa lakum min doonihee minw-wwaliyyinw-wala shafee'; afala tatazakkaroon", "translation": "It is Allah who created the heavens and the earth and whatever is between them in six days; then He established Himself above the Throne. You have not besides Him any protector or any intercessor; so will you not be reminded?"}, {"ayah": 5, "translit": "Yudabbirul amra minas samaaa'i ilal ardi Thumma ya'ruju ilai Thumma ya'ruju ilaihi fee yawmin kaana miqdaaruhoooo alfa sanatim mimmaa ta'uddoon", "translation": "He arranges [each] matter from the heaven to the earth; then it will ascend to Him in a Day, the extent of which is a thousand years of those which you count."}, {"ayah": 6, "translit": "Zaalika 'aalimul ghaybi wa shahaadatil 'azeezur raheem", "translation": "That is the Knower of the unseen and the witnessed, the Exalted in Might, the Merciful,"}, {"ayah": 7, "translit": "Allazee ahsana kulla shai in khalaqa; wa bada a khalqal insaani min teen", "translation": "Who perfected everything which He created and began the creation of man from clay."}, {"ayah": 8, "translit": "Thumma ja'ala naslahoo min sulaalatim mim maaa'immaheen", "translation": "Then He made his posterity out of the extract of a liquid disdained."}, {"ayah": 9, "translit": "Thumma sawwaahu wa nafakha feehi mir roohihih; wa ja'ala lakumus sam'a wal-absaara wal-af'idah; taqaleelam maa tashkuroon", "translation": "Then He proportioned him and breathed into him from His [created] soul and made for you hearing and vision and hearts; little are you grateful."}, {"ayah": 10, "translit": "Wa qaalooo 'a-izaa dalalnaa fil ardi 'a-innaa lafee khalqin jadeed; bal hum biliqaaa'i rabbihim kaafirroon", "translation": "And they say, \"When we are lost within the earth, will we indeed be [recreated] in a new creation?\" Rather, they are, in [the matter of] the meeting with their Lord, disbelievers."}, {"ayah": 11, "translit": "Qul yatawaffaakum malakul mawtil lazee wukkila bikum Thumma ilaa rabbikum turja'oon", "translation": "Say, \"The angel of death will take you who has been entrusted with you. Then to your Lord you will be returned.\""}, {"ayah": 12, "translit": "Wa law taraaa izil mujrimoona naakisoo ru'oosihim 'inda rabbihim rabbanaaa absarnaa wa sami'naa farji'naa na'mal saalihan innaa mooqinoon", "translation": "If you could but see when the criminals are hanging their heads before their Lord, [saying], \"Our Lord, we have seen and heard, so return us [to the world]; we will work righteousness. Indeed, we are [now] certain.\""}, {"ayah": 13, "translit": "Wa law shi'naa la-aatainaa kulla nafsin hudaahaa wa laakin haqqal qawlu minnee la amla'anna jahannama minal jinnati wannaasi ajma'een", "translation": "And if We had willed, We could have given every soul its guidance, but the word from Me will come into effect [that] \"I will surely fill Hell with jinn and people all together."}, {"ayah": 14, "translit": "Fazooqoo bimaa naseetum liqaaa'a yawminkum haaza innaa naseenaakum wa zooqoo 'azaabal khuldi bimaa kuntum ta'maloon", "translation": "So taste [punishment] because you forgot the meeting of this, your Day; indeed, We have [accordingly] forgotten you. And taste the punishment of eternity for what you used to do.\""}, {"ayah": 15, "translit": "Innamaa yu'minu bi aayaatinal lazeena izaa zukkiroo bihaa kharroo sujjadanw wa sabbahoo bihamdi rabbihim wa hum laa yastakbiroon (make sajda)", "translation": "Only those believe in Our verses who, when they are reminded by them, fall down in prostration and exalt [Allah] with praise of their Lord, and they are not arrogant."}, {"ayah": 16, "translit": "Tatajaafaa junoobuhum 'anil madaaji'i yad'oona rabbahum khawfanw wa tama'anw wa mimmaa razaqnaahum yunfiqoon", "translation": "They arise from [their] beds; they supplicate their Lord in fear and aspiration, and from what We have provided them, they spend."}, {"ayah": 17, "translit": "Falaa ta'lamu nafsum maaa ukhfiya lahum min qurrati a'yunin jazaaa'am bimaa kaanoo ya'maloon", "translation": "And no soul knows what has been hidden for them of comfort for eyes as reward for what they used to do."}, {"ayah": 18, "translit": "Afaman kaana mu'minan kaman kaana faasiqaa; laa yasta woon", "translation": "Then is one who was a believer like one who was defiantly disobedient? They are not equal."}, {"ayah": 19, "translit": "Ammal lazeena aamanoo wa 'amilus saalihaati falahum jannaatul maawa nuzulam bimaa kaanoo ya'maloon", "translation": "As for those who believed and did righteous deeds, for them will be the Gardens of Refuge as accommodation for what they used to do."}, {"ayah": 20, "translit": "Wa ammal lazeena fasaqoo famaawaahumn Naaru kullamaaa araadooo any yakhrujoo minhaaa u'eedoo feehaa wa qeela lahum zooqoo 'zaaaban Naaril lazee kuntum bihee tukazziboon", "translation": "But as for those who defiantly disobeyed, their refuge is the Fire. Every time they wish to emerge from it, they will be returned to it while it is said to them, \"Taste the punishment of the Fire which you used to deny.\""}, {"ayah": 21, "translit": "Wa lanuzeeqan nahum minal 'azaabil ladnaa doonal 'azaabil akbari la'allahum yarji'oon", "translation": "And we will surely let them taste the nearer punishment short of the greater punishment that perhaps they will repent."}, {"ayah": 22, "translit": "Wa man azlamu mimman zukkira bi aayaati rabbihee summa a'rada 'anhaa; innaa minal mujrimeena muntaqimmon", "translation": "And who is more unjust than one who is reminded of the verses of his Lord; then he turns away from them? Indeed We, from the criminals, will take retribution."}, {"ayah": 23, "translit": "Wa laqad aayainaa Moosal Kitaaba falaa takun fee miryatim mil liqaaa'ihee wa ja'alnaahu hudal li Baneee Israaa'eel", "translation": "And We certainly gave Moses the Scripture, so do not be in doubt over his meeting. And we made the Torah guidance for the Children of Israel."}, {"ayah": 24, "translit": "Wa ja'alnaa minhum a'immatany yahdoona bi amrinaa lammaa sabaroo wa kaanoo bi aayaatinaa yooqinoon", "translation": "And We made from among them leaders guiding by Our command when they were patient and [when] they were certain of Our signs."}, {"ayah": 25, "translit": "Inna rabbaka huwa yafsilu bainahum yawmal qiyaamati feemaa kaanoo feehi yakhtalifoon", "translation": "Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ."}, {"ayah": 26, "translit": "Awalam yahdi lahum kam ahlaknaa min qablihim minal qurooni yamshoona fee masaakinihim; inna fee zaalika la aayaatin afalaa yasma'oon", "translation": "Has it not become clear to them how many generations We destroyed before them, [as] they walk among their dwellings? Indeed in that are signs; then do they not hear?"}, {"ayah": 27, "translit": "Awalam yaraw annaa nasooqul maaa'a ilal lardil juruzi fanukhriju bihee zar'an taakulu minhu an'aamuhum wa anfusuhum afalaa yubsiroon", "translation": "Have they not seen that We drive the water [in clouds] to barren land and bring forth thereby crops from which their livestock eat and [they] themselves? Then do they not see?"}, {"ayah": 28, "translit": "Wa yaqooloona mataa haazal fat hu in kuntum saadiqeen", "translation": "And they say, \"When will be this conquest, if you should be truthful?\""}, {"ayah": 29, "translit": "Qul yawmal fat hi laa yanfa'ul lazeena kafarooo eemaanuhum wa laa hum yunzaroon", "translation": "Say, [O Muhammad], \"On the Day of Conquest the belief of those who had disbelieved will not benefit them, nor will they be reprieved.\""}, {"ayah": 30, "translit": "Fa a'rid 'anhum wantazir innahum muntazirron", "translation": "So turn away from them and wait. Indeed, they are waiting."}]}, {"num": 33, "name": "Al-Ahzab", "meaning": "The Combined Forces", "verses": [{"ayah": 1, "translit": "Yaa aiyuhan Nabiyyut taqil laaha wa laa tuti'il kaafireena wal munaafiqeen; innal laaha kaana 'aleeman Hakeemaa", "translation": "O Prophet, fear Allah and do not obey the disbelievers and the hypocrites. Indeed, Allah is ever Knowing and Wise."}, {"ayah": 2, "translit": "Wattabi' maa yoohaaa ilaika mir Rabbik; innal laaha kaana bimaa ta'maloona Khabeera", "translation": "And follow that which is revealed to you from your Lord. Indeed Allah is ever, with what you do, Acquainted."}, {"ayah": 3, "translit": "Wa tawakkal 'alal laah; wa kafaa billaahi Wakeelaa", "translation": "And rely upon Allah; and sufficient is Allah as Disposer of affairs."}, {"ayah": 4, "translit": "Maa ja'alal laahu lirajulim min qalbaini fee jawfih; wa maa ja'ala azwaajakumul laaa'ee tuzaahiroona minhunna ummahaatikum; wa maa ja'ala ad'iyaaa'akum abnaaa'akum; zaalikum qawlukum bi afwaa hikum wallaahu yaqoolul haqqa wa Huwa yahdis sabeel", "translation": "Allah has not made for a man two hearts in his interior. And He has not made your wives whom you declare unlawful your mothers. And he has not made your adopted sons your [true] sons. That is [merely] your saying by your mouths, but Allah says the truth, and He guides to the [right] way."}, {"ayah": 5, "translit": "Ud'oohum li aabaaa'ihim huwa aqsatu 'indal laah; fa illam ta'lamooo aabaaa'ahum fa ikhwaanukum fid deeni wa mawaaleekum; wa laisa 'alaikum junaahun feemaaa akhtaatum bihee wa laakim maa ta'ammadat quloobukum; wa kaanal laahu Ghafoorar Raheemaa", "translation": "Call them by [the names of] their fathers; it is more just in the sight of Allah. But if you do not know their fathers - then they are [still] your brothers in religion and those entrusted to you. And there is no blame upon you for that in which you have erred but [only for] what your hearts intended. And ever is Allah Forgiving and Merciful."}, {"ayah": 6, "translit": "An-Nabiyyu awlaa bil mu'mineena min anfusihim wa azwaajuhoo ummahatuhum wa ulul arbaami ba'duhum awlaa biba'din fee Kitaabil laahi minal mu'meneena wal Muhaajireena illaaa an taf'alooo ilaaa awliyaaa'ikum ma'roofaa; kaana zaalika fil kitaabi mastooraa", "translation": "The Prophet is more worthy of the believers than themselves, and his wives are [in the position of] their mothers. And those of [blood] relationship are more entitled [to inheritance] in the decree of Allah than the [other] believers and the emigrants, except that you may do to your close associates a kindness [through bequest]. That was in the Book inscribed."}, {"ayah": 7, "translit": "Wa iz akhaznaa minan Nabiyyeena meesaaqahum wa minka wa min Noohinw wa Ibraaheema wa Moosaa wa Eesab-ni-Maryama wa akhaznaa minhum meesaaqan ghaleezaa", "translation": "And [mention, O Muhammad], when We took from the prophets their covenant and from you and from Noah and Abraham and Moses and Jesus, the son of Mary; and We took from them a solemn covenant."}, {"ayah": 8, "translit": "Liyas'alas saadiqeena 'an sidqihim; wa a'adda lilkaa fireena 'azaaban aleemaa", "translation": "That He may question the truthful about their truth. And He has prepared for the disbelievers a painful punishment."}, {"ayah": 9, "translit": "Yaaa aiyuhal lazeena aamanuz kuroo ni'matal laahi 'alaikum iz jaaa'atkm junoodun fa arsalnaa 'alaihim reehanw wa junoodal lam tarawhaa; wa kaanal laahu bimaa ta'maloona Baseera", "translation": "O you who have believed, remember the favor of Allah upon you when armies came to [attack] you and We sent upon them a wind and armies [of angels] you did not see. And ever is Allah, of what you do, Seeing."}, {"ayah": 10, "translit": "Iz jaaa'ookum min fawqikum wa min asfala minkum wa iz zaaghatil absaaru wa balaghatil quloobul hanaajira wa tazunnoona billaahiz zunoonaa", "translation": "[Remember] when they came at you from above you and from below you, and when eyes shifted [in fear], and hearts reached the throats and you assumed about Allah [various] assumptions."}, {"ayah": 11, "translit": "Hunaalikab tuliyal mu'minoona wa zulziloo zilzaalan shadeedaa", "translation": "There the believers were tested and shaken with a severe shaking."}, {"ayah": 12, "translit": "Wa iz yaqoolul munaafiqoona wallazeena fee quloobihim maradum maa wa'adanal laahu wa Rasooluhooo illaa ghurooraa", "translation": "And [remember] when the hypocrites and those in whose hearts is disease said, \"Allah and His Messenger did not promise us except delusion,\""}, {"ayah": 13, "translit": "Wa iz qaalat taaa'ifatum minhum yaaa ahla Yasriba laa muqaamaa lakum farji'oo; wa yastaazina fareequm minhumun Nabiyya yaqooloona inna buyootanaa 'awrah; wa maa hiya bi'awratin iny yureedoona illaa firaaraa", "translation": "And when a faction of them said, \"O people of Yathrib, there is no stability for you [here], so return [home].\" And a party of them asked permission of the Prophet, saying, \"Indeed, our houses are unprotected,\" while they were not exposed. They did not intend except to flee."}, {"ayah": 14, "translit": "wa law dukhilat 'alaihim min aqtaarihaa summa su'ilul fitnata la aatawhaa wa maa talabbasoo bihaaa illaa yaseeraa", "translation": "And if they had been entered upon from all its [surrounding] regions and fitnah had been demanded of them, they would have done it and not hesitated over it except briefly."}, {"ayah": 15, "translit": "Wa laqad kaanoo 'aahadul laaha min qablu laa yuwal loonal adbaar; wa kaana 'ahdul laahi mas'oolaa", "translation": "And they had already promised Allah before not to turn their backs and flee. And ever is the promise to Allah [that about which one will be] questioned."}, {"ayah": 16, "translit": "Qul lany y anfa'akumul firaaru in farartum minal mawti awil qatli wa izal laa tumatta'oona illaa qaleelaa", "translation": "Say, [O Muhammad], \"Never will fleeing benefit you if you should flee from death or killing; and then [if you did], you would not be given enjoyment [of life] except for a little.\""}, {"ayah": 17, "translit": "Qul m an zal lazee ya'simukum minal laahi in araada bikum sooo'an aw araada bikum rahmah; wa laa yajidoona lahum min doonil laahi waliyyanw wa laa naseeraa", "translation": "Say, \"Who is it that can protect you from Allah if He intends for you an ill or intends for you a mercy?\" And they will not find for themselves besides Allah any protector or any helper."}, {"ayah": 18, "translit": "Qad ya'lamul laahul mu'awwiqeena minkum walqaaa'ileena li ikhwaanihim hahumma ilainaa, wa laa yaatoonal baasa illaa qaleelaa", "translation": "Already Allah knows the hinderers among you and those [hypocrites] who say to their brothers, \"Come to us,\" and do not go to battle, except for a few,"}, {"ayah": 19, "translit": "Ashihhatan 'alaikum faizaa jaaa'al khawfu ra aytahum yanzuroona ilaika tadooru a'yunuhum kallazee yughshaa 'alaihi minal mawti fa izaa zahabal khawfu salqookum bi alsinatin hidaadin ashibbatan 'alal khayr; ulaaa'ika lam yu'minoo fa ahbatal laahu a'maalahum; wa kaana zaalika 'alal laahi yaseeraa", "translation": "Indisposed toward you. And when fear comes, you see them looking at you, their eyes revolving like one being overcome by death. But when fear departs, they lash you with sharp tongues, indisposed toward [any] good. Those have not believed, so Allah has rendered their deeds worthless, and ever is that, for Allah, easy."}, {"ayah": 20, "translit": "Yahsaboonal  Ahzaaba lam yazhaboo wa iny yaatil Ahzaabu yawaddoo law annahum baadoona fil A'raabi yasaloona 'an ambaaa'ikum wa law kaanoo feekum maa qaatalooo illaa qaleela", "translation": "They think the companies have not [yet] withdrawn. And if the companies should come [again], they would wish they were in the desert among the bedouins, inquiring [from afar] about your news. And if they should be among you, they would not fight except for a little."}, {"ayah": 21, "translit": "Laqad kaana lakum fee Rasoolil laahi uswatun hasanatul liman kaana yarjul laaha wal yawmal Aakhira wa azkaral laaha kaseeraa", "translation": "There has certainly been for you in the Messenger of Allah an excellent pattern for anyone whose hope is in Allah and the Last Day and [who] remembers Allah often."}, {"ayah": 22, "translit": "Wa lammaa ra al mu'minoonal Ahzaaba qaaloo haaza maa wa'adanal laahu wa Rasooluh; wa maa zaadahum illaaa eemaananw wa tasleemaa", "translation": "And when the believers saw the companies, they said, \"This is what Allah and His Messenger had promised us, and Allah and His Messenger spoke the truth.\" And it increased them only in faith and acceptance."}, {"ayah": 23, "translit": "Minal mu'mineena rijaalun sadaqoo maa 'aahadul laaha 'alaihi faminhum man qadaa nahbahoo wa minhum mai yantaziru wa maa baddaloo tabdeelaa", "translation": "Among the believers are men true to what they promised Allah. Among them is he who has fulfilled his vow [to the death], and among them is he who awaits [his chance]. And they did not alter [the terms of their commitment] by any alteration -"}, {"ayah": 24, "translit": "Li yajziyal aahus saadiqeena bisidqihim wa yu'azzibal munaafiqeena in shaaa'a aw yatooba 'alaihim; innal laaha kaana Ghafoorar Raheemaa", "translation": "That Allah may reward the truthful for their truth and punish the hypocrites if He wills or accept their repentance. Indeed, Allah is ever Forgiving and Merciful."}, {"ayah": 25, "translit": "Wa raddal laahul lazeena kafaroo bighaizihim lam yanaaloo khairaa; wa kafal laahul mu'mineenal qitaal; wa kaanal laahu Qawiyyan 'Azeezaa", "translation": "And Allah repelled those who disbelieved, in their rage, not having obtained any good. And sufficient was Allah for the believers in battle, and ever is Allah Powerful and Exalted in Might."}, {"ayah": 26, "translit": "Wa anzalal lazeena zaaha roohum min Ahlil Kitaabi min sa yaaseehim wa qazafa fee quloobihimm mur ru'ba freeqan taqtuloona wa taasiroona fareeqaaa", "translation": "And He brought down those who supported them among the People of the Scripture from their fortresses and cast terror into their hearts [so that] a party you killed, and you took captive a party."}, {"ayah": 27, "translit": "Wa awrasakum ardahum wa diyaarahum wa amwaalahum wa ardal lam tata'oohaa; wa kaanal laahu 'alaa kulli shai'in Qadeeraa", "translation": "And He caused you to inherit their land and their homes and their properties and a land which you have not trodden. And ever is Allah, over all things, competent."}, {"ayah": 28, "translit": "Yaaa aiyuhan Nabiyyu qul li azwaajika i kuntunna turidnal hayaatad dunyaa wa zeenatahaa fata'aalaina umatti'kunna wa usarrihkunna saraahan jameela", "translation": "O Prophet, say to your wives, \"If you should desire the worldly life and its adornment, then come, I will provide for you and give you a gracious release."}, {"ayah": 29, "translit": "Wa in kuntunna turidnal laaha wa Rasoolahoo wad Daaral Aakhirata fa innal laaha a'adda lil muhsinaati min kunna ajjran 'azeemaa", "translation": "But if you should desire Allah and His Messenger and the home of the Hereafter - then indeed, Allah has prepared for the doers of good among you a great reward.\""}, {"ayah": 30, "translit": "Yaa nisaaa'an Nabiyyi mai yaati minkunna bifaa hishatim mubaiyinatiny yudaa'af lahal 'azaabu di'fain wa kaana zaalika 'alal laahi yaseera", "translation": "O wives of the Prophet, whoever of you should commit a clear immorality - for her the punishment would be doubled two fold, and ever is that, for Allah, easy."}, {"ayah": 31, "translit": "Wa mai yaqnut minkunna lillaahi wa Rasoolihee wa ta'mal saalihan nu'tihaaa ajrahaa marratayni wa a'tadnaa lahaa rizqan kareema", "translation": "And whoever of you devoutly obeys Allah and His Messenger and does righteousness - We will give her her reward twice; and We have prepared for her a noble provision."}, {"ayah": 32, "translit": "Yaa nisaaa'an Nabiyyi lastunna ka ahadim minan nisaaa'i init taqaitunna falaa takhda'na bilqawli fa yatma'al lazee fee qalbihee maradunw wa qulna qawlam ma'roofaa", "translation": "O wives of the Prophet, you are not like anyone among women. If you fear Allah, then do not be soft in speech [to men], lest he in whose heart is disease should covet, but speak with appropriate speech."}, {"ayah": 33, "translit": "Wa qarna fee bu yoo tikunna wa laa tabarrajna tabarrujal Jaahiliyyatil oolaa wa aqimnas Salaata w aaateenaz Zakaata wa ati'nal laaha wa Rasoolah; innamaa yureedul laahu liyuzhiba 'ankumur rijsa Ahlal Bayti wa yutahhirakum tatheeraa", "translation": "And abide in your houses and do not display yourselves as [was] the display of the former times of ignorance. And establish prayer and give zakah and obey Allah and His Messenger. Allah intends only to remove from you the impurity [of sin], O people of the [Prophet's] household, and to purify you with [extensive] purification."}, {"ayah": 34, "translit": "Wazkurna maa yutlaa fee bu yootikunna min aayaatil laahi wal Hikmah; innal laaha kaana lateefan Khabeera", "translation": "And remember what is recited in your houses of the verses of Allah and wisdom. Indeed, Allah is ever Subtle and Acquainted [with all things]."}, {"ayah": 35, "translit": "Innal muslimeena wal muslimaati wal mu'mineena wal mu'minaati walqaaniteena walqaanitaati wassaadiqeena wassaadiqaati wassaabireena wassaabiraati walkhaashi'eena walkhaashi'aati walmutasaddiqeena walmutasaddiqaati wassaaa'imeena wassaaa'imaati walhaafizeena furoojahum walhaafizaati waz zaakireenal laaha kaseeranw waz zaakiraati a'addal laahu lahum maghfiratanw wa ajran 'azeemaa", "translation": "Indeed, the Muslim men and Muslim women, the believing men and believing women, the obedient men and obedient women, the truthful men and truthful women, the patient men and patient women, the humble men and humble women, the charitable men and charitable women, the fasting men and fasting women, the men who guard their private parts and the women who do so, and the men who remember Allah often and the women who do so - for them Allah has prepared forgiveness and a great reward."}, {"ayah": 36, "translit": "Wa maa kaana limu'mininw wa laa mu'minatin izaa qadal laahu wa Rasooluhooo amran ai yakoona lahumul khiyaratu min amrihim; wa mai ya'sil laaha wa Rasoolahoo faqad dalla dalaalam mubeenaa", "translation": "It is not for a believing man or a believing woman, when Allah and His Messenger have decided a matter, that they should [thereafter] have any choice about their affair. And whoever disobeys Allah and His Messenger has certainly strayed into clear error."}, {"ayah": 37, "translit": "Wa iz taqoolu lillazeee an'amal laahu 'alaihi wa an'amta 'alaihi amsik 'alaika zawjaka wattaqil laaha wa tukhfee fee nafsika mal laahu mubdeehi wa takhshan naasa wallaahu ahaqqu an takhshaah; falammaa qadaa Zaidum minhaa wataran zawwajnaa kahaa likay laa yakoona 'alal mu'mineena harajun feee azwaaji ad'iyaaa'ihim izaa qadaw minhunna wataraa; wa kaana amrul laahi af'oolaa", "translation": "And [remember, O Muhammad], when you said to the one on whom Allah bestowed favor and you bestowed favor, \"Keep your wife and fear Allah,\" while you concealed within yourself that which Allah is to disclose. And you feared the people, while Allah has more right that you fear Him. So when Zayd had no longer any need for her, We married her to you in order that there not be upon the believers any discomfort concerning the wives of their adopted sons when they no longer have need of them. And ever is the command of Allah accomplished."}, {"ayah": 38, "translit": "Maa kaana 'alan nabiyyyi min harajin feemaa faradal laahu lahoo sunnatal laahi fil lazeena khalaw min qabl; wa kaana amrul laahi qadaram maqdooraa", "translation": "There is not to be upon the Prophet any discomfort concerning that which Allah has imposed upon him. [This is] the established way of Allah with those [prophets] who have passed on before. And ever is the command of Allah a destiny decreed."}, {"ayah": 39, "translit": "Allazeena yuballighoona Risaalaatil laahi wa yakhshaw nahoo wa laa yakkhshawna ahadan illal laah; wa kafaa billaahi Haseebaa", "translation": "[Allah praises] those who convey the messages of Allah and fear Him and do not fear anyone but Allah. And sufficient is Allah as Accountant."}, {"ayah": 40, "translit": "Maa kaana Muhammmadun abaaa ahadim mir rijaalikum wa laakir Rasoolal laahi wa Khaataman Nabiyyeen; wa kaanal laahu bikulli shai'in 'Aleema", "translation": "Muhammad is not the father of [any] one of your men, but [he is] the Messenger of Allah and last of the prophets. And ever is Allah, of all things, Knowing."}, {"ayah": 41, "translit": "Yaaa aiyuhal lazeena aamanuz kurul laaha zikran kaseera", "translation": "O you who have believed, remember Allah with much remembrance"}, {"ayah": 42, "translit": "Wa sabbihoohu bukratanw wa aseela", "translation": "And exalt Him morning and afternoon."}, {"ayah": 43, "translit": "Huwal lazee yusallee 'alaikum wa malaaa'ikatuhoo liyukhrijakum minazzulumaati ilan-noor wa kaana bilmu'mineena Raheemaa", "translation": "It is He who confers blessing upon you, and His angels [ask Him to do so] that He may bring you out from darknesses into the light. And ever is He, to the believers, Merciful."}, {"ayah": 44, "translit": "Tahiyyatuhum Yawma yalqawnahoo salaamunw wa a'adda lahum ajran kareemaa", "translation": "Their greeting the Day they meet Him will be, \"Peace.\" And He has prepared for them a noble reward."}, {"ayah": 45, "translit": "Yaaa aiyuhan Nabiyyu innaaa arsalnaaka shaahidanw wa mubashshiranw wa nazeeraa", "translation": "O Prophet, indeed We have sent you as a witness and a bringer of good tidings and a warner."}, {"ayah": 46, "translit": "Wa daa'iyan ilal laahi bi iznihee wa siraajam muneeraa", "translation": "And one who invites to Allah, by His permission, and an illuminating lamp."}, {"ayah": 47, "translit": "Wa bashshiril mu'mineena bi annna lahum minal laahi fadlan kabeera", "translation": "And give good tidings to the believers that they will have from Allah great bounty."}, {"ayah": 48, "translit": "Wa laa tuti'il kaafireena walmunaafiqeena wa da'azaahum wa tawakkal 'alallaah; wa kafaa billaahi Wakeelaa", "translation": "And do not obey the disbelievers and the hypocrites but do not harm them, and rely upon Allah. And sufficient is Allah as Disposer of affairs."}, {"ayah": 49, "translit": "Yaaa aiyuhal lazeena aamanooo izaa nakahtumul mu'minaati summa tallaqtu moohunna min qabli an tamas soohunna famaa lakum 'alaihinna min 'iddatin ta'taddoonahaa famatti'oohunna wa sarri hoohunna saraahan jameelaa", "translation": "O You who have believed, when you marry believing women and then divorce them before you have touched them, then there is not for you any waiting period to count concerning them. So provide for them and give them a gracious release."}, {"ayah": 50, "translit": "Yaaa aiyuhan Nabiyyu innaaa ahlalnaa laka azwaa jakal laatee aayaita ujoora hunna wa maa malakat yameenuka mimmaaa afaaa'al laahu 'alaika wa banaati 'ammika wa banaati 'ammaatika wa banaati khaalika wa banaati khaalaa tikal laatee haajarna ma'aka wamra atam mu'minatan inw wahabat nafsahaa lin Nabiyyi in araadan Nabiyyu ai yastan kihahaa khaalisatal laka min doonil mu'mineen; qad 'alim naa maa faradnaa 'alaihim feee azwaajihim wa maa malakat aimaanuhum likailaa yakoona 'alaika haraj; wa kaanal laahu Ghafoorar Raheema", "translation": "O Prophet, indeed We have made lawful to you your wives to whom you have given their due compensation and those your right hand possesses from what Allah has returned to you [of captives] and the daughters of your paternal uncles and the daughters of your paternal aunts and the daughters of your maternal uncles and the daughters of your maternal aunts who emigrated with you and a believing woman if she gives herself to the Prophet [and] if the Prophet wishes to marry her, [this is] only for you, excluding the [other] believers. We certainly know what We have made obligatory upon them concerning their wives and those their right hands possess, [but this is for you] in order that there will be upon you no discomfort. And ever is Allah Forgiving and Merciful."}, {"ayah": 51, "translit": "Turjee man tashaaa'u minhunna wa tu'weee ilaika man tashaaa'u wa manibta ghaita mimman 'azalta falaa junaaha 'alaik; zaalika adnaaa an taqarra a'yunuhunna wa laa yahzanna wa yardaina bimaa aataitahunna kulluhunn; wal laahu ya'lamu maa fee quloo bikum; wa kaanal laahu 'Aleeman haleemaa", "translation": "You, [O Muhammad], may put aside whom you will of them or take to yourself whom you will. And any that you desire of those [wives] from whom you had [temporarily] separated - there is no blame upon you [in returning her]. That is more suitable that they should be content and not grieve and that they should be satisfied with what you have given them - all of them. And Allah knows what is in your hearts. And ever is Allah Knowing and Forbearing."}, {"ayah": 52, "translit": "Laa yahillu lakan nisaaa'u mim ba'du wa laaa an tabaddala bihinna min azwaajinw wa law ajabaka husnuhunna illaa maa malakat yameenukk; wa kaanal laahu 'alaa kulli shai'ir Raqeeba", "translation": "Not lawful to you, [O Muhammad], are [any additional] women after [this], nor [is it] for you to exchange them for [other] wives, even if their beauty were to please you, except what your right hand possesses. And ever is Allah, over all things, an Observer."}, {"ayah": 53, "translit": "Yaaa aiyuhal lazeena aamanoo laa tadkhuloo bu yootan Nabiyyi ilaaa ai yu'zana lakum ilaa ta'aamin ghaira naazireena inaahu wa laakin izaa du'eetum fadkhuloo fa izaa ta'imtum fantashiroo wa laa mustaaniseena lihadees; inna zaalikum kaana yu'zin Nabiyya fa yastahyee minkum wallaahu laa yastahyee minal haqq; wa izaa sa altumoohunna mataa'an fas'aloohunna minw waraaa'i hijaab; zaalikum atharu liquloobikum wa quloobihinn; wa maa kaana lakum an tu'zoo Rasoolal laahi wa laaa an tankihooo azwaajahoo mim ba'diheee abadaa; inna zaalikum kaana 'indal laahi 'azeema", "translation": "O you who have believed, do not enter the houses of the Prophet except when you are permitted for a meal, without awaiting its readiness. But when you are invited, then enter; and when you have eaten, disperse without seeking to remain for conversation. Indeed, that [behavior] was troubling the Prophet, and he is shy of [dismissing] you. But Allah is not shy of the truth. And when you ask [his wives] for something, ask them from behind a partition. That is purer for your hearts and their hearts. And it is not [conceivable or lawful] for you to harm the Messenger of Allah or to marry his wives after him, ever. Indeed, that would be in the sight of Allah an enormity."}, {"ayah": 54, "translit": "In tubdoo shai'an aw tukhfoohu fa innal laaha kaana bikulli shai'in 'Aleemaa", "translation": "Whether you reveal a thing or conceal it, indeed Allah is ever, of all things, Knowing."}, {"ayah": 55, "translit": "Laa junaaha 'alaihinna feee aabaaa'ihinna wa laaa abnaaa'ihinna wa laaa ikhwaanihinnna wa laaa abnaaa'i ikhwaanihinna wa laaa abnaaa'i akhawaatihinna wa laa nisaaa'i hinna wa laa Maa malakat aimaanuhunn; wattaqeenal laah; innal laaha kaana 'alaa kulli shai'in Shaheedaa", "translation": "There is no blame upon women concerning their fathers or their sons or their brothers or their brothers' sons or their sisters' sons or their women or those their right hands possess. And fear Allah. Indeed Allah is ever, over all things, Witness."}, {"ayah": 56, "translit": "Innal laaha wa malaaa'i katahoo yusalloona 'alan Nabiyy; yaaa aiyuhal lazeena aamanoo salloo 'alaihi wa sallimoo tasleemaa", "translation": "Indeed, Allah confers blessing upon the Prophet, and His angels [ask Him to do so]. O you who have believed, ask [Allah to confer] blessing upon him and ask [Allah to grant him] peace."}, {"ayah": 57, "translit": "Innal lazeena yu'zoonal laaha wa Rasoolahoo la'anahumul laahu fid dunyaa wal Aakhirati wa a'adda lahum 'azaabam muheenaa", "translation": "Indeed, those who abuse Allah and His Messenger - Allah has cursed them in this world and the Hereafter and prepared for them a humiliating punishment."}, {"ayah": 58, "translit": "Wallazeena yu'zoonal mu'mineena almu'manaati bighairi mak tasaboo faqadih tamaloo buhtaananw wa ismam mubeenaa", "translation": "And those who harm believing men and believing women for [something] other than what they have earned have certainly born upon themselves a slander and manifest sin."}, {"ayah": 59, "translit": "Yaaa aiyuhan Nabiyyu qul li azwaajika wa banaatika wa nisaaa'il mu'mineena yudneena 'alaihinna min jalaabee bihinn; zaalika adnaaa ai yu'rafna falaa yu'zain; wa kaanal laahu Ghafoorar Raheemaa", "translation": "O Prophet, tell your wives and your daughters and the women of the believers to bring down over themselves [part] of their outer garments. That is more suitable that they will be known and not be abused. And ever is Allah Forgiving and Merciful."}, {"ayah": 60, "translit": "La'il lam yantahil munaafiqoona wallazeena fee quloobihim maradunw walmur jifoona fil madeenati lanughri yannaka bihim summa laa yujaawiroonaka feehaaa illaa qaleela", "translation": "If the hypocrites and those in whose hearts is disease and those who spread rumors in al-Madinah do not cease, We will surely incite you against them; then they will not remain your neighbors therein except for a little."}, {"ayah": 61, "translit": "Mal'ooneena ainamaa suqifoo ukhizoo wa quttiloo taqteelaa", "translation": "Accursed wherever they are found, [being] seized and massacred completely."}, {"ayah": 62, "translit": "Sunnatal laahi fil lazeena khalaw min qablu wa lan tajida lisunnatil laahi tabdeelaa", "translation": "[This is] the established way of Allah with those who passed on before; and you will not find in the way of Allah any change."}, {"ayah": 63, "translit": "Yas'alukan naasu 'anis Saa'ati qul innamaa 'ilmuhaa 'indal laah; wa maa yudreeka la'allas Saa'ata takoonu qareebaa", "translation": "People ask you concerning the Hour. Say,\" Knowledge of it is only with Allah. And what may make you perceive? Perhaps the Hour is near.\""}, {"ayah": 64, "translit": "Innal laaha la'anal kaafireena wa a'adda lahum sa'eeraa", "translation": "Indeed, Allah has cursed the disbelievers and prepared for them a Blaze."}, {"ayah": 65, "translit": "Khaalideena feehaaa abadaa, laa yajidoona waliyyanw wa laa naseeraa", "translation": "Abiding therein forever, they will not find a protector or a helper."}, {"ayah": 66, "translit": "Yawma tuqallabu wujoohuhum fin Naari yaqooloona yaa laitanaaa ata'nal laaha wa ata'nar Rasoolaa", "translation": "The Day their faces will be turned about in the Fire, they will say, \"How we wish we had obeyed Allah and obeyed the Messenger.\""}, {"ayah": 67, "translit": "Wa qaaloo Rabbanaaa innaaa ata'naa saadatanaa wa kubaraaa'anaa fa adalloonas sabeelaa", "translation": "And they will say, \"Our Lord, indeed we obeyed our masters and our dignitaries, and they led us astray from the [right] way."}, {"ayah": 68, "translit": "Rabbanaaa aatihim di'fai ni minal 'azaabi wal'anhum la nan kabeera", "translation": "Our Lord, give them double the punishment and curse them with a great curse.\""}, {"ayah": 69, "translit": "yaa aiyuhal lazeena aamanoo las takoonoo kalla zeena aazaw Moosaa fa barra ahul laahu mimmmaa qaaloo; wa kaana 'indal laahi wajeehaa", "translation": "O you who have believed, be not like those who abused Moses; then Allah cleared him of what they said. And he, in the sight of Allah, was distinguished."}, {"ayah": 70, "translit": "Yaaa aiyuhal lazeena aamanut taqul laaha wa qooloo qawlan sadeedaa", "translation": "O you who have believed, fear Allah and speak words of appropriate justice."}, {"ayah": 71, "translit": "Yuslih lakum a'maalakum wa yaghfir lakum zunoobakum; wa mai yuti'il laaha wa Rasoolahoo faqad faaza fawzan 'azeemaa", "translation": "He will [then] amend for you your deeds and forgive you your sins. And whoever obeys Allah and His Messenger has certainly attained a great attainment."}, {"ayah": 72, "translit": "Innaa 'aradnal amaanata 'alas samaawaati walardi wal jibaali fa abaina ai yahmil nahaa wa ashfaqna minhaa wa hamalahal insaanu innahoo kaana zalooman jahoolaa", "translation": "Indeed, we offered the Trust to the heavens and the earth and the mountains, and they declined to bear it and feared it; but man [undertook to] bear it. Indeed, he was unjust and ignorant."}, {"ayah": 73, "translit": "Liyu 'azzibal laahul munaafiqeena wal munaafiqaati walmushrikeena wal mushrikaati wa yatoobal laahu 'alal mu'mineena walmu'minaat; wa kaanal laahu Ghafoorar Raheema", "translation": "[It was] so that Allah may punish the hypocrite men and hypocrite women and the men and women who associate others with Him and that Allah may accept repentance from the believing men and believing women. And ever is Allah Forgiving and Merciful."}]}, {"num": 34, "name": "Saba", "meaning": "Sheba", "verses": [{"ayah": 1, "translit": "Alhamdu lillaahil lazee lahoo maa fis samaawaati wa maa fil ardi wa lahul hamdu fil aakhirah; wa Huwal Hakeemul Khabeer", "translation": "[All] praise is [due] to Allah, to whom belongs whatever is in the heavens and whatever is in the earth, and to Him belongs [all] praise in the Hereafter. And He is the Wise, the Acquainted."}, {"ayah": 2, "translit": "Ya'lamu maa yaliju fil ardi wa maa yakhruju minhaa wa maa yanzilu minas samaaa'i wa maa ya'ruju feehaa; wa Huwar Raheemul Ghafoor", "translation": "He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein. And He is the Merciful, the Forgiving."}, {"ayah": 3, "translit": "Wa qaalal lazeena kafaroo laa taateenas Saa'ah; qul balaa wa Rabbee lataatiyannakum 'Aalimul Ghaib; laa ya'zubu 'anhu misqaalu zarratin fis samaawaati wa laa fil ardi wa laaa asgharu min zaalika wa laaa akbaru illaa fee kitaabim mubeen", "translation": "But those who disbelieve say, \"The Hour will not come to us.\" Say, \"Yes, by my Lord, it will surely come to you. [Allah is] the Knower of the unseen.\" Not absent from Him is an atom's weight within the heavens or within the earth or [what is] smaller than that or greater, except that it is in a clear register -"}, {"ayah": 4, "translit": "Liyajziyal lazeena aamanoo wa 'amilus saalihaat; ulaaa'ika lahum maghfiratunw wa rizqun kareem", "translation": "That He may reward those who believe and do righteous deeds. Those will have forgiveness and noble provision."}, {"ayah": 5, "translit": "Wallazeena sa'aw feee aayaatinaa mu'aajizeena ulaaa 'ika lahum 'azaabum mir irjzin aleem", "translation": "But those who strive against Our verses [seeking] to cause failure - for them will be a painful punishment of foul nature."}, {"ayah": 6, "translit": "Wa yaral lazeena utul 'Ilmal lazeee unzila ilaika mir Rabbika huwal haqqa wa yahdeee ilaaa siraatil 'Azeezil Hameed", "translation": "And those who have been given knowledge see that what is revealed to you from your Lord is the truth, and it guides to the path of the Exalted in Might, the Praiseworthy."}, {"ayah": 7, "translit": "Wa qaalal lazeena kafaroo hal nadullukum 'alaa rajuliny yanabbi 'ukum izaa muzziqtum kulla mumazzaqin innakum lafee khalqin jadeed", "translation": "But those who disbelieve say, \"Shall we direct you to a man who will inform you [that] when you have disintegrated in complete disintegration, you will [then] be [recreated] in a new creation?"}, {"ayah": 8, "translit": "Aftaraa 'alal laahi kaziban am bihee jinnah; balil lazeena laa yu'minoona bil Aakhirati fil'azaabi waddad laalil ba'eed", "translation": "Has he invented about Allah a lie or is there in him madness?\" Rather, they who do not believe in the Hereafter will be in the punishment and [are in] extreme error."}, {"ayah": 9, "translit": "Afalam yaraw ilaa maa baina aydeehim wa maa khalfahum minas samaaa'i wal ard; in nashad nakhsif bihimul arda aw nusqit 'alaihim kisafam minas samaaa'; inna fee zaalika la Aayatal likulli 'abdim muneeb", "translation": "Then, do they not look at what is before them and what is behind them of the heaven and earth? If We should will, We could cause the earth to swallow them or [could] let fall upon them fragments from the sky. Indeed in that is a sign for every servant turning back [to Allah]."}, {"ayah": 10, "translit": "Wa laqad aatainaa Daawooda minnaa fadlany yaa jibaalu awwibee ma'ahoo wattaira wa alannaa lahul hadeed", "translation": "And We certainly gave David from Us bounty. [We said], \"O mountains, repeat [Our] praises with him, and the birds [as well].\" And We made pliable for him iron,"}, {"ayah": 11, "translit": "Ani'mal saabighaatinw wa qaddir fis sardi wa'maloo saalihan innee bimaa ta'maloona Baseer", "translation": "[Commanding him], \"Make full coats of mail and calculate [precisely] the links, and work [all of you] righteousness. Indeed I, of what you do, am Seeing.\""}, {"ayah": 12, "translit": "Wa li-Sulaimaanar reeha ghuduwwuhaa shahrunw wa ra-waahuhaa shahrunw wa asalnaa lahoo 'ainal qitr; wa minal jinni mai ya'malu baina yadaihi bi izni Rabbih; wa mai yazigh minhum 'an amrinaa nuziqhu min 'azaabis sa'eer", "translation": "And to Solomon [We subjected] the wind - its morning [journey was that of] a month - and its afternoon [journey was that of] a month, and We made flow for him a spring of [liquid] copper. And among the jinn were those who worked for him by the permission of his Lord. And whoever deviated among them from Our command - We will make him taste of the punishment of the Blaze."}, {"ayah": 13, "translit": "Ya'maloona lahoo ma yashaaa'u mim mahaareeba wa tamaaseela wa jifaanin kaljawaabi wa qudoorir raasiyaat; i'maloo aala Daawooda shukraa; wa qaleelum min 'ibaadiyash shakoor", "translation": "They made for him what he willed of elevated chambers, statues, bowls like reservoirs, and stationary kettles. [We said], \"Work, O family of David, in gratitude.\" And few of My servants are grateful."}, {"ayah": 14, "translit": "Falammaa qadainaa 'alaihil mawta ma dallahum 'alaa mawtiheee illaa daaabbatul ardi taakulu minsa atahoo falammaa kharra tabaiyanatil jinnu al law kaanoo ya'lamoonal ghaiba maa labisoo fil 'azaabil muheen", "translation": "And when We decreed for Solomon death, nothing indicated to the jinn his death except a creature of the earth eating his staff. But when he fell, it became clear to the jinn that if they had known the unseen, they would not have remained in humiliating punishment."}, {"ayah": 15, "translit": "Laqad kaana li Saba-in fee maskanihim Aayatun jannataani 'ai yameeninw wa shimaalin kuloo mir rizq Rabbikum washkuroolah; baldatun taiyibatunw wa Rabbun Ghafoor", "translation": "There was for [the tribe of] Saba' in their dwelling place a sign: two [fields of] gardens on the right and on the left. [They were told], \"Eat from the provisions of your Lord and be grateful to Him. A good land [have you], and a forgiving Lord.\""}, {"ayah": 16, "translit": "Fa-a''radoo fa-arsalnaa 'alaihim Sailal 'Arimi wa baddalnaahum bijannataihim jannataini zawaatai ukulin khamtinw wa aslinw wa shai'im min sidrin qaleel", "translation": "But they turned away [refusing], so We sent upon them the flood of the dam, and We replaced their two [fields of] gardens with gardens of bitter fruit, tamarisks and something of sparse lote trees."}, {"ayah": 17, "translit": "Zaalika jazainaahum bimaa kafaroo wa hal nujaazeee illal kafoor", "translation": "[By] that We repaid them because they disbelieved. And do We [thus] repay except the ungrateful?"}, {"ayah": 18, "translit": "Wa ja'alnaa bainahum wa bainal qural latee baaraknaa feehaa quran zaahiratanw wa qaddamaa feehas sayr; seeroo feehaa la yaalirya wa aiyaaman aamineen", "translation": "And We placed between them and the cities which We had blessed [many] visible cities. And We determined between them the [distances of] journey, [saying], \"Travel between them by night or day in safety.\""}, {"ayah": 19, "translit": "Faqaaloo Rabbanaa baa'id baina asfaarinaa wa zalamooo anfusahum faja'alnaahum ahaadeesa wa mazzaq naahum kulla mumazzaq; inna fee zaalika la Aayaatil likulli sabbaarin shakoor", "translation": "But [insolently] they said, \"Our Lord, lengthen the distance between our journeys,\" and wronged themselves, so We made them narrations and dispersed them in total dispersion. Indeed in that are signs for everyone patient and grateful."}, {"ayah": 20, "translit": "Wa laqad saddaq 'alaihim Ibleesu zannnabhoo fattaba'oohu illaa fareeqam minal mu'mineen", "translation": "And Iblees had already confirmed through them his assumption, so they followed him, except for a party of believers."}, {"ayah": 21, "translit": "Wa maa kaana lahoo 'alaihim min sultaanin illaa lina'lama mai yu minu bil Aakhirati mimman huwa minhaa fee shakk; wa Rabbuka 'alaa kulli shai'in Hafeez", "translation": "And he had over them no authority except [it was decreed] that We might make evident who believes in the Hereafter from who is thereof in doubt. And your Lord, over all things, is Guardian."}, {"ayah": 22, "translit": "Qulid 'ul lazeena za'amtum min doonil laahi laa yamlikoona misqaala zarratin fissamaawaati wa laa fil ardi wa maa lahum feehimaa min shirkinw wa maa lahoo minhum min zaheer", "translation": "Say, [O Muhammad], \"Invoke those you claim [as deities] besides Allah.\" They do not possess an atom's weight [of ability] in the heavens or on the earth, and they do not have therein any partnership [with Him], nor is there for Him from among them any assistant."}, {"ayah": 23, "translit": "Wa laa tanfa'ush shafaa'atu 'indahooo illaa liman azina lah; hattaaa izaa fuzzi'a 'an quloobihim qaaloo maazaa qaala Rabbukum; qaalul haqq, wa Huwal 'Aliyul Kabeer", "translation": "And intercession does not benefit with Him except for one whom He permits. [And those wait] until, when terror is removed from their hearts, they will say [to one another], \"What has your Lord said?\" They will say, \"The truth.\" And He is the Most High, the Grand."}, {"ayah": 24, "translit": "Qul mai yarzuqukum minas samaawaati wal ardi qulil laahu wa innaaa aw iyyaakum la'alaa hudan aw fee dalaalim mubeen", "translation": "Say, \"Who provides for you from the heavens and the earth?\" Say, \"Allah. And indeed, we or you are either upon guidance or in clear error.\""}, {"ayah": 25, "translit": "Qul laa tus'aloona 'ammaaa ajramnaa wa laa nus'alu 'ammaa ta'maloon", "translation": "Say, \"You will not be asked about what we committed, and we will not be asked about what you do.\""}, {"ayah": 26, "translit": "Qul yajma'u bainanaa Rabbunaa summa yaftahu bainanaa bilhaqq; wa Huwal Fattaahul 'Aleem", "translation": "Say, \"Our Lord will bring us together; then He will judge between us in truth. And He is the Knowing Judge.\""}, {"ayah": 27, "translit": "Qul arooniyal lazeena alhaqtum bihee shurakaaa'a kallaa; bal Huwal Laahul 'Azeezul Hakeem", "translation": "Say, \"Show me those whom you have attached to Him as partners. No! Rather, He [alone] is Allah, the Exalted in Might, the Wise.\""}, {"ayah": 28, "translit": "Wa maaa arsalnaaka illaa kaaffatal linnaasi basheeranw wa nazeeranw wa laakinna aksaran naasi laa ya'lamoon", "translation": "And We have not sent you except comprehensively to mankind as a bringer of good tidings and a warner. But most of the people do not know."}, {"ayah": 29, "translit": "Wa yaqooloona mataa haazal wa'du in kuntum saadiqeen", "translation": "And they say, \"When is this promise, if you should be truthful?\""}, {"ayah": 30, "translit": "Qul lakum mee'aadu Yawmil laa tastaakhiroona 'anhu saa'atanw wa la tastaqdimoon", "translation": "Say, \"For you is the appointment of a Day [when] you will not remain thereafter an hour, nor will you precede [it].\""}, {"ayah": 31, "translit": "Wa qaalal lazeena kafaroo lan nu'mina bihaazal Quraani wa laa billazee baina yadayh; wa law taraaa iziz zaalimoona mawqoofoona 'inda Rabbihim yarji'u ba'duhum ilaa ba'dinil qawla yaqoolul lazeenas tud'ifoo lillazeenas takbaroo law laaa antum lakunnaa mu'mineen", "translation": "And those who disbelieve say, \"We will never believe in this Qur'an nor in that before it.\" But if you could see when the wrongdoers are made to stand before their Lord, refuting each other's words... Those who were oppressed will say to those who were arrogant, \"If not for you, we would have been believers.\""}, {"ayah": 32, "translit": "Qaalal lazeenas takbaroo lillazeenas tud'ifooo anahnu sadadnaakum 'anil hudaa ba'da iz jaaa'akum bal kuntum mujrimeen", "translation": "Those who were arrogant will say to those who were oppressed, \"Did we avert you from guidance after it had come to you? Rather, you were criminals.\""}, {"ayah": 33, "translit": "Wa qaalal lazeenastud'ifoo lillazeenas takbaroo bal makrul laili wannahaari iz taamuroonanaaa an nakfura billaahi wa naj'ala lahooo andaadaa; wa asarrun nadaamata lammaa ra awul 'azaab; wa ja'alnal aghlaala feee a'naaqil lazeena kafaroo; hal yujzawna illaa maa kanoo ya'maloon", "translation": "Those who were oppressed will say to those who were arrogant, \"Rather, [it was your] conspiracy of night and day when you were ordering us to disbelieve in Allah and attribute to Him equals.\" But they will [all] confide regret when they see the punishment; and We will put shackles on the necks of those who disbelieved. Will they be recompensed except for what they used to do?"}, {"ayah": 34, "translit": "Wa maaa arsalnaa' fee qaryatim min nazeerin illaa qaala mutrafooaa innaa bimaaa ursiltum bihee kaafiroon", "translation": "And We did not send into a city any warner except that its affluent said, \"Indeed we, in that with which you were sent, are disbelievers.\""}, {"ayah": 35, "translit": "Wa qaaloo nahnu aksaru amwaalanw wa awlaadanw wa maa nahnu bimu 'azzabeen", "translation": "And they said, \"We are more [than the believers] in wealth and children, and we are not to be punished.\""}, {"ayah": 36, "translit": "Qul inna Rabbee yabsutur rizqa limai yashaaa'u wa yaqdiru wa laakinna aksaran naasi laa ya'lamoon", "translation": "Say, \"Indeed, my Lord extends provision for whom He wills and restricts [it], but most of the people do not know.\""}, {"ayah": 37, "translit": "Wa maaa amwaalukum wa laaa awlaadukum billatee tuqarribukum 'indanaa zulfaaa illaa man aamana wa 'amila saalihan fa ulaaa'ika lahum jazaaa'ud di'fi bimaa 'amiloo wa hum fil ghurufaati aaminoon", "translation": "And it is not your wealth or your children that bring you nearer to Us in position, but it is [by being] one who has believed and done righteousness. For them there will be the double reward for what they did, and they will be in the upper chambers [of Paradise], safe [and secure]."}, {"ayah": 38, "translit": "Wallazeena yas'awna feee Aayaatinaa mu'aajizeena ulaaa'ika fil'azaabi muhdaroon", "translation": "And the ones who strive against Our verses to cause [them] failure - those will be brought into the punishment [to remain]."}, {"ayah": 39, "translit": "Qul inna Rabbee yabsutur rizqa limai yashaaa'u min 'ibaadihee wa yaqdiru lah; wa maaa anfaqtum min shai'in fahuwa yukhlifuhoo wa Huwa khairur raaziqeen", "translation": "Say, \"Indeed, my Lord extends provision for whom He wills of His servants and restricts [it] for him. But whatever thing you spend [in His cause] - He will compensate it; and He is the best of providers.\""}, {"ayah": 40, "translit": "Wa yawma yahshuruhum jamee'an summa yaqoolu lilmalaaa'ikati a-haaa'ulaaa'i iyyaakum kaanoo ya'budoon", "translation": "And [mention] the Day when He will gather them all and then say to the angels, \"Did these [people] used to worship you?\""}, {"ayah": 41, "translit": "Qaaloo Subhaanaka Anta waliyyunaa min doonihim bal kaanoo ya'budoonal jinna aksaruhum bihim mu'minoon", "translation": "They will say, \"Exalted are You! You, [O Allah], are our benefactor not them. Rather, they used to worship the jinn; most of them were believers in them.\""}, {"ayah": 42, "translit": "Fal Yawma laa yamliku ba'dukum liba'din naf'anw wa laa darraa; wa naqoolu lilzeena zalamoo zooqoo 'azaaban Naaril latee kuntum bihaa tukazziboon", "translation": "But today you do not hold for one another [the power of] benefit or harm, and We will say to those who wronged, \"Taste the punishment of the Fire, which you used to deny.\""}, {"ayah": 43, "translit": "Wa izaa tutlaa 'alaihim Aayaatunaa baiyinaatin qaaloo maa haazaa illaa rajuluny yureedu ai-yasuddakum 'ammaa kaana ya'budu aabaaa'ukum wa qaaloo maa haazaaa illaaa ifkum muftaraa; wa qaalal lazeena kafaroo lilhaqqi lammaa jaaa'ahum in haazaaa illaa sihrum mubeen", "translation": "And when our verses are recited to them as clear evidences, they say, \"This is not but a man who wishes to avert you from that which your fathers were worshipping.\" And they say, \"This is not except a lie invented.\" And those who disbelieve say of the truth when it has come to them, \"This is not but obvious magic.\""}, {"ayah": 44, "translit": "Wa maaa aatainaahum min Kutubiny yadrusoonahaa wa maaa arsalnaaa ilaihim qablaka min nazeer", "translation": "And We had not given them any scriptures which they could study, and We had not sent to them before you, [O Muhammad], any warner."}, {"ayah": 45, "translit": "Wa kazzabal lazeena min qablihim wa maa balaghoo mi'shaara maaa aatainaahum fakazzaboo Rusulee; fakaifa kaana nakeer", "translation": "And those before them denied, and the people of Makkah have not attained a tenth of what We had given them. But the former peoples denied My messengers, so how [terrible] was My reproach."}, {"ayah": 46, "translit": "Qul innamaaa a'izukum biwaahidatin an taqoomoo lillaahi masnaa wa furaadaa summa tatafakkaroo; maa bisaahibikum min jinnah; in huwa illaa nazeerul lakum baina yadai 'azaabin shadeed", "translation": "Say, \"I only advise you of one [thing] - that you stand for Allah, [seeking truth] in pairs and individually, and then give thought.\" There is not in your companion any madness. He is only a warner to you before a severe punishment."}, {"ayah": 47, "translit": "Qul maa sa-altukum min ajrin fahuwa lakum in ajriya illaa 'alal laahi wa Huwa 'alaa kullin shai-in Shaheed", "translation": "Say, \"Whatever payment I might have asked of you - it is yours. My payment is only from Allah, and He is, over all things, Witness.\""}, {"ayah": 48, "translit": "Qul inna Rabbee yaqzifu bilhaqq 'Allaamul Ghuyoob", "translation": "Say, \"Indeed, my Lord projects the truth. Knower of the unseen.\""}, {"ayah": 49, "translit": "Qul jaaa'al haqqu wa maa yubdi'ul baatilu wa maa yu'eed", "translation": "Say, \"The truth has come, and falsehood can neither begin [anything] nor repeat [it].\""}, {"ayah": 50, "translit": "Qul in dalaltu fainnamaaa adillu 'alaa nafsee wa inih-tadaitu fabimaa yoohee ilaiya Rabbee; innahoo Samee'un Qareeb", "translation": "Say, \"If I should err, I would only err against myself. But if I am guided, it is by what my Lord reveals to me. Indeed, He is Hearing and near.\""}, {"ayah": 51, "translit": "Wa law taraaa iz fazi'oo falaa fawta wa ukhizoo mim makaanin qareeb", "translation": "And if you could see when they are terrified but there is no escape, and they will be seized from a place nearby."}, {"ayah": 52, "translit": "Wa qaloo aamannaa bihee wa annaa lahumut tanaawushu mim makaanim ba'eed", "translation": "And they will [then] say, \"We believe in it!\" But how for them will be the taking [of faith] from a place far away?"}, {"ayah": 53, "translit": "Wa qad kafaroo bihee min qablu wa yaqzifoona bilghaibi mim makaanim ba'eed", "translation": "And they had already disbelieved in it before and would assault the unseen from a place far away."}, {"ayah": 54, "translit": "Wa heela bainahum wa baina maa yashtahoona kamaa fu'ila bi-ashyaa'ihim min qabl; innahum kaanoo fee shakkim mureeb", "translation": "And prevention will be placed between them and what they desire, as was done with their kind before. Indeed, they were in disquieting denial."}]}, {"num": 35, "name": "Fatir", "meaning": "Originator", "verses": [{"ayah": 1, "translit": "Alhamdu lillaahi faatiris samaawaati wal ardi jaa'ilil malaaa'ikati rusulan uleee ajnihatim masnaa wa sulaasa wa rubaa'; yazeedu fil khalqi maa yashaaa'; innal laaha 'alaa kulli shai'in Qadeer", "translation": "[All] praise is [due] to Allah, Creator of the heavens and the earth, [who] made the angels messengers having wings, two or three or four. He increases in creation what He wills. Indeed, Allah is over all things competent."}, {"ayah": 2, "translit": "Maa yaftahil laahu linnaaasi mir rahmatin falaa mumsika lahaa wa maa yumsik falaa mursila lahoo mimb'dih; wa Huwal 'Azeezul Hakeem", "translation": "Whatever Allah grants to people of mercy - none can withhold it; and whatever He withholds - none can release it thereafter. And He is the Exalted in Might, the Wise."}, {"ayah": 3, "translit": "Yaaa ayyuhan naasuzkuroo ni'matal laahi 'alaikum; hal min khaaliqin ghairul laahi yarzuqukum minas samaaa'i wal ard; laaa ilaaha illaa Huwa fa annaa tu'fakoon", "translation": "O mankind, remember the favor of Allah upon you. Is there any creator other than Allah who provides for you from the heaven and earth? There is no deity except Him, so how are you deluded?"}, {"ayah": 4, "translit": "Wa iny yukazzibooka faqad kuzzibat Rusulum min qablik; wa ilal laahi turja'ul umoor", "translation": "And if they deny you, [O Muhammad] - already were messengers denied before you. And to Allah are returned [all] matters."}, {"ayah": 5, "translit": "Yaaa ayyuhan naasu inna wa'dal laahi haqqun falaa taghurrannakumul hayaatud dunyaa; wa laa yaghurran nakum billaahil gharoor", "translation": "O mankind, indeed the promise of Allah is truth, so let not the worldly life delude you and be not deceived about Allah by the Deceiver."}, {"ayah": 6, "translit": "Innash shaitaana lakum 'aduwwun fattakhizoohu 'aduwwaa; innamaa yad'oo hizbahoo liyakoonoo min ashaabis sa'eer", "translation": "Indeed, Satan is an enemy to you; so take him as an enemy. He only invites his party to be among the companions of the Blaze."}, {"ayah": 7, "translit": "Allazeena kafaroo lahum 'azaabun shadeed; wallazeena aamanoo wa 'amilus saalihaati lahum maghfiratunw wa ajrun kabeer", "translation": "Those who disbelieve will have a severe punishment, and those who believe and do righteous deeds will have forgiveness and great reward."}, {"ayah": 8, "translit": "Afaman zuyyina lahoo sooo'u 'amalihee fara aahu hasanaa; fa innal laaha yudillu mai yashaaa'u wa yahdee mai yahaaa'u falaa tazhab nafsuka 'alaihim hasaraat; innal laaha 'aleemun bimaa yasna'oon", "translation": "Then is one to whom the evil of his deed has been made attractive so he considers it good [like one rightly guided]? For indeed, Allah sends astray whom He wills and guides whom He wills. So do not let yourself perish over them in regret. Indeed, Allah is Knowing of what they do."}, {"ayah": 9, "translit": "Wallaahul lazeee arsalar riyaaha fatuseeru shaaban fasuqnaahu ilaa baladim maiyitin fa ahyaynaa bihil arda ba'da mawtihaa; kazaalikan nushoor", "translation": "And it is Allah who sends the winds, and they stir the clouds, and We drive them to a dead land and give life thereby to the earth after its lifelessness. Thus is the resurrection."}, {"ayah": 10, "translit": "Man kaana yureedul 'izzata falillaahil 'izzatu jamee'aa; ilaihi yas'adul kalimut taiyibu wal'amalus saalihu yarfa'uh; wallazeena yamkuroonas sayyiaati lahum 'azaabun shadeed; wa makru ulaaa'ika huwa yaboor", "translation": "Whoever desires honor [through power] - then to Allah belongs all honor. To Him ascends good speech, and righteous work raises it. But they who plot evil deeds will have a severe punishment, and the plotting of those - it will perish."}, {"ayah": 11, "translit": "Wallaahu khalaqakum min turaabin summa min nutfatin summa ja'alakum azwaajaa; wa maa tahmilu min unsaa wa laa tada'u illaa bi'ilmih; wa maa yu'ammaru mim mu'ammarinw wa laa yunqasu min 'umuriheee illaa fee kitaab; inna zaalika 'alal laahi yaseer", "translation": "And Allah created you from dust, then from a sperm-drop; then He made you mates. And no female conceives nor does she give birth except with His knowledge. And no aged person is granted [additional] life nor is his lifespan lessened but that it is in a register. Indeed, that for Allah is easy."}, {"ayah": 12, "translit": "Wa maa yastawil bahraani haaza 'azbun furaatun saaa'ighun sharaabuhoo wa haazaa milhun ujaaj; wa min kullin taakuloona lahman tariyyanw wa tastakhrijoona hilyatan talbasoonahaa wa taral fulka feehi mawaakhira litabtaghoo min fadlihee wa la'allakm tashkuroon", "translation": "And not alike are the two bodies of water. One is fresh and sweet, palatable for drinking, and one is salty and bitter. And from each you eat tender meat and extract ornaments which you wear, and you see the ships plowing through [them] that you might seek of His bounty; and perhaps you will be grateful."}, {"ayah": 13, "translit": "Yoolijul laila fin nahaari wa yoolijun nahaara fil laili wa sakhkharash shamsa wal qamara kulluny yajree li ajalim musammaa; zaalikumul lahuu Rabbukum lahul mulk; wallazeena tad'oona min doonihee maa yamlikoona min qitmeer", "translation": "He causes the night to enter the day, and He causes the day to enter the night and has subjected the sun and the moon - each running [its course] for a specified term. That is Allah, your Lord; to Him belongs sovereignty. And those whom you invoke other than Him do not possess [as much as] the membrane of a date seed."}, {"ayah": 14, "translit": "in tad'oohum laa yasma'oo du'aaa'akum wa law sami'oo mas tajaaboo lakum; wa Yawmal Qiyaamati Yakfuroona bishirkikum; wa laa yunabbi'uka mislu khabeer", "translation": "If you invoke them, they do not hear your supplication; and if they heard, they would not respond to you. And on the Day of Resurrection they will deny your association. And none can inform you like [one] Acquainted [with all matters]."}, {"ayah": 15, "translit": "Yaaa ayyunhan naasu antumul fuqaraaa'u ilallaahi wallaahu Huwal Ghaniyyul Hameed", "translation": "O mankind, you are those in need of Allah, while Allah is the Free of need, the Praiseworthy."}, {"ayah": 16, "translit": "Iny yashaa yuzhibkum wa yaati bikhalqin jadeed", "translation": "If He wills, He can do away with you and bring forth a new creation."}, {"ayah": 17, "translit": "Wa maa zaalika 'alal laahi bi'azeez", "translation": "And that is for Allah not difficult."}, {"ayah": 18, "translit": "Wa laa taziru waaziratun wizra ukhraa; wa in tad'u musqalatun ilaa himlihaa laa yuhmal minhu shai'unw wa law kaana zaa qurbaa; innamaa tunzirul lazeena yakhshawna Rabbahum bilghaibi wa aqaamus Sallah; wa man tazakkaa fa innamaa yatazakkaa linafsih; wa ilal laahil maseer", "translation": "And no bearer of burdens will bear the burden of another. And if a heavily laden soul calls [another] to [carry some of] its load, nothing of it will be carried, even if he should be a close relative. You can only warn those who fear their Lord unseen and have established prayer. And whoever purifies himself only purifies himself for [the benefit of] his soul. And to Allah is the [final] destination."}, {"ayah": 19, "translit": "Wa maa tastawil a'maa wal baseer", "translation": "Not equal are the blind and the seeing,"}, {"ayah": 20, "translit": "Wa laz zulumaatu wa lannoon", "translation": "Nor are the darknesses and the light,"}, {"ayah": 21, "translit": "Wa laz zillu wa lal haroor", "translation": "Nor are the shade and the heat,"}, {"ayah": 22, "translit": "Wa maa yastawil ahyaaa'u wa lal amwaat; innal laaha yusmi'u mai yashaaa'u wa maaa anta bimusi'im man fil quboor", "translation": "And not equal are the living and the dead. Indeed, Allah causes to hear whom He wills, but you cannot make hear those in the graves."}, {"ayah": 23, "translit": "In anta illaa nazeer", "translation": "You, [O Muhammad], are not but a warner."}, {"ayah": 24, "translit": "Innaa arsalnaak bil haqqi basheeranw wa nazeeraa; wa im min ummatin illaa khalaa feehaa nazeer", "translation": "Indeed, We have sent you with the truth as a bringer of good tidings and a warner. And there was no nation but that there had passed within it a warner."}, {"ayah": 25, "translit": "Wa inyukazzibooka faqad kazzabal lazeena min qablihim jaaa'at hum Rusuluhum bilbaiyinaati wa biz Zuburi wa bil Kitaabil Muneer", "translation": "And if they deny you - then already have those before them denied. Their messengers came to them with clear proofs and written ordinances and with the enlightening Scripture."}, {"ayah": 26, "translit": "Summa akhaztul lazeena kafaroo fakaifa kaana nakeer", "translation": "Then I seized the ones who disbelieved, and how [terrible] was My reproach."}, {"ayah": 27, "translit": "Alam tara annal laaha anzala minas samaaa'i maaa'an fa akhrajnaa bihee samaraatim mukhtalifan alwaanuhaa; wa minal jibaali judadum beedunw wa humrum mukhtalifun alwaanuhaa wa gharaabeebu sood", "translation": "Do you not see that Allah sends down rain from the sky, and We produce thereby fruits of varying colors? And in the mountains are tracts, white and red of varying shades and [some] extremely black."}, {"ayah": 28, "translit": "Wa minan naasi wadda waaabbi wal an'aami mukhtalifun alwaanuhoo kazalik; innamaa yakhshal laaha min 'ibaadihil 'ulamaaa'; innal laaha 'Azeezun Ghafoor", "translation": "And among people and moving creatures and grazing livestock are various colors similarly. Only those fear Allah, from among His servants, who have knowledge. Indeed, Allah is Exalted in Might and Forgiving."}, {"ayah": 29, "translit": "Innal lazeena yatloona Kitabbal laahi wa aqaamus Salaata wa anfaqoo mimmaa razaqnaahum sirranw wa 'alaa niyatany yarjoona tijaaratal lan taboor", "translation": "Indeed, those who recite the Book of Allah and establish prayer and spend [in His cause] out of what We have provided them, secretly and publicly, [can] expect a profit that will never perish -"}, {"ayah": 30, "translit": "Liyuwaffiyahum ujoorahum wa yazeedahum min fadlih; innahoo Ghafoorun Shakoor", "translation": "That He may give them in full their rewards and increase for them of His bounty. Indeed, He is Forgiving and Appreciative."}, {"ayah": 31, "translit": "Wallaeee awhainaaa ilaika minal Kitaabi huwal haqqu musaddiqal limaa baina yadayh; innal laaha bi'ibaadihee la khabeerum Baseer", "translation": "And that which We have revealed to you, [O Muhammad], of the Book is the truth, confirming what was before it. Indeed, Allah, of His servants, is Acquainted and Seeing."}, {"ayah": 32, "translit": "Summa awrasnal Kitaaballazeenas tafainaa min 'ibaadinaa faminhum zaalimul linafsihee wa minhum muqtasid, wa minhum saabiqum bilkhairaati bi iznil laah; zaalika huwal fadlul kabeer", "translation": "Then we caused to inherit the Book those We have chosen of Our servants; and among them is he who wrongs himself, and among them is he who is moderate, and among them is he who is foremost in good deeds by permission of Allah. That [inheritance] is what is the great bounty."}, {"ayah": 33, "translit": "jannaatu 'adniny yad khuloonahaa yuhallawna feeha min asaawira min zahabinw wa lu'lu'anw wa libaa suhum feehaa hareer", "translation": "[For them are] gardens of perpetual residence which they will enter. They will be adorned therein with bracelets of gold and pearls, and their garments therein will be silk."}, {"ayah": 34, "translit": "Wa qaalul hamdu lillaahil lazeee azhaba 'annal hazan; inna Rabbanaa la Ghafoorun Shakoor", "translation": "And they will say, \"Praise to Allah, who has removed from us [all] sorrow. Indeed, our Lord is Forgiving and Appreciative -"}, {"ayah": 35, "translit": "Allazeee ahallanaa daaral muqaamati min fadlihee laa yamassunaa feehaa nasabunw wa laa yamassunaa feehaa lughoob", "translation": "He who has settled us in the home of duration out of His bounty. There touches us not in it any fatigue, and there touches us not in it weariness [of mind].\""}, {"ayah": 36, "translit": "Wallazeena kafaroo lahum naaru Jahannama laa yuqdaa 'alaihim fa yamootoo wa laa yukhaffafu 'anhum min 'azaabihaa; kazaalika najzee kulla kafoor", "translation": "And for those who disbelieve will be the fire of Hell. [Death] is not decreed for them so they may die, nor will its torment be lightened for them. Thus do we recompense every ungrateful one."}, {"ayah": 37, "translit": "Wa hum yastarikhoona feehaa Rabbanaa akhrijnaa na'mal saalihan ghairal lazee kunnaa na'mal; awa lamnu 'ammirkum maa yatazak karu feehi man tazakkara wa jaaa'akumun nazeeru fazooqoo famaa lizzaalimeena min naseer", "translation": "And they will cry out therein, \"Our Lord, remove us; we will do righteousness - other than what we were doing!\" But did We not grant you life enough for whoever would remember therein to remember, and the warner had come to you? So taste [the punishment], for there is not for the wrongdoers any helper."}, {"ayah": 38, "translit": "Innal laaha 'aalimu ghaibis samaawaati wal ard; innahoo 'aleemum bizaatis sudoor", "translation": "Indeed, Allah is Knower of the unseen [aspects] of the heavens and earth. Indeed, He is Knowing of that within the breasts."}, {"ayah": 39, "translit": "Huwal lazee ja'alakum khalaaa'ifa fil ard; faman kafara fa'alaihi kufruhoo; wa laa yazeedul kaafireena kufruhum 'inda Rabbihim illaa maqtanw wa la yazeedul kaafireena kufruhum illaa khasaaraa", "translation": "It is He who has made you successors upon the earth. And whoever disbelieves - upon him will be [the consequence of] his disbelief. And the disbelief of the disbelievers does not increase them in the sight of their Lord except in hatred; and the disbelief of the disbelievers does not increase them except in loss."}, {"ayah": 40, "translit": "Qul ara'aytum shurakaaa'a kumul lazeena tad'oona min doonil laah; aroonee maazaa khalaqoo minal ardi am lahum shirkun fis samaawaati am aatainaahum Kitaaban fahum 'alaa baiyinatim minh; bal iny ya'iiduz zaalimoona ba 'duhum ba'dan illaa ghurooraa", "translation": "Say, \"Have you considered your 'partners' whom you invoke besides Allah? Show me what they have created from the earth, or have they partnership [with Him] in the heavens? Or have We given them a book so they are [standing] on evidence therefrom? [No], rather, the wrongdoers do not promise each other except delusion.\""}, {"ayah": 41, "translit": "Innal laaha yumsikus samaawaati wal arda an tazoolaaa; wa la'in zaalataaa in amsa kahumaa min ahadim mim ba'dih; innahoo kaana Haleeman Ghafooraa", "translation": "Indeed, Allah holds the heavens and the earth, lest they cease. And if they should cease, no one could hold them [in place] after Him. Indeed, He is Forbearing and Forgiving."}, {"ayah": 42, "translit": "Wa aqsamoo billaahi jahda aymaanihim la'in jaaa'ahum nazeerul layakoonunna ahdaa min ihdal umami falam maa jaaa'ahum nazeerum maa zaadahum illaa nufooraa", "translation": "And they swore by Allah their strongest oaths that if a warner came to them, they would be more guided than [any] one of the [previous] nations. But when a warner came to them, it did not increase them except in aversion."}, {"ayah": 43, "translit": "Istakbaaran fil ardi wa makras sayyi'; wa laa yaheequl makrus sayyi'u illaa bi ahlih; fahal yanzuroona illaa sunnatal awwaleen; falan tajida lisunnatil laahi tabdeelanw wa lan tajida lisunnatil laahi tahweela", "translation": "[Due to] arrogance in the land and plotting of evil; but the evil plot does not encompass except its own people. Then do they await except the way of the former peoples? But you will never find in the way of Allah any change, and you will never find in the way of Allah any alteration."}, {"ayah": 44, "translit": "Awalam yaseeroo fil ardi fa yanzuroo kaifa kaana 'aaqibatul lazeena min qblihim wa kaanoo ashadda minhum quwwah; wa maa kaanal laahu liyu'jizahoo min shai'in fis samaawaati wa laa fil ard; innahoo kaana 'Aleeman Qadeeraa", "translation": "Have they not traveled through the land and observed how was the end of those before them? And they were greater than them in power. But Allah is not to be caused failure by anything in the heavens or on the earth. Indeed, He is ever Knowing and Competent."}, {"ayah": 45, "translit": "Wa law yu'aakhizul laahun naasa bima kasaboo maa taraka 'alaa zahrihaa min daaabbatinw wa laakiny yu'akhkhiruhum ilaaa ajalim musamman fa izaa jaaa'a ajaluhum fa innal laaha kaana bi'ibaadihee Baseeraa", "translation": "And if Allah were to impose blame on the people for what they have earned, He would not leave upon the earth any creature. But He defers them for a specified term. And when their time comes, then indeed Allah has ever been, of His servants, Seeing."}]}, {"num": 36, "name": "Ya-Sin", "meaning": "Ya-Sin", "verses": [{"ayah": 1, "translit": "Yaa-Seeen", "translation": "Ya, Seen."}, {"ayah": 2, "translit": "Wal-Qur-aanil-Hakeem", "translation": "By the wise Qur'an."}, {"ayah": 3, "translit": "Innaka laminal mursaleen", "translation": "Indeed you, [O Muhammad], are from among the messengers,"}, {"ayah": 4, "translit": "'Alaa Siraatim Mustaqeem", "translation": "On a straight path."}, {"ayah": 5, "translit": "Tanzeelal 'Azeezir Raheem", "translation": "[This is] a revelation of the Exalted in Might, the Merciful,"}, {"ayah": 6, "translit": "Litunzira qawmam maaa unzira aabaaa'uhum fahum ghaafiloon", "translation": "That you may warn a people whose forefathers were not warned, so they are unaware."}, {"ayah": 7, "translit": "Laqad haqqal qawlu 'alaaa aksarihim fahum laa yu'minoon", "translation": "Already the word has come into effect upon most of them, so they do not believe."}, {"ayah": 8, "translit": "Innaa ja'alnaa feee a'naaqihim aghlaalan fahiya ilal azqaani fahum muqmahoon", "translation": "Indeed, We have put shackles on their necks, and they are to their chins, so they are with heads [kept] aloft."}, {"ayah": 9, "translit": "Wa ja'alnaa mim baini aydeehim saddanw-wa min khalfihim saddan fa aghshai naahum fahum laa yubsiroon", "translation": "And We have put before them a barrier and behind them a barrier and covered them, so they do not see."}, {"ayah": 10, "translit": "Wa sawaaa'un 'alaihim 'a-anzartahum am lam tunzirhum laa yu'minoon", "translation": "And it is all the same for them whether you warn them or do not warn them - they will not believe."}, {"ayah": 11, "translit": "Innamaa tunziru manit taba 'az-Zikra wa khashiyar Rahmaana bilghaib, fabashshirhu bimaghfiratinw-wa ajrin kareem", "translation": "You can only warn one who follows the message and fears the Most Merciful unseen. So give him good tidings of forgiveness and noble reward."}, {"ayah": 12, "translit": "Innaa Nahnu nuhyil mawtaa wa naktubu maa qaddamoo wa aasaarahum; wa kulla shai'in ahsainaahu feee Imaamim Mubeen", "translation": "Indeed, it is We who bring the dead to life and record what they have put forth and what they left behind, and all things We have enumerated in a clear register."}, {"ayah": 13, "translit": "Wadrib lahum masalan Ashaabal Qaryatih; iz jaaa'ahal mursaloon", "translation": "And present to them an example: the people of the city, when the messengers came to it -"}, {"ayah": 14, "translit": "Iz arsalnaaa ilaihimusnaini fakazzaboohumaa fa'azzaznaa bisaalisin faqaalooo innaaa ilaikum mursaloon", "translation": "When We sent to them two but they denied them, so We strengthened them with a third, and they said, \"Indeed, we are messengers to you.\""}, {"ayah": 15, "translit": "Qaaloo maaa antum illaa basharum mislunaa wa maaa anzalar Rahmaanu min shai'in in antum illaa takziboon", "translation": "They said, \"You are not but human beings like us, and the Most Merciful has not revealed a thing. You are only telling lies.\""}, {"ayah": 16, "translit": "Qaaloo Rabbunaa ya'lamu innaaa ilaikum lamursaloon", "translation": "They said, \"Our Lord knows that we are messengers to you,"}, {"ayah": 17, "translit": "Wa maa 'alainaaa illal balaaghul mubeen", "translation": "And we are not responsible except for clear notification.\""}, {"ayah": 18, "translit": "Qaaloo innaa tataiyarnaa bikum la'il-lam tantahoo lanar jumannakum wa la-yamassan nakum minnaa 'azaabun aleem", "translation": "They said, \"Indeed, we consider you a bad omen. If you do not desist, we will surely stone you, and there will surely touch you, from us, a painful punishment.\""}, {"ayah": 19, "translit": "Qaaloo taaa'irukum ma'akum; a'in zukkirtum; bal antum qawmum musrifoon", "translation": "They said, \"Your omen is with yourselves. Is it because you were reminded? Rather, you are a transgressing people.\""}, {"ayah": 20, "translit": "Wa jaaa'a min aqsal madeenati rajuluny yas'aa qaala yaa qawmit tabi'ul mursaleen", "translation": "And there came from the farthest end of the city a man, running. He said, \"O my people, follow the messengers."}, {"ayah": 21, "translit": "Ittabi'oo mal-laa yas'alukum ajranw-wa hum muhtadoon", "translation": "Follow those who do not ask of you [any] payment, and they are [rightly] guided."}, {"ayah": 22, "translit": "Wa maa liya laaa a'budul lazee fataranee wa ilaihi turja'oon", "translation": "And why should I not worship He who created me and to whom you will be returned?"}, {"ayah": 23, "translit": "'A-attakhizu min dooniheee aalihatan iny-yuridnir Rahmaanu bidurril-laa tughni 'annee shafaa 'atuhum shai 'anw-wa laa yunqizoon", "translation": "Should I take other than Him [false] deities [while], if the Most Merciful intends for me some adversity, their intercession will not avail me at all, nor can they save me?"}, {"ayah": 24, "translit": "Inneee izal-lafee dalaa-lim-mubeen", "translation": "Indeed, I would then be in manifest error."}, {"ayah": 25, "translit": "Inneee aamantu bi Rabbikum fasma'oon", "translation": "Indeed, I have believed in your Lord, so listen to me.\""}, {"ayah": 26, "translit": "Qeelad khulil Jannnah; qaala yaa laita qawmee ya'lamoon", "translation": "It was said, \"Enter Paradise.\" He said, \"I wish my people could know"}, {"ayah": 27, "translit": "Bimaa ghafara lee Rabbee wa ja'alanee minal mukrameen", "translation": "Of how my Lord has forgiven me and placed me among the honored.\""}, {"ayah": 28, "translit": "Wa maaa anzalnaa 'alaa qawmihee mim ba'dihee min jundim minas-samaaa'i wa maa kunnaa munzileen", "translation": "And We did not send down upon his people after him any soldiers from the heaven, nor would We have done so."}, {"ayah": 29, "translit": "In kaanat illaa saihatanw waahidatan fa-izaa hum khaamidoon", "translation": "It was not but one shout, and immediately they were extinguished."}, {"ayah": 30, "translit": "Yaa hasratan 'alal 'ibaad; maa yaateehim mir Rasoolin illaa kaanoo bihee yastahzi 'oon", "translation": "How regretful for the servants. There did not come to them any messenger except that they used to ridicule him."}, {"ayah": 31, "translit": "Alam yaraw kam ahlak naa qablahum minal qurooni annahum ilaihim laa yarji'oon", "translation": "Have they not considered how many generations We destroyed before them - that they to them will not return?"}, {"ayah": 32, "translit": "Wa in kullul lammaa jamee'ul-ladainaa muhdaroon", "translation": "And indeed, all of them will yet be brought present before Us."}, {"ayah": 33, "translit": "Wa Aayatul lahumul ardul maitatu ahyainaahaa wa akhrajnaa minhaa habban faminhu yaakuloon", "translation": "And a sign for them is the dead earth. We have brought it to life and brought forth from it grain, and from it they eat."}, {"ayah": 34, "translit": "Wa ja'alnaa feehaa jannaatim min nakheelinw wa a'naabinw wa fajjarnaa feeha minal 'uyoon", "translation": "And We placed therein gardens of palm trees and grapevines and caused to burst forth therefrom some springs -"}, {"ayah": 35, "translit": "Liyaakuloo min samarihee wa maa 'amilat-hu aideehim; afalaa yashkuroon", "translation": "That they may eat of His fruit. And their hands have not produced it, so will they not be grateful?"}, {"ayah": 36, "translit": "Subhaanal lazee khalaqal azwaaja kullahaa mimmaa tumbitul ardu wa min anfusihim wa mimmaa laa ya'lamoon", "translation": "Exalted is He who created all pairs - from what the earth grows and from themselves and from that which they do not know."}, {"ayah": 37, "translit": "Wa Aayatul lahumul lailu naslakhu minhun nahaara fa-izaa hum muzlimoon", "translation": "And a sign for them is the night. We remove from it [the light of] day, so they are [left] in darkness."}, {"ayah": 38, "translit": "Wash-shamsu tajree limustaqarril lahaa; zaalika taqdeerul 'Azeezil Aleem", "translation": "And the sun runs [on course] toward its stopping point. That is the determination of the Exalted in Might, the Knowing."}, {"ayah": 39, "translit": "Walqamara qaddarnaahu manaazila hattaa 'aada kal'ur joonil qadeem", "translation": "And the moon - We have determined for it phases, until it returns [appearing] like the old date stalk."}, {"ayah": 40, "translit": "Lash shamsu yambaghee lahaaa an tudrikal qamara wa lal lailu saabiqun nahaar; wa kullun fee falaki yasbahoon", "translation": "It is not allowable for the sun to reach the moon, nor does the night overtake the day, but each, in an orbit, is swimming."}, {"ayah": 41, "translit": "Wa Aayatul lahum annaa hamalnaa zurriyatahum fil fulkil mashhoon", "translation": "And a sign for them is that We carried their forefathers in a laden ship."}, {"ayah": 42, "translit": "Wa khalaqnaa lahum mim-mislihee maa yarkaboon", "translation": "And We created for them from the likes of it that which they ride."}, {"ayah": 43, "translit": "Wa in nashaa nughriqhum falaa sareekha lahum wa laa hum yunqazoon", "translation": "And if We should will, We could drown them; then no one responding to a cry would there be for them, nor would they be saved"}, {"ayah": 44, "translit": "Illaa rahmatam minnaa wa mataa'an ilaa heen", "translation": "Except as a mercy from Us and provision for a time."}, {"ayah": 45, "translit": "Wa izaa qeela lahumuttaqoo maa baina aideekum wa maa khalfakum la'allakum turhamoon", "translation": "But when it is said to them, \"Beware of what is before you and what is behind you; perhaps you will receive mercy... \""}, {"ayah": 46, "translit": "Wa maa taateehim min aayatim min ayataati Rabbihim illaa kaanoo 'anhaa mu'rideen", "translation": "And no sign comes to them from the signs of their Lord except that they are from it turning away."}, {"ayah": 47, "translit": "Wa izaa qeela lahum anfiqoo mimmaa razaqakumul laahu qaalal lazeena kafaroo lillazeena aamanooo anut'imu mal-law yashaaa'ul laahu at'amahooo in antum illaa fee dalaalim mubeen", "translation": "And when it is said to them, \"Spend from that which Allah has provided for you,\" those who disbelieve say to those who believe, \"Should we feed one whom, if Allah had willed, He would have fed? You are not but in clear error.\""}, {"ayah": 48, "translit": "Wa yaqooloona mataa haazal wa'du in kuntum saadiqeen", "translation": "And they say, \"When is this promise, if you should be truthful?\""}, {"ayah": 49, "translit": "Maa yanzuroona illaa saihatanw waahidatan taa khuzuhum wa hum yakhissimoon", "translation": "They do not await except one blast which will seize them while they are disputing."}, {"ayah": 50, "translit": "Falaa yastatee'oona taw siyatanw-wa laaa ilaaa ahlihim yarji'oon", "translation": "And they will not be able [to give] any instruction, nor to their people can they return."}, {"ayah": 51, "translit": "Wa nufikha fis-soori faizaa hum minal ajdaasi ilaa Rabbihim yansiloon", "translation": "And the Horn will be blown; and at once from the graves to their Lord they will hasten."}, {"ayah": 52, "translit": "Qaaloo yaa wailanaa mam ba'asanaa mim marqadinaa; haaza maa wa'adar Rahmanu wa sadaqal mursaloon", "translation": "They will say, \"O woe to us! Who has raised us up from our sleeping place?\" [The reply will be], \"This is what the Most Merciful had promised, and the messengers told the truth.\""}, {"ayah": 53, "translit": "In kaanat illaa saihatanw waahidatan fa-izaa hum jamee'ul ladainaa muhdaroon", "translation": "It will not be but one blast, and at once they are all brought present before Us."}, {"ayah": 54, "translit": "Fal-Yawma laa tuzlamu nafsun shai'anw-wa laa tujzawna illaa maa kuntum ta'maloon", "translation": "So today no soul will be wronged at all, and you will not be recompensed except for what you used to do."}, {"ayah": 55, "translit": "Inna Ashaabal jannatil Yawma fee shughulin faakihoon", "translation": "Indeed the companions of Paradise, that Day, will be amused in [joyful] occupation -"}, {"ayah": 56, "translit": "Hum wa azwaajuhum fee zilaalin 'alal araaa'iki muttaki'oon", "translation": "They and their spouses - in shade, reclining on adorned couches."}, {"ayah": 57, "translit": "Lahum feehaa faakiha tunw-wa lahum maa yadda'oon", "translation": "For them therein is fruit, and for them is whatever they request [or wish]"}, {"ayah": 58, "translit": "Salaamun qawlam mir Rabbir Raheem", "translation": "[And] \"Peace,\" a word from a Merciful Lord."}, {"ayah": 59, "translit": "Wamtaazul Yawma ayyuhal mujrimoon", "translation": "[Then He will say], \"But stand apart today, you criminals."}, {"ayah": 60, "translit": "Alam a'had ilaikum yaa Baneee Aadama al-laa ta'budush Shaitaana innahoo lakum 'aduwwum mubeen", "translation": "Did I not enjoin upon you, O children of Adam, that you not worship Satan - [for] indeed, he is to you a clear enemy -"}, {"ayah": 61, "translit": "Wa ani'budoonee; haazaa Siraatum Mustaqeem", "translation": "And that you worship [only] Me? This is a straight path."}, {"ayah": 62, "translit": "Wa laqad adalla minkum jibillan kaseeraa; afalam takoonoo ta'qiloon", "translation": "And he had already led astray from among you much of creation, so did you not use reason?"}, {"ayah": 63, "translit": "Haazihee Jahannamul latee kuntum too'adoon", "translation": "This is the Hellfire which you were promised."}, {"ayah": 64, "translit": "Islawhal Yawma bimaa kuntum takfuroon", "translation": "[Enter to] burn therein today for what you used to deny.\""}, {"ayah": 65, "translit": "Al-Yawma nakhtimu 'alaaa afwaahihim wa tukallimunaaa aideehim wa tashhadu arjuluhum bimaa kaanoo yaksiboon", "translation": "That Day, We will seal over their mouths, and their hands will speak to Us, and their feet will testify about what they used to earn."}, {"ayah": 66, "translit": "Wa law nashaaa'u lata masna 'alaaa aiyunihim fasta baqus-siraata fa-annaa yubsiroon", "translation": "And if We willed, We could have obliterated their eyes, and they would race to [find] the path, and how could they see?"}, {"ayah": 67, "translit": "Wa law nashaaa'u lamasakhnaahum 'alaa makaanatihim famas-tataa'oo mudiyyanw-wa laa yarji'oon", "translation": "And if We willed, We could have deformed them, [paralyzing them] in their places so they would not be able to proceed, nor could they return."}, {"ayah": 68, "translit": "Wa man nu 'ammirhu nunakkishu fil-khalq; afalaa ya'qiloon", "translation": "And he to whom We grant long life We reverse in creation; so will they not understand?"}, {"ayah": 69, "translit": "Wa maa 'allamnaahush shi'ra wa maa yambaghee lah; in huwa illaa zikrunw-wa Qur-aanum mubeen", "translation": "And We did not give Prophet Muhammad, knowledge of poetry, nor is it befitting for him. It is not but a message and a clear Qur'an"}, {"ayah": 70, "translit": "Liyunzira man kaana haiyanw-wa yahiqqal qawlu 'alal-kaafireen", "translation": "To warn whoever is alive and justify the word against the disbelievers."}, {"ayah": 71, "translit": "Awalam yaraw annaa khalaqnaa lahum mimmaa 'amilat aideenaaa an'aaman fahum lahaa maalikoon", "translation": "Do they not see that We have created for them from what Our hands have made, grazing livestock, and [then] they are their owners?"}, {"ayah": 72, "translit": "Wa zallalnaahaa lahum faminhaa rakoobuhum wa minhaa yaakuloon", "translation": "And We have tamed them for them, so some of them they ride, and some of them they eat."}, {"ayah": 73, "translit": "Wa lahum feehaa manaa fi'u wa mashaarib; afalaa yashkuroon", "translation": "And for them therein are [other] benefits and drinks, so will they not be grateful?"}, {"ayah": 74, "translit": "Wattakhazoo min doonil laahi aalihatal la'allahum yunsaroon", "translation": "But they have taken besides Allah [false] deities that perhaps they would be helped."}, {"ayah": 75, "translit": "Laa yastatee'oona nasrahum wa hum lahum jundum muhdaroon", "translation": "They are not able to help them, and they [themselves] are for them soldiers in attendance."}, {"ayah": 76, "translit": "Falaa yahzunka qawluhum; innaa na'lamu maa yusirroona wa maa yu'linoon", "translation": "So let not their speech grieve you. Indeed, We know what they conceal and what they declare."}, {"ayah": 77, "translit": "Awalam yaral insaanu annaa khalaqnaahu min nutfatin fa-izaa huwa khaseemum mubeen", "translation": "Does man not consider that We created him from a [mere] sperm-drop - then at once he is a clear adversary?"}, {"ayah": 78, "translit": "Wa daraba lanaa maslanw-wa nasiya khalqahoo qaala mai-yuhyil'izaama wa hiya rameem", "translation": "And he presents for Us an example and forgets his [own] creation. He says, \"Who will give life to bones while they are disintegrated?\""}, {"ayah": 79, "translit": "Qul yuh yeehal lazeee ansha ahaaa awwala marrah; wa Huwa bikulli khalqin 'Aleem", "translation": "Say, \"He will give them life who produced them the first time; and He is, of all creation, Knowing.\""}, {"ayah": 80, "translit": "Allazee ja'ala lakum minash shajaril akhdari naaran fa-izaaa antum minhu tooqidoon", "translation": "[It is] He who made for you from the green tree, fire, and then from it you ignite."}, {"ayah": 81, "translit": "Awa laisal lazee khalaqas samaawaati wal arda biqaadirin 'alaaa ai-yakhluqa mislahum; balaa wa Huwal Khallaaqul 'Aleem", "translation": "Is not He who created the heavens and the earth Able to create the likes of them? Yes, [it is so]; and He is the Knowing Creator."}, {"ayah": 82, "translit": "Innamaa amruhooo izaaa araada shai'an ai-yaqoola lahoo kun fa-yakoon", "translation": "His command is only when He intends a thing that He says to it, \"Be,\" and it is."}, {"ayah": 83, "translit": "Fa Subhaanal lazee biyadihee malakootu kulli shai-inw-wa ilaihi turja'oon", "translation": "So exalted is He in whose hand is the realm of all things, and to Him you will be returned."}]}, {"num": 37, "name": "As-Saffat", "meaning": "Those Ranged in Ranks", "verses": [{"ayah": 1, "translit": "Wassaaaffaati saffaa", "translation": "By those [angels] lined up in rows"}, {"ayah": 2, "translit": "Fazzaajiraati zajraa", "translation": "And those who drive [the clouds]"}, {"ayah": 3, "translit": "Fattaaliyaati Zikra", "translation": "And those who recite the message,"}, {"ayah": 4, "translit": "Inna Illaahakum la Waahid", "translation": "Indeed, your God is One,"}, {"ayah": 5, "translit": "Rabbus samaawaati wal ardi wa maa bainahumaa wa Rabbul mashaariq", "translation": "Lord of the heavens and the earth and that between them and Lord of the sunrises."}, {"ayah": 6, "translit": "Innaa zaiyannas samaaa 'ad dunyaa bizeenatinil kawaakib", "translation": "Indeed, We have adorned the nearest heaven with an adornment of stars"}, {"ayah": 7, "translit": "Wa hifzam min kulli Shaitaanim maarid", "translation": "And as protection against every rebellious devil"}, {"ayah": 8, "translit": "Laa yassamma 'oona ilal mala il a'alaa wa yuqzafoona min kulli jaanib", "translation": "[So] they may not listen to the exalted assembly [of angels] and are pelted from every side,"}, {"ayah": 9, "translit": "Duhooranw wa lahum 'azaabunw waasib", "translation": "Repelled; and for them is a constant punishment,"}, {"ayah": 10, "translit": "Illaa man khatifal khatfata fa atba'ahoo shihaabun saaqib", "translation": "Except one who snatches [some words] by theft, but they are pursued by a burning flame, piercing [in brightness]."}, {"ayah": 11, "translit": "Fastaftihim ahum ashaddu khalqan am man khalaqnaa; innaa khalaqnaahum min teenil laazib", "translation": "Then inquire of them, [O Muhammad], \"Are they a stronger [or more difficult] creation or those [others] We have created?\" Indeed, We created men from sticky clay."}, {"ayah": 12, "translit": "Bal'ajibta wa yaskharoon", "translation": "But you wonder, while they mock,"}, {"ayah": 13, "translit": "Wa izaa zukkiroo laa yazkuroon", "translation": "And when they are reminded, they remember not."}, {"ayah": 14, "translit": "Wa izaa ra aw Aayatinw yastaskhiroon", "translation": "And when they see a sign, they ridicule"}, {"ayah": 15, "translit": "Wa qaalooo in haazaa illaa sihrum mubeen", "translation": "And say, \"This is not but obvious magic."}, {"ayah": 16, "translit": "'A-izaa mitnaa wa kunnaa turaabanw wa 'izaaman 'ainnaa lamab'oosoon", "translation": "When we have died and become dust and bones, are we indeed to be resurrected?"}, {"ayah": 17, "translit": "Awa aabaa'unal awwaloon", "translation": "And our forefathers [as well]?\""}, {"ayah": 18, "translit": "Qul na'am wa antum daakhiroon", "translation": "Say, \"Yes, and you will be [rendered] contemptible.\""}, {"ayah": 19, "translit": "Fa innamaa hiya zajra tunw waahidatun fa izaa hum yanzuroon", "translation": "It will be only one shout, and at once they will be observing."}, {"ayah": 20, "translit": "Wa qaaloo yaa wailanaa haazaa Yawmud-Deen", "translation": "They will say, \"O woe to us! This is the Day of Recompense.\""}, {"ayah": 21, "translit": "Haazaa Yawmul Faslil lazee kuntum bihee tukaziboon", "translation": "[They will be told], \"This is the Day of Judgement which you used to deny.\""}, {"ayah": 22, "translit": "Uhshurul lazeena zalamoo wa azwaajahum wa maa kaanoo ya'budoon", "translation": "[The angels will be ordered], \"Gather those who committed wrong, their kinds, and what they used to worship"}, {"ayah": 23, "translit": "Min doonil laahi fahdoohum ilaa siraatil Jaheem", "translation": "Other than Allah, and guide them to the path of Hellfire"}, {"ayah": 24, "translit": "Wa qifoohum innahum mas'ooloon", "translation": "And stop them; indeed, they are to be questioned.\""}, {"ayah": 25, "translit": "Maa lakum laa tanaasaroon", "translation": "[They will be asked], \"What is [wrong] with you? Why do you not help each other?\""}, {"ayah": 26, "translit": "Bal humul Yawma mustaslimoon", "translation": "But they, that Day, are in surrender."}, {"ayah": 27, "translit": "Wa aqbala ba'duhum 'alaa ba'diny yatasaaa'aloon", "translation": "And they will approach one another blaming each other."}, {"ayah": 28, "translit": "Qaalooo innakum kuntum taatoonanaa 'anil yameen", "translation": "They will say, \"Indeed, you used to come at us from the right.\""}, {"ayah": 29, "translit": "Qaaloo bal lam takoonoo mu'mineen", "translation": "The oppressors will say, \"Rather, you [yourselves] were not believers,"}, {"ayah": 30, "translit": "Wa maa kaana lanaa 'alaikum min sultaanim bal kuntum qawman taagheen", "translation": "And we had over you no authority, but you were a transgressing people."}, {"ayah": 31, "translit": "Fahaqqa 'alainaa qawlu Rabbinaaa innaa lazaaa'iqoon", "translation": "So the word of our Lord has come into effect upon us; indeed, we will taste [punishment]."}, {"ayah": 32, "translit": "Fa aghwainaakum innaa kunnaa ghaaween", "translation": "And we led you to deviation; indeed, we were deviators.\""}, {"ayah": 33, "translit": "Fa innahum Yawma'izin fil'azaabi mushtarikoon", "translation": "So indeed they, that Day, will be sharing in the punishment."}, {"ayah": 34, "translit": "Innaa kazaalika naf'alu bil mujrimeen", "translation": "Indeed, that is how We deal with the criminals."}, {"ayah": 35, "translit": "Innahum kaanooo izaa qeela lahum laaa ilaaha illal laahu yastakbiroon", "translation": "Indeed they, when it was said to them, \"There is no deity but Allah,\" were arrogant"}, {"ayah": 36, "translit": "Wa yaqooloona a'innaa lataarikooo aalihatinaa lishaa'irim majnoon", "translation": "And were saying, \"Are we to leave our gods for a mad poet?\""}, {"ayah": 37, "translit": "bal jaaa'a bilhaqqi wa saddaqal mursaleen", "translation": "Rather, the Prophet has come with the truth and confirmed the [previous] messengers."}, {"ayah": 38, "translit": "Innakum lazaaa'iqul 'azaabil aleem", "translation": "Indeed, you [disbelievers] will be tasters of the painful punishment,"}, {"ayah": 39, "translit": "Wa maa tujzawna illaa maa kuntum ta'maloon", "translation": "And you will not be recompensed except for what you used to do -"}, {"ayah": 40, "translit": "Illaa 'ibaadal laahil mukhlaseen", "translation": "But not the chosen servants of Allah."}, {"ayah": 41, "translit": "Ulaaa'ika lahum rizqum ma'loom", "translation": "Those will have a provision determined -"}, {"ayah": 42, "translit": "Fa waakihu wa hum mukramoon", "translation": "Fruits; and they will be honored"}, {"ayah": 43, "translit": "Fee jannaatin Na'eem", "translation": "In gardens of pleasure"}, {"ayah": 44, "translit": "'Alaa sururim mutaqaa bileen", "translation": "On thrones facing one another."}, {"ayah": 45, "translit": "Yutaafu 'alaihim bikaasim mim ma'een", "translation": "There will be circulated among them a cup [of wine] from a flowing spring,"}, {"ayah": 46, "translit": "Baidaaa'a laz zatil lish shaaribeen", "translation": "White and delicious to the drinkers;"}, {"ayah": 47, "translit": "Laa feehaa ghawlunw wa laa hum 'anhaa yunzafoon", "translation": "No bad effect is there in it, nor from it will they be intoxicated."}, {"ayah": 48, "translit": "Wa 'indahum qaasiraatut tarfi 'een", "translation": "And with them will be women limiting [their] glances, with large, [beautiful] eyes,"}, {"ayah": 49, "translit": "Ka annahunna baidum maknoon", "translation": "As if they were [delicate] eggs, well-protected."}, {"ayah": 50, "translit": "Fa aqbala ba'duhum 'alaa badiny yatasaaa 'aloon", "translation": "And they will approach one another, inquiring of each other."}, {"ayah": 51, "translit": "Qaala qaaa'ilum minhum innee kaana lee qareen", "translation": "A speaker among them will say, \"Indeed, I had a companion [on earth]"}, {"ayah": 52, "translit": "Yaqoolu a'innnaka laminal musaddiqeen", "translation": "Who would say, 'Are you indeed of those who believe"}, {"ayah": 53, "translit": "'A-izaa mitnaa wa kunnaa turaabanw wa 'izaaman 'ainnaa lamadeenoon", "translation": "That when we have died and become dust and bones, we will indeed be recompensed?'\""}, {"ayah": 54, "translit": "Qaala hal antum muttali'oon", "translation": "He will say, \"Would you [care to] look?\""}, {"ayah": 55, "translit": "Fattala'a fara aahu fee sawaaa'il Jaheem", "translation": "And he will look and see him in the midst of the Hellfire."}, {"ayah": 56, "translit": "Qaala tallaahi in kitta laturdeen", "translation": "He will say, \"By Allah, you almost ruined me."}, {"ayah": 57, "translit": "Wa law laa ni'matu Rabbee lakuntu minal muhdareen", "translation": "If not for the favor of my Lord, I would have been of those brought in [to Hell]."}, {"ayah": 58, "translit": "Afamaa nahnu bimaiyiteen", "translation": "Then, are we not to die"}, {"ayah": 59, "translit": "Illa mawtatanal oola wa maa nahnu bimu'azzabeen", "translation": "Except for our first death, and we will not be punished?\""}, {"ayah": 60, "translit": "Inna haazaa lahuwal fawzul 'azeem", "translation": "Indeed, this is the great attainment."}, {"ayah": 61, "translit": "Limisli haaza falya'ma lil 'aamiloon", "translation": "For the like of this let the workers [on earth] work."}, {"ayah": 62, "translit": "Azaalika khairun nuzulan am shajaratuz Zaqqom", "translation": "Is Paradise a better accommodation or the tree of zaqqum?"}, {"ayah": 63, "translit": "Innaa ja'alnaahaa fitnatal lizzaalimeen", "translation": "Indeed, We have made it a torment for the wrongdoers."}, {"ayah": 64, "translit": "Innahaa shajaratun takhruju feee aslil Jaheem", "translation": "Indeed, it is a tree issuing from the bottom of the Hellfire,"}, {"ayah": 65, "translit": "Tal'uhaa ka annahoo ru'oosush Shayaateen", "translation": "Its emerging fruit as if it was heads of the devils."}, {"ayah": 66, "translit": "Fa innahum la aakiloona minhaa famaali'oona minhal butoon", "translation": "And indeed, they will eat from it and fill with it their bellies."}, {"ayah": 67, "translit": "Summa inna lahum 'alaihaa lashawbam min hameem", "translation": "Then indeed, they will have after it a mixture of scalding water."}, {"ayah": 68, "translit": "Summa inna marji'ahum la ilal Jaheem", "translation": "Then indeed, their return will be to the Hellfire."}, {"ayah": 69, "translit": "Innahum alfaw aabaaa'ahum daaalleen", "translation": "Indeed they found their fathers astray."}, {"ayah": 70, "translit": "Fahum 'alaa aasaarihim yuhra'oon", "translation": "So they hastened [to follow] in their footsteps."}, {"ayah": 71, "translit": "Wa laqad dalla qablahum aksarul awwaleen", "translation": "And there had already strayed before them most of the former peoples,"}, {"ayah": 72, "translit": "Wa laqad arsalnaa feehim munzireen", "translation": "And We had already sent among them warners."}, {"ayah": 73, "translit": "Fanzur kaifa kaana 'aaqibatul munzareen", "translation": "Then look how was the end of those who were warned -"}, {"ayah": 74, "translit": "Illaa 'ibaadal laahil mukhlaseen", "translation": "But not the chosen servants of Allah."}, {"ayah": 75, "translit": "Wa laqad naadaanaa Noohun falani'mal mujeeboon", "translation": "And Noah had certainly called Us, and [We are] the best of responders."}, {"ayah": 76, "translit": "Wa jajainaahu wa ahlahoo minal karbil 'azeem", "translation": "And We saved him and his family from the great affliction."}, {"ayah": 77, "translit": "Wa ja'alnaa zurriyyatahoo hummul baaqeen", "translation": "And We made his descendants those remaining [on the earth]"}, {"ayah": 78, "translit": "Wa taraknaa 'alaihi fil aakhireen", "translation": "And left for him [favorable mention] among later generations:"}, {"ayah": 79, "translit": "Salaamun 'alaa Noohin fil 'aalameen", "translation": "\"Peace upon Noah among the worlds.\""}, {"ayah": 80, "translit": "Innaa kazaalika najzil muhsineen", "translation": "Indeed, We thus reward the doers of good."}, {"ayah": 81, "translit": "Innahoo min 'ibaadinal mu'mineen", "translation": "Indeed, he was of Our believing servants."}, {"ayah": 82, "translit": "Summa aghraqnal aakhareen", "translation": "Then We drowned the disbelievers."}, {"ayah": 83, "translit": "Wa ina min shee'atihee la Ibraaheem", "translation": "And indeed, among his kind was Abraham,"}, {"ayah": 84, "translit": "Iz jaaa'a Rabbahoo bi qalbin saleem", "translation": "When he came to his Lord with a sound heart"}, {"ayah": 85, "translit": "Iz qaala li abeehi wa qawmihee maazaa ta'budoon", "translation": "[And] when he said to his father and his people, \"What do you worship?"}, {"ayah": 86, "translit": "A'ifkan aalihatan doonal laahi tureedoon", "translation": "Is it falsehood [as] gods other than Allah you desire?"}, {"ayah": 87, "translit": "Famaa zannukum bi Rabbil'aalameen", "translation": "Then what is your thought about the Lord of the worlds?\""}, {"ayah": 88, "translit": "Fanazara nazratan finnujoom", "translation": "And he cast a look at the stars"}, {"ayah": 89, "translit": "Faqaala inee saqeem", "translation": "And said, \"Indeed, I am [about to be] ill.\""}, {"ayah": 90, "translit": "Fatawallaw 'anhu mudbireen", "translation": "So they turned away from him, departing."}, {"ayah": 91, "translit": "Faraagha ilaaa aalihatihim faqaala alaa taakuloon", "translation": "Then he turned to their gods and said, \"Do you not eat?"}, {"ayah": 92, "translit": "Maa lakum laa tantiqoon", "translation": "What is [wrong] with you that you do not speak?\""}, {"ayah": 93, "translit": "Faraagha 'alaihim darbam bilyameen", "translation": "And he turned upon them a blow with [his] right hand."}, {"ayah": 94, "translit": "Fa aqbalooo ilaihi yaziffoon", "translation": "Then the people came toward him, hastening."}, {"ayah": 95, "translit": "Qaala ata'budoona maa tanhitoon", "translation": "He said, \"Do you worship that which you [yourselves] carve,"}, {"ayah": 96, "translit": "Wallaahu khalaqakum wa maa ta'maloon", "translation": "While Allah created you and that which you do?\""}, {"ayah": 97, "translit": "Qaalub noo lahoo bun yaanan fa alqoohu fil jaheem", "translation": "They said, \"Construct for him a furnace and throw him into the burning fire.\""}, {"ayah": 98, "translit": "Fa araadoo bihee kaidan faja 'alnaahumul asfaleen", "translation": "And they intended for him a plan, but We made them the most debased."}, {"ayah": 99, "translit": "Wa qaala innee zaahibun ilaa Rabbee sa yahdeen", "translation": "And [then] he said, \"Indeed, I will go to [where I am ordered by] my Lord; He will guide me."}, {"ayah": 100, "translit": "Rabbi hab lee minas saaliheen", "translation": "My Lord, grant me [a child] from among the righteous.\""}, {"ayah": 101, "translit": "Fabashsharnaahu bighulaamin haleem", "translation": "So We gave him good tidings of a forbearing boy."}, {"ayah": 102, "translit": "Falamma balagha ma'a hus sa'ya qaala yaa buniya inneee araa fil manaami anneee azbahuka fanzur maazaa taraa; qaala yaaa abatif 'al maa tu'maru satajidunee in shaaa'allaahu minas saabireen", "translation": "And when he reached with him [the age of] exertion, he said, \"O my son, indeed I have seen in a dream that I [must] sacrifice you, so see what you think.\" He said, \"O my father, do as you are commanded. You will find me, if Allah wills, of the steadfast.\""}, {"ayah": 103, "translit": "Falammaaa aslamaa wa tallahoo liljabeen", "translation": "And when they had both submitted and he put him down upon his forehead,"}, {"ayah": 104, "translit": "Wa naadainaahu ai yaaaa Ibraheem", "translation": "We called to him, \"O Abraham,"}, {"ayah": 105, "translit": "Qad saddaqtar ru'yaa; innaa kazaalika najzil muhsineen", "translation": "You have fulfilled the vision.\" Indeed, We thus reward the doers of good."}, {"ayah": 106, "translit": "Inna haazaa lahuwal balaaa'ul mubeen", "translation": "Indeed, this was the clear trial."}, {"ayah": 107, "translit": "Wa fadainaahu bizibhin 'azeem", "translation": "And We ransomed him with a great sacrifice,"}, {"ayah": 108, "translit": "Wa taraknaa 'alaihi fil aakhireen", "translation": "And We left for him [favorable mention] among later generations:"}, {"ayah": 109, "translit": "Salaamun 'alaaa Ibraaheem", "translation": "\"Peace upon Abraham.\""}, {"ayah": 110, "translit": "Kazaalika najzil muhsineen", "translation": "Indeed, We thus reward the doers of good."}, {"ayah": 111, "translit": "Innahoo min 'ibaadinal mu'mineen", "translation": "Indeed, he was of Our believing servants."}, {"ayah": 112, "translit": "Wa bashsharnaahu bi Ishaaqa Nabiyam minas saaliheen", "translation": "And We gave him good tidings of Isaac, a prophet from among the righteous."}, {"ayah": 113, "translit": "Wa baaraknaa 'alaihi wa 'alaaa Ishaaq; wa min zurriyya tihimaa muhsinunw wa zaalimul linafshihee mubeen", "translation": "And We blessed him and Isaac. But among their descendants is the doer of good and the clearly unjust to himself."}, {"ayah": 114, "translit": "Wa laqad mananna alaa Moosaa wa Haaroon", "translation": "And We did certainly confer favor upon Moses and Aaron."}, {"ayah": 115, "translit": "Wa najjainaahumaa wa qawmahumaa minal karbil 'azeem", "translation": "And We saved them and their people from the great affliction,"}, {"ayah": 116, "translit": "Wa nasarnaahum fakaanoo humul ghaalibeen", "translation": "And We supported them so it was they who overcame."}, {"ayah": 117, "translit": "Wa aatainaahumal Kitaabal mustabeen", "translation": "And We gave them the explicit Scripture,"}, {"ayah": 118, "translit": "Wa hadainaahumus Siraatal Mustaqeem", "translation": "And We guided them on the straight path."}, {"ayah": 119, "translit": "Wa taraknaa 'alaihimaa fil aakhireen", "translation": "And We left for them [favorable mention] among later generations:"}, {"ayah": 120, "translit": "Salaamun 'alaa Moosaa wa Haaroon", "translation": "\"Peace upon Moses and Aaron.\""}, {"ayah": 121, "translit": "Innaa kazaalika najzil muhsineen", "translation": "Indeed, We thus reward the doers of good."}, {"ayah": 122, "translit": "Innahumaa min 'ibaadinal mu'mineen", "translation": "Indeed, they were of Our believing servants."}, {"ayah": 123, "translit": "Wa inna Ilyaasa laminal mursaleen", "translation": "And indeed, Elias was from among the messengers,"}, {"ayah": 124, "translit": "Iz qaala liqawmiheee alaa tattaqoon", "translation": "When he said to his people, \"Will you not fear Allah?"}, {"ayah": 125, "translit": "Atad'oona Ba'lanw wa tazaroona ahsanal khaaliqeen", "translation": "Do you call upon Ba'l and leave the best of creators -"}, {"ayah": 126, "translit": "Allaaha Rabbakum wa Rabba aabaaa'ikumul awwaleen", "translation": "Allah, your Lord and the Lord of your first forefathers?\""}, {"ayah": 127, "translit": "Fakazzaboohu fa inna hum lamuhdaroon", "translation": "And they denied him, so indeed, they will be brought [for punishment],"}, {"ayah": 128, "translit": "Illaa 'ibaadal laahil mukhlaseen", "translation": "Except the chosen servants of Allah."}, {"ayah": 129, "translit": "Wa taraknaa 'alaihi fil aakhireen", "translation": "And We left for him [favorable mention] among later generations:"}, {"ayah": 130, "translit": "Salaamun 'alaaa Ilyaaseen", "translation": "\"Peace upon Elias.\""}, {"ayah": 131, "translit": "Innaa kazaalika najzil muhsineen", "translation": "Indeed, We thus reward the doers of good."}, {"ayah": 132, "translit": "Innahoo min 'ibaadinal mu'mineen", "translation": "Indeed, he was of Our believing servants."}, {"ayah": 133, "translit": "Wa inna Lootal laminal mursaleen", "translation": "And indeed, Lot was among the messengers."}, {"ayah": 134, "translit": "Iz najjainaahu wa ahlahooo ajma'een", "translation": "[So mention] when We saved him and his family, all,"}, {"ayah": 135, "translit": "Illaa 'ajoozan fil ghaabireen", "translation": "Except his wife among those who remained [with the evildoers]."}, {"ayah": 136, "translit": "Summa dammarnal aakhareen", "translation": "Then We destroyed the others."}, {"ayah": 137, "translit": "Wa innakum latamurroona 'alaihim musbiheen", "translation": "And indeed, you pass by them in the morning"}, {"ayah": 138, "translit": "Wa billail; afalaa ta'qiloon", "translation": "And at night. Then will you not use reason?"}, {"ayah": 139, "translit": "Wa inna Yoonusa laminal mursaleen", "translation": "And indeed, Jonah was among the messengers."}, {"ayah": 140, "translit": "Iz abaqa ilal fulkil mash hoon", "translation": "[Mention] when he ran away to the laden ship."}, {"ayah": 141, "translit": "Fasaahama fakaana minal mudhadeen", "translation": "And he drew lots and was among the losers."}, {"ayah": 142, "translit": "Faltaqamahul hootu wa huwa muleem", "translation": "Then the fish swallowed him, while he was blameworthy."}, {"ayah": 143, "translit": "Falaw laaa annahoo kaana minal musabbiheen", "translation": "And had he not been of those who exalt Allah,"}, {"ayah": 144, "translit": "Lalabisa fee batniheee ilaa Yawmi yub'asoon", "translation": "He would have remained inside its belly until the Day they are resurrected."}, {"ayah": 145, "translit": "Fanabaznaahu bil'araaa'i wa huwa saqeem", "translation": "But We threw him onto the open shore while he was ill."}, {"ayah": 146, "translit": "Wa ambatnaa 'alaihi shajaratam mai yaqteen", "translation": "And We caused to grow over him a gourd vine."}, {"ayah": 147, "translit": "Wa arsalnaahu ilaa mi'ati alfin aw yazeedoon", "translation": "And We sent him to [his people of] a hundred thousand or more."}, {"ayah": 148, "translit": "Fa aamanoo famatta' naahum ilaa heen", "translation": "And they believed, so We gave them enjoyment [of life] for a time."}, {"ayah": 149, "translit": "Fastaftihim ali Rabbikal banaatu wa lahumul banoon", "translation": "So inquire of them, [O Muhammad], \"Does your Lord have daughters while they have sons?"}, {"ayah": 150, "translit": "Am khalaqnal malaaa'i kata inaasanw wa hm shaahidoon", "translation": "Or did We create the angels as females while they were witnesses?\""}, {"ayah": 151, "translit": "Alaaa innahum min ifkihim la yaqooloon", "translation": "Unquestionably, it is out of their [invented] falsehood that they say,"}, {"ayah": 152, "translit": "Waladal laahu wa innhum lakaaziboon", "translation": "\" Allah has begotten,\" and indeed, they are liars."}, {"ayah": 153, "translit": "Astafal banaati 'alal baneen", "translation": "Has He chosen daughters over sons?"}, {"ayah": 154, "translit": "Maa lakum kaifa tahkumoon", "translation": "What is [wrong] with you? How do you make judgement?"}, {"ayah": 155, "translit": "Afalaa tazakkaroon", "translation": "Then will you not be reminded?"}, {"ayah": 156, "translit": "Am lakum sultaanum mubeen", "translation": "Or do you have a clear authority?"}, {"ayah": 157, "translit": "Faatoo bi Kitaabikum in kuntum saadiqeen", "translation": "Then produce your scripture, if you should be truthful."}, {"ayah": 158, "translit": "Wa ja'aloo bainahoo wa bainal jinnati nasabaa; wa laqad 'alimatil jinnatu innahum lamuhdaroon", "translation": "And they have claimed between Him and the jinn a lineage, but the jinn have already known that they [who made such claims] will be brought to [punishment]."}, {"ayah": 159, "translit": "Subhaanal laahi 'ammaa yasifoon", "translation": "Exalted is Allah above what they describe,"}, {"ayah": 160, "translit": "Illaa 'ibaadal laahil mukhlaseen", "translation": "Except the chosen servants of Allah [who do not share in that sin]."}, {"ayah": 161, "translit": "Fa innakum wa maa ta'ubdoon", "translation": "So indeed, you [disbelievers] and whatever you worship,"}, {"ayah": 162, "translit": "Maaa antum 'alaihi befaaatineen", "translation": "You cannot tempt [anyone] away from Him"}, {"ayah": 163, "translit": "Illaa man huwa saalil jaheem", "translation": "Except he who is to [enter and] burn in the Hellfire."}, {"ayah": 164, "translit": "Wa maa minnasa illaa lahoo maqaamum ma'loom", "translation": "[The angels say], \"There is not among us any except that he has a known position."}, {"ayah": 165, "translit": "Wa innaa llanah nus saaffoon", "translation": "And indeed, we are those who line up [for prayer]."}, {"ayah": 166, "translit": "Wa innaa lanah nul musabbihoon", "translation": "And indeed, we are those who exalt Allah.\""}, {"ayah": 167, "translit": "Wa in kaanoo la yaqooloon", "translation": "And indeed, the disbelievers used to say,"}, {"ayah": 168, "translit": "Law anna 'indana zikram minal awwaleen", "translation": "\"If we had a message from [those of] the former peoples,"}, {"ayah": 169, "translit": "Lakunna 'ibaadal laahil mukhlaseen", "translation": "We would have been the chosen servants of Allah.\""}, {"ayah": 170, "translit": "Fakafaroo bihee fasawfa ya'lamoon", "translation": "But they disbelieved in it, so they are going to know."}, {"ayah": 171, "translit": "Wa laqad sabaqat Kalimatunaa li'ibaadinal mursa leen", "translation": "And Our word has already preceded for Our servants, the messengers,"}, {"ayah": 172, "translit": "Innaa hum lahumul mansooroon", "translation": "[That] indeed, they would be those given victory"}, {"ayah": 173, "translit": "Wa inna jundana lahumul ghaaliboon", "translation": "And [that] indeed, Our soldiers will be those who overcome."}, {"ayah": 174, "translit": "Fatawalla 'anhum hatta heen", "translation": "So, [O Muhammad], leave them for a time."}, {"ayah": 175, "translit": "Wa absirhum fasawfa yubsiroon", "translation": "And see [what will befall] them, for they are going to see."}, {"ayah": 176, "translit": "Afabi'azaabinaa yasta'jiloon", "translation": "Then for Our punishment are they impatient?"}, {"ayah": 177, "translit": "Fa izaa nazala bisaahatihim fasaaa'a sabaahul munzareen", "translation": "But when it descends in their territory, then evil is the morning of those who were warned."}, {"ayah": 178, "translit": "Wa tawalla 'anhum hattaa heen", "translation": "And leave them for a time."}, {"ayah": 179, "translit": "Wa absir fasawfa yubsiroon", "translation": "And see, for they are going to see."}, {"ayah": 180, "translit": "Subhaana Rabbika Rabbil 'izzati 'amma yasifoon", "translation": "Exalted is your Lord, the Lord of might, above what they describe."}, {"ayah": 181, "translit": "Wa salaamun 'alalmursaleen", "translation": "And peace upon the messengers."}, {"ayah": 182, "translit": "Walhamdu lillaahi Rabbil 'aalameen", "translation": "And praise to Allah, Lord of the worlds."}]}, {"num": 38, "name": "Sad", "meaning": "Sad", "verses": [{"ayah": 1, "translit": "Saaad; wal-Qur-aani ziz zikr", "translation": "Sad. By the Qur'an containing reminder..."}, {"ayah": 2, "translit": "Balil lazeena kafaroo fee 'izzatilnw wa shiqaaq", "translation": "But those who disbelieve are in pride and dissension."}, {"ayah": 3, "translit": "Kam ahlaknaa min qablihim min qarnin fanaadaw wa laata heena manaas", "translation": "How many a generation have We destroyed before them, and they [then] called out; but it was not a time for escape."}, {"ayah": 4, "translit": "Wa 'ajibooo an jaaa'a hum munzirum minhum wa qaalal kaafiroona haazaa saahirun kazzaab", "translation": "And they wonder that there has come to them a warner from among themselves. And the disbelievers say, \"This is a magician and a liar."}, {"ayah": 5, "translit": "Aja'alal aalihata Ilaahanw Waahidan inna haazaa lashai'un 'ujaab", "translation": "Has he made the gods [only] one God? Indeed, this is a curious thing.\""}, {"ayah": 6, "translit": "Wantalaqal mala-u minhum anim shoo wasbiroo 'alaaa aalihatikum innna haazaa lashai 'uny yuraad", "translation": "And the eminent among them went forth, [saying], \"Continue, and be patient over [the defense of] your gods. Indeed, this is a thing intended."}, {"ayah": 7, "translit": "Maa sami'naa bihaazaa fil millatil aakhirati in haazaaa illakh tilaaq", "translation": "We have not heard of this in the latest religion. This is not but a fabrication."}, {"ayah": 8, "translit": "'A-unzila 'alaihiz zikru mim baininaa; bal hum fee shakkim min Zikree bal lammaa yazooqoo 'azaab", "translation": "Has the message been revealed to him out of [all of] us?\" Rather, they are in doubt about My message. Rather, they have not yet tasted My punishment."}, {"ayah": 9, "translit": "Am'indahum khazaaa 'inu rahmati Rabbikal 'Azeezil Wahhab", "translation": "Or do they have the depositories of the mercy of your Lord, the Exalted in Might, the Bestower?"}, {"ayah": 10, "translit": "Am lahum mulkus samaawaati wal ardi wa maa bainahumaa falyartaqoo fil asbaab", "translation": "Or is theirs the dominion of the heavens and the earth and what is between them? Then let them ascend through [any] ways of access."}, {"ayah": 11, "translit": "Jundum maa hunaalika mahzoomum minal Ahzaab", "translation": "[They are but] soldiers [who will be] defeated there among the companies [of disbelievers]."}, {"ayah": 12, "translit": "Kazzabat qablahum qawmu Lootinw-wa 'Aadunw wa Fir'awnu zul awtaad", "translation": "The people of Noah denied before them, and [the tribe of] 'Aad and Pharaoh, the owner of stakes,"}, {"ayah": 13, "translit": "Wa Samoodu wa qawmu Lootinw wa Ashaabul 'Aykah; ulaaa'ikal Ahzaab", "translation": "And [the tribe of] Thamud and the people of Lot and the companions of the thicket. Those are the companies."}, {"ayah": 14, "translit": "In kullun illaa kazzabar Rusula fahaqqa 'iqaab", "translation": "Each of them denied the messengers, so My penalty was justified."}, {"ayah": 15, "translit": "Wa maa yanzuru haaa ulaaa'i illaa saihatanw waahidatam maa lahaa min fawaaq", "translation": "And these [disbelievers] await not but one blast [of the Horn]; for it there will be no delay."}, {"ayah": 16, "translit": "Wa qaaloo Rabbanaa 'ajjil lanaa qittanaa qabla Yawmil Hisaab", "translation": "And they say, \"Our Lord, hasten for us our share [of the punishment] before the Day of Account\""}, {"ayah": 17, "translit": "Isbir 'alaa maa yaqooloona wazkur 'abdanaa Daawooda zal aidi aidi innahooo awwaab", "translation": "Be patient over what they say and remember Our servant, David, the possessor of strength; indeed, he was one who repeatedly turned back [to Allah]."}, {"ayah": 18, "translit": "Innaa sakhkharnal jibaala ma'ahoo yusabbihna bil'ashaiyi wal ishraaq", "translation": "Indeed, We subjected the mountains [to praise] with him, exalting [Allah] in the [late] afternoon and [after] sunrise."}, {"ayah": 19, "translit": "Wattayra mahshoorah; kullul lahooo awwaab", "translation": "And the birds were assembled, all with him repeating [praises]."}, {"ayah": 20, "translit": "Wa shadadnaa mulkahoo wa aatainaahul Hikmata wa faslal khitaab", "translation": "And We strengthened his kingdom and gave him wisdom and discernment in speech."}, {"ayah": 21, "translit": "Wa hal ataaka naba'ul khasm; iz tasawwarul mihraab", "translation": "And has there come to you the news of the adversaries, when they climbed over the wall of [his] prayer chamber -"}, {"ayah": 22, "translit": "Iz dakhaloo 'alaa Daawooda fafazi'a minhum qaaloo la takhaf khasmaani baghaa ba'dunaa 'alaa ba'din fahkum bainanaaa bilhaqqi wa laa tushtit wahdinaaa ilaa Sawaaa'is Siraat", "translation": "When they entered upon David and he was alarmed by them? They said, \"Fear not. [We are] two adversaries, one of whom has wronged the other, so judge between us with truth and do not exceed [it] and guide us to the sound path."}, {"ayah": 23, "translit": "Inna haazaaa akhee lahoo tis'unw wa tis'oona na'jatanw wa liya na'jatunw waahidah; faqaala akfilneeha wa 'azzanee filkhitaab", "translation": "Indeed this, my brother, has ninety-nine ewes, and I have one ewe; so he said, 'Entrust her to me,' and he overpowered me in speech.\""}, {"ayah": 24, "translit": "Qaala laqad zalamaka bisu 'aali na'jatika ilaa ni'aajihee wa inna kaseeram minal khulataaa'i la-yabghee ba'duhum 'alaa ba'din illal lazeena aamanoo wa 'amilus saalihaati wa qaleehum maa hum; wa zanna Daawoodu annamaa fatannaahu fastaghrara Rabbahoo wa kharra raaki'anw wa anaab", "translation": "[David] said, \"He has certainly wronged you in demanding your ewe [in addition] to his ewes. And indeed, many associates oppress one another, except for those who believe and do righteous deeds - and few are they.\" And David became certain that We had tried him, and he asked forgiveness of his Lord and fell down bowing [in prostration] and turned in repentance [to Allah]."}, {"ayah": 25, "translit": "Faghafarnaa lahoo zaalik; wa inna lahoo 'indanaa lazulfaa wa husna ma aab", "translation": "So We forgave him that; and indeed, for him is nearness to Us and a good place of return."}, {"ayah": 26, "translit": "Yaa Daawoodu innaa ja'alnaaka khaleefatan fil ardi fahkum bainan naasi bilhaqqi wa laa tattabi'il hawaa fayudillaka 'an sabeelil laah; innal lazeena yadilloona 'an sabeelil laah; lahum 'azaabun shadeedum bimaa nasoo Yawmal Hisaab", "translation": "[We said], \"O David, indeed We have made you a successor upon the earth, so judge between the people in truth and do not follow [your own] desire, as it will lead you astray from the way of Allah.\" Indeed, those who go astray from the way of Allah will have a severe punishment for having forgotten the Day of Account."}, {"ayah": 27, "translit": "Wa ma khalaqnas samaaa'a wal arda wa maa bainahumaa baatilaa; zaalika zannul lazeena kafaroo; fawi lul lillazeena kafaroo minan Naar", "translation": "And We did not create the heaven and the earth and that between them aimlessly. That is the assumption of those who disbelieve, so woe to those who disbelieve from the Fire."}, {"ayah": 28, "translit": "Am naj'alul lazeena aamanoo wa 'amilus saalihaati kalmufisdeena fil ardi am naj'alul muttaqeena kalfujjaar", "translation": "Or should we treat those who believe and do righteous deeds like corrupters in the land? Or should We treat those who fear Allah like the wicked?"}, {"ayah": 29, "translit": "Kitaabun anzalnaahu ilaika mubaarakul liyaddabbarooo Aayaatihee wa liyatazakkara ulul albaab", "translation": "[This is] a blessed Book which We have revealed to you, [O Muhammad], that they might reflect upon its verses and that those of understanding would be reminded."}, {"ayah": 30, "translit": "Wa wahabnaa li Daawooda Sulaimaan; ni'mal 'abd; innahoo awwaab", "translation": "And to David We gave Solomon. An excellent servant, indeed he was one repeatedly turning back [to Allah]."}, {"ayah": 31, "translit": "Iz 'urida 'alaihi bil'ashiy yis saafinaatul jiyaad", "translation": "[Mention] when there were exhibited before him in the afternoon the poised [standing] racehorses."}, {"ayah": 32, "translit": "Faqaala inneee ahbabtu hubbal khairi 'an zikri Rabbee hattaa tawaarat bilhijaab", "translation": "And he said, \"Indeed, I gave preference to the love of good [things] over the remembrance of my Lord until the sun disappeared into the curtain [of darkness].\""}, {"ayah": 33, "translit": "Ruddoohaa 'alaiya fatafiqa masham bissooqi wal a'naaq", "translation": "[He said], \"Return them to me,\" and set about striking [their] legs and necks."}, {"ayah": 34, "translit": "Wa laqad fatannaa Sulaimaana wa alqainaa 'alaa kursiyyihee jasadan summa anaab", "translation": "And We certainly tried Solomon and placed on his throne a body; then he returned."}, {"ayah": 35, "translit": "Qaala Rabbigh fir lee wa hab lee mulkal laa yambaghee li ahadim mim ba'de inaka Antal Wahhab", "translation": "He said, \"My Lord, forgive me and grant me a kingdom such as will not belong to anyone after me. Indeed, You are the Bestower.\""}, {"ayah": 36, "translit": "Fasakhkharnaa lahur reeha tajree bi amrihee rukhaaa'an haisu asaab", "translation": "So We subjected to him the wind blowing by his command, gently, wherever he directed,"}, {"ayah": 37, "translit": "Wash Shayaateena kulla bannaaa'inw wa ghawwaas", "translation": "And [also] the devils [of jinn] - every builder and diver"}, {"ayah": 38, "translit": "Wa aakhareena muqarraneena fil asfaad", "translation": "And others bound together in shackles."}, {"ayah": 39, "translit": "Haazaa 'ataaa'unaa famnun aw amsik bighairi hisaab", "translation": "[We said], \"This is Our gift, so grant or withhold without account.\""}, {"ayah": 40, "translit": "Wa inna lahoo 'indanaa lazulfaa wa husna ma-aab", "translation": "And indeed, for him is nearness to Us and a good place of return."}, {"ayah": 41, "translit": "Wazkur 'abdanaaa Ayyoob; iz naada Rabbahooo annee massaniyash Shaitaanu binus binw wa 'azaab", "translation": "And remember Our servant Job, when he called to his Lord, \"Indeed, Satan has touched me with hardship and torment.\""}, {"ayah": 42, "translit": "Urkud birijlika haaza mughtasalum baaridunw wa sharaab", "translation": "[So he was told], \"Strike [the ground] with your foot; this is a [spring for] a cool bath and drink.\""}, {"ayah": 43, "translit": "Wa wahabnaa lahoo ahlahoo wa mislahum ma'ahum rahmatam minna wa zikraa li ulil albaab", "translation": "And We granted him his family and a like [number] with them as mercy from Us and a reminder for those of understanding."}, {"ayah": 44, "translit": "Wa khuz biyadika dighsan fadrib bihee wa laa tahnas, innaa wajadnaahu saabiraa; ni'mal 'abd; innahooo awwaab", "translation": "[We said], \"And take in your hand a bunch [of grass] and strike with it and do not break your oath.\" Indeed, We found him patient, an excellent servant. Indeed, he was one repeatedly turning back [to Allah]."}, {"ayah": 45, "translit": "Wazkur 'ibaadanaaa Ibraaheema wa Is-haaqa wa Ya'qooba ulil-aydee walabsaar", "translation": "And remember Our servants, Abraham, Isaac and Jacob - those of strength and [religious] vision."}, {"ayah": 46, "translit": "Innaaa akhlasnaahum bi khaalisatin zikrad daar", "translation": "Indeed, We chose them for an exclusive quality: remembrance of the home [of the Hereafter]."}, {"ayah": 47, "translit": "Wa innahum 'indanaa laminal mustafainal akhyaar", "translation": "And indeed they are, to Us, among the chosen and outstanding."}, {"ayah": 48, "translit": "Wazkur Ismaa'eela wal Yasa'a wa Zal-Kifli wa kullum minal akhyaar", "translation": "And remember Ishmael, Elisha and Dhul-Kifl, and all are among the outstanding."}, {"ayah": 49, "translit": "Haazaa zikr; wa inna lilmuttaqeena lahusna ma aab", "translation": "This is a reminder. And indeed, for the righteous is a good place of return"}, {"ayah": 50, "translit": "Jannaati 'adnim mufat tahatal lahumul abwaab", "translation": "Gardens of perpetual residence, whose doors will be opened to them."}, {"ayah": 51, "translit": "Muttaki'eena feehaa yad'oona feehaa bifaakihatin kaseeratinw wa sharaab", "translation": "Reclining within them, they will call therein for abundant fruit and drink."}, {"ayah": 52, "translit": "Wa 'indahum qaasiraatut tarfi atraab", "translation": "And with them will be women limiting [their] glances and of equal age."}, {"ayah": 53, "translit": "Haaza maa too'odoona li Yawmil Hisaab", "translation": "This is what you, [the righteous], are promised for the Day of Account."}, {"ayah": 54, "translit": "Inna haazaa larizqunaa maa lahoo min nafaad", "translation": "Indeed, this is Our provision; for it there is no depletion."}, {"ayah": 55, "translit": "Haazaa; wa inna littaagheena lasharra ma-aab", "translation": "This [is so]. But indeed, for the transgressors is an evil place of return -"}, {"ayah": 56, "translit": "Jahannama yaslawnahaa fai'sal mihaad", "translation": "Hell, which they will [enter to] burn, and wretched is the resting place."}, {"ayah": 57, "translit": "Haazaa falyazooqoohu hameemunw wa ghassaaq", "translation": "This - so let them taste it - is scalding water and [foul] purulence."}, {"ayah": 58, "translit": "Wa aakharu min shak liheee azwaaj", "translation": "And other [punishments] of its type [in various] kinds."}, {"ayah": 59, "translit": "Haazaa fawjum muqtahimum ma'akum laa marhabam bihim; innahum saalun Naar", "translation": "[Its inhabitants will say], \"This is a company bursting in with you. No welcome for them. Indeed, they will burn in the Fire.\""}, {"ayah": 60, "translit": "Qaaloo bal antum laa marhabam bikum; antum qaddamtumoohu lanaa fabi'sal qaraar", "translation": "They will say, \"Nor you! No welcome for you. You, [our leaders], brought this upon us, and wretched is the settlement.\""}, {"ayah": 61, "translit": "Qaaloo Rabbanaa man qaddama lanaa haaza fazidhu 'azaaban di'fan fin Naar", "translation": "They will say, \"Our Lord, whoever brought this upon us - increase for him double punishment in the Fire.\""}, {"ayah": 62, "translit": "Wa qaaloo ma lanaa laa naraa rijaalan kunnaa na'udduhum minal ashraar", "translation": "And they will say, \"Why do we not see men whom we used to count among the worst?"}, {"ayah": 63, "translit": "Attakhaznaahum sikh riyyan am zaaghat 'anhumul absaar", "translation": "Is it [because] we took them in ridicule, or has [our] vision turned away from them?\""}, {"ayah": 64, "translit": "Inna zaalika lahaqqun takhaasumu Ahlin Naar", "translation": "Indeed, that is truth - the quarreling of the people of the Fire."}, {"ayah": 65, "translit": "Qul innamaaa ana munzirunw wa maa min ilaahim illal laahul Waahidul Qahhaar", "translation": "Say, [O Muhammad], \"I am only a warner, and there is not any deity except Allah, the One, the Prevailing."}, {"ayah": 66, "translit": "Rabbus samaawaati wal ardi wa maa bainahumal 'Azeezul Ghaffaar", "translation": "Lord of the heavens and the earth and whatever is between them, the Exalted in Might, the Perpetual Forgiver.\""}, {"ayah": 67, "translit": "Qul huwa naba'un 'azeem", "translation": "Say, \"It is great news"}, {"ayah": 68, "translit": "Antum 'anhu mu'ridoon", "translation": "From which you turn away."}, {"ayah": 69, "translit": "Maa kaana liya min 'ilmim bilmala il a'laaa iz yakhtasimoon", "translation": "I had no knowledge of the exalted assembly [of angels] when they were disputing [the creation of Adam]."}, {"ayah": 70, "translit": "Iny-yoohaaa ilaiya illaaa annnamaaa ana nazeerum mubeen", "translation": "It has not been revealed to me except that I am a clear warner.\""}, {"ayah": 71, "translit": "Iz qaala Rabbuka lilmalaaa'ikati innee khaaliqum basharam min teen", "translation": "[So mention] when your Lord said to the angels, \"Indeed, I am going to create a human being from clay."}, {"ayah": 72, "translit": "Fa-iza sawwaituhoo wa nafakhtu feehi mir roohee faqa'oo lahoo saajideen", "translation": "So when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration.\""}, {"ayah": 73, "translit": "Fasajadal malaaa'ikatu kulluhum ajma'oon", "translation": "So the angels prostrated - all of them entirely."}, {"ayah": 74, "translit": "Illaaa Iblees; istakbara wa kaana minal kaafireen", "translation": "Except Iblees; he was arrogant and became among the disbelievers."}, {"ayah": 75, "translit": "Qaala yaaa Ibleesu maa man'aka an tasjuda limaa khalaqtu biyadai; astakbarta am kunta min 'aaleen", "translation": "[Allah] said, \"O Iblees, what prevented you from prostrating to that which I created with My hands? Were you arrogant [then], or were you [already] among the haughty?\""}, {"ayah": 76, "translit": "Qaala ana khairum minah; khalaqtanee min naarinw wa khalaqtahoo min teen", "translation": "He said, \"I am better than him. You created me from fire and created him from clay.\""}, {"ayah": 77, "translit": "Qaala fakhruj minhaa fainnaka rajeem", "translation": "[Allah] said, \"Then get out of Paradise, for indeed, you are expelled."}, {"ayah": 78, "translit": "Wa inna 'alaika la'nateee ilaa Yawmid Deen", "translation": "And indeed, upon you is My curse until the Day of Recompense.\""}, {"ayah": 79, "translit": "Qaala Rabbi fa anzirneee ilaa Yawmi yub'asoon", "translation": "He said, \"My Lord, then reprieve me until the Day they are resurrected.\""}, {"ayah": 80, "translit": "Qaala fa innaka minal munzareen", "translation": "[Allah] said, \"So indeed, you are of those reprieved"}, {"ayah": 81, "translit": "Ilaa Yawmil waqtil ma'loom", "translation": "Until the Day of the time well-known.\""}, {"ayah": 82, "translit": "Qaala fabi'izzatika la ughwiyannahum ajma'een", "translation": "[Iblees] said, \"By your might, I will surely mislead them all"}, {"ayah": 83, "translit": "Illaa 'ibaadaka minhumul mukhlaseen", "translation": "Except, among them, Your chosen servants.\""}, {"ayah": 84, "translit": "Qaala falhaqq, walhaqqa aqool", "translation": "[Allah] said, \"The truth [is My oath], and the truth I say -"}, {"ayah": 85, "translit": "La amla'annna Jahannama minka wa mimman tabi'aka minhum ajma'een", "translation": "[That] I will surely fill Hell with you and those of them that follow you all together.\""}, {"ayah": 86, "translit": "Qul maaa as'alukum 'alaihi min ajrinw wa maaa ana minal mutakallifeen", "translation": "Say, [O Muhammad], \"I do not ask you for the Qur'an any payment, and I am not of the pretentious"}, {"ayah": 87, "translit": "In huwa illaa zikrul lil'aalameen", "translation": "It is but a reminder to the worlds."}, {"ayah": 88, "translit": "Wa lata'lamunna naba ahoo ba'da heen", "translation": "And you will surely know [the truth of] its information after a time.\""}]}, {"num": 39, "name": "Az-Zumar", "meaning": "The Troops", "verses": [{"ayah": 1, "translit": "Tanzeelul Kitaabi minal laahil 'Azeezil Hakeem", "translation": "The revelation of the Qur'an is from Allah, the Exalted in Might, the Wise."}, {"ayah": 2, "translit": "Innaaa anzalnaaa ilaikal Kitaaba bilhaqqi fa'budil laaha mukhlisal lahud deen", "translation": "Indeed, We have sent down to you the Book, [O Muhammad], in truth. So worship Allah, [being] sincere to Him in religion."}, {"ayah": 3, "translit": "Alaa lillaahid deenul khaalis; wallazeenat takhazoo min dooniheee awliyaaa'a maa na'buduhum illaa liyuqar riboonaaa ilal laahi zulfaa; innal laaha yahkumu baina hum fee maa hum feehi yakhtalifoon; innal laaha laa yahdee man huwa kaazibun kaffaar", "translation": "Unquestionably, for Allah is the pure religion. And those who take protectors besides Him [say], \"We only worship them that they may bring us nearer to Allah in position.\" Indeed, Allah will judge between them concerning that over which they differ. Indeed, Allah does not guide he who is a liar and [confirmed] disbeliever."}, {"ayah": 4, "translit": "Law araadal laahu aiyattakhiza waladal lastafaa mimmaa yakhluqu maa yashaaa'; Subhaanahoo Huwal laahul Waahidul Qahhaar", "translation": "If Allah had intended to take a son, He could have chosen from what He creates whatever He willed. Exalted is He; He is Allah, the One, the Prevailing."}, {"ayah": 5, "translit": "Khalaqas samaawaati wal arda bilhaqq; yukawwirul laila 'alan nahaari wa yukawwirun nahaara 'alaal laili wa sakhkharash shamsa walqamara kulluny yajree li ajalim musammaa; alaa Huwal 'Azeezul Ghaffaar", "translation": "He created the heavens and earth in truth. He wraps the night over the day and wraps the day over the night and has subjected the sun and the moon, each running [its course] for a specified term. Unquestionably, He is the Exalted in Might, the Perpetual Forgiver."}, {"ayah": 6, "translit": "Khalaqakum min nafsinw waahidatin summa ja'ala minhaa zawjahaa wa anzala lakum minal-an'aami samaani yata azwaaj; yakhuluqukum fee butooni ummahaatikum khalqam mim ba'di khalqin fee zulumaatin salaas; zaalikumul laahu Rabbukum lahul mulk; laaa ilaaha illaa Huwa fa annaa tusrafoon", "translation": "He created you from one soul. Then He made from it its mate, and He produced for you from the grazing livestock eight mates. He creates you in the wombs of your mothers, creation after creation, within three darknesses. That is Allah, your Lord; to Him belongs dominion. There is no deity except Him, so how are you averted?"}, {"ayah": 7, "translit": "In takfuroo fa innal laaha ghaniyyun 'ankum; wa laa yardaa li'ibaadihil kufra wa in tashkuroo yardahu lakum; wa laa taziru waaziratunw wizra ukhraa; summa ilaa Rabikum marji'ukum fa-yunabbi'ukum bimaa kuntum ta'maloon; innahoo 'aleemum bizaatissudoor", "translation": "If you disbelieve - indeed, Allah is Free from need of you. And He does not approve for His servants disbelief. And if you are grateful, He approves it for you; and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you about what you used to do. Indeed, He is Knowing of that within the breasts."}, {"ayah": 8, "translit": "Wa izaa massal insaana durrun da'aa Rabbahoo muneeban ilaihi summa izaa khawwalahoo ni'matam minhu nasiya maa kaana yad'ooo ilaihi min qablu wa ja'ala lillaahi andaadal liyudilla 'ansabeelih; qul tamatta' bikufrika qaleelan innaka min Ashaabin Naar;", "translation": "And when adversity touches man, he calls upon his Lord, turning to Him [alone]; then when He bestows on him a favor from Himself, he forgets Him whom he called upon before, and he attributes to Allah equals to mislead [people] from His way. Say, \"Enjoy your disbelief for a little; indeed, you are of the companions of the Fire.\""}, {"ayah": 9, "translit": "Amman huwa qaanitun aanaaa'al laili saajidanw wa qaaa'imai yahzarul Aakhirata wa yarjoo rahmata Rabbih; qul hal yastawil lazeena ya'lamoona wallazeena laa ya'lamoon; innamaa yatazakkaru ulul albaab", "translation": "Is one who is devoutly obedient during periods of the night, prostrating and standing [in prayer], fearing the Hereafter and hoping for the mercy of his Lord, [like one who does not]? Say, \"Are those who know equal to those who do not know?\" Only they will remember [who are] people of understanding."}, {"ayah": 10, "translit": "Qul yaa 'ibaadil lazeena aamanut taqoo Rabbakum; lillazeena ahsanoo fee haazihid dunyaa hasanah; wa ardul laahi waasi'ah; innamaa yuwaffas saabiroona ajrahum bighayri hisab", "translation": "Say, \"O My servants who have believed, fear your Lord. For those who do good in this world is good, and the earth of Allah is spacious. Indeed, the patient will be given their reward without account.\""}, {"ayah": 11, "translit": "Qul inneee umirtu an a'budal laaha mukhlisal lahud deen", "translation": "Say, [O Muhammad], \"Indeed, I have been commanded to worship Allah, [being] sincere to Him in religion."}, {"ayah": 12, "translit": "Wa umirtu li an akoona awwalal muslimeen", "translation": "And I have been commanded to be the first [among you] of the Muslims.\""}, {"ayah": 13, "translit": "Qul inneee akhaafu in 'asaitu Rabbee 'azaaba Yawmin 'azeem", "translation": "Say, \"Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day.\""}, {"ayah": 14, "translit": "Qulil laaha a'budu mukhlisal lahoo deenee", "translation": "Say, \"Allah [alone] do I worship, sincere to Him in my religion,"}, {"ayah": 15, "translit": "Fa'budoo maa shi'tum min doonih; qul innal khaasireenal lazeena khasirooo anfusahum wa ahleehim yawmal qiyaamah; alaa zaalika huwal khusraanul mubeen", "translation": "So worship what you will besides Him.\" Say, \"Indeed, the losers are the ones who will lose themselves and their families on the Day of Resurrection. Unquestionably, that is the manifest loss.\""}, {"ayah": 16, "translit": "Lahum min fawqihim zulalum minan Naari wa min tahtihim zulal; zaalika yukhaw wiful laahu bihee 'ibaadah; yaa 'ibaadi fattaqoon", "translation": "They will have canopies of fire above them and below them, canopies. By that Allah threatens His servants. O My servants, then fear Me."}, {"ayah": 17, "translit": "Wallazeenaj tanabut Taaghoota ai ya'budoohaa wa anaabooo ilal laahi lahumul bushraa; fabashshir 'ibaad", "translation": "But those who have avoided Taghut, lest they worship it, and turned back to Allah - for them are good tidings. So give good tidings to My servants"}, {"ayah": 18, "translit": "Allazeena yastami'oonal qawla fayattabi'oona ahsanah; ulaaa'ikal lazeena hadaahumul laahu wa ulaaa'ika hum ulul albaab", "translation": "Who listen to speech and follow the best of it. Those are the ones Allah has guided, and those are people of understanding."}, {"ayah": 19, "translit": "Afaman haqqa 'alaihi kalimatul 'azaab; afa anta tunqizu man fin Naar", "translation": "Then, is one who has deserved the decree of punishment [to be guided]? Then, can you save one who is in the Fire?"}, {"ayah": 20, "translit": "Laakinil lazeenat taqaw Rabbahum lahum ghurafum min fawqihaa ghurafum mabniyyatun tajree min tahtihal anhaar; wa'dal laah; laa yukhliful laahul mee'aad", "translation": "But those who have feared their Lord - for them are chambers, above them chambers built high, beneath which rivers flow. [This is] the promise of Allah. Allah does not fail in [His] promise."}, {"ayah": 21, "translit": "Alam tara annal laaha anzala minas samaaa'i maaa'an fasalakahoo yanaabee'a fil ardi summa yukhriju bihee zar'am mukhtalifan alwaanuhoo summa yaheeju fatarahu musfarran summa yaj'aluhoo hutaamaa; inna fee zaalika lazikraa li ulil albaab", "translation": "Do you not see that Allah sends down rain from the sky and makes it flow as springs [and rivers] in the earth; then He produces thereby crops of varying colors; then they dry and you see them turned yellow; then He makes them [scattered] debris. Indeed in that is a reminder for those of understanding."}, {"ayah": 22, "translit": "Afaman sharahal laahu sadrahoo lil Islaami fahuwa 'alaa noorim mir Rabbih; fa wailul lilqaasiyati quloobuhum min zikril laah; ulaaa'ika fee dalaalim mubeen", "translation": "So is one whose breast Allah has expanded to [accept] Islam and he is upon a light from his Lord [like one whose heart rejects it]? Then woe to those whose hearts are hardened against the remembrance of Allah. Those are in manifest error."}, {"ayah": 23, "translit": "Allahu nazzala ahsanal hadeesi Kitaabam mutashaa biham masaaniy taqsha'irru minhu juloodul lazeena yakhshawna Rabbahum summa taleenu julooduhum wa quloo buhum ilaa zikril laah; zaalika hudal laahi yahdee bihee mai yashaaa'; wa mai yudlilil laahu famaa lahoo min haad", "translation": "Allah has sent down the best statement: a consistent Book wherein is reiteration. The skins shiver therefrom of those who fear their Lord; then their skins and their hearts relax at the remembrance of Allah. That is the guidance of Allah by which He guides whom He wills. And one whom Allah leaves astray - for him there is no guide."}, {"ayah": 24, "translit": "Afamai yattaqee biwaj hihee sooo'al 'azaabi Yawmal Qiyaamah; wa qeela lizzaali meena zooqoo maa kuntum taksiboon", "translation": "Then is he who will shield with his face the worst of the punishment on the Day of Resurrection [like one secure from it]? And it will be said to the wrongdoers, \"Taste what you used to earn.\""}, {"ayah": 25, "translit": "Kazzabal lazeena min qablihim fa ataahumul 'azaabu min haisu laa yash'uroon", "translation": "Those before them denied, and punishment came upon them from where they did not perceive."}, {"ayah": 26, "translit": "Fa azaaqahumul laahul khizya fil hayaatid dunyaa wa la'azaabul Aakirati akbar; law kaanoo ya'lamoon", "translation": "So Allah made them taste disgrace in worldly life. But the punishment of the Hereafter is greater, if they only knew."}, {"ayah": 27, "translit": "Wa laqad darabnaa linnaasi fee haazal Qur-aani min kulli masalil la'allahum yatazakkaroon", "translation": "And We have certainly presented for the people in this Qur'an from every [kind of] example - that they might remember."}, {"ayah": 28, "translit": "Qur-aanan 'Arabiyyan ghaira zee 'iwajil la'allahum yattaqoon", "translation": "[It is] an Arabic Qur'an, without any deviance that they might become righteous."}, {"ayah": 29, "translit": "Darabal laahu masalar rajulan feehi shurakaaa'u mutashaakisoona wa rajulan salamal lirajulin hal tastawi yaani masalaa; alhamdu lillaah; bal aksaruhum laa ya'lamoon", "translation": "Allah presents an example: a slave owned by quarreling partners and another belonging exclusively to one man - are they equal in comparison? Praise be to Allah! But most of them do not know."}, {"ayah": 30, "translit": "Innaka maiyitunw wa inna hum maiyitunw wa inna hum maiyitoon", "translation": "Indeed, you are to die, and indeed, they are to die."}, {"ayah": 31, "translit": "Summa innakum Yawmal Qiyaamati 'inda Rabbikum takhtasimoon", "translation": "Then indeed you, on the Day of Resurrection, before your Lord, will dispute."}, {"ayah": 32, "translit": "Faman azlamu mimman kazaba 'alal laahi wa kazzaba bissidqi iz jaaa'ah; alaisa fee Jahannama maswal lilkaafir", "translation": "So who is more unjust than one who lies about Allah and denies the truth when it has come to him? Is there not in Hell a residence for the disbelievers?"}, {"ayah": 33, "translit": "Wallazee jaaa'a bissidqi wa saddaqa biheee ulaaa'ika humul muttaqoon", "translation": "And the one who has brought the truth and [they who] believed in it - those are the righteous."}, {"ayah": 34, "translit": "Lahum maa yashaaa'oona 'inda Rabbihim; zaalika jazaaa'ul muhsineen", "translation": "They will have whatever they desire with their Lord. That is the reward of the doers of good -"}, {"ayah": 35, "translit": "Liyukaffiral laahu 'anhum aswa allazee 'amiloo wa yajziyahum ajrahum bi ahsanil lazee kaano ya'maloon", "translation": "That Allah may remove from them the worst of what they did and reward them their due for the best of what they used to do."}, {"ayah": 36, "translit": "Alaisal laahu bikaafin 'abdahoo wa yukhawwi foonaka billazeena min doonih; wa mai yudlilil laahu famaa lahoo min haad", "translation": "Is not Allah sufficient for His Servant [Prophet Muhammad]? And [yet], they threaten you with those [they worship] other than Him. And whoever Allah leaves astray - for him there is no guide."}, {"ayah": 37, "translit": "Wa mai yahdil laahu famalahoo mim mudlil; alai sal laahu bi'azeezin zin tiqaam", "translation": "And whoever Allah guides - for him there is no misleader. Is not Allah Exalted in Might and Owner of Retribution?"}, {"ayah": 38, "translit": "Wa la'in sa altahum man khalaqas samaawaati wal arda la yaqoolunal laah; qul afara'aitum maa tad'oona min doonil laahi in araadaniyal laahu bidurrin hal hunna kaashi faatu durriheee aw araadanee birahmatin hal hunna mumsikaatu rahmatih; qul hasbiyal laahu 'alaihi tatawakkalul mutawakkiloon", "translation": "And if you asked them, \"Who created the heavens and the earth?\" they would surely say, \"Allah.\" Say, \"Then have you considered what you invoke besides Allah? If Allah intended me harm, are they removers of His harm; or if He intended me mercy, are they withholders of His mercy?\" Say, \"Sufficient for me is Allah; upon Him [alone] rely the [wise] reliers.\""}, {"ayah": 39, "translit": "Qul yaa qawmi'maloo 'alaa makaanatikum innee 'aamilun fasawfa ta'lamoon", "translation": "Say, \"O my people, work according to your position, [for] indeed, I am working; and you are going to know"}, {"ayah": 40, "translit": "Mai yaateehi 'azaabuny yukhzeehi wa yahillu 'alaihi 'azaabum muqeem", "translation": "To whom will come a torment disgracing him and on whom will descend an enduring punishment.\""}, {"ayah": 41, "translit": "Innaa anzalnaa 'alaikal Kitaaba linnaasi bilhaqq; famanih tadaa falinafsihee wa man dalla fa innamaa yadillu 'alaihaa wa maaa anta 'alaihim biwakeel", "translation": "Indeed, We sent down to you the Book for the people in truth. So whoever is guided - it is for [the benefit of] his soul; and whoever goes astray only goes astray to its detriment. And you are not a manager over them."}, {"ayah": 42, "translit": "Allaahu yatawaffal anfusa heena mawtihaa wallatee lam tamut fee manaamihaa fa yumsikul latee qadaa 'alaihal mawta wa yursilul ukhraaa ilaaa ajalim musammaa; inna fee zaalika la Aayaatil liqawmai yatafakkarron", "translation": "Allah takes the souls at the time of their death, and those that do not die [He takes] during their sleep. Then He keeps those for which He has decreed death and releases the others for a specified term. Indeed in that are signs for a people who give thought."}, {"ayah": 43, "translit": "Amit takhazoo min doonillaahi shufa'aaa'; qul awalaw kaanoo laa yamlikoona shai'aw wa laa ya'qiloon", "translation": "Or have they taken other than Allah as intercessors? Say, \"Even though they do not possess [power over] anything, nor do they reason?\""}, {"ayah": 44, "translit": "Qul lillaahish shafaa'atu jamee'aa; lahoo mulkus samaawaati wal ardi summa ilaihi turj'oon", "translation": "Say, \"To Allah belongs [the right to allow] intercession entirely. To Him belongs the dominion of the heavens and the earth. Then to Him you will be returned.\""}, {"ayah": 45, "translit": "Wa izaa zukiral laahu wahdahush ma azzat quloobul lazeena laa yu'minoona bil Aakhirati wa izaa zukiral lazeena min dooniheee izaa hum yastabshiroon", "translation": "And when Allah is mentioned alone, the hearts of those who do not believe in the Hereafter shrink with aversion, but when those [worshipped] other than Him are mentioned, immediately they rejoice."}, {"ayah": 46, "translit": "Qulil laahumma faatiras samaawaati wal ardi 'Aalimal Ghaibi washshahaadati Anta tahkumu baina 'ibaadika fee maa kaanoo fee yakhtalifoon", "translation": "Say, \"O Allah, Creator of the heavens and the earth, Knower of the unseen and the witnessed, You will judge between your servants concerning that over which they used to differ.\""}, {"ayah": 47, "translit": "Wa law anna lillazeena zalamoo maa fil ardi jamee'anw wa mislahoo ma'ahoo laftadaw bihee min sooo'il azaabi Yawmal Qiyaamah; wa badaa lahum minal laahi maa lam yakkoonoo yahtasiboon", "translation": "And if those who did wrong had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby from the worst of the punishment on the Day of Resurrection. And there will appear to them from Allah that which they had not taken into account."}, {"ayah": 48, "translit": "Wa badaa lahum saiyiaatu maa kasaboo wa haaqa bihim maa kaanoo bihee yastahzi'oon", "translation": "And there will appear to them the evils they had earned, and they will be enveloped by what they used to ridicule."}, {"ayah": 49, "translit": "Fa izaa massal insaana durrun da'aanaa summa izaa khawwalnaahu ni'matam minna qaala innamaaa ootee tuhoo 'alaa 'ilm; bal hiya fitna tunw wa laakinna aksarahum laa ya'lamoon", "translation": "And when adversity touches man, he calls upon Us; then when We bestow on him a favor from Us, he says, \"I have only been given it because of [my] knowledge.\" Rather, it is a trial, but most of them do not know."}, {"ayah": 50, "translit": "Qad qaalahul lazeena min qablihim famaaa aghnaa 'anhum maa kaanoo yaksiboon", "translation": "Those before them had already said it, but they were not availed by what they used to earn."}, {"ayah": 51, "translit": "Fa asaabahum saiyi aatu maa kasaboo; wallazeena zalamoo min haaa'ulaaa'i sa yuzeebuhum saiyi aatu maa kasaboo wa maa hum bimu'jizeen", "translation": "And the evil consequences of what they earned struck them. And those who have wronged of these [people] will be afflicted by the evil consequences of what they earned; and they will not cause failure."}, {"ayah": 52, "translit": "Awalam ya'lamooo annal laaha yabsutur rizqa limai yashaaa'u wa yaqdir; inna fee zaalika la Aayaatil liqamai yu'minoon", "translation": "Do they not know that Allah extends provision for whom He wills and restricts [it]? Indeed in that are signs for a people who believe."}, {"ayah": 53, "translit": "Qul yaa'ibaadiyal lazeena asrafoo 'alaaa anfusihim laa taqnatoo mirrahmatil laah; innal laaha yaghfiruz zunooba jamee'aa; innahoo Huwal Ghafoorur Raheem", "translation": "Say, \"O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Indeed, it is He who is the Forgiving, the Merciful.\""}, {"ayah": 54, "translit": "Wa aneebooo ilaa Rabbikum wa aslimoo lahoo min qabli ai yaatiyakumul 'azaabu summ laa tunsaroon", "translation": "And return [in repentance] to your Lord and submit to Him before the punishment comes upon you; then you will not be helped."}, {"ayah": 55, "translit": "Wattabi'ooo ahsana maaa unzila ilaikum mir Rabbikum min qabli aiyaatiyakumal 'azaabu baghtatanw wa antum laa tash'uroon", "translation": "And follow the best of what was revealed to you from your Lord before the punishment comes upon you suddenly while you do not perceive,"}, {"ayah": 56, "translit": "An taqoola nafsuny yaahasrataa 'alaa maa farrattu fee jambil laahi wa in kuntu laminas saakhireen", "translation": "Lest a soul should say, \"Oh [how great is] my regret over what I neglected in regard to Allah and that I was among the mockers.\""}, {"ayah": 57, "translit": "Aw taqoola law annal laaha hadaanee lakuntu minal muttaqeen", "translation": "Or [lest] it say, \"If only Allah had guided me, I would have been among the righteous.\""}, {"ayah": 58, "translit": "Aw taqoola heena taral 'azaaba law anna lee karratan fa akoona minal muhsineen", "translation": "Or [lest] it say when it sees the punishment, \"If only I had another turn so I could be among the doers of good.\""}, {"ayah": 59, "translit": "Balaa qad jaaa'atka Asyaatee fakazzabta bihaa wastak barta wa kunta minal kaafireen", "translation": "But yes, there had come to you My verses, but you denied them and were arrogant, and you were among the disbelievers."}, {"ayah": 60, "translit": "Wa Yawmal Qiyaamati taral lazeena kazaboo 'alallaahi wujoohuhum muswaddah; alaisa fee Hahannama maswal lilmutakabbireen", "translation": "And on the Day of Resurrection you will see those who lied about Allah [with] their faces blackened. Is there not in Hell a residence for the arrogant?"}, {"ayah": 61, "translit": "Wa yunajjil laahul lazee nat taqaw bimafaazatihim laa yamassuhumus sooo'u wa laa hum uahzanoon", "translation": "And Allah will save those who feared Him by their attainment; no evil will touch them, nor will they grieve."}, {"ayah": 62, "translit": "Allaahu khaaliqu kulli shai'inw wa Huwa 'alaa kulli shai'inw Wakeel", "translation": "Allah is the Creator of all things, and He is, over all things, Disposer of affairs."}, {"ayah": 63, "translit": "Lahoo maqaaleedus sa maawaati wal ard; wallazeena kafaroo bi ayaatil laahi ulaaa'ika humul khaasiroon", "translation": "To Him belong the keys of the heavens and the earth. And they who disbelieve in the verses of Allah - it is those who are the losers."}, {"ayah": 64, "translit": "Qul afaghairal laahi taamurooonneee a'budu ayyuhal jaahiloon", "translation": "Say, [O Muhammad], \"Is it other than Allah that you order me to worship, O ignorant ones?\""}, {"ayah": 65, "translit": "Wa laqad oohiya ilaika wa ilal lazeena min qablika la in ashrakta la yahbatanna 'amalu ka wa latakoonanna minal khaasireen", "translation": "And it was already revealed to you and to those before you that if you should associate [anything] with Allah, your work would surely become worthless, and you would surely be among the losers.\""}, {"ayah": 66, "translit": "Balil laahha fa'bud wa kum minash shaakireen", "translation": "Rather, worship [only] Allah and be among the grateful."}, {"ayah": 67, "translit": "Wa maa qadarul laaha haqqa qadrihee wal ardu jamee 'an qabdatuhoo Yawmal Qiyaamit wassamaawaatu matwiyyaatum biyameenih; Subhaanahoo wa Ta'aalaa 'amma yushrikoon", "translation": "They have not appraised Allah with true appraisal, while the earth entirely will be [within] His grip on the Day of Resurrection, and the heavens will be folded in His right hand. Exalted is He and high above what they associate with Him."}, {"ayah": 68, "translit": "Wa nufikha fis Soori fas'iqa man fis samaawaati wa man fil ardi illaa man shaa'al lahu summa nufikha feehi ukhraa fa izaa hum qiyaamuny yanzuroon", "translation": "And the Horn will be blown, and whoever is in the heavens and whoever is on the earth will fall dead except whom Allah wills. Then it will be blown again, and at once they will be standing, looking on."}, {"ayah": 69, "translit": "Wa ashraqatil ardu binoori Rabbihaa wa wudi'al Kitaabu wa jeee'a bin nabiyyeena wash shuhadaaa'i wa qudiya bainahum bilhaqqi wa hum laa yuzlamoon", "translation": "And the earth will shine with the light of its Lord, and the record [of deeds] will be placed, and the prophets and the witnesses will be brought, and it will be judged between them in truth, and they will not be wronged."}, {"ayah": 70, "translit": "Wa wuffiyat kullu nafsim maa 'amilat wa Huwa a'lamubimaa yaf'aloon", "translation": "And every soul will be fully compensated [for] what it did; and He is most knowing of what they do."}, {"ayah": 71, "translit": "Wa seeqal lazeena kafaroon ilaa jahannama zumaran battaaa izaa jaaa'oohaa futihat abwaabuhaa wa qaala lahum khazanatuhaaa alam yaatikum Rusulum minkum yatloona 'alaikum Aayaati Rabbikum wa yunziroonakum liqaaa'a Yawmikum haazaa; qaaloo balaa wa laakin haqqat kalimatul 'azaabi 'alal kaafireen", "translation": "And those who disbelieved will be driven to Hell in groups until, when they reach it, its gates are opened and its keepers will say, \"Did there not come to you messengers from yourselves, reciting to you the verses of your Lord and warning you of the meeting of this Day of yours?\" They will say, \"Yes, but the word of punishment has come into effect upon the disbelievers."}, {"ayah": 72, "translit": "Qeelad khuloo abwaaba jahannama khaalideena feeha fabi'sa maswal mutakabbireen", "translation": "[To them] it will be said, \"Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant.\""}, {"ayah": 73, "translit": "Wa seeqal lazeenat taqaw Rabbahum ilal Jannati zumaran hattaaa izaa jaaa'oohaa wa futihat abwaabuhaa wa qaala lahum khazanatuhaa salaamun 'alaikum tibtum fadkhuloohaa khaalideen", "translation": "But those who feared their Lord will be driven to Paradise in groups until, when they reach it while its gates have been opened and its keepers say, \"Peace be upon you; you have become pure; so enter it to abide eternally therein,\" [they will enter]."}, {"ayah": 74, "translit": "Wa waalull hamdulillaahil lazee sadaqanaa wa'dahoo wa awrasanal arda natabaw wa-u minal jannati haisu nashaaa'u fani'ma ajrul 'aamileen", "translation": "And they will say, \"Praise to Allah, who has fulfilled for us His promise and made us inherit the earth [so] we may settle in Paradise wherever we will. And excellent is the reward of [righteous] workers.\""}, {"ayah": 75, "translit": "Wa taral malaaa'ikata haaaffeena min hawlil 'Arshi yusabbihoona bihamdi Rabbihim wa qudiya bainahum bilhaqqi wa qeelal hamdu lillaahi Rabbil 'aalameen", "translation": "And you will see the angels surrounding the Throne, exalting [Allah] with praise of their Lord. And it will be judged between them in truth, and it will be said, \"[All] praise to Allah, Lord of the worlds.\""}]}, {"num": 40, "name": "Ghafir", "meaning": "The Forgiver", "verses": [{"ayah": 1, "translit": "Haa-Meeem", "translation": "Ha, Meem."}, {"ayah": 2, "translit": "Tanzeelul Kitaabi minal laahil Azeezil 'Aleem", "translation": "The revelation of the Book is from Allah, the Exalted in Might, the Knowing."}, {"ayah": 3, "translit": "Ghaafiriz zambi wa qaabilit tawbi shadeedil 'iqaabi zit tawli laaa ilaaha illaa Huwa ilaihil maseer", "translation": "The forgiver of sin, acceptor of repentance, severe in punishment, owner of abundance. There is no deity except Him; to Him is the destination."}, {"ayah": 4, "translit": "Maa yujaadilu feee Aayaatil laahi illal lazeena kafaroo falaa yaghrurka taqallubuhum fil bilaad", "translation": "No one disputes concerning the signs of Allah except those who disbelieve, so be not deceived by their [uninhibited] movement throughout the land."}, {"ayah": 5, "translit": "Kazzabat qablahum qawmu Noohinw wal Ahzaabu mim ba'dihim wa hammat kullu ummatim bi Rasoolihim liyaa khuzoobhu wa jaadaloo bilbaatili liyudhidoo bihil haqqa fa akhaztuhum fakifa kaana 'iqaab", "translation": "The people of Noah denied before them and the [disbelieving] factions after them, and every nation intended [a plot] for their messenger to seize him, and they disputed by [using] falsehood to [attempt to] invalidate thereby the truth. So I seized them, and how [terrible] was My penalty."}, {"ayah": 6, "translit": "Wa kazaalika haqqat Kalimatu Rabbika 'alal lazeena kafarooo annahum Ashaabun Naar", "translation": "And thus has the word of your Lord come into effect upon those who disbelieved that they are companions of the Fire."}, {"ayah": 7, "translit": "Allazeena yahmiloonal 'Arsha wa man hawlahoo yusabbihoona bihamdi Rabbihim wa yu'minoona bihee wa yastaghfiroona lillazeena aamanoo Rabbanaa wasi'ta kulla shai'ir rahmantanw wa 'ilman faghfir lillazeena taaboo wattaba'oo sabeelaka wa qihim 'azaabal Jaheem", "translation": "Those [angels] who carry the Throne and those around it exalt [Allah] with praise of their Lord and believe in Him and ask forgiveness for those who have believed, [saying], \"Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire."}, {"ayah": 8, "translit": "Rabbannaa wa adkhilhum Jannaati 'adninil latee wa'attahum wa man salaha min aabaaa'ihim wa azwaajihim wa zurriyyaatihim; innaka Antal 'Azeezul Hakeem", "translation": "Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise."}, {"ayah": 9, "translit": "Wa qihimus saiyi-aat; wa man taqis saiyi-aati Yawma'izin faqad rahimtah; wa zaalika huwal fawzul 'azeem", "translation": "And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment.\""}, {"ayah": 10, "translit": "Innal lazeena kafaroo yunaadawna lamaqtul laahi akbaru mim maqtikum anfusakum iz tud'awna ilal eemaani fatakfuroon", "translation": "Indeed, those who disbelieve will be addressed, \"The hatred of Allah for you was [even] greater than your hatred of yourselves [this Day in Hell] when you were invited to faith, but you refused.\""}, {"ayah": 11, "translit": "Qaaloo Rabbanaaa amat  tanasnataini wa ahyaitanas nataini fa'tarafnaa bizunoo binaa fahal ilaa khuroojim min sabeel", "translation": "They will say, \"Our Lord, You made us lifeless twice and gave us life twice, and we have confessed our sins. So is there to an exit any way?\""}, {"ayah": 12, "translit": "Zaalikum bi annahooo izaa du'iyal laahu wahdahoo kafartum wa iny yushrak bihee tu'minoo; falhukmu lillaahil 'Aliyyil Kabeer", "translation": "[They will be told], \"That is because, when Allah was called upon alone, you disbelieved; but if others were associated with Him, you believed. So the judgement is with Allah, the Most High, the Grand.\""}, {"ayah": 13, "translit": "Huwal lazee yureekum Aayaatihee wa yunazzilu lakum minas samaaa'i rizqaa; wa maa tatazakkaru illaa mai yuneeb", "translation": "It is He who shows you His signs and sends down to you from the sky, provision. But none will remember except he who turns back [in repentance]."}, {"ayah": 14, "translit": "Fad'ul laaha mukhliseena lahud deena wa law karihal kaafiroon", "translation": "So invoke Allah, [being] sincere to Him in religion, although the disbelievers dislike it."}, {"ayah": 15, "translit": "Rafee'ud darajaati zul 'Arshi yulqir rooha min amrihee 'alaa mai yashaaa'u min 'ibaadihee liyunzira yawmat talaaq", "translation": "[He is] the Exalted above [all] degrees, Owner of the Throne; He places the inspiration of His command upon whom He wills of His servants to warn of the Day of Meeting."}, {"ayah": 16, "translit": "Yawma hum baarizoona laa yakhfaa 'alal laahi minhum shai; limanil mulkul Yawma lillaahil Waahidil Qahaar", "translation": "The Day they come forth nothing concerning them will be concealed from Allah. To whom belongs [all] sovereignty this Day? To Allah, the One, the Prevailing."}, {"ayah": 17, "translit": "Al-Yawma tujzaa kullu nafsim bimaa kasabat; laa zulmal Yawm; innal laaha saree'ul hisaab", "translation": "This Day every soul will be recompensed for what it earned. No injustice today! Indeed, Allah is swift in account."}, {"ayah": 18, "translit": "Wa anzirhum yawmal aazifati izil quloobu ladal hanaajiri kaazimeen; maa lizzaalimeena min hameeminw wa laa shafee'iny-yutaa'", "translation": "And warn them, [O Muhammad], of the Approaching Day, when hearts are at the throats, filled [with distress]. For the wrongdoers there will be no devoted friend and no intercessor [who is] obeyed."}, {"ayah": 19, "translit": "Ya'lamu khaaa'inatal a'yuni wa maa tukhfis sudoor", "translation": "He knows that which deceives the eyes and what the breasts conceal."}, {"ayah": 20, "translit": "Wallaahu yaqdee bilhaqq, wallazeena yad'oona min doonihee laa yaqdoona bishai'; innal laaha Huwas Samee'ul Baseer", "translation": "And Allah judges with truth, while those they invoke besides Him judge not with anything. Indeed, Allah - He is the Hearing, the Seeing."}, {"ayah": 21, "translit": "Awalam yaseeroo fil ardi fa yanzuroo kaifa kaana 'aaqibatul lazeena kaanoo min qablihim; kaanoo hum ashadda minhum quwwatanw wa aasaaran fil ardi fa akhazahumul laahu bizunoobihim wa maa kaana lahum minal laahi minw waaq", "translation": "Have they not traveled through the land and observed how was the end of those who were before them? They were greater than them in strength and in impression on the land, but Allah seized them for their sins. And they had not from Allah any protector."}, {"ayah": 22, "translit": "Zaalika bi annahum kaanat taateehim Rusuluhum bilbaiyinaati fakafaroo fa akhazahumul laah; innahoo qawiyyun shadeedul 'iqaab", "translation": "That was because their messengers were coming to them with clear proofs, but they disbelieved, so Allah seized them. Indeed, He is Powerful and severe in punishment."}, {"ayah": 23, "translit": "Wa laqad arsalnaa Moosaa bi Aayaatinaa wa sultaanim mubeen", "translation": "And We did certainly send Moses with Our signs and a clear authority"}, {"ayah": 24, "translit": "Ilaa Fir'awna wa Haamaana qa Qaaroona faqaaloo saahirun kazzaab", "translation": "To Pharaoh, Haman and Qarun; but they said, \"[He is] a magician and a liar.\""}, {"ayah": 25, "translit": "Falamuna jaaa'ahum bil haqqi min 'indinaa qaaluq tulooo abnaaa'al lazeena aamanoo ma'ahoo wastahyoo nisaaa'ahum; wa maa kaidul kaafireena illaa fee dalaal", "translation": "And when he brought them the truth from Us, they said, \"Kill the sons of those who have believed with him and keep their women alive.\" But the plan of the disbelievers is not except in error."}, {"ayah": 26, "translit": "Wa qaala Fir'awnu zarooneee aqtul Moosaa walyad'u Rabbahoo inneee akhaafu ai yubaddila deenakum aw ai yuzhira fil ardil fasaad", "translation": "And Pharaoh said, \"Let me kill Moses and let him call upon his Lord. Indeed, I fear that he will change your religion or that he will cause corruption in the land.\""}, {"ayah": 27, "translit": "Wa qaala Moosaaaa innee 'uztu bi Rabbee wa Rabbikum min kulli mutakabbiril laayu'minu bi Yawmil Hisaab", "translation": "But Moses said, \"Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account.\""}, {"ayah": 28, "translit": "Wa qaala rajulum mu'minummin Aali Fir'awna yaktumu eemaanahooo ataqtuloona rajulan ai yaqoola Rabbi yal laahu wa qad jaaa'akum bil haiyinaati mir Rabbikum wa iny yaku kaaziban fa'alaihi kazi buhoo wa iny yaku saadiqany yasibkum ba'dul lazee ya'idukum innal laaha laa yahdee man huwa musrifun kaazaab", "translation": "And a believing man from the family of Pharaoh who concealed his faith said, \"Do you kill a man [merely] because he says, 'My Lord is Allah' while he has brought you clear proofs from your Lord? And if he should be lying, then upon him is [the consequence of] his lie; but if he should be truthful, there will strike you some of what he promises you. Indeed, Allah does not guide one who is a transgressor and a liar."}, {"ayah": 29, "translit": "Yaa qawmi lakumul mulkul yawma zaahireena fil ardi famai yansurunaa mim baasil laahi in jaaa'anaa; qaala Fir'awnu maaa ureekum illaa maaa araa wa maaa ahdeekum illaa sabeelar Rashaad", "translation": "O my people, sovereignty is yours today, [your being] dominant in the land. But who would protect us from the punishment of Allah if it came to us?\" Pharaoh said, \"I do not show you except what I see, and I do not guide you except to the way of right conduct.\""}, {"ayah": 30, "translit": "Wa qaalal lazee aamana yaa qawmi inneee akhaafu 'alaikum misla yawmil Ahzaab", "translation": "And he who believed said, \"O my people, indeed I fear for you [a fate] like the day of the companies -"}, {"ayah": 31, "translit": "Misla daabi qawmi Noohinw wa 'aadinw wa Samooda wallazeena mim ba'dihim; wa mal laahu yureedu zulmal lil'ibaad", "translation": "Like the custom of the people of Noah and of 'Aad and Thamud and those after them. And Allah wants no injustice for [His] servants."}, {"ayah": 32, "translit": "Wa yaa qawmi inneee akhaafu 'alaikum yawmat tanaad", "translation": "And O my people, indeed I fear for you the Day of Calling -"}, {"ayah": 33, "translit": "Yawma tuwalloona mud bireena maa lakum minal laahi min 'aasim; wa mai yudlilil laahu famaa lahoo min haad", "translation": "The Day you will turn your backs fleeing; there is not for you from Allah any protector. And whoever Allah leaves astray - there is not for him any guide."}, {"ayah": 34, "translit": "Wa laqad jaaa'akum Yoosufu min qablu bil baiyinaati famaa ziltum fee shakkim mimaa jaaa'akum bihee hattaaa izaa halaka qultum lai yab asal laahu mim ba'dihee Rasoolaa; kazaalika yudillul laahu man huwa Musrifum murtaab", "translation": "And Joseph had already come to you before with clear proofs, but you remained in doubt of that which he brought to you, until when he died, you said, 'Never will Allah send a messenger after him.' Thus does Allah leave astray he who is a transgressor and skeptic.\""}, {"ayah": 35, "translit": "Allazeena yujaadiloona feee Aaayaatil laahi bighairi sultaanin ataahum kabura maqtan 'indal laahi wa 'indal lazeena aamanoo; kazaalika yatha'ul laahu 'alaa kulli qalbi mutakabbirin jabbaar", "translation": "Those who dispute concerning the signs of Allah without an authority having come to them - great is hatred [of them] in the sight of Allah and in the sight of those who have believed. Thus does Allah seal over every heart [belonging to] an arrogant tyrant."}, {"ayah": 36, "translit": "Wa qaala Fir'awnu yaa Haamaanub-ni lee sarhal la'alleee ablughul asbaab", "translation": "And Pharaoh said, \"O Haman, construct for me a tower that I might reach the ways -"}, {"ayah": 37, "translit": "Asbaabas samaawaati faattali'a ilaaa ilaahi Moosaa wa innee la azunnuhoo kaazibaa; wa kazaalika zuyyina li-Fir'awna sooo'u 'amalihee wa sudda 'anis sabeel; wa maa kaidu Fir'awna illaa fee tabaab", "translation": "The ways into the heavens - so that I may look at the deity of Moses; but indeed, I think he is a liar.\" And thus was made attractive to Pharaoh the evil of his deed, and he was averted from the [right] way. And the plan of Pharaoh was not except in ruin."}, {"ayah": 38, "translit": "Wa qaalal lazeee aamana yaa qawmit tabi'ooni ahdikum sabeelar rashaad", "translation": "And he who believed said, \"O my people, follow me, I will guide you to the way of right conduct."}, {"ayah": 39, "translit": "Yaa qawmi innamaa haazihil hayaatud dunyaa mataa'unw wa innal Aakhirata hiya daarul qaraar", "translation": "O my people, this worldly life is only [temporary] enjoyment, and indeed, the Hereafter - that is the home of [permanent] settlement."}, {"ayah": 40, "translit": "Man 'amila saiyi'atan falaa yujzaaa illaa mislahaa wa man 'amila saaliham min zakarin aw unsaa wa huwa mu'minun fa ulaaa'ika yadkhuloonal Jannata yurzaqoona feehaa bighairi hisaab", "translation": "Whoever does an evil deed will not be recompensed except by the like thereof; but whoever does righteousness, whether male or female, while he is a believer - those will enter Paradise, being given provision therein without account."}, {"ayah": 41, "translit": "Wa yaa qawmi maa leee ad'ookum ilan najaati wa tad'oonaneee ilan Naar", "translation": "And O my people, how is it that I invite you to salvation while you invite me to the Fire?"}, {"ayah": 42, "translit": "Tad'oonanee li-akfura billaahi wa ushrika bihee maa laisa lee bihee 'ilmunw wa ana ad'ookum ilal'Azeezil Ghaffaar", "translation": "You invite me to disbelieve in Allah and associate with Him that of which I have no knowledge, and I invite you to the Exalted in Might, the Perpetual Forgiver."}, {"ayah": 43, "translit": "Laa jarama annamaa tad'oonanee ilaihi laisa lahoo da'watun fid dunyaa wa laa fil Aakhirati wa anna maraddanaaa ilal laahi wa annal musrifeenahum Ashaabun Naar", "translation": "Assuredly, that to which you invite me has no [response to a] supplication in this world or in the Hereafter; and indeed, our return is to Allah, and indeed, the transgressors will be companions of the Fire."}, {"ayah": 44, "translit": "Fasatazkuroona maaa aqoolu lakum; wa ufawwidu amreee ilal laah; innallaaha baseerum bil'ibaad", "translation": "And you will remember what I [now] say to you, and I entrust my affair to Allah. Indeed, Allah is Seeing of [His] servants.\""}, {"ayah": 45, "translit": "Fa waqaahul laahu saiyiaati maa makaroo wa haaqa bi Aali-Fir'awna sooo'ul 'azaab", "translation": "So Allah protected him from the evils they plotted, and the people of Pharaoh were enveloped by the worst of punishment -"}, {"ayah": 46, "translit": "An Naaru yu'radoona 'alaihaa ghuduwwanw wa 'ashiyyanw wa Yawma taqoomus Saa'aatu adkhilooo Aala Fir'awna ashaddal 'azaab", "translation": "The Fire, they are exposed to it morning and evening. And the Day the Hour appears [it will be said], \"Make the people of Pharaoh enter the severest punishment.\""}, {"ayah": 47, "translit": "Wa iz yatahaaajjoona fin Naari fa-yaqoolud du'afaaa'u lillazeenas takbarooo innaa kunnaa lakum taba'an fahal antum mughnoona annaa naseebam minan Naar", "translation": "And [mention] when they will argue within the Fire, and the weak will say to those who had been arrogant, \"Indeed, we were [only] your followers, so will you relieve us of a share of the Fire?\""}, {"ayah": 48, "translit": "Qaalal lazeenas takbarooo innaa kullun feehaaa innal laaha qad hakama baynal'ibaad", "translation": "Those who had been arrogant will say, \"Indeed, all [of us] are in it. Indeed, Allah has judged between the servants.\""}, {"ayah": 49, "translit": "Wa qaalal lazena fin Naari likhazanati Jahannamad-'oo Rabbakum yukhaffif 'annaa yawmam minal 'azaab", "translation": "And those in the Fire will say to the keepers of Hell, \"Supplicate your Lord to lighten for us a day from the punishment.\""}, {"ayah": 50, "translit": "Qaalooo awalam taku taateekum Rusulukum bilbaiyinaati qaaloo balaa' qaaloo fad'oo; wa maa du'aaa'ul kaafireena illaa fee dalaal", "translation": "They will say, \"Did there not come to you your messengers with clear proofs?\" They will say, \"Yes.\" They will reply, \"Then supplicate [yourselves], but the supplication of the disbelievers is not except in error.\""}, {"ayah": 51, "translit": "Innaa lanansuru Rusulanaa wallazeena aamanoo fil hayaatid dunyaa wa Yawma yaqoomul ashhaad", "translation": "Indeed, We will support Our messengers and those who believe during the life of this world and on the Day when the witnesses will stand -"}, {"ayah": 52, "translit": "Yawma laa yanfa'uz zaalimeena ma'ziratuhum wa lahumul la'natu wa lahum soooud daar", "translation": "The Day their excuse will not benefit the wrongdoers, and they will have the curse, and they will have the worst home."}, {"ayah": 53, "translit": "Wa laqad aatainaa Moosal hudaa wa awrasnaa Baneee Israaa 'eelal Kitaab", "translation": "And We had certainly given Moses guidance, and We caused the Children of Israel to inherit the Scripture"}, {"ayah": 54, "translit": "Hudanw wa zikraa li ulil albaab", "translation": "As guidance and a reminder for those of understanding."}, {"ayah": 55, "translit": "Fasbir inna wa'dal laahi haqqunw wastaghfir lizambika wa sabbih bihamdi Rabbika bil'ashiyyi wal ibkaar", "translation": "So be patient, [O Muhammad]. Indeed, the promise of Allah is truth. And ask forgiveness for your sin and exalt [Allah] with praise of your Lord in the evening and the morning."}, {"ayah": 56, "translit": "Innal lazeena yujaadi loona feee Aayaatil laahi bighairi sultaanin ataahum in fee sudoorihim illaa kibrum maa hum bibaaligheeh; fasta'iz billaahi innahoo Huwas Samee'ul Baseer", "translation": "Indeed, those who dispute concerning the signs of Allah without [any] authority having come to them - there is not within their breasts except pride, [the extent of] which they cannot reach. So seek refuge in Allah. Indeed, it is He who is the Hearing, the Seeing."}, {"ayah": 57, "translit": "Lakhalqus samaawaati wal ardi akbaru min khalqin naasi wa laakinna aksaran naasi laa ya'lamoon", "translation": "The creation of the heavens and earth is greater than the creation of mankind, but most of the people do not know."}, {"ayah": 58, "translit": "Wa maa yastawil a'maa walbaseeru wallazeena aamanoo wa 'amilus saalihaati wa lal museee'; qaleelam maa tatazakkaroon", "translation": "And not equal are the blind and the seeing, nor are those who believe and do righteous deeds and the evildoer. Little do you remember."}, {"ayah": 59, "translit": "Innas Saa'ata la aatiyatul laa raiba feehaa wa laakinna aksaran naasi laa yu'minoon", "translation": "Indeed, the Hour is coming - no doubt about it - but most of the people do not believe."}, {"ayah": 60, "translit": "Wa qaala Rabbukumud 'ooneee astajib lakum; innal lazeena yastakbiroona an 'ibaadatee sa yadkhuloona jahannama daakhireen", "translation": "And your Lord says, \"Call upon Me; I will respond to you.\" Indeed, those who disdain My worship will enter Hell [rendered] contemptible."}, {"ayah": 61, "translit": "Allaahul lazee ja'ala lakumul laila litqaskunoo feehi wannahaara mubsiraa; innal laaha lazoo fadlin 'alan naasi wa laakinna aksaran naasi laa yashkuroon", "translation": "It is Allah who made for you the night that you may rest therein and the day giving sight. Indeed, Allah is full of bounty to the people, but most of the people are not grateful."}, {"ayah": 62, "translit": "Zaalikumul laahu Rabbukum khaaliqu kulli shai'; laaa ilaaha illaa Huwa fa annaa tu'fakoon", "translation": "That is Allah, your Lord, Creator of all things; there is no deity except Him, so how are you deluded?"}, {"ayah": 63, "translit": "Kazaalika yu'fakul loazeena kaanoo bi Aayaatil laahi yajhadoon", "translation": "Thus were those [before you] deluded who were rejecting the signs of Allah."}, {"ayah": 64, "translit": "Allaahul lazee ja'ala lakumul arda qaraaranw wassa maaa'a binaaa'anw wa sawwarakum fa ahsana suwarakum wa razaqakum minat taiyibaat; zaalikumul laahu Rabbukum fatabaarakal laahu Rabbul 'aalameen", "translation": "It is Allah who made for you the earth a place of settlement and the sky a ceiling and formed you and perfected your forms and provided you with good things. That is Allah, your Lord; then blessed is Allah, Lord of the worlds."}, {"ayah": 65, "translit": "Huwal Hayyu laaa ilaaha illaa Huwa fad'oohu mukh liseena lahudeen; alhamdu lillaahi Rabbil 'aalameen", "translation": "He is the Ever-Living; there is no deity except Him, so call upon Him, [being] sincere to Him in religion. [All] praise is [due] to Allah, Lord of the worlds."}, {"ayah": 66, "translit": "Qul innee nuheetu an a'budal lazeena tad'oona min doonil laahi lammaa jaaa'a niyal biyinaatu mir Rabbee wa umirtu an uslima li Rabbil 'aalameen", "translation": "Say, [O Muhammad], \"Indeed, I have been forbidden to worship those you call upon besides Allah once the clear proofs have come to me from my Lord, and I have been commanded to submit to the Lord of the worlds.\""}, {"ayah": 67, "translit": "Huwal lazee khalaqakum min turaabin summa min nutfatin summa min 'alaqatin summa yukhrijukum tiflan summa litablughooo ashuddakum summa litakoonoo shuyookhaa; wa minkum mai yutawaffaa min qablu wa litablughooo ajalam musam manw-wa la'allakum ta'qiloon", "translation": "It is He who created you from dust, then from a sperm-drop, then from a clinging clot; then He brings you out as a child; then [He develops you] that you reach your [time of] maturity, then [further] that you become elders. And among you is he who is taken in death before [that], so that you reach a specified term; and perhaps you will use reason."}, {"ayah": 68, "translit": "Huwal lazee yuhyee wa yumeetu fa izaa qadaaa amran fa innamaa yaqoolu lahoo kun fa yakon", "translation": "He it is who gives life and causes death; and when He decrees a matter, He but says to it, \"Be,\" and it is."}, {"ayah": 69, "translit": "Alam tara ilal lazeena yujaadiloona feee Aayaatil laahi annaa yusrafoon", "translation": "Do you not consider those who dispute concerning the signs of Allah - how are they averted?"}, {"ayah": 70, "translit": "Allazeena kazzaboo bil Kitaabi wa bimaa arsalnaa bihee Rusulanaa fasawfa ya'lamoon", "translation": "Those who deny the Book and that with which We sent Our messengers - they are going to know,"}, {"ayah": 71, "translit": "Izil aghlaalu feee a'naaqi-him wassalaasilu yashaboon", "translation": "When the shackles are around their necks and the chains; they will be dragged"}, {"ayah": 72, "translit": "Fil hameemi summa fin Naari Yasjaroon", "translation": "In boiling water; then in the Fire they will be filled [with flame]."}, {"ayah": 73, "translit": "Summaa qeela lahum ayna maa kuntum tushrikoon", "translation": "Then it will be said to them, \"Where is that which you used to associate [with Him in worship]"}, {"ayah": 74, "translit": "Min doonil laahi qaaloo dalloo 'annaa bal lam nakun nad'oo min qablu shai'aa; kazaalika yudillul laahul kaafireen", "translation": "Other than Allah?\" They will say, \"They have departed from us; rather, we did not used to invoke previously anything.\" Thus does Allah put astray the disbelievers."}, {"ayah": 75, "translit": "Zaalikum bimaa kuntum tafrahoona fil ardi bighairil haqqi wa bimaa kuntum tamrahoon", "translation": "[The angels will say], \"That was because you used to exult upon the earth without right and you used to behave insolently."}, {"ayah": 76, "translit": "Udkhulooo abwaaba Jahannama khaalideena feehaa fabi'sa maswal mutakabbireen", "translation": "Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant.\""}, {"ayah": 77, "translit": "Fasbir inna wa'dal laahi haqq; fa immaa nuriyannak ba'dal lazee na'i duhum aw natawaffayannaka fa ilainaa yurja'oon", "translation": "So be patient, [O Muhammad]; indeed, the promise of Allah is truth. And whether We show you some of what We have promised them or We take you in death, it is to Us they will be returned."}, {"ayah": 78, "translit": "Wa laqad arsalnaa Rusulam min qablika minhum man qasasnaa 'alaika wa minhum mal lam naqsus 'alaik; wa maa kaana li Rasoolin any yaatiya bi Aayatin illaa bi iznil laah; fa izaa jaaa'a amrul laahi qudiya bilhaqqi wa khasira hunaalikal mubtiloon", "translation": "And We have already sent messengers before you. Among them are those [whose stories] We have related to you, and among them are those [whose stories] We have not related to you. And it was not for any messenger to bring a sign [or verse] except by permission of Allah. So when the command of Allah comes, it will be concluded in truth, and the falsifiers will thereupon lose [all]."}, {"ayah": 79, "translit": "Allaahul lazee ja'ala lakumul an'aama litarkaboo minhaa wa minhaa taakuloon", "translation": "It is Allah who made for you the grazing animals upon which you ride, and some of them you eat."}, {"ayah": 80, "translit": "Wa lakum feehaa manaafi'u wa litablughoo 'alaihaa haajatan fee sudoorikum wa 'alaihaa wa 'alal fulki tuhmaloon", "translation": "And for you therein are [other] benefits and that you may realize upon them a need which is in your breasts; and upon them and upon ships you are carried."}, {"ayah": 81, "translit": "Wa yureekum Aayaatihee fa ayya Aayaatil laahi tunkiroon", "translation": "And He shows you His signs. So which of the signs of Allah do you deny?"}, {"ayah": 82, "translit": "Afalam yaseeroo fil ardi fa yanzuroo kaifa kaana 'aaqibatul lazeena min qablihim; kaanoo aksara minhum wa ashadda quwwatanw wa aasaaran fil ardi famaaa aghnaa 'anhum maa kaanoo yaksiboon", "translation": "Have they not traveled through the land and observed how was the end of those before them? They were more numerous than themselves and greater in strength and in impression on the land, but they were not availed by what they used to earn."}, {"ayah": 83, "translit": "Falammaa jaaa'at hum Rusuluhum bilbaiyinaati farihoo bimaa 'indahum minal 'ilmi wa haaqa bihim maa kaanoo bihee yastahzi'oon", "translation": "And when their messengers came to them with clear proofs, they [merely] rejoiced in what they had of knowledge, but they were enveloped by what they used to ridicule."}, {"ayah": 84, "translit": "Falammaa ra aw baasanaa qaalooo aamannaa billaahi wahdahoo wa kafarnaa bimaa kunnaa bihee mushrikeen", "translation": "And when they saw Our punishment, they said,\" We believe in Allah alone and disbelieve in that which we used to associate with Him.\""}, {"ayah": 85, "translit": "Falam yaku tanfa 'uhum eemaanuhum lammaa ra-aw baasana sunnatal laahil latee qad khalat fee 'ibaadihee wa khasira hunaalikal kaafiroon", "translation": "But never did their faith benefit them once they saw Our punishment. [It is] the established way of Allah which has preceded among His servants. And the disbelievers thereupon lost [all]."}]}, {"num": 41, "name": "Fussilat", "meaning": "Explained in Detail", "verses": [{"ayah": 1, "translit": "Haa Meeem", "translation": "Ha, Meem."}, {"ayah": 2, "translit": "Tanzeelum Minar-Rahmaanir-Raheem", "translation": "[This is] a revelation from the Entirely Merciful, the Especially Merciful -"}, {"ayah": 3, "translit": "Kitaabun fussilat Aayaatuhoo Qur-aanan 'Arabiyyal liqawminy ya'lamoon", "translation": "A Book whose verses have been detailed, an Arabic Qur'an for a people who know,"}, {"ayah": 4, "translit": "Basheeranw wa nazeeran fa-a'rada aksaruhum fahum laa yasma'oon", "translation": "As a giver of good tidings and a warner; but most of them turn away, so they do not hear."}, {"ayah": 5, "translit": "Wa qaaloo quloobunaa feee akinnatim mimmaa tad'oonaaa ilaihi wa feee aazaaninaa waqrunw wa mim baininaa wa bainika bijaabun fa'mal innanaa 'aamiloon", "translation": "And they say, \"Our hearts are within coverings from that to which you invite us, and in our ears is deafness, and between us and you is a partition, so work; indeed, we are working.\""}, {"ayah": 6, "translit": "Qul innamaaa ana basharum mislukum yoohaaa ilaiya annamaaa ilaahukum Ilaahunw Waahidun fastaqeemooo ilaihi wastagfirooh; wa wailul lil mushrikeen", "translation": "Say, O [Muhammad], \"I am only a man like you to whom it has been revealed that your god is but one God; so take a straight course to Him and seek His forgiveness.\" And woe to those who associate others with Allah -"}, {"ayah": 7, "translit": "Allazeena laa yu'toonaz Zakaata wa hum bil-Aakhiratihum kaafiroon", "translation": "Those who do not give zakah, and in the Hereafter they are disbelievers."}, {"ayah": 8, "translit": "Innal lazeena aamanoo wa 'amilus saalihaati lahum ajrun ghairu mamnoon", "translation": "Indeed, those who believe and do righteous deeds - for them is a reward uninterrupted."}, {"ayah": 9, "translit": "Qul a'innakum latakfuroona billazee khalaqal arda fee yawmaini wa taj'aloona lahooo andaadaa; zaalika Rabbul 'aalameen", "translation": "Say, \"Do you indeed disbelieve in He who created the earth in two days and attribute to Him equals? That is the Lord of the worlds.\""}, {"ayah": 10, "translit": "Wa ja'ala feehaa rawaa siya min fawqihaa wa baaraka feehaa wa qaddara feehaaaa aqwaatahaa feee arba'ati ayyaamin sawaaa'al lissaaa'ileen", "translation": "And He placed on the earth firmly set mountains over its surface, and He blessed it and determined therein its [creatures'] sustenance in four days without distinction - for [the information] of those who ask."}, {"ayah": 11, "translit": "Summas tawaaa ilas-samaaa'i wa hiya dukhaanun faqaala lahaa wa lil ardi'tiyaaa taw'an aw karhan qaalataaa atainaa taaa'i'een", "translation": "Then He directed Himself to the heaven while it was smoke and said to it and to the earth, \"Come [into being], willingly or by compulsion.\" They said, \"We have come willingly.\""}, {"ayah": 12, "translit": "Faqadaahunna sab'a samaawaatin fee yawmaini wa awhaa fee kulli samaaa'in amarahaa; wa zaiyannassa maaa'ad dunyaa bimasaabeeha wa hifzaa; zaalika taqdeerul 'Azeezil 'Aleem", "translation": "And He completed them as seven heavens within two days and inspired in each heaven its command. And We adorned the nearest heaven with lamps and as protection. That is the determination of the Exalted in Might, the Knowing."}, {"ayah": 13, "translit": "Fa-in a'radoo faqul anzartukum saa'iqatam misla saa'iqati 'Aadinw wa Samood", "translation": "But if they turn away, then say, \"I have warned you of a thunderbolt like the thunderbolt [that struck] 'Aad and Thamud."}, {"ayah": 14, "translit": "Iz jaaa'at humur Rusulu mim baini aydeehim wa min khalfihim allaa ta'budooo illal laaha qaaloo law shaaa'a Rabunaa la anzala malaaa 'ikatan fa innaa bimaaa ursiltum bihee kaafiroon", "translation": "[That occurred] when the messengers had come to them before them and after them, [saying], \"Worship not except Allah.\" They said, \"If our Lord had willed, He would have sent down the angels, so indeed we, in that with which you have been sent, are disbelievers.\""}, {"ayah": 15, "translit": "Fa ammaa 'Aadun fastak baroo fil ardi bighairul haqqi wa qaaloo man ashaddu minnaa quwwatan awalam yaraw annal laahal lazee khalaqahum Huwa ashaddu minhum quwwatanw wa kaanoo bi Aayaatinaa yajhadoon", "translation": "As for 'Aad, they were arrogant upon the earth without right and said, \"Who is greater than us in strength?\" Did they not consider that Allah who created them was greater than them in strength? But they were rejecting Our signs."}, {"ayah": 16, "translit": "Fa arsalnaa 'alaihim reehan sarsaran feee ayyaamin nahisaatil linuzeeqahum 'azaabal khizyi fil hayaatid dunyaa wa la'azaabul Aakhirati akhzaa wa hum laa yunsaroon", "translation": "So We sent upon them a screaming wind during days of misfortune to make them taste the punishment of disgrace in the worldly life; but the punishment of the Hereafter is more disgracing, and they will not be helped."}, {"ayah": 17, "translit": "Wa ammaa Samoodu fahadinaahum fastahabbul 'ama 'alal huda fa akhazathum saa'iqatul 'azaabil hooni bimaa kaanoo yaksiboon", "translation": "And as for Thamud, We guided them, but they preferred blindness over guidance, so the thunderbolt of humiliating punishment seized them for what they used to earn."}, {"ayah": 18, "translit": "Wa najjainal lazeena aamanoo wa kaanoo yattaqoon", "translation": "And We saved those who believed and used to fear Allah."}, {"ayah": 19, "translit": "Wa yawma yuhsharu a'daaa'ul laahi ilan Naari fahum yooza'oon", "translation": "And [mention, O Muhammad], the Day when the enemies of Allah will be gathered to the Fire while they are [driven] assembled in rows,"}, {"ayah": 20, "translit": "Hattaaa izaa maa jaaa'oohaa shahida 'alaihim samu'uhum wa absaaruhum wa julooduhum bimaa kaanoo ya'maloon", "translation": "Until, when they reach it, their hearing and their eyes and their skins will testify against them of what they used to do."}, {"ayah": 21, "translit": "Wa qaaloo lijuloodihim lima shahittum 'alainaa qaaloo antaqanal laahul lazeee antaqa kulla shai'inw wa Huwa khalaqakum awwala marratinw wa ilaihi turja'oon", "translation": "And they will say to their skins, \"Why have you testified against us?\" They will say, \"We were made to speak by Allah, who has made everything speak; and He created you the first time, and to Him you are returned."}, {"ayah": 22, "translit": "Wa maa kuntum tastatiroona ai-yashhada 'alaikum sam'ukum wa laaa absaarukum wa laa juloodukum wa laakin zanantum annal laaha laa ya'lamu kaseeram mimmaa ta'maloon", "translation": "And you were not covering yourselves, lest your hearing testify against you or your sight or your skins, but you assumed that Allah does not know much of what you do."}, {"ayah": 23, "translit": "Wa zaalikum zannukumul lazee zanantum bi-Rabbikum ardaakum fa asbahtum minal khaasireen", "translation": "And that was your assumption which you assumed about your Lord. It has brought you to ruin, and you have become among the losers.\""}, {"ayah": 24, "translit": "Fa-iny yasbiroo fan Naaru maswal lahum wa iny-yasta'tiboo famaa hum minal mu'tabeen", "translation": "So [even] if they are patient, the Fire is a residence for them; and if they ask to appease [Allah], they will not be of those who are allowed to appease."}, {"ayah": 25, "translit": "Wa qaiyadnaa lahum quranaaa'a fazaiyanoo lahum maa baina aideehim wa maa khalfahum wa haqqa 'alaihimul qawlu feee umamin  qad khalat min qablihim minal jinni wal insi innahum kaanoo khaasireen", "translation": "And We appointed for them companions who made attractive to them what was before them and what was behind them [of sin], and the word has come into effect upon them among nations which had passed on before them of jinn and men. Indeed, they [all] were losers."}, {"ayah": 26, "translit": "Wa qaalal lazeena kafaroo laa tasma'oo lihaazal Quraani walghaw feehi la'allakum taghlihoon", "translation": "And those who disbelieve say, \"Do not listen to this Qur'an and speak noisily during [the recitation of] it that perhaps you will overcome.\""}, {"ayah": 27, "translit": "Falanuzeeqannal lazeena kafaroo 'azaaban shadeedanw wa lanajziyannahum aswallazee kaanoo ya'maloon", "translation": "But We will surely cause those who disbelieve to taste a severe punishment, and We will surely recompense them for the worst of what they had been doing."}, {"ayah": 28, "translit": "Zaalika jazaaa'u a'daaa'il laahin Naaru lahum feehaa daarul khuld, jazaaa'am bimaa kaanoo bi aayaatinaa yajhdoon", "translation": "That is the recompense of the enemies of Allah - the Fire. For them therein is the home of eternity as recompense for what they, of Our verses, were rejecting."}, {"ayah": 29, "translit": "Wa qaalal lazeena kafaroo Rabbanaaa arinal lazaini adal laanaa minal jinni wal insi naj'alhumaa tahta aqdaaminaa liyakoonaa minal asfaleen", "translation": "And those who disbelieved will [then] say, \"Our Lord, show us those who misled us of the jinn and men [so] we may put them under our feet that they will be among the lowest.\""}, {"ayah": 30, "translit": "Innal lazeena qaaloo Rabbunal laahu summas taqaamoo tatanazzalu 'alaihimul malaaa 'ikatu allaa takhaafoo wa laa tahzanoo wa abshiroo bil Jannnatil latee kuntum too'adoon", "translation": "Indeed, those who have said, \"Our Lord is Allah \" and then remained on a right course - the angels will descend upon them, [saying], \"Do not fear and do not grieve but receive good tidings of Paradise, which you were promised."}, {"ayah": 31, "translit": "Nahnu awliyaaa'ukum fil hayaatid dunyaa wa fil Aakhirati wa lakum feehaa maa tashtaheee anfusukum wa lakum feehaa ma tadda'oon", "translation": "We [angels] were your allies in worldly life and [are so] in the Hereafter. And you will have therein whatever your souls desire, and you will have therein whatever you request [or wish]"}, {"ayah": 32, "translit": "Nuzulam min Ghafoorir Raheem", "translation": "As accommodation from a [Lord who is] Forgiving and Merciful.\""}, {"ayah": 33, "translit": "Wa man ahsanu qawlam mimman da'aaa ilal laahi wa 'amila saalihanw wa qaala innanee minal muslimeen", "translation": "And who is better in speech than one who invites to Allah and does righteousness and says, \"Indeed, I am of the Muslims.\""}, {"ayah": 34, "translit": "Wa laa tastawil hasanatu wa las saiyi'ah; idfa' billatee hiya ahsanu fa'izal lazee bainaka wa bainahoo 'adaawatun ka'annahoo waliyun hameem", "translation": "And not equal are the good deed and the bad. Repel [evil] by that [deed] which is better; and thereupon the one whom between you and him is enmity [will become] as though he was a devoted friend."}, {"ayah": 35, "translit": "Wa maa yulaqqaahaaa illal lazeena sabaroo wa maa yulaqqaahaaa illaa zoo hazzin 'azeem", "translation": "But none is granted it except those who are patient, and none is granted it except one having a great portion [of good]."}, {"ayah": 36, "translit": "Wa immaa yanzaghannaka minash Shaitaani nazghun fasta'iz billaahi innahoo Huwas Samee'ul 'Aleem", "translation": "And if there comes to you from Satan an evil suggestion, then seek refuge in Allah. Indeed, He is the Hearing, the Knowing."}, {"ayah": 37, "translit": "Wa min Aayaatihil lailu wannahaaru washshamsu walqamar; laa tasjudoo lishshamsi wa laa lilqamari wasjudoo lillaahil lazee khala qahunna in kuntum iyyaahu ta'budoon", "translation": "And of His signs are the night and day and the sun and moon. Do not prostrate to the sun or to the moon, but prostate to Allah, who created them, if it should be Him that you worship."}, {"ayah": 38, "translit": "Fa inis-takbaroo fallazee na 'inda Rabbika yusabbihoona lahoo billaili wannnahaari wa hum laa yas'amoon", "translation": "But if they are arrogant - then those who are near your Lord exalt Him by night and by day, and they do not become weary."}, {"ayah": 39, "translit": "Wa min Aayaatiheee annaka taral arda khaashi'atan fa izaaa anzalna 'alaihal maaa'ah tazzat wa rabat; innal lazeee ahyaahaa lamuhiyil mawtaa; innahoo 'alaa kulli shai-in Qadeer", "translation": "And of His signs is that you see the earth stilled, but when We send down upon it rain, it quivers and grows. Indeed, He who has given it life is the Giver of Life to the dead. Indeed, He is over all things competent."}, {"ayah": 40, "translit": "Innal lazeena yulhidoona feee Aayaatina laa yakhfawna 'alainaa' afamai yulqaa fin Naari khayrun am mai yaateee aaminai Yawmal Qiyaamah; i'maloo ma shi'tum innahoo bimaa ta'maloona Baseer", "translation": "Indeed, those who inject deviation into Our verses are not concealed from Us. So, is he who is cast into the Fire better or he who comes secure on the Day of Resurrection? Do whatever you will; indeed, He is Seeing of what you do."}, {"ayah": 41, "translit": "Inna Lazeena kafaroo biz Zikri lammaa jaa'ahum wa innahoo la Kitaabun 'Azeez", "translation": "Indeed, those who disbelieve in the message after it has come to them... And indeed, it is a mighty Book."}, {"ayah": 42, "translit": "Laa yaateehil baatilu mim baini yadaihi wa laa min khalfihee tanzeelum min Hakeemin Hameed", "translation": "Falsehood cannot approach it from before it or from behind it; [it is] a revelation from a [Lord who is] Wise and Praiseworthy."}, {"ayah": 43, "translit": "Maa yuqaalu laka illaa maa qad qeela lir Rusuli min qablik; inna Rabbaka lazoo maghfiratinw wa zoo 'iqaabin aleem", "translation": "Nothing is said to you, [O Muhammad], except what was already said to the messengers before you. Indeed, your Lord is a possessor of forgiveness and a possessor of painful penalty."}, {"ayah": 44, "translit": "Wa law ja'alnaahu Qur-aanan A'jamiyyal laqaaloo law laa fussilat Aayaatuhoo 'a A'jamiyyunw wa 'Arabiyy; qul huwa lillazeena aamanoo hudanw wa shifaaa'unw wallazeena la yu'minoona feee aazaanihim waqrunw wa huwa 'alaihim 'amaa; ulaaa'ika yunaadawna mim maakaanim ba'eed", "translation": "And if We had made it a non-Arabic Qur'an, they would have said, \"Why are its verses not explained in detail [in our language]? Is it a foreign [recitation] and an Arab [messenger]?\" Say, \"It is, for those who believe, a guidance and cure.\" And those who do not believe - in their ears is deafness, and it is upon them blindness. Those are being called from a distant place."}, {"ayah": 45, "translit": "Wa laqad aatainaa Moosal Kitaaba fakhtulifa fee; wa lawlaa Kalimatun sabaqat mir Rabbika laqudiya bainahum; wa innahum lafee shakkim minhu mureeb", "translation": "And We had already given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been concluded between them. And indeed they are, concerning the Qur'an, in disquieting doubt."}, {"ayah": 46, "translit": "Man 'amila salihan falinafshihee wa man asaaa'a fa'alaihaa; wamaa rabbuka bizallaamil lil 'abeed", "translation": "Whoever does righteousness - it is for his [own] soul; and whoever does evil [does so] against it. And your Lord is not ever unjust to [His] servants."}, {"ayah": 47, "translit": "Ilaihi yuraddu 'ilmus Saaa'ah; wa maa takhruju min samaraatim min akmaamihaa wa maa tahmilu min unsaa wa laa tada'u illaa bi'ilmih; wa Yawma yunaadeehim aina shurakaaa'ee qaalooo aazannaaka maa minnaa min shaheed", "translation": "To him [alone] is attributed knowledge of the Hour. And fruits emerge not from their coverings nor does a female conceive or give birth except with His knowledge. And the Day He will call to them, \"Where are My 'partners'?\" they will say, \"We announce to You that there is [no longer] among us any witness [to that].\""}, {"ayah": 48, "translit": "Wa dalla 'anhum maa kaanoo yad'oona min qablu wa zannoo maa lahum mim mahees", "translation": "And lost from them will be those they were invoking before, and they will be certain that they have no place of escape."}, {"ayah": 49, "translit": "Laa yas'amul insaanu min du'aaa'il khairi wa im massa hush sharru fa ya'oosun qanoot", "translation": "Man is not weary of supplication for good [things], but if evil touches him, he is hopeless and despairing."}, {"ayah": 50, "translit": "Wa la in azaqnaahu rahmatam minnaa mim ba'di dar raaa'a massat hu la yaqoolanna haazaa lee wa maaa azunnus Saa'ata qaaa'imatanw wa la'in ruji'tu ilaa Rabbeee inna lee 'indahoo lalhusnaa; falanu nabbi'annal lazeena kafaroo bimaa 'amiloo wa lanuzeeqan nahum min 'azaabin ghaleez", "translation": "And if We let him taste mercy from Us after an adversity which has touched him, he will surely say, \"This is [due] to me, and I do not think the Hour will occur; and [even] if I should be returned to my Lord, indeed, for me there will be with Him the best.\" But We will surely inform those who disbelieved about what they did, and We will surely make them taste a massive punishment."}, {"ayah": 51, "translit": "Wa izaaa an'amnaa 'alal insaani a'rada wa na-aa bijaani bihee wa izaa massahush sharru fazoo du'aaa'in 'areed", "translation": "And when We bestow favor upon man, he turns away and distances himself; but when evil touches him, then he is full of extensive supplication."}, {"ayah": 52, "translit": "Qul araiaitum in kaana min 'indil laahi summa kafar tum bihee man adallu mimman huwa fee shiqaqim ba'eed", "translation": "Say, \"Have you considered: if the Qur'an is from Allah and you disbelieved in it, who would be more astray than one who is in extreme dissension?\""}, {"ayah": 53, "translit": "Sanureehim Aayaatinaa fil aafaaqi wa feee anfusihim hattaa yatabaiyana lahum annahul haqq; awa lam yakfi bi Rabbika annahoo 'alaa kulli shai-in Shaheed", "translation": "We will show them Our signs in the horizons and within themselves until it becomes clear to them that it is the truth. But is it not sufficient concerning your Lord that He is, over all things, a Witness?"}, {"ayah": 54, "translit": "Alaaa innahum fee miryatim mil liqaaa'i Rabbihim; alaaa innahoo bikulli shai'im muheet", "translation": "Unquestionably, they are in doubt about the meeting with their Lord. Unquestionably He is, of all things, encompassing."}]}, {"num": 42, "name": "Ash-Shura", "meaning": "The Consultation", "verses": [{"ayah": 1, "translit": "Haa Meeem", "translation": "Ha, Meem."}, {"ayah": 2, "translit": "'Ayyyn Seeen Qaaaf", "translation": "'Ayn, Seen, Qaf."}, {"ayah": 3, "translit": "Kazaalika yooheee ilaika wa ilal lazeena min qablikal laahul 'Azeezul Hakeem", "translation": "Thus has He revealed to you, [O Muhammad], and to those before you - Allah, the Exalted in Might, the Wise."}, {"ayah": 4, "translit": "Lahoo maa fis samaa waati wa maa fil ardi wa Huwal 'Aliyul 'Azeem", "translation": "To Him belongs whatever is in the heavens and whatever is in the earth, and He is the Most High, the Most Great."}, {"ayah": 5, "translit": "Takaadus samaawaatu yatafattarna min fawqihinn; walmalaaa'ikatu yusabbihoona bihamdi Rabbihim wa yastaghfiroona liman fil ard; alaaa innal laaha huwal Ghafoorur Raheem", "translation": "The heavens almost break from above them, and the angels exalt [Allah] with praise of their Lord and ask forgiveness for those on earth. Unquestionably, it is Allah who is the Forgiving, the Merciful."}, {"ayah": 6, "translit": "Wallazeenat takhazoo min dooniheee awliyaaa'al laahu hafeezun 'alaihim wa maaa anta 'alaihim biwakeel", "translation": "And those who take as allies other than Him - Allah is [yet] Guardian over them; and you, [O Muhammad], are not over them a manager."}, {"ayah": 7, "translit": "Wa kazaalika awhainaaa llaika Qur-aanan 'Arabiyyal litunzir aUmmal Quraa wa man hawlahaa wa tunzira Yawmal Jam'ilaa raiba feeh; fareequn fil jannati wa fareequn fissa'eer", "translation": "And thus We have revealed to you an Arabic Qur'an that you may warn the Mother of Cities [Makkah] and those around it and warn of the Day of Assembly, about which there is no doubt. A party will be in Paradise and a party in the Blaze."}, {"ayah": 8, "translit": "Wa law shaaa'al laahu laja'alahum ummatanw waahi datanw walaakiny yudkhilumany yashaaa'u fee rahmatih; waz zaalimoona maa lahum minw waliyyinw wa laa naseer", "translation": "And if Allah willed, He could have made them [of] one religion, but He admits whom He wills into His mercy. And the wrongdoers have not any protector or helper."}, {"ayah": 9, "translit": "Amit takhazoo min dooniheee awliyaaa'a fallaahu Huwal Waliyyu wa Huwa yuhyil mawtaa wa Huwa 'alaa kulli shai'in Qadeer", "translation": "Or have they taken protectors [or allies] besides him? But Allah - He is the Protector, and He gives life to the dead, and He is over all things competent."}, {"ayah": 10, "translit": "Wa makh-talaftum feehi min shai'in fahukmuhooo ilallaah; zaalikumul laahu Rabbee 'alaihi tawakkaltu wa ilaihi uneeb", "translation": "And in anything over which you disagree - its ruling is [to be referred] to Allah. [Say], \"That is Allah, my Lord; upon Him I have relied, and to Him I turn back.\""}, {"ayah": 11, "translit": "Faatirus samaawaati wal ard; ja'ala lakum min anfusikum azwaajanw wa minal an'aami azwaajai yazra'ukum feeh; laisa kamislihee shai'unw wa Huwas Samee'ul Baseer", "translation": "[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing."}, {"ayah": 12, "translit": "Lahoo maqaaleedus samaawaati wal ardi yabsutur rizqa limai yashaaa'u wa yaqdir; innahoo bikulli shai'in 'Aleem", "translation": "To Him belong the keys of the heavens and the earth. He extends provision for whom He wills and restricts [it]. Indeed He is, of all things, Knowing."}, {"ayah": 13, "translit": "Shara'a lakum minad deeni maa wassaa bihee Noohanw wallazeee awhainaaa ilaika wa maa wassainaa biheee Ibraaheema wa Moosa wa 'Eesaaa an aqeemud adeena wa laa tatafarraqoo feeh; kabura 'alal mushrikeena maa tad'oohum ilaih; Allaahu yajtabee ilaihi mai yashaaa'u wa yahdeee ilaihi mai yuneeb", "translation": "He has ordained for you of religion what He enjoined upon Noah and that which We have revealed to you, [O Muhammad], and what We enjoined upon Abraham and Moses and Jesus - to establish the religion and not be divided therein. Difficult for those who associate others with Allah is that to which you invite them. Allah chooses for Himself whom He wills and guides to Himself whoever turns back [to Him]."}, {"ayah": 14, "translit": "Wa maa tafarraqooo illaa mim ba'di maa jaaa'ahumul 'ilmu baghyam bainahum; wa law laa Kalimatun sabaqat mir Rabbika ilaaa ajalim musammal laqudiya bainahum; wa innal lazeena oorisul Kitaaba mim ba'dihim lafee shakkim minhu mureeb", "translation": "And they did not become divided until after knowledge had come to them - out of jealous animosity between themselves. And if not for a word that preceded from your Lord [postponing the penalty] until a specified time, it would have been concluded between them. And indeed, those who were granted inheritance of the Scripture after them are, concerning it, in disquieting doubt."}, {"ayah": 15, "translit": "Falizaalika fad'u wastaqim kamaaa umirta wa laa tattabi' ahwaaa'ahum wa qul aamantu bimaaa anzalal laahu min Kitaab, wa umirtu li a'dila bainakum Allaahu Rabbunaa wa Rabbukum lanaaa a'maa lunaa wa lakum a'maalukim laa hujjata bainanaa wa baina kumul laahu yajma'u bainanaa wa ilaihil maseer", "translation": "So to that [religion of Allah] invite, [O Muhammad], and remain on a right course as you are commanded and do not follow their inclinations but say, \"I have believed in what Allah has revealed of the Qur'an, and I have been commanded to do justice among you. Allah is our Lord and your Lord. For us are our deeds, and for you your deeds. There is no [need for] argument between us and you. Allah will bring us together, and to Him is the [final] destination.\""}, {"ayah": 16, "translit": "Wallazeena yuhaaajjoona fil laahi mim ba'di mastujeeba lahoo hujjatuhum daahidatun 'inda Rabbihim wa 'alaihim ghadabunw wa lahum 'azaabun shadeed", "translation": "And those who argue concerning Allah after He has been responded to - their argument is invalid with their Lord, and upon them is [His] wrath, and for them is a severe punishment."}, {"ayah": 17, "translit": "Allahul lazeee anzalal Kitaaba bilhaqqi wal Meezaan; wa ma yudreeka la'allas Saa'ata qareeb", "translation": "It is Allah who has sent down the Book in truth and [also] the balance. And what will make you perceive? Perhaps the Hour is near."}, {"ayah": 18, "translit": "Yasta'jilu bihal lazeena laa yu'minoona bihaa wallazeena aamanoo mushfiqoona minhaa wa ya'lamoona annahal haqq; alaaa innal lazeena yumaaroona fis Saa'ati lafee dalaalim ba'eed", "translation": "Those who do not believe in it are impatient for it, but those who believe are fearful of it and know that it is the truth. Unquestionably, those who dispute concerning the Hour are in extreme error."}, {"ayah": 19, "translit": "Allahu lateefum bi'ibaadihee yarzuqu mai yashaaa'u wa Huwal Qawiyyul 'Azeez", "translation": "Allah is Subtle with His servants; He gives provisions to whom He wills. And He is the Powerful, the Exalted in Might."}, {"ayah": 20, "translit": "Man kaana yureedu harsal Aakhirati nazid lahoo fee harsihee wa man kaana yureedu harsad dunyaa nu'tihee mnhaa wa maa lahoo fil Aakhirati min naseeb", "translation": "Whoever desires the harvest of the Hereafter - We increase for him in his harvest. And whoever desires the harvest of this world - We give him thereof, but there is not for him in the Hereafter any share."}, {"ayah": 21, "translit": "Am lahum shurakaaa'u shara'oo lahum minad deeni maa lam yaazam bihil laah; wa law laa kalimatul fasli laqudiya bainahum; wa innaz zaalimeena lahum 'azaabun aleem", "translation": "Or have they other deities who have ordained for them a religion to which Allah has not consented? But if not for the decisive word, it would have been concluded between them. And indeed, the wrongdoers will have a painful punishment."}, {"ayah": 22, "translit": "Taraz zaalimeena mushfiqeena mimmaa kasaboo wa huwa waaqi'um bihim; wallazeena aamanoo wa 'amilus saalihaati fee rawdaatil jannaati lahum maa yashaaa'oona 'inda Rabbihim; zaalika huwal fadlul kabeer", "translation": "You will see the wrongdoers fearful of what they have earned, and it will [certainly] befall them. And those who have believed and done righteous deeds will be in lush regions of the gardens [in Paradise] having whatever they will in the presence of their Lord. That is what is the great bounty."}, {"ayah": 23, "translit": "Zaalikal lazee yubash shirul laahu 'ibaadahul lazeena aamanoo wa 'amilus saalihaat; qul laaa as'alukum 'alaihi ajran illal mawaddata fil qurbaa; wa mai yaqtarif hasanatan nazid lahoo feehaa husnaa; innal laaha Ghafoorun Shakoor", "translation": "It is that of which Allah gives good tidings to His servants who believe and do righteous deeds. Say, [O Muhammad], \"I do not ask you for this message any payment [but] only good will through kinship.\" And whoever commits a good deed - We will increase for him good therein. Indeed, Allah is Forgiving and Appreciative."}, {"ayah": 24, "translit": "Am yaqooloonaf tara 'alal laahi kaziban fa-iny yasha il laahu yakhtim 'alaa qalbik; wa yamhul laahul baatila wa yuhiqqul haqqa bi Kalimaatih; innahoo 'Aleemum bizaatis sudoor", "translation": "Or do they say, \"He has invented about Allah a lie\"? But if Allah willed, He could seal over your heart. And Allah eliminates falsehood and establishes the truth by His words. Indeed, He is Knowing of that within the breasts."}, {"ayah": 25, "translit": "Wa Huwal lazee yaqbalut tawbata 'an 'ibaadihee wa ya'foo 'anis saiyiaati wa ya'lamu maa taf'aloon", "translation": "And it is He who accepts repentance from his servants and pardons misdeeds, and He knows what you do."}, {"ayah": 26, "translit": "Wa yastajeebul lazeena aamanoo wa 'amilu saalihaati wa yazeeduhum min fadlih; wal kaafiroona lahum 'azaabun shadeed", "translation": "And He answers [the supplication of] those who have believed and done righteous deeds and increases [for] them from His bounty. But the disbelievers will have a severe punishment."}, {"ayah": 27, "translit": "Wa law basatal laahur rizqa li'ibaadihee labaghaw fil ardi wa laakiny yunazzilu biqadarim maa yashaaa'; innahoo bi'ibaadihee Khabeerum Baseer", "translation": "And if Allah had extended [excessively] provision for His servants, they would have committed tyranny throughout the earth. But He sends [it] down in an amount which He wills. Indeed He is, of His servants, Acquainted and Seeing."}, {"ayah": 28, "translit": "Wa Huwal lazee yunazzilul ghaisa mim ba'di maa qanatoo wa yanshuru rahmatah; wa Huwal Waliyyul Hameed", "translation": "And it is He who sends down the rain after they had despaired and spreads His mercy. And He is the Protector, the Praiseworthy."}, {"ayah": 29, "translit": "Wa min Aayaatihee khalqus samaawaati wal ardi wa maa bassa feehimaa min daaabbah; wa Huwa 'alaa jam'ihim izaa yashaaa'u Qadeer", "translation": "And of his signs is the creation of the heavens and earth and what He has dispersed throughout them of creatures. And He, for gathering them when He wills, is competent."}, {"ayah": 30, "translit": "Wa maaa asaabakum mim museebatin fabimaa kasabat aydeekum wa ya'foo 'an kaseer", "translation": "And whatever strikes you of disaster - it is for what your hands have earned; but He pardons much."}, {"ayah": 31, "translit": "Wa maaa antum bimu'jizeena fil ardi wa maa lakum min doonil laahi minw wa liyyinw wa laa naseer", "translation": "And you will not cause failure [to Allah] upon the earth. And you have not besides Allah any protector or helper."}, {"ayah": 32, "translit": "Wa min Aayaatihil ja waarifil bahri kal a'lam", "translation": "And of His signs are the ships in the sea, like mountains."}, {"ayah": 33, "translit": "Iny yashaaa yuskinir reeha fa yazlalna rawaakida 'alaa zahirh; inna fee zaalika la Aayaatil likulli sabbaarin shakoor", "translation": "If He willed, He could still the wind, and they would remain motionless on its surface. Indeed in that are signs for everyone patient and grateful."}, {"ayah": 34, "translit": "Aw yoobiqhunna bimaa kasaboo wa ya'fu 'an kaseer", "translation": "Or He could destroy them for what they earned; but He pardons much."}, {"ayah": 35, "translit": "Wa ya'lamal lazeena yujaadiloona feee Aayaatinaa maa lahum mim mahees", "translation": "And [that is so] those who dispute concerning Our signs may know that for them there is no place of escape."}, {"ayah": 36, "translit": "Famaa ooteetum min shai'in famataa'ul hayaatid dunyaa wa maa 'indal laahi khairunw wa abqaa lillazeena aamanoo wa 'alaa Rabbihim yatawakkaloon", "translation": "So whatever thing you have been given - it is but [for] enjoyment of the worldly life. But what is with Allah is better and more lasting for those who have believed and upon their Lord rely"}, {"ayah": 37, "translit": "Wallazeena yajtaniboona kabaaa'iral ismi wal fawaa hisha wa izaa maa ghadiboo hum yaghfiroon", "translation": "And those who avoid the major sins and immoralities, and when they are angry, they forgive,"}, {"ayah": 38, "translit": "Wallazeenas tajaaboo li Rabbhim wa aqaamus Salaata wa amruhum shooraa bainahum wa mimmaa razaqnaahum yunfiqoon", "translation": "And those who have responded to their lord and established prayer and whose affair is [determined by] consultation among themselves, and from what We have provided them, they spend."}, {"ayah": 39, "translit": "Wallazeena izaa asaabahumul baghyu hum yantasiroon", "translation": "And those who, when tyranny strikes them, they defend themselves,"}, {"ayah": 40, "translit": "Wa jazaaa'u saiyi'atin saiyi'tum misluha faman 'afaa wa aslaha fa ajruhoo 'alal laah; innahoo laa yuhibbuz zaalimeen", "translation": "And the retribution for an evil act is an evil one like it, but whoever pardons and makes reconciliation - his reward is [due] from Allah. Indeed, He does not like wrongdoers."}, {"ayah": 41, "translit": "Wa lamanin tasara ba'da zulmihee fa ulaaa'ika maa 'alaihim min sabeel", "translation": "And whoever avenges himself after having been wronged - those have not upon them any cause [for blame]."}, {"ayah": 42, "translit": "Innamas sabeelu 'alal lazeena yazlimoonan naasa wa yabghoona fil ardi bighairil haqq; ulaaa'ika lahum 'azaabun aleem", "translation": "The cause is only against the ones who wrong the people and tyrannize upon the earth without right. Those will have a painful punishment."}, {"ayah": 43, "translit": "Wa laman sabara wa ghafara inna zaalika lamin 'azmil umoor", "translation": "And whoever is patient and forgives - indeed, that is of the matters [requiring] determination."}, {"ayah": 44, "translit": "Wa mai yudlilil laahu famaa lahoo minw waliyyim mim ba'dih; wa taraz zaalimeena lammaa ra awul 'azaaba yaqooloona hal ilaa maraddim min sabeel", "translation": "And he whom Allah sends astray - for him there is no protector beyond Him. And you will see the wrongdoers, when they see the punishment, saying, \"Is there for return [to the former world] any way?\""}, {"ayah": 45, "translit": "Wa taraahum yu'radoona 'alaihaa khaashi'eena minazzulli yanzuroona min tarfin khaifiyy; wa qaalal lazeena aamanooo innal khaasireenal lazeena khasiroon anfusahum wa ahleehim Yawmal Qiyaamah; alaaa innaz zaalimeena fee'azaabim muqeem", "translation": "And you will see them being exposed to the Fire, humbled from humiliation, looking from [behind] a covert glance. And those who had believed will say, \"Indeed, the [true] losers are the ones who lost themselves and their families on the Day of Resurrection. Unquestionably, the wrongdoers are in an enduring punishment.\""}, {"ayah": 46, "translit": "Wa maa kaana lahum min awliyaaa'a yansuroonahum min doonil laah; wa mai yudlilil laahu famaa lahoo min sabeel", "translation": "And there will not be for them any allies to aid them other than Allah. And whoever Allah sends astray - for him there is no way."}, {"ayah": 47, "translit": "Istajeeboo li Rabbikum min qabli any yaatiya Yawmul laa maradda lahoo minal laah; maa lakum mim malja iny yawma'izinw wa maa lakum min nakeer", "translation": "Respond to your Lord before a Day comes from Allah of which there is no repelling. No refuge will you have that day, nor for you will there be any denial."}, {"ayah": 48, "translit": "Fa-in a'radoo famaaa arsalnaaka 'alaihim hafeezan in 'alaika illal balaagh; wa innaaa izaaa azaqnal insaana minnaa rahmatan fariha bihaa wa in tusibhum saiyi'atum bimaa qaddamat aydeehim fa innal insaana kafoor", "translation": "But if they turn away - then We have not sent you, [O Muhammad], over them as a guardian; upon you is only [the duty of] notification. And indeed, when We let man taste mercy from us, he rejoices in it; but if evil afflicts him for what his hands have put forth, then indeed, man is ungrateful."}, {"ayah": 49, "translit": "Lillaahi mulkus samaawaati wal ard; yakhluqu maa yashaaa'; yahabu limai yashaaa'u inaasanw wa yahabu limai yashaaa'uz zukoor", "translation": "To Allah belongs the dominion of the heavens and the earth; He creates what he wills. He gives to whom He wills female [children], and He gives to whom He wills males."}, {"ayah": 50, "translit": "Aw yuzawwijuhum zukraananw wa inaasanw wa yaj'alu mai yashaaa'u 'aqeemaa; innahoo 'Aleemun Qadeer", "translation": "Or He makes them [both] males and females, and He renders whom He wills barren. Indeed, He is Knowing and Competent."}, {"ayah": 51, "translit": "Wa maa kaana libasharin any yukallimahul laahu illaa wahyan aw minw waraaa'i hijaabin aw yursila Rasoolan fa yoohiya bi iznuhee maa yashaaa'; innahoo 'Aliyyun Hakeem", "translation": "And it is not for any human being that Allah should speak to him except by revelation or from behind a partition or that He sends a messenger to reveal, by His permission, what He wills. Indeed, He is Most High and Wise."}, {"ayah": 52, "translit": "Wa kazaalika awhainaaa ilaika rooham min amrinaa; maa kunta tadree mal Kitaabu wa lal eemaanu wa laakin ja'alnaahu nooran nahdee bihee man nashaaa'u min 'ibaadinaa; wa innaka latahdeee ilaaa Siraatim Mustaqeem", "translation": "And thus We have revealed to you an inspiration of Our command. You did not know what is the Book or [what is] faith, but We have made it a light by which We guide whom We will of Our servants. And indeed, [O Muhammad], you guide to a straight path -"}, {"ayah": 53, "translit": "Siraatil laahil lazee lahoo maa fis samaawaati wa maa fil ard; alaaa ilal laahi taseerul umoor", "translation": "The path of Allah, to whom belongs whatever is in the heavens and whatever is on the earth. Unquestionably, to Allah do [all] matters evolve."}]}, {"num": 43, "name": "Az-Zukhruf", "meaning": "The Gold Adornment", "verses": [{"ayah": 1, "translit": "Haa-Meeem", "translation": "Ha, Meem."}, {"ayah": 2, "translit": "Wal Kitaabil Mubeen", "translation": "By the clear Book,"}, {"ayah": 3, "translit": "Innaa ja'alnaahu Quraanan 'Arabiyyal la'allakum ta'qiloon", "translation": "Indeed, We have made it an Arabic Qur'an that you might understand."}, {"ayah": 4, "translit": "Wa innahoo feee Ummil Kitaabi Ladainaa la'aliyyun hakeem", "translation": "And indeed it is, in the Mother of the Book with Us, exalted and full of wisdom."}, {"ayah": 5, "translit": "Afanadribu 'ankumuz Zikra safhan an kuntum qawmam musrifeen", "translation": "Then should We turn the message away, disregarding you, because you are a transgressing people?"}, {"ayah": 6, "translit": "Wa kam arsalnaa min Nabiyyin fil awwaleen", "translation": "And how many a prophet We sent among the former peoples,"}, {"ayah": 7, "translit": "Wa maa yaateehim min Nabiyyin illaa kaanoo bihee yasahzi'oon", "translation": "But there would not come to them a prophet except that they used to ridicule him."}, {"ayah": 8, "translit": "Fa ahlaknaaa ashadda minhum batshanw wa madaa masalul lawwaleen", "translation": "And We destroyed greater than them in [striking] power, and the example of the former peoples has preceded."}, {"ayah": 9, "translit": "Wa la'in sa altahum man khalaqas samaawaati wal arda la yaqoolunna khalaqa hunnal 'Azeezul 'Aleem", "translation": "And if you should ask them, \"Who has created the heavens and the earth?\" they would surely say, \"They were created by the Exalted in Might, the Knowing.\""}, {"ayah": 10, "translit": "Allazee ja'ala lakumul arda mahdanw wa ja'ala lakum feehaa subulal la'allakum tahtadoon", "translation": "[The one] who has made for you the earth a bed and made for you upon it roads that you might be guided"}, {"ayah": 11, "translit": "Wallazee nazzala minas samaaa'i maaa'am biqadarin fa anshamaa bihee baldatam maitaa' kazaalika tukhrajoon", "translation": "And who sends down rain from the sky in measured amounts, and We revive thereby a dead land - thus will you be brought forth -"}, {"ayah": 12, "translit": "Wallazee khalaqal azwaaja kullahaa wa ja'ala lakum minal fulki wal-an'aami maa tarkaboon", "translation": "And who created the species, all of them, and has made for you of ships and animals those which you mount."}, {"ayah": 13, "translit": "Litastawoo 'alaa zuhoorihee summa tazkuroo ni'mata Rabbikum izastawaitum 'alaihi wa taqooloo Subhaanal lazee sakhkhara lana haaza wa maa kunnaa lahoo muqrineen", "translation": "That you may settle yourselves upon their backs and then remember the favor of your Lord when you have settled upon them and say. \"Exalted is He who has subjected this to us, and we could not have [otherwise] subdued it."}, {"ayah": 14, "translit": "Wa innaaa ilaa Rabbinaa lamunqaliboon", "translation": "And indeed we, to our Lord, will [surely] return.\""}, {"ayah": 15, "translit": "Wa ja'aloo lahoo min 'ibaadihee juz'aa; innal insaana lakafoorum mubeen", "translation": "But they have attributed to Him from His servants a portion. Indeed, man is clearly ungrateful."}, {"ayah": 16, "translit": "Amit takhaza mimmaa yakhluqu banaatinw wa asfaakum bilbaneen", "translation": "Or has He taken, out of what He has created, daughters and chosen you for [having] sons?"}, {"ayah": 17, "translit": "Wa izaa bushshira ahaduhum bimaa daraba lir Rahmaani masalan zalla wajhuhoo muswaddanw wa hua kazeem", "translation": "And when one of them is given good tidings of that which he attributes to the Most Merciful in comparison, his face becomes dark, and he suppresses grief."}, {"ayah": 18, "translit": "Awa mai yunashsha'u fil hilyati wa huwa fil khisaami ghairu mubeen", "translation": "So is one brought up in ornaments while being during conflict unevident [attributed to Allah]?"}, {"ayah": 19, "translit": "Wa ja'alul malaaa'ikatal lazeena hum 'ibaadur Rahmaani inaasaa; a shahidoo khalaqhum; satuktabu shahaa datuhum wa yus'aloon", "translation": "And they have made the angels, who are servants of the Most Merciful, females. Did they witness their creation? Their testimony will be recorded, and they will be questioned."}, {"ayah": 20, "translit": "Wa qaaloo law shaaa'ar Rahmaanu maa 'abadnaahum; maa lahum bizaalika min 'ilmin in hum illaa yakhrusoon", "translation": "And they said, \"If the Most Merciful had willed, we would not have worshipped them.\" They have of that no knowledge. They are not but falsifying."}, {"ayah": 21, "translit": "Am aatainaahum Kitaabam min qablihee fahum bihee mustamsikoon", "translation": "Or have We given them a book before the Qur'an to which they are adhering?"}, {"ayah": 22, "translit": "Bal qaalooo innaa wajadnaaa aabaaa'anaa 'alaaa ummatinw wa innaa 'alaaa aasaarihim muhtadoon", "translation": "Rather, they say, \"Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided.\""}, {"ayah": 23, "translit": "Wa kazaalika maaa arsalnaa min qablika fee qaryatim min nazeerin illaa qaala mutrafoohaaa innaa wajadnaaa aabaaa'anaa 'alaaa ummatinw wa innaa 'alaaa aasaarihim muqtadoon", "translation": "And similarly, We did not send before you any warner into a city except that its affluent said, \"Indeed, we found our fathers upon a religion, and we are, in their footsteps, following.\""}, {"ayah": 24, "translit": "Qaala awa law ji'tukum bi ahdaa mimmaa wajattum 'alaihi aabaaa'akum qaalooo innaa bimaaa ursiltum bihee kaafiroon", "translation": "[Each warner] said, \"Even if I brought you better guidance than that [religion] upon which you found your fathers?\" They said, \"Indeed we, in that with which you were sent, are disbelievers.\""}, {"ayah": 25, "translit": "Fantaqamnaa minhum fanzur kaifa kaana 'aaqibatul mukazzibeen", "translation": "So we took retribution from them; then see how was the end of the deniers."}, {"ayah": 26, "translit": "Wa iz qaala Ibraaheemu liabeehi wa qawmiheee innane baraaa'um mimmaa ta'budo", "translation": "And [mention, O Muhammad], when Abraham said to his father and his people, \"Indeed, I am disassociated from that which you worship"}, {"ayah": 27, "translit": "Illal lazee fataranee innahoo sa yahdeen", "translation": "Except for He who created me; and indeed, He will guide me.\""}, {"ayah": 28, "translit": "Wa ja'alahaa Kalimatam baaqiyatan fee 'aqibihee la'al lahum yarji'oon", "translation": "And he made it a word remaining among his descendants that they might return [to it]."}, {"ayah": 29, "translit": "Bal matta'tu haaa'ulaaa'i wa aabaaa'ahum hattaa jaaa'a humul haqqu wa Rasoolum mubeen", "translation": "However, I gave enjoyment to these [people of Makkah] and their fathers until there came to them the truth and a clear Messenger."}, {"ayah": 30, "translit": "Wa lammaa jaaa'ahumul haqqu qaaloo haazaa sihrunw wa innaa bihee kaafiroon", "translation": "But when the truth came to them, they said, \"This is magic, and indeed we are, concerning it, disbelievers.\""}, {"ayah": 31, "translit": "Wa qaaloo law laa nuzzila haazal Quraanu 'alaa rajulim minal qaryataini 'azeem", "translation": "And they said, \"Why was this Qur'an not sent down upon a great man from [one of] the two cities?\""}, {"ayah": 32, "translit": "Ahum yaqsimoona rahmata Rabbik; Nahnu qasamnaa bainahum ma'eeshatahum fil hayaatid dunyaa wa rafa'naa ba'dahum fawqa ba'din darajaatil liyattakhiza ba'duhum ba'dan sukhriyyaa; wa rahmatu Rabbika khairum mimmaa yajma'oon", "translation": "Do they distribute the mercy of your Lord? It is We who have apportioned among them their livelihood in the life of this world and have raised some of them above others in degrees [of rank] that they may make use of one another for service. But the mercy of your Lord is better than whatever they accumulate."}, {"ayah": 33, "translit": "Wa law laaa any yakoonan naasu ummatanw waahidatal laja'alnaa limany yakfuru bir Rahmaani libu yootihim suqufam min fiddatinw wa ma'aarija 'alaihaa yazharoon", "translation": "And if it were not that the people would become one community [of disbelievers], We would have made for those who disbelieve in the Most Merciful - for their houses - ceilings and stairways of silver upon which to mount"}, {"ayah": 34, "translit": "Wa libu yootihim abwaabanw wa sururan 'alaihaa yattaki'oon", "translation": "And for their houses - doors and couches [of silver] upon which to recline"}, {"ayah": 35, "translit": "Wa zukhrufaa; wa in kullu zaalika lammaa mataa'ul hayaatid dunyaa; wal aakhiratu 'inda Rabbika lilmuttaqeen", "translation": "And gold ornament. But all that is not but the enjoyment of worldly life. And the Hereafter with your Lord is for the righteous."}, {"ayah": 36, "translit": "Wa mai ya'shu 'an zikrir Rahmaani nuqaiyid lahoo Shaitaanan fahuwa lahoo qareen", "translation": "And whoever is blinded from remembrance of the Most Merciful - We appoint for him a devil, and he is to him a companion."}, {"ayah": 37, "translit": "Wa innahum la yasuddoo nahum 'anis sabeeli wa yahsaboona annahum muhtadoon", "translation": "And indeed, the devils avert them from the way [of guidance] while they think that they are [rightly] guided"}, {"ayah": 38, "translit": "Hattaaa izaa jaaa'anaa qaala yaa laita bainee wa bainaka bu'dal mashriqaini fabi'sal qareen", "translation": "Until, when he comes to Us [at Judgement], he says [to his companion], \"Oh, I wish there was between me and you the distance between the east and west - how wretched a companion.\""}, {"ayah": 39, "translit": "Wa lai yanfa'akumul Yawma iz zalamtum annakum fil 'azaabi mushtarikoon", "translation": "And never will it benefit you that Day, when you have wronged, that you are [all] sharing in the punishment."}, {"ayah": 40, "translit": "Afa anta tusmi'us summa aw tahdil 'umya wa man kaana fee dalaalim mubeen", "translation": "Then will you make the deaf hear, [O Muhammad], or guide the blind or he who is in clear error?"}, {"ayah": 41, "translit": "Fa immaa nazhabanna bika fa innaa minhum muntaqimoon", "translation": "And whether [or not] We take you away [in death], indeed, We will take retribution upon them."}, {"ayah": 42, "translit": "Aw nuriyannakal lazee wa'adnaahum fa innaa 'alaihim muqtadiroon", "translation": "Or whether [or not] We show you that which We have promised them, indeed, We are Perfect in Ability."}, {"ayah": 43, "translit": "Fastamsik billazeee oohi ya ilaika innaka 'alaa Siraatim Mustaqeem", "translation": "So adhere to that which is revealed to you. Indeed, you are on a straight path."}, {"ayah": 44, "translit": "Wa innahoo lazikrul laka wa liqawmika wa sawfa tus'aloon", "translation": "And indeed, it is a remembrance for you and your people, and you [all] are going to be questioned."}, {"ayah": 45, "translit": "Was'al man arsalnaa min qablika mir Rusulinaaa aja'alnaa min doonir Rahmaani aalihatany yu badoon", "translation": "And ask those We sent before you of Our messengers; have We made besides the Most Merciful deities to be worshipped?"}, {"ayah": 46, "translit": "Wa laqad arsalnaa Moosaa bi aayaatinaaa ilaa Fir'awna wa mala'ihee faqaala innee Rasoolu Rabbil 'aalameen", "translation": "And certainly did We send Moses with Our signs to Pharaoh and his establishment, and he said, \"Indeed, I am the messenger of the Lord of the worlds.\""}, {"ayah": 47, "translit": "Falammma jaaa'ahum bi aayaatinaaa izaa hum minhaa yadhakoon", "translation": "But when he brought them Our signs, at once they laughed at them."}, {"ayah": 48, "translit": "Wa maa nureehim min aayatin illaa hiya akbaru min ukhtihaa wa akhaznaahum bil'azaabi la'allahum yarji'oon", "translation": "And We showed them not a sign except that it was greater than its sister, and We seized them with affliction that perhaps they might return [to faith]."}, {"ayah": 49, "translit": "Wa qaaloo yaaa ayyuhas saahirud'u lanaa Rabbaka bimaa 'ahida 'indaka innanaa lamuhtadoon", "translation": "And they said [to Moses], \"O magician, invoke for us your Lord by what He has promised you. Indeed, we will be guided.\""}, {"ayah": 50, "translit": "Falammaa kashafnaa 'anhumul 'azaaba izaa hum yankusoon", "translation": "But when We removed from them the affliction, at once they broke their word."}, {"ayah": 51, "translit": "Wa naadaa Fir'awnu fee qawmihee qaala yaa qawmi alaisa lee mulku Misra wa haazihil anhaaru tajree min tahtee afalaa tubsiroon", "translation": "And Pharaoh called out among his people; he said, \"O my people, does not the kingdom of Egypt belong to me, and these rivers flowing beneath me; then do you not see?"}, {"ayah": 52, "translit": "Am ana khairum min haazal lazee huwa maheenunw wa laa yuakaadu yubeen", "translation": "Or am I [not] better than this one who is insignificant and hardly makes himself clear?"}, {"ayah": 53, "translit": "Falaw laa ulqiya 'alaihi aswiratum min zahabin awjaaa'a ma'ahul malaaa'ikatu muqtarineen", "translation": "Then why have there not been placed upon him bracelets of gold or come with him the angels in conjunction?\""}, {"ayah": 54, "translit": "Fastakhaffa qawmahoo fa ataa'ooh; innahum kaanoo qawman faasiqeen", "translation": "So he bluffed his people, and they obeyed him. Indeed, they were [themselves] a people defiantly disobedient [of Allah]."}, {"ayah": 55, "translit": "Falammaaa aasafoonan taqamnaa minhum fa aghraqnaahum ajma'een", "translation": "And when they angered Us, We took retribution from them and drowned them all."}, {"ayah": 56, "translit": "Faja'alnaahum salafanw wa masalal lil aakhireen", "translation": "And We made them a precedent and an example for the later peoples."}, {"ayah": 57, "translit": "Wa lammaa duribab nu Maryama masalan izaa qawmu ka minhu yasidoon", "translation": "And when the son of Mary was presented as an example, immediately your people laughed aloud."}, {"ayah": 58, "translit": "Wa qaalooo 'a-aalihatunaa khairun am hoo; maa daraboohu laka illaa jadalaa; balhum qawmun khasimoon", "translation": "And they said, \"Are your gods better, or is he?\" They did not present the comparison except for [mere] argument. But, [in fact], they are a people prone to dispute."}, {"ayah": 59, "translit": "In huwa illaa 'abdun an'amnaa 'alaihi wa ja'alnaahu masalal li Baneee Israaa'eel", "translation": "Jesus was not but a servant upon whom We bestowed favor, and We made him an example for the Children of Israel."}, {"ayah": 60, "translit": "Wa law nashaaa'u laja'alnaa minkum malaaa'ikatan fil ardi yakhlufoon", "translation": "And if We willed, We could have made [instead] of you angels succeeding [one another] on the earth."}, {"ayah": 61, "translit": "Wa innahoo la'ilmul lis Saa'ati fala tamtarunna bihaa wattabi'oon; haazaa Siraatum Mustaqeem", "translation": "And indeed, Jesus will be [a sign for] knowledge of the Hour, so be not in doubt of it, and follow Me. This is a straight path."}, {"ayah": 62, "translit": "Wa laa yasuddan nakumush Shaitaanu innahoo lakum 'aduwwum mubeen", "translation": "And never let Satan avert you. Indeed, he is to you a clear enemy."}, {"ayah": 63, "translit": "Wa lammaa jaaa'a 'Eesaa bilbaiyinaati qaala qad ji'tukum bil Hikmati wa li-ubaiyina lakum ba'dal lazee takhtalifoona feehi fattaqul laaha wa atee'oon", "translation": "And when Jesus brought clear proofs, he said, \"I have come to you with wisdom and to make clear to you some of that over which you differ, so fear Allah and obey me."}, {"ayah": 64, "translit": "Innal laaha Huwa Rabbee wa Rabbukum fa'budooh; haaza Siraatum Mustaqeem", "translation": "Indeed, Allah is my Lord and your Lord, so worship Him. This is a straight path.\""}, {"ayah": 65, "translit": "Fakhtalafal ahzaabu mim bainihim fawailul lillazeena zalamoo min 'azaabi Yawmin aleem", "translation": "But the denominations from among them differed [and separated], so woe to those who have wronged from the punishment of a painful Day."}, {"ayah": 66, "translit": "Hal yanzuroona illas Saa'ata an taatiyahum baghtatanw wa hum laa yash'uroon", "translation": "Are they waiting except for the Hour to come upon them suddenly while they perceive not?"}, {"ayah": 67, "translit": "Al akhillaaa'u Yawma'izim ba'duhum liba'din 'aduwwun illal muttaqeen", "translation": "Close friends, that Day, will be enemies to each other, except for the righteous"}, {"ayah": 68, "translit": "Yaa 'ibaadi laa khawfun 'alaikumul Yawma wa laaa antum tahzanoon", "translation": "[To whom Allah will say], \"O My servants, no fear will there be concerning you this Day, nor will you grieve,"}, {"ayah": 69, "translit": "Allazeena aamanoo bi Aayaatinaa wa kaanoo muslimeen", "translation": "[You] who believed in Our verses and were Muslims."}, {"ayah": 70, "translit": "Udkhulul Jannata antum wa azwaajukum tuhbaroon", "translation": "Enter Paradise, you and your kinds, delighted.\""}, {"ayah": 71, "translit": "Yutaafu 'alaihim bishaa fim min zahabinw wa akwaab, wa feehaa maatashtaheehil anfusu wa talazzul a'yunu wa antum feehaa khaalidoon", "translation": "Circulated among them will be plates and vessels of gold. And therein is whatever the souls desire and [what] delights the eyes, and you will abide therein eternally."}, {"ayah": 72, "translit": "Wa tilkal jannatul lateee ooristumoohaa bimaa kuntum ta'maloon", "translation": "And that is Paradise which you are made to inherit for what you used to do."}, {"ayah": 73, "translit": "Lakum feehaa faakihatun kaseeratum minhaa taakuloon", "translation": "For you therein is much fruit from which you will eat."}, {"ayah": 74, "translit": "Innal mujrimeena fee 'azaabi jahannama khaalidoon", "translation": "Indeed, the criminals will be in the punishment of Hell, abiding eternally."}, {"ayah": 75, "translit": "Laa yufattaru 'anhum wa hum feehi mublisoon", "translation": "It will not be allowed to subside for them, and they, therein, are in despair."}, {"ayah": 76, "translit": "Wa maa zalamnaahum wa laakin kaanoo humuz zaalimeen", "translation": "And We did not wrong them, but it was they who were the wrongdoers."}, {"ayah": 77, "translit": "Wa naadaw yaa Maaliku liyaqdi 'alainaa Rabbuka qaala innakum maakisson", "translation": "And they will call, \"O Malik, let your Lord put an end to us!\" He will say, \"Indeed, you will remain.\""}, {"ayah": 78, "translit": "Laqad ji'naakum bilhaqqi wa laakinna aksarakum lilhaqqi kaarihoon", "translation": "We had certainly brought you the truth, but most of you, to the truth, were averse."}, {"ayah": 79, "translit": "Am abramooo amran fainnaa mubrimoon", "translation": "Or have they devised [some] affair? But indeed, We are devising [a plan]."}, {"ayah": 80, "translit": "Am yahsaboona annaa laa nasma'u sirrahum wa najwaahum; balaa wa Rusulunaa ladaihim yaktuboon", "translation": "Or do they think that We hear not their secrets and their private conversations? Yes, [We do], and Our messengers are with them recording."}, {"ayah": 81, "translit": "Qul in kaana lir Rahmaani walad; fa-ana awwalul 'aabideen", "translation": "Say, [O Muhammad], \"If the Most Merciful had a son, then I would be the first of [his] worshippers.\""}, {"ayah": 82, "translit": "Subhaana Rabbis samaawaati wal ardi Rabbil Arshi 'ammaa yasifoon", "translation": "Exalted is the Lord of the heavens and the earth, Lord of the Throne, above what they describe."}, {"ayah": 83, "translit": "Fazarhum yakhoodoo wa yal'aboo hattaa yulaaqoo Yawmahumul lazee yoo'adoon", "translation": "So leave them to converse vainly and amuse themselves until they meet their Day which they are promised."}, {"ayah": 84, "translit": "Wa Huwal lazee fissamaaa'i Ilaahunw wa fil ardi Ilaah; wa Huwal Hakeemul'Aleem", "translation": "And it is Allah who is [the only] deity in the heaven, and on the earth [the only] deity. And He is the Wise, the Knowing."}, {"ayah": 85, "translit": "Wa tabaarakal lazee lahoo mulkus samaawaati wal ardi wa maa bainahumaa wa 'indahoo 'ilmus Saa'ati wa ilaihi turja'oon", "translation": "And blessed is He to whom belongs the dominion of the heavens and the earth and whatever is between them and with whom is knowledge of the Hour and to whom you will be returned."}, {"ayah": 86, "translit": "Wa laa yamlikul lazeena yad'oona min doonihish shafaa'ata illaa man shahida bilhaqqi wa hum ya'lamoon", "translation": "And those they invoke besides Him do not possess [power of] intercession; but only those who testify to the truth [can benefit], and they know."}, {"ayah": 87, "translit": "Wa la'in sa altahum man khalaqahum la yaqoolun nallaahu fa annaa yu'fakoon", "translation": "And if you asked them who created them, they would surely say, \"Allah.\" So how are they deluded?"}, {"ayah": 88, "translit": "Wa qeelihee yaa Rabbi inna haa'ulaaa'i qawmul laa yu'minoon", "translation": "And [Allah acknowledges] his saying, \"O my Lord, indeed these are a people who do not believe.\""}, {"ayah": 89, "translit": "Fasfah 'anhum wa qul salaam; fasawfa ya'lamoon", "translation": "So turn aside from them and say, \"Peace.\" But they are going to know."}]}, {"num": 44, "name": "Ad-Dukhan", "meaning": "The Smoke", "verses": [{"ayah": 1, "translit": "Haa Meeem", "translation": "Ha, Meem."}, {"ayah": 2, "translit": "Wal Kitaabil Mubeen", "translation": "By the clear Book,"}, {"ayah": 3, "translit": "Innaaa anzalnaahu fee lailatim mubaarakah; innaa kunnaa munzireen", "translation": "Indeed, We sent it down during a blessed night. Indeed, We were to warn [mankind]."}, {"ayah": 4, "translit": "Feehaa yufraqu kullu amrin hakeem", "translation": "On that night is made distinct every precise matter -"}, {"ayah": 5, "translit": "Amram min 'indinaaa; innaa kunnaa mursileen", "translation": "[Every] matter [proceeding] from Us. Indeed, We were to send [a messenger]"}, {"ayah": 6, "translit": "Rahmatam mir rabbik; innahoo Huwas Samee'ul 'Aleem", "translation": "As mercy from your Lord. Indeed, He is the Hearing, the Knowing."}, {"ayah": 7, "translit": "Rabbis samaawaati wal ardi wa maa bainahumaa; in kuntum mooqineen", "translation": "Lord of the heavens and the earth and that between them, if you would be certain."}, {"ayah": 8, "translit": "Laaa ilaaha illaa Huwa yuhyee  wa yumeetu Rabbukum wa Rabbu aabaaa'ikumul awwaleen", "translation": "There is no deity except Him; He gives life and causes death. [He is] your Lord and the Lord of your first forefathers."}, {"ayah": 9, "translit": "Bal hum fee shakkiny yal'aboon", "translation": "But they are in doubt, amusing themselves."}, {"ayah": 10, "translit": "Fartaqib Yawma taatis samaaa'u bidukhaanim mubeen", "translation": "Then watch for the Day when the sky will bring a visible smoke."}, {"ayah": 11, "translit": "Yaghshan naasa haazaa 'azaabun aleem", "translation": "Covering the people; this is a painful torment."}, {"ayah": 12, "translit": "Rabbanak shif 'annal 'azaaba innaa mu'minoon", "translation": "[They will say], \"Our Lord, remove from us the torment; indeed, we are believers.\""}, {"ayah": 13, "translit": "Annaa lahumuz zikraa wa qad jaaa'ahum Rasoolum mubeen", "translation": "How will there be for them a reminder [at that time]? And there had come to them a clear Messenger."}, {"ayah": 14, "translit": "Summaa tawallaw 'anhu wa qaaloo mu'allamum majnoon", "translation": "Then they turned away from him and said, \"[He was] taught [and is] a madman.\""}, {"ayah": 15, "translit": "Innaa kaashiful 'azaabi qaleelaa; innakum 'aaa'indoon", "translation": "Indeed, We will remove the torment for a little. Indeed, you [disbelievers] will return [to disbelief]."}, {"ayah": 16, "translit": "Yawma nabtishul batsha tal kubraa innaa muntaqimoon", "translation": "The Day We will strike with the greatest assault, indeed, We will take retribution."}, {"ayah": 17, "translit": "Wa laqad fatannaa qablahum qawma Fir'awna wa jaaa'ahum Rasoolun kareem", "translation": "And We had already tried before them the people of Pharaoh, and there came to them a noble messenger,"}, {"ayah": 18, "translit": "An addooo ilaiya 'ibaadal laahi innee lakum Rasoolun ameen", "translation": "[Saying], \"Render to me the servants of Allah. Indeed, I am to you a trustworthy messenger,\""}, {"ayah": 19, "translit": "Wa al laa ta'loo 'alal laahi innee aateekum bisultaanim mubeen", "translation": "And [saying], \"Be not haughty with Allah. Indeed, I have come to you with clear authority."}, {"ayah": 20, "translit": "Wa innee 'uztu bi Rabbee wa rabbikum an tarjumoon", "translation": "And indeed, I have sought refuge in my Lord and your Lord, lest you stone me."}, {"ayah": 21, "translit": "Wa il lam tu'minoo lee fa'taziloon", "translation": "But if you do not believe me, then leave me alone.\""}, {"ayah": 22, "translit": "Fada'aa rabbahooo anna haaa'ulaaa'i qawmum mujrimoon", "translation": "And [finally] he called to his Lord that these were a criminal people."}, {"ayah": 23, "translit": "Fa asri bi'ibaadee lailan innakum muttaba'oon", "translation": "[Allah said], \"Then set out with My servants by night. Indeed, you are to be pursued."}, {"ayah": 24, "translit": "Watrukil bahra rahwan innahum jundum mughraqoon", "translation": "And leave the sea in stillness. Indeed, they are an army to be drowned.\""}, {"ayah": 25, "translit": "Kam tarakoo min jannaatinw wa 'uyoon", "translation": "How much they left behind of gardens and springs"}, {"ayah": 26, "translit": "Wa zuroo'inw wa maqaa min kareem", "translation": "And crops and noble sites"}, {"ayah": 27, "translit": "Wa na'matin kaanoo feehaa faakiheen", "translation": "And comfort wherein they were amused."}, {"ayah": 28, "translit": "Kazaalika wa awrasnaahaa qawman aakhareen", "translation": "Thus. And We caused to inherit it another people."}, {"ayah": 29, "translit": "Famaa bakat 'alaihimus samaaa'u wal ardu wa maa kaanoo munzareen", "translation": "And the heaven and earth wept not for them, nor were they reprieved."}, {"ayah": 30, "translit": "Wa laqad najjainaa Baneee Israaa'eela minal'azaabil muheen", "translation": "And We certainly saved the Children of Israel from the humiliating torment -"}, {"ayah": 31, "translit": "Min Fir'awn; innahoo kaana 'aaliyam minal musrifeen", "translation": "From Pharaoh. Indeed, he was a haughty one among the transgressors."}, {"ayah": 32, "translit": "Wa laqadikh tarnaahum 'alaa 'ilmin 'alal 'aalameen", "translation": "And We certainly chose them by knowledge over [all] the worlds."}, {"ayah": 33, "translit": "Wa aatainaahum minal aayaati maa feehi balaaa'um mubeen", "translation": "And We gave them of signs that in which there was a clear trial."}, {"ayah": 34, "translit": "Inna haaa'ulaaa'i la yaqooloon", "translation": "Indeed, these [disbelievers] are saying,"}, {"ayah": 35, "translit": "In hiya illaa mawtatunal oolaa wa maa nahnu bimun shareen", "translation": "\"There is not but our first death, and we will not be resurrected."}, {"ayah": 36, "translit": "Faatoo bi aabaaa'inaaa inkuntum saadiqeen", "translation": "Then bring [back] our forefathers, if you should be truthful.\""}, {"ayah": 37, "translit": "Ahum khayrun am qawmu Tubba'inw wallazeena min qablihim; ahlaknaahum innahum kaanoo mujrimeen", "translation": "Are they better or the people of Tubba' and those before them? We destroyed them, [for] indeed, they were criminals."}, {"ayah": 38, "translit": "Wa maa khalaqnas samaawaati wal arda wa maa baina humaa laa'ibeen", "translation": "And We did not create the heavens and earth and that between them in play."}, {"ayah": 39, "translit": "Maa khalaqnaahumaaa illaa bilhaqqi wa laakinna aksarahum laa ya'lamoon", "translation": "We did not create them except in truth, but most of them do not know."}, {"ayah": 40, "translit": "Inna yawmal fasli meeqaatuhum ajma'een", "translation": "Indeed, the Day of Judgement is the appointed time for them all -"}, {"ayah": 41, "translit": "Yawma laa yughnee mawlan 'am mawlan shai'anw wa laa hum yunsaroon", "translation": "The Day when no relation will avail a relation at all, nor will they be helped -"}, {"ayah": 42, "translit": "Illaa mar rahimal laah' innahoo huwal 'azeezur raheem", "translation": "Except those [believers] on whom Allah has mercy. Indeed, He is the Exalted in Might, the Merciful."}, {"ayah": 43, "translit": "Inna shajarataz zaqqoom", "translation": "Indeed, the tree of zaqqum"}, {"ayah": 44, "translit": "Ta'aamul aseem", "translation": "Is food for the sinful."}, {"ayah": 45, "translit": "Kalmuhli yaghlee filbutoon", "translation": "Like murky oil, it boils within bellies"}, {"ayah": 46, "translit": "Kaghalyil hameem", "translation": "Like the boiling of scalding water."}, {"ayah": 47, "translit": "Khuzoohu fa'tiloohu ilaa sawaaa'il Jaheem", "translation": "[It will be commanded], \"Seize him and drag him into the midst of the Hellfire,"}, {"ayah": 48, "translit": "Summa subboo fawqa raasihee min 'azaabil hameem", "translation": "Then pour over his head from the torment of scalding water.\""}, {"ayah": 49, "translit": "Zuq innaka antal 'azeezul kareem", "translation": "[It will be said], \"Taste! Indeed, you are the honored, the noble!"}, {"ayah": 50, "translit": "Inna haazaa maa kuntum bihee tamtaroon", "translation": "Indeed, this is what you used to dispute.\""}, {"ayah": 51, "translit": "Innal muttaqeena fee maqaamin ameen", "translation": "Indeed, the righteous will be in a secure place;"}, {"ayah": 52, "translit": "Fee jannaatinw wa 'uyoon", "translation": "Within gardens and springs,"}, {"ayah": 53, "translit": "Yalbasoona min sundusinw wa istbraqim mutaqaabileen", "translation": "Wearing [garments of] fine silk and brocade, facing each other."}, {"ayah": 54, "translit": "Kazaalika wa zawwajnaahum bihoorin 'een", "translation": "Thus. And We will marry them to fair women with large, [beautiful] eyes."}, {"ayah": 55, "translit": "Yad'oona feehaa bikulli faakihatin aamineen", "translation": "They will call therein for every [kind of] fruit - safe and secure."}, {"ayah": 56, "translit": "Laa yazooqoona feehal mawtaa illal mawtatal oolaa wa qaqaahum 'azaabal jaheem", "translation": "They will not taste death therein except the first death, and He will have protected them from the punishment of Hellfire"}, {"ayah": 57, "translit": "Fadlam mir rabbik; zaalika huwal fawzul 'azeem", "translation": "As bounty from your Lord. That is what is the great attainment."}, {"ayah": 58, "translit": "Fa innamaa yassarnaahu bilisaanika la'allahum yatazakkaroon", "translation": "And indeed, We have eased the Qur'an in your tongue that they might be reminded."}, {"ayah": 59, "translit": "Fartaqib innahum murta qiboon", "translation": "So watch, [O Muhammad]; indeed, they are watching [for your end]."}]}, {"num": 45, "name": "Al-Jathiyah", "meaning": "The Crouching", "verses": [{"ayah": 1, "translit": "Haa-Meeem", "translation": "Ha, Meem."}, {"ayah": 2, "translit": "Tanzeelul Kitaabi minal laahil 'Azeezil Hakeem", "translation": "The revelation of the Book is from Allah, the Exalted in Might, the Wise."}, {"ayah": 3, "translit": "Innaa fis samaawaati wal ardi la Aayaatil lilmu'mineen", "translation": "Indeed, within the heavens and earth are signs for the believers."}, {"ayah": 4, "translit": "Wa fee khalaqikum wa maa yabussu min daaabbatin Aayaatul liqawminy-yooqinoon", "translation": "And in the creation of yourselves and what He disperses of moving creatures are signs for people who are certain [in faith]."}, {"ayah": 5, "translit": "Wakhtilaafil laili wannahaari wa maaa anzalal laahu minas samaaa'i mir rizqin fa ahyaa bihil arda ba'da mawtihaa wa tasreefir riyaahi Aayaatul liqawminy ya'qiloon", "translation": "And [in] the alternation of night and day and [in] what Allah sends down from the sky of provision and gives life thereby to the earth after its lifelessness and [in His] directing of the winds are signs for a people who reason."}, {"ayah": 6, "translit": "Tilka Aayatul laahi natloohaa 'alika bilhaqq, fabiayyi hadeesim ba'dal laahi wa Aayaatihee yu'minoon", "translation": "These are the verses of Allah which We recite to you in truth. Then in what statement after Allah and His verses will they believe?"}, {"ayah": 7, "translit": "Wailul likulli affaakin aseem", "translation": "Woe to every sinful liar"}, {"ayah": 8, "translit": "Yasma'u Aayaatil laahi tutlaa 'alaihi summa yusirru mustakbiran ka-al lam yasma'haa fabashshirhu bi'azaabin aleem", "translation": "Who hears the verses of Allah recited to him, then persists arrogantly as if he had not heard them. So give him tidings of a painful punishment."}, {"ayah": 9, "translit": "Wa izaa 'alima min Aayaatinaa shai'anit takhazahaa huzuwaa; ulaaa'ika lahum 'azaabum muheen", "translation": "And when he knows anything of Our verses, he takes them in ridicule. Those will have a humiliating punishment."}, {"ayah": 10, "translit": "Minw waraaa'ihim Jahannamu wa laa yughnee 'anhum maa kasaboo shai'anw wa laa mat takhazoo min doonil laahi awliyaaa'a wa lahum 'azaabun 'azeem", "translation": "Before them is Hell, and what they had earned will not avail them at all nor what they had taken besides Allah as allies. And they will have a great punishment."}, {"ayah": 11, "translit": "Haazaa hudanw wal lazeena kafaroo bi aayaati Rabbihim lahum 'azaabum mir rijzin aleem", "translation": "This [Qur'an] is guidance. And those who have disbelieved in the verses of their Lord will have a painful punishment of foul nature."}, {"ayah": 12, "translit": "Allaahul lazee sahkhara lakumul bahra litajriyal fulku feehi bi amrihee wa litabtaghoo min fadlihee wa la'allakum tashkuroon", "translation": "It is Allah who subjected to you the sea so that ships may sail upon it by His command and that you may seek of His bounty; and perhaps you will be grateful."}, {"ayah": 13, "translit": "Wa sakhkhara lakum maa fis samaawaati wa maa fil ardi jamee'am minh; inna feezaalika la Aayaatil liqawminy yatafakkaroon", "translation": "And He has subjected to you whatever is in the heavens and whatever is on the earth - all from Him. Indeed in that are signs for a people who give thought."}, {"ayah": 14, "translit": "Qul lillazeena aamanoo yaghfiroo lillazeena laa yarjoona ayyaamal laahi liyajziya qawmam bimaa kaanoo yaksiboon", "translation": "Say, [O Muhammad], to those who have believed that they [should] forgive those who expect not the days of Allah so that He may recompense a people for what they used to earn."}, {"ayah": 15, "translit": "Maa 'amila saalihan falinafsihee wa man asaaa'a fa'alaihaa summa ilaa Rabbikum turja'oon", "translation": "Whoever does a good deed - it is for himself; and whoever does evil - it is against the self. Then to your Lord you will be returned."}, {"ayah": 16, "translit": "Wa laqad aatainaa Baneee Israaa'eelal Kitaaba walhukma wan Nubuwwata wa razaqnaahum minat taiyibaati wa faddalnaahum;alal 'aalameen", "translation": "And We did certainly give the Children of Israel the Scripture and judgement and prophethood, and We provided them with good things and preferred them over the worlds."}, {"ayah": 17, "translit": "Wa aatainaahum baiyinaatim minal amri famakh talafooo illaa mim ba'di maa jaaa'ahumul 'ilmu baghyam bainahum; inna Rabbaka yaqdee bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon", "translation": "And We gave them clear proofs of the matter [of religion]. And they did not differ except after knowledge had come to them - out of jealous animosity between themselves. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ."}, {"ayah": 18, "translit": "Summa ja'alnaaka 'alaa sharee'atim minal amri fattabi'haa wa laa tattabi'ahwaaa'al-lazeena laa ya'lamoon", "translation": "Then We put you, [O Muhammad], on an ordained way concerning the matter [of religion]; so follow it and do not follow the inclinations of those who do not know."}, {"ayah": 19, "translit": "Innahum lany yughnoo 'anka minal laahi shai'aa; wa innaz zaalimeena ba'duhum awliyaaa'u ba'dinw wallaahu waliyyul muttaqeen", "translation": "Indeed, they will never avail you against Allah at all. And indeed, the wrongdoers are allies of one another; but Allah is the protector of the righteous."}, {"ayah": 20, "translit": "Haazaa basaaa'iru linnaasi wa hudanw wa rahmatul liqawminy yooqinoon", "translation": "This [Qur'an] is enlightenment for mankind and guidance and mercy for a people who are certain [in faith]."}, {"ayah": 21, "translit": "Am hasibal lazeenaj tarahus saiyiaati an naj'alahum kallazeena aamanoo wa 'amilu saalihaati sawaaa'am mahyaahum wa mamaatuhum; saaa'a maa yahkumoon", "translation": "Or do those who commit evils think We will make them like those who have believed and done righteous deeds - [make them] equal in their life and their death? Evil is that which they judge."}, {"ayah": 22, "translit": "Wa khalaqal laahus samaawaati wal arda bilhaqqi wa litujzaa kullu nafsim bimaa kasabat wa hum laa yuzlamoon", "translation": "And Allah created the heavens and earth in truth and so that every soul may be recompensed for what it has earned, and they will not be wronged."}, {"ayah": 23, "translit": "Afara'ayta manit takhaza ilaahahoo hawaahu wa adal lahul laahu 'alaa 'ilminw wa khatama 'alaa sam'ihee wa qalbihee wa ja'ala 'alaa basarihee ghishaawatan famany yahdeehi mim ba'dil laah; afalaa tazakkaroon", "translation": "Have you seen he who has taken as his god his [own] desire, and Allah has sent him astray due to knowledge and has set a seal upon his hearing and his heart and put over his vision a veil? So who will guide him after Allah? Then will you not be reminded?"}, {"ayah": 24, "translit": "Wa qaaloo maa hiya illaa hayaatunad dunyaa namootu wa nahyaa wa maa yuhlikunaaa illad dahr; wa maa lahum bizaalika min 'ilmin in hum illaayazunnoon", "translation": "And they say, \"There is not but our worldly life; we die and live, and nothing destroys us except time.\" And they have of that no knowledge; they are only assuming."}, {"ayah": 25, "translit": "Wa izaa tutlaa 'alaihim aayaatuna baiyinaatim maa kaana hujjatahum illaaa an qaalu'too bi aabaaa'inaaa in kuntum saadiqeen", "translation": "And when Our verses are recited to them as clear evidences, their argument is only that they say, \"Bring [back] our forefathers, if you should be truthful.\""}, {"ayah": 26, "translit": "Qulil laahu yuhyeekum summa yumeetukum summa yajma'ukum ilaa Yawmil Qiyaamati laa raiba feehi wa laakinna aksaran naasi laa ya'lamoon", "translation": "Say, \"Allah causes you to live, then causes you to die; then He will assemble you for the Day of Resurrection, about which there is no doubt, but most of the people do not know.\""}, {"ayah": 27, "translit": "Wa lillaahi mulkus samaawaati wal ard; wa Yawma taqoomus Saa'atu Yawma 'iziny yakhsarul mubtiloon", "translation": "And to Allah belongs the dominion of the heavens and the earth. And the Day the Hour appears - that Day the falsifiers will lose."}, {"ayah": 28, "translit": "Wa taraa kulla ummatin jaasiyah; kullu ummatin tud'aaa ilaa kitaabihaa al Yawma tujzawna maa kuntum ta'maloon", "translation": "And you will see every nation kneeling [from fear]. Every nation will be called to its record [and told], \"Today you will be recompensed for what you used to do."}, {"ayah": 29, "translit": "Haazaa kitaabunaa yantiqu 'alaikum bilhaqq; innaa kunnaa nastansikhu maa kuntum ta'maloon", "translation": "This, Our record, speaks about you in truth. Indeed, We were having transcribed whatever you used to do.\""}, {"ayah": 30, "translit": "Fa ammal lazeena aamaanoo wa 'amilus saalihaati fayudkhiluhum Rabbuhum fee rahmatih; zaalika huwal fawzul mubeen", "translation": "So as for those who believed and did righteous deeds, their Lord will admit them into His mercy. That is what is the clear attainment."}, {"ayah": 31, "translit": "Wa ammal lazeena kafarooo afalam takun Aayaatee tutlaa 'alaikum fastakbartum wa kuntum qawmam mujrimeen", "translation": "But as for those who disbelieved, [it will be said], \"Were not Our verses recited to you, but you were arrogant and became a people of criminals?"}, {"ayah": 32, "translit": "Wa izaa qeela inna wa'dallaahi haqqunw was Saa'atu laa raiba feehaa qultum maa nadree mas Saa'atu in nazunnu illaa zannanw wa maa nahnu bimustaiqineen", "translation": "And when it was said, 'Indeed, the promise of Allah is truth and the Hour [is coming] - no doubt about it,' you said, 'We know not what is the Hour. We assume only assumption, and we are not convinced.' \""}, {"ayah": 33, "translit": "Wa badaa lahum saiyiaatu maa 'amiloo wa haaqa bihim maa kaanoo bihee yastahzi'oon", "translation": "And the evil consequences of what they did will appear to them, and they will be enveloped by what they used to ridicule."}, {"ayah": 34, "translit": "Wa qeelal yawma nansaakum kamaa naseetum liqaaa'a yawmikum haazaa wa maawaakumun Naaru wa maa lakum min naasireen", "translation": "And it will be said, \"Today We will forget you as you forgot the meeting of this Day of yours, and your refuge is the Fire, and for you there are no helpers."}, {"ayah": 35, "translit": "Zaalikum bi annakumut takhaztum aayaatil laahi huzuwanw wa gharratkumul hayaatud dunyaa; fal yawma laa yukhrajoona minhaa wa laahum yusta'taboon", "translation": "That is because you took the verses of Allah in ridicule, and worldly life deluded you.\" So that Day they will not be removed from it, nor will they be asked to appease [Allah]."}, {"ayah": 36, "translit": "Falillaahil hamdu Rabbis samaawaati wa Rabbil ardi Rabbil-'aalameen", "translation": "Then, to Allah belongs [all] praise - Lord of the heavens and Lord of the earth, Lord of the worlds."}, {"ayah": 37, "translit": "Wa lahul kibriyaaa'u fissamaawaati wal ardi wa Huwal 'Azeezul Hakeem", "translation": "And to Him belongs [all] grandeur within the heavens and the earth, and He is the Exalted in Might, the Wise."}]}, {"num": 46, "name": "Al-Ahqaf", "meaning": "The Wind-Curved Sandhills", "verses": [{"ayah": 1, "translit": "Haa-Meeeem", "translation": "Ha, Meem."}, {"ayah": 2, "translit": "Tanzeelul Kitaabi minal laahil-'Azeezil Hakeem", "translation": "The revelation of the Book is from Allah, the Exalted in Might, the Wise."}, {"ayah": 3, "translit": "Maa khalaqnas samaawaati wal arda wa maa bainahumaaa illaa bilhaqqi wa ajalim musammaa; wallazeena kafaroo 'ammaaa unziroo mu'ridoon", "translation": "We did not create the heavens and earth and what is between them except in truth and [for] a specified term. But those who disbelieve, from that of which they are warned, are turning away."}, {"ayah": 4, "translit": "Qul ara'aytum maa tad'oona min doonil laahi aroonee maazaa khalaqoo minal ardi am lahum shirkun fis samaawaati eetoonee bi kitaabim min qabli haazaaa aw asaaratim min 'ilmin in kuntum saadiqeen", "translation": "Say, [O Muhammad], \"Have you considered that which you invoke besides Allah? Show me what they have created of the earth; or did they have partnership in [creation of] the heavens? Bring me a scripture [revealed] before this or a [remaining] trace of knowledge, if you should be truthful.\""}, {"ayah": 5, "translit": "Wa man adallu mimmany yad'oo min doonil laahi mallaa yastajeebu lahooo ilaa Yawmil Qiyaamati wa hum'an du'aaa'ihim ghaafiloon", "translation": "And who is more astray than he who invokes besides Allah those who will not respond to him until the Day of Resurrection, and they, of their invocation, are unaware."}, {"ayah": 6, "translit": "Wa izaa hushiran naasu kaanoo lahum a'daaa'anw wa kaanoo bi'ibaadatihim kaafireen", "translation": "And when the people are gathered [that Day], they [who were invoked] will be enemies to them, and they will be deniers of their worship."}, {"ayah": 7, "translit": "Wa izaa tutlaa 'alaihim Aayaatunaa baiyinaatin qaalal lazeena kafaroo lilhaqqi lammaa jaaa'ahum haazaa sihrum mubeen", "translation": "And when Our verses are recited to them as clear evidences, those who disbelieve say of the truth when it has come to them, \"This is obvious magic.\""}, {"ayah": 8, "translit": "Am yaqooloonaf taraahu qul inif taraituhoo falaa tamlikoona lee minal laahi shai'an Huwa a'lamu bimaa tufeedoona feehi kafaa bihee shaheedam bainee wa bainakum wa Huwal Ghafoorur Raheem", "translation": "Or do they say, \"He has invented it?\" Say, \"If I have invented it, you will not possess for me [the power of protection] from Allah at all. He is most knowing of that in which you are involved. Sufficient is He as Witness between me and you, and He is the Forgiving the Merciful.\""}, {"ayah": 9, "translit": "Qul maa kuntu bid'am minal Rusuli wa maaa adreee ma yuf'alu bee wa laa bikum in attabi'u illaa maa yoohaaa ilaiya ya maaa ana illaa nazeerum mubeen", "translation": "Say, \"I am not something original among the messengers, nor do I know what will be done with me or with you. I only follow that which is revealed to me, and I am not but a clear warner.\""}, {"ayah": 10, "translit": "Qul ara'aytum in kaana min 'indil laahi wa kafartum bihee wa shahida shaahidum mim Banee Israaa'eela 'alaa mislihee fa aamana wastak bartum innal laaha laa yahdil qawmaz zaalimeen", "translation": "Say, \"Have you considered: if the Qur'an was from Allah, and you disbelieved in it while a witness from the Children of Israel has testified to something similar and believed while you were arrogant...?\" Indeed, Allah does not guide the wrongdoing people."}, {"ayah": 11, "translit": "Wa qaalal lazeena kafaroo lillazeena aamanoo law kaana khairam maa sabaqoonaaa ilyh; wa iz lam yahtadoo bihee fasa yaqooloona haazaaa ifkun qadeem", "translation": "And those who disbelieve say of those who believe, \"If it had [truly] been good, they would not have preceded us to it.\" And when they are not guided by it, they will say, \"This is an ancient falsehood.\""}, {"ayah": 12, "translit": "Wa min qablihee kitaabu Moosaaa imaamanw-wa rahmah; wa haazaa Kitaabum musad diqul lisaanan 'Arabiyyal liyunziral lazeena zalamoo wa bushraa lilmuhsineen", "translation": "And before it was the scripture of Moses to lead and as a mercy. And this is a confirming Book in an Arabic tongue to warn those who have wronged and as good tidings to the doers of good."}, {"ayah": 13, "translit": "Innal lazeena qaaloo Rabbunal laahu summas taqaamoo falaa khawfun 'alaihim wa laahum yahzanoon", "translation": "Indeed, those who have said, \"Our Lord is Allah,\" and then remained on a right course - there will be no fear concerning them, nor will they grieve."}, {"ayah": 14, "translit": "Ulaaa'ika Ashabul Jannati khaalideena feehaa jazaaa'am bimaa kaano ya'maloon", "translation": "Those are the companions of Paradise, abiding eternally therein as reward for what they used to do."}, {"ayah": 15, "translit": "Wa wassainal insaana biwaalidaihi ihsaanan hamalathu ummuhoo kurhanw-wa wada'athu kurhanw wa hamluhoo wa fisaaluhoo salaasoona shahraa; hattaaa izaa balagha ashuddahoo wa balagho arba'eena sanatan qaala Rabbi aqzi'neee an ashkura ni'matakal lateee an'amta 'alaiya wa 'alaa waalidaiya wa an a'mala saalihan tardaahu wa aslih lee fee zurriyyatee innee tubtu ilaika wa innee minal muslimeen", "translation": "And We have enjoined upon man, to his parents, good treatment. His mother carried him with hardship and gave birth to him with hardship, and his gestation and weaning [period] is thirty months. [He grows] until, when he reaches maturity and reaches [the age of] forty years, he says, \"My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to work righteousness of which You will approve and make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims.\""}, {"ayah": 16, "translit": "Ulaaa'ikal lazeena nata qabbalu 'anhum ahsana maa 'amiloo wa natajaawazu 'an saiyiaatihim feee Ashaabil jannati Wa'das sidqil lazee kaanoo yoo'adoon", "translation": "Those are the ones from whom We will accept the best of what they did and overlook their misdeeds, [their being] among the companions of Paradise. [That is] the promise of truth which they had been promised."}, {"ayah": 17, "translit": "Wallazee qaala liwaali daihi uffil lakumaaa ata'idanineee an ukhraja wa qad khalatil quroonu min qablee wa humaa yastagheesaanil laaha wailaka aamin inna wa'dal laahi haqq, fa yaqoolu maa haazaaa illaaa asaateerul awwaleen", "translation": "But one who says to his parents, \"Uff to you; do you promise me that I will be brought forth [from the earth] when generations before me have already passed on [into oblivion]?\" while they call to Allah for help [and to their son], \"Woe to you! Believe! Indeed, the promise of Allah is truth.\" But he says, \"This is not but legends of the former people\" -"}, {"ayah": 18, "translit": "Ulaaa'ikal lazeena haqqa 'alaihimul qawlu feee umamin qad khalat min qablihim minal jinni wal insi innahum kaanoo khaasireen", "translation": "Those are the ones upon whom the word has come into effect, [who will be] among nations which had passed on before them of jinn and men. Indeed, they [all] were losers."}, {"ayah": 19, "translit": "Wa likullin darajaatum mimmaa 'amiloo wa liyuwaf fiyahum a'maalahum wa hum laa yuzlamoon", "translation": "And for all there are degrees [of reward and punishment] for what they have done, and [it is] so that He may fully compensate them for their deeds, and they will not be wronged."}, {"ayah": 20, "translit": "Wa Yawma yu'radul lazeena kafaroo 'alan Naai azhabtum taiyibaatikum fee hayaatikumud dunyaa wastam ta'tum bihaa fal Yawma tujzawna 'azaabal hooni bimaa kuntum tastakbiroona fil ardi bighairil haqqi wa bimaa kuntum tafsuqoon", "translation": "And the Day those who disbelieved are exposed to the Fire [it will be said], \"You exhausted your pleasures during your worldly life and enjoyed them, so this Day you will be awarded the punishment of [extreme] humiliation because you were arrogant upon the earth without right and because you were defiantly disobedient.\""}, {"ayah": 21, "translit": "Wazkur akhaa 'Aad, iz anzara qawmahoo bil Ahqaafi wa qad khalatin nuzuru mim baini yadaihi wa min khalfiheee allaa ta'budooo illal laaha inneee akhaafu 'alaikum 'azaaba Yawmin 'azeem", "translation": "And mention, [O Muhammad], the brother of 'Aad, when he warned his people in the [region of] al-Ahqaf - and warners had already passed on before him and after him - [saying], \"Do not worship except Allah. Indeed, I fear for you the punishment of a terrible day.\""}, {"ayah": 22, "translit": "Qaaloo aji'tanaa litaa fikanaa 'an aalihatinaa faatinaa bimaa ta'idunaaa in kunta minas saadiqeen", "translation": "They said, \"Have you come to delude us away from our gods? Then bring us what you promise us, if you should be of the truthful.\""}, {"ayah": 23, "translit": "Qaala innamal 'ilmu indal laahi wa uballighukum maaa uriltu bihee wa laakinneee araakum qawman tajhaloon", "translation": "He said, \"Knowledge [of its time] is only with Allah, and I convey to you that with which I was sent; but I see you [to be] a people behaving ignorantly.\""}, {"ayah": 24, "translit": "Falammaa ra awhu 'aaridam mustaqbila awdiyatihim qaaloo haazaa 'aaridum mumtirunaa; bal huwa masta'jaltum bihee reehun feehaa 'azaabun aleem", "translation": "And when they saw it as a cloud approaching their valleys, they said, \"This is a cloud bringing us rain!\" Rather, it is that for which you were impatient: a wind, within it a painful punishment,"}, {"ayah": 25, "translit": "Tudammiru kulla shai'im bi-amri Rabbihaa fa asbahoo laa yuraaa illaa masaakinuhum; kazaalika najzil qawmal mujrimeen", "translation": "Destroying everything by command of its Lord. And they became so that nothing was seen [of them] except their dwellings. Thus do We recompense the criminal people."}, {"ayah": 26, "translit": "Wa laqad makkannaahum feemaaa im makkannaakum feehi waj'alnaa lahum sam'anw wa absaaranw wa af'idatan famaaa aghnaa 'anhum samu'uhum wa laaa absaaruhum wa laaa af'idatuhum min shai'in iz kaanoo yajhadoona bi Aayaatil laahi wa haaqa bihim maa kaanoo bihee yastahzi'oon", "translation": "And We had certainly established them in such as We have not established you, and We made for them hearing and vision and hearts. But their hearing and vision and hearts availed them not from anything [of the punishment] when they were [continually] rejecting the signs of Allah; and they were enveloped by what they used to ridicule."}, {"ayah": 27, "translit": "Wa laqad ahlaknaa ma hawlakum minal quraa wa sarrafnal Aayaati la'allahum yarji'oon", "translation": "And We have already destroyed what surrounds you of [those] cities, and We have diversified the signs [or verses] that perhaps they might return [from disbelief]."}, {"ayah": 28, "translit": "Falaw laa nasarahumul lazeenat takhazoo min doonil laahi qurbaanan aalihatam bal dalloo 'anhum' wa zaalika ifkuhum wa maa kaanoo yaftaroon", "translation": "Then why did those they took besides Allah as deities by which to approach [Him] not aid them? But they had strayed from them. And that was their falsehood and what they were inventing."}, {"ayah": 29, "translit": "Wa iz sarafinaaa ilaika nafaram minal jinni yastami'oonal Quraana falammaa hadaroohu qaalooo ansitoo falammaa qudiya wallaw ilaa qawmihim munzireen", "translation": "And [mention, O Muhammad], when We directed to you a few of the jinn, listening to the Qur'an. And when they attended it, they said, \"Listen quietly.\" And when it was concluded, they went back to their people as warners."}, {"ayah": 30, "translit": "Qaaloo yaa qawmanaaa innaa sami'naa Kitaaban unzila mim ba'di Moosa musaddiqal limaa baina yadihi yahdeee ilal haqqi wa ilaa Tareeqim Mustaqeem", "translation": "They said, \"O our people, indeed we have heard a [recited] Book revealed after Moses confirming what was before it which guides to the truth and to a straight path."}, {"ayah": 31, "translit": "Yaa qawmanaaa ajeeboo daa'iyal laahi wa aaminoo bihee yaghfir lakum min zunoobikum wa yujirkum min 'azaabin aleem", "translation": "O our people, respond to the Messenger of Allah and believe in him; Allah will forgive for you your sins and protect you from a painful punishment."}, {"ayah": 32, "translit": "Wa mal laa yujib daa'iyal laahi falaisa bimu'jizin fil ardi wa laisa lahoo min dooniheee awliyaaa'; ulaaa ika fee dalaalim mubeen", "translation": "But he who does not respond to the Caller of Allah will not cause failure [to Him] upon earth, and he will not have besides Him any protectors. Those are in manifest error.\""}, {"ayah": 33, "translit": "Awalam yaraw annal laahal lazee khalaqas samaawaati wal larda wa lam ya'ya bikhal qihinna biqaadirin 'alaaa aiyuhyiyal mawtaa; balaaa innahoo 'alaa kulli shai'in Qadeer", "translation": "Do they not see that Allah, who created the heavens and earth and did not fail in their creation, is able to give life to the dead? Yes. Indeed, He is over all things competent."}, {"ayah": 34, "translit": "Wa Yawma yu'radul lazeena kafaroo 'alan naari alaisa haaza bil haqq; qaaloo balaa wa Rabbinaa; qaala fazooqul 'azaaba bimaa kuntum takfuroon", "translation": "And the Day those who disbelieved are exposed to the Fire [it will be said], \"Is this not the truth?\" They will say, \"Yes, by our Lord.\" He will say, \"Then taste the punishment because you used to disbelieve.\""}, {"ayah": 35, "translit": "Fasbir kamaa sabara ulul 'azmi minar Rusuli wa laa tasta'jil lahum; ka annahum Yawma yarawna maa yoo'adoona lam yalbasooo illaa saa'atam min nahaar; balaagh; fahal yuhlaku illal qawmul faasiqoon", "translation": "So be patient, [O Muhammad], as were those of determination among the messengers and do not be impatient for them. It will be - on the Day they see that which they are promised - as though they had not remained [in the world] except an hour of a day. [This is] notification. And will [any] be destroyed except the defiantly disobedient people?"}]}, {"num": 47, "name": "Muhammad", "meaning": "Muhammad", "verses": [{"ayah": 1, "translit": "Allazeena kafaroo wa saddoo'an sabeelil laahi adalla a'maalahum", "translation": "Those who disbelieve and avert [people] from the way of Allah - He will waste their deeds."}, {"ayah": 2, "translit": "Wallazeena aamanoo wa 'amilus saalihaati wa aamanoo bimaa nuzzila 'alaa Muhammadinw-wa huwal haqqu mir Rabbihim kaffara 'anhum saiyiaatihim wa aslaha baalahum", "translation": "And those who believe and do righteous deeds and believe in what has been sent down upon Muhammad - and it is the truth from their Lord - He will remove from them their misdeeds and amend their condition."}, {"ayah": 3, "translit": "Zaalika bi annal lazeena kafarut taba'ul baatila wa annal lazeena aamanut taba'ul haqqa mir Rabbihim; kazaalika yadribul laahu linnaasi amsaalahum", "translation": "That is because those who disbelieve follow falsehood, and those who believe follow the truth from their Lord. Thus does Allah present to the people their comparisons."}, {"ayah": 4, "translit": "Fa-izaa laqeetumul lazeena kafaroo fadarbar riqaab, hattaaa izaa askhan tumoohum fashuddul wasaaq, fa immaa mannnam ba'du wa immaa fidaaa'an hattaa tada'al harbu awzaarahaa; zaalika wa law yashaaa'ul laahu lantasara minhum wa laakil laiyabluwa ba'dakum biba'd; wallazeena qutiloo fee sabeelil laahi falany yudilla a'maalahum", "translation": "So when you meet those who disbelieve [in battle], strike [their] necks until, when you have inflicted slaughter upon them, then secure their bonds, and either [confer] favor afterwards or ransom [them] until the war lays down its burdens. That [is the command]. And if Allah had willed, He could have taken vengeance upon them [Himself], but [He ordered armed struggle] to test some of you by means of others. And those who are killed in the cause of Allah - never will He waste their deeds."}, {"ayah": 5, "translit": "Sa-yahdeehim wa yusihu baalahum", "translation": "He will guide them and amend their condition"}, {"ayah": 6, "translit": "Wa yudkhiluhumul jannata 'arrafahaa lahum", "translation": "And admit them to Paradise, which He has made known to them."}, {"ayah": 7, "translit": "Yaaa ayyuhal lazeena aamanooo in tansurul laaha yansurkum wa yusabbit aqdaamakum", "translation": "O you who have believed, if you support Allah, He will support you and plant firmly your feet."}, {"ayah": 8, "translit": "Wallazeena kafaroo fata's al lahum wa adalla a'maalahum", "translation": "But those who disbelieve - for them is misery, and He will waste their deeds."}, {"ayah": 9, "translit": "Zaalika bi annahum karihoo maaa anzalal laahu faahbata a'maalahum", "translation": "That is because they disliked what Allah revealed, so He rendered worthless their deeds."}, {"ayah": 10, "translit": "Afalam yaseeroo fil ardi fayanzuroo kaifa kaana 'aaqibatul lazeena min qablihim;  dammaral laahu 'alaihim wa lilkaafireena amsaaluhaa", "translation": "Have they not traveled through the land and seen how was the end of those before them? Allah destroyed [everything] over them, and for the disbelievers is something comparable."}, {"ayah": 11, "translit": "Zaalika bi annal laaha mawlal lazeena aamanoo wa annal kaafireena laa mawlaa lahum", "translation": "That is because Allah is the protector of those who have believed and because the disbelievers have no protector."}, {"ayah": 12, "translit": "Innal-laaha yudkhilul lazeena aamanoo wa 'amilus saalihaati Jannaatin tajree min tahtihal anhaaru wallazeena kafaroo yatamatta'oona wa yaakuloona kamaa taakuluian'aamu wan Naaru maswallahum", "translation": "Indeed, Allah will admit those who have believed and done righteous deeds to gardens beneath which rivers flow, but those who disbelieve enjoy themselves and eat as grazing livestock eat, and the Fire will be a residence for them."}, {"ayah": 13, "translit": "Wa ka ayyim min qaryatin hiya ashaddu quwwatam min qaryatikal lateee akhrajatka ahlaknaahum falaa naasira lahum", "translation": "And how many a city was stronger than your city [Makkah] which drove you out? We destroyed them; and there was no helper for them."}, {"ayah": 14, "translit": "Afaman kaana 'alaa baiyinatim mir Rabbihee kaman zuyyina lahoo sooo'u 'amalihee wattaba'ooo ahwaaa'ahum", "translation": "So is he who is on clear evidence from his Lord like him to whom the evil of his work has been made attractive and they follow their [own] desires?"}, {"ayah": 15, "translit": "Masalul jannatil latee wu'idal muttaqoona feehaaa anhaarum mim maaa'in ghayri aasininw wa anhaarum mil labanil lam yataghaiyar ta'muhoo wa anhaarum min khamril lazzatil lishshaaribeena wa anhaarum min 'asalim musaffanw wa lahum feeha min kullis samaraati wa maghfiratum mir Rabbihim kaman huwa khaalidun fin naari wa suqoo maaa'an hameeman faqatta'a am'aaa'ahum", "translation": "Is the description of Paradise, which the righteous are promised, wherein are rivers of water unaltered, rivers of milk the taste of which never changes, rivers of wine delicious to those who drink, and rivers of purified honey, in which they will have from all [kinds of] fruits and forgiveness from their Lord, like [that of] those who abide eternally in the Fire and are given to drink scalding water that will sever their intestines?"}, {"ayah": 16, "translit": "Wa minhum mai yastami' ilaika hattaaa izaa kharajoo min 'indika qaaloo lillazeena ootul 'ilma maazaa qaala aanifaa; ulaaa'ikal lazeena taba'al laahu 'alaa quloobihim wattaba'ooo ahwaaa'ahum", "translation": "And among them, [O Muhammad], are those who listen to you, until when they depart from you, they say to those who were given knowledge, \"What has he said just now?\" Those are the ones of whom Allah has sealed over their hearts and who have followed their [own] desires."}, {"ayah": 17, "translit": "Wallazeenah tadaw zaadahum hudanw wa aataahum taqwaahum", "translation": "And those who are guided - He increases them in guidance and gives them their righteousness."}, {"ayah": 18, "translit": "Fahal yanzuroona illas Saa'ata an taatiyahum baghtatan faqad jaaa'a ashraatuhaa; fa-annnaa lahum izaa jaaa'at hum zikraahum", "translation": "Then do they await except that the Hour should come upon them unexpectedly? But already there have come [some of] its indications. Then what good to them, when it has come, will be their remembrance?"}, {"ayah": 19, "translit": "Fa'lam annahoo laaa ilaaha illal laahu wastaghfir lizambika wa lilmu'mineena walmu'minaat; wallaahu ya'lamu mutaqallabakum wa maswaakum", "translation": "So know, [O Muhammad], that there is no deity except Allah and ask forgiveness for your sin and for the believing men and believing women. And Allah knows of your movement and your resting place."}, {"ayah": 20, "translit": "Wa yaqoolul lazeena aamanoo law laa nuzzilat Sooratun fa izaaa unzilat Sooratum Muhkamatunw wa zukira feehal qitaalu ra aytal lazeena fee quloobihim maraduny yanzuroona ilaika nazaral maghshiyyi 'alaihi minal mawti fa'awlaa lahum", "translation": "Those who believe say, \"Why has a surah not been sent down? But when a precise surah is revealed and fighting is mentioned therein, you see those in whose hearts is hypocrisy looking at you with a look of one overcome by death. And more appropriate for them [would have been]"}, {"ayah": 21, "translit": "Taa'atunw wa qawlum ma'roof; fa izaa 'azamal amru falaw sadaqul laaha lakaana khairal lahum", "translation": "Obedience and good words. And when the matter [of fighting] was determined, if they had been true to Allah, it would have been better for them."}, {"ayah": 22, "translit": "Fahal 'asaitum in tawallaitum an tufsidoo fil ardi wa tuqatti'ooo arhaamakum", "translation": "So would you perhaps, if you turned away, cause corruption on earth and sever your [ties of] relationship?"}, {"ayah": 23, "translit": "Ulaaa'ikal lazeena la'anahumul laahu fa asammahum wa a'maaa absaarahum", "translation": "Those [who do so] are the ones that Allah has cursed, so He deafened them and blinded their vision."}, {"ayah": 24, "translit": "Afalaa yatadabbaroonal Qur-aana am 'alaa quloobin aqfaaluhaa", "translation": "Then do they not reflect upon the Qur'an, or are there locks upon [their] hearts?"}, {"ayah": 25, "translit": "Innal lazeenar taddoo 'alaaa adbaarihim mim ba'di maa tabaiyana lahumul hudash Shaitaanu sawwala lahum wa amlaa lahum", "translation": "Indeed, those who reverted back [to disbelief] after guidance had become clear to them - Satan enticed them and prolonged hope for them."}, {"ayah": 26, "translit": "Zaalika bi annahum qaaloo lillazeena karihoo maa nazzalal laahu sanutee'ukum fee ba'dil amri wallaahu ya'lamu israarahum", "translation": "That is because they said to those who disliked what Allah sent down, \"We will obey you in part of the matter.\" And Allah knows what they conceal."}, {"ayah": 27, "translit": "Fakaifa izaa tawaffat humul malaaa'ikatu yadriboona wujoohahum wa adbaa rahum", "translation": "Then how [will it be] when the angels take them in death, striking their faces and their backs?"}, {"ayah": 28, "translit": "Zaalika bi annahumut taba'oo maaa askhatal laaha wa karihoo ridwaanahoo fa ahbata a'maalahum (section 3)", "translation": "That is because they followed what angered Allah and disliked [what earns] His pleasure, so He rendered worthless their deeds."}, {"ayah": 29, "translit": "Am hasibal lazeena fee quloobihim maradun al lan yukhrijal laahu adghaanahum", "translation": "Or do those in whose hearts is disease think that Allah would never expose their [feelings of] hatred?"}, {"ayah": 30, "translit": "Wa law nashaaa'u la-arainaakahum fala 'araftahum bi seemaahum; wa lata'rifan nahum fee lahnil qawl; wallaahu ya'lamu a'maalakum", "translation": "And if We willed, We could show them to you, and you would know them by their mark; but you will surely know them by the tone of [their] speech. And Allah knows your deeds."}, {"ayah": 31, "translit": "Wa lanabluwannakum hattaa na'lamal mujaahideena minkum wassaabireena wa nabluwa akhbaarakum", "translation": "And We will surely test you until We make evident those who strive among you [for the cause of Allah] and the patient, and We will test your affairs."}, {"ayah": 32, "translit": "Innnal lazeena kafaroo wa saddoo 'an sabeelil laahi wa shaaaqqur Rasoola mim ba'di maa tabaiyana lahumul hudaa lany yadurrul laaha shai'anw wa sa yuhbitu a'maalahum", "translation": "Indeed, those who disbelieved and averted [people] from the path of Allah and opposed the Messenger after guidance had become clear to them - never will they harm Allah at all, and He will render worthless their deeds."}, {"ayah": 33, "translit": "Yaaa ayyuhal lazeena aamanoo atee'ul laaha wa atee'ur Rasoola wa laa tubtilooo a'maalakum", "translation": "O you who have believed, obey Allah and obey the Messenger and do not invalidate your deeds."}, {"ayah": 34, "translit": "Innal lazeena kafaroo wa saddoo 'an sabeelil laahi summa maatoo wa hum kuffaarun falany yaghfirallaahu lahum", "translation": "Indeed, those who disbelieved and averted [people] from the path of Allah and then died while they were disbelievers - never will Allah forgive them."}, {"ayah": 35, "translit": "Falaa tahinoo wa tad'ooo ilas salmi wa antumul a'lawna wallaahu ma'akum wa lany yatirakum a'maalakum", "translation": "So do not weaken and call for peace while you are superior; and Allah is with you and will never deprive you of [the reward of] your deeds."}, {"ayah": 36, "translit": "Innamal hayaatud dunyaa la'ibunw wa lahw; wa in to'minoo wa tattaqoo yu'tikum ujoorakum wa laa yas'alkum amwaalakum", "translation": "[This] worldly life is only amusement and diversion. And if you believe and fear Allah, He will give you your rewards and not ask you for your properties."}, {"ayah": 37, "translit": "Iny yas'alkumoohaa fa yuhfikum tabkhaloo wa yukhrij adghaanakum", "translation": "If He should ask you for them and press you, you would withhold, and He would expose your unwillingness."}, {"ayah": 38, "translit": "haaa antum haaa'ulaaa'i tud'awna litunfiqoo fee sabeelillaahi faminkum many yabkhalu wa many yabkhal fa innamaa yabkhalu 'an nafsih; wallaahu Ghaniyyu wa antumul fuqaraaa'; wa in tatwal law yastabdil qawman ghairakum summa laa yakoonooo amsaalakum", "translation": "Here you are - those invited to spend in the cause of Allah - but among you are those who withhold [out of greed]. And whoever withholds only withholds [benefit] from himself; and Allah is the Free of need, while you are the needy. And if you turn away, He will replace you with another people; then they will not be the likes of you."}]}, {"num": 48, "name": "Al-Fath", "meaning": "The Victory", "verses": [{"ayah": 1, "translit": "Innaa fatahnaa laka Fatham Mubeenaa", "translation": "Indeed, We have given you, [O Muhammad], a clear conquest"}, {"ayah": 2, "translit": "Liyaghfira lakal laahu maa taqaddama min zambika wa maa ta akhkhara wa yutimma ni'matahoo 'alaika wa yahdiyaka siraatam mustaqeema", "translation": "That Allah may forgive for you what preceded of your sin and what will follow and complete His favor upon you and guide you to a straight path"}, {"ayah": 3, "translit": "Wa yansurakal laahu nasran 'azeezaa", "translation": "And [that] Allah may aid you with a mighty victory."}, {"ayah": 4, "translit": "Huwal lazeee anzalas sakeenata fee quloobil mu'mineena liyazdaadooo eemaanamma'a eemaanihim; wa lillaahi junoodus samawaati wal ard; wa kaanal laahu 'Aleeman Hakeemaa", "translation": "It is He who sent down tranquillity into the hearts of the believers that they would increase in faith along with their [present] faith. And to Allah belong the soldiers of the heavens and the earth, and ever is Allah Knowing and Wise."}, {"ayah": 5, "translit": "Liyudkhilal mu'mineena walmu'minaati jannaatin tajree min tahtihal anhaaru khaalideena feehaa wa yukaffira 'anhum saiyi aatihim; wa kaana zaalika 'indal laahi fawzan 'azeemaa", "translation": "[And] that He may admit the believing men and the believing women to gardens beneath which rivers flow to abide therein eternally and remove from them their misdeeds - and ever is that, in the sight of Allah, a great attainment -"}, {"ayah": 6, "translit": "Wa yu'azzibal munaafiqeena walmunaafiqaati wal mushrikeena walmushrikaatiz zaaanneena billaahi zannas saw'; 'alaihim daaa'iratus saw'i wa ghadibal laahu 'alaihim wa la'anahum wa a'adda lahum jahannama wa saaa' at maseeraa", "translation": "And [that] He may punish the hypocrite men and hypocrite women, and the polytheist men and polytheist women - those who assume about Allah an assumption of evil nature. Upon them is a misfortune of evil nature; and Allah has become angry with them and has cursed them and prepared for them Hell, and evil it is as a destination."}, {"ayah": 7, "translit": "Wa lillaahi junoodus samaawaati wal ard; wa kaanal laahu 'azeezan hakeema", "translation": "And to Allah belong the soldiers of the heavens and the earth. And ever is Allah Exalted in Might and Wise."}, {"ayah": 8, "translit": "Innaaa arsalnaaka shaahi danw wa mubashshiranw wa nazeera", "translation": "Indeed, We have sent you as a witness and a bringer of good tidings and a warner"}, {"ayah": 9, "translit": "Litu minoo billaahi wa Rasoolihee wa tu'azziroohu watuwaqqiroohu watusabbi hoohu bukratanw wa aseelaa", "translation": "That you [people] may believe in Allah and His Messenger and honor him and respect the Prophet and exalt Allah morning and afternoon."}, {"ayah": 10, "translit": "Innal lazeena yubaayi'oonaka innamaa yubaayi'oonal laaha yadul laahi fawqa aydehim; faman nakasa fainnamaa yuankusu 'alaa nafsihee wa man awfaa bimaa 'aahada 'alihul laaha fasa yu'teehi ajran 'azeemaa", "translation": "Indeed, those who pledge allegiance to you, [O Muhammad] - they are actually pledging allegiance to Allah. The hand of Allah is over their hands. So he who breaks his word only breaks it to the detriment of himself. And he who fulfills that which he has promised Allah - He will give him a great reward."}, {"ayah": 11, "translit": "Sa yaqoolu lakal mukhal lafoona minal-A'raabi shaighalatnaaa amwaalunaa wa ahloonaa fastaghfir lanaa; yaqooloona bi alsinatihim maa laisa fee quloobihim; qul famany yamliku lakum minal laahi shai'an in araada bikum darran aw araada bikum naf'aa; bal kaanal laahu bimaa ta'maloona Khabeeraa", "translation": "Those who remained behind of the bedouins will say to you, \"Our properties and our families occupied us, so ask forgiveness for us.\" They say with their tongues what is not within their hearts. Say, \"Then who could prevent Allah at all if He intended for you harm or intended for you benefit? Rather, ever is Allah, with what you do, Acquainted."}, {"ayah": 12, "translit": "Bal zanantum al lany yanqalibar Rasoolu walmu'minoona ilaaa ahleehim abadanw wa zuyyina zaalika fee quloobikum wa zanantum zannnas saw'i wa kuntum qawmam booraa", "translation": "But you thought that the Messenger and the believers would never return to their families, ever, and that was made pleasing in your hearts. And you assumed an assumption of evil and became a people ruined.\""}, {"ayah": 13, "translit": "Wa mal lam yu'mim billaahi wa Rasoolihee fainnaaa a'tadnaa lilkaafireena sa'eeraa", "translation": "And whoever has not believed in Allah and His Messenger - then indeed, We have prepared for the disbelievers a Blaze."}, {"ayah": 14, "translit": "Wa lillaahii mulkus samaawaati wal ard; yaghfiru limany yashaaa'u wa yu'azzibu many yashaaa'; wa kaanal laahu Ghafoorar Raheemaa", "translation": "And to Allah belongs the dominion of the heavens and the earth. He forgives whom He wills and punishes whom He wills. And ever is Allah Forgiving and Merciful."}, {"ayah": 15, "translit": "Sa yaqoolul mukhalla foona izan talaqtum ilaa maghaanima litaakhuzoohaa zaroonaa nattabi'kum yureedoona any yubaddiloo Kalaamallaah; qul lan tattabi'oonaa kazaalikum qaalal laahu min qablu fasa yaqooloona bal tahsudoonanna; bal kaanoo laa yafqahoona illaa qaleela", "translation": "Those who remained behind will say when you set out toward the war booty to take it, \"Let us follow you.\" They wish to change the words of Allah. Say, \"Never will you follow us. Thus did Allah say before.\" So they will say, \"Rather, you envy us.\" But [in fact] they were not understanding except a little."}, {"ayah": 16, "translit": "Qul lilmukhallafeena minal A'raabi satud'awna ilaa qawmin ulee baasin shadeedin tuqaati loonahum aw yuslimoona fa in tutee'oo yu'tikumul laahu ajran hasananw wa in tatawallaw kamaa tawallaitum min qablu yu'azzibkum 'azaaban aleemaa", "translation": "Say to those who remained behind of the bedouins, \"You will be called to [face] a people of great military might; you may fight them, or they will submit. So if you obey, Allah will give you a good reward; but if you turn away as you turned away before, He will punish you with a painful punishment.\""}, {"ayah": 17, "translit": "Laisa 'alal a'maa harajunw wa laa 'alal a'raji harajunw wa laa 'alal mareedi haraj' wa many yutil'il laaha wa Rasoolahoo yudkhilhu jannaatin tajree min tahtihal anhaaru wa many yatawalla yu'azzibhu 'azaaban aleemaa", "translation": "There is not upon the blind any guilt or upon the lame any guilt or upon the ill any guilt [for remaining behind]. And whoever obeys Allah and His Messenger - He will admit him to gardens beneath which rivers flow; but whoever turns away - He will punish him with a painful punishment."}, {"ayah": 18, "translit": "Laqad radiyal laahu 'anil mu'mineena iz yubaayi 'oonaka tahtash shajarati fa'alima maa fee quloobihim fa anzalas sakeenata 'alaihim wa asaa bahum fat han qareebaa", "translation": "Certainly was Allah pleased with the believers when they pledged allegiance to you, [O Muhammad], under the tree, and He knew what was in their hearts, so He sent down tranquillity upon them and rewarded them with an imminent conquest"}, {"ayah": 19, "translit": "Wa maghaanima kaseera tany yaakhuzoonahaa; wa kaanal laahu 'Azeezan Hakeemaa", "translation": "And much war booty which they will take. And ever is Allah Exalted in Might and Wise."}, {"ayah": 20, "translit": "Wa'adakumul laahu ma ghaanima kaseeratan taakhuzoo nahaa fa'ajjala lakum haazihee wa kaffa aydiyan naasi 'ankum wa litakoona aayatal lilmu'mineena wa yahdiyakum siraatam mustaqeema", "translation": "Allah has promised you much booty that you will take [in the future] and has hastened for you this [victory] and withheld the hands of people from you - that it may be a sign for the believers and [that] He may guide you to a straight path."}, {"ayah": 21, "translit": "Wa ukhraa lam taqdiroo 'alaihaa qad ahaatal laahu bihaa; wa kaanal laahu 'alaa kulli shai'in qadeera", "translation": "And [He promises] other [victories] that you were [so far] unable to [realize] which Allah has already encompassed. And ever is Allah, over all things, competent."}, {"ayah": 22, "translit": "Wa law qaatalakumul lazeena kafaroo la wallawul adbaara summa laa yajidoona waliyanw-wa laa naseeraa", "translation": "And if those [Makkans] who disbelieve had fought you, they would have turned their backs [in flight]. Then they would not find a protector or a helper."}, {"ayah": 23, "translit": "Sunnatal laahil latee qad khalat min qablu wa lan tajida lisunnatil laahi tabdeelaa", "translation": "[This is] the established way of Allah which has occurred before. And never will you find in the way of Allah any change."}, {"ayah": 24, "translit": "Wa Huwal lazee kaffa aydiyahum 'ankum wa aydiyakum 'anhum bibatni Makkata mim ba'di an azfarakum 'alaihim; wa kaanal laahu bimaa ta'maloona Baseera", "translation": "And it is He who withheld their hands from you and your hands from them within [the area of] Makkah after He caused you to overcome them. And ever is Allah of what you do, Seeing."}, {"ayah": 25, "translit": "Humul lazeena kafaroo wa saddookum 'anil-Masjidil-Haraami walhadya ma'koofan any yablugha mahillah; wa law laa rijaalum mu'minoona wa nisaaa'um mu'minaatul lam ta'lamoohum an tata'oohum fatuseebakum minhum ma'arratum bighairi 'ilmin liyud khilal laahu fee rahmatihee many yashaaa'; law tazayyaloo la'azzabnal lazeena kafaroo minhum 'azaaban aleema", "translation": "They are the ones who disbelieved and obstructed you from al-Masjid al-Haram while the offering was prevented from reaching its place of sacrifice. And if not for believing men and believing women whom you did not know - that you might trample them and there would befall you because of them dishonor without [your] knowledge - [you would have been permitted to enter Makkah]. [This was so] that Allah might admit to His mercy whom He willed. If they had been apart [from them], We would have punished those who disbelieved among them with painful punishment"}, {"ayah": 26, "translit": "Iz ja'alal lazeena kafaroo fee quloobihimul hamiyyata hamiyyatal jaahiliyyati fa anzalal laahu sakeenatahoo 'alaa Rasoolihee wa 'alal mu mineena wa alzamahum kalimatat taqwaa wa kaanooo ahaqqa bihaa wa ahlahaa; wa kaanal laahu bikulli shai'in Aleema", "translation": "When those who disbelieved had put into their hearts chauvinism - the chauvinism of the time of ignorance. But Allah sent down His tranquillity upon His Messenger and upon the believers and imposed upon them the word of righteousness, and they were more deserving of it and worthy of it. And ever is Allah, of all things, Knowing."}, {"ayah": 27, "translit": "Laqad sadaqal laahu Rasoolahur ru'yaa bilhaqq, latadkhulunnal Masjidal-Haraama in shaaa'al laahu aamineena muhalliqeena ru'oosakum wa muqassireena laa takhaafoona fa'alima maa lam ta'lamoo faja'ala min dooni zaalika fathan qareebaa", "translation": "Certainly has Allah showed to His Messenger the vision in truth. You will surely enter al-Masjid al-Haram, if Allah wills, in safety, with your heads shaved and [hair] shortened, not fearing [anyone]. He knew what you did not know and has arranged before that a conquest near [at hand]."}, {"ayah": 28, "translit": "Huwal lazeee arsala Rasoolahoo bilhudaa wa deenil haqqi liyuzhirahoo 'alad deeni kullih; wa kafaa billaahi Shaheeda", "translation": "It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion. And sufficient is Allah as Witness."}, {"ayah": 29, "translit": "Muhammadur Rasoolul laah; wallazeena ma'ahooo ashiddaaa'u 'alal kuffaaari ruhamaaa'u bainahum taraahum rukka'an sujjadany yabtaghoona fadlam minal laahi wa ridwaanan seemaahum fee wujoohihim min asaris sujood; zaalika masaluhum fit tawraah; wa masaluhum fil Injeeli kazar'in akhraja shat 'ahoo fa 'aazarahoo fastaghlaza fastawaa 'alaa sooqihee yu'jibuz zurraa'a liyagheeza bihimul kuffaar; wa'adal laahul lazeena aamanoo wa 'amilus saalihaati minhum maghfiratanw wa ajran 'azeemaa", "translation": "Muhammad is the Messenger of Allah; and those with him are forceful against the disbelievers, merciful among themselves. You see them bowing and prostrating [in prayer], seeking bounty from Allah and [His] pleasure. Their mark is on their faces from the trace of prostration. That is their description in the Torah. And their description in the Gospel is as a plant which produces its offshoots and strengthens them so they grow firm and stand upon their stalks, delighting the sowers - so that Allah may enrage by them the disbelievers. Allah has promised those who believe and do righteous deeds among them forgiveness and a great reward."}]}, {"num": 49, "name": "Al-Hujurat", "meaning": "The Rooms", "verses": [{"ayah": 1, "translit": "Yaa ayyuhal lazeena aamanoo la tuqaddimoo baina yada yil laahi wa Rasoolihee wattaqul laah; innal laaha samee'un 'Aleem", "translation": "O you who have believed, do not put [yourselves] before Allah and His Messenger but fear Allah. Indeed, Allah is Hearing and Knowing."}, {"ayah": 2, "translit": "Yaa ayyuhal lazeena aamanoo laa tarfa'ooo aswaatakum fawqa sawtin Nabiyi wa laa tajharoo lahoo bilqawli kajahri ba'dikum liba 'din an tahbata a 'maalukum wa antum laa tash'uroon", "translation": "O you who have believed, do not raise your voices above the voice of the Prophet or be loud to him in speech like the loudness of some of you to others, lest your deeds become worthless while you perceive not."}, {"ayah": 3, "translit": "Innal lazeena yaghud doona aswaatahum 'inda Rasoolil laahi ulaaa'ikal lazeenam tah anal laahu quloobahum littaqwaa; lahum maghfiratunw waajrun 'azeem", "translation": "Indeed, those who lower their voices before the Messenger of Allah - they are the ones whose hearts Allah has tested for righteousness. For them is forgiveness and great reward."}, {"ayah": 4, "translit": "Innal lazeena yunaadoo naka minw waraaa'il hujuraati aksaruhum laa ya'qiloon", "translation": "Indeed, those who call you, [O Muhammad], from behind the chambers - most of them do not use reason."}, {"ayah": 5, "translit": "Wa law annahum sabaroo hatta takhruja ilaihim lakaana khairal lahum; wallaahu Ghafoorur Raheem", "translation": "And if they had been patient until you [could] come out to them, it would have been better for them. But Allah is Forgiving and Merciful."}, {"ayah": 6, "translit": "Yaaa ayyuhal lazeena aamanoo in jaaa'akum faasqum binaba in fatabaiyanooo an tuseeboo qawmam bijahalatin fatusbihoo 'alaa maa fa'altum naadimeen", "translation": "O you who have believed, if there comes to you a disobedient one with information, investigate, lest you harm a people out of ignorance and become, over what you have done, regretful."}, {"ayah": 7, "translit": "Wa'lamooo anna feekum Rasoolal laah; law yutee'ukum fee kaseerim minal amrila'anittum wa laakinnal laaha habbaba ilaikumul eemaana wa zaiyanahoo fee quloobikum wa karraha ilaikumul kufra walfusooqa wal'isyaan; ulaaaika humur raashidoon", "translation": "And know that among you is the Messenger of Allah. If he were to obey you in much of the matter, you would be in difficulty, but Allah has endeared to you the faith and has made it pleasing in your hearts and has made hateful to you disbelief, defiance and disobedience. Those are the [rightly] guided."}, {"ayah": 8, "translit": "Fadlam minal laahi wa ni'mah; wallaahu 'Aleemun Hakeem", "translation": "[It is] as bounty from Allah and favor. And Allah is Knowing and Wise."}, {"ayah": 9, "translit": "Wa in taaa'ifataani minal mu'mineenaq tataloo faaslihoo bainahumaa fa-im baghat ih daahumaa 'alal ukhraa faqaatilul latee tabhee hattaa tafeee'a ilaaa amril laah; fa-in faaa't fa aslihoo bainahumaa bil'adli wa aqsitoo innal laaha yuhibbul muqsiteen", "translation": "And if two factions among the believers should fight, then make settlement between the two. But if one of them oppresses the other, then fight against the one that oppresses until it returns to the ordinance of Allah. And if it returns, then make settlement between them in justice and act justly. Indeed, Allah loves those who act justly."}, {"ayah": 10, "translit": "Innamal mu'minoona ikhwatun fa aslihoo baina akhawaykum wattaqul laaha la'allakum tuhamoon", "translation": "The believers are but brothers, so make settlement between your brothers. And fear Allah that you may receive mercy."}, {"ayah": 11, "translit": "Yaaa ayyuhal lazeena aamanoo laa yaskhar qawmum min qawmin 'asaaa anyyakoonoo khairam minhum wa laa nisaaa'um min nisaaa'in 'Asaaa ay yakunna khairam minhunna wa laa talmizooo bil alqaab; bi'sal ismul fusooqu ba'dal eemaan; wa mal-lam yatub fa-ulaaa'ika humuz zaalimoon", "translation": "O you who have believed, let not a people ridicule [another] people; perhaps they may be better than them; nor let women ridicule [other] women; perhaps they may be better than them. And do not insult one another and do not call each other by [offensive] nicknames. Wretched is the name of disobedience after [one's] faith. And whoever does not repent - then it is those who are the wrongdoers."}, {"ayah": 12, "translit": "Yaaa ayyuhal lazeena aamanuj taniboo kaseeram minaz zanni inna ba'daz zanniismunw wa laa tajassasoo wa la yaghtab ba'dukum ba'daa; a yuhibbu ahadukum any yaakula lahma akheehi maitan fakarih tumooh; wattaqul laa; innal laaha tawwaabur Raheem", "translation": "O you who have believed, avoid much [negative] assumption. Indeed, some assumption is sin. And do not spy or backbite each other. Would one of you like to eat the flesh of his brother when dead? You would detest it. And fear Allah; indeed, Allah is Accepting of repentance and Merciful."}, {"ayah": 13, "translit": "Yaaa ayyuhan naasu innaa khalaqnaakum min zakarinw wa unsaa wa ja'alnaakum shu'oobanw wa qabaaa'ila lita'aarafoo inna akramakum 'indal laahi atqaakum innal laaha 'Aleemun khabeer", "translation": "O mankind, indeed We have created you from male and female and made you peoples and tribes that you may know one another. Indeed, the most noble of you in the sight of Allah is the most righteous of you. Indeed, Allah is Knowing and Acquainted."}, {"ayah": 14, "translit": "Qaalatil-A 'raabu aamannaa qul lam tu'minoo wa laakin qoolooo aslamnaa wa lamma yadkhulil eemaanu fee quloobikum wa in tutee'ul laaha wa Rasoolahoo laa yalitkum min a'maalikum shai'aa; innal laaha Ghafoorur Raheem", "translation": "The bedouins say, \"We have believed.\" Say, \"You have not [yet] believed; but say [instead], 'We have submitted,' for faith has not yet entered your hearts. And if you obey Allah and His Messenger, He will not deprive you from your deeds of anything. Indeed, Allah is Forgiving and Merciful.\""}, {"ayah": 15, "translit": "Innamal muu'minoonal lazeena aamanoo billaahi wa Rasoolihee summa lam yartaaboo wa jaahadoo biamwaalihim wa anfusihim fee sabeelil laah; ulaaaika humus saadiqoon", "translation": "The believers are only the ones who have believed in Allah and His Messenger and then doubt not but strive with their properties and their lives in the cause of Allah. It is those who are the truthful."}, {"ayah": 16, "translit": "Qul atu'allimoonal laaha bideenikum wallaahu ya'lamu maa fis samaawaati wa maa fil ard; wallaahu bikulli shai'in 'Aleem", "translation": "Say, \"Would you acquaint Allah with your religion while Allah knows whatever is in the heavens and whatever is on the earth, and Allah is Knowing of all things?\""}, {"ayah": 17, "translit": "Yamunnoona 'alaika an aslamoo qul laa tamunnoo 'alaiya Islaamakum balillaahu yamunnu 'alaikum an hadaakum lil eemaani in kuntum saadiqeen", "translation": "They consider it a favor to you that they have accepted Islam. Say, \"Do not consider your Islam a favor to me. Rather, Allah has conferred favor upon you that He has guided you to the faith, if you should be truthful.\""}, {"ayah": 18, "translit": "Innal laaha ya'lamu ghaibas samaawaati wal ard; wallaahu baseerum bimaa ta'maloon", "translation": "Indeed, Allah knows the unseen [aspects] of the heavens and the earth. And Allah is Seeing of what you do."}]}, {"num": 50, "name": "Qaf", "meaning": "Qaf", "verses": [{"ayah": 1, "translit": "Qaaaf; wal Qur aanil Majeed", "translation": "Qaf. By the honored Qur'an..."}, {"ayah": 2, "translit": "Bal 'ajibooo an jaa'ahum munzirum minhum faqaalal kaafiroona haazaa shai'un 'ajeeb", "translation": "But they wonder that there has come to them a warner from among themselves, and the disbelievers say, \"This is an amazing thing."}, {"ayah": 3, "translit": "'A-izaa mitnaa wa kunnaa turaaban zaalika raj'um ba'eed", "translation": "When we have died and have become dust, [we will return to life]? That is a distant return.\""}, {"ayah": 4, "translit": "Qad 'alimnaa maa tanqu-sul-ardu minhum wa 'indanaa Kitaabun Hafeez", "translation": "We know what the earth diminishes of them, and with Us is a retaining record."}, {"ayah": 5, "translit": "Bal kazzaboo bilhaqqi lammaa jaaa'ahum fahum feee amrim mareej", "translation": "But they denied the truth when it came to them, so they are in a confused condition."}, {"ayah": 6, "translit": "Afalam yanzurooo ilas samaaa'i fawqahum kaifa banainaahaa wa zaiyannaahaa wa maa lahaa min furooj", "translation": "Have they not looked at the heaven above them - how We structured it and adorned it and [how] it has no rifts?"}, {"ayah": 7, "translit": "Wal arda madadnaahaa wa alqainaa feehaa rawaasiya wa ambatnaa feehaa min kulli zawjim baheej", "translation": "And the earth - We spread it out and cast therein firmly set mountains and made grow therein [something] of every beautiful kind,"}, {"ayah": 8, "translit": "Tabsiratanw wa zikraa likulli 'abdim muneeb", "translation": "Giving insight and a reminder for every servant who turns [to Allah]."}, {"ayah": 9, "translit": "Wa nazzalnaa minas samaaa'i maaa'am mubaarakan fa ambatnaa bihee jannaatinw wa habbal haseed", "translation": "And We have sent down blessed rain from the sky and made grow thereby gardens and grain from the harvest"}, {"ayah": 10, "translit": "Wannakhla baasiqaatil laha tal'un nadeed", "translation": "And lofty palm trees having fruit arranged in layers -"}, {"ayah": 11, "translit": "Rizqal lil'ibaad, wa ahyainaa bihee baldatam maitaa; kazaalikal khurooj", "translation": "As provision for the servants, and We have given life thereby to a dead land. Thus is the resurrection."}, {"ayah": 12, "translit": "Kazzabat qablahum qawmu Noohinw wa Ashaabur Rassi wa Samood", "translation": "The people of Noah denied before them, and the companions of the well and Thamud"}, {"ayah": 13, "translit": "Wa 'Aadunw wa Fir'awnu wikhwaanu loot", "translation": "And 'Aad and Pharaoh and the brothers of Lot"}, {"ayah": 14, "translit": "Wa Ashaabul Aykati wa qawmu Tubba'; kullun kazzabar Rusula fahaqqa wa'eed", "translation": "And the companions of the thicket and the people of Tubba'. All denied the messengers, so My threat was justly fulfilled."}, {"ayah": 15, "translit": "Afa'a yeenaa bilkhalqil awwal; bal hum fee labsim min khalqin jadeed", "translation": "Did We fail in the first creation? But they are in confusion over a new creation."}, {"ayah": 16, "translit": "Wa laqad khalaqnal insaana wa na'lamu maa tuwaswisu bihee nafsuhoo wa Nahnu aqrabu ilaihi min hablil wareed", "translation": "And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein"}, {"ayah": 17, "translit": "'Iz yatalaqqal mutalaqqi yaani 'anil yameeni wa 'anish shimaali qa'eed", "translation": "When the two receivers receive, seated on the right and on the left."}, {"ayah": 18, "translit": "Maa yalfizu min qawlin illaa ladaihi raqeebun 'ateed", "translation": "Man does not utter any word except that with him is an observer prepared [to record]."}, {"ayah": 19, "translit": "Wa jaaa'at sakratul mawti bilhaqq; zaalika maa kunta minhu taheed", "translation": "And the intoxication of death will bring the truth; that is what you were trying to avoid."}, {"ayah": 20, "translit": "Wa nufikha fis Soor; zaalika yawmul wa'eed", "translation": "And the Horn will be blown. That is the Day of [carrying out] the threat."}, {"ayah": 21, "translit": "Wa jaaa'at kullu nafsim ma'ahaa saaa'iqunw wa shaheed", "translation": "And every soul will come, with it a driver and a witness."}, {"ayah": 22, "translit": "Laqad kunta fee ghaf latim min haazaa fakashafnaa 'anka ghitaaa'aka fabasarukal yawma hadeed", "translation": "[It will be said], \"You were certainly in unmindfulness of this, and We have removed from you your cover, so your sight, this Day, is sharp.\""}, {"ayah": 23, "translit": "Wa qaala qareenuhoo haazaa maa ladaiya 'ateed", "translation": "And his companion, [the angel], will say, \"This [record] is what is with me, prepared.\""}, {"ayah": 24, "translit": "Alqiyaa fee Jahannama kulla kaffaarin 'aneed", "translation": "[Allah will say], \"Throw into Hell every obstinate disbeliever,"}, {"ayah": 25, "translit": "Mannaa'il lilkhayri mu'tadim mureeb", "translation": "Preventer of good, aggressor, and doubter,"}, {"ayah": 26, "translit": "Allazee ja'ala ma'al laahi ilaahan aakhara fa alqiyaahu fil'azaabish shadeed", "translation": "Who made [as equal] with Allah another deity; then throw him into the severe punishment.\""}, {"ayah": 27, "translit": "Qaala qareenuhoo Rabbanaa maaa atghaituhoo wa laakin kaana fee dalaahim ba'eed", "translation": "His [devil] companion will say, \"Our Lord, I did not make him transgress, but he [himself] was in extreme error.\""}, {"ayah": 28, "translit": "Qaala laa takhtasimoo ladaayya wa qad qaddamtu ilaikum bilwa'eed", "translation": "[Allah] will say, \"Do not dispute before Me, while I had already presented to you the warning."}, {"ayah": 29, "translit": "Maa yubaddalul qawlu ladaiya wa maaa ana bizal laamil lil'abeed", "translation": "The word will not be changed with Me, and never will I be unjust to the servants.\""}, {"ayah": 30, "translit": "Yawma naqoolu li'jahannama halim talaati wa taqoolu hal mim mazeed", "translation": "On the Day We will say to Hell, \"Have you been filled?\" and it will say, \"Are there some more,\""}, {"ayah": 31, "translit": "Wa uzlifatil jannatu lil muttaqeena ghaira ba'eed", "translation": "And Paradise will be brought near to the righteous, not far,"}, {"ayah": 32, "translit": "Haaza maa too'adoona likulli awwaabin hafeez", "translation": "[It will be said], \"This is what you were promised - for every returner [to Allah] and keeper [of His covenant]"}, {"ayah": 33, "translit": "Man khashiyar Rahmaana bilghaibi wa jaaa'a biqalbim muneeb", "translation": "Who feared the Most Merciful unseen and came with a heart returning [in repentance]."}, {"ayah": 34, "translit": "Udkhuloohaa bisalaamin zaalika yawmul khulood", "translation": "Enter it in peace. This is the Day of Eternity.\""}, {"ayah": 35, "translit": "Lahum maa yashaaa'oona feehaa wa ladainaa mazeed", "translation": "They will have whatever they wish therein, and with Us is more."}, {"ayah": 36, "translit": "Wa kam ahlaknaa qablahum min qarnin hum ashaddu minhum batshan fanaqqaboo fil bilaad, hal mim mahees", "translation": "And how many a generation before them did We destroy who were greater than them in [striking] power and had explored throughout the lands. Is there any place of escape?"}, {"ayah": 37, "translit": "Inna fee zaalika lazikraa liman kaana lahoo qalbun aw alqas sam'a wa huwa shaheed", "translation": "Indeed in that is a reminder for whoever has a heart or who listens while he is present [in mind]."}, {"ayah": 38, "translit": "Wa laqad khalaqnas samaawaati wal arda wa maa bainahumaa fee sittati ayyaamin wa maa massanaa mil lughoob", "translation": "And We did certainly create the heavens and earth and what is between them in six days, and there touched Us no weariness."}, {"ayah": 39, "translit": "Fasbir 'alaa maa yaqooloona wa sabbih bihamdi Rabbika qabla tuloo'ish shamsi wa qablal ghuroob", "translation": "So be patient, [O Muhammad], over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting,"}, {"ayah": 40, "translit": "Wa minal laili fasabbih hu wa adbaaras sujood", "translation": "And [in part] of the night exalt Him and after prostration."}, {"ayah": 41, "translit": "Wastami' yawma yunaa dil munaadi mim makaanin qareeb", "translation": "And listen on the Day when the Caller will call out from a place that is near -"}, {"ayah": 42, "translit": "Yawma yasmaoonas sai hata bilhaqq zaalika yawmul khurooj", "translation": "The Day they will hear the blast [of the Horn] in truth. That is the Day of Emergence [from the graves]."}, {"ayah": 43, "translit": "Innaa Nahnu nuhyee wa numeetu wa ilainal maseer", "translation": "Indeed, it is We who give life and cause death, and to Us is the destination"}, {"ayah": 44, "translit": "Yawma tashaqqaqul ardu 'anhum siraa'aa; zaalika hashrun 'alainaa yaseer", "translation": "On the Day the earth breaks away from them [and they emerge] rapidly; that is a gathering easy for Us."}, {"ayah": 45, "translit": "Nahnu a'lamu bimaa yaqooloona wa maaa anta 'alihim bijabbaarin fazakkir bil quraani many yakhaafu wa'eed", "translation": "We are most knowing of what they say, and you are not over them a tyrant. But remind by the Qur'an whoever fears My threat."}]}, {"num": 51, "name": "Adh-Dhariyat", "meaning": "The Winnowing Winds", "verses": [{"ayah": 1, "translit": "Waz-zaariyaati zarwaa", "translation": "By those [winds] scattering [dust] dispersing"}, {"ayah": 2, "translit": "Falhaamilaati wiqraa", "translation": "And those [clouds] carrying a load [of water]"}, {"ayah": 3, "translit": "Faljaariyaati yusraa", "translation": "And those [ships] sailing with ease"}, {"ayah": 4, "translit": "Falmuqassimaati amraa", "translation": "And those [angels] apportioning [each] matter,"}, {"ayah": 5, "translit": "Innamaa too'adoona la-saadiq", "translation": "Indeed, what you are promised is true."}, {"ayah": 6, "translit": "Wa innad deena la waaqi'", "translation": "And indeed, the recompense is to occur."}, {"ayah": 7, "translit": "Wassamaaa'i zaatil hubuk", "translation": "By the heaven containing pathways,"}, {"ayah": 8, "translit": "Innakum lafee qawlim mukhtalif", "translation": "Indeed, you are in differing speech."}, {"ayah": 9, "translit": "Yu'faku 'anhu man ufik", "translation": "Deluded away from the Qur'an is he who is deluded."}, {"ayah": 10, "translit": "Qutilal kharraasoon", "translation": "Destroyed are the falsifiers"}, {"ayah": 11, "translit": "Allazeena hum fee ghamratin saahoon", "translation": "Who are within a flood [of confusion] and heedless."}, {"ayah": 12, "translit": "Yas'aloona ayyaana yawmud Deen", "translation": "They ask, \"When is the Day of Recompense?\""}, {"ayah": 13, "translit": "Yawma hum 'alan naari yuftanoon", "translation": "[It is] the Day they will be tormented over the Fire"}, {"ayah": 14, "translit": "Zooqoo fitnatakum haa zal lazee kuntum bihee tas ta'jiloon", "translation": "[And will be told], \"Taste your torment. This is that for which you were impatient.\""}, {"ayah": 15, "translit": "Innal muttaqeena fee jannaatinw wa 'uyoon", "translation": "Indeed, the righteous will be among gardens and springs,"}, {"ayah": 16, "translit": "Aakhizeena maaa aataahum Rabbuhum; innahum kaanoo qabla zaalika muhsineen", "translation": "Accepting what their Lord has given them. Indeed, they were before that doers of good."}, {"ayah": 17, "translit": "kaanoo qaleelam minal laili maa yahja'oon", "translation": "They used to sleep but little of the night,"}, {"ayah": 18, "translit": "Wa bilashaari hum yastaghfiroon", "translation": "And in the hours before dawn they would ask forgiveness,"}, {"ayah": 19, "translit": "Wa feee amwaalihim haqqul lissaaa'ili walmahroom", "translation": "And from their properties was [given] the right of the [needy] petitioner and the deprived."}, {"ayah": 20, "translit": "Wa fil ardi aayaatul lilmooqineen", "translation": "And on the earth are signs for the certain [in faith]"}, {"ayah": 21, "translit": "Wa feee anfusikum; afalaa tubsiroon", "translation": "And in yourselves. Then will you not see?"}, {"ayah": 22, "translit": "Wa fissamaaa'i rizqukum wa maa too'adoon", "translation": "And in the heaven is your provision and whatever you are promised."}, {"ayah": 23, "translit": "Fawa Rabbis samaaa'i wal ardi innahoo lahaqqum misla maa annakum tantiqoon", "translation": "Then by the Lord of the heaven and earth, indeed, it is truth - just as [sure as] it is that you are speaking."}, {"ayah": 24, "translit": "Hal ataaka hadeesu daifi Ibraaheemal mukrameen", "translation": "Has there reached you the story of the honored guests of Abraham? -"}, {"ayah": 25, "translit": "Iz dakhaloo 'alaihi faqaaloo salaaman qaala salaamun qawmum munkaroon", "translation": "When they entered upon him and said, \"[We greet you with] peace.\" He answered, \"[And upon you] peace, [you are] a people unknown."}, {"ayah": 26, "translit": "Faraagha ilaaa ahlihee fajaaa'a bi'ijlin sameen", "translation": "Then he went to his family and came with a fat [roasted] calf"}, {"ayah": 27, "translit": "Faqarrabahooo ilaihim qaala alaa taakuloon", "translation": "And placed it near them; he said, \"Will you not eat?\""}, {"ayah": 28, "translit": "Fa awjasa minhm khee fatan qaaloo laa takhaf wa bashsharoohu bighulaamin 'aleem", "translation": "And he felt from them apprehension. They said, \"Fear not,\" and gave him good tidings of a learned boy."}, {"ayah": 29, "translit": "Fa aqbalatim ra-atuhoo fee sarratin fasakkat wajhahaa wa qaalat 'ajoozun 'aqeem", "translation": "And his wife approached with a cry [of alarm] and struck her face and said, \"[I am] a barren old woman!\""}, {"ayah": 30, "translit": "Qaaloo kazaaliki qaala Rabbuki innahoo huwal hakeemul 'aleem", "translation": "They said, \"Thus has said your Lord; indeed, He is the Wise, the Knowing.\""}, {"ayah": 31, "translit": "Qaala famaa khatbukum ayyuhal mursaloon", "translation": "[Abraham] said, \"Then what is your business [here], O messengers?\""}, {"ayah": 32, "translit": "Qaalooo innaaa ursilnaaa ilaa qawmim mujrimeen", "translation": "They said, \"Indeed, we have been sent to a people of criminals"}, {"ayah": 33, "translit": "Linursila 'alaihim hijaa ratam min teen", "translation": "To send down upon them stones of clay,"}, {"ayah": 34, "translit": "Musawwamatan 'inda rabbika lilmusrifeen", "translation": "Marked in the presence of your Lord for the transgressors.\""}, {"ayah": 35, "translit": "Fa akhrajnaa man kaana feehaa minal mu'mineen", "translation": "So We brought out whoever was in the cities of the believers."}, {"ayah": 36, "translit": "Famaa wajadnaa feehaa ghaira baitim minal muslimeen", "translation": "And We found not within them other than a [single] house of Muslims."}, {"ayah": 37, "translit": "Wa taraknaa feehaaa aayatal lillazeena yakhaafoonal 'azaabal aleem", "translation": "And We left therein a sign for those who fear the painful punishment."}, {"ayah": 38, "translit": "Wa fee Moosaaa iz arsalnaahu ilaa Fir'wna bisultaa nim mubeen", "translation": "And in Moses [was a sign], when We sent him to Pharaoh with clear authority."}, {"ayah": 39, "translit": "Fatawalla biruknihee wa qaala saahirun aw majnoon", "translation": "But he turned away with his supporters and said,\" A magician or a madman.\""}, {"ayah": 40, "translit": "Fa akhaznaahu wa junoo dahoo fanabaznaahum fil yammi wa huwa muleem", "translation": "So We took him and his soldiers and cast them into the sea, and he was blameworthy."}, {"ayah": 41, "translit": "Wa fee 'Aadin iz arsalnaa 'alaihimur reehal'aqeem", "translation": "And in 'Aad [was a sign], when We sent against them the barren wind."}, {"ayah": 42, "translit": "Maa tazaru min shai'in atat 'alaihi illaa ja'alat hu karrameem", "translation": "It left nothing of what it came upon but that it made it like disintegrated ruins."}, {"ayah": 43, "translit": "Wa fee Samooda iz qeela lahum tamatta''oo hattaa heen", "translation": "And in Thamud, when it was said to them, \"Enjoy yourselves for a time.\""}, {"ayah": 44, "translit": "Fa'ataw 'an amri Rabbihim fa akhazal humus saa'iqatu wa hum yanzuroon", "translation": "But they were insolent toward the command of their Lord, so the thunderbolt seized them while they were looking on."}, {"ayah": 45, "translit": "Famas tataa'oo min qiyaaminw wa maa kaanoo muntasireen", "translation": "And they were unable to arise, nor could they defend themselves."}, {"ayah": 46, "translit": "Wa qawma Noohim min qablu innahum kaano qawman faasiqeen", "translation": "And [We destroyed] the people of Noah before; indeed, they were a people defiantly disobedient."}, {"ayah": 47, "translit": "Wassamaaa'a banainaa haa bi aydinw wa innaa lamoosi'oon", "translation": "And the heaven We constructed with strength, and indeed, We are [its] expander."}, {"ayah": 48, "translit": "Wal arda farashnaahaa fani'mal maahidoon", "translation": "And the earth We have spread out, and excellent is the preparer."}, {"ayah": 49, "translit": "Wa min kulli shai'in khalaqnaa zawjaini la'allakum tazakkaroon", "translation": "And of all things We created two mates; perhaps you will remember."}, {"ayah": 50, "translit": "Fafirrooo ilal laahi innee lakum minhu nazeerum mubeen", "translation": "So flee to Allah. Indeed, I am to you from Him a clear warner."}, {"ayah": 51, "translit": "Wa laa taj'aloo ma'al laahi ilaahan aakhara innee lakum minhu nazeerum mubeen", "translation": "And do not make [as equal] with Allah another deity. Indeed, I am to you from Him a clear warner."}, {"ayah": 52, "translit": "Kazaalika maaa atal lazeena min qablihim mir Rasoolin illaa qaaloo saahirun aw majnoon", "translation": "Similarly, there came not to those before them any messenger except that they said, \"A magician or a madman.\""}, {"ayah": 53, "translit": "Atawaasaw bih; bal hum qawmun taaghoon", "translation": "Did they suggest it to them? Rather, they [themselves] are a transgressing people."}, {"ayah": 54, "translit": "Fatawalla 'anhum famaaa anta bimaloom", "translation": "So leave them, [O Muhammad], for you are not to be blamed."}, {"ayah": 55, "translit": "Wa zakkir fa innaz zikraa tanfa'ul mu'mineen", "translation": "And remind, for indeed, the reminder benefits the believers."}, {"ayah": 56, "translit": "Wa maa khalaqtul jinna wal insa illaa liya'budoon", "translation": "And I did not create the jinn and mankind except to worship Me."}, {"ayah": 57, "translit": "Maaa ureedu minhum mir rizqinw wa maaa ureedu anyyut'imoon", "translation": "I do not want from them any provision, nor do I want them to feed Me."}, {"ayah": 58, "translit": "Innal laaha Huwar Razzaaqu Zul Quwwatil Mateen", "translation": "Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength."}, {"ayah": 59, "translit": "Fa inna lillazeena zalamoo zanoobam misla zanoobi ashaabihim falaa yasta'jiloon", "translation": "And indeed, for those who have wronged is a portion [of punishment] like the portion of their predecessors, so let them not impatiently urge Me."}, {"ayah": 60, "translit": "Fawailul lillazeena kafaroo miny yawmihimul lazee yoo'adoon", "translation": "And woe to those who have disbelieved from their Day which they are promised."}]}, {"num": 52, "name": "At-Tur", "meaning": "The Mount", "verses": [{"ayah": 1, "translit": "Wat-Toor", "translation": "By the mount"}, {"ayah": 2, "translit": "Wa kitaabim mastoor", "translation": "And [by] a Book inscribed"}, {"ayah": 3, "translit": "Fee raqqim manshoor", "translation": "In parchment spread open"}, {"ayah": 4, "translit": "Wal baitil ma'moor", "translation": "And [by] the frequented House"}, {"ayah": 5, "translit": "Wassaqfil marfoo'", "translation": "And [by] the heaven raised high"}, {"ayah": 6, "translit": "Wal bahril masjoor", "translation": "And [by] the sea filled [with fire],"}, {"ayah": 7, "translit": "Inna 'azaaba Rabbika lawaaqi'", "translation": "Indeed, the punishment of your Lord will occur."}, {"ayah": 8, "translit": "Maa lahoo min daafi'", "translation": "Of it there is no preventer."}, {"ayah": 9, "translit": "Yawma tamoorus samaaa'u mawraa", "translation": "On the Day the heaven will sway with circular motion"}, {"ayah": 10, "translit": "Wa taseerul jibaalu sairaa", "translation": "And the mountains will pass on, departing -"}, {"ayah": 11, "translit": "Fawailuny yawma 'izil lil mukaazzibeen", "translation": "Then woe, that Day, to the deniers,"}, {"ayah": 12, "translit": "Allazeena hum fee khawdiny yal'aboon", "translation": "Who are in [empty] discourse amusing themselves."}, {"ayah": 13, "translit": "Yawma yuda'-'oona ilaa naari jahannama da'-'aa", "translation": "The Day they are thrust toward the fire of Hell with a [violent] thrust, [its angels will say],"}, {"ayah": 14, "translit": "Haazihin naarul latee kuntum bihaa tukazziboon", "translation": "\"This is the Fire which you used to deny."}, {"ayah": 15, "translit": "Afasihrun haazaaaa am antum laa tubsiroon", "translation": "Then is this magic, or do you not see?"}, {"ayah": 16, "translit": "Islawhaa fasbirooo aw laa tasbiroo sawaaa'un 'alaikum innamaa tujzawna maa kuntum ta'maloon", "translation": "[Enter to] burn therein; then be patient or impatient - it is all the same for you. You are only being recompensed [for] what you used to do.\""}, {"ayah": 17, "translit": "Innal muttaqeena fee jannaatinw wa na'eem", "translation": "Indeed, the righteous will be in gardens and pleasure,"}, {"ayah": 18, "translit": "Faakiheena bimaaa aataahum rabbuhum wa waqaahum rabbuhum 'azaabal jaheem", "translation": "Enjoying what their Lord has given them, and their Lord protected them from the punishment of Hellfire."}, {"ayah": 19, "translit": "Kuloo washraboo haneee 'am bimaa kuntum ta'maloon", "translation": "[They will be told], \"Eat and drink in satisfaction for what you used to do.\""}, {"ayah": 20, "translit": "Muttaki'eena 'alaa sururim masfoofatinw wa zawwaj naahum bihoorin 'een", "translation": "They will be reclining on thrones lined up, and We will marry them to fair women with large, [beautiful] eyes."}, {"ayah": 21, "translit": "Wallazeena aamanoo wattaba'at hum zurriyyatuhum bieemaanin alhaqnaa bihim zurriyyatahum wa maaa alatnaahum min 'amalihim min shai'; kullum ri'im bimaa kasaba raheen", "translation": "And those who believed and whose descendants followed them in faith - We will join with them their descendants, and We will not deprive them of anything of their deeds. Every person, for what he earned, is retained."}, {"ayah": 22, "translit": "Wa amdadnaahum bifaa kihatinw wa lahmim mimmaa yashtahoon", "translation": "And We will provide them with fruit and meat from whatever they desire."}, {"ayah": 23, "translit": "Yatanaaza'oona feehaa kaasal laa laghwun feehaa wa laa taaseem", "translation": "They will exchange with one another a cup [of wine] wherein [results] no ill speech or commission of sin."}, {"ayah": 24, "translit": "Wa yatoofu 'alaihim ghilmaanul lahum ka annahum lu'lu'um maknoon", "translation": "There will circulate among them [servant] boys [especially] for them, as if they were pearls well-protected."}, {"ayah": 25, "translit": "Wa aqbala ba'duhum 'alaa ba'diny yatasaaa'aloon", "translation": "And they will approach one another, inquiring of each other."}, {"ayah": 26, "translit": "Qaalooo innaa kunnaa qablu feee ahlinaa mushfiqeen", "translation": "They will say, \"Indeed, we were previously among our people fearful [of displeasing Allah]."}, {"ayah": 27, "translit": "Famannnal laahu 'alainaa wa waqaanaa 'azaabas samoom", "translation": "So Allah conferred favor upon us and protected us from the punishment of the Scorching Fire."}, {"ayah": 28, "translit": "Innaa kunnaa min qablu nad'oohu innahoo huwal barrur raheem", "translation": "Indeed, we used to supplicate Him before. Indeed, it is He who is the Beneficent, the Merciful.\""}, {"ayah": 29, "translit": "Fazakkir famaaa anta bini'mati rabbika bikaahininw wa laa majnoon", "translation": "So remind [O Muhammad], for you are not, by the favor of your Lord, a soothsayer or a madman."}, {"ayah": 30, "translit": "Am yaqooloona shaa'irun natarabbasu bihee raibal manoon", "translation": "Or do they say [of you], \"A poet for whom we await a misfortune of time?\""}, {"ayah": 31, "translit": "Qul tarabbasoo fa innee ma'akum minal mutarabbiseen", "translation": "Say, \"Wait, for indeed I am, with you, among the waiters.\""}, {"ayah": 32, "translit": "Am taamuruhum ahlaamuhum bihaazaaa am hum qawmun taaghoon", "translation": "Or do their minds command them to [say] this, or are they a transgressing people?"}, {"ayah": 33, "translit": "Am yaqooloona taqawwalah; bal laa yu'minoon", "translation": "Or do they say, \"He has made it up\"? Rather, they do not believe."}, {"ayah": 34, "translit": "Falyaatoo bihadeesim misliheee in kaanoo saadiqeen", "translation": "Then let them produce a statement like it, if they should be truthful."}, {"ayah": 35, "translit": "Am khuliqoo min ghairi shai'in am humul khaaliqoon", "translation": "Or were they created by nothing, or were they the creators [of themselves]?"}, {"ayah": 36, "translit": "Am khalaqus samaawaati wal ard; bal laa yooqinoon", "translation": "Or did they create the heavens and the earth? Rather, they are not certain."}, {"ayah": 37, "translit": "Am'indahum khazaaa'inu rabbika am humul musaitiroon", "translation": "Or have they the depositories [containing the provision] of your Lord? Or are they the controllers [of them]?"}, {"ayah": 38, "translit": "Am lahum sullamuny yastami'oona feehi falyaati mustami'uhum bisultaanim mubeen", "translation": "Or have they a stairway [into the heaven] upon which they listen? Then let their listener produce a clear authority."}, {"ayah": 39, "translit": "Am lahul banaatu wa lakumul banoon", "translation": "Or has He daughters while you have sons?"}, {"ayah": 40, "translit": "Am tas'aluhum ajran fahum mim maghramim musqaloon", "translation": "Or do you, [O Muhammad], ask of them a payment, so they are by debt burdened down?"}, {"ayah": 41, "translit": "Am 'indahumul ghaibu fahum yaktuboon", "translation": "Or have they [knowledge of] the unseen, so they write [it] down?"}, {"ayah": 42, "translit": "Am yureedoona kaidan fallazeena kafaroo humul makeedoon", "translation": "Or do they intend a plan? But those who disbelieve - they are the object of a plan."}, {"ayah": 43, "translit": "Am lahum ilaahun ghairul laa; subhaanal laahi 'ammaa yushrikoon", "translation": "Or have they a deity other than Allah? Exalted is Allah above whatever they associate with Him."}, {"ayah": 44, "translit": "Wa iny yaraw kisfam minas samaaa'i saaqitany yaqooloo sahaabum markoom", "translation": "And if they were to see a fragment from the sky falling, they would say, \"[It is merely] clouds heaped up.\""}, {"ayah": 45, "translit": "Fazarhum hatta yulaaqoo yawmahumul lazee feehi yus'aqoon", "translation": "So leave them until they meet their Day in which they will be struck insensible -"}, {"ayah": 46, "translit": "Yawma laa yughnee 'anhum kaidumhum shai'anw wa laa hum yunsaroon", "translation": "The Day their plan will not avail them at all, nor will they be helped."}, {"ayah": 47, "translit": "Wa inna lillazeena zalamoo 'azaaban doona zalika wa laakinna aksarahum laa ya'lamoon", "translation": "And indeed, for those who have wronged is a punishment before that, but most of them do not know."}, {"ayah": 48, "translit": "Wasbir lihukmi rabbika fa innaka bi-a'yuninaa wa sabbih bihamdi rabbika heena taqoom", "translation": "And be patient, [O Muhammad], for the decision of your Lord, for indeed, you are in Our eyes. And exalt [Allah] with praise of your Lord when you arise."}, {"ayah": 49, "translit": "Wa minal laili fasabbihhu wa idbaaran nujoom", "translation": "And in a part of the night exalt Him and after [the setting of] the stars."}]}, {"num": 53, "name": "An-Najm", "meaning": "The Star", "verses": [{"ayah": 1, "translit": "Wannajmi izaa hawaa", "translation": "By the star when it descends,"}, {"ayah": 2, "translit": "Maa dalla saahibukum wa maa ghawaa", "translation": "Your companion [Muhammad] has not strayed, nor has he erred,"}, {"ayah": 3, "translit": "Wa maa yyantiqu 'anilhawaaa", "translation": "Nor does he speak from [his own] inclination."}, {"ayah": 4, "translit": "In huwa illaa Wahyuny yoohaa", "translation": "It is not but a revelation revealed,"}, {"ayah": 5, "translit": "'Allamahoo shadeedul quwaa", "translation": "Taught to him by one intense in strength -"}, {"ayah": 6, "translit": "Zoo mirratin fastawaa", "translation": "One of soundness. And he rose to [his] true form"}, {"ayah": 7, "translit": "Wa huwa bil ufuqil a'laa", "translation": "While he was in the higher [part of the] horizon."}, {"ayah": 8, "translit": "Summa danaa fatadalla", "translation": "Then he approached and descended"}, {"ayah": 9, "translit": "Fakaana qaaba qawsaini aw adnaa", "translation": "And was at a distance of two bow lengths or nearer."}, {"ayah": 10, "translit": "Fa awhaaa ilaa 'abdihee maaa awhaa", "translation": "And he revealed to His Servant what he revealed."}, {"ayah": 11, "translit": "Maa kazabal fu'aadu maa ra aa", "translation": "The heart did not lie [about] what it saw."}, {"ayah": 12, "translit": "Afatumaaroonahoo 'alaa maayaraa", "translation": "So will you dispute with him over what he saw?"}, {"ayah": 13, "translit": "Wa laqad ra aahu nazlatan ukhraa", "translation": "And he certainly saw him in another descent"}, {"ayah": 14, "translit": "'Inda sidratil muntaha", "translation": "At the Lote Tree of the Utmost Boundary -"}, {"ayah": 15, "translit": "'Indahaa jannatul maawaa", "translation": "Near it is the Garden of Refuge -"}, {"ayah": 16, "translit": "Iz yaghshas sidrata maa yaghshaa", "translation": "When there covered the Lote Tree that which covered [it]."}, {"ayah": 17, "translit": "Maa zaaghal basaru wa maa taghaa", "translation": "The sight [of the Prophet] did not swerve, nor did it transgress [its limit]."}, {"ayah": 18, "translit": "Laqad ra aa min aayaati Rabbihil kubraaa", "translation": "He certainly saw of the greatest signs of his Lord."}, {"ayah": 19, "translit": "Afara'aytumul laata wal 'uzzaa", "translation": "So have you considered al-Lat and al-'Uzza?"}, {"ayah": 20, "translit": "Wa manaatas saalisatal ukhraa", "translation": "And Manat, the third - the other one?"}, {"ayah": 21, "translit": "A-lakumuz zakaru wa lahul unsaa", "translation": "Is the male for you and for Him the female?"}, {"ayah": 22, "translit": "Tilka izan qismatun deezaa", "translation": "That, then, is an unjust division."}, {"ayah": 23, "translit": "In hiya illaaa asmaaa'un sammaitumoohaaa antum wa aabaaa'ukum maaa anzalal laahu bihaa min sultaan; inyyattabi'oona illaz zanna wa maa tahwal anfusu wa laqad jaaa'ahum mir Rabbihimul hudaa", "translation": "They are not but [mere] names you have named them - you and your forefathers - for which Allah has sent down no authority. They follow not except assumption and what [their] souls desire, and there has already come to them from their Lord guidance."}, {"ayah": 24, "translit": "Am lil insaani maa taman naa", "translation": "Or is there for man whatever he wishes?"}, {"ayah": 25, "translit": "Falillaahil aakhiratu wal oolaa", "translation": "Rather, to Allah belongs the Hereafter and the first [life]."}, {"ayah": 26, "translit": "Wa kam mim malakin fissamaawaati laa tughnee shafaa'atuhum shai'an illaa mim ba'di anyyaazanal laahu limany yashaaa'u wa yardaa", "translation": "And how many angels there are in the heavens whose intercession will not avail at all except [only] after Allah has permitted [it] to whom He wills and approves."}, {"ayah": 27, "translit": "innal lazeena laa yu'minoona bil aakhirati la yusammoonal malaaa'ikata tasmiyatal unsaa", "translation": "Indeed, those who do not believe in the Hereafter name the angels female names,"}, {"ayah": 28, "translit": "Wa maa lahum bihee min 'ilmin iny yattabi'oona illaz zanna wa innaz zanna laa yughnee minal haqqi shai'aa", "translation": "And they have thereof no knowledge. They follow not except assumption, and indeed, assumption avails not against the truth at all."}, {"ayah": 29, "translit": "Fa a'rid 'am man tawallaa 'an zikrinaa wa lam yurid illal hayaatad dunyaa", "translation": "So turn away from whoever turns his back on Our message and desires not except the worldly life."}, {"ayah": 30, "translit": "Zalika mablaghuhum minal 'ilm; inna rabbaka huwa a'lamu biman dalla 'an sabee lihee wa huwa a'lamu bimanih tadaa", "translation": "That is their sum of knowledge. Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of who is guided."}, {"ayah": 31, "translit": "Wa lillaahi maa fis samaawaati wa maa fil ardi liyajziyal lazeena asaaa'oo bimaa 'amiloo wa yajziyal lazeena ahsanoo bilhusnaa", "translation": "And to Allah belongs whatever is in the heavens and whatever is in the earth - that He may recompense those who do evil with [the penalty of] what they have done and recompense those who do good with the best [reward] -"}, {"ayah": 32, "translit": "Allazeena yajtaniboona kabaaa'iral ismi walfawaa hisha illal lamam; inna rabbaka waasi'ul maghfirah; huwa a'lamu bikum iz ansha akum minal ardi wa iz antum ajinnatun fee butooni umma haatikum falaa tuzakkooo anfusakum huwa a'lamu bimanit taqaa", "translation": "Those who avoid the major sins and immoralities, only [committing] slight ones. Indeed, your Lord is vast in forgiveness. He was most knowing of you when He produced you from the earth and when you were fetuses in the wombs of your mothers. So do not claim yourselves to be pure; He is most knowing of who fears Him."}, {"ayah": 33, "translit": "Afara'ayatal lazee tawallaa", "translation": "Have you seen the one who turned away"}, {"ayah": 34, "translit": "Wa a'taa qaleelanw wa akdaa", "translation": "And gave a little and [then] refrained?"}, {"ayah": 35, "translit": "A'indahoo 'ilmul ghaibi fahuwa yaraa", "translation": "Does he have knowledge of the unseen, so he sees?"}, {"ayah": 36, "translit": "Am lam yunabbaa bimaa fee suhuhfi Moosa", "translation": "Or has he not been informed of what was in the scriptures of Moses"}, {"ayah": 37, "translit": "Wa Ibraaheemal lazee waffaaa", "translation": "And [of] Abraham, who fulfilled [his obligations] -"}, {"ayah": 38, "translit": "Allaa taziru waaziratunw wizra ukhraa", "translation": "That no bearer of burdens will bear the burden of another"}, {"ayah": 39, "translit": "Wa al laisa lil insaani illaa maa sa'aa", "translation": "And that there is not for man except that [good] for which he strives"}, {"ayah": 40, "translit": "Wa anna sa'yahoo sawfa yuraa", "translation": "And that his effort is going to be seen -"}, {"ayah": 41, "translit": "Summa yujzaahul jazaaa 'al awfaa", "translation": "Then he will be recompensed for it with the fullest recompense"}, {"ayah": 42, "translit": "Wa anna ilaa rabbikal muntahaa", "translation": "And that to your Lord is the finality"}, {"ayah": 43, "translit": "Wa annahoo huwa adhaka wa abkaa", "translation": "And that it is He who makes [one] laugh and weep"}, {"ayah": 44, "translit": "Wa annahoo huwa amaata wa ahyaa", "translation": "And that it is He who causes death and gives life"}, {"ayah": 45, "translit": "Wa annahoo khalaqaz zawjainiz zakara wal unsaa", "translation": "And that He creates the two mates - the male and female -"}, {"ayah": 46, "translit": "Min nutfatin izaa tumnaa", "translation": "From a sperm-drop when it is emitted"}, {"ayah": 47, "translit": "Wa anna 'alaihin nash atal ukhraa", "translation": "And that [incumbent] upon Him is the next creation"}, {"ayah": 48, "translit": "Wa annahoo huwa aghnaa wa aqnaa", "translation": "And that it is He who enriches and suffices"}, {"ayah": 49, "translit": "Wa annahoo huwa rabbush shi'raa", "translation": "And that it is He who is the Lord of Sirius"}, {"ayah": 50, "translit": "Wa annahooo ahlak a 'Aadanil oolaa", "translation": "And that He destroyed the first [people of] 'Aad"}, {"ayah": 51, "translit": "Wa samooda famaaa abqaa", "translation": "And Thamud - and He did not spare [them] -"}, {"ayah": 52, "translit": "Wa qawma Noohim min qablu innahum kaanoo hum azlama wa atghaa", "translation": "And the people of Noah before. Indeed, it was they who were [even] more unjust and oppressing."}, {"ayah": 53, "translit": "Wal mu'tafikata ahwaa", "translation": "And the overturned towns He hurled down"}, {"ayah": 54, "translit": "Faghashshaahaa maa ghashshaa", "translation": "And covered them by that which He covered."}, {"ayah": 55, "translit": "Fabi ayyi aalaaa'i Rabbika tatamaaraa", "translation": "Then which of the favors of your Lord do you doubt?"}, {"ayah": 56, "translit": "Haazaa nazeerum minan nuzuril oolaa", "translation": "This [Prophet] is a warner like the former warners."}, {"ayah": 57, "translit": "Azifatil laazifah", "translation": "The Approaching Day has approached."}, {"ayah": 58, "translit": "Laisa lahaa min doonil laahi kaashifah", "translation": "Of it, [from those] besides Allah, there is no remover."}, {"ayah": 59, "translit": "Afamin hazal hadeesi ta'jaboon", "translation": "Then at this statement do you wonder?"}, {"ayah": 60, "translit": "Wa tadhakoona wa laa tabkoon", "translation": "And you laugh and do not weep"}, {"ayah": 61, "translit": "Wa antum saamidoon", "translation": "While you are proudly sporting?"}, {"ayah": 62, "translit": "Fasjudoo lillaahi wa'budoo", "translation": "So prostrate to Allah and worship [Him]."}]}, {"num": 54, "name": "Al-Qamar", "meaning": "The Moon", "verses": [{"ayah": 1, "translit": "Iqtarabatis Saa'atu wsan shaqqal qamar", "translation": "The Hour has come near, and the moon has split [in two]."}, {"ayah": 2, "translit": "Wa iny yaraw aayatany yu'ridoo wa yaqooloo sihrum mustamirr", "translation": "And if they see a miracle, they turn away and say, \"Passing magic.\""}, {"ayah": 3, "translit": "Wa kazzaboo wattaba'ooo ahwaaa'ahum; wa kullu amrim mustaqirr", "translation": "And they denied and followed their inclinations. But for every matter is a [time of] settlement."}, {"ayah": 4, "translit": "Wa laqad jaaa'ahum minal ambaaa'i maa feehi muzdajar", "translation": "And there has already come to them of information that in which there is deterrence -"}, {"ayah": 5, "translit": "Hikmatum baalighatun famaa tughnin nuzur", "translation": "Extensive wisdom - but warning does not avail [them]."}, {"ayah": 6, "translit": "Fatawalla 'anhum; yawma yad'ud daa'i ilaa shai 'in nukur", "translation": "So leave them, [O Muhammad]. The Day the Caller calls to something forbidding,"}, {"ayah": 7, "translit": "khushsha'an absaaruhum yakrujoona minal ajdaasi ka annahum jaraadum muntashir", "translation": "Their eyes humbled, they will emerge from the graves as if they were locusts spreading,"}, {"ayah": 8, "translit": "Muhti'eena ilad daa'i yaqoolul kafiroona haazaa yawmun 'asir", "translation": "Racing ahead toward the Caller. The disbelievers will say, \"This is a difficult Day.\""}, {"ayah": 9, "translit": "Kazzabat qablahum qawmu Noohin fakazzaboo 'abdanaa wa qaaloo majnoo nunw wazdujir", "translation": "The people of Noah denied before them, and they denied Our servant and said, \"A madman,\" and he was repelled."}, {"ayah": 10, "translit": "Fada'aa Rabbahooo annee maghloobun fantasir", "translation": "So he invoked his Lord, \"Indeed, I am overpowered, so help.\""}, {"ayah": 11, "translit": "Fafatahnaaa abwaabas sa maaa'i bimaa'im munhamir", "translation": "Then We opened the gates of the heaven with rain pouring down"}, {"ayah": 12, "translit": "Wa fajjamal arda 'uyoonan faltaqal maaa'u 'alaaa amrin qad qudir", "translation": "And caused the earth to burst with springs, and the waters met for a matter already predestined."}, {"ayah": 13, "translit": "Wa hamalnaahu 'alaa zaati alwaahinw wa dusur", "translation": "And We carried him on a [construction of] planks and nails,"}, {"ayah": 14, "translit": "Tajree bi a'yuninaa jazaaa 'al liman kaana kufir", "translation": "Sailing under Our observation as reward for he who had been denied."}, {"ayah": 15, "translit": "Wa laqat taraknaahaad aayatan fahal mim muddakir", "translation": "And We left it as a sign, so is there any who will remember?"}, {"ayah": 16, "translit": "Fakaifa kaana 'azaabee wa nuzur", "translation": "And how [severe] were My punishment and warning."}, {"ayah": 17, "translit": "Wa laqad yassamal Quraana liz zikri fahal mimmuddakir", "translation": "And We have certainly made the Qur'an easy for remembrance, so is there any who will remember?"}, {"ayah": 18, "translit": "Kazzabat 'Aadun fakaifa kaana 'azaabee wa nuzur", "translation": "'Aad denied; and how [severe] were My punishment and warning."}, {"ayah": 19, "translit": "Innaa arsalnaa 'alaihim reehan sarsaran fee Yawmi nahsim mustamirr", "translation": "Indeed, We sent upon them a screaming wind on a day of continuous misfortune,"}, {"ayah": 20, "translit": "Tanzi;un naasa ka anna huma'jaazu nakhlim munqa'ir", "translation": "Extracting the people as if they were trunks of palm trees uprooted."}, {"ayah": 21, "translit": "'Fakaifa kaana 'azaabee wa nuzur", "translation": "And how [severe] were My punishment and warning."}, {"ayah": 22, "translit": "Wa laqad yassamal Quraana liz zikri fahal mim muddakir", "translation": "And We have certainly made the Qur'an easy for remembrance, so is there any who will remember?"}, {"ayah": 23, "translit": "Kazzabat Samoodu binnuzur", "translation": "Thamud denied the warning"}, {"ayah": 24, "translit": "Faqaalooo a-basharam minnaa waahidan nattabi'uhooo innaa izal lafee dalaalinw wa su'ur", "translation": "And said, \"Is it one human being among us that we should follow? Indeed, we would then be in error and madness."}, {"ayah": 25, "translit": "'A-ulqiyaz zikru 'alaihi mim baininaa bal huwa kazzaabun ashir", "translation": "Has the message been sent down upon him from among us? Rather, he is an insolent liar.\""}, {"ayah": 26, "translit": "Sa-ya'lamoona ghadam manil kazzaabul ashir", "translation": "They will know tomorrow who is the insolent liar."}, {"ayah": 27, "translit": "Innaa mursilun naaqati fitnatal lahum fartaqibhum wastabir", "translation": "Indeed, We are sending the she-camel as trial for them, so watch them and be patient."}, {"ayah": 28, "translit": "Wa nabbi'hum annal maaa'a qismatum bainahum kullu shirbim muhtadar", "translation": "And inform them that the water is shared between them, each [day of] drink attended [by turn]."}, {"ayah": 29, "translit": "Fanaadaw saahibahum fata'aataa fa'aqar", "translation": "But they called their companion, and he dared and hamstrung [her]."}, {"ayah": 30, "translit": "Fakaifa kaana 'azaabee wa nuzur", "translation": "And how [severe] were My punishment and warning."}, {"ayah": 31, "translit": "Innaaa arsalnaa 'alaihim saihatanw waahidatan fakaano kahasheemil muhtazir", "translation": "Indeed, We sent upon them one blast from the sky, and they became like the dry twig fragments of an [animal] pen."}, {"ayah": 32, "translit": "Wa laqad yassarnal quraana liz zikri fahal mim muddakir", "translation": "And We have certainly made the Qur'an easy for remembrance, so is there any who will remember?"}, {"ayah": 33, "translit": "Kazzabat qawmu lootim binnuzur", "translation": "The people of Lot denied the warning."}, {"ayah": 34, "translit": "Innaa arsalnaa 'alaihim haasiban illaaa aala Loot najjainaahum bisahar", "translation": "Indeed, We sent upon them a storm of stones, except the family of Lot - We saved them before dawn"}, {"ayah": 35, "translit": "Ni'matam min 'indinaa; kazaalika najzee man shakar", "translation": "As favor from us. Thus do We reward he who is grateful."}, {"ayah": 36, "translit": "Wa laqad anzarahum batshatanaa fatamaaraw binnuzur", "translation": "And he had already warned them of Our assault, but they disputed the warning."}, {"ayah": 37, "translit": "Wa laqad raawadoohu 'andaifee fatamasnaaa a'yunahum fazooqoo 'azaabee wa nuzur", "translation": "And they had demanded from him his guests, but We obliterated their eyes, [saying], \"Taste My punishment and warning.\""}, {"ayah": 38, "translit": "Wa laqad sabbahahum bukratan 'azaabum mustaqirr", "translation": "And there came upon them by morning an abiding punishment."}, {"ayah": 39, "translit": "Fazooqoo 'azaabee wa nuzur", "translation": "So taste My punishment and warning."}, {"ayah": 40, "translit": "Wa laqad yassarnal Quraana liz zikri fahal mim muddakir", "translation": "And We have certainly made the Qur'an easy for remembrance, so is there any who will remember?"}, {"ayah": 41, "translit": "Wa laqad jaaa'a Aala Fir'awnan nuzur", "translation": "And there certainly came to the people of Pharaoh warning."}, {"ayah": 42, "translit": "Kazzaboo bi Aayaatinaa kullihaa fa akhaznaahum akhza 'azeezim muqtadir", "translation": "They denied Our signs, all of them, so We seized them with a seizure of one Exalted in Might and Perfect in Ability."}, {"ayah": 43, "translit": "Akuffaarukum khairum min ulaaa'ikum am lakum baraaa'atun fiz Zubur", "translation": "Are your disbelievers better than those [former ones], or have you immunity in the scripture?"}, {"ayah": 44, "translit": "Am yaqooloona nahnu jamee'um muntasir", "translation": "Or do they say, \"We are an assembly supporting [each other]\"?"}, {"ayah": 45, "translit": "Sa yuhzamul jam'u wa yuwalloonad dubur", "translation": "[Their] assembly will be defeated, and they will turn their backs [in retreat]."}, {"ayah": 46, "translit": "Balis Saa'atu maw'iduhum was Saa'atu adhaa wa amarr", "translation": "But the Hour is their appointment [for due punishment], and the Hour is more disastrous and more bitter."}, {"ayah": 47, "translit": "Innal mujrimeena fee dalaalinw wa su'ur", "translation": "Indeed, the criminals are in error and madness."}, {"ayah": 48, "translit": "Yawma yushaboona fin Naari'alaa wujoohimim zooqoo massa saqar", "translation": "The Day they are dragged into the Fire on their faces [it will be said], \"Taste the touch of Saqar.\""}, {"ayah": 49, "translit": "Innaa kulla shai'in khalaqnaahu biqadar", "translation": "Indeed, all things We created with predestination."}, {"ayah": 50, "translit": "Wa maaa amrunaaa illaa waahidatun kalamhim bilbasar", "translation": "And Our command is but one, like a glance of the eye."}, {"ayah": 51, "translit": "Wa laqad ahlaknaaa ashyaa'akum fahal mim muddakir", "translation": "And We have already destroyed your kinds, so is there any who will remember?"}, {"ayah": 52, "translit": "Wa kullu shai'in fa'aloohu fiz Zubur", "translation": "And everything they did is in written records."}, {"ayah": 53, "translit": "Wa kullu sagheerinw wa kabeerim mustatar", "translation": "And every small and great [thing] is inscribed."}, {"ayah": 54, "translit": "Innal muttaqeena fee jannaatinw wa nahar", "translation": "Indeed, the righteous will be among gardens and rivers,"}, {"ayah": 55, "translit": "Fee maq'adi sidqin 'inda Maleekim Muqtadir", "translation": "In a seat of honor near a Sovereign, Perfect in Ability."}]}, {"num": 55, "name": "Ar-Rahman", "meaning": "The Most Merciful", "verses": [{"ayah": 1, "translit": "Ar Rahmaan", "translation": "The Most Merciful"}, {"ayah": 2, "translit": "'Allamal Quran", "translation": "Taught the Qur'an,"}, {"ayah": 3, "translit": "Khalaqal insaan", "translation": "Created man,"}, {"ayah": 4, "translit": "'Allamahul bayaan", "translation": "[And] taught him eloquence."}, {"ayah": 5, "translit": "Ashshamsu walqamaru bihusbaan", "translation": "The sun and the moon [move] by precise calculation,"}, {"ayah": 6, "translit": "Wannajmu washshajaru yasjudan", "translation": "And the stars and trees prostrate."}, {"ayah": 7, "translit": "Wassamaaa'a rafa'ahaa wa wada'al Meezan", "translation": "And the heaven He raised and imposed the balance"}, {"ayah": 8, "translit": "Allaa tatghaw fil meezaan", "translation": "That you not transgress within the balance."}, {"ayah": 9, "translit": "Wa aqeemul wazna bilqisti wa laa tukhsirul meezaan", "translation": "And establish weight in justice and do not make deficient the balance."}, {"ayah": 10, "translit": "Wal arda wada'ahaa lilanaame", "translation": "And the earth He laid [out] for the creatures."}, {"ayah": 11, "translit": "Feehaa faakihatunw wan nakhlu zaatul akmaam", "translation": "Therein is fruit and palm trees having sheaths [of dates]"}, {"ayah": 12, "translit": "Walhabbu zul 'asfi war Raihaanu", "translation": "And grain having husks and scented plants."}, {"ayah": 13, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 14, "translit": "Khalaqal insaana min salsaalin kalfakhkhaari", "translation": "He created man from clay like [that of] pottery."}, {"ayah": 15, "translit": "Wa khalaqal jaaan mim maarijim min naar", "translation": "And He created the jinn from a smokeless flame of fire."}, {"ayah": 16, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 17, "translit": "Rabbul mashriqayni wa Rabbul maghribayni", "translation": "[He is] Lord of the two sunrises and Lord of the two sunsets."}, {"ayah": 18, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 19, "translit": "Marajal bahrayni yalta qiyaani", "translation": "He released the two seas, meeting [side by side];"}, {"ayah": 20, "translit": "Bainahumaa barzakhul laa yabghiyaan", "translation": "Between them is a barrier [so] neither of them transgresses."}, {"ayah": 21, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 22, "translit": "Yakhruju minhumal lu 'lu u wal marjaanu", "translation": "From both of them emerge pearl and coral."}, {"ayah": 23, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 24, "translit": "Wa lahul jawaaril mun sha'aatu fil bahri kal a'laam", "translation": "And to Him belong the ships [with sails] elevated in the sea like mountains."}, {"ayah": 25, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 26, "translit": "Kullu man 'alaihaa faan", "translation": "Everyone upon the earth will perish,"}, {"ayah": 27, "translit": "Wa yabqaa wajhu rabbika zul jalaali wal ikraam", "translation": "And there will remain the Face of your Lord, Owner of Majesty and Honor."}, {"ayah": 28, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 29, "translit": "Yas'aluhoo man fissamaawaati walard; kulla ywmin huwa fee shaan", "translation": "Whoever is within the heavens and earth asks Him; every day He is bringing about a matter."}, {"ayah": 30, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 31, "translit": "Sanafrughu lakum ayyuhas saqalaan", "translation": "We will attend to you, O prominent beings."}, {"ayah": 32, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 33, "translit": "Yaa ma'sharal jinni wal insi inis tata'tum an tanfuzoo min aqtaaris samaawaati wal ardi fanfuzoo; laa tanfuzoona illaa bisultaan", "translation": "O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allah]."}, {"ayah": 34, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 35, "translit": "Yursalu 'alaikumaa shuwaazum min naarifiw-wa nuhaasun falaa tantasiraan", "translation": "There will be sent upon you a flame of fire and smoke, and you will not defend yourselves."}, {"ayah": 36, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 37, "translit": "Fa-izan shaqqatis samaaa'u fakaanat wardatan kaddihaan", "translation": "And when the heaven is split open and becomes rose-colored like oil -"}, {"ayah": 38, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny? -"}, {"ayah": 39, "translit": "Fa-yawma'izil laa yus'alu 'an zambiheee insunw wa laa jaann", "translation": "Then on that Day none will be asked about his sin among men or jinn."}, {"ayah": 40, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 41, "translit": "Yu'raful mujrimoona biseemaahum fa'yu'khazu binna waasi wal aqdaam", "translation": "The criminals will be known by their marks, and they will be seized by the forelocks and the feet."}, {"ayah": 42, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 43, "translit": "Haazihee jahannamul latee yukazzibu bihal mujrimoon", "translation": "This is Hell, which the criminals deny."}, {"ayah": 44, "translit": "Yatoofoona bainahaa wa baina hameemim aan", "translation": "They will go around between it and scalding water, heated [to the utmost degree]."}, {"ayah": 45, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 46, "translit": "Wa liman khaafa maqaama rabbihee jannataan", "translation": "But for he who has feared the position of his Lord are two gardens -"}, {"ayah": 47, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny? -"}, {"ayah": 48, "translit": "Zawaataaa afnaan", "translation": "Having [spreading] branches."}, {"ayah": 49, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 50, "translit": "Feehimaa 'aynaani tajriyaan", "translation": "In both of them are two springs, flowing."}, {"ayah": 51, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 52, "translit": "Feehimaa min kulli faakihatin zawjaan", "translation": "In both of them are of every fruit, two kinds."}, {"ayah": 53, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 54, "translit": "Muttaki'eena 'alaa furushim bataaa'inuhaa min istabraq; wajanal jannataini daan", "translation": "[They are] reclining on beds whose linings are of silk brocade, and the fruit of the two gardens is hanging low."}, {"ayah": 55, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 56, "translit": "Feehinna qaasiratut tarfi lam yatmishunna insun qablahum wa laa jaaann", "translation": "In them are women limiting [their] glances, untouched before them by man or jinni -"}, {"ayah": 57, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny? -"}, {"ayah": 58, "translit": "ka annahunnal yaaqootu wal marjaan", "translation": "As if they were rubies and coral."}, {"ayah": 59, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 60, "translit": "Hal jazaaa'ul ihsaani illal ihsaan", "translation": "Is the reward for good [anything] but good?"}, {"ayah": 61, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 62, "translit": "Wa min doonihimaa jannataan", "translation": "And below them both [in excellence] are two [other] gardens -"}, {"ayah": 63, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny? -"}, {"ayah": 64, "translit": "Mudhaaammataan", "translation": "Dark green [in color]."}, {"ayah": 65, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 66, "translit": "Feehimaa 'aynaani nad daakhataan", "translation": "In both of them are two springs, spouting."}, {"ayah": 67, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 68, "translit": "Feehimaa faakihatunw wa nakhlunw wa rummaan", "translation": "In both of them are fruit and palm trees and pomegranates."}, {"ayah": 69, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 70, "translit": "Feehinna khairaatun hisaan", "translation": "In them are good and beautiful women -"}, {"ayah": 71, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny? -"}, {"ayah": 72, "translit": "Hoorum maqsooraatun fil khiyaam", "translation": "Fair ones reserved in pavilions -"}, {"ayah": 73, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny? -"}, {"ayah": 74, "translit": "Lam yatmis hunna insun qablahum wa laa jaaann", "translation": "Untouched before them by man or jinni -"}, {"ayah": 75, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny? -"}, {"ayah": 76, "translit": "Muttaki'eena 'alaa rafrafin khudrinw wa 'abqariyyin hisaan", "translation": "Reclining on green cushions and beautiful fine carpets."}, {"ayah": 77, "translit": "Fabi ayyi aalaaa'i Rabbikumaa tukazzibaan.", "translation": "So which of the favors of your Lord would you deny?"}, {"ayah": 78, "translit": "Tabaarakasmu Rabbika Zil-Jalaali wal-Ikraam", "translation": "Blessed is the name of your Lord, Owner of Majesty and Honor."}]}, {"num": 56, "name": "Al-Waqi'ah", "meaning": "The Inevitable", "verses": [{"ayah": 1, "translit": "Izaa waqa'atil waaqi'ah", "translation": "When the Occurrence occurs,"}, {"ayah": 2, "translit": "Laisa liwaq'atihaa kaazibah", "translation": "There is, at its occurrence, no denial."}, {"ayah": 3, "translit": "Khafidatur raafi'ah", "translation": "It will bring down [some] and raise up [others]."}, {"ayah": 4, "translit": "Izaa rujjatil ardu rajjaa", "translation": "When the earth is shaken with convulsion"}, {"ayah": 5, "translit": "Wa bussatil jibaalu bassaa", "translation": "And the mountains are broken down, crumbling"}, {"ayah": 6, "translit": "Fakaanat habaaa'am mumbassaa", "translation": "And become dust dispersing."}, {"ayah": 7, "translit": "Wa kuntum azwaajan salaasah", "translation": "And you become [of] three kinds:"}, {"ayah": 8, "translit": "Fa as haabul maimanati maaa as haabul maimanah", "translation": "Then the companions of the right - what are the companions of the right?"}, {"ayah": 9, "translit": "Wa as haabul mash'amati maaa as haabul mash'amah", "translation": "And the companions of the left - what are the companions of the left?"}, {"ayah": 10, "translit": "Wassaabiqoonas saabiqoon", "translation": "And the forerunners, the forerunners -"}, {"ayah": 11, "translit": "Ulaaa'ikal muqarraboon", "translation": "Those are the ones brought near [to Allah]"}, {"ayah": 12, "translit": "Fee Jannaatin Na'eem", "translation": "In the Gardens of Pleasure,"}, {"ayah": 13, "translit": "Sullatum minal awwaleen", "translation": "A [large] company of the former peoples"}, {"ayah": 14, "translit": "Wa qaleelum minal aa khireen", "translation": "And a few of the later peoples,"}, {"ayah": 15, "translit": "'Alaa sururim mawdoonah", "translation": "On thrones woven [with ornament],"}, {"ayah": 16, "translit": "Muttaki'eena 'alaihaa mutaqabileen", "translation": "Reclining on them, facing each other."}, {"ayah": 17, "translit": "Yatoofu 'alaihim wildaa num mukkhalladoon", "translation": "There will circulate among them young boys made eternal"}, {"ayah": 18, "translit": "Bi akwaabinw wa abaareeq, wa kaasim mim ma'een", "translation": "With vessels, pitchers and a cup [of wine] from a flowing spring -"}, {"ayah": 19, "translit": "Laa yusadda'oona 'anhaa wa laa yunzifoon", "translation": "No headache will they have therefrom, nor will they be intoxicated -"}, {"ayah": 20, "translit": "Wa faakihatim mimmaa yatakhaiyaroon", "translation": "And fruit of what they select"}, {"ayah": 21, "translit": "Wa lahmi tairim mimmaa yashtahoon", "translation": "And the meat of fowl, from whatever they desire."}, {"ayah": 22, "translit": "Wa hoorun'een", "translation": "And [for them are] fair women with large, [beautiful] eyes,"}, {"ayah": 23, "translit": "Ka amsaalil lu'lu'il maknoon", "translation": "The likenesses of pearls well-protected,"}, {"ayah": 24, "translit": "Jazaaa'am bimaa kaanoo ya'maloon", "translation": "As reward for what they used to do."}, {"ayah": 25, "translit": "Laa yasma'oona feehaa laghwanw wa laa taaseemaa", "translation": "They will not hear therein ill speech or commission of sin -"}, {"ayah": 26, "translit": "Illaa qeelan salaaman salaamaa", "translation": "Only a saying: \"Peace, peace.\""}, {"ayah": 27, "translit": "Wa as haabul yameeni maaa as haabul Yameen", "translation": "The companions of the right - what are the companions of the right?"}, {"ayah": 28, "translit": "Fee sidrim makhdood", "translation": "[They will be] among lote trees with thorns removed"}, {"ayah": 29, "translit": "Wa talhim mandood", "translation": "And [banana] trees layered [with fruit]"}, {"ayah": 30, "translit": "Wa zillim mamdood", "translation": "And shade extended"}, {"ayah": 31, "translit": "Wa maaa'im maskoob", "translation": "And water poured out"}, {"ayah": 32, "translit": "Wa faakihatin kaseerah", "translation": "And fruit, abundant [and varied],"}, {"ayah": 33, "translit": "Laa maqtoo'atinw wa laa mamnoo'ah", "translation": "Neither limited [to season] nor forbidden,"}, {"ayah": 34, "translit": "Wa furushim marfoo'ah", "translation": "And [upon] beds raised high."}, {"ayah": 35, "translit": "Innaaa anshaanaahunna inshaaa'aa", "translation": "Indeed, We have produced the women of Paradise in a [new] creation"}, {"ayah": 36, "translit": "Faja'alnaahunna abkaaraa", "translation": "And made them virgins,"}, {"ayah": 37, "translit": "'Uruban atraabaa", "translation": "Devoted [to their husbands] and of equal age,"}, {"ayah": 38, "translit": "Li as haabil yameen", "translation": "For the companions of the right [who are]"}, {"ayah": 39, "translit": "Sullatum minal awwa leen", "translation": "A company of the former peoples"}, {"ayah": 40, "translit": "Wa sullatum minal aakhireen", "translation": "And a company of the later peoples."}, {"ayah": 41, "translit": "Wa as haabush shimaali maaa as haabush shimaal", "translation": "And the companions of the left - what are the companions of the left?"}, {"ayah": 42, "translit": "Fee samoominw wa hameem", "translation": "[They will be] in scorching fire and scalding water"}, {"ayah": 43, "translit": "Wa zillim miny yahmoom", "translation": "And a shade of black smoke,"}, {"ayah": 44, "translit": "Laa baaridinw wa laa kareem", "translation": "Neither cool nor beneficial."}, {"ayah": 45, "translit": "Innaahum kaanoo qabla zaalika mutrafeen", "translation": "Indeed they were, before that, indulging in affluence,"}, {"ayah": 46, "translit": "Wa kaanoo yusirroona 'alal hinsil 'azeem", "translation": "And they used to persist in the great violation,"}, {"ayah": 47, "translit": "Wa kaanoo yaqooloona a'izaa mitnaa wa kunnaa turaabanw wa izaaman'ainnaa lamab'oosoon", "translation": "And they used to say, \"When we die and become dust and bones, are we indeed to be resurrected?"}, {"ayah": 48, "translit": "Awa aabaaa'unal awwaloon", "translation": "And our forefathers [as well]?\""}, {"ayah": 49, "translit": "Qul innal awwaleena wal aakhireen", "translation": "Say, [O Muhammad], \"Indeed, the former and the later peoples"}, {"ayah": 50, "translit": "Lamajmoo'oona ilaa meeqaati yawmim ma'loom", "translation": "Are to be gathered together for the appointment of a known Day.\""}, {"ayah": 51, "translit": "summa innakum ayyuhad daaalloonal mukazziboon", "translation": "Then indeed you, O those astray [who are] deniers,"}, {"ayah": 52, "translit": "La aakiloona min shaja rim min zaqqoom", "translation": "Will be eating from trees of zaqqum"}, {"ayah": 53, "translit": "Famaali'oona minhal butoon", "translation": "And filling with it your bellies"}, {"ayah": 54, "translit": "Fashaariboona 'alaihi minal hameem", "translation": "And drinking on top of it from scalding water"}, {"ayah": 55, "translit": "Fashaariboona shurbal heem", "translation": "And will drink as the drinking of thirsty camels."}, {"ayah": 56, "translit": "Haazaa nuzuluhum yawmad deen", "translation": "That is their accommodation on the Day of Recompense."}, {"ayah": 57, "translit": "Nahnu khalaqnaakum falaw laa tusaddiqoon", "translation": "We have created you, so why do you not believe?"}, {"ayah": 58, "translit": "Afara'aytum maa tumnoon", "translation": "Have you seen that which you emit?"}, {"ayah": 59, "translit": "'A-antum takhluqoo nahooo am nahnul khaaliqoon", "translation": "Is it you who creates it, or are We the Creator?"}, {"ayah": 60, "translit": "Nahnu qaddarnaa baina kumul mawta wa maa nahnu bimasbooqeen", "translation": "We have decreed death among you, and We are not to be outdone"}, {"ayah": 61, "translit": "'Alaaa an nubaddila amsaalakum wa nunshi'akum fee maa laa ta'lamoon", "translation": "In that We will change your likenesses and produce you in that [form] which you do not know."}, {"ayah": 62, "translit": "Wa laqad 'alimtumun nash atal oolaa falaw laa tazakkaroon", "translation": "And you have already known the first creation, so will you not remember?"}, {"ayah": 63, "translit": "Afara'aytum maa tahrusoon", "translation": "And have you seen that [seed] which you sow?"}, {"ayah": 64, "translit": "'A-antum tazra'oonahooo am nahnuz zaari'ooon", "translation": "Is it you who makes it grow, or are We the grower?"}, {"ayah": 65, "translit": "Law nashaaa'u laja'al naahu hutaaman fazaltum tafakkahoon", "translation": "If We willed, We could make it [dry] debris, and you would remain in wonder,"}, {"ayah": 66, "translit": "Innaa lamughramoon", "translation": "[Saying], \"Indeed, we are [now] in debt;"}, {"ayah": 67, "translit": "Bal nahnu mahroomoon", "translation": "Rather, we have been deprived.\""}, {"ayah": 68, "translit": "Afara'aytumul maaa'allazee tashraboon", "translation": "And have you seen the water that you drink?"}, {"ayah": 69, "translit": "'A-antum anzaltumoohu minal muzni am nahnul munziloon", "translation": "Is it you who brought it down from the clouds, or is it We who bring it down?"}, {"ayah": 70, "translit": "Law nashaaa'u ja'alnaahu ujaajan falaw laa tashkuroon", "translation": "If We willed, We could make it bitter, so why are you not grateful?"}, {"ayah": 71, "translit": "Afara'aytumun naaral latee tooroon", "translation": "And have you seen the fire that you ignite?"}, {"ayah": 72, "translit": "'A-antum anshaatum shajaratahaaa am nahnul munshi'oon", "translation": "Is it you who produced its tree, or are We the producer?"}, {"ayah": 73, "translit": "Nahnu ja'alnaahaa tazkira tanw wa mataa'al lilmuqween", "translation": "We have made it a reminder and provision for the travelers,"}, {"ayah": 74, "translit": "Fasabbih bismi Rabbikal 'azeem", "translation": "So exalt the name of your Lord, the Most Great."}, {"ayah": 75, "translit": "Falaa uqsimu bimaawaa qi'innujoom", "translation": "Then I swear by the setting of the stars,"}, {"ayah": 76, "translit": "Wa innahoo laqasamul lawta'lamoona'azeem", "translation": "And indeed, it is an oath - if you could know - [most] great."}, {"ayah": 77, "translit": "Innahoo la quraanun kareem", "translation": "Indeed, it is a noble Qur'an"}, {"ayah": 78, "translit": "Fee kitaabim maknoon", "translation": "In a Register well-protected;"}, {"ayah": 79, "translit": "Laa yamassuhooo illal mutahharoon", "translation": "None touch it except the purified."}, {"ayah": 80, "translit": "Tanzeelum mir Rabbil'aalameen", "translation": "[It is] a revelation from the Lord of the worlds."}, {"ayah": 81, "translit": "Afabihaazal hadeesi antum mudhinoon", "translation": "Then is it to this statement that you are indifferent"}, {"ayah": 82, "translit": "Wa taj'aloona rizqakum annakum tukazziboon", "translation": "And make [the thanks for] your provision that you deny [the Provider]?"}, {"ayah": 83, "translit": "Falaw laaa izaa balaghatil hulqoom", "translation": "Then why, when the soul at death reaches the throat"}, {"ayah": 84, "translit": "Wa antum heena'izin tanzuroon", "translation": "And you are at that time looking on -"}, {"ayah": 85, "translit": "Wa nahnu aqrabu ilaihi minkum wa laakil laa tubsiroon", "translation": "And Our angels are nearer to him than you, but you do not see -"}, {"ayah": 86, "translit": "Falaw laaa in kuntum ghaira madeeneen", "translation": "Then why do you not, if you are not to be recompensed,"}, {"ayah": 87, "translit": "Tarji'oonahaaa in kuntum saadiqeen", "translation": "Bring it back, if you should be truthful?"}, {"ayah": 88, "translit": "Fa ammaaa in kaana minal muqarrabeen", "translation": "And if the deceased was of those brought near to Allah,"}, {"ayah": 89, "translit": "Farawhunw wa raihaa nunw wa jannatu na'eem", "translation": "Then [for him is] rest and bounty and a garden of pleasure."}, {"ayah": 90, "translit": "Wa ammaaa in kaana min as haabil yameen", "translation": "And if he was of the companions of the right,"}, {"ayah": 91, "translit": "Fasalaamul laka min as haabil yameen", "translation": "Then [the angels will say], \"Peace for you; [you are] from the companions of the right.\""}, {"ayah": 92, "translit": "Wa ammaaa in kaana minal mukazzibeenad daaalleen", "translation": "But if he was of the deniers [who were] astray,"}, {"ayah": 93, "translit": "Fanuzulum min hameem", "translation": "Then [for him is] accommodation of scalding water"}, {"ayah": 94, "translit": "Wa tasliyatu jaheem", "translation": "And burning in Hellfire"}, {"ayah": 95, "translit": "Inna haaza lahuwa haqqul yaqeen", "translation": "Indeed, this is the true certainty,"}, {"ayah": 96, "translit": "Fasabbih bismi rabbikal 'azeem", "translation": "So exalt the name of your Lord, the Most Great."}]}, {"num": 57, "name": "Al-Hadid", "meaning": "The Iron", "verses": [{"ayah": 1, "translit": "Sabbaha lillaahi maa fissamaawaati wal ardi wa Huwal 'Azeezul Hakeem", "translation": "Whatever is in the heavens and earth exalts Allah, and He is the Exalted in Might, the Wise."}, {"ayah": 2, "translit": "Lahoo mulkus samaawaati wal ardi yuhyee wa yumeetu wa Huwa 'alaa kulli shai'in Qadeer", "translation": "His is the dominion of the heavens and earth. He gives life and causes death, and He is over all things competent."}, {"ayah": 3, "translit": "Huwal Awwalu wal'Aakhiru waz Zaahiru wal Baatinu wa huwa bikulli shai'in Aleem", "translation": "He is the First and the Last, the Ascendant and the Intimate, and He is, of all things, Knowing."}, {"ayah": 4, "translit": "Huwal lazee khalaqas samaawaati wal arda fee sittati ayyaamin summas tawaa 'alal 'Arsh; ya'lamu maa yaliju filardi wa maa yakhruju minhaa wa maa yanzilu minas samaaa'i wa maa ya'ruju feeha wa Huwa ma'akum ayna maa kuntum; wallaahu bimaa ta'maloona Baseer", "translation": "It is He who created the heavens and earth in six days and then established Himself above the Throne. He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein; and He is with you wherever you are. And Allah, of what you do, is Seeing."}, {"ayah": 5, "translit": "Lahoo mulkus samaawaati wal ard; wa ilal laahi turja'ul umoor", "translation": "His is the dominion of the heavens and earth. And to Allah are returned [all] matters."}, {"ayah": 6, "translit": "Yoolijul laila fin nahaari wa yoolijun nahaara fil lail; wa Huwa 'Aleemum bizaatis sudoor", "translation": "He causes the night to enter the day and causes the day to enter the night, and he is Knowing of that within the breasts."}, {"ayah": 7, "translit": "Aaaminoo billaahi wa Rasoolihee wa anfiqoo mimmaa ja'alakum mustakh lafeena feehi fallazeena aamanoo minkum wa anfaqoo lahum ajrun kabeer", "translation": "Believe in Allah and His Messenger and spend out of that in which He has made you successors. For those who have believed among you and spent, there will be a great reward."}, {"ayah": 8, "translit": "Wa maa lakum laa tu'minoona billaahi war Rasoolu yad'ookum lituu'minoo bi Rabbikum wa qad akhaza meesaaqakum in kuntum mu'mineen", "translation": "And why do you not believe in Allah while the Messenger invites you to believe in your Lord and He has taken your covenant, if you should [truly] be believers?"}, {"ayah": 9, "translit": "Huwal lazee yunazzilu 'alaa 'abdiheee Aayaatim baiyinaatil liyukhrijakum minaz zulumaati ilan noor; wa innal laaha bikum la Ra'oofur Raheem", "translation": "It is He who sends down upon His Servant [Muhammad] verses of clear evidence that He may bring you out from darknesses into the light. And indeed, Allah is to you Kind and Merciful."}, {"ayah": 10, "translit": "Wa maa lakum allaa tunfiqoo fee sabeelil laahi wa lillaahi meeraasus samaawaati wal-ard; laa yastawee minkum man anfaqa min qablil fat-hi wa qaatal; ulaaaika a'zamu darajatam minal lazeena anfaqoo mim ba'du wa qaataloo; wa kullanw wa'adallaahul husnaa; wallaahu bimaa ta'maloona Khabeer", "translation": "And why do you not spend in the cause of Allah while to Allah belongs the heritage of the heavens and the earth? Not equal among you are those who spent before the conquest [of Makkah] and fought [and those who did so after it]. Those are greater in degree than they who spent afterwards and fought. But to all Allah has promised the best [reward]. And Allah, with what you do, is Acquainted."}, {"ayah": 11, "translit": "man zal lazee yuqridul laaha qardan hasanan fa yudaa'ifahoo lahoo wa lahooo ajrun kareem", "translation": "Who is it that would loan Allah a goodly loan so He will multiply it for him and he will have a noble reward?"}, {"ayah": 12, "translit": "Yawma taral mu'mineena walmu'minaati yas'aa nooruhum baina aydeehim wa biaymaanihim bushraakumul yawma jannaatun tajree min tahtihal anhaaru khaalideena feeha; zaalika huwal fawzul 'azeem", "translation": "On the Day you see the believing men and believing women, their light proceeding before them and on their right, [it will be said], \"Your good tidings today are [of] gardens beneath which rivers flow, wherein you will abide eternally.\" That is what is the great attainment."}, {"ayah": 13, "translit": "Yawma yaqoolul munaa fiqoona walmunaafiqaatu lillazeena aamanun zuroonaa naqtabis min noorikum qeelarji'oo waraaa'akum faltamisoo nooran faduriba bainahum bisooril lahoo baab, baatinuhoo feehir rahmatu wa zaahiruhoo min qibalihi-'azaab", "translation": "On the [same] Day the hypocrite men and hypocrite women will say to those who believed, \"Wait for us that we may acquire some of your light.\" It will be said, \"Go back behind you and seek light.\" And a wall will be placed between them with a door, its interior containing mercy, but on the outside of it is torment."}, {"ayah": 14, "translit": "Yunaadoonahum alam nakum ma'akum qaaloo balaa wa laakinnakum fatantum anfusakum wa tarabbastum wartabtum wa gharratkumul amaaniyyu hatta jaaa'a amrul laahi wa gharrakum billaahil gharoor", "translation": "The hypocrites will call to the believers, \"Were we not with you?\" They will say, \"Yes, but you afflicted yourselves and awaited [misfortune for us] and doubted, and wishful thinking deluded you until there came the command of Allah. And the Deceiver deceived you concerning Allah."}, {"ayah": 15, "translit": "Fal Yawma laa yu'khazu minkum fidyatunw wa laa minal lazeena kafaroo; maawaakumun Naaru hiya maw laakum wa bi'sal maseer", "translation": "So today no ransom will be taken from you or from those who disbelieved. Your refuge is the Fire. It is most worthy of you, and wretched is the destination."}, {"ayah": 16, "translit": "Alam yaani laillzeena aamanooo an takhsha'a quloo buhum lizikril laahi wa maa nazala minal haqqi wa laa yakoonoo kallazeena ootul Kitaaba min qablu fataala 'alaihimul amadu faqasat quloobuhum wa kaseerum minhum faasiqoon", "translation": "Has the time not come for those who have believed that their hearts should become humbly submissive at the remembrance of Allah and what has come down of the truth? And let them not be like those who were given the Scripture before, and a long period passed over them, so their hearts hardened; and many of them are defiantly disobedient."}, {"ayah": 17, "translit": "I'lamooo annal laaha yuhyil arda ba'da mawtihaa; qad baiyannaa lakumul Aayaati la'allakum ta'qiloon", "translation": "Know that Allah gives life to the earth after its lifelessness. We have made clear to you the signs; perhaps you will understand."}, {"ayah": 18, "translit": "Innal mussaddiqeena wal mussaddiqaati wa aqradul laaha qardan hassanany yudaa'afu lahum wa lahum ajrun kareem", "translation": "Indeed, the men who practice charity and the women who practice charity and [they who] have loaned Allah a goodly loan - it will be multiplied for them, and they will have a noble reward."}, {"ayah": 19, "translit": "Wallazeena aamanoo billaahi wa Rusuliheee ulaaa'ika humus siddeeqoona wash shuhadaaa'u 'inda Rabbihim lahum ajruhum wa nooruhum wallazeena kafaroo wa kazzaboo bi aayaatinaaa ulaaaika As haabul jaheem", "translation": "And those who have believed in Allah and His messengers - those are [in the ranks of] the supporters of truth and the martyrs, with their Lord. For them is their reward and their light. But those who have disbelieved and denied Our verses - those are the companions of Hellfire."}, {"ayah": 20, "translit": "I'lamooo annamal hayaa tud dunyaa la'ibunw wa lahwunw wa zeenatunw wa takaasurun bainakum wa takaasurn fil amwaali wal awlaad, kamasali ghaisin a'jabal kuffaara nabaatuhoo summa yaheeju fataraahu musfaaran summa yakoonu hutaamaa; wa fil aakhirati 'azaabun shadeedunw wa magh firatum minal laahi wa ridwaan; wa mal haiyaa tuddun yaaa illaa mataa'ul ghuroor", "translation": "Know that the life of this world is but amusement and diversion and adornment and boasting to one another and competition in increase of wealth and children - like the example of a rain whose [resulting] plant growth pleases the tillers; then it dries and you see it turned yellow; then it becomes [scattered] debris. And in the Hereafter is severe punishment and forgiveness from Allah and approval. And what is the worldly life except the enjoyment of delusion."}, {"ayah": 21, "translit": "Saabiqooo ilaa maghfiratim mir Rabbikum wa jannatin 'arduhaa ka-'ardis samaaa'i wal ardi u'iddat lillazeena aamanoo billaahi wa Rusulih; zaalika fadlul laahi yu'teehi many yashaaa'; wal laahu zul fadlil 'azeem", "translation": "Race toward forgiveness from your Lord and a Garden whose width is like the width of the heavens and earth, prepared for those who believed in Allah and His messengers. That is the bounty of Allah which He gives to whom He wills, and Allah is the possessor of great bounty."}, {"ayah": 22, "translit": "Maaa asaaba mim musee batin fil ardi wa laa feee anfusikum illaa fee kitaabim min qabli an nabra ahaa; innaa zaalika 'alal laahi yaseer", "translation": "No disaster strikes upon the earth or among yourselves except that it is in a register before We bring it into being - indeed that, for Allah, is easy -"}, {"ayah": 23, "translit": "Likailaa taasaw 'alaa maa faatakum wa laa tafrahoo bimaaa aataakum; wallaahu laa yuhibbu kulla mukhtaalin fakhoor", "translation": "In order that you not despair over what has eluded you and not exult [in pride] over what He has given you. And Allah does not like everyone self-deluded and boastful -"}, {"ayah": 24, "translit": "Allazeeena yabkhaloona wa yaamuroonan naasa bil bukhl; wa many yatawalla fa innal laaha Huwal Ghaniyyul Hameed", "translation": "[Those] who are stingy and enjoin upon people stinginess. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy."}, {"ayah": 25, "translit": "Laqad arsalnaa Rusulanaa bilbaiyinaati wa anzalnaa ma'ahumul Kitaaba wal Meezaana liyaqooman naasu bilqist, wa anzalnal hadeeda feehi baasun shadeedunw wa manaafi'u linnaasi wa liya'lamal laahu many yansuruhoo wa Rusulahoo bilghaib; innal laaha Qawiyyn 'Azeez", "translation": "We have already sent Our messengers with clear evidences and sent down with them the Scripture and the balance that the people may maintain [their affairs] in justice. And We sent down iron, wherein is great military might and benefits for the people, and so that Allah may make evident those who support Him and His messengers unseen. Indeed, Allah is Powerful and Exalted in Might."}, {"ayah": 26, "translit": "Wa laqad arsalnaa Noohanw wa Ibraaheema wa ja'alnaa fee zurriyyatihiman nubuwwata wal Kitaaba faminhum muhtad; wa kaseerum minhum faasiqoon", "translation": "And We have already sent Noah and Abraham and placed in their descendants prophethood and scripture; and among them is he who is guided, but many of them are defiantly disobedient."}, {"ayah": 27, "translit": "Summa qaffainaa 'alaa aasaarihim bi Rusulinaa wa qaffainaa be 'Eesab ni Maryama wa aatainaahul Injeela wa ja'alnaa fee quloobil lazeenat taba' oohu raafatanw wa rahmatanw wa rahbaaniyyatanib tada' oohaa maa katanaahaa 'alaihim illab tighaaa'a ridwaanil laahi famaa ra'awhaa haqqa ri'aayatihaa fa aatainal lazeena aamanoo minhum ajrahum wa kaseerum minhum faasiqoon", "translation": "Then We sent following their footsteps Our messengers and followed [them] with Jesus, the son of Mary, and gave him the Gospel. And We placed in the hearts of those who followed him compassion and mercy and monasticism, which they innovated; We did not prescribe it for them except [that they did so] seeking the approval of Allah. But they did not observe it with due observance. So We gave the ones who believed among them their reward, but many of them are defiantly disobedient."}, {"ayah": 28, "translit": "Yaaa ayyuhal lazeena aamaanut taqullaaha wa aaminoo bi Rasoolihee yu'tikum kiflaini mir rahmatihee wa yaj'al lakum nooran tamshoona bihee wa yaghfir lakum; wallaahu Ghafoorur Raheem", "translation": "O you who have believed, fear Allah and believe in His Messenger; He will [then] give you a double portion of His mercy and make for you a light by which you will walk and forgive you; and Allah is Forgiving and Merciful."}, {"ayah": 29, "translit": "Li'alla ya'lama Ahlul kitaabi allaa yaqdiroona 'alaa shai'im min fadlil laahi wa annal fadla bi Yadil laahi u'teehi many yashaaa'; wallaahu Zul fadilil 'azeem", "translation": "[This is] so that the People of the Scripture may know that they are not able [to obtain] anything from the bounty of Allah and that [all] bounty is in the hand of Allah; He gives it to whom He wills. And Allah is the possessor of great bounty."}]}, {"num": 58, "name": "Al-Mujadila", "meaning": "The Pleading Woman", "verses": [{"ayah": 1, "translit": "Qad sami'al laahu qawlal latee tujaadiluka fee zawjihaa wa tashtakeee ilal laahi wallaahu yasma'u tahaawurakumaa; innal laaha samee'um baseer", "translation": "Certainly has Allah heard the speech of the one who argues with you, [O Muhammad], concerning her husband and directs her complaint to Allah. And Allah hears your dialogue; indeed, Allah is Hearing and Seeing."}, {"ayah": 2, "translit": "Allazeena yuzaahiroona minkum min nisaaa'ihim maa hunnaa ummahaatihim in ummahaatuhum illal laaa'ee waladnahum; wa innaahum la yaqooloona munkaram minal qawli wa zooraa; wa innal laaha la'afuwwun ghafoor", "translation": "Those who pronounce thihar among you [to separate] from their wives - they are not [consequently] their mothers. Their mothers are none but those who gave birth to them. And indeed, they are saying an objectionable statement and a falsehood. But indeed, Allah is Pardoning and Forgiving."}, {"ayah": 3, "translit": "Wallazeena yuzaahiroona min nisaaa'ihim summa ya'oodoona limaa qaaloo fatabreeru raqabatim min qabli any-yatamaaassaa; zaalikum too'azoona bih; wallaahu bimaa ta'maloona khabeer", "translation": "And those who pronounce thihar from their wives and then [wish to] go back on what they said - then [there must be] the freeing of a slave before they touch one another. That is what you are admonished thereby; and Allah is Acquainted with what you do."}, {"ayah": 4, "translit": "Famal lam yajid fa siyaamu shahraini mutataabi'ayni min qabli any-yatamaaassaa famal lam yastati' fa-it'aamu sitteena miskeena; zaalika litu'minoo billaahi wa rasoolih'wa tilka hudoodul laah; wa lilkaafireena 'azaabun aleem", "translation": "And he who does not find [a slave] - then a fast for two months consecutively before they touch one another; and he who is unable - then the feeding of sixty poor persons. That is for you to believe [completely] in Allah and His Messenger; and those are the limits [set by] Allah. And for the disbelievers is a painful punishment."}, {"ayah": 5, "translit": "Innal lazeena yuhaaaddoonal laaha wa Rasoolahoo kubitoo kamaa kubital lazeena min qablihim; wa qad anzalnaaa aayaatim baiyinaat; wa lilkaa fireena 'azaabum muheen", "translation": "Indeed, those who oppose Allah and His Messenger are abased as those before them were abased. And We have certainly sent down verses of clear evidence. And for the disbelievers is a humiliating punishment."}, {"ayah": 6, "translit": "Yawma yab'asuhumul laahu jamee'an fayunabbi'uhum bimaa 'amiloo; ahsaahul laahu wa nasooh; wallaahu 'alaa kulli shai'in shaheed", "translation": "On the Day when Allah will resurrect them all and inform them of what they did. Allah had enumerated it, while they forgot it; and Allah is, over all things, Witness."}, {"ayah": 7, "translit": "Alam tara annal laaha ya'lamu maa fis samaawaati wa maa fil ardi maa yakoonu min najwaa salaasatin illaa Huwa raabi'uhum wa laa khamsatin illaa huwa saadisuhum wa laaa adnaa min zaalika wa laaa aksara illaa huwa ma'ahum ayna, maa kaanoo summa yunabbi'uhum bimaa 'amiloo yawmal qiyaamah; innal laaha bikulli shai'in aleem", "translation": "Have you not considered that Allah knows what is in the heavens and what is on the earth? There is in no private conversation three but that He is the fourth of them, nor are there five but that He is the sixth of them - and no less than that and no more except that He is with them [in knowledge] wherever they are. Then He will inform them of what they did, on the Day of Resurrection. Indeed Allah is, of all things, Knowing."}, {"ayah": 8, "translit": "Alam tara ilal lazeena nuhoo 'anin najwaa summa ya'oodoona limaa nuhoo 'anhu wa yatanaajawna bil ismi wal'udwaani wa ma'siyatir rasooli wa izaa jaaa'ooka haiyawka bimaa lam yuhai yika bihil laahu wa yaqooloona fee anfusihim law laa yu'azzibunal laahu bimaa naqool; hasbuhum jahannnamu yaslawnahaa fabi'sal maseer", "translation": "Have you not considered those who were forbidden from private conversation, then they return to that which they were forbidden and converse among themselves about sin and aggression and disobedience to the Messenger? And when they come to you, they greet you with that [word] by which Allah does not greet you and say among themselves, \"Why does Allah not punish us for what we say?\" Sufficient for them is Hell, which they will [enter to] burn, and wretched is the destination."}, {"ayah": 9, "translit": "Yaaa ayyuhal lazeena aamanoo izaa tanaajaytum falaa tatanaajaw bil ismi wal 'udwaani wa ma'siyatir rasooli wa tanaajaw bil birri wattaqwaa wattaqul laahal lazeee ilaihi tuhsharoon", "translation": "O you who have believed, when you converse privately, do not converse about sin and aggression and disobedience to the Messenger but converse about righteousness and piety. And fear Allah, to whom you will be gathered."}, {"ayah": 10, "translit": "Innaman najwaa minash shaitaani liyahzunal lazeena aamanoo wa laisa bidaaarrihim shai'an illaa bi-iznil laah; wa 'alal laahi falyatawakkalil mu'minoon", "translation": "Private conversation is only from Satan that he may grieve those who have believed, but he will not harm them at all except by permission of Allah. And upon Allah let the believers rely."}, {"ayah": 11, "translit": "Yaaa ayyuhal lazeena aamanoo izaa qeela lakum tafassahoo fil majaalisi fafsahoo yafsahil laahu lakum wa izaa qeelan shuzoo fanshuzoo yarfa'il laahul lazeena aamanoo minkum wallazeena ootul 'ilma darajaat; wallaahu bimaa ta'maloona khabeer", "translation": "O you who have believed, when you are told, \"Space yourselves\" in assemblies, then make space; Allah will make space for you. And when you are told, \"Arise,\" then arise; Allah will raise those who have believed among you and those who were given knowledge, by degrees. And Allah is Acquainted with what you do."}, {"ayah": 12, "translit": "Yaaa ayyuhal lazeena aamanooo izaa naajitumur Rasoola faqaddimoo baina yadai najwaakum sadaqah; zaalika khairul lakum wa athar; fa il lam tajidoo fa innal laaha ghafoorur Raheem", "translation": "O you who have believed, when you [wish to] privately consult the Messenger, present before your consultation a charity. That is better for you and purer. But if you find not [the means] - then indeed, Allah is Forgiving and Merciful."}, {"ayah": 13, "translit": "'A-ashfaqtum an tuqaddimoo baina yadai najwaakum sadaqaat; fa-iz lam taf'aloo wa taabal laahu 'alaikum fa aqeemus Salaata wa aatuz Zakaata wa atee'ul laaha wa rasoolah; wallaahu khabeerum bimaa ta'maloon", "translation": "Have you feared to present before your consultation charities? Then when you do not and Allah has forgiven you, then [at least] establish prayer and give zakah and obey Allah and His Messenger. And Allah is Acquainted with what you do."}, {"ayah": 14, "translit": "Alam tara ilal lazeena tawallaw qawman ghadibal laahu 'alaihim maa hum minkum wa laa minhum wa yahlifoona 'alal kazibi wa hum ya'lamoon", "translation": "Have you not considered those who make allies of a people with whom Allah has become angry? They are neither of you nor of them, and they swear to untruth while they know [they are lying]."}, {"ayah": 15, "translit": "A'addal laahu lahum 'azaaban shadeedan innahum saaa'a maa kaanoo ya'maloon", "translation": "Allah has prepared for them a severe punishment. Indeed, it was evil that they were doing."}, {"ayah": 16, "translit": "Ittakhazooo aymaanahum junnatan fasaddoo 'an sabeelil laahi falahum 'azaabum muheen", "translation": "They took their [false] oaths as a cover, so they averted [people] from the way of Allah, and for them is a humiliating punishment."}, {"ayah": 17, "translit": "Lan tughniya 'anhum amwaaluhum wa laaa awladuhum minal laahi shai'aa; ulaaa 'ika As haabun Naari hum feehaa khaalidoon", "translation": "Never will their wealth or their children avail them against Allah at all. Those are the companions of the Fire; they will abide therein eternally"}, {"ayah": 18, "translit": "Yawma yab'asuhumul laahujamee'an fa yahlifoona lahoo kamaa yahlifoona lakum wa yahsaboona annahum 'alaa shai'; alaaa innahum humul kaaziboon", "translation": "On the Day Allah will resurrect them all, and they will swear to Him as they swear to you and think that they are [standing] on something. Unquestionably, it is they who are the liars."}, {"ayah": 19, "translit": "Istahwaza 'alaihimush shaitaanu fa ansaahum zikral laah; ulaaa'ika hizbush shaitaaan; alaaa innaa hizbash shaitaani humul khaasiroon", "translation": "Satan has overcome them and made them forget the remembrance of Allah. Those are the party of Satan. Unquestionably, the party of Satan - they will be the losers."}, {"ayah": 20, "translit": "Innal lazeena yuhaaaddoonal laaha wa Rasoolahooo ulaaa'ika fil azalleen", "translation": "Indeed, the ones who oppose Allah and His Messenger - those will be among the most humbled."}, {"ayah": 21, "translit": "Katabal laahu la aghlibanna ana wa Rusulee; innal laaha qawiyyun 'Azeez", "translation": "Allah has written, \"I will surely overcome, I and My messengers.\" Indeed, Allah is Powerful and Exalted in Might."}, {"ayah": 22, "translit": "Laa tajidu qawmany yu'minoona billaahi wal yawmil aakhiri yuwaaaddoona man haaaddal laaha wa Rasoolahoo wa law kaanooo aabaaa'ahum aw abnaaa'ahum aw ikhwaa nahum aw 'asheeratahum; ulaaa'ika kataba fee quloobihi mul eemaana wa ayyadahum biroohimminhu wa yudkhilu hum jannatin tajree min tahtihal anhaaru khaalideena feehaa; radiyal laahu 'anhum wa radoo 'anh; ulaaa 'ika hizbul laah; alaaa inna hizbal laahi humul muflihoon", "translation": "You will not find a people who believe in Allah and the Last Day having affection for those who oppose Allah and His Messenger, even if they were their fathers or their sons or their brothers or their kindred. Those - He has decreed within their hearts faith and supported them with spirit from Him. And We will admit them to gardens beneath which rivers flow, wherein they abide eternally. Allah is pleased with them, and they are pleased with Him - those are the party of Allah. Unquestionably, the party of Allah - they are the successful."}]}, {"num": 59, "name": "Al-Hashr", "meaning": "The Exile", "verses": [{"ayah": 1, "translit": "Sabbaha lillaahi maa fissamaawaati wa maa fil ardi wa Huwal 'Azeezul Hakeem", "translation": "Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise."}, {"ayah": 2, "translit": "Huwal lazeee akharajal lazeena kafaroo min ahlil kitaabi min diyaarihim li awwalil Hashr; maa zanantum any yakhrujoo wa zannooo annahum maa ni'atuhum husoonuhum minal laahi faataahumul laahu min haisu lam yahtasiboo wa qazafa fee quloobihimur ru'ba yukhriboona bu yootahum bi aydeehim wa aydil mu'mineena fa'tabiroo yaaa ulil absaar", "translation": "It is He who expelled the ones who disbelieved among the People of the Scripture from their homes at the first gathering. You did not think they would leave, and they thought that their fortresses would protect them from Allah; but [the decree of] Allah came upon them from where they had not expected, and He cast terror into their hearts [so] they destroyed their houses by their [own] hands and the hands of the believers. So take warning, O people of vision."}, {"ayah": 3, "translit": "Wa law laaa an katabal laahu 'alaihimul jalaaa'a la'azzabahum fid dunyaa wa lahum fil Aakhirati 'azaabun Naar", "translation": "And if not that Allah had decreed for them evacuation, He would have punished them in [this] world, and for them in the Hereafter is the punishment of the Fire."}, {"ayah": 4, "translit": "Zaalika bi annahum shaaqqul laaha wa Rasoolahoo wa many yushaaaqqil laaha fa innal laaha shadeedul-'iqaab", "translation": "That is because they opposed Allah and His Messenger. And whoever opposes Allah - then indeed, Allah is severe in penalty."}, {"ayah": 5, "translit": "Maa qata'tum mil leenatin aw taraktumoohaa qaaa'imatan'alaaa usoolihaa fabi iznil laahi wa liyukhziyal faasiqeen", "translation": "Whatever you have cut down of [their] palm trees or left standing on their trunks - it was by permission of Allah and so He would disgrace the defiantly disobedient."}, {"ayah": 6, "translit": "Wa maaa afaaa'al laahu 'alaaa Rasoolihee minhum famaaa awjaftum 'alaihi min khailiinw wa laa rikaabinw wa laakinnal laaha yusallitu Rusulahoo 'alaa many yashaaa'; wallaahu 'alaa kulli shai'in Qadeer", "translation": "And what Allah restored [of property] to His Messenger from them - you did not spur for it [in an expedition] any horses or camels, but Allah gives His messengers power over whom He wills, and Allah is over all things competent."}, {"ayah": 7, "translit": "Maaa afaaa'al laahu 'alaa Rasoolihee min ahlil quraa falillaahi wa lir Rasooli wa lizil qurbaa wal yataamaa walmasaakeeni wabnis sabeeli kai laa yakoona doolatam bainal aghniyaaa'i minkum; wa maaa aataakumur Rasoolu fakhuzoohu wa maa nahaakum 'anhu fantahoo; wattaqul laaha innal laaha shadeedul-'iqaab", "translation": "And what Allah restored to His Messenger from the people of the towns - it is for Allah and for the Messenger and for [his] near relatives and orphans and the [stranded] traveler - so that it will not be a perpetual distribution among the rich from among you. And whatever the Messenger has given you - take; and what he has forbidden you - refrain from. And fear Allah; indeed, Allah is severe in penalty."}, {"ayah": 8, "translit": "Lilfuqaraaa'il Muhaaji reenal lazeena ukhrijoo min diyaarihim wa amwaalihim yabtaghoona fadlam minal laahi wa ridwaananw wa yansuroonal laaha wa Rasoolah; ulaaa'ika humus saadiqoon", "translation": "For the poor emigrants who were expelled from their homes and their properties, seeking bounty from Allah and [His] approval and supporting Allah and His Messenger, [there is also a share]. Those are the truthful."}, {"ayah": 9, "translit": "Wallazeena tabawwa'ud daara wal eemaana min qablihim yuhibboona man haajara ilaihim wa laa yajidoona fee sudoorihim haajatam mimmaa ootoo wa yu'siroona 'alaa anfusihim wa law kaana bihim khasaasah; wa many yooqa shuhha nafsihee fa ulaaa'ika humul muflihoon", "translation": "And [also for] those who were settled in al-Madinah and [adopted] the faith before them. They love those who emigrated to them and find not any want in their breasts of what the emigrants were given but give [them] preference over themselves, even though they are in privation. And whoever is protected from the stinginess of his soul - it is those who will be the successful."}, {"ayah": 10, "translit": "Wallazeena jaaa'oo min ba'dihim yaqooloona Rabbanagh fir lanaa wa li ikhwaani nal lazeena sabqoonaa bil eemaani wa laa taj'al fee quloobinaa ghillalil lazeena aamanoo rabbannaaa innaka Ra'oofur Raheem", "translation": "And [there is a share for] those who came after them, saying, \"Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful.\""}, {"ayah": 11, "translit": "Alam tara ilal lazeena naafaqoo yaqooloona li ikhwaanihimul lazeena kafaroo min ahlil kitaabi la'in ukhrijtum lanakhrujanna ma'akum wa laa nutee'u feekum ahadan abadanw-wa in qootiltum lanansuran nakum wallaahu yashhadu innahum lakaaziboon", "translation": "Have you not considered those who practice hypocrisy, saying to their brothers who have disbelieved among the People of the Scripture, \"If you are expelled, we will surely leave with you, and we will not obey, in regard to you, anyone - ever; and if you are fought, we will surely aid you.\" But Allah testifies that they are liars."}, {"ayah": 12, "translit": "La'in ukhrijoo laa yakhrujoona ma'ahum wa la'in qootiloo laa yansuroonahum wa la'in nasaroohum la yuwallunnal adbaara summa laa yunsaroon", "translation": "If they are expelled, they will not leave with them, and if they are fought, they will not aid them. And [even] if they should aid them, they will surely turn their backs; then [thereafter] they will not be aided."}, {"ayah": 13, "translit": "La antum ashaddu rahbatan fee sudoorihim minal laah; zaalika bi annahum qawmul laa yafqahoon", "translation": "You [believers] are more fearful within their breasts than Allah. That is because they are a people who do not understand."}, {"ayah": 14, "translit": "Laa yuqaatiloonakum jamee'an illaa fee quram muhas sanatin aw minw waraaa'i judur; baasuhum bainahum shadeed; tahsabuhum jamee'anw-wa quloobuhum shatta; zaalika biannahum qawmul laa ya'qiloon", "translation": "They will not fight you all except within fortified cities or from behind walls. Their violence among themselves is severe. You think they are together, but their hearts are diverse. That is because they are a people who do not reason."}, {"ayah": 15, "translit": "Kamasalil lazeena min qablihim qareeban zaaqoo wabaala amrihim wa lahum 'azaabun aleem", "translation": "[Theirs is] like the example of those shortly before them: they tasted the bad consequence of their affair, and they will have a painful punishment."}, {"ayah": 16, "translit": "Kamasalish shaitaani izqaala lil insaanik fur falammaa kafara qaala innee bareee'um minka inneee akhaaful laaha rabbal 'aalameen", "translation": "[The hypocrites are] like the example of Satan when he says to man, \"Disbelieve.\" But when he disbelieves, he says, \"Indeed, I am disassociated from you. Indeed, I fear Allah, Lord of the worlds.\""}, {"ayah": 17, "translit": "Fakaana 'aaqibatahumaaa annahumaa fin naari khaalidaini feehaa; wa zaalika jazaaa'uz zaalimeen", "translation": "So the outcome for both of them is that they will be in the Fire, abiding eternally therein. And that is the recompense of the wrong-doers."}, {"ayah": 18, "translit": "Yaaa ayyuhal lazeena aamanut taqul laa; waltanzur nafsum maa qaddamat lighadiw wattaqual laah; innal laaha khabeerum bimaa ta'maloon", "translation": "O you who have believed, fear Allah. And let every soul look to what it has put forth for tomorrow - and fear Allah. Indeed, Allah is Acquainted with what you do."}, {"ayah": 19, "translit": "Wa laa takoonoo kallazeena nasul laaha fa ansaahum anfusahum; ulaaa'ika humul faasiqoon", "translation": "And be not like those who forgot Allah, so He made them forget themselves. Those are the defiantly disobedient."}, {"ayah": 20, "translit": "Laa yastaweee as-haabun naari wa ashaabul jannah; as haabul jannati humul faaa'izoon", "translation": "Not equal are the companions of the Fire and the companions of Paradise. The companions of Paradise - they are the attainers [of success]."}, {"ayah": 21, "translit": "Law anzalnaa haazal quraana 'alaa jabilil lara aytahoo khaashi'am muta saddi'am min khashiyatil laah; wa tilkal amsaalu nadribuhaa linnaasi la'allahum yatafakkaroon", "translation": "If We had sent down this Qur'an upon a mountain, you would have seen it humbled and coming apart from fear of Allah. And these examples We present to the people that perhaps they will give thought."}, {"ayah": 22, "translit": "Huwal-laahul-lazee laaa Ilaaha illaa Huwa 'Aalimul Ghaibi wash-shahaada; Huwar Rahmaanur-Raheem", "translation": "He is Allah, other than whom there is no deity, Knower of the unseen and the witnessed. He is the Entirely Merciful, the Especially Merciful."}, {"ayah": 23, "translit": "Huwal-laahul-lazee laaa Ilaaha illaa Huwal-Malikul Quddoosus-Salaamul Muminul Muhaiminul-'aAzeezul Jabbaarul-Mutakabbir; Subhaanal laahi 'Ammaa yushrikoon", "translation": "He is Allah, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Bestower of Faith, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allah above whatever they associate with Him."}, {"ayah": 24, "translit": "Huwal Laahul Khaaliqul Baari 'ul Musawwir; lahul Asmaaa'ul Husnaa; yusabbihu lahoo maa fis samaawaati wal ardi wa Huwal 'Azeezul Hakeem", "translation": "He is Allah, the Creator, the Inventor, the Fashioner; to Him belong the best names. Whatever is in the heavens and earth is exalting Him. And He is the Exalted in Might, the Wise."}]}, {"num": 60, "name": "Al-Mumtahanah", "meaning": "She That Is To Be Examined", "verses": [{"ayah": 1, "translit": "Yaa ayyuhal lazeena aamanoo laa tattakhizoo 'aduwwee wa 'aduwaakum awliyaaa'a tulqoona ilaihim bilmawaddati wa qad kafaroo bima jaaa'akum minal haqq, yukhrijoonar Rasoola wa iyyaakum an tu'minoo billaahi rabbikum in kuntum kharajtum jihaadan fee sabeelee wabtighaaa'a mardaatee; tusirroona ilaihim bilma waddati wa ana a'alamu bimaaa akhfaitum wa maaa a'lantum; wa many yaf'alhu minkum faqad dalla sawaaa'as sabeel", "translation": "O you who have believed, do not take My enemies and your enemies as allies, extending to them affection while they have disbelieved in what came to you of the truth, having driven out the Prophet and yourselves [only] because you believe in Allah, your Lord. If you have come out for jihad in My cause and seeking means to My approval, [take them not as friends]. You confide to them affection, but I am most knowing of what you have concealed and what you have declared. And whoever does it among you has certainly strayed from the soundness of the way."}, {"ayah": 2, "translit": "Iny yasqafookum yakoonoo lakum a'daaa'anw wa yabsutooo ilaikum aydiyahum wa alsinatahum bissooo'i wa waddoo law takfuroon", "translation": "If they gain dominance over you, they would be to you as enemies and extend against you their hands and their tongues with evil, and they wish you would disbelieve."}, {"ayah": 3, "translit": "Lan tanfa'akum arhaamukum wa laaa awlaadukum; yawmal qiyaamati yafsilu bainakum; wallaahu bimaa ta'maloon baseer", "translation": "Never will your relatives or your children benefit you; the Day of Resurrection He will judge between you. And Allah, of what you do, is Seeing."}, {"ayah": 4, "translit": "Qad kaanat lakum uswatun basanatun feee Ibraaheema wallazeena ma'ahoo iz qaaloo liqawmihim innaa bura'aaa'u minkum wa mimmaa ta'budoona min doonil laahi kafarnaa bikum wa badaa bainanaa wa bainakumul 'adaawatu wal baghdaaa'u abadan hattaa tu'minoo billaahi wahdahooo illaa qawla Ibraheema li abeehi la astaghfiranna laka wa maaa amliku laka minal laahi min shai; rabbanaa 'alaika tawakkalnaa wa ilaika anabnaa wa ilaikal maseer", "translation": "There has already been for you an excellent pattern in Abraham and those with him, when they said to their people, \"Indeed, we are disassociated from you and from whatever you worship other than Allah. We have denied you, and there has appeared between us and you animosity and hatred forever until you believe in Allah alone\" except for the saying of Abraham to his father, \"I will surely ask forgiveness for you, but I have not [power to do] for you anything against Allah. Our Lord, upon You we have relied, and to You we have returned, and to You is the destination."}, {"ayah": 5, "translit": "Rabbana laa taj'alnaa fitnatal lillazeena kafaroo waghfir lanaa rabbanaa innaka antal azeezul hakeem", "translation": "Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise.\""}, {"ayah": 6, "translit": "Laqad kaana lakum feehim uswatunhasanatul liman kaana yarjul laaha wal yawmal aakhir; wa many yatawalla fa innal laaha huwal ghaniyyul hameed", "translation": "There has certainly been for you in them an excellent pattern for anyone whose hope is in Allah and the Last Day. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy."}, {"ayah": 7, "translit": "Asal laahu any yaj'ala bainakum wa bainal lazeena 'aadaitum minhum mawaddah; wallahu qadeer; wallahu ghafoorur raheem", "translation": "Perhaps Allah will put, between you and those to whom you have been enemies among them, affection. And Allah is competent, and Allah is Forgiving and Merciful."}, {"ayah": 8, "translit": "Laa yanhaakumul laahu 'anil lazeena lam yuqaatilookum fid deeni wa lam yukhrijookum min diyaarikum an tabarroohum wa tuqsitooo ilaihim; innal laaha yuhibbul muqsiteen", "translation": "Allah does not forbid you from those who do not fight you because of religion and do not expel you from your homes - from being righteous toward them and acting justly toward them. Indeed, Allah loves those who act justly."}, {"ayah": 9, "translit": "Innamaa yanhaakumul laahu 'anil lazeena qaatalookum fid deeni wa akhrajookum min diyaarikum wa zaaharoo 'alaa ikhraajikum an tawallawhum; wa many yatawallahum faulaaa'ika humuz zaalimoon", "translation": "Allah only forbids you from those who fight you because of religion and expel you from your homes and aid in your expulsion - [forbids] that you make allies of them. And whoever makes allies of them, then it is those who are the wrongdoers."}, {"ayah": 10, "translit": "Yaa ayyuhal lazeena aamanoo izaa jaaa'akumul mu'minaatu muhaajiraatin famtah inoohunna Allaahu a'lamu bieemaanihinna fa in 'alimtumoohunna mu'minaatin falaa tarji'oohunna ilal kuffaar; laa hunna hillul lahum wa laa hum uahilloona lahunna wa aatoohum maa anfaqoo wa laa junaaha 'alaikum an tankihoohunna izaaa aataitumoohunna ujoorahunn; wa laa tumsikoo bi 'isamil kawaafiri was'aloo maaa anfaqtum walyas'aloo maaa anfaqoo zaalikum hukmul laahi yahkumu bainakum wallaahu 'aleemun hakeem", "translation": "O you who have believed, when the believing women come to you as emigrants, examine them. Allah is most knowing as to their faith. And if you know them to be believers, then do not return them to the disbelievers; they are not lawful [wives] for them, nor are they lawful [husbands] for them. But give the disbelievers what they have spent. And there is no blame upon you if you marry them when you have given them their due compensation. And hold not to marriage bonds with disbelieving women, but ask for what you have spent and let them ask for what they have spent. That is the judgement of Allah; He judges between you. And Allah is Knowing and Wise."}, {"ayah": 11, "translit": "Wa in faatakum shai'um min azwaajikum ilal kuffaari fa'aaqabtum fa aatul lazeena zahabat azwaajuhum misla maaa anfaqoo; wattaqul laahal lazeee antum bihee mu'minoon", "translation": "And if you have lost any of your wives to the disbelievers and you subsequently obtain [something], then give those whose wives have gone the equivalent of what they had spent. And fear Allah, in whom you are believers."}, {"ayah": 12, "translit": "Yaaa ayyuhan nabbiyyu izaa jaaa'akal mu'minaau yubaai naka 'alaaa allaa yushrikna billaahi shai 'anw wa laa yasriqna wa laa yazneena wa laa yaqtulna awlaadahunna wa laa yaateena bibuhtaaniny yaftaree nahoo baina aydeehinna wa arjulihinna wa laa ya'seenaka fee ma'roofin fabaayi'hunna wastaghfir lahunnal laaha innnal laaha ghafoorur raheem", "translation": "O Prophet, when the believing women come to you pledging to you that they will not associate anything with Allah, nor will they steal, nor will they commit unlawful sexual intercourse, nor will they kill their children, nor will they bring forth a slander they have invented between their arms and legs, nor will they disobey you in what is right - then accept their pledge and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful."}, {"ayah": 13, "translit": "Yaaa ayyuhal lazeena amanoo laa tatawallaw qawman ghadibal laahu 'alaihim qad ya'isoo minal aakhirati kamaa ya'isal kuffaaru min as haabil quboor", "translation": "O you who have believed, do not make allies of a people with whom Allah has become angry. They have despaired of [reward in] the Hereafter just as the disbelievers have despaired of [meeting] the inhabitants of the graves."}]}, {"num": 61, "name": "As-Saff", "meaning": "The Ranks", "verses": [{"ayah": 1, "translit": "Sabbaha lillaahi maa fisamaawaati wa maa fil ardi wa huwal 'Azeezul Hakeem", "translation": "Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise."}, {"ayah": 2, "translit": "Yaa ayyuhal lazeena aamanoo lima taqooloona maa laa taf'aloon", "translation": "O you who have believed, why do you say what you do not do?"}, {"ayah": 3, "translit": "Kabura maqtan 'indal laahi an taqooloo maa laa taf'aloon", "translation": "Great is hatred in the sight of Allah that you say what you do not do."}, {"ayah": 4, "translit": "Innal laaha yuhibbul lazeena yuqaatiloona fee sabeelihee saffan kaannahum bunyaanum marsoos", "translation": "Indeed, Allah loves those who fight in His cause in a row as though they are a [single] structure joined firmly."}, {"ayah": 5, "translit": "Wa iz qaala Moosa liqawmihee yaa qawmi lima tu'zoonanee wa qat ta'lamoona annee Rasoolul laahi ilaikum falammaa zaaghooo azaaghal laahu quloobahum; wallaahu laa yahdil qawmal faasiqeen", "translation": "And [mention, O Muhammad], when Moses said to his people, \"O my people, why do you harm me while you certainly know that I am the messenger of Allah to you?\" And when they deviated, Allah caused their hearts to deviate. And Allah does not guide the defiantly disobedient people."}, {"ayah": 6, "translit": "Wa iz qaala 'Eesab-nu-Mayama yaa Banee Israaa'eela innee Rasoolul laahi ilaikum musaddiqal limaa baina yadayya minat Tawraati wa mubashshiram bi Rasooliny yaatee mim ba'dis muhooo Ahmad; falammaa jaaa'ahum bil baiyinaati qaaloo haazaa sihrum mubeen", "translation": "And [mention] when Jesus, the son of Mary, said, \"O children of Israel, indeed I am the messenger of Allah to you confirming what came before me of the Torah and bringing good tidings of a messenger to come after me, whose name is Ahmad.\" But when he came to them with clear evidences, they said, \"This is obvious magic.\""}, {"ayah": 7, "translit": "Wa man azlamu mimma nif taraa 'alal laahil kaziba wa huwa yad'aaa ilal Islaam; wallaahu laa yahdil qawmaz zaalimeen", "translation": "And who is more unjust than one who invents about Allah untruth while he is being invited to Islam. And Allah does not guide the wrongdoing people."}, {"ayah": 8, "translit": "Yureedoona liyutfi'oo nooral laahi bi afwaahimim wallaahu mutimmu noorihee wa law karihal kaafiroon", "translation": "They want to extinguish the light of Allah with their mouths, but Allah will perfect His light, although the disbelievers dislike it."}, {"ayah": 9, "translit": "Huwal lazee arsala Rasoolahoo bilhudaa wa deenil haqqi liyuzhirahoo 'alad deeni kullihee wa law karihal mushrikoon", "translation": "It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion, although those who associate others with Allah dislike it."}, {"ayah": 10, "translit": "Yaaa ayyuhal lazeena aammano hal adullukum 'alaa tijaaratin tunjeekum min 'azaabin aleem", "translation": "O you who have believed, shall I guide you to a transaction that will save you from a painful punishment?"}, {"ayah": 11, "translit": "Tu'minoona billaahi wa Rasoolihee wa tujaahidoona fee sabeelil laahi bi amwaalikum wa anfusikum; zaalikum khairul lakum in kuntum ta'lamoon", "translation": "[It is that] you believe in Allah and His Messenger and strive in the cause of Allah with your wealth and your lives. That is best for you, if you should know."}, {"ayah": 12, "translit": "Yaghfir lakum zunoobakum wa yudkhilkum Jannaatin tajree min tahtihal anhaaru wa masaakina taiyibatan fee Jannaati 'Ad; zaalikal fawzul 'Azeem", "translation": "He will forgive for you your sins and admit you to gardens beneath which rivers flow and pleasant dwellings in gardens of perpetual residence. That is the great attainment."}, {"ayah": 13, "translit": "Wa ukhraa tuhibboonahaa nasrum minal laahi wa fat hun qaree; wa bashshiril mu 'mineen", "translation": "And [you will obtain] another [favor] that you love - victory from Allah and an imminent conquest; and give good tidings to the believers."}, {"ayah": 14, "translit": "Yaaa ayyuhal lazeena aamaanoo koonooo ansaaral laahi kamaa qaala 'Eesab-nu-Maryama lil Hawaariyyeena man ansaareee ilal laah; qaalal Hawaariyyoona nahnu ansaa rul laahi fa aamanat taaa'ifatum mim Bannee Israaa'eela wa kafarat taaa'ifatun fa ayyadnal lazeena aammanoo 'alaa 'aduwwihim fa asbahoo zaahireen", "translation": "O you who have believed, be supporters of Allah, as when Jesus, the son of Mary, said to the disciples, \"Who are my supporters for Allah?\" The disciples said, \"We are supporters of Allah.\" And a faction of the Children of Israel believed and a faction disbelieved. So We supported those who believed against their enemy, and they became dominant."}]}, {"num": 62, "name": "Al-Jumu'ah", "meaning": "Congregation/Friday", "verses": [{"ayah": 1, "translit": "Yusabbihu lilaahi maa fis samaawaati wa maa fil ardil Malikil Quddoosil 'Azeezil Hakeem", "translation": "Whatever is in the heavens and whatever is on the earth is exalting Allah, the Sovereign, the Pure, the Exalted in Might, the Wise."}, {"ayah": 2, "translit": "Huwal lazee ba'asa fil ummiyyeena Rasoolam min hum yatloo 'alaihim aayaatihee wa yuzakkeehim wa yu'allimuhumul Kitaaba wal Hikmata wa in kaano min qablu lafee dalaalim mubeen", "translation": "It is He who has sent among the unlettered a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book and wisdom - although they were before in clear error -"}, {"ayah": 3, "translit": "Wa aakhareena minhum lammaa yalhaqoo bihim wa huwal 'azeezul hakeem", "translation": "And [to] others of them who have not yet joined them. And He is the Exalted in Might, the Wise."}, {"ayah": 4, "translit": "Zaalika fadlul laahi yu'teehi many-yashaaa; wallaahu zul fadlil 'azeem", "translation": "That is the bounty of Allah, which He gives to whom He wills, and Allah is the possessor of great bounty."}, {"ayah": 5, "translit": "Masalul lazeena hum milut tawraata summa lam yahmiloonhaa kamasalil himaari yah milu asfaaraa; bi'sa masalul qawmil lazeena kaazzaboo bi aayaatil laah; wallaahu laa yahdil qawmazzaalimeen", "translation": "The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people."}, {"ayah": 6, "translit": "Qul yaaa ayyuhal lazeena haadoo in za'amtum annakum awliyaaa'u lilaahi min doonin naasi fatamannawul mawta in kuntum saadiqeen", "translation": "Say, \"O you who are Jews, if you claim that you are allies of Allah, excluding the [other] people, then wish for death, if you should be truthful.\""}, {"ayah": 7, "translit": "Wa laa yatamannaw nahooo abadam bimaa qaddamat aydeehim; wallaahu 'aleemum bix zaalimeen", "translation": "But they will not wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers."}, {"ayah": 8, "translit": "Qul innal mawtal lazee tafirroona minhu fa innahoo mulaaqeekum summa turaddoona ilaa 'Aalimil Ghaibi wash shahaadati fa yunabbi'ukum bimaa kuntum ta'maloon", "translation": "Say, \"Indeed, the death from which you flee - indeed, it will meet you. Then you will be returned to the Knower of the unseen and the witnessed, and He will inform you about what you used to do.\""}, {"ayah": 9, "translit": "Yaaa ayyuhal lazeena aamanoo izaa noodiya lis-Salaati miny yawmil Jumu'ati fas'aw ilaa zikril laahi wa zarul bai'; zaalikum khayrul lakum in kuntum ta'lamoon", "translation": "O you who have believed, when [the adhan] is called for the prayer on the day of Jumu'ah [Friday], then proceed to the remembrance of Allah and leave trade. That is better for you, if you only knew."}, {"ayah": 10, "translit": "Fa-izaa qudiyatis Salaatu fantashiroo fil ardi wabtaghoo min fadlil laahi wazkurul laaha kaseeral la'allakum tuflihoon", "translation": "And when the prayer has been concluded, disperse within the land and seek from the bounty of Allah, and remember Allah often that you may succeed."}, {"ayah": 11, "translit": "Wa izaa ra'aw tijaaratan aw lahwanin faddooo ilaihaa wa tarakooka qaaa'imaa; qul maa 'indal laahi khairum minal lahwi wa minat tijaarah; wallaahu khayrur raaziqeen", "translation": "But when they saw a transaction or a diversion, [O Muhammad], they rushed to it and left you standing. Say, \"What is with Allah is better than diversion and than a transaction, and Allah is the best of providers.\""}]}, {"num": 63, "name": "Al-Munafiqun", "meaning": "The Hypocrites", "verses": [{"ayah": 1, "translit": "Izaa jaaa'akal munaafiqoona qaaloo nashhadu innaka la rasoolul laah; wallaahu ya'lamu innaka la rasooluhoo wallaahu yashhadu innal munaafiqeena lakaaziboon", "translation": "When the hypocrites come to you, [O Muhammad], they say, \"We testify that you are the Messenger of Allah.\" And Allah knows that you are His Messenger, and Allah testifies that the hypocrites are liars."}, {"ayah": 2, "translit": "Ittakhazoo aymaanahum junnatan fasaddoo 'an sabeelil laah; innahum saaa'a maa kaanoo ya'maloon", "translation": "They have taken their oaths as a cover, so they averted [people] from the way of Allah. Indeed, it was evil that they were doing."}, {"ayah": 3, "translit": "Zaalika bi annahum aamanoo summa kafaroo fatubi'a 'alaa quloobihim fahum laa yafqahoon", "translation": "That is because they believed, and then they disbelieved; so their hearts were sealed over, and they do not understand."}, {"ayah": 4, "translit": "Wa izaa ra aytahum tu'jibuka ajsaamuhum wa iny yaqooloo tasma' liqawlihim kaannahum khushubum musannadah; yahsaboona kulla saihatin 'alaihim; humul 'aduwwu fahzarhum; qaatalahumul laahu annaa yu'fakoon", "translation": "And when you see them, their forms please you, and if they speak, you listen to their speech. [They are] as if they were pieces of wood propped up - they think that every shout is against them. They are the enemy, so beware of them. May Allah destroy them; how are they deluded?"}, {"ayah": 5, "translit": "Wa izaa qeela lahum ta'aalaw yastaghfir lakum rasoolul laahi lawwaw ru'oo sahum wa ra aytahum yasuddoona wa hum mustakbiroon", "translation": "And when it is said to them, \"Come, the Messenger of Allah will ask forgiveness for you,\" they turn their heads aside and you see them evading while they are arrogant."}, {"ayah": 6, "translit": "Sawaaa'un 'alaihim as taghfarta lahum am lam tastaghfir lahum lany yaghfiral laahu lahum; innal laaha laa yahdil qawmal faasiqeen", "translation": "It is all the same for them whether you ask forgiveness for them or do not ask forgiveness for them; never will Allah forgive them. Indeed, Allah does not guide the defiantly disobedient people."}, {"ayah": 7, "translit": "Humul lazeena yaqooloona laa tunfiqoo 'alaa man inda Rasoolil laahi hatta yanfaddoo; wa lillaahi khazaaa' inus samaawaati wal ardi wa laakinnal munaafiqeena la yafqahoon", "translation": "They are the ones who say, \"Do not spend on those who are with the Messenger of Allah until they disband.\" And to Allah belongs the depositories of the heavens and the earth, but the hypocrites do not understand."}, {"ayah": 8, "translit": "Yaqooloona la'ir raja'naaa ilal madeenati la yukhrijanal a'azzu minhal azall; wa lillaahil 'izzatu wa li Rasoolihee wa lilmu'mineena wa laakinnal munaafiqeena laa ya'lamoon", "translation": "They say, \"If we return to al-Madinah, the more honored [for power] will surely expel therefrom the more humble.\" And to Allah belongs [all] honor, and to His Messenger, and to the believers, but the hypocrites do not know."}, {"ayah": 9, "translit": "Yaaa ayyuhal lazeena aamanoo la tulhikum amwaalukum wa laa awlaadukum 'anzikril laah; wa mai-yaf'al zaalika fa-ulaaa'ika humul khaasiroon", "translation": "O you who have believed, let not your wealth and your children divert you from remembrance of Allah. And whoever does that - then those are the losers."}, {"ayah": 10, "translit": "Wa anifqoo mim maa razaqnaakum min qabli any-yaatiya ahadakumul mawtu fa yaqoola rabbi law laaa akhkhartaneee ilaaa ajalin qareebin fa assaddaqa wa akum minassaaliheen", "translation": "And spend [in the way of Allah] from what We have provided you before death approaches one of you and he says, \"My Lord, if only You would delay me for a brief term so I would give charity and be among the righteous.\""}, {"ayah": 11, "translit": "Wa lany yu 'akhkhiral laahu nafsan izaa jaaa'a ajaluhaa; wallaahu khabeerum bimaa ta'maloon", "translation": "But never will Allah delay a soul when its time has come. And Allah is Acquainted with what you do."}]}, {"num": 64, "name": "At-Taghabun", "meaning": "The Mutual Disillusion", "verses": [{"ayah": 1, "translit": "Yusabbihu lillaahi maa fis samaawaati wa maa fil ardi lahul mulku wa lahul hamd, wa Huwa 'alaa kulli shai 'in Qadeer", "translation": "Whatever is in the heavens and whatever is on the earth is exalting Allah. To Him belongs dominion, and to Him belongs [all] praise, and He is over all things competent."}, {"ayah": 2, "translit": "Huwal lazee khalaqakum faminkum kaafirunw wa min kum mu'min ; wallaahu bimaa ta'maloona Baseer", "translation": "It is He who created you, and among you is the disbeliever, and among you is the believer. And Allah, of what you do, is Seeing."}, {"ayah": 3, "translit": "Khalaqas samaawaati wal arda bilhaqqi wa sawwarakum fa ahsana suwarakum wa ilaihil maseer", "translation": "He created the heavens and earth in truth and formed you and perfected your forms; and to Him is the [final] destination."}, {"ayah": 4, "translit": "Ya'lamu maa fis samaawaati wal ardi wa ya'lamu maa tusirroona wa maa tu'linoon; wallaahu 'Aleemum bizaatis sudoor", "translation": "He knows what is within the heavens and earth and knows what you conceal and what you declare. And Allah is Knowing of that within the breasts."}, {"ayah": 5, "translit": "Alam yaatikum naba'ul lazeena kafaroo min qablu fazaaqoo wabaala amrihim wa lahum 'azaabun aleem", "translation": "Has there not come to you the news of those who disbelieved before? So they tasted the bad consequence of their affair, and they will have a painful punishment."}, {"ayah": 6, "translit": "Zaalika bi annahoo kaanat taateehim  Rusuluhum bilbaiyinaati faqaaloo a basharuny yahdoonanaa fakafaroo  wa tawallaw; wastaghnal laah; wallaahu ghaniyyun hameed", "translation": "That is because their messengers used to come to them with clear evidences, but they said, \"Shall human beings guide us?\" and disbelieved and turned away. And Allah dispensed [with them]; and Allah is Free of need and Praiseworthy."}, {"ayah": 7, "translit": "Za'amal lazeena kafarooo al-lany yub'asoo; qul balaa wa rabbee latub'asunna summa latunabba'unna bimaa 'amiltum; wa zaalika 'alal laahi yaseer", "translation": "Those who disbelieve have claimed that they will never be resurrected. Say, \"Yes, by my Lord, you will surely be resurrected; then you will surely be informed of what you did. And that, for Allah, is easy.\""}, {"ayah": 8, "translit": "Fa-aaminoo billaahi wa rasoolihee wannooril lazeee anzalnaa; wallaahu bima ta'maloona khabeer", "translation": "So believe in Allah and His Messenger and the Qur'an which We have sent down. And Allah is Acquainted with what you do."}, {"ayah": 9, "translit": "Ywma yajma'ukum li yawmil jam'i zaalika yawmut taghaabun; wa many-yumim billaahi wa ya'mal saalihany yukaffir 'anhu sayyi aatihee wa yudkhilhu jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa; zaalikal fawzul 'azeem", "translation": "The Day He will assemble you for the Day of Assembly - that is the Day of Deprivation. And whoever believes in Allah and does righteousness - He will remove from him his misdeeds and admit him to gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment."}, {"ayah": 10, "translit": "Wallazeena kafaroo wa kazzaboo bi aayaaatinaaa ulaaa'ika ashaabun naari khaalideena feehaa wa bi'sal maseer", "translation": "But the ones who disbelieved and denied Our verses - those are the companions of the Fire, abiding eternally therein; and wretched is the destination."}, {"ayah": 11, "translit": "Maaa asaaba mim musee batin illaa bi-iznil laah; wa many yu'mim billaahi yahdi qalbah; wallaahu bikulli shai;in Aleem", "translation": "No disaster strikes except by permission of Allah. And whoever believes in Allah - He will guide his heart. And Allah is Knowing of all things."}, {"ayah": 12, "translit": "Wa atee'ul laaha wa atee'ur Rasool; fa in tawallaitum fa innamaa 'alaa Rasoolinal balaaghul mubeen", "translation": "And obey Allah and obey the Messenger; but if you turn away - then upon Our Messenger is only [the duty of] clear notification."}, {"ayah": 13, "translit": "Allaahu laaa ilaaha illaa Hoo; wa 'alal laahi falyata wakkalil mu'minoon", "translation": "Allah - there is no deity except Him. And upon Allah let the believers rely."}, {"ayah": 14, "translit": "Yaaa ayyuhal lazeena aamanooo inna min azwaaji kum wa awlaadikum 'aduwwal lakum fahzaroohum; wa in ta'foo wa tasfahoo wa taghfiroo fa innal laaha ghafoorur Raheem", "translation": "O you who have believed, indeed, among your wives and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allah is Forgiving and Merciful."}, {"ayah": 15, "translit": "Innamaa amwaalukum wa awlaadukum fitnah; wallaahu 'indahooo ajrun 'azeem", "translation": "Your wealth and your children are but a trial, and Allah has with Him a great reward."}, {"ayah": 16, "translit": "Fattaqul laaha mastat'tum wasma'oo wa atee'oo waanfiqoo khairal li anfusikum; wa many-yooqa shuha nafsihee fa-ulaaa'ika humul muflihoon", "translation": "So fear Allah as much as you are able and listen and obey and spend [in the way of Allah]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful."}, {"ayah": 17, "translit": "In tuqridul laaha qardan hasanany yudd'ifhu lakum wa yaghfir lakum; wallaahu Shakoorun Haleem", "translation": "If you loan Allah a goodly loan, He will multiply it for you and forgive you. And Allah is Most Appreciative and Forbearing."}, {"ayah": 18, "translit": "'Aalimul-Ghaibi wash-shahaadatil 'Azeezul Hakeem", "translation": "Knower of the unseen and the witnessed, the Exalted in Might, the Wise."}]}, {"num": 65, "name": "At-Talaq", "meaning": "The Divorce", "verses": [{"ayah": 1, "translit": "Yaaa ayyuhan nabiyyu izaa tallaqtummun nisaaa'a fatalliqoohunna li'iddatihinna wa ahsul'iddata; wattaqul laaha rabbakum laa tukhri joohunna mim bu-yootihinna wa laa yakhrujna illaaa any yaateema bifaahishatim mubaiyinah; wa tilka hudoodul laah; wa many yata'adda hudoodal laahi faqad zalama nafsha; laa tadree la'allal laaha yuhdisu ba'dazaalika amraa", "translation": "O Prophet, when you [Muslims] divorce women, divorce them for [the commencement of] their waiting period and keep count of the waiting period, and fear Allah, your Lord. Do not turn them out of their [husbands'] houses, nor should they [themselves] leave [during that period] unless they are committing a clear immorality. And those are the limits [set by] Allah. And whoever transgresses the limits of Allah has certainly wronged himself. You know not; perhaps Allah will bring about after that a [different] matter."}, {"ayah": 2, "translit": "Fa izaa balaghna ajalahunna fa amsikoohunna bima'roofin aw faariqoohunna bima'roofinw wa ashhidoo zawai 'adlim minkum wa aqeemush shahaadata lillaah; zaalikum yoo'azu bihee man kaana yu'minu billaahi wal yawmil aakhir; wa many yattaqil laaha yaj'al lahoo makhrajaa", "translation": "And when they have [nearly] fulfilled their term, either retain them according to acceptable terms or part with them according to acceptable terms. And bring to witness two just men from among you and establish the testimony for [the acceptance of] Allah. That is instructed to whoever should believe in Allah and the Last day. And whoever fears Allah - He will make for him a way out"}, {"ayah": 3, "translit": "Wa yarzuqhu min haisu laa yahtasib; wa many yatawakkal 'alal laahi fahuwa husbuh; innal laaha baalighu amrih; qad ja'alal laahu likulli shai'in qadraa", "translation": "And will provide for him from where he does not expect. And whoever relies upon Allah - then He is sufficient for him. Indeed, Allah will accomplish His purpose. Allah has already set for everything a [decreed] extent."}, {"ayah": 4, "translit": "Wallaaa'ee ya'isna minal maheedi min nisaaa 'ikum inir tabtum fa'iddatuhunna salaasatu ashhurinw wallaaa'ee lam yahidn; wa ulaatul ahmaali ajaluhunna any yada'na hamlahun; wa many yattaqil laaha yaj'al lahoo min armrihee yusraa", "translation": "And those who no longer expect menstruation among your women - if you doubt, then their period is three months, and [also for] those who have not menstruated. And for those who are pregnant, their term is until they give birth. And whoever fears Allah - He will make for him of his matter ease."}, {"ayah": 5, "translit": "Zaalika amrul laahi anzalahoo ilaikum; wa many yattaqil laaha yukaffir 'anhu saiyi aatihee wa yu'zim lahoo ajraa", "translation": "That is the command of Allah, which He has sent down to you; and whoever fears Allah - He will remove for him his misdeeds and make great for him his reward."}, {"ayah": 6, "translit": "Askinoohunna min haisu sakantum minw wujdikum wa laa tudaaarroohunna litudaiyiqoo 'alaihinn; wa in kunna ulaati hamlin fa anfiqoo 'alihinna  hattaa yada'na hamlahunn; fain arda'na lakum fa aatoo hunna ujoorahunna waatamiroo bainakum bima'roofinw wa in ta'aasartum fasaturdi'u lahooo ukhraa", "translation": "Lodge them [in a section] of where you dwell out of your means and do not harm them in order to oppress them. And if they should be pregnant, then spend on them until they give birth. And if they breastfeed for you, then give them their payment and confer among yourselves in the acceptable way; but if you are in discord, then there may breastfeed for the father another woman."}, {"ayah": 7, "translit": "Liyuntiq zoo sa'atim min sa'atihee wa man qudira 'alaihi riquhoo falyunfiq mimmaaa aataahul laah; laa yukalliful laahu nafsan illaa maaa aataahaa; sa yaj'alul laahu ba'da'usriny yusraa", "translation": "Let a man of wealth spend from his wealth, and he whose provision is restricted - let him spend from what Allah has given him. Allah does not charge a soul except [according to] what He has given it. Allah will bring about, after hardship, ease."}, {"ayah": 8, "translit": "Wa ka ayyim min qaryatin 'atat 'an amri Rabbihaa wa Rusulihee fahaasabnaahaa hisaaban shadeedanw wa 'azzabnaahaa 'azaaban nukraa", "translation": "And how many a city was insolent toward the command of its Lord and His messengers, so We took it to severe account and punished it with a terrible punishment."}, {"ayah": 9, "translit": "Fazaaqat wabbala amrihaa wa kaana 'aaqibatu amrihaa khusraa", "translation": "And it tasted the bad consequence of its affair, and the outcome of its affair was loss."}, {"ayah": 10, "translit": "A'addal laahu lahum 'azaaban shadeedan fattaqul laaha yaaa ulil albaab, allazeena aammanoo; qad anzalal laahu ilaikum zikraa", "translation": "Allah has prepared for them a severe punishment; so fear Allah, O you of understanding who have believed. Allah has sent down to you the Qur'an."}, {"ayah": 11, "translit": "Rasoolany yatloo 'alaikum aayaatil laahi mubaiyinaatil liyukhrijal lazeena aamanoo wa 'amilus saalihaati minaz zulumaati ilan noor; wa many yu'mim billaahi wa ya;mal saalihany yudkhilhu jannaatin tajree min tahtihal anhaaru khaalideena feehaa abadan qad ahsanal laahu lahoo rizqqq", "translation": "[He sent] a Messenger [Muhammad] reciting to you the distinct verses of Allah that He may bring out those who believe and do righteous deeds from darknesses into the light. And whoever believes in Allah and does righteousness - He will admit him into gardens beneath which rivers flow to abide therein forever. Allah will have perfected for him a provision."}, {"ayah": 12, "translit": "Allaahul lazee khalaq Sab'a Samaawaatinw wa minal ardi mislahunna yatanazzalul amru bainahunna lita'lamooo annal laaha 'alaa kulli shai'in Qadeerunw wa annal laaha qad ahaata bikulli shai'in ilmaa", "translation": "It is Allah who has created seven heavens and of the earth, the like of them. [His] command descends among them so you may know that Allah is over all things competent and that Allah has encompassed all things in knowledge."}]}, {"num": 66, "name": "At-Tahrim", "meaning": "The Prohibition", "verses": [{"ayah": 1, "translit": "Yaaa ayyuhan nabiyyu lima tuharrimu maaa ahallal laahu laka tabtaghee mardaata azwaajik; wallaahu ghafoorur raheem", "translation": "O Prophet, why do you prohibit [yourself from] what Allah has made lawful for you, seeking the approval of your wives? And Allah is Forgiving and Merciful."}, {"ayah": 2, "translit": "Qad faradal laahu lakum tahillata aymaanikum; wallaahu mawlaakum wa huwal'aleemul hakeem", "translation": "Allah has already ordained for you [Muslims] the dissolution of your oaths. And Allah is your protector, and He is the Knowing, the Wise."}, {"ayah": 3, "translit": "Wa iz asarran nabiyyu ilaa ba'di azwaajihee hadeesan falammaa nabba at bihee wa azharahul laahu 'alaihi 'arrafa ba'dahoo wa a'rada 'am ba'din falammaa nabba ahaa bihee qaalat man amba aka haaza qaala nabba aniyal 'aleemul khabeer", "translation": "And [remember] when the Prophet confided to one of his wives a statement; and when she informed [another] of it and Allah showed it to him, he made known part of it and ignored a part. And when he informed her about it, she said, \"Who told you this?\" He said, \"I was informed by the Knowing, the Acquainted.\""}, {"ayah": 4, "translit": "In tatoobaaa ilal laahi faqad saghat quloobukumaa wa in tazaaharaa 'alihi fa innal laaha huwa mawlaahu wa jibreelu wa saalihul mu'mineen; walma laaa'ikatu ba'dazaalika zaheer", "translation": "If you two [wives] repent to Allah, [it is best], for your hearts have deviated. But if you cooperate against him - then indeed Allah is his protector, and Gabriel and the righteous of the believers and the angels, moreover, are [his] assistants."}, {"ayah": 5, "translit": "'Asaa rabbuhooo in tallaqakunna anyyubdilahooo azwaajan khairam mnkunna muslimaatim mu'minaatin qaanitaatin taaa'ibaatin 'aabidaatin saaa'ihaatin saiyibaatinw wa abkaaraa", "translation": "Perhaps his Lord, if he divorced you [all], would substitute for him wives better than you - submitting [to Allah], believing, devoutly obedient, repentant, worshipping, and traveling - [ones] previously married and virgins."}, {"ayah": 6, "translit": "Yaaa ayyuhal lazeena samanoo qooo anfusakum wa ahleekum naaranw waqoodu han naasu wal hijaaratu 'alaihaa malaaa'ikatun ghilaazun shidaadul laa ya'soonal laaha maa amarahum wa yaf'aloona maa yu'maroon", "translation": "O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allah in what He commands them but do what they are commanded."}, {"ayah": 7, "translit": "Yaaa ayyuhal lazeena kafaroo la ta'tazinul yawma innamaa tujzawna maa kuntum ta'maloon", "translation": "O you who have disbelieved, make no excuses that Day. You will only be recompensed for what you used to do."}, {"ayah": 8, "translit": "Yaaa ayyuhal lazeena aammano toobooo ilal laahi tawbatan nasoohan 'asaa rabbukum any-yukaffira 'ankum sayyi aatikum wa yudkhilakum jannaatin tajree min tahtihal anhaaru yawma laa yukhzil laahun nabiyya wallazeena aamanoo ma'ahoo nooruhum yas'aa baina aydeehim wa bi aymaanihim yaqooloona rabbanaaa atmim lanaa nooranaa waghfir lana innaka 'alaa kulli shai'in qadeer", "translation": "O you who have believed, repent to Allah with sincere repentance. Perhaps your Lord will remove from you your misdeeds and admit you into gardens beneath which rivers flow [on] the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right; they will say, \"Our Lord, perfect for us our light and forgive us. Indeed, You are over all things competent.\""}, {"ayah": 9, "translit": "yaaa ayyuuhan nabiyyu jaahidil kuffaara walmunaa-fiqeena waghluz 'alaihim; wa maawaahum jahannamu wa bi'sal maseer", "translation": "O Prophet, strive against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination."}, {"ayah": 10, "translit": "Darabal laahu masalal lillazeena kafarum ra ata Noobinw wamra ata Loot, kaanataa tahta 'abdaini min 'ibaadinaa saalihaini fakhaanataahumaa falam yughniyaa 'anhumaa minal laahi shai anw-wa qeelad khulan naara ma'ad Daakhileen", "translation": "Allah presents an example of those who disbelieved: the wife of Noah and the wife of Lot. They were under two of Our righteous servants but betrayed them, so those prophets did not avail them from Allah at all, and it was said, \"Enter the Fire with those who enter.\""}, {"ayah": 11, "translit": "Wa darabal laahu masa lal-lillazeena aamanumra ata Fir'awn; iz qaalat rabbibni lee 'indaka baitan fil jannati wa najjinee min Fir'awna wa 'amalihii wa najjinee minal qawmiz zaalimeen", "translation": "And Allah presents an example of those who believed: the wife of Pharaoh, when she said, \"My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds and save me from the wrongdoing people.\""}, {"ayah": 12, "translit": "Wa Maryamab nata 'Imraanal lateee ahsanat farjahaa fanafakhnaa feehi mir roobinaa wa saddaqat bikali maati Rabbihaa wa Kutubihee wakaanat minal qaaniteen", "translation": "And [the example of] Mary, the daughter of 'Imran, who guarded her chastity, so We blew into [her garment] through Our angel, and she believed in the words of her Lord and His scriptures and was of the devoutly obedient."}]}, {"num": 67, "name": "Al-Mulk", "meaning": "The Sovereignty", "verses": [{"ayah": 1, "translit": "Tabaarakal lazee biyadihil mulku wa huwa 'alaa kulli shai-in qadeer", "translation": "Blessed is He in whose hand is dominion, and He is over all things competent -"}, {"ayah": 2, "translit": "Allazee khalaqal mawta walhayaata liyabluwakum ayyukum ahsanu 'amalaa; wa huwal 'azeezul ghafoor", "translation": "[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -"}, {"ayah": 3, "translit": "Allazee khalaqa sab'a samaawaatin tibaaqam maa taraa fee khalqir rahmaani min tafaawutin farji'il basara hal taraa min futoor", "translation": "[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks?"}, {"ayah": 4, "translit": "Summar ji'il basara karrataini yanqalib ilaikal basaru khaasi'anw wa huwa haseer", "translation": "Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued."}, {"ayah": 5, "translit": "Wa laqad zaiyannas samaaa'ad dunyaa bimasaa beeha wa ja'alnaahaa rujoomal lish shayaateeni wa a'tadnaa lahum 'azaabas sa'eer", "translation": "And We have certainly beautified the nearest heaven with stars and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze."}, {"ayah": 6, "translit": "Wa lillazeena kafaroo bi rabbihim 'azaabu jahannama wa bi'sal maseer", "translation": "And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination."}, {"ayah": 7, "translit": "Izaaa ulqoo feehaa sami'oo lahaa shaheeqanw wa hiya tafoor", "translation": "When they are thrown into it, they hear from it a [dreadful] inhaling while it boils up."}, {"ayah": 8, "translit": "Takaadu tamayyazu minal ghaizi kullamaaa ulqiya feehaa fawjun sa alahum khazanatuhaaa alam yaatikum nazeer", "translation": "It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, \"Did there not come to you a warner?\""}, {"ayah": 9, "translit": "Qaaloo balaa qad jaaa'anaa nazeerun fakazzabnaa wa qulnaa maa nazzalal laahu min shai in in antum illaa fee dalaalin kabeer", "translation": "They will say,\" Yes, a warner had come to us, but we denied and said, 'Allah has not sent down anything. You are not but in great error.'\""}, {"ayah": 10, "translit": "Wa qaaloo law kunnaa nasma'u awna'qilu maa kunnaa feee as haabis sa'eer", "translation": "And they will say, \"If only we had been listening or reasoning, we would not be among the companions of the Blaze.\""}, {"ayah": 11, "translit": "Fa'tarafoo bizambihim fasuhqal li as haabis sa'eer", "translation": "And they will admit their sin, so [it is] alienation for the companions of the Blaze."}, {"ayah": 12, "translit": "Innal lazeena yakhshawna rabbahum bilghaibi lahum maghfiratunw wa ajrun kabeer", "translation": "Indeed, those who fear their Lord unseen will have forgiveness and great reward."}, {"ayah": 13, "translit": "Wa asirroo qawlakum awijharoo bihee innahoo 'aleemum bizaatis sudoor", "translation": "And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts."}, {"ayah": 14, "translit": "Alaa ya'lamu man khalaq wa huwal lateeful khabeer", "translation": "Does He who created not know, while He is the Subtle, the Acquainted?"}, {"ayah": 15, "translit": "Huwal lazee ja'ala lakumul arda zaloolan famshoo fee manaakibihaa wa kuloo mir rizqihee wa ilaihin nushoor", "translation": "It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection."}, {"ayah": 16, "translit": "'A-amintum man fissamaaa'i aiyakhsifa bi kumul arda fa izaa hiya tamoor", "translation": "Do you feel secure that He who [holds authority] in the heaven would not cause the earth to swallow you and suddenly it would sway?"}, {"ayah": 17, "translit": "Am amintum man fissamaaa'i ai yursila 'alaikum haasiban fasata'lamoona kaifa nazeer", "translation": "Or do you feel secure that He who [holds authority] in the heaven would not send against you a storm of stones? Then you would know how [severe] was My warning."}, {"ayah": 18, "translit": "Wa laqad kazzabal lazeena min qablihim fakaifa kaana nakeer", "translation": "And already had those before them denied, and how [terrible] was My reproach."}, {"ayah": 19, "translit": "Awalam yaraw ilat tairi fawqahum saaaffaatinw wa yaqbidn; maa yumsikuhunna illaar rahmaan; innahoo bikulli shai im baseer", "translation": "Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing."}, {"ayah": 20, "translit": "Amman haazal lazee huwa jundul lakum yansurukum min doonir rahmaan; inilkaafiroona illaa fee ghuroor", "translation": "Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion."}, {"ayah": 21, "translit": "Amman haazal lazee yarzuqukum in amsaka rizqah; bal lajjoo fee 'utuwwinw wa nufoor", "translation": "Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion."}, {"ayah": 22, "translit": "Afamai yamshee mukibban 'alaa wajhihee ahdaaa ammany yamshee sawiyyan 'alaa siratim mustaqeem", "translation": "Then is one who walks fallen on his face better guided or one who walks erect on a straight path?"}, {"ayah": 23, "translit": "Qul huwal lazee ansha akum wa ja'ala lakumus sam'a wal absaara wal af'idata qaleelam maa tashkuroon", "translation": "Say, \"It is He who has produced you and made for you hearing and vision and hearts; little are you grateful.\""}, {"ayah": 24, "translit": "Qul huwal lazee zara akum fil ardi wa ilaihi tuhsharoon", "translation": "Say, \"It is He who has multiplied you throughout the earth, and to Him you will be gathered.\""}, {"ayah": 25, "translit": "Wa yaqooloona mataa haazal wa'du in kuntum saadiqeen", "translation": "And they say, \"When is this promise, if you should be truthful?\""}, {"ayah": 26, "translit": "Qul innamal 'ilmu 'indallaahi wa innamaaa ana nazeerum mubeen", "translation": "Say, \"The knowledge is only with Allah, and I am only a clear warner.\""}, {"ayah": 27, "translit": "Falaammaa ra-awhu zulfatan seee'at wujoohul lazeena kafaroo wa qeela haazal lazee kuntum bihee tadda'oon", "translation": "But when they see it approaching, the faces of those who disbelieve will be distressed, and it will be said, \"This is that for which you used to call.\""}, {"ayah": 28, "translit": "Qul ara'aytum in ahlaka niyal laahu wa mam ma'iya aw rahimanaa famai-yujeerul kaafireena min 'azaabin aleem", "translation": "Say, [O Muhammad], \"Have you considered: whether Allah should cause my death and those with me or have mercy upon us, who can protect the disbelievers from a painful punishment?\""}, {"ayah": 29, "translit": "Qul huwar rahmaanu aamannaa bihee wa 'alaihi tawakkalnaa fasata'lamoona man huwa fee dalaalim mubeen", "translation": "Say, \"He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will [come to] know who it is that is in clear error.\""}, {"ayah": 30, "translit": "Qul ara'aytum in asbaha maaa'ukum ghawran famai yaateekum bimaaa'im ma'een", "translation": "Say, \"Have you considered: if your water was to become sunken [into the earth], then who could bring you flowing water?\""}]}, {"num": 68, "name": "Al-Qalam", "meaning": "The Pen", "verses": [{"ayah": 1, "translit": "Noon; walqalami wa maa yasturoon", "translation": "Nun. By the pen and what they inscribe,"}, {"ayah": 2, "translit": "Maa anta bini'mati Rabbika bimajnoon", "translation": "You are not, [O Muhammad], by the favor of your Lord, a madman."}, {"ayah": 3, "translit": "Wa inna laka la ajran ghaira mamnoon", "translation": "And indeed, for you is a reward uninterrupted."}, {"ayah": 4, "translit": "Wa innaka la'alaa khuluqin 'azeem", "translation": "And indeed, you are of a great moral character."}, {"ayah": 5, "translit": "Fasatubsiru wa yubsiroon", "translation": "So you will see and they will see"}, {"ayah": 6, "translit": "Bi ayyikumul maftoon", "translation": "Which of you is the afflicted [by a devil]."}, {"ayah": 7, "translit": "Innaa Rabbaka Huwa a'lamu biman dalla 'an sabeelihee wa Huwa a'lamu bilmuhtadeen", "translation": "Indeed, your Lord is most knowing of who has gone astray from His way, and He is most knowing of the [rightly] guided."}, {"ayah": 8, "translit": "Falaa tuti'il mukazzibeen", "translation": "Then do not obey the deniers."}, {"ayah": 9, "translit": "Waddoo law tudhinu fa-yudhinoon", "translation": "They wish that you would soften [in your position], so they would soften [toward you]."}, {"ayah": 10, "translit": "Wa laa tuti' kulla hallaa fim maheen", "translation": "And do not obey every worthless habitual swearer"}, {"ayah": 11, "translit": "Hammaazim mash shaaa'im binameem", "translation": "[And] scorner, going about with malicious gossip -"}, {"ayah": 12, "translit": "Mannaa'il lilkhairi mu'tadin aseem", "translation": "A preventer of good, transgressing and sinful,"}, {"ayah": 13, "translit": "'Utullim ba'da zaalika zaneem", "translation": "Cruel, moreover, and an illegitimate pretender."}, {"ayah": 14, "translit": "An kaana zaa maalinw-wa baneen", "translation": "Because he is a possessor of wealth and children,"}, {"ayah": 15, "translit": "Izaa tutlaa 'alaihi aayaatunaa qaala asaateerul awwaleen", "translation": "When Our verses are recited to him, he says, \"Legends of the former peoples.\""}, {"ayah": 16, "translit": "Sanasimuhoo 'alal khurtoom", "translation": "We will brand him upon the snout."}, {"ayah": 17, "translit": "Innaa balawnaahum kamaa balawnaaa As-haabal jannati iz 'aqsamoo la-yasri munnahaa musbiheen", "translation": "Indeed, We have tried them as We tried the companions of the garden, when they swore to cut its fruit in the [early] morning"}, {"ayah": 18, "translit": "Wa laa yastasnoon", "translation": "Without making exception."}, {"ayah": 19, "translit": "Fataafa 'alaihaa taaa'i fum mir rabbika wa hum naaa'imoon", "translation": "So there came upon the garden an affliction from your Lord while they were asleep."}, {"ayah": 20, "translit": "Fa asbahat kassareem", "translation": "And it became as though reaped."}, {"ayah": 21, "translit": "Fatanaadaw musbiheen", "translation": "And they called one another at morning,"}, {"ayah": 22, "translit": "Anighdoo 'alaa harsikum in kuntum saarimeen", "translation": "[Saying], \"Go early to your crop if you would cut the fruit.\""}, {"ayah": 23, "translit": "Fantalaqoo wa hum yatakhaafatoon", "translation": "So they set out, while lowering their voices,"}, {"ayah": 24, "translit": "Al laa yadkhulannahal yawma 'alaikum miskeen", "translation": "[Saying], \"There will surely not enter it today upon you [any] poor person.\""}, {"ayah": 25, "translit": "Wa ghadaw 'alaa hardin qaadireen", "translation": "And they went early in determination, [assuming themselves] able."}, {"ayah": 26, "translit": "Falammaa ra awhaa qaalooo innaa ladaaalloon", "translation": "But when they saw it, they said, \"Indeed, we are lost;"}, {"ayah": 27, "translit": "Bal nahnu mahroomoon", "translation": "Rather, we have been deprived.\""}, {"ayah": 28, "translit": "Qaala awsatuhum alam aqul lakum law laa tusabbihoon", "translation": "The most moderate of them said, \"Did I not say to you, 'Why do you not exalt [Allah]?' \""}, {"ayah": 29, "translit": "Qaaloo subhaana rabbinaaa innaa kunnaa zaalimeen", "translation": "They said, \"Exalted is our Lord! Indeed, we were wrongdoers.\""}, {"ayah": 30, "translit": "Fa aqbala ba'duhum 'alaa ba'diny yatalaawamoon", "translation": "Then they approached one another, blaming each other."}, {"ayah": 31, "translit": "Qaaloo yaa wailanaaa innaa kunnaa taagheen", "translation": "They said, \"O woe to us; indeed we were transgressors."}, {"ayah": 32, "translit": "'Asaa rabbunaaa any yubdilanaa khairam minhaaa innaaa ilaa rabbinaa raaghiboon", "translation": "Perhaps our Lord will substitute for us [one] better than it. Indeed, we are toward our Lord desirous.\""}, {"ayah": 33, "translit": "Kazaalikal azaab, wa la'azaabul aakhirati akbar; law kaanoo ya'lamoon", "translation": "Such is the punishment [of this world]. And the punishment of the Hereafter is greater, if they only knew."}, {"ayah": 34, "translit": "Inna lilmuttaqeena 'inda rabbihim jannaatin na'eem", "translation": "Indeed, for the righteous with their Lord are the Gardens of Pleasure."}, {"ayah": 35, "translit": "Afanaj'alul muslimeena kalmujrimeen", "translation": "Then will We treat the Muslims like the criminals?"}, {"ayah": 36, "translit": "Maa lakum kaifa tahhkumoon", "translation": "What is [the matter] with you? How do you judge?"}, {"ayah": 37, "translit": "Am lakum kitaabun feehi tadrusoon", "translation": "Or do you have a scripture in which you learn"}, {"ayah": 38, "translit": "Inna lakum feehi lamaa takhaiyaroon", "translation": "That indeed for you is whatever you choose?"}, {"ayah": 39, "translit": "Am lakum aymaanun 'alainaa baalighatun ilaa yawmil qiyaamati inna lakum lamaa tahkumoon", "translation": "Or do you have oaths [binding] upon Us, extending until the Day of Resurrection, that indeed for you is whatever you judge?"}, {"ayah": 40, "translit": "Salhum ayyuhum bizaa lika za'eem", "translation": "Ask them which of them, for that [claim], is responsible."}, {"ayah": 41, "translit": "Am lahum shurakaaa'u falyaatoo bishurakaaa 'ihim in kaanoo saadiqeen", "translation": "Or do they have partners? Then let them bring their partners, if they should be truthful."}, {"ayah": 42, "translit": "Yawma yukshafu 'am saaqinw wa yud'awna ilas sujoodi falaa yastatee'oon", "translation": "The Day the shin will be uncovered and they are invited to prostration but the disbelievers will not be able,"}, {"ayah": 43, "translit": "Khaashi'atan absaaruhum tarhaquhum zillatunw wa qad kaanoo yud'awna ilassujoodi wa hum saalimoon", "translation": "Their eyes humbled, humiliation will cover them. And they used to be invited to prostration while they were sound."}, {"ayah": 44, "translit": "Fazarnee wa many yukazzibu bihaazal hadeesi sanastad rijuhum min haisu laa ya'lamoon", "translation": "So leave Me, [O Muhammad], with [the matter of] whoever denies the Qur'an. We will progressively lead them [to punishment] from where they do not know."}, {"ayah": 45, "translit": "Wa umlee lahum; inna kaidee mateen", "translation": "And I will give them time. Indeed, My plan is firm."}, {"ayah": 46, "translit": "Am tas'aluhum ajran fahum mim maghramim musqaloon", "translation": "Or do you ask of them a payment, so they are by debt burdened down?"}, {"ayah": 47, "translit": "Am 'indahumul ghaibu fahum yaktuboon", "translation": "Or have they [knowledge of] the unseen, so they write [it] down?"}, {"ayah": 48, "translit": "Fasbir lihkmi rabbika wa laa takun kasaahibil boot; iz naadaa wa huwa makzoom", "translation": "Then be patient for the decision of your Lord, [O Muhammad], and be not like the companion of the fish when he called out while he was distressed."}, {"ayah": 49, "translit": "Law laaa an tadaara kahoo ni'matum mir rabbihee lanubiza bil'araaa'i wa huwa mazmoom", "translation": "If not that a favor from his Lord overtook him, he would have been thrown onto the naked shore while he was censured."}, {"ayah": 50, "translit": "Fajtabaahu rabbuhoo faja'alahoo minas saaliheen", "translation": "And his Lord chose him and made him of the righteous."}, {"ayah": 51, "translit": "Wa iny-yakaadul lazeena kafaroo la-yuzliqoonaka biabsaarihim lammaa saml'uz-Zikra wa yaqooloona innahoo lamajnoon", "translation": "And indeed, those who disbelieve would almost make you slip with their eyes when they hear the message, and they say, \"Indeed, he is mad.\""}, {"ayah": 52, "translit": "Wa maa huwa illaa zikrul lil'aalameen", "translation": "But it is not except a reminder to the worlds."}]}, {"num": 69, "name": "Al-Haqqah", "meaning": "The Reality", "verses": [{"ayah": 1, "translit": "Al haaaqqah", "translation": "The Inevitable Reality -"}, {"ayah": 2, "translit": "Mal haaaqqah", "translation": "What is the Inevitable Reality?"}, {"ayah": 3, "translit": "Wa maaa adraaka mal haaaqqah", "translation": "And what can make you know what is the Inevitable Reality?"}, {"ayah": 4, "translit": "Kazzabat samoodu wa 'Aadum bil qaari'ah", "translation": "Thamud and 'Aad denied the Striking Calamity."}, {"ayah": 5, "translit": "Fa-ammaa Samoodu fauhlikoo bittaaghiyah", "translation": "So as for Thamud, they were destroyed by the overpowering [blast]."}, {"ayah": 6, "translit": "Wa ammaa 'Aadun fa uhlikoo bireehin sarsarin 'aatiyah", "translation": "And as for 'Aad, they were destroyed by a screaming, violent wind"}, {"ayah": 7, "translit": "Sakhkharahaa 'alaihim sab'a la yaalinw wa samaaniyata ayyaamin husooman fataral qawma feehaa sar'aa ka annahum a'jaazu nakhlin khaawiyah", "translation": "Which Allah imposed upon them for seven nights and eight days in succession, so you would see the people therein fallen as if they were hollow trunks of palm trees."}, {"ayah": 8, "translit": "Fahal taraa lahum mim baaqiyah", "translation": "Then do you see of them any remains?"}, {"ayah": 9, "translit": "Wa jaaa'a Firawnu wa man qablahoo wal mu'tafikaatu bilhaati'ah", "translation": "And there came Pharaoh and those before him and the overturned cities with sin."}, {"ayah": 10, "translit": "Fa'ansaw Rasoola Rabbihim fa akhazahum akhzatar raabiyah", "translation": "And they disobeyed the messenger of their Lord, so He seized them with a seizure exceeding [in severity]."}, {"ayah": 11, "translit": "Innaa lammaa taghal maaa'u hamalnaakum fil jaariyah", "translation": "Indeed, when the water overflowed, We carried your ancestors in the sailing ship"}, {"ayah": 12, "translit": "Linaj'alahaa lakum tazki ratanw-wa ta'iyahaa unzununw waa'iyah", "translation": "That We might make it for you a reminder and [that] a conscious ear would be conscious of it."}, {"ayah": 13, "translit": "Fa izaa nufikha fis soori nafkhatunw waahidah", "translation": "Then when the Horn is blown with one blast"}, {"ayah": 14, "translit": "Wa humilatil ardu wal jibaalu fadukkataa dakkatanw waahidah", "translation": "And the earth and the mountains are lifted and leveled with one blow -"}, {"ayah": 15, "translit": "Fa yawma'izinw waqa'atil waaqi'ah", "translation": "Then on that Day, the Resurrection will occur,"}, {"ayah": 16, "translit": "Wanshaqqatis samaaa'u fahiya yawma 'izinw-waahiyah", "translation": "And the heaven will split [open], for that Day it is infirm."}, {"ayah": 17, "translit": "Wal malaku 'alaaa arjaaa'ihaa; wa yahmilu 'Arsha Rabbika fawqahum yawma'izin samaaniyah", "translation": "And the angels are at its edges. And there will bear the Throne of your Lord above them, that Day, eight [of them]."}, {"ayah": 18, "translit": "Yawma'izin tu'radoona laa takhfaa min kum khaafiyah", "translation": "That Day, you will be exhibited [for judgement]; not hidden among you is anything concealed."}, {"ayah": 19, "translit": "Fa ammaa man ootiya kitaabahoo biyameenihee fa yaqoolu haaa'umuq ra'oo kitaabiyah", "translation": "So as for he who is given his record in his right hand, he will say, \"Here, read my record!"}, {"ayah": 20, "translit": "Innee zannantu annee mulaaqin hisaabiyah", "translation": "Indeed, I was certain that I would be meeting my account.\""}, {"ayah": 21, "translit": "Fahuwa fee 'eeshatir raadiyah", "translation": "So he will be in a pleasant life -"}, {"ayah": 22, "translit": "Fee jannnatin 'aaliyah", "translation": "In an elevated garden,"}, {"ayah": 23, "translit": "Qutoofuhaa daaniyah", "translation": "Its [fruit] to be picked hanging near."}, {"ayah": 24, "translit": "Kuloo washraboo haneee'am bimaaa aslaftum fil ayyaamil khaliyah", "translation": "[They will be told], \"Eat and drink in satisfaction for what you put forth in the days past.\""}, {"ayah": 25, "translit": "Wa ammaa man ootiya kitaabahoo bishimaalihee fa yaqoolu yaalaitanee lam oota kitaaabiyah", "translation": "But as for he who is given his record in his left hand, he will say, \"Oh, I wish I had not been given my record"}, {"ayah": 26, "translit": "Wa lam adri maa hisaabiyah", "translation": "And had not known what is my account."}, {"ayah": 27, "translit": "Yaa laitahaa kaanatil qaadiyah", "translation": "I wish my death had been the decisive one."}, {"ayah": 28, "translit": "Maaa aghnaa 'annee maaliyah", "translation": "My wealth has not availed me."}, {"ayah": 29, "translit": "Halaka 'annee sultaaniyah", "translation": "Gone from me is my authority.\""}, {"ayah": 30, "translit": "Khuzoohu faghullooh", "translation": "[Allah will say], \"Seize him and shackle him."}, {"ayah": 31, "translit": "Summal Jaheema sallooh", "translation": "Then into Hellfire drive him."}, {"ayah": 32, "translit": "Summa fee silsilatin zar'uhaa sab'oona ziraa'an faslukooh", "translation": "Then into a chain whose length is seventy cubits insert him.\""}, {"ayah": 33, "translit": "Innahoo kaana laa yu'minubillaahil 'Azeem", "translation": "Indeed, he did not used to believe in Allah, the Most Great,"}, {"ayah": 34, "translit": "wa laa yahuddu 'alaa ta'aamil miskeen", "translation": "Nor did he encourage the feeding of the poor."}, {"ayah": 35, "translit": "Falaysa lahul yawma haahunaa hameem", "translation": "So there is not for him here this Day any devoted friend"}, {"ayah": 36, "translit": "Wa laa ta'aamun illaa min ghisleen", "translation": "Nor any food except from the discharge of wounds;"}, {"ayah": 37, "translit": "Laa yaakuluhooo illal khati'oon", "translation": "None will eat it except the sinners."}, {"ayah": 38, "translit": "Falaaa uqsimu bimaa tubsiroon", "translation": "So I swear by what you see"}, {"ayah": 39, "translit": "Wa maa laa tubsiroon", "translation": "And what you do not see"}, {"ayah": 40, "translit": "Innahoo laqawlu Rasoolin kareem", "translation": "[That] indeed, the Qur'an is the word of a noble Messenger."}, {"ayah": 41, "translit": "Wa ma huwa biqawli shaa'ir; qaleelam maa tu'minoon", "translation": "And it is not the word of a poet; little do you believe."}, {"ayah": 42, "translit": "Wa laa biqawli kaahin; qaleelam maa tazakkaroon", "translation": "Nor the word of a soothsayer; little do you remember."}, {"ayah": 43, "translit": "Tanzeelum mir rabbil 'aalameen", "translation": "[It is] a revelation from the Lord of the worlds."}, {"ayah": 44, "translit": "Wa law taqawwala 'alainaa ba'dal aqaaweel", "translation": "And if Muhammad had made up about Us some [false] sayings,"}, {"ayah": 45, "translit": "La-akhaznaa minhu bilyameen", "translation": "We would have seized him by the right hand;"}, {"ayah": 46, "translit": "Summa laqata'naa minhul wateen", "translation": "Then We would have cut from him the aorta."}, {"ayah": 47, "translit": "Famaa minkum min ahadin'anhu haajizeen", "translation": "And there is no one of you who could prevent [Us] from him."}, {"ayah": 48, "translit": "Wa innahoo latazkiratul lilmuttaqeen", "translation": "And indeed, the Qur'an is a reminder for the righteous."}, {"ayah": 49, "translit": "Wa inna lana'lamu anna minkum mukazzibeen", "translation": "And indeed, We know that among you are deniers."}, {"ayah": 50, "translit": "Wa innahu lahasratun 'alal kaafireen", "translation": "And indeed, it will be [a cause of] regret upon the disbelievers."}, {"ayah": 51, "translit": "Wa innahoo lahaqqul yaqeen", "translation": "And indeed, it is the truth of certainty."}, {"ayah": 52, "translit": "Fasbbih bismi Rabbikal 'Azeem", "translation": "So exalt the name of your Lord, the Most Great."}]}, {"num": 70, "name": "Al-Ma'arij", "meaning": "The Ascending Stairways", "verses": [{"ayah": 1, "translit": "Sa ala saaa'ilum bi'azaa binw-waaqi'", "translation": "A supplicant asked for a punishment bound to happen"}, {"ayah": 2, "translit": "Lilkaafireen laisa lahoo daafi'", "translation": "To the disbelievers; of it there is no preventer."}, {"ayah": 3, "translit": "Minal laahi zil ma'aarij", "translation": "[It is] from Allah, owner of the ways of ascent."}, {"ayah": 4, "translit": "Ta'rujul malaaa'ikatu war Roohu ilaihi fee yawmin kaana miqdaaruhoo khamseena alfa sanah", "translation": "The angels and the Spirit will ascend to Him during a Day the extent of which is fifty thousand years."}, {"ayah": 5, "translit": "Fasbir ssabran jameelaa", "translation": "So be patient with gracious patience."}, {"ayah": 6, "translit": "Inaahum yarawnahoo ba'eedaa", "translation": "Indeed, they see it [as] distant,"}, {"ayah": 7, "translit": "Wa naraahu qareebaa", "translation": "But We see it [as] near."}, {"ayah": 8, "translit": "Yawma takoonus samaaa'u kalmuhl", "translation": "On the Day the sky will be like murky oil,"}, {"ayah": 9, "translit": "Wa takoonul jibaalu kal'ihn", "translation": "And the mountains will be like wool,"}, {"ayah": 10, "translit": "Wa laa yas'alu hameemun hameemaa", "translation": "And no friend will ask [anything of] a friend,"}, {"ayah": 11, "translit": "Yubassaroonahum; ya waddul mujrimu law yaftadee min 'azaabi yawma'izim bibaneeh", "translation": "They will be shown each other. The criminal will wish that he could be ransomed from the punishment of that Day by his children"}, {"ayah": 12, "translit": "Wa saahibatihee wa akheeh", "translation": "And his wife and his brother"}, {"ayah": 13, "translit": "Wa faseelathil latee tu'weeh", "translation": "And his nearest kindred who shelter him"}, {"ayah": 14, "translit": "Wa man fil ardi jamee'an summa yunjeeh", "translation": "And whoever is on earth entirely [so] then it could save him."}, {"ayah": 15, "translit": "Kallaa innahaa lazaa", "translation": "No! Indeed, it is the Flame [of Hell],"}, {"ayah": 16, "translit": "Nazzaa'atal lishshawaa", "translation": "A remover of exteriors."}, {"ayah": 17, "translit": "Tad'oo man adbara wa tawallaa", "translation": "It invites he who turned his back [on truth] and went away [from obedience]"}, {"ayah": 18, "translit": "W jama'a fa aw'aa", "translation": "And collected [wealth] and hoarded."}, {"ayah": 19, "translit": "Innal insaana khuliqa haloo'aa", "translation": "Indeed, mankind was created anxious:"}, {"ayah": 20, "translit": "Izaa massahush sharru jazoo'aa", "translation": "When evil touches him, impatient,"}, {"ayah": 21, "translit": "Wa izaa massahul khairu manoo'aa", "translation": "And when good touches him, withholding [of it],"}, {"ayah": 22, "translit": "Illal musalleen", "translation": "Except the observers of prayer -"}, {"ayah": 23, "translit": "Allazeena hum 'alaa Salaatihim daaa'imoon", "translation": "Those who are constant in their prayer"}, {"ayah": 24, "translit": "Wallazeena feee amwaalihim haqqum ma'loom", "translation": "And those within whose wealth is a known right"}, {"ayah": 25, "translit": "Lissaaa 'ili walmahroom", "translation": "For the petitioner and the deprived -"}, {"ayah": 26, "translit": "Wallazeena yusaddiqoona bi yawmid Deen", "translation": "And those who believe in the Day of Recompense"}, {"ayah": 27, "translit": "Wallazeena hum min 'azaabi Rabbihim mushfiqoon", "translation": "And those who are fearful of the punishment of their Lord -"}, {"ayah": 28, "translit": "Inna 'azaaba Rabbihim ghairu maamoon", "translation": "Indeed, the punishment of their Lord is not that from which one is safe -"}, {"ayah": 29, "translit": "Wallazeena hum lifuroo jihim haafizoon", "translation": "And those who guard their private parts"}, {"ayah": 30, "translit": "Illaa 'alaaa azwaajihim aw maa malakat aymaanuhum fainnahum ghairu maloomeen", "translation": "Except from their wives or those their right hands possess, for indeed, they are not to be blamed -"}, {"ayah": 31, "translit": "Famanib taghaa waraaa'a zaalika fa ulaaa'ika humul 'aadoon", "translation": "But whoever seeks beyond that, then they are the transgressors -"}, {"ayah": 32, "translit": "Wallazeena hum li amaa naatihim wa 'ahdihim raa'oon", "translation": "And those who are to their trusts and promises attentive"}, {"ayah": 33, "translit": "Wallazeena hum bishahaadaatihim qaaa'imoon", "translation": "And those who are in their testimonies upright"}, {"ayah": 34, "translit": "Wallazeena hum 'alaa salaatihim yuhaafizoon", "translation": "And those who [carefully] maintain their prayer:"}, {"ayah": 35, "translit": "Ulaaa'ika fee jannaatim mukramoon", "translation": "They will be in gardens, honored."}, {"ayah": 36, "translit": "Famaa lil lazeena kafaroo qibalaka muhti'een", "translation": "So what is [the matter] with those who disbelieve, hastening [from] before you, [O Muhammad],"}, {"ayah": 37, "translit": "'Anil yameeni wa 'anish shimaali 'izeen", "translation": "[To sit] on [your] right and [your] left in separate groups?"}, {"ayah": 38, "translit": "Ayatma'u kullum ri'im minhum anyyudkhala jannata Na'eem", "translation": "Does every person among them aspire to enter a garden of pleasure?"}, {"ayah": 39, "translit": "Kallaaa innaa khalaq nahum mimmaa ya'lamoon", "translation": "No! Indeed, We have created them from that which they know."}, {"ayah": 40, "translit": "Falaaa uqsimu bi Rabbil mashaariqi wal maghaaribi innaa laqaadiroon", "translation": "So I swear by the Lord of [all] risings and settings that indeed We are able"}, {"ayah": 41, "translit": "'Alaaa an nubaddila khairam minhum wa maa Nahnu bimasbooqeen", "translation": "To replace them with better than them; and We are not to be outdone."}, {"ayah": 42, "translit": "Fazarhum yakhoodoo wa yal'aboo hattaa yulaaqoo yaw mahumul lazee yoo'adoon", "translation": "So leave them to converse vainly and amuse themselves until they meet their Day which they are promised -"}, {"ayah": 43, "translit": "Yawma yakhrujoona minal ajdaasi siraa'an ka anna hum ilaa nusubiny yoofidoon", "translation": "The Day they will emerge from the graves rapidly as if they were, toward an erected idol, hastening."}, {"ayah": 44, "translit": "Khaashi'atan absaaruhum tarhaquhum zillah; zaalikal yawmul lazee kaanoo yoo'adoon", "translation": "Their eyes humbled, humiliation will cover them. That is the Day which they had been promised."}]}, {"num": 71, "name": "Nuh", "meaning": "Noah", "verses": [{"ayah": 1, "translit": "Innaaa arsalnaa Noohan ilaa qawmihee an anzir qawmaka min qabli any yaatiyahum 'azaabun aleem", "translation": "Indeed, We sent Noah to his people, [saying], \"Warn your people before there comes to them a painful punishment.\""}, {"ayah": 2, "translit": "Qaala yaa qawmi innee lakum nazeerum mubeen", "translation": "He said, \"O my people, indeed I am to you a clear warner,"}, {"ayah": 3, "translit": "Ani'udul laaha watta qoohu wa atee'oon", "translation": "[Saying], 'Worship Allah, fear Him and obey me."}, {"ayah": 4, "translit": "Yaghfir lakum min zunoobikum wa yu'akhkhirkum ilaaa ajalim musammaa; innaa ajalal laahi izaa jaaa'a laa yu'akhkhar; law kuntum ta'lamoon", "translation": "Allah will forgive you of your sins and delay you for a specified term. Indeed, the time [set by] Allah, when it comes, will not be delayed, if you only knew.' \""}, {"ayah": 5, "translit": "Qaala rabbi innee da'awtu qawmee lailanw wa naharaa", "translation": "He said, \"My Lord, indeed I invited my people [to truth] night and day."}, {"ayah": 6, "translit": "Falam yazid hum du'aaa 'eee illaa firaaraa", "translation": "But my invitation increased them not except in flight."}, {"ayah": 7, "translit": "Wa inee kullamaa da'awtuhum litaghfira lahum ja'alooo asaabi'ahum fee aazaanihim wastaghshaw siyaabahum wa asaarroo wastakbarus tikbaaraa", "translation": "And indeed, every time I invited them that You may forgive them, they put their fingers in their ears, covered themselves with their garments, persisted, and were arrogant with [great] arrogance."}, {"ayah": 8, "translit": "Summa innee da'aw tuhum jihaara", "translation": "Then I invited them publicly."}, {"ayah": 9, "translit": "Summaa inneee a'lantu lahum wa asrartu lahum israaraa", "translation": "Then I announced to them and [also] confided to them secretly"}, {"ayah": 10, "translit": "Faqultus taghfiroo Rabakam innahoo kaana Ghaffaaraa", "translation": "And said, 'Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver."}, {"ayah": 11, "translit": "Yursilis samaaa'a 'alaikum midraaraa", "translation": "He will send [rain from] the sky upon you in [continuing] showers"}, {"ayah": 12, "translit": "Wa yumdidkum bi am waalinw wa baneena wa yaj'al lakum Jannaatinw wa yaj'al lakum anhaaraa", "translation": "And give you increase in wealth and children and provide for you gardens and provide for you rivers."}, {"ayah": 13, "translit": "Maa lakum laa tarjoona lillaahi waqaaraa", "translation": "What is [the matter] with you that you do not attribute to Allah [due] grandeur"}, {"ayah": 14, "translit": "Wa qad khalaqakum at waaraa", "translation": "While He has created you in stages?"}, {"ayah": 15, "translit": "Alam taraw kaifa khalaqal laahu sab'a samaawaatin tibaaqaa", "translation": "Do you not consider how Allah has created seven heavens in layers"}, {"ayah": 16, "translit": "Wa ja'alal qamara feehinna nooranw wa ja'alash shamsa siraajaa", "translation": "And made the moon therein a [reflected] light and made the sun a burning lamp?"}, {"ayah": 17, "translit": "Wallaahu ambatakum minal ardi nabaataa", "translation": "And Allah has caused you to grow from the earth a [progressive] growth."}, {"ayah": 18, "translit": "Summa yu'eedukum feehaa wa ukhrijukum ikhraajaa", "translation": "Then He will return you into it and extract you [another] extraction."}, {"ayah": 19, "translit": "Wallaahu ja'ala lakumul arda bisaataa", "translation": "And Allah has made for you the earth an expanse"}, {"ayah": 20, "translit": "Litaslukoo minhaa subulan fijaajaa", "translation": "That you may follow therein roads of passage.' \""}, {"ayah": 21, "translit": "Qaala Noohur Robbi innahum 'asawnee wattaba'oo mal lam yazid hu maaluhoo wa waladuhooo illaa khasaara", "translation": "Noah said, \"My Lord, indeed they have disobeyed me and followed him whose wealth and children will not increase him except in loss."}, {"ayah": 22, "translit": "Wa makaroo makran kubbaaraa", "translation": "And they conspired an immense conspiracy."}, {"ayah": 23, "translit": "Wa qaaloo laa tazarunna aalihatakum wa laa tazarunna Waddanw wa laa Suwaa'anw wa laa Yaghoosa wa Ya'ooqa wa Nasraa", "translation": "And said, 'Never leave your gods and never leave Wadd or Suwa' or Yaghuth and Ya'uq and Nasr."}, {"ayah": 24, "translit": "Wa qad adalloo kasee ranw wa laa tazidiz zaalimeena illaa dalaalaa", "translation": "And already they have misled many. And, [my Lord], do not increase the wrongdoers except in error.\""}, {"ayah": 25, "translit": "Mimmaa khateee' aatihim ughriqoo fa udkhiloo Naaran falam yajidoo lahum min doonil laahi ansaaraa", "translation": "Because of their sins they were drowned and put into the Fire, and they found not for themselves besides Allah [any] helpers."}, {"ayah": 26, "translit": "Wa qaala Noohur Rabbi laa tazar 'alal ardi minal kaafireena daiyaaraa", "translation": "And Noah said, \"My Lord, do not leave upon the earth from among the disbelievers an inhabitant."}, {"ayah": 27, "translit": "Innaka in tazarhum yudil loo 'ibaadaka wa laa yalidooo illaa faajiran kaffaaraa", "translation": "Indeed, if You leave them, they will mislead Your servants and not beget except [every] wicked one and [confirmed] disbeliever."}, {"ayah": 28, "translit": "Rabbigh fir lee wa liwaa lidaiya wa liman dakhala baitiya mu'minanw wa lil mu'mineena wal mu'minaati wa laa tazidiz zaalimeena illaa tabaaraa", "translation": "My Lord, forgive me and my parents and whoever enters my house a believer and the believing men and believing women. And do not increase the wrongdoers except in destruction.\""}]}, {"num": 72, "name": "Al-Jinn", "meaning": "The Jinn", "verses": [{"ayah": 1, "translit": "Qul oohiya ilaiya annna hustama'a nafarum minal jinnni faqaalooo innaa sami'naa quraanan 'ajabaa", "translation": "Say, [O Muhammad], \"It has been revealed to me that a group of the jinn listened and said, 'Indeed, we have heard an amazing Qur'an."}, {"ayah": 2, "translit": "Yahdeee ilar rushdi fa aamannaa bihee wa lan nushrika bi rabbinaaa ahadaa", "translation": "It guides to the right course, and we have believed in it. And we will never associate with our Lord anyone."}, {"ayah": 3, "translit": "Wa annahoo Ta'aalaa jaddu Rabbinaa mat takhaza saahibatanw wa la waladaa", "translation": "And [it teaches] that exalted is the nobleness of our Lord; He has not taken a wife or a son"}, {"ayah": 4, "translit": "Wa annahoo kaana yaqoolu safeehunaa 'alal laahi shatataa", "translation": "And that our foolish one has been saying about Allah an excessive transgression."}, {"ayah": 5, "translit": "Wa annaa zanannaaa al lan taqoolal insu wal jinnu 'alal laahi kazibaa", "translation": "And we had thought that mankind and the jinn would never speak about Allah a lie."}, {"ayah": 6, "translit": "Wa annahoo kaana rijaa lum minal insi ya'oozoona birijaalim minal jinni fazaa doohum rahaqaa", "translation": "And there were men from mankind who sought refuge in men from the jinn, so they [only] increased them in burden."}, {"ayah": 7, "translit": "Wa annahum zannoo kamaa zanantum al lany yab'asal laahu ahadaa", "translation": "And they had thought, as you thought, that Allah would never send anyone [as a messenger]."}, {"ayah": 8, "translit": "Wa annaa lamasnas sa maaa'a fa wajadnaahaa muli'at harasan shadeedanw wa shuhubaa", "translation": "And we have sought [to reach] the heaven but found it filled with powerful guards and burning flames."}, {"ayah": 9, "translit": "Wa annaa kunnaa naq'udu minhaa maqaa'ida lis'sam'i famany yastami'il aana yajid lahoo shihaabar rasada", "translation": "And we used to sit therein in positions for hearing, but whoever listens now will find a burning flame lying in wait for him."}, {"ayah": 10, "translit": "Wa annaa laa nadreee asharrun ureeda biman fil ardi am araada bihim rabbuhum rashadaa", "translation": "And we do not know [therefore] whether evil is intended for those on earth or whether their Lord intends for them a right course."}, {"ayah": 11, "translit": "Wa annaa minnas saalihoona wa minnaa doona zaalika kunnaa taraaa'ilqa qidadaa", "translation": "And among us are the righteous, and among us are [others] not so; we were [of] divided ways."}, {"ayah": 12, "translit": "Wa annaa zanannaaa al lan nu'jizal laaha fil ardi wa lan nu'jizahoo harabaa", "translation": "And we have become certain that we will never cause failure to Allah upon earth, nor can we escape Him by flight."}, {"ayah": 13, "translit": "Wa annaa lammaa sami'nal hudaaa aamannaa bihee famany yu'mim bi rabbihee falaa yakhaafu bakhsanw wa laa rahaqaa", "translation": "And when we heard the guidance, we believed in it. And whoever believes in his Lord will not fear deprivation or burden."}, {"ayah": 14, "translit": "Wa annaa minnal muslimoona wa minnal qaasitoona faman aslama fa ulaaa'ika taharraw rashadaa", "translation": "And among us are Muslims [in submission to Allah], and among us are the unjust. And whoever has become Muslim - those have sought out the right course."}, {"ayah": 15, "translit": "Wa ammal qaasitoona fa kaanoo li jahannama hatabaa", "translation": "But as for the unjust, they will be, for Hell, firewood.'"}, {"ayah": 16, "translit": "Wa alla wis taqaamoo 'alat tareeqati la asqaynaahum maa'an ghadaqaa", "translation": "And [Allah revealed] that if they had remained straight on the way, We would have given them abundant provision"}, {"ayah": 17, "translit": "Linaftinahum feeh; wa many yu'rid 'an zikri rabbihee yasluk hu 'azaaban sa'adaa", "translation": "So We might test them therein. And whoever turns away from the remembrance of his Lord He will put into arduous punishment."}, {"ayah": 18, "translit": "Wa annal masaajida lillaahi falaa tad'oo ma'al laahi ahadaa", "translation": "And [He revealed] that the masjids are for Allah, so do not invoke with Allah anyone."}, {"ayah": 19, "translit": "Wa annahoo lammaa qaama 'adul laahi yad'oohu kaadoo yakoonoona 'alaihi libadaa", "translation": "And that when the Servant of Allah stood up supplicating Him, they almost became about him a compacted mass.\""}, {"ayah": 20, "translit": "Qul innamaaa ad'oo rabbee wa laaa ushriku biheee ahadaa", "translation": "Say, [O Muhammad], \"I only invoke my Lord and do not associate with Him anyone.\""}, {"ayah": 21, "translit": "Qul innee laaa amliku lakum darranw wa laa rashadaa", "translation": "Say, \"Indeed, I do not possess for you [the power of] harm or right direction.\""}, {"ayah": 22, "translit": "Qul innee lany yujeeranee minal laahi ahad, wa lan ajida min doonihee multahadaa", "translation": "Say, \"Indeed, there will never protect me from Allah anyone [if I should disobey], nor will I find in other than Him a refuge."}, {"ayah": 23, "translit": "Illaa balaagham minal laahi wa risaalaatih; wa many ya'sil laaha wa rasoolahoo fa inna lahoo naara jahannama khaalideena feehaaa abadaa", "translation": "But [I have for you] only notification from Allah, and His messages.\" And whoever disobeys Allah and His Messenger - then indeed, for him is the fire of Hell; they will abide therein forever."}, {"ayah": 24, "translit": "Hattaaa izaa ra aw maa yoo'adoona fasaya'lamoona man ad'afu naasiranw wa aqallu 'adadaa", "translation": "[The disbelievers continue] until, when they see that which they are promised, then they will know who is weaker in helpers and less in number."}, {"ayah": 25, "translit": "Qul in adreee a qareebum maa too'adoona am yaj'alu lahoo rabbeee amadaa", "translation": "Say, \"I do not know if what you are promised is near or if my Lord will grant for it a [long] period.\""}, {"ayah": 26, "translit": "'Aalimul ghaibi falaa yuzhiru alaa ghaibiheee ahadaa", "translation": "[He is] Knower of the unseen, and He does not disclose His [knowledge of the] unseen to anyone"}, {"ayah": 27, "translit": "Illaa manir tadaa mir rasoolin fa innahoo yasluku mim baini yadihi wa min khalfihee rasadaa", "translation": "Except whom He has approved of messengers, and indeed, He sends before each messenger and behind him observers"}, {"ayah": 28, "translit": "Liya'lama an qad ablaghoo risaalaati rabbihim wa ahaata bima ladihim wa ahsaa kulla shai'in 'adadaa", "translation": "That he may know that they have conveyed the messages of their Lord; and He has encompassed whatever is with them and has enumerated all things in number."}]}, {"num": 73, "name": "Al-Muzzammil", "meaning": "The Enshrouded One", "verses": [{"ayah": 1, "translit": "Ya aiyuhal muzzammil", "translation": "O you who wraps himself [in clothing],"}, {"ayah": 2, "translit": "Qumil laila illaa qaleelaa", "translation": "Arise [to pray] the night, except for a little -"}, {"ayah": 3, "translit": "Nisfahooo awinqus minhu qaleelaa", "translation": "Half of it - or subtract from it a little"}, {"ayah": 4, "translit": "Aw zid 'alaihi wa rattilil Qur'aana tarteela", "translation": "Or add to it, and recite the Qur'an with measured recitation."}, {"ayah": 5, "translit": "Innaa sanulqee 'alika qawalan saqeelaa", "translation": "Indeed, We will cast upon you a heavy word."}, {"ayah": 6, "translit": "Inn naashi'atal laili hiya ashadddu wat anw wa aqwamu qeelaa", "translation": "Indeed, the hours of the night are more effective for concurrence [of heart and tongue] and more suitable for words."}, {"ayah": 7, "translit": "Inna laka fin nahaari sabhan taweelaa", "translation": "Indeed, for you by day is prolonged occupation."}, {"ayah": 8, "translit": "Wazkuris ma rabbika wa tabattal ilaihi tabteelaa", "translation": "And remember the name of your Lord and devote yourself to Him with [complete] devotion."}, {"ayah": 9, "translit": "Rabbul mashriqi wal maghriibi laaa ilaaha illaa Huwa fattakhizhu wakeelaa", "translation": "[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs."}, {"ayah": 10, "translit": "Wasbir 'alaa maa yaqoo loona wahjurhum hajran jameelaa", "translation": "And be patient over what they say and avoid them with gracious avoidance."}, {"ayah": 11, "translit": "Wa zarnee walmukaz zibeena ulin na'mati wa mahhilhum qaleelaa", "translation": "And leave Me with [the matter of] the deniers, those of ease [in life], and allow them respite a little."}, {"ayah": 12, "translit": "Inna ladainaaa ankaalanw wa jaheemaa", "translation": "Indeed, with Us [for them] are shackles and burning fire"}, {"ayah": 13, "translit": "Wa ta'aaman zaa ghussa tinw wa'azaaban aleemaa", "translation": "And food that chokes and a painful punishment -"}, {"ayah": 14, "translit": "Yawma tarjuful ardu waljibaalu wa kaanatil jibaalu kaseebam maheelaa", "translation": "On the Day the earth and the mountains will convulse and the mountains will become a heap of sand pouring down."}, {"ayah": 15, "translit": "Innaa arsalnaaa ilaikum rasoolan shahidan 'alikum kamaaa arsalnaaa ilaa Fir'awna Rasoolna", "translation": "Indeed, We have sent to you a Messenger as a witness upon you just as We sent to Pharaoh a messenger."}, {"ayah": 16, "translit": "Fa'asaa Fir'awnur Rasoola fa akhaznaahu akhzanw wabeelaa", "translation": "But Pharaoh disobeyed the messenger, so We seized him with a ruinous seizure."}, {"ayah": 17, "translit": "Fakaifa tattaqoona in kafartum yawmany yaj'alul wildaana sheeba", "translation": "Then how can you fear, if you disbelieve, a Day that will make the children white- haired?"}, {"ayah": 18, "translit": "Assamaaa'u munfatirum bih; kaana wa'duhoo maf'oola", "translation": "The heaven will break apart therefrom; ever is His promise fulfilled."}, {"ayah": 19, "translit": "Inna haazihee tazkiratun fa man shaaa'at takhaza ilaa Rabbihee sabeelaa", "translation": "Indeed, this is a reminder, so whoever wills may take to his Lord a way."}, {"ayah": 20, "translit": "Inna Rabbaka ya'lamu annaka taqoomu adnaa min sulusa yil laili wa nisfahoo wa sulusahoo wa taaa'ifatum minal lazeena ma'ak; wal laahu yuqaddirul laila wanna haar; 'alima al lan tuhsoohu fataaba  'alaikum faqra'oo maa tayassara minal quraan; 'alima an sa yakoonu minkum mardaa wa aakharoona yadriboona fil ardi yabtaghoona min fadlil laahi wa aakharoona yuqaatiloona fee sabeelil laahi faqra'oo ma tayassara minhu wa aqeemus salaata wa aatuz zakaata wa aqridul laaha qardan hasanaa; wa maa tuqadimoo li anfusikum min khairin tajidoohu 'indal laahi huwa khayranw wa a'zama ajraa; wastaghfirul laahaa innal laaha ghafoorur raheem.", "translation": "Indeed, your Lord knows, [O Muhammad], that you stand [in prayer] almost two thirds of the night or half of it or a third of it, and [so do] a group of those with you. And Allah determines [the extent of] the night and the day. He has known that you [Muslims] will not be able to do it and has turned to you in forgiveness, so recite what is easy [for you] of the Qur'an. He has known that there will be among you those who are ill and others traveling throughout the land seeking [something] of the bounty of Allah and others fighting for the cause of Allah. So recite what is easy from it and establish prayer and give zakah and loan Allah a goodly loan. And whatever good you put forward for yourselves - you will find it with Allah. It is better and greater in reward. And seek forgiveness of Allah. Indeed, Allah is Forgiving and Merciful."}]}, {"num": 74, "name": "Al-Muddaththir", "meaning": "The Cloaked One", "verses": [{"ayah": 1, "translit": "Yaaa ayyuhal muddassir", "translation": "O you who covers himself [with a garment],"}, {"ayah": 2, "translit": "Qum fa anzir", "translation": "Arise and warn"}, {"ayah": 3, "translit": "Wa rabbaka fakabbir", "translation": "And your Lord glorify"}, {"ayah": 4, "translit": "Wa siyaabaka fatahhir", "translation": "And your clothing purify"}, {"ayah": 5, "translit": "Warrujza fahjur", "translation": "And uncleanliness avoid"}, {"ayah": 6, "translit": "Wa laa tamnun tastaksir", "translation": "And do not confer favor to acquire more"}, {"ayah": 7, "translit": "Wa li Rabbika fasbir", "translation": "But for your Lord be patient."}, {"ayah": 8, "translit": "Fa izaa nuqira fin naaqoor", "translation": "And when the trumpet is blown,"}, {"ayah": 9, "translit": "Fazaalika yawma 'iziny yawmun 'aseer", "translation": "That Day will be a difficult day"}, {"ayah": 10, "translit": "'Alal kaafireena ghairu yaseer", "translation": "For the disbelievers - not easy."}, {"ayah": 11, "translit": "Zarnee wa man khalaqtu waheedaa", "translation": "Leave Me with the one I created alone"}, {"ayah": 12, "translit": "Wa ja'altu lahoo maalam mamdoodaa", "translation": "And to whom I granted extensive wealth"}, {"ayah": 13, "translit": "Wa baneena shuhoodaa", "translation": "And children present [with him]"}, {"ayah": 14, "translit": "Wa mahhattu lahoo tamheeda", "translation": "And spread [everything] before him, easing [his life]."}, {"ayah": 15, "translit": "Summa yat ma'u an azeed", "translation": "Then he desires that I should add more."}, {"ayah": 16, "translit": "Kallaaa innahoo kaana li Aayaatinaa 'aneedaa", "translation": "No! Indeed, he has been toward Our verses obstinate."}, {"ayah": 17, "translit": "Sa urhiquhoo sa'oodaa", "translation": "I will cover him with arduous torment."}, {"ayah": 18, "translit": "Innahoo fakkara wa qaddar", "translation": "Indeed, he thought and deliberated."}, {"ayah": 19, "translit": "Faqutila kayfa qaddar", "translation": "So may he be destroyed [for] how he deliberated."}, {"ayah": 20, "translit": "Summa qutila kaifa qaddar", "translation": "Then may he be destroyed [for] how he deliberated."}, {"ayah": 21, "translit": "Summa nazar", "translation": "Then he considered [again];"}, {"ayah": 22, "translit": "Summa 'abasa wa basar", "translation": "Then he frowned and scowled;"}, {"ayah": 23, "translit": "Summaa adbara wastakbar", "translation": "Then he turned back and was arrogant"}, {"ayah": 24, "translit": "Faqaala in haazaaa illaa sihruny yu'sar", "translation": "And said, \"This is not but magic imitated [from others]."}, {"ayah": 25, "translit": "In haazaaa illaa qawlul bashar", "translation": "This is not but the word of a human being.\""}, {"ayah": 26, "translit": "Sa usleehi saqar", "translation": "I will drive him into Saqar."}, {"ayah": 27, "translit": "Wa maaa adraaka maa saqar", "translation": "And what can make you know what is Saqar?"}, {"ayah": 28, "translit": "Laa tubqee wa laa tazar", "translation": "It lets nothing remain and leaves nothing [unburned],"}, {"ayah": 29, "translit": "Lawwaahatul lilbashar", "translation": "Blackening the skins."}, {"ayah": 30, "translit": "'Alaihaa tis'ata 'ashar", "translation": "Over it are nineteen [angels]."}, {"ayah": 31, "translit": "Wa maaja'alnaaa As-haaban naari illaa malaaa 'ikatanw wa maa ja'alnaa 'iddatahum illaa fitnatal lillazeena kafaroo liyastaiqinal lazeena ootul kitaaba wa yazdaadal lazeena aamanooo eemaananw wa laa yartaabal lazeena ootul kitaaba walmu'minoona wa liyaqoolal lazeena fee quloo bihim maradunw walkaafiroona maazaaa araadal laahu bihaazaa masalaa; kazaalika yudillul laahu mai yashaaa'u wa yahdee mai yashaaa'; wa maa ya'lamu junooda rabbika illaa hoo; wa maa hiya illaa zikraa lil bashar", "translation": "And We have not made the keepers of the Fire except angels. And We have not made their number except as a trial for those who disbelieve - that those who were given the Scripture will be convinced and those who have believed will increase in faith and those who were given the Scripture and the believers will not doubt and that those in whose hearts is hypocrisy and the disbelievers will say, \"What does Allah intend by this as an example?\" Thus does Allah leave astray whom He wills and guides whom He wills. And none knows the soldiers of your Lord except Him. And mention of the Fire is not but a reminder to humanity."}, {"ayah": 32, "translit": "Kallaa walqamar", "translation": "No! By the moon"}, {"ayah": 33, "translit": "Wallaili id adbar", "translation": "And [by] the night when it departs"}, {"ayah": 34, "translit": "Wassub hi izaaa asfar", "translation": "And [by] the morning when it brightens,"}, {"ayah": 35, "translit": "Innahaa la ihdal kubar", "translation": "Indeed, the Fire is of the greatest [afflictions]"}, {"ayah": 36, "translit": "Nazeeral lilbashar", "translation": "As a warning to humanity -"}, {"ayah": 37, "translit": "Liman shaaa'a minkum any yataqaddama aw yata akhkhar", "translation": "To whoever wills among you to proceed or stay behind."}, {"ayah": 38, "translit": "Kullu nafsim bim kasabat raheenah", "translation": "Every soul, for what it has earned, will be retained"}, {"ayah": 39, "translit": "Illaaa as haabal yameen", "translation": "Except the companions of the right,"}, {"ayah": 40, "translit": "Fee jannaatiny yata saaa'aloon", "translation": "[Who will be] in gardens, questioning each other"}, {"ayah": 41, "translit": "'Anil mujrimeen", "translation": "About the criminals,"}, {"ayah": 42, "translit": "Maa salakakum fee saqar", "translation": "[And asking them], \"What put you into Saqar?\""}, {"ayah": 43, "translit": "Qaaloo lam naku minal musalleen", "translation": "They will say, \"We were not of those who prayed,"}, {"ayah": 44, "translit": "Wa lam naku nut'imul miskeen", "translation": "Nor did we used to feed the poor."}, {"ayah": 45, "translit": "Wa kunnaa nakhoodu ma'al khaaa'ideen", "translation": "And we used to enter into vain discourse with those who engaged [in it],"}, {"ayah": 46, "translit": "Wa kunnaa nukazzibu bi yawmid Deen", "translation": "And we used to deny the Day of Recompense"}, {"ayah": 47, "translit": "Hattaaa ataanal yaqeen", "translation": "Until there came to us the certainty.\""}, {"ayah": 48, "translit": "Famaa tanfa'uhum shafaa'atush shaafi'een", "translation": "So there will not benefit them the intercession of [any] intercessors."}, {"ayah": 49, "translit": "Famaa lahum 'anittazkirati mu'rideen", "translation": "Then what is [the matter] with them that they are, from the reminder, turning away"}, {"ayah": 50, "translit": "Ka annahum humurum mustanfirah", "translation": "As if they were alarmed donkeys"}, {"ayah": 51, "translit": "Farrat min qaswarah", "translation": "Fleeing from a lion?"}, {"ayah": 52, "translit": "Bal yureedu kullum ri'im minhum any yu'taa suhufam munashsharah", "translation": "Rather, every person among them desires that he would be given scriptures spread about."}, {"ayah": 53, "translit": "Kallaa bal laa yakhaafoonal aakhirah", "translation": "No! But they do not fear the Hereafter."}, {"ayah": 54, "translit": "Kallaaa innahoo tazkirah", "translation": "No! Indeed, the Qur'an is a reminder"}, {"ayah": 55, "translit": "Fa man shaaa'a zakarah", "translation": "Then whoever wills will remember it."}, {"ayah": 56, "translit": "Wa maa yazkuroona illaaa any yashaaa'al laah; Huwa ahlut taqwaa wa ahlul maghfirah", "translation": "And they will not remember except that Allah wills. He is worthy of fear and adequate for [granting] forgiveness."}]}, {"num": 75, "name": "Al-Qiyamah", "meaning": "The Resurrection", "verses": [{"ayah": 1, "translit": "Laaa uqsimu bi yawmil qiyaamah", "translation": "I swear by the Day of Resurrection"}, {"ayah": 2, "translit": "Wa laaa uqsimu bin nafsil lawwaamah", "translation": "And I swear by the reproaching soul [to the certainty of resurrection]."}, {"ayah": 3, "translit": "Ayahsabul insaanu al lan najm'a 'izaamah", "translation": "Does man think that We will not assemble his bones?"}, {"ayah": 4, "translit": "Balaa qaadireena 'alaaa an nusawwiya banaanah", "translation": "Yes. [We are] Able [even] to proportion his fingertips."}, {"ayah": 5, "translit": "Bal yureedul insaanu liyafjura amaamah", "translation": "But man desires to continue in sin."}, {"ayah": 6, "translit": "Yas'alu ayyyaana yawmul qiyaamah", "translation": "He asks, \"When is the Day of Resurrection?\""}, {"ayah": 7, "translit": "Fa izaa bariqal basar", "translation": "So when vision is dazzled"}, {"ayah": 8, "translit": "Wa khasafal qamar", "translation": "And the moon darkens"}, {"ayah": 9, "translit": "Wa jumi'ash shamusu wal qamar", "translation": "And the sun and the moon are joined,"}, {"ayah": 10, "translit": "Yaqoolul insaanu yaw ma 'izin aynal mafarr", "translation": "Man will say on that Day, \"Where is the [place of] escape?\""}, {"ayah": 11, "translit": "Kallaa laa wazar", "translation": "No! There is no refuge."}, {"ayah": 12, "translit": "Ilaa rabbika yawma 'izinil mustaqarr", "translation": "To your Lord, that Day, is the [place of] permanence."}, {"ayah": 13, "translit": "Yunabba 'ul insaanu yawma 'izim bimaa qaddama wa akhkhar", "translation": "Man will be informed that Day of what he sent ahead and kept back."}, {"ayah": 14, "translit": "Balil insaanu 'alaa nafsihee baseerah", "translation": "Rather, man, against himself, will be a witness,"}, {"ayah": 15, "translit": "Wa law alqaa ma'aazeerah", "translation": "Even if he presents his excuses."}, {"ayah": 16, "translit": "Laa tuharrik bihee lisaa naka lita'jala bih", "translation": "Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an."}, {"ayah": 17, "translit": "Inna 'alainaa jam'ahoo wa qur aanah", "translation": "Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation."}, {"ayah": 18, "translit": "Fa izaa qaraanaahu fattabi' qur aanah", "translation": "So when We have recited it [through Gabriel], then follow its recitation."}, {"ayah": 19, "translit": "Summa inna 'alainaa bayaanah", "translation": "Then upon Us is its clarification [to you]."}, {"ayah": 20, "translit": "Kallaa bal tuhibboonal 'aajilah", "translation": "No! But you love the immediate"}, {"ayah": 21, "translit": "Wa tazaroonal Aakhirah", "translation": "And leave the Hereafter."}, {"ayah": 22, "translit": "Wujoohuny yawma 'izin naadirah", "translation": "[Some] faces, that Day, will be radiant,"}, {"ayah": 23, "translit": "Ilaa rabbihaa naazirah", "translation": "Looking at their Lord."}, {"ayah": 24, "translit": "Wa wujoohuny yawma 'izim baasirah", "translation": "And [some] faces, that Day, will be contorted,"}, {"ayah": 25, "translit": "Tazunnu any yuf'ala bihaa faaqirah", "translation": "Expecting that there will be done to them [something] backbreaking."}, {"ayah": 26, "translit": "Kallaaa izaa balaghatit taraaqee", "translation": "No! When the soul has reached the collar bones"}, {"ayah": 27, "translit": "Wa qeela man raaq", "translation": "And it is said, \"Who will cure [him]?\""}, {"ayah": 28, "translit": "Wa zanna annahul firaaq", "translation": "And the dying one is certain that it is the [time of] separation"}, {"ayah": 29, "translit": "Waltaffatis saaqu bissaaq", "translation": "And the leg is wound about the leg,"}, {"ayah": 30, "translit": "Ilaa rabbika yawma'izinil masaaq", "translation": "To your Lord, that Day, will be the procession."}, {"ayah": 31, "translit": "Falaa saddaqa wa laa sallaa", "translation": "And the disbeliever had not believed, nor had he prayed."}, {"ayah": 32, "translit": "Wa laakin kazzaba wa tawalla", "translation": "But [instead], he denied and turned away."}, {"ayah": 33, "translit": "Summa zahaba ilaaa ahlihee yatamatta", "translation": "And then he went to his people, swaggering [in pride]."}, {"ayah": 34, "translit": "Awlaa laka fa awlaa", "translation": "Woe to you, and woe!"}, {"ayah": 35, "translit": "Summa awlaa laka fa awla", "translation": "Then woe to you, and woe!"}, {"ayah": 36, "translit": "Ayahsabul insaanu anyytraka sudaa", "translation": "Does man think that he will be left neglected?"}, {"ayah": 37, "translit": "Alam yaku nutfatam mim maniyyiny yumnaa", "translation": "Had he not been a sperm from semen emitted?"}, {"ayah": 38, "translit": "Summa kaana 'alaqata fakhalaq fasawwaa", "translation": "Then he was a clinging clot, and [Allah] created [his form] and proportioned [him]"}, {"ayah": 39, "translit": "Faja'ala minhuz zawjayniz zakara wal unsaa", "translation": "And made of him two mates, the male and the female."}, {"ayah": 40, "translit": "Alaisa zaalika biqaadirin 'alaaa any yuhyiyal mawtaa", "translation": "Is not that [Creator] Able to give life to the dead?"}]}, {"num": 76, "name": "Al-Insan", "meaning": "The Man", "verses": [{"ayah": 1, "translit": "Hal ataa 'alal insaani heenum minad dahri lam yakun shai'am mazkooraa", "translation": "Has there [not] come upon man a period of time when he was not a thing [even] mentioned?"}, {"ayah": 2, "translit": "Innaa khalaqnal insaana min nutfatin amshaajin nabta leehi faja'alnaahu samee'am baseeraa", "translation": "Indeed, We created man from a sperm-drop mixture that We may try him; and We made him hearing and seeing."}, {"ayah": 3, "translit": "Innaa hadainaahus sabeela immaa shaakiranw wa immaa kafoora", "translation": "Indeed, We guided him to the way, be he grateful or be he ungrateful."}, {"ayah": 4, "translit": "Innaaa a'tadnaa lilkaa fireena salaasila wa aghlaalanw wa sa'eeraa", "translation": "Indeed, We have prepared for the disbelievers chains and shackles and a blaze."}, {"ayah": 5, "translit": "innal abraara yashra boona min kaasin kaana mizaa juhaa kaafooraa", "translation": "Indeed, the righteous will drink from a cup [of wine] whose mixture is of Kafur,"}, {"ayah": 6, "translit": "'Aynany yashrabu bihaa 'ibaadul laahi yafajjiroonahaa tafjeeraa", "translation": "A spring of which the [righteous] servants of Allah will drink; they will make it gush forth in force [and abundance]."}, {"ayah": 7, "translit": "Yoofoona binnazri wa yakhaafoona yawman kaana sharruhoo mustateeraa", "translation": "They [are those who] fulfill [their] vows and fear a Day whose evil will be widespread."}, {"ayah": 8, "translit": "Wa yut''imoonat ta'aama 'alaa hubbihee miskeenanw wa yatemanw wa aseeraa", "translation": "And they give food in spite of love for it to the needy, the orphan, and the captive,"}, {"ayah": 9, "translit": "Innaamaa nut'imukum li wajhil laahi laa nureedu minkum jazaaa'anw wa laa shukooraa", "translation": "[Saying], \"We feed you only for the countenance of Allah. We wish not from you reward or gratitude."}, {"ayah": 10, "translit": "Innaa nakhaafu mir Rabbinna Yawman 'aboosan qamtareeraa", "translation": "Indeed, We fear from our Lord a Day austere and distressful.\""}, {"ayah": 11, "translit": "Fa waqaahumul laahu sharra zaalikal yawmi wa laqqaahum nadratanw wa surooraa", "translation": "So Allah will protect them from the evil of that Day and give them radiance and happiness"}, {"ayah": 12, "translit": "Wa jazaahum bimaa sabaroo janatanw wa hareeraa", "translation": "And will reward them for what they patiently endured [with] a garden [in Paradise] and silk [garments]."}, {"ayah": 13, "translit": "muttaki'eena feeha 'alal araaa 'iki laa yarawna feehaa shamsanw wa laa zamhareeraa", "translation": "[They will be] reclining therein on adorned couches. They will not see therein any [burning] sun or [freezing] cold."}, {"ayah": 14, "translit": "Wa daaniyatan 'alaihim zilaaluhaa wa zullilat qutoofu haa tazleela", "translation": "And near above them are its shades, and its [fruit] to be picked will be lowered in compliance."}, {"ayah": 15, "translit": "Wa yutaafu 'alaihim bi aaniyatim min fiddatinw wa akwaabin kaanat qawaareeraa", "translation": "And there will be circulated among them vessels of silver and cups having been [created] clear [as glass],"}, {"ayah": 16, "translit": "Qawaareera min fiddatin qaddaroohaa taqdeeraa", "translation": "Clear glasses [made] from silver of which they have determined the measure."}, {"ayah": 17, "translit": "Wa yuskawna feehaa kaasan kaana mizaajuhaa zanjabeelaa", "translation": "And they will be given to drink a cup [of wine] whose mixture is of ginger"}, {"ayah": 18, "translit": "'Aynan feeha tusammaa salsabeelaa", "translation": "[From] a fountain within Paradise named Salsabeel."}, {"ayah": 19, "translit": "Wa yatoofu 'alaihim wildaanum mukhalladoona izaa ra aytahum hasibtahum lu'lu 'am mansoora", "translation": "There will circulate among them young boys made eternal. When you see them, you would think them [as beautiful as] scattered pearls."}, {"ayah": 20, "translit": "Wa izaa ra ayta summa ra ayta na'eemanw wa mulkan kabeera", "translation": "And when you look there [in Paradise], you will see pleasure and great dominion."}, {"ayah": 21, "translit": "'Aaliyahum siyaabu sundusin khudrunw wa istabraq, wa hullooo asaawira min fiddatinw wa saqaahum Rabbuhum sharaaban tahooraa", "translation": "Upon the inhabitants will be green garments of fine silk and brocade. And they will be adorned with bracelets of silver, and their Lord will give them a purifying drink."}, {"ayah": 22, "translit": "Innaa haazaa kaana lakum jazz 'anw wa kaana sa'yukum mashkooraa", "translation": "[And it will be said], \"Indeed, this is for you a reward, and your effort has been appreciated.\""}, {"ayah": 23, "translit": "Innaa nahnu nazzalnaa 'alaikal quraana tanzeelaa", "translation": "Indeed, it is We who have sent down to you, [O Muhammad], the Qur'an progressively."}, {"ayah": 24, "translit": "Fasbir lihukmi Rabbika wa laa tuti' minhum aasiman aw kafooraa", "translation": "So be patient for the decision of your Lord and do not obey from among them a sinner or ungrateful [disbeliever]."}, {"ayah": 25, "translit": "Wazkuris ma Rabbika bukratanw wa aseelaa", "translation": "And mention the name of your Lord [in prayer] morning and evening"}, {"ayah": 26, "translit": "Wa minal laili fasjud lahoo wa sabbihhu lailan taweelaa", "translation": "And during the night prostrate to Him and exalt Him a long [part of the] night."}, {"ayah": 27, "translit": "Inna haaa'ulaa'i yuhibboona 'aajilata wa yazaroona waraaa'ahum yawman saqeelaa", "translation": "Indeed, these [disbelievers] love the immediate and leave behind them a grave Day."}, {"ayah": 28, "translit": "Nahnu khalaqnaahum wa shadadnaaa asrahum wa izaa shi'naa baddalnaaa amsaala hum tabdeelaa", "translation": "We have created them and strengthened their forms, and when We will, We can change their likenesses with [complete] alteration."}, {"ayah": 29, "translit": "Inna haazihee tazkiratun fa man shaaa'at takhaza ilaa rabbihee sabeela", "translation": "Indeed, this is a reminder, so he who wills may take to his Lord a way."}, {"ayah": 30, "translit": "Wa maa tashaaa'oona illaa anyyashaaa'al laah; innal laahaa kaana'Aleeman Hakeema", "translation": "And you do not will except that Allah wills. Indeed, Allah is ever Knowing and Wise."}, {"ayah": 31, "translit": "Yudkhilu mai yashaaa'u fee rahmatih; wazzaalimeena a'adda lahum 'azaaban aleemaa", "translation": "He admits whom He wills into His mercy; but the wrongdoers - He has prepared for them a painful punishment."}]}, {"num": 77, "name": "Al-Mursalat", "meaning": "The Emissaries", "verses": [{"ayah": 1, "translit": "Wal mursalaati'urfaa", "translation": "By those [winds] sent forth in gusts"}, {"ayah": 2, "translit": "Fal'aasifaati 'asfaa", "translation": "And the winds that blow violently"}, {"ayah": 3, "translit": "Wannaashiraati nashraa", "translation": "And [by] the winds that spread [clouds]"}, {"ayah": 4, "translit": "Falfaariqaati farqaa", "translation": "And those [angels] who bring criterion"}, {"ayah": 5, "translit": "Falmulqiyaati zikra", "translation": "And those [angels] who deliver a message"}, {"ayah": 6, "translit": "'Uzran aw nuzraa", "translation": "As justification or warning,"}, {"ayah": 7, "translit": "Innamaa too'adoona lawaaqi'", "translation": "Indeed, what you are promised is to occur."}, {"ayah": 8, "translit": "Fa izam nujoomu tumisat", "translation": "So when the stars are obliterated"}, {"ayah": 9, "translit": "Wa izas samaaa'u furijat", "translation": "And when the heaven is opened"}, {"ayah": 10, "translit": "Wa izal jibaalu nusifat", "translation": "And when the mountains are blown away"}, {"ayah": 11, "translit": "Wa izar Rusulu uqqitat", "translation": "And when the messengers' time has come..."}, {"ayah": 12, "translit": "Li ayyi yawmin ujjilat", "translation": "For what Day was it postponed?"}, {"ayah": 13, "translit": "Li yawmil Fasl", "translation": "For the Day of Judgement."}, {"ayah": 14, "translit": "Wa maaa adraaka maa yawmul fasl", "translation": "And what can make you know what is the Day of Judgement?"}, {"ayah": 15, "translit": "Wailuny yawma 'izillilmukazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 16, "translit": "Alam nuhlikil awwaleen", "translation": "Did We not destroy the former peoples?"}, {"ayah": 17, "translit": "Summa nutbi'uhumul aakhireen", "translation": "Then We will follow them with the later ones."}, {"ayah": 18, "translit": "Kazzlika naf'alu bilmujrimeen", "translation": "Thus do We deal with the criminals."}, {"ayah": 19, "translit": "Wailunw yawma 'izil lil mukazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 20, "translit": "Alam nakhlukkum mimmaaa'im maheen", "translation": "Did We not create you from a liquid disdained?"}, {"ayah": 21, "translit": "Faja'alnaahu fee qaraarim makeen", "translation": "And We placed it in a firm lodging"}, {"ayah": 22, "translit": "Illaa qadrim ma'loom", "translation": "For a known extent."}, {"ayah": 23, "translit": "Faqadarnaa fani'mal qaadiroon", "translation": "And We determined [it], and excellent [are We] to determine."}, {"ayah": 24, "translit": "Wailuny yawma 'izil lilmukazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 25, "translit": "Alam naj'alil arda kifaataa", "translation": "Have We not made the earth a container"}, {"ayah": 26, "translit": "Ahyaaa'anw wa amwaataa", "translation": "Of the living and the dead?"}, {"ayah": 27, "translit": "Wa ja'alnaa feehaa rawaasiya shaamikhaatinw wa asqainaakum maaa'an furaataa", "translation": "And We placed therein lofty, firmly set mountains and have given you to drink sweet water."}, {"ayah": 28, "translit": "Wailuny yawma 'izil lilmukazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 29, "translit": "Intaliqooo ilaa maa kuntum bihee tukazziboon", "translation": "[They will be told], \"Proceed to that which you used to deny."}, {"ayah": 30, "translit": "Intaliqooo ilaa zillin zee salaasi shu'ab", "translation": "Proceed to a shadow [of smoke] having three columns"}, {"ayah": 31, "translit": "Laa zaleelinw wa laa yughnee minal lahab", "translation": "[But having] no cool shade and availing not against the flame.\""}, {"ayah": 32, "translit": "Innahaa tarmee bishararin kalqasr", "translation": "Indeed, it throws sparks [as huge] as a fortress,"}, {"ayah": 33, "translit": "Ka annahoo jimaalatun sufr", "translation": "As if they were yellowish [black] camels."}, {"ayah": 34, "translit": "Wailuny yawma 'izil lilmukazibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 35, "translit": "Haazaa yawmu laa uantiqoon", "translation": "This is a Day they will not speak,"}, {"ayah": 36, "translit": "Wa laa yu'zanu lahum fa ya'taziroon", "translation": "Nor will it be permitted for them to make an excuse."}, {"ayah": 37, "translit": "Wailunw yawma 'izil lilmukazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 38, "translit": "Haaza yawmul fasli jama 'naakum wal awwaleen", "translation": "This is the Day of Judgement; We will have assembled you and the former peoples."}, {"ayah": 39, "translit": "Fa in kaana lakum kaidun fakeedoon", "translation": "So if you have a plan, then plan against Me."}, {"ayah": 40, "translit": "Wailuny yawma'izil lilmukazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 41, "translit": "Innal muttaqeena fee zilaalinw wa 'uyoon", "translation": "Indeed, the righteous will be among shades and springs"}, {"ayah": 42, "translit": "Wa fawaakiha mimmaa yashtahoon", "translation": "And fruits from whatever they desire,"}, {"ayah": 43, "translit": "Kuloo washraboo haneee 'am bimaa kuntum ta'maloon", "translation": "[Being told], \"Eat and drink in satisfaction for what you used to do.\""}, {"ayah": 44, "translit": "Innaa kazaalika najzil muhsineen", "translation": "Indeed, We thus reward the doers of good."}, {"ayah": 45, "translit": "Wailuny yawma 'izil lilmuzkazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 46, "translit": "Kuloo wa tamatta'oo qaleelan innakum mujrimoon", "translation": "[O disbelievers], eat and enjoy yourselves a little; indeed, you are criminals."}, {"ayah": 47, "translit": "Wailunny yawma 'izil lilmukazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 48, "translit": "Wa izaa qeela lahumur ka'oo aa yarka'oon", "translation": "And when it is said to them, \"Bow [in prayer],\" they do not bow."}, {"ayah": 49, "translit": "Wailunny yawma 'izil lilmukazzibeen", "translation": "Woe, that Day, to the deniers."}, {"ayah": 50, "translit": "Fabi ayyi hadeesim ba'dahoo yu'minoon", "translation": "Then in what statement after the Qur'an will they believe?"}]}, {"num": 78, "name": "An-Naba", "meaning": "The Tidings", "verses": [{"ayah": 1, "translit": "'Amma Yatasaa-aloon", "translation": "About what are they asking one another?"}, {"ayah": 2, "translit": "'Anin-nabaa-il 'azeem", "translation": "About the great news -"}, {"ayah": 3, "translit": "Allazi hum feehi mukh talifoon", "translation": "That over which they are in disagreement."}, {"ayah": 4, "translit": "Kallaa sa y'alamoon", "translation": "No! They are going to know."}, {"ayah": 5, "translit": "Thumma kallaa sa y'alamoon", "translation": "Then, no! They are going to know."}, {"ayah": 6, "translit": "Alam naj'alil arda mihaa da", "translation": "Have We not made the earth a resting place?"}, {"ayah": 7, "translit": "Wal jibaala au taada", "translation": "And the mountains as stakes?"}, {"ayah": 8, "translit": "Wa khalaq naakum azwaaja", "translation": "And We created you in pairs"}, {"ayah": 9, "translit": "Waja'alna naumakum subata", "translation": "And made your sleep [a means for] rest"}, {"ayah": 10, "translit": "Waja'alnal laila libasa", "translation": "And made the night as clothing"}, {"ayah": 11, "translit": "Waja'alnan nahara ma 'aasha", "translation": "And made the day for livelihood"}, {"ayah": 12, "translit": "Wa banaina fauqakum sab 'an shi daada", "translation": "And constructed above you seven strong [heavens]"}, {"ayah": 13, "translit": "Waja'alna siraajaw wah haaja", "translation": "And made [therein] a burning lamp"}, {"ayah": 14, "translit": "Wa anzalna minal m'usiraati maa-an thaj-jaaja", "translation": "And sent down, from the rain clouds, pouring water"}, {"ayah": 15, "translit": "Linukh rija bihee habbaw wana baata", "translation": "That We may bring forth thereby grain and vegetation"}, {"ayah": 16, "translit": "Wa jan naatin alfafa", "translation": "And gardens of entwined growth."}, {"ayah": 17, "translit": "Inna yaumal-fasli kana miqaata", "translation": "Indeed, the Day of Judgement is an appointed time -"}, {"ayah": 18, "translit": "Yauma yun fakhu fis-soori fataa toona afwaaja", "translation": "The Day the Horn is blown and you will come forth in multitudes"}, {"ayah": 19, "translit": "Wa futiha tis samaa-u fakaanat abwaaba", "translation": "And the heaven is opened and will become gateways"}, {"ayah": 20, "translit": "Wa suyyi raatil jibaalu fa kaanat saraaba", "translation": "And the mountains are removed and will be [but] a mirage."}, {"ayah": 21, "translit": "Inna jahan nama kaanat mirsaada", "translation": "Indeed, Hell has been lying in wait"}, {"ayah": 22, "translit": "Lit taa gheena ma aaba", "translation": "For the transgressors, a place of return,"}, {"ayah": 23, "translit": "Laa bitheena feehaa ahqaaba", "translation": "In which they will remain for ages [unending]."}, {"ayah": 24, "translit": "Laa ya zooqoona feeha bar daw walaa sharaaba", "translation": "They will not taste therein [any] coolness or drink"}, {"ayah": 25, "translit": "Illa hamee maw-wa ghas saaqa", "translation": "Except scalding water and [foul] purulence -"}, {"ayah": 26, "translit": "Jazaa-aw wi faaqa", "translation": "An appropriate recompense."}, {"ayah": 27, "translit": "Innahum kaanu laa yarjoona hisaaba", "translation": "Indeed, they were not expecting an account"}, {"ayah": 28, "translit": "Wa kazzabu bi aayaa tina kizzaba", "translation": "And denied Our verses with [emphatic] denial."}, {"ayah": 29, "translit": "Wa kulla shai-in ahsai naahu kitaa ba", "translation": "But all things We have enumerated in writing."}, {"ayah": 30, "translit": "Fa zooqoo falan-nazee dakum ill-laa azaaba", "translation": "\"So taste [the penalty], and never will We increase you except in torment.\""}, {"ayah": 31, "translit": "Inna lil mutta qeena mafaaza", "translation": "Indeed, for the righteous is attainment -"}, {"ayah": 32, "translit": "Hadaa-iqa wa a'anaa ba", "translation": "Gardens and grapevines"}, {"ayah": 33, "translit": "Wa kaawa 'iba at raaba", "translation": "And full-breasted [companions] of equal age"}, {"ayah": 34, "translit": "Wa ka'san di haaqa", "translation": "And a full cup."}, {"ayah": 35, "translit": "Laa yasma'oona fiha lagh waw walaa kizzaba", "translation": "No ill speech will they hear therein or any falsehood -"}, {"ayah": 36, "translit": "Jazaa-am mir-rabbika ataa-an hisaaba", "translation": "[As] reward from your Lord, [a generous] gift [made due by] account,"}, {"ayah": 37, "translit": "Rabbis samaa waati wal ardi wa maa baina humar rahmaani laa yam likoona minhu khi taaba", "translation": "[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech."}, {"ayah": 38, "translit": "Yauma yaqoo mur roohu wal malaa-ikatu saf-fal laa yata kalla moona illa man azina lahur rahmaanu wa qaala sawaaba", "translation": "The Day that the Spirit and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct."}, {"ayah": 39, "translit": "Zaalikal yaumul haqqu faman shaa-at ta khaaza ill-laa rabbihi ma-aaba", "translation": "That is the True Day; so he who wills may take to his Lord a [way of] return."}, {"ayah": 40, "translit": "In naa anzar naakum azaaban qareebaiy-yauma yan zurul marr-u maa qaddamat yadaahu wa ya qoolul-kaafiru yaa lai tanee kuntu turaaba", "translation": "Indeed, We have warned you of a near punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, \"Oh, I wish that I were dust!\""}]}, {"num": 79, "name": "An-Nazi'at", "meaning": "Those Who Drag Forth", "verses": [{"ayah": 1, "translit": "Wan naazi 'aati gharqa", "translation": "By those [angels] who extract with violence"}, {"ayah": 2, "translit": "Wan naa shi taati nashta", "translation": "And [by] those who remove with ease"}, {"ayah": 3, "translit": "Wass saabi-haati sabha", "translation": "And [by] those who glide [as if] swimming"}, {"ayah": 4, "translit": "Fass saabi qaati sabqa", "translation": "And those who race each other in a race"}, {"ayah": 5, "translit": "Fal mu dab-bi raati amra", "translation": "And those who arrange [each] matter,"}, {"ayah": 6, "translit": "Yawma tarjufur raajifa", "translation": "On the Day the blast [of the Horn] will convulse [creation],"}, {"ayah": 7, "translit": "Tatba'u har raadifa", "translation": "There will follow it the subsequent [one]."}, {"ayah": 8, "translit": "Quloobuny-yau maaiziw-waaji-fa", "translation": "Hearts, that Day, will tremble,"}, {"ayah": 9, "translit": "Absaa ruhaa khashi'ah", "translation": "Their eyes humbled."}, {"ayah": 10, "translit": "Ya qoo loona a-inna lamar doo doona fil haafirah", "translation": "They are [presently] saying, \"Will we indeed be returned to [our] former state [of life]?"}, {"ayah": 11, "translit": "Aizaa kunna 'izaa man-nakhirah", "translation": "Even if we should be decayed bones?"}, {"ayah": 12, "translit": "Qaalu tilka izan karratun khaasirah.", "translation": "They say, \"That, then, would be a losing return.\""}, {"ayah": 13, "translit": "Fa inna ma hiya zajratuw-waahida", "translation": "Indeed, it will be but one shout,"}, {"ayah": 14, "translit": "Faizaa hum biss saahirah", "translation": "And suddenly they will be [alert] upon the earth's surface."}, {"ayah": 15, "translit": "Hal ataaka hadeethu Musaa", "translation": "Has there reached you the story of Moses? -"}, {"ayah": 16, "translit": "Iz nadaahu rabbuhu bil waadil-muqad dasi tuwa", "translation": "When his Lord called to him in the sacred valley of Tuwa,"}, {"ayah": 17, "translit": "Izhab ilaa fir'auna innahu taghaa.", "translation": "\"Go to Pharaoh. Indeed, he has transgressed."}, {"ayah": 18, "translit": "Faqul hal laka ilaa-an tazakka.", "translation": "And say to him, 'Would you [be willing to] purify yourself"}, {"ayah": 19, "translit": "Wa ahdi yaka ila rabbika fatakh sha", "translation": "And let me guide you to your Lord so you would fear [Him]?'\""}, {"ayah": 20, "translit": "Fa araahul-aayatal kubra.", "translation": "And he showed him the greatest sign,"}, {"ayah": 21, "translit": "Fa kazzaba wa asaa.", "translation": "But Pharaoh denied and disobeyed."}, {"ayah": 22, "translit": "Thumma adbara yas'aa.", "translation": "Then he turned his back, striving."}, {"ayah": 23, "translit": "Fa hashara fanada.", "translation": "And he gathered [his people] and called out"}, {"ayah": 24, "translit": "Faqala ana rabbu kumul-a'laa.", "translation": "And said, \"I am your most exalted lord.\""}, {"ayah": 25, "translit": "Fa-akha zahul laahu nakalal aakhirati wal-oola.", "translation": "So Allah seized him in exemplary punishment for the last and the first [transgression]."}, {"ayah": 26, "translit": "Inna fee zaalika la'ibratal limaiy-yaksha", "translation": "Indeed in that is a warning for whoever would fear [Allah]."}, {"ayah": 27, "translit": "A-antum a shaddu khalqan amis samaa-u banaaha.", "translation": "Are you a more difficult creation or is the heaven? Allah constructed it."}, {"ayah": 28, "translit": "Raf'a sam kaha fasaw waaha", "translation": "He raised its ceiling and proportioned it."}, {"ayah": 29, "translit": "Wa aghtasha lailaha wa akhraja duhaaha.", "translation": "And He darkened its night and extracted its brightness."}, {"ayah": 30, "translit": "Wal arda b'ada zaalika dahaaha.", "translation": "And after that He spread the earth."}, {"ayah": 31, "translit": "Akhraja minha maa-aha wa mar 'aaha.", "translation": "He extracted from it its water and its pasture,"}, {"ayah": 32, "translit": "Wal jibala arsaaha.", "translation": "And the mountains He set firmly"}, {"ayah": 33, "translit": "Mataa'al lakum wali an 'aamikum.", "translation": "As provision for you and your grazing livestock."}, {"ayah": 34, "translit": "Fa-izaa jaaa'atit taaam matul kubraa.", "translation": "But when there comes the greatest Overwhelming Calamity -"}, {"ayah": 35, "translit": "Yauma Yata zakkarul insaanu ma sa'aa.", "translation": "The Day when man will remember that for which he strove,"}, {"ayah": 36, "translit": "Wa burrizatil-jaheemu limany-yaraa.", "translation": "And Hellfire will be exposed for [all] those who see -"}, {"ayah": 37, "translit": "Fa ammaa man taghaa.", "translation": "So as for he who transgressed"}, {"ayah": 38, "translit": "Wa aasaral hayaatad dunyaa", "translation": "And preferred the life of the world,"}, {"ayah": 39, "translit": "Fa innal jaheema hiyal maawaa.", "translation": "Then indeed, Hellfire will be [his] refuge."}, {"ayah": 40, "translit": "Wa ammaa man khaafa maqaama Rabbihee wa nahan nafsa 'anil hawaa", "translation": "But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination,"}, {"ayah": 41, "translit": "Fa innal jannata hiyal maawaa", "translation": "Then indeed, Paradise will be [his] refuge."}, {"ayah": 42, "translit": "Yas'aloonaka 'anis saa'ati ayyaana mursaahaa", "translation": "They ask you, [O Muhammad], about the Hour: when is its arrival?"}, {"ayah": 43, "translit": "Feema anta min zikraahaa", "translation": "In what [position] are you that you should mention it?"}, {"ayah": 44, "translit": "Ilaa Rabbika muntahaa haa", "translation": "To your Lord is its finality."}, {"ayah": 45, "translit": "Innamaaa anta munziru maiy yakshaahaa", "translation": "You are only a warner for those who fear it."}, {"ayah": 46, "translit": "Ka annahum Yawma yarawnahaa lam yalbasooo illaa 'ashiyyatan aw duhaahaa", "translation": "It will be, on the Day they see it, as though they had not remained [in the world] except for an afternoon or a morning thereof."}]}, {"num": 80, "name": "Abasa", "meaning": "He Frowned", "verses": [{"ayah": 1, "translit": "'Abasa wa tawallaa.", "translation": "The Prophet frowned and turned away"}, {"ayah": 2, "translit": "An jaa-ahul 'a-maa", "translation": "Because there came to him the blind man, [interrupting]."}, {"ayah": 3, "translit": "Wa maa yudreeka la'allahu yaz zakkaa.", "translation": "But what would make you perceive, [O Muhammad], that perhaps he might be purified"}, {"ayah": 4, "translit": "Au yaz zak karu fatanfa 'ahuz zikraa.", "translation": "Or be reminded and the remembrance would benefit him?"}, {"ayah": 5, "translit": "Amma manis taghnaa", "translation": "As for he who thinks himself without need,"}, {"ayah": 6, "translit": "Fa-anta lahu tasaddaa", "translation": "To him you give attention."}, {"ayah": 7, "translit": "Wa ma 'alaika allaa yaz zakka.", "translation": "And not upon you [is any blame] if he will not be purified."}, {"ayah": 8, "translit": "Wa amma man jaa-aka yas'a", "translation": "But as for he who came to you striving [for knowledge]"}, {"ayah": 9, "translit": "Wahuwa yakhshaa,", "translation": "While he fears [Allah],"}, {"ayah": 10, "translit": "Fa-anta 'anhu talah haa.", "translation": "From him you are distracted."}, {"ayah": 11, "translit": "Kalla innaha tazkirah", "translation": "No! Indeed, these verses are a reminder;"}, {"ayah": 12, "translit": "Faman shaa a zakarah", "translation": "So whoever wills may remember it."}, {"ayah": 13, "translit": "Fi suhufim mukar rama,", "translation": "[It is recorded] in honored sheets,"}, {"ayah": 14, "translit": "Marfoo'atim mutah hara,", "translation": "Exalted and purified,"}, {"ayah": 15, "translit": "Bi'aidee safara", "translation": "[Carried] by the hands of messenger-angels,"}, {"ayah": 16, "translit": "Kiraamim bararah.", "translation": "Noble and dutiful."}, {"ayah": 17, "translit": "Qutilal-insanu maa akfarah.", "translation": "Cursed is man; how disbelieving is he."}, {"ayah": 18, "translit": "Min aiyyi shai-in Khalaq", "translation": "From what substance did He create him?"}, {"ayah": 19, "translit": "Min nutfatin khalaqahoo faqaddarah.", "translation": "From a sperm-drop He created him and destined for him;"}, {"ayah": 20, "translit": "Thummas sabeela yas-sarah", "translation": "Then He eased the way for him;"}, {"ayah": 21, "translit": "Thumma amatahu fa-aqbarah", "translation": "Then He causes his death and provides a grave for him."}, {"ayah": 22, "translit": "Thumma iza shaa-a ansharah", "translation": "Then when He wills, He will resurrect him."}, {"ayah": 23, "translit": "Kalla lamma yaqdi maa amarah.", "translation": "No! Man has not yet accomplished what He commanded him."}, {"ayah": 24, "translit": "Falyanzuril insanu ilaa ta-amih", "translation": "Then let mankind look at his food -"}, {"ayah": 25, "translit": "Anna sabab nalmaa-a sabba.", "translation": "How We poured down water in torrents,"}, {"ayah": 26, "translit": "Thumma sha qaqnal-arda shaqqa.", "translation": "Then We broke open the earth, splitting [it with sprouts],"}, {"ayah": 27, "translit": "Fa ambatna feeha habba", "translation": "And caused to grow within it grain"}, {"ayah": 28, "translit": "Wa 'inabaw-wa qadba", "translation": "And grapes and herbage"}, {"ayah": 29, "translit": "Wa zaitoonaw wanakh la'", "translation": "And olive and palm trees"}, {"ayah": 30, "translit": "Wa hadaa-iqa ghulba", "translation": "And gardens of dense shrubbery"}, {"ayah": 31, "translit": "Wa faki hataw-wa abba.", "translation": "And fruit and grass -"}, {"ayah": 32, "translit": "Mata'al-lakum wa li-an'amikum.", "translation": "[As] enjoyment for you and your grazing livestock."}, {"ayah": 33, "translit": "Faiza jaa-atis saakhah.", "translation": "But when there comes the Deafening Blast"}, {"ayah": 34, "translit": "Yauma yafir-rul mar-u min akheeh", "translation": "On the Day a man will flee from his brother"}, {"ayah": 35, "translit": "Wa ummihee wa abeeh", "translation": "And his mother and his father"}, {"ayah": 36, "translit": "Wa sahi batihee wa baneeh.", "translation": "And his wife and his children,"}, {"ayah": 37, "translit": "Likul limri-im-minuhm yaumaa-izin shaa nuy-yughneeh", "translation": "For every man, that Day, will be a matter adequate for him."}, {"ayah": 38, "translit": "Wujoo huny-yauma-izim-musfira;", "translation": "[Some] faces, that Day, will be bright -"}, {"ayah": 39, "translit": "Dahi katum mustab shirah", "translation": "Laughing, rejoicing at good news."}, {"ayah": 40, "translit": "Wa wujoohuy yauma-izin 'alaiha ghabar a", "translation": "And [other] faces, that Day, will have upon them dust."}, {"ayah": 41, "translit": "Tarhaquha qatarah.", "translation": "Blackness will cover them."}, {"ayah": 42, "translit": "Ulaa-ika humul-kafa ratul-fajarah.", "translation": "Those are the disbelievers, the wicked ones."}]}, {"num": 81, "name": "At-Takwir", "meaning": "The Overthrowing", "verses": [{"ayah": 1, "translit": "Izash shamsu kuwwirat", "translation": "When the sun is wrapped up [in darkness]"}, {"ayah": 2, "translit": "Wa izan nujoomun kadarat", "translation": "And when the stars fall, dispersing,"}, {"ayah": 3, "translit": "Wa izal jibaalu suyyirat", "translation": "And when the mountains are removed"}, {"ayah": 4, "translit": "Wa izal 'ishaaru 'uttilat", "translation": "And when full-term she-camels are neglected"}, {"ayah": 5, "translit": "Wa izal wuhooshu hushirat", "translation": "And when the wild beasts are gathered"}, {"ayah": 6, "translit": "Wa izal bihaaru sujjirat", "translation": "And when the seas are filled with flame"}, {"ayah": 7, "translit": "Wa izan nufoosu zuwwijat", "translation": "And when the souls are paired"}, {"ayah": 8, "translit": "Wa izal maw'oodatu su'ilat", "translation": "And when the girl [who was] buried alive is asked"}, {"ayah": 9, "translit": "Bi ayyi zambin qutilat", "translation": "For what sin she was killed"}, {"ayah": 10, "translit": "Wa izas suhufu nushirat", "translation": "And when the pages are made public"}, {"ayah": 11, "translit": "Wa izas samaaa'u kushitat", "translation": "And when the sky is stripped away"}, {"ayah": 12, "translit": "Wa izal jaheemu su'-'irat", "translation": "And when Hellfire is set ablaze"}, {"ayah": 13, "translit": "Wa izal jannatu uzlifat", "translation": "And when Paradise is brought near,"}, {"ayah": 14, "translit": "'Alimat nafsum maaa ahdarat", "translation": "A soul will [then] know what it has brought [with it]."}, {"ayah": 15, "translit": "Falaaa uqsimu bil khunnas", "translation": "So I swear by the retreating stars -"}, {"ayah": 16, "translit": "Al jawaaril kunnas", "translation": "Those that run [their courses] and disappear -"}, {"ayah": 17, "translit": "Wallaili izaa 'as'as", "translation": "And by the night as it closes in"}, {"ayah": 18, "translit": "Wassubhi izaa tanaffas", "translation": "And by the dawn when it breathes"}, {"ayah": 19, "translit": "Innahoo laqawlu rasoolin kareem", "translation": "[That] indeed, the Qur'an is a word [conveyed by] a noble messenger"}, {"ayah": 20, "translit": "Zee quwwatin 'inda zil 'arshi makeen", "translation": "[Who is] possessed of power and with the Owner of the Throne, secure [in position],"}, {"ayah": 21, "translit": "Mutaa'in samma ameen", "translation": "Obeyed there [in the heavens] and trustworthy."}, {"ayah": 22, "translit": "Wa maa saahibukum bimajnoon", "translation": "And your companion is not [at all] mad."}, {"ayah": 23, "translit": "Wa laqad ra aahu bilufuqil mubeen", "translation": "And he has already seen Gabriel in the clear horizon."}, {"ayah": 24, "translit": "Wa maa huwa 'alal ghaibi bidaneen", "translation": "And Muhammad is not a withholder of [knowledge of] the unseen."}, {"ayah": 25, "translit": "Wa maa huwa biqawli shaitaanir rajeem", "translation": "And the Qur'an is not the word of a devil, expelled [from the heavens]."}, {"ayah": 26, "translit": "Fa ayna tazhaboon", "translation": "So where are you going?"}, {"ayah": 27, "translit": "In huwa illaa zikrul lil'aalameen", "translation": "It is not except a reminder to the worlds"}, {"ayah": 28, "translit": "Liman shaaa'a minkum ai yastaqeem", "translation": "For whoever wills among you to take a right course."}, {"ayah": 29, "translit": "Wa maa tashaaa'oona illaaa ai yashaaa 'al laahu Rabbul 'Aalameen", "translation": "And you do not will except that Allah wills - Lord of the worlds."}]}, {"num": 82, "name": "Al-Infitar", "meaning": "The Cleaving", "verses": [{"ayah": 1, "translit": "Izas samaaa'un fatarat", "translation": "When the sky breaks apart"}, {"ayah": 2, "translit": "Wa izal kawaakibun tasarat", "translation": "And when the stars fall, scattering,"}, {"ayah": 3, "translit": "Wa izal bihaaru fujjirat", "translation": "And when the seas are erupted"}, {"ayah": 4, "translit": "Wa izal qubooru bu'sirat", "translation": "And when the [contents of] graves are scattered,"}, {"ayah": 5, "translit": "'Alimat nafsum maa qaddamat wa akhkharat", "translation": "A soul will [then] know what it has put forth and kept back."}, {"ayah": 6, "translit": "Yaaa ayyuhal insaaanu maa gharraka bi Rabbikal kareem", "translation": "O mankind, what has deceived you concerning your Lord, the Generous,"}, {"ayah": 7, "translit": "Allazee khalaqaka fasaw waaka fa'adalak", "translation": "Who created you, proportioned you, and balanced you?"}, {"ayah": 8, "translit": "Feee ayye sooratim maa shaaa'a rakkabak", "translation": "In whatever form He willed has He assembled you."}, {"ayah": 9, "translit": "Kalla bal tukazziboona bid deen", "translation": "No! But you deny the Recompense."}, {"ayah": 10, "translit": "Wa inna 'alaikum lahaa fizeen", "translation": "And indeed, [appointed] over you are keepers,"}, {"ayah": 11, "translit": "Kiraaman kaatibeen", "translation": "Noble and recording;"}, {"ayah": 12, "translit": "Ya'lamoona ma taf'aloon", "translation": "They know whatever you do."}, {"ayah": 13, "translit": "Innal abraara lafee na'eem", "translation": "Indeed, the righteous will be in pleasure,"}, {"ayah": 14, "translit": "Wa innal fujjaara lafee jaheem", "translation": "And indeed, the wicked will be in Hellfire."}, {"ayah": 15, "translit": "Yaslawnahaa Yawmad Deen", "translation": "They will [enter to] burn therein on the Day of Recompense,"}, {"ayah": 16, "translit": "Wa maa hum 'anhaa bighaaa 'ibeen", "translation": "And never therefrom will they be absent."}, {"ayah": 17, "translit": "Wa maaa adraaka maa Yawmud Deen", "translation": "And what can make you know what is the Day of Recompense?"}, {"ayah": 18, "translit": "Summa maaa adraaka maa Yawmud Deen", "translation": "Then, what can make you know what is the Day of Recompense?"}, {"ayah": 19, "translit": "Yawma laa tamliku nafsul linafsin shai'anw walamru yawma'izil lillaah", "translation": "It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah."}]}, {"num": 83, "name": "Al-Mutaffifin", "meaning": "The Defrauding", "verses": [{"ayah": 1, "translit": "Wailul lil mutaffifeen", "translation": "Woe to those who give less [than due],"}, {"ayah": 2, "translit": "Allazeena izak taaloo 'alan naasi yastawfoon", "translation": "Who, when they take a measure from people, take in full."}, {"ayah": 3, "translit": "Wa izaa kaaloohum aw wazanoohum yukhsiroon", "translation": "But if they give by measure or by weight to them, they cause loss."}, {"ayah": 4, "translit": "Alaa yazunnu ulaaa'ika annahum mab'oosoon", "translation": "Do they not think that they will be resurrected"}, {"ayah": 5, "translit": "Li Yawmin 'Azeem", "translation": "For a tremendous Day -"}, {"ayah": 6, "translit": "Yawma yaqoomun naasu li Rabbil 'aalameen", "translation": "The Day when mankind will stand before the Lord of the worlds?"}, {"ayah": 7, "translit": "Kallaaa inna kitaabal fujjaari lafee Sijjeen", "translation": "No! Indeed, the record of the wicked is in sijjeen."}, {"ayah": 8, "translit": "Wa maa adraaka maa Sijjeen", "translation": "And what can make you know what is sijjeen?"}, {"ayah": 9, "translit": "Kitaabum marqoom", "translation": "It is [their destination recorded in] a register inscribed."}, {"ayah": 10, "translit": "Wailuny yawma'izil lil mukazzibeen", "translation": "Woe, that Day, to the deniers,"}, {"ayah": 11, "translit": "Allazeena yukazziboona bi yawmid deen", "translation": "Who deny the Day of Recompense."}, {"ayah": 12, "translit": "Wa maa yukazzibu biheee illaa kullu mu'tadin aseem", "translation": "And none deny it except every sinful transgressor."}, {"ayah": 13, "translit": "Izaa tutlaa'alaihi aayaatunaa qaala asaateerul awwaleen", "translation": "When Our verses are recited to him, he says, \"Legends of the former peoples.\""}, {"ayah": 14, "translit": "Kallaa bal raana 'alaa quloobihim maa kaanoo yaksiboon", "translation": "No! Rather, the stain has covered their hearts of that which they were earning."}, {"ayah": 15, "translit": "Kallaaa innahum 'ar Rabbihim yawma'izil lamah jooboon", "translation": "No! Indeed, from their Lord, that Day, they will be partitioned."}, {"ayah": 16, "translit": "Summa innahum lasaa lul jaheem", "translation": "Then indeed, they will [enter and] burn in Hellfire."}, {"ayah": 17, "translit": "Summa yuqaalu haazal lazee kuntum bihee tukazziboon", "translation": "Then it will be said [to them], \"This is what you used to deny.\""}, {"ayah": 18, "translit": "Kallaaa inna kitaabal abraari lafee'Illiyyeen", "translation": "No! Indeed, the record of the righteous is in 'illiyyun."}, {"ayah": 19, "translit": "Wa maaa adraaka maa 'Illiyyoon", "translation": "And what can make you know what is 'illiyyun?"}, {"ayah": 20, "translit": "Kitaabum marqoom", "translation": "It is [their destination recorded in] a register inscribed"}, {"ayah": 21, "translit": "Yashhadu hul muqarra boon", "translation": "Which is witnessed by those brought near [to Allah]."}, {"ayah": 22, "translit": "Innal abraara lafee Na'eem", "translation": "Indeed, the righteous will be in pleasure"}, {"ayah": 23, "translit": "'Alal araaa'iki yanzuroon", "translation": "On adorned couches, observing."}, {"ayah": 24, "translit": "Ta'rifu fee wujoohihim nadratan na'eem", "translation": "You will recognize in their faces the radiance of pleasure."}, {"ayah": 25, "translit": "Yusqawna mir raheeqim makhtoom", "translation": "They will be given to drink [pure] wine [which was] sealed."}, {"ayah": 26, "translit": "Khitaamuhoo misk; wa fee zaalika falyatanaafasil Mutanaafisoon", "translation": "The last of it is musk. So for this let the competitors compete."}, {"ayah": 27, "translit": "Wa mizaajuhoo min Tasneem", "translation": "And its mixture is of Tasneem,"}, {"ayah": 28, "translit": "'Ainaiy yashrabu bihal muqarraboon", "translation": "A spring from which those near [to Allah] drink."}, {"ayah": 29, "translit": "Innal lazeena ajramoo kaanoo minal lazeena aamanoo yadhakoon", "translation": "Indeed, those who committed crimes used to laugh at those who believed."}, {"ayah": 30, "translit": "Wa izaa marroo bihim yataghaamazoon", "translation": "And when they passed by them, they would exchange derisive glances."}, {"ayah": 31, "translit": "Wa izan qalabooo ilaaa ahlihimun qalaboo fakiheen", "translation": "And when they returned to their people, they would return jesting."}, {"ayah": 32, "translit": "Wa izaa ra awhum qaalooo inna haaa'ulaaa'i ladaaal loon", "translation": "And when they saw them, they would say, \"Indeed, those are truly lost.\""}, {"ayah": 33, "translit": "Wa maaa ursiloo 'alaihim haafizeen", "translation": "But they had not been sent as guardians over them."}, {"ayah": 34, "translit": "Fal yawmal lazeena aamanoo minal kuffaari yadhakoon", "translation": "So Today those who believed are laughing at the disbelievers,"}, {"ayah": 35, "translit": "'Alal araaa'iki yanzuroon", "translation": "On adorned couches, observing."}, {"ayah": 36, "translit": "Hal suwwibal kuffaaru maa kaanoo yaf'aloon", "translation": "Have the disbelievers [not] been rewarded [this Day] for what they used to do?"}]}, {"num": 84, "name": "Al-Inshiqaq", "meaning": "The Sundering", "verses": [{"ayah": 1, "translit": "Izas samaaa'un shaqqat", "translation": "When the sky has split [open]"}, {"ayah": 2, "translit": "Wa azinat li Rabbihaa wa huqqat", "translation": "And has responded to its Lord and was obligated [to do so]"}, {"ayah": 3, "translit": "Wa izal ardu muddat", "translation": "And when the earth has been extended"}, {"ayah": 4, "translit": "Wa alqat maa feehaa wa takhallat", "translation": "And has cast out that within it and relinquished [it]"}, {"ayah": 5, "translit": "Wa azinat li Rabbihaa wa huqqat", "translation": "And has responded to its Lord and was obligated [to do so] -"}, {"ayah": 6, "translit": "Yaaa ayyuhal insaanu innaka kaadihun ilaa Rabbika kad han famulaaqeeh", "translation": "O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it."}, {"ayah": 7, "translit": "Fa ammaa man ootiya kitaabahoo biyameenih", "translation": "Then as for he who is given his record in his right hand,"}, {"ayah": 8, "translit": "Fasawfa yuhaasabu hi saabai yaseeraa", "translation": "He will be judged with an easy account"}, {"ayah": 9, "translit": "Wa yanqalibu ilaaa ahlihee masrooraa", "translation": "And return to his people in happiness."}, {"ayah": 10, "translit": "Wa ammaa man ootiya kitaabahoo waraaa'a zahrih", "translation": "But as for he who is given his record behind his back,"}, {"ayah": 11, "translit": "Fasawfa yad'oo subooraa", "translation": "He will cry out for destruction"}, {"ayah": 12, "translit": "Wa yaslaa sa'eeraa", "translation": "And [enter to] burn in a Blaze."}, {"ayah": 13, "translit": "Innahoo kaana feee ahlihee masrooraa", "translation": "Indeed, he had [once] been among his people in happiness;"}, {"ayah": 14, "translit": "Innahoo zanna al lai yahoor", "translation": "Indeed, he had thought he would never return [to Allah]."}, {"ayah": 15, "translit": "Balaaa inna Rabbahoo kaana bihee baseeraa", "translation": "But yes! Indeed, his Lord was ever of him, Seeing."}, {"ayah": 16, "translit": "Falaaa uqsimu bishshafaq", "translation": "So I swear by the twilight glow"}, {"ayah": 17, "translit": "Wallaili wa maa wasaq", "translation": "And [by] the night and what it envelops"}, {"ayah": 18, "translit": "Walqamari izat tasaq", "translation": "And [by] the moon when it becomes full"}, {"ayah": 19, "translit": "Latarkabunna tabaqan 'an tabaq", "translation": "[That] you will surely experience state after state."}, {"ayah": 20, "translit": "Famaa lahum laa yu'minoon", "translation": "So what is [the matter] with them [that] they do not believe,"}, {"ayah": 21, "translit": "Wa izaa quri'a 'alaihimul Quraanu laa yasjudoon", "translation": "And when the Qur'an is recited to them, they do not prostrate [to Allah]?"}, {"ayah": 22, "translit": "Balil lazeena kafaroo yukazziboon", "translation": "But those who have disbelieved deny,"}, {"ayah": 23, "translit": "Wallaahu a'lamu bimaa yoo'oon", "translation": "And Allah is most knowing of what they keep within themselves."}, {"ayah": 24, "translit": "Fabashshirhum bi'azaabin aleem", "translation": "So give them tidings of a painful punishment,"}, {"ayah": 25, "translit": "Illal lazeena aamanoo wa 'amilus saalihaati lahum ajrun ghairu mamnoon", "translation": "Except for those who believe and do righteous deeds. For them is a reward uninterrupted."}]}, {"num": 85, "name": "Al-Buruj", "meaning": "The Mansions of the Stars", "verses": [{"ayah": 1, "translit": "Wassamaaa'i zaatil burooj", "translation": "By the sky containing great stars"}, {"ayah": 2, "translit": "Wal yawmil maw'ood", "translation": "And [by] the promised Day"}, {"ayah": 3, "translit": "Wa shaahidinw wa mashhood", "translation": "And [by] the witness and what is witnessed,"}, {"ayah": 4, "translit": "Qutila as haabul ukhdood", "translation": "Cursed were the companions of the trench"}, {"ayah": 5, "translit": "Annaari zaatil waqood", "translation": "[Containing] the fire full of fuel,"}, {"ayah": 6, "translit": "Iz hum 'alaihaa qu'ood", "translation": "When they were sitting near it"}, {"ayah": 7, "translit": "Wa hum 'alaa maa yaf'aloona bilmu 'mineena shuhood", "translation": "And they, to what they were doing against the believers, were witnesses."}, {"ayah": 8, "translit": "Wa maa naqamoo minhum illaaa aiyu'minoo billaahil 'azeezil Hameed", "translation": "And they resented them not except because they believed in Allah, the Exalted in Might, the Praiseworthy,"}, {"ayah": 9, "translit": "Allazee lahoo mulkus samaawaati wal ard; wallaahu 'alaa kulli shai 'in Shaheed", "translation": "To whom belongs the dominion of the heavens and the earth. And Allah, over all things, is Witness."}, {"ayah": 10, "translit": "Innal lazeena fatanul mu'mineena wal mu'minaati summa lam yatooboo falahum 'azaabu Jahannama wa lahum 'azaabul hareeq", "translation": "Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire."}, {"ayah": 11, "translit": "Innal lazeena aamanoo wa 'amilus saalihaati lahum Jannaatun tajree min tahtihal anhaar; zaalikal fawzul kabeer", "translation": "Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment."}, {"ayah": 12, "translit": "Inna batsha Rabbika lashadeed", "translation": "Indeed, the vengeance of your Lord is severe."}, {"ayah": 13, "translit": "Innahoo Huwa yubdi'u wa yu'eed", "translation": "Indeed, it is He who originates [creation] and repeats."}, {"ayah": 14, "translit": "Wa Huwal Ghafoorul Wadood", "translation": "And He is the Forgiving, the Affectionate,"}, {"ayah": 15, "translit": "Zul 'Arshil Majeed", "translation": "Honorable Owner of the Throne,"}, {"ayah": 16, "translit": "Fa' 'aalul limaa yureed", "translation": "Effecter of what He intends."}, {"ayah": 17, "translit": "Hal ataaka hadeesul junood", "translation": "Has there reached you the story of the soldiers -"}, {"ayah": 18, "translit": "Fir'awna wa Samood", "translation": "[Those of] Pharaoh and Thamud?"}, {"ayah": 19, "translit": "Balil lazeena kafaroo fee takzeeb", "translation": "But they who disbelieve are in [persistent] denial,"}, {"ayah": 20, "translit": "Wallaahu minw waraaa'ihim muheet", "translation": "While Allah encompasses them from behind."}, {"ayah": 21, "translit": "Bal huwa Quraanum Majeed", "translation": "But this is an honored Qur'an"}, {"ayah": 22, "translit": "Fee Lawhim Mahfooz", "translation": "[Inscribed] in a Preserved Slate."}]}, {"num": 86, "name": "At-Tariq", "meaning": "The Morning Star", "verses": [{"ayah": 1, "translit": "Wassamaaa'i wattaariq", "translation": "By the sky and the night comer -"}, {"ayah": 2, "translit": "Wa maaa adraaka mattaariq", "translation": "And what can make you know what is the night comer?"}, {"ayah": 3, "translit": "Annajmus saaqib", "translation": "It is the piercing star -"}, {"ayah": 4, "translit": "In kullu nafsil lammaa 'alaihaa haafiz", "translation": "There is no soul but that it has over it a protector."}, {"ayah": 5, "translit": "Fal yanzuril insaanu mimma khuliq", "translation": "So let man observe from what he was created."}, {"ayah": 6, "translit": "Khuliqa mim maaa'in daafiq", "translation": "He was created from a fluid, ejected,"}, {"ayah": 7, "translit": "Yakhruju mim bainissulbi wat taraaa'ib", "translation": "Emerging from between the backbone and the ribs."}, {"ayah": 8, "translit": "Innahoo 'alaa raj'ihee laqaadir", "translation": "Indeed, Allah, to return him [to life], is Able."}, {"ayah": 9, "translit": "Yawma tublas saraaa'ir", "translation": "The Day when secrets will be put on trial,"}, {"ayah": 10, "translit": "Famaa lahoo min quwwatinw wa laa naasir", "translation": "Then man will have no power or any helper."}, {"ayah": 11, "translit": "Wassamaaa'i zaatir raj'", "translation": "By the sky which returns [rain]"}, {"ayah": 12, "translit": "Wal ardi zaatis sad'", "translation": "And [by] the earth which cracks open,"}, {"ayah": 13, "translit": "Innahoo laqawlun fasl", "translation": "Indeed, the Qur'an is a decisive statement,"}, {"ayah": 14, "translit": "Wa maa huwa bil hazl", "translation": "And it is not amusement."}, {"ayah": 15, "translit": "Innahum yakeedoona kaidaa", "translation": "Indeed, they are planning a plan,"}, {"ayah": 16, "translit": "Wa akeedu kaidaa", "translation": "But I am planning a plan."}, {"ayah": 17, "translit": "Famahhilil kaafireena amhilhum ruwaidaa", "translation": "So allow time for the disbelievers. Leave them awhile."}]}, {"num": 87, "name": "Al-A'la", "meaning": "The Most High", "verses": [{"ayah": 1, "translit": "Sabbihisma Rabbikal A'laa", "translation": "Exalt the name of your Lord, the Most High,"}, {"ayah": 2, "translit": "Allazee khalaqa fasawwaa", "translation": "Who created and proportioned"}, {"ayah": 3, "translit": "Wallazee qaddara fahadaa", "translation": "And who destined and [then] guided"}, {"ayah": 4, "translit": "Wallazeee akhrajal mar'aa", "translation": "And who brings out the pasture"}, {"ayah": 5, "translit": "Faja'alahoo ghusaaa'an ahwaa", "translation": "And [then] makes it black stubble."}, {"ayah": 6, "translit": "Sanuqri'uka falaa tansaaa", "translation": "We will make you recite, [O Muhammad], and you will not forget,"}, {"ayah": 7, "translit": "Illaa maa shaaa'al laah; innahoo ya'lamul jahra wa maa yakhfaa", "translation": "Except what Allah should will. Indeed, He knows what is declared and what is hidden."}, {"ayah": 8, "translit": "Wa nu-yassiruka lilyusraa", "translation": "And We will ease you toward ease."}, {"ayah": 9, "translit": "Fazakkir in nafa'atizzikraa", "translation": "So remind, if the reminder should benefit;"}, {"ayah": 10, "translit": "Sa yazzakkaru maiyakhshaa", "translation": "He who fears [Allah] will be reminded."}, {"ayah": 11, "translit": "Wa yatajannabuhal ashqaa", "translation": "But the wretched one will avoid it -"}, {"ayah": 12, "translit": "Allazee yaslan Naaral kubraa", "translation": "[He] who will [enter and] burn in the greatest Fire,"}, {"ayah": 13, "translit": "Summa laa yamootu feehaa wa laa yahyaa", "translation": "Neither dying therein nor living."}, {"ayah": 14, "translit": "Qad aflaha man tazakkaa", "translation": "He has certainly succeeded who purifies himself"}, {"ayah": 15, "translit": "Wa zakaras ma Rabbihee fasallaa", "translation": "And mentions the name of his Lord and prays."}, {"ayah": 16, "translit": "Bal tu'siroonal hayaatad dunyaa", "translation": "But you prefer the worldly life,"}, {"ayah": 17, "translit": "Wal Aakhiratu khairunw wa abqaa", "translation": "While the Hereafter is better and more enduring."}, {"ayah": 18, "translit": "Inna haazaa lafis suhu fil oolaa", "translation": "Indeed, this is in the former scriptures,"}, {"ayah": 19, "translit": "Suhufi Ibraaheema wa Moosaa", "translation": "The scriptures of Abraham and Moses."}]}, {"num": 88, "name": "Al-Ghashiyah", "meaning": "The Overwhelming", "verses": [{"ayah": 1, "translit": "Hal ataaka hadeesul ghaashiyah", "translation": "Has there reached you the report of the Overwhelming [event]?"}, {"ayah": 2, "translit": "Wujoohuny yawma 'izin khaashi'ah", "translation": "[Some] faces, that Day, will be humbled,"}, {"ayah": 3, "translit": "'Aamilatun naasibah", "translation": "Working [hard] and exhausted."}, {"ayah": 4, "translit": "Taslaa naaran haamiyah", "translation": "They will [enter to] burn in an intensely hot Fire."}, {"ayah": 5, "translit": "Tusqaa min 'aynin aaniyah", "translation": "They will be given drink from a boiling spring."}, {"ayah": 6, "translit": "Laisa lahum ta'aamun illaa min daree'", "translation": "For them there will be no food except from a poisonous, thorny plant"}, {"ayah": 7, "translit": "Laa yusminu wa laa yughnee min joo'", "translation": "Which neither nourishes nor avails against hunger."}, {"ayah": 8, "translit": "Wujoohuny yawma 'izin naa'imah", "translation": "[Other] faces, that Day, will show pleasure."}, {"ayah": 9, "translit": "Lisa'yihaa raadiyah", "translation": "With their effort [they are] satisfied"}, {"ayah": 10, "translit": "Fee jannatin 'aaliyah", "translation": "In an elevated garden,"}, {"ayah": 11, "translit": "Laa tasma'u feehaa laaghiyah", "translation": "Wherein they will hear no unsuitable speech."}, {"ayah": 12, "translit": "Feehaa 'aynun jaariyah", "translation": "Within it is a flowing spring."}, {"ayah": 13, "translit": "Feehaa sururum marfoo'ah", "translation": "Within it are couches raised high"}, {"ayah": 14, "translit": "Wa akwaabum mawdoo 'ah", "translation": "And cups put in place"}, {"ayah": 15, "translit": "Wa namaariqu masfoofah", "translation": "And cushions lined up"}, {"ayah": 16, "translit": "Wa zaraabiyyu mabsoosah", "translation": "And carpets spread around."}, {"ayah": 17, "translit": "Afalaa yanzuroona ilalibili kaifa khuliqat", "translation": "Then do they not look at the camels - how they are created?"}, {"ayah": 18, "translit": "Wa ilas samaaa'i kaifa rufi'at", "translation": "And at the sky - how it is raised?"}, {"ayah": 19, "translit": "Wa ilal jibaali kaifa nusibat", "translation": "And at the mountains - how they are erected?"}, {"ayah": 20, "translit": "Wa ilal ardi kaifa sutihat", "translation": "And at the earth - how it is spread out?"}, {"ayah": 21, "translit": "Fazakkir innama anta Muzakkir", "translation": "So remind, [O Muhammad]; you are only a reminder."}, {"ayah": 22, "translit": "Lasta 'alaihim bimusaitir", "translation": "You are not over them a controller."}, {"ayah": 23, "translit": "Illaa man tawallaa wa kafar", "translation": "However, he who turns away and disbelieves -"}, {"ayah": 24, "translit": "Fa yu'azzibuhul laahul 'azaabal akbar", "translation": "Then Allah will punish him with the greatest punishment."}, {"ayah": 25, "translit": "Innaa ilainaaa iyaabahum", "translation": "Indeed, to Us is their return."}, {"ayah": 26, "translit": "Summa inna 'alainaa hisaabahum", "translation": "Then indeed, upon Us is their account."}]}, {"num": 89, "name": "Al-Fajr", "meaning": "The Dawn", "verses": [{"ayah": 1, "translit": "Wal-Fajr", "translation": "By the dawn"}, {"ayah": 2, "translit": "Wa layaalin 'ashr", "translation": "And [by] ten nights"}, {"ayah": 3, "translit": "Wash shaf'i wal watr", "translation": "And [by] the even [number] and the odd"}, {"ayah": 4, "translit": "Wallaili izaa yasr", "translation": "And [by] the night when it passes,"}, {"ayah": 5, "translit": "Hal fee zaalika qasamul lizee hijr", "translation": "Is there [not] in [all] that an oath [sufficient] for one of perception?"}, {"ayah": 6, "translit": "Alam tara kaifa fa'ala rabbuka bi'aad", "translation": "Have you not considered how your Lord dealt with 'Aad -"}, {"ayah": 7, "translit": "Iramaa zaatil 'imaad", "translation": "[With] Iram - who had lofty pillars,"}, {"ayah": 8, "translit": "Allatee lam yukhlaq misluhaa fil bilaad", "translation": "The likes of whom had never been created in the land?"}, {"ayah": 9, "translit": "Wa samoodal lazeena jaabus sakhra bil waad", "translation": "And [with] Thamud, who carved out the rocks in the valley?"}, {"ayah": 10, "translit": "Wa fir'awna zil awtaad", "translation": "And [with] Pharaoh, owner of the stakes? -"}, {"ayah": 11, "translit": "Allazeena taghaw fil bilaad", "translation": "[All of] whom oppressed within the lands"}, {"ayah": 12, "translit": "Fa aksaroo feehal fasaad", "translation": "And increased therein the corruption."}, {"ayah": 13, "translit": "Fasabba 'alaihim Rabbuka sawta 'azaab", "translation": "So your Lord poured upon them a scourge of punishment."}, {"ayah": 14, "translit": "Inna Rabbaka labil mirsaad", "translation": "Indeed, your Lord is in observation."}, {"ayah": 15, "translit": "Fa ammal insaanu izaa mab talaahu Rabbuhoo fa akramahoo wa na' 'amahoo fa yaqoolu Rabbeee akraman", "translation": "And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, \"My Lord has honored me.\""}, {"ayah": 16, "translit": "Wa ammaaa izaa mabtalaahu faqadara 'alaihi rizqahoo fa yaqoolu Rabbeee ahaanan", "translation": "But when He tries him and restricts his provision, he says, \"My Lord has humiliated me.\""}, {"ayah": 17, "translit": "Kalla bal laa tukrimooo nal yateem", "translation": "No! But you do not honor the orphan"}, {"ayah": 18, "translit": "Wa laa tahaaaddoona 'alaata'aamil miskeen", "translation": "And you do not encourage one another to feed the poor."}, {"ayah": 19, "translit": "Wa taakuloonat turaasa aklal lammaa", "translation": "And you consume inheritance, devouring [it] altogether,"}, {"ayah": 20, "translit": "Wa tuhibboonal maala hubban jammaa", "translation": "And you love wealth with immense love."}, {"ayah": 21, "translit": "Kallaaa izaaa dukkatil ardu dakkan dakka", "translation": "No! When the earth has been leveled - pounded and crushed -"}, {"ayah": 22, "translit": "Wa jaaa'a Rabbuka wal malaku saffan saffaa", "translation": "And your Lord has come and the angels, rank upon rank,"}, {"ayah": 23, "translit": "Wa jeee'a yawma'izim bi jahannnam; Yawma 'iziny yatazakkarul insaanu wa annaa lahuz zikraa", "translation": "And brought [within view], that Day, is Hell - that Day, man will remember, but what good to him will be the remembrance?"}, {"ayah": 24, "translit": "Yaqoolu yaa laitanee qaddamtu lihayaatee", "translation": "He will say, \"Oh, I wish I had sent ahead [some good] for my life.\""}, {"ayah": 25, "translit": "Fa Yawma izil laa yu'azzibu 'azaabahooo ahad", "translation": "So on that Day, none will punish [as severely] as His punishment,"}, {"ayah": 26, "translit": "Wa laa yoosiqu wasaaqa hooo ahad", "translation": "And none will bind [as severely] as His binding [of the evildoers]."}, {"ayah": 27, "translit": "Yaaa ayyatuhan nafsul mutma 'innah", "translation": "[To the righteous it will be said], \"O reassured soul,"}, {"ayah": 28, "translit": "Irji'eee ilaa Rabbiki raadiyatam mardiyyah", "translation": "Return to your Lord, well-pleased and pleasing [to Him],"}, {"ayah": 29, "translit": "Fadkhulee fee 'ibaadee", "translation": "And enter among My [righteous] servants"}, {"ayah": 30, "translit": "Wadkhulee jannatee", "translation": "And enter My Paradise.\""}]}, {"num": 90, "name": "Al-Balad", "meaning": "The City", "verses": [{"ayah": 1, "translit": "Laaa uqsimu bihaazal balad", "translation": "I swear by this city, Makkah -"}, {"ayah": 2, "translit": "Wa anta hillum bihaazal balad", "translation": "And you, [O Muhammad], are free of restriction in this city -"}, {"ayah": 3, "translit": "Wa waalidinw wa maa walad", "translation": "And [by] the father and that which was born [of him],"}, {"ayah": 4, "translit": "Laqad khalaqnal insaana fee kabad", "translation": "We have certainly created man into hardship."}, {"ayah": 5, "translit": "Ayahsabu al-lai yaqdira 'alaihi ahad", "translation": "Does he think that never will anyone overcome him?"}, {"ayah": 6, "translit": "Yaqoolu ahlaktu maalal lubadaa", "translation": "He says, \"I have spent wealth in abundance.\""}, {"ayah": 7, "translit": "Ayahsabu al lam yarahooo ahad", "translation": "Does he think that no one has seen him?"}, {"ayah": 8, "translit": "Alam naj'al lahoo 'aynayn", "translation": "Have We not made for him two eyes?"}, {"ayah": 9, "translit": "Wa lisaananw wa shafatayn", "translation": "And a tongue and two lips?"}, {"ayah": 10, "translit": "Wa hadaynaahun najdayn", "translation": "And have shown him the two ways?"}, {"ayah": 11, "translit": "Falaq tahamal-'aqabah", "translation": "But he has not broken through the difficult pass."}, {"ayah": 12, "translit": "Wa maaa adraaka mal'aqabah", "translation": "And what can make you know what is [breaking through] the difficult pass?"}, {"ayah": 13, "translit": "Fakku raqabah", "translation": "It is the freeing of a slave"}, {"ayah": 14, "translit": "Aw it'aamun fee yawmin zee masghabah", "translation": "Or feeding on a day of severe hunger"}, {"ayah": 15, "translit": "Yateeman zaa maqrabah", "translation": "An orphan of near relationship"}, {"ayah": 16, "translit": "Aw miskeenan zaa matrabah", "translation": "Or a needy person in misery"}, {"ayah": 17, "translit": "Summa kaana minal lazeena aamanoo wa tawaasaw bissabri wa tawaasaw bilmarhamah", "translation": "And then being among those who believed and advised one another to patience and advised one another to compassion."}, {"ayah": 18, "translit": "Ulaaa'ika As-haabul maimanah", "translation": "Those are the companions of the right."}, {"ayah": 19, "translit": "Wallazeena kafaroo bi aayaatinaa hum as-haabul Mash'amah", "translation": "But they who disbelieved in Our signs - those are the companions of the left."}, {"ayah": 20, "translit": "Alaihim naarum mu'sadah", "translation": "Over them will be fire closed in."}]}, {"num": 91, "name": "Ash-Shams", "meaning": "The Sun", "verses": [{"ayah": 1, "translit": "Wash shamsi wa duhaa haa", "translation": "By the sun and its brightness"}, {"ayah": 2, "translit": "Wal qamari izaa talaa haa", "translation": "And [by] the moon when it follows it"}, {"ayah": 3, "translit": "Wannahaari izaa jallaa haa", "translation": "And [by] the day when it displays it"}, {"ayah": 4, "translit": "Wallaili izaa yaghshaa haa", "translation": "And [by] the night when it covers it"}, {"ayah": 5, "translit": "Wassamaaa'i wa maa banaahaa", "translation": "And [by] the sky and He who constructed it"}, {"ayah": 6, "translit": "Wal ardi wa maa tahaahaa", "translation": "And [by] the earth and He who spread it"}, {"ayah": 7, "translit": "Wa nafsinw wa maa sawwaahaa", "translation": "And [by] the soul and He who proportioned it"}, {"ayah": 8, "translit": "Fa-alhamahaa fujoorahaa wa taqwaahaa", "translation": "And inspired it [with discernment of] its wickedness and its righteousness,"}, {"ayah": 9, "translit": "Qad aflaha man zakkaahaa", "translation": "He has succeeded who purifies it,"}, {"ayah": 10, "translit": "Wa qad khaaba man dassaahaa", "translation": "And he has failed who instills it [with corruption]."}, {"ayah": 11, "translit": "Kazzabat Samoodu bi taghwaahaaa", "translation": "Thamud denied [their prophet] by reason of their transgression,"}, {"ayah": 12, "translit": "Izim ba'asa ashqaahaa", "translation": "When the most wretched of them was sent forth."}, {"ayah": 13, "translit": "Faqaala lahum Rasoolul laahi naaqatal laahi wa suqiyaahaa", "translation": "And the messenger of Allah [Salih] said to them, \"[Do not harm] the she-camel of Allah or [prevent her from] her drink.\""}, {"ayah": 14, "translit": "Fakazzaboohu fa'aqaroohaa fadamdama 'alaihim Rabbuhum bizambihim fasaw waahaa", "translation": "But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them]."}, {"ayah": 15, "translit": "Wa laa yakhaafu'uqbaahaa", "translation": "And He does not fear the consequence thereof."}]}, {"num": 92, "name": "Al-Layl", "meaning": "The Night", "verses": [{"ayah": 1, "translit": "Wallaili izaa yaghshaa", "translation": "By the night when it covers"}, {"ayah": 2, "translit": "Wannahaari izaa tajalla", "translation": "And [by] the day when it appears"}, {"ayah": 3, "translit": "Wa maa khalaqaz zakara wal unthaa", "translation": "And [by] He who created the male and female,"}, {"ayah": 4, "translit": "Inna sa'yakum lashattaa", "translation": "Indeed, your efforts are diverse."}, {"ayah": 5, "translit": "Fa ammaa man a'taa wattaqaa", "translation": "As for he who gives and fears Allah"}, {"ayah": 6, "translit": "Wa saddaqa bil husnaa", "translation": "And believes in the best [reward],"}, {"ayah": 7, "translit": "Fasanu yassiruhoo lilyusraa", "translation": "We will ease him toward ease."}, {"ayah": 8, "translit": "Wa ammaa man bakhila wastaghnaa", "translation": "But as for he who withholds and considers himself free of need"}, {"ayah": 9, "translit": "Wa kazzaba bil husnaa", "translation": "And denies the best [reward],"}, {"ayah": 10, "translit": "Fasanu yassiruhoo lil'usraa", "translation": "We will ease him toward difficulty."}, {"ayah": 11, "translit": "Wa maa yughnee 'anhu maaluhooo izaa taraddaa", "translation": "And what will his wealth avail him when he falls?"}, {"ayah": 12, "translit": "Inna 'alainaa lal hudaa", "translation": "Indeed, [incumbent] upon Us is guidance."}, {"ayah": 13, "translit": "Wa inna lanaa lal Aakhirata wal oolaa", "translation": "And indeed, to Us belongs the Hereafter and the first [life]."}, {"ayah": 14, "translit": "Fa anzartukum naaran talazzaa", "translation": "So I have warned you of a Fire which is blazing."}, {"ayah": 15, "translit": "Laa yaslaahaaa illal ashqaa", "translation": "None will [enter to] burn therein except the most wretched one."}, {"ayah": 16, "translit": "Allazee kazzaba wa tawallaa", "translation": "Who had denied and turned away."}, {"ayah": 17, "translit": "Wa sa yujannnabuhal atqaa", "translation": "But the righteous one will avoid it -"}, {"ayah": 18, "translit": "Allazee yu'tee maalahoo yatazakkaa", "translation": "[He] who gives [from] his wealth to purify himself"}, {"ayah": 19, "translit": "Wa maa li ahadin 'indahoo min ni'matin tujzaaa", "translation": "And not [giving] for anyone who has [done him] a favor to be rewarded"}, {"ayah": 20, "translit": "Illab tighaaa'a wajhi rabbihil a 'laa", "translation": "But only seeking the countenance of his Lord, Most High."}, {"ayah": 21, "translit": "Wa lasawfa yardaa", "translation": "And he is going to be satisfied."}]}, {"num": 93, "name": "Ad-Duhaa", "meaning": "The Morning Hours", "verses": [{"ayah": 1, "translit": "Wad duhaa", "translation": "By the morning brightness"}, {"ayah": 2, "translit": "Wal laili iza sajaa", "translation": "And [by] the night when it covers with darkness,"}, {"ayah": 3, "translit": "Ma wad da'aka rabbuka wa ma qalaa", "translation": "Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you]."}, {"ayah": 4, "translit": "Walal-aakhiratu khairul laka minal-oola", "translation": "And the Hereafter is better for you than the first [life]."}, {"ayah": 5, "translit": "Wa la sawfa y'uteeka rabbuka fatarda", "translation": "And your Lord is going to give you, and you will be satisfied."}, {"ayah": 6, "translit": "Alam ya jidka yateeman fa aawaa", "translation": "Did He not find you an orphan and give [you] refuge?"}, {"ayah": 7, "translit": "Wa wa jadaka daal lan fahada", "translation": "And He found you lost and guided [you],"}, {"ayah": 8, "translit": "Wa wa jadaka 'aa-ilan fa aghnaa", "translation": "And He found you poor and made [you] self-sufficient."}, {"ayah": 9, "translit": "Fa am mal yateema fala taqhar", "translation": "So as for the orphan, do not oppress [him]."}, {"ayah": 10, "translit": "Wa am mas saa-ila fala tanhar", "translation": "And as for the petitioner, do not repel [him]."}, {"ayah": 11, "translit": "Wa amma bi ni'mati rabbika fahad dith", "translation": "But as for the favor of your Lord, report [it]."}]}, {"num": 94, "name": "Ash-Sharh", "meaning": "The Relief", "verses": [{"ayah": 1, "translit": "Alam nashrah laka sadrak", "translation": "Did We not expand for you, [O Muhammad], your breast?"}, {"ayah": 2, "translit": "Wa wa d'ana 'anka wizrak", "translation": "And We removed from you your burden"}, {"ayah": 3, "translit": "Allazee anqada zahrak", "translation": "Which had weighed upon your back"}, {"ayah": 4, "translit": "Wa raf 'ana laka zikrak", "translation": "And raised high for you your repute."}, {"ayah": 5, "translit": "Fa inna ma'al usri yusra", "translation": "For indeed, with hardship [will be] ease."}, {"ayah": 6, "translit": "Inna ma'al 'usri yusra", "translation": "Indeed, with hardship [will be] ease."}, {"ayah": 7, "translit": "Fa iza faragh ta fansab", "translation": "So when you have finished [your duties], then stand up [for worship]."}, {"ayah": 8, "translit": "Wa ilaa rabbika far ghab", "translation": "And to your Lord direct [your] longing."}]}, {"num": 95, "name": "At-Tin", "meaning": "The Fig", "verses": [{"ayah": 1, "translit": "Wat teeni waz zaitoon", "translation": "By the fig and the olive"}, {"ayah": 2, "translit": "Wa toori sineen", "translation": "And [by] Mount Sinai"}, {"ayah": 3, "translit": "Wa haazal balad-il ameen", "translation": "And [by] this secure city [Makkah],"}, {"ayah": 4, "translit": "Laqad khalaqnal insaana fee ahsani taqweem", "translation": "We have certainly created man in the best of stature;"}, {"ayah": 5, "translit": "Thumma ra dad naahu asfala saafileen", "translation": "Then We return him to the lowest of the low,"}, {"ayah": 6, "translit": "Ill-lal lazeena aamanoo wa 'amilus saalihaati; falahum ajrun ghairu mamnoon", "translation": "Except for those who believe and do righteous deeds, for they will have a reward uninterrupted."}, {"ayah": 7, "translit": "Fama yu kaz zibuka b'adu bid deen", "translation": "So what yet causes you to deny the Recompense?"}, {"ayah": 8, "translit": "Alai sal laahu bi-ahkamil haakimeen", "translation": "Is not Allah the most just of judges?"}]}, {"num": 96, "name": "Al-Alaq", "meaning": "The Clot", "verses": [{"ayah": 1, "translit": "Iqra bismi rab bikal lazee khalaq", "translation": "Recite in the name of your Lord who created -"}, {"ayah": 2, "translit": "Khalaqal insaana min 'alaq", "translation": "Created man from a clinging substance."}, {"ayah": 3, "translit": "Iqra wa rab bukal akram", "translation": "Recite, and your Lord is the most Generous -"}, {"ayah": 4, "translit": "Al lazee 'allama bil qalam", "translation": "Who taught by the pen -"}, {"ayah": 5, "translit": "'Al lamal insaana ma lam y'alam", "translation": "Taught man that which he knew not."}, {"ayah": 6, "translit": "Kallaa innal insaana layatghaa", "translation": "No! [But] indeed, man transgresses"}, {"ayah": 7, "translit": "Ar-ra aahus taghnaa", "translation": "Because he sees himself self-sufficient."}, {"ayah": 8, "translit": "Innna ilaa rabbikar ruj'aa", "translation": "Indeed, to your Lord is the return."}, {"ayah": 9, "translit": "Ara-aital lazee yanhaa", "translation": "Have you seen the one who forbids"}, {"ayah": 10, "translit": "'Abdan iza sallaa", "translation": "A servant when he prays?"}, {"ayah": 11, "translit": "Ara-aita in kana 'alal hudaa", "translation": "Have you seen if he is upon guidance"}, {"ayah": 12, "translit": "Au amara bit taqwaa", "translation": "Or enjoins righteousness?"}, {"ayah": 13, "translit": "Ara-aita in kaz zaba wa ta walla", "translation": "Have you seen if he denies and turns away -"}, {"ayah": 14, "translit": "Alam y'alam bi-an nal lahaa yaraa", "translation": "Does he not know that Allah sees?"}, {"ayah": 15, "translit": "Kalla la illam yantahi la nasfa'am bin nasiyah", "translation": "No! If he does not desist, We will surely drag him by the forelock -"}, {"ayah": 16, "translit": "Nasiyatin kazi batin khaatiyah", "translation": "A lying, sinning forelock."}, {"ayah": 17, "translit": "Fal yad'u naadiyah", "translation": "Then let him call his associates;"}, {"ayah": 18, "translit": "Sanad 'uz zabaaniyah", "translation": "We will call the angels of Hell."}, {"ayah": 19, "translit": "Kalla; la tuti'hu wasjud waqtarib", "translation": "No! Do not obey him. But prostrate and draw near [to Allah]."}]}, {"num": 97, "name": "Al-Qadr", "meaning": "The Power", "verses": [{"ayah": 1, "translit": "Innaa anzalnaahu fee lailatil qadr", "translation": "Indeed, We sent the Qur'an down during the Night of Decree."}, {"ayah": 2, "translit": "Wa maa adraaka ma lailatul qadr", "translation": "And what can make you know what is the Night of Decree?"}, {"ayah": 3, "translit": "Lailatul qadri khairum min alfee shahr", "translation": "The Night of Decree is better than a thousand months."}, {"ayah": 4, "translit": "Tanaz zalul malaa-ikatu war roohu feeha bi izni-rab bihim min kulli amr", "translation": "The angels and the Spirit descend therein by permission of their Lord for every matter."}, {"ayah": 5, "translit": "Salaamun hiya hattaa mat la'il fajr", "translation": "Peace it is until the emergence of dawn."}]}, {"num": 98, "name": "Al-Bayyinah", "meaning": "The Clear Proof", "verses": [{"ayah": 1, "translit": "Lam ya kunil lazeena kafaru min ahlil kitaabi wal mushri keena mun fak keena hattaa ta-tiya humul bayyinah", "translation": "Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence -"}, {"ayah": 2, "translit": "Rasoolum minal laahi yatlu suhufam mutahharah", "translation": "A Messenger from Allah, reciting purified scriptures"}, {"ayah": 3, "translit": "Feeha kutubun qaiyimah", "translation": "Within which are correct writings."}, {"ayah": 4, "translit": "Wa maa tafarraqal lazeena ootul kitaaba il-la mim b'adi ma jaa-at humul baiyyinah", "translation": "Nor did those who were given the Scripture become divided until after there had come to them clear evidence."}, {"ayah": 5, "translit": "Wa maa umiroo il-la liy'abu dul laaha mukhliseena lahud-deena huna faa-a wa yuqeemus salaahta wa yu-tuz zakaata; wa zaalika deenul qaiyimah", "translation": "And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion."}, {"ayah": 6, "translit": "Innal lazeena kafaru min ahlil kitaabi wal mushri keena fee nari jahan nama khaali deena feeha; ulaa-ika hum shar rul ba reeyah", "translation": "Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures."}, {"ayah": 7, "translit": "Innal lazeena aamanu wa 'amilus saalihaati ula-ika hum khairul bareey yah", "translation": "Indeed, they who have believed and done righteous deeds - those are the best of creatures."}, {"ayah": 8, "translit": "Jazaa-uhum inda rabbihim jan naatu 'adnin tajree min tahtihal an haaru khalideena feeha abada; radiy-yallaahu 'anhum wa ra du 'an zaalika liman khashiya rabbah.", "translation": "Their reward with Allah will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allah being pleased with them and they with Him. That is for whoever has feared his Lord."}]}, {"num": 99, "name": "Az-Zalzalah", "meaning": "The Earthquake", "verses": [{"ayah": 1, "translit": "Izaa zul zilatil ardu zil zaalaha", "translation": "When the earth is shaken with its [final] earthquake"}, {"ayah": 2, "translit": "Wa akh rajatil ardu athqaalaha", "translation": "And the earth discharges its burdens"}, {"ayah": 3, "translit": "Wa qaalal insaanu ma laha", "translation": "And man says, \"What is [wrong] with it?\" -"}, {"ayah": 4, "translit": "Yawmaa izin tuhad dithu akhbaaraha", "translation": "That Day, it will report its news"}, {"ayah": 5, "translit": "Bi-anna rabbaka awhaa laha", "translation": "Because your Lord has commanded it."}, {"ayah": 6, "translit": "Yawma iziy yas durun naasu ash tatal liyuraw a'maalahum", "translation": "That Day, the people will depart separated [into categories] to be shown [the result of] their deeds."}, {"ayah": 7, "translit": "Famaiy ya'mal mithqala zarratin khai raiy-yarah", "translation": "So whoever does an atom's weight of good will see it,"}, {"ayah": 8, "translit": "Wa maiy-y'amal mithqala zarratin sharraiy-yarah", "translation": "And whoever does an atom's weight of evil will see it."}]}, {"num": 100, "name": "Al-Adiyat", "meaning": "The Courser", "verses": [{"ayah": 1, "translit": "Wal'aadi yaati dabha", "translation": "By the racers, panting,"}, {"ayah": 2, "translit": "Fal moori yaati qadha", "translation": "And the producers of sparks [when] striking"}, {"ayah": 3, "translit": "Fal mugheeraati subha", "translation": "And the chargers at dawn,"}, {"ayah": 4, "translit": "Fa atharna bihee naq'a", "translation": "Stirring up thereby [clouds of] dust,"}, {"ayah": 5, "translit": "Fawa satna bihee jam'a", "translation": "Arriving thereby in the center collectively,"}, {"ayah": 6, "translit": "Innal-insana lirabbihee lakanood", "translation": "Indeed mankind, to his Lord, is ungrateful."}, {"ayah": 7, "translit": "Wa innahu 'alaa zaalika la shaheed", "translation": "And indeed, he is to that a witness."}, {"ayah": 8, "translit": "Wa innahu lihubbil khairi la shadeed", "translation": "And indeed he is, in love of wealth, intense."}, {"ayah": 9, "translit": "Afala ya'lamu iza b'uthira ma filquboor", "translation": "But does he not know that when the contents of the graves are scattered"}, {"ayah": 10, "translit": "Wa hussila maa fis sudoor", "translation": "And that within the breasts is obtained,"}, {"ayah": 11, "translit": "Inna rabbahum bihim yauma 'izil la khabeer", "translation": "Indeed, their Lord with them, that Day, is [fully] Acquainted."}]}, {"num": 101, "name": "Al-Qari'ah", "meaning": "The Calamity", "verses": [{"ayah": 1, "translit": "Al qaari'ah", "translation": "The Striking Calamity -"}, {"ayah": 2, "translit": "Mal qaariah", "translation": "What is the Striking Calamity?"}, {"ayah": 3, "translit": "Wa maa adraaka mal qaari'ah", "translation": "And what can make you know what is the Striking Calamity?"}, {"ayah": 4, "translit": "Yauma ya koonun naasu kal farashil mabthooth", "translation": "It is the Day when people will be like moths, dispersed,"}, {"ayah": 5, "translit": "Wa ta koonul jibalu kal 'ihnil manfoosh", "translation": "And the mountains will be like wool, fluffed up."}, {"ayah": 6, "translit": "Fa-amma man thaqulat mawa zeenuh", "translation": "Then as for one whose scales are heavy [with good deeds],"}, {"ayah": 7, "translit": "Fahuwa fee 'ishatir raadiyah", "translation": "He will be in a pleasant life."}, {"ayah": 8, "translit": "Wa amma man khaffat mawa zeenuh", "translation": "But as for one whose scales are light,"}, {"ayah": 9, "translit": "Fa-ummuhu haawiyah", "translation": "His refuge will be an abyss."}, {"ayah": 10, "translit": "Wa maa adraaka maa hiyah", "translation": "And what can make you know what that is?"}, {"ayah": 11, "translit": "Naarun hamiyah", "translation": "It is a Fire, intensely hot."}]}, {"num": 102, "name": "At-Takathur", "meaning": "The Rivalry", "verses": [{"ayah": 1, "translit": "Al haaku mut takathur", "translation": "Competition in [worldly] increase diverts you"}, {"ayah": 2, "translit": "Hatta zurtumul-maqaabir", "translation": "Until you visit the graveyards."}, {"ayah": 3, "translit": "Kalla sawfa ta'lamoon", "translation": "No! You are going to know."}, {"ayah": 4, "translit": "Thumma kalla sawfa ta'lamoon", "translation": "Then no! You are going to know."}, {"ayah": 5, "translit": "Kalla law ta'lamoona 'ilmal yaqeen", "translation": "No! If you only knew with knowledge of certainty..."}, {"ayah": 6, "translit": "Latara-wun nal jaheem", "translation": "You will surely see the Hellfire."}, {"ayah": 7, "translit": "Thumma latara wunnaha 'ainal yaqeen", "translation": "Then you will surely see it with the eye of certainty."}, {"ayah": 8, "translit": "Thumma latus alunna yauma-izin 'anin na'eem", "translation": "Then you will surely be asked that Day about pleasure."}]}, {"num": 103, "name": "Al-Asr", "meaning": "The Declining Day", "verses": [{"ayah": 1, "translit": "Wal' asr", "translation": "By time,"}, {"ayah": 2, "translit": "Innal insaana lafee khusr", "translation": "Indeed, mankind is in loss,"}, {"ayah": 3, "translit": "Il lal lazeena aamanu wa 'amilus saali haati wa tawa saw bil haqqi wa tawa saw bis sabr", "translation": "Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience."}]}, {"num": 104, "name": "Al-Humazah", "meaning": "The Traducer", "verses": [{"ayah": 1, "translit": "Wai lul-li kulli hu mazatil-lumaza", "translation": "Woe to every scorner and mocker"}, {"ayah": 2, "translit": "Al-lazi jama'a maalaw wa'addadah", "translation": "Who collects wealth and [continuously] counts it."}, {"ayah": 3, "translit": "Yahsabu anna maalahu akhladah", "translation": "He thinks that his wealth will make him immortal."}, {"ayah": 4, "translit": "Kalla layum ba zanna fil hutamah", "translation": "No! He will surely be thrown into the Crusher."}, {"ayah": 5, "translit": "Wa maa adraaka mal-hutamah", "translation": "And what can make you know what is the Crusher?"}, {"ayah": 6, "translit": "Narul laahil-mooqada", "translation": "It is the fire of Allah, [eternally] fueled,"}, {"ayah": 7, "translit": "Al latee tat tali'u 'alalafidah", "translation": "Which mounts directed at the hearts."}, {"ayah": 8, "translit": "Innaha 'alaihim moosada", "translation": "Indeed, Hellfire will be closed down upon them"}, {"ayah": 9, "translit": "Fee 'amadim-mu mad dadah", "translation": "In extended columns."}]}, {"num": 105, "name": "Al-Fil", "meaning": "The Elephant", "verses": [{"ayah": 1, "translit": "Alam tara kaifa fa'ala rabbuka bi ashaabil feel", "translation": "Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?"}, {"ayah": 2, "translit": "Alam yaj'al kai dahum fee tad leel", "translation": "Did He not make their plan into misguidance?"}, {"ayah": 3, "translit": "Wa arsala 'alaihim tairan abaabeel", "translation": "And He sent against them birds in flocks,"}, {"ayah": 4, "translit": "Tar meehim bi hi jaaratim min sij jeel", "translation": "Striking them with stones of hard clay,"}, {"ayah": 5, "translit": "Faja 'alahum ka'asfim m'akool", "translation": "And He made them like eaten straw."}]}, {"num": 106, "name": "Quraysh", "meaning": "Quraysh", "verses": [{"ayah": 1, "translit": "Li-ilaafi quraish", "translation": "For the accustomed security of the Quraysh -"}, {"ayah": 2, "translit": "Elaafihim rihlatash shitaa-i wass saif", "translation": "Their accustomed security [in] the caravan of winter and summer -"}, {"ayah": 3, "translit": "Fal y'abudu rabba haazal-bait", "translation": "Let them worship the Lord of this House,"}, {"ayah": 4, "translit": "Allazi at'amahum min ju'inw-wa-aamana hum min khawf", "translation": "Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear."}]}, {"num": 107, "name": "Al-Ma'un", "meaning": "The Small Kindnesses", "verses": [{"ayah": 1, "translit": "Ara-aital lazee yu kazzibu bid deen", "translation": "Have you seen the one who denies the Recompense?"}, {"ayah": 2, "translit": "Fa zaalikal lazi yadu'ul-yateem", "translation": "For that is the one who drives away the orphan"}, {"ayah": 3, "translit": "Wa la ya huddu 'alaa ta'amil miskeen", "translation": "And does not encourage the feeding of the poor."}, {"ayah": 4, "translit": "Fa wai lul-lil mu salleen", "translation": "So woe to those who pray"}, {"ayah": 5, "translit": "Al lazeena hum 'an salaatihim sahoon", "translation": "[But] who are heedless of their prayer -"}, {"ayah": 6, "translit": "Al lazeena hum yuraa-oon", "translation": "Those who make show [of their deeds]"}, {"ayah": 7, "translit": "Wa yamna'oonal ma'oon", "translation": "And withhold [simple] assistance."}]}, {"num": 108, "name": "Al-Kawthar", "meaning": "The Abundance", "verses": [{"ayah": 1, "translit": "Innaa a'taina kal kauthar", "translation": "Indeed, We have granted you, [O Muhammad], al-Kawthar."}, {"ayah": 2, "translit": "Fa salli li rabbika wanhar", "translation": "So pray to your Lord and sacrifice [to Him alone]."}, {"ayah": 3, "translit": "Inna shani-aka huwal abtar", "translation": "Indeed, your enemy is the one cut off."}]}, {"num": 109, "name": "Al-Kafirun", "meaning": "The Disbelievers", "verses": [{"ayah": 1, "translit": "Qul yaa-ai yuhal kaafiroon", "translation": "Say, \"O disbelievers,"}, {"ayah": 2, "translit": "Laa a'budu ma t'abudoon", "translation": "I do not worship what you worship."}, {"ayah": 3, "translit": "Wa laa antum 'aabidoona maa a'bud", "translation": "Nor are you worshippers of what I worship."}, {"ayah": 4, "translit": "Wa laa ana 'abidum maa 'abattum", "translation": "Nor will I be a worshipper of what you worship."}, {"ayah": 5, "translit": "Wa laa antum 'aabidoona ma a'bud", "translation": "Nor will you be worshippers of what I worship."}, {"ayah": 6, "translit": "Lakum deenukum wa liya deen.", "translation": "For you is your religion, and for me is my religion.\""}]}, {"num": 110, "name": "An-Nasr", "meaning": "The Divine Support", "verses": [{"ayah": 1, "translit": "Iza jaa-a nas rullahi walfath", "translation": "When the victory of Allah has come and the conquest,"}, {"ayah": 2, "translit": "Wa ra-aitan naasa yadkhuloona fee deenil laahi afwajah", "translation": "And you see the people entering into the religion of Allah in multitudes,"}, {"ayah": 3, "translit": "Fa sab bih bihamdi rabbika was taghfir, innahu kaana tawwaaba", "translation": "Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance."}]}, {"num": 111, "name": "Al-Masad", "meaning": "The Palm Fiber", "verses": [{"ayah": 1, "translit": "Tab bat yadaa abee Lahabinw-wa tabb", "translation": "May the hands of Abu Lahab be ruined, and ruined is he."}, {"ayah": 2, "translit": "Maa aghna 'anhu maaluhu wa ma kasab", "translation": "His wealth will not avail him or that which he gained."}, {"ayah": 3, "translit": "Sa yas laa naran zaata lahab", "translation": "He will [enter to] burn in a Fire of [blazing] flame"}, {"ayah": 4, "translit": "Wam ra-atuhu hamma latal-hatab", "translation": "And his wife [as well] - the carrier of firewood."}, {"ayah": 5, "translit": "Fee jeediha hab lum mim-masad", "translation": "Around her neck is a rope of [twisted] fiber."}]}, {"num": 112, "name": "Al-Ikhlas", "meaning": "The Sincerity", "verses": [{"ayah": 1, "translit": "Qul huwal laahu ahad", "translation": "Say, \"He is Allah, [who is] One,"}, {"ayah": 2, "translit": "Allah hus-samad", "translation": "Allah, the Eternal Refuge."}, {"ayah": 3, "translit": "Lam yalid wa lam yoolad", "translation": "He neither begets nor is born,"}, {"ayah": 4, "translit": "Wa lam yakul-lahu kufuwan ahad", "translation": "Nor is there to Him any equivalent.\""}]}, {"num": 113, "name": "Al-Falaq", "meaning": "The Daybreak", "verses": [{"ayah": 1, "translit": "Qul a'uzoo bi rabbil-falaq", "translation": "Say, \"I seek refuge in the Lord of daybreak"}, {"ayah": 2, "translit": "Min sharri ma khalaq", "translation": "From the evil of that which He created"}, {"ayah": 3, "translit": "Wa min sharri ghasiqin iza waqab", "translation": "And from the evil of darkness when it settles"}, {"ayah": 4, "translit": "Wa min sharrin-naffaa-saati fil 'uqad", "translation": "And from the evil of the blowers in knots"}, {"ayah": 5, "translit": "Wa min shar ri haasidin iza hasad", "translation": "And from the evil of an envier when he envies.\""}]}, {"num": 114, "name": "An-Nas", "meaning": "The Mankind", "verses": [{"ayah": 1, "translit": "Qul a'uzu birabbin naas", "translation": "Say, \"I seek refuge in the Lord of mankind,"}, {"ayah": 2, "translit": "Malikin naas", "translation": "The Sovereign of mankind."}, {"ayah": 3, "translit": "Ilaahin naas", "translation": "The God of mankind,"}, {"ayah": 4, "translit": "Min sharril was waasil khannaas", "translation": "From the evil of the retreating whisperer -"}, {"ayah": 5, "translit": "Al lazee yuwas wisu fee sudoorin naas", "translation": "Who whispers [evil] into the breasts of mankind -"}, {"ayah": 6, "translit": "Minal jinnati wan naas", "translation": "From among the jinn and mankind.\""}]}]};